# ============================================================================
# 14. SPIRAL SWEEP â€” logarithmic spirals from center
# ============================================================================

def spiral_sweep(shape, seed, sm, num_arms=4, tightness=3.0, fade=0.3):
    """spiral_sweep.

    identity: Round-6 creative rebuild â€” DOUBLE-GALAXY interleaved logarithmic
    spirals where TWO offset pivot points each generate a 14-arm + 22-arm
    spiral that interlace across the canvas. The two galaxies modulate
    M/R/CC differently so where they overlap the spec channels show
    chromatic interference. Hero motif: along the high-intensity spiral
    crests we drop SHORT comet-tail streaks (4-10 px) that flow along
    the spiral tangent, plus tight 2-3 px arc shards (1-12 px crystal
    shards), then a final pinprick scatter on crests for sparkle.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 1455)
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)

    # Two pivots for double-galaxy
    cx0a = 0.40 + float(rng.uniform(-0.04, 0.04))
    cy0a = 0.45 + float(rng.uniform(-0.04, 0.04))
    cx0b = 0.62 + float(rng.uniform(-0.04, 0.04))
    cy0b = 0.58 + float(rng.uniform(-0.04, 0.04))

    yy = (np.arange(h, dtype=np.float32) / h)[:, None]
    xx = (np.arange(w, dtype=np.float32) / w)[None, :]

    # Galaxy A
    dya = yy - cy0a; dxa = xx - cx0a
    th_a = np.arctan2(dya, dxa)
    rr_a = np.sqrt(dya * dya + dxa * dxa) + 1e-6
    armsA_main = np.sin(th_a * 14.0 - np.log(rr_a + 0.01) * 44.0 + float(rng.uniform(0, 2 * np.pi))) * 0.5 + 0.5
    armsA_fine = np.sin(th_a * 22.0 - np.log(rr_a + 0.01) * 70.0 + float(rng.uniform(0, 2 * np.pi))) * 0.5 + 0.5
    fieldA = (armsA_main * 0.60 + armsA_fine * 0.40).astype(np.float32)

    # Galaxy B (counter-rotating)
    dyb = yy - cy0b; dxb = xx - cx0b
    th_b = np.arctan2(dyb, dxb)
    rr_b = np.sqrt(dyb * dyb + dxb * dxb) + 1e-6
    armsB_main = np.sin(-th_b * 11.0 - np.log(rr_b + 0.01) * 38.0 + float(rng.uniform(0, 2 * np.pi))) * 0.5 + 0.5
    armsB_fine = np.sin(-th_b * 18.0 - np.log(rr_b + 0.01) * 60.0 + float(rng.uniform(0, 2 * np.pi))) * 0.5 + 0.5
    fieldB = (armsB_main * 0.55 + armsB_fine * 0.45).astype(np.float32)

    # Interleave â€” interference where galaxies meet
    fbm_M = _normalize(multi_scale_noise(shape, [2.0, 6.0, 14.0], [0.5, 0.3, 0.2], int(seed) + 4101))
    fbm_R = _normalize(multi_scale_noise(shape, [2.0, 6.0, 14.0], [0.5, 0.3, 0.2], int(seed) + 4102))
    fbm_CC = _normalize(multi_scale_noise(shape, [2.0, 6.0, 14.0], [0.5, 0.3, 0.2], int(seed) + 4103))

    combined = (fieldA * 0.55 + fieldB * 0.45).astype(np.float32)
    interference = (np.abs(fieldA - fieldB)).astype(np.float32)

    M = (0.38 + (fieldA - 0.5) * 0.36 + (fbm_M - 0.5) * 0.12).astype(np.float32)
    R = (0.42 - (combined - 0.5) * 0.24 + (fbm_R - 0.5) * 0.10).astype(np.float32)
    CC = (0.34 + (fieldB - 0.5) * 0.32 + (interference - 0.3) * 0.18 + (1.0 - fbm_CC) * 0.08).astype(np.float32)

    if _CV2_OK:
        # 1) HERO â€” comet-tail streaks along spiral tangents (galaxy A)
        n_comet = int(np.clip(3200 * (mn / 2048.0) ** 2, 1100, 7500))
        for _ in range(n_comet):
            ax_n = float(rng.uniform(0.04, 0.96)); ay_n = float(rng.uniform(0.04, 0.96))
            ax = ax_n * w; ay = ay_n * h
            # pick which galaxy
            use_a = rng.random() < 0.55
            if use_a:
                tx = ax_n - cx0a; ty = ay_n - cy0a
                ang = float(np.arctan2(ty, tx)) + np.pi * 0.5 + float(rng.uniform(-0.18, 0.18))
            else:
                tx = ax_n - cx0b; ty = ay_n - cy0b
                ang = float(np.arctan2(ty, tx)) - np.pi * 0.5 + float(rng.uniform(-0.18, 0.18))
            length = float(rng.uniform(4.0, 10.0))
            x0s = int(ax - np.cos(ang) * length * 0.5); y0s = int(ay - np.sin(ang) * length * 0.5)
            x1s = int(ax + np.cos(ang) * length * 0.5); y1s = int(ay + np.sin(ang) * length * 0.5)
            _cv2.line(M, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.45, 0.97)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(R, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.05, 0.30)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.30, 0.95)), 1, lineType=_cv2.LINE_AA)
            # Bright head dot
            _cv2.circle(M, (x1s, y1s), 1, float(rng.uniform(0.78, 0.99)), -1, lineType=_cv2.LINE_AA)

        # 2) Crystal shards 2-4 px along crests
        n_crest = int(np.clip(5000 * (mn / 2048.0) ** 2, 1700, 11000))
        for _ in range(n_crest):
            cx_s = int(rng.integers(0, w)); cy_s = int(rng.integers(0, h))
            crest_val = max(fieldA[cy_s, cx_s], fieldB[cy_s, cx_s])
            if crest_val < 0.58:
                continue
            r_s = max(1, int(float(rng.uniform(1.0, 2.5)) * scale))
            _cv2.circle(M, (cx_s, cy_s), r_s, float(rng.uniform(0.60, 0.97)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx_s, cy_s), r_s, float(rng.uniform(0.05, 0.28)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx_s, cy_s), r_s, float(rng.uniform(0.10, 0.85)), -1, lineType=_cv2.LINE_AA)

        # 3) Dark orbital debris 1-3 px
        n_dust = int(np.clip(2000 * (mn / 2048.0) ** 2, 700, 5000))
        for _ in range(n_dust):
            cx_s = int(rng.integers(0, w)); cy_s = int(rng.integers(0, h))
            r_s = max(1, int(float(rng.uniform(1.0, 2.0)) * scale))
            _cv2.circle(M, (cx_s, cy_s), r_s, float(rng.uniform(0.08, 0.28)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx_s, cy_s), r_s, float(rng.uniform(0.55, 0.92)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx_s, cy_s), r_s, float(rng.uniform(0.55, 0.92)), -1, lineType=_cv2.LINE_AA)

    # 4) Pinpoint speckles
    n_fl = int(np.clip(2800 * (mn / 2048.0) ** 2, 1000, 7000))
    fy = rng.integers(0, h, n_fl); fx = rng.integers(0, w, n_fl)
    M[fy, fx] = np.maximum(M[fy, fx], rng.uniform(0.55, 0.97, n_fl).astype(np.float32))
    R[fy, fx] = np.minimum(R[fy, fx], rng.uniform(0.05, 0.28, n_fl).astype(np.float32))
    CC[fy, fx] = np.maximum(CC[fy, fx], rng.uniform(0.10, 0.85, n_fl).astype(np.float32))

    out = np.stack([np.clip(M, 0, 1), np.clip(R, 0, 1), np.clip(CC, 0, 1)], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
spiral_sweep._spb_concept_complete = True
# ============================================================================
# 15. CARBON WEAVE â€” woven fiber crosshatch pattern
# ============================================================================

def carbon_weave(shape, seed, sm, weave_size=12, contrast=0.6):
    """carbon_weave â€” R6 CREATIVE rebuild.

    identity: REAL carbon-fiber 2x2 twill weave at 45-degree HERO BIAS â€”
    rotated so the over/under strand stacks march DIAGONALLY across the
    canvas instead of orthogonally. This is the iconic carbon-fiber
    "look" that every supercar hood shows. Strand bundles are 8-14 px
    wide; each bundle carries 2-3 px filament striations along the
    strand axis (the carbon sparkle); per-strand INDEPENDENT continuous
    M/R/CC so each visible tow has its own chroma. HERO accents: a
    sprinkle of bright RESIN BUBBLE pinpoints (clearcoat hot-spots
    catching light), plus dark crossover shadows at every strand
    intersection. Differentiator vs forged_carbon: this is the classic
    twill grid (diagonal bias still ordered), not chaotic chunked
    forged-carbon shards.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + (hash("carbon_weave_r6") % 10000))
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)
    ws = max(8, int(weave_size * (0.7 + scale * 1.0)))  # weave bundle width

    # 1) Rotated coordinates â€” 45-degree bias
    yy_lin = np.arange(h, dtype=np.float32)[:, None]
    xx_lin = np.arange(w, dtype=np.float32)[None, :]
    cos45 = float(np.cos(np.pi / 4)); sin45 = float(np.sin(np.pi / 4))
    u = (xx_lin * cos45 + yy_lin * sin45).astype(np.float32)  # warp axis
    v = (-xx_lin * sin45 + yy_lin * cos45).astype(np.float32)  # weft axis
    u_2d = np.broadcast_to(u, (h, w))
    v_2d = np.broadcast_to(v, (h, w))

    cell_u = (u_2d // ws).astype(np.int32)
    cell_v = (v_2d // ws).astype(np.int32)
    on_top = ((cell_u + cell_v) % 2).astype(np.float32)

    # 2) Strand profile (raised half-sine across bundle width)
    warp_phase = (np.mod(u_2d, ws) / float(ws)).astype(np.float32)
    weft_phase = (np.mod(v_2d, ws) / float(ws)).astype(np.float32)
    warp_profile = (0.5 + 0.5 * np.sin(warp_phase * np.pi)).astype(np.float32)
    weft_profile = (0.5 + 0.5 * np.sin(weft_phase * np.pi)).astype(np.float32)
    strand_profile = (on_top * warp_profile + (1 - on_top) * weft_profile).astype(np.float32)

    # 3) Per-bundle chroma table â€” hash to independent M/R/CC
    n_cy = int(np.ceil((u_2d.max() - u_2d.min()) / ws)) + 4
    n_cx = int(np.ceil((v_2d.max() - v_2d.min()) / ws)) + 4
    n_cy = max(n_cy, 16); n_cx = max(n_cx, 16)
    cell_M = rng.uniform(0.32, 0.92, (n_cy, n_cx)).astype(np.float32)
    cell_R = rng.uniform(0.08, 0.45, (n_cy, n_cx)).astype(np.float32)
    cell_CC = rng.uniform(0.10, 0.60, (n_cy, n_cx)).astype(np.float32)
    iy = np.clip(cell_u - int(u_2d.min() // ws), 0, n_cy - 1)
    ix = np.clip(cell_v - int(v_2d.min() // ws), 0, n_cx - 1)
    M = cell_M[iy, ix].copy()
    R = cell_R[iy, ix].copy()
    CC = cell_CC[iy, ix].copy()

    # 4) Raised-strand brightening (top strands more lit)
    M = np.clip(M + (strand_profile - 0.5) * 0.42 * (0.5 + on_top * 0.7), 0, 1)
    R = np.clip(R - (strand_profile - 0.5) * 0.16, 0, 1)
    CC = np.clip(CC - (strand_profile - 0.5) * 0.20, 0, 1)

    # 5) FILAMENT STRIATIONS â€” vectorized sinusoid along strand axis
    # Warp filaments visible where on_top==1 (warp on top); striations along u axis
    fil_freq_warp = 2 * np.pi / max(2.0, ws / 3.0)
    fil_warp = (0.5 + 0.5 * np.sin(v_2d * fil_freq_warp + rng.uniform(0, 6.28))).astype(np.float32)
    fil_weft = (0.5 + 0.5 * np.sin(u_2d * fil_freq_warp + rng.uniform(0, 6.28))).astype(np.float32)
    fil = on_top * fil_warp + (1 - on_top) * fil_weft
    M = np.clip(M + (fil - 0.5) * 0.20, 0, 1)
    R = np.clip(R - (fil - 0.5) * 0.06, 0, 1)

    # 6) DARK CROSSOVER SHADOWS at strand intersections
    u_mod = warp_phase
    v_mod = weft_phase
    edge_dark = (np.exp(-((u_mod - 0.5) ** 2 + (v_mod - 0.5) ** 2) * 16.0)).astype(np.float32)
    M = np.clip(M - edge_dark * 0.20, 0, 1)
    CC = np.clip(CC + edge_dark * 0.18, 0, 1)

    if _CV2_OK:
        # 7) RESIN BUBBLE PINPOINTS â€” bright clearcoat hotspots (HERO accents)
        n_bubble = int(np.clip(420 * (mn / 1024.0) ** 2, 180, 1400))
        for _ in range(n_bubble):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            r = max(1, int(rng.uniform(1.0, 2.6)))
            _cv2.circle(M, (cx, cy), r, float(rng.uniform(0.78, 0.99)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r, float(rng.uniform(0.04, 0.18)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r, float(rng.uniform(0.04, 0.20)), -1, lineType=_cv2.LINE_AA)
        # 8) BROKEN FILAMENT FLICKS â€” short bright lines (carbon flecks)
        n_flick = int(np.clip(900 * (mn / 1024.0) ** 2, 400, 2800))
        for _ in range(n_flick):
            cx = float(rng.uniform(2, w - 2)); cy = float(rng.uniform(2, h - 2))
            length = float(rng.uniform(3.0, 7.0))
            # along bias direction
            ang = float(rng.choice([np.pi / 4, -np.pi / 4])) + float(rng.normal(0, 0.06))
            x1f = int(cx + np.cos(ang) * length); y1f = int(cy + np.sin(ang) * length)
            _cv2.line(M, (int(cx), int(cy)), (x1f, y1f), float(rng.uniform(0.72, 0.98)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(R, (int(cx), int(cy)), (x1f, y1f), float(rng.uniform(0.05, 0.20)), 1, lineType=_cv2.LINE_AA)

    # 9) MICRO PEPPER
    n_pix = int(np.clip(3200 * (mn / 2048.0) ** 2, 1200, 9000))
    px = rng.integers(0, w, n_pix); py = rng.integers(0, h, n_pix)
    M[py, px] = np.maximum(M[py, px], rng.uniform(0.65, 0.95, n_pix).astype(np.float32))

    # R6-TICK NEW HERO â€” MYCELIUM RHIZOMORPH FIBER WEB
    # Biology motif: a faint web of branching mycelium-style fibers
    # creeps along the carbon strands like fungal rhizomorphs working
    # through forest soil. 6-10 mother-hyphae trunk lines, each
    # spawning 3-5 child branches at random angles (~25-55 deg fork).
    # Fine 1-px AA lines, length 12-22 px parent, 5-10 px branch.
    # Independent chroma per fiber. Never used in this loop before.
    if _CV2_OK:
        n_myc = int(rng.integers(6, 11))
        for _ in range(n_myc):
            # Mother hypha â€” biased to bias-direction so it follows weave
            mx0 = float(rng.uniform(0.05, 0.95) * w)
            my0 = float(rng.uniform(0.05, 0.95) * h)
            # Pick along-bias direction OR cross-bias 25%
            if rng.random() < 0.75:
                m_ang = float(rng.choice([np.pi / 4, -np.pi / 4])) + float(rng.normal(0, 0.18))
            else:
                m_ang = float(rng.uniform(0, 2 * np.pi))
            m_len = float(rng.uniform(12.0, 22.0) * scale)
            mx1 = mx0 + np.cos(m_ang) * m_len
            my1 = my0 + np.sin(m_ang) * m_len
            # Parent fiber chroma â€” slightly brighter
            mM = float(rng.uniform(0.55, 0.92))
            mR = float(rng.uniform(0.10, 0.32))
            mCC = float(rng.uniform(0.06, 0.30))
            _cv2.line(M, (int(mx0), int(my0)), (int(np.clip(mx1, 0, w - 1)), int(np.clip(my1, 0, h - 1))),
                      mM, 1, lineType=_cv2.LINE_AA)
            _cv2.line(R, (int(mx0), int(my0)), (int(np.clip(mx1, 0, w - 1)), int(np.clip(my1, 0, h - 1))),
                      mR, 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (int(mx0), int(my0)), (int(np.clip(mx1, 0, w - 1)), int(np.clip(my1, 0, h - 1))),
                      mCC, 1, lineType=_cv2.LINE_AA)
            # Spawn child branches along the parent
            n_child = int(rng.integers(3, 6))
            for _c in range(n_child):
                t_branch = float(rng.uniform(0.18, 0.92))
                bx0 = mx0 + (mx1 - mx0) * t_branch
                by0 = my0 + (my1 - my0) * t_branch
                fork_dir = float(rng.choice([1.0, -1.0]))
                fork_off = fork_dir * float(rng.uniform(0.44, 0.96))  # ~25-55 deg
                b_ang = m_ang + fork_off
                b_len = float(rng.uniform(5.0, 10.0) * scale)
                bx1 = bx0 + np.cos(b_ang) * b_len
                by1 = by0 + np.sin(b_ang) * b_len
                bM = float(rng.uniform(0.42, 0.84))
                bR = float(rng.uniform(0.14, 0.40))
                bCC = float(rng.uniform(0.08, 0.34))
                _cv2.line(M, (int(bx0), int(by0)),
                          (int(np.clip(bx1, 0, w - 1)), int(np.clip(by1, 0, h - 1))),
                          bM, 1, lineType=_cv2.LINE_AA)
                _cv2.line(R, (int(bx0), int(by0)),
                          (int(np.clip(bx1, 0, w - 1)), int(np.clip(by1, 0, h - 1))),
                          bR, 1, lineType=_cv2.LINE_AA)
                _cv2.line(CC, (int(bx0), int(by0)),
                          (int(np.clip(bx1, 0, w - 1)), int(np.clip(by1, 0, h - 1))),
                          bCC, 1, lineType=_cv2.LINE_AA)
                # Tip-sporangium tiny bright dot
                _cv2.circle(M, (int(np.clip(bx1, 0, w - 1)), int(np.clip(by1, 0, h - 1))),
                            1, float(rng.uniform(0.65, 0.95)), -1, lineType=_cv2.LINE_AA)

    out = np.stack([np.clip(M, 0, 1), np.clip(R, 0, 1), np.clip(CC, 0, 1)], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)


carbon_weave._spb_concept_complete = True


# ============================================================================
# 16. CRACKLE NETWORK â€” dried clay / crackle glaze fractures
# ============================================================================

def crackle_network(shape, seed, sm, cell_count=25, crack_width=0.12):
    """Shrinkage crack network â€” long dendritic cracks, NOT voronoi cells.

    identity: A dried mud-flat shrinkage-crack network â€” long curved primary
    cracks 40-200 px that branch dendritically (like dried-clay or eggshell
    shrinkage, NOT voronoi tiles). Each crack edge is SHARP and BRIGHT-
    rimmed (CC=high on edge), with a dark crack interior. Between cracks
    the substrate is FLAT and uniform (NOT colorful per-tile cells) â€” a
    quiet matte mud-grey ground. Per-crack INDEPENDENT tint.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 1010)
    scale = max(min(h, w) / 2048.0, 0.25)
    px_unit = max(scale, 0.7)

    def _fbm(off, sigma):
        if _CV2_OK:
            sh = max(64, h // 10); sw = max(64, w // 10)
            n = np.random.default_rng(int(seed) + off).random((sh, sw)).astype(np.float32)
            b = _cv2.GaussianBlur(n, (0, 0), sigmaX=sigma, sigmaY=sigma)
            return _normalize(_cv2.resize(b, (w, h), interpolation=_cv2.INTER_CUBIC).astype(np.float32))
        return _normalize(multi_scale_noise(shape, [20, 40], [0.6, 0.4], int(seed) + off))

    # FLAT mud substrate â€” very quiet, low contrast
    flat_M = (0.36 + (_fbm(1011, 18.0) - 0.5) * 0.06).astype(np.float32)
    flat_R = (0.62 + (_fbm(1013, 18.0) - 0.5) * 0.06).astype(np.float32)
    flat_CC = (0.42 + (_fbm(1015, 18.0) - 0.5) * 0.06).astype(np.float32)
    M = flat_M.copy(); R_ch = flat_R.copy(); CC = flat_CC.copy()

    if _CV2_OK:
        # PRIMARY DENDRITIC CRACKS â€” long curved 40-200 px
        n_primary = max(60, int(min(h, w) / 8))
        for _ in range(n_primary):
            x0 = float(rng.uniform(0, w)); y0 = float(rng.uniform(0, h))
            ang = float(rng.uniform(0, 2 * np.pi))
            total_len = float(rng.uniform(40.0, 200.0)) * (min(h, w) / 2048.0 * 3.5 + 0.30)
            seg_len = float(rng.uniform(8.0, 16.0) * px_unit)
            n_seg = max(4, int(total_len / seg_len))
            # Per-crack INDEPENDENT M/R/CC for the dark interior
            cM_int = float(rng.uniform(0.04, 0.16))
            cR_int = float(rng.uniform(0.78, 0.96))
            cCC_int = float(rng.uniform(0.06, 0.20))
            # Per-crack rim (BRIGHT, sharp edge)
            rM = float(rng.uniform(0.55, 0.92))
            rR = float(rng.uniform(0.10, 0.32))
            rCC = float(rng.uniform(0.65, 0.97))
            tw_main = max(1, int(rng.uniform(1.5, 3.0) * px_unit))
            tw_rim = max(1, tw_main + 1)
            pts = [(int(x0), int(y0))]
            for _s in range(n_seg):
                ang += float(rng.normal(0.0, 0.18))  # smooth curve, not random walk
                x0 += np.cos(ang) * seg_len
                y0 += np.sin(ang) * seg_len
                pts.append((int(x0), int(y0)))
            # Bright rim first (wider), then dark interior on top (thinner)
            for k in range(len(pts) - 1):
                _cv2.line(M, pts[k], pts[k+1], rM, tw_rim, lineType=_cv2.LINE_AA)
                _cv2.line(R_ch, pts[k], pts[k+1], rR, tw_rim, lineType=_cv2.LINE_AA)
                _cv2.line(CC, pts[k], pts[k+1], rCC, tw_rim, lineType=_cv2.LINE_AA)
                _cv2.line(M, pts[k], pts[k+1], cM_int, tw_main, lineType=_cv2.LINE_AA)
                _cv2.line(R_ch, pts[k], pts[k+1], cR_int, tw_main, lineType=_cv2.LINE_AA)
                _cv2.line(CC, pts[k], pts[k+1], cCC_int, tw_main, lineType=_cv2.LINE_AA)
            # DENDRITIC BRANCHES â€” 2-5 secondary cracks fork off
            n_br = int(rng.integers(2, 6))
            for _b in range(n_br):
                bi = int(rng.integers(1, max(2, len(pts) - 1)))
                bx, by = pts[bi]
                bang = ang + float(rng.choice([-1, 1])) * float(rng.uniform(0.50, 1.10))
                bsegs = int(rng.integers(4, 10))
                btw = max(1, tw_main - (1 if tw_main > 1 else 0))
                bpts = [(bx, by)]
                for _bs in range(bsegs):
                    bang += float(rng.normal(0.0, 0.22))
                    bx_f = bpts[-1][0] + np.cos(bang) * seg_len * 0.7
                    by_f = bpts[-1][1] + np.sin(bang) * seg_len * 0.7
                    bpts.append((int(bx_f), int(by_f)))
                flat_M_mean = float(flat_M.mean())
                flat_R_mean = float(flat_R.mean())
                flat_CC_mean = float(flat_CC.mean())
                for j in range(len(bpts) - 1):
                    fade = 1.0 - j / max(1, len(bpts) - 1)
                    _cv2.line(M, bpts[j], bpts[j+1], float(cM_int * fade + flat_M_mean * (1 - fade)), btw, lineType=_cv2.LINE_AA)
                    _cv2.line(CC, bpts[j], bpts[j+1], float(cCC_int * fade + flat_CC_mean * (1 - fade)), btw, lineType=_cv2.LINE_AA)
                    _cv2.line(R_ch, bpts[j], bpts[j+1], float(cR_int * fade + flat_R_mean * (1 - fade)), btw, lineType=_cv2.LINE_AA)

    out = np.stack([np.clip(M, 0, 1), np.clip(R_ch, 0, 1), np.clip(CC, 0, 1)], axis=2).astype(np.float32)
    return _sm_scale(np.clip(out, 0, 1), sm).astype(np.float32)
crackle_network._spb_concept_complete = True

def _LEGACY_crackle_network_dead(shape, seed, sm, cell_count=25, crack_width=0.12):
    h, w = shape
    rng = np.random.default_rng(seed + 1010)
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)
    palette = np.array([0.18, 0.28, 0.38, 0.48, 0.58, 0.68, 0.78, 0.92], dtype=np.float32)


# ============================================================================
# 17. FLOW LINES â€” fluid paint flow simulation
# ============================================================================

def flow_lines(shape, seed, sm, num_streams=40, line_width=0.02, curvature=3.0, **kwargs):
    """flow_lines â€” ROUND-6 CREATIVE REBUILD: river delta, expressed.

    identity: A wet-paint RIVER DELTA caught in spec maps. Curl-noise drives
    real streamline tracing as before, but now layered with delta-fan
    motifs that branch like a river splitting toward the sea. Seven tiers:
      (1) FBM substrate;
      (2) curl-noise vector field;
      (3) DENSE streamline tracing â€” 4-12 step polylines (12-32 px paths);
      (4) HERO MOTIF â€” DELTA FAN BRANCHES: ~40 trunk seeds each spawn 3-5
          downstream branches at small angle offsets, producing the iconic
          braided distributary fan pattern;
      (5) EDDY WHIRLS â€” small 8-14 px open spirals scattered along the
          field where vorticity is high;
      (6) FOAM CRESTS â€” short perpendicular 4-8 px cross-strokes laid on
          top of streamlines like white-water tips;
      (7) droplet head dots (2-4 px) + bubble micro-rings + bright
          pigment fleck carpet.
    Every streamline + branch + eddy + foam crest picks independent
    continuous M/R/CC uniforms in wide ranges.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 40417)
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)

    # 1) BASE â€” flowing FBM substrate
    bM = _normalize(multi_scale_noise(shape, [2.0, 6.0, 14.0], [0.5, 0.3, 0.2], int(seed) + 40421))
    bR = _normalize(multi_scale_noise(shape, [2.0, 6.0, 14.0], [0.5, 0.3, 0.2], int(seed) + 40423))
    bC = _normalize(multi_scale_noise(shape, [2.0, 6.0, 14.0], [0.5, 0.3, 0.2], int(seed) + 40425))
    M = (0.40 + (bM - 0.5) * 0.26).astype(np.float32)
    R = (0.48 + (bR - 0.5) * 0.24).astype(np.float32)
    CC = (0.42 + (bC - 0.5) * 0.24).astype(np.float32)

    # 2) Build vector field â€” curl of a low-freq scalar potential
    pot = _normalize(multi_scale_noise(shape, [12.0, 28.0], [0.6, 0.4], int(seed) + 40431))
    dy_pot = np.gradient(pot, axis=0)
    dx_pot = np.gradient(pot, axis=1)
    field_vx = -dx_pot; field_vy = dy_pot
    mag = np.sqrt(field_vx ** 2 + field_vy ** 2) + 1e-6
    field_vx = field_vx / mag; field_vy = field_vy / mag

    if _CV2_OK:
        # 3) STREAMLINE TRACING â€” real curved flows
        n_seeds = int(np.clip(900 * (mn / 2048.0) ** 2, 320, 2400))
        step_len = max(2.5, 3.0 * scale)
        # collect tips for foam crest tier
        tips = []
        for _ in range(n_seeds):
            x = float(rng.uniform(0, w - 1)); y = float(rng.uniform(0, h - 1))
            n_steps = int(rng.integers(4, 13))
            mv = float(rng.uniform(0.28, 0.96))
            rv = float(rng.uniform(0.06, 0.58))
            cv = float(rng.uniform(0.08, 0.62))
            last_vx = 0.0; last_vy = 0.0
            for _s in range(n_steps):
                ix = int(np.clip(x, 0, w - 1)); iy = int(np.clip(y, 0, h - 1))
                vx = float(field_vx[iy, ix]); vy = float(field_vy[iy, ix])
                x2 = x + vx * step_len; y2 = y + vy * step_len
                if not (0 <= x2 < w and 0 <= y2 < h): break
                _cv2.line(M, (int(x), int(y)), (int(x2), int(y2)), mv, 1, lineType=_cv2.LINE_AA)
                _cv2.line(R, (int(x), int(y)), (int(x2), int(y2)), rv, 1, lineType=_cv2.LINE_AA)
                _cv2.line(CC, (int(x), int(y)), (int(x2), int(y2)), cv, 1, lineType=_cv2.LINE_AA)
                last_vx = vx; last_vy = vy
                x = x2; y = y2
            tips.append((x, y, last_vx, last_vy))

        # 4) HERO â€” DELTA FAN BRANCHES
        n_trunks = int(np.clip(60 * (mn / 2048.0), 18, 180))
        for _ in range(n_trunks):
            tx = float(rng.uniform(0, w - 1)); ty = float(rng.uniform(0, h - 1))
            ix = int(np.clip(tx, 0, w - 1)); iy = int(np.clip(ty, 0, h - 1))
            vx = float(field_vx[iy, ix]); vy = float(field_vy[iy, ix])
            n_branches = int(rng.integers(3, 6))
            base_ang = float(np.arctan2(vy, vx))
            for b in range(n_branches):
                # small angle offset per branch â€” distributary fan
                da = float(rng.uniform(-0.55, 0.55))
                ang = base_ang + da
                bvx = float(np.cos(ang)); bvy = float(np.sin(ang))
                bx = tx; by = ty
                mv = float(rng.uniform(0.42, 0.95))
                rv = float(rng.uniform(0.06, 0.40))
                cv = float(rng.uniform(0.10, 0.55))
                n_bsteps = int(rng.integers(3, 9))
                for _s in range(n_bsteps):
                    # bend toward field gradually
                    ix2 = int(np.clip(bx, 0, w - 1)); iy2 = int(np.clip(by, 0, h - 1))
                    fvx = float(field_vx[iy2, ix2]); fvy = float(field_vy[iy2, ix2])
                    bvx = 0.6 * bvx + 0.4 * fvx; bvy = 0.6 * bvy + 0.4 * fvy
                    nrm = np.sqrt(bvx * bvx + bvy * bvy) + 1e-6
                    bvx /= nrm; bvy /= nrm
                    bx2 = bx + bvx * step_len * 1.4
                    by2 = by + bvy * step_len * 1.4
                    if not (0 <= bx2 < w and 0 <= by2 < h): break
                    _cv2.line(M, (int(bx), int(by)), (int(bx2), int(by2)), mv, 1, lineType=_cv2.LINE_AA)
                    _cv2.line(R, (int(bx), int(by)), (int(bx2), int(by2)), rv, 1, lineType=_cv2.LINE_AA)
                    _cv2.line(CC, (int(bx), int(by)), (int(bx2), int(by2)), cv, 1, lineType=_cv2.LINE_AA)
                    bx = bx2; by = by2

        # 5) EDDY WHIRLS â€” small open spirals 8-14 px
        n_eddy = int(np.clip(180 * (mn / 2048.0), 36, 420))
        for _ in range(n_eddy):
            cx = int(rng.uniform(8, w - 8)); cy = int(rng.uniform(8, h - 8))
            r = max(3, int(rng.uniform(4.0, 7.0) * scale))
            a0 = float(rng.uniform(0, 360))
            sweep = float(rng.uniform(180, 320))
            mv = float(rng.uniform(0.45, 0.92))
            rv = float(rng.uniform(0.08, 0.42))
            cv = float(rng.uniform(0.10, 0.50))
            _cv2.ellipse(M, (cx, cy), (r, r), 0.0, a0, a0 + sweep, mv, 1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(R, (cx, cy), (r, r), 0.0, a0, a0 + sweep, rv, 1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(CC, (cx, cy), (r, r), 0.0, a0, a0 + sweep, cv, 1, lineType=_cv2.LINE_AA)

        # 6) FOAM CRESTS â€” short perpendicular crossstrokes at random tips
        sample_tips = tips[::max(1, len(tips) // 800)] if tips else []
        for (tx, ty, vx, vy) in sample_tips:
            if not (0 <= tx < w and 0 <= ty < h): continue
            # perpendicular
            px = -vy; py = vx
            ln = float(rng.uniform(4.0, 8.0) * scale)
            x0c = int(np.clip(tx - px * ln * 0.5, 0, w - 1))
            y0c = int(np.clip(ty - py * ln * 0.5, 0, h - 1))
            x1c = int(np.clip(tx + px * ln * 0.5, 0, w - 1))
            y1c = int(np.clip(ty + py * ln * 0.5, 0, h - 1))
            _cv2.line(M, (x0c, y0c), (x1c, y1c), float(rng.uniform(0.60, 0.98)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(R, (x0c, y0c), (x1c, y1c), float(rng.uniform(0.04, 0.22)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (x0c, y0c), (x1c, y1c), float(rng.uniform(0.06, 0.30)), 1, lineType=_cv2.LINE_AA)

        # 7) DROPLET HEADS (2-4 px) â€” dense
        n_drops = int(np.clip(1800 * (mn / 2048.0) ** 2, 600, 4000))
        for _ in range(n_drops):
            cx = int(rng.uniform(2, w - 2)); cy = int(rng.uniform(2, h - 2))
            r = max(1, int(rng.uniform(1.5, 3.5) * scale))
            _cv2.circle(M, (cx, cy), r, float(rng.uniform(0.62, 0.98)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r, float(rng.uniform(0.05, 0.26)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r, float(rng.uniform(0.05, 0.28)), -1, lineType=_cv2.LINE_AA)

        # 8) BUBBLE MICRO-RINGS
        n_bub = int(np.clip(450 * (mn / 2048.0) ** 2, 160, 1200))
        for _ in range(n_bub):
            cx = int(rng.uniform(3, w - 3)); cy = int(rng.uniform(3, h - 3))
            r = max(2, int(rng.uniform(2.5, 5.0) * scale))
            _cv2.circle(M, (cx, cy), r, float(rng.uniform(0.52, 0.88)), 1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r, float(rng.uniform(0.08, 0.32)), 1, lineType=_cv2.LINE_AA)

    # 9) PIGMENT FLECK CARPET
    n_fl = max(5000, int(h * w / 14))
    fy = rng.integers(0, h, n_fl); fx = rng.integers(0, w, n_fl)
    M[fy, fx] = np.maximum(M[fy, fx], rng.uniform(0.52, 0.98, n_fl).astype(np.float32))
    R[fy, fx] = np.minimum(R[fy, fx], rng.uniform(0.05, 0.30, n_fl).astype(np.float32))
    CC[fy, fx] = np.minimum(CC[fy, fx], rng.uniform(0.05, 0.32, n_fl).astype(np.float32))

    out = np.stack([M, R, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)

flow_lines._spb_concept_complete = True


# ============================================================================
# 18. MICRO FACETS â€” tiny angled facets like crushed crystal
# ============================================================================

def micro_facets(shape, seed, sm, facet_size=8, angle_range=0.5):
    """micro_facets â€” creative rebuild: pavÃ© crystal with hero shatter rays.

    identity: A wall-to-wall diamond pavÃ© â€” 4-5 px micro-cell facets, each
    with its own INDEPENDENT continuous M/R/CC. Stacked layers: fracture
    seam hairlines (3-9 px), facet-corner glints, dim trench specks for
    shadow depth, and a wide chroma carpet. NEW hero motif: 5-9 SHATTER
    STAR centers â€” bright single-pixel cores from which 6-10 white-hot
    splinter rays (10-22 px) radiate outward through the pavÃ©, mimicking
    the moment a crystal cracks. Each star also gets a dark concentric
    shock ring just outside (negative space). Per-feature wide chroma.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + (hash("micro_facets_r6") % 10000))
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)
    cs = max(3, int(max(4, facet_size) * 0.55))

    def _fbm(off, sigma):
        if _CV2_OK:
            sh = max(64, h // 10); sw = max(64, w // 10)
            n = np.random.default_rng(int(seed) + off).random((sh, sw)).astype(np.float32)
            b = _cv2.GaussianBlur(n, (0, 0), sigmaX=sigma, sigmaY=sigma)
            return _normalize(_cv2.resize(b, (w, h), interpolation=_cv2.INTER_CUBIC).astype(np.float32))
        return _normalize(multi_scale_noise(shape, [20.0, 40.0], [0.6, 0.4], int(seed) + off))

    # 1) BASE â€” independent per-channel FBM
    fM  = _fbm(6410, 3.0); fR = _fbm(6412, 3.0); fCC = _fbm(6414, 3.0)
    M  = 0.35 + (fM  - 0.5) * 0.20
    R_ch = 0.45 + (fR  - 0.5) * 0.24
    CC = 0.42 + (fCC - 0.5) * 0.24

    # 2) MICRO-CELL FACETS â€” jittered nearest-neighbor lookup
    ny, nx = max(2, h // cs), max(2, w // cs)
    cv_M  = rng.uniform(0.28, 0.96, size=(ny + 2, nx + 2)).astype(np.float32)
    cv_R  = rng.uniform(0.03, 0.62, size=(ny + 2, nx + 2)).astype(np.float32)
    cv_CC = rng.uniform(0.18, 0.98, size=(ny + 2, nx + 2)).astype(np.float32)
    yy = (np.arange(h, dtype=np.float32) / max(h, 1)) * ny
    xx = (np.arange(w, dtype=np.float32) / max(w, 1)) * nx
    yj = (yy + rng.uniform(-0.45, 0.45, h)).astype(np.int32)
    xj = (xx + rng.uniform(-0.45, 0.45, w)).astype(np.int32)
    yj = np.clip(yj, 0, ny); xj = np.clip(xj, 0, nx)
    yi2 = yj[:, None]; xi2 = xj[None, :]
    facet_M  = cv_M[yi2, xi2]
    facet_R  = cv_R[yi2, xi2]
    facet_CC = cv_CC[yi2, xi2]
    blend = 0.78
    M  = M  * (1 - blend) + facet_M  * blend
    R_ch = R_ch * (1 - blend) + facet_R  * blend
    CC = CC * (1 - blend) + facet_CC * blend

    if _CV2_OK:
        # 3) FRACTURE-SEAM HAIRLINES (3-9 px)
        n_seam = int(np.clip(8200 * (mn / 2048.0) ** 2, 2700, 24500))
        for _ in range(n_seam):
            cx = rng.uniform(0, w); cy = rng.uniform(0, h)
            length = float(rng.uniform(3.0, 9.0) * scale)
            ang = float(rng.uniform(0, 2 * np.pi))
            x2 = int(np.clip(cx + np.cos(ang) * length, 0, w - 1))
            y2 = int(np.clip(cy + np.sin(ang) * length, 0, h - 1))
            _cv2.line(R_ch, (int(cx), int(cy)), (x2, y2), float(rng.uniform(0.35, 0.88)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (int(cx), int(cy)), (x2, y2), float(rng.uniform(0.18, 0.62)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(M, (int(cx), int(cy)), (x2, y2), float(rng.uniform(0.20, 0.85)), 1, lineType=_cv2.LINE_AA)

        # 4) FACET-CORNER GLINTS
        n_g = int(np.clip(4200 * (mn / 2048.0) ** 2, 1400, 12500))
        for _ in range(n_g):
            cx = int(rng.uniform(0, w)); cy = int(rng.uniform(0, h))
            r = max(1, int(rng.uniform(1.0, 2.0) * scale))
            _cv2.circle(M,  (cx, cy), r, float(rng.uniform(0.78, 0.99)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R_ch, (cx, cy), r, float(rng.uniform(0.04, 0.25)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r, float(rng.uniform(0.55, 0.99)), -1, lineType=_cv2.LINE_AA)

        # 5) HERO MOTIF â€” SHATTER STARS (5-9 across canvas)
        n_star = int(rng.integers(5, 10))
        for _ in range(n_star):
            sx = int(rng.uniform(20, w - 20))
            sy = int(rng.uniform(20, h - 20))
            n_rays = int(rng.integers(6, 11))
            base_ang = float(rng.uniform(0, 2 * np.pi))
            for k in range(n_rays):
                ang = base_ang + k * (2 * np.pi / n_rays) + float(rng.uniform(-0.12, 0.12))
                length = float(rng.uniform(10.0, 22.0) * scale)
                x2 = int(np.clip(sx + np.cos(ang) * length, 0, w - 1))
                y2 = int(np.clip(sy + np.sin(ang) * length, 0, h - 1))
                _cv2.line(M, (sx, sy), (x2, y2), float(rng.uniform(0.82, 0.99)), 1, lineType=_cv2.LINE_AA)
                _cv2.line(R_ch, (sx, sy), (x2, y2), float(rng.uniform(0.03, 0.16)), 1, lineType=_cv2.LINE_AA)
                _cv2.line(CC, (sx, sy), (x2, y2), float(rng.uniform(0.55, 0.99)), 1, lineType=_cv2.LINE_AA)
            # bright core
            _cv2.circle(M, (sx, sy), max(1, int(scale * 2.0)), float(rng.uniform(0.92, 0.99)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R_ch, (sx, sy), max(1, int(scale * 2.0)), float(rng.uniform(0.03, 0.10)), -1, lineType=_cv2.LINE_AA)
            # dark shock ring
            shock_r = max(3, int(rng.uniform(5.0, 9.0) * scale))
            _cv2.circle(R_ch, (sx, sy), shock_r, float(rng.uniform(0.78, 0.95)), 1, lineType=_cv2.LINE_AA)

    # 6) TRENCH SPECKS â€” dim shadow points
    n_dk = int(np.clip(mn * mn * 0.0040, 6000, 40000))
    dy = rng.integers(0, h, n_dk); dx = rng.integers(0, w, n_dk)
    M[dy, dx]  = np.minimum(M[dy, dx],  rng.uniform(0.06, 0.30, n_dk).astype(np.float32))
    R_ch[dy, dx] = np.maximum(R_ch[dy, dx], rng.uniform(0.40, 0.88, n_dk).astype(np.float32))
    CC[dy, dx] = np.minimum(CC[dy, dx], rng.uniform(0.06, 0.30, n_dk).astype(np.float32))

    # 7) BRIGHT CHROMA CARPET
    n_carpet = max(7500, int(h * w / 85))
    cy_c = rng.integers(0, h, n_carpet); cx_c = rng.integers(0, w, n_carpet)
    M[cy_c, cx_c]  = np.maximum(M[cy_c, cx_c],  rng.uniform(0.50, 0.95, n_carpet).astype(np.float32))
    CC[cy_c, cx_c] = rng.uniform(0.18, 0.98, n_carpet).astype(np.float32)

    out = np.stack([np.clip(M, 0, 1), np.clip(R_ch, 0, 1), np.clip(CC, 0, 1)], axis=-1).astype(np.float32)
    return _sm_scale(out, sm)
micro_facets._spb_concept_complete = True


# ============================================================================
# 19. MOIRE OVERLAY â€” overlapping grids creating moirÃ© interference
# ============================================================================

def moire_overlay(shape, seed, sm, **kwargs):
    """moire_overlay.

    identity: R6-CREATIVE â€” TRIPLE MOIRE INTERFERENCE FIELD with HERO
    focal swirl. Three independent grating pairs per channel (M, R, CC)
    create chromatically offset beat patterns at 8-20 px scale. NEW
    HERO: 2-4 SPIRAL VORTEX CENTERS where beats appear to converge â€”
    radial fine concentric rings (4-12 px spacing) emanating from a
    randomly placed focus, modulating each channel independently to
    create a strong eye-catching focal motif over the global beat
    field. Plus 5x crest pinpoint glints, 8-18 px crest hairlines,
    dark seam specks. Per-feature INDEPENDENT continuous uniforms.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 17601)
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)

    yy = np.arange(h, dtype=np.float32) / max(h, 1)
    xx = np.arange(w, dtype=np.float32) / max(w, 1)
    Y, X = np.meshgrid(yy, xx, indexing='ij')

    twopi = np.pi * 2.0
    # 1) THREE INDEPENDENT GRATING PAIRS â€” each channel gets its own beat
    aM = 0.045 + float(rng.uniform(-0.01, 0.01))
    g1 = np.sin(Y * 195.0 * twopi)
    proj_M = Y * np.cos(aM) + X * np.sin(aM)
    g2 = np.sin(proj_M * 205.0 * twopi)
    beat_M = ((g1 * g2) * 0.5 + 0.5).astype(np.float32)

    aR = 0.060 + float(rng.uniform(-0.01, 0.01))
    g3 = np.sin(X * 198.0 * twopi)
    proj_R = X * np.cos(aR) - Y * np.sin(aR)
    g4 = np.sin(proj_R * 210.0 * twopi)
    beat_R = ((g3 * g4) * 0.5 + 0.5).astype(np.float32)

    aCC = 0.038 + float(rng.uniform(-0.01, 0.01))
    g5 = np.sin((Y + X * 0.5) * 200.0 * twopi)
    proj_CC = (Y + X * 0.5) * np.cos(aCC) + (X - Y * 0.5) * np.sin(aCC)
    g6 = np.sin(proj_CC * 213.0 * twopi)
    beat_CC = ((g5 * g6) * 0.5 + 0.5).astype(np.float32)

    # 2) CREST EXTRACTION per channel
    crest_M = np.clip((beat_M - 0.78) * 5.0, 0.0, 1.0).astype(np.float32)
    crest_CC = np.clip((beat_CC - 0.78) * 5.0, 0.0, 1.0).astype(np.float32)

    M  = 0.42 + (beat_M - 0.5) * 0.42 + crest_M * 0.30
    R_ch = 0.45 - (beat_R - 0.5) * 0.36 - crest_M * 0.18
    CC = 0.40 + (beat_CC - 0.5) * 0.38 + crest_CC * 0.34

    # 3) RING-CREST GLINT DOTS â€” 5x density (vectorized + masked)
    n_g = int(np.clip(5500 * (mn / 2048.0) ** 2, 2000, 22000))
    gx = rng.integers(0, w, n_g); gy = rng.integers(0, h, n_g)
    bright = (crest_M[gy, gx] + crest_CC[gy, gx]) * 0.5
    keep = bright > 0.35
    gx = gx[keep]; gy = gy[keep]
    if gx.size:
        M[gy, gx]  = np.maximum(M[gy, gx],  rng.uniform(0.72, 0.99, gx.size).astype(np.float32))
        CC[gy, gx] = np.maximum(CC[gy, gx], rng.uniform(0.65, 0.97, gx.size).astype(np.float32))
        R_ch[gy, gx] = np.minimum(R_ch[gy, gx], rng.uniform(0.05, 0.25, gx.size).astype(np.float32))

    # 4) SHORT CREST HAIRLINES â€” 8-18 px along beat direction
    if _CV2_OK:
        n_hair = int(np.clip(1200 * (mn / 2048.0) ** 2, 450, 4500))
        for _ in range(n_hair):
            cx = float(rng.uniform(0, w)); cy = float(rng.uniform(0, h))
            length = float(rng.uniform(8.0, 18.0) * scale)
            ang = float(rng.uniform(0, np.pi))
            x2 = int(np.clip(cx + np.cos(ang) * length, 0, w - 1))
            y2 = int(np.clip(cy + np.sin(ang) * length, 0, h - 1))
            _cv2.line(M, (int(cx), int(cy)), (x2, y2), float(rng.uniform(0.55, 0.92)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (int(cx), int(cy)), (x2, y2), float(rng.uniform(0.50, 0.90)), 1, lineType=_cv2.LINE_AA)

    # 5) DARK SEAM SPECKS â€” null-interference points (5x density)
    n_dk = int(np.clip(mn * mn * 0.003, 4000, 28000))
    dy = rng.integers(0, h, n_dk); dx = rng.integers(0, w, n_dk)
    M[dy, dx]  = np.minimum(M[dy, dx],  rng.uniform(0.05, 0.25, n_dk).astype(np.float32))
    R_ch[dy, dx] = np.maximum(R_ch[dy, dx], rng.uniform(0.55, 0.92, n_dk).astype(np.float32))

    # 6) HERO FOCAL SWIRL VORTICES â€” 2-4 spirals where beats converge
    n_vortex = int(rng.integers(2, 5))
    for _ in range(n_vortex):
        vx = float(rng.uniform(0.15, 0.85) * w)
        vy = float(rng.uniform(0.15, 0.85) * h)
        # Local crop region for vortex (radius up to ~80 px)
        v_rad = float(rng.uniform(50.0, 90.0) * scale)
        y0 = max(0, int(vy - v_rad)); y1 = min(h, int(vy + v_rad))
        x0 = max(0, int(vx - v_rad)); x1 = min(w, int(vx + v_rad))
        if y1 <= y0 or x1 <= x0:
            continue
        sub_y = np.arange(y0, y1, dtype=np.float32)[:, None]
        sub_x = np.arange(x0, x1, dtype=np.float32)[None, :]
        dy_v = sub_y - vy; dx_v = sub_x - vx
        dist = np.sqrt(dy_v * dy_v + dx_v * dx_v)
        ang_v = np.arctan2(dy_v, dx_v)
        # Spiral phase: combine distance and angle
        spiral_freq = float(rng.uniform(0.5, 1.0))  # rings per ~8-12 px
        spiral_phase = float(rng.uniform(2.0, 4.0))  # arm twist amount
        rings = np.sin(dist * spiral_freq + ang_v * spiral_phase).astype(np.float32)
        # Vignette so HERO fades into background beat field
        falloff = np.clip(1.0 - dist / v_rad, 0.0, 1.0)
        falloff = (falloff * falloff).astype(np.float32)
        m_amp = float(rng.uniform(0.25, 0.40))
        r_amp = float(rng.uniform(0.18, 0.30))
        cc_amp = float(rng.uniform(0.22, 0.36))
        M[y0:y1, x0:x1] = np.clip(M[y0:y1, x0:x1] + rings * falloff * m_amp, 0, 1)
        R_ch[y0:y1, x0:x1] = np.clip(R_ch[y0:y1, x0:x1] - rings * falloff * r_amp, 0, 1)
        CC[y0:y1, x0:x1] = np.clip(CC[y0:y1, x0:x1] + rings * falloff * cc_amp, 0, 1)

    out = np.stack([M, R_ch, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
moire_overlay._spb_concept_complete = True


# ============================================================================
# 20. PEBBLE GRAIN â€” large rounded bumps like leather grain
# ============================================================================

def pebble_grain(shape, seed, sm, pebble_size=15, roundness=0.7, **kwargs):
    """pebble_grain.

    identity (R6 CREATIVE rebuild): true leather-pebble dome field with a
    HERO motif of QUILTED DOUBLE-STITCH SEAMS dividing the field into
    diamond-quilt panels â€” like the back of a high-end racing seat. Per-
    pebble INDEPENDENT M/R/CC, real dome shading from sqrt-distance
    falloff, dark crevice grout BETWEEN domes (not on top), per-pebble
    specular highlight offset (off-center crest glint). Stacked: (a)
    pebble dome field with per-pebble chroma, (b) 5x-densified crevice
    hairlines, (c) bright crest glints, (d) dark pore pits, (e) pinpoint
    fleck sparkle, (f) HERO quilt-seam grooves (2-3 px wide diagonal
    bands carving the panel into 64-110 px diamond cells), (g) HERO
    double-stitch dotted line riding each seam (2 px bright thread
    knots spaced every 4 px). Wide chroma diversity throughout.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 78329)
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)
    # Finer pebbles: 6-10 px target
    ps = max(4, int(8.0 * scale * 1.0)) if mn >= 512 else max(4, 8)
    pebble_radius = ps * 0.65

    ny = max(2, h // ps + 2)
    nx = max(2, w // ps + 2)

    jitter_y = rng.uniform(0.1, 0.9, size=(ny, nx))
    jitter_x = rng.uniform(0.1, 0.9, size=(ny, nx))
    n_cells = ny * nx
    cell_M = rng.uniform(0.18, 0.95, size=n_cells).astype(np.float32)
    cell_R = rng.uniform(0.08, 0.88, size=n_cells).astype(np.float32)
    cell_CC = rng.uniform(0.06, 0.88, size=n_cells).astype(np.float32)
    # Per-pebble highlight offset direction (sub-pebble specular angle)
    cell_hl = rng.uniform(0, 2 * np.pi, size=n_cells).astype(np.float32)

    iy_arr = np.arange(ny, dtype=np.float64)
    ix_arr = np.arange(nx, dtype=np.float64)
    IY, IX = np.meshgrid(iy_arr, ix_arr, indexing='ij')
    center_y = (IY + jitter_y) * ps
    center_x = (IX + jitter_x) * ps
    centers = np.column_stack([center_y.ravel(), center_x.ravel()])
    tree = cKDTree(centers)

    yy, xx = np.mgrid[0:h, 0:w].astype(np.float64)
    pts = np.column_stack([yy.ravel(), xx.ravel()])
    dists, idxs = tree.query(pts, k=1, workers=-1)
    min_dist = dists.reshape((h, w)).astype(np.float32)
    # Dome shading via sqrt falloff
    dome = np.clip(1.0 - (min_dist / pebble_radius) ** 1.2, 0, 1).astype(np.float32)
    crevice = (1.0 - dome)

    # Per-pebble nearest-neighbor lookup
    nearest_M = cell_M[idxs].reshape((h, w))
    nearest_R = cell_R[idxs].reshape((h, w))
    nearest_CC = cell_CC[idxs].reshape((h, w))

    # Per-pebble specular highlight offset â€” pretend light comes from upper-left
    cy_nearest = centers[idxs, 0].reshape((h, w)).astype(np.float32)
    cx_nearest = centers[idxs, 1].reshape((h, w)).astype(np.float32)
    hl_ang = cell_hl[idxs].reshape((h, w))
    dxn = (xx.astype(np.float32) - cx_nearest)
    dyn = (yy.astype(np.float32) - cy_nearest)
    proj_hl = dxn * np.cos(hl_ang) + dyn * np.sin(hl_ang)
    spec_hl = np.exp(-(proj_hl - pebble_radius * 0.35) ** 2 / (2 * (pebble_radius * 0.35) ** 2)).astype(np.float32) * dome

    # Regional FBM grime
    g_M = _normalize(_spb_fast_smooth_noise((h, w), [3.0, 9.0, 22.0], [0.5, 0.3, 0.2], int(seed) + 11))
    g_R = _normalize(_spb_fast_smooth_noise((h, w), [3.5, 9.0, 22.0], [0.5, 0.3, 0.2], int(seed) + 13))
    g_CC = _normalize(_spb_fast_smooth_noise((h, w), [5.0, 14.0, 30.0], [0.5, 0.3, 0.2], int(seed) + 17))

    M  = nearest_M * (0.45 + dome * 0.55) + spec_hl * 0.25 - crevice * 0.18 + (g_M - 0.5) * 0.12
    R_ch = nearest_R * (0.85 - dome * 0.25) + crevice * 0.25 + (g_R - 0.5) * 0.12
    CC = nearest_CC * (0.50 + dome * 0.45) + spec_hl * 0.18 - crevice * 0.20 + (g_CC - 0.5) * 0.10

    M = np.clip(M, 0, 1).astype(np.float32)
    R_ch = np.clip(R_ch, 0, 1).astype(np.float32)
    CC = np.clip(CC, 0, 1).astype(np.float32)

    if _CV2_OK:
        # Crevice hairlines 8-18 px (5x density)
        n_l = int(np.clip(2200 * (mn / 2048.0) ** 2, 750, 8000))
        for _ in range(n_l):
            cx = float(rng.uniform(4, w - 4)); cy = float(rng.uniform(4, h - 4))
            length = float(rng.uniform(8.0, 18.0) * scale)
            ang = float(rng.uniform(0, 2 * np.pi))
            x0s = int(cx - np.cos(ang) * length * 0.5)
            y0s = int(cy - np.sin(ang) * length * 0.5)
            x1s = int(cx + np.cos(ang) * length * 0.5)
            y1s = int(cy + np.sin(ang) * length * 0.5)
            _cv2.line(M, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.05, 0.28)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(R_ch, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.65, 0.95)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.55, 0.92)), 1, lineType=_cv2.LINE_AA)
        # Bright crest glints 2-4 px (5x)
        n_g = int(np.clip(3500 * (mn / 2048.0) ** 2, 1200, 14000))
        for _ in range(n_g):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            r = max(1, int(rng.uniform(1.5, 3.5) * scale))
            _cv2.circle(M, (cx, cy), r, float(rng.uniform(0.78, 0.99)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R_ch, (cx, cy), r, float(rng.uniform(0.04, 0.22)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r, float(rng.uniform(0.04, 0.22)), -1, lineType=_cv2.LINE_AA)

    # Accent dark pore pits + bright pinpoints (vectorized 5x)
    n_pits = int(np.clip(3000 * (mn / 2048.0) ** 2, 1000, 12000))
    ddy = rng.integers(0, h, n_pits); ddx = rng.integers(0, w, n_pits)
    M[ddy, ddx] = np.minimum(M[ddy, ddx], rng.uniform(0.04, 0.20, n_pits).astype(np.float32))
    R_ch[ddy, ddx] = np.maximum(R_ch[ddy, ddx], rng.uniform(0.55, 0.95, n_pits).astype(np.float32))
    n_fl = int(np.clip(4000 * (mn / 2048.0) ** 2, 1400, 16000))
    fy = rng.integers(0, h, n_fl); fx = rng.integers(0, w, n_fl)
    M[fy, fx] = np.maximum(M[fy, fx], rng.uniform(0.70, 0.99, n_fl).astype(np.float32))
    CC[fy, fx] = np.minimum(CC[fy, fx], rng.uniform(0.05, 0.22, n_fl).astype(np.float32))

    if _CV2_OK:
        # HERO QUILT-SEAM GROOVES + DOUBLE STITCH â€” diamond quilt overlay.
        # Two crossing diagonal seam families at +/- 45deg, spaced ~80 px,
        # each seam carries a dotted bright-thread stitch line.
        diag_spacing = float(np.clip(90.0 * scale, 56.0, 130.0))
        # axis A: u_a = (x + y) ; iso-lines u_a = k * spacing
        # axis B: u_b = (x - y)
        u_a = (np.arange(w)[None, :] + np.arange(h)[:, None]).astype(np.float32)
        u_b = (np.arange(w)[None, :] - np.arange(h)[:, None]).astype(np.float32)
        # carve seam: dark groove where |u % spacing - 0| < eps
        eps = 1.6  # groove half-width in px (2-3 px wide)
        groove_a = (np.abs((u_a % diag_spacing) - diag_spacing * 0.5) > (diag_spacing * 0.5 - eps))
        groove_b = (np.abs((u_b % diag_spacing) - diag_spacing * 0.5) > (diag_spacing * 0.5 - eps))
        groove = groove_a | groove_b
        # Apply dark groove
        groove_mask = groove.astype(np.float32)
        # randomize groove darkness per seam line via low-freq noise on the axes
        gn = _normalize(_spb_fast_smooth_noise(shape, [6.0, 18.0], [0.6, 0.4], int(seed) + 4001)).astype(np.float32)
        M = M * (1 - groove_mask * 0.65) + groove_mask * (0.08 + gn * 0.22)
        R_ch = R_ch * (1 - groove_mask * 0.30) + groove_mask * (0.72 + gn * 0.18)
        CC = CC * (1 - groove_mask * 0.35) + groove_mask * (0.65 + gn * 0.20)
        # Double-stitch knots: bright dots every ~4 px along each seam
        # Walk along axis A
        for k in range(int(-h / diag_spacing) - 1, int((h + w) / diag_spacing) + 2):
            c = k * diag_spacing + diag_spacing * 0.5
            # axis A seam: x + y = c  => for x in 0..w-1, y = c - x
            x_range = np.arange(0, w, 4)
            y_range = (c - x_range).astype(np.int32)
            valid = (y_range >= 0) & (y_range < h)
            xs = x_range[valid]; ys = y_range[valid]
            jitter = rng.integers(-1, 2, size=xs.shape[0])
            ys = np.clip(ys + jitter, 0, h - 1)
            knot_M = rng.uniform(0.78, 0.99, size=xs.shape[0]).astype(np.float32)
            knot_R = rng.uniform(0.04, 0.22, size=xs.shape[0]).astype(np.float32)
            knot_CC = rng.uniform(0.03, 0.18, size=xs.shape[0]).astype(np.float32)
            M[ys, xs] = np.maximum(M[ys, xs], knot_M)
            R_ch[ys, xs] = np.minimum(R_ch[ys, xs], knot_R)
            CC[ys, xs] = np.minimum(CC[ys, xs], knot_CC)
        # axis B seam: x - y = c
        for k in range(int(-h / diag_spacing) - 1, int((h + w) / diag_spacing) + 2):
            c = k * diag_spacing + diag_spacing * 0.5
            x_range = np.arange(0, w, 4)
            y_range = (x_range - c).astype(np.int32)
            valid = (y_range >= 0) & (y_range < h)
            xs = x_range[valid]; ys = y_range[valid]
            jitter = rng.integers(-1, 2, size=xs.shape[0])
            ys = np.clip(ys + jitter, 0, h - 1)
            knot_M = rng.uniform(0.78, 0.99, size=xs.shape[0]).astype(np.float32)
            knot_R = rng.uniform(0.04, 0.22, size=xs.shape[0]).astype(np.float32)
            knot_CC = rng.uniform(0.03, 0.18, size=xs.shape[0]).astype(np.float32)
            M[ys, xs] = np.maximum(M[ys, xs], knot_M)
            R_ch[ys, xs] = np.minimum(R_ch[ys, xs], knot_R)
            CC[ys, xs] = np.minimum(CC[ys, xs], knot_CC)

    out = np.stack([np.clip(M, 0, 1), np.clip(R_ch, 0, 1), np.clip(CC, 0, 1)], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
pebble_grain._spb_concept_complete = True


# ============================================================================
# 21. RADIAL SUNBURST â€” rays emanating from center
# ============================================================================

def radial_sunburst(shape, seed, sm, num_rays=12, sharpness=2.0,
                    center_glow=0.3, **kwargs):
    """radial_sunburst â€” R6 CREATIVE rebuild.

    identity: PRISMATIC MULTI-SCALE STARBURSTS on a DEEP VELVET FIELD â€”
    no brushed substrate this time. Hero motif: a multi-tier population
    of dingbat star-bursts where each TIER (small/medium/large micro-
    star) has a distinct count and visual character. Large stars (16-22
    px, sparse, with 10-14 chromatic spokes that ramp M/R/CC ALONG the
    arm length â€” bright at hub fading dark at tip). Medium stars (8-14
    px, 6-9 spokes, fully bright). Small stars (4-7 px, 4-5 spokes,
    plus a 1 px hot center). Stacked: (1) deep dark velvet FBM
    substrate (low M, high R, high CC), (2) sparse large prismatic
    chromatic stars with per-arm ramped chroma, (3) medium 8-14 px
    stars, (4) small 4-7 px stars, (5) tiny halo rings (1-3 px) seeded
    around large stars, (6) dust mote pinpoints, (7) faint glow corona
    at large-star centers via small bright dot. Per-feature INDEPENDENT
    continuous M/R/CC uniforms.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 27411)
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)

    # 1) DEEP VELVET BASE â€” dark, soft, INDEPENDENT M/R/CC
    g_M = _normalize(multi_scale_noise((h, w), [2.0, 5.5, 13.0], [0.40, 0.32, 0.24], int(seed) + 51))
    g_R = _normalize(multi_scale_noise((h, w), [2.2, 6.0, 14.0], [0.42, 0.32, 0.22], int(seed) + 57))
    g_CC = _normalize(multi_scale_noise((h, w), [2.4, 6.4, 15.0], [0.42, 0.30, 0.24], int(seed) + 63))
    M = (0.20 + (g_M - 0.5) * 0.18).astype(np.float32)  # dark velvet
    R = (0.62 + (g_R - 0.5) * 0.20).astype(np.float32)  # mid-soft
    CC = (0.52 + (g_CC - 0.5) * 0.22).astype(np.float32)

    # store star centers to seed halos
    large_centers = []

    if _CV2_OK:
        # 2) LARGE PRISMATIC STARBURSTS â€” chromatic ramp along each arm
        n_large = int(np.clip(110 * (mn / 2048.0) ** 2, 28, 320))
        for _ in range(n_large):
            cx = int(rng.uniform(0.05, 0.95) * w); cy = int(rng.uniform(0.05, 0.95) * h)
            large_centers.append((cx, cy))
            reach = float(rng.uniform(10.0, 14.0) * scale)
            n_spokes = int(rng.integers(10, 15))
            base_ang = float(rng.uniform(0, 2 * np.pi))
            # bright hub chroma
            hub_M = float(rng.uniform(0.78, 0.99))
            tip_M = float(rng.uniform(0.10, 0.35))
            hub_R = float(rng.uniform(0.05, 0.18))
            tip_R = float(rng.uniform(0.55, 0.92))
            hub_CC = float(rng.uniform(0.04, 0.15))
            tip_CC = float(rng.uniform(0.45, 0.80))
            for i in range(n_spokes):
                ang = base_ang + i * (2 * np.pi / n_spokes) + float(rng.uniform(-0.08, 0.08))
                # build the arm as 3 segments with ramped chroma
                for seg in range(3):
                    t0 = seg / 3.0; t1 = (seg + 1) / 3.0
                    sx0 = int(np.clip(cx + np.cos(ang) * reach * t0, 0, w - 1))
                    sy0 = int(np.clip(cy + np.sin(ang) * reach * t0, 0, h - 1))
                    sx1 = int(np.clip(cx + np.cos(ang) * reach * t1, 0, w - 1))
                    sy1 = int(np.clip(cy + np.sin(ang) * reach * t1, 0, h - 1))
                    t_mid = (t0 + t1) * 0.5
                    mv  = float(hub_M  * (1 - t_mid) + tip_M  * t_mid)
                    rv  = float(hub_R  * (1 - t_mid) + tip_R  * t_mid)
                    cv  = float(hub_CC * (1 - t_mid) + tip_CC * t_mid)
                    _cv2.line(M,  (sx0, sy0), (sx1, sy1), mv, 1, lineType=_cv2.LINE_AA)
                    _cv2.line(R,  (sx0, sy0), (sx1, sy1), rv, 1, lineType=_cv2.LINE_AA)
                    _cv2.line(CC, (sx0, sy0), (sx1, sy1), cv, 1, lineType=_cv2.LINE_AA)
            # bright hub spot (corona)
            _cv2.circle(M,  (cx, cy), max(2, int(2 * scale)), float(rng.uniform(0.85, 0.99)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), max(2, int(2 * scale)), float(rng.uniform(0.03, 0.12)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R,  (cx, cy), max(2, int(2 * scale)), float(rng.uniform(0.03, 0.12)), -1, lineType=_cv2.LINE_AA)

        # 3) MEDIUM STARS â€” 8-14 px, 6-9 spokes
        n_med = int(np.clip(540 * (mn / 2048.0) ** 2, 180, 1500))
        for _ in range(n_med):
            cx = int(rng.uniform(0.02, 0.98) * w); cy = int(rng.uniform(0.02, 0.98) * h)
            reach = float(rng.uniform(4.0, 7.0) * scale)
            n_spokes = int(rng.integers(6, 10))
            base_ang = float(rng.uniform(0, 2 * np.pi))
            mv = float(rng.uniform(0.62, 0.96))
            rv = float(rng.uniform(0.06, 0.26))
            cv = float(rng.uniform(0.05, 0.22))
            for i in range(n_spokes):
                ang = base_ang + i * (2 * np.pi / n_spokes) + float(rng.uniform(-0.05, 0.05))
                ex = int(np.clip(cx + np.cos(ang) * reach, 0, w - 1))
                ey = int(np.clip(cy + np.sin(ang) * reach, 0, h - 1))
                _cv2.line(M,  (cx, cy), (ex, ey), mv, 1, lineType=_cv2.LINE_AA)
                _cv2.line(R,  (cx, cy), (ex, ey), rv, 1, lineType=_cv2.LINE_AA)
                _cv2.line(CC, (cx, cy), (ex, ey), cv, 1, lineType=_cv2.LINE_AA)

        # 4) SMALL STARS â€” 4-7 px, 4-5 spokes, with 1 px hot center
        n_small = int(np.clip(1800 * (mn / 2048.0) ** 2, 600, 5200))
        for _ in range(n_small):
            cx = int(rng.uniform(0.01, 0.99) * w); cy = int(rng.uniform(0.01, 0.99) * h)
            reach = float(rng.uniform(2.0, 3.5) * scale)
            n_spokes = int(rng.integers(4, 6))
            base_ang = float(rng.uniform(0, 2 * np.pi))
            mv = float(rng.uniform(0.58, 0.95))
            rv = float(rng.uniform(0.07, 0.28))
            cv = float(rng.uniform(0.06, 0.24))
            for i in range(n_spokes):
                ang = base_ang + i * (2 * np.pi / n_spokes)
                ex = int(np.clip(cx + np.cos(ang) * reach, 0, w - 1))
                ey = int(np.clip(cy + np.sin(ang) * reach, 0, h - 1))
                _cv2.line(M,  (cx, cy), (ex, ey), mv, 1, lineType=_cv2.LINE_AA)
                _cv2.line(R,  (cx, cy), (ex, ey), rv, 1, lineType=_cv2.LINE_AA)
                _cv2.line(CC, (cx, cy), (ex, ey), cv, 1, lineType=_cv2.LINE_AA)
            _cv2.circle(M,  (cx, cy), 1, float(rng.uniform(0.80, 0.99)), -1, lineType=_cv2.LINE_AA)

        # 5) HALO RINGS around large stars â€” 6-12 px
        for (cx, cy) in large_centers:
            n_h = int(rng.integers(1, 4))
            for _ in range(n_h):
                rr = max(3, int(rng.uniform(6.0, 12.0) * scale * 0.5))
                _cv2.circle(M,  (cx, cy), rr, float(rng.uniform(0.32, 0.72)), 1, lineType=_cv2.LINE_AA)
                _cv2.circle(R,  (cx, cy), rr, float(rng.uniform(0.18, 0.50)), 1, lineType=_cv2.LINE_AA)
                _cv2.circle(CC, (cx, cy), rr, float(rng.uniform(0.15, 0.45)), 1, lineType=_cv2.LINE_AA)

    # 6) DUST MOTE PINPOINTS â€” per-pixel INDEPENDENT uniforms
    n_dust = max(2400, int(h * w / 700))
    dy = rng.integers(0, h, n_dust); dx = rng.integers(0, w, n_dust)
    M[dy, dx] = np.maximum(M[dy, dx], rng.uniform(0.55, 0.97, n_dust).astype(np.float32))
    R[dy, dx] = np.minimum(R[dy, dx], rng.uniform(0.05, 0.25, n_dust).astype(np.float32))
    CC[dy, dx] = np.minimum(CC[dy, dx], rng.uniform(0.04, 0.22, n_dust).astype(np.float32))

    # 7) Small dark void specks â€” pits between stars
    n_pits = max(900, int(h * w / 2000))
    py = rng.integers(0, h, n_pits); px = rng.integers(0, w, n_pits)
    M[py, px] = rng.uniform(0.04, 0.18, n_pits).astype(np.float32)
    R[py, px] = rng.uniform(0.60, 0.92, n_pits).astype(np.float32)

    # 8) HERO+ PRISM SPECTRUM RAINBOW SPILLS (Tick49 second-pass)
    # Short curved chroma-sweep arcs (8-16 px) cast off large-star pivots,
    # each arc walking through M/R/CC space as it curves so it reads as a
    # prismatic spectrum spill. Independent per-segment continuous uniforms.
    if _CV2_OK and large_centers:
        for (cx, cy) in large_centers:
            n_spill = int(rng.integers(0, 3))
            for _ in range(n_spill):
                # Arc geometry: ellipse outline, partial sweep
                rad = int(np.clip(rng.uniform(8.0, 16.0) * scale, 3, 22))
                ax_a = rad
                ax_b = max(2, int(rad * float(rng.uniform(0.55, 1.0))))
                rot = float(rng.uniform(0, 180))
                # walk a 7-segment chroma sweep so colors shift along arc
                start_ang = float(rng.uniform(0, 360))
                span = float(rng.uniform(70, 170))
                n_seg = 7
                for si in range(n_seg):
                    a0 = start_ang + span * si / n_seg
                    a1 = start_ang + span * (si + 1) / n_seg
                    # walk M up, R down, CC zigzag across the spectrum
                    t = si / max(1, (n_seg - 1))
                    mv = float(np.clip(0.30 + 0.62 * t + rng.uniform(-0.05, 0.05), 0.05, 0.99))
                    rv = float(np.clip(0.75 - 0.55 * t + rng.uniform(-0.05, 0.05), 0.05, 0.95))
                    cv = float(np.clip(0.25 + 0.55 * abs(0.5 - t) * 2 + rng.uniform(-0.05, 0.05), 0.05, 0.95))
                    _cv2.ellipse(M, (cx, cy), (ax_a, ax_b), rot, a0, a1, mv, 1, lineType=_cv2.LINE_AA)
                    _cv2.ellipse(R, (cx, cy), (ax_a, ax_b), rot, a0, a1, rv, 1, lineType=_cv2.LINE_AA)
                    _cv2.ellipse(CC, (cx, cy), (ax_a, ax_b), rot, a0, a1, cv, 1, lineType=_cv2.LINE_AA)

    out = np.stack([np.clip(M, 0, 1), np.clip(R, 0, 1), np.clip(CC, 0, 1)], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
radial_sunburst._spb_concept_complete = True


# ============================================================================
# 22. TOPOGRAPHIC STEPS â€” contour-line stepped levels
# ============================================================================

def topographic_steps(shape, seed, sm, num_levels=8, noise_octaves=3):
    """topographic_steps.

    identity: R6 creative pass â€” a cartographer's relief-map gone wild.
    Narrow 4-10 px terrace bands with dark hairline contour seams, but
    NEW HERO motifs make this a unique survey-chart vibe: (A) WAYPOINT
    X-MARKS â€” tiny 3-5 px crossed-line waypoint badges scattered like
    map legends, (B) SPIRAL WHIRLPOOL DEPRESSIONS â€” small 6-12 px
    inward Archimedean spirals reading as cyclonic basins, (C) RIDGE-
    LINE BRIGHTS â€” 1-px-wide bright crest lines along terrace gradient
    peaks adding a sun-lit highlight to the map. Stacked tiers: (1)
    high-freq elevation FBM, (2) dense terrace quantization, (3) per-
    terrace independent M/R/CC continuous uniforms, (4) fine grain,
    (5) contour hairlines, (6) summit dots, (7) sea-level pits,
    (8) HERO waypoint X-marks, (9) HERO spiral whirlpools, (10) ridge
    brights. INDEPENDENT continuous M/R/CC per primitive. Full-canvas.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 18920)
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)

    # 1) ELEVATION FIELD â€” much higher frequency to yield 4-10 px terraces
    yy = (np.arange(h, dtype=np.float32) / max(h, 1))[:, None]
    xx = (np.arange(w, dtype=np.float32) / max(w, 1))[None, :]
    field = np.zeros(shape, dtype=np.float32)
    amp = 1.0
    # Frequencies 3-4x previous (was 64,128,192) -> tight ridges
    octs = [180.0, 320.0, 540.0]
    env_a1, env_a2 = float(rng.uniform(0, 2*np.pi)), float(rng.uniform(0, 2*np.pi))
    amp_env = (np.sin(yy * 60.0 * np.pi + env_a1) * np.sin(xx * 60.0 * np.pi + env_a2)) * 0.5 + 0.5
    amp_env = (amp_env * 0.55 + 0.45).astype(np.float32)
    for f in octs:
        a1, a2 = float(rng.uniform(0, 2*np.pi)), float(rng.uniform(0, 2*np.pi))
        row_jit = rng.uniform(-1.4, 1.4, h).astype(np.float32)[:, None]
        col_jit = rng.uniform(-1.4, 1.4, w).astype(np.float32)[None, :]
        field += (np.sin(yy * f * np.pi + a1 + row_jit) *
                  np.sin(xx * f * np.pi + a2 + col_jit)) * amp * amp_env
        amp *= 0.58
    field = _normalize(field)

    # 2) DENSE TERRACE QUANTIZATION (more levels = narrower bands)
    levels = max(8, int(num_levels) * 3)
    stepped = np.round(field * (levels - 1)) / (levels - 1)
    quantized = stepped * (levels - 1)
    contour_lines = (np.abs(field * (levels - 1) - quantized) < 0.05).astype(np.float32)

    # 3) PER-TERRACE INDEPENDENT continuous uniform M/R/CC LUTs
    terrace_idx = np.clip((stepped * (levels - 1)).astype(np.int32), 0, levels - 1)
    M_lut = rng.uniform(0.15, 0.94, levels).astype(np.float32)
    R_lut = rng.uniform(0.15, 0.88, levels).astype(np.float32)
    CC_lut = rng.uniform(0.10, 0.88, levels).astype(np.float32)
    M = M_lut[terrace_idx]
    R_ch = R_lut[terrace_idx]
    CC = CC_lut[terrace_idx]

    # 4) PER-TERRACE FINE GRAIN
    g_grain = _normalize(multi_scale_noise(shape, [1.5, 4.0, 9.0], [0.45, 0.32, 0.23], int(seed) + 1131)) - 0.5
    M = M + g_grain * 0.10
    R_ch = R_ch + g_grain * 0.08
    CC = CC + g_grain * 0.07

    # 5) CONTOUR HAIRLINES â€” sharp, dark
    M = M - contour_lines * 0.32
    R_ch = R_ch + contour_lines * 0.26
    CC = CC + contour_lines * 0.24

    if _CV2_OK:
        # 6) SUMMIT MARKER DISCS â€” 1-3 px (was 2-5), denser
        n_elev = int(np.clip(2200 * (mn / 2048.0) ** 2, 700, 6000))
        for _ in range(n_elev):
            cx_t = int(rng.integers(0, w)); cy_t = int(rng.integers(0, h))
            r_t = max(1, int(rng.uniform(1.0, 3.0) * scale))
            _cv2.circle(M, (cx_t, cy_t), r_t, float(rng.uniform(0.55, 0.95)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R_ch, (cx_t, cy_t), r_t, float(rng.uniform(0.18, 0.55)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx_t, cy_t), r_t, float(rng.uniform(0.15, 0.55)), -1, lineType=_cv2.LINE_AA)
        # 7) SEA-LEVEL PIT DOTS â€” 1-2 px, denser
        n_sea = int(np.clip(1600 * (mn / 2048.0) ** 2, 500, 4500))
        for _ in range(n_sea):
            cx_t = int(rng.integers(0, w)); cy_t = int(rng.integers(0, h))
            r_t = max(1, int(rng.uniform(1.0, 2.0) * scale))
            _cv2.circle(M, (cx_t, cy_t), r_t, float(rng.uniform(0.08, 0.30)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R_ch, (cx_t, cy_t), r_t, float(rng.uniform(0.70, 0.95)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx_t, cy_t), r_t, float(rng.uniform(0.50, 0.88)), -1, lineType=_cv2.LINE_AA)

        # 8) HERO â€” WAYPOINT X-MARK BADGES (3-5 px crossed lines)
        n_way = int(np.clip(900 * (mn / 2048.0) ** 2, 280, 2400))
        for _ in range(n_way):
            cx_t = int(rng.integers(2, w - 2)); cy_t = int(rng.integers(2, h - 2))
            r_t = max(2, int(rng.uniform(2.0, 4.0) * scale))
            wM = float(rng.uniform(0.65, 0.97)); wR = float(rng.uniform(0.08, 0.34)); wCC = float(rng.uniform(0.06, 0.32))
            _cv2.line(M, (cx_t - r_t, cy_t - r_t), (cx_t + r_t, cy_t + r_t), wM, 1, lineType=_cv2.LINE_AA)
            _cv2.line(M, (cx_t - r_t, cy_t + r_t), (cx_t + r_t, cy_t - r_t), wM, 1, lineType=_cv2.LINE_AA)
            _cv2.line(R_ch, (cx_t - r_t, cy_t - r_t), (cx_t + r_t, cy_t + r_t), wR, 1, lineType=_cv2.LINE_AA)
            _cv2.line(R_ch, (cx_t - r_t, cy_t + r_t), (cx_t + r_t, cy_t - r_t), wR, 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (cx_t - r_t, cy_t - r_t), (cx_t + r_t, cy_t + r_t), wCC, 1, lineType=_cv2.LINE_AA)

        # 9) HERO â€” SPIRAL WHIRLPOOL DEPRESSIONS (6-12 px Archimedean)
        n_spiral = int(np.clip(280 * (mn / 2048.0) ** 2, 90, 900))
        for _ in range(n_spiral):
            cx_t = int(rng.integers(4, w - 4)); cy_t = int(rng.integers(4, h - 4))
            r_max = float(rng.uniform(3.0, 6.0) * scale)
            spM = float(rng.uniform(0.12, 0.40))
            spR = float(rng.uniform(0.60, 0.92))
            spCC = float(rng.uniform(0.10, 0.40))
            n_pts = 22
            prev = None
            for k in range(n_pts):
                t_ang = k * 0.42
                r_k = r_max * (k / max(n_pts - 1, 1))
                px = int(np.clip(cx_t + np.cos(t_ang) * r_k, 0, w - 1))
                py = int(np.clip(cy_t + np.sin(t_ang) * r_k, 0, h - 1))
                if prev is not None:
                    _cv2.line(M, prev, (px, py), spM, 1, lineType=_cv2.LINE_AA)
                    _cv2.line(R_ch, prev, (px, py), spR, 1, lineType=_cv2.LINE_AA)
                    _cv2.line(CC, prev, (px, py), spCC, 1, lineType=_cv2.LINE_AA)
                prev = (px, py)

    # 10) RIDGE BRIGHTS â€” sun-lit crest highlights along terrace gradient (vector)
    gy = np.empty_like(M); gx = np.empty_like(M)
    gy[1:, :] = stepped[1:, :] - stepped[:-1, :]; gy[0, :] = 0
    gx[:, 1:] = stepped[:, 1:] - stepped[:, :-1]; gx[:, 0] = 0
    ridge_mask = ((np.abs(gy) > 0.001) | (np.abs(gx) > 0.001)) & (stepped > 0.55)
    ridge_jitter = (rng.random(shape).astype(np.float32) > 0.55) & ridge_mask
    M[ridge_jitter] = np.minimum(1.0, M[ridge_jitter] + 0.18)
    CC[ridge_jitter] = np.maximum(0.0, CC[ridge_jitter] - 0.10)

    out = np.stack([np.clip(M, 0, 1), np.clip(R_ch, 0, 1), np.clip(CC, 0, 1)], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)


topographic_steps._spb_concept_complete = True


# ============================================================================
# 23. WAVE RIPPLE â€” directional water surface interference
# ============================================================================

def wave_ripple(shape, seed, sm, num_waves=5, base_freq=6.0, choppy=0.3):
    """wave_ripple.

    identity: R6 creative rebuild â€” a koi-pond-style water surface caught
    mid-disturbance. FIVE stacked tiers: (1) glassy water substrate FBM,
    (2) tight 6-14 px interference wave-field (18 layers), (3) HERO
    concentric raindrop ripples at 4-7 random impact points with multiple
    expanding rings (radial bright crest + dark trough alternation),
    (4) dense small crescent crest arcs scattered between, (5) bright
    foam-bubble pinpoints + dark sub-surface dapple specks.

    NEW HERO (tick 78): FIBONACCI PHYLLOTAXIS FOAM TRAIL. A golden-angle
    (137.5 deg) spiral of bright foam dots emerging from a single
    central drift point â€” biology meets fluid dynamics. The same
    spiral that gives sunflower seed heads their pattern, here laid as
    surface foam tracking a slow vortex eddy. 80-160 dots in a single
    curving sweep across the pond. Per-dot INDEPENDENT M/R/CC.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 22197)
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)
    px_scale = mn / 256.0

    # 1) GLASSY WATER SUBSTRATE â€” cool toned FBM
    fM = _normalize(multi_scale_noise(shape, [1.5, 4.0, 11.0, 24.0], [0.35, 0.30, 0.22, 0.13], int(seed) + 5101))
    fR = _normalize(multi_scale_noise(shape, [1.5, 4.0, 11.0, 24.0], [0.36, 0.28, 0.21, 0.15], int(seed) + 5102))
    fCC = _normalize(multi_scale_noise(shape, [1.5, 4.0, 11.0, 24.0], [0.34, 0.31, 0.23, 0.12], int(seed) + 5103))
    M = (0.45 + (fM - 0.5) * 0.28).astype(np.float32)
    R_ch = (0.42 + (fR - 0.5) * 0.30).astype(np.float32)
    CC = (0.55 + (fCC - 0.5) * 0.28).astype(np.float32)

    # 2) INTERFERENCE WAVE-FIELD (6-14 px period, 18 layers)
    yy_n = np.arange(h, dtype=np.float32) / max(mn, 1)
    xx_n = np.arange(w, dtype=np.float32) / max(mn, 1)
    wave_field = np.zeros(shape, dtype=np.float32)
    n_waves = 18
    choppy = 0.3
    for _ in range(n_waves):
        angle = rng.uniform(0, np.pi)
        target_period_px = rng.uniform(6.0, 14.0) * scale
        cycles = mn / max(target_period_px, 1.0)
        phase = rng.uniform(0, 2 * np.pi)
        amp = rng.uniform(0.08, 0.22)
        proj = yy_n[:, None] * np.cos(angle) + xx_n[None, :] * np.sin(angle)
        wave = np.sin(proj * cycles * 2 * np.pi + phase)
        wave = np.sign(wave) * np.abs(wave) ** max(0.3, 1 - choppy * 0.5)
        wave_field += wave * amp
    wave_field = wave_field / max(1.0, n_waves * 0.18)
    R_ch = R_ch + wave_field * 0.22
    CC = CC - wave_field * 0.18
    M = M + wave_field * 0.14

    # 3) HERO RAINDROP CONCENTRIC RIPPLES â€” 4-7 impact points with multi-ring expansion
    yy_grid = np.arange(h, dtype=np.float32)[:, None]
    xx_grid = np.arange(w, dtype=np.float32)[None, :]
    n_impacts = int(rng.integers(4, 8))
    for _ in range(n_impacts):
        cx_i = float(rng.uniform(0.10, 0.90) * w)
        cy_i = float(rng.uniform(0.10, 0.90) * h)
        d = np.sqrt((xx_grid - cx_i) ** 2 + (yy_grid - cy_i) ** 2).astype(np.float32)
        # multiple expanding rings: alternating crest/trough at 7-13 px spacing
        # tick 78 iter: clamp px_scale + scale floors so ripples are
        # actually visible at small canvases (512/256 thumbnail).
        ring_period = float(rng.uniform(7.0, 13.0) * max(scale, 0.6))
        max_r = float(rng.uniform(40, 90) * max(scale, 0.7) * max(px_scale, 1.0))
        falloff = np.exp(-d / max_r).astype(np.float32)
        ring_phase = np.sin(d * (2.0 * np.pi / max(ring_period, 2.0))) * falloff
        # Sharp ring crest (positive-only) for bright fringes
        crest = np.clip(ring_phase, 0.0, 1.0) ** 1.4
        trough = np.clip(-ring_phase, 0.0, 1.0) ** 1.4
        # Per-impact independent channel biases
        mb = float(rng.uniform(0.55, 0.95))
        cb = float(rng.uniform(0.65, 0.97))
        rb = float(rng.uniform(0.06, 0.30))
        # tick 78 iter: hero crest amplitude boosted ~50% so ripples
        # read clearly on the canvas instead of getting washed by dapple.
        M = M + crest * (mb - 0.45) * 0.85
        CC = CC + crest * (cb - 0.50) * 0.85
        R_ch = R_ch - crest * 0.28
        # trough: darker, rougher
        M = M - trough * 0.32
        CC = CC - trough * 0.28
        R_ch = R_ch + trough * 0.30

    if _CV2_OK:
        # 4) FINE crescent crest arcs (radius 2-5 px) â€” scattered everywhere
        n_crests = int(np.clip(1800 * (mn / 2048.0) ** 2, 700, 4600))
        for _ in range(n_crests):
            cx = int(rng.uniform(0.01, 0.99) * w); cy = int(rng.uniform(0.01, 0.99) * h)
            r = max(1, int(rng.uniform(2.0, 5.0) * scale))
            a0 = float(rng.uniform(0, 360)); a1 = a0 + float(rng.uniform(45, 140))
            _cv2.ellipse(M,    (cx, cy), (r, r), 0, a0, a1, float(rng.uniform(0.30, 0.96)), 1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(R_ch, (cx, cy), (r, r), 0, a0, a1, float(rng.uniform(0.06, 0.55)), 1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(CC,   (cx, cy), (r, r), 0, a0, a1, float(rng.uniform(0.40, 0.96)), 1, lineType=_cv2.LINE_AA)

        # 5a) FOAM-BUBBLE PINPOINTS â€” bright, glossy 1-3 px
        n_bub = int(np.clip(1400 * (mn / 2048.0) ** 2, 540, 3600))
        for _ in range(n_bub):
            cx = int(rng.uniform(0.01, 0.99) * w); cy = int(rng.uniform(0.01, 0.99) * h)
            r = max(1, int(rng.uniform(1.0, 2.5) * scale))
            _cv2.circle(M, (cx, cy), r, float(rng.uniform(0.60, 0.98)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R_ch, (cx, cy), r, float(rng.uniform(0.04, 0.22)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r, float(rng.uniform(0.70, 0.99)), -1, lineType=_cv2.LINE_AA)

    # 5b) SUB-SURFACE DAPPLE â€” darker specks (tick 78: density CUT to
    # let HERO ripples + Fibonacci foam read clearly, not noise wash).
    n_dapp = int(np.clip(900 * (mn / 2048.0) ** 2, 300, 2200))
    fxx = rng.integers(0, w, n_dapp); fyy = rng.integers(0, h, n_dapp)
    M[fyy, fxx] = np.minimum(M[fyy, fxx], rng.uniform(0.10, 0.40, n_dapp).astype(np.float32))
    R_ch[fyy, fxx] = np.maximum(R_ch[fyy, fxx], rng.uniform(0.45, 0.85, n_dapp).astype(np.float32))
    CC[fyy, fxx] = np.minimum(CC[fyy, fxx], rng.uniform(0.10, 0.42, n_dapp).astype(np.float32))

    # 6) NEW HERO (tick 78) â€” FIBONACCI PHYLLOTAXIS FOAM TRAIL.
    # Single golden-angle spiral of bright foam dots emerging from a
    # central eddy point. 80-160 dots, dot radius grows with sqrt(n),
    # spiral arm sweeps across the pond.
    if _CV2_OK:
        n_phyllo = int(rng.integers(110, 181))
        cx_ph = float(rng.uniform(0.30, 0.70) * w)
        cy_ph = float(rng.uniform(0.30, 0.70) * h)
        golden = float(np.pi * (3.0 - np.sqrt(5.0)))  # ~2.39996 rad = 137.508 deg
        # tick 78 iter: spiral_c large enough that 130-dot trail fills
        # a clear arm across the canvas; uses sqrt() expansion already
        # so far end is naturally bigger.
        spiral_c = max(float(min(w, h) / 22.0), 2.0)
        # base palette: cool foam (low M, low R, high CC) with tiny jitter
        base_ph_M  = float(rng.uniform(0.74, 0.88))
        base_ph_R  = float(rng.uniform(0.08, 0.14))
        base_ph_CC = float(rng.uniform(0.78, 0.92))
        for k_ph in range(n_phyllo):
            t_ph = float(k_ph) * golden
            r_ph = spiral_c * np.sqrt(float(k_ph + 1))
            dx_ph = np.cos(t_ph) * r_ph
            dy_ph = np.sin(t_ph) * r_ph
            px_ph = int(cx_ph + dx_ph); py_ph = int(cy_ph + dy_ph)
            if not (0 <= px_ph < w and 0 <= py_ph < h):
                continue
            dot_r = max(1, int((1.6 + 0.06 * float(k_ph) ** 0.5) * max(scale, 0.6)))
            jM  = float(np.clip(base_ph_M  + rng.uniform(-0.05, 0.05), 0, 1))
            jR  = float(np.clip(base_ph_R  + rng.uniform(-0.04, 0.04), 0, 1))
            jCC = float(np.clip(base_ph_CC + rng.uniform(-0.05, 0.05), 0, 1))
            _cv2.circle(M,    (px_ph, py_ph), dot_r, jM,  -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R_ch, (px_ph, py_ph), dot_r, jR,  -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC,   (px_ph, py_ph), dot_r, jCC, -1, lineType=_cv2.LINE_AA)

    out = np.stack([M, R_ch, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
wave_ripple._spb_concept_complete = True
# ============================================================================
# 24. PATINA BLOOM â€” circular bloom spots from chemical reaction
# ============================================================================

def patina_bloom(shape, seed, sm, num_blooms=20, min_radius=0.02,
                 max_radius=0.12, **kwargs):
    """patina_bloom.

    identity: R6-creative rebuild - DUAL-PHASE OXIDATION FIELD. A working
    bronze panel mid-corrosion shows TWO distinct bloom phases co-existing:
    (1) cool teal-verdigris feathered patches (FBM-mask), AND (2) warm
    rust-bronze halo blooms with concentric ring banding (the literal
    moisture-edge stain). Six stacked tiers: aged-copper substrate with
    chroma noise, teal patches via FBM threshold mask, rust-halo rings
    stamped 20-40 px with feathered concentric bands, salt-crystal pin
    glints, dark sulphide mineral spots, dense per-patch fleck variance.
    Per-feature INDEPENDENT continuous M/R/CC.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 41819)
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)

    # 1) Aged copper base
    gM = _normalize(multi_scale_noise(shape, [3.0, 8.0, 18.0], [0.45, 0.32, 0.23], int(seed) + 51))
    gR = _normalize(multi_scale_noise(shape, [3.5, 9.0, 20.0], [0.45, 0.32, 0.23], int(seed) + 53))
    gCC = _normalize(multi_scale_noise(shape, [4.0, 10.0, 22.0], [0.45, 0.32, 0.23], int(seed) + 59))
    M = (0.60 + (gM - 0.5) * 0.26).astype(np.float32)
    R = (0.40 + (gR - 0.5) * 0.24).astype(np.float32)
    CC = (0.42 + (gCC - 0.5) * 0.26).astype(np.float32)

    # 2) TEAL VERDIGRIS PATCHES - FBM-thresholded organic blotches
    patch_field = _normalize(multi_scale_noise(shape, [9.0, 22.0, 55.0], [0.35, 0.35, 0.30], int(seed) + 7101))
    thresh = float(rng.uniform(0.54, 0.60))
    patch_mask = np.clip((patch_field - thresh) / max(1.0 - thresh, 1e-3), 0.0, 1.0).astype(np.float32)
    patch_mask = _gauss(patch_mask, sigma=max(1.5, 2.5 * scale))
    patch_mask = _normalize(patch_mask) ** 0.85
    # Independent verdigris chroma variation across the field
    verd_M = 0.18 + _normalize(multi_scale_noise(shape, [4.0, 11.0], [0.5, 0.5], int(seed) + 7201)) * 0.18
    verd_R = 0.68 + _normalize(multi_scale_noise(shape, [4.5, 12.0], [0.5, 0.5], int(seed) + 7203)) * 0.22
    verd_CC = 0.78 + _normalize(multi_scale_noise(shape, [5.0, 13.0], [0.5, 0.5], int(seed) + 7205)) * 0.18
    M = (M * (1.0 - patch_mask) + verd_M * patch_mask).astype(np.float32)
    R = (R * (1.0 - patch_mask) + verd_R * patch_mask).astype(np.float32)
    CC = (CC * (1.0 - patch_mask) + verd_CC * patch_mask).astype(np.float32)

    # 3) RUST-HALO RING BLOOMS - the WATER-STAIN signature
    # Build with vectorized distance fields rather than stamping
    n_halos = int(np.clip(38 * (mn / 256.0) ** 2, 22, 220))
    yy = np.arange(h, dtype=np.float32)[:, None]
    xx = np.arange(w, dtype=np.float32)[None, :]
    halo_mask = np.zeros(shape, dtype=np.float32)
    halo_rust = np.zeros(shape, dtype=np.float32)
    for _ in range(n_halos):
        cx = float(rng.uniform(0.02, 0.98) * w)
        cy = float(rng.uniform(0.02, 0.98) * h)
        r_outer = float(rng.uniform(14.0, 30.0) * scale)
        # Distance from center
        d = np.sqrt((xx - cx) ** 2 + (yy - cy) ** 2)
        # Concentric ring banding
        band_period = float(rng.uniform(2.5, 4.5))
        bands = (np.cos(d / band_period * 2.0 * np.pi) * 0.5 + 0.5).astype(np.float32)
        # Outer-edge weighted: stain is strongest at the moisture edge
        envelope = np.exp(-((d - r_outer * 0.6) ** 2) / (2.0 * (r_outer * 0.4) ** 2)).astype(np.float32)
        halo_mask = np.maximum(halo_mask, envelope * (0.5 + bands * 0.5))
        halo_rust = np.maximum(halo_rust, envelope * float(rng.uniform(0.6, 1.0)))

    # Rust chroma: high M, mid-low R, low CC
    rust_M = 0.78 + (gM - 0.5) * 0.14
    rust_R = 0.30 + (gR - 0.5) * 0.18
    rust_CC = 0.22 + (gCC - 0.5) * 0.16
    M = (M * (1.0 - halo_mask) + rust_M * halo_mask).astype(np.float32)
    R = (R * (1.0 - halo_mask) + rust_R * halo_mask).astype(np.float32)
    CC = (CC * (1.0 - halo_mask) + rust_CC * halo_mask).astype(np.float32)

    # 4) DENSE per-patch fleck variance (vectorized) - SHADES inside patches
    n_micro = int(np.clip(3400 * (mn / 2048.0) ** 2, 1200, 8500))
    mx = rng.integers(0, w, n_micro); my = rng.integers(0, h, n_micro)
    mask_at = patch_mask[my, mx]
    keep = mask_at > 0.22
    mx = mx[keep]; my = my[keep]
    n_keep = mx.size
    if n_keep > 0:
        M[my, mx] = np.clip(M[my, mx] + rng.uniform(-0.22, 0.16, n_keep).astype(np.float32), 0, 1)
        R[my, mx] = np.clip(R[my, mx] + rng.uniform(-0.14, 0.22, n_keep).astype(np.float32), 0, 1)
        CC[my, mx] = np.clip(CC[my, mx] + rng.uniform(-0.14, 0.20, n_keep).astype(np.float32), 0, 1)

    # 5) SALT CRYSTAL PIN GLINTS - ultra-bright pinpoints in copper zones
    n_salt = int(np.clip(2200 * (mn / 2048.0) ** 2, 800, 5400))
    sy = rng.integers(0, h, n_salt); sx = rng.integers(0, w, n_salt)
    bg_zone = (patch_mask[sy, sx] < 0.25) & (halo_mask[sy, sx] < 0.30)
    sx = sx[bg_zone]; sy = sy[bg_zone]
    if sx.size > 0:
        M[sy, sx] = np.maximum(M[sy, sx], rng.uniform(0.80, 0.98, sx.size).astype(np.float32))
        R[sy, sx] = np.minimum(R[sy, sx], rng.uniform(0.08, 0.24, sx.size).astype(np.float32))
        CC[sy, sx] = np.maximum(CC[sy, sx], rng.uniform(0.55, 0.92, sx.size).astype(np.float32))

    if _CV2_OK:
        # 6) Sulphide mineral spots - dark inclusions inside patches
        n_min = int(np.clip(620 * (mn / 2048.0) ** 2, 220, 2200))
        for _ in range(n_min):
            cxi = int(rng.uniform(0.02, 0.98) * w); cyi = int(rng.uniform(0.02, 0.98) * h)
            if patch_mask[cyi, cxi] < 0.3 and halo_mask[cyi, cxi] < 0.25:
                continue
            rr = max(1, int(rng.uniform(1.5, 3.5) * scale))
            _cv2.circle(M, (cxi, cyi), rr, float(rng.uniform(0.06, 0.24)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cxi, cyi), rr, float(rng.uniform(0.68, 0.94)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cxi, cyi), rr, float(rng.uniform(0.60, 0.94)), -1, lineType=_cv2.LINE_AA)

        # 7) RUST-EDGE RUNOFF - short curved streaks at halo edges
        n_run = int(np.clip(420 * (mn / 2048.0) ** 2, 160, 1600))
        for _ in range(n_run):
            cx = float(rng.uniform(4, w - 4)); cy = float(rng.uniform(4, h - 4))
            if halo_mask[int(cy), int(cx)] < 0.25:
                continue
            length = float(rng.uniform(4.0, 9.0) * scale)
            ang = float(rng.uniform(0, 2 * np.pi))
            x1 = int(cx + np.cos(ang) * length)
            y1 = int(cy + np.sin(ang) * length)
            _cv2.line(M, (int(cx), int(cy)), (x1, y1), float(rng.uniform(0.55, 0.88)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(R, (int(cx), int(cy)), (x1, y1), float(rng.uniform(0.18, 0.42)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (int(cx), int(cy)), (x1, y1), float(rng.uniform(0.18, 0.45)), 1, lineType=_cv2.LINE_AA)

    out = np.stack([M, R, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
patina_bloom._spb_concept_complete = True


# ============================================================================
# 25. ELECTRIC BRANCHES â€” branching tree / Lichtenberg figures
# ============================================================================

def electric_branches(shape, seed, sm, num_trees=8, branch_depth=8,
                      thickness=0.008, **kwargs):
    """electric_branches â€” R6 CREATIVE rebuild â€” woven Lichtenberg storm.

    identity: A panel scarred by hundreds of overlapping Lichtenberg
    discharges, each captured at the moment of strike. Six tiers stack:
    (1) dark plasma-stained substrate with independent per-channel FBM,
    (2) CASCADING TREES grown branch-by-branch (4-18 px segments, depth 5,
    1-3 child branches each), (3) HALO GLOW corona blurred around the
    brightest junctions (heat-shadow ring), (4) HOT-CORE pinpoint nodes
    (1-2 px white-hot disks), (5) FORK SPARK BURSTS â€” micro-rosettes of
    3-6 radial 2-5 px tendrils at random branch tips simulating secondary
    arc-flash, (6) ion sparkle dust + soot pockets. Per-segment
    INDEPENDENT continuous M/R/CC. Differentiator vs fractal_discharge:
    cascade growth + halo glow + fork bursts give a STORM feel, not a
    fractal feel.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 25017)
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)

    # 1) BASE â€” plasma-stained substrate, INDEPENDENT per-channel FBM
    bM = _normalize(multi_scale_noise(shape, [2.0, 6.0, 16.0], [0.5, 0.3, 0.2], int(seed) + 25021))
    bR = _normalize(multi_scale_noise(shape, [2.4, 6.8, 17.5], [0.5, 0.3, 0.2], int(seed) + 25023))
    bC = _normalize(multi_scale_noise(shape, [2.8, 7.5, 19.0], [0.5, 0.3, 0.2], int(seed) + 25025))
    M = (0.20 + (bM - 0.5) * 0.22).astype(np.float32)
    R = (0.60 + (bR - 0.5) * 0.24).astype(np.float32)
    CC = (0.55 + (bC - 0.5) * 0.24).astype(np.float32)

    # Halo glow accumulator â€” collected before blur
    halo_seeds = np.zeros(shape, dtype=np.float32)
    fork_tips: list = []

    # 2) CASCADING LICHTENBERG TREES
    if _CV2_OK:
        n_trees = int(np.clip(240 * (mn / 2048.0) ** 2, 90, 640))
        for _ in range(n_trees):
            root_x = float(rng.uniform(0, w)); root_y = float(rng.uniform(0, h))
            root_ang = float(rng.uniform(0, 2 * np.pi))
            frontier = [(root_x, root_y, root_ang, 0)]
            max_depth = 5
            seg_count = 0
            while frontier:
                cx, cy, ang, depth = frontier.pop()
                if depth >= max_depth: continue
                length = float(rng.uniform(4.0, 18.0) * scale)
                x2 = cx + np.cos(ang) * length; y2 = cy + np.sin(ang) * length
                if 0 <= x2 < w and 0 <= y2 < h:
                    _cv2.line(M, (int(cx), int(cy)), (int(x2), int(y2)),
                              float(rng.uniform(0.70, 0.99)), 1, lineType=_cv2.LINE_AA)
                    _cv2.line(R, (int(cx), int(cy)), (int(x2), int(y2)),
                              float(rng.uniform(0.04, 0.22)), 1, lineType=_cv2.LINE_AA)
                    _cv2.line(CC, (int(cx), int(cy)), (int(x2), int(y2)),
                              float(rng.uniform(0.04, 0.25)), 1, lineType=_cv2.LINE_AA)
                    # Halo seed at endpoint
                    if 0 <= int(y2) < h and 0 <= int(x2) < w:
                        halo_seeds[int(y2), int(x2)] = max(halo_seeds[int(y2), int(x2)], float(rng.uniform(0.5, 1.0)))
                    # Occasionally record a fork-spark tip
                    if rng.random() < 0.06 and seg_count > 1:
                        fork_tips.append((x2, y2))
                    seg_count += 1
                    n_child = int(rng.integers(1, 4))
                    for _c in range(n_child):
                        child_ang = ang + float(rng.normal(0, 0.55))
                        frontier.append((x2, y2, child_ang, depth + 1))

        # 3) HALO GLOW â€” soft warm corona around junction endpoints
        if halo_seeds.max() > 0:
            halo = _gauss(halo_seeds, sigma=max(1.8, 2.4 * scale))
            halo = _normalize(halo)
            M = np.clip(M + halo * 0.18, 0, 1)
            CC = np.clip(CC + halo * 0.12, 0, 1)
            R = np.clip(R - halo * 0.10, 0, 1)

        # 4) HOT-CORE JUNCTION NODES â€” bright pinpoint disks
        n_cores = max(3500, int(h * w / 22))
        cx_arr = rng.integers(0, w, n_cores); cy_arr = rng.integers(0, h, n_cores)
        M[cy_arr, cx_arr] = np.maximum(M[cy_arr, cx_arr], rng.uniform(0.80, 0.99, n_cores).astype(np.float32))
        R[cy_arr, cx_arr] = np.minimum(R[cy_arr, cx_arr], rng.uniform(0.04, 0.18, n_cores).astype(np.float32))
        CC[cy_arr, cx_arr] = np.minimum(CC[cy_arr, cx_arr], rng.uniform(0.04, 0.20, n_cores).astype(np.float32))

        # 5) FORK SPARK BURSTS â€” micro radial rosettes at selected tips
        max_forks = min(len(fork_tips), int(np.clip(450 * (mn / 2048.0) ** 2, 120, 1200)))
        if max_forks > 0:
            chosen = rng.choice(len(fork_tips), size=max_forks, replace=False)
            for idx in chosen:
                fx_, fy_ = fork_tips[int(idx)]
                n_arm = int(rng.integers(3, 7))
                for a_i in range(n_arm):
                    ang = float(rng.uniform(0, 2 * np.pi))
                    L = float(rng.uniform(2.0, 5.0) * scale)
                    x_e = int(np.clip(fx_ + np.cos(ang) * L, 0, w - 1))
                    y_e = int(np.clip(fy_ + np.sin(ang) * L, 0, h - 1))
                    _cv2.line(M, (int(fx_), int(fy_)), (x_e, y_e),
                              float(rng.uniform(0.78, 0.99)), 1, lineType=_cv2.LINE_AA)
                    _cv2.line(R, (int(fx_), int(fy_)), (x_e, y_e),
                              float(rng.uniform(0.04, 0.16)), 1, lineType=_cv2.LINE_AA)
                    _cv2.line(CC, (int(fx_), int(fy_)), (x_e, y_e),
                              float(rng.uniform(0.04, 0.20)), 1, lineType=_cv2.LINE_AA)

        # 6) ION-SPARKLE DUST
        n_ions = max(6000, int(h * w / 12))
        fy = rng.integers(0, h, n_ions); fx = rng.integers(0, w, n_ions)
        M[fy, fx] = np.maximum(M[fy, fx], rng.uniform(0.55, 0.92, n_ions).astype(np.float32))
        R[fy, fx] = np.minimum(R[fy, fx], rng.uniform(0.10, 0.35, n_ions).astype(np.float32))

        # 7) SOOT POCKETS â€” small dark patches 3-6 px
        n_soot = int(np.clip(750 * (mn / 2048.0) ** 2, 240, 1800))
        for _ in range(n_soot):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            rr = max(2, int(rng.uniform(2.0, 4.0) * scale))
            _cv2.circle(M, (cx, cy), rr, float(rng.uniform(0.05, 0.18)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), rr, float(rng.uniform(0.70, 0.95)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), rr, float(rng.uniform(0.55, 0.85)), -1, lineType=_cv2.LINE_AA)

    out = np.stack([M, R, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)

electric_branches._spb_concept_complete = True


# ============================================================================
# 26. MULTI_BAND_SPEC â€” convenience combo (outputs 0-255)
# ============================================================================

def multi_band_spec(shape, seed, sm, base_val, variation, num_bands=30,
                    palette_size=10, flake_density=0.01, depth_weight=0.3):
    """
    Convenience: combines banded_rows + flake_scatter + depth_gradient
    into a ready-to-use spec channel value array in 0-255 range.
    """
    bands = banded_rows(shape, seed, sm, num_bands=num_bands,
                        palette_size=palette_size)
    flakes = flake_scatter(shape, seed + 7777, sm, density=flake_density)
    depth = depth_gradient(shape, seed + 8888, sm)

    combined = bands * 0.5 + flakes * 0.3 + depth * depth_weight
    combined = _normalize(combined)
    result = base_val + (combined - 0.5) * 2.0 * variation * sm

    # Normalize to [0,1] to match all other pattern functions
    result_01 = np.clip(result / 255.0, 0.0, 1.0)
    return _sm_scale(result_01, sm).astype(np.float32)


# ============================================================================
# 26. VORONOI_FRACTURE â€” shattered glass cell boundaries
# ============================================================================

def voronoi_fracture(shape, seed, sm, num_cells=40, edge_width=2.0, **kwargs):
    """voronoi_fracture.

    identity: a SHATTERED tempered-glass pane caught mid-fracture â€” the
    differentiator vs other shatter/fracture patterns is the IMPACT
    SPIDER: 3-5 radial primary cracks lance across the field from a hidden
    impact origin, branching into secondary forks before fading. Beneath
    that spider sits a TIGHT Voronoi cell lattice (cells 14-22 px, 5x
    denser than before) joined by sharp dark seams; every cell has its
    own INDEPENDENT continuous M/R/CC plus a per-cell tilt phase so each
    fragment catches light differently. Six tiers: (1) jitter-grid Voronoi
    cells with per-cell triples, (2) sharp dark fracture seams, (3) radial
    spider cracks bursting from a hidden origin, (4) triple-junction
    glints (2-4 px), (5) micro-crack hairlines INSIDE cells (4-10 px),
    (6) tiny shard chips (1-2 px) scattered everywhere. Fine 1-22 px only.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 51729)
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)

    # 1) TIGHTER JITTERED-GRID CELLS â€” 14-22 px
    cell_px = float(np.clip(18.0 * scale, 9.0, 22.0))
    ny = max(8, int(h / cell_px) + 1); nx = max(8, int(w / cell_px) + 1)
    cell_jx = rng.uniform(-cell_px * 0.38, cell_px * 0.38, (ny + 2, nx + 2)).astype(np.float32)
    cell_jy = rng.uniform(-cell_px * 0.38, cell_px * 0.38, (ny + 2, nx + 2)).astype(np.float32)
    # Per-cell INDEPENDENT continuous M/R/CC â€” NOT a shared palette
    cell_M = rng.uniform(0.18, 0.95, (ny + 2, nx + 2)).astype(np.float32)
    cell_R = rng.uniform(0.12, 0.88, (ny + 2, nx + 2)).astype(np.float32)
    cell_C = rng.uniform(0.10, 0.88, (ny + 2, nx + 2)).astype(np.float32)
    yy_px, xx_px = np.mgrid[0:h, 0:w].astype(np.float32)
    gy = yy_px / cell_px; gx = xx_px / cell_px
    iy = np.clip(gy.astype(np.int32), 0, ny); ix = np.clip(gx.astype(np.int32), 0, nx)
    best_d = np.full(shape, np.inf, dtype=np.float32)
    sec_d = np.full(shape, np.inf, dtype=np.float32)
    best_iy = np.zeros(shape, dtype=np.int32); best_ix = np.zeros(shape, dtype=np.int32)
    for dy_o in (-1, 0, 1):
        for dx_o in (-1, 0, 1):
            cy_i = np.clip(iy + dy_o, 0, ny + 1)
            cx_i = np.clip(ix + dx_o, 0, nx + 1)
            cx_p = (cx_i.astype(np.float32) + 0.5) * cell_px + cell_jx[cy_i, cx_i]
            cy_p = (cy_i.astype(np.float32) + 0.5) * cell_px + cell_jy[cy_i, cx_i]
            d = (xx_px - cx_p) ** 2 + (yy_px - cy_p) ** 2
            update = d < best_d
            sec_d = np.where(update, best_d, np.minimum(sec_d, d))
            best_iy = np.where(update, cy_i, best_iy)
            best_ix = np.where(update, cx_i, best_ix)
            best_d = np.where(update, d, best_d)

    M = cell_M[best_iy, best_ix].astype(np.float32)
    R_ch = cell_R[best_iy, best_ix].astype(np.float32)
    CC = cell_C[best_iy, best_ix].astype(np.float32)

    # 2) SHARP DARK FRACTURE SEAMS
    edge_dist = np.sqrt(sec_d) - np.sqrt(np.maximum(best_d, 0))
    edge_mask = (edge_dist < max(1.2, float(edge_width))).astype(np.float32)
    M = M - edge_mask * 0.48
    R_ch = R_ch + edge_mask * 0.34
    CC = CC + edge_mask * 0.28

    if _CV2_OK:
        # 3) IMPACT SPIDER â€” radial primary cracks from a hidden origin (THIS NAME'S DIFFERENTIATOR)
        ox = float(rng.uniform(0.2, 0.8) * w); oy = float(rng.uniform(0.2, 0.8) * h)
        n_primary = int(rng.integers(3, 6))
        for k in range(n_primary):
            base_ang = float(k * (2 * np.pi / n_primary) + rng.uniform(-0.3, 0.3))
            cx, cy = ox, oy
            # Walk the crack outward in 8-14 px segments with slight wobble
            for seg in range(int(rng.integers(10, 18))):
                ang = base_ang + float(rng.uniform(-0.12, 0.12))
                length = float(rng.uniform(10.0, 18.0) * scale)
                nx2 = float(np.clip(cx + np.cos(ang) * length, 0, w - 1))
                ny2 = float(np.clip(cy + np.sin(ang) * length, 0, h - 1))
                _cv2.line(M,    (int(cx), int(cy)), (int(nx2), int(ny2)), float(rng.uniform(0.08, 0.28)), 1, lineType=_cv2.LINE_AA)
                _cv2.line(R_ch, (int(cx), int(cy)), (int(nx2), int(ny2)), float(rng.uniform(0.70, 0.96)), 1, lineType=_cv2.LINE_AA)
                _cv2.line(CC,   (int(cx), int(cy)), (int(nx2), int(ny2)), float(rng.uniform(0.55, 0.90)), 1, lineType=_cv2.LINE_AA)
                # Secondary fork
                if rng.random() < 0.35:
                    f_ang = ang + float(rng.uniform(-0.9, 0.9))
                    f_len = float(rng.uniform(6.0, 14.0) * scale)
                    fx2 = float(np.clip(cx + np.cos(f_ang) * f_len, 0, w - 1))
                    fy2 = float(np.clip(cy + np.sin(f_ang) * f_len, 0, h - 1))
                    _cv2.line(M,    (int(cx), int(cy)), (int(fx2), int(fy2)), float(rng.uniform(0.12, 0.32)), 1, lineType=_cv2.LINE_AA)
                    _cv2.line(R_ch, (int(cx), int(cy)), (int(fx2), int(fy2)), float(rng.uniform(0.65, 0.92)), 1, lineType=_cv2.LINE_AA)
                cx, cy = nx2, ny2

        # 4) TRIPLE-JUNCTION GLINTS
        n_glint = int(np.clip(1400 * (mn / 2048.0) ** 2, 480, 4800))
        for _ in range(n_glint):
            cx2 = int(rng.integers(0, w)); cy2 = int(rng.integers(0, h))
            r = max(1, int(rng.uniform(1.2, 2.8) * scale))
            _cv2.circle(M,    (cx2, cy2), r, float(rng.uniform(0.68, 0.99)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R_ch, (cx2, cy2), r, float(rng.uniform(0.08, 0.30)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC,   (cx2, cy2), r, float(rng.uniform(0.06, 0.28)), -1, lineType=_cv2.LINE_AA)

        # 5) MICRO-CRACK HAIRLINES INSIDE CELLS (4-10 px)
        n_micro = int(np.clip(2200 * (mn / 2048.0) ** 2, 750, 7500))
        for _ in range(n_micro):
            cx2 = float(rng.uniform(0.02, 0.98) * w); cy2 = float(rng.uniform(0.02, 0.98) * h)
            length = float(rng.uniform(4.0, 10.0) * scale)
            ang = float(rng.uniform(0, 2 * np.pi))
            x2 = int(np.clip(cx2 + np.cos(ang) * length, 0, w - 1))
            y2 = int(np.clip(cy2 + np.sin(ang) * length, 0, h - 1))
            _cv2.line(M,    (int(cx2), int(cy2)), (x2, y2), float(rng.uniform(0.18, 0.48)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(R_ch, (int(cx2), int(cy2)), (x2, y2), float(rng.uniform(0.55, 0.90)), 1, lineType=_cv2.LINE_AA)

    # 6) SHARD CHIP FLECKS â€” 1-2 px points everywhere
    n_ch = int(np.clip(4500 * (mn / 2048.0) ** 2, 1500, 15000))
    cy = rng.integers(0, h, n_ch); cx = rng.integers(0, w, n_ch)
    M[cy, cx]    = np.maximum(M[cy, cx],    rng.uniform(0.55, 0.95, n_ch).astype(np.float32))
    R_ch[cy, cx] = np.minimum(R_ch[cy, cx], rng.uniform(0.04, 0.22, n_ch).astype(np.float32))
    CC[cy, cx]   = np.minimum(CC[cy, cx],   rng.uniform(0.04, 0.22, n_ch).astype(np.float32))

    out = np.stack([np.clip(M, 0, 1), np.clip(R_ch, 0, 1), np.clip(CC, 0, 1)], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)


voronoi_fracture._spb_concept_complete = True


# ============================================================================
# 27. PLASMA_TURBULENCE â€” hot plasma energy field
# ============================================================================

def plasma_turbulence(shape, seed, sm, **kwargs):
    """Plasma turbulence -- R6 creative rebuild with HERO plasma serpents.

    identity: A raging plasma cell viewed up close - hero motif is CHAINED
    SERPENT FILAMENTS that snake across the canvas in 12-24 short connected
    segments (each 5-9 px) tracing curved sinuous paths like real plasma
    streamers. Six stacked tiers: (1) low-amp swirling turbulent FBM
    substrate where M/R/CC are decorrelated via independent seeds plus a
    warm/cool heat-domain mask so the surface reads as having charge
    pockets; (2) HERO 6-16 chained serpent filaments, each a 12-24 segment
    polyline curling via sin/cos perturbation with bright charge-cloud
    beads riding the path; (3) dense 6-18 px secondary chaos filament
    arcs; (4) crackle-spark beads 1-3 px (4x density); (5) dark cooled
    void pits 1-3 px; (6) single-pixel sparkle floor. Every feature uses
    INDEPENDENT continuous M/R/CC uniforms with WIDE chroma ranges. No
    palette quantization, no panel-scale features, full canvas coverage.
    """
    shape = tuple(shape) if hasattr(shape, '__iter__') else shape
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 71823)
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)

    # --- Tier 1: low-amp swirling turbulent substrate -------------------
    g_M  = _normalize(multi_scale_noise((h, w), [1.6, 4.2, 9.5], [0.52, 0.30, 0.18], int(seed) + 61))
    g_R  = _normalize(multi_scale_noise((h, w), [2.4, 6.0, 13.0], [0.48, 0.32, 0.20], int(seed) + 137))
    g_CC = _normalize(multi_scale_noise((h, w), [3.0, 7.5, 17.0], [0.46, 0.34, 0.20], int(seed) + 211))
    domain = _normalize(multi_scale_noise((h, w), [1.2, 3.0], [0.6, 0.4], int(seed) + 313))
    warm = (domain > 0.5).astype(np.float32)
    M  = (0.40 + (g_M  - 0.5) * 0.26 + warm * 0.05).astype(np.float32)
    R  = (0.50 - warm * 0.10 + (g_R  - 0.5) * 0.26).astype(np.float32)
    CC = (0.40 + (g_CC - 0.5) * 0.26 + warm * 0.03).astype(np.float32)

    if _CV2_OK:
        # --- Tier 2: HERO chained serpent filaments --------------------
        n_serp = int(rng.integers(6, 16))
        for _ in range(n_serp):
            cx = float(rng.uniform(8, w - 8)); cy = float(rng.uniform(8, h - 8))
            base_ang = float(rng.uniform(0, 2 * np.pi))
            curl_freq = float(rng.uniform(0.15, 0.45))
            curl_amp = float(rng.uniform(0.6, 1.4))
            seg_len = float(rng.uniform(5.0, 9.0) * scale)
            n_seg = int(rng.integers(12, 25))
            heroM = float(rng.uniform(0.78, 0.99))
            heroR = float(rng.uniform(0.03, 0.18))
            heroCC = float(rng.uniform(0.04, 0.30))
            px, py = cx, cy
            for s in range(n_seg):
                ang = base_ang + np.sin(s * curl_freq) * curl_amp + float(rng.normal(0.0, 0.18))
                nx = px + np.cos(ang) * seg_len
                ny = py + np.sin(ang) * seg_len
                _cv2.line(M,  (int(px), int(py)), (int(nx), int(ny)),
                          float(np.clip(heroM + rng.uniform(-0.06, 0.06), 0, 1)), 1, lineType=_cv2.LINE_AA)
                _cv2.line(R,  (int(px), int(py)), (int(nx), int(ny)),
                          float(np.clip(heroR + rng.uniform(-0.04, 0.04), 0, 1)), 1, lineType=_cv2.LINE_AA)
                _cv2.line(CC, (int(px), int(py)), (int(nx), int(ny)),
                          float(np.clip(heroCC + rng.uniform(-0.06, 0.06), 0, 1)), 1, lineType=_cv2.LINE_AA)
                if rng.random() < 0.55:
                    rr = max(1, int(rng.uniform(1.5, 3.0)))
                    _cv2.circle(M,  (int(nx), int(ny)), rr, float(rng.uniform(0.72, 0.99)), -1, lineType=_cv2.LINE_AA)
                    _cv2.circle(R,  (int(nx), int(ny)), rr, float(rng.uniform(0.04, 0.20)), -1, lineType=_cv2.LINE_AA)
                    _cv2.circle(CC, (int(nx), int(ny)), rr, float(rng.uniform(0.04, 0.32)), -1, lineType=_cv2.LINE_AA)
                px, py = nx, ny
                if px < 2 or px > w - 2 or py < 2 or py > h - 2:
                    base_ang += np.pi
                    px = float(np.clip(px, 4, w - 4))
                    py = float(np.clip(py, 4, h - 4))

        # --- Tier 3: secondary chaos filament arcs ---------------------
        n_arc = int(np.clip(2400 * (mn / 2048.0) ** 2, 1200, 7200))
        for _ in range(n_arc):
            cx = float(rng.uniform(2, w - 2)); cy = float(rng.uniform(2, h - 2))
            length = float(rng.uniform(6.0, 18.0) * scale)
            ang = float(rng.uniform(0, 2 * np.pi))
            x0s = int(cx - np.cos(ang) * length * 0.5); y0s = int(cy - np.sin(ang) * length * 0.5)
            x1s = int(cx + np.cos(ang) * length * 0.5); y1s = int(cy + np.sin(ang) * length * 0.5)
            _cv2.line(M,  (x0s, y0s), (x1s, y1s), float(rng.uniform(0.50, 0.95)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(R,  (x0s, y0s), (x1s, y1s), float(rng.uniform(0.06, 0.36)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.06, 0.42)), 1, lineType=_cv2.LINE_AA)

        # --- Tier 4: crackle-spark beads -------------------------------
        n_sp = int(np.clip(4200 * (mn / 2048.0) ** 2, 1800, 11500))
        for _ in range(n_sp):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            r = max(1, int(rng.uniform(1.0, 2.5) * scale))
            _cv2.circle(M,  (cx, cy), r, float(rng.uniform(0.62, 0.99)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R,  (cx, cy), r, float(rng.uniform(0.03, 0.28)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r, float(rng.uniform(0.05, 0.36)), -1, lineType=_cv2.LINE_AA)

        # --- Tier 5: dark cooled void pits -----------------------------
        n_void = int(np.clip(2200 * (mn / 2048.0) ** 2, 900, 6400))
        for _ in range(n_void):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            r = max(1, int(rng.uniform(1.0, 2.2) * scale))
            _cv2.circle(M,  (cx, cy), r, float(rng.uniform(0.04, 0.26)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R,  (cx, cy), r, float(rng.uniform(0.58, 0.96)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r, float(rng.uniform(0.55, 0.95)), -1, lineType=_cv2.LINE_AA)

    # --- Tier 6: single-pixel plasma sparkle floor ---------------------
    n_fl = int(np.clip(5400 * (mn / 2048.0) ** 2, 2000, 13500))
    fx = rng.integers(0, w, n_fl); fy = rng.integers(0, h, n_fl)
    M[fy, fx]  = np.maximum(M[fy, fx],  rng.uniform(0.55, 0.99, n_fl).astype(np.float32))
    R[fy, fx]  = np.minimum(R[fy, fx],  rng.uniform(0.04, 0.30, n_fl).astype(np.float32))
    CC[fy, fx] = np.minimum(CC[fy, fx], rng.uniform(0.05, 0.40, n_fl).astype(np.float32))

    # --- Tier 7: R6-CREATIVE NEW ï¿½ RETINAL VASCULATURE CAPILLARIES -----
    # Biological branching: 4-8 root vessels each recursively split into
    # finer 6-14 px capillary children (depth 3). Charge currents read as
    # the optic-fundus vasculature network superimposed on the plasma.
    # Per-tree INDEPENDENT continuous M/R/CC. Iterative stack to keep <200ms.
    if _CV2_OK:
        n_tree = int(rng.integers(4, 9))
        for _ in range(n_tree):
            cx = float(rng.uniform(0.05, 0.95) * w)
            cy = float(rng.uniform(0.05, 0.95) * h)
            base_ang = float(rng.uniform(0, 2 * np.pi))
            treeM  = float(rng.uniform(0.55, 0.95))
            treeR  = float(rng.uniform(0.05, 0.30))
            treeCC = float(rng.uniform(0.06, 0.42))
            # stack entries: (x, y, ang, length, depth_left)
            stack = [(cx, cy, base_ang, float(rng.uniform(10.0, 16.0) * scale), 3)]
            n_drawn = 0
            while stack and n_drawn < 64:
                x0, y0, ang, seglen, d = stack.pop()
                if seglen < 1.2: continue
                x1 = x0 + np.cos(ang) * seglen
                y1 = y0 + np.sin(ang) * seglen
                ix0, iy0 = int(np.clip(x0, 0, w-1)), int(np.clip(y0, 0, h-1))
                ix1, iy1 = int(np.clip(x1, 0, w-1)), int(np.clip(y1, 0, h-1))
                _cv2.line(M,  (ix0, iy0), (ix1, iy1),
                          float(np.clip(treeM  + rng.uniform(-0.05, 0.05), 0, 1)), 1, lineType=_cv2.LINE_AA)
                _cv2.line(R,  (ix0, iy0), (ix1, iy1),
                          float(np.clip(treeR  + rng.uniform(-0.04, 0.04), 0, 1)), 1, lineType=_cv2.LINE_AA)
                _cv2.line(CC, (ix0, iy0), (ix1, iy1),
                          float(np.clip(treeCC + rng.uniform(-0.05, 0.05), 0, 1)), 1, lineType=_cv2.LINE_AA)
                n_drawn += 1
                if d > 0:
                    branch_da = float(rng.uniform(0.45, 0.85))
                    nseg = seglen * float(rng.uniform(0.58, 0.82))
                    # two children
                    stack.append((x1, y1, ang + branch_da + float(rng.normal(0, 0.12)), nseg, d - 1))
                    stack.append((x1, y1, ang - branch_da + float(rng.normal(0, 0.12)), nseg, d - 1))

    out = np.stack([M, R, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
plasma_turbulence._spb_concept_complete = True


# ============================================================================
# 28. DIAMOND_LATTICE â€” geometric diamond/rhombus grid with depth
# ============================================================================

def diamond_lattice(shape, seed, sm, cell_size=24, depth_variation=0.4, **kwargs):
    """diamond_lattice â€” R6 OWNER REBUILD 2026-05-26.

    Owner: "I'm asking for a rebuild to make it cleaner/sharper - less noisy.
    The DESIGN is fine. Just need to make it better."
    Owner LIKES the diamond design â€” keep the lattice grid. Removed all
    grain/noise/FBM layers and per-cell-tarnish micro-features. Each cell
    now has a UNIFORM fill from a TIGHT 32-entry palette + crisp polyline
    diamond outlines (cv2.polylines width 1 px, no blur). HERO: every 7th
    cell is a brighter statement gem with a sharp edge highlight.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + (hash("diamond_lattice_r6_cleansharp") % 10000))
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)

    # COHESIVE polished-steel palette â€” TIGHT, no Lisa-Frank
    BASE_M, BASE_R, BASE_C = 0.62, 0.22, 0.55  # polished mirror-steel
    M = np.full((h, w), 0.08, dtype=np.float32)   # dark mortar substrate (composite-dark)
    R_ch = np.full((h, w), 0.10, dtype=np.float32)
    CC = np.full((h, w), 0.06, dtype=np.float32)

    if _CV2_OK:
        # Build diamond polygons on a tilted grid. Use cell pitch ~14-20 px.
        pitch = max(12, int(16 * max(scale, 1.0)))
        pitch = min(pitch, 22)
        half = pitch // 2
        # Walk grid in rotated (u,v) basis (45deg)
        n_rows = (h // half) + 4
        n_cols = (w // half) + 4
        gem_idx = 0
        for ri in range(-2, n_rows):
            for ci in range(-2, n_cols):
                # Center of each diamond cell â€” staggered checker
                if (ri + ci) % 2 != 0:
                    continue
                cx = ci * half
                cy = ri * half
                if not (-half < cx < w + half and -half < cy < h + half):
                    continue
                # Diamond vertices: top, right, bottom, left
                v_top    = (cx, cy - half)
                v_right  = (cx + half, cy)
                v_bottom = (cx, cy + half)
                v_left   = (cx - half, cy)
                pts = np.array([v_top, v_right, v_bottom, v_left], dtype=np.int32)
                # TIGHT palette â€” pick from 32 cohesive shades around BASE
                shade = (gem_idx * 73856093 ^ ci * 19349663 ^ ri * 83492791) & 31
                tint = (shade / 31.0 - 0.5) * 0.10  # Â±0.05 jitter
                pM = float(np.clip(BASE_M + tint, 0, 1))
                pR = float(np.clip(BASE_R - tint * 0.6, 0, 1))
                pC = float(np.clip(BASE_C + tint * 0.8, 0, 1))
                # HERO: every 7th cell = STATEMENT GEM
                is_gem = (gem_idx % 7 == 0)
                if is_gem:
                    pM = float(np.clip(BASE_M + 0.22, 0, 1))
                    pR = float(np.clip(BASE_R - 0.08, 0, 1))
                    pC = float(np.clip(BASE_C + 0.22, 0, 1))
                # CLEAN UNIFORM FILL â€” NO blur, NO noise
                _cv2.fillPoly(M, [pts], pM)
                _cv2.fillPoly(R_ch, [pts], pR)
                _cv2.fillPoly(CC, [pts], pC)
                # SHARP outline â€” crisp 1 px polyline (no LINE_AA blur on edges
                # for cleanliness)
                _cv2.polylines(M, [pts], True, min(0.95, pM + 0.18), 1)
                _cv2.polylines(R_ch, [pts], True, max(0.04, pR - 0.10), 1)
                _cv2.polylines(CC, [pts], True, min(0.95, pC + 0.18), 1)
                # Hero gems get an extra sharp top-edge highlight
                if is_gem:
                    _cv2.line(M, v_left, v_top, 0.97, 1)
                    _cv2.line(M, v_top, v_right, 0.97, 1)
                    _cv2.line(CC, v_left, v_top, 0.92, 1)
                    _cv2.line(CC, v_top, v_right, 0.92, 1)
                gem_idx += 1

    out = np.stack([M, R_ch, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
diamond_lattice._spb_concept_complete = True


def acid_etch(shape, seed, sm, intensity=0.6, blob_count=30, **kwargs):
    """acid_etch.

    identity: R6-CREATIVE + R6-LOOP creativity-mandate layer â€” A
    CHEMISTRY-LAB acid-bite map. Hero motif is now a HYBRID:
    (A) the SPLATTERED ACID DROPLET starbursts that ATE through the
    coating (4-7 radial fingers, 10-22 px reach, bare-metal core), and
    (B) NEW HERO â€” LICHEN COLONY THALLI: 14-22 px crustose lichen
    patches (BIOLOGY motif dropped into a chemistry pattern) drawn as
    irregular concentric rings with scalloped lobate edges + apothecia
    cup pinpoints â€” symbolizing slow biological reclamation of the
    eaten metal. Stacked underneath: a Voronoi-style fracture web that
    LINKS splash sites (chemistry pathway), hex/cubic crystallised
    residue scabs (4-7 px polygons in straw/turquoise oxide tones), a
    dense fine pit carpet, hairline craze fissures, micro-bubble
    pockets (CC dips to near-zero), bare-metal pixel flecks. Per-
    feature INDEPENDENT continuous M/R/CC uniforms with WIDE ranges
    (0.08-0.95 on each channel). Full canvas coverage, fine features.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + (hash("acid_etch_r6c") % 10000))
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)

    # 1) OXIDISED SUBSTRATE â€” quiet 3-channel FBM wash, per-channel
    fM  = _normalize(multi_scale_noise(shape, [2.0, 5.5, 14.0], [0.45, 0.35, 0.20], int(seed) + 6081))
    fR  = _normalize(multi_scale_noise(shape, [2.5, 6.0, 15.0], [0.42, 0.36, 0.22], int(seed) + 6083))
    fCC = _normalize(multi_scale_noise(shape, [2.0, 5.0, 13.0], [0.44, 0.34, 0.22], int(seed) + 6085))
    M  = (0.34 + (fM  - 0.5) * 0.22).astype(np.float32)
    R  = (0.66 + (fR  - 0.5) * 0.26).astype(np.float32)
    CC = (0.50 + (fCC - 0.5) * 0.30).astype(np.float32)

    # 2) ACID-SPLATTER ANCHOR SITES â€” distribute pseudo-Poisson via jittered grid
    grid_pitch = max(28, int(36 * scale))
    splash_sites = []
    for gy in range(0, h, grid_pitch):
        for gx in range(0, w, grid_pitch):
            if rng.random() < 0.78:
                jx = float(rng.uniform(-grid_pitch * 0.45, grid_pitch * 0.45))
                jy = float(rng.uniform(-grid_pitch * 0.45, grid_pitch * 0.45))
                splash_sites.append((int(np.clip(gx + jx, 1, w - 2)),
                                     int(np.clip(gy + jy, 1, h - 2))))

    if _CV2_OK:
        # 3) ACID-SPLATTER STARS â€” the hero motif
        for (cx, cy) in splash_sites:
            n_fingers = int(rng.integers(4, 8))
            ang0 = float(rng.uniform(0, 2 * np.pi))
            # bright bare-metal core
            core_r = max(1, int(rng.uniform(2.0, 3.5) * scale))
            _cv2.circle(M, (cx, cy), core_r, float(rng.uniform(0.72, 0.99)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), core_r, float(rng.uniform(0.04, 0.22)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), core_r, float(rng.uniform(0.04, 0.30)), -1, lineType=_cv2.LINE_AA)
            for fi in range(n_fingers):
                a = ang0 + fi * (2 * np.pi / n_fingers) + float(rng.uniform(-0.4, 0.4))
                L = float(rng.uniform(8.0, 18.0)) * scale
                # taper: draw a few decreasing-radius circles along the finger
                steps = max(4, int(L / 2.5))
                for s in range(steps):
                    t = s / max(1, steps - 1)
                    fx = int(np.clip(cx + np.cos(a) * t * L, 0, w - 1))
                    fy = int(np.clip(cy + np.sin(a) * t * L, 0, h - 1))
                    rr = max(1, int((1.0 - t) * rng.uniform(1.4, 2.6) * scale))
                    _cv2.circle(M, (fx, fy), rr, float(rng.uniform(0.55, 0.92)), -1, lineType=_cv2.LINE_AA)
                    _cv2.circle(R, (fx, fy), rr, float(rng.uniform(0.10, 0.42)), -1, lineType=_cv2.LINE_AA)
                    _cv2.circle(CC, (fx, fy), rr, float(rng.uniform(0.05, 0.40)), -1, lineType=_cv2.LINE_AA)

        # 4) LINKING FRACTURE WEB â€” connect random adjacent splash sites
        n_links = min(len(splash_sites) * 2, int(np.clip(800 * (mn / 256.0), 200, 2500)))
        if len(splash_sites) > 1:
            for _ in range(n_links):
                i = int(rng.integers(0, len(splash_sites)))
                # pick a neighbour within ~2*pitch
                a_pt = splash_sites[i]
                j = int(rng.integers(0, len(splash_sites)))
                b_pt = splash_sites[j]
                dx = b_pt[0] - a_pt[0]; dy = b_pt[1] - a_pt[1]
                if dx * dx + dy * dy > (3 * grid_pitch) ** 2:
                    continue
                _cv2.line(M, a_pt, b_pt, float(rng.uniform(0.08, 0.24)), 1, lineType=_cv2.LINE_AA)
                _cv2.line(R, a_pt, b_pt, float(rng.uniform(0.66, 0.95)), 1, lineType=_cv2.LINE_AA)
                _cv2.line(CC, a_pt, b_pt, float(rng.uniform(0.55, 0.92)), 1, lineType=_cv2.LINE_AA)

        # 5) CRYSTALLISED RESIDUE SCABS â€” small polygons (4-7 px)
        n_cryst = int(np.clip(900 * (mn / 256.0), 280, 3000))
        for _ in range(n_cryst):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            n_sides = int(rng.integers(5, 8))
            rr = float(rng.uniform(2.5, 4.0)) * scale
            a0 = float(rng.uniform(0, 2 * np.pi))
            poly = []
            for k in range(n_sides):
                a = a0 + k * (2 * np.pi / n_sides)
                px = int(np.clip(cx + np.cos(a) * rr, 0, w - 1))
                py = int(np.clip(cy + np.sin(a) * rr, 0, h - 1))
                poly.append([px, py])
            pts = np.array([poly], dtype=np.int32)
            _cv2.fillPoly(M, pts, float(rng.uniform(0.18, 0.55)), lineType=_cv2.LINE_AA)
            _cv2.fillPoly(R, pts, float(rng.uniform(0.55, 0.92)), lineType=_cv2.LINE_AA)
            # WIDE CC for rainbow-oxide chemistry chroma
            _cv2.fillPoly(CC, pts, float(rng.uniform(0.10, 0.95)), lineType=_cv2.LINE_AA)

        # 6) DENSE FINE PIT CARPET (3-5 px) â€” under everything
        n_pits = int(np.clip(3500 * (mn / 2048.0) ** 2, 1400, 12000))
        for _ in range(n_pits):
            cx = int(rng.uniform(0.01, 0.99) * w)
            cy = int(rng.uniform(0.01, 0.99) * h)
            r = max(1, int(rng.uniform(1.5, 3.0) * scale))
            _cv2.circle(M,  (cx, cy), r, float(rng.uniform(0.55, 0.95)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R,  (cx, cy), r, float(rng.uniform(0.06, 0.32)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r, float(rng.uniform(0.04, 0.30)), -1, lineType=_cv2.LINE_AA)

        # 7) HAIRLINE CRAZE FISSURES (6-14 px, very thin)
        n_fis = int(np.clip(1800 * (mn / 2048.0) ** 2, 600, 6500))
        for _ in range(n_fis):
            cx = float(rng.uniform(0.02, 0.98) * w)
            cy = float(rng.uniform(0.02, 0.98) * h)
            ang = float(rng.uniform(0, 2 * np.pi))
            length = float(rng.uniform(6.0, 14.0) * scale)
            x1p = int(np.clip(cx + np.cos(ang) * length, 0, w - 1))
            y1p = int(np.clip(cy + np.sin(ang) * length, 0, h - 1))
            _cv2.line(M,  (int(cx), int(cy)), (x1p, y1p), float(rng.uniform(0.08, 0.22)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(R,  (int(cx), int(cy)), (x1p, y1p), float(rng.uniform(0.70, 0.95)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (int(cx), int(cy)), (x1p, y1p), float(rng.uniform(0.60, 0.90)), 1, lineType=_cv2.LINE_AA)

    # 8) BARE-METAL PIXEL FLECKS
    n_fl = int(np.clip(4500 * (mn / 2048.0) ** 2, 1600, 16000))
    fx = rng.integers(0, w, n_fl); fy = rng.integers(0, h, n_fl)
    M[fy, fx] = np.maximum(M[fy, fx], rng.uniform(0.72, 0.98, n_fl).astype(np.float32))
    R[fy, fx] = np.minimum(R[fy, fx], rng.uniform(0.06, 0.22, n_fl).astype(np.float32))
    CC[fy, fx] = np.minimum(CC[fy, fx], rng.uniform(0.04, 0.18, n_fl).astype(np.float32))

    # 9) MICRO-BUBBLE pockets â€” wide CC dips (chemistry froth)
    n_bub = int(np.clip(3000 * (mn / 2048.0) ** 2, 1000, 10000))
    bx = rng.integers(0, w, n_bub); by = rng.integers(0, h, n_bub)
    CC[by, bx] = np.clip(CC[by, bx] + rng.uniform(-0.45, 0.45, n_bub).astype(np.float32), 0, 1)
    R[by, bx] = np.clip(R[by, bx] + rng.uniform(-0.30, 0.30, n_bub).astype(np.float32), 0, 1)

    # 10) NEW HERO â€” LICHEN COLONY THALLI (R6-Loop creativity mandate:
    # BIOLOGY dropped into a CHEMISTRY pattern). Crustose lichen patches
    # 14-22 px with scalloped lobate edges + 2-4 concentric ring rims +
    # apothecia cup pinpoints. Each patch picks INDEPENDENT M/R/CC across
    # 0.08-0.95 â€” chartreuse / pumpkin / chalky-blue / rust colonies.
    if _CV2_OK:
        n_lich = int(np.clip(140 * (mn / 2048.0) ** 2, 36, 360))
        for _ in range(n_lich):
            cx = float(rng.uniform(0.04, 0.96) * w)
            cy = float(rng.uniform(0.04, 0.96) * h)
            r_outer = float(rng.uniform(14.0, 22.0) * scale)
            n_lobes = int(rng.integers(9, 18))  # scalloped lobate edge
            # Per-colony INDEPENDENT M/R/CC across owner's wide chroma range
            colM = float(rng.uniform(0.10, 0.92))
            colR = float(rng.uniform(0.18, 0.92))
            colCC = float(rng.uniform(0.10, 0.93))
            # Build scalloped polygon (each lobe radius perturbed)
            poly = []
            a0 = float(rng.uniform(0, 2 * np.pi))
            for k in range(n_lobes):
                ang = a0 + k * (2 * np.pi / n_lobes)
                rk = r_outer * float(rng.uniform(0.70, 1.08))
                px = int(np.clip(cx + np.cos(ang) * rk, 0, w - 1))
                py = int(np.clip(cy + np.sin(ang) * rk, 0, h - 1))
                poly.append([px, py])
            pts = np.array([poly], dtype=np.int32)
            _cv2.fillPoly(M, pts, colM, lineType=_cv2.LINE_AA)
            _cv2.fillPoly(R, pts, colR, lineType=_cv2.LINE_AA)
            _cv2.fillPoly(CC, pts, colCC, lineType=_cv2.LINE_AA)
            # 2-4 concentric ring rims inside the thallus (lichen growth zones)
            n_rings = int(rng.integers(2, 5))
            for ri in range(n_rings):
                rr = int(max(2, r_outer * (0.30 + ri * 0.20)))
                rim_M = float(rng.uniform(0.08, 0.95))
                rim_R = float(rng.uniform(0.08, 0.95))
                rim_CC = float(rng.uniform(0.08, 0.95))
                _cv2.circle(M, (int(cx), int(cy)), rr, rim_M, 1, lineType=_cv2.LINE_AA)
                _cv2.circle(R, (int(cx), int(cy)), rr, rim_R, 1, lineType=_cv2.LINE_AA)
                _cv2.circle(CC, (int(cx), int(cy)), rr, rim_CC, 1, lineType=_cv2.LINE_AA)
            # 4-8 apothecia cup pinpoints scattered inside
            n_apo = int(rng.integers(4, 9))
            for _ai in range(n_apo):
                aa = float(rng.uniform(0, 2 * np.pi))
                ad = float(rng.uniform(0.0, 0.78)) * r_outer
                ax = int(np.clip(cx + np.cos(aa) * ad, 0, w - 1))
                ay = int(np.clip(cy + np.sin(aa) * ad, 0, h - 1))
                ar = max(1, int(rng.uniform(1.4, 2.6) * scale))
                _cv2.circle(M, (ax, ay), ar, float(rng.uniform(0.55, 0.96)), -1, lineType=_cv2.LINE_AA)
                _cv2.circle(R, (ax, ay), ar, float(rng.uniform(0.08, 0.40)), -1, lineType=_cv2.LINE_AA)
                _cv2.circle(CC, (ax, ay), ar, float(rng.uniform(0.10, 0.95)), -1, lineType=_cv2.LINE_AA)

    out = np.stack([np.clip(M, 0, 1), np.clip(R, 0, 1), np.clip(CC, 0, 1)], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)


acid_etch._spb_concept_complete = True


# ============================================================================
# 30. GALAXY_SWIRL â€” spiral galaxy arms with star clusters
# ============================================================================

def galaxy_swirl(shape, seed, sm, num_arms=4, twist=3.0, **kwargs):
    """galaxy_swirl.

    identity: ROTATING SNAKES (Kitaoka anomalous-motion illusion).
    8-14 concentric rings sliced into 24-48 angular wedges. Per-wedge luminance
    follows an ASYMMETRIC 4-step pattern (low â†’ mid-low â†’ high â†’ mid-high)
    repeated around each ring â€” that asymmetry is the thing that drives the
    motion perception. M carries the illusion. R = mid uniform. CC = wide
    independent uniform per ring (angle-dependent rainbow on a 3D body).
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 911001)

    yy, xx = np.indices((h, w), dtype=np.float32)
    cy, cx = h * 0.5, w * 0.5
    dy = yy - cy
    dx = xx - cx
    r = np.hypot(dy, dx)
    theta = np.arctan2(dy, dx)  # -pi..pi

    n_rings = int(rng.integers(9, 15))
    n_wedges = int(rng.integers(28, 49))
    r_max = float(np.hypot(cy, cx))

    ring_idx = np.clip((r / r_max * n_rings).astype(np.int32), 0, n_rings - 1)
    wedge_f = (theta + np.pi) / (2.0 * np.pi) * n_wedges
    wedge_idx = (wedge_f.astype(np.int32)) % n_wedges

    # ASYMMETRIC 4-step palette per ring (Kitaoka order: dark â†’ mid-dark â†’ bright â†’ mid-bright)
    base_asym = np.array([0.10, 0.32, 0.92, 0.62], dtype=np.float32)

    M = np.zeros((h, w), dtype=np.float32)
    R_ch = np.full((h, w), 0.34, dtype=np.float32)
    CC = np.zeros((h, w), dtype=np.float32)

    for ri in range(n_rings):
        # Per-ring random phase + tint multiplier
        phase = int(rng.integers(0, 4))
        amp = float(rng.uniform(0.85, 1.10))
        palette = np.clip(base_asym * amp, 0.04, 0.97)
        # Rotate palette per-ring (so adjacent rings don't all align)
        rot_pal = np.roll(palette, phase)
        ring_mask = (ring_idx == ri)
        if not ring_mask.any():
            continue
        # Per-wedge step (0..3) is wedge_idx % 4
        step = wedge_idx[ring_mask] % 4
        M[ring_mask] = rot_pal[step]
        # R per-ring continuous uniform mid-band
        R_ch[ring_mask] = float(rng.uniform(0.22, 0.46))
        # CC per-ring INDEPENDENT continuous uniform â†’ rainbow on car
        CC[ring_mask] = float(rng.uniform(0.06, 0.95))

    # Thin black radial separators every wedge boundary (sharpens illusion)
    sep = (np.abs(wedge_f - np.round(wedge_f)) < 0.06).astype(np.float32)
    M = M * (1.0 - sep * 0.55)

    # Per-pixel jitter so each wedge has its own continuous variation
    jitter = rng.uniform(-0.05, 0.05, (h, w)).astype(np.float32)
    M = np.clip(M + jitter, 0.0, 1.0)

    out = np.stack([M, R_ch, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
galaxy_swirl._spb_concept_complete = True


def _LEGACY_galaxy_swirl_dead(shape, seed, sm, num_arms=4, twist=3.0, **kwargs):
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    if min(h, w) > 384:
        scale = 384.0 / float(min(h, w))
        small_shape = (max(64, int(round(h * scale))), max(64, int(round(w * scale))))
        small = None  # dead â€” was recursive
        up = _cv2.resize(small.astype(np.float32), (w, h), interpolation=_cv2.INTER_LINEAR).astype(np.float32)
        yy = np.linspace(-1.0, 1.0, h, dtype=np.float32)[:, np.newaxis]
        xx = np.linspace(-1.0, 1.0, w, dtype=np.float32)[np.newaxis, :]
        radius = np.sqrt(xx * xx + yy * yy)
        theta = np.arctan2(yy, xx)
        grain = _spb_fast_hash_grid(shape, seed + 319)
        arm_carrier = _spb_fast_line_distance((theta + radius * 14.0) * 53.0, 29.0, 0.58, seed + 320)
        dust_lanes = _spb_fast_line_distance((xx * w * 0.37 - yy * h * 0.19) + up * 80.0, 41.0, 0.62, seed + 321)
        stars = ((grain > 0.970).astype(np.float32) * 0.08 +
                 (grain > 0.986).astype(np.float32) * (0.18 + np.clip(1.25 - radius, 0, 1) * 0.22) +
                 (grain > 0.997).astype(np.float32) * 0.34)
        stellar_grain = (grain - 0.5) * np.clip(up * 1.4 + 0.18, 0, 1) * 0.24
        full = up * 0.50 + arm_carrier * np.clip(up * 1.7, 0, 1) * 0.24 + dust_lanes * np.clip(up, 0, 1) * 0.20 + stars + stellar_grain
        # SPB-106 r2 (2026-05-20 tick 27): cosmic background dust at full
        # resolution (upsampling blurred the small-scale grain). 0.18 amp
        # FULL-RES grain restores paintFineEnergy capability.
        full_grain_rng = np.random.RandomState(seed + 351)
        full_grain = (full_grain_rng.rand(h, w).astype(np.float32) - 0.5) * 0.18
        full = (full + full_grain).astype(np.float32)
        # post-blackout-29 EARLY BRU + DENSE FINE: galaxy_swirl was FSC=27.4, BRU=50, RT=397.
        # Recursive downscale loses fine detail. Add early BRU + scattered star primitives
        # at FULL resolution so doctrine fineness is restored after upsample.
        rng_gs = np.random.default_rng(seed + 360)
        mlo_gs = rng_gs.random(full.shape).astype(np.float32) < 0.055
        mhi_gs = rng_gs.random(full.shape).astype(np.float32) < 0.055
        full = np.where(mlo_gs, 0.10, full).astype(np.float32)
        full = np.where(mhi_gs, 0.92, full).astype(np.float32)
        if _CV2_OK:
            palette_gs = np.array([0.18,0.28,0.38,0.48,0.58,0.68,0.78,0.92], dtype=np.float32)
            scale_gs = max(min(h, w) / 2048.0, 0.25)
            # Bright stars (2-5 px) palette top
            n_star = int(np.clip(1200 * (min(h, w) / 2048.0) ** 2, 440, 3000))
            for _ in range(n_star):
                cx_g = int(rng_gs.integers(0, w)); cy_g = int(rng_gs.integers(0, h))
                r_g = max(1, int(rng_gs.uniform(2.0, 5.0) * scale_gs * 0.5))
                v_g = float(palette_gs[rng_gs.integers(5, 8)])
                _cv2.circle(full, (cx_g, cy_g), r_g, v_g, -1, lineType=_cv2.LINE_AA)
            # Dust filament hairlines (10-22 px)
            n_dust = int(np.clip(500 * (min(h, w) / 2048.0) ** 2, 180, 1500))
            for _ in range(n_dust):
                cx_g = rng_gs.uniform(4, w - 4); cy_g = rng_gs.uniform(4, h - 4)
                length_g = float(rng_gs.uniform(10.0, 22.0) * scale_gs * 0.5)
                ang_g = float(rng_gs.uniform(0, 2 * np.pi))
                x0g = int(cx_g - np.cos(ang_g) * length_g * 0.5)
                y0g = int(cy_g - np.sin(ang_g) * length_g * 0.5)
                x1g = int(cx_g + np.cos(ang_g) * length_g * 0.5)
                y1g = int(cy_g + np.sin(ang_g) * length_g * 0.5)
                v_g = float(palette_gs[rng_gs.integers(2, 7)])
                _cv2.line(full, (x0g, y0g), (x1g, y1g), v_g, 1, lineType=_cv2.LINE_AA)
            # Dark void dots
            n_void = int(np.clip(500 * (min(h, w) / 2048.0) ** 2, 180, 1500))
            for _ in range(n_void):
                cx_g = int(rng_gs.integers(0, w)); cy_g = int(rng_gs.integers(0, h))
                r_g = max(1, int(rng_gs.uniform(1.0, 2.5) * scale_gs))
                v_g = float(palette_gs[rng_gs.integers(0, 3)])
                _cv2.circle(full, (cx_g, cy_g), r_g, v_g, -1, lineType=_cv2.LINE_AA)
        # Flecks
        n_fl_gs = int(np.clip(1200 * (min(h, w) / 2048.0) ** 2, 400, 3000))
        fx_gs = rng_gs.integers(0, w, n_fl_gs); fy_gs = rng_gs.integers(0, h, n_fl_gs)
        full[fy_gs, fx_gs] = np.maximum(full[fy_gs, fx_gs], np.array([0.18,0.28,0.38,0.48,0.58,0.68,0.78,0.92], dtype=np.float32)[rng_gs.integers(0, 8, n_fl_gs)])
        return _validate_spec_output(_sm_scale(_normalize(np.clip(full, 0, 1)), sm).astype(np.float32), "galaxy_swirl")
    rng2 = np.random.default_rng(seed + 301)
    yy = np.linspace(-1.0, 1.0, h, dtype=np.float32)
    xx = np.linspace(-1.0, 1.0, w, dtype=np.float32)
    X, Y = np.meshgrid(xx, yy)
    result = np.zeros(shape, dtype=np.float32)
    for _ in range(max(6, int(num_arms) + 3)):
        cx = rng2.uniform(-0.86, 0.86)
        cy = rng2.uniform(-0.86, 0.86)
        sx = rng2.uniform(0.30, 0.62)
        sy = rng2.uniform(0.22, 0.55)
        angle = rng2.uniform(-np.pi, np.pi)
        ca, sa = np.cos(angle), np.sin(angle)
        dx = X - cx
        dy = Y - cy
        rx = (dx * ca + dy * sa) / sx
        ry = (-dx * sa + dy * ca) / sy
        r = np.sqrt(rx * rx + ry * ry) + 1e-5
        theta = np.arctan2(ry, rx)
        local_twist = rng2.uniform(2.4, 5.7)
        arm_count = int(rng2.integers(3, 7))
        arms = np.zeros(shape, dtype=np.float32)
        for arm in range(arm_count):
            phase = theta - local_twist * np.log(r + 0.09) + arm * 2.0 * np.pi / arm_count
            arms += np.exp(-((np.sin(phase) * r) ** 2) * rng2.uniform(16.0, 34.0))
        result += arms * np.exp(-r * rng2.uniform(2.4, 4.8)) * rng2.uniform(0.18, 0.42)
    dust = _normalize(multi_scale_noise(shape, [0.8, 2.5, 7.0, 19.0], [0.40, 0.31, 0.20, 0.09], seed + 302))
    filaments = _spb_fast_line_distance(
        (X * w * 0.72) + (Y * h * 0.38) + _gauss(dust, 6.0) * 54.0,
        max(18.0, min(h, w) / 22.0),
        0.62,
        seed,
    )
    grain2 = rng2.random((h, w), dtype=np.float32)
    stars = ((grain2 > 0.972).astype(np.float32) * 0.08 +
             (grain2 > 0.989).astype(np.float32) * 0.20 +
             (grain2 > 0.997).astype(np.float32) * 0.42)
    star_glow = np.maximum(stars, _gauss(stars, sigma=max(0.55, min(h, w) / 700.0)) * 0.62)
    stellar_grain = (grain2 - 0.5) * np.clip(result * 1.2 + 0.18, 0, 1) * 0.22
    out = result * 0.48 + filaments * 0.22 + star_glow * 0.34 + dust * 0.12 + stellar_grain
    return _sm_scale(_normalize(out), sm).astype(np.float32)


# ============================================================================
# 31. REPTILE_SCALE â€” overlapping biological scales
# ============================================================================

def reptile_scale(shape, seed=0, sm=1.0, **kwargs):
    """reptile_scale.

    identity: R6 tick-50 second-pass â€” densely overlapping snake-belly
    scale field with NEW HERO stacked on prior build. Existing heroes:
    IRIDESCENT EYE-SPOT OCELLI (10-16 px peacock concentric rings) and
    tight 8-18 px teardrop scales packed in offset rows. NEW HERO
    (tick-50): VENOM-DROPLET DEW BEADS â€” 3-6 px ultra-bright wet
    hemispherical droplets each with a dark refractive cast shadow
    down-right and a 1 px specular hot-spot up-left, reading as wet
    venomous freshly-shed snake belly. Plus: bright crescent rims, dark
    slit shadows, keel ridge highlights, shed-skin sloughed flake arcs,
    molt-peel curl fragments, dust pits, pinpoint flecks. Full-canvas.
    Per-feature INDEPENDENT continuous M/R/CC.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 40213)
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)
    # 1) Skin substrate â€” independent FBM per channel
    g1 = _normalize(_spb_fast_smooth_noise(shape, [2.5, 6.0, 13.0, 21.0], [0.38, 0.30, 0.20, 0.12], int(seed) + 4011))
    g2 = _normalize(_spb_fast_smooth_noise(shape, [3.0, 7.0, 15.0, 24.0], [0.36, 0.30, 0.20, 0.14], int(seed) + 4013))
    g3 = _normalize(_spb_fast_smooth_noise(shape, [3.5, 8.0, 16.0, 25.0], [0.34, 0.30, 0.22, 0.14], int(seed) + 4017))
    M = (0.34 + (g1 - 0.5) * 0.26).astype(np.float32)
    R = (0.56 + (g2 - 0.5) * 0.28).astype(np.float32)
    CC = (0.38 + (g3 - 0.5) * 0.24).astype(np.float32)

    if _CV2_OK:
        # 2) TIGHT SCALE GRID â€” 5x density via finer step + per-scale chroma
        # 2026-05-30 perf pass: the old 10 px pitch drew ~85k overlapping
        # ellipses at 2048. A 14 px pitch still keeps 8-18 px scale bodies
        # densely interlocked, but removes redundant overdraw.
        step = max(8, int(14 * scale))
        for row, y in enumerate(range(step // 2, h, max(3, int(step * 0.68)))):
            offset = (step // 2) if row % 2 == 1 else 0
            for x in range(offset + step // 2, w, max(4, int(step * 0.85))):
                jx = int(rng.integers(-2, 3)); jy = int(rng.integers(-2, 3))
                cx = x + jx; cy = y + jy
                if not (0 <= cx < w and 0 <= cy < h):
                    continue
                rr = int(max(3, rng.uniform(8, 18) * scale * 0.5))
                ry = max(2, int(rr * float(rng.uniform(0.65, 0.85))))
                rot = float(rng.uniform(-25, 25))
                # body fill â€” independent M/R/CC continuous uniforms
                aM = float(rng.uniform(0.22, 0.78))
                aR = float(rng.uniform(0.28, 0.82))
                aCC = float(rng.uniform(0.16, 0.62))
                _cv2.ellipse(M, (cx, cy), (rr, ry), rot, 0, 360, aM, -1, lineType=_cv2.LINE_AA)
                _cv2.ellipse(R, (cx, cy), (rr, ry), rot, 0, 360, aR, -1, lineType=_cv2.LINE_AA)
                _cv2.ellipse(CC, (cx, cy), (rr, ry), rot, 0, 360, aCC, -1, lineType=_cv2.LINE_AA)
                # bright leading rim crescent
                lM = float(rng.uniform(0.66, 0.97)); lR = float(rng.uniform(0.06, 0.28)); lCC = float(rng.uniform(0.05, 0.24))
                _cv2.ellipse(M, (cx, cy), (rr, ry), rot, 200, 340, lM, 1, lineType=_cv2.LINE_AA)
                _cv2.ellipse(R, (cx, cy), (rr, ry), rot, 200, 340, lR, 1, lineType=_cv2.LINE_AA)
                _cv2.ellipse(CC, (cx, cy), (rr, ry), rot, 200, 340, lCC, 1, lineType=_cv2.LINE_AA)
                # central keel ridge dot (1-2 px)
                kr = max(1, int(rr * 0.18))
                _cv2.circle(M, (cx, cy), kr, float(rng.uniform(0.70, 0.96)), -1, lineType=_cv2.LINE_AA)
                _cv2.circle(CC, (cx, cy), kr, float(rng.uniform(0.04, 0.18)), -1, lineType=_cv2.LINE_AA)

        # 3) DARK SLIT CRESCENTS â€” trailing edges (5x density)
        n_slit = int(np.clip(3000 * (mn / 2048.0) ** 2, 1100, 8200))
        for _ in range(n_slit):
            cx = int(rng.integers(2, w - 2)); cy = int(rng.integers(2, h - 2))
            rr = int(max(2, rng.uniform(5, 12) * scale * 0.5))
            sM = float(rng.uniform(0.04, 0.20)); sR = float(rng.uniform(0.68, 0.94)); sCC = float(rng.uniform(0.50, 0.92))
            _cv2.ellipse(M, (cx, cy), (rr, max(1, rr - 1)), 0, 30, 150, sM, 1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(R, (cx, cy), (rr, max(1, rr - 1)), 0, 30, 150, sR, 1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(CC, (cx, cy), (rr, max(1, rr - 1)), 0, 30, 150, sCC, 1, lineType=_cv2.LINE_AA)

        # 4) NEW â€” shed-skin sloughed flake arcs (4-10 px torn keratin)
        n_shed = int(np.clip(1800 * (mn / 2048.0) ** 2, 600, 4800))
        for _ in range(n_shed):
            cx = int(rng.integers(2, w - 2)); cy = int(rng.integers(2, h - 2))
            rr = int(max(2, rng.uniform(4, 10) * scale * 0.5))
            a0 = float(rng.uniform(0, 360)); span = float(rng.uniform(70, 160))
            shM = float(rng.uniform(0.45, 0.88)); shR = float(rng.uniform(0.30, 0.65)); shCC = float(rng.uniform(0.18, 0.55))
            _cv2.ellipse(M, (cx, cy), (rr, max(1, rr - 1)), 0, a0, a0 + span, shM, 1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(R, (cx, cy), (rr, max(1, rr - 1)), 0, a0, a0 + span, shR, 1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(CC, (cx, cy), (rr, max(1, rr - 1)), 0, a0, a0 + span, shCC, 1, lineType=_cv2.LINE_AA)

        # 5) MICRO-KEEL HIGHLIGHTS â€” tiny bright spots (5x)
        n_keel = int(np.clip(4000 * (mn / 2048.0) ** 2, 1400, 10000))
        for _ in range(n_keel):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            rr = max(1, int(rng.uniform(1.0, 2.2) * scale))
            kM = float(rng.uniform(0.58, 0.94)); kR = float(rng.uniform(0.08, 0.30)); kCC = float(rng.uniform(0.04, 0.28))
            _cv2.circle(M, (cx, cy), rr, kM, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), rr, kR, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), rr, kCC, -1, lineType=_cv2.LINE_AA)

        # 5b) HERO â€” IRIDESCENT EYE-SPOT OCELLI (10-16 px concentric rings)
        n_ocelli = int(np.clip(220 * (mn / 2048.0) ** 2, 70, 700))
        for _ in range(n_ocelli):
            cx = int(rng.integers(6, w - 6)); cy = int(rng.integers(6, h - 6))
            r_o = max(4, int(rng.uniform(5.0, 8.0) * scale))
            # 3 concentric chroma rings, INDEPENDENT M/R/CC per ring
            for ring_idx in range(3):
                rr_ring = max(1, int(r_o * (1.0 - ring_idx * 0.32)))
                eM = float(rng.uniform(0.30, 0.95))
                eR = float(rng.uniform(0.12, 0.78))
                eCC = float(rng.uniform(0.08, 0.78))
                _cv2.circle(M, (cx, cy), rr_ring, eM, 1, lineType=_cv2.LINE_AA)
                _cv2.circle(R, (cx, cy), rr_ring, eR, 1, lineType=_cv2.LINE_AA)
                _cv2.circle(CC, (cx, cy), rr_ring, eCC, 1, lineType=_cv2.LINE_AA)
            # bright pupil core
            _cv2.circle(M, (cx, cy), max(1, r_o // 4), float(rng.uniform(0.78, 0.98)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), max(1, r_o // 4), float(rng.uniform(0.02, 0.18)), -1, lineType=_cv2.LINE_AA)

        # 5c) MOLT-PEEL CURL FRAGMENTS (6-12 px peeling arc + shadow)
        n_molt = int(np.clip(900 * (mn / 2048.0) ** 2, 300, 2400))
        for _ in range(n_molt):
            cx = int(rng.integers(3, w - 3)); cy = int(rng.integers(3, h - 3))
            rr_m = max(2, int(rng.uniform(3.0, 6.0) * scale))
            a0 = float(rng.uniform(0, 360)); span = float(rng.uniform(60, 140))
            # bright curl lit edge
            _cv2.ellipse(M, (cx, cy), (rr_m, rr_m), 0, a0, a0 + span, float(rng.uniform(0.62, 0.95)), 1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(R, (cx, cy), (rr_m, rr_m), 0, a0, a0 + span, float(rng.uniform(0.18, 0.50)), 1, lineType=_cv2.LINE_AA)
            # dark cast shadow underneath (offset 1 px)
            _cv2.ellipse(CC, (cx + 1, cy + 1), (rr_m, rr_m), 0, a0, a0 + span, float(rng.uniform(0.55, 0.90)), 1, lineType=_cv2.LINE_AA)

        # 5d) R6-TICK50 NEW HERO â€” VENOM-DROPLET DEW BEADS.
        # 3-6 px ultra-bright hemispherical wet droplets each with a
        # dark refractive shadow offset down-right. Captures wet
        # venomous/freshly-shed snake belly. Per-bead INDEPENDENT M/R/CC.
        n_dew = int(np.clip(680 * (mn / 2048.0) ** 2, 220, 1800))
        for _ in range(n_dew):
            cx_d = int(rng.integers(3, w - 4)); cy_d = int(rng.integers(3, h - 4))
            rd = max(2, int(rng.uniform(2.0, 3.5) * scale))
            # dark refractive cast shadow (lower-right offset, lifts R, dim M)
            shx = cx_d + max(1, rd // 2); shy = cy_d + max(1, rd // 2)
            _cv2.circle(M, (shx, shy), rd, float(rng.uniform(0.06, 0.22)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (shx, shy), rd, float(rng.uniform(0.55, 0.85)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (shx, shy), rd, float(rng.uniform(0.62, 0.92)), -1, lineType=_cv2.LINE_AA)
            # main bead body â€” wet hemispherical (low R, low CC, mid M)
            _cv2.circle(M, (cx_d, cy_d), rd, float(rng.uniform(0.34, 0.62)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx_d, cy_d), rd, float(rng.uniform(0.05, 0.18)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx_d, cy_d), rd, float(rng.uniform(0.04, 0.20)), -1, lineType=_cv2.LINE_AA)
            # specular hot-spot highlight (upper-left, 1 px)
            hx = cx_d - max(1, rd // 2); hy = cy_d - max(1, rd // 2)
            if 0 <= hx < w and 0 <= hy < h:
                M[hy, hx] = float(rng.uniform(0.90, 0.99))
                R[hy, hx] = float(rng.uniform(0.02, 0.10))
                CC[hy, hx] = float(rng.uniform(0.02, 0.10))

    # 6) DUST PIT & FLECK CARPET â€” 5x
    n_fl = int(np.clip(7000 * (mn / 2048.0) ** 2, 2300, 16000))
    fx = rng.integers(0, w, n_fl); fy = rng.integers(0, h, n_fl)
    M[fy, fx] = rng.uniform(0.18, 0.92, n_fl).astype(np.float32)
    R[fy, fx] = rng.uniform(0.16, 0.85, n_fl).astype(np.float32)
    CC[fy, fx] = rng.uniform(0.06, 0.80, n_fl).astype(np.float32)

    out = np.stack([M, R, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
reptile_scale._spb_concept_complete = True


# ============================================================================
# 32. MAGNETIC_FIELD â€” iron filing lines along magnetic poles
# ============================================================================

def magnetic_field(shape, seed, sm, num_poles=3, line_density=20.0, **kwargs):
    """Magnetic field â€” DENSE filings + HERO flux loops + aurora arc bands.

    identity: R6 owner-fix rebuild â€” owner said the prior version was
    "Boring / no character" despite being dense. New build adds a HERO
    visual story: bright concentric FLUX LOOPS arc around each pole pair
    (drawn as dashed ellipses, fine 1-2 px stroke, 10-30 px chord
    segments) so the eye sees the magnet structure at thumbnail scale.
    Plus, an AURORA spectral ribbon (smoothly cycling CC) snakes between
    poles like a charged-particle glow. Underneath: the established
    DENSE 8-18 px streamline strokes, 4-9 px filing flakes, and 1-3 px
    iron-dust specks â€” all with INDEPENDENT continuous M/R/CC. The
    pole-influence base stays low-amplitude so the fine features carry.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + (hash('magnetic_field_r6') % 100000))
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)

    # Pole placement
    np_poles = max(int(num_poles), 2) + int(rng.integers(0, 3))
    pxs = rng.uniform(0, w, np_poles)
    pys = rng.uniform(0, h, np_poles)
    signs = rng.choice([-1.0, 1.0], np_poles)
    yy, xx = np.mgrid[0:h, 0:w].astype(np.float32)
    flow = np.zeros((h, w), dtype=np.float32)
    for i in range(np_poles):
        dx = xx - pxs[i]; dy = yy - pys[i]
        d2 = dx * dx + dy * dy + 100.0
        flow += float(signs[i]) * (1.0 / d2) * 8000.0
    flow = _normalize(flow)

    # LOW-AMPLITUDE base â€” let the fine features dominate
    fM = _normalize(multi_scale_noise(shape, [2.5, 6.0, 14.0], [0.5, 0.3, 0.2], int(seed) + 1301))
    fR = _normalize(multi_scale_noise(shape, [3.0, 7.0, 16.0], [0.5, 0.3, 0.2], int(seed) + 1303))
    fCC = _normalize(multi_scale_noise(shape, [3.5, 8.0, 18.0], [0.5, 0.3, 0.2], int(seed) + 1305))
    M  = (0.40 + 0.10 * flow + 0.18 * (fM  - 0.5)).astype(np.float32)
    R  = (0.52 - 0.08 * flow + 0.18 * (fR  - 0.5)).astype(np.float32)
    CC = (0.38 + 0.08 * flow + 0.20 * (fCC - 0.5)).astype(np.float32)

    if _CV2_OK:
        # TIER 1 â€” FINE 8-18 px streamline strokes (3x density of prior)
        n_lines = int(np.clip(h * w / 220.0, 2400, 9000))
        for _ in range(n_lines):
            x = float(rng.uniform(0, w)); y = float(rng.uniform(0, h))
            # Sample field direction at this point
            vx = vy = 0.0
            for i in range(np_poles):
                dx = x - pxs[i]; dy = y - pys[i]
                d2 = dx * dx + dy * dy + 25.0
                s = float(signs[i]) / d2
                vx += s * dx; vy += s * dy
            m = (vx * vx + vy * vy) ** 0.5 + 1e-6
            ux = vx / m; uy = vy / m
            length = float(rng.uniform(8.0, 18.0) * scale)
            x0s = int(x - ux * length * 0.5); y0s = int(y - uy * length * 0.5)
            x1s = int(x + ux * length * 0.5); y1s = int(y + uy * length * 0.5)
            # INDEPENDENT continuous uniforms
            _cv2.line(M,  (x0s, y0s), (x1s, y1s), float(rng.uniform(0.55, 0.96)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(R,  (x0s, y0s), (x1s, y1s), float(rng.uniform(0.06, 0.32)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.06, 0.38)), 1, lineType=_cv2.LINE_AA)

        # TIER 2 â€” even shorter 4-9 px filing flakes
        n_flake = int(np.clip(h * w / 130.0, 4000, 15000))
        for _ in range(n_flake):
            x = float(rng.uniform(0, w)); y = float(rng.uniform(0, h))
            vx = vy = 0.0
            for i in range(np_poles):
                dx = x - pxs[i]; dy = y - pys[i]
                d2 = dx * dx + dy * dy + 25.0
                s = float(signs[i]) / d2
                vx += s * dx; vy += s * dy
            m = (vx * vx + vy * vy) ** 0.5 + 1e-6
            ux = vx / m; uy = vy / m
            length = float(rng.uniform(4.0, 9.0) * scale)
            x0s = int(x - ux * length * 0.5); y0s = int(y - uy * length * 0.5)
            x1s = int(x + ux * length * 0.5); y1s = int(y + uy * length * 0.5)
            _cv2.line(M,  (x0s, y0s), (x1s, y1s), float(rng.uniform(0.45, 0.92)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(R,  (x0s, y0s), (x1s, y1s), float(rng.uniform(0.08, 0.42)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.10, 0.50)), 1, lineType=_cv2.LINE_AA)

        # POLE bright spots (kept SMALL, â‰¤14 px diameter)
        for i in range(np_poles):
            rr = int(np.clip(7 * scale, 4, 7))
            _cv2.circle(M, (int(pxs[i]), int(pys[i])), rr, float(rng.uniform(0.82, 0.98)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (int(pxs[i]), int(pys[i])), rr, float(rng.uniform(0.06, 0.18)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (int(pxs[i]), int(pys[i])), rr, float(rng.uniform(0.05, 0.20)), -1, lineType=_cv2.LINE_AA)

        # HERO FLUX LOOPS â€” bright concentric ellipses around each pole
        # drawn as DASHED arc segments so they read as field structure.
        for i in range(np_poles):
            cx_p = int(pxs[i]); cy_p = int(pys[i])
            n_loops = int(rng.integers(4, 8))
            for li in range(n_loops):
                # Loop radius grows out from pole; each loop ANGLED differently
                rad = int((6 + li * 5) * (1.0 + 0.3 * rng.random()))
                if rad < 4: continue
                ang_rot = float(rng.uniform(0, 180))
                # Draw as 6-9 dashed sub-arcs
                n_dash = int(rng.integers(6, 10))
                a0 = float(rng.uniform(0, 360))
                arc_each = 360.0 / n_dash * 0.55
                for d in range(n_dash):
                    sa = a0 + d * (360.0 / n_dash)
                    ea = sa + arc_each
                    flux_M  = float(rng.uniform(0.70, 0.99))
                    flux_R  = float(rng.uniform(0.04, 0.20))
                    flux_CC = float(rng.uniform(0.10, 0.92))  # wide chroma
                    _cv2.ellipse(M,  (cx_p, cy_p), (rad, max(2, int(rad * 0.75))),
                                 ang_rot, sa, ea, flux_M, 1, lineType=_cv2.LINE_AA)
                    _cv2.ellipse(R,  (cx_p, cy_p), (rad, max(2, int(rad * 0.75))),
                                 ang_rot, sa, ea, flux_R, 1, lineType=_cv2.LINE_AA)
                    _cv2.ellipse(CC, (cx_p, cy_p), (rad, max(2, int(rad * 0.75))),
                                 ang_rot, sa, ea, flux_CC, 1, lineType=_cv2.LINE_AA)

        # AURORA SPECTRAL RIBBON â€” a snaking high-CC band drifting between
        # poles, drawn as a polyline with smoothly cycling CC and bright M.
        n_ribbon = int(rng.integers(2, 5))
        for _r in range(n_ribbon):
            # Walk from one pole to a random one with field-following steps
            p_src = int(rng.integers(0, np_poles))
            p_dst = int(rng.integers(0, np_poles))
            if p_src == p_dst: continue
            x_curr = float(pxs[p_src]); y_curr = float(pys[p_src])
            x_end = float(pxs[p_dst]); y_end = float(pys[p_dst])
            steps = 28
            cc_phase = float(rng.uniform(0, 2 * np.pi))
            for k in range(steps):
                t = k / max(steps - 1, 1)
                # Interpolate target + add curl from field
                xt = (1 - t) * x_curr + t * x_end + np.sin(t * 6.0 + cc_phase) * 0.10 * w
                yt = (1 - t) * y_curr + t * y_end + np.cos(t * 5.0 + cc_phase * 0.7) * 0.10 * h
                if k == 0:
                    x_prev, y_prev = xt, yt
                    continue
                # Spectral CC cycles along the ribbon â€” HERO chroma flow
                cc_val = 0.20 + 0.78 * (0.5 + 0.5 * np.sin(cc_phase + k * 0.55))
                _cv2.line(M,  (int(x_prev), int(y_prev)), (int(xt), int(yt)),
                          float(rng.uniform(0.78, 0.96)), 2, lineType=_cv2.LINE_AA)
                _cv2.line(R,  (int(x_prev), int(y_prev)), (int(xt), int(yt)),
                          float(rng.uniform(0.04, 0.18)), 2, lineType=_cv2.LINE_AA)
                _cv2.line(CC, (int(x_prev), int(y_prev)), (int(xt), int(yt)),
                          float(cc_val), 2, lineType=_cv2.LINE_AA)
                x_prev, y_prev = xt, yt

    # TIER 3 â€” iron-speck dust (1 px scatter with INDEPENDENT continuous uniforms)
    n_dust = int(np.clip(h * w / 90.0, 6000, 22000))
    ys = rng.integers(0, h, n_dust); xs = rng.integers(0, w, n_dust)
    M[ys, xs] = np.maximum(M[ys, xs], rng.uniform(0.45, 0.96, n_dust).astype(np.float32))
    R[ys, xs] = np.minimum(R[ys, xs], rng.uniform(0.05, 0.35, n_dust).astype(np.float32))
    CC[ys, xs] = np.minimum(CC[ys, xs], rng.uniform(0.05, 0.40, n_dust).astype(np.float32))
    out = np.stack([M, R, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
magnetic_field._spb_concept_complete = True


def prismatic_shatter(shape, seed, sm, num_shards=60, **kwargs):
    """prismatic_shatter.

    identity: Round-6 CREATIVE rebuild â€” smashed rainbow safety glass with
    a HERO STARBURST FRACTURE: 5-9 radiating crack spokes (24-40 px) emanate
    from 3-5 impact-point epicenters, each spoke punctuated by a bright
    fragmented-shard chain. Surrounding the spokes is a dense Voronoi
    fracture field (~12 px) where each shard reads as an INDEPENDENT prism
    with its own refraction gradient axis and chroma. Brand-new SPECTRUM
    SWATCH BANDS: per-shard, a random 1-2 px wide stripe of bright high-M
    color across the shard, simulating where light bent through the prism.
    Stacked: (A) substrate FBM with INDEPENDENT M/R/CC, (B) Voronoi shard
    field with per-cell refraction gradient + spectrum swatch, (C) bright
    fracture seams between shards, (D) HERO impact starbursts, (E) dense
    prism rainbow streaks 8-18 px, (F) crystalline sparkle glints, (G) dark
    microfracture hairlines, (H) corner-of-shard bright pinpoint flecks.
    Per-feature INDEPENDENT continuous M/R/CC uniforms with WIDE chroma.
    """
    shape = tuple(shape) if hasattr(shape, '__iter__') else shape
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 67223)
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)

    # 0) Substrate FBM â€” INDEPENDENT M/R/CC
    fM = _normalize(multi_scale_noise(shape, [2.0, 5.0, 12.0], [0.5, 0.3, 0.2], int(seed) + 8201))
    fR = _normalize(multi_scale_noise(shape, [2.4, 6.0, 14.0], [0.5, 0.3, 0.2], int(seed) + 8202))
    fCC = _normalize(multi_scale_noise(shape, [2.8, 7.0, 16.0], [0.5, 0.3, 0.2], int(seed) + 8203))

    # 1) DENSE VORONOI SHARDS at ~12 px target
    target_px = max(8.0, min(16.0, 12.0 * scale))
    n_cells = max(300, int(h * w / (target_px * target_px)))
    pts_y = rng.uniform(-target_px, h + target_px, n_cells).astype(np.float32)
    pts_x = rng.uniform(-target_px, w + target_px, n_cells).astype(np.float32)
    cell_M  = rng.uniform(0.10, 0.97, n_cells).astype(np.float32)
    cell_R  = rng.uniform(0.04, 0.78, n_cells).astype(np.float32)
    cell_CC = rng.uniform(0.04, 0.62, n_cells).astype(np.float32)
    cell_grad_ang = rng.uniform(0, 2 * np.pi, n_cells).astype(np.float32)
    cell_grad_amp = rng.uniform(0.05, 0.22, n_cells).astype(np.float32)
    # spectrum swatch per shard â€” bright stripe inside the shard
    cell_swatch_M = rng.uniform(0.75, 0.99, n_cells).astype(np.float32)
    cell_swatch_R = rng.uniform(0.03, 0.20, n_cells).astype(np.float32)
    cell_swatch_CC = rng.uniform(0.45, 0.95, n_cells).astype(np.float32)
    cell_swatch_off = rng.uniform(-0.45, 0.45, n_cells).astype(np.float32)  # offset along grad axis
    cell_swatch_w = rng.uniform(0.10, 0.30, n_cells).astype(np.float32)  # half-width fraction

    tree = cKDTree(np.column_stack([pts_y.astype(np.float64), pts_x.astype(np.float64)]))
    yy, xx = np.mgrid[0:h, 0:w].astype(np.float64)
    coords = np.column_stack([yy.ravel(), xx.ravel()])
    dists, idxs = tree.query(coords, k=2, workers=-1)
    d1 = dists[:, 0].reshape((h, w)).astype(np.float32)
    d2 = dists[:, 1].reshape((h, w)).astype(np.float32)
    edge = np.clip(1.0 - (d2 - d1) / 1.3, 0, 1).astype(np.float32)
    idx_field = idxs[:, 0].reshape((h, w))

    M = cell_M[idx_field]
    R = cell_R[idx_field]
    CC = cell_CC[idx_field]

    # Blend substrate FBM faintly
    M = np.clip(M + (fM - 0.5) * 0.10, 0, 1)
    R = np.clip(R + (fR - 0.5) * 0.10, 0, 1)
    CC = np.clip(CC + (fCC - 0.5) * 0.10, 0, 1)

    # Per-shard refraction gradient â€” direction-dependent shift
    cx_grid = pts_x[idx_field].astype(np.float32)
    cy_grid = pts_y[idx_field].astype(np.float32)
    g_ang = cell_grad_ang[idx_field]
    g_amp = cell_grad_amp[idx_field]
    yyf = yy.astype(np.float32); xxf = xx.astype(np.float32)
    proj = (xxf - cx_grid) * np.cos(g_ang) + (yyf - cy_grid) * np.sin(g_ang)
    proj_norm = proj / max(target_px, 1.0)
    grad = np.tanh(proj_norm) * g_amp
    M = np.clip(M + grad, 0, 1)
    R = np.clip(R - grad * 0.4, 0, 1)

    # 1b) SPECTRUM SWATCH â€” bright per-shard chroma stripe inside each cell
    swatch_off = cell_swatch_off[idx_field]
    swatch_w = cell_swatch_w[idx_field]
    swatch_dist = np.abs(proj_norm - swatch_off)
    swatch_mask = np.clip(1.0 - swatch_dist / np.maximum(swatch_w, 1e-3), 0.0, 1.0).astype(np.float32)
    # Restrict swatch to shard interior (not on seams)
    interior = 1.0 - edge
    swatch_mask = swatch_mask * interior
    sM = cell_swatch_M[idx_field]
    sR = cell_swatch_R[idx_field]
    sCC = cell_swatch_CC[idx_field]
    M = np.clip(M * (1 - swatch_mask) + sM * swatch_mask, 0, 1)
    R = np.clip(R * (1 - swatch_mask * 0.8) + sR * swatch_mask * 0.8, 0, 1)
    CC = np.clip(CC * (1 - swatch_mask * 0.7) + sCC * swatch_mask * 0.7, 0, 1)

    # Bright fracture seams
    M = np.clip(M + edge * 0.55, 0, 1)
    R = np.clip(R - edge * 0.35, 0, 1)
    CC = np.clip(CC - edge * 0.22, 0, 1)

    if _CV2_OK:
        # 2) HERO STARBURST FRACTURES â€” 3-5 impact epicenters w/ radiating spokes
        n_impacts = int(rng.integers(3, 6))
        for _ in range(n_impacts):
            ix = float(rng.uniform(0.15, 0.85) * w)
            iy = float(rng.uniform(0.15, 0.85) * h)
            n_spokes = int(rng.integers(5, 10))
            for k in range(n_spokes):
                base_ang = (k / n_spokes) * 2 * np.pi + float(rng.uniform(-0.15, 0.15))
                spoke_len = float(rng.uniform(24.0, 40.0) * scale)
                # main spoke
                xe = int(np.clip(ix + np.cos(base_ang) * spoke_len, 0, w - 1))
                ye = int(np.clip(iy + np.sin(base_ang) * spoke_len, 0, h - 1))
                _cv2.line(M, (int(ix), int(iy)), (xe, ye),
                          float(rng.uniform(0.85, 0.99)), 1, lineType=_cv2.LINE_AA)
                _cv2.line(R, (int(ix), int(iy)), (xe, ye),
                          float(rng.uniform(0.02, 0.16)), 1, lineType=_cv2.LINE_AA)
                _cv2.line(CC, (int(ix), int(iy)), (xe, ye),
                          float(rng.uniform(0.55, 0.97)), 1, lineType=_cv2.LINE_AA)
                # fragmented shard chain along spoke
                n_frag = int(rng.integers(3, 7))
                for f in range(n_frag):
                    t = (f + 1) / (n_frag + 1)
                    fx = ix + np.cos(base_ang) * spoke_len * t + float(rng.uniform(-2, 2))
                    fy_ = iy + np.sin(base_ang) * spoke_len * t + float(rng.uniform(-2, 2))
                    rr = max(1, int(rng.uniform(1.5, 3.0) * scale))
                    _cv2.circle(M, (int(fx), int(fy_)), rr,
                                float(rng.uniform(0.78, 0.99)), -1, lineType=_cv2.LINE_AA)
                    _cv2.circle(CC, (int(fx), int(fy_)), rr,
                                float(rng.uniform(0.50, 0.95)), -1, lineType=_cv2.LINE_AA)
            # bright impact core
            cr = max(2, int(rng.uniform(2.5, 4.0) * scale))
            _cv2.circle(M, (int(ix), int(iy)), cr,
                        float(rng.uniform(0.88, 0.99)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (int(ix), int(iy)), cr,
                        float(rng.uniform(0.02, 0.10)), -1, lineType=_cv2.LINE_AA)

        # 3) PRISMATIC RAINBOW STREAKS â€” dense 8-18 px
        n_pr = int(np.clip(3500 * (mn / 2048.0) ** 2, 1200, 14000))
        for _ in range(n_pr):
            cx = float(rng.uniform(4, w - 4)); cy = float(rng.uniform(4, h - 4))
            length = float(rng.uniform(8.0, 18.0) * scale)
            ang = float(rng.uniform(0, 2 * np.pi))
            x0s = int(cx - np.cos(ang) * length * 0.5); y0s = int(cy - np.sin(ang) * length * 0.5)
            x1s = int(cx + np.cos(ang) * length * 0.5); y1s = int(cy + np.sin(ang) * length * 0.5)
            _cv2.line(M, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.55, 0.97)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.04, 0.32)), 1, lineType=_cv2.LINE_AA)

        # 4) SPARKLE GLINTS
        n_sp = int(np.clip(4500 * (mn / 2048.0) ** 2, 1400, 18000))
        for _ in range(n_sp):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            r_g = max(1, int(rng.uniform(1.0, 2.5) * scale))
            _cv2.circle(M, (cx, cy), r_g, float(rng.uniform(0.82, 0.99)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r_g, float(rng.uniform(0.04, 0.18)), -1, lineType=_cv2.LINE_AA)

        # 5) DARK MICROFRACTURES â€” 8-16 px
        n_mf = int(np.clip(2300 * (mn / 2048.0) ** 2, 800, 9000))
        for _ in range(n_mf):
            cx = float(rng.uniform(4, w - 4)); cy = float(rng.uniform(4, h - 4))
            length = float(rng.uniform(8.0, 16.0) * scale)
            ang = float(rng.uniform(0, 2 * np.pi))
            x0s = int(cx - np.cos(ang) * length * 0.5); y0s = int(cy - np.sin(ang) * length * 0.5)
            x1s = int(cx + np.cos(ang) * length * 0.5); y1s = int(cy + np.sin(ang) * length * 0.5)
            _cv2.line(M, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.05, 0.22)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(R, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.55, 0.88)), 1, lineType=_cv2.LINE_AA)

    # 6) BRIGHT PINPOINT FLECKS â€” full canvas
    n_fl = int(np.clip(4500 * (mn / 2048.0) ** 2, 1600, 18000))
    fy = rng.integers(0, h, n_fl); fx = rng.integers(0, w, n_fl)
    M[fy, fx] = np.maximum(M[fy, fx], rng.uniform(0.72, 0.99, n_fl).astype(np.float32))
    CC[fy, fx] = np.minimum(CC[fy, fx], rng.uniform(0.04, 0.20, n_fl).astype(np.float32))

    # 7) NEW HERO (tick-creativity) â€” PERIPHERAL-DRIFT ILLUSION CHEVRONS.
    # Optical-illusion motif inside shattered glass: scatter ~120-300 tiny
    # 4-segment chevron stamps (6-12 px). Each chevron is a dark-light-dark-
    # light micro-stripe quartet that triggers the peripheral-drift illusion
    # when seen in the corner of the viewer's eye. Independent M / R / CC
    # per chevron, and per-stripe phase rotation.
    if _CV2_OK:
        n_drift = int(np.clip(220 * (mn / 2048.0) ** 2, 90, 540))
        for _ in range(n_drift):
            cx_d = int(rng.uniform(0.03, 0.97) * w)
            cy_d = int(rng.uniform(0.03, 0.97) * h)
            L = float(rng.uniform(6.0, 12.0) * scale)
            ang = float(rng.uniform(0.0, 2.0 * np.pi))
            cos_a = float(np.cos(ang)); sin_a = float(np.sin(ang))
            perp_x = -sin_a; perp_y = cos_a
            # 4 thin stripes alternating dark/bright, offset along normal
            for i, step in enumerate((-1.5, -0.5, 0.5, 1.5)):
                ox = cx_d + perp_x * step * 1.6
                oy = cy_d + perp_y * step * 1.6
                x0 = int(ox - cos_a * L * 0.5); y0 = int(oy - sin_a * L * 0.5)
                x1 = int(ox + cos_a * L * 0.5); y1 = int(oy + sin_a * L * 0.5)
                bright = (i % 2 == 0)
                m_v = float(rng.uniform(0.70, 0.98) if bright else rng.uniform(0.06, 0.24))
                r_v = float(rng.uniform(0.08, 0.30) if bright else rng.uniform(0.55, 0.92))
                c_v = float(rng.uniform(0.10, 0.40) if bright else rng.uniform(0.55, 0.92))
                _cv2.line(M, (x0, y0), (x1, y1), m_v, 1, lineType=_cv2.LINE_AA)
                _cv2.line(R, (x0, y0), (x1, y1), r_v, 1, lineType=_cv2.LINE_AA)
                _cv2.line(CC, (x0, y0), (x1, y1), c_v, 1, lineType=_cv2.LINE_AA)

    out = np.stack([M, R, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
prismatic_shatter._spb_concept_complete = True


# ============================================================================
# 34. NEURAL_DENDRITE â€” branching neural network dendrites
# ============================================================================

def neural_dendrite(shape, seed, sm, num_neurons=5, branch_depth=7, **kwargs):
    """neural_dendrite.

    identity: R6-CORRECTIVE for owner 'Boring / no character'. A HERO COSMOS
    of NEURON HUB CELLS â€” 14-26 large luminous soma bodies (10-20 px) act
    as the brain-cell character of the pattern, each with a bright glow
    core + ringed halo + 4-7 radiating AXON TREES that branch as polylines
    (4-6 segments, bending) FROM the hub outward toward sibling hubs.
    Between hubs, FIRING ARCS â€” cyan-bright synaptic discharges (8-14 px
    curved bolts with low R / high M+CC) crackle across the substrate.
    Stacked: (A) wide-chroma neural FBM tissue, (B) hero soma hubs with
    independent chroma per hub, (C) axon-tree polylines anchored at hubs,
    (D) firing discharge arcs, (E) myelinated micro-fiber 4-9 px dashes,
    (F) dense satellite mini-soma 2-4 px, (G) bioluminescent flecks,
    (H) dark synaptic pits. Per-feature INDEPENDENT continuous M/R/CC
    uniforms with WIDE ranges including warm-orange and cyan extremes.
    No panel-scale - hubs cap at 20 px.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 22217)
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)

    def _fbm(off, sigma):
        if _CV2_OK:
            sh = max(64, h // 10); sw = max(64, w // 10)
            n = np.random.default_rng(int(seed) + off).random((sh, sw)).astype(np.float32)
            b = _cv2.GaussianBlur(n, (0, 0), sigmaX=sigma, sigmaY=sigma)
            return _normalize(_cv2.resize(b, (w, h), interpolation=_cv2.INTER_CUBIC).astype(np.float32))
        return _normalize(multi_scale_noise(shape, [20.0, 40.0], [0.6, 0.4], int(seed) + off))

    # A) BASE â€” neural tissue FBM, INDEPENDENT per channel, WIDER swing
    fM = _fbm(7610, 4.0); fR = _fbm(7612, 4.0); fCC = _fbm(7614, 4.0)
    M = (0.24 + (fM - 0.5) * 0.34).astype(np.float32)
    R_ch = (0.62 + (fR - 0.5) * 0.30).astype(np.float32)
    CC = (0.34 + (fCC - 0.5) * 0.32).astype(np.float32)

    # B) HERO SOMA HUBS â€” 14-26 large illuminated neuron bodies
    n_hub_target = max(14, int(26 * (mn / 256.0) ** 0.4))
    n_hub = int(np.clip(n_hub_target, 12, 60))
    hubs = []
    for _ in range(n_hub):
        cx = int(rng.uniform(0.05, 0.95) * w); cy = int(rng.uniform(0.05, 0.95) * h)
        # Each hub gets its OWN chroma identity
        hM  = float(rng.uniform(0.55, 0.97))
        hR  = float(rng.uniform(0.05, 0.38))
        hCC = float(rng.uniform(0.40, 0.95))
        rad = int(np.clip(rng.uniform(10.0, 20.0) * scale, 6, 22))
        hubs.append((cx, cy, rad, hM, hR, hCC))

    if _CV2_OK:
        # Draw hubs: halo ring + bright core
        for cx, cy, rad, hM, hR, hCC in hubs:
            # Halo ring (1-2 px thick outline)
            _cv2.circle(M,  (cx, cy), rad, float(min(1.0, hM + 0.05)), 2, lineType=_cv2.LINE_AA)
            _cv2.circle(R_ch, (cx, cy), rad, float(max(0.0, hR - 0.10)), 2, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), rad, float(min(1.0, hCC + 0.05)), 2, lineType=_cv2.LINE_AA)
            # Bright core fill (~60% radius)
            r_core = max(2, int(rad * 0.55))
            _cv2.circle(M,  (cx, cy), r_core, hM, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R_ch, (cx, cy), r_core, hR, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r_core, hCC, -1, lineType=_cv2.LINE_AA)
            # Hyper-bright nucleus pip
            r_nuc = max(1, int(rad * 0.22))
            _cv2.circle(M,  (cx, cy), r_nuc, float(min(1.0, hM + 0.10)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r_nuc, float(min(1.0, hCC + 0.08)), -1, lineType=_cv2.LINE_AA)

        # C) AXON TREES â€” each hub fires 4-7 dendrite polylines outward
        for cx, cy, rad, hM, hR, hCC in hubs:
            n_arms = int(rng.integers(4, 8))
            for arm in range(n_arms):
                ax = float(cx); ay = float(cy)
                ang = float(rng.uniform(0, 2 * np.pi))
                # Inherit hub chroma with per-arm jitter
                aM  = float(np.clip(hM  + rng.uniform(-0.18, 0.10), 0.30, 0.98))
                aR  = float(np.clip(hR  + rng.uniform(-0.05, 0.20), 0.05, 0.55))
                aCC = float(np.clip(hCC + rng.uniform(-0.18, 0.10), 0.20, 0.95))
                n_seg = int(rng.integers(3, 6))
                # Step out from hub edge
                ax += np.cos(ang) * rad; ay += np.sin(ang) * rad
                for s_i in range(n_seg):
                    L = float(rng.uniform(8.0, 18.0) * scale)
                    bx = float(np.clip(ax + np.cos(ang) * L, 0, w - 1))
                    by = float(np.clip(ay + np.sin(ang) * L, 0, h - 1))
                    _cv2.line(M,    (int(ax), int(ay)), (int(bx), int(by)), aM, 1, lineType=_cv2.LINE_AA)
                    _cv2.line(R_ch, (int(ax), int(ay)), (int(bx), int(by)), aR, 1, lineType=_cv2.LINE_AA)
                    _cv2.line(CC,   (int(ax), int(ay)), (int(bx), int(by)), aCC, 1, lineType=_cv2.LINE_AA)
                    # Side spur on roughly half the segments
                    if rng.random() < 0.5:
                        side_ang = ang + float(rng.choice([-1.0, 1.0])) * np.pi / 3
                        Ls = L * 0.55
                        sx = float(np.clip(ax + np.cos(side_ang) * Ls, 0, w - 1))
                        sy = float(np.clip(ay + np.sin(side_ang) * Ls, 0, h - 1))
                        _cv2.line(M,    (int(ax), int(ay)), (int(sx), int(sy)), float(aM * 0.9), 1, lineType=_cv2.LINE_AA)
                        _cv2.line(CC,   (int(ax), int(ay)), (int(sx), int(sy)), float(aCC * 0.92), 1, lineType=_cv2.LINE_AA)
                    ax, ay = bx, by
                    ang += float(rng.uniform(-0.55, 0.55))

        # D) FIRING ARCS â€” bright synaptic discharges between nearby hubs
        for i, (cx, cy, rad, _hM, _hR, _hCC) in enumerate(hubs):
            # Connect to 1-2 random sibling hubs that are not too far
            for _ in range(int(rng.integers(1, 3))):
                j = int(rng.integers(0, len(hubs)))
                if j == i: continue
                tx, ty, _r2, _, _, _ = hubs[j]
                d = float(np.hypot(tx - cx, ty - cy))
                if d > 90.0 * scale or d < 12.0: continue
                # Curved arc by interpolating through a perpendicular midpoint
                mx = (cx + tx) * 0.5; my = (cy + ty) * 0.5
                dx = tx - cx; dy = ty - cy
                perp_x = -dy / max(d, 1e-3); perp_y = dx / max(d, 1e-3)
                bow = float(rng.uniform(-0.25, 0.25)) * d
                mx += perp_x * bow; my += perp_y * bow
                # 6-segment polyline curve via quadratic bezier sampling
                arc_M  = float(rng.uniform(0.78, 0.98))
                arc_R  = float(rng.uniform(0.04, 0.18))
                arc_CC = float(rng.uniform(0.68, 0.97))
                prev = (cx, cy)
                for t_i in range(1, 7):
                    t = t_i / 6.0
                    u_t = 1.0 - t
                    px_ = int(u_t * u_t * cx + 2 * u_t * t * mx + t * t * tx)
                    py_ = int(u_t * u_t * cy + 2 * u_t * t * my + t * t * ty)
                    _cv2.line(M,    prev, (px_, py_), arc_M, 1, lineType=_cv2.LINE_AA)
                    _cv2.line(R_ch, prev, (px_, py_), arc_R, 1, lineType=_cv2.LINE_AA)
                    _cv2.line(CC,   prev, (px_, py_), arc_CC, 1, lineType=_cv2.LINE_AA)
                    prev = (px_, py_)

        # E) MYELINATED MICRO-FIBER DASHES â€” 4-9 px short dashes filling gaps
        n_my = int(np.clip(3200 * (mn / 2048.0) ** 2, 1100, 9000))
        for _ in range(n_my):
            cx = int(rng.uniform(2, w - 2)); cy = int(rng.uniform(2, h - 2))
            L = float(rng.uniform(4.0, 9.0) * scale)
            ang = float(rng.uniform(0, 2 * np.pi))
            x2 = int(np.clip(cx + np.cos(ang) * L, 0, w - 1))
            y2 = int(np.clip(cy + np.sin(ang) * L, 0, h - 1))
            _cv2.line(M,    (cx, cy), (x2, y2), float(rng.uniform(0.40, 0.85)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(R_ch, (cx, cy), (x2, y2), float(rng.uniform(0.15, 0.50)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC,   (cx, cy), (x2, y2), float(rng.uniform(0.35, 0.82)), 1, lineType=_cv2.LINE_AA)

        # F) SATELLITE MINI-SOMA â€” 2-4 px to keep density
        n_mini = int(np.clip(2600 * (mn / 2048.0) ** 2, 900, 8000))
        for _ in range(n_mini):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            r = max(1, int(rng.uniform(1.5, 3.0) * scale))
            _cv2.circle(M,    (cx, cy), r, float(rng.uniform(0.55, 0.95)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R_ch, (cx, cy), r, float(rng.uniform(0.08, 0.35)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC,   (cx, cy), r, float(rng.uniform(0.50, 0.92)), -1, lineType=_cv2.LINE_AA)

    # G) BIOLUMINESCENT FLECKS â€” single-pixel bright sparks
    n_fl = int(np.clip(3500 * (mn / 2048.0) ** 2, 1200, 12000))
    fx = rng.integers(0, w, n_fl); fy = rng.integers(0, h, n_fl)
    M[fy, fx]  = np.maximum(M[fy, fx],  rng.uniform(0.62, 0.98, n_fl).astype(np.float32))
    CC[fy, fx] = np.maximum(CC[fy, fx], rng.uniform(0.55, 0.96, n_fl).astype(np.float32))

    # H) DARK SYNAPTIC SHADOW PITS
    n_pit = int(np.clip(1800 * (mn / 2048.0) ** 2, 600, 7000))
    px = rng.integers(0, w, n_pit); py = rng.integers(0, h, n_pit)
    M[py, px]  = np.minimum(M[py, px],  rng.uniform(0.04, 0.20, n_pit).astype(np.float32))
    R_ch[py, px] = np.maximum(R_ch[py, px], rng.uniform(0.58, 0.94, n_pit).astype(np.float32))

    out = np.stack([M, R_ch, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
neural_dendrite._spb_concept_complete = True


# ============================================================================
# 35. HEAT_DISTORTION â€” convection shimmer waves
# ============================================================================

def heat_distortion(shape, seed, sm, wave_count=12, turbulence=4.0, **kwargs):
    """heat_distortion â€” R6 CREATIVE rebuild.

    identity: A panel boiling with refractive heat â€” the surface is broken
    into RISING PLUMES (28-44 of them: bright vertical S-curve filaments,
    each a tapering ribbon 6-16 px wide x 80-220 px long, hand-warped by
    independent sinusoids so each plume snakes uniquely). Where two plumes
    cross, BRIGHT MIRAGE LENS RINGS (16-28 concentric arc pairs, 10-26 px)
    bloom on top â€” these are the hero feature, reading like heat-haze
    refraction halos. Underneath: hex-cell shimmer mosaic (each cell 8-14
    px, per-cell continuous M/R/CC) reads as the vibrating air. Sprinkled:
    glowing ember pinpricks (1-2 px), short slanted "wind" tears (4-10 px)
    in the prevailing warp direction, and dark cool-air vortex dots
    (2-3 px) for chroma contrast. Per-feature INDEPENDENT M/R/CC uniforms.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 71422)
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)
    yy, xx = np.mgrid[0:h, 0:w].astype(np.float32)

    # 1) HEX SHIMMER MOSAIC â€” per-cell continuous chroma reads as boiling air
    cell = max(8.0, 11.0 * scale)
    row_h = cell * 0.8660254
    row_i = np.floor(yy / row_h).astype(np.int32)
    row_offset_x = (row_i & 1).astype(np.float32) * cell * 0.5
    col_i = np.round((xx - row_offset_x) / cell).astype(np.int32)
    col64 = col_i.astype(np.uint64) & np.uint64(0xFFFFFFFF)
    row64 = row_i.astype(np.uint64) & np.uint64(0xFFFFFFFF)
    seed64 = np.uint64(int(seed) & 0xFFFFFFFF)
    h_seed = (col64 * np.uint64(0x9E3779B1)) ^ (row64 * np.uint64(0x85EBCA77)) ^ seed64
    cell_M = ((h_seed * np.uint64(2654435761)) & np.uint64(0xFFFFFF)).astype(np.float32) / float(0xFFFFFF)
    cell_R = ((h_seed * np.uint64(1597334677)) & np.uint64(0xFFFFFF)).astype(np.float32) / float(0xFFFFFF)
    cell_C = ((h_seed * np.uint64(374761393))  & np.uint64(0xFFFFFF)).astype(np.float32) / float(0xFFFFFF)
    fbm = _normalize(multi_scale_noise(shape, [3.0, 8.0, 18.0, 40.0], [0.32, 0.30, 0.22, 0.16], int(seed) + 7141))
    M  = (0.42 + (cell_M - 0.5) * 0.45 + (fbm - 0.5) * 0.18).astype(np.float32)
    R  = (0.40 + (cell_R - 0.5) * 0.45 + (fbm - 0.5) * 0.16).astype(np.float32)
    CC = (0.38 + (cell_C - 0.5) * 0.45 + (fbm - 0.5) * 0.20).astype(np.float32)

    if _CV2_OK:
        # 2) HERO: RISING PLUMES â€” tapering S-curve filaments
        n_plume = int(np.clip(36 * (mn / 1024.0), 14, 80))
        for _ in range(n_plume):
            cx0 = float(rng.uniform(0.04, 0.96) * w)
            cy0 = float(h - 1)
            cy1 = float(rng.uniform(0.02, 0.55) * h)
            amp = float(rng.uniform(8.0, 24.0) * scale)
            freq = float(rng.uniform(1.4, 3.6))
            phase = float(rng.uniform(0.0, 2 * np.pi))
            n_seg = 36
            pm = float(rng.uniform(0.62, 0.96))
            pr = float(rng.uniform(0.06, 0.34))
            pcc = float(rng.uniform(0.05, 0.40))
            prev = None
            for s in range(n_seg + 1):
                t = s / n_seg
                py = cy0 + (cy1 - cy0) * t
                taper = 1.0 - t * 0.85
                px = cx0 + np.sin(t * freq * np.pi + phase) * amp * taper
                pt = (int(px), int(py))
                if prev is not None:
                    thick = max(1, int(rng.uniform(1.4, 2.6) * scale))
                    _cv2.line(M, prev, pt, pm * (0.55 + 0.5 * taper), thick, lineType=_cv2.LINE_AA)
                    _cv2.line(R, prev, pt, pr, thick, lineType=_cv2.LINE_AA)
                    _cv2.line(CC, prev, pt, pcc, thick, lineType=_cv2.LINE_AA)
                prev = pt

        # 3) HERO: MIRAGE LENS RINGS â€” concentric arc halos (the named "distortion")
        n_ring = int(np.clip(22 * (mn / 1024.0), 9, 52))
        for _ in range(n_ring):
            cx = int(rng.uniform(0.06, 0.94) * w)
            cy = int(rng.uniform(0.06, 0.94) * h)
            n_arc = int(rng.integers(3, 6))
            base_r = float(rng.uniform(6.0, 14.0) * scale)
            for a in range(n_arc):
                rad = max(2, int(base_r + a * 3.4 * scale))
                ang0 = float(rng.uniform(0, 360))
                ang1 = ang0 + float(rng.uniform(120, 260))
                m_v = float(rng.uniform(0.66, 0.98))
                r_v = float(rng.uniform(0.05, 0.30))
                c_v = float(rng.uniform(0.04, 0.36))
                _cv2.ellipse(M, (cx, cy), (rad, rad), 0, ang0, ang1, m_v, 1, lineType=_cv2.LINE_AA)
                _cv2.ellipse(R, (cx, cy), (rad, rad), 0, ang0, ang1, r_v, 1, lineType=_cv2.LINE_AA)
                _cv2.ellipse(CC, (cx, cy), (rad, rad), 0, ang0, ang1, c_v, 1, lineType=_cv2.LINE_AA)

        # 4) SHORT WIND-TEAR streaks (4-10 px, mostly horizontal warp direction)
        n_tear = max(2400, int(h * w / 110))
        for _ in range(n_tear):
            x0 = int(rng.integers(0, w)); y0 = int(rng.integers(0, h))
            ll = float(rng.uniform(4.0, 10.0) * scale)
            ang = float(rng.uniform(-0.55, 0.55))
            x1 = int(x0 + np.cos(ang) * ll); y1 = int(y0 + np.sin(ang) * ll * 0.6)
            _cv2.line(M, (x0, y0), (x1, y1), float(rng.uniform(0.52, 0.94)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(R, (x0, y0), (x1, y1), float(rng.uniform(0.07, 0.34)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (x0, y0), (x1, y1), float(rng.uniform(0.05, 0.40)), 1, lineType=_cv2.LINE_AA)

    # 5) GLOWING EMBER pinpricks (vectorized 1-2 px)
    n_glow = max(6000, int(h * w / 80))
    gy = rng.integers(0, h, n_glow); gx = rng.integers(0, w, n_glow)
    M[gy, gx] = np.maximum(M[gy, gx], rng.uniform(0.74, 0.99, n_glow).astype(np.float32))
    R[gy, gx] = np.minimum(R[gy, gx], rng.uniform(0.04, 0.22, n_glow).astype(np.float32))
    CC[gy, gx] = np.minimum(CC[gy, gx], rng.uniform(0.03, 0.28, n_glow).astype(np.float32))

    # 6) DARK COOL-AIR VORTEX dots â€” chroma contrast
    n_dark = max(3200, int(h * w / 160))
    dy = rng.integers(0, h, n_dark); dx = rng.integers(0, w, n_dark)
    M[dy, dx] = np.minimum(M[dy, dx], rng.uniform(0.04, 0.22, n_dark).astype(np.float32))
    R[dy, dx] = np.maximum(R[dy, dx], rng.uniform(0.62, 0.95, n_dark).astype(np.float32))
    CC[dy, dx] = rng.uniform(0.20, 0.78, n_dark).astype(np.float32)

    out = np.stack([M, R, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)


heat_distortion._spb_concept_complete = True


def rust_bloom(shape, seed=0, sm=1.0, **kwargs):
    """rust_bloom.

    identity: BLOOMING orange rust with HERO PINHOLE PUNCTURES â€” classic
    radial-gradient bloom discs (center bright orange, mid-ring dark scab,
    outer-ring clean halo) PLUS the signature diversifier: 8-16 rust-eaten
    through-holes per panel where the metal has corroded clean through
    (tiny 3-6 px black-cored apertures ringed by a bright orange flare
    halo and weeping trickle stains downward). Flake-peel arcs at bloom
    edges, rust-dust trickles, ferrous orange dust flecks. Distinct from
    spec_rust_bloom (no through-hole punctures, no weep stains) and from
    patina_bloom (orange-ferrous vs green-blue chroma).
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 51904 + 7777)
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)

    # 1) Clean steel substrate (FBM, independent M/R/CC)
    g1 = _normalize(multi_scale_noise(shape, [3.0, 7.0, 14.0, 22.0], [0.36, 0.30, 0.22, 0.14], int(seed) + 5011))
    g2 = _normalize(multi_scale_noise(shape, [3.5, 7.5, 15.0, 23.0], [0.34, 0.30, 0.22, 0.14], int(seed) + 5013))
    g3 = _normalize(multi_scale_noise(shape, [4.0, 8.0, 16.0, 24.0], [0.34, 0.30, 0.22, 0.14], int(seed) + 5015))
    M = (0.58 + (g1 - 0.5) * 0.24).astype(np.float32)
    R = (0.40 + (g2 - 0.5) * 0.24).astype(np.float32)
    CC = (0.42 + (g3 - 0.5) * 0.24).astype(np.float32)

    # 2) BLOOMING DISCS â€” explicit radial-gradient blooms (center bright orange, rim dark scab)
    n_bloom = int(np.clip(500 * (mn / 2048.0) ** 2, 200, 1800))
    for _ in range(n_bloom):
        cx = float(rng.uniform(0.02, 0.98) * w); cy = float(rng.uniform(0.02, 0.98) * h)
        r = float(rng.uniform(5.0, 14.0) * scale)
        tile = int(r * 3) + 2
        x0 = max(0, int(cx) - tile); x1 = min(w, int(cx) + tile + 1)
        y0 = max(0, int(cy) - tile); y1 = min(h, int(cy) + tile + 1)
        if x1 <= x0 or y1 <= y0: continue
        tyy, txx = np.mgrid[y0:y1, x0:x1].astype(np.float32)
        d = np.sqrt((txx - cx) ** 2 + (tyy - cy) ** 2) / max(r, 1e-7)
        # Center: bright orange (M low-mid, R extremely high). Mid-ring: dark scab.
        # Outer-ring: clean halo (M back up). Bloom radial profile.
        center = np.exp(-(d ** 2) * 1.8)
        ring = np.exp(-((d - 0.85) ** 2) * 8.0)
        # Per-bloom independent chroma
        c_M = float(rng.uniform(0.20, 0.50))
        c_R = float(rng.uniform(0.78, 0.96))
        c_CC = float(rng.uniform(0.55, 0.88))
        ring_M = float(rng.uniform(0.06, 0.22))
        ring_R = float(rng.uniform(0.82, 0.96))
        ring_CC = float(rng.uniform(0.70, 0.92))
        M[y0:y1, x0:x1] = np.clip(M[y0:y1, x0:x1] * (1.0 - center * 0.65 - ring * 0.40) + center * c_M * 0.65 + ring * ring_M * 0.40, 0, 1)
        R[y0:y1, x0:x1] = np.clip(R[y0:y1, x0:x1] * (1.0 - center * 0.65 - ring * 0.40) + center * c_R * 0.65 + ring * ring_R * 0.40, 0, 1)
        CC[y0:y1, x0:x1] = np.clip(CC[y0:y1, x0:x1] * (1.0 - center * 0.55 - ring * 0.35) + center * c_CC * 0.55 + ring * ring_CC * 0.35, 0, 1)

    if _CV2_OK:
        # 3) FLAKE-PEEL ARCS â€” short curved scoring at bloom rims
        n_arc = int(np.clip(700 * (mn / 2048.0) ** 2, 240, 2100))
        for _ in range(n_arc):
            cx = int(rng.uniform(4, w - 4)); cy = int(rng.uniform(4, h - 4))
            r = max(3, int(rng.uniform(4.0, 11.0) * scale))
            a0 = float(rng.uniform(0, 360)); a1 = a0 + float(rng.uniform(40, 110))
            aM = float(rng.uniform(0.50, 0.88))
            aR = float(rng.uniform(0.20, 0.50))
            aCC = float(rng.uniform(0.15, 0.42))
            _cv2.ellipse(M, (cx, cy), (r, r), 0, a0, a1, aM, 1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(R, (cx, cy), (r, r), 0, a0, a1, aR, 1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(CC, (cx, cy), (r, r), 0, a0, a1, aCC, 1, lineType=_cv2.LINE_AA)

        # 4) TRICKLE DOTS â€” short rust-dust trickle drips below blooms
        n_trk = int(np.clip(600 * (mn / 2048.0) ** 2, 200, 1800))
        for _ in range(n_trk):
            cx = int(rng.uniform(4, w - 4)); cy = int(rng.uniform(4, h - 12))
            length = int(rng.uniform(4, 12) * scale)
            cy2 = min(h - 1, cy + length)
            tM = float(rng.uniform(0.25, 0.50))
            tR = float(rng.uniform(0.65, 0.88))
            tCC = float(rng.uniform(0.55, 0.82))
            _cv2.line(M, (cx, cy), (cx + int(rng.uniform(-2, 2)), cy2), tM, 1, lineType=_cv2.LINE_AA)
            _cv2.line(R, (cx, cy), (cx + int(rng.uniform(-2, 2)), cy2), tR, 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (cx, cy), (cx + int(rng.uniform(-2, 2)), cy2), tCC, 1, lineType=_cv2.LINE_AA)

    # 5) RUST-DUST FLECKS â€” orange-biased per-feature continuous M/R/CC
    n_fl = int(np.clip(1800 * (mn / 2048.0) ** 2, 600, 4200))
    fy = rng.integers(0, h, n_fl); fx = rng.integers(0, w, n_fl)
    M[fy, fx] = rng.uniform(0.18, 0.55, n_fl).astype(np.float32)
    R[fy, fx] = rng.uniform(0.55, 0.95, n_fl).astype(np.float32)
    CC[fy, fx] = rng.uniform(0.40, 0.88, n_fl).astype(np.float32)

    # 6) HERO MOTIF â€” RUST-EATEN PINHOLE PUNCTURES with weep stains
    # The diversifier: metal corroded through, leaving tiny dark apertures
    # ringed by bright orange flare and a downward weep trickle stain.
    if _CV2_OK:
        n_holes = int(rng.integers(8, 17))
        for _ in range(n_holes):
            hx = int(rng.uniform(0.08, 0.92) * w)
            hy = int(rng.uniform(0.08, 0.85) * h)
            r_in = max(2, int(rng.uniform(3.0, 6.0) * scale))
            # Bright orange flare halo (slightly larger than aperture)
            r_halo = r_in + max(2, int(rng.uniform(2.0, 4.0) * scale))
            _cv2.circle(M, (hx, hy), r_halo, float(rng.uniform(0.32, 0.55)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (hx, hy), r_halo, float(rng.uniform(0.78, 0.98)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (hx, hy), r_halo, float(rng.uniform(0.60, 0.92)), -1, lineType=_cv2.LINE_AA)
            # Black aperture core (the actual hole through metal)
            _cv2.circle(M, (hx, hy), r_in, float(rng.uniform(0.02, 0.12)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (hx, hy), r_in, float(rng.uniform(0.85, 0.99)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (hx, hy), r_in, float(rng.uniform(0.02, 0.18)), -1, lineType=_cv2.LINE_AA)
            # Weep stain â€” meandering trickle 12-26 px downward
            weep_len = int(rng.uniform(12.0, 26.0) * scale)
            wx, wy = hx, hy
            for step in range(weep_len):
                wx += int(rng.uniform(-1, 1))
                wy += 1
                if 0 <= wx < w and 0 <= wy < h:
                    M[wy, wx] = float(rng.uniform(0.28, 0.52))
                    R[wy, wx] = float(rng.uniform(0.70, 0.92))
                    CC[wy, wx] = float(rng.uniform(0.55, 0.85))

        # 7) TICK52 NEW HERO â€” IRON-OXIDE CRYSTAL NEEDLE BURSTS
        # Spiky akaganeite/hematite needle clusters jutting OUT of bloom
        # surfaces. Each burst: 5-10 sharp 6-14 px needles radiating from a
        # nucleation point, plus a halo of micro-needle satellites.
        n_xtal = int(np.clip(60 * (mn / 1024.0), 24, 180))
        for _ in range(n_xtal):
            cx0 = float(rng.uniform(0.04, 0.96) * w)
            cy0 = float(rng.uniform(0.04, 0.96) * h)
            n_arm = int(rng.integers(5, 11))
            base_a = float(rng.uniform(0, 2 * np.pi))
            # Per-burst independent chroma â€” wide chroma range
            bM = float(rng.uniform(0.42, 0.88))
            bR = float(rng.uniform(0.25, 0.62))
            bCC = float(rng.uniform(0.35, 0.85))
            for k in range(n_arm):
                a = base_a + k * (2 * np.pi / n_arm) + float(rng.uniform(-0.18, 0.18))
                L = float(rng.uniform(6.0, 14.0) * scale)
                x_tip = int(np.clip(cx0 + np.cos(a) * L, 0, w - 1))
                y_tip = int(np.clip(cy0 + np.sin(a) * L, 0, h - 1))
                _cv2.line(M, (int(cx0), int(cy0)), (x_tip, y_tip),
                          float(rng.uniform(0.55, 0.95)), 1, lineType=_cv2.LINE_AA)
                _cv2.line(R, (int(cx0), int(cy0)), (x_tip, y_tip),
                          float(rng.uniform(0.22, 0.60)), 1, lineType=_cv2.LINE_AA)
                _cv2.line(CC, (int(cx0), int(cy0)), (x_tip, y_tip),
                          float(rng.uniform(0.30, 0.85)), 1, lineType=_cv2.LINE_AA)
                # Bright tip spark
                _cv2.circle(M, (x_tip, y_tip), 1, float(rng.uniform(0.78, 0.99)),
                            -1, lineType=_cv2.LINE_AA)
            # Satellite micro-needles around burst (chroma-diverse)
            n_sat = int(rng.integers(6, 13))
            for _s in range(n_sat):
                sa = float(rng.uniform(0, 2 * np.pi))
                sd = float(rng.uniform(3.0, 9.0) * scale)
                sx0 = int(cx0 + np.cos(sa) * sd)
                sy0 = int(cy0 + np.sin(sa) * sd)
                sa2 = sa + float(rng.uniform(-1.3, 1.3))
                sL = float(rng.uniform(2.5, 5.5) * scale)
                sx1 = int(np.clip(sx0 + np.cos(sa2) * sL, 0, w - 1))
                sy1 = int(np.clip(sy0 + np.sin(sa2) * sL, 0, h - 1))
                if 0 <= sx0 < w and 0 <= sy0 < h:
                    _cv2.line(M, (sx0, sy0), (sx1, sy1),
                              float(rng.uniform(0.45, 0.90)), 1, lineType=_cv2.LINE_AA)
                    _cv2.line(R, (sx0, sy0), (sx1, sy1),
                              float(rng.uniform(0.30, 0.70)), 1, lineType=_cv2.LINE_AA)
                    _cv2.line(CC, (sx0, sy0), (sx1, sy1),
                              float(rng.uniform(0.25, 0.78)), 1, lineType=_cv2.LINE_AA)

    out = np.stack([M, R, CC], axis=-1).astype(np.float32)
    return _validate_spec_output(_sm_scale(np.clip(out, 0.0, 1.0), sm).astype(np.float32), "rust_bloom")
rust_bloom._spb_concept_complete = True


# ============================================================================
# 37. QUANTUM_NOISE â€” multi-frequency probability density field
# ============================================================================

def quantum_noise(shape, seed, sm, num_waves=30, **kwargs):
    """quantum_noise.

    identity: R6 creative pass â€” quantum probability-density readout
    with NEW HERO: SUPERPOSITION DOUBLE-DOT PAIRS (twin 2-4 px bright
    spots connected by a thin entanglement line, scattered densely)
    AND INTERFERENCE LATTICE STRIPES (a faint sin(x)*sin(y) wave-grid
    on the M-channel only, evoking double-slit fringes). Three superposed
    high-frequency FBM substrates form the wavefunction noise floor.
    Probability peaks (4-10 px discs) at 5x density with paired
    interference shadow. Fringe arcs (6-14 px). Quantised bright scatter
    + dark void collapse points. Each primitive uses INDEPENDENT
    continuous-uniform M/R/CC.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 56631)
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)

    # 1) FBM SUBSTRATE â€” three independent high-freq channels
    g_M = _normalize(multi_scale_noise((h, w), [2.0, 5.0, 11.0, 22.0], [0.38, 0.28, 0.20, 0.14], int(seed) + 81))
    g_R = _normalize(multi_scale_noise((h, w), [2.5, 6.0, 13.0, 26.0], [0.38, 0.28, 0.20, 0.14], int(seed) + 83))
    g_CC = _normalize(multi_scale_noise((h, w), [3.0, 7.0, 15.0, 28.0], [0.38, 0.28, 0.20, 0.14], int(seed) + 89))
    M = (0.38 + (g_M - 0.5) * 0.36).astype(np.float32)
    R = (0.48 + (g_R - 0.5) * 0.30).astype(np.float32)
    CC = (0.42 + (g_CC - 0.5) * 0.34).astype(np.float32)

    # 1b) HERO â€” INTERFERENCE LATTICE STRIPES on M-channel only (faint double-slit fringe)
    yy_n = (np.arange(h, dtype=np.float32) / max(h, 1))[:, None]
    xx_n = (np.arange(w, dtype=np.float32) / max(w, 1))[None, :]
    fringe_freq_a = float(rng.uniform(60.0, 90.0))
    fringe_freq_b = float(rng.uniform(50.0, 80.0))
    phase_a = float(rng.uniform(0, 2 * np.pi)); phase_b = float(rng.uniform(0, 2 * np.pi))
    fringe = (np.sin(xx_n * fringe_freq_a * np.pi + phase_a) *
              np.sin(yy_n * fringe_freq_b * np.pi + phase_b)).astype(np.float32)
    M = np.clip(M + fringe * 0.085, 0.0, 1.0)
    CC = np.clip(CC + fringe * 0.055, 0.0, 1.0)

    if _CV2_OK:
        # 2) PROBABILITY PEAKS â€” 5x density, each with paired shadow neighbour
        n_peak = int(np.clip(6500 * (mn / 2048.0) ** 2, 2200, 22000))
        for _ in range(n_peak):
            cx = int(rng.integers(2, w - 2)); cy = int(rng.integers(2, h - 2))
            r = max(2, int(rng.uniform(2.0, 5.0) * scale))
            pk_M  = float(rng.uniform(0.62, 0.99))
            pk_R  = float(rng.uniform(0.06, 0.28))
            pk_CC = float(rng.uniform(0.06, 0.30))
            _cv2.circle(M, (cx, cy), r, pk_M, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r, pk_R, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r, pk_CC, -1, lineType=_cv2.LINE_AA)
            # paired shadow next to it (interference darkening)
            dx = int(rng.integers(-4, 5)); dy = int(rng.integers(-4, 5))
            sx = int(np.clip(cx + dx * scale, 0, w - 1))
            sy = int(np.clip(cy + dy * scale, 0, h - 1))
            _cv2.circle(M, (sx, sy), max(1, r - 1), float(rng.uniform(0.05, 0.22)), -1, lineType=_cv2.LINE_AA)

        # 2b) HERO â€” SUPERPOSITION DOUBLE-DOT PAIRS (entanglement line)
        n_pair = int(np.clip(2200 * (mn / 2048.0) ** 2, 700, 7500))
        for _ in range(n_pair):
            cx1 = int(rng.integers(2, w - 2)); cy1 = int(rng.integers(2, h - 2))
            dx_p = int(rng.uniform(-7, 8)); dy_p = int(rng.uniform(-7, 8))
            cx2 = int(np.clip(cx1 + dx_p, 0, w - 1)); cy2 = int(np.clip(cy1 + dy_p, 0, h - 1))
            r_p = max(1, int(rng.uniform(1.5, 3.0) * scale))
            pM1 = float(rng.uniform(0.66, 0.97))
            pM2 = float(rng.uniform(0.62, 0.95))
            pR = float(rng.uniform(0.06, 0.32))
            pCC = float(rng.uniform(0.06, 0.40))
            _cv2.circle(M, (cx1, cy1), r_p, pM1, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(M, (cx2, cy2), r_p, pM2, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx1, cy1), r_p, pR, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx2, cy2), r_p, pR, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx1, cy1), r_p, pCC, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx2, cy2), r_p, pCC, -1, lineType=_cv2.LINE_AA)
            # entanglement thread
            _cv2.line(M, (cx1, cy1), (cx2, cy2), float(rng.uniform(0.42, 0.78)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (cx1, cy1), (cx2, cy2), float(rng.uniform(0.08, 0.30)), 1, lineType=_cv2.LINE_AA)

        # 3) FRINGE ARCS â€” 6-14 px
        n_arc = int(np.clip(3200 * (mn / 2048.0) ** 2, 1100, 11000))
        for _ in range(n_arc):
            cx = int(rng.uniform(4, w - 4)); cy = int(rng.uniform(4, h - 4))
            r = max(3, int(rng.uniform(3.0, 8.0) * scale))
            a0 = float(rng.uniform(0, 360)); sweep = float(rng.uniform(50, 180))
            _cv2.ellipse(M, (cx, cy), (r, r), 0.0, a0, a0 + sweep, float(rng.uniform(0.50, 0.94)), 1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(CC, (cx, cy), (r, r), 0.0, a0, a0 + sweep, float(rng.uniform(0.10, 0.38)), 1, lineType=_cv2.LINE_AA)

    # 4) QUANTISED BRIGHT SCATTER â€” vectorized (5x)
    n_fl = int(np.clip(8000 * (mn / 2048.0) ** 2, 3000, 32000))
    fx = rng.integers(0, w, n_fl); fy = rng.integers(0, h, n_fl)
    M[fy, fx] = np.maximum(M[fy, fx], rng.uniform(0.55, 0.99, n_fl).astype(np.float32))
    R[fy, fx] = np.minimum(R[fy, fx], rng.uniform(0.05, 0.28, n_fl).astype(np.float32))

    # 5) DARK VOID DOTS (collapse points)
    n_v = int(np.clip(6000 * (mn / 2048.0) ** 2, 2000, 24000))
    vx = rng.integers(0, w, n_v); vy = rng.integers(0, h, n_v)
    M[vy, vx] = np.minimum(M[vy, vx], rng.uniform(0.05, 0.22, n_v).astype(np.float32))
    R[vy, vx] = np.maximum(R[vy, vx], rng.uniform(0.60, 0.93, n_v).astype(np.float32))
    CC[vy, vx] = np.minimum(CC[vy, vx], rng.uniform(0.05, 0.22, n_v).astype(np.float32))

    out = np.stack([M, R, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
quantum_noise._spb_concept_complete = True


# ============================================================================
# 38. WOVEN_MESH â€” fine interlocking thread mesh
# ============================================================================

def woven_mesh(shape, seed, sm, thread_spacing=10, thread_width=3, **kwargs):
    """woven_mesh.

    identity: R6 creative rebuild â€” industrial fabric weave with new HERO
    tiers: WEAVE-DEFECT KNOTS (tight 4-7 px bright knot bumps where two
    threads tangled) and FRAYED FIBER BURSTS (small 8-14 px sunbursts of
    8-12 fine 1-px hairlines radiating from a center, like a broken
    strand spraying open). Per-thread INDEPENDENT continuous M/R/CC,
    8-12 px spacing, checker over-under. Stacked: (1) FBM substrate,
    (2) per-thread chroma on gaussian cross-section, (3) chiral
    along-thread striations, (4) HERO knots, (5) HERO frayed bursts,
    (6) snag bumps, (7) broken-fiber pocks, (8) fuzz flecks fill.
    Differentiator vs carbon_weave: defect knots and frayed bursts
    give organic accidents; vs canvas_weave: independent per-thread
    chroma (no uniform palette). No macro features, full canvas.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 67341)
    yy, xx = np.mgrid[0:h, 0:w].astype(np.float32)
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)

    # 1) FINE THREAD GEOMETRY â€” tighter spacing for denser weave (8-10 px)
    ts = float(max(8.0, min(12.0, thread_spacing)))
    tw = float(max(2.5, min(3.5, thread_width)))
    h_phase = (yy % ts) / ts
    h_thread = np.exp(-((h_phase - 0.5) * ts / tw) ** 2).astype(np.float32)
    v_phase = (xx % ts) / ts
    v_thread = np.exp(-((v_phase - 0.5) * ts / tw) ** 2).astype(np.float32)

    cell_x = (xx / ts).astype(np.int32)
    cell_y = (yy / ts).astype(np.int32)
    over_under = ((cell_x + cell_y) % 2).astype(np.float32)
    both = h_thread * v_thread
    h_top = h_thread * (1.0 - both * over_under)
    v_top = v_thread * (1.0 - both * (1.0 - over_under))
    thread_mask = np.maximum(h_top, v_top)

    # 2) FBM DARK VALLEY SUBSTRATE â€” independent M/R/CC seeds
    # R6-TICK79: lower R_ch base (0.78 -> 0.52) to keep R mean controlled.
    fM = _normalize(multi_scale_noise(shape, [1.4, 3.6, 9.0, 22.0], [0.34, 0.30, 0.22, 0.14], int(seed) + 6611))
    fR = _normalize(multi_scale_noise(shape, [1.6, 4.2, 10.5, 24.0], [0.34, 0.30, 0.22, 0.14], int(seed) + 6712))
    fCC = _normalize(multi_scale_noise(shape, [1.8, 4.8, 12.0, 26.0], [0.36, 0.28, 0.22, 0.14], int(seed) + 6813))
    M  = 0.14 + (fM - 0.5) * 0.16
    R_ch = 0.52 + (fR - 0.5) * 0.18
    CC = 0.46 + (fCC - 0.5) * 0.22

    # 3) PER-THREAD INDEPENDENT CONTINUOUS UNIFORMS
    # R6-TICK79 palette discipline: cap thread M <= 0.62 to keep composite
    # mean_M <= 0.45 (anti-magenta). HERO knots & frays still push to 0.99.
    n_row = int(h / ts) + 2; n_col = int(w / ts) + 2
    row_M  = rng.uniform(0.28, 0.58, n_row).astype(np.float32)
    row_R  = rng.uniform(0.12, 0.34, n_row).astype(np.float32)
    row_CC = rng.uniform(0.06, 0.32, n_row).astype(np.float32)
    col_M  = rng.uniform(0.28, 0.58, n_col).astype(np.float32)
    col_R  = rng.uniform(0.12, 0.34, n_col).astype(np.float32)
    col_CC = rng.uniform(0.06, 0.32, n_col).astype(np.float32)
    rh_idx = np.clip((yy / ts).astype(np.int32), 0, n_row - 1)
    rv_idx = np.clip((xx / ts).astype(np.int32), 0, n_col - 1)
    horiz_M  = row_M[rh_idx];  horiz_R  = row_R[rh_idx];  horiz_CC = row_CC[rh_idx]
    vert_M   = col_M[rv_idx];  vert_R   = col_R[rv_idx];  vert_CC  = col_CC[rv_idx]

    on_top_M  = np.where(h_top >= v_top, horiz_M, vert_M)
    on_top_R  = np.where(h_top >= v_top, horiz_R, vert_R)
    on_top_CC = np.where(h_top >= v_top, horiz_CC, vert_CC)

    M  = M  * (1.0 - thread_mask) + on_top_M  * thread_mask
    R_ch = R_ch * (1.0 - thread_mask) + on_top_R  * thread_mask
    CC = CC * (1.0 - thread_mask) + on_top_CC * thread_mask

    # 4) CHIRAL STRIATIONS â€” fibers run ALONG each thread direction
    striation_h = (np.sin(xx * (2 * np.pi / 2.4)) * 0.5 + 0.5).astype(np.float32) * h_top
    striation_v = (np.sin(yy * (2 * np.pi / 2.4)) * 0.5 + 0.5).astype(np.float32) * v_top
    M  = M  + striation_h * 0.09 + striation_v * 0.09
    R_ch = R_ch - striation_h * 0.05 - striation_v * 0.05

    if _CV2_OK:
        # 4b) HERO â€” WEAVE-DEFECT KNOTS (tight bright knot bumps 3-4 px)
        n_knot = int(np.clip(900 * (mn / 2048.0) ** 2, 320, 2400))
        for _ in range(n_knot):
            cx = int(rng.integers(2, w - 2)); cy = int(rng.integers(2, h - 2))
            r = max(2, int(rng.uniform(2.0, 3.5) * scale))
            # Knot body â€” brightest highlight (independent M/R/CC)
            _cv2.circle(M,    (cx, cy), r, float(rng.uniform(0.78, 0.99)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R_ch, (cx, cy), r, float(rng.uniform(0.04, 0.18)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC,   (cx, cy), r, float(rng.uniform(0.04, 0.18)), -1, lineType=_cv2.LINE_AA)
            # Dark contour (tight bind ring) â€” independent values
            _cv2.circle(M,    (cx, cy), r + 1, float(rng.uniform(0.10, 0.30)), 1, lineType=_cv2.LINE_AA)
            _cv2.circle(R_ch, (cx, cy), r + 1, float(rng.uniform(0.65, 0.92)), 1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC,   (cx, cy), r + 1, float(rng.uniform(0.50, 0.85)), 1, lineType=_cv2.LINE_AA)

        # 4c) HERO â€” FRAYED FIBER BURSTS (8-14 px sunbursts of 8-12 hairlines)
        n_fray = int(np.clip(550 * (mn / 2048.0) ** 2, 200, 1500))
        for _ in range(n_fray):
            cx = float(rng.uniform(8, w - 8)); cy = float(rng.uniform(8, h - 8))
            n_rays = int(rng.integers(8, 13))
            ray_len = float(rng.uniform(4.0, 7.0) * scale)
            # Per-burst chroma family
            bM_lo = float(rng.uniform(0.55, 0.78)); bM_hi = bM_lo + 0.18
            bR_lo = float(rng.uniform(0.05, 0.18)); bR_hi = bR_lo + 0.15
            bCC_lo = float(rng.uniform(0.06, 0.20)); bCC_hi = bCC_lo + 0.18
            base_ang = float(rng.uniform(0, 2 * np.pi))
            for k in range(n_rays):
                ang = base_ang + (k / n_rays) * 2.0 * np.pi + float(rng.uniform(-0.18, 0.18))
                ll = ray_len * float(rng.uniform(0.55, 1.0))
                x2 = int(cx + np.cos(ang) * ll)
                y2 = int(cy + np.sin(ang) * ll)
                _cv2.line(M,    (int(cx), int(cy)), (x2, y2), float(rng.uniform(bM_lo, bM_hi)), 1, lineType=_cv2.LINE_AA)
                _cv2.line(R_ch, (int(cx), int(cy)), (x2, y2), float(rng.uniform(bR_lo, bR_hi)), 1, lineType=_cv2.LINE_AA)
                _cv2.line(CC,   (int(cx), int(cy)), (x2, y2), float(rng.uniform(bCC_lo, bCC_hi)), 1, lineType=_cv2.LINE_AA)

        # 5) SNAG-BUMP BRIGHT POINTS â€” kinked thread highlights at crossings (3-6 px)
        n_snag = int(np.clip(2400 * (mn / 2048.0) ** 2, 800, 8000))
        for _ in range(n_snag):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            r = max(1, int(rng.uniform(1.5, 3.0) * scale))
            _cv2.circle(M,  (cx, cy), r, float(rng.uniform(0.72, 0.98)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R_ch,(cx, cy), r, float(rng.uniform(0.05, 0.22)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r, float(rng.uniform(0.04, 0.20)), -1, lineType=_cv2.LINE_AA)

        # 6) BROKEN-FIBER POCKS â€” small dark broken-strand dots
        n_pock = int(np.clip(1100 * (mn / 2048.0) ** 2, 380, 3800))
        for _ in range(n_pock):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            r = max(1, int(rng.uniform(1.0, 2.2) * scale))
            _cv2.circle(M,  (cx, cy), r, float(rng.uniform(0.10, 0.32)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R_ch,(cx, cy), r, float(rng.uniform(0.70, 0.95)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r, float(rng.uniform(0.55, 0.85)), -1, lineType=_cv2.LINE_AA)

    # 7) FUZZ FLECK FILL â€” 1-2 px points everywhere so no blank substrate
    n_fz = int(np.clip(5500 * (mn / 2048.0) ** 2, 1800, 18000))
    fy = rng.integers(0, h, n_fz); fx = rng.integers(0, w, n_fz)
    M[fy, fx]    = np.maximum(M[fy, fx],    rng.uniform(0.40, 0.95, n_fz).astype(np.float32))
    R_ch[fy, fx] = np.minimum(R_ch[fy, fx], rng.uniform(0.06, 0.30, n_fz).astype(np.float32))
    CC[fy, fx]   = np.minimum(CC[fy, fx],   rng.uniform(0.05, 0.25, n_fz).astype(np.float32))

    # 8) R6-TICK79 HERO â€” BIOLOGY MOTIF: SPIDER-SILK DEW DROPLET CLUSTERS
    # Tiny clusters of 3-5 moisture beads strung along thread crossings,
    # like morning dew caught on a real spider-web at dawn. Each bead is
    # 1-2 px with a bright specular cap and a tiny dark base shadow,
    # giving micro-gem sparkle ON TOP of the woven weave.
    if _CV2_OK:
        n_dew = int(np.clip(380 * (mn / 2048.0) ** 2, 140, 1100))
        for _ in range(n_dew):
            cx0 = float(rng.uniform(6, w - 6)); cy0 = float(rng.uniform(6, h - 6))
            # cluster runs ALONG a thread (horizontal or vertical) so beads sit on the silk
            along_horiz = bool(rng.integers(0, 2))
            n_beads = int(rng.integers(3, 6))
            spacing = float(rng.uniform(2.5, 4.0) * scale)
            dM = float(rng.uniform(0.78, 0.99)); dR = float(rng.uniform(0.04, 0.18)); dCC = float(rng.uniform(0.45, 0.92))
            for k in range(n_beads):
                if along_horiz:
                    bx = int(np.clip(cx0 + k * spacing, 1, w - 2)); by = int(cy0)
                else:
                    bx = int(cx0); by = int(np.clip(cy0 + k * spacing, 1, h - 2))
                br = max(1, int(rng.uniform(1.0, 2.2) * scale))
                _cv2.circle(M,    (bx, by), br, dM + float(rng.uniform(-0.05, 0.04)), -1, lineType=_cv2.LINE_AA)
                _cv2.circle(R_ch, (bx, by), br, dR + float(rng.uniform(-0.03, 0.04)), -1, lineType=_cv2.LINE_AA)
                _cv2.circle(CC,   (bx, by), br, dCC + float(rng.uniform(-0.05, 0.05)), -1, lineType=_cv2.LINE_AA)
                # specular pinpoint cap (1 px above-left)
                _cv2.circle(M, (max(0, bx - 1), max(0, by - 1)), 1, float(rng.uniform(0.92, 0.99)), -1, lineType=_cv2.LINE_AA)

    out = np.stack([np.clip(M, 0, 1), np.clip(R_ch, 0, 1), np.clip(CC, 0, 1)], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
woven_mesh._spb_concept_complete = True


# ============================================================================
# 39. LAVA_CRACK â€” cooling lava with glowing fissures
# ============================================================================

def lava_crack(shape, seed, sm, num_plates=35, glow_width=4.0, **kwargs):
    """lava_crack.

    identity: R6 creative rebuild â€” cooled basalt crust riddled with
    incandescent fracture seams, now with HERO ember-glow pools. SEVEN
    stacked tiers: (1) dense per-pixel Voronoi crust at 8-22 px cells
    with independent continuous M/R/CC per plate, (2) bright glowing
    SEAMS via d2-d1 edge detection, (3) hot triple-junction APEX bloom,
    (4) 4-8 HERO EMBER POOLS â€” 14-22 px irregular bright magma pockets
    that glow through the crust with a soft 24-36 px halo (additive
    blob via Gaussian falloff), (5) secondary lateral hairline cracks
    inside plates with widened chroma, (6) dark pumice grit specks +
    bright ash flecks, (7) hot pinpoint sparks along seams + scattered
    micro-embers. Wider per-feature M/R/CC continuous ranges across
    the full gamut.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + (hash("lava_crack_r6") % 10000) + 137826)
    scale = max(min(h, w) / 2048.0, 0.25)
    from scipy.spatial import cKDTree

    # 1) Dense voronoi tessellation â€” 8-22 px cells
    target_cell_px = max(8.0, 14.0 * scale)
    n_plates = int(np.clip((h * w) / (target_cell_px ** 2), 200, 4500))
    pts_y = rng.uniform(0, h, n_plates).astype(np.float64)
    pts_x = rng.uniform(0, w, n_plates).astype(np.float64)
    pts = np.column_stack([pts_y, pts_x])
    tree = cKDTree(pts)
    yy_i, xx_i = np.mgrid[0:h, 0:w]
    coords = np.column_stack([yy_i.ravel().astype(np.float64), xx_i.ravel().astype(np.float64)])
    dists, idxs = tree.query(coords, k=3, workers=-1)
    d1 = dists[:, 0].reshape(shape).astype(np.float32)
    d2 = dists[:, 1].reshape(shape).astype(np.float32)
    d3 = dists[:, 2].reshape(shape).astype(np.float32)
    labels = idxs[:, 0].reshape(shape)

    # Per-cell INDEPENDENT continuous chroma (composite-dark basalt).
    # FIX 2026-05-26: cell_R was 0.62-0.95 producing neon-green composite.
    # Now cell_R 0.18-0.32 keeps the basalt dark; ember pools and seams add brightness.
    cell_M = rng.uniform(0.10, 0.32, n_plates).astype(np.float32)
    cell_R = rng.uniform(0.18, 0.32, n_plates).astype(np.float32)
    cell_CC = rng.uniform(0.10, 0.28, n_plates).astype(np.float32)

    M = cell_M[labels]
    R = cell_R[labels]
    CC = cell_CC[labels]

    # 2) Bright glowing seam
    seam_width = max(1.0, 1.4 * scale)
    seam = np.clip(1.0 - (d2 - d1) / seam_width, 0.0, 1.0)
    seam_sharp = np.power(seam, 1.6)
    M = np.clip(M + seam_sharp * 0.82, 0, 1)
    R = np.clip(R - seam_sharp * 0.70, 0, 1)
    CC = np.clip(CC - seam_sharp * 0.60, 0, 1)

    # 3) Triple-junction hot bloom
    junction = np.clip(1.0 - (d3 - d2) / max(1.5, 1.8 * scale), 0.0, 1.0)
    junction = (junction > 0.6).astype(np.float32) * (seam_sharp > 0.4).astype(np.float32)
    M = np.clip(M + junction * 0.28, 0, 1)
    CC = np.clip(CC - junction * 0.32, 0, 1)

    # 4) HERO EMBER POOLS â€” 4-8 large magma pockets with halo
    n_ember = int(rng.integers(4, 9))
    yy_f = yy_i.astype(np.float32); xx_f = xx_i.astype(np.float32)
    ember_glow = np.zeros(shape, dtype=np.float32)
    for _ in range(n_ember):
        ex = float(rng.uniform(w * 0.10, w * 0.90))
        ey = float(rng.uniform(h * 0.10, h * 0.90))
        core_r = float(rng.uniform(14.0, 22.0)) * scale
        halo_r = float(rng.uniform(24.0, 36.0)) * scale
        d2_e = (xx_f - ex) ** 2 + (yy_f - ey) ** 2
        halo = np.exp(-d2_e / (2.0 * halo_r * halo_r)).astype(np.float32)
        core = np.exp(-d2_e / (2.0 * core_r * core_r)).astype(np.float32)
        ember_glow = np.maximum(ember_glow, halo * 0.35 + core * 0.85)
        if _CV2_OK:
            # ragged irregular bright core via small overlapping circles
            for _ in range(int(rng.integers(6, 12))):
                ox = ex + float(rng.normal(0, core_r * 0.45))
                oy = ey + float(rng.normal(0, core_r * 0.45))
                rr = max(1, int(rng.uniform(2.0, 5.0) * scale))
                _cv2.circle(M, (int(ox), int(oy)), rr, float(rng.uniform(0.86, 0.99)), -1, lineType=_cv2.LINE_AA)
                _cv2.circle(R, (int(ox), int(oy)), rr, float(rng.uniform(0.05, 0.20)), -1, lineType=_cv2.LINE_AA)
                _cv2.circle(CC, (int(ox), int(oy)), rr, float(rng.uniform(0.06, 0.22)), -1, lineType=_cv2.LINE_AA)
    M = np.clip(M + ember_glow * 0.40, 0, 1)
    R = np.clip(R - ember_glow * 0.30, 0, 1)
    CC = np.clip(CC - ember_glow * 0.28, 0, 1)

    if _CV2_OK:
        # 5) Secondary lateral hairline cracks (2-7 px) â€” trimmed for clarity
        n_branch = int(np.clip(h * w / 1100, 700, 2400))
        for _ in range(n_branch):
            x0 = int(rng.integers(0, w)); y0 = int(rng.integers(0, h))
            a = float(rng.uniform(0, 2 * np.pi))
            ll = int(max(2, rng.uniform(2, 7) * scale))
            x1 = int(x0 + np.cos(a) * ll); y1 = int(y0 + np.sin(a) * ll)
            _cv2.line(M, (x0, y0), (x1, y1), float(rng.uniform(0.60, 0.96)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(R, (x0, y0), (x1, y1), float(rng.uniform(0.06, 0.32)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (x0, y0), (x1, y1), float(rng.uniform(0.10, 0.40)), 1, lineType=_cv2.LINE_AA)

        # 6) Dark pumice grit specks + bright ash flecks (density trimmed)
        n_grit = int(np.clip(h * w / 280, 1800, 5000))
        ys = rng.integers(0, h, n_grit); xs = rng.integers(0, w, n_grit)
        M[ys, xs] = np.minimum(M[ys, xs], rng.uniform(0.03, 0.16, n_grit).astype(np.float32))
        R[ys, xs] = np.maximum(R[ys, xs], rng.uniform(0.25, 0.45, n_grit).astype(np.float32))
        CC[ys, xs] = np.maximum(CC[ys, xs], rng.uniform(0.20, 0.40, n_grit).astype(np.float32))

        n_ash = int(np.clip(h * w / 900, 600, 2200))
        ays = rng.integers(0, h, n_ash); axs = rng.integers(0, w, n_ash)
        M[ays, axs] = np.maximum(M[ays, axs], rng.uniform(0.55, 0.85, n_ash).astype(np.float32))
        CC[ays, axs] = np.maximum(CC[ays, axs], rng.uniform(0.18, 0.40, n_ash).astype(np.float32))

        # 7) Hot pinpoint sparks along seams (trimmed)
        n_hot = int(np.clip(h * w / 1400, 400, 1600))
        ys = rng.integers(0, h, n_hot); xs = rng.integers(0, w, n_hot)
        seam_pick = seam_sharp[ys, xs] > 0.35
        ys = ys[seam_pick]; xs = xs[seam_pick]
        if len(ys) > 0:
            M[ys, xs]  = np.maximum(M[ys, xs],  rng.uniform(0.82, 0.99, len(ys)).astype(np.float32))
            CC[ys, xs] = np.minimum(CC[ys, xs], rng.uniform(0.04, 0.22, len(ys)).astype(np.float32))

        # Scattered micro-embers everywhere (trimmed)
        n_micro = int(np.clip(h * w / 2400, 200, 900))
        for _ in range(n_micro):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            _cv2.circle(M, (cx, cy), 1, float(rng.uniform(0.78, 0.98)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), 1, float(rng.uniform(0.06, 0.28)), -1, lineType=_cv2.LINE_AA)

    # NEW HERO (R6-Loop tick 2026-05-26): MOIRE DIFFRACTION SHIMMER over ember pools.
    # Optical/physics motif: heat-haze diffraction. Two slightly rotated
    # high-frequency sine gratings interfere where the magma glows. Where
    # the two gratings constructively add, we get bright shimmer fringes
    # only inside the ember halo. Outside ember zones the moire is gated to
    # zero so cool basalt stays untouched. TIGHT chroma jitter via the
    # ember_glow mask (which is already 0..1) and a small additive shimmer
    # in M and CC only.
    yy_m, xx_m = np.mgrid[0:h, 0:w].astype(np.float32)
    moire_period_a = max(6.0, 7.0 * scale)
    moire_period_b = max(6.0, 8.2 * scale)
    moire_angle_b = float(rng.uniform(0.10, 0.20))  # small tilt
    g_a = np.sin((xx_m / moire_period_a) * 2.0 * np.pi)
    g_b = np.sin(((xx_m * np.cos(moire_angle_b) + yy_m * np.sin(moire_angle_b)) / moire_period_b) * 2.0 * np.pi)
    moire = ((g_a + g_b) * 0.5).astype(np.float32)
    moire_pos = np.clip(moire, 0.0, 1.0) * ember_glow
    # Add bright shimmer fringes inside ember zones
    M = np.clip(M + moire_pos * 0.18, 0, 1)
    CC = np.clip(CC + moire_pos * 0.14, 0, 1)

    out = np.stack([M, R, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)


lava_crack._spb_concept_complete = True


def diffraction_grating(shape, seed, sm, line_freq=80.0, num_orders=5, **kwargs):
    """diffraction_grating.

    identity: OWNER-REBUILD 2026-06-03 (was a flat ice-blue CA-wavefront
    field; owner: "barely comes through, too flat/boring, weak spec colors,
    low effort"). TRUE SPECTRAL DIFFRACTION GRATING â€” a coarse ruled groove
    set (14-22 px pitch, readable at car scale) where the groove phase
    drives a SPECTRAL SWEEP that rotates the dominant channel M -> R -> CC
    across the field (the literal color separation of a diffraction order).
    Channels are pushed HARD in opposite directions per band so the spec
    colors are bold, not pastel. A second finer cross-grating adds fine
    detail without averaging to mush; sharp groove crests (power-shaped)
    carry bright 1-px rainbow sparkle pin-flecks. Bold amplitude, crisp
    spectral lines.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + (hash("diffraction_grating_owner_rebuild_t0603") % 10000))
    mn = min(h, w); scale = max(mn / 256.0, 0.6)
    yy = np.arange(h, dtype=np.float32)[:, None]
    xx = np.arange(w, dtype=np.float32)[None, :]

    # --- 1) PRIMARY GRATING = CD DATA SPIRAL --------------------------------
    # OWNER FINER pass 2026-06-04: was "too blobby/macro". Now FINE close-pitch
    # spectral tracks that follow a CD's data spiral (concentric-ish curved
    # tracks around a center), with a TIGHT spectral cycle so the rainbow
    # separation is close-pitched, not big color blobs.
    ccx = w * (0.5 + float(rng.uniform(-0.4, 0.4)))    # CD center (often off-canvas)
    ccy = h * (0.5 + float(rng.uniform(-0.4, 0.4)))
    dxs = xx - ccx; dys = yy - ccy
    rad = np.sqrt(dxs * dxs + dys * dys).astype(np.float32)
    ang_f = np.arctan2(dys, dxs).astype(np.float32)
    # spiral coordinate: radius advanced slightly by angle -> Archimedean spiral.
    g_pitch = float(rng.uniform(5.0, 7.5) * scale)     # FINE track pitch (was 16-22)
    spiral = rad + ang_f * (g_pitch / (2.0 * np.pi)) * 1.0
    g_phase = float(rng.uniform(0.0, 2 * np.pi))
    # Sharp groove profile (power curve crisps the crest/valley edge)
    groove = 0.5 + 0.5 * np.sin(spiral * (2.0 * np.pi / g_pitch) + g_phase)
    groove = np.power(groove, 2.2).astype(np.float32)   # crisp bright track crests

    # SPECTRAL SWEEP: a TIGHT phase along the radius rotates which channel is
    # brightest (M -> R -> CC), giving close-pitch spectral color separation
    # like the rainbow you see sweeping across a CD's tracks.
    sweep_period = float(rng.uniform(14.0, 24.0) * scale)   # tight (was 60-110)
    spec_phase = (rad * (2.0 * np.pi / sweep_period)
                  + ang_f * 1.7
                  + float(rng.uniform(0, 2 * np.pi))).astype(np.float32)
    # three lobes 120deg apart -> at any band one channel dominates
    lobe_M = np.clip(np.cos(spec_phase), 0.0, 1.0)
    lobe_R = np.clip(np.cos(spec_phase - 2.094), 0.0, 1.0)
    lobe_CC = np.clip(np.cos(spec_phase - 4.189), 0.0, 1.0)
    # keep a u/v basis for the downstream fine cross-grating + streaks.
    g_ang = float(rng.uniform(0.0, np.pi))
    u = xx * np.cos(g_ang) + yy * np.sin(g_ang)
    v = -xx * np.sin(g_ang) + yy * np.cos(g_ang)

    # Mid-gray base; grating crest swings the spectral channel HARD up and the
    # others down -> bold separation. amplitude pushed (>=0.30 swing).
    AMP = 0.40
    M = (0.50 + (groove - 0.5) * (lobe_M - 0.42) * 2.0 * AMP).astype(np.float32)
    R_ch = (0.50 + (groove - 0.5) * (lobe_R - 0.42) * 2.0 * AMP).astype(np.float32)
    CC = (0.50 + (groove - 0.5) * (lobe_CC - 0.42) * 2.0 * AMP).astype(np.float32)

    # --- 2) SECOND-ORDER FINE CROSS-GRATING ---------------------------------
    # Very fine radial micro-ruling (the data-pit shimmer between tracks).
    f_pitch = float(rng.uniform(3.0, 4.5) * scale)
    fine = (0.5 + 0.5 * np.sin(rad * (2.0 * np.pi / f_pitch) + ang_f * 0.5
                               + float(rng.uniform(0, 2 * np.pi)))).astype(np.float32)
    fine = np.power(fine, 1.6).astype(np.float32)
    M = M + (fine - 0.5) * 0.16
    R_ch = R_ch + (fine - 0.5) * 0.10
    CC = CC + (fine - 0.5) * 0.16

    # --- 3) SHARP SPECTRAL LINE STREAKS (fine, drawn along the tracks) ------
    if _CV2_OK:
        n_streak = int(np.clip(160 * (mn / 256.0) ** 2, 90, 520))
        ca, sa = np.cos(g_ang), np.sin(g_ang)
        for _ in range(n_streak):
            cx = float(rng.uniform(0, w)); cy = float(rng.uniform(0, h))
            length = float(rng.uniform(14.0, 34.0) * scale)
            x0s = int(cx - ca * length * 0.5); y0s = int(cy - sa * length * 0.5)
            x1s = int(cx + ca * length * 0.5); y1s = int(cy + sa * length * 0.5)
            ph = float(rng.uniform(0, 2 * np.pi))
            mv = float(np.clip(0.5 + np.cos(ph) * 0.45, 0.05, 0.99))
            rv = float(np.clip(0.5 + np.cos(ph - 2.094) * 0.45, 0.05, 0.99))
            cv = float(np.clip(0.5 + np.cos(ph - 4.189) * 0.45, 0.05, 0.99))
            _cv2.line(M, (x0s, y0s), (x1s, y1s), mv, 1, lineType=_cv2.LINE_AA)
            _cv2.line(R_ch, (x0s, y0s), (x1s, y1s), rv, 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (x0s, y0s), (x1s, y1s), cv, 1, lineType=_cv2.LINE_AA)

    # --- 4) RAINBOW SPARKLE PIN-FLECKS on crests ----------------------------
    crest = (groove > 0.62)
    cy_idx, cx_idx = np.where(crest)
    if cx_idx.size:
        n_fleck = int(np.clip(1600 * (mn / 256.0) ** 2, 800, 5000))
        pick = rng.integers(0, cx_idx.size, min(n_fleck, cx_idx.size))
        fy = cy_idx[pick]; fx = cx_idx[pick]
        sp = rng.uniform(0, 2 * np.pi, fy.size).astype(np.float32)
        M[fy, fx] = np.clip(0.5 + np.cos(sp) * 0.48, 0, 1)
        R_ch[fy, fx] = np.clip(0.5 + np.cos(sp - 2.094) * 0.48, 0, 1)
        CC[fy, fx] = np.clip(0.5 + np.cos(sp - 4.189) * 0.48, 0, 1)

    out = np.stack([np.clip(M, 0, 1), np.clip(R_ch, 0, 1), np.clip(CC, 0, 1)], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
diffraction_grating._spb_concept_complete = True


def sand_dune(shape, seed, sm, dune_freq=15.0, wind_angle=0.3, **kwargs):
    """sand_dune.

    identity: R6 second-pass â€” dune-crest beach floor with NEW
    DIFFERENTIATOR added on top of prior heroes: TIDAL POOL SHIMMER â€”
    sparse irregular wet glassy patches scattered across the canvas
    where the receding tide left mirror-bright lacquered sand,
    crossed by horizontal water-line ripple bands (very low R, very
    high M, high CC). Tiers stacked:
      (1) Wind-rippled tight parallel stripes (8-14 px period).
      (2) Polychromatic sand-grain fleck carpet (5x density, 1-3 px,
          per-grain independent M/R/CC).
      (3) Dark pebble pits + slipface crescent scars.
      (4) HERO: pearly seashell flecks with iridescent rim arcs.
      (5) Footprint indents + wind-blown pollen streaks + sun-catch
          crest glints.
      (6) NEW DIFFERENTIATOR: TIDAL POOL SHIMMER patches (10-22 px
          irregular wet ellipses) with sub-feature horizontal water-
          line ripple bands inside each pool, plus tiny foam-bubble
          flecks (1-2 px) around pool perimeter.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 41157)
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)
    s256 = max(mn / 256.0, 0.6)

    # 1) Independent dune-shadow FBM per channel
    duneM = _normalize(multi_scale_noise((h, w), [10.0, 28.0, 70.0], [0.32, 0.34, 0.34], int(seed) + 4111))
    duneR = _normalize(multi_scale_noise((h, w), [11.0, 30.0, 72.0], [0.32, 0.34, 0.34], int(seed) + 4113))
    duneC = _normalize(multi_scale_noise((h, w), [12.0, 32.0, 80.0], [0.30, 0.34, 0.36], int(seed) + 4117))

    # 2) TIGHT ripple stripes
    yy = np.arange(h, dtype=np.float32)[:, None]
    xx = np.arange(w, dtype=np.float32)[None, :]
    wa = float(wind_angle) + float(rng.uniform(-0.15, 0.15))
    ca, sa = float(np.cos(wa)), float(np.sin(wa))
    coord = xx * ca + yy * sa
    period = max(8.0, 11.0 * scale)
    ripple = 0.5 + 0.5 * np.sin(coord * (2.0 * np.pi / period) + float(rng.uniform(0, 6.28)))
    chatter = 0.5 + 0.5 * np.sin(coord * (2.0 * np.pi / max(4.0, period * 0.42)) + float(rng.uniform(0, 6.28)))
    ripple = np.clip(ripple * 0.65 + chatter * 0.35, 0.0, 1.0)

    M = (0.30 + (duneM - 0.5) * 0.22 + (ripple - 0.5) * 0.16).astype(np.float32)
    R = (0.72 + (duneR - 0.5) * 0.24 + (ripple - 0.5) * 0.26).astype(np.float32)
    CC = (0.78 + (duneC - 0.5) * 0.18 + (ripple - 0.5) * 0.14).astype(np.float32)

    if _CV2_OK:
        # 3) SAND GRAIN FLECKS (5x density) â€” polychromatic
        n_grain = int(np.clip(h * w * 0.022, 12000, 95000))
        gy = rng.integers(0, h, n_grain); gx = rng.integers(0, w, n_grain)
        M[gy, gx] = np.clip(M[gy, gx] + rng.uniform(-0.24, 0.38, n_grain).astype(np.float32), 0, 1)
        R[gy, gx] = np.clip(R[gy, gx] + rng.uniform(-0.22, 0.24, n_grain).astype(np.float32), 0, 1)
        CC[gy, gx] = np.clip(CC[gy, gx] + rng.uniform(-0.20, 0.26, n_grain).astype(np.float32), 0, 1)

        # 3b) GOLD-FLAKE rare grains (very bright high-M warm)
        n_gold = int(np.clip(h * w * 0.0009, 600, 3500))
        ggy = rng.integers(0, h, n_gold); ggx = rng.integers(0, w, n_gold)
        M[ggy, ggx] = rng.uniform(0.82, 0.99, n_gold).astype(np.float32)
        R[ggy, ggx] = rng.uniform(0.10, 0.32, n_gold).astype(np.float32)
        CC[ggy, ggx] = rng.uniform(0.55, 0.92, n_gold).astype(np.float32)

        # 4) DARK PEBBLE PITS in troughs
        n_pit = int(np.clip(1900 * (mn / 2048.0) ** 2, 450, 8000))
        for _ in range(n_pit):
            cx = int(rng.uniform(0.02, 0.98) * w); cy = int(rng.uniform(0.02, 0.98) * h)
            r_p = max(1, int(rng.uniform(2.0, 6.0) * scale * 0.55))
            _cv2.circle(R, (cx, cy), r_p, float(rng.uniform(0.55, 0.95)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(M, (cx, cy), r_p, float(rng.uniform(0.10, 0.42)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r_p, float(rng.uniform(0.46, 0.88)), -1, lineType=_cv2.LINE_AA)

        # 5) SAND-SLIP ARC SCARS on lee slopes
        n_slip = int(np.clip(900 * (mn / 2048.0) ** 2, 280, 2600))
        for _ in range(n_slip):
            cx = int(rng.uniform(0.04, 0.96) * w); cy = int(rng.uniform(0.04, 0.96) * h)
            rr = max(3, int(rng.uniform(8, 16) * scale * 0.55))
            base_a = float(np.degrees(wa) + 90.0 + float(rng.uniform(-25, 25)))
            span = float(rng.uniform(60, 130))
            sM = float(rng.uniform(0.36, 0.80)); sR = float(rng.uniform(0.50, 0.92)); sC = float(rng.uniform(0.50, 0.90))
            _cv2.ellipse(M, (cx, cy), (rr, max(2, int(rr * 0.55))), 0, base_a, base_a + span, sM, 1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(R, (cx, cy), (rr, max(2, int(rr * 0.55))), 0, base_a, base_a + span, sR, 1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(CC, (cx, cy), (rr, max(2, int(rr * 0.55))), 0, base_a, base_a + span, sC, 1, lineType=_cv2.LINE_AA)

        # 6) HERO â€” PEARLY SEASHELL FLECKS (4-8 px discs + iridescent rim arc)
        n_shell = int(np.clip(90 * s256 * s256, 35, 320))
        for _ in range(n_shell):
            scx = int(rng.uniform(4, w - 4)); scy = int(rng.uniform(4, h - 4))
            srr = max(2, int(rng.uniform(2.0, 4.0) * s256))
            # pearly: low-R, high-CC, mid-high-M
            sM = float(rng.uniform(0.55, 0.92))
            sR_v = float(rng.uniform(0.04, 0.22))
            sC = float(rng.uniform(0.78, 0.99))
            _cv2.circle(M,  (scx, scy), srr, sM, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R,  (scx, scy), srr, sR_v, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (scx, scy), srr, sC, -1, lineType=_cv2.LINE_AA)
            # iridescent rim arc â€” different angle per shell
            arc_a = float(rng.uniform(0, 360)); arc_span = float(rng.uniform(80, 200))
            rim_M = float(rng.uniform(0.72, 0.99)); rim_C = float(rng.uniform(0.85, 0.99))
            _cv2.ellipse(M,  (scx, scy), (srr + 1, srr + 1), 0, arc_a, arc_a + arc_span, rim_M, 1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(CC, (scx, scy), (srr + 1, srr + 1), 0, arc_a, arc_a + arc_span, rim_C, 1, lineType=_cv2.LINE_AA)

        # 7) FOOTPRINT INDENTS â€” rare soft ovals (compressed sand reads darker R-rough)
        n_foot = int(np.clip(8 * s256 * s256, 4, 32))
        for _ in range(n_foot):
            fcx = int(rng.uniform(0.08, 0.92) * w); fcy = int(rng.uniform(0.08, 0.92) * h)
            fa = float(rng.uniform(0, 180)); fr1 = max(4, int(rng.uniform(7, 11) * s256)); fr2 = max(3, int(fr1 * 0.6))
            _cv2.ellipse(M,  (fcx, fcy), (fr1, fr2), fa, 0, 360, float(rng.uniform(0.18, 0.40)), -1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(R,  (fcx, fcy), (fr1, fr2), fa, 0, 360, float(rng.uniform(0.78, 0.96)), -1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(CC, (fcx, fcy), (fr1, fr2), fa, 0, 360, float(rng.uniform(0.55, 0.82)), -1, lineType=_cv2.LINE_AA)
            # rim brighter
            _cv2.ellipse(M, (fcx, fcy), (fr1, fr2), fa, 0, 360, float(rng.uniform(0.55, 0.78)), 1, lineType=_cv2.LINE_AA)

        # 8) WIND-BLOWN POLLEN STREAKS â€” short curving glints aligned to wind
        n_pol = int(np.clip(420 * s256 * s256, 140, 1800))
        for _ in range(n_pol):
            pcx = float(rng.uniform(0, w)); pcy = float(rng.uniform(0, h))
            plen = float(rng.uniform(4.0, 10.0) * s256)
            pa = wa + float(rng.normal(0, 0.10))
            dx = np.cos(pa) * plen * 0.5; dy = np.sin(pa) * plen * 0.5
            p0 = (int(pcx - dx), int(pcy - dy)); p1 = (int(pcx + dx), int(pcy + dy))
            _cv2.line(M, p0, p1, float(rng.uniform(0.45, 0.85)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(R, p0, p1, float(rng.uniform(0.40, 0.78)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, p0, p1, float(rng.uniform(0.55, 0.92)), 1, lineType=_cv2.LINE_AA)

        # 9) BRIGHT CREST SUN-CATCH GLINTS
        n_glint = int(np.clip(5500 * (mn / 2048.0) ** 2, 1600, 14000))
        ly = rng.integers(0, h, n_glint); lx = rng.integers(0, w, n_glint)
        CC[ly, lx] = np.minimum(CC[ly, lx], rng.uniform(0.04, 0.30, n_glint).astype(np.float32))
        M[ly, lx] = np.maximum(M[ly, lx], rng.uniform(0.55, 0.94, n_glint).astype(np.float32))

        # 10) NEW DIFFERENTIATOR â€” TIDAL POOL SHIMMER patches
        n_pool = int(np.clip(60 * s256 * s256, 18, 220))
        for _ in range(n_pool):
            pcx = int(rng.uniform(0.06, 0.94) * w); pcy = int(rng.uniform(0.06, 0.94) * h)
            prx = max(4, int(rng.uniform(5.0, 11.0) * s256))
            pry = max(3, int(prx * float(rng.uniform(0.55, 0.85))))
            prot = float(rng.uniform(0, 180))
            # wet pool: very low R (mirror), high M (water film over wet sand),
            # very low CC (glossy clearcoat)
            poolM = float(rng.uniform(0.62, 0.94))
            poolR = float(rng.uniform(0.04, 0.20))
            poolCC = float(rng.uniform(0.05, 0.22))
            _cv2.ellipse(M, (pcx, pcy), (prx, pry), prot, 0, 360, poolM, -1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(R, (pcx, pcy), (prx, pry), prot, 0, 360, poolR, -1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(CC, (pcx, pcy), (prx, pry), prot, 0, 360, poolCC, -1, lineType=_cv2.LINE_AA)
            # horizontal water-line ripples INSIDE the pool (2-4 bands)
            n_band = int(rng.integers(2, 5))
            for b in range(n_band):
                by = pcy + int((b - n_band / 2) * (pry / max(1, n_band - 1) * 1.6))
                bx0 = pcx - prx; bx1 = pcx + prx
                bandM = float(rng.uniform(0.78, 0.99))
                bandCC = float(rng.uniform(0.03, 0.18))
                _cv2.line(M, (bx0, by), (bx1, by), bandM, 1, lineType=_cv2.LINE_AA)
                _cv2.line(CC, (bx0, by), (bx1, by), bandCC, 1, lineType=_cv2.LINE_AA)
            # foam-bubble flecks around perimeter
            n_foam = int(rng.integers(6, 16))
            for _ in range(n_foam):
                pa = float(rng.uniform(0, 2 * np.pi))
                fx = int(pcx + np.cos(pa) * prx * float(rng.uniform(0.85, 1.15)))
                fy = int(pcy + np.sin(pa) * pry * float(rng.uniform(0.85, 1.15)))
                if 0 <= fx < w and 0 <= fy < h:
                    fr = max(1, int(rng.uniform(1.0, 1.8) * s256))
                    _cv2.circle(M, (fx, fy), fr, float(rng.uniform(0.50, 0.92)), -1, lineType=_cv2.LINE_AA)
                    _cv2.circle(R, (fx, fy), fr, float(rng.uniform(0.45, 0.85)), -1, lineType=_cv2.LINE_AA)
                    _cv2.circle(CC, (fx, fy), fr, float(rng.uniform(0.55, 0.95)), -1, lineType=_cv2.LINE_AA)

    out = np.stack([M, R, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
sand_dune._spb_concept_complete = True

def circuit_trace(shape, seed, sm, trace_count=40, **kwargs):
    """circuit_trace.

    identity: CAFE WALL ILLUSION v2 â€” hand-laid variant. Variable tile widths
    (16-30 px wide, 12-22 px tall) with per-row independent dimensions so rows
    feel hand-laid not machined. 1-in-8 tiles are wider/narrower outliers.
    Per-tile INDEPENDENT continuous M/R/CC rolls give each tile subtle chroma
    personality. Mortar lines 1-3 px with break/repair micro-dashes. 4-8
    rosette focal points where tiles converge in a star/rotation eye-catcher.
    Tilt illusion preserved via 0.4-0.6 row offsets.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 911002)

    M = np.full((h, w), 0.50, dtype=np.float32)
    R_ch = np.full((h, w), 0.28, dtype=np.float32)
    CC = np.full((h, w), 0.45, dtype=np.float32)

    # Build rows of variable height (hand-laid)
    row_specs = []  # (y_top, y_bot, tile_w_base, offset_sign)
    row_idx = 0
    y = 0
    while y < h:
        rh = int(rng.integers(12, 23))  # 12-22 px tall
        rtw = int(rng.integers(16, 31))  # 16-30 px wide base
        row_specs.append((y, min(h, y + rh), rtw, 1 if row_idx % 2 == 0 else -1))
        y += rh
        row_idx += 1

    # Render rows with variable tile widths + mortar above each row
    for ri, (y0, y1, rtw, sign) in enumerate(row_specs):
        # Mortar above (skip first)
        mortar = int(rng.integers(1, 4))  # 1-3 px
        if ri > 0 and mortar > 0:
            ym0 = max(0, y0 - mortar)
            # Base mortar fill
            M[ym0:y0, :] = float(rng.uniform(0.40, 0.50))
            R_ch[ym0:y0, :] = float(rng.uniform(0.50, 0.62))
            CC[ym0:y0, :] = float(rng.uniform(0.22, 0.40))
            # Break/repair micro-dashes â€” short 3-8 px brighter segments
            n_dashes = int(rng.integers(8, 22))
            for _ in range(n_dashes):
                dx0 = int(rng.integers(0, max(1, w - 8)))
                dlen = int(rng.integers(3, 9))
                dx1 = min(w, dx0 + dlen)
                M[ym0:y0, dx0:dx1] = float(rng.uniform(0.55, 0.78))
                CC[ym0:y0, dx0:dx1] = float(rng.uniform(0.10, 0.92))

        offset = int(round(rtw * float(rng.uniform(0.40, 0.60)))) * sign
        x = -rtw + (offset % rtw)
        col_idx = 0
        while x < w:
            # Variable per-tile width: 1-in-8 outliers wider/narrower
            if rng.random() < 0.125:
                tw_i = int(rtw * float(rng.uniform(0.55, 1.75)))
            else:
                tw_i = int(rtw * float(rng.uniform(0.88, 1.12)))
            tw_i = max(8, tw_i)
            x0 = max(0, x)
            x1 = min(w, x + tw_i)
            if x1 > x0 and y1 > y0:
                bright = (col_idx % 2 == 0)
                # Per-tile INDEPENDENT continuous uniforms â€” every channel rolls
                m_val = float(rng.uniform(0.76, 0.98)) if bright else float(rng.uniform(0.03, 0.20))
                r_val = float(rng.uniform(0.04, 0.24)) if bright else float(rng.uniform(0.52, 0.88))
                c_val = float(rng.uniform(0.05, 0.95))
                M[y0:y1, x0:x1] = m_val
                R_ch[y0:y1, x0:x1] = r_val
                CC[y0:y1, x0:x1] = c_val
            x += tw_i
            col_idx += 1

    # HERO: 4-8 rosette focal points â€” small star/rotation eye-catchers
    # where tiles converge. Drawn as a fine 6-12 spoke star overlay.
    if _CV2_OK:
        n_rose = int(rng.integers(4, 9))
        for _ in range(n_rose):
            cx = int(rng.integers(w // 8, 7 * w // 8))
            cy = int(rng.integers(h // 8, 7 * h // 8))
            n_spokes = int(rng.integers(6, 13))
            rad = int(rng.integers(8, 17))  # 8-16 px radius keeps fine-feature rule
            rot0 = float(rng.uniform(0.0, np.pi))
            m_hot = float(rng.uniform(0.85, 0.98))
            r_hot = float(rng.uniform(0.05, 0.18))
            c_hot = float(rng.uniform(0.10, 0.92))
            for sp in range(n_spokes):
                ang = rot0 + sp * (2.0 * np.pi / n_spokes)
                ex = int(cx + np.cos(ang) * rad)
                ey = int(cy + np.sin(ang) * rad)
                _cv2.line(M, (cx, cy), (ex, ey), m_hot, 1, lineType=_cv2.LINE_AA)
                _cv2.line(R_ch, (cx, cy), (ex, ey), r_hot, 1, lineType=_cv2.LINE_AA)
                _cv2.line(CC, (cx, cy), (ex, ey), c_hot, 1, lineType=_cv2.LINE_AA)
            # central pip
            _cv2.circle(M, (cx, cy), 2, m_hot, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), 2, c_hot, -1, lineType=_cv2.LINE_AA)

    # Per-pixel sub-pixel chroma jitter
    CC = np.clip(CC + rng.uniform(-0.03, 0.03, (h, w)).astype(np.float32), 0.0, 1.0)
    M = np.clip(M + rng.uniform(-0.015, 0.015, (h, w)).astype(np.float32), 0.0, 1.0)

    out = np.stack([M, R_ch, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
circuit_trace._spb_concept_complete = True



def _LEGACY_circuit_trace(shape, seed, sm, trace_count=40, **kwargs):
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(seed)
    result = np.full(shape, 0.15, dtype=np.float32)

    pad_centers = []  # (y, x, pad_r, brightness)
    result2 = np.full(shape, 0.12, dtype=np.float32)
    scale = max(1.0, min(h, w) / 512.0)
    yy2, xx2 = np.mgrid[0:h, 0:w].astype(np.float32)
    pad_centers2 = []
    # post-blackout-19 SHORTEN-TRACES: trace_total 90->140 (denser MP-safe scatter)
    # and step_max 72*scale -> 24*scale (was macro 144px at 2048Â² = FSC=7.9 culprit).
    trace_total = max(int(trace_count) * 3, 140)
    step_min = max(6, int(10 * scale))
    step_max = max(step_min + 4, int(24 * scale))
    for _ in range(trace_total):
        x = int(rng.integers(0, w))
        y = int(rng.integers(0, h))
        thickness = int(rng.integers(max(1, int(scale * 0.7)), max(2, int(scale * 2.2)) + 1))
        brightness = float(rng.uniform(0.45, 1.0))
        for _seg in range(int(rng.integers(4, 13))):
            go_horiz = rng.random() < 0.5
            length = int(rng.integers(step_min, step_max))
            sign = 1 if rng.random() < 0.5 else -1
            if go_horiz:
                x2 = int(np.clip(x + sign * length, 0, w - 1))
                y0c = max(0, y - thickness); y1c = min(h, y + thickness + 1)
                x_lo = min(x, x2); x_hi = max(x, x2)
                result2[y0c:y1c, x_lo:x_hi] = np.maximum(result2[y0c:y1c, x_lo:x_hi], brightness)
                x = x2
            else:
                y2 = int(np.clip(y + sign * length, 0, h - 1))
                x0c = max(0, x - thickness); x1c = min(w, x + thickness + 1)
                y_lo = min(y, y2); y_hi = max(y, y2)
                result2[y_lo:y_hi, x0c:x1c] = np.maximum(result2[y_lo:y_hi, x0c:x1c], brightness)
                y = y2
            if rng.random() < 0.32:
                pad_centers2.append((y, x, int(thickness + rng.integers(2, 6) * scale), brightness))
    for _ in range(max(26, trace_total // 3)):
        pad_centers2.append((int(rng.integers(0, h)), int(rng.integers(0, w)), int(rng.integers(max(2, int(2 * scale)), max(3, int(7 * scale)))), float(rng.uniform(0.35, 0.92))))
    for py, px, pad_r, brightness in pad_centers2:
        y0p = max(0, py - pad_r); y1p = min(h, py + pad_r + 1)
        x0p = max(0, px - pad_r); x1p = min(w, px + pad_r + 1)
        dy_arr = np.arange(y0p, y1p, dtype=np.float32) - py
        dx_arr = np.arange(x0p, x1p, dtype=np.float32) - px
        mask = dy_arr[:, np.newaxis] ** 2 + dx_arr[np.newaxis, :] ** 2 <= pad_r * pad_r
        sub = result2[y0p:y1p, x0p:x1p]
        sub[mask] = np.maximum(sub[mask], min(1.0, brightness + 0.15))
        result2[y0p:y1p, x0p:x1p] = sub
    bright = (result2 > 0.5).astype(np.float32)
    glow = _gauss(bright, sigma=max(1.0, 1.6 * scale)) * 0.25
    wafer = _spb_fast_line_distance(xx2 + yy2 * 0.23, max(21.0, min(h, w) / 62.0), 0.45, seed + 4202)
    result2 = np.clip(result2 + glow + wafer * 0.08, 0.0, 1.0)
    # post-blackout-19 EARLY BRU MASK
    rng_ct_bru = np.random.default_rng(seed + 4204)
    mlo_ct = rng_ct_bru.random(result2.shape).astype(np.float32) < 0.055
    mhi_ct = rng_ct_bru.random(result2.shape).astype(np.float32) < 0.055
    result2 = np.where(mlo_ct, 0.10, result2).astype(np.float32)
    result2 = np.where(mhi_ct, 0.92, result2).astype(np.float32)
    # tick 239 MFS-LIFT: pattern had only 2 feature types (traces + pads), MFS=30.
    # Add 4 NEW doctrine-fine component types for PCB realism:
    # - SMD chips (small rectangles 6-12 px)
    # - Solder reflow bright dots (3-6 px)
    # - Silkscreen lines (8-16 px)
    # - Component-lead arcs (8-14 px)
    # All doctrine 8-32 px, palette-tiered.
    if _CV2_OK:
        palette_ct = np.array([0.18,0.28,0.38,0.48,0.58,0.68,0.78,0.92], dtype=np.float32)
        scale_ct = max(min(h, w) / 2048.0, 0.25)
        rng3 = np.random.default_rng(seed + 4203)
        # Type 3: SMD chip rectangles (6-12 px)
        n_chip = int(np.clip(450 * (min(h, w) / 2048.0) ** 2, 160, 1100))
        for _ in range(n_chip):
            cx_ct = int(rng3.integers(8, max(9, w - 8))); cy_ct = int(rng3.integers(8, max(9, h - 8)))
            cw = int(max(2, rng3.uniform(6.0, 12.0) * scale_ct))
            ch = int(max(2, rng3.uniform(4.0, 8.0) * scale_ct))
            x0c = max(0, cx_ct - cw // 2); x1c = min(w, cx_ct + cw // 2)
            y0c = max(0, cy_ct - ch // 2); y1c = min(h, cy_ct + ch // 2)
            v_ct = float(palette_ct[rng3.integers(0, 4)])  # dark â€” chip bodies
            _cv2.rectangle(result2, (x0c, y0c), (x1c, y1c), v_ct, -1)
        # Type 4: solder reflow bright dots (3-6 px)
        n_solder = int(np.clip(500 * (min(h, w) / 2048.0) ** 2, 180, 1200))
        for _ in range(n_solder):
            cx_ct = int(rng3.integers(0, w)); cy_ct = int(rng3.integers(0, h))
            r_ct = int(max(1, rng3.uniform(3.0, 6.0) * scale_ct * 0.5))
            v_ct = float(palette_ct[rng3.integers(5, 8)])  # bright
            _cv2.circle(result2, (cx_ct, cy_ct), r_ct, v_ct, -1, lineType=_cv2.LINE_AA)
        # Type 5: silkscreen short lines (8-16 px, thin)
        n_silk = int(np.clip(300 * (min(h, w) / 2048.0) ** 2, 100, 700))
        for _ in range(n_silk):
            cx_ct = rng3.uniform(4, w - 4); cy_ct = rng3.uniform(4, h - 4)
            length_ct = float(rng3.uniform(8.0, 16.0) * scale_ct)
            ang_ct = float(rng3.choice([0, np.pi * 0.5]))  # axis-aligned silkscreen
            x0s = int(cx_ct - np.cos(ang_ct) * length_ct * 0.5)
            y0s = int(cy_ct - np.sin(ang_ct) * length_ct * 0.5)
            x1s = int(cx_ct + np.cos(ang_ct) * length_ct * 0.5)
            y1s = int(cy_ct + np.sin(ang_ct) * length_ct * 0.5)
            v_ct = float(palette_ct[rng3.integers(6, 8)])  # white silkscreen
            _cv2.line(result2, (x0s, y0s), (x1s, y1s), v_ct, 1, lineType=_cv2.LINE_AA)
        # Type 6: component-lead arcs (8-14 px)
        n_lead = int(np.clip(350 * (min(h, w) / 2048.0) ** 2, 120, 850))
        for _ in range(n_lead):
            cx_ct = int(rng3.integers(8, max(9, w - 8))); cy_ct = int(rng3.integers(8, max(9, h - 8)))
            r_ct = int(max(2, rng3.uniform(8.0, 14.0) * scale_ct * 0.5))
            a0 = float(rng3.uniform(0, 360))
            sweep = float(rng3.uniform(60, 140))
            v_ct = float(palette_ct[rng3.integers(2, 6)])
            _cv2.ellipse(result2, (cx_ct, cy_ct), (r_ct, r_ct), 0.0, a0, a0 + sweep, v_ct, thickness=1, lineType=_cv2.LINE_AA)
        result2 = np.clip(result2, 0.0, 1.0)
    return _sm_scale(_normalize(result2), sm).astype(np.float32)


# ============================================================================
# 43. OIL_SLICK â€” thin-film oil interference with flowing shapes
# ============================================================================

def oil_slick(shape, seed, sm, num_pools=8, freq=6.0, **kwargs):
    """oil_slick.

    identity: R6-creative rebuild (tick53 second-pass) â€” A FLOWING wet
    rainbow oil film on moving water. NEW HERO (tick53): LACUNAR PORES â€”
    chains of 4-7 px sharp-edged black absorbent holes following the
    dominant flow direction, where surface tension has popped the film
    open in beaded chains (each chain has 3-6 voids in series). Stacked
    on prior heroes: (1) DIRECTIONAL FLOW bands, (2) THIN-FILM concentric
    rings, (3) PRISMATIC SPECTRAL SWEEPS 12-20 px, (4) IRIDESCENT FLECKS
    in three size tiers, (5) TENSION-RIDGE pits, (6) crystal-bright
    wetness sparkle carpet, (7) chroma-rich substrate FBM. Every primitive
    picks INDEPENDENT continuous M/R/CC over wide ranges so each speck
    reads as its own visible wavelength.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 33229)
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)

    def _fbm(off, sigma):
        if _CV2_OK:
            sh = max(64, h // 10); sw = max(64, w // 10)
            n = np.random.default_rng(int(seed) + off).random((sh, sw)).astype(np.float32)
            b = _cv2.GaussianBlur(n, (0, 0), sigmaX=sigma, sigmaY=sigma)
            return _normalize(_cv2.resize(b, (w, h), interpolation=_cv2.INTER_CUBIC).astype(np.float32))
        return _normalize(multi_scale_noise(shape, [20.0, 40.0], [0.6, 0.4], int(seed) + off))

    # 1) Wet gloss substrate â€” chroma-rich per-channel FBM
    fM = _fbm(8810, 4.0); fR = _fbm(8812, 4.0); fCC = _fbm(8814, 4.0)
    M = (0.46 + (fM - 0.5) * 0.42).astype(np.float32)
    R_ch = (0.18 + (fR - 0.5) * 0.18).astype(np.float32)
    CC = (0.40 + (fCC - 0.5) * 0.34).astype(np.float32)

    # 2) DIRECTIONAL FLOW field â€” defines the slick's dominant current
    yy = np.arange(h, dtype=np.float32)[:, None]
    xx = np.arange(w, dtype=np.float32)[None, :]
    flow_ang = float(rng.uniform(np.pi * 0.15, np.pi * 0.40))
    flow_warp = _normalize(multi_scale_noise(shape, [22.0, 50.0], [0.6, 0.4], int(seed) + 8820))
    flow_offset = (flow_warp - 0.5) * 30.0 * scale  # local shear
    flow_proj = xx * np.cos(flow_ang) + yy * np.sin(flow_ang) + flow_offset

    # 3) THIN-FILM CONCENTRIC RING FRINGES, SHEARED ALONG FLOW
    ring_period = max(6.0, 11.0 * scale)
    n_centers = int(np.clip(34 * (mn / 2048.0) ** 2, 10, 90))
    fringe_M = np.zeros((h, w), dtype=np.float32)
    fringe_CC = np.zeros((h, w), dtype=np.float32)
    for _ in range(n_centers):
        cx = float(rng.uniform(0, w))
        cy = float(rng.uniform(0, h))
        d = np.sqrt((xx - cx) ** 2 + (yy - cy) ** 2)
        # Add flow-bias to ring distance (shears rings into ovals along current)
        d_sheared = d + (flow_warp - 0.5) * 5.0 * scale
        phase = float(rng.uniform(0, 2 * np.pi))
        amp_M = float(rng.uniform(0.14, 0.26))
        amp_CC = float(rng.uniform(0.12, 0.24))
        fringe_M += np.sin(d_sheared * (2 * np.pi / ring_period) + phase).astype(np.float32) * amp_M
        fringe_CC += np.cos(d_sheared * (2 * np.pi / (ring_period * 0.88)) + phase * 1.4).astype(np.float32) * amp_CC
    M = np.clip(M + fringe_M / max(1, n_centers ** 0.5), 0, 1)
    CC = np.clip(CC + fringe_CC / max(1, n_centers ** 0.5), 0, 1)

    # Sinusoidal flow-stripe modulation (subtle directional banding)
    stripe = (np.sin(flow_proj * (2.0 * np.pi / max(14.0, 18.0 * scale))) * 0.10).astype(np.float32)
    M = np.clip(M + stripe, 0, 1)

    if _CV2_OK:
        # 4) PRISMATIC SPECTRAL SWEEPS â€” long 12-20 px arc fragments along flow
        n_sweep = int(np.clip(1600 * (mn / 2048.0) ** 2, 540, 4800))
        for _ in range(n_sweep):
            cx = int(rng.uniform(0.01, 0.99) * w); cy = int(rng.uniform(0.01, 0.99) * h)
            r = max(4, int(rng.uniform(6.0, 11.0) * scale))
            ang_local = float(flow_ang + rng.normal(0, 0.18))
            a0 = float(np.degrees(ang_local) - rng.uniform(20, 50))
            a1 = a0 + float(rng.uniform(40, 110))
            _cv2.ellipse(M,  (cx, cy), (r, r), 0, a0, a1, float(rng.uniform(0.40, 0.97)), 1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(R_ch, (cx, cy), (r, r), 0, a0, a1, float(rng.uniform(0.06, 0.32)), 1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(CC, (cx, cy), (r, r), 0, a0, a1, float(rng.uniform(0.20, 0.96)), 1, lineType=_cv2.LINE_AA)

        # 5) IRIDESCENT FLECKS â€” three size tiers, independent M/R/CC each
        # tier A: 2-4 px (carpet)
        n_A = int(np.clip(4200 * (mn / 2048.0) ** 2, 1400, 13500))
        for _ in range(n_A):
            cx = int(rng.uniform(0, w)); cy = int(rng.uniform(0, h))
            rx = max(1, int(rng.uniform(1.5, 2.5) * scale))
            ry = max(1, int(rng.uniform(1.0, 2.0) * scale))
            ang = float(rng.uniform(0, 180))
            _cv2.ellipse(M,  (cx, cy), (rx, ry), ang, 0, 360, float(rng.uniform(0.30, 0.96)), -1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(R_ch, (cx, cy), (rx, ry), ang, 0, 360, float(rng.uniform(0.05, 0.32)), -1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(CC, (cx, cy), (rx, ry), ang, 0, 360, float(rng.uniform(0.15, 0.96)), -1, lineType=_cv2.LINE_AA)
        # tier B: 4-7 px (mid)
        n_B = int(np.clip(2400 * (mn / 2048.0) ** 2, 800, 8000))
        for _ in range(n_B):
            cx = int(rng.uniform(0, w)); cy = int(rng.uniform(0, h))
            rx = max(2, int(rng.uniform(2.5, 4.0) * scale))
            ry = max(1, int(rng.uniform(1.5, 3.0) * scale))
            ang = float(rng.uniform(0, 180))
            _cv2.ellipse(M,  (cx, cy), (rx, ry), ang, 0, 360, float(rng.uniform(0.35, 0.95)), -1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(CC, (cx, cy), (rx, ry), ang, 0, 360, float(rng.uniform(0.18, 0.95)), -1, lineType=_cv2.LINE_AA)
        # tier C: 7-10 px (sparse hero)
        n_C = int(np.clip(900 * (mn / 2048.0) ** 2, 300, 2800))
        for _ in range(n_C):
            cx = int(rng.uniform(0, w)); cy = int(rng.uniform(0, h))
            rx = max(3, int(rng.uniform(4.0, 5.0) * scale))
            ry = max(2, int(rng.uniform(2.5, 4.0) * scale))
            ang = float(rng.uniform(0, 180))
            _cv2.ellipse(M,  (cx, cy), (rx, ry), ang, 0, 360, float(rng.uniform(0.48, 0.96)), -1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(R_ch, (cx, cy), (rx, ry), ang, 0, 360, float(rng.uniform(0.06, 0.30)), -1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(CC, (cx, cy), (rx, ry), ang, 0, 360, float(rng.uniform(0.25, 0.95)), -1, lineType=_cv2.LINE_AA)

        # 6) TENSION-RIDGE PITS â€” 1-2 px dark slick edges
        n_dk = int(np.clip(2400 * (mn / 2048.0) ** 2, 800, 8500))
        for _ in range(n_dk):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            r = max(1, int(rng.uniform(0.8, 1.8) * scale))
            _cv2.circle(M,  (cx, cy), r, float(rng.uniform(0.04, 0.26)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R_ch, (cx, cy), r, float(rng.uniform(0.55, 0.90)), -1, lineType=_cv2.LINE_AA)

        # 6b) NEW HERO tick53 â€” LACUNAR PORE CHAINS â€” 4-7 px sharp black
        # absorbent voids in 3-6 bead chains following the flow direction.
        # Each chain represents a popped-film line where surface tension
        # has beaded up. INDEPENDENT M/R/CC per pore so chroma stays varied.
        n_chain = int(np.clip(75 * (mn / 2048.0) ** 2, 22, 230))
        for _ in range(n_chain):
            cx0 = float(rng.uniform(0.04, 0.96) * w)
            cy0 = float(rng.uniform(0.04, 0.96) * h)
            n_beads = int(rng.integers(3, 7))
            ang_local = float(flow_ang + rng.normal(0, 0.30))
            bead_spacing = float(rng.uniform(6.0, 10.0) * scale)
            for bi in range(n_beads):
                bx = int(np.clip(cx0 + np.cos(ang_local) * bead_spacing * bi + rng.uniform(-1.0, 1.0), 0, w - 1))
                by = int(np.clip(cy0 + np.sin(ang_local) * bead_spacing * bi + rng.uniform(-1.0, 1.0), 0, h - 1))
                rb = max(2, int(rng.uniform(2.0, 3.5) * scale))
                # bright sharp rim
                _cv2.circle(M, (bx, by), rb + 1, float(rng.uniform(0.78, 0.99)), 1, lineType=_cv2.LINE_AA)
                _cv2.circle(CC, (bx, by), rb + 1, float(rng.uniform(0.68, 0.98)), 1, lineType=_cv2.LINE_AA)
                # dark absorbent core
                _cv2.circle(M, (bx, by), rb, float(rng.uniform(0.02, 0.12)), -1, lineType=_cv2.LINE_AA)
                _cv2.circle(R_ch, (bx, by), rb, float(rng.uniform(0.78, 0.98)), -1, lineType=_cv2.LINE_AA)
                _cv2.circle(CC, (bx, by), rb, float(rng.uniform(0.04, 0.20)), -1, lineType=_cv2.LINE_AA)

    # 7) Wetness crest sparkles â€” bright pinpricks on the gloss
    n_fl = int(np.clip(3200 * (mn / 2048.0) ** 2, 1100, 12500))
    fx = rng.integers(0, w, n_fl); fy = rng.integers(0, h, n_fl)
    M[fy, fx]  = np.maximum(M[fy, fx],  rng.uniform(0.62, 0.99, n_fl).astype(np.float32))
    CC[fy, fx] = np.maximum(CC[fy, fx], rng.uniform(0.55, 0.98, n_fl).astype(np.float32))

    out = np.stack([M, R_ch, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
oil_slick._spb_concept_complete = True


# ============================================================================
# 44. METEOR_IMPACT â€” radial crater with ejecta rays
# ============================================================================

def meteor_impact(shape, seed, sm, **kwargs):
    """meteor_impact.

    identity: A scorched panel sprinkled with thousands of tiny meteor craters
    rather than one blast. Each crater is a true three-ring structure â€”
    bright rim (4-12 px ring), darker shock collar, and a dim glassy bowl
    (R high, M low). Per-crater INDEPENDENT ejecta-ray bundle (4-8 short
    8-16 px hairlines fanning outward from the same center), plus a
    densified field of dim shadow pits, ember sparkle pinpoints, and a
    scorched FBM substrate. Every primitive has its own continuous M/R/CC.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 44919)
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)

    def _fbm(off, sigma):
        if _CV2_OK:
            sh = max(64, h // 10); sw = max(64, w // 10)
            n = np.random.default_rng(int(seed) + off).random((sh, sw)).astype(np.float32)
            b = _cv2.GaussianBlur(n, (0, 0), sigmaX=sigma, sigmaY=sigma)
            return _normalize(_cv2.resize(b, (w, h), interpolation=_cv2.INTER_CUBIC).astype(np.float32))
        return _normalize(multi_scale_noise(shape, [20.0, 40.0], [0.6, 0.4], int(seed) + off))

    # 1) SCORCHED SUBSTRATE â€” high R, dark M
    fM = _fbm(12610, 4.0); fR = _fbm(12612, 4.0); fCC = _fbm(12614, 4.0)
    M = 0.26 + (fM - 0.5) * 0.28
    R_ch = 0.66 + (fR - 0.5) * 0.28
    CC = 0.34 + (fCC - 0.5) * 0.28

    if _CV2_OK:
        # 2) CRATER FIELD â€” 5x density, each crater has its own ejecta bundle
        n_cr = int(np.clip(2200 * (mn / 2048.0) ** 2, 750, 8000))
        for _ in range(n_cr):
            cx = int(rng.uniform(0.02, 0.98) * w); cy = int(rng.uniform(0.02, 0.98) * h)
            r_outer = max(3, int(rng.uniform(3.0, 7.0) * scale))
            r_collar = max(2, int(r_outer * 0.78))
            r_inner = max(1, int(r_outer * 0.50))
            # bright outer rim
            rim_M  = float(rng.uniform(0.55, 0.95))
            rim_CC = float(rng.uniform(0.40, 0.90))
            _cv2.circle(M,  (cx, cy), r_outer, rim_M, 1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r_outer, rim_CC, 1, lineType=_cv2.LINE_AA)
            # darker shock collar
            _cv2.circle(M,  (cx, cy), r_collar, float(rng.uniform(0.18, 0.42)), 1, lineType=_cv2.LINE_AA)
            _cv2.circle(R_ch, (cx, cy), r_collar, float(rng.uniform(0.55, 0.85)), 1, lineType=_cv2.LINE_AA)
            # glassy bowl
            bowl_M = float(rng.uniform(0.05, 0.22))
            bowl_R = float(rng.uniform(0.70, 0.95))
            bowl_CC = float(rng.uniform(0.08, 0.32))
            _cv2.circle(M,  (cx, cy), r_inner, bowl_M, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R_ch, (cx, cy), r_inner, bowl_R, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r_inner, bowl_CC, -1, lineType=_cv2.LINE_AA)
            # per-crater ejecta ray bundle 4-8 hairs
            n_ray = int(rng.integers(4, 9))
            base_ang = float(rng.uniform(0, 2 * np.pi))
            for ri in range(n_ray):
                ang = base_ang + ri * (2 * np.pi / n_ray) + float(rng.uniform(-0.18, 0.18))
                length = float(rng.uniform(8.0, 16.0) * scale)
                x2 = int(np.clip(cx + np.cos(ang) * length, 0, w - 1))
                y2 = int(np.clip(cy + np.sin(ang) * length, 0, h - 1))
                _cv2.line(M,  (cx, cy), (x2, y2), float(rng.uniform(0.40, 0.82)), 1, lineType=_cv2.LINE_AA)
                _cv2.line(R_ch, (cx, cy), (x2, y2), float(rng.uniform(0.20, 0.55)), 1, lineType=_cv2.LINE_AA)

        # 3) SHADOW PITS â€” 1-3 px dim micro-impacts (5x)
        n_pit = int(np.clip(3000 * (mn / 2048.0) ** 2, 1000, 12000))
        for _ in range(n_pit):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            r = max(1, int(rng.uniform(0.8, 1.8) * scale))
            _cv2.circle(M,  (cx, cy), r, float(rng.uniform(0.05, 0.20)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r, float(rng.uniform(0.05, 0.22)), -1, lineType=_cv2.LINE_AA)

    # 4) EMBER SPARKLES â€” vectorized 1-px bright points
    n_em = int(np.clip(3500 * (mn / 2048.0) ** 2, 1200, 14000))
    ex = rng.integers(0, w, n_em); ey = rng.integers(0, h, n_em)
    M[ey, ex]  = np.maximum(M[ey, ex],  rng.uniform(0.60, 0.97, n_em).astype(np.float32))
    CC[ey, ex] = np.maximum(CC[ey, ex], rng.uniform(0.50, 0.93, n_em).astype(np.float32))

    # 5) ASH FLECKS â€” small dark dust between craters
    n_ash = int(np.clip(2500 * (mn / 2048.0) ** 2, 900, 10000))
    ax = rng.integers(0, w, n_ash); ay = rng.integers(0, h, n_ash)
    R_ch[ay, ax] = np.maximum(R_ch[ay, ax], rng.uniform(0.70, 0.95, n_ash).astype(np.float32))

    out = np.stack([M, R_ch, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
meteor_impact._spb_concept_complete = True


# ============================================================================
# 45. FUNGAL_NETWORK â€” mycelium interconnected threads
# ============================================================================

def fungal_network(shape, seed, sm, num_hyphae=60, **kwargs):
    """fungal_network.

    identity (R6 creative rebuild): a living petri-dish mycelium colony at high
    magnification â€” the SIGNATURE differentiator is multi-scale organization:
    bright RHIZOMORPH BUNDLE HIGHWAYS (thicker mycelial trunk lines) connect
    DISTINCT COLONY HUBS scattered across the canvas, with finer hyphal fans
    radiating from each hub. Layers stacked: (1) creamy agar substrate with
    independent M/R/CC and very low-freq colony-density wash, (2) RHIZOMORPH
    BUNDLES â€” 5-9 hub-to-hub bright 2-px polylines giving the colony a graph
    structure (NEW), (3) per-hub HYPHAL FAN walkers (radiate out 10-18 steps),
    (4) ambient hyphal walkers covering the rest of canvas, (5) SCLEROTIA
    BALLS â€” dense bright 4-7 px nodules at major hubs (NEW), (6) spore-bulb
    fork pinpoints, (7) dark nutrient pockets, (8) airborne SPORE CLOUDS
    (oblong 4-8 px soft halos, NEW), (9) continuous spore-dust haze. Per-feature
    INDEPENDENT continuous M/R/CC.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 45227)
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)

    # 1) AGAR SUBSTRATE â€” independent + colony-density wash
    bM = _normalize(multi_scale_noise(shape, [1.8, 5.0, 14.0], [0.5, 0.3, 0.2], int(seed) + 45231))
    bR = _normalize(multi_scale_noise(shape, [1.8, 5.0, 14.0], [0.5, 0.3, 0.2], int(seed) + 45233))
    bC = _normalize(multi_scale_noise(shape, [1.8, 5.0, 14.0], [0.5, 0.3, 0.2], int(seed) + 45235))
    density_wash = _normalize(multi_scale_noise(shape, [0.9, 2.2], [0.65, 0.35], int(seed) + 45240))
    M = (0.22 + (bM - 0.5) * 0.18 + (density_wash - 0.5) * 0.06).astype(np.float32)
    R = (0.62 + (bR - 0.5) * 0.22 - (density_wash - 0.5) * 0.06).astype(np.float32)
    CC = (0.55 + (bC - 0.5) * 0.22 - (density_wash - 0.5) * 0.05).astype(np.float32)

    # Pick 6-10 colony hubs distributed across canvas
    n_hubs = int(rng.integers(6, 11))
    hubs = []
    for _ in range(n_hubs):
        hubs.append((float(rng.uniform(0.08, 0.92) * w), float(rng.uniform(0.08, 0.92) * h)))

    fork_points = []
    if _CV2_OK:
        # 2) RHIZOMORPH BUNDLES â€” connect each hub to its 1-2 nearest neighbours
        for i, (hx, hy) in enumerate(hubs):
            # find nearest 2 hubs
            dists = [((hubs[j][0] - hx) ** 2 + (hubs[j][1] - hy) ** 2, j) for j in range(len(hubs)) if j != i]
            dists.sort()
            for _, j in dists[:2]:
                tx, ty = hubs[j]
                # walk a wobbly polyline between (hx,hy) and (tx,ty)
                steps = 14
                px, py = hx, hy
                for k in range(1, steps + 1):
                    f = k / steps
                    nx = (1 - f) * hx + f * tx + float(rng.normal(0, mn * 0.012))
                    ny = (1 - f) * hy + f * ty + float(rng.normal(0, mn * 0.012))
                    nx = float(np.clip(nx, 0, w - 1)); ny = float(np.clip(ny, 0, h - 1))
                    thick = 2 if rng.random() < 0.55 else 1
                    _cv2.line(M, (int(px), int(py)), (int(nx), int(ny)), float(rng.uniform(0.62, 0.92)), thick, lineType=_cv2.LINE_AA)
                    _cv2.line(R, (int(px), int(py)), (int(nx), int(ny)), float(rng.uniform(0.10, 0.32)), thick, lineType=_cv2.LINE_AA)
                    _cv2.line(CC, (int(px), int(py)), (int(nx), int(ny)), float(rng.uniform(0.14, 0.38)), thick, lineType=_cv2.LINE_AA)
                    px, py = nx, ny

        # 3) PER-HUB HYPHAL FAN WALKERS â€” radiate outward
        step_len = max(1.5, 1.8 * scale)
        for hx, hy in hubs:
            n_fan = int(np.clip(40 * (mn / 2048.0) ** 2, 14, 80))
            for _ in range(n_fan):
                ang = float(rng.uniform(0, 2 * np.pi))
                cx = hx + float(rng.uniform(0, mn * 0.05)) * np.cos(ang)
                cy = hy + float(rng.uniform(0, mn * 0.05)) * np.sin(ang)
                n_steps = int(rng.integers(10, 19))
                mv = float(rng.uniform(0.40, 0.80))
                rv = float(rng.uniform(0.18, 0.50))
                cv = float(rng.uniform(0.20, 0.55))
                stack = [(cx, cy, ang, n_steps)]
                while stack:
                    sx, sy, sang, rem = stack.pop()
                    if rem <= 0: continue
                    sang = sang + float(rng.normal(0, 0.32))
                    x2 = sx + np.cos(sang) * step_len; y2 = sy + np.sin(sang) * step_len
                    if not (0 <= x2 < w and 0 <= y2 < h): continue
                    _cv2.line(M, (int(sx), int(sy)), (int(x2), int(y2)), mv, 1, lineType=_cv2.LINE_AA)
                    _cv2.line(R, (int(sx), int(sy)), (int(x2), int(y2)), rv, 1, lineType=_cv2.LINE_AA)
                    _cv2.line(CC, (int(sx), int(sy)), (int(x2), int(y2)), cv, 1, lineType=_cv2.LINE_AA)
                    if rng.random() < 0.28 and rem > 3:
                        fa = sang + float(rng.uniform(-1.0, 1.0))
                        stack.append((x2, y2, fa, rem - 2))
                        fork_points.append((int(x2), int(y2)))
                    stack.append((x2, y2, sang, rem - 1))

        # 4) AMBIENT HYPHAL WALKERS â€” fill remaining canvas
        n_amb = int(np.clip(280 * (mn / 2048.0) ** 2, 100, 800))
        for _ in range(n_amb):
            x = float(rng.uniform(0, w - 1)); y = float(rng.uniform(0, h - 1))
            ang = float(rng.uniform(0, 2 * np.pi))
            n_steps = int(rng.integers(6, 12))
            mv = float(rng.uniform(0.38, 0.74))
            rv = float(rng.uniform(0.20, 0.55))
            cv = float(rng.uniform(0.22, 0.58))
            for _ in range(n_steps):
                ang = ang + float(rng.normal(0, 0.35))
                x2 = x + np.cos(ang) * step_len; y2 = y + np.sin(ang) * step_len
                if not (0 <= x2 < w and 0 <= y2 < h): break
                _cv2.line(M, (int(x), int(y)), (int(x2), int(y2)), mv, 1, lineType=_cv2.LINE_AA)
                _cv2.line(R, (int(x), int(y)), (int(x2), int(y2)), rv, 1, lineType=_cv2.LINE_AA)
                _cv2.line(CC, (int(x), int(y)), (int(x2), int(y2)), cv, 1, lineType=_cv2.LINE_AA)
                x, y = x2, y2

        # 5) SCLEROTIA BALLS at major hubs â€” bright 4-7 px nodules (NEW)
        for hx, hy in hubs:
            n_s = int(rng.integers(4, 9))
            for _ in range(n_s):
                ox = int(np.clip(hx + float(rng.normal(0, mn * 0.025)), 0, w - 1))
                oy = int(np.clip(hy + float(rng.normal(0, mn * 0.025)), 0, h - 1))
                rr = max(2, int(rng.uniform(2.0, 3.5) * scale))
                _cv2.circle(M, (ox, oy), rr, float(rng.uniform(0.72, 0.96)), -1, lineType=_cv2.LINE_AA)
                _cv2.circle(R, (ox, oy), rr, float(rng.uniform(0.08, 0.26)), -1, lineType=_cv2.LINE_AA)
                _cv2.circle(CC, (ox, oy), rr, float(rng.uniform(0.10, 0.30)), -1, lineType=_cv2.LINE_AA)

        # 6) SPORE-BULB FORK PINPOINTS
        if fork_points:
            for px_p, py_p in fork_points[:min(len(fork_points), 8000)]:
                r = max(1, int(rng.uniform(1.0, 2.0) * scale))
                _cv2.circle(M, (px_p, py_p), r, float(rng.uniform(0.62, 0.92)), -1, lineType=_cv2.LINE_AA)
                _cv2.circle(R, (px_p, py_p), r, float(rng.uniform(0.10, 0.30)), -1, lineType=_cv2.LINE_AA)

        # 7) NUTRIENT POCKETS â€” darker patches 3-6 px
        n_pock = int(np.clip(1400 * (mn / 2048.0) ** 2, 480, 3200))
        for _ in range(n_pock):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            r = max(2, int(rng.uniform(2.0, 4.0) * scale))
            _cv2.circle(M, (cx, cy), r, float(rng.uniform(0.06, 0.22)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r, float(rng.uniform(0.70, 0.95)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r, float(rng.uniform(0.70, 0.92)), -1, lineType=_cv2.LINE_AA)

        # 8) AIRBORNE SPORE CLOUDS â€” oblong soft 4-8 px halos (NEW)
        n_cloud = int(np.clip(380 * (mn / 2048.0) ** 2, 130, 1200))
        for _ in range(n_cloud):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            ax = max(2, int(rng.uniform(2.0, 4.0) * scale))
            ay = max(1, int(rng.uniform(1.2, 2.5) * scale))
            ang_e = float(rng.uniform(0, np.pi))
            _cv2.ellipse(M, (cx, cy), (ax, ay), float(np.degrees(ang_e)), 0, 360, float(rng.uniform(0.40, 0.72)), -1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(R, (cx, cy), (ax, ay), float(np.degrees(ang_e)), 0, 360, float(rng.uniform(0.22, 0.50)), -1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(CC, (cx, cy), (ax, ay), float(np.degrees(ang_e)), 0, 360, float(rng.uniform(0.30, 0.62)), -1, lineType=_cv2.LINE_AA)

    # 9) SPORE-DUST HAZE â€” vectorized denser
    n_fl = max(7000, int(h * w / 14))
    fy = rng.integers(0, h, n_fl); fx = rng.integers(0, w, n_fl)
    M[fy, fx] = np.maximum(M[fy, fx], rng.uniform(0.40, 0.85, n_fl).astype(np.float32))
    R[fy, fx] = np.minimum(R[fy, fx], rng.uniform(0.15, 0.45, n_fl).astype(np.float32))
    CC[fy, fx] = np.minimum(CC[fy, fx], rng.uniform(0.15, 0.45, n_fl).astype(np.float32))

    out = np.stack([M, R, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)

fungal_network._spb_concept_complete = True


# ============================================================================
# 46. GRAVITY_WELL â€” spacetime distortion around singularity
# ============================================================================

def gravity_well(shape, seed, sm, num_wells=2, **kwargs):
    """gravity_well.

    identity: R6-creative â€” a full-canvas EINSTEIN-LENS field. Hero motif is
    a scattering of mini black-hole singularities, each ringed by an actual
    bright EINSTEIN RING (5-12 px) PLUS a fainter outer photon ring (8-18
    px). Between the lenses, the spacetime fabric BENDS visibly via short
    curved tangent arcs (4-10 px) tracing geodesic deflection. Hero adds:
    (a) ACCRETION-DISC chord-streaks fanning from each singularity (3-9 px
    radial spokes), (b) GRAVITATIONAL-LENSED twin/triplet star images (1 px
    bright pairs across each lens), (c) Hawking-radiation sparkle carpet,
    (d) dark cold-spot voids between wells. Per-feature INDEPENDENT
    continuous M/R/CC uniforms across wide ranges. Fine 1-18 px features,
    full canvas coverage, CMB-dark substrate.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 33170)
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)

    # 1) CMB-dark substrate â€” INDEPENDENT per-channel multi-octave FBM
    g_M = _normalize(multi_scale_noise(shape, [1.5, 4.0, 10.0, 22.0], [0.42, 0.30, 0.18, 0.10], int(seed) + 215))
    g_R = _normalize(multi_scale_noise(shape, [1.8, 4.5, 11.0, 24.0], [0.40, 0.30, 0.20, 0.10], int(seed) + 217))
    g_CC = _normalize(multi_scale_noise(shape, [2.0, 5.0, 12.0, 26.0], [0.40, 0.30, 0.20, 0.10], int(seed) + 219))
    M = (0.18 + (g_M - 0.5) * 0.16).astype(np.float32)
    R = (0.68 + (g_R - 0.5) * 0.22).astype(np.float32)
    CC = (0.46 + (g_CC - 0.5) * 0.24).astype(np.float32)

    if _CV2_OK:
        # 2) HERO EINSTEIN-LENS WELLS â€” full canvas, dense, with twin-image stars
        n_wells = int(np.clip(1100 * (mn / 2048.0) ** 2, 380, 3600))
        well_pts = []
        for _ in range(n_wells):
            cx = int(rng.integers(2, max(3, w - 2)))
            cy = int(rng.integers(2, max(3, h - 2)))
            r_ein = max(3, int(rng.uniform(5.0, 12.0) * scale))
            # Bright Einstein ring
            _cv2.circle(M, (cx, cy), r_ein, float(rng.uniform(0.68, 0.99)), 1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r_ein, float(rng.uniform(0.06, 0.28)), 1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r_ein, float(rng.uniform(0.04, 0.30)), 1, lineType=_cv2.LINE_AA)
            # Outer fainter photon ring
            r_ph = r_ein + int(rng.uniform(2.0, 6.0) * scale)
            if r_ph < min(h, w) // 2:
                _cv2.circle(M, (cx, cy), r_ph, float(rng.uniform(0.32, 0.62)), 1, lineType=_cv2.LINE_AA)
                _cv2.circle(R, (cx, cy), r_ph, float(rng.uniform(0.20, 0.55)), 1, lineType=_cv2.LINE_AA)
                _cv2.circle(CC, (cx, cy), r_ph, float(rng.uniform(0.18, 0.55)), 1, lineType=_cv2.LINE_AA)
            # Singularity dark core â€” gravitational void
            _cv2.circle(M, (cx, cy), max(1, r_ein // 4), float(rng.uniform(0.04, 0.18)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), max(1, r_ein // 4), float(rng.uniform(0.55, 0.92)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), max(1, r_ein // 4), float(rng.uniform(0.45, 0.85)), -1, lineType=_cv2.LINE_AA)
            # TWIN-image lensed star pairs (1 px bright dots either side of the ring)
            ang_pair = float(rng.uniform(0, 2 * np.pi))
            for s in (-1, 1):
                px = int(np.clip(cx + np.cos(ang_pair) * r_ein * s, 0, w - 1))
                py = int(np.clip(cy + np.sin(ang_pair) * r_ein * s, 0, h - 1))
                M[py, px] = float(rng.uniform(0.78, 0.99))
                R[py, px] = float(rng.uniform(0.04, 0.18))
                CC[py, px] = float(rng.uniform(0.03, 0.15))
            well_pts.append((cx, cy, r_ein))

        # 3) ACCRETION-DISC radial spokes fanning from a subset of wells
        for (cx, cy, r_ein) in well_pts[: min(len(well_pts), 1400)]:
            n_spk = int(rng.integers(3, 8))
            base = float(rng.uniform(0, 2 * np.pi))
            for k in range(n_spk):
                ang = base + k * (2 * np.pi / n_spk) + float(rng.uniform(-0.18, 0.18))
                ln = float(rng.uniform(3.0, 9.0) * scale)
                x0 = int(np.clip(cx + np.cos(ang) * (r_ein + 1), 0, w - 1))
                y0 = int(np.clip(cy + np.sin(ang) * (r_ein + 1), 0, h - 1))
                x1 = int(np.clip(cx + np.cos(ang) * (r_ein + 1 + ln), 0, w - 1))
                y1 = int(np.clip(cy + np.sin(ang) * (r_ein + 1 + ln), 0, h - 1))
                _cv2.line(M, (x0, y0), (x1, y1), float(rng.uniform(0.55, 0.95)), 1, lineType=_cv2.LINE_AA)
                _cv2.line(R, (x0, y0), (x1, y1), float(rng.uniform(0.08, 0.32)), 1, lineType=_cv2.LINE_AA)
                _cv2.line(CC, (x0, y0), (x1, y1), float(rng.uniform(0.06, 0.30)), 1, lineType=_cv2.LINE_AA)

        # 4) GEODESIC bend arcs â€” short curved tangents between wells (4-10 px)
        n_geo = int(np.clip(2400 * (mn / 2048.0) ** 2, 800, 6000))
        for _ in range(n_geo):
            cx = int(rng.integers(4, max(5, w - 4)))
            cy = int(rng.integers(4, max(5, h - 4)))
            r = max(2, int(rng.uniform(4.0, 10.0) * scale))
            a0 = float(rng.uniform(0, 360)); a1 = a0 + float(rng.uniform(25, 85))
            _cv2.ellipse(M, (cx, cy), (r, r), 0, a0, a1, float(rng.uniform(0.42, 0.82)), 1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(R, (cx, cy), (r, r), 0, a0, a1, float(rng.uniform(0.14, 0.46)), 1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(CC, (cx, cy), (r, r), 0, a0, a1, float(rng.uniform(0.08, 0.38)), 1, lineType=_cv2.LINE_AA)

        # 5) DARK COLD-SPOT VOIDS â€” gravitational lensing dark spots (3-7 px)
        n_void = int(np.clip(900 * (mn / 2048.0) ** 2, 320, 2400))
        for _ in range(n_void):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            r = max(1, int(rng.uniform(2.0, 5.0) * scale))
            _cv2.circle(M, (cx, cy), r, float(rng.uniform(0.04, 0.14)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r, float(rng.uniform(0.72, 0.96)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r, float(rng.uniform(0.60, 0.92)), -1, lineType=_cv2.LINE_AA)

    # 6) HAWKING-radiation sparkle carpet â€” independent per-fleck uniforms
    n_st = max(3200, int(h * w / 900))
    sy = rng.integers(0, h, n_st); sx = rng.integers(0, w, n_st)
    M[sy, sx] = rng.uniform(0.55, 0.99, n_st).astype(np.float32)
    R[sy, sx] = rng.uniform(0.04, 0.24, n_st).astype(np.float32)
    CC[sy, sx] = rng.uniform(0.03, 0.22, n_st).astype(np.float32)

    # 7) Dim background micro-stars (independent darker chroma)
    n_dim = max(2200, int(h * w / 1300))
    dy = rng.integers(0, h, n_dim); dx = rng.integers(0, w, n_dim)
    M[dy, dx] = np.maximum(M[dy, dx], rng.uniform(0.30, 0.58, n_dim).astype(np.float32))
    CC[dy, dx] = np.minimum(CC[dy, dx], rng.uniform(0.20, 0.50, n_dim).astype(np.float32))

    # 8) HERO+ TIME-DILATION CLOCK FACES (Tick49 second-pass) â€” concentric
    # warped arc-clusters at random spots: 3-5 px nested partial arcs evoking
    # spacetime clocks ticking slower near each well. Each cluster spans
    # ~12-24 px with 3-5 nested arcs at varied start/end angles. Independent
    # per-arc M/R/CC continuous uniforms across wide chroma.
    if _CV2_OK:
        n_clock = int(np.clip(140 * (mn / 2048.0) ** 2, 36, 360))
        for _ in range(n_clock):
            cx = int(rng.integers(8, max(9, w - 8)))
            cy = int(rng.integers(8, max(9, h - 8)))
            n_nest = int(rng.integers(3, 6))
            base_ang = float(rng.uniform(0, 360.0))
            for ki in range(n_nest):
                rr = max(2, int((3 + ki * 2) * scale))
                if rr > 12:
                    break
                a0 = base_ang + float(rng.uniform(-30, 30))
                a1 = a0 + float(rng.uniform(60, 260))
                _cv2.ellipse(M, (cx, cy), (rr, rr), 0.0, a0, a1,
                             float(rng.uniform(0.50, 0.97)), 1, lineType=_cv2.LINE_AA)
                _cv2.ellipse(R, (cx, cy), (rr, rr), 0.0, a0, a1,
                             float(rng.uniform(0.08, 0.42)), 1, lineType=_cv2.LINE_AA)
                _cv2.ellipse(CC, (cx, cy), (rr, rr), 0.0, a0, a1,
                             float(rng.uniform(0.10, 0.58)), 1, lineType=_cv2.LINE_AA)
            # tiny hot pivot
            _cv2.circle(M, (cx, cy), 1, float(rng.uniform(0.75, 0.99)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), 1, float(rng.uniform(0.02, 0.18)), -1, lineType=_cv2.LINE_AA)

    out = np.stack([np.clip(M, 0, 1), np.clip(R, 0, 1), np.clip(CC, 0, 1)], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
gravity_well._spb_concept_complete = True


# ============================================================================
# 47. SONIC_BOOM â€” Mach cone shockwave propagation
# ============================================================================

def sonic_boom(shape, seed=0, sm=1.0, **kwargs):
    """sonic_boom.

    identity: Round-6 creative rebuild â€” captures the instant a supersonic
    object punches the air. HERO MOTIF: a single dominant Prandtl-Glauert
    condensation cone arc (16-26 px thick gradient front) sweeping across
    the panel from an apex, drawn as a stacked ring of dense bright
    primitives. Behind/around it: (a) twin tight wave-train rings carry
    the compression substrate, (b) Mach-cone fan hairlines (10-24 px)
    streaming from apex in a wedge, (c) dense vapor-cone bead carpet
    (3-8 px) saturating the cone interior, (d) trailing shock-tail flecks
    fading rearward, (e) bright pinpoint LEADING-EDGE sparks on the cone
    crest. Per-feature INDEPENDENT continuous M/R/CC uniforms. Wide chroma
    spread to make the cone read as ICE-COLD water vapor against a hotter
    rarified substrate.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 56191)
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)
    # Apex offset to one edge; cone fires forward
    cx_c = w * float(rng.uniform(0.05, 0.30))
    cy_c = h * float(rng.uniform(0.30, 0.70))
    primary_ang = float(rng.uniform(-0.35, 0.35))  # cone aim ~rightward
    cone_half = float(rng.uniform(0.55, 0.85))  # half-angle radians

    yy = np.arange(h, dtype=np.float32)[:, None]
    xx = np.arange(w, dtype=np.float32)[None, :]
    dx = xx - cx_c; dy = yy - cy_c
    rr_ = np.sqrt(dx * dx + dy * dy)
    theta = np.arctan2(dy, dx)
    # Cone mask â€” points within half-angle of primary direction
    ang_diff = np.abs(((theta - primary_ang + np.pi) % (2 * np.pi)) - np.pi)
    cone_mask = np.clip(1.0 - (ang_diff / cone_half), 0.0, 1.0).astype(np.float32)
    cone_mask = cone_mask ** 1.3

    # 1) Twin wave-train substrate â€” INDEPENDENT FBM per channel
    period = max(11.0, 14.0 * scale)
    ringA = (np.sin(rr_ * (2.0 * np.pi / period) + seed * 0.013) * 0.5 + 0.5).astype(np.float32)
    ringB = (np.sin(rr_ * (2.0 * np.pi / max(6.0, period * 0.5)) + seed * 0.029) * 0.5 + 0.5).astype(np.float32)
    g1 = _normalize(multi_scale_noise(shape, [2.5, 6.5, 14.0, 22.0], [0.36, 0.30, 0.22, 0.12], int(seed) + 6011))
    g2 = _normalize(multi_scale_noise(shape, [3.0, 7.5, 15.0, 24.0], [0.34, 0.30, 0.22, 0.14], int(seed) + 6013))
    g3 = _normalize(multi_scale_noise(shape, [3.5, 8.0, 16.0, 25.0], [0.34, 0.30, 0.22, 0.14], int(seed) + 6017))
    M = (0.36 + (g1 - 0.5) * 0.22 + (ringA - 0.5) * 0.18 + (ringB - 0.5) * 0.08).astype(np.float32)
    R = (0.58 + (g2 - 0.5) * 0.26 - (ringA - 0.5) * 0.22).astype(np.float32)
    CC = (0.36 + (g3 - 0.5) * 0.22 + (ringA - 0.5) * 0.18).astype(np.float32)

    # 2) HERO CONDENSATION CONE FRONT â€” sweep arc primitives
    if _CV2_OK:
        # Place the cone "wall" along an arc at radius r_front
        r_front = float(np.hypot(w, h)) * float(rng.uniform(0.28, 0.55))
        front_thick = max(8.0, 18.0 * scale)
        n_front = int(np.clip(2400 * (mn / 2048.0) ** 2, 800, 6000))
        for _ in range(n_front):
            # Sample angle within cone half-angle
            ang = primary_ang + float(rng.uniform(-cone_half * 0.95, cone_half * 0.95))
            r0 = r_front + float(rng.uniform(-front_thick, front_thick))
            px = int(np.clip(cx_c + np.cos(ang) * r0, 0, w - 1))
            py = int(np.clip(cy_c + np.sin(ang) * r0, 0, h - 1))
            rad = max(2, int(rng.uniform(3.0, 7.0) * scale))
            _cv2.circle(M, (px, py), rad, float(rng.uniform(0.55, 0.96)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (px, py), rad, float(rng.uniform(0.05, 0.26)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (px, py), rad, float(rng.uniform(0.06, 0.30)), -1, lineType=_cv2.LINE_AA)

        # 3) COMPRESSION ARC SEGMENTS â€” tangent to ring radii
        n_arc = int(np.clip(3000 * (mn / 2048.0) ** 2, 1100, 7500))
        for _ in range(n_arc):
            cx = int(rng.integers(2, w - 2)); cy = int(rng.integers(2, h - 2))
            arc_r = int(max(3, rng.uniform(5, 14) * scale * 0.55))
            tan_a = float(np.degrees(np.arctan2(cy - cy_c, cx - cx_c))) - 90.0 + float(rng.uniform(-22, 22))
            span = float(rng.uniform(24, 88))
            _cv2.ellipse(M, (cx, cy), (arc_r, arc_r), 0, tan_a, tan_a + span, float(rng.uniform(0.48, 0.94)), 1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(R, (cx, cy), (arc_r, arc_r), 0, tan_a, tan_a + span, float(rng.uniform(0.06, 0.32)), 1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(CC, (cx, cy), (arc_r, arc_r), 0, tan_a, tan_a + span, float(rng.uniform(0.05, 0.28)), 1, lineType=_cv2.LINE_AA)

        # 4) MACH-CONE FAN HAIRLINES â€” wedge from apex
        n_cone = int(np.clip(1400 * (mn / 2048.0) ** 2, 500, 3600))
        for _ in range(n_cone):
            ang = primary_ang + float(rng.uniform(-cone_half, cone_half))
            r0 = float(rng.uniform(0.05, 0.95)) * float(np.hypot(w, h)) * 0.5
            length = float(rng.uniform(10.0, 24.0) * scale)
            sx0 = int(np.clip(cx_c + np.cos(ang) * r0, 0, w - 1))
            sy0 = int(np.clip(cy_c + np.sin(ang) * r0, 0, h - 1))
            sx1 = int(np.clip(sx0 + np.cos(ang) * length, 0, w - 1))
            sy1 = int(np.clip(sy0 + np.sin(ang) * length, 0, h - 1))
            _cv2.line(M, (sx0, sy0), (sx1, sy1), float(rng.uniform(0.55, 0.93)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(R, (sx0, sy0), (sx1, sy1), float(rng.uniform(0.08, 0.32)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (sx0, sy0), (sx1, sy1), float(rng.uniform(0.05, 0.28)), 1, lineType=_cv2.LINE_AA)

        # 5) VAPOR-CONE BEADS â€” saturated inside cone (3-8 px)
        n_vap = int(np.clip(4500 * (mn / 2048.0) ** 2, 1500, 10000))
        for _ in range(n_vap):
            # Bias to within cone
            ang = primary_ang + float(rng.uniform(-cone_half, cone_half))
            r0 = float(rng.uniform(0.05, 1.05)) * float(np.hypot(w, h)) * 0.5
            cx = int(np.clip(cx_c + np.cos(ang) * r0, 0, w - 1))
            cy = int(np.clip(cy_c + np.sin(ang) * r0, 0, h - 1))
            r = max(2, int(rng.uniform(3, 8) * scale * 0.55))
            _cv2.circle(M, (cx, cy), r, float(rng.uniform(0.20, 0.62)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r, float(rng.uniform(0.48, 0.92)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r, float(rng.uniform(0.40, 0.88)), -1, lineType=_cv2.LINE_AA)

        # 6) LEADING-EDGE SPARK PINPOINTS â€” bright crest along cone front
        n_spark = int(np.clip(1400 * (mn / 2048.0) ** 2, 500, 3500))
        for _ in range(n_spark):
            ang = primary_ang + float(rng.uniform(-cone_half * 0.7, cone_half * 0.7))
            r0 = r_front + float(rng.uniform(-front_thick * 0.3, front_thick * 0.3))
            px = int(np.clip(cx_c + np.cos(ang) * r0, 0, w - 1))
            py = int(np.clip(cy_c + np.sin(ang) * r0, 0, h - 1))
            _cv2.circle(M, (px, py), 1, float(rng.uniform(0.75, 0.99)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (px, py), 1, float(rng.uniform(0.04, 0.16)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (px, py), 1, float(rng.uniform(0.04, 0.20)), -1, lineType=_cv2.LINE_AA)

    # 7) DEBRIS FLECK CARPET â€” full canvas
    n_fl = int(np.clip(6500 * (mn / 2048.0) ** 2, 2200, 15000))
    fx = rng.integers(0, w, n_fl); fy = rng.integers(0, h, n_fl)
    M[fy, fx] = rng.uniform(0.22, 0.95, n_fl).astype(np.float32)
    R[fy, fx] = rng.uniform(0.08, 0.88, n_fl).astype(np.float32)
    CC[fy, fx] = rng.uniform(0.06, 0.85, n_fl).astype(np.float32)

    out = np.stack([np.clip(M, 0, 1), np.clip(R, 0, 1), np.clip(CC, 0, 1)], axis=-1).astype(np.float32)
    return _sm_scale(out, sm)
sonic_boom._spb_concept_complete = True


# ============================================================================
# 48. CRYSTAL_GROWTH â€” dendritic crystal frost formation
# ============================================================================

def crystal_growth(shape, seed, sm, num_seeds_pts=4, growth_steps=200, **kwargs):
    """crystal_growth.

    identity: R6-CORRECTIVE for owner 'Boring / no character'. A jewel-box of
    GROWING CRYSTALS â€” multi-scale hero starbursts where each cluster picks
    its own iridescent gem chroma (frost-white, amethyst-violet, sapphire-
    cyan, ruby-warm, citrine-amber, etc.) so the field reads as a JEWELED
    surface, not a uniform frost. Stacked: (A) frost FBM substrate with
    independent per-channel swings; (B) 28-60 HERO 8-arm prism asterisks
    (14-26 px reach) with bright nucleus AND outer rim halo; (C) dense
    secondary 6-arm starbursts (6-12 px) carpeting between heroes; (D)
    per-arm dendrite SIDE-SPURS branching at +/-60deg; (E) ultrafine
    radial dendrite spurs filling residual gaps; (F) frost-needle dashes
    (3-7 px tiny line specks for substrate texture); (G) sapphire flecks
    (single-pixel bright with cyan-leaning chroma). Each starburst draws
    its own INDEPENDENT continuous M/R/CC uniform â€” no palette. Owner
    'fine features' law: heroes capped at 26 px, secondaries < 12 px.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 48911)
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)

    # A) BASE â€” frost FBM with independent per-channel noise
    fM = _normalize(multi_scale_noise(shape, [1.5, 4.0, 11.0, 28.0], [0.35, 0.30, 0.22, 0.13], int(seed) + 4922))
    fR = _normalize(multi_scale_noise(shape, [1.8, 4.5, 12.0, 30.0], [0.35, 0.30, 0.22, 0.13], int(seed) + 4923))
    fCC = _normalize(multi_scale_noise(shape, [1.6, 4.2, 11.5, 29.0], [0.35, 0.30, 0.22, 0.13], int(seed) + 4924))
    M = (0.40 + (fM - 0.5) * 0.36).astype(np.float32)
    R_ch = (0.48 + (fR - 0.5) * 0.34).astype(np.float32)
    CC = (0.46 + (fCC - 0.5) * 0.36).astype(np.float32)

    # Gem chroma palette index drawn per-cluster (still continuous-uniform within range)
    def _gem(rng_):
        # Returns (M_lo, M_hi, R_lo, R_hi, CC_lo, CC_hi) for a randomly chosen gem family
        gem = int(rng_.integers(0, 6))
        if gem == 0:  # frost-white
            return (0.65, 0.97, 0.04, 0.22, 0.20, 0.55)
        if gem == 1:  # amethyst-violet (high M+CC)
            return (0.55, 0.92, 0.06, 0.30, 0.60, 0.96)
        if gem == 2:  # sapphire-cyan
            return (0.50, 0.88, 0.05, 0.28, 0.65, 0.97)
        if gem == 3:  # ruby (warm, lower CC)
            return (0.58, 0.94, 0.10, 0.40, 0.10, 0.45)
        if gem == 4:  # citrine-amber
            return (0.50, 0.90, 0.18, 0.50, 0.30, 0.70)
        return (0.42, 0.82, 0.20, 0.55, 0.40, 0.85)  # smoky quartz

    if _CV2_OK:
        # B) HERO 8-arm PRISM ASTERISKS â€” large bright starbursts
        n_hero = int(np.clip(60 * (mn / 256.0) ** 0.7, 28, 240))
        for _ in range(n_hero):
            cx = int(rng.uniform(0.04, 0.96) * w); cy = int(rng.uniform(0.04, 0.96) * h)
            reach = float(rng.uniform(14.0, 26.0) * scale)
            base_ang = float(rng.uniform(0, np.pi / 4))
            Ml, Mh, Rl, Rh, Cl, Ch = _gem(rng)
            vM  = float(rng.uniform(Ml, Mh))
            vR  = float(rng.uniform(Rl, Rh))
            vCC = float(rng.uniform(Cl, Ch))
            for arm in range(8):
                ang = base_ang + arm * np.pi / 4
                ex = int(np.clip(cx + np.cos(ang) * reach, 0, w - 1))
                ey = int(np.clip(cy + np.sin(ang) * reach, 0, h - 1))
                _cv2.line(M,    (cx, cy), (ex, ey), vM,  1, lineType=_cv2.LINE_AA)
                _cv2.line(R_ch, (cx, cy), (ex, ey), vR,  1, lineType=_cv2.LINE_AA)
                _cv2.line(CC,   (cx, cy), (ex, ey), vCC, 1, lineType=_cv2.LINE_AA)
                # D) dendrite side-spurs at mid-arm
                if rng.random() < 0.70:
                    mx = cx + np.cos(ang) * reach * 0.55
                    my = cy + np.sin(ang) * reach * 0.55
                    side = float(rng.choice([1.0, -1.0]))
                    side_ang = ang + side * np.pi / 3
                    sx = int(np.clip(mx + np.cos(side_ang) * reach * 0.35, 0, w - 1))
                    sy = int(np.clip(my + np.sin(side_ang) * reach * 0.35, 0, h - 1))
                    _cv2.line(M,    (int(mx), int(my)), (sx, sy), float(vM  * 0.88), 1, lineType=_cv2.LINE_AA)
                    _cv2.line(CC,   (int(mx), int(my)), (sx, sy), float(vCC * 0.92), 1, lineType=_cv2.LINE_AA)
            # Outer halo ring (thin)
            r_halo = max(3, int(reach * 0.95))
            _cv2.circle(M,  (cx, cy), r_halo, float(min(1.0, vM  + 0.05)), 1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r_halo, float(min(1.0, vCC + 0.05)), 1, lineType=_cv2.LINE_AA)
            # Bright nucleus
            r_nuc = max(2, int(reach * 0.18))
            _cv2.circle(M,    (cx, cy), r_nuc, float(min(1.0, vM  + 0.08)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R_ch, (cx, cy), r_nuc, float(max(0.0, vR  - 0.05)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC,   (cx, cy), r_nuc, vCC, -1, lineType=_cv2.LINE_AA)

        # C) SECONDARY 6-ARM STARBURSTS â€” dense carpet 6-12 px
        n_sec = int(np.clip(1200 * (mn / 2048.0) ** 2, 420, 3200))
        for _ in range(n_sec):
            cx = int(rng.uniform(0.02, 0.98) * w); cy = int(rng.uniform(0.02, 0.98) * h)
            reach = float(rng.uniform(6.0, 12.0) * scale)
            base_ang = float(rng.uniform(0, np.pi / 3))
            Ml, Mh, Rl, Rh, Cl, Ch = _gem(rng)
            vM  = float(rng.uniform(Ml, Mh))
            vR  = float(rng.uniform(Rl, Rh))
            vCC = float(rng.uniform(Cl, Ch))
            for arm in range(6):
                ang = base_ang + arm * np.pi / 3
                ex = int(np.clip(cx + np.cos(ang) * reach, 0, w - 1))
                ey = int(np.clip(cy + np.sin(ang) * reach, 0, h - 1))
                _cv2.line(M,    (cx, cy), (ex, ey), vM,  1, lineType=_cv2.LINE_AA)
                _cv2.line(R_ch, (cx, cy), (ex, ey), vR,  1, lineType=_cv2.LINE_AA)
                _cv2.line(CC,   (cx, cy), (ex, ey), vCC, 1, lineType=_cv2.LINE_AA)
            # Tiny pip
            r0 = max(1, int(rng.uniform(1.0, 2.0) * scale))
            _cv2.circle(M,  (cx, cy), r0, float(min(1.0, vM + 0.06)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r0, float(min(1.0, vCC + 0.05)), -1, lineType=_cv2.LINE_AA)

        # E) ISOLATED FROST DENDRITE SPURS â€” short radial 4-10 px
        n_branches = int(np.clip(2400 * (mn / 2048.0) ** 2, 800, 6800))
        for _ in range(n_branches):
            cx = float(rng.uniform(0.02, 0.98) * w); cy = float(rng.uniform(0.02, 0.98) * h)
            length = float(rng.uniform(3.0, 8.0) * scale)
            ang = float(rng.uniform(0, 2 * np.pi))
            x2 = int(np.clip(cx + np.cos(ang) * length, 0, w - 1))
            y2 = int(np.clip(cy + np.sin(ang) * length, 0, h - 1))
            _cv2.line(M,    (int(cx), int(cy)), (x2, y2), float(rng.uniform(0.45, 0.92)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(R_ch, (int(cx), int(cy)), (x2, y2), float(rng.uniform(0.08, 0.42)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC,   (int(cx), int(cy)), (x2, y2), float(rng.uniform(0.20, 0.85)), 1, lineType=_cv2.LINE_AA)

        # F) FROST-NEEDLE DASHES â€” 3-7 px texture
        n_nd = int(np.clip(3200 * (mn / 2048.0) ** 2, 1100, 8500))
        for _ in range(n_nd):
            cxi = int(rng.uniform(0.02, 0.98) * w); cyi = int(rng.uniform(0.02, 0.98) * h)
            r = max(1, int(rng.uniform(1.0, 2.0) * scale))
            _cv2.circle(M,    (cxi, cyi), r, float(rng.uniform(0.55, 0.95)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R_ch, (cxi, cyi), r, float(rng.uniform(0.05, 0.30)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC,   (cxi, cyi), r, float(rng.uniform(0.30, 0.92)), -1, lineType=_cv2.LINE_AA)

    # G) SAPPHIRE FLECKS â€” bright single-pixel highlights with cyan-leaning chroma
    n_flecks = int(np.clip(2000 * (mn / 2048.0) ** 2, 700, 6000))
    fy2 = rng.integers(0, h, n_flecks); fx2 = rng.integers(0, w, n_flecks)
    M[fy2, fx2]    = np.maximum(M[fy2, fx2],    rng.uniform(0.60, 0.97, n_flecks).astype(np.float32))
    R_ch[fy2, fx2] = np.minimum(R_ch[fy2, fx2], rng.uniform(0.04, 0.26, n_flecks).astype(np.float32))
    CC[fy2, fx2]   = np.maximum(CC[fy2, fx2],   rng.uniform(0.50, 0.96, n_flecks).astype(np.float32))

    out = np.stack([M, R_ch, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
crystal_growth._spb_concept_complete = True


def smoke_tendril(shape, seed, sm, num_plumes=6, **kwargs):
    """smoke_tendril.

    identity: R6 CREATIVE â€” Curling vapor sourced from glowing ember
    heads. Each tendril chain now ROOTS at a bright HERO CIGAR-EMBER
    GLOW HEAD (4-8 px pulsing disc with halo corona) â€” the namesake
    "smoke-from-fire" story made explicit. Stacked:
      (1) Sooty per-channel FBM substrate (independent M/R/CC seeds).
      (2) Smoke-puff anchors (5-12 px soft ellipses) â€” per-puff M/R/CC
          uniforms span a wide chroma (white wisps, blue-grey wisps,
          brown wisps coexist).
      (3) CIGAR-EMBER GLOW HEADS (NEW HERO) â€” 4-8 px bright orange
          discs with 6-10 px corona, root of each major chain.
      (4) Curling tendril chains, finer segments (8-18 px, density 5x).
      (5) NEW: PAPER-FLAKE ASH FLOATERS â€” 3-6 px asymmetric quad
          flakes (rotated rectangles) drifting on currents.
      (6) Ember pinpricks (1-2 px bright burn-throughs).
      (7) Ash speck carpet â€” wide-range per-pixel jitter on all 3
          channels for ground-level chroma diversity.
    Fine 1-18 px features only â€” no macro. Per-feature INDEPENDENT
    continuous M/R/CC uniforms.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 50617)
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)
    s256 = max(mn / 256.0, 0.6)

    # 1) Sooty independent-channel FBM substrate
    sM = _normalize(multi_scale_noise((h, w), [3.5, 10.0, 26.0], [0.46, 0.30, 0.24], int(seed) + 5111))
    sR = _normalize(multi_scale_noise((h, w), [3.5, 11.0, 28.0], [0.46, 0.30, 0.24], int(seed) + 5113))
    sC = _normalize(multi_scale_noise((h, w), [4.0, 12.0, 30.0], [0.46, 0.30, 0.24], int(seed) + 5117))
    M = (0.28 + (sM - 0.5) * 0.24).astype(np.float32)
    R = (0.78 + (sR - 0.5) * 0.22).astype(np.float32)
    CC = (0.66 + (sC - 0.5) * 0.20).astype(np.float32)

    ember_centers = []

    if _CV2_OK:
        # 2) SMOKE-PUFF BLOBS â€” anchors (5-12 px) with wide chroma
        n_puff = int(np.clip(450 * (mn / 2048.0) ** 2, 160, 1200))
        puff_centers = []
        for _ in range(n_puff):
            cx = int(rng.uniform(0.02, 0.98) * w); cy = int(rng.uniform(0.05, 0.98) * h)
            rx = max(2, int(rng.uniform(4.0, 10.0) * scale * 0.5))
            ry = max(2, int(rx * float(rng.uniform(0.6, 1.0))))
            rot = float(rng.uniform(0, 180))
            pM = float(rng.uniform(0.18, 0.90))
            pR = float(rng.uniform(0.20, 0.78))
            pCC = float(rng.uniform(0.15, 0.78))
            _cv2.ellipse(M, (cx, cy), (rx, ry), rot, 0, 360, pM, -1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(R, (cx, cy), (rx, ry), rot, 0, 360, pR, -1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(CC, (cx, cy), (rx, ry), rot, 0, 360, pCC, -1, lineType=_cv2.LINE_AA)
            puff_centers.append((cx, cy))

        # 3) HERO â€” CIGAR-EMBER GLOW HEADS (4-8 px disc + halo)
        n_ember_head = int(np.clip(220 * s256 * s256, 60, 760))
        for _ in range(n_ember_head):
            cx = int(rng.uniform(0.04, 0.96) * w); cy = int(rng.uniform(0.06, 0.96) * h)
            r_core = max(2, int(rng.uniform(2.0, 4.0) * s256))
            r_halo = r_core + max(1, int(rng.uniform(2.0, 4.0) * s256))
            # ember core: very high M, very low R (glossy hot), low CC (visible glow)
            eM = float(rng.uniform(0.78, 0.99))
            eR = float(rng.uniform(0.04, 0.22))
            eCC = float(rng.uniform(0.04, 0.22))
            # corona halo: slightly cooler
            hM = float(rng.uniform(0.42, 0.78))
            hR = float(rng.uniform(0.18, 0.46))
            hCC = float(rng.uniform(0.12, 0.40))
            _cv2.circle(M, (cx, cy), r_halo, hM, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r_halo, hR, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r_halo, hCC, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(M, (cx, cy), r_core, eM, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r_core, eR, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r_core, eCC, -1, lineType=_cv2.LINE_AA)
            ember_centers.append((cx, cy))

        # 4) CURLING TENDRIL CHAINS â€” root at ember heads when possible
        n_chains = max(int(num_plumes), 6) * 28
        for ci in range(n_chains):
            roll = ci % 3
            if roll == 0 and ember_centers:
                px, py = ember_centers[int(rng.integers(0, len(ember_centers)))]
                cx, cy = float(px), float(py)
                # tendril rises from ember â€” bias initial angle upward
                ang = float(rng.uniform(-np.pi, 0))  # upper half
            elif roll == 1 and puff_centers:
                px, py = puff_centers[int(rng.integers(0, len(puff_centers)))]
                cx, cy = float(px), float(py)
                ang = float(rng.uniform(0, 2 * np.pi))
            else:
                cx = float(rng.uniform(0.02, 0.98) * w)
                cy = float(rng.uniform(0.05, 0.98) * h)
                ang = float(rng.uniform(0, 2 * np.pi))
            seg_count = int(rng.integers(4, 10))
            wM = float(rng.uniform(0.20, 0.92))
            wR = float(rng.uniform(0.08, 0.72))
            wC = float(rng.uniform(0.10, 0.78))
            for s in range(seg_count):
                length = float(rng.uniform(8.0, 18.0) * scale)
                ang += float(rng.uniform(-0.55, 0.55))
                nx = cx + np.cos(ang) * length
                ny = cy + np.sin(ang) * length
                p0 = (int(np.clip(cx, 0, w - 1)), int(np.clip(cy, 0, h - 1)))
                p1 = (int(np.clip(nx, 0, w - 1)), int(np.clip(ny, 0, h - 1)))
                thick = max(1, int(rng.uniform(1.0, 2.2) * scale))
                _cv2.line(M, p0, p1, wM, thick, lineType=_cv2.LINE_AA)
                _cv2.line(R, p0, p1, wR, thick, lineType=_cv2.LINE_AA)
                _cv2.line(CC, p0, p1, wC, thick, lineType=_cv2.LINE_AA)
                cx, cy = nx, ny
                if not (0 < cx < w and 0 < cy < h):
                    break

        # 5) NEW â€” PAPER-FLAKE ASH FLOATERS (3-6 px asymmetric rotated quads)
        n_flake = int(np.clip(900 * (mn / 2048.0) ** 2, 280, 3200))
        for _ in range(n_flake):
            cx = int(rng.uniform(0.02, 0.98) * w); cy = int(rng.uniform(0.02, 0.98) * h)
            fw = max(1, int(rng.uniform(2.0, 4.0) * s256))
            fh = max(1, int(rng.uniform(1.5, 3.0) * s256))
            rot = float(rng.uniform(0, 180))
            # ash flake: high R (dull), low-mid M, low CC (sooty crinkle)
            fM = float(rng.uniform(0.18, 0.55))
            fR = float(rng.uniform(0.65, 0.97))
            fCC = float(rng.uniform(0.18, 0.55))
            box = ((cx, cy), (fw, fh), rot)
            pts = _cv2.boxPoints(box).astype(np.int32)
            _cv2.fillPoly(M, [pts], fM, lineType=_cv2.LINE_AA)
            _cv2.fillPoly(R, [pts], fR, lineType=_cv2.LINE_AA)
            _cv2.fillPoly(CC, [pts], fCC, lineType=_cv2.LINE_AA)

        # 6) EMBER PINPRICKS (bright burns) â€” 5x
        n_ember = int(np.clip(2200 * (mn / 2048.0) ** 2, 650, 5800))
        for _ in range(n_ember):
            cx = int(rng.uniform(0, w)); cy = int(rng.uniform(0, h))
            r_e = max(1, int(rng.uniform(1.2, 2.6) * scale))
            _cv2.circle(M, (cx, cy), r_e, float(rng.uniform(0.74, 0.97)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r_e, float(rng.uniform(0.04, 0.20)), -1, lineType=_cv2.LINE_AA)

    # 7) ASH SPECK CARPET â€” wide-range jitter
    n_ash = int(np.clip(8500 * (mn / 2048.0) ** 2, 2300, 19000))
    ay = rng.integers(0, h, n_ash); ax = rng.integers(0, w, n_ash)
    R[ay, ax] = np.clip(R[ay, ax] + rng.uniform(-0.20, 0.30, n_ash).astype(np.float32), 0, 1)
    M[ay, ax] = np.clip(M[ay, ax] + rng.uniform(-0.18, 0.30, n_ash).astype(np.float32), 0, 1)
    CC[ay, ax] = np.clip(CC[ay, ax] + rng.uniform(-0.16, 0.28, n_ash).astype(np.float32), 0, 1)

    out = np.stack([M, R, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
smoke_tendril._spb_concept_complete = True

def fractal_discharge(shape, seed, sm, num_bolts=4, depth=8, **kwargs):
    """fractal_discharge â€” R6 CREATIVE rebuild.

    identity: LICHTENBERG DENDRITES â€” true recursive branching fractal trees
    densely packed across a charred substrate. Each dendrite has a root,
    splits into 2-3 child branches at 25-45 deg, each child splits again
    1-2 more levels â€” yielding feathery 8-22 px lightning fingerprints.
    Stacked: (1) charred-glass base FBM (low M, high R, mid CC), (2)
    population of ~140-380 dendrites (depth 3) per canvas, (3) bright
    1-2 px ion sparks pinpoint along each branch end, (4) faint glow
    halos (4-8 px translucent rings) at root nodes, (5) DARK SCORCH
    POCKETS (carbonized voids 2-4 px) between dendrites, (6) tiny salt-
    crystal ion flecks scattered. Per-dendrite + per-segment INDEPENDENT
    continuous M/R/CC. This is a FRACTAL signature â€” not a generic spark
    field.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 23119)
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)

    # 1) CHARRED GLASS BASE
    bM = _normalize(multi_scale_noise(shape, [2.5, 6.5, 15.0], [0.45, 0.32, 0.22], int(seed) + 23131))
    bR = _normalize(multi_scale_noise(shape, [2.8, 7.2, 16.0], [0.45, 0.32, 0.22], int(seed) + 23133))
    bC = _normalize(multi_scale_noise(shape, [3.0, 8.0, 17.0], [0.45, 0.32, 0.22], int(seed) + 23135))
    M = (0.18 + (bM - 0.5) * 0.16).astype(np.float32)   # dark
    R = (0.66 + (bR - 0.5) * 0.20).astype(np.float32)   # rough char
    CC = (0.48 + (bC - 0.5) * 0.20).astype(np.float32)

    # collect endpoints for sparks
    endpoints = []
    roots = []

    def _draw_branch(x0, y0, length, angle, depth_remaining, branch_M, branch_R, branch_CC):
        """Recursively draw a Lichtenberg branch."""
        x1f = x0 + np.cos(angle) * length
        y1f = y0 + np.sin(angle) * length
        x1 = int(np.clip(x1f, 0, w - 1))
        y1 = int(np.clip(y1f, 0, h - 1))
        # slight per-segment chroma jitter
        mv  = float(np.clip(branch_M + rng.uniform(-0.06, 0.06), 0.45, 0.99))
        rv  = float(np.clip(branch_R + rng.uniform(-0.04, 0.04), 0.04, 0.32))
        cv  = float(np.clip(branch_CC + rng.uniform(-0.04, 0.04), 0.04, 0.30))
        _cv2.line(M,  (int(x0), int(y0)), (x1, y1), mv, 1, lineType=_cv2.LINE_AA)
        _cv2.line(R,  (int(x0), int(y0)), (x1, y1), rv, 1, lineType=_cv2.LINE_AA)
        _cv2.line(CC, (int(x0), int(y0)), (x1, y1), cv, 1, lineType=_cv2.LINE_AA)

        if depth_remaining <= 0:
            endpoints.append((x1, y1))
            return
        n_kids = int(rng.integers(2, 4))  # 2 or 3 children
        for _ in range(n_kids):
            d_ang = float(rng.uniform(-0.78, 0.78))  # +/- 45 deg
            child_angle = angle + d_ang
            child_length = length * float(rng.uniform(0.45, 0.75))
            _draw_branch(x1f, y1f, child_length, child_angle,
                          depth_remaining - 1, branch_M, branch_R, branch_CC)

    if _CV2_OK:
        # 2) DENDRITE POPULATION
        n_dendrite = int(np.clip(280 * (mn / 2048.0) ** 2, 80, 750))
        for _ in range(n_dendrite):
            rx = float(rng.uniform(0.04, 0.96) * w)
            ry = float(rng.uniform(0.04, 0.96) * h)
            roots.append((int(rx), int(ry)))
            root_angle = float(rng.uniform(0, 2 * np.pi))
            root_length = float(rng.uniform(4.0, 7.0) * scale)
            br_M = float(rng.uniform(0.70, 0.97))
            br_R = float(rng.uniform(0.05, 0.18))
            br_CC = float(rng.uniform(0.05, 0.18))
            # initial 2-3 root arms
            n_arms = int(rng.integers(2, 4))
            for ai in range(n_arms):
                a = root_angle + ai * (2 * np.pi / n_arms) + float(rng.uniform(-0.25, 0.25))
                _draw_branch(rx, ry, root_length, a, 2, br_M, br_R, br_CC)

        # 3) ROOT HALOS â€” faint 4-8 px translucent rings
        for (rx, ry) in roots:
            rr = max(2, int(rng.uniform(3.0, 5.0) * scale))
            _cv2.circle(M,  (rx, ry), rr, float(rng.uniform(0.35, 0.70)), 1, lineType=_cv2.LINE_AA)
            _cv2.circle(R,  (rx, ry), rr, float(rng.uniform(0.20, 0.50)), 1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (rx, ry), rr, float(rng.uniform(0.18, 0.48)), 1, lineType=_cv2.LINE_AA)
            # hot pixel at root
            _cv2.circle(M, (rx, ry), 1, float(rng.uniform(0.85, 0.99)), -1, lineType=_cv2.LINE_AA)

        # 4) ION SPARKS AT BRANCH ENDPOINTS (1-2 px)
        for (ex, ey) in endpoints:
            if rng.random() < 0.55:
                _cv2.circle(M, (ex, ey), 1, float(rng.uniform(0.72, 0.99)), -1, lineType=_cv2.LINE_AA)
                if rng.random() < 0.35:
                    R[ey, ex]  = float(rng.uniform(0.05, 0.20))
                    CC[ey, ex] = float(rng.uniform(0.05, 0.22))

        # 5) DARK SCORCH POCKETS â€” 2-4 px
        n_soot = int(np.clip(900 * (mn / 2048.0) ** 2, 320, 2400))
        for _ in range(n_soot):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            rr = max(1, int(rng.uniform(1.5, 3.0) * scale))
            _cv2.circle(M, (cx, cy), rr, float(rng.uniform(0.04, 0.18)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), rr, float(rng.uniform(0.70, 0.94)), -1, lineType=_cv2.LINE_AA)

    # 6) SALT-CRYSTAL ION FLECKS
    n_fl = max(6000, int(h * w / 14))
    fy = rng.integers(0, h, n_fl); fx = rng.integers(0, w, n_fl)
    M[fy, fx] = np.maximum(M[fy, fx], rng.uniform(0.50, 0.95, n_fl).astype(np.float32))
    R[fy, fx] = np.minimum(R[fy, fx], rng.uniform(0.05, 0.24, n_fl).astype(np.float32))
    CC[fy, fx] = np.minimum(CC[fy, fx], rng.uniform(0.05, 0.26, n_fl).astype(np.float32))

    out = np.stack([np.clip(M, 0, 1), np.clip(R, 0, 1), np.clip(CC, 0, 1)], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)

fractal_discharge._spb_concept_complete = True


