def metallic_sand(shape, seed, sm, block_size=2, flow_angle=0.18):
    """metallic_sand.

    identity: R6 CREATIVE â€” Saturated ferromagnetic metallic sand bed
    with NEW HEROES: (1) MAGNETITE-RIDGE FERROFLUID SPIKES â€” 3-7 px
    star-spike clusters where ferrous grains gather under magnetic
    pull (cross-hatched bright spokes radiating from a dark core),
    and (2) GLINT CHAINS â€” linear arrays of 5-12 connected bright
    micro-discs along the drift axis evoking iron filings aligned
    to a field line. Stacked tiers:
      (i) Per-channel FBM substrate (independent M/R/CC seeds).
      (ii) Ultra-dense 1-px speckle carpet (wider chroma).
      (iii) 1-2 px micro-discs.
      (iv) 2-3 px medium grain.
      (v) Drift flow streaks 4-7 px.
      (vi) Bright accent clusters 3-5 px.
      (vii) HERO â€” FERROFLUID SPIKE STARS (4-pointed + 8-pointed mix).
      (viii) HERO â€” GLINT CHAINS (5-12 disc beads tightly spaced along
            flow axis with subtle angle jitter).
    Per-feature INDEPENDENT continuous M/R/CC uniforms.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 9217)
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)
    s256 = max(mn / 256.0, 0.6)

    def _fbm(off, sigma):
        if _CV2_OK:
            sh = max(64, h // 10); sw = max(64, w // 10)
            n = np.random.default_rng(int(seed) + off).random((sh, sw)).astype(np.float32)
            b = _cv2.GaussianBlur(n, (0, 0), sigmaX=sigma, sigmaY=sigma)
            return _normalize(_cv2.resize(b, (w, h), interpolation=_cv2.INTER_CUBIC).astype(np.float32))
        return _normalize(multi_scale_noise(shape, [20, 40], [0.6, 0.4], int(seed) + off))

    fM = _fbm(1501, 7.0); fR = _fbm(1503, 7.0); fCC = _fbm(1505, 7.0)
    M  = (0.42 + (fM  - 0.5) * 0.26).astype(np.float32)
    R  = (0.42 + (fR  - 0.5) * 0.22).astype(np.float32)
    CC = (0.40 + (fCC - 0.5) * 0.24).astype(np.float32)

    flow_ang = float(flow_angle) * np.pi + float(rng.uniform(-0.05, 0.05))

    if _CV2_OK:
        # Tier 1: ULTRA-DENSE 1 px speckle
        n1 = max(int(h * w / 12), 90000)
        ys = rng.integers(0, h, n1); xs = rng.integers(0, w, n1)
        M[ys, xs]  = np.maximum(M[ys, xs],  rng.uniform(0.45, 0.97, n1).astype(np.float32))
        R[ys, xs]  = np.minimum(R[ys, xs],  rng.uniform(0.05, 0.42, n1).astype(np.float32))
        CC[ys, xs] = np.maximum(CC[ys, xs], rng.uniform(0.38, 0.95, n1).astype(np.float32))

        # Tier 2: 1-2 px micro-discs (R6 trim for new rose-curve budget)
        n2 = max(int(h * w / 280), 4200)
        for _ in range(n2):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            rr = max(1, int(rng.uniform(1, 2) * scale))
            _cv2.circle(M,  (cx, cy), rr, float(rng.uniform(0.55, 0.97)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R,  (cx, cy), rr, float(rng.uniform(0.04, 0.28)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), rr, float(rng.uniform(0.50, 0.94)), -1, lineType=_cv2.LINE_AA)

        # Tier 3: 2-3 px medium grain (R6 trim for new rose-curve budget)
        n3 = max(int(h * w / 950), 1400)
        for _ in range(n3):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            rr = max(1, int(rng.uniform(2, 3) * scale))
            _cv2.circle(M,  (cx, cy), rr, float(rng.uniform(0.48, 0.94)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R,  (cx, cy), rr, float(rng.uniform(0.08, 0.38)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), rr, float(rng.uniform(0.38, 0.88)), -1, lineType=_cv2.LINE_AA)

        # Tier 4: Flow streaks 4-7 px along drift
        n_st = max(int(h * w / 450), 1200)
        for _ in range(n_st):
            x0 = int(rng.integers(0, w)); y0 = int(rng.integers(0, h))
            ll = int(rng.uniform(4, 7) * scale)
            x1 = int(x0 + np.cos(flow_ang) * ll); y1 = int(y0 + np.sin(flow_ang) * ll)
            _cv2.line(M,  (x0, y0), (x1, y1), float(rng.uniform(0.55, 0.96)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(R,  (x0, y0), (x1, y1), float(rng.uniform(0.06, 0.32)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (x0, y0), (x1, y1), float(rng.uniform(0.38, 0.92)), 1, lineType=_cv2.LINE_AA)

        # Tier 5: bright accent clusters 3-5 px
        n_c = max(int(h * w / 1400), 460)
        for _ in range(n_c):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            rr = max(2, int(rng.uniform(2, 4) * scale))
            _cv2.circle(M, (cx, cy), rr, float(rng.uniform(0.72, 0.99)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), rr, float(rng.uniform(0.04, 0.18)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), rr, float(rng.uniform(0.48, 0.96)), -1, lineType=_cv2.LINE_AA)

        # Tier 6 â€” HERO: FERROFLUID SPIKE STARS (3-7 px star spike clusters)
        # Slight R6 trim to make budget room for rose-curve rosettes.
        n_spike = int(np.clip(260 * s256 * s256, 70, 1200))
        for _ in range(n_spike):
            cx = int(rng.uniform(0.02, 0.98) * w); cy = int(rng.uniform(0.02, 0.98) * h)
            r_sp = max(2, int(rng.uniform(2.0, 4.0) * s256))
            # dark core (gathered magnetite)
            coreM = float(rng.uniform(0.62, 0.96))
            coreR = float(rng.uniform(0.25, 0.55))
            coreCC = float(rng.uniform(0.08, 0.42))
            _cv2.circle(M, (cx, cy), max(1, r_sp - 1), coreM, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), max(1, r_sp - 1), coreR, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), max(1, r_sp - 1), coreCC, -1, lineType=_cv2.LINE_AA)
            # spokes â€” 4 or 8 spike arms
            n_arm = 8 if rng.random() < 0.4 else 4
            base_rot = float(rng.uniform(0, np.pi))
            for k in range(n_arm):
                ang = base_rot + (np.pi * 2 / n_arm) * k
                spike_len = float(rng.uniform(r_sp + 1, r_sp + 4))
                x1 = int(cx + np.cos(ang) * spike_len)
                y1 = int(cy + np.sin(ang) * spike_len)
                spM = float(rng.uniform(0.78, 0.99))
                spR = float(rng.uniform(0.04, 0.20))
                spCC = float(rng.uniform(0.55, 0.96))
                _cv2.line(M, (cx, cy), (x1, y1), spM, 1, lineType=_cv2.LINE_AA)
                _cv2.line(R, (cx, cy), (x1, y1), spR, 1, lineType=_cv2.LINE_AA)
                _cv2.line(CC, (cx, cy), (x1, y1), spCC, 1, lineType=_cv2.LINE_AA)

        # Tier 7 â€” HERO: GLINT CHAINS (5-12 micro-discs aligned to flow axis)
        # Density trimmed (R6-CREATIVE) so rose-curve rosettes below fit
        # the 200 ms budget; still dense at 2048.
        n_chain = int(np.clip(110 * s256 * s256, 32, 420))
        for _ in range(n_chain):
            cx = float(rng.uniform(0.04, 0.96) * w)
            cy = float(rng.uniform(0.04, 0.96) * h)
            n_beads = int(rng.integers(5, 13))
            chain_ang = flow_ang + float(rng.normal(0, 0.12))
            step = float(rng.uniform(2.0, 3.4) * s256)
            # per-chain chroma signature (shared M/R/CC across beads with jitter)
            chM = float(rng.uniform(0.72, 0.99))
            chR = float(rng.uniform(0.04, 0.24))
            chCC = float(rng.uniform(0.55, 0.95))
            for b in range(n_beads):
                bx = int(cx + np.cos(chain_ang) * step * b + rng.normal(0, 0.6))
                by = int(cy + np.sin(chain_ang) * step * b + rng.normal(0, 0.6))
                if not (0 <= bx < w and 0 <= by < h):
                    continue
                br = max(1, int(rng.uniform(1.0, 1.8) * s256))
                _cv2.circle(M, (bx, by), br, chM + float(rng.uniform(-0.05, 0.05)), -1, lineType=_cv2.LINE_AA)
                _cv2.circle(R, (bx, by), br, chR + float(rng.uniform(-0.04, 0.06)), -1, lineType=_cv2.LINE_AA)
                _cv2.circle(CC, (bx, by), br, chCC + float(rng.uniform(-0.06, 0.04)), -1, lineType=_cv2.LINE_AA)

        # Tier 9 - R6-CREATIVE NEW: ROSE-CURVE MAGNETIC ROSETTES
        # 8-22 small rhodonea curves r=A*cos(k*theta) plotted as 26-step
        # polylines, 10-22 px across. Petal counts k in {3,4,5,6,8}. These
        # are the field-line rosettes where multiple iron-filing chains
        # spiral around a strong magnet pole. Per-rosette INDEPENDENT
        # continuous M/R/CC. Replaces some glint-chain density to keep
        # the 200 ms budget at 256^2.
        n_rose = int(np.clip(14 * s256, 7, 26))
        k_pool = (3, 4, 5, 6, 8)
        for _ in range(n_rose):
            cx = float(rng.uniform(0.08, 0.92) * w)
            cy = float(rng.uniform(0.08, 0.92) * h)
            A_amp = float(rng.uniform(4.5, 10.0) * s256)
            k_pet = int(rng.choice(k_pool))
            phase = float(rng.uniform(0, 2 * np.pi))
            rM  = float(rng.uniform(0.65, 0.97))
            rR  = float(rng.uniform(0.06, 0.30))
            rCC = float(rng.uniform(0.45, 0.92))
            n_seg = 26
            ts = np.linspace(0.0, 2.0 * np.pi, n_seg + 1, dtype=np.float32) + phase
            radii = A_amp * np.cos(k_pet * ts)
            xs = cx + radii * np.cos(ts)
            ys = cy + radii * np.sin(ts)
            for kk in range(n_seg):
                x0 = int(np.clip(xs[kk], 0, w - 1)); y0 = int(np.clip(ys[kk], 0, h - 1))
                x1 = int(np.clip(xs[kk + 1], 0, w - 1)); y1 = int(np.clip(ys[kk + 1], 0, h - 1))
                _cv2.line(M,  (x0, y0), (x1, y1),
                          float(np.clip(rM  + rng.uniform(-0.05, 0.05), 0, 1)), 1, lineType=_cv2.LINE_AA)
                _cv2.line(R,  (x0, y0), (x1, y1),
                          float(np.clip(rR  + rng.uniform(-0.04, 0.04), 0, 1)), 1, lineType=_cv2.LINE_AA)
                _cv2.line(CC, (x0, y0), (x1, y1),
                          float(np.clip(rCC + rng.uniform(-0.05, 0.05), 0, 1)), 1, lineType=_cv2.LINE_AA)

    out = np.stack([M, R, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
metallic_sand._spb_concept_complete = True
def holographic_flake(shape, seed, sm, density=0.004, freq_x=12.0, freq_y=9.0):
    """holographic_flake.

    identity: A true diffraction-grating holographic film coat. CREATIVE
    REBUILD: stacked SIX tiers â€” (1) two crossed micro-rulings at sub-pixel
    pitch producing a moire interference field, (2) a smooth THIN-FILM
    SPECTRAL WAVE (M/R/CC each at different phase offsets) that simulates
    the rainbow shift across the panel, (3) per-pixel ULTRA-DENSE 1-2 px
    flakes with INDEPENDENT M/R/CC uniforms, (4) ring-flakes 2-4 px,
    (5) elongated RAINBOW-STREAK diffraction segments (4-10 px) aligned
    to one of the grating axes, each with an internal red->violet hue
    progression (rim positions vary M/R/CC continuously along their length),
    (6) tiny dark interference nulls. The new spectral-wave tier and
    rainbow-streak tier give the panel an unmistakable holographic identity
    even at thumbnail scale.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 82643)
    scale = max(min(h, w) / 2048.0, 0.25)

    def _fbm(off, sigma):
        if _CV2_OK:
            sh = max(64, h // 10); sw = max(64, w // 10)
            n = np.random.default_rng(int(seed) + off).random((sh, sw)).astype(np.float32)
            b = _cv2.GaussianBlur(n, (0, 0), sigmaX=sigma, sigmaY=sigma)
            return _normalize(_cv2.resize(b, (w, h), interpolation=_cv2.INTER_CUBIC).astype(np.float32))
        return _normalize(multi_scale_noise(shape, [20, 40], [0.6, 0.4], int(seed) + off))

    yy, xx = np.mgrid[0:h, 0:w].astype(np.float32)
    # TIER 1 â€” Two crossed fine gratings (3-6 px pitch)
    a1 = float(rng.uniform(0, np.pi))
    a2 = a1 + float(rng.uniform(0.35, 1.2))
    u1 = xx * np.cos(a1) + yy * np.sin(a1)
    u2 = xx * np.cos(a2) + yy * np.sin(a2)
    pitch1 = max(2.5, 4.0 * scale); pitch2 = max(2.5, 5.5 * scale)
    g1 = 0.5 + 0.5 * np.sin(u1 / pitch1 * np.pi * 2.0)
    g2 = 0.5 + 0.5 * np.sin(u2 / pitch2 * np.pi * 2.0)
    interf = g1 * g2

    # TIER 2 â€” THIN-FILM SPECTRAL WAVE â€” three offset-phase sinusoids
    # along an arbitrary direction; each channel reads a different "wavelength"
    sw_ang = float(rng.uniform(0, 2 * np.pi))
    sw_pitch = max(28.0, 50.0 * scale)
    sw_proj = (xx * np.cos(sw_ang) + yy * np.sin(sw_ang)) / sw_pitch
    swM  = 0.5 + 0.5 * np.sin(sw_proj * 2.0 * np.pi + float(rng.uniform(0, 2 * np.pi)))
    swR  = 0.5 + 0.5 * np.sin(sw_proj * 2.0 * np.pi + 2.094 + float(rng.uniform(-0.4, 0.4)))  # +120 deg
    swCC = 0.5 + 0.5 * np.sin(sw_proj * 2.0 * np.pi + 4.188 + float(rng.uniform(-0.4, 0.4)))  # +240 deg

    fM = _fbm(9011, 5.5); fR = _fbm(9013, 5.5); fCC = _fbm(9015, 5.5)
    # 3 INDEPENDENT bias-shifted channel mixes with spectral-wave tilt
    M  = (0.38 + 0.18 * g1 + 0.14 * interf + 0.16 * (swM  - 0.5) + 0.12 * (fM  - 0.5)).astype(np.float32)
    R  = (0.32 + 0.18 * (1.0 - g2) + 0.12 * (1.0 - interf) + 0.18 * (swR  - 0.5) + 0.14 * (fR - 0.5)).astype(np.float32)
    CC = (0.30 + 0.18 * g2 + 0.16 * interf + 0.20 * (swCC - 0.5) + 0.14 * (fCC - 0.5)).astype(np.float32)

    if _CV2_OK:
        # TIER 3 â€” ULTRA-DENSE micro-flakes (1-2 px) with INDEPENDENT M/R/CC
        n_fine = int(max(h * w * float(density) * 22.0, 36000))
        ys = rng.integers(0, h, n_fine); xs = rng.integers(0, w, n_fine)
        M[ys, xs]  = np.maximum(M[ys, xs],  rng.uniform(0.62, 0.99, n_fine).astype(np.float32))
        R[ys, xs]  = np.minimum(R[ys, xs],  rng.uniform(0.03, 0.26, n_fine).astype(np.float32))
        CC[ys, xs] = np.maximum(CC[ys, xs], rng.uniform(0.48, 0.97, n_fine).astype(np.float32))

        # TIER 4 â€” Ring-flakes 2-4 px (pigment platelets)
        n_med = max(int(h * w / 600), 2200)
        for _ in range(n_med):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            rr = int(max(1, rng.uniform(1.5, 3.0) * scale))
            _cv2.circle(M,  (cx, cy), rr, float(rng.uniform(0.66, 0.97)), 1, lineType=_cv2.LINE_AA)
            _cv2.circle(R,  (cx, cy), rr, float(rng.uniform(0.04, 0.22)), 1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), rr, float(rng.uniform(0.50, 0.96)), 1, lineType=_cv2.LINE_AA)

        # TIER 5 â€” RAINBOW-STREAK diffraction segments
        # Each streak is 5-12 px long, aligned to one of the two grating
        # axes; along its length M/R/CC sweep through hue-shifted values
        # (red end vs violet end) to mimic spectral dispersion.
        n_streak = max(int(h * w / 220), 4800)
        for _ in range(n_streak):
            sx = float(rng.uniform(0, w)); sy = float(rng.uniform(0, h))
            ax = a1 if rng.random() < 0.55 else a2
            ax = ax + float(rng.normal(0, 0.10))
            ll = float(rng.uniform(4.0, 10.0) * scale)
            n_steps = max(2, int(ll * 0.85))
            # Endpoint phase positions in the rainbow â€” independent per streak
            ph0 = float(rng.uniform(0, 2 * np.pi))
            ph1 = ph0 + float(rng.uniform(0.7, 2.2))  # sweeps a chunk of spectrum
            for si in range(n_steps):
                t = si / max(1, n_steps - 1)
                px = int(sx + np.cos(ax) * (t - 0.5) * ll)
                py = int(sy + np.sin(ax) * (t - 0.5) * ll)
                if 0 <= px < w and 0 <= py < h:
                    ph = ph0 + (ph1 - ph0) * t
                    # 3-phase shift: simulates hue rotation
                    vM  = float(0.55 + 0.40 * np.sin(ph))
                    vR  = float(0.40 + 0.30 * np.sin(ph + 2.094))
                    vCC = float(0.55 + 0.40 * np.sin(ph + 4.188))
                    # Independent jitter per pixel
                    vM  = float(np.clip(vM  + rng.uniform(-0.06, 0.06), 0.0, 1.0))
                    vR  = float(np.clip(vR  + rng.uniform(-0.06, 0.06), 0.0, 1.0))
                    vCC = float(np.clip(vCC + rng.uniform(-0.06, 0.06), 0.0, 1.0))
                    if vM > M[py, px]: M[py, px] = vM
                    R[py, px]  = min(R[py, px],  vR * 0.6 + R[py, px] * 0.4)
                    if vCC > CC[py, px]: CC[py, px] = vCC

        # TIER 6 â€” Tiny dark interference NULLS
        n_null = max(int(h * w / 550), 2400)
        ys2 = rng.integers(0, h, n_null); xs2 = rng.integers(0, w, n_null)
        M[ys2, xs2]  = np.minimum(M[ys2, xs2],  rng.uniform(0.10, 0.30, n_null).astype(np.float32))
        CC[ys2, xs2] = np.minimum(CC[ys2, xs2], rng.uniform(0.08, 0.30, n_null).astype(np.float32))

    out = np.stack([M, R, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)


holographic_flake._spb_concept_complete = True


def crystal_shimmer(shape, seed, sm, cell_size=10, edge_width=0.25, **kwargs):
    """crystal_shimmer.

    identity: R6-creative â€” DUAL-TIER cleaved-quartz mosaic. A primary
    Voronoi facet field (6 px pitch) is overlaid with a second, COARSER
    facet tier (14 px) for kaleidoscopic depth â€” bigger crystals sit on
    top of finer ones, giving real cleaved-crystal layering, not a single
    flat mosaic. Hero motifs: rare bright cleavage-star bursts (5-10 px,
    asymmetric 4-arm + 1-pixel cross spikes) salted across the canvas,
    rainbow CC dispersion threads along facet edges (independent
    continuous CC chroma jumps), facet-corner micro-pyramid pips, dense
    trench specks, and a wide chroma uniform [0.05, 0.97] on every
    feature channel. No empty substrate. 6-32 px features only.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    from scipy.spatial import cKDTree
    rng = np.random.default_rng(int(seed) + (hash("crystal_shimmer_r6c") % 10000))
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)

    # --- TIER 1: FINE FACET FIELD (6 px) ----------------------------------
    cs1 = max(4, int(cell_size * 0.6))
    ny1 = max(2, h // cs1 + 2); nx1 = max(2, w // cs1 + 2)
    IY, IX = np.meshgrid(np.arange(ny1), np.arange(nx1), indexing='ij')
    cy1 = (IY.astype(np.float64) + rng.uniform(0.1, 0.9, (ny1, nx1))) * cs1
    cx1 = (IX.astype(np.float64) + rng.uniform(0.1, 0.9, (ny1, nx1))) * cs1
    n1 = ny1 * nx1
    cM1 = rng.uniform(0.08, 0.97, n1).astype(np.float32)
    cR1 = rng.uniform(0.05, 0.92, n1).astype(np.float32)
    cC1 = rng.uniform(0.06, 0.96, n1).astype(np.float32)

    centers1 = np.column_stack([cy1.ravel(), cx1.ravel()])
    tree1 = cKDTree(centers1)
    yy, xx = np.mgrid[0:h, 0:w].astype(np.float64)
    pts = np.column_stack([yy.ravel(), xx.ravel()])
    d_, i_ = tree1.query(pts, k=2, workers=-1)
    d1a = d_[:, 0].reshape(shape).astype(np.float32)
    d1b = d_[:, 1].reshape(shape).astype(np.float32)
    edge1 = np.clip((d1b - d1a) / (edge_width * cs1 + 0.01), 0, 1)
    near1 = i_[:, 0]
    M_f = cM1[near1].reshape(shape)
    R_f = cR1[near1].reshape(shape)
    C_f = cC1[near1].reshape(shape)

    M = M_f * (0.55 + 0.45 * edge1)
    R_ch = R_f * (0.45 + 0.55 * (1.0 - edge1))
    CC = C_f * (0.55 + 0.45 * edge1)

    # --- TIER 2: COARSER FACET OVERLAY (14 px) â€” kaleidoscope depth ------
    cs2 = max(8, int(cell_size * 1.4))
    ny2 = max(2, h // cs2 + 2); nx2 = max(2, w // cs2 + 2)
    IY2, IX2 = np.meshgrid(np.arange(ny2), np.arange(nx2), indexing='ij')
    cy2 = (IY2.astype(np.float64) + rng.uniform(0.1, 0.9, (ny2, nx2))) * cs2
    cx2 = (IX2.astype(np.float64) + rng.uniform(0.1, 0.9, (ny2, nx2))) * cs2
    n2 = ny2 * nx2
    cM2 = rng.uniform(0.10, 0.95, n2).astype(np.float32)
    cR2 = rng.uniform(0.08, 0.90, n2).astype(np.float32)
    cC2 = rng.uniform(0.07, 0.97, n2).astype(np.float32)
    centers2 = np.column_stack([cy2.ravel(), cx2.ravel()])
    tree2 = cKDTree(centers2)
    d2_, i2_ = tree2.query(pts, k=2, workers=-1)
    e2 = np.clip((d2_[:, 1].reshape(shape) - d2_[:, 0].reshape(shape)) / (edge_width * cs2 + 0.01), 0, 1).astype(np.float32)
    near2 = i2_[:, 0]
    M2 = cM2[near2].reshape(shape); R2 = cR2[near2].reshape(shape); C2 = cC2[near2].reshape(shape)
    # Blend coarse tier in with ~35% weight where its edges are NOT prominent (interior)
    blend = (0.65 - 0.35 * e2).astype(np.float32)
    M = M * (1.0 - blend * 0.35) + M2 * (blend * 0.35)
    R_ch = R_ch * (1.0 - blend * 0.30) + R2 * (blend * 0.30)
    CC = CC * (1.0 - blend * 0.40) + C2 * (blend * 0.40)

    if _CV2_OK:
        # Tier-1 facet pips
        pip_idx = np.where(rng.random(n1) > 0.66)[0]
        for ci in pip_idx[:30000]:
            cxp = int(centers1[ci, 1]); cyp = int(centers1[ci, 0])
            if 0 <= cxp < w and 0 <= cyp < h:
                r = max(1, int(rng.uniform(1.0, 2.0) * scale))
                _cv2.circle(M, (cxp, cyp), r, float(rng.uniform(0.62, 0.99)), -1, lineType=_cv2.LINE_AA)
                _cv2.circle(R_ch, (cxp, cyp), r, float(rng.uniform(0.04, 0.30)), -1, lineType=_cv2.LINE_AA)
                _cv2.circle(CC, (cxp, cyp), r, float(rng.uniform(0.05, 0.96)), -1, lineType=_cv2.LINE_AA)

        # HERO motif: rare cleavage-star bursts (asymmetric 4-arm + cross spikes)
        n_hero = int(np.clip(280 * (mn / 2048.0) ** 2, 90, 900))
        for _ in range(n_hero):
            cx_h = int(rng.uniform(6, w - 6)); cy_h = int(rng.uniform(6, h - 6))
            arm = max(3, int(rng.uniform(5.0, 10.0) * scale))
            hM = float(rng.uniform(0.80, 0.99))
            hR = float(rng.uniform(0.03, 0.16))
            hC = float(rng.uniform(0.08, 0.96))
            # asymmetric 4 arms
            for sign_x, sign_y, scale_a in [(1,0,1.0),(-1,0,0.7),(0,1,0.85),(0,-1,1.1)]:
                ax = int(cx_h + sign_x * arm * scale_a)
                ay = int(cy_h + sign_y * arm * scale_a)
                _cv2.line(M, (cx_h, cy_h), (ax, ay), hM, 1, lineType=_cv2.LINE_AA)
                _cv2.line(R_ch, (cx_h, cy_h), (ax, ay), hR, 1, lineType=_cv2.LINE_AA)
                _cv2.line(CC, (cx_h, cy_h), (ax, ay), hC, 1, lineType=_cv2.LINE_AA)
            # 1-px diagonal cross spikes
            d_arm = max(2, arm // 2)
            _cv2.line(M, (cx_h - d_arm, cy_h - d_arm), (cx_h + d_arm, cy_h + d_arm),
                      float(rng.uniform(0.75, 0.99)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(M, (cx_h - d_arm, cy_h + d_arm), (cx_h + d_arm, cy_h - d_arm),
                      float(rng.uniform(0.75, 0.99)), 1, lineType=_cv2.LINE_AA)
            # center pip
            _cv2.circle(M, (cx_h, cy_h), max(1, int(scale * 1.5)), float(rng.uniform(0.88, 0.99)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx_h, cy_h), max(1, int(scale * 1.5)), float(rng.uniform(0.65, 0.96)), -1, lineType=_cv2.LINE_AA)

        # FACET-CORNER MICRO-PYRAMIDS â€” 1-px crosses
        n_star = int(np.clip(3500 * (mn / 2048.0) ** 2, 1100, 11000))
        for _ in range(n_star):
            cx_s = int(rng.uniform(2, w - 2)); cy_s = int(rng.uniform(2, h - 2))
            L = max(1, int(rng.uniform(1.0, 2.0) * scale))
            v_M = float(rng.uniform(0.72, 0.99))
            _cv2.line(M, (cx_s - L, cy_s), (cx_s + L, cy_s), v_M, 1, lineType=_cv2.LINE_AA)
            _cv2.line(M, (cx_s, cy_s - L), (cx_s, cy_s + L), v_M, 1, lineType=_cv2.LINE_AA)

    # RAINBOW DISPERSION THREADS along tier-1 edges (vectorized)
    edge_mask = (edge1 < 0.18)
    n_thread_px = int(np.clip(edge_mask.sum() * 0.08, 0, 60000))
    if n_thread_px > 0:
        idx_flat = np.flatnonzero(edge_mask.ravel())
        pick = rng.choice(idx_flat, size=n_thread_px, replace=False)
        py = (pick // w).astype(np.int32); px = (pick % w).astype(np.int32)
        CC[py, px] = rng.uniform(0.05, 0.97, n_thread_px).astype(np.float32)
        M[py, px] = np.maximum(M[py, px], rng.uniform(0.60, 0.97, n_thread_px).astype(np.float32))

    # 5x glint speckles
    n_glint = int(np.clip(4500 * (mn / 2048.0) ** 2, 1300, 13000))
    gy = rng.integers(0, h, n_glint); gx = rng.integers(0, w, n_glint)
    M[gy, gx] = np.maximum(M[gy, gx], rng.uniform(0.65, 0.99, n_glint).astype(np.float32))
    R_ch[gy, gx] = np.minimum(R_ch[gy, gx], rng.uniform(0.04, 0.25, n_glint).astype(np.float32))
    CC[gy, gx] = rng.uniform(0.08, 0.96, n_glint).astype(np.float32)

    # TRENCH SPECKS â€” dim 1-px shadow points
    n_dk = int(np.clip(mn * mn * 0.0012, 1800, 10000))
    dy = rng.integers(0, h, n_dk); dx = rng.integers(0, w, n_dk)
    M[dy, dx]  = np.minimum(M[dy, dx],  rng.uniform(0.05, 0.28, n_dk).astype(np.float32))
    CC[dy, dx] = np.minimum(CC[dy, dx], rng.uniform(0.05, 0.30, n_dk).astype(np.float32))

    out = np.stack([np.clip(M, 0, 1), np.clip(R_ch, 0, 1), np.clip(CC, 0, 1)], axis=-1).astype(np.float32)
    return _sm_scale(out, sm)
crystal_shimmer._spb_concept_complete = True


def stardust_fine(shape, seed, sm, density=0.012):
    """stardust_fine.

    identity: R6-creative â€” DEEP-FIELD ASTROPHOTO with a MILKY WAY DENSITY
    BAND running diagonally across the canvas (FBM-modulated brighter
    stripe of stars), HERO supergiants (8-14 px bright discs with full
    6-arm diffraction spikes + halo ring), CONSTELLATION CHAINS (4-7
    bright stars linked by faint 1-px guideline arcs), a sodium-amber
    nebula glow blob layered behind the brightest cluster, dense cosmic
    speck carpet, mid filler stars, dim halo flecks, and per-channel
    deep-field FBM. Each feature picks INDEPENDENT continuous M/R/CC
    across [0.04, 0.99] for true blue-white through red-shift chroma.
    Fine features 1-14 px, no panel-scale blobs, full coverage.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + (hash("stardust_fine_r6c") % 10000))
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)
    yy = np.arange(h, dtype=np.float32).reshape(h, 1)
    xx = np.arange(w, dtype=np.float32).reshape(1, w)

    # 1) Per-channel night-sky FBM
    fbm_M = _normalize(multi_scale_noise(shape, [2.5, 7.0, 18.0, 40.0],
                                          [0.36, 0.30, 0.22, 0.12], int(seed) + 8801))
    fbm_R = _normalize(multi_scale_noise(shape, [3.0, 8.0, 20.0, 44.0],
                                          [0.36, 0.30, 0.22, 0.12], int(seed) + 8803))
    fbm_CC = _normalize(multi_scale_noise(shape, [2.0, 6.0, 16.0, 36.0],
                                            [0.36, 0.30, 0.22, 0.12], int(seed) + 8807))
    neb = _normalize(multi_scale_noise(shape, [60.0, 140.0], [0.6, 0.4], int(seed) + 8809))

    M = (0.20 + (fbm_M - 0.5) * 0.18 + (neb - 0.5) * 0.08).astype(np.float32)
    R = (0.68 + (fbm_R - 0.5) * 0.18 - (neb - 0.5) * 0.10).astype(np.float32)
    CC = (0.55 + (fbm_CC - 0.5) * 0.30 + (neb - 0.5) * 0.18).astype(np.float32)

    # 2) MILKY WAY band â€” diagonal density gradient modulated by FBM
    band_ang = float(rng.uniform(0.35, 1.20))   # ~20-70 deg
    band_center_off = float(rng.uniform(-0.15, 0.15)) * w
    cy_h = h * 0.5; cx_w = w * 0.5
    # signed perpendicular distance to band axis
    d_band = ((xx - cx_w - band_center_off) * np.cos(band_ang) - (yy - cy_h) * np.sin(band_ang))
    band_half = float(mn) * 0.28
    band_mask = np.exp(-(d_band ** 2) / (2.0 * band_half * band_half + 1e-6)).astype(np.float32)
    band_density_field = _normalize(multi_scale_noise(shape, [8.0, 22.0], [0.6, 0.4], int(seed) + 8821))
    band_density = (band_mask * (0.55 + 0.45 * band_density_field)).astype(np.float32)

    if _CV2_OK:
        # 3) HERO SUPERGIANTS â€” rare, with 6-arm spikes + halo ring
        n_hero = int(np.clip(14 + 18 * (mn / 256.0), 6, 80))
        for _ in range(n_hero):
            cx = int(rng.uniform(8, w - 8)); cy = int(rng.uniform(8, h - 8))
            r_h = max(3, int(rng.uniform(4.0, 8.0) * scale * 1.2))
            hM = float(rng.uniform(0.86, 0.99))
            hR = float(rng.uniform(0.03, 0.12))
            hC = float(rng.uniform(0.10, 0.96))
            _cv2.circle(M, (cx, cy), r_h, hM, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r_h, hR, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r_h, hC, -1, lineType=_cv2.LINE_AA)
            # halo ring
            _cv2.circle(M, (cx, cy), r_h + 2, float(rng.uniform(0.50, 0.80)), 1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r_h + 2, float(rng.uniform(0.20, 0.92)), 1, lineType=_cv2.LINE_AA)
            # 6-arm diffraction spikes
            arm = max(4, int(rng.uniform(6.0, 12.0) * scale))
            for ang_deg in (0, 60, 120):
                a = np.deg2rad(ang_deg + float(rng.uniform(-4, 4)))
                dx = int(np.cos(a) * arm); dy = int(np.sin(a) * arm)
                _cv2.line(M, (cx - dx, cy - dy), (cx + dx, cy + dy), hM, 1, lineType=_cv2.LINE_AA)
                _cv2.line(CC, (cx - dx, cy - dy), (cx + dx, cy + dy), hC, 1, lineType=_cv2.LINE_AA)

        # 4) CONSTELLATION CHAINS â€” 4-7 stars linked by faint arcs
        n_const = int(np.clip(3 + 6 * (mn / 256.0), 2, 30))
        for _ in range(n_const):
            n_nodes = int(rng.integers(4, 8))
            cx_c = float(rng.uniform(0.10, 0.90) * w)
            cy_c = float(rng.uniform(0.10, 0.90) * h)
            theta = float(rng.uniform(0, 2 * np.pi))
            nodes = []
            cur_x, cur_y = cx_c, cy_c
            for k in range(n_nodes):
                step = float(rng.uniform(9.0, 18.0) * scale * 1.3)
                theta += float(rng.uniform(-0.9, 0.9))
                cur_x = float(np.clip(cur_x + np.cos(theta) * step, 3, w - 3))
                cur_y = float(np.clip(cur_y + np.sin(theta) * step, 3, h - 3))
                nodes.append((int(cur_x), int(cur_y)))
                # bright node star
                r_n = max(2, int(rng.uniform(2.0, 4.0) * scale))
                _cv2.circle(M, (int(cur_x), int(cur_y)), r_n, float(rng.uniform(0.80, 0.99)), -1, lineType=_cv2.LINE_AA)
                _cv2.circle(R, (int(cur_x), int(cur_y)), r_n, float(rng.uniform(0.03, 0.15)), -1, lineType=_cv2.LINE_AA)
                _cv2.circle(CC, (int(cur_x), int(cur_y)), r_n, float(rng.uniform(0.15, 0.96)), -1, lineType=_cv2.LINE_AA)
            # faint guideline 1-px between consecutive nodes
            line_v = float(rng.uniform(0.32, 0.55))
            for a, b in zip(nodes[:-1], nodes[1:]):
                _cv2.line(M, a, b, line_v, 1, lineType=_cv2.LINE_AA)

        # 5) Star discs â€” 5x density (smaller individual stars to keep them fine)
        n_star = int(np.clip(18000 * (mn / 2048.0) ** 2, 6000, 40000))
        for _ in range(n_star):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            # density-modulated retention: skip if outside band weight
            if rng.random() > 0.35 + 0.65 * float(band_density[cy, cx]):
                continue
            r_s = max(1, int(float(rng.uniform(1.0, 3.0)) * scale))
            _cv2.circle(M, (cx, cy), r_s, float(rng.uniform(0.55, 0.99)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r_s, float(rng.uniform(0.04, 0.30)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r_s, float(rng.uniform(0.05, 0.97)), -1, lineType=_cv2.LINE_AA)

        # 6) Diffraction spikes on bright stars (more crosses)
        n_spike = int(np.clip(2500 * (mn / 2048.0) ** 2, 800, 6000))
        for _ in range(n_spike):
            cx = int(rng.uniform(6, w - 6)); cy = int(rng.uniform(6, h - 6))
            arm = max(2, int(float(rng.uniform(4.0, 12.0)) * scale * 0.5))
            mM = float(rng.uniform(0.72, 0.99))
            mR = float(rng.uniform(0.04, 0.20))
            mCC = float(rng.uniform(0.08, 0.95))
            _cv2.line(M, (cx - arm, cy), (cx + arm, cy), mM, 1, lineType=_cv2.LINE_AA)
            _cv2.line(M, (cx, cy - arm), (cx, cy + arm), mM, 1, lineType=_cv2.LINE_AA)
            _cv2.line(R, (cx - arm, cy), (cx + arm, cy), mR, 1, lineType=_cv2.LINE_AA)
            _cv2.line(R, (cx, cy - arm), (cx, cy + arm), mR, 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (cx - arm, cy), (cx + arm, cy), mCC, 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (cx, cy - arm), (cx, cy + arm), mCC, 1, lineType=_cv2.LINE_AA)

        # 7) Mid-bright filler stars â€” 5x
        n_mid = int(np.clip(8000 * (mn / 2048.0) ** 2, 2500, 18000))
        for _ in range(n_mid):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            r_s = max(1, int(float(rng.uniform(1.0, 2.0)) * scale))
            _cv2.circle(M, (cx, cy), r_s, float(rng.uniform(0.38, 0.78)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r_s, float(rng.uniform(0.18, 0.50)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r_s, float(rng.uniform(0.15, 0.85)), -1, lineType=_cv2.LINE_AA)

    # 8) Cosmic-speck single-pixel carpet (5x) â€” boosted in band
    n_flecks = int(np.clip(16000 * (mn / 2048.0) ** 2, 5000, 30000))
    fy = rng.integers(0, h, n_flecks); fx = rng.integers(0, w, n_flecks)
    bd = band_density[fy, fx]
    # keep all, but brightness biased by band
    M[fy, fx] = np.maximum(M[fy, fx], (rng.uniform(0.45, 0.97, n_flecks).astype(np.float32) * (0.6 + 0.4 * bd)))
    R[fy, fx] = np.minimum(R[fy, fx], rng.uniform(0.04, 0.30, n_flecks).astype(np.float32))
    CC[fy, fx] = rng.uniform(0.05, 0.97, n_flecks).astype(np.float32)

    # 9) Dim halo flecks
    n_dim = int(np.clip(12000 * (mn / 2048.0) ** 2, 3500, 22000))
    dy = rng.integers(0, h, n_dim); dx = rng.integers(0, w, n_dim)
    M[dy, dx] = np.clip(M[dy, dx] + rng.uniform(-0.08, 0.22, n_dim).astype(np.float32), 0, 1)
    CC[dy, dx] = np.clip(CC[dy, dx] + rng.uniform(-0.18, 0.25, n_dim).astype(np.float32), 0, 1)

    # 10) Apply Milky Way band brightness lift
    M = np.clip(M + band_density * 0.06, 0, 1).astype(np.float32)
    CC = np.clip(CC + band_density * 0.04, 0, 1).astype(np.float32)

    out = np.stack([np.clip(M, 0, 1), np.clip(R, 0, 1), np.clip(CC, 0, 1)], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
stardust_fine._spb_concept_complete = True


# ============================================================================
# 56. PEARL MICRO â€” soft pearlescent micro-texture with sine harmonics
# ============================================================================

def pearl_micro(shape, seed, sm, octaves=4, **kwargs):
    """pearl_micro.

    identity: Tick-44 creative rebuild â€” MICROPEARL NACRE close-up. Hero motif:
    tight Voronoi nacre mosaic at 8-12 px cell pitch where every cell is
    an individual pearl-platelet with its own INDEPENDENT continuous
    M/R/CC tint pulled from a wide chroma range (cool blues, pink
    rainbows, mint greens, champagne). Stacked on top: iridescent
    interference ARC BANDS (the rainbow flash that real nacre does),
    bright EDGE SEAMS where platelets meet (Voronoi second-neighbor
    distance map drives this), per-cell asymmetric MICRO-LUMP highlights
    (single pixel bright kiss per cell, biased toward one corner â€”
    breaking the lazy "every cell is equal" look), fine pore noise per
    channel for organic texture, DENSE 1-2 px pinpoint sparkles, DENSE
    dark pit nodes for shadow chroma, and a vectorized fleck-dust
    carpet so substrate never reads empty. Owner-eye target.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + (hash("pearl_micro_t44") % 10000))
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)

    # 1) HERO: Dense Voronoi cell field at 9 px pitch â€” every cell its own chroma.
    # 2026-05-30 perf pass: build the ownership map at half-res for 2048.
    # The cell pitch is scaled down before query, then the cell fields are
    # nearest-upsampled; full-res sparkle/lump layers below preserve the fine
    # pin detail that actually sells the material.
    cell_pitch = max(6.5, 9.0 * scale)
    cell_ds = 2 if _CV2_OK and max(h, w) > 1024 else 1
    vh = max(128, h // cell_ds)
    vw = max(128, w // cell_ds)
    cell_pitch_q = max(3.25, cell_pitch / cell_ds)
    n_cells = int(np.clip((vh * vw) / (cell_pitch_q * cell_pitch_q), 1000, 45000))
    pts_y = rng.uniform(-cell_pitch_q, vh + cell_pitch_q, n_cells).astype(np.float32)
    pts_x = rng.uniform(-cell_pitch_q, vw + cell_pitch_q, n_cells).astype(np.float32)
    # INDEPENDENT M/R/CC per cell, wide spread for rainbow nacre
    cell_M = rng.uniform(0.38, 0.98, n_cells).astype(np.float32)
    cell_R = rng.uniform(0.08, 0.55, n_cells).astype(np.float32)
    cell_CC = rng.uniform(0.04, 0.65, n_cells).astype(np.float32)

    tree = cKDTree(np.column_stack([pts_y.astype(np.float64), pts_x.astype(np.float64)]))
    if cell_ds > 1:
        yy_q, xx_q = np.mgrid[0:vh, 0:vw].astype(np.float32)
        coords = np.column_stack([yy_q.ravel().astype(np.float64), xx_q.ravel().astype(np.float64)])
    else:
        yy, xx = np.mgrid[0:h, 0:w].astype(np.float32)
        coords = np.column_stack([yy.ravel().astype(np.float64), xx.ravel().astype(np.float64)])
    dists, idxs = tree.query(coords, k=2, workers=-1)
    q_shape = (vh, vw) if cell_ds > 1 else (h, w)
    d1 = dists[:, 0].reshape(q_shape).astype(np.float32)
    d2 = dists[:, 1].reshape(q_shape).astype(np.float32)
    edge_mask = np.clip(1.0 - (d2 - d1) / 2.0, 0, 1).astype(np.float32)
    idx_field = idxs[:, 0].reshape(q_shape)

    M = cell_M[idx_field]
    R = cell_R[idx_field]
    CC = cell_CC[idx_field]
    if cell_ds > 1:
        M = _cv2.resize(M.astype(np.float32), (w, h), interpolation=_cv2.INTER_NEAREST)
        R = _cv2.resize(R.astype(np.float32), (w, h), interpolation=_cv2.INTER_NEAREST)
        CC = _cv2.resize(CC.astype(np.float32), (w, h), interpolation=_cv2.INTER_NEAREST)
        edge_mask = _cv2.resize(edge_mask.astype(np.float32), (w, h), interpolation=_cv2.INTER_LINEAR)
        pts_y = (pts_y * cell_ds).astype(np.float32)
        pts_x = (pts_x * cell_ds).astype(np.float32)

    # 2) IRIDESCENT INTERFERENCE ARCS â€” the rainbow flash of real nacre
    # Bug fix 2026-06-02: supersample the arc field to >=256 px (crisp,
    # anti-aliased rainbow arcs on small thumbnails) ONLY when cv2 is present to
    # downsample it back to (h, w); otherwise build it natively at (h, w).
    # Previously the >=256 floor applied unconditionally but the downsample was
    # gated on arc_ds>1, so any canvas < 256 px left shell at 256x256 and the
    # `M + shell` broadcast failed -> pearl_micro errored at every preview size.
    arc_ds = 2 if _CV2_OK and max(h, w) > 1024 else 1
    if _CV2_OK:
        ah = max(256, h // arc_ds)
        aw = max(256, w // arc_ds)
    else:
        ah, aw = h, w
    yy_a, xx_a = np.mgrid[0:ah, 0:aw].astype(np.float32)
    xn = xx_a / max(aw, 1); yn = yy_a / max(ah, 1)
    shell = np.zeros((ah, aw), dtype=np.float32)
    shell_chroma = np.zeros((ah, aw), dtype=np.float32)
    for _ in range(8):
        cxn = float(rng.uniform(-0.20, 1.20)); cyn = float(rng.uniform(-0.20, 1.20))
        dist = np.hypot((xn - cxn) * float(rng.uniform(0.80, 1.55)),
                        (yn - cyn) * float(rng.uniform(0.80, 1.55))).astype(np.float32)
        phase = float(rng.uniform(0.0, np.pi * 2.0))
        freq = float(rng.uniform(55.0, 145.0))
        arcs = (np.sin(dist * freq + phase) * 0.5 + 0.5) ** float(rng.uniform(2.5, 5.5))
        shell = np.maximum(shell, arcs.astype(np.float32) * float(rng.uniform(0.30, 0.78)))
        # cross-phased chroma band for the rainbow shift
        chroma = (np.sin(dist * freq + phase + np.pi * 0.5) * 0.5 + 0.5) ** float(rng.uniform(2.5, 5.0))
        shell_chroma = np.maximum(shell_chroma, chroma.astype(np.float32) * float(rng.uniform(0.20, 0.55)))
    if (ah, aw) != (h, w):
        shell = _cv2.resize(shell.astype(np.float32), (w, h), interpolation=_cv2.INTER_LINEAR)
        shell_chroma = _cv2.resize(shell_chroma.astype(np.float32), (w, h), interpolation=_cv2.INTER_LINEAR)

    # 3) Per-channel modulation by edges + arc bands + chroma shift
    M = np.clip(M + edge_mask * 0.34 + shell * 0.26, 0, 1)
    R = np.clip(R - edge_mask * 0.20 + (1.0 - shell) * 0.06, 0, 1)
    CC = np.clip(CC - edge_mask * 0.12 + shell * 0.14 + shell_chroma * 0.18, 0, 1)

    # 4) Fine pore noise per channel (independent)
    if _CV2_OK and max(h, w) > 1024:
        pore_ds = 2
        pore_shape = (max(256, h // pore_ds), max(256, w // pore_ds))
        pore_M = _cv2.resize(
            _normalize(_gauss(rng.random(pore_shape, dtype=np.float32), sigma=max(0.35, mn / (780.0 * pore_ds)))).astype(np.float32),
            (w, h),
            interpolation=_cv2.INTER_LINEAR,
        )
        pore_R = _cv2.resize(
            _normalize(_gauss(rng.random(pore_shape, dtype=np.float32), sigma=max(0.35, mn / (880.0 * pore_ds)))).astype(np.float32),
            (w, h),
            interpolation=_cv2.INTER_LINEAR,
        )
        pore_C = _cv2.resize(
            _normalize(_gauss(rng.random(pore_shape, dtype=np.float32), sigma=max(0.35, mn / (720.0 * pore_ds)))).astype(np.float32),
            (w, h),
            interpolation=_cv2.INTER_LINEAR,
        )
    else:
        pore_M = _normalize(_gauss(rng.random((h, w), dtype=np.float32), sigma=max(0.40, mn / 780.0))).astype(np.float32)
        pore_R = _normalize(_gauss(rng.random((h, w), dtype=np.float32), sigma=max(0.40, mn / 880.0))).astype(np.float32)
        pore_C = _normalize(_gauss(rng.random((h, w), dtype=np.float32), sigma=max(0.40, mn / 720.0))).astype(np.float32)
    M = np.clip(M + (pore_M - 0.5) * 0.14, 0, 1)
    R = np.clip(R + (pore_R - 0.5) * 0.11, 0, 1)
    CC = np.clip(CC + (pore_C - 0.5) * 0.12, 0, 1)

    if _CV2_OK:
        # 5) PER-CELL ASYMMETRIC MICRO-LUMP HIGHLIGHTS â€” one bright kiss per cell, off-center
        # sample subset of cell centers to put a bright lump near each
        sample_count = min(n_cells, int(np.clip(n_cells * 0.34, 800, 6500)))
        sample_idx = rng.choice(n_cells, sample_count, replace=False)
        for i in sample_idx:
            cy = float(pts_y[i]); cx = float(pts_x[i])
            if cx < 0 or cx >= w or cy < 0 or cy >= h:
                continue
            # bias toward one corner of cell â€” asymmetric
            off_ang = float(rng.uniform(0, 2 * np.pi))
            off_r = float(rng.uniform(1.0, cell_pitch * 0.35))
            kx = int(cx + np.cos(off_ang) * off_r); ky = int(cy + np.sin(off_ang) * off_r)
            r = max(1, int(rng.uniform(1.0, 2.0) * scale))
            _cv2.circle(M, (kx, ky), r, float(rng.uniform(0.82, 0.99)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (kx, ky), r, float(rng.uniform(0.04, 0.18)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (kx, ky), r, float(rng.uniform(0.04, 0.36)), -1, lineType=_cv2.LINE_AA)

        # 6) DENSE PINPOINT SPARKLES (1-3 px)
        n_sp = int(np.clip(4600 * (mn / 2048.0) ** 2, 1900, 12500))
        for _ in range(n_sp):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            r = max(1, int(rng.uniform(1.0, 2.6) * scale))
            _cv2.circle(M, (cx, cy), r, float(rng.uniform(0.78, 0.99)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r, float(rng.uniform(0.04, 0.24)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r, float(rng.uniform(0.04, 0.40)), -1, lineType=_cv2.LINE_AA)

        # 7) DARK PIT NODES (1-2 px) â€” shadow chroma diversity
        n_dk = int(np.clip(2300 * (mn / 2048.0) ** 2, 800, 6800))
        for _ in range(n_dk):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            r = max(1, int(rng.uniform(1.0, 2.0) * scale))
            _cv2.circle(M, (cx, cy), r, float(rng.uniform(0.12, 0.42)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r, float(rng.uniform(0.55, 0.88)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r, float(rng.uniform(0.08, 0.30)), -1, lineType=_cv2.LINE_AA)

    # 8) FLECK DUST carpet â€” vectorized chroma diversity
    n_fl = max(8500, int(h * w / 80))
    fy = rng.integers(0, h, n_fl); fx = rng.integers(0, w, n_fl)
    M[fy, fx] = np.maximum(M[fy, fx], rng.uniform(0.48, 0.96, n_fl).astype(np.float32))
    R[fy, fx] = np.minimum(R[fy, fx], rng.uniform(0.06, 0.42, n_fl).astype(np.float32))
    CC[fy, fx] = np.maximum(CC[fy, fx], rng.uniform(0.22, 0.94, n_fl).astype(np.float32))

    # 2026-06-13 perf: direct float32 buffer assembly + single in-place clip
    # instead of three clip temporaries + stack + astype copy. Bit-identical.
    out = np.empty((h, w, 3), dtype=np.float32)
    out[:, :, 0] = M
    out[:, :, 1] = R
    out[:, :, 2] = CC
    np.clip(out, 0.0, 1.0, out=out)
    return _sm_scale(out, sm)
pearl_micro._spb_concept_complete = True


# ============================================================================
# 57. GOLD FLAKE â€” large sparse gold-leaf style irregular flakes
# ============================================================================

def gold_flake(shape, seed, sm, density1=0.35, density2=0.3):
    """gold_flake.

    identity: HAND-APPLIED gold-leaf finish â€” the HERO motif is a tessellation
    of irregular 18-30 px gold-leaf SQUARES with hairline gap-cracks between
    them (the signature of real gold leaf application), overlaid on five
    classical flake tiers: 1-2 px micro-shimmer dust, 2-4 px fine fragments,
    4-8 px primary foil chips, 8-14 px irregular leaf shards, and 6-12 px
    torn hairlines. The visible leaf-square tessellation is the diversifier
    vs plain gold flake â€” no other catalog entry shows the artisan tile grid
    that authentic gold-leaf application produces. Per-feature INDEPENDENT
    continuous M/R/CC.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 31151 + 9001)
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)

    # 1) Gold-leaning substrate
    base = _normalize(multi_scale_noise(shape, [2.0, 6.0, 14.0], [0.45, 0.35, 0.20], int(seed) + 11))
    M = (0.55 + (base - 0.5) * 0.28).astype(np.float32)
    R = (0.42 + (1.0 - base) * 0.22).astype(np.float32)
    CC = (0.38 + (base - 0.5) * 0.16).astype(np.float32)

    # 1b) HERO MOTIF â€” gold-leaf SQUARE TESSELLATION
    if _CV2_OK:
        leaf_size = max(18, int(24 * scale))
        # Jittered grid of square tiles with hairline gap cracks
        for gy in range(-leaf_size, h + leaf_size, leaf_size):
            for gx in range(-leaf_size, w + leaf_size, leaf_size):
                # Each square jitters position + rotates slightly + has its own chroma
                jx = gx + int(rng.uniform(-3, 3))
                jy = gy + int(rng.uniform(-3, 3))
                sz = leaf_size + int(rng.uniform(-3, 4))
                ang = float(rng.uniform(-12, 12))
                cx = jx + sz // 2; cy = jy + sz // 2
                box = ((cx, cy), (sz, sz), ang)
                pts = _cv2.boxPoints(box).astype(np.int32)
                # Per-tile independent chroma
                tM = float(rng.uniform(0.68, 0.97))
                tR = float(rng.uniform(0.10, 0.42))
                tCC = float(rng.uniform(0.08, 0.38))
                _cv2.fillConvexPoly(M, pts, tM, lineType=_cv2.LINE_AA)
                _cv2.fillConvexPoly(R, pts, tR, lineType=_cv2.LINE_AA)
                _cv2.fillConvexPoly(CC, pts, tCC, lineType=_cv2.LINE_AA)
                # HAIRLINE GAP CRACK â€” thin dark outline at tile boundary
                _cv2.polylines(M, [pts], True, float(rng.uniform(0.20, 0.40)), 1, lineType=_cv2.LINE_AA)
                _cv2.polylines(R, [pts], True, float(rng.uniform(0.55, 0.85)), 1, lineType=_cv2.LINE_AA)
                _cv2.polylines(CC, [pts], True, float(rng.uniform(0.50, 0.78)), 1, lineType=_cv2.LINE_AA)

    if _CV2_OK:
        # 2) Tier A â€” irregular leaf shards 8-14 px (was 6-18, slightly tighter, 1.6x count)
        n_shard = int(np.clip(3800 * (mn / 2048.0) ** 2, 1200, 9000))
        for _ in range(n_shard):
            cx = int(rng.uniform(2, w - 2)); cy = int(rng.uniform(2, h - 2))
            fw = int(max(3, rng.uniform(8.0, 14.0) * scale))
            fh = int(max(3, rng.uniform(8.0, 14.0) * scale))
            ang = float(rng.uniform(0, 180))
            box = ((cx, cy), (fw, fh), ang)
            pts = _cv2.boxPoints(box).astype(np.int32)
            _cv2.fillConvexPoly(M, pts, float(rng.uniform(0.70, 0.98)), lineType=_cv2.LINE_AA)
            _cv2.fillConvexPoly(R, pts, float(rng.uniform(0.06, 0.40)), lineType=_cv2.LINE_AA)
            _cv2.fillConvexPoly(CC, pts, float(rng.uniform(0.04, 0.32)), lineType=_cv2.LINE_AA)

        # 3) Tier B â€” primary 4-8 px foil chips (3x prior count, smaller)
        n_chip = int(np.clip(7800 * (mn / 2048.0) ** 2, 2400, 18000))
        for _ in range(n_chip):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            r = int(max(2, rng.uniform(2.0, 4.0) * scale))
            _cv2.circle(M, (cx, cy), r, float(rng.uniform(0.65, 0.97)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r, float(rng.uniform(0.06, 0.36)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r, float(rng.uniform(0.04, 0.30)), -1, lineType=_cv2.LINE_AA)

        # 4) Tier C â€” fine 2-4 px fragments (4x prior count)
        n_frag = int(np.clip(9000 * (mn / 2048.0) ** 2, 2800, 22000))
        for _ in range(n_frag):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            r = max(1, int(rng.uniform(1.0, 2.5) * scale))
            _cv2.circle(M, (cx, cy), r, float(rng.uniform(0.55, 0.94)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r, float(rng.uniform(0.10, 0.45)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r, float(rng.uniform(0.06, 0.36)), -1, lineType=_cv2.LINE_AA)

        # 5) Tier D â€” short torn hairlines 6-12 px (was 8-18)
        n_l = int(np.clip(2400 * (mn / 2048.0) ** 2, 800, 5500))
        for _ in range(n_l):
            cx = float(rng.uniform(4, w - 4)); cy = float(rng.uniform(4, h - 4))
            length = float(rng.uniform(6.0, 12.0) * scale)
            ang = float(rng.uniform(0, 2 * np.pi))
            x0 = int(cx - np.cos(ang) * length * 0.5); y0 = int(cy - np.sin(ang) * length * 0.5)
            x1 = int(cx + np.cos(ang) * length * 0.5); y1 = int(cy + np.sin(ang) * length * 0.5)
            _cv2.line(M, (x0, y0), (x1, y1), float(rng.uniform(0.30, 0.70)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(R, (x0, y0), (x1, y1), float(rng.uniform(0.35, 0.78)), 1, lineType=_cv2.LINE_AA)

    # 6) Tier E â€” ULTRA-DENSE pinpoint micro-shimmer dust
    n_dust = max(6000, int(h * w / 35))
    fy = rng.integers(0, h, n_dust); fx = rng.integers(0, w, n_dust)
    M[fy, fx] = np.maximum(M[fy, fx], rng.uniform(0.62, 0.98, n_dust).astype(np.float32))
    R[fy, fx] = np.minimum(R[fy, fx], rng.uniform(0.06, 0.28, n_dust).astype(np.float32))
    CC[fy, fx] = np.minimum(CC[fy, fx], rng.uniform(0.04, 0.22, n_dust).astype(np.float32))

    # 7) Substrate micro-pits
    n_pit = max(1500, int(h * w / 4000))
    py = rng.integers(0, h, n_pit); px = rng.integers(0, w, n_pit)
    M[py, px] = np.minimum(M[py, px], rng.uniform(0.08, 0.30, n_pit).astype(np.float32))
    R[py, px] = np.maximum(R[py, px], rng.uniform(0.55, 0.92, n_pit).astype(np.float32))

    out = np.stack([M, R, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
gold_flake._spb_concept_complete = True
# ============================================================================
# 58. BRUSHED SPARKLE â€” directional anisotropic noise + embedded sparkle points
# ============================================================================

def brushed_sparkle(shape, seed, sm, sparkle_density=0.002, **kwargs):
    """brushed_sparkle.

    identity: Brushed metal with TRIPLE signature â€” clearly visible horizontal
    grain DIRECTION (parallel scratch lines marching across the canvas) PAIRED
    with a heavy field of cross-shaped 4-armed sparkle stars, PLUS a HERO
    SUPERNOVA CONSTELLATION of 3-6 large 6-arm asterism stars with diffraction
    spike rays (the "wow" sparkles) clustered to break up the uniform field.
    Each star is a CROSS-HAIR (horizontal + vertical arms) and each supernova
    adds two extra diagonal rays for the asterism effect. Plain brushed has
    no cross-stars; plain sparkle has no aligned grain; only THIS one has
    both PLUS the hero asterism cluster.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 88105)
    scale = max(min(h, w) / 2048.0, 0.25)

    # GRAIN DIRECTION â€” strong horizontal striations (3 octaves)
    yy = np.arange(h, dtype=np.float32) / max(h - 1, 1)
    grain_row = (np.sin(yy * 130.0 * np.pi * 2.0) * 0.55 +
                 np.sin(yy * 280.0 * np.pi * 2.0 + rng.uniform(0, np.pi)) * 0.30 +
                 np.sin(yy * 560.0 * np.pi * 2.0 + rng.uniform(0, np.pi)) * 0.15)
    grain = grain_row[:, None] * np.ones((1, w), np.float32)
    fbm_M = _normalize(multi_scale_noise(shape, [3.5, 7.5, 15.0], [0.5, 0.3, 0.2], int(seed) + 211))
    fbm_R = _normalize(multi_scale_noise(shape, [3.5, 7.5, 15.0], [0.5, 0.3, 0.2], int(seed) + 212))
    fbm_CC = _normalize(multi_scale_noise(shape, [3.5, 7.5, 15.0], [0.5, 0.3, 0.2], int(seed) + 213))
    M = (0.58 + (fbm_M - 0.5) * 0.20 + grain * 0.12).astype(np.float32)
    R_ch = (0.36 + (fbm_R - 0.5) * 0.18 - grain * 0.10).astype(np.float32)
    CC = (0.50 + (fbm_CC - 0.5) * 0.20 + grain * 0.08).astype(np.float32)

    # HEAVY HORIZONTAL DRAG SCRATCHES â€” many short horizontal lines (grain)
    if _CV2_OK:
        n_drag = int(np.clip(h * w / 70, 3500, 16000))
        for _ in range(n_drag):
            cx = rng.uniform(2, w - 2); cy = rng.uniform(2, h - 2)
            length = float(rng.uniform(8.0, 18.0) * scale)
            ang = float(rng.normal(0.0, 0.04))  # near-horizontal
            x0s = int(cx - np.cos(ang) * length * 0.5); y0s = int(cy - np.sin(ang) * length * 0.5)
            x1s = int(cx + np.cos(ang) * length * 0.5); y1s = int(cy + np.sin(ang) * length * 0.5)
            _cv2.line(M, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.30, 0.90)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(R_ch, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.10, 0.42)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.30, 0.85)), 1, lineType=_cv2.LINE_AA)

        # CROSS-HAIR SPARKLE STARS â€” short horizontal + vertical glint per star.
        # This is the unmistakable sparkle signature.
        n_star = int(np.clip(h * w / 220, 600, 9000))
        for _ in range(n_star):
            cx = int(rng.integers(2, w - 2)); cy = int(rng.integers(2, h - 2))
            arm = max(2, int(rng.uniform(2.0, 4.5) * scale))
            star_M = float(rng.uniform(0.78, 0.99))
            star_R = float(rng.uniform(0.03, 0.18))
            star_CC = float(rng.uniform(0.70, 0.98))
            _cv2.line(M, (cx - arm, cy), (cx + arm, cy), star_M, 1, lineType=_cv2.LINE_AA)
            _cv2.line(M, (cx, cy - arm), (cx, cy + arm), star_M, 1, lineType=_cv2.LINE_AA)
            _cv2.line(R_ch, (cx - arm, cy), (cx + arm, cy), star_R, 1, lineType=_cv2.LINE_AA)
            _cv2.line(R_ch, (cx, cy - arm), (cx, cy + arm), star_R, 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (cx - arm, cy), (cx + arm, cy), star_CC, 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (cx, cy - arm), (cx, cy + arm), star_CC, 1, lineType=_cv2.LINE_AA)
            # Bright pinpoint at center for extra punch
            M[cy, cx] = max(M[cy, cx], 0.95)
            R_ch[cy, cx] = min(R_ch[cy, cx], 0.05)
            CC[cy, cx] = max(CC[cy, cx], 0.92)

        # HERO SUPERNOVA CONSTELLATION â€” 3-6 large 6-arm asterism stars with
        # diffraction spikes. The "wow" focal sparkles.
        n_super = int(rng.integers(3, 7))
        for _ in range(n_super):
            sx = int(rng.integers(int(w*0.10), int(w*0.90)))
            sy = int(rng.integers(int(h*0.10), int(h*0.90)))
            arm = max(5, int(rng.uniform(8.0, 16.0) * scale))
            sM = float(rng.uniform(0.85, 0.99))
            sR = float(rng.uniform(0.02, 0.10))
            sCC = float(rng.uniform(0.85, 0.99))
            # 6 arms: H, V, two diagonals
            _cv2.line(M, (sx-arm, sy), (sx+arm, sy), sM, 2, lineType=_cv2.LINE_AA)
            _cv2.line(M, (sx, sy-arm), (sx, sy+arm), sM, 2, lineType=_cv2.LINE_AA)
            _cv2.line(M, (sx-int(arm*0.7), sy-int(arm*0.7)), (sx+int(arm*0.7), sy+int(arm*0.7)), sM, 1, lineType=_cv2.LINE_AA)
            _cv2.line(M, (sx-int(arm*0.7), sy+int(arm*0.7)), (sx+int(arm*0.7), sy-int(arm*0.7)), sM, 1, lineType=_cv2.LINE_AA)
            _cv2.line(R_ch, (sx-arm, sy), (sx+arm, sy), sR, 2, lineType=_cv2.LINE_AA)
            _cv2.line(R_ch, (sx, sy-arm), (sx, sy+arm), sR, 2, lineType=_cv2.LINE_AA)
            _cv2.line(R_ch, (sx-int(arm*0.7), sy-int(arm*0.7)), (sx+int(arm*0.7), sy+int(arm*0.7)), sR, 1, lineType=_cv2.LINE_AA)
            _cv2.line(R_ch, (sx-int(arm*0.7), sy+int(arm*0.7)), (sx+int(arm*0.7), sy-int(arm*0.7)), sR, 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (sx-arm, sy), (sx+arm, sy), sCC, 2, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (sx, sy-arm), (sx, sy+arm), sCC, 2, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (sx-int(arm*0.7), sy-int(arm*0.7)), (sx+int(arm*0.7), sy+int(arm*0.7)), sCC, 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (sx-int(arm*0.7), sy+int(arm*0.7)), (sx+int(arm*0.7), sy-int(arm*0.7)), sCC, 1, lineType=_cv2.LINE_AA)
            # Bright bloom core
            _cv2.circle(M, (sx, sy), max(2, int(2.5*scale)), float(rng.uniform(0.90, 0.99)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (sx, sy), max(2, int(2.5*scale)), float(rng.uniform(0.90, 0.99)), -1, lineType=_cv2.LINE_AA)
            # Small companion sparkles in the constellation halo
            for _c in range(int(rng.integers(4, 9))):
                ox = sx + int(rng.uniform(-arm*2.5, arm*2.5))
                oy = sy + int(rng.uniform(-arm*2.5, arm*2.5))
                if 2 <= ox < w-2 and 2 <= oy < h-2:
                    carm = max(1, int(rng.uniform(2.0, 4.0) * scale))
                    cM_ = float(rng.uniform(0.70, 0.96))
                    _cv2.line(M, (ox-carm, oy), (ox+carm, oy), cM_, 1, lineType=_cv2.LINE_AA)
                    _cv2.line(M, (ox, oy-carm), (ox, oy+carm), cM_, 1, lineType=_cv2.LINE_AA)
                    _cv2.line(CC, (ox-carm, oy), (ox+carm, oy), float(rng.uniform(0.70, 0.95)), 1, lineType=_cv2.LINE_AA)
                    _cv2.line(CC, (ox, oy-carm), (ox, oy+carm), float(rng.uniform(0.70, 0.95)), 1, lineType=_cv2.LINE_AA)

    # BACKGROUND FLECKS â€” independent uniforms
    n_fl = int(np.clip(h * w / 130, 1200, 16000))
    fy = rng.integers(0, h, n_fl); fx = rng.integers(0, w, n_fl)
    M[fy, fx] = np.maximum(M[fy, fx], rng.uniform(0.45, 0.95, n_fl).astype(np.float32))
    R_ch[fy, fx] = np.minimum(R_ch[fy, fx], rng.uniform(0.05, 0.30, n_fl).astype(np.float32))
    CC[fy, fx] = np.maximum(CC[fy, fx], rng.uniform(0.40, 0.92, n_fl).astype(np.float32))
    out = np.stack([np.clip(M, 0, 1), np.clip(R_ch, 0, 1), np.clip(CC, 0, 1)], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
brushed_sparkle._spb_concept_complete = True


# ============================================================================
# 59. CRUSHED GLASS â€” jagged angular bright fragments via sharp thresholding
# ============================================================================

def crushed_glass(shape, seed, sm, threshold_hi=0.72, **kwargs):
    """crushed_glass.

    identity: An angular crushed-glass shard field on dark velvet â€” hard-
    thresholded sin-interference shards form the panel-fracture geometry,
    paired with many bright fracture-edge hairline glints (8-18 px),
    crowded micro chip dots (2-4 px), short jag scratches, and a fine
    sub-grain layer so the velvet substrate never reads blank. Distinct
    from prismatic_shatter by dark velvet background plus dense small
    chip coverage. Per-feature INDEPENDENT continuous M/R/CC.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + (hash("crushed_glass_r5") % 10000))
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)

    yy = np.arange(h, dtype=np.float32) / max(h, 1)
    xx = np.arange(w, dtype=np.float32) / max(w, 1)
    field = np.zeros(shape, dtype=np.float32)
    for _ in range(8):
        fy = rng.uniform(20, 80); fx = rng.uniform(20, 80)
        py = rng.uniform(0, 2 * np.pi); px = rng.uniform(0, 2 * np.pi)
        field += np.sin(yy[:, None] * fy * np.pi + py) * np.sin(xx[None, :] * fx * np.pi + px)
    field = _normalize(field)
    bright = (field > threshold_hi).astype(np.float32)

    fM = _normalize(multi_scale_noise(shape, [2.0, 5.0, 14.0], [0.45, 0.32, 0.23], int(seed) + 5904))
    fR = _normalize(multi_scale_noise(shape, [2.0, 5.0, 14.0], [0.45, 0.32, 0.23], int(seed) + 5905))
    fCC = _normalize(multi_scale_noise(shape, [2.0, 5.0, 14.0], [0.45, 0.32, 0.23], int(seed) + 5906))

    M = (0.18 + (fM - 0.5) * 0.20 + bright * (0.55 + (fM - 0.5) * 0.28)).astype(np.float32)
    R_ch = (0.68 - bright * (0.48 + (fR - 0.5) * 0.20) + (fR - 0.5) * 0.12).astype(np.float32)
    CC = (0.58 - bright * (0.32 + (fCC - 0.5) * 0.20) + (fCC - 0.5) * 0.12).astype(np.float32)

    if _CV2_OK:
        # FRACTURE EDGE GLINTS â€” 3x density
        n_edges = int(np.clip(2700 * (mn / 2048.0) ** 2, 900, 7000))
        for _ in range(n_edges):
            cx = float(rng.uniform(2, w - 2)); cy = float(rng.uniform(2, h - 2))
            length = rng.uniform(8.0, 18.0) * scale
            ang = rng.uniform(0, 2 * np.pi)
            x0s = int(cx - np.cos(ang) * length * 0.5)
            y0s = int(cy - np.sin(ang) * length * 0.5)
            x1s = int(cx + np.cos(ang) * length * 0.5)
            y1s = int(cy + np.sin(ang) * length * 0.5)
            _cv2.line(M, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.55, 0.97)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(R_ch, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.06, 0.30)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.08, 0.42)), 1, lineType=_cv2.LINE_AA)

        # MICRO CHIP DOTS â€” 3x density
        n_chip = int(np.clip(1800 * (mn / 2048.0) ** 2, 600, 5400))
        for _ in range(n_chip):
            cx = int(rng.uniform(0, w)); cy = int(rng.uniform(0, h))
            r = max(1, int(rng.uniform(1.0, 2.5) * scale))
            _cv2.circle(M, (cx, cy), r, float(rng.uniform(0.65, 0.98)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R_ch, (cx, cy), r, float(rng.uniform(0.05, 0.25)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r, float(rng.uniform(0.05, 0.25)), -1, lineType=_cv2.LINE_AA)

        # JAG SCRATCHES â€” angular 6-10 px
        n_jag = int(np.clip(1200 * (mn / 2048.0) ** 2, 400, 3600))
        for _ in range(n_jag):
            cx = float(rng.uniform(2, w - 2)); cy = float(rng.uniform(2, h - 2))
            length = float(rng.uniform(6.0, 10.0) * scale)
            ang = float(rng.choice([0.0, np.pi / 4, np.pi / 2, 3 * np.pi / 4])) + float(rng.normal(0, 0.18))
            x0s = int(cx - np.cos(ang) * length * 0.5)
            y0s = int(cy - np.sin(ang) * length * 0.5)
            x1s = int(cx + np.cos(ang) * length * 0.5)
            y1s = int(cy + np.sin(ang) * length * 0.5)
            _cv2.line(M, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.40, 0.85)), 1, lineType=_cv2.LINE_AA)

    # Accent fleck speckle (sub-grain) â€” fills velvet
    n_flecks = int(np.clip(2200 * (mn / 2048.0) ** 2, 800, 6000))
    fy2 = rng.integers(0, h, n_flecks); fx2 = rng.integers(0, w, n_flecks)
    M[fy2, fx2] = np.maximum(M[fy2, fx2], rng.uniform(0.40, 0.90, n_flecks).astype(np.float32))
    R_ch[fy2, fx2] = np.clip(R_ch[fy2, fx2] + rng.uniform(-0.20, 0.25, n_flecks).astype(np.float32), 0, 1)
    CC[fy2, fx2] = np.clip(CC[fy2, fx2] + rng.uniform(-0.20, 0.25, n_flecks).astype(np.float32), 0, 1)

    out = np.stack([M, R_ch, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
crushed_glass._spb_concept_complete = True


def prismatic_dust(shape, seed, sm, scatter_density=0.005, ring_freq=18.0, **kwargs):
    """prismatic_dust.

    identity: Round-6 creative rebuild â€” TRIANGULAR prism crystals are the
    HERO motif (not generic dust). Every triangle is a full RGB-split prism
    whose three corners take strongly contrasting M/R/CC values, so each
    crystal reads as a dichroic spectral splitter. Layered with: hex
    micro-flakes for chroma diversity, ringed rainbow halos with 3
    concentric bands that drift hue per band, double-bounce dichroic
    starbursts (4-pointed "X" pinpricks), and a full-canvas pinprick
    carpet. Fine features 1-12 px throughout â€” no panel-scale blobs.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + (hash("prismatic_dust_r6") % 10000))
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)

    # 1) Triple-channel substrate â€” strong chroma divergence between channels
    g_M = _normalize(multi_scale_noise((h, w), [2.0, 6.0, 16.0], [0.45, 0.32, 0.23], int(seed) + 91))
    g_R = _normalize(multi_scale_noise((h, w), [2.5, 7.0, 18.0], [0.45, 0.32, 0.23], int(seed) + 93))
    g_CC = _normalize(multi_scale_noise((h, w), [3.0, 8.0, 20.0], [0.45, 0.32, 0.23], int(seed) + 97))
    M = (0.40 + (g_M - 0.5) * 0.34).astype(np.float32)
    R = (0.46 + (g_R - 0.5) * 0.34).astype(np.float32)
    CC = (0.40 + (g_CC - 0.5) * 0.36).astype(np.float32)

    # 2) Pinprick carpet â€” vectorized base scatter
    n_dust = int(np.clip(13000 * (mn / 2048.0) ** 2, 4500, 26000))
    dx = rng.integers(0, w, n_dust); dy = rng.integers(0, h, n_dust)
    M[dy, dx] = np.maximum(M[dy, dx], rng.uniform(0.40, 0.99, n_dust).astype(np.float32))
    R[dy, dx] = np.minimum(R[dy, dx], rng.uniform(0.04, 0.36, n_dust).astype(np.float32))
    CC[dy, dx] = rng.uniform(0.05, 0.97, n_dust).astype(np.float32)

    if _CV2_OK:
        # 3) HERO â€” TRIANGULAR PRISM CRYSTALS with three-corner chroma split
        n_prisms = int(np.clip(2600 * (mn / 2048.0) ** 2, 900, 6000))
        for _ in range(n_prisms):
            cx = float(rng.uniform(5, w - 5)); cy = float(rng.uniform(5, h - 5))
            r = max(2.5, float(rng.uniform(2.5, 6.0) * scale))
            rot = float(rng.uniform(0, 2 * np.pi))
            # Three vertices of equilateral triangle
            v0 = (int(cx + r * np.cos(rot)), int(cy + r * np.sin(rot)))
            v1 = (int(cx + r * np.cos(rot + 2.094)), int(cy + r * np.sin(rot + 2.094)))
            v2 = (int(cx + r * np.cos(rot + 4.188)), int(cy + r * np.sin(rot + 4.188)))
            pts = np.array([v0, v1, v2], dtype=np.int32)
            # Each channel gets its own value â€” strongly varied for RGB-split look
            vM = float(rng.uniform(0.50, 0.99))
            vR = float(rng.uniform(0.05, 0.30))
            vCC = float(rng.uniform(0.20, 0.98))
            _cv2.fillPoly(M, [pts], vM, lineType=_cv2.LINE_AA)
            _cv2.fillPoly(R, [pts], vR, lineType=_cv2.LINE_AA)
            _cv2.fillPoly(CC, [pts], vCC, lineType=_cv2.LINE_AA)
            # Bright corner glint at one random vertex â€” adds dichroic edge
            cv = rng.choice([v0, v1, v2])
            _cv2.circle(CC, tuple(cv), 1, float(rng.uniform(0.85, 0.99)), -1, lineType=_cv2.LINE_AA)

        # 4) Concentric rainbow halos â€” 3 bands each, drifting per-band hue
        n_halos = int(np.clip(700 * (mn / 2048.0) ** 2, 250, 1800))
        for _ in range(n_halos):
            cx = int(rng.uniform(8, w - 8)); cy = int(rng.uniform(8, h - 8))
            r0 = max(2, int(rng.uniform(3.0, 6.0) * scale))
            for band_i in range(3):
                rr = r0 + band_i
                _cv2.circle(M, (cx, cy), rr, float(rng.uniform(0.42, 0.96)), 1, lineType=_cv2.LINE_AA)
                _cv2.circle(R, (cx, cy), rr, float(rng.uniform(0.06, 0.40)), 1, lineType=_cv2.LINE_AA)
                _cv2.circle(CC, (cx, cy), rr, float(rng.uniform(0.05, 0.95)), 1, lineType=_cv2.LINE_AA)

        # 5) Hex flakes â€” chroma diversity layer
        n_hex = int(np.clip(1500 * (mn / 2048.0) ** 2, 500, 3800))
        for _ in range(n_hex):
            cx = float(rng.uniform(4, w - 4)); cy = float(rng.uniform(4, h - 4))
            r = max(1.8, float(rng.uniform(2.0, 4.5) * scale))
            rot = float(rng.uniform(0, 2 * np.pi))
            pts = np.array([
                [int(cx + r * np.cos(rot + k * np.pi / 3.0)),
                 int(cy + r * np.sin(rot + k * np.pi / 3.0))]
                for k in range(6)
            ], dtype=np.int32)
            _cv2.fillPoly(M, [pts], float(rng.uniform(0.42, 0.96)), lineType=_cv2.LINE_AA)
            _cv2.fillPoly(R, [pts], float(rng.uniform(0.06, 0.42)), lineType=_cv2.LINE_AA)
            _cv2.fillPoly(CC, [pts], float(rng.uniform(0.04, 0.80)), lineType=_cv2.LINE_AA)

        # 6) Dichroic 4-pointed starbursts â€” X-shaped crystal pinpricks
        n_star = int(np.clip(2200 * (mn / 2048.0) ** 2, 800, 5200))
        for _ in range(n_star):
            cx = int(rng.uniform(3, w - 3)); cy = int(rng.uniform(3, h - 3))
            L = max(1, int(rng.uniform(2.0, 4.0) * scale))
            vM = float(rng.uniform(0.55, 0.99))
            vCC = float(rng.uniform(0.10, 0.95))
            # diagonal X
            _cv2.line(M, (cx - L, cy - L), (cx + L, cy + L), vM, 1, lineType=_cv2.LINE_AA)
            _cv2.line(M, (cx - L, cy + L), (cx + L, cy - L), vM, 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (cx - L, cy - L), (cx + L, cy + L), vCC, 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (cx - L, cy + L), (cx + L, cy - L), vCC, 1, lineType=_cv2.LINE_AA)

    out = np.stack([M, R, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
prismatic_dust._spb_concept_complete = True


# ============================================================================
# 61. CHEVRON BANDS â€” V-shaped horizontal bands
# ============================================================================

def chevron_bands(shape, seed, sm, num_bands=20, v_angle=0.6, palette_size=8):
    """chevron_bands â€” R6 CLEAN rebuild (owner 4/REBUILD, "too much noise").

    Owner directive: "Not clean enough - too much noise on this one."
    FIX: STRIP all the noise tiers (no per-pixel flecks, no random
    crosshatch, no zigzag hairlines, no pin-speck carpet). Keep ONLY
    the clean chevron band field + crisp rivet stitching at every
    apex. Result reads as industrial chevron tread-plate with bright
    rivets marching the centerline ridges â€” nothing else, no static.
    Per-band INDEPENDENT TIGHT-jittered M/R/CC from a single brushed-
    steel palette so the bands feel like one material catching light,
    not a Lisa Frank stripe.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 54311)
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)

    yy, xx = np.mgrid[0:h, 0:w].astype(np.float32)
    cx = w * 0.50
    effective_bands = max(int(num_bands) * 3, int(mn / 14.0))
    pitch = max(5.0, h / max(effective_bands, 1))
    # NO warp noise â€” keep chevron CLEAN
    coord = yy + np.abs(xx - cx) * v_angle
    band_idx = np.floor(coord / pitch).astype(np.int32)
    frac = (coord / pitch) - band_idx
    # Sharp triangle ridge profile
    stripe = 1.0 - np.abs(frac - 0.5) * 2.0
    ridge = np.clip((stripe - 0.55) / 0.45, 0, 1).astype(np.float32)
    # Soft pin glow along V centerline (every band)
    pin = np.exp(-((frac - 0.5) ** 2) / 0.0020).astype(np.float32)

    # TIGHT per-band chroma jitter from ONE brushed-steel base
    B_M, B_R, B_C = 0.58, 0.30, 0.40
    n_bands = int(band_idx.max() - band_idx.min() + 2)
    band_M = np.clip(B_M + rng.uniform(-0.05, 0.05, n_bands), 0, 1).astype(np.float32)
    band_R = np.clip(B_R + rng.uniform(-0.05, 0.05, n_bands), 0, 1).astype(np.float32)
    band_CC = np.clip(B_C + rng.uniform(-0.05, 0.05, n_bands), 0, 1).astype(np.float32)
    bi = (band_idx - band_idx.min()).astype(np.int32)
    parity = (bi % 2).astype(np.float32)
    # Alternate ridge / valley with a gentle highlight gradient
    M = (band_M[bi] * (0.55 + ridge * 0.45 * (0.7 + 0.6 * parity)) + pin * 0.18).astype(np.float32)
    R = (band_R[bi] * (1.0 - ridge * 0.30 * (0.7 + 0.4 * parity))).astype(np.float32)
    CC = (band_CC[bi] * (1.0 - ridge * 0.22 * (0.7 + 0.4 * parity)) + pin * 0.10).astype(np.float32)
    np.clip(M, 0, 1, out=M); np.clip(R, 0, 1, out=R); np.clip(CC, 0, 1, out=CC)

    if _CV2_OK:
        # RIVET-STITCH ROWS along V-tip ridge â€” bright paired pin dots
        band_min = int(band_idx.min()); band_max = int(band_idx.max())
        stitch_pitch = float(np.clip(8.0 * scale, 5.0, 14.0))
        tilt = v_angle
        for bi_val in range(band_min, band_max + 1, 1):
            # row chroma TIGHT jitter from steel base
            rv_M = float(np.clip(0.88 + rng.uniform(-0.04, 0.06), 0, 1))
            rv_R = float(np.clip(0.18 + rng.uniform(-0.04, 0.04), 0, 1))
            rv_CC = float(np.clip(0.50 + rng.uniform(-0.05, 0.05), 0, 1))
            n_stitches = int(np.clip(w / max(stitch_pitch, 1.0), 6, 180))
            for sk in range(n_stitches):
                ax = float(sk) * stitch_pitch
                for sign in (-1.0, 1.0):
                    xx_p = cx + sign * (ax - w * 0.5)
                    yy_p = (bi_val + 0.5) * pitch - abs(xx_p - cx) * tilt
                    cxp = int(np.clip(xx_p, 1, w - 2))
                    cyp = int(np.clip(yy_p, 1, h - 2))
                    rr = max(1, int(rng.uniform(1.0, 1.8) * scale))
                    _cv2.circle(M, (cxp, cyp), rr, rv_M, -1, lineType=_cv2.LINE_AA)
                    _cv2.circle(R, (cxp, cyp), rr, rv_R, -1, lineType=_cv2.LINE_AA)
                    _cv2.circle(CC, (cxp, cyp), rr, rv_CC, -1, lineType=_cv2.LINE_AA)
                    # Dark 1-px center (rivet hole)
                    _cv2.circle(M, (cxp, cyp), 1, 0.12, -1, lineType=_cv2.LINE_AA)

    out = np.stack([M, R, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)


chevron_bands._spb_concept_complete = True

# ============================================================================
# 62. WAVE BANDS â€” sinusoidal wavy horizontal bands
# ============================================================================

def wave_bands(shape, seed, sm, num_bands=18, wave_freq=5.0, wave_amp=0.025,
               palette_size=8):
    """wave_bands â€” R6 CREATIVE rebuild.

    identity: INTERFEROMETRIC WAVE BANDS â€” two analytic sinusoidal wave
    systems running at slightly different angles/frequencies (theta1 vs
    theta2) overlaid, producing BEAT-ZONE moire ridges where they
    constructively/destructively interfere. Hero motif: bright phosphor
    crests that bloom where waves stack, deep troughs between them.
    Stacked tiers: (1) cross-frequency analytic wave field on each M/R/CC
    channel (independent phases per channel), (2) ridge-detected crest
    sparkles (2-4 px) on top of constructive peaks, (3) chevron sub-
    pattern micro-dabs (4-9 px) seeded along crest lines, (4) tiny edge
    fizz droplets (1-2 px) scattered in troughs, (5) horizon FBM modulator
    breaking perfect symmetry. Per-feature INDEPENDENT continuous M/R/CC.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng2 = np.random.default_rng(int(seed) + 73111)
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)

    # 1) Two-wave interferometric field (analytic, vectorized)
    yy, xx = np.mgrid[0:h, 0:w].astype(np.float32)
    yn = yy / max(h - 1, 1); xn = xx / max(w - 1, 1)
    # Two slightly-different wave systems => beat zones
    theta1 = float(rng2.uniform(0.10, 0.55))
    theta2 = theta1 + float(rng2.uniform(0.12, 0.35))
    f1 = float(rng2.uniform(11.0, 16.0))  # cycles across canvas
    f2 = f1 * float(rng2.uniform(1.08, 1.22))
    # per-channel independent phases
    phM_1 = float(rng2.uniform(0, 2*np.pi)); phM_2 = float(rng2.uniform(0, 2*np.pi))
    phR_1 = float(rng2.uniform(0, 2*np.pi)); phR_2 = float(rng2.uniform(0, 2*np.pi))
    phC_1 = float(rng2.uniform(0, 2*np.pi)); phC_2 = float(rng2.uniform(0, 2*np.pi))

    u1 = xn * np.cos(theta1) + yn * np.sin(theta1)
    u2 = xn * np.cos(theta2) + yn * np.sin(theta2)

    waveM = 0.5 + 0.5 * np.sin(u1 * f1 * 2 * np.pi + phM_1) * np.sin(u2 * f2 * 2 * np.pi + phM_2)
    waveR = 0.5 + 0.5 * np.sin(u1 * f1 * 2 * np.pi + phR_1) * np.sin(u2 * f2 * 2 * np.pi + phR_2)
    waveC = 0.5 + 0.5 * np.sin(u1 * f1 * 2 * np.pi + phC_1) * np.sin(u2 * f2 * 2 * np.pi + phC_2)

    # FBM modulator to break perfect symmetry
    horizon = _normalize(multi_scale_noise(shape, [3.5, 9.0, 18.0], [0.45, 0.32, 0.20], int(seed) + 6299))

    M  = (0.30 + waveM * 0.55 + (horizon - 0.5) * 0.12).astype(np.float32)
    R_ch = (0.62 - waveR * 0.42 + (horizon - 0.5) * 0.08).astype(np.float32)
    CC = (0.55 - waveC * 0.40 + (horizon - 0.5) * 0.10).astype(np.float32)

    # 2) Crest-ridge detect â€” boolean mask of constructive peaks
    crest_mask = (waveM > 0.82) & (waveC > 0.78)

    if _CV2_OK:
        # 3) CREST SPARKLES â€” 2-4 px, on constructive peaks
        ys, xs = np.where(crest_mask)
        if ys.size > 0:
            pick = rng2.integers(0, ys.size, min(int(np.clip(2200 * (mn/2048.0)**2, 700, 5500)), ys.size))
            for idx in pick:
                cx = int(xs[idx]); cy = int(ys[idx])
                r = max(1, int(rng2.uniform(2.0, 4.0) * scale * 0.5))
                _cv2.circle(M,    (cx, cy), r, float(rng2.uniform(0.78, 0.99)), -1, lineType=_cv2.LINE_AA)
                _cv2.circle(R_ch, (cx, cy), r, float(rng2.uniform(0.04, 0.20)), -1, lineType=_cv2.LINE_AA)
                _cv2.circle(CC,   (cx, cy), r, float(rng2.uniform(0.04, 0.18)), -1, lineType=_cv2.LINE_AA)

        # 4) CHEVRON sub-pattern micro-dabs (4-9 px), drift along crest direction
        n_chev = int(np.clip(900 * (mn / 2048.0) ** 2, 320, 2400))
        # crest direction is perpendicular to mean of theta1/theta2
        crest_angle = (theta1 + theta2) * 0.5 + np.pi * 0.5
        for _ in range(n_chev):
            cx = float(rng2.uniform(3, w - 3)); cy = float(rng2.uniform(3, h - 3))
            length = float(rng2.uniform(4.0, 9.0) * scale)
            jitter = float(rng2.uniform(-0.25, 0.25))
            a = crest_angle + jitter
            # short V-chevron: two arms
            for sign in (-1.0, 1.0):
                x1 = int(np.clip(cx + np.cos(a + sign * 0.45) * length, 0, w - 1))
                y1 = int(np.clip(cy + np.sin(a + sign * 0.45) * length, 0, h - 1))
                _cv2.line(M,    (int(cx), int(cy)), (x1, y1), float(rng2.uniform(0.45, 0.92)), 1, lineType=_cv2.LINE_AA)
                _cv2.line(R_ch, (int(cx), int(cy)), (x1, y1), float(rng2.uniform(0.06, 0.30)), 1, lineType=_cv2.LINE_AA)
                _cv2.line(CC,   (int(cx), int(cy)), (x1, y1), float(rng2.uniform(0.05, 0.26)), 1, lineType=_cv2.LINE_AA)

    # 5) EDGE FIZZ â€” tiny 1 px droplets in troughs
    trough = (waveM < 0.18)
    ty, tx = np.where(trough)
    if ty.size > 0:
        n_fizz = min(int(np.clip(3800 * (mn / 2048.0) ** 2, 1200, 9000)), ty.size)
        pick2 = rng2.integers(0, ty.size, n_fizz)
        py = ty[pick2]; px = tx[pick2]
        M[py, px]    = np.maximum(M[py, px],    rng2.uniform(0.40, 0.92, n_fizz).astype(np.float32))
        R_ch[py, px] = np.minimum(R_ch[py, px], rng2.uniform(0.05, 0.24, n_fizz).astype(np.float32))
        CC[py, px]   = np.minimum(CC[py, px],   rng2.uniform(0.05, 0.22, n_fizz).astype(np.float32))

    # 6) global flecks for chroma breakup
    n_flecks = int(np.clip(2200 * (mn / 2048.0) ** 2, 800, 5500))
    fx = rng2.integers(0, w, n_flecks); fy = rng2.integers(0, h, n_flecks)
    M[fy, fx]    = np.maximum(M[fy, fx],    rng2.uniform(0.55, 0.97, n_flecks).astype(np.float32))
    R_ch[fy, fx] = np.minimum(R_ch[fy, fx], rng2.uniform(0.05, 0.28, n_flecks).astype(np.float32))
    CC[fy, fx]   = np.minimum(CC[fy, fx],   rng2.uniform(0.04, 0.22, n_flecks).astype(np.float32))

    out = np.stack([M, R_ch, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
wave_bands._spb_concept_complete = True
# ============================================================================
# 63. GRADIENT BANDS â€” bands with internal bright-to-dark gradient
# ============================================================================

def gradient_bands(shape, seed, sm, num_bands=16, palette_size=6):
    """gradient_bands.

    identity: R6 creative rebuild â€” an IRIDESCENT oil-slick stratification.
    Diagonal angled fine banding (8-14 px each) with per-channel phase-shifted
    chroma waves so the bands gradient through gold, teal, magenta, indigo
    like a fuel-puddle rainbow. HERO MOTIF: 12-22 floating "BUBBLE CAUSTICS"
    â€” bright AA rings 10-26 px scattered across the canvas as if surface
    tension is lifting the iridescent skin. Per-band INDEPENDENT continuous
    M/R/CC. Fine 2-4 px shimmer flecks, 1 px sparkles, and dark grain spots
    between bands. Diagonal axis breaks symmetry â€” not a flat horizontal sweep.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 11277)
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)

    # DIAGONAL axis for bands â€” breaks horizontal-stripe symmetry
    theta = float(rng.uniform(0.18, 0.55))
    yy, xx = np.mgrid[0:h, 0:w].astype(np.float32)
    axis = (xx * np.cos(theta) + yy * np.sin(theta))
    axis_n = (axis - float(axis.min())) / max(float(axis.max() - axis.min()), 1.0)

    # Band pitch â€” bands 8-14 px tall along diagonal
    band_pitch = float(rng.uniform(10.0, 16.0))
    band_idx = (axis / band_pitch).astype(np.int32)
    n_b = int(band_idx.max() - band_idx.min()) + 4
    band_M = rng.uniform(0.32, 0.96, n_b).astype(np.float32)
    band_R = rng.uniform(0.08, 0.62, n_b).astype(np.float32)
    band_CC = rng.uniform(0.28, 0.94, n_b).astype(np.float32)
    bo = np.clip(band_idx - int(band_idx.min()), 0, n_b - 1)
    pM = band_M[bo]
    pR = band_R[bo]
    pCC = band_CC[bo]

    # Per-channel phase-shifted iridescent chroma along the diagonal axis
    irM  = (np.sin(axis_n * np.pi * 3.0 + 0.0) * 0.5 + 0.5).astype(np.float32)
    irR  = (np.sin(axis_n * np.pi * 3.0 + 2.094) * 0.5 + 0.5).astype(np.float32)
    irCC = (np.sin(axis_n * np.pi * 3.0 + 4.188) * 0.5 + 0.5).astype(np.float32)

    grain = _normalize(multi_scale_noise(shape, [2.0, 6.0, 14.0], [0.45, 0.35, 0.20], int(seed) + 632))
    M  = (pM * 0.70 + irM * 0.25 + (grain - 0.5) * 0.10).astype(np.float32)
    R  = (pR * 0.70 + irR * 0.18 + (1.0 - grain) * 0.10).astype(np.float32)
    CC = (pCC * 0.70 + irCC * 0.25 + (grain - 0.5) * 0.08).astype(np.float32)

    if _CV2_OK:
        # HERO MOTIF â€” BUBBLE CAUSTICS â€” 12-22 floating bright AA rings
        n_bub = int(rng.integers(14, 24))
        for _ in range(n_bub):
            bx = int(rng.uniform(0.04, 0.96) * w)
            by = int(rng.uniform(0.04, 0.96) * h)
            br = int(rng.uniform(10.0, 26.0) * scale)
            # bright ring
            _cv2.circle(M, (bx, by), br, float(rng.uniform(0.78, 0.99)), 2, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (bx, by), br, float(rng.uniform(0.04, 0.18)), 2, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (bx, by), br, float(rng.uniform(0.75, 0.98)), 2, lineType=_cv2.LINE_AA)
            # inner sheen ring (thinner)
            _cv2.circle(M, (bx, by), max(2, br - 4), float(rng.uniform(0.50, 0.72)), 1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (bx, by), max(2, br - 4), float(rng.uniform(0.55, 0.80)), 1, lineType=_cv2.LINE_AA)
            # tiny lit highlight at top-left of bubble
            hlx = int(bx - br * 0.45); hly = int(by - br * 0.45)
            _cv2.circle(M, (hlx, hly), max(1, int(2 * scale)), 0.99, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (hlx, hly), max(1, int(2 * scale)), 0.99, -1, lineType=_cv2.LINE_AA)

        # FINE shimmer ribbons 4-10 px running along band axis
        n_rib = int(np.clip(4500 * (mn / 2048.0) ** 2, 1400, 11000))
        for _ in range(n_rib):
            cxv = float(rng.uniform(4, w - 4)); cyv = float(rng.uniform(2, h - 2))
            length = float(rng.uniform(4.0, 10.0) * scale)
            ang = theta + np.pi * 0.5 + float(rng.normal(0, 0.12))  # along band, not across
            x0 = int(cxv - np.cos(ang) * length * 0.5); y0 = int(cyv - np.sin(ang) * length * 0.5)
            x1 = int(cxv + np.cos(ang) * length * 0.5); y1 = int(cyv + np.sin(ang) * length * 0.5)
            _cv2.line(M, (x0, y0), (x1, y1), float(rng.uniform(0.28, 0.96)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(R, (x0, y0), (x1, y1), float(rng.uniform(0.08, 0.55)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (x0, y0), (x1, y1), float(rng.uniform(0.06, 0.55)), 1, lineType=_cv2.LINE_AA)

        # Cross-strands 3-7 px perpendicular for crosshatch
        n_cr = int(np.clip(1600 * (mn / 2048.0) ** 2, 500, 3600))
        for _ in range(n_cr):
            cxv = float(rng.uniform(4, w - 4)); cyv = float(rng.uniform(4, h - 4))
            length = float(rng.uniform(3.0, 7.0) * scale)
            ang = theta + float(rng.normal(0, 0.12))
            x0 = int(cxv - np.cos(ang) * length * 0.5); y0 = int(cyv - np.sin(ang) * length * 0.5)
            x1 = int(cxv + np.cos(ang) * length * 0.5); y1 = int(cyv + np.sin(ang) * length * 0.5)
            _cv2.line(M, (x0, y0), (x1, y1), float(rng.uniform(0.18, 0.55)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (x0, y0), (x1, y1), float(rng.uniform(0.30, 0.72)), 1, lineType=_cv2.LINE_AA)

        # Sheen dots 2-4 px scattered
        n_d = int(np.clip(2000 * (mn / 2048.0) ** 2, 600, 4800))
        for _ in range(n_d):
            cxv = int(rng.integers(0, w)); cyv = int(rng.integers(0, h))
            r = int(max(1, rng.uniform(2.0, 4.0) * scale))
            _cv2.circle(M, (cxv, cyv), r, float(rng.uniform(0.55, 0.96)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cxv, cyv), r, float(rng.uniform(0.08, 0.42)), -1, lineType=_cv2.LINE_AA)

    # 1-px sparkle flecks
    n_f = max(2000, int(h * w / 3200))
    fy = rng.integers(0, h, n_f); fx = rng.integers(0, w, n_f)
    M[fy, fx] = np.maximum(M[fy, fx], rng.uniform(0.55, 0.96, n_f).astype(np.float32))
    R[fy, fx] = np.minimum(R[fy, fx], rng.uniform(0.08, 0.28, n_f).astype(np.float32))

    # Dark grain dots between bands
    n_dk = max(1200, int(h * w / 6000))
    dy = rng.integers(0, h, n_dk); dx = rng.integers(0, w, n_dk)
    M[dy, dx] = np.minimum(M[dy, dx], rng.uniform(0.08, 0.26, n_dk).astype(np.float32))
    R[dy, dx] = np.maximum(R[dy, dx], rng.uniform(0.55, 0.90, n_dk).astype(np.float32))

    out = np.stack([M, R, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
gradient_bands._spb_concept_complete = True
# ============================================================================
# 64. SPLIT BANDS â€” alternating thick/thin bands with different intensities
# ============================================================================

def split_bands(shape, seed, sm, num_pairs=12, ratio=3.0,
                thick_bright=0.85, thin_bright=0.25, warp_strength=0.04):
    """split_bands -- R6 tick51 second-pass with PERFORATION HOLE-PUNCH hero.

    identity: A racing-livery surface where each panel is "split" by paired
    bright/dark band families - razor-cut chevron CUT-OUTS gouge across the
    bands at ~30 deg, revealing a glossier under-stripe inside the cut.
    NEW TICK-51 HERO MOTIF: PERFORATION HOLE-PUNCH ROWS â€” tiny 3-5 px
    bright AA donut rings arranged in evenly-pitched dotted rows running
    along the thin/seam bands, like body-trim perforated tape stitched
    through the livery (each donut has dark center + bright rim). Seven
    stacked tiers: (1) base bands packed h/36 pitch with per-stripe
    INDEPENDENT M/R/CC; (2) razor-cut chevron cut-outs revealing bright
    under-stripe; (3) NEW perforation hole-punch rows 3-5 px donuts in
    18-26 dotted rows; (4) angled splice hairlines 5-11 px; (5) pigment
    microbeads 2-3 px; (6) dark grit dots 1-2 px; (7) sparkle floor.
    WIDE per-feature continuous M/R/CC chroma.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 88599)
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)

    yy, xx = np.mgrid[0:h, 0:w].astype(np.float32)
    pairs = max(int(num_pairs) * 3, int(mn / 36.0))
    unit = max(2.0, h / max(pairs * (ratio + 1.0), 1.0))
    warp = (np.sin(xx / max(w, 1) * np.pi * float(rng.uniform(4.0, 8.0)) + float(seed)) +
            np.sin(xx / max(w, 1) * np.pi * float(rng.uniform(10.0, 18.0)) + float(seed) * 0.13) * 0.35) * warp_strength * h
    coord = yy + warp
    cycle = np.mod(coord, unit * (ratio + 1.0))
    thick_mask = (cycle < unit * ratio).astype(np.float32)
    edge_dist = np.minimum(np.abs(cycle - unit * ratio), np.minimum(cycle, unit * (ratio + 1.0) - cycle)) / max(unit, 1.0)
    seam = np.exp(-(edge_dist ** 2) / 0.010).astype(np.float32)

    stripe_idx = np.floor(coord / max(unit * (ratio + 1.0), 1.0)).astype(np.int32)
    n_stripes = int(stripe_idx.max() - stripe_idx.min() + 2)
    base = int(stripe_idx.min())
    stripe_M = rng.uniform(0.22, 0.97, n_stripes).astype(np.float32)
    stripe_R = rng.uniform(0.04, 0.62, n_stripes).astype(np.float32)
    stripe_CC = rng.uniform(0.05, 0.92, n_stripes).astype(np.float32)
    idx_norm = stripe_idx - base
    pM = stripe_M[idx_norm]
    pR = stripe_R[idx_norm]
    pCC = stripe_CC[idx_norm]

    fbm_m = _normalize(multi_scale_noise(shape, [2.0, 6.0, 16.0], [0.5, 0.3, 0.2], int(seed) + 6431))
    fbm_r = _normalize(multi_scale_noise(shape, [2.5, 7.0, 17.0], [0.5, 0.3, 0.2], int(seed) + 6437))
    fbm_c = _normalize(multi_scale_noise(shape, [3.0, 8.0, 19.0], [0.5, 0.3, 0.2], int(seed) + 6441))

    M = (thick_mask * pM + (1.0 - thick_mask) * (pM * 0.18 + 0.06) + (fbm_m - 0.5) * 0.10).astype(np.float32)
    R = (thick_mask * pR + (1.0 - thick_mask) * (pR + 0.30) + (fbm_r - 0.5) * 0.08).astype(np.float32)
    CC = (thick_mask * pCC + (1.0 - thick_mask) * (pCC * 0.30 + 0.15) + (fbm_c - 0.5) * 0.10).astype(np.float32)
    M -= seam * 0.22
    R += seam * 0.26
    CC -= seam * 0.16

    if _CV2_OK:
        # --- NEW TICK-51 HERO: PERFORATION HOLE-PUNCH ROWS ---
        # Dotted rows of tiny donuts running along seam bands (dark center,
        # bright rim) â€” like body-trim perforated tape stitched through livery
        n_rows = int(rng.integers(18, 27))
        for _ in range(n_rows):
            row_y = float(rng.uniform(4, h - 4))
            row_ang = float(np.deg2rad(rng.uniform(-3.0, 3.0)))  # near-horizontal
            dot_pitch = float(rng.uniform(7.0, 12.0) * scale)
            n_dots = int(np.clip(w / max(dot_pitch, 1.0), 8, 240))
            row_M = float(rng.uniform(0.65, 0.97))
            row_R = float(rng.uniform(0.04, 0.18))
            row_CC = float(rng.uniform(0.20, 0.82))
            ring_r = max(2, int(rng.uniform(2.0, 3.0) * scale))
            for k in range(n_dots):
                dx0 = float(k) * dot_pitch + float(rng.uniform(-0.4, 0.4))
                dy0 = row_y + np.sin(row_ang) * dx0
                cx_d = int(np.clip(dx0, 1, w - 2))
                cy_d = int(np.clip(dy0, 1, h - 2))
                # Bright rim
                _cv2.circle(M, (cx_d, cy_d), ring_r, row_M + float(rng.uniform(-0.05, 0.02)), 1, lineType=_cv2.LINE_AA)
                _cv2.circle(R, (cx_d, cy_d), ring_r, row_R + float(rng.uniform(-0.02, 0.04)), 1, lineType=_cv2.LINE_AA)
                _cv2.circle(CC, (cx_d, cy_d), ring_r, row_CC + float(rng.uniform(-0.06, 0.06)), 1, lineType=_cv2.LINE_AA)
                # Dark punch center (1 px)
                _cv2.circle(M, (cx_d, cy_d), 1, float(rng.uniform(0.05, 0.18)), -1, lineType=_cv2.LINE_AA)
                _cv2.circle(R, (cx_d, cy_d), 1, float(rng.uniform(0.55, 0.88)), -1, lineType=_cv2.LINE_AA)

        # --- HERO: razor-cut chevron cut-outs revealing glossy under-stripe ---
        n_chev = int(rng.integers(14, 27))
        for _ in range(n_chev):
            cx = float(rng.uniform(20, w - 20)); cy = float(rng.uniform(20, h - 20))
            arm_len = float(rng.uniform(16.0, 26.0) * scale)
            thick = max(2, int(rng.uniform(3.0, 5.5) * scale))
            tilt = float(rng.choice([1.0, -1.0])) * float(np.deg2rad(rng.uniform(25, 38)))
            # Two arms of the chevron, sharing a tip
            tip_x, tip_y = cx, cy
            for side in (-1, 1):
                ex = int(tip_x + np.cos(tilt) * arm_len * side)
                ey = int(tip_y + np.sin(tilt) * arm_len)
                # Under-stripe glossy fill
                _cv2.line(M, (int(tip_x), int(tip_y)), (ex, ey),
                          float(rng.uniform(0.80, 0.99)), thick, lineType=_cv2.LINE_AA)
                _cv2.line(R, (int(tip_x), int(tip_y)), (ex, ey),
                          float(rng.uniform(0.03, 0.16)), thick, lineType=_cv2.LINE_AA)
                _cv2.line(CC, (int(tip_x), int(tip_y)), (ex, ey),
                          float(rng.uniform(0.74, 0.98)), thick, lineType=_cv2.LINE_AA)
                # Rim-bright edge highlight (thinner, brighter on M, lower R)
                _cv2.line(M, (int(tip_x), int(tip_y)), (ex, ey),
                          float(rng.uniform(0.92, 0.99)), 1, lineType=_cv2.LINE_AA)
                _cv2.line(R, (int(tip_x), int(tip_y)), (ex, ey),
                          float(rng.uniform(0.02, 0.10)), 1, lineType=_cv2.LINE_AA)

        # Angled splice hairlines 5-11 px - livery tape edges
        n_splice = int(np.clip(2200 * (mn / 2048.0) ** 2, 800, 5200))
        for _ in range(n_splice):
            cx_b = float(rng.uniform(4, w - 4)); cy_b = float(rng.uniform(4, h - 4))
            length_b = float(rng.uniform(5.0, 11.0)) * scale
            ang_b = float(rng.choice([np.deg2rad(30), np.deg2rad(-30), 0.0])) + float(rng.normal(0.0, 0.10))
            x0b = int(cx_b - np.cos(ang_b) * length_b * 0.5); y0b = int(cy_b - np.sin(ang_b) * length_b * 0.5)
            x1b = int(cx_b + np.cos(ang_b) * length_b * 0.5); y1b = int(cy_b + np.sin(ang_b) * length_b * 0.5)
            _cv2.line(M, (x0b, y0b), (x1b, y1b), float(rng.uniform(0.40, 0.96)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(R, (x0b, y0b), (x1b, y1b), float(rng.uniform(0.05, 0.32)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (x0b, y0b), (x1b, y1b), float(rng.uniform(0.08, 0.75)), 1, lineType=_cv2.LINE_AA)

        # Pigment microbeads 2-3 px along stripe centerlines
        n_pig = int(np.clip(2200 * (mn / 2048.0) ** 2, 700, 5400))
        for _ in range(n_pig):
            cx_b = int(rng.integers(0, w)); cy_b = int(rng.integers(0, h))
            r_b = max(1, int(float(rng.uniform(1.2, 2.5)) * scale))
            _cv2.circle(M, (cx_b, cy_b), r_b, float(rng.uniform(0.42, 0.96)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx_b, cy_b), r_b, float(rng.uniform(0.06, 0.40)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx_b, cy_b), r_b, float(rng.uniform(0.10, 0.85)), -1, lineType=_cv2.LINE_AA)

        # Grit dots 1-2 px
        n_dk = int(np.clip(1600 * (mn / 2048.0) ** 2, 500, 3800))
        for _ in range(n_dk):
            cx_b = int(rng.integers(0, w)); cy_b = int(rng.integers(0, h))
            r_b = max(1, int(float(rng.uniform(1.0, 2.0)) * scale))
            _cv2.circle(M, (cx_b, cy_b), r_b, float(rng.uniform(0.05, 0.24)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx_b, cy_b), r_b, float(rng.uniform(0.55, 0.94)), -1, lineType=_cv2.LINE_AA)

    n_fl = int(np.clip(2600 * (mn / 2048.0) ** 2, 900, 6200))
    fy = rng.integers(0, h, n_fl); fx = rng.integers(0, w, n_fl)
    M[fy, fx] = np.maximum(M[fy, fx], rng.uniform(0.48, 0.96, n_fl).astype(np.float32))
    R[fy, fx] = np.minimum(R[fy, fx], rng.uniform(0.04, 0.28, n_fl).astype(np.float32))
    CC[fy, fx] = np.maximum(CC[fy, fx], rng.uniform(0.14, 0.82, n_fl).astype(np.float32))

    out = np.stack([np.clip(M, 0, 1), np.clip(R, 0, 1), np.clip(CC, 0, 1)], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
split_bands._spb_concept_complete = True
# ============================================================================
# 65. DIAGONAL BANDS â€” 45-degree angled bands
# ============================================================================

def diagonal_bands(shape, seed, sm, **kwargs):
    """diagonal_bands â€” R6-Loop second-pass creative refinement (tick 81).

    identity: NEW HERO â€” fashion-print TARTAN-WEAVE tape: warp 9-13 px
    diagonal ribbons at +30 deg are now CROSSED by a perpendicular weft
    set at -60 deg with the SAME pitch, giving woven plaid intersections.
    At every crossing a small 3-5 px square knot bead. Single STORM
    BLUE-GREY palette (M_base=0.22, R_base=0.30, CC_base=0.48 â€” composite
    reads cool blue-grey) with TIGHT +-0.05 per-feature jitter. Hero
    additions: (a) houndstooth notch-corner cutouts every 5 warp bands
    where the diagonal silhouette breaks into stepped triangles, (b) frayed
    thread strands (3-7 px) escaping band edges. Dressed with dense glint
    flecks aligned to weave axis and perpendicular nick dots.

    TICK-81 SECOND-PASS HERO: CHLADNI NODAL CURVES â€” an analytic
    standing-wave interference field cos(k*x)*cos(k*y) - cos(k*y)*cos(k*x)
    rendered as bright nodal-line ridges crossing the tartan plaid like
    a violin-plate sand pattern frozen onto the fabric. Pulls the eye
    away from pure grid and adds physics-print intrigue.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + (hash("diagonal_bands_r6loop_t156") % 10000))
    scale = max(min(h, w) / 2048.0, 0.25)
    yy = np.arange(h, dtype=np.float32)[:, None]
    xx = np.arange(w, dtype=np.float32)[None, :]

    # STORM BLUE-GREY palette: M low, R mid, CC mid-high
    M_BASE, R_BASE, CC_BASE = 0.22, 0.30, 0.48
    JIT = 0.05

    # WARP (+30) and WEFT (-60) axes â€” tartan crossing
    ang_warp = np.deg2rad(30.0)
    ang_weft = np.deg2rad(-60.0)
    ca_wa, sa_wa = float(np.cos(ang_warp)), float(np.sin(ang_warp))
    ca_we, sa_we = float(np.cos(ang_weft)), float(np.sin(ang_weft))
    u_warp = xx * ca_wa + yy * sa_wa
    u_weft = xx * ca_we + yy * sa_we

    # Substrate FBM
    bM = _normalize(multi_scale_noise(shape, [2.4, 7.0, 16.0], [0.5, 0.3, 0.2], int(seed) + 311))
    bR = _normalize(multi_scale_noise(shape, [2.4, 7.0, 16.0], [0.5, 0.3, 0.2], int(seed) + 312))
    bC = _normalize(multi_scale_noise(shape, [2.4, 7.0, 16.0], [0.5, 0.3, 0.2], int(seed) + 313))
    M = (M_BASE + (bM - 0.5) * 0.10).astype(np.float32)
    R = (R_BASE + (bR - 0.5) * 0.10).astype(np.float32)
    CC = (CC_BASE + (bC - 0.5) * 0.10).astype(np.float32)

    pitch = max(9.0, 11.0 * scale)

    # WARP RIBBONS â€” tight sine-modulated, tight chroma from base
    warp_phase = (u_warp / pitch) - np.floor(u_warp / pitch)  # 0..1
    warp_band = np.floor(u_warp / pitch).astype(np.int32)
    warp_groove = np.sin(warp_phase * 2.0 * np.pi)
    # Slight per-band offset table (tight)
    TABLE = 1024
    warp_jit_M = rng.uniform(-JIT, JIT, TABLE).astype(np.float32)
    warp_jit_R = rng.uniform(-JIT, JIT, TABLE).astype(np.float32)
    warp_jit_CC = rng.uniform(-JIT, JIT, TABLE).astype(np.float32)
    hidx_w = ((warp_band.astype(np.int64) * 73856093) ^ np.int64(int(seed) * 83492791)) & (TABLE - 1)
    hidx_w = hidx_w.astype(np.int32)
    warp_strength = np.clip(warp_groove * 0.5 + 0.5, 0, 1)
    M = np.clip(M + warp_jit_M[hidx_w] + warp_strength * 0.20, 0, 1)
    R = np.clip(R + warp_jit_R[hidx_w] - warp_strength * 0.10, 0, 1)
    CC = np.clip(CC + warp_jit_CC[hidx_w] + warp_strength * 0.18, 0, 1)

    # WEFT RIBBONS â€” perpendicular crossing
    weft_phase = (u_weft / pitch) - np.floor(u_weft / pitch)
    weft_band = np.floor(u_weft / pitch).astype(np.int32)
    weft_groove = np.sin(weft_phase * 2.0 * np.pi)
    weft_jit_M = rng.uniform(-JIT, JIT, TABLE).astype(np.float32)
    weft_jit_CC = rng.uniform(-JIT, JIT, TABLE).astype(np.float32)
    hidx_we = ((weft_band.astype(np.int64) * 19349663) ^ np.int64(int(seed) * 83492791)) & (TABLE - 1)
    hidx_we = hidx_we.astype(np.int32)
    weft_strength = np.clip(weft_groove * 0.5 + 0.5, 0, 1)
    # Weft alternates over/under via parity for woven look
    over = ((warp_band + weft_band) % 2 == 0).astype(np.float32)
    M = np.clip(M + (weft_jit_M[hidx_we] + weft_strength * 0.18) * over, 0, 1)
    CC = np.clip(CC + (weft_jit_CC[hidx_we] + weft_strength * 0.14) * over, 0, 1)
    R = np.clip(R - weft_strength * 0.06 * over, 0, 1)

    # CROSSING-KNOT BEADS â€” small 3-5 px squares where warp & weft crest
    knot_mask = (warp_strength > 0.78) & (weft_strength > 0.78)
    # Sample knot centers
    knot_y, knot_x = np.where(knot_mask)
    if knot_y.size > 0:
        step = max(1, knot_y.size // 2000)
        ks = slice(0, None, step)
        kM = np.clip(M_BASE + rng.uniform(-JIT, JIT, knot_y[ks].shape).astype(np.float32) + 0.32, 0, 1)
        kCC = np.clip(CC_BASE + rng.uniform(-JIT, JIT, knot_y[ks].shape).astype(np.float32) + 0.28, 0, 1)
        M[knot_y[ks], knot_x[ks]] = kM
        CC[knot_y[ks], knot_x[ks]] = kCC

    if _CV2_OK:
        # HOUNDSTOOTH NOTCH CUTOUTS â€” every 5 warp bands, stepped triangles
        houndstooth_period = 5
        n_notch = int(np.clip(220 * (min(h, w) / 256.0) ** 2, 120, 800))
        for _ in range(n_notch):
            bx = int(rng.uniform(0, w)); by = int(rng.uniform(0, h))
            # Only place on every-5th band
            band_here = int(((bx * ca_wa + by * sa_wa) / pitch))
            if band_here % houndstooth_period != 0:
                continue
            # Stepped triangle notch
            sz = max(3, int(rng.uniform(3.0, 6.0) * scale))
            pts = np.array([
                [bx, by],
                [bx + sz, by],
                [bx + sz, by + sz],
                [bx + sz * 2, by + sz],
                [bx + sz * 2, by + sz * 2],
            ], dtype=np.int32).reshape((-1, 1, 2))
            mv = float(np.clip(M_BASE + rng.uniform(-JIT, JIT) + 0.30, 0.05, 0.95))
            cv = float(np.clip(CC_BASE + rng.uniform(-JIT, JIT) + 0.22, 0.05, 0.95))
            _cv2.polylines(M, [pts], False, mv, 1, lineType=_cv2.LINE_AA)
            _cv2.polylines(CC, [pts], False, cv, 1, lineType=_cv2.LINE_AA)

        # FRAYED THREAD STRANDS â€” 3-7 px escaping band edges
        n_fray = int(np.clip(900 * (min(h, w) / 256.0) ** 2, 400, 2400))
        for _ in range(n_fray):
            cx = float(rng.uniform(2, w - 2)); cy = float(rng.uniform(2, h - 2))
            length = float(rng.uniform(3.0, 7.0) * scale)
            a = (ang_warp if rng.random() < 0.5 else ang_weft) + float(rng.normal(0.0, 0.30))
            x0s = int(cx); y0s = int(cy)
            x1s = int(cx + np.cos(a) * length); y1s = int(cy + np.sin(a) * length)
            mv = float(np.clip(M_BASE + rng.uniform(-JIT, JIT) + 0.18, 0.05, 0.95))
            cv = float(np.clip(CC_BASE + rng.uniform(-JIT, JIT) + 0.10, 0.05, 0.95))
            _cv2.line(M, (x0s, y0s), (x1s, y1s), mv, 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (x0s, y0s), (x1s, y1s), cv, 1, lineType=_cv2.LINE_AA)

        # NICK DOTS â€” tiny perpendicular marks
        n_dot = int(np.clip(700 * (min(h, w) / 256.0) ** 2, 300, 2000))
        for _ in range(n_dot):
            cxd = int(rng.integers(0, w)); cyd = int(rng.integers(0, h))
            r = max(1, int(rng.uniform(1.0, 2.0) * scale))
            mv = float(np.clip(M_BASE + rng.uniform(-JIT, JIT) + 0.30, 0.05, 0.95))
            _cv2.circle(M, (cxd, cyd), r, mv, -1, lineType=_cv2.LINE_AA)

    # GLINT FLECKS â€” vectorized, tight jitter
    n_fl = int(np.clip(2200 * (min(h, w) / 256.0) ** 2, 1200, 6500))
    fy = rng.integers(0, h, n_fl); fx = rng.integers(0, w, n_fl)
    M[fy, fx] = np.clip(M_BASE + rng.uniform(-JIT, JIT, n_fl).astype(np.float32) + 0.34, 0, 1)
    CC[fy, fx] = np.clip(CC_BASE + rng.uniform(-JIT, JIT, n_fl).astype(np.float32) + 0.18, 0, 1)

    # TICK-81 HERO: CHLADNI NODAL CURVES â€” analytic standing-wave interference.
    # Field f(x,y) = cos(kx*x)*cos(ky*y) - cos(ky*x)*cos(kx*y). The nodal set
    # |f| < eps is a curving lacework of lines that doesn't coincide with the
    # plaid grid, breaking up the tartan with a physics motif.
    kx_pix = 2.0 * np.pi * float(rng.uniform(2.6, 3.4)) / max(min(h, w), 1)
    ky_pix = 2.0 * np.pi * float(rng.uniform(3.6, 4.6)) / max(min(h, w), 1)
    chl = (np.cos(kx_pix * xx) * np.cos(ky_pix * yy)
           - np.cos(ky_pix * xx) * np.cos(kx_pix * yy)).astype(np.float32)
    nodal = (np.abs(chl) < 0.06).astype(np.float32)
    if nodal.any():
        # Bright nodal ridges â€” cool palette boost on CC, slight M lift.
        node_lift = nodal * 0.32
        M = np.clip(M + node_lift * 0.55, 0, 1)
        CC = np.clip(CC + node_lift * 0.95, 0, 1)
        R = np.clip(R - node_lift * 0.18, 0, 1)
        # Per-pixel chroma jitter sprinkled along the nodal lines (cool tints).
        ny_idx, nx_idx = np.where(nodal > 0.5)
        if ny_idx.size > 0:
            step = max(1, ny_idx.size // 1400)
            ks = slice(0, None, step)
            CC[ny_idx[ks], nx_idx[ks]] = np.clip(
                CC_BASE + rng.uniform(-JIT, JIT, ny_idx[ks].shape).astype(np.float32) + 0.36, 0, 1)

    out = np.stack([M, R, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
diagonal_bands._spb_concept_complete = True

def brushed_linear(shape, seed, sm, frequency=80.0, phase_noise=0.02, **kwargs):
    """brushed_linear -- tick51 second-pass adds SCANLINE GLOW BARS hero.

    identity: Purely HORIZONTAL brushed metal panel (LINEAR axis differentiator
    vs brushed_diagonal). Every stroke runs +/-5 deg of true horizontal.
    TICK-51 NEW HERO: SCANLINE GLOW BARS â€” 3-5 wide horizontal bright
    caustic stripes (4-7 px tall, full-canvas width) blooming at random
    y-positions, like a CRT scanline catching the brushed metal sheen.
    Each scanline gets bright M crest + low R + boosted CC + soft 2 px
    falloff halo above/below, INDEPENDENT continuous M/R/CC per scanline.
    Eight stacked tiers: (0) NEW scanline glow bars; (1) horizontal sine
    grain at 1-2 px pitch over metal FBM substrate; (2) three horizontal
    grit bands with +/-5 deg drift (multi-pass mill); (3) dense 4-10 px
    horizontal micro striations; (4) 8-16 px drag marks horizontal;
    (5) horizontal polish ribbons 2-3 px tall x 30-60 px; (6) bright
    pixel flecks; (7) dark pit specks. Per-feature INDEPENDENT M/R/CC.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + (hash("brushed_linear_r5") % 10000))
    scale = max(min(h, w) / 2048.0, 0.25)

    fM  = _normalize(multi_scale_noise(shape, [3.0, 7.0, 14.0], [0.5, 0.3, 0.2], int(seed) + 711))
    fR  = _normalize(multi_scale_noise(shape, [3.0, 7.0, 14.0], [0.5, 0.3, 0.2], int(seed) + 712))
    fCC = _normalize(multi_scale_noise(shape, [3.0, 7.0, 14.0], [0.5, 0.3, 0.2], int(seed) + 713))
    M    = (0.58 + (fM  - 0.5) * 0.24).astype(np.float32)
    R_ch = (0.38 + (fR  - 0.5) * 0.24).astype(np.float32)
    CC   = (0.50 + (fCC - 0.5) * 0.24).astype(np.float32)

    # 1) CONTINUOUS HORIZONTAL FINE GRAIN â€” 1-2 px pitch, pure horizontal
    yy = np.arange(h, dtype=np.float32)[:, None]
    grain = (np.sin(yy * (2 * np.pi / 1.9)) * 0.5 +
             np.sin(yy * (2 * np.pi / 1.1) + rng.uniform(0, np.pi)) * 0.3).astype(np.float32)
    grain = np.broadcast_to(grain, (h, w))
    M = np.clip(M + grain * 0.16, 0, 1)
    R_ch = np.clip(R_ch - grain * 0.09, 0, 1)
    CC = np.clip(CC - grain * 0.07, 0, 1)

    # 2) THREE HORIZONTAL MILL BANDS â€” each its own micro-drift within +/-5 deg
    band_angles = rng.uniform(-0.087, 0.087, 3).astype(np.float32)  # +/-5 deg in radians
    band_edges = [0, h // 3, 2 * h // 3, h]

    # TICK-51 NEW HERO â€” SCANLINE GLOW BARS â€” 3-5 wide horizontal bright
    # caustic stripes blooming across the canvas like CRT scanlines.
    n_scan = int(rng.integers(3, 6))
    yy_full = np.arange(h, dtype=np.float32)[:, None]
    for _ in range(n_scan):
        sc_y = float(rng.uniform(0.06, 0.94) * h)
        sc_thk = float(rng.uniform(4.0, 7.0) * scale)
        # Gaussian falloff band (vectorized)
        falloff = np.exp(-((yy_full - sc_y) ** 2) / (2.0 * sc_thk * sc_thk)).astype(np.float32)
        sc_M = float(rng.uniform(0.78, 0.99))
        sc_R = float(rng.uniform(0.04, 0.16))
        sc_CC = float(rng.uniform(0.20, 0.78))
        # Lift M, depress R, boost CC where scanline is brightest
        M = np.clip(M + falloff * (sc_M - 0.50) * 0.85, 0, 1)
        R_ch = np.clip(R_ch - falloff * (0.50 - sc_R) * 0.55, 0, 1)
        CC = np.clip(CC + falloff * (sc_CC - 0.40) * 0.45, 0, 1)

    if _CV2_OK:
        # 3) DENSE MICRO-STRIATIONS â€” 4-10 px, horizontal-only
        n_str = int(np.clip(h * w / 11, 25000, 110000))
        sxs = rng.uniform(2, w - 2, n_str); sys = rng.uniform(2, h - 2, n_str)
        # bucket by horizontal band
        band_idx = np.zeros(n_str, dtype=np.int32)
        for bi in range(3):
            band_idx[(sys >= band_edges[bi]) & (sys < band_edges[bi + 1])] = bi
        lengths = rng.uniform(4.0, 10.0, n_str) * scale
        angs = band_angles[band_idx] + rng.normal(0.0, 0.03, n_str)  # tight horizontal
        bm = rng.uniform(0.12, 0.96, n_str).astype(np.float32)
        br = rng.uniform(0.05, 0.42, n_str).astype(np.float32)
        bc = rng.uniform(0.05, 0.52, n_str).astype(np.float32)
        for i in range(n_str):
            x0s = int(sxs[i] - np.cos(angs[i]) * lengths[i] * 0.5)
            y0s = int(sys[i] - np.sin(angs[i]) * lengths[i] * 0.5)
            x1s = int(sxs[i] + np.cos(angs[i]) * lengths[i] * 0.5)
            y1s = int(sys[i] + np.sin(angs[i]) * lengths[i] * 0.5)
            _cv2.line(M, (x0s, y0s), (x1s, y1s), float(bm[i]), 1, lineType=_cv2.LINE_AA)
            _cv2.line(R_ch, (x0s, y0s), (x1s, y1s), float(br[i]), 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (x0s, y0s), (x1s, y1s), float(bc[i]), 1, lineType=_cv2.LINE_AA)

        # 4) DRAG MARKS â€” 8-16 px, horizontal
        n_drag = int(np.clip(h * w / 950, 700, 6500))
        for _ in range(n_drag):
            cx = rng.uniform(4, w - 4); cy = rng.uniform(4, h - 4)
            yi = int(np.clip(cy, 0, h - 1))
            bi = 0 if yi < band_edges[1] else (1 if yi < band_edges[2] else 2)
            length = float(rng.uniform(8.0, 16.0) * scale)
            a = float(band_angles[bi]) + float(rng.normal(0.0, 0.025))
            x0s = int(cx - np.cos(a) * length * 0.5); y0s = int(cy - np.sin(a) * length * 0.5)
            x1s = int(cx + np.cos(a) * length * 0.5); y1s = int(cy + np.sin(a) * length * 0.5)
            tw = int(rng.choice([1, 1, 2]))
            _cv2.line(M, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.10, 0.98)), tw, lineType=_cv2.LINE_AA)
            _cv2.line(R_ch, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.05, 0.32)), tw, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.06, 0.40)), tw, lineType=_cv2.LINE_AA)

        # 5) POLISH RIBBONS â€” NEW horizontal bright bands 30-60 px x 2-3 px
        n_rib = int(np.clip(h * w / 4200, 200, 1400))
        for _ in range(n_rib):
            cy = float(rng.uniform(0, h))
            cx = float(rng.uniform(0, w))
            length = float(rng.uniform(30.0, 60.0) * scale)
            thick = int(rng.choice([2, 3]))
            a = float(rng.uniform(-0.04, 0.04))
            x0s = int(cx - np.cos(a) * length * 0.5); y0s = int(cy - np.sin(a) * length * 0.5)
            x1s = int(cx + np.cos(a) * length * 0.5); y1s = int(cy + np.sin(a) * length * 0.5)
            _cv2.line(M, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.70, 0.98)), thick, lineType=_cv2.LINE_AA)
            _cv2.line(R_ch, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.04, 0.20)), thick, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.08, 0.45)), thick, lineType=_cv2.LINE_AA)

    # 6) BRIGHT PIXEL FLECKS
    n_fl = int(np.clip(h * w / 32, 5500, 44000))
    fy = rng.integers(0, h, n_fl); fx = rng.integers(0, w, n_fl)
    M[fy, fx] = np.maximum(M[fy, fx], rng.uniform(0.45, 0.97, n_fl).astype(np.float32))
    R_ch[fy, fx] = np.minimum(R_ch[fy, fx], rng.uniform(0.04, 0.22, n_fl).astype(np.float32))

    # 7) DARK PIT SPECKS â€” micro-pitting in troughs
    n_pit = int(np.clip(h * w / 110, 1800, 14000))
    py = rng.integers(0, h, n_pit); px = rng.integers(0, w, n_pit)
    M[py, px] = np.minimum(M[py, px], rng.uniform(0.14, 0.38, n_pit).astype(np.float32))
    R_ch[py, px] = np.maximum(R_ch[py, px], rng.uniform(0.42, 0.78, n_pit).astype(np.float32))

    out = np.stack([np.clip(M, 0, 1), np.clip(R_ch, 0, 1), np.clip(CC, 0, 1)], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)


brushed_linear._spb_concept_complete = True


def brushed_diagonal(shape, seed, sm, **kwargs):
    """Brushed diagonal â€” DAMASCUS-FOLDED diagonal with HERO WATERED WAVE BANDS.

    identity: ONE pass at 45 degrees with DAMASCUS-FOLDED-STEEL CHARACTER.
    Every visible stroke aligns to a single chosen diagonal (45 or 135).
    HERO MOTIF #1: Damascus watered-wave ribbon bands (12-26 px wide
    diagonal stripes of contrasting roughness/clearcoat) sweeping across
    the canvas â€” each band carries an INTERNAL turbulent watered grain
    (sinusoidal modulation along its length) giving the layered pattern-
    welded-steel character. HERO MOTIF #2: scattered MOKUME-GANE
    'pool-and-eye' polish marks (16-22 px elliptical inclusions, 10-18
    of them) â€” places where the folded steel layers expose a cross-
    section eye. Stacked: hero damascus bands, mokume eyes, continuous
    45-deg sine grain, dense 8-18 px primary strokes, 4-9 px sub-
    strokes, bright 1-2 px crest sparkles riding ONLY along the diagonal
    grain. Per-stroke INDEPENDENT continuous M/R/CC.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + (hash("brushed_diagonal_r5") % 10000))
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)
    # ONE diagonal direction â€” either +45 or -45, locked
    sign = 1.0 if rng.random() < 0.5 else -1.0
    angle = float(np.deg2rad(45.0 * sign + rng.uniform(-3.0, 3.0)))
    ca = np.cos(angle); sa = np.sin(angle)

    # 45-deg pure projection
    yy = np.arange(h, dtype=np.float32)
    xx = np.arange(w, dtype=np.float32)
    proj_d = (yy[:, None] * sa + xx[None, :] * ca).astype(np.float32)

    # Continuous 45-deg grain â€” multi-octave at 1-3 px pitch
    pitch_a = float(rng.uniform(2.5, 3.5))
    pitch_b = pitch_a * 0.55
    pitch_c = pitch_a * 0.30
    diag = (np.sin(proj_d * (2 * np.pi / pitch_a)) * 0.5 +
            np.sin(proj_d * (2 * np.pi / pitch_b) + rng.uniform(0, np.pi)) * 0.3 +
            np.sin(proj_d * (2 * np.pi / pitch_c) + rng.uniform(0, np.pi)) * 0.2).astype(np.float32)
    crest = np.clip((diag - 0.78) * 5.5, 0, 1).astype(np.float32)

    fbm_M = _normalize(multi_scale_noise(shape, [3.0, 7.0, 14.0], [0.5, 0.3, 0.2], int(seed) + 811))
    fbm_R = _normalize(multi_scale_noise(shape, [3.0, 7.0, 14.0], [0.5, 0.3, 0.2], int(seed) + 812))
    fbm_CC = _normalize(multi_scale_noise(shape, [3.0, 7.0, 14.0], [0.5, 0.3, 0.2], int(seed) + 813))
    M    = 0.58 + (fbm_M  - 0.5) * 0.16 + diag * 0.11 + crest * 0.22
    R_ch = 0.38 + (fbm_R  - 0.5) * 0.16 - diag * 0.10 - crest * 0.18
    CC   = 0.48 + (fbm_CC - 0.5) * 0.16 + diag * 0.08 + crest * 0.20

    # HERO TIER 0 â€” RIBBON BANDS. Wide diagonal stripes at the locked angle.
    # Use the projection 'proj_d' (already aligned to angle) to define stripe
    # boundaries â€” bands are regions where proj_d falls within chosen intervals.
    proj_min = float(proj_d.min()); proj_max = float(proj_d.max())
    span = max(proj_max - proj_min, 1.0)
    n_bands = int(rng.integers(4, 8))
    # Random non-overlapping interval picks
    band_starts = sorted([float(rng.uniform(0.0, 1.0)) for _ in range(n_bands)])
    for bs in band_starts:
        bw = float(rng.uniform(0.05, 0.13))  # band width as fraction of span
        lo = proj_min + bs * span
        hi = lo + bw * span
        # Soft-edged mask via smooth saturation
        edge_soft = max(2.5 * scale, 1.5)
        mask = np.clip((proj_d - lo) / edge_soft, 0, 1) * np.clip((hi - proj_d) / edge_soft, 0, 1)
        mask = (mask * 4.0).clip(0, 1).astype(np.float32)
        # NEW: internal DAMASCUS watered-wave grain INSIDE the band.
        # Use a perpendicular axis (along-band coord) to modulate the band's
        # interior so each band reads as a layered folded-steel ribbon.
        # perp_axis = projection along the band-tangent direction
        perp_axis = (yy[:, None] * ca - xx[None, :] * sa).astype(np.float32)
        wave_pitch = float(rng.uniform(11.0, 19.0))
        watered = (np.sin(perp_axis * (2 * np.pi / wave_pitch) + rng.uniform(0, np.pi)) * 0.5 +
                   np.sin(perp_axis * (2 * np.pi / (wave_pitch * 0.55)) + rng.uniform(0, np.pi)) * 0.3).astype(np.float32)
        # Independent continuous M/R/CC for THIS band
        bm = float(rng.uniform(0.30, 0.92))
        br = float(rng.uniform(0.08, 0.55))
        bc = float(rng.uniform(0.25, 0.95))
        strength = float(rng.uniform(0.35, 0.62))
        band_apply = mask * strength
        M    = M    * (1.0 - band_apply) + (bm + watered * 0.14) * band_apply
        R_ch = R_ch * (1.0 - band_apply) + (br - watered * 0.06) * band_apply
        CC   = CC   * (1.0 - band_apply) + (bc + watered * 0.12) * band_apply

    # HERO MOTIF #2 â€” MOKUME-GANE 'pool-and-eye' polish marks.
    # 10-18 elliptical inclusions where the folded steel layers expose
    # a cross-section eye, scattered across the canvas.
    if _CV2_OK:
        sc_eye = max(min(h, w) / 512.0, 0.5)
        n_eyes = int(rng.integers(10, 19))
        for _ in range(n_eyes):
            ecx = float(rng.uniform(0.06, 0.94) * w)
            ecy = float(rng.uniform(0.06, 0.94) * h)
            er_long = float(rng.uniform(10.0, 14.0) * sc_eye)
            er_short = er_long * float(rng.uniform(0.45, 0.70))
            # eye rotation ALIGNED to diagonal axis for cohesion
            eye_ang = np.degrees(angle) + float(rng.uniform(-12, 12))
            em_body = float(rng.uniform(0.62, 0.88))
            er_body = float(rng.uniform(0.10, 0.30))
            ec_body = float(rng.uniform(0.45, 0.85))
            _cv2.ellipse(M, (int(ecx), int(ecy)), (int(er_long), int(er_short)), eye_ang, 0, 360, em_body, -1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(R_ch, (int(ecx), int(ecy)), (int(er_long), int(er_short)), eye_ang, 0, 360, er_body, -1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(CC, (int(ecx), int(ecy)), (int(er_long), int(er_short)), eye_ang, 0, 360, ec_body, -1, lineType=_cv2.LINE_AA)
            # concentric inner-ring (the cross-section "eye" ring)
            inner = max(2, int(er_short * 0.55))
            _cv2.ellipse(M, (int(ecx), int(ecy)), (int(er_long * 0.55), inner), eye_ang, 0, 360, min(0.96, em_body + 0.18), 1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(CC, (int(ecx), int(ecy)), (int(er_long * 0.55), inner), eye_ang, 0, 360, min(0.98, ec_body + 0.15), 1, lineType=_cv2.LINE_AA)
            # dark eye-spot pinpoint center
            _cv2.circle(M, (int(ecx), int(ecy)), max(1, int(er_short * 0.25)), 0.20, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R_ch, (int(ecx), int(ecy)), max(1, int(er_short * 0.25)), 0.70, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (int(ecx), int(ecy)), max(1, int(er_short * 0.25)), 0.15, -1, lineType=_cv2.LINE_AA)

    if _CV2_OK:
        # TIER 1 â€” dense 8-18 px primary 45-deg strokes
        n_pri = int(np.clip(4200 * (mn / 2048.0) ** 2, 1700, 12000))
        for _ in range(n_pri):
            cx = float(rng.uniform(2, w - 2)); cy = float(rng.uniform(2, h - 2))
            length = float(rng.uniform(8.0, 18.0) * scale)
            # tiny jitter ONLY around the locked diagonal
            ang_use = angle + float(rng.normal(0.0, 0.03))
            dx = np.cos(ang_use) * length * 0.5; dy = np.sin(ang_use) * length * 0.5
            x0s = int(cx - dx); y0s = int(cy - dy)
            x1s = int(cx + dx); y1s = int(cy + dy)
            _cv2.line(M,    (x0s, y0s), (x1s, y1s), float(rng.uniform(0.50, 0.96)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(R_ch, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.06, 0.34)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC,   (x0s, y0s), (x1s, y1s), float(rng.uniform(0.20, 0.55)), 1, lineType=_cv2.LINE_AA)

        # TIER 2 â€” short 4-9 px sub-strokes, still 45-deg
        n_sub = int(np.clip(3000 * (mn / 2048.0) ** 2, 1200, 8500))
        for _ in range(n_sub):
            cx = float(rng.uniform(2, w - 2)); cy = float(rng.uniform(2, h - 2))
            length = float(rng.uniform(4.0, 9.0) * scale)
            ang_use = angle + float(rng.normal(0.0, 0.04))
            dx = np.cos(ang_use) * length * 0.5; dy = np.sin(ang_use) * length * 0.5
            x0s = int(cx - dx); y0s = int(cy - dy)
            x1s = int(cx + dx); y1s = int(cy + dy)
            _cv2.line(M,    (x0s, y0s), (x1s, y1s), float(rng.uniform(0.45, 0.92)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(R_ch, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.10, 0.40)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC,   (x0s, y0s), (x1s, y1s), float(rng.uniform(0.22, 0.60)), 1, lineType=_cv2.LINE_AA)

    # TIER 3 â€” sparkle only on diagonal crests
    n_fl = int(np.clip(h * w / 110, 1200, 16000))
    fy = rng.integers(0, h, n_fl); fx = rng.integers(0, w, n_fl)
    crest_at = crest[fy, fx]
    sel = (crest_at > 0.20) | (rng.random(n_fl) < 0.35)
    if np.any(sel):
        yi = fy[sel]; xi = fx[sel]
        M[yi, xi]    = np.maximum(M[yi, xi],    rng.uniform(0.55, 0.99, yi.size).astype(np.float32))
        R_ch[yi, xi] = np.minimum(R_ch[yi, xi], rng.uniform(0.05, 0.30, yi.size).astype(np.float32))
        CC[yi, xi]   = np.maximum(CC[yi, xi],   rng.uniform(0.20, 0.92, yi.size).astype(np.float32))
    out = np.stack([M, R_ch, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
brushed_diagonal._spb_concept_complete = True


def brushed_cross(shape, seed, sm, **kwargs):
    """Brushed cross â€” TWO perpendicular grains + HERO ENGINE-TURNED ROSETTES.

    identity: Scotch-brite finished with TWO distinct passes â€” one horizontal
    pass and one vertical pass as separate strata, PLUS the HERO diversifier:
    a scattered field of 8-14 ENGINE-TURNED ROSETTES (jeweled-spot circles
    18-26 px each, the watchmaker's mark from a rotating abrasive tool)
    overlaid on the cross-hatch. Each rosette has its own clockwise polish
    spiral inside. Catch nodes glint at H/V intersections; short cross
    hatch scratch dashes fill gaps. Per-stroke INDEPENDENT continuous M/R/CC
    keeps the two grain directions chromatically distinct. The rosette
    field is the differentiator vs all other brushed/cross-hatch patterns.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + (hash("brushed_cross_r6_jewel") % 10000))
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)

    fbm_M = _normalize(multi_scale_noise(shape, [3.0, 7.0, 14.0], [0.5, 0.3, 0.2], int(seed) + 901))
    fbm_R = _normalize(multi_scale_noise(shape, [3.5, 8.0, 16.0], [0.5, 0.3, 0.2], int(seed) + 902))
    fbm_CC = _normalize(multi_scale_noise(shape, [4.0, 9.0, 18.0], [0.5, 0.3, 0.2], int(seed) + 903))
    M = 0.58 + (fbm_M - 0.5) * 0.18
    R_ch = 0.36 + (fbm_R - 0.5) * 0.18
    CC = 0.50 + (fbm_CC - 0.5) * 0.18

    # Continuous H/V grain via projection sines (pure horizontal + pure vertical)
    yy = np.arange(h, dtype=np.float32)
    xx = np.arange(w, dtype=np.float32)
    # Horizontal pass (varies in Y): 1-2 px pitch
    h_pitch = float(rng.uniform(2.4, 3.4))
    h_grain = (np.sin(yy * (2 * np.pi / h_pitch)) * 0.6 +
               np.sin(yy * (2 * np.pi / (h_pitch * 0.55)) + rng.uniform(0, np.pi)) * 0.4)[:, None]
    # Vertical pass (varies in X): independent pitch so the two grains don't moire
    v_pitch = float(rng.uniform(2.6, 3.6))
    v_grain = (np.sin(xx * (2 * np.pi / v_pitch)) * 0.6 +
               np.sin(xx * (2 * np.pi / (v_pitch * 0.55)) + rng.uniform(0, np.pi)) * 0.4)[None, :]
    h_grain = h_grain.astype(np.float32); v_grain = v_grain.astype(np.float32)

    # H pass gets warm chroma, V pass gets cool chroma â€” distinct passes
    M    = M    + h_grain * 0.14 + v_grain * 0.05
    R_ch = R_ch - h_grain * 0.06 - v_grain * 0.10
    CC   = CC   + h_grain * 0.04 + v_grain * 0.14

    # Catch-node glints where both grains crest
    catch = np.clip((h_grain * v_grain) + 0.35, 0, 1) ** 4
    M    = M    + catch * 0.18
    R_ch = R_ch - catch * 0.15
    CC   = CC   + catch * 0.20

    if _CV2_OK:
        # TIER A â€” explicit horizontal stroke field (8-18 px, exactly horizontal)
        n_h = int(np.clip(3200 * (mn / 2048.0) ** 2, 1300, 9000))
        for _ in range(n_h):
            cx = float(rng.uniform(2, w - 2)); cy = float(rng.uniform(2, h - 2))
            length = float(rng.uniform(8.0, 18.0) * scale)
            jit = float(rng.uniform(-0.05, 0.05))  # tiny waver only
            x0s = int(cx - length * 0.5); y0s = int(cy + jit)
            x1s = int(cx + length * 0.5); y1s = int(cy + jit)
            # Horizontal pass chroma palette (warm/bright M)
            _cv2.line(M,    (x0s, y0s), (x1s, y1s), float(rng.uniform(0.55, 0.96)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(R_ch, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.08, 0.32)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC,   (x0s, y0s), (x1s, y1s), float(rng.uniform(0.18, 0.55)), 1, lineType=_cv2.LINE_AA)

        # TIER B â€” explicit vertical stroke field (8-18 px, exactly vertical)
        n_v = int(np.clip(3200 * (mn / 2048.0) ** 2, 1300, 9000))
        for _ in range(n_v):
            cx = float(rng.uniform(2, w - 2)); cy = float(rng.uniform(2, h - 2))
            length = float(rng.uniform(8.0, 18.0) * scale)
            jit = float(rng.uniform(-0.05, 0.05))
            x0s = int(cx + jit); y0s = int(cy - length * 0.5)
            x1s = int(cx + jit); y1s = int(cy + length * 0.5)
            # Vertical pass chroma (cool/distinct from horizontal)
            _cv2.line(M,    (x0s, y0s), (x1s, y1s), float(rng.uniform(0.40, 0.85)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(R_ch, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.20, 0.50)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC,   (x0s, y0s), (x1s, y1s), float(rng.uniform(0.45, 0.92)), 1, lineType=_cv2.LINE_AA)

        # TIER C â€” short cross-hatch scratch dashes 4-8 px (at exact 0/90)
        n_sc = int(np.clip(1600 * (mn / 2048.0) ** 2, 600, 4800))
        for _ in range(n_sc):
            cx = int(rng.integers(2, w - 2)); cy = int(rng.integers(2, h - 2))
            length = int(rng.uniform(4.0, 8.0) * scale)
            is_h = rng.random() < 0.5
            if is_h:
                p0 = (cx - length // 2, cy); p1 = (cx + length // 2, cy)
            else:
                p0 = (cx, cy - length // 2); p1 = (cx, cy + length // 2)
            _cv2.line(M,    p0, p1, float(rng.uniform(0.55, 0.95)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(R_ch, p0, p1, float(rng.uniform(0.06, 0.32)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC,   p0, p1, float(rng.uniform(0.20, 0.55)), 1, lineType=_cv2.LINE_AA)

    # Grit flecks
    n_fl = int(np.clip(h * w / 110, 1200, 16000))
    fy = rng.integers(0, h, n_fl); fx = rng.integers(0, w, n_fl)
    M[fy, fx]    = np.maximum(M[fy, fx],    rng.uniform(0.50, 0.96, n_fl).astype(np.float32))
    R_ch[fy, fx] = np.minimum(R_ch[fy, fx], rng.uniform(0.05, 0.30, n_fl).astype(np.float32))
    CC[fy, fx]   = np.maximum(CC[fy, fx],   rng.uniform(0.20, 0.92, n_fl).astype(np.float32))

    # R6 OWNER REBUILD 2026-05-26: owner LIKED the bidirectional cross-brushed
    # look but HATED the engine-turned rosette circles. REMOVED rosettes;
    # ADDED explicit "+" cross marks scattered across canvas so the pattern
    # reads as CROSS-pattern, not generic bidirectional brushing.
    # HERO MOTIF â€” EXPLICIT "+" CROSS MARKS (100-200 of them, 8-16 px each).
    # Owner phrasing: "I REALLY like the effect in general but hate the
    # circles and there should be more crosses prominent throughout".
    if _CV2_OK:
        # Cohesive brushed-steel palette base for the cross marks. TIGHT
        # Â±0.04-0.06 jitter per cross from this base (not Lisa-Frank rolls).
        BASE_M, BASE_R, BASE_CC = 0.78, 0.18, 0.55
        n_cross = int(np.clip(160 * (mn / 256.0) ** 2, 100, 200))
        for _ in range(n_cross):
            cx = int(rng.uniform(0.04, 0.96) * w)
            cy = int(rng.uniform(0.04, 0.96) * h)
            half_len = int(rng.uniform(4, 8) * max(scale, 1.0))  # 8-16 px total cross arm
            half_len = max(3, min(half_len, 12))
            arm_w = max(1, int(rng.uniform(1, 2)))
            cM = float(np.clip(BASE_M + rng.uniform(-0.05, 0.05), 0, 1))
            cR = float(np.clip(BASE_R + rng.uniform(-0.04, 0.04), 0, 1))
            cC = float(np.clip(BASE_CC + rng.uniform(-0.05, 0.05), 0, 1))
            # Horizontal arm of "+"
            _cv2.line(M, (cx - half_len, cy), (cx + half_len, cy), cM, arm_w, lineType=_cv2.LINE_AA)
            _cv2.line(R_ch, (cx - half_len, cy), (cx + half_len, cy), cR, arm_w, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (cx - half_len, cy), (cx + half_len, cy), cC, arm_w, lineType=_cv2.LINE_AA)
            # Vertical arm of "+"
            _cv2.line(M, (cx, cy - half_len), (cx, cy + half_len), cM, arm_w, lineType=_cv2.LINE_AA)
            _cv2.line(R_ch, (cx, cy - half_len), (cx, cy + half_len), cR, arm_w, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (cx, cy - half_len), (cx, cy + half_len), cC, arm_w, lineType=_cv2.LINE_AA)
            # Bright glint at intersection
            _cv2.circle(M, (cx, cy), 1, min(0.96, cM + 0.15), -1, lineType=_cv2.LINE_AA)

        # HERO â€” 14-22 LARGER crosses with bright halo (12-16 px arms)
        n_hero = int(rng.integers(14, 23))
        for _ in range(n_hero):
            hx = int(rng.uniform(0.06, 0.94) * w)
            hy = int(rng.uniform(0.06, 0.94) * h)
            harm = int(rng.uniform(6, 10) * max(scale, 1.0))
            harm = max(6, min(harm, 16))
            hM = float(np.clip(BASE_M + 0.10 + rng.uniform(-0.04, 0.04), 0, 1))
            hR = float(np.clip(BASE_R + rng.uniform(-0.04, 0.04), 0, 1))
            hC = float(np.clip(BASE_CC + 0.10 + rng.uniform(-0.04, 0.04), 0, 1))
            # Wide halo first
            _cv2.line(M, (hx - harm, hy), (hx + harm, hy), 0.60, 3, lineType=_cv2.LINE_AA)
            _cv2.line(M, (hx, hy - harm), (hx, hy + harm), 0.60, 3, lineType=_cv2.LINE_AA)
            # Bright cross
            _cv2.line(M, (hx - harm, hy), (hx + harm, hy), hM, 2, lineType=_cv2.LINE_AA)
            _cv2.line(M, (hx, hy - harm), (hx, hy + harm), hM, 2, lineType=_cv2.LINE_AA)
            _cv2.line(R_ch, (hx - harm, hy), (hx + harm, hy), hR, 2, lineType=_cv2.LINE_AA)
            _cv2.line(R_ch, (hx, hy - harm), (hx, hy + harm), hR, 2, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (hx - harm, hy), (hx + harm, hy), hC, 2, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (hx, hy - harm), (hx, hy + harm), hC, 2, lineType=_cv2.LINE_AA)
            _cv2.circle(M, (hx, hy), 2, 0.97, -1, lineType=_cv2.LINE_AA)

    out = np.stack([M, R_ch, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
brushed_cross._spb_concept_complete = True


def brushed_radial(shape, seed, sm, num_lines=120, phase_noise=0.03, **kwargs):
    """brushed_radial.

    identity: Round-6 creative rebuild â€” turbine-disc brushed radial finish.
    HERO motif is the TURBINE TICK PATTERN: along each major concentric ring,
    short radial tick marks repeat at regular angular spacing (like a wheel
    speedometer or a turntable). This gives the disc its mechanical
    fingerprint â€” a thing brushed_arc and brushed_cross cannot deliver.
    Layered with: multi-frequency concentric rings, log-spaced ring crests
    (denser near center, sparser at rim), ring-tangent arc shards,
    occasional radial polish-skip scars, and crest pinprick glints.
    Per-primitive INDEPENDENT M/R/CC.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + (hash("brushed_radial_r6") % 10000))
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)
    cy, cx = h / 2.0, w / 2.0
    yy, xx = np.mgrid[0:h, 0:w].astype(np.float32)
    dy, dx = yy - cy, xx - cx
    theta = np.arctan2(dy, dx).astype(np.float32)
    dist = np.sqrt(dy * dy + dx * dx).astype(np.float32)

    # 1) BASE â€” radial FBM substrate
    fbm_M = _normalize(multi_scale_noise(shape, [3.0, 7.0, 14.0], [0.5, 0.3, 0.2], int(seed) + 5611))
    fbm_R = _normalize(multi_scale_noise(shape, [3.0, 7.0, 14.0], [0.5, 0.3, 0.2], int(seed) + 5613))
    fbm_CC = _normalize(multi_scale_noise(shape, [3.0, 7.0, 14.0], [0.5, 0.3, 0.2], int(seed) + 5615))
    M  = (0.52 + (fbm_M - 0.5) * 0.18).astype(np.float32)
    R_ch = (0.42 + (fbm_R - 0.5) * 0.18).astype(np.float32)
    CC = (0.48 + (fbm_CC - 0.5) * 0.20).astype(np.float32)

    # 2) Log-spaced ring crests â€” denser near center, sparser near rim
    ring_step_a = max(2.5, 3.0 * scale)
    ring_step_b = max(4.0, 6.0 * scale)
    log_rings = np.sin(np.log(dist + 2.0) * 9.0 + float(rng.uniform(0, 2 * np.pi))) * 0.5 + 0.5
    rings_a = (np.sin(dist / ring_step_a * 2.0 * np.pi + float(rng.uniform(0, 2 * np.pi))) * 0.5 + 0.5)
    rings_b = (np.sin(dist / ring_step_b * 2.0 * np.pi + float(rng.uniform(0, 2 * np.pi))) * 0.5 + 0.5)
    ring_crest = np.clip((rings_a * 0.45 + rings_b * 0.30 + log_rings * 0.25) ** 2.2, 0, 1)
    M  = M  + (ring_crest - 0.35) * 0.36
    R_ch = R_ch - (ring_crest - 0.35) * 0.22
    CC = CC + (ring_crest - 0.35) * 0.30

    if _CV2_OK:
        # 3) HERO â€” TURBINE TICK PATTERN: rings of regularly-spaced radial ticks
        n_tick_rings = int(np.clip(14 + 6 * scale, 12, 36))
        for ri in range(n_tick_rings):
            # log-distribute ring radii
            t = (ri + 1) / float(n_tick_rings + 1)
            r_ring = float((mn * 0.05) * np.exp(t * np.log(mn * 0.50 / (mn * 0.05 + 1e-6))))
            # number of ticks scales with circumference
            n_ticks = int(np.clip(2 * np.pi * r_ring / max(6.0 * scale, 3.0), 18, 220))
            ang0 = float(rng.uniform(0, 2 * np.pi))
            tick_len = float(rng.uniform(3.0, 7.0) * scale) + 2.0
            tick_M = float(rng.uniform(0.55, 0.92))
            tick_R = float(rng.uniform(0.08, 0.32))
            tick_CC = float(rng.uniform(0.45, 0.95))
            for ti in range(n_ticks):
                a = ang0 + ti * 2.0 * np.pi / n_ticks
                # per-tick chroma jitter (independent)
                jM = float(rng.uniform(-0.18, 0.18))
                jR = float(rng.uniform(-0.10, 0.10))
                jCC = float(rng.uniform(-0.20, 0.18))
                x0s = int(cx + np.cos(a) * r_ring)
                y0s = int(cy + np.sin(a) * r_ring)
                x1s = int(cx + np.cos(a) * (r_ring + tick_len))
                y1s = int(cy + np.sin(a) * (r_ring + tick_len))
                _cv2.line(M, (x0s, y0s), (x1s, y1s), float(np.clip(tick_M + jM, 0.10, 0.99)), 1, lineType=_cv2.LINE_AA)
                _cv2.line(R_ch, (x0s, y0s), (x1s, y1s), float(np.clip(tick_R + jR, 0.04, 0.55)), 1, lineType=_cv2.LINE_AA)
                _cv2.line(CC, (x0s, y0s), (x1s, y1s), float(np.clip(tick_CC + jCC, 0.10, 0.99)), 1, lineType=_cv2.LINE_AA)

        # 4) Ring-tangent arc shards â€” short 4-22 deg fragments
        n_arc = int(np.clip(2000 * (mn / 2048.0) ** 2, 1100, 5500))
        for _ in range(n_arc):
            r_arc = float(rng.uniform(6.0, mn * 0.52))
            ang0 = float(rng.uniform(0, 360))
            sweep = float(rng.uniform(3.0, 18.0))
            mv = float(rng.uniform(0.32, 0.96))
            rv = float(rng.uniform(0.06, 0.42))
            cv2v = float(rng.uniform(0.25, 0.95))
            _cv2.ellipse(M,    (int(cx), int(cy)), (int(r_arc), int(r_arc)), 0.0, ang0, ang0 + sweep, mv, 1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(R_ch, (int(cx), int(cy)), (int(r_arc), int(r_arc)), 0.0, ang0, ang0 + sweep, rv, 1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(CC,   (int(cx), int(cy)), (int(r_arc), int(r_arc)), 0.0, ang0, ang0 + sweep, cv2v, 1, lineType=_cv2.LINE_AA)

        # 5) Polish-skip scars â€” short dark radial striations
        n_scar = int(np.clip(500 * (mn / 2048.0) ** 2, 220, 1400))
        for _ in range(n_scar):
            ang = float(rng.uniform(0, 2 * np.pi))
            r0 = float(rng.uniform(6.0, mn * 0.45))
            scar_len = float(rng.uniform(4.0, 10.0) * scale)
            r1 = r0 + scar_len
            x0s = int(cx + np.cos(ang) * r0); y0s = int(cy + np.sin(ang) * r0)
            x1s = int(cx + np.cos(ang) * r1); y1s = int(cy + np.sin(ang) * r1)
            _cv2.line(M, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.10, 0.30)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(R_ch, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.55, 0.88)), 1, lineType=_cv2.LINE_AA)

    # 6) RING-CREST PINPOINT GLINTS
    n_fl = int(np.clip(h * w / 90, 1500, 22000))
    fy = rng.integers(0, h, n_fl); fx = rng.integers(0, w, n_fl)
    crest_mask = ring_crest[fy, fx] > 0.50
    sel = np.where(crest_mask)[0]
    if sel.size:
        M[fy[sel], fx[sel]] = np.maximum(M[fy[sel], fx[sel]], rng.uniform(0.55, 0.99, sel.size).astype(np.float32))
        R_ch[fy[sel], fx[sel]] = np.minimum(R_ch[fy[sel], fx[sel]], rng.uniform(0.04, 0.28, sel.size).astype(np.float32))
        CC[fy[sel], fx[sel]] = np.maximum(CC[fy[sel], fx[sel]], rng.uniform(0.40, 0.97, sel.size).astype(np.float32))

    out = np.stack([np.clip(M, 0, 1), np.clip(R_ch, 0, 1), np.clip(CC, 0, 1)], axis=-1).astype(np.float32)
    return _sm_scale(out, sm)
brushed_radial._spb_concept_complete = True


def brushed_arc(shape, seed, sm, **kwargs):
    """Brushed arc â€” creative rebuild with hero whorls + intersection burnish.

    identity: Hand-polished brushed steel â€” every mark is a curved DRAG
    arc around an off-canvas pivot. Dense tangential drags (4-9 px arc
    radius) tile the canvas, secondary buff-spike arcs add cross-direction
    variation, and the hero motif is a scatter of 3-7 concentric WHORL
    centers: each whorl is 4-7 nested partial arcs (8-22 px) sharing a
    tight common center, the visible polish-knot left by a cloth rotation.
    On top: bright sparkle crests at whorl intersections, and a wide
    chroma single-pixel polish-dust carpet. Per-feature INDEPENDENT
    continuous M/R/CC keeps every arc chromatically distinct.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + (hash("brushed_arc_r6") % 10000))
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)
    pivot_y = h * 1.5 + rng.uniform(-h * 0.10, h * 0.10)
    pivot_x = w * (0.5 + rng.uniform(-0.08, 0.08))

    # Independent per-channel steel substrate
    fbm_M = _normalize(multi_scale_noise(shape, [2.5, 6.0, 14.0], [0.5, 0.3, 0.2], int(seed) + 3855))
    fbm_R = _normalize(multi_scale_noise(shape, [2.8, 6.5, 15.0], [0.5, 0.3, 0.2], int(seed) + 3857))
    fbm_CC = _normalize(multi_scale_noise(shape, [3.0, 7.0, 13.0], [0.5, 0.3, 0.2], int(seed) + 3859))
    M  = (0.56 + (fbm_M  - 0.5) * 0.22).astype(np.float32)
    R  = (0.38 + (fbm_R  - 0.5) * 0.22).astype(np.float32)
    CC = (0.45 + (fbm_CC - 0.5) * 0.22).astype(np.float32)

    if _CV2_OK:
        # TIER 1 â€” DENSE primary curved drag arcs tangent to pivot
        n_drag = int(np.clip(5800 * (mn / 2048.0) ** 2, 2400, 14500))
        for _ in range(n_drag):
            px = float(rng.uniform(-2, w + 2)); py = float(rng.uniform(-2, h + 2))
            dx_p = px - pivot_x; dy_p = py - pivot_y
            arc_r = max(2, int(rng.uniform(4.0, 9.0) * scale))
            ang_to_pivot = float(np.arctan2(dy_p, dx_p))
            cx_arc = int(px + np.cos(ang_to_pivot) * arc_r * rng.uniform(0.4, 1.1))
            cy_arc = int(py + np.sin(ang_to_pivot) * arc_r * rng.uniform(0.4, 1.1))
            bearing = float(np.rad2deg(ang_to_pivot + np.pi)) + float(rng.uniform(-8, 8))
            sweep = float(rng.uniform(25, 60))
            a0 = bearing - sweep * 0.5
            _cv2.ellipse(M,  (cx_arc, cy_arc), (arc_r, arc_r), 0.0, a0, a0 + sweep, float(rng.uniform(0.55, 0.96)), 1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(R,  (cx_arc, cy_arc), (arc_r, arc_r), 0.0, a0, a0 + sweep, float(rng.uniform(0.05, 0.32)), 1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(CC, (cx_arc, cy_arc), (arc_r, arc_r), 0.0, a0, a0 + sweep, float(rng.uniform(0.06, 0.42)), 1, lineType=_cv2.LINE_AA)

        # TIER 2 â€” shorter buff-spike arcs at random tangent angles
        n_buff = int(np.clip(2600 * (mn / 2048.0) ** 2, 1000, 7000))
        for _ in range(n_buff):
            cx = int(rng.uniform(0, w)); cy = int(rng.uniform(0, h))
            arc_r = max(2, int(rng.uniform(3.0, 6.0) * scale))
            a0 = float(rng.uniform(0, 360)); sweep = float(rng.uniform(40, 110))
            _cv2.ellipse(M,  (cx, cy), (arc_r, arc_r), 0.0, a0, a0 + sweep, float(rng.uniform(0.50, 0.94)), 1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(R,  (cx, cy), (arc_r, arc_r), 0.0, a0, a0 + sweep, float(rng.uniform(0.08, 0.36)), 1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(CC, (cx, cy), (arc_r, arc_r), 0.0, a0, a0 + sweep, float(rng.uniform(0.08, 0.44)), 1, lineType=_cv2.LINE_AA)

        # TIER 3 â€” HERO POLISH WHORLS: 3-7 concentric arc clusters
        n_whorl = int(rng.integers(3, 8))
        for _ in range(n_whorl):
            wcx = int(rng.uniform(20, w - 20))
            wcy = int(rng.uniform(20, h - 20))
            n_rings = int(rng.integers(4, 8))
            base_ang = float(rng.uniform(0, 360))
            for kr in range(n_rings):
                r_w = max(3, int((8.0 + kr * 2.6) * scale))
                if r_w > min(w, h) // 4:
                    break
                sweep_w = float(rng.uniform(120, 300))
                a0_w = base_ang + kr * float(rng.uniform(-20, 20))
                _cv2.ellipse(M, (wcx, wcy), (r_w, r_w), 0.0, a0_w, a0_w + sweep_w,
                             float(rng.uniform(0.72, 0.97)), 1, lineType=_cv2.LINE_AA)
                _cv2.ellipse(R, (wcx, wcy), (r_w, r_w), 0.0, a0_w, a0_w + sweep_w,
                             float(rng.uniform(0.04, 0.22)), 1, lineType=_cv2.LINE_AA)
                _cv2.ellipse(CC, (wcx, wcy), (r_w, r_w), 0.0, a0_w, a0_w + sweep_w,
                             float(rng.uniform(0.04, 0.30)), 1, lineType=_cv2.LINE_AA)
            # whorl center burnish
            _cv2.circle(M, (wcx, wcy), max(1, int(scale * 2.0)),
                        float(rng.uniform(0.82, 0.98)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (wcx, wcy), max(1, int(scale * 2.0)),
                        float(rng.uniform(0.04, 0.16)), -1, lineType=_cv2.LINE_AA)

        # TIER 4 â€” INTERSECTION BURNISH DOTS where arcs cross
        n_burn = int(np.clip(900 * (mn / 2048.0) ** 2, 300, 2400))
        for _ in range(n_burn):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            rb = max(1, int(rng.uniform(1.0, 2.0) * scale))
            _cv2.circle(M, (cx, cy), rb, float(rng.uniform(0.78, 0.99)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), rb, float(rng.uniform(0.04, 0.15)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), rb, float(rng.uniform(0.05, 0.30)), -1, lineType=_cv2.LINE_AA)

    # TIER 5 â€” 1-px polish-dust crest sparkle, wider chroma
    n_fl = int(np.clip(4200 * (mn / 2048.0) ** 2, 1500, 11000))
    fx = rng.integers(0, w, n_fl); fy = rng.integers(0, h, n_fl)
    M[fy, fx]  = np.maximum(M[fy, fx],  rng.uniform(0.60, 0.99, n_fl).astype(np.float32))
    R[fy, fx]  = np.minimum(R[fy, fx],  rng.uniform(0.04, 0.30, n_fl).astype(np.float32))
    CC[fy, fx] = rng.uniform(0.04, 0.60, n_fl).astype(np.float32)

    out = np.stack([M, R, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
brushed_arc._spb_concept_complete = True


def hairline_polish(shape, seed, sm, **kwargs):
    """hairline_polish.

    identity: R6 tick 2026-05-26 â€” owner rated 2/REBUILD ("random lines /
    scribbles, too noisy"). CALM, DISCIPLINED brushed stainless: ONE
    coherent grain direction, 3 phase-locked hairline carriers (NOT seven
    fighting layers), NO cross-grain perpendicular hairs, NO random
    scratches sprayed across the canvas, NO hero arc-sweep bundles. The
    "creativity" lives in the metallography HERO motif: a flow-line
    anisotropy field where the grain direction itself bends slowly across
    the panel (real bench-belt operator drift, not chaos). Tight chroma
    jitter from a single stainless base. 8-32 px primitives.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 47281)
    mn = min(h, w)
    s = max(mn / 256.0, 0.6)

    yy_g, xx_g = np.mgrid[0:h, 0:w].astype(np.float32)
    yy_n = yy_g / h
    xx_n = xx_g / w

    # 1) Substrate â€” single coherent stainless base, Â±0.04 mottle
    fbm = _normalize(multi_scale_noise(shape, [3.5, 9.0], [0.6, 0.4], int(seed) + 4711))
    BASE_M, BASE_R, BASE_CC = 0.58, 0.30, 0.26
    M  = (BASE_M  + (fbm - 0.5) * 0.06).astype(np.float32)
    R  = (BASE_R  - (fbm - 0.5) * 0.05).astype(np.float32)
    CC = (BASE_CC + (fbm - 0.5) * 0.04).astype(np.float32)

    # 2) HERO METALLOGRAPHY: flow-line anisotropy â€” grain direction bends
    #    smoothly across the panel like a real polished bench belt where
    #    operator drift creates long curving streamlines.
    flow_phase = float(rng.uniform(0, 2 * np.pi))
    flow_amp = 0.10  # radians of drift (tight)
    flow_field = flow_amp * np.sin(xx_n * np.pi * 1.4 + flow_phase) + \
                 0.6 * flow_amp * np.cos(yy_n * np.pi * 0.9 + flow_phase * 0.7)
    # Carrier coordinate that follows the flow field (warped y-axis)
    u_carrier = yy_g + flow_field * mn * 0.08

    # 3) Three phase-locked hairline carriers â€” NOT seven fighting layers.
    #    Periods ~10-18 px (8-32 px primitives), tight chroma jitter.
    periods = [12.0 * s, 16.0 * s, 22.0 * s]
    weights = [0.20, 0.13, 0.08]
    for k, (p, wt) in enumerate(zip(periods, weights)):
        carrier = 0.5 + 0.5 * np.cos(u_carrier * (2 * np.pi / max(p, 4.0)) + k * 0.7)
        # Tight Â±0.04 jitter only â€” owner wants calm, not chaos
        M  = M  + (carrier - 0.5) * wt * 0.55
        CC = CC + (carrier - 0.5) * wt * 0.35
        R  = R  - (carrier - 0.5) * wt * 0.20

    M = M.astype(np.float32); R = R.astype(np.float32); CC = CC.astype(np.float32)

    # 4) Sparse, restrained polish micro-grain â€” flecks ONLY, not scratches.
    #    Density tuned for 256Â² and 2048Â² (h*w/scale).
    if _CV2_OK:
        # Bright mica flecks â€” sparse, single-tone, Â±0.04 around stainless peak
        n_spk = int(np.clip(h * w / 480.0, 200, 1400))
        sy = rng.integers(0, h, n_spk); sx = rng.integers(0, w, n_spk)
        # Each fleck a TIGHT roll around bright stainless (M 0.78, CC 0.40)
        M[sy, sx]  = np.clip(M[sy, sx]  + rng.uniform(0.16, 0.22, n_spk).astype(np.float32), 0, 1)
        CC[sy, sx] = np.clip(CC[sy, sx] + rng.uniform(0.10, 0.16, n_spk).astype(np.float32), 0, 1)
        R[sy, sx]  = np.clip(R[sy, sx]  - rng.uniform(0.06, 0.10, n_spk).astype(np.float32), 0, 1)

        # Dark micropits â€” also sparse, tight roll
        n_pit = int(np.clip(h * w / 950.0, 120, 800))
        py = rng.integers(0, h, n_pit); px = rng.integers(0, w, n_pit)
        M[py, px]  = np.clip(M[py, px]  - rng.uniform(0.18, 0.24, n_pit).astype(np.float32), 0, 1)
        R[py, px]  = np.clip(R[py, px]  + rng.uniform(0.14, 0.18, n_pit).astype(np.float32), 0, 1)

    out = np.stack([M, R, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)


hairline_polish._spb_concept_complete = True


def lathe_concentric(shape, seed, sm, **kwargs):
    """lathe_concentric.

    identity: Round-6 creative rebuild â€” a metal disc FRESH off the lathe.
    Six tiers stacked:
      (1) Tight concentric ring field (3-8 px pitch) from off-center pivot
          with FBM micro-warble (chuck wobble).
      (2) Secondary fainter feed-mark rings at 2x pitch (cleanup pass).
      (3) Sharp bright apex pinpoints on ring crests (5x density,
          independent continuous M/R/CC per pinpoint).
      (4) HERO: chuck-jaw triangular grip indents â€” clusters of 3-4
          small triangle marks at random radial angles (radial spokes
          of indents that suggest the 3-jaw chuck).
      (5) HERO: tool-bit chatter clusters â€” groups of 4-7 short radial
          streaks bunched at irregular tangents (where the bit walked).
      (6) Dark valley grit + bright mica spark carpet.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 126723)
    scale = max(min(h, w) / 2048.0, 0.25)
    mn = float(min(h, w)); s256 = max(mn / 256.0, 0.6)

    def _fbm(off, sigma):
        if _CV2_OK:
            sh = max(64, h // 10); sw = max(64, w // 10)
            n = np.random.default_rng(int(seed) + off).random((sh, sw)).astype(np.float32)
            b = _cv2.GaussianBlur(n, (0, 0), sigmaX=sigma, sigmaY=sigma)
            return _normalize(_cv2.resize(b, (w, h), interpolation=_cv2.INTER_CUBIC).astype(np.float32))
        return _normalize(multi_scale_noise(shape, [20, 40], [0.6, 0.4], int(seed) + off))

    yy, xx = np.mgrid[0:h, 0:w].astype(np.float32)
    cx = w * float(rng.uniform(0.25, 0.75))
    cy = h * float(rng.uniform(0.25, 0.75))
    warble = _fbm(12671, 6.5) - 0.5
    rdist = np.sqrt((xx - cx) ** 2 + (yy - cy) ** 2) + warble * 4.0

    # Primary tight ring pitch
    period_px = max(3.5, 6.5 * scale)
    ring1 = np.abs(np.sin(rdist / period_px * np.pi))
    ring1_sharp = np.power(ring1, 2.6)
    ring2 = np.abs(np.sin(rdist / (period_px * 2.0) * np.pi))

    fM = _fbm(12673, 5.0); fR = _fbm(12675, 5.0); fCC = _fbm(12677, 5.0)
    M  = (0.52 + 0.36 * ring1_sharp + 0.10 * (ring2 - 0.5) + 0.10 * (fM  - 0.5)).astype(np.float32)
    R  = (0.48 - 0.34 * ring1_sharp + 0.18 * (fR  - 0.5)).astype(np.float32)
    CC = (0.36 - 0.28 * ring1_sharp + 0.18 * (fCC - 0.5)).astype(np.float32)

    if _CV2_OK:
        # 3) Bright apex pinpoints on ring crests (vectorized random pick)
        peak = (ring1_sharp > 0.55)
        idxs = np.argwhere(peak)
        if len(idxs) > 0:
            n_pick = min(len(idxs), max(7000, int(h * w / 90)))
            pick = rng.choice(len(idxs), size=n_pick, replace=False)
            ys_pk = idxs[pick, 0]; xs_pk = idxs[pick, 1]
            M[ys_pk, xs_pk] = rng.uniform(0.82, 0.99, n_pick).astype(np.float32)
            R[ys_pk, xs_pk] = rng.uniform(0.03, 0.18, n_pick).astype(np.float32)
            CC[ys_pk, xs_pk] = rng.uniform(0.03, 0.24, n_pick).astype(np.float32)

        # 4) HERO â€” CHUCK-JAW TRIANGULAR GRIP INDENTS
        # Clusters of 3-4 triangle indents arranged at 120Â° around pivot
        n_jaw_clusters = int(np.clip(6 * s256 * s256, 3, 24))
        for _ in range(n_jaw_clusters):
            # cluster sits at a radius from pivot
            cl_r = float(rng.uniform(0.20, 0.45)) * min(h, w)
            cl_base = float(rng.uniform(0, 2 * np.pi))
            for jaw in range(3):  # classic 3-jaw chuck
                ja = cl_base + jaw * (2 * np.pi / 3.0) + float(rng.normal(0, 0.05))
                jcx = cx + np.cos(ja) * cl_r
                jcy = cy + np.sin(ja) * cl_r
                if not (4 <= jcx < w - 4 and 4 <= jcy < h - 4):
                    continue
                tr_size = float(rng.uniform(5.0, 9.0) * s256 * 0.6)
                # build a triangle pointing radially inward
                tip_a = ja + np.pi  # tip points inward
                p0 = (int(jcx + np.cos(tip_a) * tr_size),
                      int(jcy + np.sin(tip_a) * tr_size))
                p1 = (int(jcx + np.cos(tip_a + 2.4) * tr_size * 0.7),
                      int(jcy + np.sin(tip_a + 2.4) * tr_size * 0.7))
                p2 = (int(jcx + np.cos(tip_a - 2.4) * tr_size * 0.7),
                      int(jcy + np.sin(tip_a - 2.4) * tr_size * 0.7))
                tri = np.array([p0, p1, p2], dtype=np.int32)
                _cv2.fillPoly(M, [tri], float(rng.uniform(0.20, 0.42)), lineType=_cv2.LINE_AA)
                _cv2.fillPoly(R, [tri], float(rng.uniform(0.65, 0.92)), lineType=_cv2.LINE_AA)
                _cv2.fillPoly(CC,[tri], float(rng.uniform(0.45, 0.78)), lineType=_cv2.LINE_AA)
                # bright outline rim
                _cv2.polylines(M, [tri], True, float(rng.uniform(0.72, 0.96)), 1, lineType=_cv2.LINE_AA)
                _cv2.polylines(CC,[tri], True, float(rng.uniform(0.35, 0.62)), 1, lineType=_cv2.LINE_AA)

        # 5) HERO â€” TOOL-BIT CHATTER CLUSTERS (groups of streaks at tangents)
        n_chatter_cl = int(np.clip(14 * s256 * s256, 7, 60))
        for _ in range(n_chatter_cl):
            # cluster center somewhere on the disc
            ccx = float(rng.uniform(0.05, 0.95) * w)
            ccy = float(rng.uniform(0.05, 0.95) * h)
            # tangent angle at that point
            tan_a = np.arctan2(ccy - cy, ccx - cx) + np.pi * 0.5
            n_strk = int(rng.integers(4, 8))
            spread = float(rng.uniform(4.0, 9.0) * s256)
            for k in range(n_strk):
                ox = ccx + float(rng.normal(0, spread * 0.6))
                oy = ccy + float(rng.normal(0, spread * 0.6))
                ll = float(rng.uniform(3.0, 9.0) * scale)
                ka = tan_a + float(rng.normal(0, 0.20))
                dx = np.cos(ka) * ll * 0.5; dy = np.sin(ka) * ll * 0.5
                p0 = (int(ox - dx), int(oy - dy)); p1 = (int(ox + dx), int(oy + dy))
                _cv2.line(M, p0, p1, float(rng.uniform(0.32, 0.68)), 1, lineType=_cv2.LINE_AA)
                _cv2.line(R, p0, p1, float(rng.uniform(0.45, 0.88)), 1, lineType=_cv2.LINE_AA)
                _cv2.line(CC,p0, p1, float(rng.uniform(0.15, 0.50)), 1, lineType=_cv2.LINE_AA)

        # Standalone short radial chatter (background tool walk)
        n_str = max(int(h * w / 380), 1200)
        for _ in range(n_str):
            x0 = int(rng.integers(0, w)); y0 = int(rng.integers(0, h))
            r_a = np.arctan2(y0 - cy, x0 - cx)
            ll = float(rng.uniform(2.5, 5.0) * scale)
            x1 = int(x0 + np.cos(r_a) * ll); y1 = int(y0 + np.sin(r_a) * ll)
            _cv2.line(R, (x0, y0), (x1, y1), float(rng.uniform(0.42, 0.88)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(M, (x0, y0), (x1, y1), float(rng.uniform(0.32, 0.64)), 1, lineType=_cv2.LINE_AA)

    # 6) Dark valley grit + bright mica sparks
    n_v = max(int(h * w / 130), 4500)
    ys_v = rng.integers(0, h, n_v); xs_v = rng.integers(0, w, n_v)
    M[ys_v, xs_v] = np.minimum(M[ys_v, xs_v], rng.uniform(0.16, 0.38, n_v).astype(np.float32))
    R[ys_v, xs_v] = np.maximum(R[ys_v, xs_v], rng.uniform(0.55, 0.90, n_v).astype(np.float32))

    n_sp = max(int(h * w / 320), 2500)
    sy = rng.integers(0, h, n_sp); sx = rng.integers(0, w, n_sp)
    M[sy, sx] = np.maximum(M[sy, sx], rng.uniform(0.78, 0.99, n_sp).astype(np.float32))
    R[sy, sx] = np.minimum(R[sy, sx], rng.uniform(0.02, 0.16, n_sp).astype(np.float32))
    CC[sy, sx] = np.minimum(CC[sy, sx], rng.uniform(0.02, 0.22, n_sp).astype(np.float32))

    out = np.stack([M, R, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)


lathe_concentric._spb_concept_complete = True


def bead_blast_uniform(shape, seed, sm, **kwargs):
    """bead_blast_uniform.

    identity: R6 CREATIVE SECOND-PASS â€” saturated bead-blasted aluminum
    with a NEW HERO motif: FROST-DENDRITE CRYSTAL GROWTHS bloom out
    from a handful of nozzle-dwell centers as L-system tree branches
    (12-30 px tall, bifurcating at 30-45Â°, very thin 1 px arms). It
    looks like frozen frost crystals scattered across the matte
    blasted surface. Substrate shifted to a cooler DEEP-VIOLET cast
    (Mâ‰ˆ0.40 Râ‰ˆ0.30 CCâ‰ˆ0.55 â€” under anti-magenta cap 0.45). Seven
    stacked tiers: (1) cool violet FBM substrate, (2) ultra-dense pit
    rim field (Gaussian splat), (3) bright pit-core dimples, (4)
    dense 2-4 px secondary craters, (5) HERO frost-dendrite crystal
    growths, (6) blast rosettes (existing), (7) 1-3 px crystalline
    media-grain shards. Per-feature TIGHT independent M/R/CC.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 19443)
    scale = max(min(h, w) / 2048.0, 0.25)
    mn = min(h, w); s256 = max(mn / 256.0, 0.6)

    # 1) Independent per-channel FBM substrate â€” DEEP VIOLET cool cast
    bM = _normalize(multi_scale_noise(shape, [2.0, 6.0, 14.0], [0.42, 0.34, 0.24], int(seed) + 3995))
    bR = _normalize(multi_scale_noise(shape, [2.5, 6.5, 15.0], [0.42, 0.34, 0.24], int(seed) + 3997))
    bC = _normalize(multi_scale_noise(shape, [3.0, 7.0, 16.0], [0.42, 0.34, 0.24], int(seed) + 3999))
    # deep violet â€” M low (â‰¤0.45) anti-magenta; R cool; CC 0.55 mid
    M = (0.34 + (bM - 0.5) * 0.10).astype(np.float32)
    R = (0.30 + (bR - 0.5) * 0.10).astype(np.float32)
    CC = (0.55 + (bC - 0.5) * 0.16).astype(np.float32)

    # 2) ULTRA-DENSE pit centers via splat (vectorized, fast)
    n_pits = max(12000, int(32000 * scale * scale))
    py = rng.integers(0, h, n_pits)
    px = rng.integers(0, w, n_pits)
    pv = rng.uniform(0.4, 1.0, n_pits).astype(np.float32)
    pit_centers = np.zeros(shape, dtype=np.float32)
    np.maximum.at(pit_centers, (py, px), pv)
    pit_wide = _gauss(pit_centers, sigma=max(1.2, 1.8 * scale))
    pit_narrow = _gauss(pit_centers, sigma=max(0.5, 0.9 * scale))
    pit_rim = _normalize(np.clip(pit_wide - pit_narrow * 0.6, 0, 1))
    M = np.clip(M + pit_rim * 0.34, 0, 1)
    R = np.clip(R - pit_rim * 0.24, 0, 1)
    CC = np.clip(CC - pit_rim * 0.14, 0, 1)
    pit_core = _normalize(pit_narrow)
    M = np.clip(M - pit_core * 0.22, 0, 1)
    R = np.clip(R + pit_core * 0.18, 0, 1)
    CC = np.clip(CC + pit_core * 0.08, 0, 1)

    if _CV2_OK:
        # 3) Dense secondary craters 2-4 px
        n_deep = int(np.clip(1200 * (mn / 2048.0) ** 2, 400, 3500))
        for _ in range(n_deep):
            cxv = int(rng.integers(0, w)); cyv = int(rng.integers(0, h))
            r = max(1, int(rng.uniform(2.0, 4.0) * scale * 0.5))
            _cv2.circle(M, (cxv, cyv), r, float(rng.uniform(0.08, 0.30)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cxv, cyv), r, float(rng.uniform(0.65, 0.95)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cxv, cyv), r, float(rng.uniform(0.30, 0.65)), -1, lineType=_cv2.LINE_AA)

        # 4) Fine 1-2 px micro pits
        n_micro = int(np.clip(3000 * (mn / 2048.0) ** 2, 900, 8000))
        for _ in range(n_micro):
            cxv = int(rng.integers(0, w)); cyv = int(rng.integers(0, h))
            r = max(1, int(rng.uniform(1.0, 2.0) * scale))
            _cv2.circle(M, (cxv, cyv), r, float(rng.uniform(0.20, 0.45)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cxv, cyv), r, float(rng.uniform(0.55, 0.85)), -1, lineType=_cv2.LINE_AA)

        # 4b) NEW HERO â€” FROST-DENDRITE CRYSTAL GROWTHS (L-system bifurcating arms)
        n_frost = int(np.clip(28 * s256, 14, 70))

        def _frost_branch(x, y, ang, depth, brightM, brightR, brightCC):
            if depth <= 0:
                return
            seg = float(rng.uniform(2.0, 3.5) * s256)
            n_segs = int(rng.integers(3, 7))
            cx_cur, cy_cur = x, y
            cur_ang = ang
            for _i in range(n_segs):
                cur_ang += float(rng.uniform(-0.10, 0.10))
                x2 = cx_cur + np.cos(cur_ang) * seg
                y2 = cy_cur + np.sin(cur_ang) * seg
                if not (1 <= x2 < w - 1 and 1 <= y2 < h - 1):
                    return
                vM = float(np.clip(brightM + rng.uniform(-0.04, 0.04), 0.55, 0.99))
                vR = float(np.clip(brightR + rng.uniform(-0.04, 0.04), 0.05, 0.30))
                vCC = float(np.clip(brightCC + rng.uniform(-0.05, 0.05), 0.55, 0.99))
                _cv2.line(M, (int(cx_cur), int(cy_cur)), (int(x2), int(y2)), vM, 1, lineType=_cv2.LINE_AA)
                _cv2.line(R, (int(cx_cur), int(cy_cur)), (int(x2), int(y2)), vR, 1, lineType=_cv2.LINE_AA)
                _cv2.line(CC, (int(cx_cur), int(cy_cur)), (int(x2), int(y2)), vCC, 1, lineType=_cv2.LINE_AA)
                if depth > 1 and rng.random() < 0.55:
                    split = float(np.deg2rad(rng.uniform(30, 45))) * (1 if rng.random() < 0.5 else -1)
                    _frost_branch(x2, y2, cur_ang + split, depth - 1, brightM, brightR, brightCC)
                cx_cur, cy_cur = x2, y2

        for _ in range(n_frost):
            cx0 = float(rng.integers(10, max(11, w - 10)))
            cy0 = float(rng.integers(10, max(11, h - 10)))
            bM_ = float(rng.uniform(0.78, 0.96))
            bR_ = float(rng.uniform(0.06, 0.18))
            bCC_ = float(rng.uniform(0.70, 0.95))
            # 5-7 primary arms from each crystal seed
            n_arms = int(rng.integers(5, 8))
            for k in range(n_arms):
                a0 = (k / n_arms) * 2 * np.pi + float(rng.uniform(-0.18, 0.18))
                _frost_branch(cx0, cy0, a0, depth=2, brightM=bM_, brightR=bR_, brightCC=bCC_)

        # 5) HERO BLAST ROSETTES â€” nozzle-dwell pit clusters
        n_rose = int(np.clip(120 * (mn / 2048.0) ** 2, 35, 360))
        for _ in range(n_rose):
            ox = float(rng.uniform(8, w - 8)); oy = float(rng.uniform(8, h - 8))
            radius = float(rng.uniform(6.0, 11.0) * scale)
            n_sat = int(rng.integers(8, 15))
            # deep center
            cr = max(2, int(rng.uniform(2.5, 4.0) * scale))
            _cv2.circle(M, (int(ox), int(oy)), cr, float(rng.uniform(0.05, 0.18)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (int(ox), int(oy)), cr, float(rng.uniform(0.75, 0.95)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (int(ox), int(oy)), cr, float(rng.uniform(0.20, 0.50)), -1, lineType=_cv2.LINE_AA)
            for k in range(n_sat):
                a = float(rng.uniform(0, 2 * np.pi))
                rr = radius * float(rng.uniform(0.5, 1.0))
                sx = int(np.clip(ox + np.cos(a) * rr, 0, w - 1))
                sy = int(np.clip(oy + np.sin(a) * rr, 0, h - 1))
                ssize = max(1, int(rng.uniform(1.0, 2.5) * scale))
                _cv2.circle(M, (sx, sy), ssize, float(rng.uniform(0.30, 0.85)), -1, lineType=_cv2.LINE_AA)
                _cv2.circle(R, (sx, sy), ssize, float(rng.uniform(0.18, 0.55)), -1, lineType=_cv2.LINE_AA)
                _cv2.circle(CC, (sx, sy), ssize, float(rng.uniform(0.35, 0.78)), -1, lineType=_cv2.LINE_AA)

        # 6) Crystalline media-grain SHARDS â€” short bright slivers
        n_shard = int(np.clip(2200 * (mn / 2048.0) ** 2, 700, 5500))
        for _ in range(n_shard):
            cx = float(rng.uniform(1, w - 1)); cy = float(rng.uniform(1, h - 1))
            length = float(rng.uniform(1.5, 3.5) * scale)
            ang = float(rng.uniform(0, 2 * np.pi))
            x0 = int(cx - np.cos(ang) * length * 0.5); y0 = int(cy - np.sin(ang) * length * 0.5)
            x1 = int(cx + np.cos(ang) * length * 0.5); y1 = int(cy + np.sin(ang) * length * 0.5)
            _cv2.line(M, (x0, y0), (x1, y1), float(rng.uniform(0.78, 0.99)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(R, (x0, y0), (x1, y1), float(rng.uniform(0.04, 0.18)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (x0, y0), (x1, y1), float(rng.uniform(0.60, 0.92)), 1, lineType=_cv2.LINE_AA)

    # 7) Ultra-dense single-pixel sparkle carpet (independent uniforms)
    n_fl = int(np.clip(6500 * (mn / 2048.0) ** 2, 2000, 16000))
    fx = rng.integers(0, w, n_fl); fy = rng.integers(0, h, n_fl)
    M[fy, fx] = np.maximum(M[fy, fx], rng.uniform(0.70, 0.96, n_fl).astype(np.float32))
    R[fy, fx] = np.minimum(R[fy, fx], rng.uniform(0.10, 0.40, n_fl).astype(np.float32))
    CC[fy, fx] = np.maximum(CC[fy, fx], rng.uniform(0.55, 0.92, n_fl).astype(np.float32))

    out = np.stack([M, R, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
bead_blast_uniform._spb_concept_complete = True
def orbital_swirl(shape, seed, sm, **kwargs):
    """Orbital swirl â€” DENSE tiny-radius orbital polish flecks.

    identity: Round-6 CREATIVE rebuild â€” DA polisher worked the panel with
    a complex multi-tier story: TIER 1 short 4-10 px hairline streaks,
    TIER 2 dense tiny orbital arcs at 3-7 px radius, TIER 3 4-9 px
    elongated swirl marks. NEW TIER A: hero SPIRAL CHAIN motifs â€” 8-14
    connected arc-segments per chain (~4-7 px each) spiraling outward from
    a center, suggesting the pad path. NEW TIER B: micro LACQUER PITS
    (1-3 px dark voids with bright halo dot). NEW TIER C: chromium DUST
    BAND streaks (10-22 px ultra-faint long sweeps following dominant
    flow). TIER 4 1-2 px crest sparkle dots retained. Each arc/stroke/dot
    INDEPENDENT continuous M/R/CC uniforms; no palette tier.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + (hash("orbital_swirl_r5") % 10000))
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)

    # Brushed substrate â€” per-channel independent FBM (low amp)
    g_M = _normalize(multi_scale_noise((h, w), [2.0, 5.5, 14.0], [0.5, 0.3, 0.2], int(seed) + 101))
    g_R = _normalize(multi_scale_noise((h, w), [2.5, 6.0, 16.0], [0.5, 0.3, 0.2], int(seed) + 103))
    g_CC = _normalize(multi_scale_noise((h, w), [3.0, 7.0, 18.0], [0.5, 0.3, 0.2], int(seed) + 107))
    M  = (0.56 + (g_M  - 0.5) * 0.18).astype(np.float32)
    R  = (0.36 + (g_R  - 0.5) * 0.18).astype(np.float32)
    CC = (0.48 + (g_CC - 0.5) * 0.18).astype(np.float32)

    if _CV2_OK:
        # TIER 1 â€” short 4-10 px hairline polish streaks (2.5x density)
        n_brush = int(np.clip(2200 * (mn / 2048.0) ** 2, 900, 6500))
        for _ in range(n_brush):
            cx = float(rng.uniform(2, w - 2)); cy = float(rng.uniform(2, h - 2))
            length = float(rng.uniform(4.0, 10.0) * scale)
            ang = float(rng.uniform(0, 2 * np.pi))
            x0s = int(cx - np.cos(ang) * length * 0.5); y0s = int(cy - np.sin(ang) * length * 0.5)
            x1s = int(cx + np.cos(ang) * length * 0.5); y1s = int(cy + np.sin(ang) * length * 0.5)
            _cv2.line(M,  (x0s, y0s), (x1s, y1s), float(rng.uniform(0.50, 0.94)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(R,  (x0s, y0s), (x1s, y1s), float(rng.uniform(0.08, 0.36)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.10, 0.42)), 1, lineType=_cv2.LINE_AA)

        # TIER 2 â€” tiny orbital arcs at 3-7 px radius (3x density)
        n_orbit = int(np.clip(3300 * (mn / 2048.0) ** 2, 1300, 9000))
        for _ in range(n_orbit):
            cx = int(rng.uniform(-0.05, 1.05) * w); cy = int(rng.uniform(-0.05, 1.05) * h)
            r = max(2, int(rng.uniform(3.0, 7.0) * scale))
            a0 = float(rng.uniform(0, 360)); sweep = float(rng.uniform(70, 260))
            _cv2.ellipse(M,  (cx, cy), (r, r), 0.0, a0, a0 + sweep, float(rng.uniform(0.55, 0.98)), 1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(R,  (cx, cy), (r, r), 0.0, a0, a0 + sweep, float(rng.uniform(0.04, 0.28)), 1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(CC, (cx, cy), (r, r), 0.0, a0, a0 + sweep, float(rng.uniform(0.05, 0.36)), 1, lineType=_cv2.LINE_AA)

        # TIER 3 â€” elongated swirl marks 4-9 px (slight ellipse stretch)
        n_swirl = int(np.clip(1800 * (mn / 2048.0) ** 2, 700, 5200))
        for _ in range(n_swirl):
            cx = int(rng.uniform(0, w)); cy = int(rng.uniform(0, h))
            rx = max(2, int(rng.uniform(2.0, 4.5) * scale))
            ry = max(1, int(rx * rng.uniform(0.35, 0.7)))
            rot = float(rng.uniform(0, 360))
            a0 = float(rng.uniform(0, 360)); sweep = float(rng.uniform(60, 200))
            _cv2.ellipse(M,  (cx, cy), (rx, ry), rot, a0, a0 + sweep, float(rng.uniform(0.55, 0.96)), 1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(R,  (cx, cy), (rx, ry), rot, a0, a0 + sweep, float(rng.uniform(0.05, 0.30)), 1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(CC, (cx, cy), (rx, ry), rot, a0, a0 + sweep, float(rng.uniform(0.06, 0.38)), 1, lineType=_cv2.LINE_AA)

    if _CV2_OK:
        # NEW TIER A â€” HERO SPIRAL CHAINS â€” 12-24 spiral motifs across canvas
        n_chain = int(np.clip(60 * (mn / 2048.0) ** 2, 12, 180))
        for _ in range(n_chain):
            cx = float(rng.uniform(0.08 * w, 0.92 * w))
            cy = float(rng.uniform(0.08 * h, 0.92 * h))
            n_seg = int(rng.integers(8, 15))
            base_ang = float(rng.uniform(0, 2 * np.pi))
            spiral_dir = float(rng.choice([1.0, -1.0]))
            r_start = float(rng.uniform(1.5, 3.0) * scale)
            sM = float(rng.uniform(0.55, 0.95))
            sR = float(rng.uniform(0.06, 0.32))
            sCC = float(rng.uniform(0.06, 0.34))
            prev_x, prev_y = cx, cy
            for si in range(n_seg):
                r = r_start + si * float(rng.uniform(0.7, 1.4)) * scale
                ang = base_ang + spiral_dir * si * float(rng.uniform(0.55, 0.85))
                nx = cx + np.cos(ang) * r; ny = cy + np.sin(ang) * r
                # Per-segment uniform jitter for chroma variety
                jM = float(np.clip(sM + rng.uniform(-0.10, 0.10), 0.0, 1.0))
                jR = float(np.clip(sR + rng.uniform(-0.06, 0.10), 0.0, 1.0))
                jCC = float(np.clip(sCC + rng.uniform(-0.08, 0.10), 0.0, 1.0))
                _cv2.line(M, (int(prev_x), int(prev_y)), (int(nx), int(ny)), jM, 1, lineType=_cv2.LINE_AA)
                _cv2.line(R, (int(prev_x), int(prev_y)), (int(nx), int(ny)), jR, 1, lineType=_cv2.LINE_AA)
                _cv2.line(CC, (int(prev_x), int(prev_y)), (int(nx), int(ny)), jCC, 1, lineType=_cv2.LINE_AA)
                prev_x, prev_y = nx, ny

        # NEW TIER B â€” LACQUER PITS â€” 1-3 px dark voids with bright halo
        n_pit = int(np.clip(1100 * (mn / 2048.0) ** 2, 360, 2800))
        for _ in range(n_pit):
            cx = int(rng.integers(1, w - 1)); cy = int(rng.integers(1, h - 1))
            r = max(1, int(rng.uniform(1.0, 3.0) * scale))
            # Bright halo ring
            _cv2.circle(M, (cx, cy), r + 1, float(rng.uniform(0.62, 0.92)), 1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r + 1, float(rng.uniform(0.55, 0.88)), 1, lineType=_cv2.LINE_AA)
            # Dark pit core
            _cv2.circle(M, (cx, cy), r, float(rng.uniform(0.10, 0.28)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r, float(rng.uniform(0.60, 0.92)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r, float(rng.uniform(0.10, 0.30)), -1, lineType=_cv2.LINE_AA)

        # NEW TIER C â€” CHROMIUM DUST BAND STREAKS â€” long faint sweeps
        flow_ang = float(rng.uniform(0, 2 * np.pi))
        n_dust = int(np.clip(700 * (mn / 2048.0) ** 2, 240, 1700))
        for _ in range(n_dust):
            cx = float(rng.uniform(0, w)); cy = float(rng.uniform(0, h))
            length = float(rng.uniform(10.0, 22.0) * scale)
            ang = flow_ang + float(rng.normal(0, 0.18))
            x0d = int(cx - np.cos(ang) * length * 0.5); y0d = int(cy - np.sin(ang) * length * 0.5)
            x1d = int(cx + np.cos(ang) * length * 0.5); y1d = int(cy + np.sin(ang) * length * 0.5)
            # Ultra-faint blend â€” slight bias
            uM = float(rng.uniform(0.42, 0.62))
            uR = float(rng.uniform(0.32, 0.50))
            uCC = float(rng.uniform(0.35, 0.58))
            _cv2.line(M, (x0d, y0d), (x1d, y1d), uM, 1, lineType=_cv2.LINE_AA)
            _cv2.line(R, (x0d, y0d), (x1d, y1d), uR, 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (x0d, y0d), (x1d, y1d), uCC, 1, lineType=_cv2.LINE_AA)

    # TIER 4 â€” 1-px crest sparkle with INDEPENDENT uniforms
    n_fl = int(np.clip(4500 * (mn / 2048.0) ** 2, 1700, 12000))
    fy = rng.integers(0, h, n_fl); fx = rng.integers(0, w, n_fl)
    M[fy, fx]  = np.maximum(M[fy, fx],  rng.uniform(0.62, 0.99, n_fl).astype(np.float32))
    R[fy, fx]  = np.minimum(R[fy, fx],  rng.uniform(0.04, 0.24, n_fl).astype(np.float32))
    CC[fy, fx] = np.minimum(CC[fy, fx], rng.uniform(0.05, 0.30, n_fl).astype(np.float32))

    # R6-TICK NEW HERO â€” RHODONEA (ROSE CURVE) CHROME RIBBONS
    # 2-4 small rose-curves r=cos(k*theta) sweep across the canvas as
    # mirror-polish ribbon flourishes. Math-curve motif â€” never used in
    # this loop. Petal counts k=3,4,5 randomized for variety; envelope
    # 10-18 px (stays inside fine-feature budget). Each ribbon has
    # INDEPENDENT continuous M/R/CC and rotates randomly.
    if _CV2_OK:
        n_rose = int(rng.integers(2, 5))
        for _ in range(n_rose):
            cx_r = float(rng.uniform(0.10, 0.90) * w)
            cy_r = float(rng.uniform(0.10, 0.90) * h)
            env_r = float(rng.uniform(10.0, 18.0) * scale)
            k_rose = int(rng.choice([3, 4, 5, 7]))
            rot_r = float(rng.uniform(0, 2 * np.pi))
            cos_r, sin_r = np.cos(rot_r), np.sin(rot_r)
            roseM = float(rng.uniform(0.72, 0.96))
            roseR = float(rng.uniform(0.04, 0.20))
            roseCC = float(rng.uniform(0.06, 0.24))
            n_pts = 80
            prev = None
            for kk in range(n_pts):
                theta = kk / float(n_pts - 1) * 2.0 * np.pi
                r_v = np.cos(k_rose * theta) * env_r
                rx = r_v * np.cos(theta)
                ry = r_v * np.sin(theta)
                # rotate
                xr = rx * cos_r - ry * sin_r
                yr = rx * sin_r + ry * cos_r
                px_r = int(np.clip(cx_r + xr, 0, w - 1))
                py_r = int(np.clip(cy_r + yr, 0, h - 1))
                if prev is not None:
                    _cv2.line(M, prev, (px_r, py_r), roseM, 1, lineType=_cv2.LINE_AA)
                    _cv2.line(R, prev, (px_r, py_r), roseR, 1, lineType=_cv2.LINE_AA)
                    _cv2.line(CC, prev, (px_r, py_r), roseCC, 1, lineType=_cv2.LINE_AA)
                prev = (px_r, py_r)

    out = np.stack([M, R, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
orbital_swirl._spb_concept_complete = True


def buffer_swirl(shape, seed, sm, n_swirls=120, **kwargs):
    """Buffer polish â€” TRIPLE-density arcs, deep ridge/valley M, bold CC variety.

    identity: A heavily buffer-polished panel where the swirl pattern reads
    LOUD. 3x the arc density of before, each arc 6-22 px, paired with a
    deep burnish-ridge / valley relief â€” adjacent arcs alternate between
    near-mirror M (>0.92) burnish RIDGES and dark-valley M (<0.18) â€” so
    contrast across the M channel is the dominant feature. Per-swirl
    INDEPENDENT M/R/CC drawn from wide continuous ranges so neighbors
    show distinct color/tint, not just position. Sharp crosshatch micro.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 4717)
    scale = max(min(h, w) / 2048.0, 0.25)
    px_unit = max(scale, 0.7)

    def _fbm(off, sigma):
        if _CV2_OK:
            sh = max(64, h // 10); sw = max(64, w // 10)
            n = np.random.default_rng(int(seed) + off).random((sh, sw)).astype(np.float32)
            b = _cv2.GaussianBlur(n, (0, 0), sigmaX=sigma, sigmaY=sigma)
            return _normalize(_cv2.resize(b, (w, h), interpolation=_cv2.INTER_CUBIC).astype(np.float32))
        return _normalize(multi_scale_noise(shape, [20, 40], [0.6, 0.4], int(seed) + off))
    fbm_M = _fbm(4720, 5.0); fbm_R = _fbm(4722, 4.0); fbm_CC = _fbm(4724, 6.0)
    M = (0.58 + (fbm_M - 0.5) * 0.30).astype(np.float32)
    R_ch = (0.30 + (fbm_R - 0.5) * 0.26).astype(np.float32)
    CC = (0.58 + (fbm_CC - 0.5) * 0.32).astype(np.float32)
    # Sharp cross-hatch micro
    yy = np.arange(h, dtype=np.float32)[:, None]
    xx = np.arange(w, dtype=np.float32)[None, :]
    hatch_a = np.sin((xx + yy) / 2.7 * 2 * np.pi)
    hatch_b = np.sin((xx - yy) / 2.7 * 2 * np.pi)
    micro = (np.maximum(hatch_a, hatch_b) > 0.0).astype(np.float32) - 0.5
    M = M + micro * 0.16
    R_ch = R_ch - micro * 0.12
    CC = CC + micro * 0.12
    grit = multi_scale_noise(shape, [2.0, 4.5, 9.0], [0.5, 0.3, 0.2], int(seed) + 4719)
    grit = _normalize(grit) - 0.5
    M = M + grit * 0.10
    R_ch = R_ch + grit * 0.12
    CC = CC + grit * 0.10

    if _CV2_OK:
        # TRIPLE density polish arcs
        n_arcs = max(2700, int(h * w / 130))
        for i in range(n_arcs):
            cx = int(rng.uniform(-0.1, 1.1) * w)
            cy = int(rng.uniform(-0.1, 1.1) * h)
            radius = int(rng.uniform(3.0, 11.0) * px_unit)  # 6-22 px diameter
            arc_start = float(rng.uniform(0, 360))
            arc_sweep = float(rng.uniform(60, 280))
            # Alternate ridge/valley for deep contrast
            is_ridge = (i % 2) == 0
            if is_ridge:
                sw_M = float(rng.uniform(0.86, 0.99))
                sw_R = float(rng.uniform(0.03, 0.15))
                sw_CC = float(rng.uniform(0.70, 0.98))
            else:
                sw_M = float(rng.uniform(0.04, 0.20))
                sw_R = float(rng.uniform(0.55, 0.88))
                sw_CC = float(rng.uniform(0.10, 0.35))
            thick = 1
            _cv2.ellipse(M, (cx, cy), (radius, radius), 0, arc_start, arc_start + arc_sweep, sw_M, thick, lineType=_cv2.LINE_AA)
            _cv2.ellipse(R_ch, (cx, cy), (radius, radius), 0, arc_start, arc_start + arc_sweep, sw_R, thick, lineType=_cv2.LINE_AA)
            _cv2.ellipse(CC, (cx, cy), (radius, radius), 0, arc_start, arc_start + arc_sweep, sw_CC, thick, lineType=_cv2.LINE_AA)
        # Wide-range tinted accent arcs (chromatic CC variety so colors stand out)
        n_tint = max(400, int(h * w / 1100))
        for _ in range(n_tint):
            cx = int(rng.uniform(0, w)); cy = int(rng.uniform(0, h))
            radius = int(rng.uniform(4.0, 10.0) * px_unit)
            arc_start = float(rng.uniform(0, 360))
            arc_sweep = float(rng.uniform(40, 200))
            # Full continuous CC range
            _cv2.ellipse(CC, (cx, cy), (radius, radius), 0, arc_start, arc_start + arc_sweep,
                         float(rng.uniform(0.08, 0.96)), 1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(M, (cx, cy), (radius, radius), 0, arc_start, arc_start + arc_sweep,
                         float(rng.uniform(0.20, 0.99)), 1, lineType=_cv2.LINE_AA)
        # Per-pixel scratch frosting
        n_sc = max(10000, int(h * w / 110))
        sy = rng.integers(0, h, n_sc); sx = rng.integers(0, w, n_sc)
        M[sy, sx] = np.maximum(M[sy, sx], rng.uniform(0.78, 0.99, n_sc).astype(np.float32))
        R_ch[sy, sx] = np.minimum(R_ch[sy, sx], rng.uniform(0.04, 0.18, n_sc).astype(np.float32))
        CC[sy, sx] = np.maximum(CC[sy, sx], rng.uniform(0.55, 0.96, n_sc).astype(np.float32))

    out = np.stack([np.clip(M, 0, 1), np.clip(R_ch, 0, 1), np.clip(CC, 0, 1)], axis=2).astype(np.float32)
    return _sm_scale(np.clip(out, 0, 1), sm).astype(np.float32)
buffer_swirl._spb_concept_complete = True

def _LEGACY_buffer_swirl_stub(*args, **kwargs):
    """Shadowed by fast_buffer_swirl via _fast() factory L11031 â€” body stripped tick 127."""
    pass


def wire_brushed_coarse(shape, seed, sm, frequency=25.0, waviness=0.06, **kwargs):
    """wire_brushed_coarse.

    identity: R6-CREATIVE tick 47 push â€” a stainless panel BRUTALIZED by a
    rotating wire wheel that has carved CIRCULAR WHEEL-PASS ARC BUNDLES into
    the surface alongside the straight bristle gouges. HERO MOTIF (new):
    20-40 ghost wheel-pass arcs (each arc tile spawns 8-16 nearly-parallel
    bristle furrows traced along a partial 30-50 deg ellipse, individual
    stroke 14-28 px) reading as places where the wire wheel physically
    contacted and rotated. Seven stacked layers: (1) INDEPENDENT FBM
    substrate M/R/CC, (2) HERO wheel-pass arc bundles with per-bundle and
    per-bristle continuous chroma, (3) wandering near-horizontal bristle
    gouges, (4) cross-pull bristle catches 8-16 px, (5) bright 1-3 px swarf
    pinpoints, (6) dark chatter pocks, (7) accent fleck floor. Per-feature
    INDEPENDENT continuous M/R/CC. Fine 1-32 px features only.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng2 = np.random.default_rng(int(seed) + 73159)
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)

    # 1) SUBSTRATE â€” INDEPENDENT FBM M/R/CC
    fM = _normalize(multi_scale_noise(shape, [1.6, 4.4, 11.0, 26.0], [0.34, 0.30, 0.22, 0.14], int(seed) + 7220))
    fR = _normalize(multi_scale_noise(shape, [1.8, 5.0, 12.0, 28.0], [0.34, 0.30, 0.22, 0.14], int(seed) + 7321))
    fCC = _normalize(multi_scale_noise(shape, [2.0, 5.6, 13.0, 30.0], [0.36, 0.28, 0.22, 0.14], int(seed) + 7422))
    M = (0.55 + (fM - 0.5) * 0.26).astype(np.float32)
    R_ch = (0.55 + (fR - 0.5) * 0.24).astype(np.float32)
    CC = (0.38 + (fCC - 0.5) * 0.22).astype(np.float32)

    if _CV2_OK:
        # 2) HERO WHEEL-PASS ARC BUNDLES â€” clusters of 8-16 nearly parallel
        # short bristle strokes traced along a shared partial-ellipse arc
        # so each bundle reads as one wheel rotation contact zone.
        n_bundles = int(np.clip(28 * (mn / 256.0), 18, 44))
        for _ in range(n_bundles):
            bcx = float(rng2.uniform(0.05, 0.95) * w)
            bcy = float(rng2.uniform(0.05, 0.95) * h)
            # arc center sits well outside the bundle so we read curve
            arc_r = float(rng2.uniform(28.0, 70.0) * scale)
            base_ang = float(rng2.uniform(0.0, 2.0 * np.pi))
            wheel_cx = bcx + np.cos(base_ang) * arc_r * 1.05
            wheel_cy = bcy + np.sin(base_ang) * arc_r * 1.05
            n_bristles = int(rng2.integers(8, 17))
            ang_span = float(rng2.uniform(0.35, 0.75))  # ~20-43 deg
            bundle_mv = float(rng2.uniform(0.45, 0.95))
            bundle_rv = float(rng2.uniform(0.12, 0.55))
            bundle_ccv = float(rng2.uniform(0.10, 0.50))
            for bi in range(n_bristles):
                t = -0.5 + (bi + 0.5) / n_bristles  # -0.5..0.5
                ba = base_ang + np.pi + t * ang_span  # pointing back toward bundle
                # short bristle stroke 14-28 px tangent to arc
                bx = wheel_cx + np.cos(ba) * arc_r
                by = wheel_cy + np.sin(ba) * arc_r
                tang_ang = ba + np.pi / 2.0 + float(rng2.uniform(-0.10, 0.10))
                blen = float(rng2.uniform(14.0, 28.0) * scale)
                x0 = int(np.clip(bx - np.cos(tang_ang) * blen * 0.5, 0, w - 1))
                y0 = int(np.clip(by - np.sin(tang_ang) * blen * 0.5, 0, h - 1))
                x1 = int(np.clip(bx + np.cos(tang_ang) * blen * 0.5, 0, w - 1))
                y1 = int(np.clip(by + np.sin(tang_ang) * blen * 0.5, 0, h - 1))
                # per-bristle continuous chroma jitter around the bundle
                mv = float(np.clip(bundle_mv + rng2.uniform(-0.18, 0.18), 0.20, 0.99))
                rv = float(np.clip(bundle_rv + rng2.uniform(-0.18, 0.18), 0.05, 0.92))
                ccv = float(np.clip(bundle_ccv + rng2.uniform(-0.18, 0.18), 0.04, 0.78))
                _cv2.line(M,    (x0, y0), (x1, y1), mv, 1, lineType=_cv2.LINE_AA)
                _cv2.line(R_ch, (x0, y0), (x1, y1), rv, 1, lineType=_cv2.LINE_AA)
                _cv2.line(CC,   (x0, y0), (x1, y1), ccv, 1, lineType=_cv2.LINE_AA)

        # 3) PRIMARY SCRATCH FURROWS â€” wandering individually-stroked gouges
        n_scr = int(np.clip(2800 * (mn / 2048.0) ** 2, 950, 9500))
        for _ in range(n_scr):
            cx = float(rng2.uniform(0.02, 0.98) * w); cy = float(rng2.uniform(0.02, 0.98) * h)
            length = float(rng2.uniform(16.0, 28.0) * scale)
            # Near-horizontal but with wobble in [-0.22, 0.22] rad
            ang = float(rng2.uniform(-0.22, 0.22))
            x2 = int(np.clip(cx + np.cos(ang) * length, 0, w - 1))
            y2 = int(np.clip(cy + np.sin(ang) * length, 0, h - 1))
            # Per-stroke INDEPENDENT continuous M / R / CC
            mv = float(rng2.uniform(0.32, 0.92))
            rv = float(rng2.uniform(0.18, 0.85))
            ccv = float(rng2.uniform(0.10, 0.55))
            _cv2.line(M,    (int(cx), int(cy)), (x2, y2), mv, 1, lineType=_cv2.LINE_AA)
            _cv2.line(R_ch, (int(cx), int(cy)), (x2, y2), rv, 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC,   (int(cx), int(cy)), (x2, y2), ccv, 1, lineType=_cv2.LINE_AA)

        # 3) CROSS-PULL BRISTLE MARKS â€” short, ~perpendicular
        n_xp = int(np.clip(900 * (mn / 2048.0) ** 2, 320, 3200))
        for _ in range(n_xp):
            cx = float(rng2.uniform(0.02, 0.98) * w); cy = float(rng2.uniform(0.02, 0.98) * h)
            length = float(rng2.uniform(8.0, 16.0) * scale)
            ang = float(rng2.uniform(np.pi / 2 - 0.20, np.pi / 2 + 0.20))
            x0 = int(np.clip(cx - np.cos(ang) * length * 0.5, 0, w - 1))
            y0 = int(np.clip(cy - np.sin(ang) * length * 0.5, 0, h - 1))
            x1 = int(np.clip(cx + np.cos(ang) * length * 0.5, 0, w - 1))
            y1 = int(np.clip(cy + np.sin(ang) * length * 0.5, 0, h - 1))
            _cv2.line(M,    (x0, y0), (x1, y1), float(rng2.uniform(0.38, 0.88)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(R_ch, (x0, y0), (x1, y1), float(rng2.uniform(0.12, 0.50)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC,   (x0, y0), (x1, y1), float(rng2.uniform(0.08, 0.40)), 1, lineType=_cv2.LINE_AA)

        # 4) CHATTER POCKS â€” dark rough pits, INDEPENDENT chroma
        n_pock = int(np.clip(900 * (mn / 2048.0) ** 2, 280, 3000))
        for _ in range(n_pock):
            cx = int(rng2.integers(0, w)); cy = int(rng2.integers(0, h))
            r = max(1, int(rng2.uniform(1.5, 3.0) * scale))
            _cv2.circle(M,    (cx, cy), r, float(rng2.uniform(0.08, 0.38)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R_ch, (cx, cy), r, float(rng2.uniform(0.62, 0.96)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC,   (cx, cy), r, float(rng2.uniform(0.42, 0.90)), -1, lineType=_cv2.LINE_AA)

    # 5) SWARF SHAVINGS â€” bright 2-3 px metallic pinpoints (vectorized)
    n_p = int(np.clip(3800 * (mn / 2048.0) ** 2, 1300, 12000))
    py = rng2.integers(0, h, n_p); px = rng2.integers(0, w, n_p)
    M[py, px]    = np.maximum(M[py, px],    rng2.uniform(0.62, 0.99, n_p).astype(np.float32))
    R_ch[py, px] = np.minimum(R_ch[py, px], rng2.uniform(0.04, 0.22, n_p).astype(np.float32))
    CC[py, px]   = np.minimum(CC[py, px],   rng2.uniform(0.04, 0.22, n_p).astype(np.float32))

    # 6) ACCENT FLECK FLOOR
    n_g = int(np.clip(3000 * (mn / 2048.0) ** 2, 1000, 10000))
    gx = rng2.integers(0, w, n_g); gy = rng2.integers(0, h, n_g)
    M[gy, gx]    = np.maximum(M[gy, gx],    rng2.uniform(0.45, 0.92, n_g).astype(np.float32))
    R_ch[gy, gx] = np.minimum(R_ch[gy, gx], rng2.uniform(0.08, 0.40, n_g).astype(np.float32))
    CC[gy, gx]   = np.minimum(CC[gy, gx],   rng2.uniform(0.08, 0.40, n_g).astype(np.float32))

    out = np.stack([np.clip(M, 0, 1), np.clip(R_ch, 0, 1), np.clip(CC, 0, 1)], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
wire_brushed_coarse._spb_concept_complete = True


def hand_polished(shape, seed, sm, num_regions=25, **kwargs):
    """hand_polished.

    identity: R6 OWNER-REBUILD â€” *iconic rotary-buffer swirl lacework on a
    show-car panel*. Owner complaint: "doesn't match name, looks like
    noise, boring". Fix: HERO motif is now the unmistakable HAND-POLISH
    SIGNATURE â€” large overlapping CIRCULAR SWIRL PATHS drawn by a buffer
    that traces FULL CIRCLES (3/4 to full loops) all over the panel,
    leaving the classic interlocking "polish-lace" look you see on dark
    show cars under sunlight. ALSO: per-feature TIGHT chroma jitter from a
    single polished-metal base (NO wide rolls). Multiple tiers:
    (a) 60-140 macro swirl loops 22-30 px (half/full circles - bright rim,
        single-pixel â€” the SIGNATURE element),
    (b) 220-420 fine micro buff hairlines 4-9 px (curved sweep),
    (c) 18-32 polished disc highlights 14-18 px (deeper rotary marks),
    (d) burnish pinpricks for sparkle,
    (e) panel FBM substrate for spec coloring.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 50921)
    mn = min(h, w)
    s = max(mn / 256.0, 0.6)
    scale = s  # alias

    def _fbm(off, sigma):
        if _CV2_OK:
            sh = max(48, h // 8); sw = max(48, w // 8)
            n = np.random.default_rng(int(seed) + off).random((sh, sw)).astype(np.float32)
            b = _cv2.GaussianBlur(n, (0, 0), sigmaX=sigma, sigmaY=sigma)
            return _normalize(_cv2.resize(b, (w, h), interpolation=_cv2.INTER_CUBIC).astype(np.float32))
        return _normalize(multi_scale_noise(shape, [20, 40], [0.6, 0.4], int(seed) + off))

    # === SUBSTRATE: deep polished metal panel ===
    # Single base (polished-aluminum) with FBM jitter â€” composite-dark balance
    fM = _fbm(7011, 5.0)
    fR = _fbm(7013, 4.4)
    fCC = _fbm(7015, 5.8)
    M = (0.48 + (fM - 0.5) * 0.10).astype(np.float32)
    R = (0.30 + (fR - 0.5) * 0.08).astype(np.float32)
    CC = (0.22 + (fCC - 0.5) * 0.14).astype(np.float32)

    # Single coherent palette base for ALL features
    BASE_M, BASE_R, BASE_C = 0.78, 0.20, 0.42  # polished aluminum / show-finish
    BUFF_M, BUFF_R, BUFF_C = 0.92, 0.10, 0.55  # bright buffer rim

    if _CV2_OK:
        # === SIGNATURE: ROTARY BUFFER SWIRL LOOPS ===
        # Real hand-polish marks: overlapping full/partial CIRCLES from the
        # rotary buffer pad. Density gives that "lacework" look across the
        # whole panel. 22-30 px diameter, single-pixel rim with bright crest.
        n_swirls = int(np.clip(100 * s * s, 60, 180))
        for _ in range(n_swirls):
            cx = int(rng.integers(0, w))
            cy = int(rng.integers(0, h))
            rr = int(np.clip(rng.uniform(11, 15) * s, 9, 16))   # radius 9-16 â†’ 18-32 px loop
            # how much of the loop is drawn: 0.6 to 1.0 turns
            arc_frac = float(rng.uniform(0.6, 1.0))
            arc_span = arc_frac * 360.0
            a0 = float(rng.uniform(0, 360))
            # TIGHT jitter from buff base
            pM = float(np.clip(BUFF_M + rng.uniform(-0.04, 0.04), 0, 1))
            pR = float(np.clip(BUFF_R + rng.uniform(-0.04, 0.04), 0, 1))
            pC = float(np.clip(BUFF_C + rng.uniform(-0.05, 0.05), 0, 1))
            # single-pixel bright rim â€” the iconic swirl mark
            _cv2.ellipse(M, (cx, cy), (rr, rr), 0, a0, a0 + arc_span, pM, 1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(R, (cx, cy), (rr, rr), 0, a0, a0 + arc_span, pR, 1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(CC, (cx, cy), (rr, rr), 0, a0, a0 + arc_span, pC, 1, lineType=_cv2.LINE_AA)
            # subtle inner shadow companion (1 px smaller, darker) â€” depth cue
            if rr > 3:
                _cv2.ellipse(M, (cx, cy), (rr - 1, rr - 1), 0, a0 + 10, a0 + arc_span * 0.7, float(BASE_M * 0.55), 1, lineType=_cv2.LINE_AA)

        # === DEEPER ROTARY DISCS â€” 18-32 brighter filled-disc rims ===
        # Where the buffer paused/repeated â€” denser polished spots
        n_disc = int(np.clip(rng.integers(18, 33), 16, 40))
        for _ in range(n_disc):
            cx = int(rng.integers(0, w))
            cy = int(rng.integers(0, h))
            rr = int(np.clip(rng.uniform(7, 10) * s, 6, 11))
            pM = float(np.clip(BASE_M + rng.uniform(-0.04, 0.04), 0, 1))
            pR = float(np.clip(BASE_R + rng.uniform(-0.04, 0.04), 0, 1))
            pC = float(np.clip(BASE_C + rng.uniform(-0.05, 0.05), 0, 1))
            # filled bright disc
            _cv2.circle(M, (cx, cy), rr, pM, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), rr, pR, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), rr, pC, -1, lineType=_cv2.LINE_AA)
            # bright rim
            _cv2.circle(M, (cx, cy), rr, 0.95, 1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), rr, 0.65, 1, lineType=_cv2.LINE_AA)

        # === MICRO BUFF HAIRLINES â€” short curved sweep marks ===
        # Drawn as tiny arcs (not straight lines) so they read as buffer wear
        n_hair = int(np.clip(320 * s * s, 200, 480))
        for _ in range(n_hair):
            cx = int(rng.integers(0, w))
            cy = int(rng.integers(0, h))
            rr = int(np.clip(rng.uniform(2.5, 4.5) * s, 2, 5))
            a0 = float(rng.uniform(0, 360))
            span = float(rng.uniform(35, 75))
            pM = float(np.clip(BASE_M + 0.12 + rng.uniform(-0.04, 0.04), 0, 1))
            pC = float(np.clip(BASE_C + 0.08 + rng.uniform(-0.04, 0.04), 0, 1))
            _cv2.ellipse(M, (cx, cy), (rr, rr), 0, a0, a0 + span, pM, 1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(CC, (cx, cy), (rr, rr), 0, a0, a0 + span, pC, 1, lineType=_cv2.LINE_AA)

        # === BURNISH PINPRICKS â€” sparkle highlights ===
        n_fl = int(np.clip(h * w / 180.0, 380, 3200))
        ys = rng.integers(0, h, n_fl)
        xs = rng.integers(0, w, n_fl)
        M[ys, xs] = np.maximum(M[ys, xs], np.clip(rng.uniform(0.82, 0.98, n_fl).astype(np.float32), 0, 1))
        R[ys, xs] = np.minimum(R[ys, xs], np.clip(rng.uniform(0.06, 0.18, n_fl).astype(np.float32), 0, 1))
        CC[ys, xs] = np.clip(rng.uniform(0.50, 0.78, n_fl).astype(np.float32), 0, 1)

    out = np.stack([M, R, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)


hand_polished._spb_concept_complete = True

def guilloche_barleycorn(shape, seed, sm, frequency=40.0, n_lobes=8, amplitude=0.3, **kwargs):
    """guilloche_barleycorn.

    identity: R6 creative rebuild â€” Patek Philippe barleycorn engine-turning.
    A dense brick-offset lattice of vertically-elongated oat-grain cells (3:1 aspect)
    each engraved with a bright micro-rim and a darker recessed core. R6 push: cells
    are smaller and finer (12-18 px wide), per-cell INDEPENDENT continuous M/R/CC
    uniforms span wide ranges so every kernel reads with its own chroma. HERO motif:
    superimposed long diagonal SUNRAY ENGRAVE LINES sweeping across the field at a
    shallow angle â€” narrow bright incisions every ~9-13 px that bisect rows. Stacked
    tiers: (1) staggered oat-grain bed, (2) hero sunray engraving sweep, (3) ultra-fine
    cross-hatched hairlines between cells, (4) bright micro-pin sparks at cell corners,
    (5) dense substrate engraving flecks for body grain.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 33912)
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)

    # Substrate â€” dark engraved metal with body grain.
    # FIX 2026-05-26: R lowered from 0.56 to 0.22 for composite-dark substrate.
    fbm_a = _normalize(multi_scale_noise(shape, [3.5, 8.0, 18.0], [0.45, 0.35, 0.20], int(seed) + 333))
    fbm_b = _normalize(multi_scale_noise(shape, [2.0, 5.0], [0.6, 0.4], int(seed) + 339))
    M = (0.30 + (fbm_a - 0.5) * 0.14 + (fbm_b - 0.5) * 0.06).astype(np.float32)
    R = (0.22 + (fbm_a - 0.5) * 0.10).astype(np.float32)
    CC = (0.26 + (fbm_a - 0.5) * 0.10 + (fbm_b - 0.5) * 0.04).astype(np.float32)

    # OAT-GRAIN CELL GRID â€” FINER cells, randomized chroma per cell
    cell_w = float(np.clip(14.0 * scale * (mn / 256.0) * rng.uniform(0.85, 1.05), 10.0, 18.0))
    cell_h = cell_w * 2.4
    oval_rx = cell_w * 0.40
    oval_ry = cell_h * 0.42

    n_rows = int(np.ceil(h / cell_h)) + 2
    n_cols = int(np.ceil(w / cell_w)) + 2
    for ri in range(-1, n_rows):
        for ci in range(-1, n_cols):
            ox = (cell_w * 0.5) if (ri % 2 == 1) else 0.0
            ccx = ci * cell_w + ox + cell_w * 0.5
            ccy = ri * cell_h + cell_h * 0.5
            if ccx < -oval_rx or ccx > w + oval_rx or ccy < -oval_ry or ccy > h + oval_ry:
                continue
            tile = int(max(oval_rx, oval_ry) * 1.4) + 2
            x0 = max(0, int(ccx) - tile); x1 = min(w, int(ccx) + tile + 1)
            y0 = max(0, int(ccy) - tile); y1 = min(h, int(ccy) + tile + 1)
            if x1 <= x0 or y1 <= y0:
                continue
            tyy, txx = np.mgrid[y0:y1, x0:x1].astype(np.float32)
            ex = (txx - ccx) / oval_rx
            ey = (tyy - ccy) / oval_ry
            d2 = ex * ex + ey * ey
            body = np.clip(1.0 - d2, 0.0, 1.0).astype(np.float32)
            rim = np.exp(-((np.sqrt(d2) - 0.92) ** 2) * 60.0).astype(np.float32)
            # WIDE per-cell INDEPENDENT continuous uniforms
            body_M = float(rng.uniform(0.20, 0.55)); body_R = float(rng.uniform(0.45, 0.92)); body_CC = float(rng.uniform(0.08, 0.40))
            rim_M = float(rng.uniform(0.55, 0.98)); rim_R = float(rng.uniform(0.05, 0.32)); rim_CC = float(rng.uniform(0.45, 0.95))
            sl_M = M[y0:y1, x0:x1]; sl_R = R[y0:y1, x0:x1]; sl_CC = CC[y0:y1, x0:x1]
            sl_M = sl_M * (1.0 - body * 0.78) + body * body_M * 0.78
            sl_R = sl_R * (1.0 - body * 0.78) + body * body_R * 0.78
            sl_CC = sl_CC * (1.0 - body * 0.78) + body * body_CC * 0.78
            sl_M = sl_M * (1.0 - rim * 0.85) + rim * rim_M * 0.85
            sl_R = sl_R * (1.0 - rim * 0.85) + rim * rim_R * 0.85
            sl_CC = sl_CC * (1.0 - rim * 0.85) + rim * rim_CC * 0.85
            M[y0:y1, x0:x1] = sl_M; R[y0:y1, x0:x1] = sl_R; CC[y0:y1, x0:x1] = sl_CC

    if _CV2_OK:
        # HERO MOTIF â€” diagonal sunray engrave lines at shallow angle
        sun_angle = float(rng.uniform(-0.35, 0.35))  # near-horizontal sweep
        sun_period = float(np.clip(11.0 * scale * (mn / 256.0), 8.0, 16.0))
        # Scan along normal direction
        nx, ny = float(-np.sin(sun_angle)), float(np.cos(sun_angle))
        # Coverage by stepping along normal in sun_period intervals
        diag = float(np.sqrt(w*w + h*h))
        n_rays = int(diag / sun_period) + 2
        cx_center, cy_center = w * 0.5, h * 0.5
        for ri in range(-n_rays // 2, n_rays // 2 + 1):
            offset = ri * sun_period + float(rng.uniform(-1.5, 1.5))
            # Line endpoints: from (-diag/2 along ray dir) to (+diag/2)
            mx = cx_center + nx * offset; my = cy_center + ny * offset
            dx = float(np.cos(sun_angle)) * diag; dy = float(np.sin(sun_angle)) * diag
            x0 = int(mx - dx); y0 = int(my - dy)
            x1 = int(mx + dx); y1 = int(my + dy)
            _cv2.line(M, (x0, y0), (x1, y1), float(rng.uniform(0.78, 0.99)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(R, (x0, y0), (x1, y1), float(rng.uniform(0.05, 0.20)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (x0, y0), (x1, y1), float(rng.uniform(0.65, 0.98)), 1, lineType=_cv2.LINE_AA)

        # FINE CROSS-HATCH hairlines between cells
        n_hair = int(np.clip(1400 * (mn / 2048.0) ** 2, 480, 3600))
        for _ in range(n_hair):
            cx = int(rng.uniform(2, w - 2)); cy = int(rng.uniform(2, h - 2))
            length = max(2, int(rng.uniform(3.0, 7.0) * scale))
            ang = float(rng.choice([0.0, np.pi*0.5, sun_angle]))
            dx = int(np.cos(ang) * length); dy = int(np.sin(ang) * length)
            _cv2.line(M, (cx, cy), (cx + dx, cy + dy), float(rng.uniform(0.50, 0.92)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (cx, cy), (cx + dx, cy + dy), float(rng.uniform(0.50, 0.92)), 1, lineType=_cv2.LINE_AA)

        # ENGRAVED SPARKS at random cell corners (1-2 px)
        n_spk = int(np.clip(1400 * (mn / 2048.0) ** 2, 480, 3600))
        sy = rng.integers(0, h, size=n_spk); sx = rng.integers(0, w, size=n_spk)
        M[sy, sx] = rng.uniform(0.65, 0.99, size=n_spk).astype(np.float32)
        R[sy, sx] = rng.uniform(0.05, 0.22, size=n_spk).astype(np.float32)
        CC[sy, sx] = rng.uniform(0.55, 0.98, size=n_spk).astype(np.float32)

        # SUBSTRATE FLECKS â€” body grain
        n_grain = int(np.clip(1800 * (mn / 2048.0) ** 2, 600, 4800))
        gy = rng.integers(0, h, size=n_grain); gx = rng.integers(0, w, size=n_grain)
        M[gy, gx] = (M[gy, gx] * 0.7 + rng.uniform(0.20, 0.85, size=n_grain).astype(np.float32) * 0.3)
        R[gy, gx] = (R[gy, gx] * 0.7 + rng.uniform(0.20, 0.85, size=n_grain).astype(np.float32) * 0.3)
        CC[gy, gx] = (CC[gy, gx] * 0.7 + rng.uniform(0.15, 0.80, size=n_grain).astype(np.float32) * 0.3)

        # NEW HERO (R6-Loop tick 2026-05-26): CAFE-WALL OPTICAL ILLUSION TRIGGER DOTS.
        # Optical-illusion motif: bright 2-3 px trigger dots placed at the
        # MID-POINTS between staggered cell rows so the eye sees a slight
        # downward slope along each row â€” the classic Munsterberg cafe-wall
        # effect. Plus thin dark mortar hairlines between rows. The dots'
        # row offset (half-period vs none) alternates per row pair, creating
        # the illusion of converging rows on a perfectly regular grid.
        # TIGHT chroma jitter from a single onyx-trigger palette.
        n_row_dots = int(np.ceil(h / cell_h)) + 2
        n_col_dots = int(np.ceil(w / cell_w)) + 2
        for ri in range(-1, n_row_dots):
            row_parity = ri % 4
            if row_parity not in (1, 2):
                continue  # only paint every other row pair to keep illusion subtle
            # offset alternates between rows of the pair
            row_offset = cell_w * 0.25 if row_parity == 1 else cell_w * 0.75
            dot_y = ri * cell_h + cell_h * 0.5 + cell_h * 0.5
            for ci in range(-1, n_col_dots):
                dot_x = ci * cell_w + row_offset
                if dot_x < 0 or dot_x >= w or dot_y < 0 or dot_y >= h:
                    continue
                cx_d, cy_d = int(dot_x), int(dot_y)
                # TIGHT jitter from onyx-trigger palette
                base_M = 0.92 + float(rng.uniform(-0.04, 0.04))
                base_R = 0.08 + float(rng.uniform(-0.04, 0.04))
                base_CC = 0.18 + float(rng.uniform(-0.04, 0.04))
                rr = max(1, int(rng.uniform(1.5, 2.5)))
                _cv2.circle(M, (cx_d, cy_d), rr, float(np.clip(base_M, 0, 1)), -1, lineType=_cv2.LINE_AA)
                _cv2.circle(R, (cx_d, cy_d), rr, float(np.clip(base_R, 0, 1)), -1, lineType=_cv2.LINE_AA)
                _cv2.circle(CC, (cx_d, cy_d), rr, float(np.clip(base_CC, 0, 1)), -1, lineType=_cv2.LINE_AA)

    out = np.stack([np.clip(M, 0, 1), np.clip(R, 0, 1), np.clip(CC, 0, 1)], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
guilloche_barleycorn._spb_concept_complete = True


def guilloche_hobnail(shape, seed, sm, spacing=16, dome_radius_frac=0.45, **kwargs):
    """guilloche_hobnail.

    identity: R6 creative rebuild â€” a HEXAGONAL honeycomb pin-jewel field.
    Breaks the square-lattice cliche by using a true hex lattice: each row of
    pin-domes is offset by half-pitch so the dots cluster like honeycomb cells.
    Pitch 10-14 px gives fine raised pin-heads with directional 3D lighting
    (upper-left highlight, lower-right shadow). HERO MOTIF: 5-9 "JEWEL CAP"
    pins â€” slightly larger 8-12 px domes with prismatic per-channel hue lit
    by extra bright halos, scattered across the canvas as if a few rare cells
    have been crowned. Per-pin INDEPENDENT continuous M/R/CC via hash-modulus.
    Plus engraved hex-edge stitches between cells and 1-px tip glints.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 90871)
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)

    # Substrate â€” dark engraved metal between pins.
    # FIX 2026-05-26: R was 0.66 (too high â†’ green composite). Now 0.22 keeps the
    # interstitial recess dark so the per-pin chroma reads.
    fbm = _normalize(multi_scale_noise(shape, [3.0, 7.0, 16.0], [0.45, 0.35, 0.20], int(seed) + 333))
    M = (0.22 + (fbm - 0.5) * 0.12).astype(np.float32)
    R = (0.22 + (fbm - 0.5) * 0.10).astype(np.float32)
    CC = (0.22 + (fbm - 0.5) * 0.10).astype(np.float32)

    # HEX LATTICE â€” true honeycomb, not square
    yy, xx = np.mgrid[0:h, 0:w].astype(np.float32)
    pitch = max(10.0, float(spacing) * 0.75)
    row_h = pitch * 0.866  # sqrt(3)/2 â€” vertical hex spacing
    # Row index from y
    row_idx = np.floor(yy / row_h).astype(np.int32)
    # Half-pitch horizontal offset on odd rows
    x_off = (row_idx & 1).astype(np.float32) * (pitch * 0.5)
    cx_mod = ((xx - x_off) % pitch) - pitch * 0.5
    cy_mod = (yy % row_h) - row_h * 0.5
    # Pin disc
    r2 = (cx_mod * cx_mod + cy_mod * cy_mod) / (pitch * 0.42) ** 2
    pin = np.clip(1.0 - r2, 0.0, 1.0).astype(np.float32)
    # Directional lighting
    light_dx = cx_mod + pitch * 0.20
    light_dy = cy_mod + pitch * 0.20
    light_r2 = (light_dx * light_dx + light_dy * light_dy) / (pitch * 0.30) ** 2
    highlight = np.exp(-light_r2).astype(np.float32) * pin
    shadow_dx = cx_mod - pitch * 0.20
    shadow_dy = cy_mod - pitch * 0.20
    shadow_r2 = (shadow_dx * shadow_dx + shadow_dy * shadow_dy) / (pitch * 0.32) ** 2
    shadow = np.exp(-shadow_r2).astype(np.float32) * pin

    # Per-pin independent chroma via hex-cell hash
    col_idx = np.floor((xx - x_off) / pitch).astype(np.int32)
    h_m = (np.mod(row_idx * 53 + col_idx * 89 + int(seed) * 13, 991).astype(np.float32) / 991.0)
    h_r = (np.mod(row_idx * 71 + col_idx * 113 + int(seed) * 17, 983).astype(np.float32) / 983.0)
    h_c = (np.mod(row_idx * 97 + col_idx * 131 + int(seed) * 19, 977).astype(np.float32) / 977.0)

    M = M + pin * (0.30 + h_m * 0.30)
    R = R - pin * (0.30 + h_r * 0.18)
    CC = CC + pin * (0.30 + h_c * 0.28)
    M = M + highlight * (0.35 + h_m * 0.10)
    R = R - highlight * (0.20 + h_r * 0.10)
    CC = CC + highlight * (0.30 + h_c * 0.12)
    M = M - shadow * 0.22
    R = R + shadow * 0.18
    CC = CC - shadow * 0.18

    np.clip(M, 0, 1, out=M); np.clip(R, 0, 1, out=R); np.clip(CC, 0, 1, out=CC)

    if _CV2_OK:
        # HERO â€” JEWEL CAP pins: 5-9 prismatic crowned cells
        n_jewel = int(rng.integers(5, 10))
        for _ in range(n_jewel):
            jx = int(rng.uniform(0.08, 0.92) * w)
            jy = int(rng.uniform(0.08, 0.92) * h)
            jr = int(rng.uniform(8.0, 12.0) * scale)
            # bright crown halo (outer)
            _cv2.circle(M, (jx, jy), jr + 3, float(rng.uniform(0.78, 0.96)), 1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (jx, jy), jr + 3, float(rng.uniform(0.78, 0.96)), 1, lineType=_cv2.LINE_AA)
            # main dome
            _cv2.circle(M, (jx, jy), jr, float(rng.uniform(0.78, 0.99)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (jx, jy), jr, float(rng.uniform(0.04, 0.16)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (jx, jy), jr, float(rng.uniform(0.78, 0.99)), -1, lineType=_cv2.LINE_AA)
            # prismatic highlight at top-left
            hlx = int(jx - jr * 0.42); hly = int(jy - jr * 0.42)
            _cv2.circle(M, (hlx, hly), max(1, int(jr * 0.30)), 0.99, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (hlx, hly), max(1, int(jr * 0.30)), 0.99, -1, lineType=_cv2.LINE_AA)

        # Engraved hex-edge stitches â€” short diagonal hairlines between cells
        n_int = int(np.clip(900 * (mn / 2048.0) ** 2, 300, 2400))
        for _ in range(n_int):
            cx = int(rng.uniform(0, w)); cy = int(rng.uniform(0, h))
            arm = max(1, int(rng.uniform(1.0, 2.2)))
            ang = float(rng.choice([0.0, 1.047, 2.094]))  # 0, 60, 120 deg
            dx = int(np.cos(ang) * arm); dy = int(np.sin(ang) * arm)
            _cv2.line(R, (cx - dx, cy - dy), (cx + dx, cy + dy),
                     float(rng.uniform(0.55, 0.85)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(M, (cx - dx, cy - dy), (cx + dx, cy + dy),
                     float(rng.uniform(0.15, 0.35)), 1, lineType=_cv2.LINE_AA)

    # Final tip-glints
    n_spk = max(800, int(h * w / 6000))
    sy = rng.integers(0, h, n_spk); sx = rng.integers(0, w, n_spk)
    M[sy, sx] = np.maximum(M[sy, sx], rng.uniform(0.70, 0.96, n_spk).astype(np.float32))
    R[sy, sx] = np.minimum(R[sy, sx], rng.uniform(0.05, 0.22, n_spk).astype(np.float32))
    CC[sy, sx] = np.maximum(CC[sy, sx], rng.uniform(0.55, 0.92, n_spk).astype(np.float32))

    # NEW HERO (R6-Loop tick 2026-05-26): ROSE-CURVE PETAL OVERLAYS.
    # Math motif r = a*cos(k*theta) traced as polylines. 10-18 small rose
    # rosettes (k=3,4,5,7 petals) scattered across the canvas, 12-22 px
    # radius, drawn as bright burnish curves layered over groups of pins
    # â€” like a watchmaker engraved decorative florets between the honeycomb.
    # TIGHT per-rosette chroma jitter from a single platinum palette.
    if _CV2_OK:
        n_rose = int(rng.integers(10, 19))
        for _ in range(n_rose):
            rx = float(rng.uniform(0.07, 0.93) * w)
            ry = float(rng.uniform(0.07, 0.93) * h)
            amp = float(rng.uniform(12.0, 22.0)) * scale
            k_pet = float(rng.choice([3.0, 4.0, 5.0, 7.0]))
            steps = 60
            theta = np.linspace(0.0, 2.0 * np.pi, steps, dtype=np.float32)
            r_curve = amp * np.cos(k_pet * theta)
            xs = (rx + r_curve * np.cos(theta)).astype(np.int32)
            ys = (ry + r_curve * np.sin(theta)).astype(np.int32)
            pts = np.stack([xs, ys], axis=-1)
            # TIGHT platinum palette + small jitter
            base_M = 0.88 + float(rng.uniform(-0.04, 0.04))
            base_R = 0.10 + float(rng.uniform(-0.04, 0.04))
            base_CC = 0.86 + float(rng.uniform(-0.04, 0.04))
            _cv2.polylines(M, [pts], True, float(np.clip(base_M, 0, 1)), 1, lineType=_cv2.LINE_AA)
            _cv2.polylines(R, [pts], True, float(np.clip(base_R, 0, 1)), 1, lineType=_cv2.LINE_AA)
            _cv2.polylines(CC, [pts], True, float(np.clip(base_CC, 0, 1)), 1, lineType=_cv2.LINE_AA)

    out = np.stack([np.clip(M, 0, 1), np.clip(R, 0, 1), np.clip(CC, 0, 1)], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
guilloche_hobnail._spb_concept_complete = True


def guilloche_waves(shape, seed, sm, x_freq=60.0, y_mod_freq=8.0, amplitude=0.15, **kwargs):
    """guilloche_waves.

    identity: R6 tick 2026-05-26 â€” owner rated 3/REBUILD ("cross razor
    ribbons look crappy"). REMOVED the braided ribbon HERO motif entirely.
    NEW CREATIVE: classic engine-turned guillochÃ© wave engraving â€” long
    serpentine wave-engrave lines running across the panel, each line a
    smooth sinusoid with vertical phase drift (like the back of a Vacheron
    pocket watch). Multiple frequency-staggered carrier sets create a
    delicate moirÃ© beat WITHOUT chaotic crossing ribbons. Bright burin
    cut + dark groove shadow per line. Tight chroma jitter from a single
    cool-silver palette (NO rainbow rolls). Pure wave engraving, no braid.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 80217)
    mn = min(h, w); s = max(mn / 256.0, 0.6)

    yy_g, xx_g = np.mgrid[0:h, 0:w].astype(np.float32)
    xx_n = xx_g / w
    yy_n = yy_g / h

    # 1) Substrate â€” cool guillochÃ© silver, composite-mid (not green)
    fbm = _normalize(multi_scale_noise(shape, [3.0, 8.0, 16.0], [0.55, 0.30, 0.15], int(seed) + 4011))
    BASE_M, BASE_R, BASE_CC = 0.30, 0.45, 0.28
    M  = (BASE_M  + (fbm - 0.5) * 0.06).astype(np.float32)
    R  = (BASE_R  + (fbm - 0.5) * 0.06).astype(np.float32)
    CC = (BASE_CC + (fbm - 0.5) * 0.05).astype(np.float32)

    # 2) Three frequency-staggered wave-engrave carriers â€” long serpentine
    #    lines across the panel. Phase drifts smoothly so lines bend.
    periods = [10.0 * s, 14.0 * s, 20.0 * s]  # 10-20 px line spacing
    drift_freqs = [1.6, 2.4, 0.9]              # how often the carrier bends
    drift_amps = [0.06, 0.04, 0.08]            # bend amplitude in screen frac
    weights = [0.32, 0.22, 0.16]
    phase_base = float(rng.uniform(0, 2 * np.pi))
    for k, (p, df, da, wt) in enumerate(zip(periods, drift_freqs, drift_amps, weights)):
        # Carrier y = yy + drift(xx) â€” gives serpentine line crests
        drift = da * mn * np.sin(xx_n * np.pi * df + phase_base + k * 1.3)
        u = (yy_g + drift) * (2 * np.pi / max(p, 4.0))
        line = 0.5 + 0.5 * np.cos(u)
        # Ridge = bright burin cut, trough = dark groove shadow
        ridge = np.exp(-((line - 1.0) ** 2) * 12.0).astype(np.float32)
        trough = np.exp(-(line ** 2) * 12.0).astype(np.float32)
        M  = M  + (ridge - trough) * wt * 0.55
        CC = CC + (ridge - trough) * wt * 0.42
        R  = R  - (ridge - trough) * wt * 0.30

    # 3) ONE softer counter-direction wave for moirÃ© beat (NOT cross ribbons)
    drift2 = 0.05 * mn * np.cos(yy_n * np.pi * 1.4 + phase_base * 0.7)
    u2 = (xx_g + drift2) * (2 * np.pi / max(16.0 * s, 4.0))
    line2 = 0.5 + 0.5 * np.cos(u2)
    ridge2 = np.exp(-((line2 - 1.0) ** 2) * 12.0).astype(np.float32)
    M  = M  + ridge2 * 0.08
    CC = CC + ridge2 * 0.06
    R  = R  - ridge2 * 0.05

    M = M.astype(np.float32); R = R.astype(np.float32); CC = CC.astype(np.float32)

    if _CV2_OK:
        # 4) Sparse silver flecks at constructive nodes (small, restrained)
        n_spk = int(np.clip(h * w / 600.0, 150, 1200))
        sy = rng.integers(0, h, n_spk); sx = rng.integers(0, w, n_spk)
        M[sy, sx]  = np.clip(M[sy, sx]  + rng.uniform(0.16, 0.22, n_spk).astype(np.float32), 0, 1)
        CC[sy, sx] = np.clip(CC[sy, sx] + rng.uniform(0.12, 0.18, n_spk).astype(np.float32), 0, 1)
        R[sy, sx]  = np.clip(R[sy, sx]  - rng.uniform(0.08, 0.12, n_spk).astype(np.float32), 0, 1)

        # 5) Dark recess pits in deep grooves
        n_pit = int(np.clip(h * w / 1100.0, 90, 700))
        py = rng.integers(0, h, n_pit); px = rng.integers(0, w, n_pit)
        M[py, px]  = np.clip(M[py, px]  - rng.uniform(0.14, 0.20, n_pit).astype(np.float32), 0, 1)
        R[py, px]  = np.clip(R[py, px]  + rng.uniform(0.16, 0.22, n_pit).astype(np.float32), 0, 1)

    out = np.stack([M, R, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
guilloche_waves._spb_concept_complete = True


def guilloche_sunray(shape, seed, sm, n_rays=72, ring_freq=20.0, ray_fade=0.6, **kwargs):
    """guilloche_sunray.

    identity: TRUE radial sunburst â€” explicit long ray-spokes drawn from a
    single center point all the way out to the canvas edge via cv2.line so
    the rays READ AS RAYS, not as a sin field. 96 primary spokes at uniform
    angular spacing, 96 thinner intermediate ray-fragments at half-radius,
    and a small set of explicit concentric ring contours crossing them.
    Distinct from guilloche_waves (no horizontal-only carrier), from
    guilloche_moire_eng (single center, not two), and from radial_sunburst
    by the layered ring contours making it a sunray-DIAL not a sunburst.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 71024)
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)
    cy_c = h * 0.5 + float(rng.uniform(-h * 0.015, h * 0.015))
    cx_c = w * 0.5 + float(rng.uniform(-w * 0.015, w * 0.015))

    # 1) BASE â€” quiet dark-bronze dial substrate, independent M/R/CC FBMs
    gM = _normalize(multi_scale_noise(shape, [3.0, 8.0, 18.0], [0.45, 0.32, 0.23], int(seed) + 3201))
    gR = _normalize(multi_scale_noise(shape, [3.5, 9.0, 20.0], [0.45, 0.32, 0.23], int(seed) + 3203))
    gCC = _normalize(multi_scale_noise(shape, [4.0, 10.0, 22.0], [0.45, 0.32, 0.23], int(seed) + 3205))
    M = (0.32 + (gM - 0.5) * 0.20).astype(np.float32)
    R = (0.62 + (gR - 0.5) * 0.20).astype(np.float32)
    CC = (0.42 + (gCC - 0.5) * 0.20).astype(np.float32)

    radius_max = float(np.hypot(h, w)) * 0.55

    if _CV2_OK:
        # 2) PRIMARY RAY SPOKES â€” 96 explicit lines from center to edge
        n_primary = 96
        for i in range(n_primary):
            ang = (i / n_primary) * 2 * np.pi + float(rng.uniform(-0.005, 0.005))
            x1 = int(cx_c + np.cos(ang) * radius_max)
            y1 = int(cy_c + np.sin(ang) * radius_max)
            pM = float(rng.uniform(0.62, 0.96))
            pR = float(rng.uniform(0.06, 0.28))
            pCC = float(rng.uniform(0.05, 0.24))
            thick = max(1, int(scale * 1.1))
            _cv2.line(M, (int(cx_c), int(cy_c)), (x1, y1), pM, thick, lineType=_cv2.LINE_AA)
            _cv2.line(R, (int(cx_c), int(cy_c)), (x1, y1), pR, thick, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (int(cx_c), int(cy_c)), (x1, y1), pCC, thick, lineType=_cv2.LINE_AA)

        # 3) INTERMEDIATE RAY-FRAGMENTS â€” half-length, between primary rays
        n_inter = 96
        for i in range(n_inter):
            ang = (i / n_inter + 0.5 / n_inter) * 2 * np.pi
            r0 = float(rng.uniform(0.10, 0.18)) * radius_max
            r1 = float(rng.uniform(0.45, 0.95)) * radius_max
            x0 = int(cx_c + np.cos(ang) * r0); y0 = int(cy_c + np.sin(ang) * r0)
            x1 = int(cx_c + np.cos(ang) * r1); y1 = int(cy_c + np.sin(ang) * r1)
            iM = float(rng.uniform(0.45, 0.82))
            iR = float(rng.uniform(0.12, 0.35))
            iCC = float(rng.uniform(0.10, 0.32))
            _cv2.line(M, (x0, y0), (x1, y1), iM, 1, lineType=_cv2.LINE_AA)
            _cv2.line(R, (x0, y0), (x1, y1), iR, 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (x0, y0), (x1, y1), iCC, 1, lineType=_cv2.LINE_AA)

        # 4) CONCENTRIC RING CONTOURS â€” 6 actual circles
        n_rings = 6
        for k in range(n_rings):
            rr = int(radius_max * ((k + 1) / (n_rings + 1)) * 0.92)
            rM = float(rng.uniform(0.55, 0.85))
            rR = float(rng.uniform(0.15, 0.36))
            rCC = float(rng.uniform(0.12, 0.32))
            _cv2.circle(M, (int(cx_c), int(cy_c)), rr, rM, 1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (int(cx_c), int(cy_c)), rr, rR, 1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (int(cx_c), int(cy_c)), rr, rCC, 1, lineType=_cv2.LINE_AA)

        # 5) CENTER HUB â€” small bright disc
        hub_r = max(3, int(min(h, w) * 0.012))
        _cv2.circle(M, (int(cx_c), int(cy_c)), hub_r, 0.92, -1, lineType=_cv2.LINE_AA)
        _cv2.circle(R, (int(cx_c), int(cy_c)), hub_r, 0.10, -1, lineType=_cv2.LINE_AA)
        _cv2.circle(CC, (int(cx_c), int(cy_c)), hub_r, 0.08, -1, lineType=_cv2.LINE_AA)

    # 6) Intersection sparks along rings
    n_spk = int(np.clip(900 * (mn / 2048.0) ** 2, 320, 2600))
    sy = rng.integers(0, h, n_spk); sx = rng.integers(0, w, n_spk)
    M[sy, sx] = np.maximum(M[sy, sx], rng.uniform(0.65, 0.96, n_spk).astype(np.float32))
    R[sy, sx] = np.minimum(R[sy, sx], rng.uniform(0.05, 0.22, n_spk).astype(np.float32))
    CC[sy, sx] = np.minimum(CC[sy, sx], rng.uniform(0.05, 0.22, n_spk).astype(np.float32))

    out = np.stack([M, R, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
guilloche_sunray._spb_concept_complete = True


def guilloche_moire_eng(shape, seed, sm, freq=30.0, offset_frac=0.15, **kwargs):
    """guilloche_moire_eng.

    identity: R6 creative rebuild â€” a THREE-CENTER moire engraving where three
    independent ring engravings beat against each other producing a triangular
    interference rosette. Each ring center carries its own pitch (7/9/11 px)
    creating compound beats. HERO MOTIF: at the geometric centroid of the
    three origins a bright "bullseye crown" â€” 5 stacked concentric AA rings
    burnished into the metal. Per-ring INDEPENDENT continuous M/R/CC uniforms.
    Constructive nodes spark gold; cancellation nodes engrave dark.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 60314)
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)

    # THREE ring centers â€” triangular layout, varied positions per seed
    cx1 = float(w * rng.uniform(0.18, 0.30)); cy1 = float(h * rng.uniform(0.18, 0.30))
    cx2 = float(w * rng.uniform(0.70, 0.84)); cy2 = float(h * rng.uniform(0.20, 0.34))
    cx3 = float(w * rng.uniform(0.40, 0.58)); cy3 = float(h * rng.uniform(0.72, 0.86))

    # SUBSTRATE â€” triple-beat field for chroma background
    yy, xx = np.mgrid[0:h, 0:w].astype(np.float32)
    d1 = np.sqrt((xx - cx1) ** 2 + (yy - cy1) ** 2)
    d2 = np.sqrt((xx - cx2) ** 2 + (yy - cy2) ** 2)
    d3 = np.sqrt((xx - cx3) ** 2 + (yy - cy3) ** 2)
    f1 = freq; f2 = freq * 1.18; f3 = freq * 0.88
    beat = (np.sin(d1 / max(mn, 1) * f1 * np.pi * 2)
            + np.sin(d2 / max(mn, 1) * f2 * np.pi * 2)
            + np.sin(d3 / max(mn, 1) * f3 * np.pi * 2)) / 3.0
    beat_n = (beat + 1.0) * 0.5
    grain = _normalize(multi_scale_noise(shape, [3.0, 8.0, 20.0], [0.42, 0.34, 0.24], int(seed) + 11))
    M = (0.32 + (beat_n - 0.5) * 0.20 + (grain - 0.5) * 0.10).astype(np.float32)
    R = (0.54 - (beat_n - 0.5) * 0.14 + (1.0 - grain) * 0.08).astype(np.float32)
    CC = (0.32 + (beat_n - 0.5) * 0.18 + (grain - 0.5) * 0.06).astype(np.float32)

    if _CV2_OK:
        # THREE sets of actual ring contours, each with its own pitch
        max_rad = int(np.hypot(w, h))
        centers = [(cx1, cy1, max(5, int(7.0 * scale)), 37, 53, 71),
                   (cx2, cy2, max(5, int(9.0 * scale)), 41, 59, 79),
                   (cx3, cy3, max(5, int(11.0 * scale)), 47, 61, 83)]
        for (cxc, cyc, step, sM, sCC, sR) in centers:
            for ri, rad in enumerate(range(step, max_rad, step)):
                v_M = float(rng.uniform(0.42, 0.96))
                v_CC = float(rng.uniform(0.38, 0.92))
                v_R = float(rng.uniform(0.08, 0.38))
                _cv2.circle(M, (int(cxc), int(cyc)), rad, v_M, 1, lineType=_cv2.LINE_AA)
                _cv2.circle(CC, (int(cxc), int(cyc)), rad, v_CC, 1, lineType=_cv2.LINE_AA)
                _cv2.circle(R, (int(cxc), int(cyc)), rad, v_R, 1, lineType=_cv2.LINE_AA)

        # HERO MOTIF â€” centroid bullseye crown
        cxh = int((cx1 + cx2 + cx3) / 3.0)
        cyh = int((cy1 + cy2 + cy3) / 3.0)
        for ring_i in range(5):
            rad = int(4 + ring_i * 4 * scale)
            _cv2.circle(M, (cxh, cyh), rad, float(rng.uniform(0.82, 0.99)), 2, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cxh, cyh), rad, float(rng.uniform(0.04, 0.14)), 2, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cxh, cyh), rad, float(rng.uniform(0.80, 0.98)), 2, lineType=_cv2.LINE_AA)
        # Bullseye core dot
        _cv2.circle(M, (cxh, cyh), max(2, int(3 * scale)), 0.98, -1, lineType=_cv2.LINE_AA)
        _cv2.circle(CC, (cxh, cyh), max(2, int(3 * scale)), 0.98, -1, lineType=_cv2.LINE_AA)
        _cv2.circle(R, (cxh, cyh), max(2, int(3 * scale)), 0.04, -1, lineType=_cv2.LINE_AA)

        # CONSTRUCTIVE INTERFERENCE SPARKS â€” only where beat is high
        n_sp = int(np.clip(1400 * (mn / 2048.0) ** 2, 480, 3200))
        for _ in range(n_sp):
            cxd = int(rng.integers(0, w)); cyd = int(rng.integers(0, h))
            if beat_n[cyd, cxd] < 0.68:
                continue
            r_d = max(1, int(rng.uniform(1.0, 2.4) * scale))
            _cv2.circle(M, (cxd, cyd), r_d, float(rng.uniform(0.78, 0.99)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cxd, cyd), r_d, float(rng.uniform(0.04, 0.18)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cxd, cyd), r_d, float(rng.uniform(0.72, 0.96)), -1, lineType=_cv2.LINE_AA)
        # CANCELLATION DARK NODES â€” only where beat is low
        n_dk = int(np.clip(1100 * (mn / 2048.0) ** 2, 360, 2600))
        for _ in range(n_dk):
            cxd = int(rng.integers(0, w)); cyd = int(rng.integers(0, h))
            if beat_n[cyd, cxd] > 0.32:
                continue
            r_d = max(1, int(rng.uniform(1.0, 2.4) * scale))
            _cv2.circle(M, (cxd, cyd), r_d, float(rng.uniform(0.06, 0.22)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cxd, cyd), r_d, float(rng.uniform(0.62, 0.92)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cxd, cyd), r_d, float(rng.uniform(0.08, 0.26)), -1, lineType=_cv2.LINE_AA)

        # Engraved tool burnish â€” short connecting arcs between the 3 centers
        for (cxa, cya, cxb, cyb) in [(cx1, cy1, cx2, cy2), (cx2, cy2, cx3, cy3), (cx3, cy3, cx1, cy1)]:
            mxp = (cxa + cxb) / 2; myp = (cya + cyb) / 2
            n_arc = 18
            for k in range(n_arc):
                t = k / float(n_arc - 1)
                px = int(cxa * (1 - t) + cxb * t)
                py = int(cya * (1 - t) + cyb * t)
                _cv2.circle(M, (px, py), max(1, int(1.6 * scale)),
                           float(rng.uniform(0.60, 0.92)), -1, lineType=_cv2.LINE_AA)
                _cv2.circle(CC, (px, py), max(1, int(1.6 * scale)),
                           float(rng.uniform(0.65, 0.95)), -1, lineType=_cv2.LINE_AA)
    out = np.stack([np.clip(M, 0, 1), np.clip(R, 0, 1), np.clip(CC, 0, 1)], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
guilloche_moire_eng._spb_concept_complete = True


def jeweling_circles(shape, seed, sm, spacing=14, circle_radius_frac=0.55, **kwargs):
    """jeweling_circles.

    identity: Tick-44 creative rebuild â€” ENGINE-TURNED jeweling, the precision
    decorative finish from watchmaking and firearm receivers. Hero motif:
    a TIGHT staggered grid of overlapping jewel cells where each cell
    (10-18 px diameter) is a true engine-turned swirl built from
    NESTED ROTATING ARCS â€” not a flat ring but multiple eccentric arc
    sweeps (3-5 arcs per cell at slightly offset centers and angles)
    that emulate the cycloidal pattern of an actual rose-engine bit.
    Each cell has INDEPENDENT per-cell continuous M/R/CC chroma and an
    INDEPENDENT random base angle, so the field reads as live machined
    jewels not stamped clones. Around the jewels: thin TRAVEL HAIRLINES
    between cells (the cutter's lift trails), a dense BURNISH-RING
    layer at cell rims, a CENTER PIN-DOT per cell (the spindle dimple),
    and a vectorized 1-2 px sparkle carpet so the substrate stays alive.
    Faint independent-FBM brushed substrate underneath. Wide M/R/CC
    spread, no macro panel scale, no 8-tier palette.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 93744)
    scale = max(min(h, w) / 2048.0, 0.25)

    def _fbm(off, sigma):
        if _CV2_OK:
            sh = max(64, h // 10); sw = max(64, w // 10)
            n = np.random.default_rng(int(seed) + off).random((sh, sw)).astype(np.float32)
            b = _cv2.GaussianBlur(n, (0, 0), sigmaX=sigma, sigmaY=sigma)
            return _normalize(_cv2.resize(b, (w, h), interpolation=_cv2.INTER_CUBIC).astype(np.float32))
        return _normalize(multi_scale_noise(shape, [20, 40], [0.6, 0.4], int(seed) + off))

    # 1) INDEPENDENT FBM brushed substrate per channel
    fM = _fbm(9421, 5.5); fR = _fbm(9423, 5.5); fCC = _fbm(9425, 5.5)
    M  = (0.55 + (fM  - 0.5) * 0.20).astype(np.float32)
    R  = (0.28 + (fR  - 0.5) * 0.18).astype(np.float32)
    CC = (0.22 + (fCC - 0.5) * 0.20).astype(np.float32)

    cell_centers = []
    if _CV2_OK:
        # 2) HERO: tight staggered jewel grid with nested rotating arcs per cell
        sp = max(8, int(spacing * scale * 1.0))
        cell_rad = max(4, int(sp * 0.70))
        for j, cy in enumerate(range(cell_rad, h + cell_rad, sp)):
            row_off = (sp // 2) if (j % 2) else 0
            for cx in range(cell_rad + row_off, w + cell_rad, sp):
                jcx = int(cx + rng.integers(-1, 2))
                jcy = int(cy + rng.integers(-1, 2))
                # INDEPENDENT per-cell continuous M/R/CC chroma
                cell_M = float(rng.uniform(0.60, 0.98))
                cell_R = float(rng.uniform(0.05, 0.26))
                cell_CC = float(rng.uniform(0.04, 0.34))
                base_ang = float(rng.uniform(0, 2 * np.pi))
                # Nested rotating arcs â€” 3-5 per cell, eccentric centers
                n_arcs = int(rng.integers(3, 6))
                for a in range(n_arcs):
                    arc_ang = base_ang + a * float(rng.uniform(0.18, 0.42))
                    ecc = cell_rad * float(rng.uniform(0.10, 0.30))
                    ax = int(jcx + np.cos(arc_ang) * ecc)
                    ay = int(jcy + np.sin(arc_ang) * ecc)
                    arc_r = max(2, int(cell_rad * float(rng.uniform(0.40, 0.85))))
                    # arc span â€” partial sweep, not full ring
                    start_deg = float(np.degrees(arc_ang) - 35.0)
                    end_deg = float(np.degrees(arc_ang) + 35.0)
                    fade = 1.0 - (a / max(1, n_arcs)) * 0.35
                    _cv2.ellipse(M, (ax, ay), (arc_r, arc_r), 0.0, start_deg, end_deg,
                                 cell_M * fade, 1, lineType=_cv2.LINE_AA)
                    _cv2.ellipse(R, (ax, ay), (arc_r, arc_r), 0.0, start_deg, end_deg,
                                 cell_R, 1, lineType=_cv2.LINE_AA)
                    _cv2.ellipse(CC, (ax, ay), (arc_r, arc_r), 0.0, start_deg, end_deg,
                                 cell_CC, 1, lineType=_cv2.LINE_AA)
                # BURNISH RIM
                _cv2.circle(M, (jcx, jcy), cell_rad, float(rng.uniform(0.62, 0.94)), 1, lineType=_cv2.LINE_AA)
                _cv2.circle(R, (jcx, jcy), cell_rad, float(rng.uniform(0.08, 0.28)), 1, lineType=_cv2.LINE_AA)
                _cv2.circle(CC, (jcx, jcy), cell_rad, float(rng.uniform(0.08, 0.36)), 1, lineType=_cv2.LINE_AA)
                # CENTER PIN-DOT (spindle dimple)
                _cv2.circle(M, (jcx, jcy), max(1, int(scale)), float(rng.uniform(0.20, 0.44)), -1, lineType=_cv2.LINE_AA)
                _cv2.circle(R, (jcx, jcy), max(1, int(scale)), float(rng.uniform(0.55, 0.88)), -1, lineType=_cv2.LINE_AA)
                _cv2.circle(CC, (jcx, jcy), max(1, int(scale)), float(rng.uniform(0.40, 0.80)), -1, lineType=_cv2.LINE_AA)
                cell_centers.append((jcx, jcy))

        # 3) TRAVEL HAIRLINES between cells (cutter lift trails)
        if len(cell_centers) > 1:
            n_links = min(len(cell_centers) - 1, max(int(h * w / 1500), 600))
            for _ in range(n_links):
                i0 = int(rng.integers(0, len(cell_centers)))
                i1 = (i0 + int(rng.integers(1, 4))) % len(cell_centers)
                x0, y0 = cell_centers[i0]
                x1, y1 = cell_centers[i1]
                d = float(np.hypot(x1 - x0, y1 - y0))
                if d < sp * 2.2 and d > 0.0:
                    _cv2.line(M,  (x0, y0), (x1, y1), float(rng.uniform(0.38, 0.74)), 1, lineType=_cv2.LINE_AA)
                    _cv2.line(R,  (x0, y0), (x1, y1), float(rng.uniform(0.16, 0.42)), 1, lineType=_cv2.LINE_AA)
                    _cv2.line(CC, (x0, y0), (x1, y1), float(rng.uniform(0.08, 0.34)), 1, lineType=_cv2.LINE_AA)

        # 4) Dense rim sparkles (1-2 px)
        n_dot = max(int((h * w) / 80), 7000)
        ys = rng.integers(0, h, n_dot); xs = rng.integers(0, w, n_dot)
        M[ys, xs]  = np.maximum(M[ys, xs],  rng.uniform(0.72, 0.99, n_dot).astype(np.float32))
        R[ys, xs]  = np.minimum(R[ys, xs],  rng.uniform(0.03, 0.22, n_dot).astype(np.float32))
        CC[ys, xs] = np.minimum(CC[ys, xs], rng.uniform(0.03, 0.28, n_dot).astype(np.float32))

    out = np.stack([M, R, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
jeweling_circles._spb_concept_complete = True


