def knurl_diamond(shape, seed, sm, frequency=30.0, angle_deg=45.0, **kwargs):
    """knurl_diamond â€” R6 creative push.

    identity: a precision diamond knurl like a gun-grip â€” TIGHT crossed
    ridge pattern at +/-45 deg forming a dense field of sharp pyramid
    apex peaks (6-14 px pitch, NOT macro). Ridges are sharpened to a
    steep crest, apex peaks burn bright on M, valleys read dark/rough.
    HERO motif: a curved POLISHED WEAR BAND (one or two sweeping low-freq
    arcs across the panel where the grip has been HELD â€” apex peaks in
    this band have been polished smoother, reading brighter M, much
    smoother R, brighter CC â€” like a thumb-path or palm-wear line).
    Stacked: sharp crossed ridges, FBM-mottle for honest worn-tool feel,
    apex bright pinpoints, valley grit specks, diagonal slip-marks where
    the knurl wheel walked, plus tiny oil-blackened valley pools where
    grease pooled. Per-feature INDEPENDENT continuous M/R/CC.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 104517)
    scale = max(min(h, w) / 2048.0, 0.25)

    def _fbm(off, sigma):
        if _CV2_OK:
            sh = max(64, h // 10); sw = max(64, w // 10)
            n = np.random.default_rng(int(seed) + off).random((sh, sw)).astype(np.float32)
            b = _cv2.GaussianBlur(n, (0, 0), sigmaX=sigma, sigmaY=sigma)
            return _normalize(_cv2.resize(b, (w, h), interpolation=_cv2.INTER_CUBIC).astype(np.float32))
        return _normalize(multi_scale_noise(shape, [20, 40], [0.6, 0.4], int(seed) + off))

    yy, xx = np.mgrid[0:h, 0:w].astype(np.float32)
    a = np.deg2rad(float(angle_deg))
    u1 =  np.cos(a) * xx + np.sin(a) * yy
    u2 = -np.sin(a) * xx + np.cos(a) * yy
    # Tight pitch (6-14 px)
    pitch_px = max(4.0, 8.0 * scale)
    f = (2.0 * np.pi) / pitch_px
    rid1 = np.abs(np.sin(u1 * f))
    rid2 = np.abs(np.sin(u2 * f))
    # Sharpen ridges (steep apex)
    rid1s = np.power(rid1, 3.2)
    rid2s = np.power(rid2, 3.2)
    ridge = np.maximum(rid1s, rid2s)
    apex  = rid1s * rid2s

    # INDEPENDENT FBM per channel
    fM = _fbm(10011, 6.0); fR = _fbm(10013, 6.0); fCC = _fbm(10015, 6.0)
    M  = (0.45 + 0.40 * ridge + 0.10 * (fM  - 0.5)).astype(np.float32)
    R  = (0.62 - 0.38 * ridge + 0.18 * (fR  - 0.5)).astype(np.float32)
    CC = (0.42 - 0.34 * ridge + 0.18 * (fCC - 0.5)).astype(np.float32)

    # Apex strong bright shadow
    apex_mask = (apex > 0.55).astype(np.float32)
    M  = np.clip(M  + apex_mask * 0.18, 0.0, 1.0)
    CC = np.clip(CC - apex_mask * 0.20, 0.0, 1.0)

    # HERO: 1-2 curved POLISHED WEAR BAND arcs (thumb/palm wear paths)
    n_wear = int(rng.integers(1, 3))
    wear_mask = np.zeros((h, w), dtype=np.float32)
    for _ in range(n_wear):
        # Pick a random axis and a low-freq sine wander
        a_w = float(rng.uniform(0, np.pi))
        ca_w, sa_w = float(np.cos(a_w)), float(np.sin(a_w))
        u_w = xx * ca_w + yy * sa_w
        v_w = -xx * sa_w + yy * ca_w
        cx_w = float(rng.uniform(0.25 * w, 0.75 * w))
        wavelen_w = max(180.0, 260.0 * scale)
        amp_w = float(rng.uniform(15.0, 38.0)) * scale
        path_c = cx_w + amp_w * np.sin(v_w * (2.0 * np.pi / wavelen_w) + float(rng.uniform(0, 2*np.pi)))
        thickness_w = float(rng.uniform(36.0, 65.0)) * scale
        d_w = np.abs(u_w - path_c)
        band = np.clip(1.0 - d_w / thickness_w, 0, 1)
        # smooth falloff
        band = band * band * (3.0 - 2.0 * band)
        wear_mask = np.maximum(wear_mask, band)
    # Apply wear: apex peaks polished smoother, brighter; valleys still readable
    M  = np.clip(M  + wear_mask * apex_mask * 0.18 + wear_mask * 0.05, 0, 1)
    R  = np.clip(R  - wear_mask * 0.28, 0, 1)
    CC = np.clip(CC + wear_mask * 0.32 - wear_mask * apex_mask * 0.10, 0, 1)

    if _CV2_OK:
        # Apex bright pinpoints (5x prior)
        idxs = np.argwhere(apex > 0.65)
        if len(idxs) > 0:
            n_pick = min(len(idxs), max(4500, int(h * w / 140)))
            pick = rng.choice(len(idxs), size=n_pick, replace=False)
            for p in pick:
                y, x = idxs[p]
                M[y, x]  = float(rng.uniform(0.86, 0.99))
                R[y, x]  = float(rng.uniform(0.04, 0.16))
                CC[y, x] = float(rng.uniform(0.04, 0.20))

        # Valley grit specks (5x prior)
        n_v = max(int(h * w / 80), 7000)
        ys = rng.integers(0, h, n_v); xs = rng.integers(0, w, n_v)
        R[ys, xs]  = np.maximum(R[ys, xs],  rng.uniform(0.55, 0.94, n_v).astype(np.float32))
        CC[ys, xs] = np.maximum(CC[ys, xs], rng.uniform(0.42, 0.86, n_v).astype(np.float32))

        # Diagonal slip-marks (rare 10-22 px walking lines)
        n_slip = max(int(h * w / 7500), 80)
        for _ in range(n_slip):
            x0 = int(rng.integers(0, w)); y0 = int(rng.integers(0, h))
            ang = float(np.deg2rad(float(angle_deg)) + rng.uniform(-0.1, 0.1))
            ll = float(rng.uniform(10.0, 22.0) * scale)
            x1 = int(x0 + np.cos(ang) * ll); y1 = int(y0 + np.sin(ang) * ll)
            _cv2.line(M, (x0, y0), (x1, y1), float(rng.uniform(0.30, 0.55)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (x0, y0), (x1, y1), float(rng.uniform(0.05, 0.24)), 1, lineType=_cv2.LINE_AA)

        # OIL-BLACKENED VALLEY POOLS â€” tiny dark grease pockets at valley intersections
        n_oil = max(int(h * w / 1100), 800)
        for _ in range(n_oil):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            # only place in valleys (ridge field low)
            if ridge[cy, cx] > 0.20:
                continue
            r = max(1, int(rng.uniform(1.0, 2.5) * scale))
            _cv2.circle(M, (cx, cy), r, float(rng.uniform(0.06, 0.20)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r, float(rng.uniform(0.08, 0.28)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r, float(rng.uniform(0.62, 0.90)), -1, lineType=_cv2.LINE_AA)

    out = np.stack([M, R, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)


knurl_diamond._spb_concept_complete = True


def knurl_straight(shape, seed, sm, frequency=40.0, sharpness=3.0, **kwargs):
    """knurl_straight â€” R6 creative push.

    identity: a precision STRAIGHT-knurled grip â€” parallel sharp metal
    ridges marching across the panel at a fixed angle, tight 5-10 px
    pitch (NOT macro), each ridge sharpened to a steep apex.
    HERO motif: 4-7 evenly-spaced ACCENT RIDGES burned to mirror-bright
    (like polished gold guide-rails between matte steel), plus PERPENDICULAR
    WEAR BAND across the panel where the part has been gripped (chrome-rail
    polish stripe). Stacked: primary sharp ridges (M peaks / R troughs),
    faint secondary perpendicular scribe lines, bright apex pinpoints,
    dark valley grit specks, micro-BURR highlights on ridge crests where
    the cutter pulled a tiny lip, and fine FBM wear-mottle. Per-feature
    INDEPENDENT continuous M/R/CC.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 115620)
    scale = max(min(h, w) / 2048.0, 0.25)

    def _fbm(off, sigma):
        if _CV2_OK:
            sh = max(64, h // 10); sw = max(64, w // 10)
            n = np.random.default_rng(int(seed) + off).random((sh, sw)).astype(np.float32)
            b = _cv2.GaussianBlur(n, (0, 0), sigmaX=sigma, sigmaY=sigma)
            return _normalize(_cv2.resize(b, (w, h), interpolation=_cv2.INTER_CUBIC).astype(np.float32))
        return _normalize(multi_scale_noise(shape, [20, 40], [0.6, 0.4], int(seed) + off))

    yy, xx = np.mgrid[0:h, 0:w].astype(np.float32)
    ang = float(rng.uniform(0, np.pi))
    u = np.cos(ang) * xx + np.sin(ang) * yy
    # Tight pitch (5-10 px)
    pitch_px = max(3.5, 7.0 * scale)
    f = (2.0 * np.pi) / pitch_px
    raw = np.abs(np.sin(u * f))
    ridge = np.power(raw, max(2.0, float(sharpness)))

    fM = _fbm(10511, 6.5); fR = _fbm(10513, 6.5); fCC = _fbm(10515, 6.5)
    M  = (0.46 + 0.38 * ridge + 0.10 * (fM  - 0.5)).astype(np.float32)
    R  = (0.60 - 0.36 * ridge + 0.16 * (fR  - 0.5)).astype(np.float32)
    CC = (0.42 - 0.32 * ridge + 0.18 * (fCC - 0.5)).astype(np.float32)

    # HERO: 4-7 ACCENT RIDGES â€” every Nth ridge burnt to mirror-bright
    ridge_idx = np.floor(u / pitch_px).astype(np.int32)
    n_accent = int(rng.integers(4, 8))
    accent_period = int(max(8, (max(np.abs(ridge_idx).max(), 8)) / max(n_accent, 1)))
    accent_offset = int(rng.integers(0, accent_period))
    accent_band = (((ridge_idx - accent_offset) % accent_period) == 0)
    # within the accent ridge band, take strongest contribution near apex
    accent_strength = accent_band.astype(np.float32) * ridge
    M  = np.clip(M  + accent_strength * 0.42, 0, 1)
    R  = np.clip(R  - accent_strength * 0.30, 0, 1)
    CC = np.clip(CC - accent_strength * 0.22, 0, 1)

    # HERO 2: PERPENDICULAR WEAR BAND â€” chrome polish stripe across grip
    v_axis = -np.sin(ang) * xx + np.cos(ang) * yy
    v_lo = float(v_axis.min()); v_hi = float(v_axis.max())
    v_range = v_hi - v_lo
    v_center = v_lo + v_range * float(rng.uniform(0.30, 0.70))
    wear_thickness = float(rng.uniform(35.0, 75.0)) * scale
    wear_band = np.clip(1.0 - np.abs(v_axis - v_center) / wear_thickness, 0, 1)
    wear_band = wear_band * wear_band * (3.0 - 2.0 * wear_band)
    # Inside wear: ridges polished smoother, brighter, glossier
    M  = np.clip(M  + wear_band * ridge * 0.18 + wear_band * 0.04, 0, 1)
    R  = np.clip(R  - wear_band * 0.26, 0, 1)
    CC = np.clip(CC + wear_band * 0.30, 0, 1)

    if _CV2_OK:
        # Top-of-ridge highlight pinpoints (5x prior)
        peak = (ridge > 0.65)
        idxs = np.argwhere(peak)
        if len(idxs) > 0:
            n_pick = min(len(idxs), max(5000, int(h * w / 120)))
            pick = rng.choice(len(idxs), size=n_pick, replace=False)
            for p in pick:
                y, x = idxs[p]
                M[y, x] = float(rng.uniform(0.88, 0.99))
                R[y, x] = float(rng.uniform(0.04, 0.16))
                CC[y, x] = float(rng.uniform(0.04, 0.20))

        # Valley grit specks (5x prior)
        n_v = max(int(h * w / 90), 6500)
        ys = rng.integers(0, h, n_v); xs = rng.integers(0, w, n_v)
        R[ys, xs] = np.maximum(R[ys, xs], rng.uniform(0.55, 0.92, n_v).astype(np.float32))

        # Perpendicular cross-machining scribe lines (3-8 px, dense â€” 5x)
        n_str = max(int(h * w / 350), 1500)
        for _ in range(n_str):
            x0 = int(rng.integers(0, w)); y0 = int(rng.integers(0, h))
            a2 = ang + np.pi / 2 + float(rng.uniform(-0.22, 0.22))
            ll = int(max(2, rng.uniform(2, 5) * scale))
            x1 = int(x0 + np.cos(a2) * ll); y1 = int(y0 + np.sin(a2) * ll)
            _cv2.line(M, (x0, y0), (x1, y1), float(rng.uniform(0.30, 0.62)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (x0, y0), (x1, y1), float(rng.uniform(0.05, 0.30)), 1, lineType=_cv2.LINE_AA)

        # MICRO-BURR HIGHLIGHTS â€” ridge-crest lip where cutter pulled tiny burr
        # tiny 2-4 px bright lines aligned along ridge axis
        n_burr = max(int(h * w / 600), 1100)
        for _ in range(n_burr):
            # pick a point and check if near ridge apex
            x0 = int(rng.integers(2, w - 2)); y0 = int(rng.integers(2, h - 2))
            if ridge[y0, x0] < 0.55:
                continue
            ll = float(rng.uniform(2.0, 4.0) * scale)
            x1 = int(x0 + np.cos(ang) * ll); y1 = int(y0 + np.sin(ang) * ll)
            _cv2.line(M, (x0, y0), (x1, y1), float(rng.uniform(0.85, 0.99)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (x0, y0), (x1, y1), float(rng.uniform(0.55, 0.92)), 1, lineType=_cv2.LINE_AA)

    out = np.stack([M, R, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)


knurl_straight._spb_concept_complete = True


def face_mill_bands(shape, seed, sm, pass_width=60, freq=20.0, **kwargs):
    """face_mill_bands â€” R6 CREATIVE rebuild â€” true CNC face-mill identity.

    identity: A CNC face-milled aluminum plate captured straight off the
    machine. TIGHT 8-12 px horizontal cutter-pass bands (each band a thin
    bright ridge over a dark valley with per-band continuous chroma).
    Stacked in the valleys: (1) analytic 4-12 px scallop-arc field, (2)
    30deg micro-crosshatch, (3) dense 4-16 px chatter hairlines along
    feed, (4) NEW â€” INSERT-TOOTH SIGNATURE: regularly-spaced 6-10 px
    bright cusp dots along every other band (every cutter tooth leaves a
    spec'd cusp where it bites), (5) NEW â€” DWELL ZIG-ZAGS: short 6-12 px
    zig-zag chatter clusters at random pass-stops where the cutter
    paused, (6) sub-pixel burr-glint carpet + recess pits at band seams.
    Per-row + per-feature INDEPENDENT continuous M/R/CC. Looks like real
    machined aluminum â€” not generic scratches.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 41019)
    yy = np.arange(h, dtype=np.float32)[:, None]
    xx = np.arange(w, dtype=np.float32)[None, :]
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)

    # 1) BASE â€” milled aluminum
    bM = _normalize(multi_scale_noise(shape, [2.0, 6.0, 14.0], [0.5, 0.3, 0.2], int(seed) + 41021))
    bR = _normalize(multi_scale_noise(shape, [2.0, 6.0, 14.0], [0.5, 0.3, 0.2], int(seed) + 41023))
    bC = _normalize(multi_scale_noise(shape, [2.0, 6.0, 14.0], [0.5, 0.3, 0.2], int(seed) + 41025))
    M = (0.58 + (bM - 0.5) * 0.22).astype(np.float32)
    R = (0.40 + (bR - 0.5) * 0.22).astype(np.float32)
    CC = (0.42 + (bC - 0.5) * 0.22).astype(np.float32)

    # 2) TIGHT CUTTER-PASS BANDS â€” 5x density, 8-12 px pitch
    pitch = max(8.0, 10.0 * scale)
    band_phase = (yy % pitch) / pitch  # 0-1 within each band
    ridge = np.exp(-((band_phase - 0.5) * 8.0) ** 2)  # sharp crest at center
    valley = 1.0 - ridge
    # per-band continuous chroma (Weyl) â€” uint64 to avoid overflow
    row_idx = np.floor(yy / pitch).astype(np.int64).astype(np.uint64)
    rh = ((row_idx * np.uint64(0x9E3779B1)) & np.uint64(0xFFFFFF)).astype(np.float32) / 0xFFFFFF
    rh2 = ((row_idx * np.uint64(0x85EBCA77)) & np.uint64(0xFFFFFF)).astype(np.float32) / 0xFFFFFF
    rh3 = ((row_idx * np.uint64(0xC2B2AE3D)) & np.uint64(0xFFFFFF)).astype(np.float32) / 0xFFFFFF
    M = M * (1.0 - ridge * 0.65) + (0.60 + rh * 0.38) * ridge * 0.95 + (rh - 0.5) * 0.08
    R = R * (1.0 - ridge * 0.55) + (0.08 + rh2 * 0.28) * ridge * 0.85 + (rh2 - 0.5) * 0.08
    CC = CC * (1.0 - ridge * 0.50) + (0.12 + rh3 * 0.32) * ridge * 0.80 + (rh3 - 0.5) * 0.08
    # Valleys: darker M, higher R
    M = M - valley * 0.12
    R = R + valley * 0.10

    # 3) ANALYTIC SCALLOP-ARC field within bands
    arc_period = max(14.0, 14.0 * scale)
    arc_phase = np.sin((xx / arc_period + band_phase * 1.5) * 2.0 * np.pi)
    arc_field = np.clip(arc_phase, 0.0, 1.0)
    M = M + arc_field * 0.12
    CC = CC + arc_field * 0.08

    # 4) 30deg CROSSHATCH micro-texture
    ca, sa = float(np.cos(np.deg2rad(30.0))), float(np.sin(np.deg2rad(30.0)))
    u_h = xx * ca + yy * sa; v_h = -xx * sa + yy * ca
    hatch = np.maximum(np.sin(u_h / 3.0 * 2.0 * np.pi), np.sin(v_h / 3.0 * 2.0 * np.pi))
    hatch_field = (hatch > 0.6).astype(np.float32) * 0.12
    M = M + hatch_field
    R = R - hatch_field * 0.5

    # 5) CHATTER HAIRLINES â€” 4-16 px feed-direction (5x prior)
    if _CV2_OK:
        n_chat = int(np.clip(3500 * (mn / 2048.0) ** 2, 1100, 7000))
        for _ in range(n_chat):
            cx = float(rng.uniform(2, w - 2)); cy = float(rng.uniform(2, h - 2))
            length = float(rng.uniform(4.0, 16.0) * scale)
            ang = float(rng.normal(0.0, 0.08))
            x0s = int(cx - np.cos(ang) * length * 0.5); y0s = int(cy - np.sin(ang) * length * 0.5)
            x1s = int(cx + np.cos(ang) * length * 0.5); y1s = int(cy + np.sin(ang) * length * 0.5)
            _cv2.line(M, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.40, 0.95)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(R, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.08, 0.40)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.10, 0.42)), 1, lineType=_cv2.LINE_AA)

    # 6) BURR-GLINT CARPET + RECESS PITS â€” vectorized, dense
    n_burr = max(7000, int(h * w / 18))
    fy = rng.integers(0, h, n_burr); fx = rng.integers(0, w, n_burr)
    M[fy, fx] = np.maximum(M[fy, fx], rng.uniform(0.70, 0.99, n_burr).astype(np.float32))
    R[fy, fx] = np.minimum(R[fy, fx], rng.uniform(0.04, 0.20, n_burr).astype(np.float32))
    n_pit = max(3000, int(h * w / 40))
    ddy = rng.integers(0, h, n_pit); ddx = rng.integers(0, w, n_pit)
    M[ddy, ddx] = np.minimum(M[ddy, ddx], rng.uniform(0.05, 0.22, n_pit).astype(np.float32))
    R[ddy, ddx] = np.maximum(R[ddy, ddx], rng.uniform(0.55, 0.92, n_pit).astype(np.float32))

    # 7) INSERT-TOOTH SIGNATURE â€” bright cusp dots at regular spacing
    if _CV2_OK:
        n_bands = max(1, int(h / pitch))
        tooth_pitch = max(10.0, 11.0 * scale)
        for bi in range(0, n_bands, 2):
            y_row = int(bi * pitch + pitch * 0.5)
            if y_row >= h: break
            x_off = float(rng.uniform(0, tooth_pitch))
            n_t = int(w / tooth_pitch) + 1
            for ti in range(n_t):
                cx_t = int(x_off + ti * tooth_pitch)
                if not (0 <= cx_t < w): continue
                rrr = max(1, int(rng.uniform(2.5, 4.0) * scale * 0.5))
                _cv2.circle(M, (cx_t, y_row), rrr, float(rng.uniform(0.78, 0.99)), -1, lineType=_cv2.LINE_AA)
                _cv2.circle(R, (cx_t, y_row), rrr, float(rng.uniform(0.04, 0.16)), -1, lineType=_cv2.LINE_AA)
                _cv2.circle(CC, (cx_t, y_row), rrr, float(rng.uniform(0.68, 0.96)), -1, lineType=_cv2.LINE_AA)

        # 8) DWELL ZIG-ZAGS â€” short chatter clusters at random pass-stops
        n_zig = int(np.clip(140 * (mn / 2048.0) ** 2, 40, 320))
        for _ in range(n_zig):
            cx_z = float(rng.uniform(6, w - 6)); cy_z = float(rng.uniform(6, h - 6))
            n_seg = int(rng.integers(3, 6))
            ang0 = float(rng.normal(0, 0.18))
            x_cur = cx_z; y_cur = cy_z
            for s in range(n_seg):
                L = float(rng.uniform(3.0, 6.0) * scale)
                sign = 1 if (s % 2 == 0) else -1
                local_ang = ang0 + sign * float(rng.uniform(0.6, 1.1))
                x_n = float(np.clip(x_cur + np.cos(local_ang) * L, 0, w - 1))
                y_n = float(np.clip(y_cur + np.sin(local_ang) * L, 0, h - 1))
                _cv2.line(M, (int(x_cur), int(y_cur)), (int(x_n), int(y_n)),
                          float(rng.uniform(0.55, 0.95)), 1, lineType=_cv2.LINE_AA)
                _cv2.line(R, (int(x_cur), int(y_cur)), (int(x_n), int(y_n)),
                          float(rng.uniform(0.10, 0.42)), 1, lineType=_cv2.LINE_AA)
                _cv2.line(CC, (int(x_cur), int(y_cur)), (int(x_n), int(y_n)),
                          float(rng.uniform(0.20, 0.55)), 1, lineType=_cv2.LINE_AA)
                x_cur = x_n; y_cur = y_n

    out = np.stack([M, R, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)

face_mill_bands._spb_concept_complete = True


def fly_cut_arcs(shape, seed, sm, cutter_radius_frac=1.2, pass_pitch=40, **kwargs):
    """fly_cut_arcs.

    identity: R6-CREATIVE tick 47 push â€” fly-cut aluminum with TRUE scallop
    rows AND a new HERO MOTIF: BRIGHT LEADING-EDGE CRESCENT HIGHLIGHTS on
    each scallop tile. Each cutter pass leaves a tile of 3-5 concentric
    8-18 px arcs (the scallop family); ON TOP of those arcs we now stamp
    a thin, very bright crescent at the leading edge of the cut where the
    tool tip pushed material up â€” this is what gives real fly-cut its
    "engine-turn" sparkle pattern. Plus dense 6-14 px chatter hairlines,
    burr-glint pinpoints, recess pits, and per-tile INDEPENDENT M/R/CC.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 41218)
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)

    # 1) BASE â€” milled aluminum substrate
    bM = _normalize(multi_scale_noise(shape, [2.0, 6.0, 14.0], [0.5, 0.3, 0.2], int(seed) + 41221))
    bR = _normalize(multi_scale_noise(shape, [2.0, 6.0, 14.0], [0.5, 0.3, 0.2], int(seed) + 41223))
    bC = _normalize(multi_scale_noise(shape, [2.0, 6.0, 14.0], [0.5, 0.3, 0.2], int(seed) + 41225))
    M = (0.58 + (bM - 0.5) * 0.22).astype(np.float32)
    R = (0.40 + (bR - 0.5) * 0.22).astype(np.float32)
    CC = (0.42 + (bC - 0.5) * 0.22).astype(np.float32)

    # 2) SCALLOP-ARC TILE GRID â€” real cutter pass layout
    if _CV2_OK:
        tile_w = max(22, int(22 * scale))
        tile_h = max(18, int(18 * scale))
        row_idx = 0
        cy = tile_h // 2
        while cy < h + tile_h:
            shift = (row_idx % 2) * (tile_w // 2)
            cx = -tile_w + shift
            while cx < w + tile_w:
                # per-tile chroma
                mv_center = float(rng.uniform(0.60, 0.96))
                rv_center = float(rng.uniform(0.08, 0.32))
                cv_center = float(rng.uniform(0.10, 0.40))
                # nested arc family â€” 3-5 concentric arcs
                n_arcs = int(rng.integers(3, 6))
                base_r = int(max(5, tile_w * 0.45))
                a0 = 200.0 + float(rng.uniform(-15, 15))
                sweep = 140.0 + float(rng.uniform(-20, 20))
                for ai in range(n_arcs):
                    r_arc = max(2, base_r - ai * max(2, int(scale * 2)))
                    bright = mv_center * (1.0 - ai * 0.10)
                    _cv2.ellipse(M, (int(cx), int(cy)), (r_arc, r_arc), 0.0,
                                 a0, a0 + sweep, float(bright), 1, lineType=_cv2.LINE_AA)
                    _cv2.ellipse(R, (int(cx), int(cy)), (r_arc, r_arc), 0.0,
                                 a0, a0 + sweep, rv_center, 1, lineType=_cv2.LINE_AA)
                    _cv2.ellipse(CC, (int(cx), int(cy)), (r_arc, r_arc), 0.0,
                                 a0, a0 + sweep, cv_center, 1, lineType=_cv2.LINE_AA)
                # HERO LEADING-EDGE CRESCENT â€” extra bright thin arc on the
                # leading edge of the cut where material got pushed up
                lead_r = max(3, base_r + max(1, int(scale * 1.5)))
                lead_a0 = a0 + sweep * 0.55 + float(rng.uniform(-8, 8))
                lead_sw = float(rng.uniform(40.0, 65.0))
                lead_M = float(np.clip(mv_center + rng.uniform(0.05, 0.18), 0.55, 0.99))
                lead_R = float(np.clip(rv_center - rng.uniform(0.02, 0.10), 0.02, 0.30))
                lead_CC = float(np.clip(cv_center - rng.uniform(0.02, 0.10), 0.02, 0.35))
                _cv2.ellipse(M, (int(cx), int(cy)), (lead_r, lead_r), 0.0,
                             lead_a0, lead_a0 + lead_sw, lead_M, 1, lineType=_cv2.LINE_AA)
                _cv2.ellipse(R, (int(cx), int(cy)), (lead_r, lead_r), 0.0,
                             lead_a0, lead_a0 + lead_sw, lead_R, 1, lineType=_cv2.LINE_AA)
                _cv2.ellipse(CC, (int(cx), int(cy)), (lead_r, lead_r), 0.0,
                             lead_a0, lead_a0 + lead_sw, lead_CC, 1, lineType=_cv2.LINE_AA)
                cx += tile_w
            cy += tile_h
            row_idx += 1

        # 3) CHATTER HAIRLINES â€” dense 6-14 px feed-direction
        n_chat = int(np.clip(2500 * (mn / 2048.0) ** 2, 800, 5500))
        for _ in range(n_chat):
            cx = float(rng.uniform(2, w - 2)); cy = float(rng.uniform(2, h - 2))
            length = float(rng.uniform(6.0, 14.0) * scale)
            ang = float(rng.normal(0.0, 0.07))
            x0 = int(cx - np.cos(ang) * length * 0.5); y0 = int(cy - np.sin(ang) * length * 0.5)
            x1 = int(cx + np.cos(ang) * length * 0.5); y1 = int(cy + np.sin(ang) * length * 0.5)
            _cv2.line(M, (x0, y0), (x1, y1), float(rng.uniform(0.40, 0.90)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(R, (x0, y0), (x1, y1), float(rng.uniform(0.08, 0.38)), 1, lineType=_cv2.LINE_AA)

    # 4) BURR-GLINT CARPET + RECESS PITS
    n_burr = max(6000, int(h * w / 16))
    fy = rng.integers(0, h, n_burr); fx = rng.integers(0, w, n_burr)
    M[fy, fx] = np.maximum(M[fy, fx], rng.uniform(0.65, 0.99, n_burr).astype(np.float32))
    R[fy, fx] = np.minimum(R[fy, fx], rng.uniform(0.04, 0.20, n_burr).astype(np.float32))
    CC[fy, fx] = np.minimum(CC[fy, fx], rng.uniform(0.05, 0.22, n_burr).astype(np.float32))
    n_dk = max(2500, int(h * w / 45))
    ddy = rng.integers(0, h, n_dk); ddx = rng.integers(0, w, n_dk)
    M[ddy, ddx] = np.minimum(M[ddy, ddx], rng.uniform(0.05, 0.22, n_dk).astype(np.float32))
    R[ddy, ddx] = np.maximum(R[ddy, ddx], rng.uniform(0.55, 0.92, n_dk).astype(np.float32))

    out = np.stack([M, R, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)

fly_cut_arcs._spb_concept_complete = True


def engraved_crosshatch(shape, seed, sm, **kwargs):
    """engraved_crosshatch â€” R6 creative push.

    identity: A burin-engraved metal plate covered edge-to-edge with
    THREE superimposed periodic crosshatch grids â€” primary 45/135 grid
    fine and bright, secondary 30/120 grid lighter on top, plus a
    tertiary 75/165 fine hatch barely visible like a third pass with a
    different burin. Hero motif: scattered DEEP BURIN GASHES (5-12 px
    bright bevel-edged lines following ridge directions) where the
    engraver bore down hard. Per-cell burnish chroma, dense dark
    recess pits at grid intersections, gold-tone sparkle pops where
    burin slipped, dark recess pools (rare 8-14 px circles) where
    coppered hatching deepened, and crossing micro-scratches between
    hatches. Per-feature INDEPENDENT M/R/CC.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 61317)
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)
    yy, xx = np.mgrid[0:h, 0:w].astype(np.float32)

    # 1) BASE â€” engraved DARK metal plate FBM (composite-dark substrate)
    # FIX 2026-05-26: substrate was 0.50/0.45/0.48 = mid-range pink composite.
    # Now 0.32/0.20/0.28 so ridges + chroma can pop against a dark recess.
    bM = _normalize(_spb_fast_smooth_noise(shape, [1.8, 5.0, 14.0], [0.5, 0.3, 0.2], int(seed) + 61321))
    bR = _normalize(_spb_fast_smooth_noise(shape, [1.8, 5.0, 14.0], [0.5, 0.3, 0.2], int(seed) + 61323))
    bC = _normalize(_spb_fast_smooth_noise(shape, [1.8, 5.0, 14.0], [0.5, 0.3, 0.2], int(seed) + 61325))
    M = (0.32 + (bM - 0.5) * 0.16).astype(np.float32)
    R_ch = (0.20 + (bR - 0.5) * 0.14).astype(np.float32)
    CC = (0.28 + (bC - 0.5) * 0.14).astype(np.float32)

    # 2) ANALYTICAL CROSSHATCH GRIDS â€” THREE superimposed (sharpened ridges)
    # Primary 45/135 grid: pitch ~6 px
    pitch_a = max(6.0, 6.0 * scale)
    u1 = (xx + yy) / pitch_a
    v1 = (xx - yy) / pitch_a
    # Sharper ridge profile (power) so lines read as crisp bright/dark
    hatch1_a = np.power(np.abs(np.sin(u1 * np.pi)), 4.0).astype(np.float32)
    hatch1_b = np.power(np.abs(np.sin(v1 * np.pi)), 4.0).astype(np.float32)
    grid1 = np.maximum(hatch1_a, hatch1_b)
    # Secondary 30/120 grid: pitch ~10 px (lighter)
    pitch_b = max(10.0, 10.0 * scale)
    ca, sa = np.cos(np.deg2rad(30.0)), np.sin(np.deg2rad(30.0))
    u2 = (xx * ca + yy * sa) / pitch_b
    v2 = (xx * sa - yy * ca) / pitch_b
    hatch2_a = np.power(np.abs(np.sin(u2 * np.pi)), 4.0).astype(np.float32)
    hatch2_b = np.power(np.abs(np.sin(v2 * np.pi)), 4.0).astype(np.float32)
    grid2 = np.maximum(hatch2_a, hatch2_b)
    # Tertiary 75/165 grid: pitch ~14 px (very faint third pass)
    pitch_c = max(14.0, 14.0 * scale)
    ca3, sa3 = np.cos(np.deg2rad(75.0)), np.sin(np.deg2rad(75.0))
    u3 = (xx * ca3 + yy * sa3) / pitch_c
    v3 = (xx * sa3 - yy * ca3) / pitch_c
    hatch3_a = np.power(np.abs(np.sin(u3 * np.pi)), 4.0).astype(np.float32)
    hatch3_b = np.power(np.abs(np.sin(v3 * np.pi)), 4.0).astype(np.float32)
    grid3 = np.maximum(hatch3_a, hatch3_b)
    # Combine: bright burnished ridges on dark recess (engrave look)
    line_field = grid1 * 0.80 + grid2 * 0.48 + grid3 * 0.24
    line_field = np.clip(line_field, 0.0, 1.0)
    # Tighter binary ridge â€” only the very tip of each hatch line lights up
    # (keeps mean composite dark; lines read as crisp bright filaments)
    ridge_mask = (line_field > 0.82).astype(np.float32)
    # per-cell chroma jitter (Weyl on cell index)
    cell_i = np.floor((xx + yy) / pitch_a).astype(np.int64).astype(np.uint64)
    cell_j = np.floor((xx - yy) / pitch_a).astype(np.int64).astype(np.uint64)
    h_seed = ((cell_i * np.uint64(0x9E3779B1)) ^ (cell_j * np.uint64(0x85EBCA77)) ^ np.uint64(int(seed) & 0xFFFFFFFF)) & np.uint64(0xFFFFFFFF)
    cell_tM = ((h_seed * np.uint64(2654435761)) & np.uint64(0xFFFFFF)).astype(np.float32) / 0xFFFFFF
    cell_tR = ((h_seed * np.uint64(1597334677)) & np.uint64(0xFFFFFF)).astype(np.float32) / 0xFFFFFF
    cell_tC = ((h_seed * np.uint64(374761393)) & np.uint64(0xFFFFFF)).astype(np.float32) / 0xFFFFFF

    # Ridge gets bright metal ONLY where ridge_mask is true (sharp binary),
    # recesses stay dark. Using ridge_mask (binary) keeps mean low so the
    # composite isn't flooded magenta.
    M = M + ridge_mask * 0.55 + (cell_tM - 0.5) * 0.10
    R_ch = R_ch - ridge_mask * 0.10 + (cell_tR - 0.5) * 0.08
    CC = CC + ridge_mask * 0.42 + (cell_tC - 0.5) * 0.10

    if _CV2_OK:
        # 3) RECESS PITS â€” sparse dark dots (was h*w/16 = overwriting whole canvas)
        n_rec = int(np.clip(h * w / 220, 1200, 5000))
        ry = rng.integers(0, h, n_rec); rx = rng.integers(0, w, n_rec)
        M[ry, rx] = np.minimum(M[ry, rx], rng.uniform(0.05, 0.22, n_rec).astype(np.float32))
        R_ch[ry, rx] = np.maximum(R_ch[ry, rx], rng.uniform(0.40, 0.70, n_rec).astype(np.float32))

        # 4) BURIN SLIP SPARKLES â€” sparse (was h*w/12)
        n_spark = int(np.clip(h * w / 260, 900, 4200))
        sy = rng.integers(0, h, n_spark); sx = rng.integers(0, w, n_spark)
        M[sy, sx] = np.maximum(M[sy, sx], rng.uniform(0.62, 0.95, n_spark).astype(np.float32))
        R_ch[sy, sx] = np.minimum(R_ch[sy, sx], rng.uniform(0.10, 0.25, n_spark).astype(np.float32))
        CC[sy, sx] = np.maximum(CC[sy, sx], rng.uniform(0.45, 0.85, n_spark).astype(np.float32))

        # 5) GOLD-TONE MICRO-SCRATCHES (3-10 px) â€” burnish accents (sparse)
        n_scr = int(np.clip(400 * (mn / 2048.0) ** 2, 140, 900))
        for _ in range(n_scr):
            cx = float(rng.uniform(2, w - 2)); cy = float(rng.uniform(2, h - 2))
            length = float(rng.uniform(3.0, 10.0) * scale)
            ang = float(rng.uniform(0, 2 * np.pi))
            x0s = int(cx - np.cos(ang) * length * 0.5); y0s = int(cy - np.sin(ang) * length * 0.5)
            x1s = int(cx + np.cos(ang) * length * 0.5); y1s = int(cy + np.sin(ang) * length * 0.5)
            _cv2.line(M, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.60, 0.95)), 1, lineType=_cv2.LINE_AA)

        # 6) DEEP BURIN GASHES â€” HERO motif: where engraver bore down (5-12 px bright bevel)
        #    Drawn along primary hatch directions (45 and 135) with stronger contrast
        n_gash = int(np.clip(420 * (mn / 2048.0) ** 2, 140, 900))
        for _ in range(n_gash):
            cx = float(rng.uniform(4, w - 4)); cy = float(rng.uniform(4, h - 4))
            length = float(rng.uniform(5.0, 12.0) * scale)
            # follow one of the two primary hatch directions
            base_ang = float(np.deg2rad(45.0)) if rng.random() < 0.5 else float(np.deg2rad(135.0))
            a_g = base_ang + float(rng.normal(0.0, 0.04))
            x0s = int(cx - np.cos(a_g) * length * 0.5); y0s = int(cy - np.sin(a_g) * length * 0.5)
            x1s = int(cx + np.cos(a_g) * length * 0.5); y1s = int(cy + np.sin(a_g) * length * 0.5)
            # Bright apex of gash + dark adjacent recess
            _cv2.line(M, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.82, 0.99)), 2, lineType=_cv2.LINE_AA)
            _cv2.line(R_ch, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.04, 0.18)), 2, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.06, 0.24)), 2, lineType=_cv2.LINE_AA)

        # 7) DARK RECESS POOLS â€” rare 6-12 px circles where hatch deepens
        n_pool = int(np.clip(180 * (mn / 2048.0) ** 2, 60, 360))
        for _ in range(n_pool):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            r = max(2, int(rng.uniform(3.0, 6.0) * scale))
            _cv2.circle(M, (cx, cy), r, float(rng.uniform(0.06, 0.22)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R_ch, (cx, cy), r, float(rng.uniform(0.55, 0.88)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r, float(rng.uniform(0.08, 0.28)), -1, lineType=_cv2.LINE_AA)

        # 8) GOLD LEAF FLECKS â€” sparse tiny bright blooms (was 800-5500 â†’ 300-1400)
        n_leaf = int(np.clip(900 * (mn / 2048.0) ** 2, 300, 1400))
        ly = rng.integers(0, h, n_leaf); lx = rng.integers(0, w, n_leaf)
        M[ly, lx] = np.maximum(M[ly, lx], rng.uniform(0.75, 0.95, n_leaf).astype(np.float32))
        CC[ly, lx] = np.maximum(CC[ly, lx], rng.uniform(0.45, 0.78, n_leaf).astype(np.float32))

        # 9) HERO â€” LISSAJOUS PARAMETRIC OVERLAY STROKES.
        # Math curve where polylines normally belong: scatter ~24-60 small
        # Lissajous figure-8 / 3:2 / 5:4 loops across the plate (16-26 px AABB).
        # Each loop is rasterized as a short polyline of bright burnish chroma
        # over the engraved grid. Independent M / R / CC per loop.
        n_liss = int(np.clip(18 * (mn / 2048.0) ** 2, 8, 32))
        for _ in range(n_liss):
            cx_l = int(rng.uniform(0.04, 0.96) * w)
            cy_l = int(rng.uniform(0.04, 0.96) * h)
            R_box = float(rng.uniform(8.0, 13.0) * scale)
            a_ratio = float(rng.choice([2.0, 3.0, 4.0, 5.0]))
            b_ratio = float(rng.choice([1.0, 2.0, 3.0]))
            phase = float(rng.uniform(0.0, np.pi))
            steps = 28
            t_vals = np.linspace(0.0, 2.0 * np.pi, steps, dtype=np.float32)
            xs = (cx_l + np.cos(a_ratio * t_vals + phase) * R_box).astype(np.int32)
            ys = (cy_l + np.sin(b_ratio * t_vals) * R_box).astype(np.int32)
            pts = np.stack([xs, ys], axis=-1)
            m_v = float(rng.uniform(0.62, 0.97))
            r_v = float(rng.uniform(0.08, 0.34))
            c_v = float(rng.uniform(0.40, 0.88))
            _cv2.polylines(M, [pts], False, m_v, 1, lineType=_cv2.LINE_AA)
            _cv2.polylines(R_ch, [pts], False, r_v, 1, lineType=_cv2.LINE_AA)
            _cv2.polylines(CC, [pts], False, c_v, 1, lineType=_cv2.LINE_AA)

    # 10) NEW HERO (R6-Loop tick 2026-05-26): TURING REACTION-DIFFUSION VEINS.
    # Biological motif: sparse 6-14 px sinuous bronze capillaries threaded
    # through the engraved grid like organic patina creep. Tightened threshold
    # to 0.30 so it covers ~5-10% of canvas (not whole image), and reduced
    # blend strength so it accents rather than dominates.
    turing_seed = int(seed) + 61337
    turing_a = _normalize(multi_scale_noise(shape, [4.5, 11.0], [0.55, 0.45], turing_seed))
    turing_b = _normalize(multi_scale_noise(shape, [4.5, 11.0], [0.55, 0.45], turing_seed + 7))
    ux = (xx + yy) / max(8.0, 8.0 * scale)
    grain_gate = (0.5 + 0.5 * np.sin(ux * np.pi))
    turing_field = (turing_a - turing_b) * grain_gate
    vein_mask = (turing_field > 0.38).astype(np.float32)
    bronze_M = 0.85 + (turing_a - 0.5) * 0.08
    bronze_R = 0.12 + (turing_b - 0.5) * 0.06
    bronze_CC = 0.55 + (turing_a - 0.5) * 0.08
    # Blend at 0.70 only inside the rare vein zones so the veins read as crisp accents
    blend = vein_mask * 0.70
    M = M * (1.0 - blend) + bronze_M * blend
    R_ch = R_ch * (1.0 - blend) + bronze_R * blend
    CC = CC * (1.0 - blend) + bronze_CC * blend

    out = np.stack([M, R_ch, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)

engraved_crosshatch._spb_concept_complete = True


def edm_dimple(shape, seed, sm, spacing=12, dimple_radius_frac=0.4, **kwargs):
    """edm_dimple â€” R6 CREATIVE rebuild.

    identity: Electrical Discharge Machined surface â€” random-walk crater
    field (NOT hex grid). 280-700 PLUNGE CRATERS scattered organically:
    each crater is a recessed dark well (4-12 px) ringed by a luminous
    rolled-lip rim where molten metal froze. Where craters overlap, a
    bright RECAST WELT bridges them (the hero motif â€” that wet-frozen
    fused look). Between craters: short ELECTRODE SCORE LINES (8-16 px,
    chevron-clustered in 6-10 random direction-zones) plus a fine
    crackle web (1 px hairline polygons) reading as heat-stress fracture.
    Carpet of micro-pit specks (1-2 px) and bright spark-trail droplet
    arcs (3-5 px linked points) cover every blank inch. Per-feature
    INDEPENDENT continuous M/R/CC for total chroma diversity.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 60107)
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)
    yy, xx = np.mgrid[0:h, 0:w].astype(np.float32)

    # 1) BASE substrate â€” fine-grained machined metal, independent M/R/CC
    fM = _normalize(multi_scale_noise(shape, [2.0, 5.0, 12.0], [0.46, 0.32, 0.22], int(seed) + 60111))
    fR = _normalize(multi_scale_noise(shape, [2.4, 5.6, 13.0], [0.46, 0.32, 0.22], int(seed) + 60113))
    fCC = _normalize(multi_scale_noise(shape, [2.2, 5.3, 12.5], [0.46, 0.32, 0.22], int(seed) + 60115))
    M    = (0.46 + (fM  - 0.5) * 0.26).astype(np.float32)
    R_ch = (0.50 + (fR  - 0.5) * 0.26).astype(np.float32)
    CC   = (0.48 + (fCC - 0.5) * 0.26).astype(np.float32)

    # 2) ORGANIC CRATER FIELD (NOT hex grid) â€” Poisson-ish scatter, painted vectorized
    n_crater = int(np.clip(420 * (mn / 1024.0) ** 2, 120, 1400))
    cxs = rng.uniform(0, w, n_crater)
    cys = rng.uniform(0, h, n_crater)
    crads = rng.uniform(3.0, 7.0, n_crater) * scale
    # build composite well + rim fields via tiled stamp (faster than full grid distance per crater)
    well_field = np.zeros(shape, dtype=np.float32)
    rim_field = np.zeros(shape, dtype=np.float32)
    tint_M = np.zeros(shape, dtype=np.float32)
    tint_R = np.zeros(shape, dtype=np.float32)
    tint_C = np.zeros(shape, dtype=np.float32)
    if _CV2_OK:
        for i in range(n_crater):
            r = max(2, int(crads[i] + 1))
            x0 = int(cxs[i] - r - 1); y0 = int(cys[i] - r - 1)
            x1 = int(cxs[i] + r + 2); y1 = int(cys[i] + r + 2)
            if x1 <= 0 or y1 <= 0 or x0 >= w or y0 >= h:
                continue
            xa = max(x0, 0); ya = max(y0, 0); xb = min(x1, w); yb = min(y1, h)
            local_x = xx[ya:yb, xa:xb] - cxs[i]
            local_y = yy[ya:yb, xa:xb] - cys[i]
            d = np.sqrt(local_x * local_x + local_y * local_y)
            pit = np.clip(1.0 - (d / max(crads[i], 1.0)) ** 2, 0.0, 1.0)
            rim = np.exp(-((d - crads[i]) ** 2) / (2.0 * max(scale * 1.3, 0.7) ** 2))
            cM = float(rng.uniform(0.10, 0.95))
            cR = float(rng.uniform(0.10, 0.95))
            cC = float(rng.uniform(0.05, 0.95))
            sub_w = well_field[ya:yb, xa:xb]
            mask = pit > sub_w
            sub_w[mask] = pit[mask]
            sub_r = rim_field[ya:yb, xa:xb]
            mask_r = rim > sub_r
            sub_r[mask_r] = rim[mask_r]
            sub_tM = tint_M[ya:yb, xa:xb]; sub_tM[mask] = cM
            sub_tR = tint_R[ya:yb, xa:xb]; sub_tR[mask] = cR
            sub_tC = tint_C[ya:yb, xa:xb]; sub_tC[mask] = cC

    M    = M    - well_field * 0.55 + rim_field * 0.38 + (tint_M - 0.5) * well_field * 0.32
    R_ch = R_ch + well_field * 0.40 - rim_field * 0.22 + (tint_R - 0.5) * well_field * 0.28
    CC   = CC   + well_field * 0.18 - rim_field * 0.12 + (tint_C - 0.5) * well_field * 0.24

    if _CV2_OK:
        # 3) HERO: RECAST WELT BRIDGES â€” bright fused metal between near-pairs of craters
        order = np.argsort(cxs)
        n_link = min(int(np.clip(180 * (mn / 1024.0), 60, 480)), len(order) - 1)
        for k in range(n_link):
            i = int(order[k])
            j = int(order[k + 1])
            d = float(np.hypot(cxs[i] - cxs[j], cys[i] - cys[j]))
            if d < 2.0 or d > 24.0 * scale:
                continue
            wM = float(rng.uniform(0.70, 0.97))
            wR = float(rng.uniform(0.05, 0.26))
            wCC = float(rng.uniform(0.04, 0.34))
            thick = max(1, int(rng.uniform(1.6, 2.8) * scale))
            _cv2.line(M, (int(cxs[i]), int(cys[i])), (int(cxs[j]), int(cys[j])), wM, thick, lineType=_cv2.LINE_AA)
            _cv2.line(R_ch, (int(cxs[i]), int(cys[i])), (int(cxs[j]), int(cys[j])), wR, thick, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (int(cxs[i]), int(cys[i])), (int(cxs[j]), int(cys[j])), wCC, thick, lineType=_cv2.LINE_AA)

        # 4) ELECTRODE SCORE LINES â€” chevron-clustered in 6-10 direction zones
        n_zone = int(rng.integers(6, 11))
        zone_dirs = rng.uniform(0, 2 * np.pi, n_zone)
        zone_cx = rng.uniform(0, w, n_zone)
        zone_cy = rng.uniform(0, h, n_zone)
        n_score = int(np.clip(900 * (mn / 1024.0) ** 2, 280, 2800))
        for _ in range(n_score):
            z = int(rng.integers(0, n_zone))
            cx = float(zone_cx[z] + rng.uniform(-w * 0.18, w * 0.18))
            cy = float(zone_cy[z] + rng.uniform(-h * 0.18, h * 0.18))
            ang = float(zone_dirs[z] + rng.uniform(-0.22, 0.22))
            length = float(rng.uniform(8.0, 16.0) * scale)
            x0s = int(cx - np.cos(ang) * length * 0.5)
            y0s = int(cy - np.sin(ang) * length * 0.5)
            x1s = int(cx + np.cos(ang) * length * 0.5)
            y1s = int(cy + np.sin(ang) * length * 0.5)
            _cv2.line(M, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.42, 0.92)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(R_ch, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.10, 0.45)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.06, 0.38)), 1, lineType=_cv2.LINE_AA)

        # 5) HEAT-STRESS CRACKLE WEB â€” Delaunay-ish fracture polygons (hairline)
        n_node = int(np.clip(140 * (mn / 1024.0), 50, 360))
        nodes_x = rng.uniform(0, w, n_node)
        nodes_y = rng.uniform(0, h, n_node)
        # Each node connects to 2 nearest by random sample
        for k in range(n_node):
            idxs = rng.integers(0, n_node, 4)
            for j in idxs:
                if j == k:
                    continue
                d = float(np.hypot(nodes_x[k] - nodes_x[j], nodes_y[k] - nodes_y[j]))
                if d > 22.0 * scale or d < 3.0:
                    continue
                _cv2.line(M, (int(nodes_x[k]), int(nodes_y[k])), (int(nodes_x[j]), int(nodes_y[j])),
                          float(rng.uniform(0.10, 0.32)), 1, lineType=_cv2.LINE_AA)
                _cv2.line(R_ch, (int(nodes_x[k]), int(nodes_y[k])), (int(nodes_x[j]), int(nodes_y[j])),
                          float(rng.uniform(0.55, 0.88)), 1, lineType=_cv2.LINE_AA)

        # 6) SPARK-TRAIL droplet arcs â€” 3-5 small bright dots along an arc
        n_trail = int(np.clip(180 * (mn / 1024.0), 60, 540))
        for _ in range(n_trail):
            cx0 = float(rng.uniform(0, w)); cy0 = float(rng.uniform(0, h))
            ang = float(rng.uniform(0, 2 * np.pi))
            step = float(rng.uniform(2.0, 4.5) * scale)
            curve = float(rng.uniform(-0.35, 0.35))
            n_drop = int(rng.integers(3, 6))
            for d in range(n_drop):
                px = int(cx0 + np.cos(ang + curve * d) * step * d)
                py = int(cy0 + np.sin(ang + curve * d) * step * d)
                if 0 <= px < w and 0 <= py < h:
                    rr = max(1, int(rng.uniform(0.8, 1.6) * scale))
                    _cv2.circle(M, (px, py), rr, float(rng.uniform(0.78, 0.99)), -1, lineType=_cv2.LINE_AA)
                    _cv2.circle(R_ch, (px, py), rr, float(rng.uniform(0.05, 0.22)), -1, lineType=_cv2.LINE_AA)

    # 7) MICRO-PIT carpet (vectorized 1-2 px dark dots)
    n_pit = max(5000, int(h * w / 28))
    py_v = rng.integers(0, h, n_pit); px_v = rng.integers(0, w, n_pit)
    M[py_v, px_v]    = np.minimum(M[py_v, px_v],    rng.uniform(0.04, 0.24, n_pit).astype(np.float32))
    R_ch[py_v, px_v] = np.maximum(R_ch[py_v, px_v], rng.uniform(0.62, 0.95, n_pit).astype(np.float32))
    CC[py_v, px_v]   = rng.uniform(0.20, 0.55, n_pit).astype(np.float32)

    out = np.stack([M, R_ch, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)

edm_dimple._spb_concept_complete = True


def guilloche_straight(shape, seed, sm, frequency=50.0, pitch=0.02, phase_vary=0.008, **kwargs):
    """Straight-line guillochÃ© â€” tight-pitch sinusoidal parallels with x-amplitude modulation, groove/land metallic."""
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    yy = np.arange(h, dtype=np.float32) / h
    xx = np.arange(w, dtype=np.float32) / w
    # Amplitude envelope across x: sin(x*freq) creates bright/dark column zones
    A = np.sin(xx * frequency * np.pi * 2.0)[np.newaxis, :]
    # Phase shifts subtly with x â€” creates sinusoidal wandering lines
    phase_shift = np.sin(xx * 6.0 * np.pi) * phase_vary
    rows = np.sin(yy[:, np.newaxis] / pitch * np.pi * 2.0 + phase_shift[np.newaxis, :])
    result = rows * (0.5 + 0.5 * A)
    return _sm_scale(_normalize(result), sm).astype(np.float32)


def guilloche_wavy(shape, seed, sm, freq=45.0, angle_diff_deg=7.0, **kwargs):
    """Wavy guillochÃ© â€” two sinusoid families at slight angle difference, beating creates shimmering wave metallic."""
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    yy = np.arange(h, dtype=np.float32) / h
    xx = np.arange(w, dtype=np.float32) / w
    Y, X = np.meshgrid(yy, xx, indexing='ij')
    eps = np.deg2rad(angle_diff_deg)
    # Family 1: horizontal lines
    f1 = np.sin(Y * freq * np.pi * 2.0)
    # Family 2: rotated by eps creates beating interference
    f2 = np.sin((Y * np.cos(eps) + X * np.sin(eps)) * freq * np.pi * 2.0)
    result = f1 * f2  # Amplitude modulation: envelope is the interference pattern
    return _sm_scale(_normalize(result), sm).astype(np.float32)


def guilloche_basket(shape, seed, sm, frequency=40.0, **kwargs):
    """Basket-weave guillochÃ© â€” two 90Â° sinusoid families phase-shifted half-period per band for over/under 3D depth."""
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    yy = np.arange(h, dtype=np.float32) / h
    xx = np.arange(w, dtype=np.float32) / w
    Y, X = np.meshgrid(yy, xx, indexing='ij')
    # Band index per axis
    v_band = np.floor(X * frequency).astype(np.int32)
    h_phase = ((v_band % 2) * np.pi).astype(np.float32)
    h_lines = np.sin(Y * frequency * np.pi * 2.0)
    v_lines = np.sin(X * frequency * np.pi * 2.0 + h_phase)
    # Interleave: horizontal strands over even v-bands, vertical over odd
    weave_select = ((v_band % 2) == 0).astype(np.float32)
    result = h_lines * weave_select + v_lines * (1.0 - weave_select)
    return _sm_scale(_normalize(result), sm).astype(np.float32)


def sunburst_rays(shape, seed, sm, n_rays=128, **kwargs):
    """Precision radial ray engraving â€” 128+ even/odd groove-land alternating rays with feathered edges."""
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    cy, cx = h / 2.0, w / 2.0
    yy, xx = np.mgrid[0:h, 0:w].astype(np.float32)
    theta = np.arctan2(yy - cy, xx - cx)
    # Fractional position within ray cycle
    ray_frac = ((theta + np.pi) / (np.pi * 2.0) * n_rays) % 1.0
    # Even/odd alternation with cosine feather at ray edges
    ray_idx = np.floor((theta + np.pi) / (np.pi * 2.0) * n_rays).astype(np.int32)
    base = (ray_idx % 2).astype(np.float32)
    edge_feather = np.cos((ray_frac - 0.5) * np.pi * 2.0)
    result = base * 0.6 + edge_feather * 0.4
    return _sm_scale(_normalize(result), sm).astype(np.float32)


def sunburst_wavy_rays(shape, seed, sm, n_rays=96, waver_freq=6.0, waver_amp=0.015, **kwargs):
    """Wavy-width radial rays â€” ray boundaries waver sinusoidally in r, creating spinning optical illusion."""
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    cy, cx = h / 2.0, w / 2.0
    yy, xx = np.mgrid[0:h, 0:w].astype(np.float32)
    dy, dx = yy - cy, xx - cx
    theta = np.arctan2(dy, dx)
    r = np.sqrt(dy * dy + dx * dx) / (min(h, w) * 0.5 + 1e-6)
    # Width modulation: waver_amp * sin(r * waver_freq * 2Ï€) varies ray width with radius
    width_mod = waver_amp * np.sin(r * waver_freq * np.pi * 2.0)
    eff_theta = theta + width_mod
    ray_frac = ((eff_theta + np.pi) / (np.pi * 2.0) * n_rays) % 1.0
    result = np.cos(ray_frac * np.pi * 2.0)
    return _sm_scale(_normalize(result), sm).astype(np.float32)


def cloisonne_grid(shape, seed, sm, scale=16.0, wire_width=0.12, **kwargs):
    """CloisonnÃ© raised wire grid â€” high-metallic wire lines, smooth-center cell interior roughness gradient."""
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    yy = np.arange(h, dtype=np.float32) / h * scale
    xx = np.arange(w, dtype=np.float32) / w * scale
    Y, X = np.meshgrid(yy, xx, indexing='ij')
    fy = Y % 1.0
    fx = X % 1.0
    dist_y = np.minimum(fy, 1.0 - fy)
    dist_x = np.minimum(fx, 1.0 - fx)
    wire_dist = np.minimum(dist_y, dist_x)
    # Wire proximity mask: near wire = full metallic, interior = smooth gradient
    wire_mask = np.clip(1.0 - wire_dist / wire_width, 0.0, 1.0)
    center_dist = wire_dist / 0.5
    result = wire_mask * 1.0 + (1.0 - wire_mask) * (1.0 - center_dist * 0.8)
    return _sm_scale(_normalize(result), sm).astype(np.float32)


def damascene_inlay(shape, seed, sm, freq=14.0, node_sharpness=4.0, **kwargs):
    """Damascene inlay â€” abs(sin)Â·abs(sin) nodes with metallic peaks at intersections, gold-inlay geometry."""
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    yy = np.arange(h, dtype=np.float32) / h
    xx = np.arange(w, dtype=np.float32) / w
    Y, X = np.meshgrid(yy, xx, indexing='ij')
    # Node: both axes high simultaneously
    node = (np.abs(np.sin(X * freq * np.pi)) * np.abs(np.sin(Y * freq * np.pi))) ** node_sharpness
    # Cross arms: partial high in one axis â€” lower metallic weave between nodes
    h_cross = np.abs(np.sin(Y * freq * np.pi)) ** (node_sharpness * 0.4)
    v_cross = np.abs(np.sin(X * freq * np.pi)) ** (node_sharpness * 0.4)
    result = node * 1.0 + (h_cross + v_cross) * 0.25 - (1.0 - node) * 0.15
    return _sm_scale(_normalize(result), sm).astype(np.float32)


def moire_engine(shape, seed, sm, freq=40.0, rotation_deg=5.0, **kwargs):
    """MoirÃ© interference guillochÃ© â€” two slightly-rotated vertical line families beat into emergent interference bands."""
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    yy = np.arange(h, dtype=np.float32) / h
    xx = np.arange(w, dtype=np.float32) / w
    Y, X = np.meshgrid(yy, xx, indexing='ij')
    eps = np.deg2rad(rotation_deg)
    # Family 1: pure vertical lines
    f1 = np.sin(X * freq * np.pi * 2.0)
    # Family 2: rotated by eps â€” the slight mis-alignment creates beating envelope
    f2 = np.sin((X * np.cos(eps) + Y * np.sin(eps)) * freq * np.pi * 2.0)
    result = f1 + f2
    return _sm_scale(_normalize(result), sm).astype(np.float32)


# ============================================================================
# PRIORITY 2 BATCH C -- WORN, PATINA & WEATHERING (90-101)
# R=Metallic (0=none,255=full), G=Roughness (0=mirror,255=matte),
# B=Clearcoat INVERTED (16=max gloss, 255=dull)
# ============================================================================

def spec_rust_bloom(shape, seed, sm, num_seeds=30, bloom_radius_frac=0.12, **kwargs):
    """spec_rust_bloom.

    identity: R6-CREATIVE â€” IRON OXIDE COLONY MAP. The original granular
    crust patches stay, but now overlaid with HERO motifs that make the
    pattern read as an active corrosion organism: (HERO A) DEEP CORE
    CRATERS â€” 6-12 jagged crater pits 14-20 px wide with darker rust
    sediment and a halo of brighter oxide bloom 20-28 px out; (HERO B)
    FLAKING SCABS â€” 10-18 px irregular polygonal scab plates that lift
    off the surface (bright lit-edge, dark shadow-edge giving 3D peel
    appearance); (HERO C) BRIGHT RIVULET STAINS â€” 30-60 px tear-shaped
    runoff trails downhill from a few craters (orange streaks in R, low
    M, low CC). Plus prior dense granule clusters (2-6 px), radial
    micro-cracks (8-16 px), dense pit-pore flecks, and bright crystal
    spec glints. Per-feature INDEPENDENT continuous M/R/CC.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 62103)
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)

    # 1) BASE â€” oxidized iron substrate
    g1 = _normalize(multi_scale_noise(shape, [2.0, 5.5, 12.0, 26.0], [0.34, 0.30, 0.22, 0.14], int(seed) + 4112))
    g2 = _normalize(multi_scale_noise(shape, [2.5, 6.5, 14.0, 28.0], [0.34, 0.30, 0.22, 0.14], int(seed) + 4113))
    g3 = _normalize(multi_scale_noise(shape, [3.0, 7.5, 16.0, 30.0], [0.34, 0.30, 0.22, 0.14], int(seed) + 4114))
    M = (0.55 + (g1 - 0.5) * 0.30).astype(np.float32)
    R = (0.50 + (g2 - 0.5) * 0.28).astype(np.float32)
    CC = (0.50 + (g3 - 0.5) * 0.30).astype(np.float32)

    if _CV2_OK:
        # HERO A: DEEP CORE CRATERS â€” 6-12 jagged pits with halo bloom
        n_crater = int(rng.integers(6, 13))
        for _ in range(n_crater):
            ccx = float(rng.uniform(0.06, 0.94) * w); ccy = float(rng.uniform(0.06, 0.94) * h)
            r_core = max(3, int(rng.uniform(14.0, 20.0) * scale * 0.5))
            r_halo = max(r_core + 4, int(rng.uniform(20.0, 28.0) * scale * 0.5))
            # Halo of brighter oxide bloom first (so core overrides)
            _cv2.circle(M, (int(ccx), int(ccy)), r_halo, float(rng.uniform(0.18, 0.38)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (int(ccx), int(ccy)), r_halo, float(rng.uniform(0.82, 0.96)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (int(ccx), int(ccy)), r_halo, float(rng.uniform(0.55, 0.82)), -1, lineType=_cv2.LINE_AA)
            # Jagged core â€” 6-8 small polygon points around center
            n_pts = int(rng.integers(7, 11))
            poly_pts = []
            for k in range(n_pts):
                ang = (k / n_pts) * 2 * np.pi + float(rng.uniform(-0.3, 0.3))
                r_k = r_core * float(rng.uniform(0.7, 1.2))
                px_ = int(np.clip(ccx + np.cos(ang) * r_k, 0, w - 1))
                py_ = int(np.clip(ccy + np.sin(ang) * r_k, 0, h - 1))
                poly_pts.append([px_, py_])
            poly_arr = np.array([poly_pts], dtype=np.int32)
            core_M = float(rng.uniform(0.05, 0.18))
            core_R = float(rng.uniform(0.86, 0.98))
            core_CC = float(rng.uniform(0.70, 0.92))
            _cv2.fillPoly(M, poly_arr, core_M, lineType=_cv2.LINE_AA)
            _cv2.fillPoly(R, poly_arr, core_R, lineType=_cv2.LINE_AA)
            _cv2.fillPoly(CC, poly_arr, core_CC, lineType=_cv2.LINE_AA)

        # HERO B: FLAKING SCABS â€” 10-18 px irregular polygonal plates with lit/shadow
        n_scab = int(np.clip(120 * (mn / 2048.0) ** 2, 50, 350))
        for _ in range(n_scab):
            cx = float(rng.uniform(0.03, 0.97) * w); cy = float(rng.uniform(0.03, 0.97) * h)
            r_sc = float(rng.uniform(10.0, 18.0) * scale * 0.5)
            n_pts = int(rng.integers(5, 8))
            poly_pts = []
            for k in range(n_pts):
                ang = (k / n_pts) * 2 * np.pi + float(rng.uniform(-0.25, 0.25))
                r_k = r_sc * float(rng.uniform(0.75, 1.15))
                px_ = int(np.clip(cx + np.cos(ang) * r_k, 0, w - 1))
                py_ = int(np.clip(cy + np.sin(ang) * r_k, 0, h - 1))
                poly_pts.append([px_, py_])
            poly_arr = np.array([poly_pts], dtype=np.int32)
            sM = float(rng.uniform(0.22, 0.42))
            sR = float(rng.uniform(0.75, 0.92))
            sCC = float(rng.uniform(0.58, 0.84))
            _cv2.fillPoly(M, poly_arr, sM, lineType=_cv2.LINE_AA)
            _cv2.fillPoly(R, poly_arr, sR, lineType=_cv2.LINE_AA)
            _cv2.fillPoly(CC, poly_arr, sCC, lineType=_cv2.LINE_AA)
            # Lit edge (top-left of polygon)
            lit_pts = [[int(cx - r_sc * 0.6), int(cy - r_sc * 0.6)],
                       [int(cx - r_sc * 0.1), int(cy - r_sc * 0.9)],
                       [int(cx - r_sc * 0.9), int(cy - r_sc * 0.1)]]
            _cv2.polylines(M, [np.array(lit_pts, dtype=np.int32)], False,
                           float(rng.uniform(0.70, 0.95)), 1, lineType=_cv2.LINE_AA)
            # Shadow edge (bottom-right)
            sh_pts = [[int(cx + r_sc * 0.5), int(cy + r_sc * 0.9)],
                      [int(cx + r_sc * 0.9), int(cy + r_sc * 0.5)]]
            _cv2.polylines(R, [np.array(sh_pts, dtype=np.int32)], False,
                           float(rng.uniform(0.88, 0.98)), 1, lineType=_cv2.LINE_AA)

        # HERO C: BRIGHT RIVULET STAINS â€” vertical-ish runoff tears
        n_riv = int(rng.integers(4, 9))
        for _ in range(n_riv):
            rx = float(rng.uniform(0.05, 0.95) * w)
            ry0 = float(rng.uniform(0.05, 0.60) * h)
            length = float(rng.uniform(30.0, 60.0) * scale)
            drift = float(rng.uniform(-6.0, 6.0))
            n_seg = max(6, int(length / 4))
            for s in range(n_seg):
                t = s / max(n_seg - 1, 1)
                px_ = int(np.clip(rx + drift * t, 0, w - 1))
                py_ = int(np.clip(ry0 + length * t, 0, h - 1))
                rr = max(1, int(rng.uniform(1.5, 3.5) * scale))
                # Tapers â€” narrower toward bottom
                rr = max(1, int(rr * (1.0 - 0.4 * t)))
                _cv2.circle(M, (px_, py_), rr, float(rng.uniform(0.15, 0.35)), -1, lineType=_cv2.LINE_AA)
                _cv2.circle(R, (px_, py_), rr, float(rng.uniform(0.78, 0.95)), -1, lineType=_cv2.LINE_AA)
                _cv2.circle(CC, (px_, py_), rr, float(rng.uniform(0.62, 0.85)), -1, lineType=_cv2.LINE_AA)

        # 2) CRUST GRANULE CLUSTERS â€” preserved
        n_clusters = int(np.clip(280 * (mn / 2048.0) ** 2, 100, 900))
        for _ in range(n_clusters):
            cx0 = float(rng.uniform(0.03, 0.97) * w); cy0 = float(rng.uniform(0.03, 0.97) * h)
            n_in_cluster = int(rng.integers(4, 10))
            cl_M = float(rng.uniform(0.10, 0.38))
            cl_R = float(rng.uniform(0.76, 0.97))
            cl_CC = float(rng.uniform(0.60, 0.93))
            for _g in range(n_in_cluster):
                dx = float(rng.normal(0, 5.0 * scale))
                dy = float(rng.normal(0, 5.0 * scale))
                gx = int(np.clip(cx0 + dx, 0, w - 1))
                gy = int(np.clip(cy0 + dy, 0, h - 1))
                r_g = max(1, int(rng.uniform(2.0, 5.5) * scale))
                jit_M = float(np.clip(cl_M + rng.uniform(-0.13, 0.13), 0.04, 0.55))
                jit_R = float(np.clip(cl_R + rng.uniform(-0.11, 0.06), 0.62, 0.99))
                jit_CC = float(np.clip(cl_CC + rng.uniform(-0.13, 0.11), 0.42, 0.97))
                _cv2.circle(M, (gx, gy), r_g, jit_M, -1, lineType=_cv2.LINE_AA)
                _cv2.circle(R, (gx, gy), r_g, jit_R, -1, lineType=_cv2.LINE_AA)
                _cv2.circle(CC, (gx, gy), r_g, jit_CC, -1, lineType=_cv2.LINE_AA)

        # 3) RADIAL MICRO-CRACKS
        n_crack = int(np.clip(900 * (mn / 2048.0) ** 2, 320, 2800))
        for _ in range(n_crack):
            cx = float(rng.uniform(0.02, 0.98) * w); cy = float(rng.uniform(0.02, 0.98) * h)
            ang = float(rng.uniform(0, 2 * np.pi))
            length = float(rng.uniform(8.0, 16.0) * scale)
            x2 = int(np.clip(cx + np.cos(ang) * length, 0, w - 1))
            y2 = int(np.clip(cy + np.sin(ang) * length, 0, h - 1))
            kM = float(rng.uniform(0.06, 0.30))
            kR = float(rng.uniform(0.70, 0.94))
            kCC = float(rng.uniform(0.62, 0.90))
            _cv2.line(M, (int(cx), int(cy)), (x2, y2), kM, 1, lineType=_cv2.LINE_AA)
            _cv2.line(R, (int(cx), int(cy)), (x2, y2), kR, 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (int(cx), int(cy)), (x2, y2), kCC, 1, lineType=_cv2.LINE_AA)

    # 4) DENSE PIT-PORE FLECKS
    n_pit = int(np.clip(2400 * (mn / 2048.0) ** 2, 800, 6500))
    py = rng.integers(0, h, n_pit); px = rng.integers(0, w, n_pit)
    M[py, px] = np.minimum(M[py, px], rng.uniform(0.04, 0.26, n_pit).astype(np.float32))
    R[py, px] = np.maximum(R[py, px], rng.uniform(0.68, 0.97, n_pit).astype(np.float32))
    CC[py, px] = np.maximum(CC[py, px], rng.uniform(0.52, 0.92, n_pit).astype(np.float32))

    # 5) BRIGHT CRYSTAL SPECS
    n_crys = int(np.clip(700 * (mn / 2048.0) ** 2, 240, 2200))
    cxs = rng.integers(0, w, n_crys); cys = rng.integers(0, h, n_crys)
    M[cys, cxs] = np.maximum(M[cys, cxs], rng.uniform(0.55, 0.95, n_crys).astype(np.float32))
    R[cys, cxs] = np.minimum(R[cys, cxs], rng.uniform(0.15, 0.48, n_crys).astype(np.float32))
    CC[cys, cxs] = np.minimum(CC[cys, cxs], rng.uniform(0.10, 0.40, n_crys).astype(np.float32))

    out = np.stack([M, R, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
spec_rust_bloom._spb_concept_complete = True


def spec_patina_verdigris(shape, seed, sm, octaves=5, persistence=0.55, **kwargs):
    """spec_patina_verdigris.

    identity: R6-CREATIVE â€” DENDRITIC VERDIGRIS REEF. Crystalline teal
    patina that has grown into reef-like dendritic branches (think
    coral colonies). Three crystal scales stack:
      â€¢ Macro dendrites: branching tree-shaped growth networks
        (random-walk root that forks into 2-4 subbranches, each
        plated with crystalline polygons along its length).
      â€¢ Mid crystal facets (4-6 px irregular polygons, varied
        chroma per facet â€” from chalky white-green to deep ocean
        teal to vivid emerald to indigo blue).
      â€¢ Micro grain crust (2-3 px triangular wedges densely
        packed in the space between dendrites).
    Punctuated by bare bronze flake-pinholes (the substrate
    showing through) and tiny mineral SUNSPOTS that catch hard
    highlight. Differentiates from patina_bloom (no branching),
    copper_patina_drip (no vertical motion), spec_oxidized_pitting
    (additive crystal growth not corrosive cratering).
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 41617)
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)

    # 1) Deep teal crust BASE (low M, high R, very high CC)
    gM = _normalize(multi_scale_noise(shape, [2.5, 6.0, 14.0], [0.45, 0.32, 0.23], int(seed) + 7411))
    gR = _normalize(multi_scale_noise(shape, [3.0, 7.0, 16.0], [0.45, 0.32, 0.23], int(seed) + 7413))
    gCC = _normalize(multi_scale_noise(shape, [3.5, 8.0, 18.0], [0.45, 0.32, 0.23], int(seed) + 7415))
    M = (0.22 + (gM - 0.5) * 0.18).astype(np.float32)
    R = (0.72 + (gR - 0.5) * 0.20).astype(np.float32)
    CC = (0.78 + (gCC - 0.5) * 0.18).astype(np.float32)

    if _CV2_OK:
        # 2) MACRO DENDRITES â€” branching reef-coral networks
        n_dendrites = int(np.clip(28 * (mn / 256.0), 12, 70))
        for _ in range(n_dendrites):
            # Each dendrite: root â†’ 2-4 main branches â†’ each branch has sub-twigs
            rx = float(rng.uniform(0.05, 0.95) * w)
            ry = float(rng.uniform(0.05, 0.95) * h)
            d_M = float(rng.uniform(0.06, 0.22))
            d_R = float(rng.uniform(0.78, 0.96))
            d_CC = float(rng.uniform(0.82, 0.98))
            n_branches = int(rng.integers(2, 5))
            for b in range(n_branches):
                ang = float(rng.uniform(0, 2 * np.pi))
                steps = int(rng.uniform(6, 14))
                bx, by = rx, ry
                step_len = float(rng.uniform(2.0, 4.0) * scale)
                for _s in range(steps):
                    ang += float(rng.uniform(-0.45, 0.45))
                    nx = bx + np.cos(ang) * step_len
                    ny = by + np.sin(ang) * step_len
                    if not (0 <= nx < w and 0 <= ny < h): break
                    r = max(1, int(rng.uniform(1.5, 3.0) * scale))
                    _cv2.line(M, (int(bx), int(by)), (int(nx), int(ny)), d_M, r, lineType=_cv2.LINE_AA)
                    _cv2.line(R, (int(bx), int(by)), (int(nx), int(ny)), d_R, r, lineType=_cv2.LINE_AA)
                    _cv2.line(CC, (int(bx), int(by)), (int(nx), int(ny)), d_CC, r, lineType=_cv2.LINE_AA)
                    # Twig fork (occasional)
                    if rng.random() < 0.35:
                        tw_ang = ang + float(rng.choice([-1, 1])) * float(rng.uniform(0.6, 1.2))
                        tw_len = step_len * float(rng.uniform(0.7, 1.4))
                        tx2 = nx + np.cos(tw_ang) * tw_len
                        ty2 = ny + np.sin(tw_ang) * tw_len
                        if 0 <= tx2 < w and 0 <= ty2 < h:
                            _cv2.line(M, (int(nx), int(ny)), (int(tx2), int(ty2)), d_M, 1, lineType=_cv2.LINE_AA)
                            _cv2.line(R, (int(nx), int(ny)), (int(tx2), int(ty2)), d_R, 1, lineType=_cv2.LINE_AA)
                            _cv2.line(CC, (int(nx), int(ny)), (int(tx2), int(ty2)), d_CC, 1, lineType=_cv2.LINE_AA)
                    bx, by = nx, ny

        # 3) MID CRYSTAL FACETS â€” irregular 4-6 px polygons with WIDE chroma palette
        n_facets = int(np.clip(1800 * (mn / 2048.0) ** 2, 600, 5500))
        for _ in range(n_facets):
            cx = float(rng.uniform(2, w - 2)); cy = float(rng.uniform(2, h - 2))
            r0 = float(rng.uniform(3.0, 6.0) * scale)
            n_v = int(rng.integers(4, 7))
            pts = []
            a0 = float(rng.uniform(0, 2 * np.pi))
            for k in range(n_v):
                ang = a0 + (k * 2 * np.pi / n_v) + float(rng.uniform(-0.3, 0.3))
                rk = r0 * float(rng.uniform(0.6, 1.3))
                pts.append([int(np.clip(cx + np.cos(ang) * rk, 0, w - 1)),
                            int(np.clip(cy + np.sin(ang) * rk, 0, h - 1))])
            poly = np.array(pts, dtype=np.int32)
            palette = rng.choice(5)
            if palette == 0:   # deep ocean teal
                cM, cR, cCC = rng.uniform(0.05, 0.15), rng.uniform(0.82, 0.96), rng.uniform(0.85, 0.97)
            elif palette == 1: # chalky white-green
                cM, cR, cCC = rng.uniform(0.18, 0.30), rng.uniform(0.65, 0.82), rng.uniform(0.72, 0.88)
            elif palette == 2: # vivid emerald
                cM, cR, cCC = rng.uniform(0.10, 0.22), rng.uniform(0.55, 0.72), rng.uniform(0.88, 0.97)
            elif palette == 3: # indigo blue
                cM, cR, cCC = rng.uniform(0.15, 0.28), rng.uniform(0.78, 0.92), rng.uniform(0.92, 0.99)
            else:              # bright mineral facet
                cM, cR, cCC = rng.uniform(0.35, 0.58), rng.uniform(0.42, 0.62), rng.uniform(0.55, 0.78)
            _cv2.fillPoly(M, [poly], float(cM), lineType=_cv2.LINE_AA)
            _cv2.fillPoly(R, [poly], float(cR), lineType=_cv2.LINE_AA)
            _cv2.fillPoly(CC, [poly], float(cCC), lineType=_cv2.LINE_AA)

        # 4) MICRO GRAIN CRUST â€” small triangle wedges packing the field
        n_micro = int(np.clip(4200 * (mn / 2048.0) ** 2, 1400, 12000))
        for _ in range(n_micro):
            cx = float(rng.uniform(2, w - 2)); cy = float(rng.uniform(2, h - 2))
            r0 = float(rng.uniform(1.2, 2.6) * scale)
            a0 = float(rng.uniform(0, 2 * np.pi))
            pts = []
            for k in range(3):
                ang = a0 + (k * 2 * np.pi / 3) + float(rng.uniform(-0.4, 0.4))
                rk = r0 * float(rng.uniform(0.7, 1.3))
                pts.append([int(np.clip(cx + np.cos(ang) * rk, 0, w - 1)),
                            int(np.clip(cy + np.sin(ang) * rk, 0, h - 1))])
            poly = np.array(pts, dtype=np.int32)
            mM = float(rng.uniform(0.08, 0.28))
            mR = float(rng.uniform(0.70, 0.92))
            mCC = float(rng.uniform(0.75, 0.96))
            _cv2.fillPoly(M, [poly], mM, lineType=_cv2.LINE_AA)
            _cv2.fillPoly(R, [poly], mR, lineType=_cv2.LINE_AA)
            _cv2.fillPoly(CC, [poly], mCC, lineType=_cv2.LINE_AA)

        # 5) BARE BRONZE FLAKE-PINHOLES â€” substrate showing through
        n_flake = int(np.clip(700 * (mn / 2048.0) ** 2, 240, 2100))
        for _ in range(n_flake):
            cx = int(rng.uniform(0.02, 0.98) * w); cy = int(rng.uniform(0.02, 0.98) * h)
            r = max(1, int(rng.uniform(1.5, 3.5) * scale))
            _cv2.circle(M, (cx, cy), r, float(rng.uniform(0.72, 0.95)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r, float(rng.uniform(0.15, 0.38)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r, float(rng.uniform(0.12, 0.35)), -1, lineType=_cv2.LINE_AA)

    # 6) MINERAL SUNSPOTS â€” bright micro-glints (mineral facet hits)
    n_fl = int(np.clip(1500 * (mn / 2048.0) ** 2, 500, 3800))
    fy = rng.integers(0, h, n_fl); fx = rng.integers(0, w, n_fl)
    M[fy, fx] = np.maximum(M[fy, fx], rng.uniform(0.45, 0.85, n_fl).astype(np.float32))
    CC[fy, fx] = np.maximum(CC[fy, fx], rng.uniform(0.55, 0.95, n_fl).astype(np.float32))

    out = np.stack([M, R, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
spec_patina_verdigris._spb_concept_complete = True


def spec_oxidized_pitting(shape, seed, sm, **kwargs):
    """spec_oxidized_pitting.

    identity: R6 creative rebuild â€” chloride pit-cluster colony with a HERO
    "exfoliating scale lift" motif. Real chloride pitting forms COLONIES,
    not isolated craters: clusters of 5-9 deep pits 2-5 px each share a
    common rust halo (8-16 px) so you read the colony as one organism.
    NEW hero tier: small curved scale-LIFT EDGES (8-16 px arcs) where
    the cracking oxide is peeling up from the substrate â€” the dramatic
    differentiator. Plus undermining tunnels (short 6-12 px hairlines
    radiating from colony cores), bare-metal nick stars, brown sweat
    streaks running gravitationally, fine pepper. Independent
    continuous M/R/CC per primitive; wide chroma ranges so neighbouring
    colonies never read alike. Differentiator vs salt_spray (mist,
    no colonies) and vs galvanic (interface, no lifts).
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 31011)
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)
    # 1) BASE â€” corroded aluminum substrate, independent M/R/CC FBM
    base_M = _normalize(multi_scale_noise(shape, [2.5, 6.5, 14.0, 24.0], [0.34, 0.28, 0.22, 0.16], int(seed) + 31101))
    base_R = _normalize(multi_scale_noise(shape, [3.0, 7.5, 15.0, 26.0], [0.32, 0.28, 0.24, 0.16], int(seed) + 31102))
    base_CC = _normalize(multi_scale_noise(shape, [3.5, 8.0, 17.0, 28.0], [0.30, 0.28, 0.24, 0.18], int(seed) + 31103))
    M = (0.52 + (base_M - 0.5) * 0.34).astype(np.float32)
    R = (0.66 + (base_R - 0.5) * 0.32).astype(np.float32)
    CC = (0.50 + (base_CC - 0.5) * 0.32).astype(np.float32)
    if _CV2_OK:
        # 2) PIT COLONIES â€” clustered crater colonies sharing a soft rust halo
        n_col = int(np.clip(1500 * (mn / 2048.0) ** 2, 550, 3800))
        for _ in range(n_col):
            cxc = float(rng.uniform(8, w - 8)); cyc = float(rng.uniform(8, h - 8))
            halo_r = max(3, int(rng.uniform(8.0, 16.0) * scale * 0.5))
            # Soft rust halo (low-amp brown stain ring)
            hM = float(rng.uniform(0.32, 0.58))
            hR = float(rng.uniform(0.62, 0.86))
            hCC = float(rng.uniform(0.55, 0.82))
            _cv2.circle(M, (int(cxc), int(cyc)), halo_r, hM, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (int(cxc), int(cyc)), halo_r, hR, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (int(cxc), int(cyc)), halo_r, hCC, -1, lineType=_cv2.LINE_AA)
            # 5-9 deep pit craters inside the colony, each independent
            n_pit = int(rng.integers(5, 10))
            for _k in range(n_pit):
                pang = float(rng.uniform(0, 2 * np.pi))
                pdist = float(rng.uniform(0.0, halo_r * 0.85))
                px = int(cxc + np.cos(pang) * pdist)
                py = int(cyc + np.sin(pang) * pdist)
                pr = max(1, int(rng.uniform(2.0, 5.0) * scale * 0.5))
                _cv2.circle(M, (px, py), pr, float(rng.uniform(0.05, 0.22)), -1, lineType=_cv2.LINE_AA)
                _cv2.circle(R, (px, py), pr, float(rng.uniform(0.72, 0.97)), -1, lineType=_cv2.LINE_AA)
                _cv2.circle(CC, (px, py), pr, float(rng.uniform(0.58, 0.92)), -1, lineType=_cv2.LINE_AA)
                # bright work-hardened rim on ~half
                if rng.random() < 0.55:
                    _cv2.circle(M, (px, py), pr + 1, float(rng.uniform(0.68, 0.94)), 1, lineType=_cv2.LINE_AA)
                    _cv2.circle(R, (px, py), pr + 1, float(rng.uniform(0.12, 0.36)), 1, lineType=_cv2.LINE_AA)
                    _cv2.circle(CC, (px, py), pr + 1, float(rng.uniform(0.10, 0.32)), 1, lineType=_cv2.LINE_AA)
            # Undermining tunnels â€” short hairlines radiating from colony core
            n_und = int(rng.integers(3, 7))
            for _k in range(n_und):
                ang = float(rng.uniform(0, 2 * np.pi))
                ln = float(rng.uniform(6.0, 12.0) * scale)
                x2 = int(cxc + np.cos(ang) * ln); y2 = int(cyc + np.sin(ang) * ln)
                _cv2.line(M, (int(cxc), int(cyc)), (x2, y2), float(rng.uniform(0.18, 0.42)), 1, lineType=_cv2.LINE_AA)
                _cv2.line(R, (int(cxc), int(cyc)), (x2, y2), float(rng.uniform(0.62, 0.92)), 1, lineType=_cv2.LINE_AA)
                _cv2.line(CC, (int(cxc), int(cyc)), (x2, y2), float(rng.uniform(0.48, 0.85)), 1, lineType=_cv2.LINE_AA)
        # 3) HERO â€” EXFOLIATING SCALE LIFTS (curved 8-16 px arcs where oxide
        #    is peeling up). Drawn as eyebrow polylines with bright top edge.
        n_lift = int(np.clip(1800 * (mn / 2048.0) ** 2, 650, 4500))
        for _ in range(n_lift):
            cx = float(rng.uniform(6, w - 6)); cy = float(rng.uniform(6, h - 6))
            arc_len = float(rng.uniform(8.0, 16.0) * scale)
            arc_ang = float(rng.uniform(0, 2 * np.pi))
            # Sample 4 points along a shallow arc
            curv = float(rng.uniform(-0.6, 0.6))
            perp = arc_ang + np.pi * 0.5
            pts_x = []; pts_y = []
            for t in [-0.5, -0.16, 0.16, 0.5]:
                bx = cx + np.cos(arc_ang) * arc_len * t
                by = cy + np.sin(arc_ang) * arc_len * t
                bow = (1.0 - (2 * t) ** 2) * curv * arc_len * 0.18
                pts_x.append(int(bx + np.cos(perp) * bow))
                pts_y.append(int(by + np.sin(perp) * bow))
            poly = np.array(list(zip(pts_x, pts_y)), dtype=np.int32)
            # Bright top edge (lifted scale catches light)
            lM = float(rng.uniform(0.62, 0.94))
            lR = float(rng.uniform(0.14, 0.42))
            lCC = float(rng.uniform(0.08, 0.34))
            _cv2.polylines(M, [poly], False, lM, 1, lineType=_cv2.LINE_AA)
            _cv2.polylines(R, [poly], False, lR, 1, lineType=_cv2.LINE_AA)
            _cv2.polylines(CC, [poly], False, lCC, 1, lineType=_cv2.LINE_AA)
            # Dark shadow under-edge (offset by 1 px perpendicular)
            off = 1
            shd_x = [int(x + np.cos(perp) * off) for x in pts_x]
            shd_y = [int(y + np.sin(perp) * off) for y in pts_y]
            shd_poly = np.array(list(zip(shd_x, shd_y)), dtype=np.int32)
            _cv2.polylines(M, [shd_poly], False, float(rng.uniform(0.10, 0.30)), 1, lineType=_cv2.LINE_AA)
            _cv2.polylines(R, [shd_poly], False, float(rng.uniform(0.68, 0.94)), 1, lineType=_cv2.LINE_AA)
            _cv2.polylines(CC, [shd_poly], False, float(rng.uniform(0.55, 0.88)), 1, lineType=_cv2.LINE_AA)
        # 4) BARE-METAL NICK STARS â€” 4-arm hairline crosses
        n_nick = int(np.clip(1800 * (mn / 2048.0) ** 2, 600, 4500))
        for _ in range(n_nick):
            cx = float(rng.uniform(6, w - 6)); cy = float(rng.uniform(6, h - 6))
            base_ang = float(rng.uniform(0, np.pi))
            arm = float(rng.uniform(3.0, 5.5) * scale)
            nM = float(rng.uniform(0.72, 0.97))
            nR = float(rng.uniform(0.10, 0.32))
            nCC = float(rng.uniform(0.06, 0.26))
            for k in range(4):
                ang = base_ang + k * (np.pi / 2.0)
                x2 = int(cx + np.cos(ang) * arm); y2 = int(cy + np.sin(ang) * arm)
                _cv2.line(M, (int(cx), int(cy)), (x2, y2), nM, 1, lineType=_cv2.LINE_AA)
                _cv2.line(R, (int(cx), int(cy)), (x2, y2), nR, 1, lineType=_cv2.LINE_AA)
                _cv2.line(CC, (int(cx), int(cy)), (x2, y2), nCC, 1, lineType=_cv2.LINE_AA)
        # 5) GRAVITY SWEAT STREAKS â€” vertical bias 10-18 px (corrosion runs downward)
        n_sw = int(np.clip(900 * (mn / 2048.0) ** 2, 320, 2400))
        for _ in range(n_sw):
            cx = float(rng.uniform(4, w - 4)); cy = float(rng.uniform(4, h - 4))
            length = float(rng.uniform(10.0, 18.0) * scale)
            ang = float(rng.uniform(np.pi * 0.40, np.pi * 0.60))  # near-vertical
            x0s = int(cx - np.cos(ang) * length * 0.5)
            y0s = int(cy - np.sin(ang) * length * 0.5)
            x1s = int(cx + np.cos(ang) * length * 0.5)
            y1s = int(cy + np.sin(ang) * length * 0.5)
            _cv2.line(M, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.25, 0.52)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(R, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.58, 0.88)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.42, 0.78)), 1, lineType=_cv2.LINE_AA)
    # 6) MICROFLORA PEPPER CARPET â€” saturation so no pixel reads as virgin
    n_flecks = int(np.clip(mn * mn / 60.0, 4000, 16000))
    fx = rng.integers(0, w, n_flecks); fy = rng.integers(0, h, n_flecks)
    fM = rng.uniform(0.08, 0.95, n_flecks).astype(np.float32)
    fR = rng.uniform(0.25, 0.97, n_flecks).astype(np.float32)
    fCC = rng.uniform(0.10, 0.92, n_flecks).astype(np.float32)
    M[fy, fx] = fM; R[fy, fx] = fR; CC[fy, fx] = fCC
    out = np.stack([M, R, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
spec_oxidized_pitting._spb_concept_complete = True


def spec_heat_scale(shape, seed, sm, band_count=14, noise_warp=0.08, **kwargs):
    """spec_heat_scale.

    identity: R6 creative rebuild â€” titanium turbine-housing heat-blue spectral
    scale. Polychrome oxide rings radiate asymmetrically from a hot zone with
    pronounced WIDE-CHROMA shifts band-to-band (blue/purple/straw/copper bands
    via independent M, R, CC continuous uniforms ranges 0.08-0.95). HERO motif:
    a constellation of curved scale-EDGE CRACK ARCS â€” dramatic 18-36 px curved
    hairlines that trace ring tangents, leaving the surface looking truly
    exfoliated. Stacked tiers: (1) ring substrate with high band count + fbm
    warp, (2) tight hot core glow with desaturated peak, (3) hero arc-cracks,
    (4) carbon soot micro-flecks (1-2 px), (5) recrystallised metal pinpoints
    (1-2 px) with bright CC spikes, (6) micro spangle along ring crests.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 2707)
    mn = float(min(h, w))
    scale = max(mn / 256.0, 0.6)

    yy, xx = np.mgrid[0:h, 0:w].astype(np.float32)
    xn = xx / max(w - 1, 1)
    yn = yy / max(h - 1, 1)

    src_x = float(rng.uniform(0.18, 0.82))
    src_y = float(rng.uniform(0.18, 0.82))
    aspect = float(rng.uniform(1.05, 1.5))
    dist = np.sqrt((xn - src_x) ** 2 + ((yn - src_y) * aspect) ** 2)

    warp_a = _gauss(rng.random((h, w)).astype(np.float32), sigma=max(mn / 40.0, 1.5))
    warp_b = _gauss(rng.random((h, w)).astype(np.float32), sigma=max(mn / 14.0, 1.5))
    warp = (warp_a * 0.55 + warp_b * 0.45) - 0.5

    band_freq = float(np.clip(band_count * rng.uniform(0.9, 1.2), 14.0, 22.0))
    oxide = dist * float(rng.uniform(7.0, 10.0)) + warp * float(rng.uniform(0.9, 1.6))
    bands_cos = 0.5 + 0.5 * np.sin(oxide * np.pi * band_freq)

    # Band index â€” for INDEPENDENT per-ring chroma palette
    band_idx = np.floor(oxide * band_freq).astype(np.int32)
    n_bands = int(np.max(band_idx) - np.min(band_idx)) + 4
    rng_b = np.random.default_rng(int(seed) + 2711)
    m_pal = rng_b.uniform(0.08, 0.95, n_bands).astype(np.float32)
    r_pal = rng_b.uniform(0.08, 0.95, n_bands).astype(np.float32)
    c_pal = rng_b.uniform(0.08, 0.95, n_bands).astype(np.float32)
    idx_norm = np.clip(band_idx - int(np.min(band_idx)), 0, n_bands - 1)

    core = np.exp(-(dist / float(rng.uniform(0.16, 0.26))) ** 2)

    # Substrate per-ring polychrome
    M = (m_pal[idx_norm] * (0.6 + bands_cos * 0.4) + core * 0.12 - warp * 0.06).astype(np.float32)
    R_ch = (r_pal[idx_norm] * (0.6 + (1.0 - bands_cos) * 0.4) + warp * 0.08).astype(np.float32)
    CC = (c_pal[idx_norm] * (0.6 + bands_cos * 0.4) - core * 0.08 + warp * 0.05).astype(np.float32)

    # Hot-core desaturate
    M = M * (1.0 - core * 0.55) + core * 0.94
    R_ch = R_ch * (1.0 - core * 0.55) + core * 0.06
    CC = CC * (1.0 - core * 0.55) + core * 0.90

    # Pass A â€” dense carbon soot micro-flecks
    n_soot = int(np.clip(mn * mn / 80.0, 2000, 10000))
    sy = rng.integers(0, h, size=n_soot); sx = rng.integers(0, w, size=n_soot)
    M[sy, sx] = rng.uniform(0.05, 0.28, size=n_soot).astype(np.float32)
    R_ch[sy, sx] = rng.uniform(0.55, 0.95, size=n_soot).astype(np.float32)
    CC[sy, sx] = rng.uniform(0.10, 0.45, size=n_soot).astype(np.float32)

    # Pass B â€” recrystallisation pinpoints
    n_xt = int(np.clip(mn * mn / 120.0, 1500, 8000))
    cy_ = rng.integers(0, h, size=n_xt); cx_ = rng.integers(0, w, size=n_xt)
    M[cy_, cx_] = rng.uniform(0.70, 0.99, size=n_xt).astype(np.float32)
    R_ch[cy_, cx_] = rng.uniform(0.05, 0.25, size=n_xt).astype(np.float32)
    CC[cy_, cx_] = rng.uniform(0.55, 0.99, size=n_xt).astype(np.float32)

    if _CV2_OK:
        # HERO MOTIF â€” long curved arc-cracks tracing ring tangents (18-36 px)
        n_arc = int(np.clip(220 * scale * scale, 90, 450))
        for _ in range(n_arc):
            # Pick a radial position
            r0 = float(rng.uniform(0.10, 0.65))
            theta0 = float(rng.uniform(0, 2 * np.pi))
            # Walk along tangent in segments to render an arc
            n_seg = int(rng.uniform(5, 11))
            seg_len = float(rng.uniform(4.0, 7.0) * scale)
            theta = theta0
            vM = float(rng.uniform(0.10, 0.32))
            vR = float(rng.uniform(0.55, 0.92))
            vCC = float(rng.uniform(0.18, 0.50))
            for s_ in range(n_seg):
                # Position in normalized coords
                px = src_x + r0 * np.cos(theta)
                py = src_y + r0 * np.sin(theta) / aspect
                # Tangent direction
                tan = theta + np.pi * 0.5
                # Next position
                arc_dx = float(np.cos(tan)) * seg_len / max(w, 1)
                arc_dy = float(np.sin(tan)) * seg_len / max(h, 1)
                px2 = px + arc_dx; py2 = py + arc_dy
                # Slowly bend
                theta += float(rng.uniform(0.05, 0.20)) * float(rng.choice([-1, 1]))
                x_a = int(px * w); y_a = int(py * h)
                x_b = int(px2 * w); y_b = int(py2 * h)
                if 0 <= x_a < w and 0 <= y_a < h and 0 <= x_b < w and 0 <= y_b < h:
                    _cv2.line(M, (x_a, y_a), (x_b, y_b), vM, 1, lineType=_cv2.LINE_AA)
                    _cv2.line(R_ch, (x_a, y_a), (x_b, y_b), vR, 1, lineType=_cv2.LINE_AA)
                    _cv2.line(CC, (x_a, y_a), (x_b, y_b), vCC, 1, lineType=_cv2.LINE_AA)

        # SHORT TANGENTIAL HAIRLINE FRACTURES (4-12 px)
        n_hair = int(np.clip(800 * scale * scale, 300, 2200))
        for _ in range(n_hair):
            cx0 = float(rng.uniform(0, w)); cy0 = float(rng.uniform(0, h))
            tangent = float(np.arctan2(cy0 / max(h, 1) - src_y, cx0 / max(w, 1) - src_x) + np.pi * 0.5)
            length = float(rng.uniform(4.0, 12.0) * scale)
            x_a = int(cx0 - np.cos(tangent) * length * 0.5)
            y_a = int(cy0 - np.sin(tangent) * length * 0.5)
            x_b = int(cx0 + np.cos(tangent) * length * 0.5)
            y_b = int(cy0 + np.sin(tangent) * length * 0.5)
            _cv2.line(M, (x_a, y_a), (x_b, y_b), float(rng.uniform(0.18, 0.50)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(R_ch, (x_a, y_a), (x_b, y_b), float(rng.uniform(0.40, 0.88)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (x_a, y_a), (x_b, y_b), float(rng.uniform(0.20, 0.60)), 1, lineType=_cv2.LINE_AA)

        # R6 OWNER-REBUILD (REBUILD 5): "Get rid of the random bigger circles".
        # The burnt-oil iridescent stains (4-9 irregular 10-20px blobs) were
        # the offending feature â€” REMOVED. We keep ONLY the incandescent
        # ember pinpoints (3-5 px, fine, in-doctrine) and the existing arc
        # cracks + soot + recrystallisation pinpoints.

        # incandescent ember pinpoints near the hot core
        n_ember = int(np.clip(11 * scale, 8, 18))
        for _ in range(n_ember):
            ea = float(rng.uniform(0, 2 * np.pi))
            ed = float(rng.uniform(0.05, 0.32))
            ex_n = src_x + np.cos(ea) * ed
            ey_n = src_y + np.sin(ea) * ed
            ex = int(np.clip(ex_n * w, 1, w - 2))
            ey = int(np.clip(ey_n * h, 1, h - 2))
            er = max(1, int(rng.uniform(1.5, 3.0) * scale))
            _cv2.circle(M, (ex, ey), er, float(rng.uniform(0.88, 0.99)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R_ch, (ex, ey), er, float(rng.uniform(0.04, 0.16)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (ex, ey), er, float(rng.uniform(0.75, 0.99)), -1, lineType=_cv2.LINE_AA)

    out = np.stack([M, R_ch, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
spec_heat_scale._spb_concept_complete = True


def spec_galvanic_corrosion(shape, seed, sm, num_sites=120, corrosion_band=6.0, **kwargs):
    """spec_galvanic_corrosion.

    identity: OWNER REDESIGN 2026-06-04 ("should be more abstract, the pattern
    is just wrong"). The old version was a rigid wavy HORIZONTAL interface line
    that read as a stripe. Now fully ABSTRACT galvanic corrosion: two dissimilar
    metals interpenetrate as ORGANIC reaction regions (domain-warped noise, no
    line), the galvanic couple drives ANODIC blooms eaten into the cathodic
    metal, and every metal-to-metal boundary is an ELECTROLYTIC EATEN EDGE
    (dissolved, ragged, with bright crust + dark pitting). Organic corrosion
    field, not a fault line.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 21987)
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)
    s256 = max(mn / 256.0, 0.6)

    # --- ABSTRACT two-metal field: domain-warped noise gives organic, irregular
    #     interpenetrating regions of the two dissimilar metals (NO line). ---
    # PERF 2026-06-04: these are all smooth low-freq carrier fields; render them
    # at capped resolution and upscale (identical math <=1024px, so std@256 is
    # unchanged and the only effect at 2048 is invisible softening of the
    # carrier). This is the dominant cost of the function at 2048.
    warp_x = (_normalize(_spb_fast_smooth_noise(shape, [10.0, 24.0], [0.6, 0.4], int(seed) + 7201, max_dim=768)) - 0.5)
    warp_y = (_normalize(_spb_fast_smooth_noise(shape, [11.0, 26.0], [0.6, 0.4], int(seed) + 7203, max_dim=768)) - 0.5)
    base = _spb_fast_smooth_noise(shape, [6.0, 14.0, 30.0], [0.5, 0.3, 0.2], int(seed) + 7205, max_dim=768)
    # warp the field so the boundaries are ragged/organic (electrolytic eaten).
    field = _normalize(base + (warp_x + warp_y) * 0.6).astype(np.float32)
    # anodic fraction = how corroded; smoothstep gives soft-but-irregular regions.
    thr = float(rng.uniform(0.45, 0.55))
    anodic = np.clip((field - thr) / 0.18 + 0.5, 0.0, 1.0).astype(np.float32)

    gM = _normalize(_spb_fast_smooth_noise(shape, [3.0, 7.0, 14.0], [0.45, 0.32, 0.23], int(seed) + 7211, max_dim=768))
    gR = _normalize(_spb_fast_smooth_noise(shape, [3.5, 8.0, 16.0], [0.45, 0.32, 0.23], int(seed) + 7213, max_dim=768))
    gCC = _normalize(_spb_fast_smooth_noise(shape, [4.0, 9.0, 18.0], [0.45, 0.32, 0.23], int(seed) + 7215, max_dim=768))

    # Cathodic (nobler, cleaner) metal vs anodic (sacrificed, corroded) metal.
    M_cath = 0.74 + (gM - 0.5) * 0.18
    R_cath = 0.28 + (gR - 0.5) * 0.16
    CC_cath = 0.30 + (gCC - 0.5) * 0.16
    M_anod = 0.22 + (gM - 0.5) * 0.18
    R_anod = 0.78 + (gR - 0.5) * 0.18
    CC_anod = 0.70 + (gCC - 0.5) * 0.20

    M = (M_cath * (1.0 - anodic) + M_anod * anodic).astype(np.float32)
    R = (R_cath * (1.0 - anodic) + R_anod * anodic).astype(np.float32)
    CC = (CC_cath * (1.0 - anodic) + CC_anod * anodic).astype(np.float32)

    # ELECTROLYTIC EATEN EDGE: every metal-to-metal boundary (gradient of the
    # anodic fraction) gets darkened + crusted -> ragged dissolved seams.
    gy, gx = np.gradient(anodic.astype(np.float32))
    edge = np.clip(np.sqrt(gx * gx + gy * gy) * 14.0, 0.0, 1.0).astype(np.float32)
    M = np.clip(M - edge * 0.22, 0, 1)
    R = np.clip(R + edge * 0.24, 0, 1)
    CC = np.clip(CC + edge * 0.16, 0, 1)

    if _CV2_OK:
        # Sample helper: pick points biased to the EATEN EDGES (boundaries) or
        # to the ANODIC regions, abstractly (no interface line).
        edge_pts = np.argwhere(edge > 0.35)
        anod_pts = np.argwhere(anodic > 0.6)

        def _pick(pool, n):
            if len(pool) == 0:
                return np.empty((0, 2), dtype=np.int64)
            idx = rng.integers(0, len(pool), n)
            return pool[idx]

        # DENSE FINE pitting eaten along the electrolytic edges (organic, not a band).
        n_pit = int(np.clip(2200 * (mn / 2048.0) ** 2, 800, 6500))
        ep = _pick(edge_pts, n_pit)
        for cy, cx in ep:
            cy = int(cy + rng.normal(0, 3) * scale); cx = int(cx + rng.normal(0, 3) * scale)
            if not (0 <= cy < h and 0 <= cx < w):
                continue
            r = max(1, int(rng.uniform(1.6, 4.0) * scale))
            _cv2.circle(M, (cx, cy), r, float(rng.uniform(0.05, 0.18)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r, float(rng.uniform(0.78, 0.96)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r, float(rng.uniform(0.62, 0.90)), -1, lineType=_cv2.LINE_AA)

        # Bright galvanic crust micro-grains along the eaten edges (M peaks).
        n_crust = int(np.clip(900 * (mn / 2048.0) ** 2, 300, 2400))
        cp = _pick(edge_pts, n_crust)
        for cy, cx in cp:
            r = max(1, int(rng.uniform(1.0, 2.5) * scale))
            _cv2.circle(M, (int(cx), int(cy)), r, float(rng.uniform(0.62, 0.92)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (int(cx), int(cy)), r, float(rng.uniform(0.15, 0.42)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (int(cx), int(cy)), r, float(rng.uniform(0.10, 0.32)), -1, lineType=_cv2.LINE_AA)

        # ABSTRACT anodic BLOOMS: irregular many-sided corrosion patches eaten
        # into the metal, scattered through the anodic regions.
        n_bloom = int(np.clip(220 * (mn / 256.0) ** 2, 40, 700))
        bp = _pick(anod_pts, n_bloom)
        for cy0, cx0 in bp:
            cx0 = int(cx0); cy0 = int(cy0)
            rb = max(2, int(rng.uniform(4.0, 11.0) * s256))
            sides = int(rng.integers(6, 11))
            pts = []
            for k in range(sides):
                a = 2 * np.pi * k / sides + float(rng.uniform(-0.3, 0.3))
                rr = rb * float(rng.uniform(0.55, 1.25))   # ragged organic edge
                pts.append([int(cx0 + np.cos(a) * rr), int(cy0 + np.sin(a) * rr)])
            poly = np.asarray(pts, dtype=np.int32)
            _cv2.fillPoly(M, [poly], float(rng.uniform(0.10, 0.26)), lineType=_cv2.LINE_AA)
            _cv2.fillPoly(R, [poly], float(rng.uniform(0.74, 0.94)), lineType=_cv2.LINE_AA)
            _cv2.fillPoly(CC, [poly], float(rng.uniform(0.66, 0.90)), lineType=_cv2.LINE_AA)
            # bright crust ring around the bloom
            _cv2.polylines(M, [poly], True, float(rng.uniform(0.55, 0.85)), 1, lineType=_cv2.LINE_AA)

        # DENDRITIC corrosion fingers ramifying out from random bloom seeds.
        n_dend = int(np.clip(200 * (mn / 256.0) ** 2, 40, 600))
        dp = _pick(anod_pts, n_dend)
        for cy0, cx0 in dp:
            cx = int(cx0); cy = int(cy0)
            base_ang = float(rng.uniform(0, 2 * np.pi))
            dM = float(rng.uniform(0.08, 0.22)); dR = float(rng.uniform(0.72, 0.94)); dCC = float(rng.uniform(0.68, 0.90))
            for seg in range(3):
                L = float(rng.uniform(4.0, 9.0) * s256)
                ang = base_ang + float(rng.normal(0, 0.45))
                nx = int(cx + np.cos(ang) * L); ny = int(cy + np.sin(ang) * L)
                _cv2.line(M, (cx, cy), (nx, ny), dM, 1, lineType=_cv2.LINE_AA)
                _cv2.line(R, (cx, cy), (nx, ny), dR, 1, lineType=_cv2.LINE_AA)
                _cv2.line(CC, (cx, cy), (nx, ny), dCC, 1, lineType=_cv2.LINE_AA)
                if seg < 2 and rng.random() < 0.6:
                    bang = ang + float(rng.choice([-1.0, 1.0])) * float(rng.uniform(0.5, 1.1))
                    bL = float(rng.uniform(3.0, 6.0) * s256)
                    bx = int(cx + np.cos(bang) * bL); by_ = int(cy + np.sin(bang) * bL)
                    _cv2.line(M, (cx, cy), (bx, by_), dM, 1, lineType=_cv2.LINE_AA)
                    _cv2.line(R, (cx, cy), (bx, by_), dR, 1, lineType=_cv2.LINE_AA)
                cx, cy = nx, ny

        # Galvanic SPARK pinpoints scattered on the eaten edges (bright M).
        n_spark = int(np.clip(420 * (mn / 2048.0) ** 2, 140, 1100))
        sp = _pick(edge_pts, n_spark)
        for cy, cx in sp:
            r = max(1, int(rng.uniform(1.0, 2.0) * scale))
            _cv2.circle(M, (int(cx), int(cy)), r, float(rng.uniform(0.78, 0.98)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (int(cx), int(cy)), r, float(rng.uniform(0.04, 0.18)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (int(cx), int(cy)), r, float(rng.uniform(0.04, 0.18)), -1, lineType=_cv2.LINE_AA)

    # Fine pepper flecks on both sides
    n_fl = int(np.clip(1500 * (mn / 2048.0) ** 2, 500, 3800))
    fy = rng.integers(0, h, n_fl); fx = rng.integers(0, w, n_fl)
    M[fy, fx] = np.clip(M[fy, fx] + rng.uniform(-0.18, 0.18, n_fl).astype(np.float32), 0, 1)
    R[fy, fx] = np.clip(R[fy, fx] + rng.uniform(-0.15, 0.18, n_fl).astype(np.float32), 0, 1)
    CC[fy, fx] = np.clip(CC[fy, fx] + rng.uniform(-0.15, 0.15, n_fl).astype(np.float32), 0, 1)

    # R6-TICK56 NEW HERO â€” HYDROGEN-BUBBLE VEILS.
    # 4-9 cluster zones (12-22 px diam) of 8-22 micro hydrogen bubbles each,
    # sitting on the anodic surface as the reaction evolves gas. Each bubble
    # is a 1-2 px high-CC pinpoint with a tight subtle dark accumulation
    # ring â€” the visual signature of active electrochemistry.
    if _CV2_OK:
        n_veil = int(rng.integers(4, 10))
        for _ in range(n_veil):
            x_n = float(rng.uniform(0.06, 0.94))
            # Anchor veil somewhere on the anodic side
            y_n = float(rng.uniform(0.55, 0.95))
            vcx = int(x_n * (w - 1)); vcy = int(y_n * (h - 1))
            cluster_r = int(rng.uniform(12.0, 22.0) * scale)
            n_bub = int(rng.integers(8, 23))
            for _b in range(n_bub):
                ang = float(rng.uniform(0, 2 * np.pi))
                rad = float(rng.uniform(0, cluster_r))
                bx = int(np.clip(vcx + np.cos(ang) * rad, 0, w - 1))
                by = int(np.clip(vcy + np.sin(ang) * rad, 0, h - 1))
                br = max(1, int(rng.uniform(1.0, 2.2) * scale))
                # Bubble center â€” bright CC pinpoint
                _cv2.circle(M, (bx, by), br, float(rng.uniform(0.32, 0.55)), -1, lineType=_cv2.LINE_AA)
                _cv2.circle(R, (bx, by), br, float(rng.uniform(0.20, 0.40)), -1, lineType=_cv2.LINE_AA)
                _cv2.circle(CC, (bx, by), br, float(rng.uniform(0.82, 0.99)), -1, lineType=_cv2.LINE_AA)

    out = np.stack([M, R, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
spec_galvanic_corrosion._spb_concept_complete = True


def spec_stress_fractures(shape, seed, sm, num_seeds=8, crack_steps=120, **kwargs):
    """spec_stress_fractures.

    identity: R6 creative rebuild â€” a coating under structural failure,
    with HERO crater-impact starbursts as the headline read. Seven
    stacked tiers: (1) independent per-channel FBM substrate showing
    micro-stress haze, (2) 4-7 HERO impact CRATERS â€” large 16-26 px
    dark pits with a polished bright lip-rim AND 6-10 hairline petal
    cracks radiating 12-22 px out from each (independent M/R/CC per
    petal), (3) packed minor 3-5 ray STARBURSTS (8-16 px rays) across
    the canvas, (4) dense hairline FISSURE BED 5-14 px at random
    angles, (5) WANDERING crack walks â€” 3-pass random-walk fractures
    spanning 22-50 px with kinks, (6) 1-3 px dark stress NODES at
    branch points, (7) bare-substrate exposure flecks. Per-feature
    INDEPENDENT continuous M/R/CC across the widest gamut.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + (hash("spec_stress_fractures_r6") % 10000))
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)

    # 1) SUBSTRATE â€” independent FBM fields (stressed coating with subtle haze)
    bM = _normalize(multi_scale_noise(shape, [2.5, 6.0, 12.0, 22.0], [0.36, 0.30, 0.22, 0.12], int(seed) + 3401))
    bR = _normalize(multi_scale_noise(shape, [3.0, 7.0, 14.0, 24.0], [0.34, 0.30, 0.22, 0.14], int(seed) + 3402))
    bC = _normalize(multi_scale_noise(shape, [3.5, 8.0, 15.0, 26.0], [0.32, 0.28, 0.22, 0.18], int(seed) + 3403))
    M = (0.46 + (bM - 0.5) * 0.28).astype(np.float32)
    R = (0.52 + (bR - 0.5) * 0.30).astype(np.float32)
    CC = (0.42 + (bC - 0.5) * 0.30).astype(np.float32)

    if _CV2_OK:
        # 2) HERO IMPACT CRATERS â€” 4-7 large pits with polished rims + petal cracks
        n_crater = int(rng.integers(4, 8))
        for _ in range(n_crater):
            cx = float(rng.uniform(w * 0.10, w * 0.90))
            cy = float(rng.uniform(h * 0.10, h * 0.90))
            crater_r = int(max(8.0, rng.uniform(16.0, 26.0) * scale))
            # Bright lip rim
            _cv2.circle(M, (int(cx), int(cy)), crater_r,
                        float(rng.uniform(0.78, 0.98)), 2, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (int(cx), int(cy)), crater_r,
                        float(rng.uniform(0.08, 0.25)), 2, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (int(cx), int(cy)), crater_r,
                        float(rng.uniform(0.78, 0.98)), 2, lineType=_cv2.LINE_AA)
            # Dark pit core
            _cv2.circle(M, (int(cx), int(cy)), max(2, crater_r - 3),
                        float(rng.uniform(0.08, 0.22)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (int(cx), int(cy)), max(2, crater_r - 3),
                        float(rng.uniform(0.78, 0.96)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (int(cx), int(cy)), max(2, crater_r - 3),
                        float(rng.uniform(0.55, 0.85)), -1, lineType=_cv2.LINE_AA)
            # 6-10 petal hairline cracks radiating outward
            n_petal = int(rng.integers(6, 11))
            for pi in range(n_petal):
                pang = pi * (2 * np.pi / n_petal) + float(rng.uniform(-0.18, 0.18))
                pL = float(rng.uniform(12.0, 22.0)) * scale
                x0p = int(cx + np.cos(pang) * crater_r)
                y0p = int(cy + np.sin(pang) * crater_r)
                x1p = int(cx + np.cos(pang) * (crater_r + pL))
                y1p = int(cy + np.sin(pang) * (crater_r + pL))
                _cv2.line(M, (x0p, y0p), (x1p, y1p), float(rng.uniform(0.55, 0.95)), 1, lineType=_cv2.LINE_AA)
                _cv2.line(R, (x0p, y0p), (x1p, y1p), float(rng.uniform(0.20, 0.62)), 1, lineType=_cv2.LINE_AA)
                _cv2.line(CC, (x0p, y0p), (x1p, y1p), float(rng.uniform(0.18, 0.55)), 1, lineType=_cv2.LINE_AA)

        # 3) MINOR IMPACT STARBURSTS â€” 3-5 ray rosettes
        n_imp = int(np.clip(1200 * (mn / 2048.0) ** 2, 420, 3200))
        for _ in range(n_imp):
            ix = float(rng.uniform(6, w - 6)); iy = float(rng.uniform(6, h - 6))
            n_rays = int(rng.integers(3, 6))
            base_ang = float(rng.uniform(0, 2 * np.pi))
            iM = float(rng.uniform(0.55, 0.96))
            iR = float(rng.uniform(0.16, 0.58))
            iC = float(rng.uniform(0.10, 0.45))
            for ci in range(n_rays):
                ang = base_ang + ci * (2 * np.pi / n_rays) + float(rng.normal(0, 0.20))
                L = float(rng.uniform(8.0, 16.0)) * scale
                x2 = int(ix + np.cos(ang) * L); y2 = int(iy + np.sin(ang) * L)
                _cv2.line(M, (int(ix), int(iy)), (x2, y2), iM, 1, lineType=_cv2.LINE_AA)
                _cv2.line(R, (int(ix), int(iy)), (x2, y2), iR, 1, lineType=_cv2.LINE_AA)
                _cv2.line(CC, (int(ix), int(iy)), (x2, y2), iC, 1, lineType=_cv2.LINE_AA)
            _cv2.circle(M, (int(ix), int(iy)), max(1, int(1.5 * scale)),
                        float(rng.uniform(0.10, 0.32)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (int(ix), int(iy)), max(1, int(1.5 * scale)),
                        float(rng.uniform(0.72, 0.96)), -1, lineType=_cv2.LINE_AA)

        # 4) HAIRLINE FISSURE BED â€” dense 5-14 px standalone cracks
        n_fiss = int(np.clip(5000 * (mn / 2048.0) ** 2, 1800, 13000))
        for _ in range(n_fiss):
            cx = float(rng.uniform(2, w - 2)); cy = float(rng.uniform(2, h - 2))
            ang = float(rng.uniform(0, 2 * np.pi))
            L = float(rng.uniform(5.0, 14.0)) * scale
            x2 = int(cx + np.cos(ang) * L); y2 = int(cy + np.sin(ang) * L)
            _cv2.line(M, (int(cx), int(cy)), (x2, y2), float(rng.uniform(0.30, 0.92)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(R, (int(cx), int(cy)), (x2, y2), float(rng.uniform(0.20, 0.65)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (int(cx), int(cy)), (x2, y2), float(rng.uniform(0.12, 0.55)), 1, lineType=_cv2.LINE_AA)

        # 5) WANDERING KINKED CRACKS â€” 3-segment random walks 22-50 px total
        n_wander = int(np.clip(450 * (mn / 2048.0) ** 2, 160, 1200))
        for _ in range(n_wander):
            wx = float(rng.uniform(4, w - 4)); wy = float(rng.uniform(4, h - 4))
            wang = float(rng.uniform(0, 2 * np.pi))
            wM = float(rng.uniform(0.45, 0.92))
            wR = float(rng.uniform(0.20, 0.55))
            wC = float(rng.uniform(0.15, 0.50))
            for seg in range(3):
                segL = float(rng.uniform(7.0, 18.0)) * scale
                nx = wx + np.cos(wang) * segL; ny = wy + np.sin(wang) * segL
                _cv2.line(M, (int(wx), int(wy)), (int(nx), int(ny)), wM, 1, lineType=_cv2.LINE_AA)
                _cv2.line(R, (int(wx), int(wy)), (int(nx), int(ny)), wR, 1, lineType=_cv2.LINE_AA)
                _cv2.line(CC, (int(wx), int(wy)), (int(nx), int(ny)), wC, 1, lineType=_cv2.LINE_AA)
                wx, wy = nx, ny
                wang += float(rng.uniform(-0.9, 0.9))

        # 6) BRANCH STRESS NODES â€” small dark 1-3 px pits
        n_node = int(np.clip(3200 * (mn / 2048.0) ** 2, 1100, 8500))
        for _ in range(n_node):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            r = max(1, int(rng.uniform(1.0, 2.5) * scale))
            _cv2.circle(M, (cx, cy), r, float(rng.uniform(0.16, 0.42)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r, float(rng.uniform(0.70, 0.96)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r, float(rng.uniform(0.55, 0.90)), -1, lineType=_cv2.LINE_AA)

    # 7) BARE-SUBSTRATE EXPOSURE FLECKS
    n_fl = int(np.clip(3800 * (mn / 2048.0) ** 2, 1300, 9500))
    fx = rng.integers(0, w, n_fl); fy = rng.integers(0, h, n_fl)
    M[fy, fx] = np.maximum(M[fy, fx], rng.uniform(0.55, 0.97, n_fl).astype(np.float32))
    R[fy, fx] = np.minimum(R[fy, fx], rng.uniform(0.08, 0.42, n_fl).astype(np.float32))
    CC[fy, fx] = np.minimum(CC[fy, fx], rng.uniform(0.06, 0.38, n_fl).astype(np.float32))

    out = np.stack([M, R, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
spec_stress_fractures._spb_concept_complete = True


def spec_battle_scars(shape, seed, sm, num_scratches=18, scratch_length_frac=0.35, **kwargs):
    """spec_battle_scars â€” creative R6 rebuild with hero bullet craters.

    identity: War-damaged armor plate read at thumbnail. Independent
    per-channel FBM substrate (no flat ground). Stacked: radial-fan
    impact stars (dent + 4-6 fissures 12-22 px), skip-skid gouge clusters
    (3-5 parallels 8-20 px), blast pits with char wells + bright meniscus
    rim, shrapnel chips, pinpoint bare-metal flecks, AND new hero motifs:
    3-6 BULLET CRATERS â€” large dark char center, polished bright-metal
    crescent rim where steel peeled back, plus a halo of 8-14 hairline
    petal cracks radiating 8-16 px outward (independent M/R/CC per crack).
    Also: 2-4 BARBED-WIRE SNAG dragouts â€” long curving 20-40 px arcs that
    show a continuous bright drag of scratched paint. Widest per-feature
    chroma ranges.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 76251)
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)
    # 1) ARMOR SUBSTRATE â€” independent M/R/CC FBM fields
    base_M = _normalize(multi_scale_noise(shape, [3.0, 7.0, 14.0, 22.0], [0.36, 0.30, 0.22, 0.14], seed + 7625))
    base_R = _normalize(multi_scale_noise(shape, [4.0, 9.0, 18.0, 26.0], [0.32, 0.28, 0.22, 0.18], seed + 7626))
    base_CC = _normalize(multi_scale_noise(shape, [3.5, 8.0, 16.0, 24.0], [0.34, 0.30, 0.22, 0.14], seed + 7627))
    # R6-loop tick (owner 6/KEEP refinement): substrate dimmed so mean M stays
    # â‰¤0.40 cap; armor reads as darker dirty steel before features paint over.
    M = (0.32 + (base_M - 0.5) * 0.26).astype(np.float32)
    R = (0.52 + (base_R - 0.5) * 0.32).astype(np.float32)
    CC = (0.44 + (base_CC - 0.5) * 0.28).astype(np.float32)
    for arr in (M, R, CC):
        mlo = rng.random(arr.shape) < 0.055
        mhi = rng.random(arr.shape) < 0.055
        arr[mlo] = float(rng.uniform(0.05, 0.18))
        arr[mhi] = float(rng.uniform(0.82, 0.97))
    if _CV2_OK:
        # 2) RADIAL-FAN IMPACT STARS â€” dent + 4-6 outward fissures
        n_star = int(np.clip(210 * (mn / 2048.0) ** 2, 70, 490))
        for _ in range(n_star):
            cx = float(rng.uniform(20, w - 20)); cy = float(rng.uniform(20, h - 20))
            r_dent = max(3, int(rng.uniform(5, 9) * scale))
            dM = float(rng.uniform(0.08, 0.28)); dR = float(rng.uniform(0.62, 0.92)); dCC = float(rng.uniform(0.50, 0.88))
            _cv2.circle(M, (int(cx), int(cy)), r_dent, dM, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (int(cx), int(cy)), r_dent, dR, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (int(cx), int(cy)), r_dent, dCC, -1, lineType=_cv2.LINE_AA)
            n_rays = int(rng.integers(4, 7))
            for i in range(n_rays):
                ang = (i / n_rays) * 2 * np.pi + float(rng.uniform(-0.20, 0.20))
                length = float(rng.uniform(12.0, 22.0) * scale)
                x1 = int(cx + np.cos(ang) * length); y1 = int(cy + np.sin(ang) * length)
                fM = float(rng.uniform(0.20, 0.55)); fR = float(rng.uniform(0.62, 0.95)); fCC = float(rng.uniform(0.40, 0.90))
                _cv2.line(M, (int(cx), int(cy)), (x1, y1), fM, 1, lineType=_cv2.LINE_AA)
                _cv2.line(R, (int(cx), int(cy)), (x1, y1), fR, 1, lineType=_cv2.LINE_AA)
                _cv2.line(CC, (int(cx), int(cy)), (x1, y1), fCC, 1, lineType=_cv2.LINE_AA)
        # 3) SKIP-SKID GOUGE CLUSTERS â€” 3-5 parallel streaks at matched angle
        n_cluster = int(np.clip(280 * (mn / 2048.0) ** 2, 100, 670))
        for _ in range(n_cluster):
            cx = float(rng.uniform(15, w - 15)); cy = float(rng.uniform(15, h - 15))
            ang = float(rng.uniform(0, 2 * np.pi))
            perp = ang + np.pi * 0.5
            n_par = int(rng.integers(3, 6))
            length = float(rng.uniform(8.0, 20.0) * scale)
            for k in range(n_par):
                off = (k - n_par * 0.5) * float(rng.uniform(2.5, 5.0))
                ox = cx + np.cos(perp) * off; oy = cy + np.sin(perp) * off
                x0 = int(ox - np.cos(ang) * length * 0.5); y0 = int(oy - np.sin(ang) * length * 0.5)
                x1 = int(ox + np.cos(ang) * length * 0.5); y1 = int(oy + np.sin(ang) * length * 0.5)
                gM = float(rng.uniform(0.65, 0.96)); gR = float(rng.uniform(0.12, 0.38)); gCC = float(rng.uniform(0.55, 0.92))
                _cv2.line(M, (x0, y0), (x1, y1), gM, 1, lineType=_cv2.LINE_AA)
                _cv2.line(R, (x0, y0), (x1, y1), gR, 1, lineType=_cv2.LINE_AA)
                _cv2.line(CC, (x0, y0), (x1, y1), gCC, 1, lineType=_cv2.LINE_AA)
        # 4) BLAST PITS â€” 6-12 px char wells with bright rim
        n_pit = int(np.clip(310 * (mn / 2048.0) ** 2, 110, 730))
        for _ in range(n_pit):
            cx = int(rng.uniform(10, w - 10)); cy = int(rng.uniform(10, h - 10))
            r = int(max(3, rng.uniform(6, 12) * scale * 0.5))
            # char well
            wM = float(rng.uniform(0.05, 0.18)); wR = float(rng.uniform(0.78, 0.97)); wCC = float(rng.uniform(0.60, 0.92))
            _cv2.circle(M, (cx, cy), r, wM, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r, wR, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r, wCC, -1, lineType=_cv2.LINE_AA)
            # bright meniscus rim
            rM = float(rng.uniform(0.70, 0.96)); rR = float(rng.uniform(0.10, 0.32)); rCC = float(rng.uniform(0.08, 0.30))
            _cv2.circle(M, (cx, cy), r, rM, 1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r, rR, 1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r, rCC, 1, lineType=_cv2.LINE_AA)
        # 5) SHRAPNEL CHIPS (3-6 px) â€” irregular bright bare-metal flakes
        n_chip = int(np.clip(1260 * (mn / 2048.0) ** 2, 450, 3080))
        for _ in range(n_chip):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            r = max(1, int(rng.uniform(3.0, 6.0) * scale * 0.5))
            cM = float(rng.uniform(0.62, 0.96)); cR = float(rng.uniform(0.10, 0.35)); cCC = float(rng.uniform(0.60, 0.95))
            _cv2.circle(M, (cx, cy), r, cM, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r, cR, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r, cCC, -1, lineType=_cv2.LINE_AA)
        # 6) HERO MOTIF â€” BULLET CRATERS (3-6) with crescent rim + petal cracks
        n_crater = int(rng.integers(3, 7))
        for _ in range(n_crater):
            ccx = int(rng.uniform(18, w - 18)); ccy = int(rng.uniform(18, h - 18))
            r_core = max(3, int(rng.uniform(6.0, 11.0) * scale))
            # dark char center
            _cv2.circle(M, (ccx, ccy), r_core, float(rng.uniform(0.05, 0.16)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (ccx, ccy), r_core, float(rng.uniform(0.80, 0.97)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (ccx, ccy), r_core, float(rng.uniform(0.55, 0.92)), -1, lineType=_cv2.LINE_AA)
            # polished bright-metal crescent rim (arc on one side)
            rim_ang = float(rng.uniform(0, 360))
            rim_sweep = float(rng.uniform(80, 180))
            _cv2.ellipse(M, (ccx, ccy), (r_core + 2, r_core + 2), 0.0, rim_ang, rim_ang + rim_sweep,
                         float(rng.uniform(0.80, 0.98)), 2, lineType=_cv2.LINE_AA)
            _cv2.ellipse(R, (ccx, ccy), (r_core + 2, r_core + 2), 0.0, rim_ang, rim_ang + rim_sweep,
                         float(rng.uniform(0.05, 0.20)), 2, lineType=_cv2.LINE_AA)
            _cv2.ellipse(CC, (ccx, ccy), (r_core + 2, r_core + 2), 0.0, rim_ang, rim_ang + rim_sweep,
                         float(rng.uniform(0.04, 0.22)), 2, lineType=_cv2.LINE_AA)
            # petal cracks 8-14 radiating outward 8-16 px
            n_petal = int(rng.integers(8, 15))
            for k in range(n_petal):
                pang = (k / n_petal) * 2 * np.pi + float(rng.uniform(-0.18, 0.18))
                plen = float(rng.uniform(8.0, 16.0) * scale)
                px2 = int(np.clip(ccx + np.cos(pang) * (r_core + plen), 0, w - 1))
                py2 = int(np.clip(ccy + np.sin(pang) * (r_core + plen), 0, h - 1))
                px1 = int(np.clip(ccx + np.cos(pang) * r_core, 0, w - 1))
                py1 = int(np.clip(ccy + np.sin(pang) * r_core, 0, h - 1))
                _cv2.line(M, (px1, py1), (px2, py2), float(rng.uniform(0.18, 0.55)), 1, lineType=_cv2.LINE_AA)
                _cv2.line(R, (px1, py1), (px2, py2), float(rng.uniform(0.65, 0.95)), 1, lineType=_cv2.LINE_AA)
                _cv2.line(CC, (px1, py1), (px2, py2), float(rng.uniform(0.20, 0.85)), 1, lineType=_cv2.LINE_AA)
        # 7) HERO MOTIF â€” BARBED-WIRE SNAG DRAGOUTS (2-4 long curving arcs)
        n_snag = int(rng.integers(2, 5))
        for _ in range(n_snag):
            scx = int(rng.uniform(8, w - 8)); scy = int(rng.uniform(8, h - 8))
            arc_r = max(8, int(rng.uniform(20.0, 40.0) * scale))
            a0 = float(rng.uniform(0, 360)); sweep = float(rng.uniform(35, 90))
            _cv2.ellipse(M, (scx, scy), (arc_r, arc_r), 0.0, a0, a0 + sweep,
                         float(rng.uniform(0.78, 0.98)), 1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(R, (scx, scy), (arc_r, arc_r), 0.0, a0, a0 + sweep,
                         float(rng.uniform(0.05, 0.22)), 1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(CC, (scx, scy), (arc_r, arc_r), 0.0, a0, a0 + sweep,
                         float(rng.uniform(0.10, 0.45)), 1, lineType=_cv2.LINE_AA)
            # bright snag-points (3-5 along the arc)
            n_snag_pt = int(rng.integers(3, 6))
            for kk in range(n_snag_pt):
                pa = np.deg2rad(a0 + sweep * (kk + 0.5) / n_snag_pt)
                sx = int(np.clip(scx + np.cos(pa) * arc_r, 0, w - 1))
                sy = int(np.clip(scy + np.sin(pa) * arc_r, 0, h - 1))
                _cv2.circle(M, (sx, sy), max(1, int(scale * 1.6)),
                            float(rng.uniform(0.85, 0.99)), -1, lineType=_cv2.LINE_AA)
    # 8) BARE-METAL FLECKS â€” pinpoint exposures
    n_flecks = int(np.clip(2300 * (mn / 2048.0) ** 2, 800, 5200))
    fx = rng.integers(0, w, n_flecks); fy = rng.integers(0, h, n_flecks)
    M[fy, fx] = np.maximum(M[fy, fx], rng.uniform(0.55, 0.98, n_flecks).astype(np.float32))
    R[fy, fx] = np.minimum(R[fy, fx], rng.uniform(0.06, 0.30, n_flecks).astype(np.float32))
    CC[fy, fx] = rng.uniform(0.06, 0.95, n_flecks).astype(np.float32)
    out = np.stack([M, R, CC], axis=-1).astype(np.float32)
    return _validate_spec_output(_sm_scale(np.clip(out, 0.0, 1.0), sm).astype(np.float32), "spec_battle_scars")
spec_battle_scars._spb_concept_complete = True


def spec_worn_edges(shape, seed, sm, num_contours=25, contour_noise=0.04, **kwargs):
    """spec_worn_edges.

    identity (R6 creative rebuild): a vintage panel where wear concentrates near
    edges but spreads convincingly into the interior. SIGNATURE differentiators:
    (a) STRESS-CRACK NETWORKS radiating inward from corners, and (b) PAINT
    BUBBLE-FLAKES â€” small dome-rings of lifted paint clusters near the edges.
    Layered stack: (1) chalky aged-paint FBM substrate with edge halo,
    (2) STRESS-CRACK BRANCHES from each of the 4 corners â€” thin polyline
    crack networks reaching ~30% into the canvas, (3) dense 2-5 px chip
    recesses with bright sub-rim halo (edge-biased), (4) bare-metal exposure
    dots 3-6 px, (5) BUBBLE-FLAKE RINGS â€” small 4-7 px hollow circle rings
    showing lifted-paint domes (NEW), (6) handling scratches 6-14 px,
    (7) mid-tone dust flecks 1-3 px, (8) accent specks. Per-feature INDEPENDENT
    continuous M/R/CC.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 76421)
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)

    # 1) SUBSTRATE â€” aged-paint FBM with subtle edge halo (independent per channel)
    bM = _normalize(multi_scale_noise(shape, [2.5, 6.0, 12.0, 22.0], [0.36, 0.30, 0.22, 0.12], int(seed) + 7641))
    bR = _normalize(multi_scale_noise(shape, [3.0, 7.0, 14.0, 24.0], [0.34, 0.30, 0.22, 0.14], int(seed) + 7643))
    bC = _normalize(multi_scale_noise(shape, [3.5, 8.0, 15.0, 26.0], [0.32, 0.28, 0.22, 0.18], int(seed) + 7645))
    yy, xx = np.mgrid[0:h, 0:w].astype(np.float32)
    edge_arr = np.minimum.reduce([yy, xx, h - 1 - yy, w - 1 - xx])
    edge_mask = np.exp(-edge_arr / max(18.0, mn / 14.0)).astype(np.float32)

    M = (0.34 + (bM - 0.5) * 0.18 + edge_mask * 0.16).astype(np.float32)
    R = (0.56 + (bR - 0.5) * 0.22 + edge_mask * 0.12).astype(np.float32)
    CC = (0.50 + (bC - 0.5) * 0.22 - edge_mask * 0.18).astype(np.float32)

    # Edge-bias sampler used to skew density toward borders WITHOUT clipping the interior
    def _sample_n(n_total, edge_bias=0.55):
        # Edge bias: edge_bias fraction of samples drawn near border, rest uniform full canvas
        n_edge = int(n_total * edge_bias)
        n_full = n_total - n_edge
        ex = np.empty(n_total, dtype=np.int32); ey = np.empty(n_total, dtype=np.int32)
        # Edge samples: pick a side then a thin strip
        sides = rng.integers(0, 4, n_edge)
        strip = max(4, mn // 10)
        for i in range(n_edge):
            s = int(sides[i])
            if s == 0:
                ex[i] = int(rng.integers(0, w)); ey[i] = int(rng.integers(0, strip))
            elif s == 1:
                ex[i] = int(rng.integers(0, w)); ey[i] = int(rng.integers(max(1, h - strip), h))
            elif s == 2:
                ex[i] = int(rng.integers(0, strip)); ey[i] = int(rng.integers(0, h))
            else:
                ex[i] = int(rng.integers(max(1, w - strip), w)); ey[i] = int(rng.integers(0, h))
        # Full canvas samples
        ex[n_edge:] = rng.integers(0, w, n_full)
        ey[n_edge:] = rng.integers(0, h, n_full)
        return ex, ey

    if _CV2_OK:
        # 2) STRESS-CRACK BRANCHES from corners (NEW)
        corners = [(0, 0), (w - 1, 0), (0, h - 1), (w - 1, h - 1)]
        for cx0, cy0 in corners:
            n_cracks = int(rng.integers(8, 14))
            for _ in range(n_cracks):
                # Direction: from corner into interior
                if cx0 == 0 and cy0 == 0: ang0 = float(rng.uniform(0.05, np.pi/2 - 0.05))
                elif cx0 == w - 1 and cy0 == 0: ang0 = float(rng.uniform(np.pi/2 + 0.05, np.pi - 0.05))
                elif cx0 == 0 and cy0 == h - 1: ang0 = float(rng.uniform(-np.pi/2 + 0.05, -0.05))
                else: ang0 = float(rng.uniform(np.pi + 0.05, 3*np.pi/2 - 0.05))
                x, y = float(cx0), float(cy0)
                ang = ang0
                steps = int(rng.integers(8, 22))
                step_len = max(2.0, 2.5 * scale)
                for _ in range(steps):
                    ang = ang + float(rng.normal(0, 0.22))
                    x2 = x + np.cos(ang) * step_len; y2 = y + np.sin(ang) * step_len
                    if not (0 <= x2 < w and 0 <= y2 < h): break
                    _cv2.line(M, (int(x), int(y)), (int(x2), int(y2)), float(rng.uniform(0.08, 0.28)), 1, lineType=_cv2.LINE_AA)
                    _cv2.line(R, (int(x), int(y)), (int(x2), int(y2)), float(rng.uniform(0.62, 0.92)), 1, lineType=_cv2.LINE_AA)
                    _cv2.line(CC, (int(x), int(y)), (int(x2), int(y2)), float(rng.uniform(0.55, 0.85)), 1, lineType=_cv2.LINE_AA)
                    # Occasional sub-branch
                    if rng.random() < 0.22:
                        sa = ang + float(rng.uniform(-0.9, 0.9))
                        sx2 = x2 + np.cos(sa) * step_len * 1.4
                        sy2 = y2 + np.sin(sa) * step_len * 1.4
                        if 0 <= sx2 < w and 0 <= sy2 < h:
                            _cv2.line(M, (int(x2), int(y2)), (int(sx2), int(sy2)), float(rng.uniform(0.10, 0.30)), 1, lineType=_cv2.LINE_AA)
                            _cv2.line(R, (int(x2), int(y2)), (int(sx2), int(sy2)), float(rng.uniform(0.60, 0.90)), 1, lineType=_cv2.LINE_AA)
                    x, y = x2, y2

        # 3) CHIP RECESSES â€” 5x density, dark 2-5 px pits with bright sub-rim
        n_chip = int(np.clip(5500 * (mn / 2048.0) ** 2, 2000, 14000))
        cx_arr, cy_arr = _sample_n(n_chip, edge_bias=0.55)
        for i in range(n_chip):
            cx = int(cx_arr[i]); cy = int(cy_arr[i])
            r_s = max(1, int(rng.uniform(1.6, 3.2) * scale))
            _cv2.circle(M, (cx, cy), r_s, float(rng.uniform(0.06, 0.22)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r_s, float(rng.uniform(0.62, 0.92)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r_s, float(rng.uniform(0.55, 0.88)), -1, lineType=_cv2.LINE_AA)
            # Bright sub-rim halo
            _cv2.circle(M, (cx, cy), r_s + 1, float(rng.uniform(0.55, 0.88)), 1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r_s + 1, float(rng.uniform(0.18, 0.42)), 1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r_s + 1, float(rng.uniform(0.20, 0.55)), 1, lineType=_cv2.LINE_AA)

        # 3b) BUBBLE-FLAKE RINGS â€” lifted dome rings 4-7 px, edge-biased (NEW)
        n_bub = int(np.clip(900 * (mn / 2048.0) ** 2, 320, 2600))
        bx_arr, by_arr = _sample_n(n_bub, edge_bias=0.50)
        for i in range(n_bub):
            cx = int(bx_arr[i]); cy = int(by_arr[i])
            rr = max(2, int(rng.uniform(2.0, 3.5) * scale))
            _cv2.circle(M, (cx, cy), rr, float(rng.uniform(0.42, 0.78)), 1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), rr, float(rng.uniform(0.18, 0.45)), 1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), rr, float(rng.uniform(0.22, 0.55)), 1, lineType=_cv2.LINE_AA)
            # interior dome highlight (1 px)
            _cv2.circle(M, (cx, cy), max(1, rr - 2), float(rng.uniform(0.55, 0.92)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), max(1, rr - 2), float(rng.uniform(0.12, 0.34)), -1, lineType=_cv2.LINE_AA)

        # 3) BARE-METAL EXPOSURES â€” bright 3-6 px (5x density)
        n_hi = int(np.clip(3500 * (mn / 2048.0) ** 2, 1200, 9000))
        hx, hy = _sample_n(n_hi, edge_bias=0.45)
        for i in range(n_hi):
            cx = int(hx[i]); cy = int(hy[i])
            r_s = max(1, int(rng.uniform(2.0, 4.0) * scale))
            _cv2.circle(M, (cx, cy), r_s, float(rng.uniform(0.72, 0.98)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r_s, float(rng.uniform(0.06, 0.26)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r_s, float(rng.uniform(0.08, 0.40)), -1, lineType=_cv2.LINE_AA)

        # 4) HANDLING SCRATCHES â€” 6-14 px short hairlines (denser)
        n_scr = int(np.clip(3000 * (mn / 2048.0) ** 2, 1100, 8000))
        scratch_ang_base = float(rng.uniform(-0.30, 0.30))
        for _ in range(n_scr):
            cx = float(rng.uniform(2, w - 2)); cy = float(rng.uniform(2, h - 2))
            L = float(rng.uniform(6.0, 14.0)) * scale
            A = scratch_ang_base + float(rng.uniform(-0.18, 0.18))
            x0 = int(cx - np.cos(A) * L * 0.5); y0 = int(cy - np.sin(A) * L * 0.5)
            x1 = int(cx + np.cos(A) * L * 0.5); y1 = int(cy + np.sin(A) * L * 0.5)
            _cv2.line(M, (x0, y0), (x1, y1), float(rng.uniform(0.42, 0.90)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(R, (x0, y0), (x1, y1), float(rng.uniform(0.14, 0.42)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (x0, y0), (x1, y1), float(rng.uniform(0.18, 0.62)), 1, lineType=_cv2.LINE_AA)

        # 5) MID-TONE DUST FLECKS â€” 1-3 px dense
        n_md = int(np.clip(3000 * (mn / 2048.0) ** 2, 1000, 8000))
        for _ in range(n_md):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            r_s = max(1, int(rng.uniform(1.0, 2.0) * scale))
            _cv2.circle(M, (cx, cy), r_s, float(rng.uniform(0.18, 0.52)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r_s, float(rng.uniform(0.32, 0.68)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r_s, float(rng.uniform(0.28, 0.72)), -1, lineType=_cv2.LINE_AA)

    # 6) ACCENT SPECKS â€” dense single-pixel
    n_fl = int(np.clip(4000 * (mn / 2048.0) ** 2, 1400, 10000))
    fy = rng.integers(0, h, n_fl); fx = rng.integers(0, w, n_fl)
    M[fy, fx] = np.maximum(M[fy, fx], rng.uniform(0.42, 0.92, n_fl).astype(np.float32))
    R[fy, fx] = np.minimum(R[fy, fx], rng.uniform(0.08, 0.38, n_fl).astype(np.float32))
    CC[fy, fx] = np.maximum(CC[fy, fx], rng.uniform(0.18, 0.78, n_fl).astype(np.float32))

    out = np.stack([np.clip(M, 0, 1), np.clip(R, 0, 1), np.clip(CC, 0, 1)], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
spec_worn_edges._spb_concept_complete = True


def spec_peeling_clear(shape, seed, sm, **kwargs):
    """spec_peeling_clear.

    identity: R6-creative rebuild â€” Sun-baked clearcoat lifting off the panel
    with theatrical detail. Stacked hero motifs: (1) Voronoi-like crack
    network from low-freq gradient field, dividing into 12-22 px island
    flakes with dark sharp crack seams, (2) CURLED-CORNER bright crescent
    lifts on every island (chevron pair lit on the up-curve, shadowed under-
    side), (3) UV-AGED amber crust patches â€” small 6-10 px yellow-tinted
    plateaus where the clear has cooked, (4) ripped UNDERLAYMENT exposure
    dots (2-5 px bare-basecoat bright spots), (5) dense hairline crazing
    network (4-12 px), (6) tiny bubble ring-stamps (3-6 px), (7) micro
    fleck carpet for full coverage. Per-feature INDEPENDENT continuous
    M/R/CC across wide ranges so the canvas is a chroma-rich storm.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 76721)
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)

    # 1) BASE â€” aged paint substrate
    g1 = _normalize(multi_scale_noise(shape, [2.5, 6.5, 14.0, 26.0], [0.34, 0.30, 0.22, 0.14], int(seed) + 76772))
    g2 = _normalize(multi_scale_noise(shape, [3.0, 7.0, 15.0, 28.0], [0.34, 0.30, 0.22, 0.14], int(seed) + 76773))
    g3 = _normalize(multi_scale_noise(shape, [2.0, 5.5, 12.0, 24.0], [0.34, 0.30, 0.22, 0.14], int(seed) + 76774))
    M  = (0.48 + (g1 - 0.5) * 0.24).astype(np.float32)
    R  = (0.42 + (g2 - 0.5) * 0.22).astype(np.float32)
    CC = (0.30 + (g3 - 0.5) * 0.20).astype(np.float32)

    # 2) CRACK NETWORK â€” derived from low-freq noise, splits canvas into islands
    crack_noise = _normalize(multi_scale_noise(shape, [12.0, 22.0], [0.6, 0.4], int(seed) + 76775))
    # gradient magnitude of the noise -> crack lines
    gy = np.zeros_like(crack_noise); gx = np.zeros_like(crack_noise)
    gy[1:, :] = np.abs(crack_noise[1:, :] - crack_noise[:-1, :])
    gx[:, 1:] = np.abs(crack_noise[:, 1:] - crack_noise[:, :-1])
    crack = np.clip((gy + gx) * 18.0, 0, 1).astype(np.float32)
    # Crack seams are dark + dull + high CC
    M  = np.clip(M  - crack * 0.30, 0, 1)
    R  = np.clip(R  + crack * 0.32, 0, 1)
    CC = np.clip(CC + crack * 0.42, 0, 1)

    if _CV2_OK:
        # 3) CORNER-LIFTED FLAKE EDGES â€” bright crescent arcs along island borders (8-16 px)
        n_lift = int(np.clip(4400 * (mn / 2048.0) ** 2, 1400, 9200))
        for _ in range(n_lift):
            cx = float(rng.uniform(6, w - 6)); cy = float(rng.uniform(6, h - 6))
            length = float(rng.uniform(8.0, 16.0) * scale)
            ang = float(rng.uniform(0, 2 * np.pi))
            # Two-segment chevron (lifted corner)
            x_m = int(cx); y_m = int(cy)
            x_a = int(cx + np.cos(ang) * length * 0.5)
            y_a = int(cy + np.sin(ang) * length * 0.5)
            x_b = int(cx + np.cos(ang + 1.3) * length * 0.5)
            y_b = int(cy + np.sin(ang + 1.3) * length * 0.5)
            eM = float(rng.uniform(0.66, 0.96))
            eR = float(rng.uniform(0.08, 0.30))
            eCC = float(rng.uniform(0.05, 0.24))
            for (xa, ya, xb, yb) in [(x_a, y_a, x_m, y_m), (x_m, y_m, x_b, y_b)]:
                _cv2.line(M, (xa, ya), (xb, yb), eM, 1, lineType=_cv2.LINE_AA)
                _cv2.line(R, (xa, ya), (xb, yb), eR, 1, lineType=_cv2.LINE_AA)
                _cv2.line(CC, (xa, ya), (xb, yb), eCC, 1, lineType=_cv2.LINE_AA)

        # 4) DENSE HAIRLINE CRAZING â€” short cracks fanning out (4-12 px)
        n_cracks = int(np.clip(3200 * (mn / 2048.0) ** 2, 1000, 7200))
        for _ in range(n_cracks):
            cx = rng.uniform(2, w - 2); cy = rng.uniform(2, h - 2)
            length = rng.uniform(4.0, 12.0) * scale
            ang = rng.uniform(0, 2 * np.pi)
            x2 = int(np.clip(cx + np.cos(ang) * length, 0, w - 1))
            y2 = int(np.clip(cy + np.sin(ang) * length, 0, h - 1))
            mM = float(rng.uniform(0.06, 0.24))
            mR = float(rng.uniform(0.66, 0.92))
            mCC = float(rng.uniform(0.55, 0.90))
            _cv2.line(M, (int(cx), int(cy)), (x2, y2), mM, 1, lineType=_cv2.LINE_AA)
            _cv2.line(R, (int(cx), int(cy)), (x2, y2), mR, 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (int(cx), int(cy)), (x2, y2), mCC, 1, lineType=_cv2.LINE_AA)

        # 4b) UV-AGED AMBER CRUST PATCHES â€” 6-10 px yellow-tinted plateaus
        n_amber = int(np.clip(1800 * (mn / 2048.0) ** 2, 600, 4800))
        for _ in range(n_amber):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            rx = max(2, int(rng.uniform(3.0, 5.0) * scale))
            ry = max(2, int(rng.uniform(2.5, 4.5) * scale))
            ang = float(rng.uniform(0, 180))
            # amber = warm CC chroma, mid M, raised R
            aM = float(rng.uniform(0.42, 0.72))
            aR = float(rng.uniform(0.55, 0.82))
            aCC = float(rng.uniform(0.50, 0.85))
            _cv2.ellipse(M, (cx, cy), (rx, ry), ang, 0, 360, aM, -1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(R, (cx, cy), (rx, ry), ang, 0, 360, aR, -1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(CC, (cx, cy), (rx, ry), ang, 0, 360, aCC, -1, lineType=_cv2.LINE_AA)

        # 5) TINY BUBBLE RING-STAMPS (3-6 px circles, not filled)
        n_bub = int(np.clip(2400 * (mn / 2048.0) ** 2, 800, 5600))
        for _ in range(n_bub):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            r_b = max(2, int(rng.uniform(3.0, 6.0) * scale))
            bM = float(rng.uniform(0.30, 0.72))
            bR = float(rng.uniform(0.16, 0.55))
            bCC = float(rng.uniform(0.18, 0.65))
            _cv2.circle(M, (cx, cy), r_b, bM, 1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r_b, bR, 1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r_b, bCC, 1, lineType=_cv2.LINE_AA)

        # 5b) CURLED-CORNER SHADOW UNDERSIDES â€” short dark hairlines pairing lifts
        n_shadow = int(np.clip(2200 * (mn / 2048.0) ** 2, 700, 5500))
        for _ in range(n_shadow):
            cx = float(rng.uniform(4, w - 4)); cy = float(rng.uniform(4, h - 4))
            length = float(rng.uniform(4.0, 9.0) * scale)
            ang = float(rng.uniform(0, 2 * np.pi))
            x0 = int(cx); y0 = int(cy)
            x1 = int(cx + np.cos(ang) * length)
            y1 = int(cy + np.sin(ang) * length)
            sM = float(rng.uniform(0.10, 0.28))
            sR = float(rng.uniform(0.60, 0.88))
            sCC = float(rng.uniform(0.55, 0.85))
            _cv2.line(M, (x0, y0), (x1, y1), sM, 1, lineType=_cv2.LINE_AA)
            _cv2.line(R, (x0, y0), (x1, y1), sR, 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (x0, y0), (x1, y1), sCC, 1, lineType=_cv2.LINE_AA)

        # 6) BARE-BASECOAT EXPOSURE PATCHES â€” small bright spots where clear ripped off (2-5 px)
        n_bare = int(np.clip(2800 * (mn / 2048.0) ** 2, 900, 6400))
        for _ in range(n_bare):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            r = max(1, int(rng.uniform(2.0, 5.0) * scale * 0.5))
            xM = float(rng.uniform(0.58, 0.92))
            xR = float(rng.uniform(0.45, 0.78))
            xCC = float(rng.uniform(0.72, 0.97))
            _cv2.circle(M, (cx, cy), r, xM, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r, xR, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r, xCC, -1, lineType=_cv2.LINE_AA)

    # 7) BRIGHT FLECK CARPET â€” full canvas coverage
    n_fl = int(np.clip(mn * mn / 80.0, 2400, 10000))
    fx = rng.integers(0, w, n_fl); fy = rng.integers(0, h, n_fl)
    M[fy, fx] = np.maximum(M[fy, fx], rng.uniform(0.50, 0.95, n_fl).astype(np.float32))
    R[fy, fx] = np.minimum(R[fy, fx], rng.uniform(0.10, 0.40, n_fl).astype(np.float32))
    CC[fy, fx] = np.minimum(CC[fy, fx], rng.uniform(0.05, 0.30, n_fl).astype(np.float32))

    out = np.stack([M, R, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
spec_peeling_clear._spb_concept_complete = True


def spec_sandblast_strip(shape, seed, sm, blob_octaves=4, blob_freq=2.5, **kwargs):
    """spec_sandblast_strip.

    identity: R6-creative rebuild â€” A sandblast-stripped panel showing the
    nozzle operator's working pattern. Stacked motifs: (1) dominant
    diagonal nozzle-pass STRIPE field (~9-14 px pitch), (2) fully saturated
    fine impact-grit carpet (1-3 px pits, dark M dull R), (3) abrasive
    SCUFF STREAKS along stripe angle (4-10 px), (4) cross-hatch GRIT
    CLUSTERS â€” tiny 6-9 dot rosette stamps where nozzle paused (8-12 px
    overall footprint), (5) NOZZLE-ARC STRIKE crescents 8-14 px where the
    blast turned, (6) cross-cut chips perpendicular to stripe direction
    (5-12 px), (7) bare-metal sparkle fleck carpet for full coverage. Per-
    feature INDEPENDENT continuous M/R/CC. No panel-scale features.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 76920)
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)

    # 1) BASE â€” independent M/R/CC FBM (rough bare-metal substrate)
    g1 = _normalize(multi_scale_noise(shape, [2.0, 5.5, 13.0, 24.0], [0.36, 0.30, 0.20, 0.14], int(seed) + 7691))
    g2 = _normalize(multi_scale_noise(shape, [2.5, 6.5, 14.0, 26.0], [0.34, 0.30, 0.22, 0.14], int(seed) + 7693))
    g3 = _normalize(multi_scale_noise(shape, [3.0, 7.5, 15.5, 28.0], [0.32, 0.28, 0.22, 0.18], int(seed) + 7695))

    # 2) DIAGONAL NOZZLE-PASS STRIPE FIELD â€” the "strip" identity
    yy = np.arange(h, dtype=np.float32)[:, None]
    xx = np.arange(w, dtype=np.float32)[None, :]
    base_ang = float(rng.uniform(np.pi * 0.18, np.pi * 0.32))  # consistent diagonal
    proj = xx * np.cos(base_ang) + yy * np.sin(base_ang)
    stripe_pitch = max(11.0, float(min(h, w)) / 28.0)  # ~9-14 px stripe pitch
    stripe = (np.sin(proj * (2.0 * np.pi / stripe_pitch)) * 0.5 + 0.5).astype(np.float32)
    stripe_mod = stripe * 0.18

    M  = np.clip(0.62 + (g1 - 0.5) * 0.20 + stripe_mod, 0.0, 1.0).astype(np.float32)
    R  = np.clip(0.74 + (g2 - 0.5) * 0.22 - stripe_mod * 0.6, 0.0, 1.0).astype(np.float32)
    CC = np.clip(0.74 + (g3 - 0.5) * 0.20 + stripe_mod * 0.4, 0.0, 1.0).astype(np.float32)

    if _CV2_OK:
        # 3) FINE GRIT PITS â€” 5x prior density, 1-3 px dark impact craters everywhere
        n_grit = int(np.clip(4800 * (mn / 2048.0) ** 2, 1800, 12000))
        gx = rng.integers(0, w, n_grit); gy = rng.integers(0, h, n_grit)
        gr = np.maximum(1, (rng.uniform(0.9, 2.6, n_grit) * scale).astype(np.int32))
        gM = rng.uniform(0.18, 0.50, n_grit).astype(np.float32)
        gR = rng.uniform(0.78, 0.98, n_grit).astype(np.float32)
        gC = rng.uniform(0.68, 0.96, n_grit).astype(np.float32)
        for i in range(n_grit):
            _cv2.circle(M, (int(gx[i]), int(gy[i])), int(gr[i]), float(gM[i]), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (int(gx[i]), int(gy[i])), int(gr[i]), float(gR[i]), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (int(gx[i]), int(gy[i])), int(gr[i]), float(gC[i]), -1, lineType=_cv2.LINE_AA)

        # 4) ABRASIVE SCUFF STREAKS â€” short 4-10 px sweeps aligned with nozzle pass
        n_streak = int(np.clip(2400 * (mn / 2048.0) ** 2, 900, 6500))
        sx = rng.uniform(2, w - 2, n_streak); sy = rng.uniform(2, h - 2, n_streak)
        slen = (rng.uniform(4.0, 10.0, n_streak) * scale).astype(np.float32)
        sang = base_ang + rng.normal(0, 0.10, n_streak).astype(np.float32)
        sM = rng.uniform(0.70, 0.96, n_streak).astype(np.float32)
        sR = rng.uniform(0.42, 0.72, n_streak).astype(np.float32)
        sC = rng.uniform(0.55, 0.88, n_streak).astype(np.float32)
        for i in range(n_streak):
            cx = float(sx[i]); cy = float(sy[i]); L = float(slen[i]); A = float(sang[i])
            x0 = int(cx - np.cos(A) * L * 0.5); y0 = int(cy - np.sin(A) * L * 0.5)
            x1 = int(cx + np.cos(A) * L * 0.5); y1 = int(cy + np.sin(A) * L * 0.5)
            _cv2.line(M, (x0, y0), (x1, y1), float(sM[i]), 1, lineType=_cv2.LINE_AA)
            _cv2.line(R, (x0, y0), (x1, y1), float(sR[i]), 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (x0, y0), (x1, y1), float(sC[i]), 1, lineType=_cv2.LINE_AA)

        # 5) CROSS-CUT CHIPS â€” perpendicular dashes 5-12 px (where blast crossed)
        cross_ang = base_ang + np.pi * 0.5
        n_cut = int(np.clip(1200 * (mn / 2048.0) ** 2, 420, 3200))
        for _ in range(n_cut):
            cx = float(rng.uniform(2, w - 2)); cy = float(rng.uniform(2, h - 2))
            L = float(rng.uniform(5.0, 12.0)) * scale
            A = cross_ang + float(rng.normal(0, 0.22))
            x0 = int(cx - np.cos(A) * L * 0.5); y0 = int(cy - np.sin(A) * L * 0.5)
            x1 = int(cx + np.cos(A) * L * 0.5); y1 = int(cy + np.sin(A) * L * 0.5)
            _cv2.line(M, (x0, y0), (x1, y1), float(rng.uniform(0.55, 0.86)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(R, (x0, y0), (x1, y1), float(rng.uniform(0.45, 0.78)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (x0, y0), (x1, y1), float(rng.uniform(0.50, 0.82)), 1, lineType=_cv2.LINE_AA)

        # 5b) GRIT CLUSTERS â€” 6-9 dot rosettes where nozzle paused (~10 px footprint)
        n_clust = int(np.clip(900 * (mn / 2048.0) ** 2, 320, 2400))
        for _ in range(n_clust):
            ccx = float(rng.uniform(8, w - 8)); ccy = float(rng.uniform(8, h - 8))
            n_dot = int(rng.integers(6, 10))
            spread = float(rng.uniform(4.0, 6.0) * scale)
            cM = float(rng.uniform(0.22, 0.55))
            cR = float(rng.uniform(0.72, 0.96))
            cCC = float(rng.uniform(0.55, 0.92))
            for _di in range(n_dot):
                dx = ccx + float(rng.normal(0, spread))
                dy = ccy + float(rng.normal(0, spread))
                dr = max(1, int(rng.uniform(1.0, 2.2) * scale))
                _cv2.circle(M, (int(dx), int(dy)), dr, cM + float(rng.uniform(-0.08, 0.08)), -1, lineType=_cv2.LINE_AA)
                _cv2.circle(R, (int(dx), int(dy)), dr, cR + float(rng.uniform(-0.06, 0.06)), -1, lineType=_cv2.LINE_AA)
                _cv2.circle(CC, (int(dx), int(dy)), dr, cCC + float(rng.uniform(-0.08, 0.08)), -1, lineType=_cv2.LINE_AA)

        # 5c) NOZZLE-ARC STRIKE CRESCENTS â€” 8-14 px arc fragments where blast turned
        n_arc = int(np.clip(700 * (mn / 2048.0) ** 2, 240, 1900))
        for _ in range(n_arc):
            cx = int(rng.uniform(0.01, 0.99) * w); cy = int(rng.uniform(0.01, 0.99) * h)
            r = max(3, int(rng.uniform(4.0, 7.0) * scale))
            a0 = float(rng.uniform(0, 360))
            a1 = a0 + float(rng.uniform(60, 140))
            _cv2.ellipse(M,  (cx, cy), (r, r), 0, a0, a1, float(rng.uniform(0.55, 0.92)), 1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(R,  (cx, cy), (r, r), 0, a0, a1, float(rng.uniform(0.30, 0.60)), 1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(CC, (cx, cy), (r, r), 0, a0, a1, float(rng.uniform(0.40, 0.78)), 1, lineType=_cv2.LINE_AA)

    # 6) BARE-METAL FLECK CARPET â€” dense single-pixel highlights
    n_fl = int(np.clip(3500 * (mn / 2048.0) ** 2, 1200, 9000))
    fx = rng.integers(0, w, n_fl); fy = rng.integers(0, h, n_fl)
    M[fy, fx] = np.maximum(M[fy, fx], rng.uniform(0.62, 0.98, n_fl).astype(np.float32))
    R[fy, fx] = np.minimum(R[fy, fx], rng.uniform(0.25, 0.55, n_fl).astype(np.float32))
    CC[fy, fx] = np.minimum(CC[fy, fx], rng.uniform(0.20, 0.55, n_fl).astype(np.float32))

    out = np.stack([M, R, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
spec_sandblast_strip._spb_concept_complete = True


def spec_micro_chips(shape, seed, sm, chip_radius=3.5, base_density=0.0015, **kwargs):
    """spec_micro_chips.

    identity: R6-creative â€” Salt-belt rock-chip carnage. Stone-blasted fender
    with FRESH, OLD, and FILLED chips simultaneously. Hero motifs: (1) FRESH
    angular chip pits 4-9 px (5-8 sided polygons) with sharp primer-exposed
    interiors, (2) OLD chips with rust-bloom HALOS (a 6-12 px oxidized ring
    around the pit), (3) FILLED chips â€” small 3-6 px discs where touch-up
    paint sits proud (bright M dome center), (4) DIRECTIONAL impact STARS
    (3-arm cracks emanating biased toward forward motion direction), (5)
    PRIMER-FLECK carpet (2-4 px primer-grey specks), (6) chip-cluster TRAIL
    lines linking chips along a likely stone-trajectory (short hairlines
    4-8 px), (7) bare-metal sparkle dust. Per-feature INDEPENDENT continuous
    M/R/CC across wide ranges. 2-12 px features only.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 77113)
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)

    # 1) BASE â€” intact paint substrate, INDEPENDENT FBM per channel
    g1 = _normalize(multi_scale_noise(shape, [2.5, 6.5, 14.0, 26.0], [0.34, 0.30, 0.22, 0.14], int(seed) + 77131))
    g2 = _normalize(multi_scale_noise(shape, [3.0, 7.0, 15.0, 28.0], [0.34, 0.30, 0.22, 0.14], int(seed) + 77132))
    g3 = _normalize(multi_scale_noise(shape, [2.0, 5.5, 12.0, 24.0], [0.34, 0.30, 0.22, 0.14], int(seed) + 77133))
    M  = (0.50 + (g1 - 0.5) * 0.24).astype(np.float32)
    R  = (0.44 + (g2 - 0.5) * 0.22).astype(np.float32)
    CC = (0.22 + (g3 - 0.5) * 0.20).astype(np.float32)

    # Dominant stone-trajectory angle (slight downward bias, simulating impact direction)
    impact_ang = float(rng.uniform(-0.4, 0.4)) + np.pi * 0.5

    if _CV2_OK:
        # 2) FRESH ANGULAR CHIP PITS (4-9 px) â€” sharp polygon pits
        n_fresh = int(np.clip(4200 * (mn / 2048.0) ** 2, 1500, 11000))
        fresh_pts = []
        for _ in range(n_fresh):
            cx = float(rng.uniform(3, w - 3)); cy = float(rng.uniform(3, h - 3))
            rr = max(2, int(rng.uniform(4.0, 9.0) * scale * 0.5))
            n_v = int(rng.integers(5, 9))
            pts = []
            ang0 = float(rng.uniform(0, 2 * np.pi))
            for k in range(n_v):
                ang = ang0 + k * (2 * np.pi / n_v) + float(rng.uniform(-0.25, 0.25))
                rk = rr * float(rng.uniform(0.65, 1.25))
                pts.append([int(cx + np.cos(ang) * rk), int(cy + np.sin(ang) * rk)])
            pts_arr = np.array([pts], dtype=np.int32)
            pM = float(rng.uniform(0.12, 0.42))
            pR = float(rng.uniform(0.68, 0.96))
            pCC = float(rng.uniform(0.68, 0.96))
            _cv2.fillPoly(M, pts_arr, pM)
            _cv2.fillPoly(R, pts_arr, pR)
            _cv2.fillPoly(CC, pts_arr, pCC)
            fresh_pts.append((int(cx), int(cy), rr))

        # 3) OLD CHIPS â€” rust-bloom HALO around a subset (6-12 px outer rings)
        n_old = int(np.clip(2200 * (mn / 2048.0) ** 2, 800, 6200))
        for _ in range(n_old):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            r_h = max(3, int(rng.uniform(6.0, 12.0) * scale * 0.5))
            # Rust bloom: lower M, mid R, mid CC, ring pixel
            _cv2.circle(M, (cx, cy), r_h, float(rng.uniform(0.22, 0.55)), 1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r_h, float(rng.uniform(0.55, 0.86)), 1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r_h, float(rng.uniform(0.40, 0.78)), 1, lineType=_cv2.LINE_AA)
            # Inner darker dot â€” old pit core
            r_in = max(1, r_h // 3)
            _cv2.circle(M, (cx, cy), r_in, float(rng.uniform(0.08, 0.24)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r_in, float(rng.uniform(0.62, 0.90)), -1, lineType=_cv2.LINE_AA)

        # 4) FILLED CHIPS (touch-up paint domes) â€” bright proud discs 3-6 px
        n_fill = int(np.clip(1800 * (mn / 2048.0) ** 2, 600, 4800))
        for _ in range(n_fill):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            r = max(1, int(rng.uniform(3.0, 6.0) * scale * 0.5))
            _cv2.circle(M, (cx, cy), r, float(rng.uniform(0.55, 0.88)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r, float(rng.uniform(0.22, 0.50)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r, float(rng.uniform(0.10, 0.32)), -1, lineType=_cv2.LINE_AA)
            # Bright proud highlight pixel offset
            _cv2.circle(M, (cx - 1, cy - 1), 1, float(rng.uniform(0.80, 0.98)), -1, lineType=_cv2.LINE_AA)

        # 5) DIRECTIONAL IMPACT-STARS â€” 3-arm cracks biased toward impact_ang (5-10 px arms)
        n_star = int(np.clip(2200 * (mn / 2048.0) ** 2, 800, 6400))
        for (cx, cy, rr) in fresh_pts[: min(len(fresh_pts), 1800)]:
            if rng.random() > 0.55:
                continue
            base_ang = impact_ang + float(rng.uniform(-0.6, 0.6))
            cM = float(rng.uniform(0.08, 0.28))
            cR = float(rng.uniform(0.62, 0.88))
            cCC = float(rng.uniform(0.40, 0.80))
            for k in range(3):
                ang = base_ang + k * (2.0 * np.pi / 3.0) + float(rng.uniform(-0.30, 0.30))
                length = float(rng.uniform(5.0, 10.0) * scale * 0.5)
                x2 = int(np.clip(cx + np.cos(ang) * length, 0, w - 1))
                y2 = int(np.clip(cy + np.sin(ang) * length, 0, h - 1))
                _cv2.line(M, (cx, cy), (x2, y2), cM, 1, lineType=_cv2.LINE_AA)
                _cv2.line(R, (cx, cy), (x2, y2), cR, 1, lineType=_cv2.LINE_AA)
                _cv2.line(CC, (cx, cy), (x2, y2), cCC, 1, lineType=_cv2.LINE_AA)

        # 6) CHIP-TRAIL hairlines â€” short 4-8 px lines along stone-impact trajectory
        n_tr = int(np.clip(1400 * (mn / 2048.0) ** 2, 500, 4000))
        for _ in range(n_tr):
            cx = float(rng.uniform(3, w - 3)); cy = float(rng.uniform(3, h - 3))
            ln = float(rng.uniform(4.0, 8.0) * scale)
            a = impact_ang + float(rng.uniform(-0.20, 0.20))
            x0 = int(cx - np.cos(a) * ln * 0.5); y0 = int(cy - np.sin(a) * ln * 0.5)
            x1 = int(cx + np.cos(a) * ln * 0.5); y1 = int(cy + np.sin(a) * ln * 0.5)
            _cv2.line(M, (x0, y0), (x1, y1), float(rng.uniform(0.20, 0.48)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(R, (x0, y0), (x1, y1), float(rng.uniform(0.50, 0.84)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (x0, y0), (x1, y1), float(rng.uniform(0.30, 0.68)), 1, lineType=_cv2.LINE_AA)

        # 7) PRIMER-FLECK CARPET â€” 2-4 px primer-grey discs
        n_pf = int(np.clip(2800 * (mn / 2048.0) ** 2, 950, 7000))
        for _ in range(n_pf):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            r = max(1, int(rng.uniform(2.0, 4.0) * scale * 0.5))
            _cv2.circle(M, (cx, cy), r, float(rng.uniform(0.18, 0.42)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r, float(rng.uniform(0.60, 0.92)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r, float(rng.uniform(0.55, 0.90)), -1, lineType=_cv2.LINE_AA)

    # 8) BARE-METAL SPARKLE DUST â€” single-pixel highlights
    n_fl = int(np.clip(mn * mn / 90.0, 2200, 9000))
    fx = rng.integers(0, w, n_fl); fy = rng.integers(0, h, n_fl)
    M[fy, fx] = np.maximum(M[fy, fx], rng.uniform(0.55, 0.97, n_fl).astype(np.float32))
    R[fy, fx] = np.minimum(R[fy, fx], rng.uniform(0.08, 0.36, n_fl).astype(np.float32))
    CC[fy, fx] = np.minimum(CC[fy, fx], rng.uniform(0.04, 0.26, n_fl).astype(np.float32))

    # 9) HERO CRATER CHIPS â€” 2-4 LARGE angular chip craters (10-18 px)
    #    with bright rim flare and dark interior, plus a small star pattern.
    #    This is the "character" feature the owner is looking for.
    if _CV2_OK:
        n_hero = int(np.clip(4 * (mn / 256.0) ** 0.4, 2, 12))
        for _ in range(n_hero):
            cx = int(rng.uniform(0.06, 0.94) * w); cy = int(rng.uniform(0.06, 0.94) * h)
            rh = max(5, int(rng.uniform(10.0, 18.0) * scale))
            # 7-9 sided angular polygon
            n_v = int(rng.integers(7, 10))
            pts = []
            ang0 = float(rng.uniform(0, 2 * np.pi))
            for k in range(n_v):
                ang = ang0 + k * (2 * np.pi / n_v) + float(rng.uniform(-0.18, 0.18))
                rk = rh * float(rng.uniform(0.65, 1.15))
                pts.append([int(cx + np.cos(ang) * rk), int(cy + np.sin(ang) * rk)])
            pts_arr = np.array([pts], dtype=np.int32)
            cM = float(rng.uniform(0.08, 0.28))
            cR = float(rng.uniform(0.78, 0.97))
            cCC = float(rng.uniform(0.74, 0.96))
            _cv2.fillPoly(M, pts_arr, cM)
            _cv2.fillPoly(R, pts_arr, cR)
            _cv2.fillPoly(CC, pts_arr, cCC)
            # Bright rim flare (1-2 px outline at ~110% radius)
            r_rim = int(rh * 1.12)
            _cv2.circle(M, (cx, cy), r_rim, float(rng.uniform(0.62, 0.92)), 1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r_rim, float(rng.uniform(0.20, 0.45)), 1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r_rim, float(rng.uniform(0.18, 0.45)), 1, lineType=_cv2.LINE_AA)
            # Mini impact-star around the hero (3 arms)
            base_ang = impact_ang + float(rng.uniform(-0.5, 0.5))
            for k in range(3):
                a = base_ang + k * (2.0 * np.pi / 3.0)
                Ls = float(rng.uniform(6.0, 10.0) * scale)
                x2 = int(np.clip(cx + np.cos(a) * (rh + Ls), 0, w - 1))
                y2 = int(np.clip(cy + np.sin(a) * (rh + Ls), 0, h - 1))
                _cv2.line(M, (cx, cy), (x2, y2), float(rng.uniform(0.10, 0.28)), 1, lineType=_cv2.LINE_AA)
                _cv2.line(R, (cx, cy), (x2, y2), float(rng.uniform(0.62, 0.88)), 1, lineType=_cv2.LINE_AA)
                _cv2.line(CC, (cx, cy), (x2, y2), float(rng.uniform(0.40, 0.78)), 1, lineType=_cv2.LINE_AA)

        # 10) PAINT BLISTER BUBBLES â€” 5-9 px proud domes (touch-up paint dried lifted)
        n_blis = int(np.clip(120 * (mn / 256.0) ** 0.7, 40, 600))
        for _ in range(n_blis):
            cx = int(rng.uniform(0.04, 0.96) * w); cy = int(rng.uniform(0.04, 0.96) * h)
            r = max(2, int(rng.uniform(5.0, 9.0) * scale))
            _cv2.circle(M, (cx, cy), r, float(rng.uniform(0.55, 0.86)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r, float(rng.uniform(0.18, 0.42)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r, float(rng.uniform(0.14, 0.40)), -1, lineType=_cv2.LINE_AA)
            # Highlight pip on top-left of dome
            off = max(1, int(r * 0.45))
            _cv2.circle(M, (cx - off, cy - off), max(1, r // 3), float(rng.uniform(0.82, 0.98)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx - off, cy - off), max(1, r // 3), float(rng.uniform(0.10, 0.32)), -1, lineType=_cv2.LINE_AA)

        # R6-TICK NEW HERO â€” LICHEN CRUSTOSE COLONIES
        # Biology motif: 4-8 lichen colonies growing on/around old chips.
        # Each colony = an irregular blob of 12-22 dense 1-2 px discs
        # clustered around a center (Gaussian scatter, radius 4-9 px),
        # with chroma in the chartreuse/sage/mustard ranges (specifically
        # mid-low M, high R rough surface, mid CC). A few apothecia
        # (1 px bright disc fruiting bodies) inside each colony. Owner
        # has never seen organic-growth motif on a rock-chip pattern.
        n_lichen = int(rng.integers(4, 9))
        for _ in range(n_lichen):
            lcx = float(rng.uniform(0.05, 0.95) * w)
            lcy = float(rng.uniform(0.05, 0.95) * h)
            spread = float(rng.uniform(4.0, 9.0) * scale)
            # Colony chroma palette â€” drifts per colony
            base_lM = float(rng.uniform(0.22, 0.48))   # dim metallic (organic, not shiny)
            base_lR = float(rng.uniform(0.62, 0.92))   # rough/matte
            base_lCC = float(rng.uniform(0.32, 0.66))  # uneven clearcoat
            n_thallus = int(rng.integers(12, 23))
            for _t in range(n_thallus):
                # Gaussian scatter around center
                dxg = float(rng.normal(0, spread * 0.7))
                dyg = float(rng.normal(0, spread * 0.7))
                tx = int(np.clip(lcx + dxg, 0, w - 1))
                ty = int(np.clip(lcy + dyg, 0, h - 1))
                tr = max(1, int(rng.uniform(1.0, 2.0)))
                _cv2.circle(M, (tx, ty), tr,
                            float(np.clip(base_lM + rng.uniform(-0.10, 0.12), 0, 1)),
                            -1, lineType=_cv2.LINE_AA)
                _cv2.circle(R, (tx, ty), tr,
                            float(np.clip(base_lR + rng.uniform(-0.12, 0.10), 0, 1)),
                            -1, lineType=_cv2.LINE_AA)
                _cv2.circle(CC, (tx, ty), tr,
                            float(np.clip(base_lCC + rng.uniform(-0.14, 0.14), 0, 1)),
                            -1, lineType=_cv2.LINE_AA)
            # APOTHECIA â€” 2-4 tiny bright fruiting bodies per colony
            n_apo = int(rng.integers(2, 5))
            for _a in range(n_apo):
                axg = float(rng.normal(0, spread * 0.5))
                ayg = float(rng.normal(0, spread * 0.5))
                ax = int(np.clip(lcx + axg, 0, w - 1))
                ay = int(np.clip(lcy + ayg, 0, h - 1))
                _cv2.circle(M, (ax, ay), 1,
                            float(rng.uniform(0.62, 0.92)), -1, lineType=_cv2.LINE_AA)
                _cv2.circle(R, (ax, ay), 1,
                            float(rng.uniform(0.18, 0.40)), -1, lineType=_cv2.LINE_AA)

    out = np.stack([M, R, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
spec_micro_chips._spb_concept_complete = True


def spec_aged_matte(shape, seed, sm, octaves=6, persistence=0.48, **kwargs):
    """spec_aged_matte.

    identity: R6 creative rebuild â€” a weather-aged matte panel that has
    been left out a season. HERO motif: an irregular meandering CRAQUELURE
    NETWORK â€” the chalked paint has cracked into 12-24 px tile islands
    rimmed by hairline 1-2 px crack veins (organic shapes, not a grid).
    HERO #2: PIGMENT TIDE-MARKS â€” wandering 1-2 px curving streaks
    (10-30 px arc length) where rainwater dragged loose chalk pigment
    across the panel. Plus: oxidation bloom discs (4-12 px, varied chroma
    chalk-white/grey/tan/faded-brown), pore voids (2-6 px), wind-deposit
    dust flecks (carpet), micro grit pinpoints (1 px). Each primitive
    draws INDEPENDENT continuous M/R/CC uniforms. R skews high (matte),
    M low (dielectric chalk), CC patchy where rain glaze remains.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 78119)
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)

    # 1) Independent FBM per channel â€” chalky weathered substrate
    g1 = _normalize(multi_scale_noise(shape, [2.5, 6.0, 13.0, 21.0], [0.36, 0.30, 0.22, 0.12], int(seed) + 7831))
    g2 = _normalize(multi_scale_noise(shape, [3.0, 7.0, 15.0, 24.0], [0.34, 0.30, 0.22, 0.14], int(seed) + 7833))
    g3 = _normalize(multi_scale_noise(shape, [3.5, 8.0, 16.0, 25.0], [0.34, 0.30, 0.22, 0.14], int(seed) + 7835))
    M = (0.18 + (g1 - 0.5) * 0.22).astype(np.float32)
    R = (0.72 + (g2 - 0.5) * 0.28).astype(np.float32)
    CC = (0.60 + (g3 - 0.5) * 0.34).astype(np.float32)

    if _CV2_OK:
        # 2) HERO â€” CRAQUELURE NETWORK. Seed island centers, draw an
        # irregular meandering crack vein from each center to its nearest
        # neighbor with mid-vein zig-zag jitter (organic, not Voronoi).
        n_islands = int(np.clip(420 * (mn / 256.0) ** 2, 220, 1800))
        cx_arr = rng.uniform(0, w, n_islands).astype(np.float32)
        cy_arr = rng.uniform(0, h, n_islands).astype(np.float32)
        # for each island, connect to 2 random nearby islands -> dense web
        for i in range(n_islands):
            # pick 2 neighbors quickly via random sampling
            for _link in range(2):
                j = int(rng.integers(0, n_islands))
                if j == i:
                    continue
                # only link if reasonably close (so we get tile-scale veins)
                dx = cx_arr[j] - cx_arr[i]; dy = cy_arr[j] - cy_arr[i]
                d = float(np.sqrt(dx * dx + dy * dy))
                if d < 6.0 or d > 26.0 * scale + 12.0:
                    continue
                # build a 4-segment meandering polyline
                steps = 4
                px = cx_arr[i]; py = cy_arr[i]
                # unit step toward target
                ux = dx / max(d, 1e-3); uy = dy / max(d, 1e-3)
                seg = d / steps
                # perpendicular jitter axis
                nx_p = -uy; ny_p = ux
                cM = float(rng.uniform(0.28, 0.62))
                cR = float(rng.uniform(0.55, 0.92))
                cCC = float(rng.uniform(0.18, 0.55))
                pts_x = [px]; pts_y = [py]
                for s in range(1, steps + 1):
                    jitter = float(rng.uniform(-1.5, 1.5)) * scale
                    nxp = cx_arr[i] + ux * seg * s + nx_p * jitter
                    nyp = cy_arr[i] + uy * seg * s + ny_p * jitter
                    pts_x.append(nxp); pts_y.append(nyp)
                for s in range(steps):
                    p0 = (int(np.clip(pts_x[s], 0, w - 1)), int(np.clip(pts_y[s], 0, h - 1)))
                    p1 = (int(np.clip(pts_x[s + 1], 0, w - 1)), int(np.clip(pts_y[s + 1], 0, h - 1)))
                    _cv2.line(M, p0, p1, cM, 1, lineType=_cv2.LINE_AA)
                    _cv2.line(R, p0, p1, cR, 1, lineType=_cv2.LINE_AA)
                    _cv2.line(CC, p0, p1, cCC, 1, lineType=_cv2.LINE_AA)

        # 3) HERO #2 â€” PIGMENT TIDE-MARKS. Wandering 1-2 px curving streaks
        # like dried rain trails dragging chalk pigment across the surface.
        n_tide = int(np.clip(380 * (mn / 256.0) ** 2, 180, 1400))
        for _ in range(n_tide):
            cx0 = float(rng.uniform(0, w)); cy0 = float(rng.uniform(0, h))
            base_ang = float(rng.uniform(0, 2 * np.pi))
            curve = float(rng.uniform(-0.18, 0.18))
            n_seg = int(rng.integers(8, 14))
            seg_len = float(rng.uniform(1.8, 3.2) * scale)
            tM = float(rng.uniform(0.20, 0.55))
            tR = float(rng.uniform(0.62, 0.92))
            tCC = float(rng.uniform(0.30, 0.78))
            px = cx0; py = cy0; ang = base_ang
            for s in range(n_seg):
                nxp = px + np.cos(ang) * seg_len
                nyp = py + np.sin(ang) * seg_len
                p0 = (int(np.clip(px, 0, w - 1)), int(np.clip(py, 0, h - 1)))
                p1 = (int(np.clip(nxp, 0, w - 1)), int(np.clip(nyp, 0, h - 1)))
                # vary tint slightly along the streak so it doesn't read flat
                _cv2.line(M, p0, p1, tM + float(rng.uniform(-0.04, 0.04)), 1, lineType=_cv2.LINE_AA)
                _cv2.line(R, p0, p1, tR + float(rng.uniform(-0.04, 0.04)), 1, lineType=_cv2.LINE_AA)
                _cv2.line(CC, p0, p1, tCC + float(rng.uniform(-0.05, 0.05)), 1, lineType=_cv2.LINE_AA)
                px = nxp; py = nyp; ang += curve + float(rng.uniform(-0.10, 0.10))

        # 4) OXIDATION BLOOM DISCS (4-12 px) â€” chalky pigment patches
        n_disc = int(np.clip(2400 * (mn / 2048.0) ** 2, 800, 6000))
        for _ in range(n_disc):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            r = int(max(2, rng.uniform(4, 12) * scale * 0.5))
            mM = float(rng.uniform(0.06, 0.32))
            mR = float(rng.uniform(0.70, 0.96))
            mCC = float(rng.uniform(0.42, 0.92))
            _cv2.circle(M, (cx, cy), r, mM, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r, mR, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r, mCC, -1, lineType=_cv2.LINE_AA)

        # 5) PORE VOIDS (2-6 px) â€” fine micro-erosion pits
        n_pore = int(np.clip(3200 * (mn / 2048.0) ** 2, 1000, 8000))
        for _ in range(n_pore):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            r = int(max(1, rng.uniform(2, 6) * scale * 0.5))
            pM = float(rng.uniform(0.08, 0.30))
            pR = float(rng.uniform(0.65, 0.96))
            pCC = float(rng.uniform(0.35, 0.85))
            _cv2.circle(M, (cx, cy), r, pM, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r, pR, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r, pCC, -1, lineType=_cv2.LINE_AA)

    # 6) WIND-DEPOSIT DUST FLECK CARPET â€” vectorized
    n_flecks = int(np.clip(8500 * (mn / 2048.0) ** 2, 2800, 18000))
    fx = rng.integers(0, w, n_flecks); fy = rng.integers(0, h, n_flecks)
    M[fy, fx] = rng.uniform(0.06, 0.50, n_flecks).astype(np.float32)
    R[fy, fx] = rng.uniform(0.50, 0.96, n_flecks).astype(np.float32)
    CC[fy, fx] = rng.uniform(0.28, 0.92, n_flecks).astype(np.float32)

    # 7) MICRO GRIT PINPOINTS â€” single-pixel high-R sparkles for chalk crystal
    n_grit = int(np.clip(4000 * (mn / 2048.0) ** 2, 1200, 9000))
    gx = rng.integers(0, w, n_grit); gy = rng.integers(0, h, n_grit)
    R[gy, gx] = np.maximum(R[gy, gx], rng.uniform(0.78, 0.98, n_grit).astype(np.float32))

    out = np.stack([M, R, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
spec_aged_matte._spb_concept_complete = True


