def spec_carbon_2x2_twill(shape, seed, sm, tow_width=8.0, **kwargs):
    """spec_carbon_2x2_twill.

    identity: CRISP DIAGONAL TWILL â€” the defining 2-over-2-under diagonal
    step is the dominant visual. Two Â±45-degree tow families interlace
    with a clear diagonal staircase (each tow shifts 1 cell along its
    perpendicular every 2 rows), unlike plain weave (no diagonal) or 3K
    (finer tow + sub-bundle ribbing). Per-tow INDEPENDENT continuous
    M/R/CC chroma, Gaussian-crown tow shading, dark crossover shadow
    seams, resin-pocket glints in the gaps. Now 3-channel (previous
    revision returned mono).
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + (hash("spec_carbon_2x2_twill_r5") % 10000))
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)
    # 2026-06-13 perf: broadcast arange grids (cheaper than mgrid materializing
    # two full int arrays, then casting). xx/yy are only ever read additively.
    yy = np.arange(h, dtype=np.float32)[:, None]
    xx = np.arange(w, dtype=np.float32)[None, :]

    # Tow pitch â€” ~10-14 px tows for visible weave at any canvas size.
    tow_px = max(8.0, mn / 110.0)
    # Twill projection axes â€” Â±45 deg
    u_raw = (xx + yy) / tow_px           # diagonal A
    v_raw = (xx - yy) / tow_px           # diagonal B
    # Add a gentle organic warp so it doesn't look stenciled
    # 2026-05-30 perf pass: this is only a soft carrier warp, so build it
    # through bounded smooth noise instead of blurring full-canvas white noise.
    warp = (_normalize(_spb_fast_smooth_noise(shape, [max(3.0, tow_px * 0.55)], [1.0], int(seed) + 10209)) - 0.5) * 0.16
    u = u_raw + warp
    v = v_raw - warp * 0.7

    # Tow crown â€” Gaussian profile across each tow
    uf = (u % 1.0) - 0.5
    vf = (v % 1.0) - 0.5
    crown_a = np.exp(-(uf * 2.55) ** 2).astype(np.float32)
    crown_b = np.exp(-(vf * 2.55) ** 2).astype(np.float32)

    # 2x2 TWILL RULE: family A is "on top" when (floor(v) - floor(u/2)) mod 4 < 2.
    # This produces the canonical diagonal staircase that distinguishes twill.
    iu = np.floor(u).astype(np.int32)
    iv = np.floor(v).astype(np.int32)
    twill_phase = ((iv - (iu // 2)) % 4).astype(np.int32)  # 0..3
    a_on_top = (twill_phase < 2).astype(np.float32)
    b_on_top = 1.0 - a_on_top

    # Per-tow hash â†’ INDEPENDENT continuous M/R/CC values for each tow cell
    # 2026-06-13 perf: precompute the int64 lattice products ONCE instead of
    # recasting iu/iv to int64 inside all six _hash01 calls (bit-identical).
    iu64 = iu.astype(np.int64) * 73856093
    iv64 = iv.astype(np.int64) * 19349663
    _ha_xor = iu64 ^ iv64

    def _hash01(off):
        ha = _ha_xor ^ (int(seed) + off)
        return ((ha & 0xFFFF).astype(np.float32) / 65535.0)
    tow_M_a = (0.30 + _hash01(11) * 0.60).astype(np.float32)
    tow_R_a = (0.10 + _hash01(13) * 0.40).astype(np.float32)
    tow_C_a = (0.25 + _hash01(15) * 0.65).astype(np.float32)
    tow_M_b = (0.30 + _hash01(21) * 0.60).astype(np.float32)
    tow_R_b = (0.10 + _hash01(23) * 0.40).astype(np.float32)
    tow_C_b = (0.25 + _hash01(25) * 0.65).astype(np.float32)

    # 1) BASE â€” dark resin substrate
    base_fbm = _normalize(_spb_fast_smooth_noise(shape, [4.0, 10.0, 22.0], [0.5, 0.3, 0.2], int(seed) + 10211))
    M  = (0.30 + (base_fbm - 0.5) * 0.18).astype(np.float32)
    R_ch = (0.55 + (base_fbm - 0.5) * 0.18).astype(np.float32)
    CC = (0.40 + (base_fbm - 0.5) * 0.18).astype(np.float32)

    # 2) APPLY TOWS â€” top tow paints its chroma; bottom tow paints a darker echo.
    # 2026-06-13 perf: fold the darker bottom-echo term (bot = crown*other*0.30)
    # into a single combined offset so each channel does one add instead of two,
    # and cut the 1-w temporaries by precomputing the complements once. The
    # weave-blend math (M*(1-w)+tow*w) is left in its original op order so the
    # output is bit-identical.
    top_a_w = crown_a * a_on_top
    top_b_w = crown_b * b_on_top
    bot_a_w = crown_a * b_on_top * 0.30  # bottom tow darker
    bot_b_w = crown_b * a_on_top * 0.30
    inv_a = 1 - top_a_w
    inv_b = 1 - top_b_w
    bot_sum = bot_a_w + bot_b_w
    M  = M  * inv_a + tow_M_a * top_a_w
    M  = M  * inv_b + tow_M_b * top_b_w
    M  = M  - bot_sum * 0.12
    R_ch = R_ch * inv_a + tow_R_a * top_a_w
    R_ch = R_ch * inv_b + tow_R_b * top_b_w
    R_ch = R_ch + bot_sum * 0.10
    CC = CC * inv_a + tow_C_a * top_a_w
    CC = CC * inv_b + tow_C_b * top_b_w
    CC = CC - bot_sum * 0.10

    # 3) CROSSOVER SHADOW SEAMS â€” dark hairlines where tows pass under
    crossover = np.minimum(crown_a, crown_b)
    M  -= crossover * 0.18
    CC -= crossover * 0.12

    # 4) Micro-filaments along each tow direction
    fib_freq_a = (2.0 * np.pi / max(tow_px * 0.42, 2.0))
    fib_freq_b = (2.0 * np.pi / max(tow_px * 0.42, 2.0))
    fib_a = (np.sin((xx + yy) * fib_freq_a) * 0.5 + 0.5).astype(np.float32) * crown_a * a_on_top
    fib_b = (np.sin((xx - yy) * fib_freq_b) * 0.5 + 0.5).astype(np.float32) * crown_b * b_on_top
    M = M + (fib_a + fib_b - 0.5) * 0.08
    R_ch = R_ch - (fib_a + fib_b - 0.5) * 0.06

    if _CV2_OK:
        # 5) RESIN-POCKET GLINTS in tow gaps â€” bright glossy specks
        n_resin = max(1800, int(h * w / 850))
        for _ in range(n_resin):
            cx_p = int(rng.integers(0, w)); cy_p = int(rng.integers(0, h))
            rr = max(1, int(rng.uniform(1.2, 2.6) * scale))
            _cv2.circle(M,    (cx_p, cy_p), rr, float(rng.uniform(0.15, 0.45)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R_ch, (cx_p, cy_p), rr, float(rng.uniform(0.06, 0.25)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC,   (cx_p, cy_p), rr, float(rng.uniform(0.70, 0.96)), -1, lineType=_cv2.LINE_AA)

    # 6) Filament flecks â€” dense single-pixel chroma diversity
    n_fl = max(7000, int(h * w / 90))
    fy = rng.integers(0, h, n_fl); fx = rng.integers(0, w, n_fl)
    M[fy, fx]    = np.maximum(M[fy, fx],    rng.uniform(0.20, 0.92, n_fl).astype(np.float32))
    R_ch[fy, fx] = np.minimum(R_ch[fy, fx], rng.uniform(0.06, 0.38, n_fl).astype(np.float32))
    CC[fy, fx]   = np.maximum(CC[fy, fx],   rng.uniform(0.25, 0.94, n_fl).astype(np.float32))

    # 2026-06-13 perf: assemble the HxWx3 output directly into one float32
    # buffer with in-place clip, instead of three clip temporaries + np.stack +
    # an astype copy. Bit-identical.
    out = np.empty((h, w, 3), dtype=np.float32)
    out[:, :, 0] = M
    out[:, :, 1] = R_ch
    out[:, :, 2] = CC
    np.clip(out, 0.0, 1.0, out=out)
    return _sm_scale(out, sm)
spec_carbon_2x2_twill._spb_concept_complete = True


def spec_carbon_plain_weave(shape, seed, sm, tow_width=6.0, **kwargs):
    """spec_carbon_plain_weave â€” R6 CREATIVE rebuild.

    identity: A premium 1x1 plain-weave carbon panel with HERO wet-resin
    story. Orthogonal warp/weft tows at 10-12 px pitch with 4-5 sub-
    filament microridges per tow; parity-driven over/under alternating
    squares with crisp 1-px dark inter-tow grooves. HEROES: (1) WET
    RESIN DROPLET CAUSTICS â€” sparse 5-9 px gloss puddles with bright
    crescent rim highlights (mirror caustic edge) and a deep shadow on
    the opposite side, scattered like droplets on cured clear coat.
    (2) CARBON DUST CONSTELLATION â€” tight micro-clusters (3-7 dust
    grains in 8-12 px radius), giving the panel scatter rather than
    uniform fleck noise. Plus: bright tow-top filament glints, resin
    gap-pocket dots, and burnished fiber flecks. Diverges from twill
    (no diagonal) and 3K (orthogonal not Â±45deg). Per-tow continuous
    M/R/CC uniforms.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 43017)
    scale = max(min(h, w) / 2048.0, 0.25)
    yy = np.arange(h, dtype=np.float32)[:, None]
    xx = np.arange(w, dtype=np.float32)[None, :]
    tow_px = max(10.0, 11.0 * scale)

    def _fbm_local(off, sigma):
        if _CV2_OK:
            sh = max(64, h // 10); sw = max(64, w // 10)
            n = np.random.default_rng(int(seed) + off).random((sh, sw)).astype(np.float32)
            b = _cv2.GaussianBlur(n, (0, 0), sigmaX=sigma, sigmaY=sigma)
            return _normalize(_cv2.resize(b, (w, h), interpolation=_cv2.INTER_CUBIC).astype(np.float32))
        return _normalize(multi_scale_noise(shape, [20, 40], [0.6, 0.4], int(seed) + off))

    M = (0.45 + (_fbm_local(4301, 5.0) - 0.5) * 0.22).astype(np.float32)
    R_ch = (0.48 + (_fbm_local(4303, 5.0) - 0.5) * 0.22).astype(np.float32)
    CC = (0.42 + (_fbm_local(4305, 5.0) - 0.5) * 0.22).astype(np.float32)
    # Per-tow hash for uniqueness
    tow_u_idx = np.floor(xx / tow_px).astype(np.int32)
    tow_v_idx = np.floor(yy / tow_px).astype(np.int32)
    def _hash01(a, b, off):
        h_arr = (a.astype(np.int64) * 73856093) ^ (b.astype(np.int64) * 19349663) ^ (int(seed) + off)
        return ((h_arr & 0xFFFF).astype(np.float32) / 65535.0)
    tow_M = (0.10 + _hash01(tow_u_idx, tow_v_idx, 11) * 0.85).astype(np.float32)
    tow_R = (0.08 + _hash01(tow_u_idx, tow_v_idx, 12) * 0.85).astype(np.float32)
    tow_CC = (0.10 + _hash01(tow_u_idx, tow_v_idx, 13) * 0.85).astype(np.float32)
    # Parity-driven over/under
    parity = ((tow_u_idx + tow_v_idx) & 1).astype(np.float32)
    # Tow crown profile (Gaussian)
    uf = ((xx / tow_px) % 1.0) - 0.5
    vf = ((yy / tow_px) % 1.0) - 0.5
    crown_u = np.exp(-(uf * 2.6) ** 2)
    crown_v = np.exp(-(vf * 2.6) ** 2)
    top = crown_u * parity + crown_v * (1.0 - parity)
    # Inter-tow gap mask â€” 1-px dark grooves where neither crown dominates
    gap = ((np.abs(uf) > 0.46) | (np.abs(vf) > 0.46)).astype(np.float32)
    M = M * (1.0 - top) + tow_M * top
    R_ch = R_ch * (1.0 - top) + tow_R * top
    CC = CC * (1.0 - top) + tow_CC * top
    # 4-5 sub-filament microridges
    sub_freq = (2.0 * np.pi / max(tow_px * 0.22, 2.0))  # ~4-5 sub-filaments per tow
    sub_u = (np.sin(yy * sub_freq) * 0.5 + 0.5) * crown_u
    sub_v = (np.sin(xx * sub_freq) * 0.5 + 0.5) * crown_v
    fiber_mod = (sub_u * parity + sub_v * (1.0 - parity)).astype(np.float32)
    M = np.clip(M + (fiber_mod - 0.5) * 0.16, 0, 1)
    R_ch = np.clip(R_ch - (fiber_mod - 0.5) * 0.12, 0, 1)
    CC = np.clip(CC + (fiber_mod - 0.5) * 0.12, 0, 1)
    # Apply dark inter-tow gap
    M = M * (1.0 - gap * 0.55)
    R_ch = R_ch + gap * 0.30
    CC = CC + gap * 0.40
    # Early BRU
    for arr in (M, R_ch, CC):
        mlo = rng.random(arr.shape) < 0.05
        mhi = rng.random(arr.shape) < 0.05
        arr[mlo] = float(rng.uniform(0.04, 0.18))
        arr[mhi] = float(rng.uniform(0.82, 0.97))
    if _CV2_OK:
        # Resin pockets bright glossy dots â€” placed in gap zones (QC: 1.4x)
        n_resin = max(3920, int(h * w / 285))
        for _ in range(n_resin):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            rr = max(1, int(rng.uniform(1.5, 3.0) * scale))
            _cv2.circle(M, (cx, cy), rr, float(rng.uniform(0.08, 0.32)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R_ch, (cx, cy), rr, float(rng.uniform(0.10, 0.40)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), rr, float(rng.uniform(0.72, 0.98)), -1, lineType=_cv2.LINE_AA)
        # Bright tow-top filament glints (1-2 px) (QC: 1.4x)
        n_glint = max(3080, int(h * w / 430))
        for _ in range(n_glint):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            r = max(1, int(rng.uniform(1.0, 2.0) * scale))
            _cv2.circle(M, (cx, cy), r, float(rng.uniform(0.45, 0.95)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R_ch, (cx, cy), r, float(rng.uniform(0.05, 0.25)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r, float(rng.uniform(0.05, 0.25)), -1, lineType=_cv2.LINE_AA)
        # Fiber filament flecks
        n_fl = max(8000, int(h * w / 70))
        fy = rng.integers(0, h, n_fl); fx = rng.integers(0, w, n_fl)
        M[fy, fx] = np.maximum(M[fy, fx], rng.uniform(0.10, 0.92, n_fl).astype(np.float32))
        R_ch[fy, fx] = np.minimum(R_ch[fy, fx], rng.uniform(0.06, 0.42, n_fl).astype(np.float32))
        CC[fy, fx] = np.maximum(CC[fy, fx], rng.uniform(0.10, 0.92, n_fl).astype(np.float32))
        # HERO: WET RESIN DROPLET CAUSTICS â€” bright crescent rim, dark opposite shadow
        n_drop = int(np.clip(h * w / 2200, 180, 1400))
        for _ in range(n_drop):
            cx = int(rng.uniform(4, w - 4)); cy = int(rng.uniform(4, h - 4))
            r_d = max(2, int(rng.uniform(3.0, 5.0) * scale))
            # Body: super-high CC, low R (glossy wet)
            _cv2.circle(M, (cx, cy), r_d, float(rng.uniform(0.10, 0.38)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R_ch, (cx, cy), r_d, float(rng.uniform(0.05, 0.20)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r_d, float(rng.uniform(0.82, 0.99)), -1, lineType=_cv2.LINE_AA)
            # Crescent rim highlight (sun-side)
            sun = float(rng.uniform(0, 2 * np.pi))
            sx_off = int(np.cos(sun) * r_d * 0.5); sy_off = int(np.sin(sun) * r_d * 0.5)
            gx = int(np.clip(cx + sx_off, 0, w - 1)); gy = int(np.clip(cy + sy_off, 0, h - 1))
            _cv2.circle(M, (gx, gy), max(1, r_d // 2), float(rng.uniform(0.88, 1.0)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R_ch, (gx, gy), max(1, r_d // 2), float(rng.uniform(0.02, 0.12)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (gx, gy), max(1, r_d // 2), float(rng.uniform(0.92, 1.0)), -1, lineType=_cv2.LINE_AA)
            # Opposite shadow
            sx_o = -sx_off; sy_o = -sy_off
            sxp = int(np.clip(cx + sx_o, 0, w - 1)); syp = int(np.clip(cy + sy_o, 0, h - 1))
            _cv2.circle(M, (sxp, syp), max(1, r_d // 3), float(rng.uniform(0.05, 0.18)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R_ch, (sxp, syp), max(1, r_d // 3), float(rng.uniform(0.40, 0.70)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (sxp, syp), max(1, r_d // 3), float(rng.uniform(0.50, 0.78)), -1, lineType=_cv2.LINE_AA)
        # HERO: CARBON DUST CONSTELLATIONS â€” tight clusters of 3-7 grains
        n_const = int(np.clip(h * w / 3500, 120, 900))
        for _ in range(n_const):
            cx = float(rng.uniform(6, w - 6)); cy = float(rng.uniform(6, h - 6))
            n_grain = int(rng.integers(3, 8))
            for _g in range(n_grain):
                gx = int(np.clip(cx + rng.normal(0, 4.0 * scale), 0, w - 1))
                gy = int(np.clip(cy + rng.normal(0, 4.0 * scale), 0, h - 1))
                r_g = max(1, int(rng.uniform(1.0, 1.8) * scale))
                _cv2.circle(M, (gx, gy), r_g, float(rng.uniform(0.05, 0.28)), -1, lineType=_cv2.LINE_AA)
                _cv2.circle(R_ch, (gx, gy), r_g, float(rng.uniform(0.55, 0.92)), -1, lineType=_cv2.LINE_AA)
                _cv2.circle(CC, (gx, gy), r_g, float(rng.uniform(0.40, 0.78)), -1, lineType=_cv2.LINE_AA)
    out = np.stack([np.clip(M, 0, 1), np.clip(R_ch, 0, 1), np.clip(CC, 0, 1)], axis=2).astype(np.float32)
    return _validate_spec_output(_sm_scale(np.clip(out, 0.0, 1.0), sm).astype(np.float32), "spec_carbon_plain_weave")
spec_carbon_plain_weave._spb_concept_complete = True


def spec_carbon_3k_fine(shape, seed, sm, tow_width=4.5, **kwargs):
    """spec_carbon_3k_fine.

    identity: CREATIVE REBUILD â€” Ultra-fine 3K carbon HYBRID LAYUP with
    seven stacked tiers: (1) a faint UD (unidirectional) shadow PLY
    underneath at a slight rotation showing through the resin matrix,
    (2) primary plain weave at Â±45Â° with 4-6 px tows, (3) sub-filament
    ribbing splitting every tow into 3 finer 1-2 px strands (true 3K
    filament-count read), (4) per-tow INDEPENDENT M/R/CC chroma hash,
    (5) BRIGHT RESIN-POCKET PEARL BLOOMS (4-8 px iridescent glaze
    spots â€” small patches where extra epoxy pooled and CC reads high
    with hue shift), (6) cleavage cracks and resin pinprick glints,
    (7) dense single-pixel filament flecks. The UD shadow + pearl
    blooms give it a unique hybrid layup identity vs sibling carbon
    weaves.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + (hash("spec_carbon_3k_fine_r5") % 10000))
    scale = max(min(h, w) / 2048.0, 0.25)
    yy, xx = np.mgrid[0:h, 0:w].astype(np.float32)

    # TIER 1 â€” UD (unidirectional) shadow ply at a slight rotation, faint
    # under-weave that shows through resin between top-ply tows.
    ud_ang = float(rng.uniform(0.10, 0.45))  # small offset from primary 0
    ud_proj = xx * np.cos(ud_ang) + yy * np.sin(ud_ang)
    ud_pitch = max(2.5, 3.5 * scale)
    ud_stripe = 0.5 + 0.5 * np.sin(ud_proj / ud_pitch * 2 * np.pi)
    ud_under = (ud_stripe * 0.10 - 0.05).astype(np.float32)  # Â±5% modulation

    # ULTRA-FINE: 4-6 px tows (was 12+). Brief contract.
    tow = max(4.0, min(h, w) / 380.0)
    if tow > 6.5:
        tow = 6.0
    sub = tow / 3.0
    # 2026-05-30 perf pass: preserve the full-res weave math, but generate
    # only the smooth organic warp at bounded resolution.
    warp = (_normalize(_spb_fast_smooth_noise(shape, [max(3.0, tow * 0.6)], [1.0], int(seed) + 14661)) - 0.5) * tow * 0.30
    # Â±45Â° tow projections
    u = (xx + yy + warp) / tow
    v = (xx - yy - warp * 0.6) / tow
    crown_u = np.exp(-(((u % 1.0) - 0.5) * 2.6) ** 2)
    crown_v = np.exp(-(((v % 1.0) - 0.5) * 2.6) ** 2)
    parity = ((np.floor(u).astype(np.int32) + np.floor(v).astype(np.int32)) & 1).astype(np.float32)
    top = crown_u * parity + crown_v * (1.0 - parity)
    # Sub-bundle ribbing â€” 3 stripes per tow
    us = (xx + yy + warp * 1.4) / sub
    vs = (xx - yy - warp) / sub
    ribb_u = (np.cos((us % 1.0) * 2.0 * np.pi) * 0.5 + 0.5)
    ribb_v = (np.cos((vs % 1.0) * 2.0 * np.pi) * 0.5 + 0.5)
    rib = ribb_u * parity + ribb_v * (1.0 - parity)
    # Per-tow hash for chroma variation
    tu_i = np.floor(u).astype(np.int32); tv_i = np.floor(v).astype(np.int32)
    def _hash01(a, b, off):
        ha = (a.astype(np.int64) * 73856093) ^ (b.astype(np.int64) * 19349663) ^ (int(seed) + off)
        return ((ha & 0xFFFF).astype(np.float32) / 65535.0)
    tM = 0.30 + _hash01(tu_i, tv_i, 1) * 0.55
    tR = 0.20 + _hash01(tu_i, tv_i, 2) * 0.50
    tCC = 0.20 + _hash01(tu_i, tv_i, 3) * 0.65
    # Base â€” dark carbon resin with UD shadow ply showing through
    # the gaps between top-ply tows (visible where `top` is low).
    inter_tow = (1.0 - top).astype(np.float32)
    M = 0.42 + (top - 0.5) * 0.45 + (rib - 0.5) * 0.12 + ud_under * inter_tow * 0.85
    M = M * 0.55 + tM * 0.55 * top
    R = 0.55 + (top - 0.5) * (-0.30) + (rib - 0.5) * 0.10 - ud_under * inter_tow * 0.40
    R = R * 0.6 + tR * 0.6 * top
    CC = 0.42 + (top - 0.5) * 0.30 + ud_under * inter_tow * 0.65
    CC = CC * 0.55 + tCC * 0.55 * top
    if _CV2_OK:
        # Resin-pocket glints at tow crossovers
        n_res = max(1500, int(h * w / 1200))
        for _ in range(n_res):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            r = max(1, int(rng.uniform(1.5, 3.5) * scale))
            _cv2.circle(M, (cx, cy), r, float(rng.uniform(0.08, 0.35)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r, float(rng.uniform(0.08, 0.35)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r, float(rng.uniform(0.70, 0.96)), -1, lineType=_cv2.LINE_AA)
        # Cleavage cracks â€” short dark hairlines between tows
        n_crk = max(700, int(h * w / 2200))
        for _ in range(n_crk):
            cx = rng.uniform(4, w - 4); cy = rng.uniform(4, h - 4)
            length = float(rng.uniform(6.0, 14.0) * scale)
            ang = float(rng.choice([np.pi * 0.25, -np.pi * 0.25]) + rng.uniform(-0.18, 0.18))
            x0s = int(cx - np.cos(ang) * length * 0.5); y0s = int(cy - np.sin(ang) * length * 0.5)
            x1s = int(cx + np.cos(ang) * length * 0.5); y1s = int(cy + np.sin(ang) * length * 0.5)
            _cv2.line(M, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.05, 0.20)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(R, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.60, 0.92)), 1, lineType=_cv2.LINE_AA)

        # NEW TIER â€” RESIN-POCKET PEARL BLOOMS (4-8 px iridescent glaze spots)
        # Small patches where extra epoxy pooled and reads high CC with hue shift.
        n_bloom = max(120, int(h * w / 6500))
        for _ in range(n_bloom):
            cx = int(rng.integers(2, w - 2)); cy = int(rng.integers(2, h - 2))
            r = max(2, int(rng.uniform(2.0, 4.0) * scale))
            # 3-shell bloom: dim halo, mid ring, bright pearl core
            # halo
            _cv2.circle(M, (cx, cy), int(r * 1.4),
                        float(rng.uniform(0.36, 0.58)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), int(r * 1.4),
                        float(rng.uniform(0.22, 0.42)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), int(r * 1.4),
                        float(rng.uniform(0.55, 0.78)), -1, lineType=_cv2.LINE_AA)
            # mid ring
            _cv2.circle(M, (cx, cy), r,
                        float(rng.uniform(0.55, 0.80)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r,
                        float(rng.uniform(0.10, 0.28)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r,
                        float(rng.uniform(0.75, 0.92)), -1, lineType=_cv2.LINE_AA)
            # pearl core â€” pure independent uniforms for chroma diversity
            _cv2.circle(M, (cx, cy), max(1, r // 2),
                        float(rng.uniform(0.78, 0.97)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), max(1, r // 2),
                        float(rng.uniform(0.04, 0.16)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), max(1, r // 2),
                        float(rng.uniform(0.85, 0.98)), -1, lineType=_cv2.LINE_AA)

    # Filament flecks across canvas
    n_fl = max(5000, int(h * w / 120))
    fy = rng.integers(0, h, n_fl); fx = rng.integers(0, w, n_fl)
    M[fy, fx] = np.maximum(M[fy, fx], rng.uniform(0.18, 0.90, n_fl).astype(np.float32))
    R[fy, fx] = np.minimum(R[fy, fx], rng.uniform(0.10, 0.50, n_fl).astype(np.float32))
    out = np.stack([M, R, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
spec_carbon_3k_fine._spb_concept_complete = True


def spec_carbon_forged(shape, seed, sm, num_strands=800, strand_len_frac=0.25, **kwargs):
    """spec_carbon_forged.

    identity: R6 creative rebuild â€” FORGED CARBON SLAB seen at thumbnail
    scale. The defining read: chopped 14-22 px shiny carbon FLAKES in
    random orientations packed into a dark resin matrix, with HERO bright
    diagonal STRESS FOLDS where the press squeezed flake edges into
    catch-light ridges. Six stacked feature tiers: (1) independent
    per-channel FBM substrate (no shared map), (2) Voronoi mosaic of 14-22
    px flake patches with independent continuous M/R/CC, (3) per-flake
    SWIRL anisotropy at random angle revealing chopped-strand bundle,
    (4) dark resin SEAMS at cell boundaries, (5) 6-10 HERO compression
    folds â€” long bright bands 30-80 px crossing the slab where flakes
    folded under pressure, (6) bright resin pinpricks + chip hairlines
    + chroma flecks. Per-feature INDEPENDENT M/R/CC continuous uniforms
    across the full gamut.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + (hash("spec_carbon_forged_r6") % 10000))
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)

    # 1) INDEPENDENT PER-CHANNEL FBM SUBSTRATE â€” dark resin with subtle variance
    bM = _normalize(multi_scale_noise(shape, [3.0, 8.0, 18.0], [0.40, 0.32, 0.28], int(seed) + 4201))
    bR = _normalize(multi_scale_noise(shape, [3.5, 9.0, 19.0], [0.40, 0.32, 0.28], int(seed) + 4202))
    bC = _normalize(multi_scale_noise(shape, [4.0, 10.0, 20.0], [0.40, 0.32, 0.28], int(seed) + 4203))
    M  = (0.26 + (bM - 0.5) * 0.18).astype(np.float32)
    R  = (0.60 + (bR - 0.5) * 0.18).astype(np.float32)
    CC = (0.38 + (bC - 0.5) * 0.18).astype(np.float32)

    # 2) FLAKE VORONOI MOSAIC â€” 14-22 px chopped carbon flakes
    patch_pitch = max(12.0, 18.0 * scale)
    n_patch = int(np.clip((h * w) / (patch_pitch * patch_pitch), 280, 9000))
    py = rng.uniform(-patch_pitch, h + patch_pitch, n_patch).astype(np.float32)
    px = rng.uniform(-patch_pitch, w + patch_pitch, n_patch).astype(np.float32)
    pts = np.column_stack([py.astype(np.float64), px.astype(np.float64)])
    tree = cKDTree(pts)
    yy_i, xx_i = np.mgrid[0:h, 0:w]
    coords = np.column_stack([yy_i.ravel().astype(np.float64), xx_i.ravel().astype(np.float64)])
    dists, idxs = tree.query(coords, k=2, workers=-1)
    d1 = dists[:, 0].reshape(shape).astype(np.float32)
    d2 = dists[:, 1].reshape(shape).astype(np.float32)
    patch_idx = idxs[:, 0].reshape(shape)

    # Per-flake INDEPENDENT continuous M/R/CC across full gamut
    patch_M = rng.uniform(0.15, 0.95, n_patch).astype(np.float32)
    patch_R = rng.uniform(0.05, 0.58, n_patch).astype(np.float32)
    patch_C = rng.uniform(0.18, 0.95, n_patch).astype(np.float32)
    patch_ang = rng.uniform(0, 2 * np.pi, n_patch).astype(np.float32)
    patch_freq = rng.uniform(0.20, 0.55, n_patch).astype(np.float32)

    M_field = patch_M[patch_idx]
    R_field = patch_R[patch_idx]
    C_field = patch_C[patch_idx]

    # 3) PER-FLAKE SWIRL â€” chopped strand bundle direction in each flake
    yy_f = yy_i.astype(np.float32)
    xx_f = xx_i.astype(np.float32)
    ang_field = patch_ang[patch_idx]
    freq_field = patch_freq[patch_idx]
    proj = xx_f * np.cos(ang_field) + yy_f * np.sin(ang_field)
    swirl = (np.sin(proj * freq_field) * 0.5 + 0.5).astype(np.float32)
    swirl_warp = _normalize(multi_scale_noise(shape, [3.0, 7.0], [0.6, 0.4], int(seed) + 4211))
    swirl = swirl * 0.70 + swirl_warp * 0.30

    # 4) DARK RESIN SEAMS â€” between flakes
    seam = np.clip(1.0 - (d2 - d1) / max(patch_pitch * 0.22, 1.0), 0, 1).astype(np.float32)

    # Combine flake fill + swirl + seams
    M  = M_field * (0.70 + (swirl - 0.5) * 0.40) - seam * 0.32
    R  = R_field * (0.74 + (0.5 - swirl) * 0.22) + seam * 0.26
    CC = C_field * (0.70 + (swirl - 0.5) * 0.36) - seam * 0.24

    if _CV2_OK:
        # 5) HERO COMPRESSION FOLDS â€” 6-10 long bright diagonal bands
        n_fold = int(rng.integers(6, 11))
        for _ in range(n_fold):
            cx = float(rng.uniform(-w * 0.10, w * 1.10))
            cy = float(rng.uniform(-h * 0.10, h * 1.10))
            ang = float(rng.uniform(0, 2 * np.pi))
            length = float(rng.uniform(36.0, 90.0)) * scale
            x0f = int(cx - np.cos(ang) * length * 0.5); y0f = int(cy - np.sin(ang) * length * 0.5)
            x1f = int(cx + np.cos(ang) * length * 0.5); y1f = int(cy + np.sin(ang) * length * 0.5)
            thk = max(1, int(rng.uniform(2.0, 3.5) * scale))
            fM = float(rng.uniform(0.80, 0.99))
            fR = float(rng.uniform(0.04, 0.22))
            fC = float(rng.uniform(0.78, 0.97))
            _cv2.line(M, (x0f, y0f), (x1f, y1f), fM, thk, lineType=_cv2.LINE_AA)
            _cv2.line(R, (x0f, y0f), (x1f, y1f), fR, thk, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (x0f, y0f), (x1f, y1f), fC, thk, lineType=_cv2.LINE_AA)
            # shadow companion â€” dark trailing edge for fold depth
            ox = int(np.cos(ang + np.pi / 2) * (thk + 1))
            oy = int(np.sin(ang + np.pi / 2) * (thk + 1))
            sM = float(rng.uniform(0.08, 0.25))
            _cv2.line(M, (x0f + ox, y0f + oy), (x1f + ox, y1f + oy), sM, 1, lineType=_cv2.LINE_AA)

        # 6) BRIGHT RESIN PINPRICKS â€” small glossy specks
        n_glint = max(900, int(h * w / 1500))
        for _ in range(n_glint):
            cxg = int(rng.integers(0, w)); cyg = int(rng.integers(0, h))
            r = max(1, int(rng.uniform(1.2, 2.8) * scale))
            _cv2.circle(M, (cxg, cyg), r, float(rng.uniform(0.70, 0.99)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cxg, cyg), r, float(rng.uniform(0.04, 0.20)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cxg, cyg), r, float(rng.uniform(0.70, 0.97)), -1, lineType=_cv2.LINE_AA)

        # 7) SHORT CHIP HAIRLINES â€” fine flake-edge breaks
        n_chip = max(1000, int(h * w / 1800))
        for _ in range(n_chip):
            cx = rng.uniform(4, w - 4); cy = rng.uniform(4, h - 4)
            length = float(rng.uniform(3.0, 8.0) * scale)
            ang = float(rng.uniform(0, 2 * np.pi))
            x0s = int(cx - np.cos(ang) * length * 0.5); y0s = int(cy - np.sin(ang) * length * 0.5)
            x1s = int(cx + np.cos(ang) * length * 0.5); y1s = int(cy + np.sin(ang) * length * 0.5)
            _cv2.line(M, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.50, 0.95)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.40, 0.90)), 1, lineType=_cv2.LINE_AA)

    # 8) Single-pixel chroma flecks â€” wide gamut
    n_fl = max(5500, int(h * w / 110))
    fy = rng.integers(0, h, n_fl); fx = rng.integers(0, w, n_fl)
    M[fy, fx]  = np.maximum(M[fy, fx],  rng.uniform(0.20, 0.96, n_fl).astype(np.float32))
    R[fy, fx]  = np.minimum(R[fy, fx],  rng.uniform(0.05, 0.50, n_fl).astype(np.float32))
    CC[fy, fx] = np.maximum(CC[fy, fx], rng.uniform(0.18, 0.94, n_fl).astype(np.float32))

    out = np.stack([np.clip(M, 0, 1), np.clip(R, 0, 1), np.clip(CC, 0, 1)], axis=-1).astype(np.float32)
    return _sm_scale(out, sm)
spec_carbon_forged._spb_concept_complete = True


def spec_carbon_wet_layup(shape, seed, sm, tow_width=9.0, **kwargs):
    """spec_carbon_wet_layup.

    identity: R6 creative rebuild (tick53 second-pass) â€” hand-laid wet
    carbon SHOP CHAOS. NEW HERO (tick53): CHEMICAL OUTGAS PIN-HOLE
    CRATERS â€” 4-9 px round volcano craters from off-gassing resin
    bubbles that ruptured the clearcoat. Each crater has a sharp bright
    rim (1 px ring), a depressed dim bowl, and a single bright glint
    speck at one edge of the rim. Stacked on prior heroes: (1) vertical
    resin SAG DRIPS (12-28 px tall, 2-3 px wide); (2) dust-and-lint
    HAIRS (8-20 px wavy filaments); (3) 6-12 px BLOB CLUSTERS of
    trapped resin domes with bright halos; (4) crowded AIR-BUBBLE RINGS
    (3-8 px open rings); (5) sandpaper SCUFF HAIRLINES (4-10 px);
    (6) micro carbon flecks. Per-feature INDEPENDENT continuous M/R/CC.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + (hash("spec_carbon_wet_layup_r6") % 10000))
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)

    # 1) SUBSTRATE â€” independent per-channel FBM (no shared map)
    bM = _normalize(multi_scale_noise(shape, [3.5, 8.0, 18.0, 36.0], [0.34, 0.30, 0.22, 0.14], int(seed) + 44011))
    bR = _normalize(multi_scale_noise(shape, [4.0, 9.0, 20.0, 38.0], [0.32, 0.30, 0.22, 0.16], int(seed) + 44012))
    bC = _normalize(multi_scale_noise(shape, [4.5, 10.0, 22.0, 40.0], [0.30, 0.28, 0.24, 0.18], int(seed) + 44013))
    M  = (0.42 + (bM - 0.5) * 0.30).astype(np.float32)
    R  = (0.58 - (bR - 0.5) * 0.34).astype(np.float32)
    CC = (0.32 + (bC - 0.5) * 0.36).astype(np.float32)

    # Resin-ridge mask (where drips originate) â€” high-puddle zones
    ridge = np.clip((bC - 0.55) * 3.0, 0.0, 1.0).astype(np.float32)

    if _CV2_OK:
        # 2) GRAVITY SAG DRIPS â€” vertical drools from ridges (one of the hero features)
        n_drip = int(np.clip(900 * scale * scale, 320, 2400))
        for _ in range(n_drip):
            cx = int(rng.integers(2, max(3, w - 2)))
            cy = int(rng.integers(0, max(1, int(h * 0.7))))
            if ridge[min(cy, h - 1), cx] < 0.20 + rng.uniform(-0.1, 0.1):
                continue
            drop_len = int(rng.uniform(12.0, 28.0) * scale)
            drop_w = max(1, int(rng.uniform(1.5, 3.0) * scale))
            y_end = min(h - 1, cy + drop_len)
            vm = float(rng.uniform(0.55, 0.95))
            vr = float(rng.uniform(0.18, 0.55))
            vc = float(rng.uniform(0.62, 0.97))
            _cv2.line(M,  (cx, cy), (cx, y_end), vm, drop_w, lineType=_cv2.LINE_AA)
            _cv2.line(R,  (cx, cy), (cx, y_end), vr, drop_w, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (cx, cy), (cx, y_end), vc, drop_w, lineType=_cv2.LINE_AA)
            # Heavy drop bead at the bottom
            br = max(2, int(rng.uniform(2.0, 4.0) * scale))
            _cv2.circle(M,  (cx, y_end), br, float(rng.uniform(0.62, 0.97)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, y_end), br, float(rng.uniform(0.70, 0.99)), -1, lineType=_cv2.LINE_AA)

        # 3) TRAPPED HAIRS / LINT â€” wavy 8-20 px filaments under clearcoat
        n_hair = int(np.clip(1800 * scale * scale, 600, 4500))
        for _ in range(n_hair):
            cx0 = float(rng.uniform(0, w)); cy0 = float(rng.uniform(0, h))
            length = float(rng.uniform(8.0, 20.0) * scale)
            base_a = float(rng.uniform(0, 2 * np.pi))
            steps = int(rng.uniform(4, 7))
            stride = length / steps
            pts = [(int(cx0), int(cy0))]
            cxp, cyp = cx0, cy0
            a = base_a
            for _s in range(steps):
                a += float(rng.uniform(-0.5, 0.5))
                cxp += np.cos(a) * stride
                cyp += np.sin(a) * stride
                pts.append((int(cxp), int(cyp)))
            vm = float(rng.uniform(0.12, 0.45))
            vr = float(rng.uniform(0.55, 0.92))
            vc = float(rng.uniform(0.18, 0.55))
            for k in range(len(pts) - 1):
                _cv2.line(M,  pts[k], pts[k+1], vm, 1, lineType=_cv2.LINE_AA)
                _cv2.line(R,  pts[k], pts[k+1], vr, 1, lineType=_cv2.LINE_AA)
                _cv2.line(CC, pts[k], pts[k+1], vc, 1, lineType=_cv2.LINE_AA)

        # 4) RESIN DOME BLOBS â€” 6-12 px raised domes with bright halos
        n_dome = int(np.clip(1500 * scale * scale, 500, 4000))
        for _ in range(n_dome):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            r = max(2, int(rng.uniform(3.0, 6.0) * scale))
            _cv2.circle(M,  (cx, cy), r, float(rng.uniform(0.55, 0.92)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R,  (cx, cy), r, float(rng.uniform(0.12, 0.40)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r, float(rng.uniform(0.70, 0.99)), -1, lineType=_cv2.LINE_AA)
            # Bright halo ring
            if r >= 3:
                _cv2.circle(M, (cx, cy), r + 1, float(rng.uniform(0.78, 0.99)), 1, lineType=_cv2.LINE_AA)

        # 5) AIR BUBBLE RINGS â€” champagne fizz, 3-8 px open rings with dark cores
        n_bub = int(np.clip(4200 * scale * scale, 1500, 11000))
        for _ in range(n_bub):
            cx = int(rng.integers(2, max(3, w - 2))); cy = int(rng.integers(2, max(3, h - 2)))
            r_b = max(2, int(rng.uniform(2.0, 5.0) * scale))
            _cv2.circle(M,  (cx, cy), r_b, float(rng.uniform(0.62, 0.96)), 1, lineType=_cv2.LINE_AA)
            _cv2.circle(R,  (cx, cy), r_b, float(rng.uniform(0.06, 0.22)), 1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r_b, float(rng.uniform(0.72, 0.97)), 1, lineType=_cv2.LINE_AA)
            if r_b > 2:
                _cv2.circle(R, (cx, cy), max(1, r_b - 2), float(rng.uniform(0.55, 0.90)), -1, lineType=_cv2.LINE_AA)

        # 6) SHOP-RAG SCUFF HAIRLINES â€” 4-10 px clustered axial scrub marks
        n_clusters = int(np.clip(36 * scale, 14, 90))
        for _c in range(n_clusters):
            ccx = float(rng.uniform(0, w)); ccy = float(rng.uniform(0, h))
            cluster_ang = float(rng.choice([0.0, np.pi * 0.5])) + float(rng.uniform(-0.15, 0.15))
            for _k in range(int(rng.integers(8, 22))):
                dx = float(rng.uniform(-22, 22)) * scale
                dy = float(rng.uniform(-22, 22)) * scale
                cx = ccx + dx; cy = ccy + dy
                L = float(rng.uniform(4.0, 10.0)) * scale
                x0 = int(cx - np.cos(cluster_ang) * L * 0.5); y0 = int(cy - np.sin(cluster_ang) * L * 0.5)
                x1 = int(cx + np.cos(cluster_ang) * L * 0.5); y1 = int(cy + np.sin(cluster_ang) * L * 0.5)
                _cv2.line(M, (x0, y0), (x1, y1), float(rng.uniform(0.30, 0.78)), 1, lineType=_cv2.LINE_AA)
                _cv2.line(R, (x0, y0), (x1, y1), float(rng.uniform(0.35, 0.78)), 1, lineType=_cv2.LINE_AA)

        # 6b) NEW HERO tick53 â€” CHEMICAL OUTGAS PIN-HOLE CRATERS (4-9 px).
        # Sharp bright 1-px rim, dim depressed bowl, single glint speck on
        # the rim edge. Per-crater INDEPENDENT continuous M/R/CC.
        n_pin = int(np.clip(1100 * scale * scale, 360, 3200))
        for _ in range(n_pin):
            cx = int(rng.integers(3, max(4, w - 3))); cy = int(rng.integers(3, max(4, h - 3)))
            r_o = max(2, int(rng.uniform(2.0, 4.5) * scale))
            # rim
            _cv2.circle(M, (cx, cy), r_o, float(rng.uniform(0.74, 0.97)), 1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r_o, float(rng.uniform(0.05, 0.22)), 1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r_o, float(rng.uniform(0.68, 0.97)), 1, lineType=_cv2.LINE_AA)
            # depressed bowl
            r_i = max(1, r_o - 1)
            _cv2.circle(M, (cx, cy), r_i, float(rng.uniform(0.08, 0.28)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r_i, float(rng.uniform(0.55, 0.85)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r_i, float(rng.uniform(0.10, 0.32)), -1, lineType=_cv2.LINE_AA)
            # bright glint speck on rim edge
            ang_g = float(rng.uniform(0, 2 * np.pi))
            gx = int(np.clip(cx + np.cos(ang_g) * r_o, 0, w - 1))
            gy = int(np.clip(cy + np.sin(ang_g) * r_o, 0, h - 1))
            _cv2.circle(M, (gx, gy), max(1, int(scale)), float(rng.uniform(0.88, 0.99)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (gx, gy), max(1, int(scale)), float(rng.uniform(0.80, 0.99)), -1, lineType=_cv2.LINE_AA)

    # 7) CARBON FLECKS â€” dense per-pixel INDEPENDENT M/R/CC
    n_fl = max(6500, int(h * w / 110))
    fy = rng.integers(0, h, n_fl); fx = rng.integers(0, w, n_fl)
    M[fy, fx]  = rng.uniform(0.20, 0.95, n_fl).astype(np.float32)
    R[fy, fx]  = rng.uniform(0.08, 0.85, n_fl).astype(np.float32)
    CC[fy, fx] = rng.uniform(0.20, 0.96, n_fl).astype(np.float32)

    out = np.stack([np.clip(M, 0, 1), np.clip(R, 0, 1), np.clip(CC, 0, 1)], axis=-1).astype(np.float32)
    return _sm_scale(out, sm)
spec_carbon_wet_layup._spb_concept_complete = True


def spec_kevlar_weave(shape, seed, sm, **kwargs):
    """Bright yellow-aramid Kevlar weave â€” 2x2 twill, fine 8-12 px bundles.

    identity: An aramid Kevlar twill fabric â€” fine 8-12 px fiber bundles
    woven in a 2x2 twill rule with per-bundle INDEPENDENT continuous M
    (low â€” dielectric), R (variable matte) and CC (dull to silky) values,
    micro-filament striations running along each bundle's long axis,
    short bright aramid hairs catching light, resin pockets between
    bundles and dense filament flecks for fine pigment diversity.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 7491)
    scale = max(min(h, w) / 2048.0, 0.25)
    yy = np.arange(h, dtype=np.float32)[:, None]
    xx = np.arange(w, dtype=np.float32)[None, :]
    bundle_px = max(8.0, 10.0 * scale)
    def _fbm(off, sigma):
        if _CV2_OK:
            sh = max(64, h // 10); sw = max(64, w // 10)
            n = np.random.default_rng(int(seed) + off).random((sh, sw)).astype(np.float32)
            b = _cv2.GaussianBlur(n, (0, 0), sigmaX=sigma, sigmaY=sigma)
            return _normalize(_cv2.resize(b, (w, h), interpolation=_cv2.INTER_CUBIC).astype(np.float32))
        return _normalize(multi_scale_noise(shape, [20, 40], [0.6, 0.4], int(seed) + off))
    # Kevlar base â€” dielectric so M is LOW. R variable matte. CC variable.
    M = (0.18 + (_fbm(7501, 5.0) - 0.5) * 0.16).astype(np.float32)
    R_ch = (0.62 + (_fbm(7503, 5.0) - 0.5) * 0.26).astype(np.float32)
    CC = (0.45 + (_fbm(7505, 5.0) - 0.5) * 0.26).astype(np.float32)
    # 2x2 twill â€” bundles step over 2 in one direction, under 2 in other
    bu = np.floor(xx / bundle_px).astype(np.int32)
    bv = np.floor(yy / bundle_px).astype(np.int32)
    # 2x2 twill rule: top fiber when (bu - bv) mod 4 in {0,1}, else bottom
    twill = (((bu - bv) % 4) < 2).astype(np.float32)
    def _hash01(a, b, off):
        h_arr = (a.astype(np.int64) * 73856093) ^ (b.astype(np.int64) * 19349663) ^ (int(seed) + off)
        return ((h_arr & 0xFFFF).astype(np.float32) / 65535.0)
    # Per-bundle independent values â€” M LOW range (Kevlar dielectric), R wide matte, CC wide
    bun_M = (0.08 + _hash01(bu, bv, 1) * 0.35).astype(np.float32)  # M LOW
    bun_R = (0.30 + _hash01(bu, bv, 2) * 0.65).astype(np.float32)  # R variable matte
    bun_CC = (0.10 + _hash01(bu, bv, 3) * 0.85).astype(np.float32)  # CC dull to silky
    # Bundle profile crown
    uf = ((xx / bundle_px) % 1.0) - 0.5
    vf = ((yy / bundle_px) % 1.0) - 0.5
    crown_u = np.exp(-(uf * 2.4) ** 2)
    crown_v = np.exp(-(vf * 2.4) ** 2)
    top = crown_u * twill + crown_v * (1.0 - twill)
    M = M * (1.0 - top) + bun_M * top
    R_ch = R_ch * (1.0 - top) + bun_R * top
    CC = CC * (1.0 - top) + bun_CC * top
    # Micro-filament striations â€” long axis of bundle
    fib_freq = (2.0 * np.pi / max(bundle_px * 0.4, 2.0))
    fib_warp = (np.sin(yy * fib_freq) * 0.5 + 0.5) * crown_u
    fib_weft = (np.sin(xx * fib_freq) * 0.5 + 0.5) * crown_v
    fiber_mod = (fib_warp * twill + fib_weft * (1.0 - twill)).astype(np.float32)
    M = np.clip(M + (fiber_mod - 0.5) * 0.08, 0, 1)
    R_ch = np.clip(R_ch + (fiber_mod - 0.5) * 0.12, 0, 1)
    CC = np.clip(CC + (fiber_mod - 0.5) * 0.10, 0, 1)
    if _CV2_OK:
        # Aramid filament strands â€” short bright streaks
        n_str = max(6000, int(h * w / 110))
        for _ in range(n_str):
            cx = rng.uniform(2, w - 2); cy = rng.uniform(2, h - 2)
            length = float(rng.uniform(4.0, 12.0) * scale)
            # Pick warp or weft direction at this point
            bui = int(np.clip(cx / bundle_px, 0, 9999)); bvi = int(np.clip(cy / bundle_px, 0, 9999))
            tdir = ((bui - bvi) % 4) < 2
            a = 0.0 if tdir else (np.pi * 0.5)
            a += float(rng.normal(0.0, 0.05))
            x0s = int(cx - np.cos(a) * length * 0.5)
            y0s = int(cy - np.sin(a) * length * 0.5)
            x1s = int(cx + np.cos(a) * length * 0.5)
            y1s = int(cy + np.sin(a) * length * 0.5)
            _cv2.line(M, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.08, 0.40)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(R_ch, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.30, 0.85)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.15, 0.90)), 1, lineType=_cv2.LINE_AA)
        # Resin pockets between bundles
        n_resin = max(1800, int(h * w / 600))
        for _ in range(n_resin):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            rr = max(1, int(rng.uniform(1.5, 3.5) * scale))
            _cv2.circle(CC, (cx, cy), rr, float(rng.uniform(0.65, 0.95)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R_ch, (cx, cy), rr, float(rng.uniform(0.15, 0.45)), -1, lineType=_cv2.LINE_AA)
        # Filament flecks
        n_fl = max(6000, int(h * w / 90))
        fy = rng.integers(0, h, n_fl); fx = rng.integers(0, w, n_fl)
        M[fy, fx] = np.maximum(M[fy, fx], rng.uniform(0.08, 0.42, n_fl).astype(np.float32))
        R_ch[fy, fx] = np.minimum(R_ch[fy, fx], rng.uniform(0.20, 0.85, n_fl).astype(np.float32))
        CC[fy, fx] = np.maximum(CC[fy, fx], rng.uniform(0.10, 0.92, n_fl).astype(np.float32))
    out = np.stack([np.clip(M, 0, 1), np.clip(R_ch, 0, 1), np.clip(CC, 0, 1)], axis=2).astype(np.float32)
    if sm != 1.0:
        out = out * float(sm) + 0.5 * (1.0 - float(sm))
    return np.clip(out, 0, 1).astype(np.float32)


def spec_fiberglass_chopped(shape, seed, sm, num_strands=600, **kwargs):
    """spec_fiberglass_chopped.

    identity: Round-6 creative rebuild â€” true chopped-strand fiberglass MAT
    where the HERO motif is interlocking BUNDLED clusters of fibers. Each
    "chop cluster" is 6-14 parallel-ish fibers grouped together with a
    micro-rotation, like real CSM mat where the chopper-gun lays down
    overlapping bundles at random angles. Five layered tiers:
    (A) 250-400 chop CLUSTERS (the hero â€” each cluster is a tight bundle),
    (B) thin glass mono-filaments scattered between clusters,
    (C) resin-puddle micro-domes (5-10 px ovals with bright CC),
    (D) trapped air bubbles (1-3 px) with very high CC,
    (E) cool-tinted resin pinpoint sparkle. Wide INDEPENDENT M/R/CC per
    primitive â€” clusters often share base hue then drift per-fiber.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 2705)
    mn = float(min(h, w))
    scale = max(mn / 256.0, 0.6)

    # Resin substrate with translucent zone variation
    grain = _gauss(rng.random((h, w)).astype(np.float32), sigma=max(mn / 90.0, 1.0))
    zone = _gauss(rng.random((h, w)).astype(np.float32), sigma=max(mn / 22.0, 2.0))
    grain = _normalize(grain * 0.55 + zone * 0.45)
    tint = _gauss(rng.random((h, w)).astype(np.float32), sigma=max(mn / 30.0, 1.5))
    tint = _normalize(tint)

    M = (0.32 + (grain - 0.5) * 0.22 + (tint - 0.5) * 0.10).astype(np.float32)
    R_ch = (0.60 + (1.0 - grain) * 0.22 - (tint - 0.5) * 0.08).astype(np.float32)
    CC = (0.38 + (grain - 0.5) * 0.18 + (tint - 0.5) * 0.14).astype(np.float32)

    if _CV2_OK:
        # HERO PASS A â€” chop CLUSTERS (bundled fibers in tight groups)
        n_clusters = int(np.clip(420 * scale * scale, 250, 900))
        for _ in range(n_clusters):
            ccx = float(rng.uniform(0, w))
            ccy = float(rng.uniform(0, h))
            base_ang = float(rng.uniform(0, 2 * np.pi))
            cluster_len = float(rng.uniform(10.0, 22.0) * scale)
            n_fibers = int(rng.integers(5, 15))
            # cluster shares a base hue then drifts per fiber
            base_M = float(rng.uniform(0.45, 0.92))
            base_R = float(rng.uniform(0.08, 0.36))
            base_CC = float(rng.uniform(0.42, 0.95))
            for _f in range(n_fibers):
                # micro-rotate around base angle
                ang = base_ang + float(rng.uniform(-0.35, 0.35))
                # perpendicular offset for parallel-ish bundle look
                perp = float(rng.uniform(-3.5, 3.5)) * scale
                px = perp * np.cos(base_ang + np.pi * 0.5)
                py = perp * np.sin(base_ang + np.pi * 0.5)
                length = cluster_len + float(rng.uniform(-3.0, 4.0)) * scale
                x_a = int(ccx + px - np.cos(ang) * length * 0.5)
                y_a = int(ccy + py - np.sin(ang) * length * 0.5)
                x_b = int(ccx + px + np.cos(ang) * length * 0.5)
                y_b = int(ccy + py + np.sin(ang) * length * 0.5)
                vM = float(np.clip(base_M + rng.uniform(-0.18, 0.18), 0.10, 0.99))
                vR = float(np.clip(base_R + rng.uniform(-0.10, 0.18), 0.04, 0.55))
                vCC = float(np.clip(base_CC + rng.uniform(-0.18, 0.16), 0.10, 0.99))
                _cv2.line(M, (x_a, y_a), (x_b, y_b), vM, 1, lineType=_cv2.LINE_AA)
                _cv2.line(R_ch, (x_a, y_a), (x_b, y_b), vR, 1, lineType=_cv2.LINE_AA)
                _cv2.line(CC, (x_a, y_a), (x_b, y_b), vCC, 1, lineType=_cv2.LINE_AA)

        # PASS B â€” solo mono-filaments scattered between clusters
        n_solo = int(np.clip(2400 * scale * scale, 1600, 7000))
        for _ in range(n_solo):
            cx_s = float(rng.uniform(0, w))
            cy_s = float(rng.uniform(0, h))
            length = float(rng.uniform(8.0, 18.0) * scale)
            ang = float(rng.uniform(0, 2 * np.pi))
            x_a = int(cx_s - np.cos(ang) * length * 0.5)
            y_a = int(cy_s - np.sin(ang) * length * 0.5)
            x_b = int(cx_s + np.cos(ang) * length * 0.5)
            y_b = int(cy_s + np.sin(ang) * length * 0.5)
            _cv2.line(M, (x_a, y_a), (x_b, y_b), float(rng.uniform(0.30, 0.94)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(R_ch, (x_a, y_a), (x_b, y_b), float(rng.uniform(0.05, 0.40)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (x_a, y_a), (x_b, y_b), float(rng.uniform(0.35, 0.96)), 1, lineType=_cv2.LINE_AA)

        # PASS C â€” resin-puddle micro-domes (oval pools of resin sitting on top)
        n_pud = int(np.clip(450 * scale * scale, 280, 1200))
        for _ in range(n_pud):
            cx_p = int(rng.uniform(0, w))
            cy_p = int(rng.uniform(0, h))
            rx = max(2, int(rng.uniform(3.0, 6.0) * scale))
            ry = max(2, int(rng.uniform(2.0, 5.0) * scale))
            ang_deg = float(rng.uniform(0, 180))
            _cv2.ellipse(CC, (cx_p, cy_p), (rx, ry), ang_deg, 0, 360,
                         float(rng.uniform(0.65, 0.98)), -1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(R_ch, (cx_p, cy_p), (rx, ry), ang_deg, 0, 360,
                         float(rng.uniform(0.18, 0.46)), -1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(M, (cx_p, cy_p), (rx, ry), ang_deg, 0, 360,
                         float(rng.uniform(0.20, 0.55)), -1, lineType=_cv2.LINE_AA)

        # PASS D â€” trapped air bubbles (bright CC, mid R, low M)
        n_bub = int(np.clip(900 * scale * scale, 500, 2400))
        for _ in range(n_bub):
            cx_b = int(rng.uniform(0, w))
            cy_b = int(rng.uniform(0, h))
            rr = int(max(1, rng.uniform(1.0, 3.0)))
            _cv2.circle(CC, (cx_b, cy_b), rr, float(rng.uniform(0.82, 0.99)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R_ch, (cx_b, cy_b), rr, float(rng.uniform(0.22, 0.45)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(M, (cx_b, cy_b), rr, float(rng.uniform(0.25, 0.55)), -1, lineType=_cv2.LINE_AA)

    # PASS E â€” resin pinpoint sparkle carpet (vectorized)
    n_fleck = int(np.clip(mn * mn / 60.0, 3000, 14000))
    fy = rng.integers(0, h, size=n_fleck)
    fx = rng.integers(0, w, size=n_fleck)
    M[fy, fx] = rng.uniform(0.55, 0.97, size=n_fleck).astype(np.float32)
    R_ch[fy, fx] = rng.uniform(0.06, 0.36, size=n_fleck).astype(np.float32)
    CC[fy, fx] = rng.uniform(0.42, 0.96, size=n_fleck).astype(np.float32)

    # R6 TICK 54 SECOND-PASS HERO â€” RESIN-GLOSS POOL SHEETS w/ FIBER-KNOT FOSSILS
    # 3-8 irregular ultra-bright wet-resin pools (12-22 px diam) sitting on
    # top of the chopped mat where extra resin pooled deep â€” ultra-high CC,
    # very low R. Each pool has 4-9 trapped fiber-knot fossils inside
    # (tiny 1-2 px specks with bright M & varying chroma) â€” like fly-in-amber.
    if _CV2_OK:
        n_pool = int(np.clip(6 * scale, 3, 12))
        for _ in range(n_pool):
            pcx = int(rng.uniform(0.06, 0.94) * w)
            pcy = int(rng.uniform(0.06, 0.94) * h)
            n_lobe = int(rng.integers(3, 6))
            pool_M = float(rng.uniform(0.18, 0.40))
            pool_R = float(rng.uniform(0.04, 0.14))
            pool_CC = float(rng.uniform(0.85, 0.99))
            knot_seed_pts = []
            for li in range(n_lobe):
                ang = float(rng.uniform(0, 2 * np.pi))
                off = float(rng.uniform(0, 5.0)) * scale
                lcx = int(pcx + np.cos(ang) * off)
                lcy = int(pcy + np.sin(ang) * off)
                rx = max(3, int(rng.uniform(6.0, 11.0) * scale))
                ry = max(3, int(rng.uniform(5.0, 10.0) * scale))
                aa = float(rng.uniform(0, 180))
                _cv2.ellipse(M,    (lcx, lcy), (rx, ry), aa, 0, 360, pool_M, -1, lineType=_cv2.LINE_AA)
                _cv2.ellipse(R_ch, (lcx, lcy), (rx, ry), aa, 0, 360, pool_R, -1, lineType=_cv2.LINE_AA)
                _cv2.ellipse(CC,   (lcx, lcy), (rx, ry), aa, 0, 360, pool_CC, -1, lineType=_cv2.LINE_AA)
                knot_seed_pts.append((lcx, lcy, max(rx, ry)))
            # trapped fiber-knot fossils inside pool
            for (kcx, kcy, kr) in knot_seed_pts:
                n_knot = int(rng.integers(4, 10))
                for _k in range(n_knot):
                    ka = float(rng.uniform(0, 2 * np.pi))
                    kd = float(rng.uniform(0.0, 0.85)) * kr
                    knx = int(kcx + np.cos(ka) * kd)
                    kny = int(kcy + np.sin(ka) * kd)
                    if 0 <= knx < w and 0 <= kny < h:
                        kbr = max(1, int(rng.uniform(1.0, 2.4) * scale))
                        _cv2.circle(M,    (knx, kny), kbr, float(rng.uniform(0.55, 0.99)), -1, lineType=_cv2.LINE_AA)
                        _cv2.circle(R_ch, (knx, kny), kbr, float(rng.uniform(0.08, 0.38)), -1, lineType=_cv2.LINE_AA)
                        _cv2.circle(CC,   (knx, kny), kbr, float(rng.uniform(0.40, 0.95)), -1, lineType=_cv2.LINE_AA)

    # R6-TICK56 NEW HERO â€” SWIRL-CURE FLOW LINES.
    # Long sinuous curved resin-flow rivers swept by the squeegee during
    # lay-up â€” 8-18 polyline strokes spanning 60-140 px each, with a slight
    # CC sheen along the spine. Real CSM has these subtle flow signatures.
    if _CV2_OK:
        n_swirl = int(rng.integers(8, 19))
        for _ in range(n_swirl):
            cx = float(rng.uniform(0.05, 0.95) * w)
            cy = float(rng.uniform(0.05, 0.95) * h)
            base_ang = float(rng.uniform(0, 2 * np.pi))
            seg_len = float(rng.uniform(6.0, 10.0) * scale)
            n_seg = int(rng.integers(10, 18))
            curl = float(rng.uniform(-0.18, 0.18))  # gentle curve
            ang = base_ang
            swirl_M = float(rng.uniform(0.32, 0.62))
            swirl_R = float(rng.uniform(0.15, 0.32))
            swirl_CC = float(rng.uniform(0.62, 0.92))
            for _s in range(n_seg):
                nx = cx + np.cos(ang) * seg_len
                ny = cy + np.sin(ang) * seg_len
                _cv2.line(M,    (int(cx), int(cy)), (int(nx), int(ny)),
                          swirl_M + float(rng.uniform(-0.05, 0.05)), 1, lineType=_cv2.LINE_AA)
                _cv2.line(R_ch, (int(cx), int(cy)), (int(nx), int(ny)),
                          swirl_R + float(rng.uniform(-0.04, 0.04)), 1, lineType=_cv2.LINE_AA)
                _cv2.line(CC,   (int(cx), int(cy)), (int(nx), int(ny)),
                          swirl_CC + float(rng.uniform(-0.06, 0.06)), 1, lineType=_cv2.LINE_AA)
                cx, cy = nx, ny
                ang += curl + float(rng.normal(0, 0.06))

    out = np.stack([M, R_ch, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
spec_fiberglass_chopped._spb_concept_complete = True


def spec_woven_dyneema(shape, seed, sm, grid_spacing=5.0, **kwargs):
    """spec_woven_dyneema.

    identity: R6-CORRECTIVE for owner KEEP-but-could-be-better. A tight
    Dyneema/UHMWPE ballistic weave at 5-6 px ribbon pitch â€” but pushed
    further: SHARPER ribbon contrast, WIDER per-ribbon chroma so adjacent
    ribbons read with iridescent silver/champagne/steel-blue/oyster-pearl
    variety, HOTTER glint hairlines (brighter M peak, lower R) for that
    UHMWPE slick reflection. Adds crossover SHEEN PATCHES â€” small bright
    oval reflection blobs (5-9 px) at random weave crossings as the hero
    pattern motif. Stacked feature types: (a) per-ribbon CONTINUOUS M/R/CC
    diagonal field, (b) perpendicular braid fibers at +72deg, (c) doubled
    moire iridescence with 2 chroma sub-bands, (d) HOT fiber-glint
    hairlines, (e) NEW crossover sheen oval blobs (HERO), (f) fiber knot
    specks 1-3 px, (g) micro fiber-lint single pixels. NO panel-scale;
    primitives 1-9 px. Per-feature INDEPENDENT continuous M/R/CC uniforms.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 50311)
    mn = min(h, w); pscale = max(mn / 2048.0, 0.25)

    yy, xx = np.mgrid[0:h, 0:w].astype(np.float32)
    ribbon_period = max(4.5, mn / 380.0)  # tighter weave: ~5-6 px pitch at 2048
    fiber_period = max(2.6, mn / 620.0)
    angle = np.deg2rad(-18.0)
    warp = _gauss(rng.normal(0.0, 1.0, shape).astype(np.float32),
                  sigma=max(2.0, ribbon_period * 0.55)) * ribbon_period * 0.20
    u = (xx * np.cos(angle) + yy * np.sin(angle) + warp) / ribbon_period
    v = (-xx * np.sin(angle) + yy * np.cos(angle) - warp * 0.4) / fiber_period

    # 1) RIBBON FIELD â€” sharper contrast (tighter sigma)
    ribbon = np.exp(-(((u % 1.0) - 0.5) * 3.40) ** 2).astype(np.float32)
    # 2) BRAID FIBERS â€” perpendicular bright lines
    fiber = _spb_fast_line_distance(v, 1.0, 0.14, float(seed) * 0.13)
    # 3) DOUBLE MOIRE IRIDESCENCE
    moire_a = (np.sin((u * 0.45 + v * 1.20) * np.pi * 2.0) * 0.5 + 0.5).astype(np.float32)
    moire_b = (np.sin((u * 0.90 - v * 0.65) * np.pi * 2.0) * 0.5 + 0.5).astype(np.float32)
    moire = (moire_a * 0.6 + moire_b * 0.4)
    # 4) FIBER GLINTS â€” hotter reflective hairlines along ribbon crests
    glints = _spb_fast_line_distance(u + np.sin(v * 4.0) * 0.055, 0.26, 0.040, float(seed) * 0.19)

    # Per-ribbon INDEPENDENT continuous M/R/CC uniforms with WIDER chroma sweep
    ribbon_idx = np.floor(u).astype(np.int32)
    base = int(ribbon_idx.min()); n_rib = int(ribbon_idx.max() - base + 2)
    rib_M  = rng.uniform(0.42, 0.97, n_rib).astype(np.float32)
    rib_R  = rng.uniform(0.04, 0.42, n_rib).astype(np.float32)
    rib_CC = rng.uniform(0.10, 0.92, n_rib).astype(np.float32)
    idx_norm = ribbon_idx - base
    pM = rib_M[idx_norm]; pR = rib_R[idx_norm]; pCC = rib_CC[idx_norm]

    # Stronger ribbon push, hotter glint pop
    M = (0.28 + ribbon * (pM - 0.28) + glints * 0.28 + (moire - 0.5) * 0.12).astype(np.float32)
    R = (0.56 - ribbon * (0.56 - pR) - glints * 0.30 + fiber * 0.10).astype(np.float32)
    CC = (0.38 + (moire - 0.5) * 0.40 + ribbon * (pCC - 0.38) * 0.60 + fiber * 0.14).astype(np.float32)

    if _CV2_OK:
        # 5) CROSSOVER SHEEN OVAL BLOBS â€” HERO bright reflection patches 5-9 px
        n_sheen = int(np.clip(380 * (mn / 256.0) ** 0.6, 140, 1800))
        for _ in range(n_sheen):
            cx = int(rng.integers(2, w - 2)); cy = int(rng.integers(2, h - 2))
            ax = max(2, int(rng.uniform(3.0, 5.0) * pscale))
            ay = max(1, int(ax * float(rng.uniform(0.45, 0.75))))
            ang_deg = float(rng.uniform(-32, -12))  # roughly along ribbon angle
            _cv2.ellipse(M, (cx, cy), (ax, ay), ang_deg, 0, 360, float(rng.uniform(0.75, 0.97)), -1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(R, (cx, cy), (ax, ay), ang_deg, 0, 360, float(rng.uniform(0.04, 0.22)), -1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(CC, (cx, cy), (ax, ay), ang_deg, 0, 360, float(rng.uniform(0.45, 0.95)), -1, lineType=_cv2.LINE_AA)

        # 6) FIBER KNOT SPECKS â€” 1-3 px
        n_knot = int(np.clip(4400 * (mn / 2048.0) ** 2, 1500, 9500))
        for _ in range(n_knot):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            r_s = max(1, int(float(rng.uniform(1.0, 2.4)) * pscale))
            _cv2.circle(M, (cx, cy), r_s, float(rng.uniform(0.50, 0.96)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r_s, float(rng.uniform(0.04, 0.30)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r_s, float(rng.uniform(0.16, 0.92)), -1, lineType=_cv2.LINE_AA)

    # 7) MICRO LINT â€” single-pixel fiber lint
    n_fl = int(np.clip(3200 * (mn / 2048.0) ** 2, 1100, 8000))
    fy = rng.integers(0, h, n_fl); fx = rng.integers(0, w, n_fl)
    M[fy, fx] = np.maximum(M[fy, fx], rng.uniform(0.55, 0.97, n_fl).astype(np.float32))
    R[fy, fx] = np.minimum(R[fy, fx], rng.uniform(0.06, 0.34, n_fl).astype(np.float32))
    CC[fy, fx] = np.maximum(CC[fy, fx], rng.uniform(0.20, 0.92, n_fl).astype(np.float32))

    out = np.stack([np.clip(M, 0, 1), np.clip(R, 0, 1), np.clip(CC, 0, 1)], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)


spec_woven_dyneema._spb_concept_complete = True


def spec_mesh_perforated(shape, seed, sm, hole_spacing=18.0, hole_radius_frac=0.38, **kwargs):
    """spec_mesh_perforated â€” R6 CREATIVE rebuild (tick 78: MOIRE GHOST GRID).

    identity: A TWO-LAYER perforated grille â€” front sheet stamped with
    hex-packed circular holes (8-12 px pitch, void dark inside) PLUS a
    second, offset half-pitch subgrid of SMALLER counter-pierced
    micro-holes (4-6 px) that reads as parallax depth. Inside each hole,
    a subtle SHADOW DROP gradient (top brighter, bottom darker) sells
    the recessed cavity. Around each large hole, a STAMPED CHAMFER RIM
    (luminous lip) and per-hole INDEPENDENT M/R/CC tint so neighbor holes
    read as different metal sheens (brass, steel, aluminum chroma mix).
    Decorating the LANDS between holes: short tangential brushing strokes
    (4-10 px in dominant horizontal direction), burr-bead bright dots
    (1-3 px), and a sparse glint-arc sprinkle (3-pt droplet arcs) reading
    as machine-polish micro-marks. Full canvas coverage, no edge anchor.

    NEW HERO (tick 78): MOIRE INTERFERENCE GHOST GRID. A faint secondary
    rotated hex point grid (~17 deg offset, slightly different pitch)
    beat-interferes with the primary grid, producing low-frequency
    interference fringes ONLY visible as subtle 24-72 px periodic CC/M
    waves. Optical-illusion category: the eye reads the same plate as
    having both a real hex perforation AND a "ghost" layer underneath.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 10532)
    yy, xx = np.mgrid[0:h, 0:w].astype(np.float32)
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)

    # 1) PRIMARY HEX HOLE GRID
    spacing = max(9.0, mn / 26.0)
    row = np.floor(yy / spacing).astype(np.int32)
    col = np.floor((xx - (row & 1) * spacing * 0.50) / spacing).astype(np.int32)
    cx = (col + 0.5) * spacing + (row & 1) * spacing * 0.50
    cy = (row + 0.5) * spacing
    dx = xx - cx; dy = yy - cy
    dist = np.sqrt(dx * dx + dy * dy)
    radius = spacing * (0.30 + 0.04 * np.sin((col * 0.91 + row * 1.37 + int(seed)) * 1.7))
    edge_soft = max(1.2, spacing * 0.10)
    inside_t = np.clip((radius - dist) / edge_soft, 0.0, 1.0)
    inside = inside_t * inside_t * (3.0 - 2.0 * inside_t)
    chamfer = np.exp(-((dist - radius) ** 2) / (2.0 * max(1.0, spacing * 0.075) ** 2))
    # Shadow drop inside hole: top bright, bottom dark
    norm_dy = np.clip((dy + radius) / (2 * np.clip(radius, 1.0, None)), 0.0, 1.0)
    drop_shadow = norm_dy * inside

    # 2) PER-HOLE CHROMA TINT (Weyl hash)
    col64 = col.astype(np.uint64) & np.uint64(0xFFFFFFFF)
    row64 = row.astype(np.uint64) & np.uint64(0xFFFFFFFF)
    seed64 = np.uint64(int(seed) & 0xFFFFFFFF)
    hsh = (col64 * np.uint64(0x9E3779B1)) ^ (row64 * np.uint64(0x85EBCA77)) ^ seed64
    tint_M = ((hsh * np.uint64(2654435761)) & np.uint64(0xFFFFFF)).astype(np.float32) / float(0xFFFFFF)
    tint_R = ((hsh * np.uint64(1597334677)) & np.uint64(0xFFFFFF)).astype(np.float32) / float(0xFFFFFF)
    tint_C = ((hsh * np.uint64(374761393)) & np.uint64(0xFFFFFF)).astype(np.float32) / float(0xFFFFFF)

    # 3) SECONDARY MICRO-HOLE SUBGRID (offset half-pitch, smaller holes)
    sub_sp = spacing * 0.5
    sub_row = np.floor((yy - sub_sp * 0.5) / sub_sp).astype(np.int32)
    sub_col = np.floor(((xx - sub_sp * 0.5) - (sub_row & 1) * sub_sp * 0.5) / sub_sp).astype(np.int32)
    sub_cx = (sub_col + 0.5) * sub_sp + (sub_row & 1) * sub_sp * 0.5 + sub_sp * 0.5
    sub_cy = (sub_row + 0.5) * sub_sp + sub_sp * 0.5
    sub_dist = np.sqrt((xx - sub_cx) ** 2 + (yy - sub_cy) ** 2)
    sub_radius = sub_sp * 0.18
    sub_inside_t = np.clip((sub_radius - sub_dist) / max(0.9, sub_sp * 0.10), 0.0, 1.0)
    sub_inside = sub_inside_t * sub_inside_t * (3.0 - 2.0 * sub_inside_t)
    # only mask sub-holes where they don't overlap the primary holes
    sub_inside = sub_inside * (1.0 - inside)

    # 4) BASE LAND â€” polished metal w/ FBM grain
    g1 = _normalize(multi_scale_noise(shape, [2.0, 5.5, 12.0, 22.0], [0.34, 0.30, 0.22, 0.14], int(seed) + 10532))
    g2 = _normalize(multi_scale_noise(shape, [2.5, 6.5, 13.0, 24.0], [0.34, 0.30, 0.22, 0.14], int(seed) + 10533))
    g3 = _normalize(multi_scale_noise(shape, [3.0, 7.0, 14.0, 26.0], [0.34, 0.30, 0.22, 0.14], int(seed) + 10534))
    M_land  = 0.78 + (g1 - 0.5) * 0.18 + (tint_M - 0.5) * 0.08
    R_land  = 0.22 + (g2 - 0.5) * 0.16 + (tint_R - 0.5) * 0.06
    CC_land = 0.18 + (g3 - 0.5) * 0.18 + (tint_C - 0.5) * 0.08

    # Hole void: tinted dark with shadow drop
    M_hole  = 0.08 + (tint_M - 0.5) * 0.10 - drop_shadow * 0.12
    R_hole  = 0.86 + (g2 - 0.5) * 0.06
    CC_hole = 0.92 + (g3 - 0.5) * 0.05

    M  = (M_land * (1.0 - inside) + M_hole * inside).astype(np.float32)
    R  = (R_land * (1.0 - inside) + R_hole * inside).astype(np.float32)
    CC = (CC_land * (1.0 - inside) + CC_hole * inside).astype(np.float32)

    # Sub-holes: dark micro pierce
    M  = M  - sub_inside * 0.55
    R  = R  + sub_inside * 0.40
    CC = CC + sub_inside * 0.22

    # 5) CHAMFER RING â€” bright stamped lip
    M = np.clip(M + chamfer * 0.32, 0.0, 1.0)
    R = np.clip(R - chamfer * 0.32, 0.0, 1.0)
    CC = np.clip(CC - chamfer * 0.28, 0.0, 1.0)

    # R6 OWNER-REBUILD: "Too messy". Drastically reduced density on every
    # decorative pass. Removed glint-arc sprinkle and dust flecks entirely.
    if _CV2_OK:
        # 6) BRUSHED LAND STROKES â€” 1/3 prior density, TIGHT chroma jitter
        n_br = int(np.clip(700 * (mn / 2048.0) ** 2, 240, 1800))
        for _ in range(n_br):
            xp = rng.uniform(2, w - 2); yp = rng.uniform(2, h - 2)
            length = float(rng.uniform(4.0, 10.0) * scale)
            ang = float(rng.uniform(-0.32, 0.32))
            x1p = int(xp + np.cos(ang) * length)
            y1p = int(yp + np.sin(ang) * length)
            _cv2.line(M, (int(xp), int(yp)), (x1p, y1p), float(np.clip(0.82 + rng.uniform(-0.05, 0.05), 0, 1)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(R, (int(xp), int(yp)), (x1p, y1p), float(np.clip(0.16 + rng.uniform(-0.04, 0.04), 0, 1)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (int(xp), int(yp)), (x1p, y1p), float(np.clip(0.14 + rng.uniform(-0.04, 0.04), 0, 1)), 1, lineType=_cv2.LINE_AA)

        # 7) BURR-BEAD DOTS â€” 1/3 prior density
        n_burr = int(np.clip(400 * (mn / 2048.0) ** 2, 140, 1000))
        for _ in range(n_burr):
            cxp = int(rng.integers(0, w)); cyp = int(rng.integers(0, h))
            r_p = max(1, int(rng.uniform(1.0, 2.0) * scale))
            _cv2.circle(M, (cxp, cyp), r_p, float(np.clip(0.88 + rng.uniform(-0.05, 0.05), 0, 1)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cxp, cyp), r_p, float(np.clip(0.14 + rng.uniform(-0.04, 0.04), 0, 1)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cxp, cyp), r_p, float(np.clip(0.12 + rng.uniform(-0.04, 0.04), 0, 1)), -1, lineType=_cv2.LINE_AA)

        # 8) (REMOVED) glint-arc droplet sprinkles â€” were a noisy element.

    # 9b) NEW HERO (tick 78) â€” MOIRE INTERFERENCE GHOST GRID.
    # Secondary hex point grid rotated ~17 deg with slightly larger pitch.
    # The beat between primary and secondary lattices produces 24-72 px
    # interference fringes that subtly modulate CC and M across the canvas.
    ghost_ang = float(rng.uniform(0.26, 0.32))  # ~15-18 deg
    cos_g = float(np.cos(ghost_ang)); sin_g = float(np.sin(ghost_ang))
    ghost_pitch = spacing * float(rng.uniform(1.06, 1.13))
    xr_g = xx * cos_g + yy * sin_g
    yr_g = -xx * sin_g + yy * cos_g
    row_g = np.floor(yr_g / ghost_pitch).astype(np.float32)
    col_g = np.floor((xr_g - (row_g.astype(np.int32) & 1) * ghost_pitch * 0.50) / ghost_pitch).astype(np.float32)
    cx_g = (col_g + 0.5) * ghost_pitch + (row_g.astype(np.int32) & 1) * ghost_pitch * 0.50
    cy_g = (row_g + 0.5) * ghost_pitch
    dx_g = xr_g - cx_g; dy_g = yr_g - cy_g
    dist_g = np.sqrt(dx_g * dx_g + dy_g * dy_g)
    ghost_radius = ghost_pitch * 0.18
    ghost_t = np.clip((ghost_radius - dist_g) / max(0.8, ghost_pitch * 0.10), 0.0, 1.0)
    ghost_dot = (ghost_t * ghost_t * (3.0 - 2.0 * ghost_t)).astype(np.float32)
    # subtle: only modulate where NOT inside primary hole (avoid stomping)
    ghost_alpha = 0.16 * (1.0 - inside)
    M  = np.clip(M  + (ghost_dot - 0.4) * ghost_alpha * 0.55, 0.0, 1.0)
    CC = np.clip(CC + (ghost_dot - 0.4) * ghost_alpha * 0.85, 0.0, 1.0)
    R  = np.clip(R  - (ghost_dot - 0.4) * ghost_alpha * 0.30, 0.0, 1.0)

    # 9) (REMOVED) DUST FLECKS â€” were the dominant messy element. Replaced
    # with a much lighter additive jitter that preserves base chroma.
    n_fl = max(500, int(h * w / 5500))
    fx = rng.integers(0, w, n_fl); fy = rng.integers(0, h, n_fl)
    M[fy, fx] = np.clip(M[fy, fx] + rng.uniform(-0.04, 0.04, n_fl).astype(np.float32), 0, 1)
    R[fy, fx] = np.clip(R[fy, fx] + rng.uniform(-0.03, 0.03, n_fl).astype(np.float32), 0, 1)
    CC[fy, fx] = np.clip(CC[fy, fx] + rng.uniform(-0.03, 0.03, n_fl).astype(np.float32), 0, 1)

    out = np.stack([M, R, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)


def spec_expanded_metal(shape, seed, sm, diamond_size=20.0, angle_deg=30.0, **kwargs):
    """Expanded metal diamond mesh â€” fine slit-and-stretch lath.

    identity: R6 creative rebuild â€” fine-gauge expanded-metal lath stamped
    from sheet steel. Every diamond cell is 14-22 px tall so the mesh reads
    as dense pixel-fine perforations on the panel. Multiple tiers stack: tiny
    diamond lip + interior strand glint + crossover node, short tangential
    lath striations (6-14 px), a second-order half-pitch sub-grid, dense
    mill-scale flecks (1-3 px), and per-cell INDEPENDENT continuous M/R/CC
    uniforms (ranges 0.08-0.95). R6 push: stronger node-crossover chroma
    spikes and brighter strand glint highlights for a 3D embossed lath look.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + (hash('expanded_metal_r5') % 10000))
    yy, xx = np.mgrid[0:h, 0:w].astype(np.float32)
    mn = float(min(h, w))
    scale = max(mn / 2048.0, 0.25)

    # PRIMARY DIAMOND CELL: clamp to 14-22 px (FINE feature range, per owner doctrine)
    cell_h = float(np.clip(18.0 * scale * rng.uniform(0.85, 1.15), 14.0, 22.0))
    cell_w = cell_h * rng.uniform(0.54, 0.66)
    angle = np.deg2rad(rng.uniform(22.0, 38.0))
    warp_field = _gauss(rng.random((h, w)).astype(np.float32), sigma=max(3.0, cell_h * 0.35)) * cell_h * 0.05
    xr = xx * np.cos(angle) + yy * np.sin(angle) + warp_field
    yr = -xx * np.sin(angle) + yy * np.cos(angle) - warp_field * 0.6
    u = (xr / cell_w) % 1.0
    v = (yr / cell_h) % 1.0

    diamond = np.abs(u - 0.5) + np.abs(v - 0.5)
    edge = np.exp(-((diamond - 0.50) ** 2) / (2.0 * 0.045 ** 2))
    torn_lip = np.exp(-((diamond - 0.42) ** 2) / (2.0 * 0.026 ** 2))
    node = np.exp(-(((u - 0.5) ** 2 + (v - 0.5) ** 2) / 0.018))
    interior = 1.0 - np.clip(edge + torn_lip * 0.7, 0.0, 1.0)

    # SECOND-ORDER half-pitch sub-grid (tier 2: even finer 7-11 px features)
    u2 = (xr / (cell_w * 0.5)) % 1.0
    v2 = (yr / (cell_h * 0.5)) % 1.0
    sub_diamond = np.abs(u2 - 0.5) + np.abs(v2 - 0.5)
    sub_lip = np.exp(-((sub_diamond - 0.48) ** 2) / (2.0 * 0.030 ** 2)) * 0.35

    # FINE lath striations (along rotation direction, period ~6-14 px)
    lath_per = float(np.clip(cell_w * 0.16, 3.0, 7.0))
    lath = 0.5 + 0.5 * np.sin((xr * np.pi * 2.0) / lath_per + rng.uniform(0, 2*np.pi))

    # Build channels â€” base
    R_ch = (0.30 + edge * 0.50 + node * 0.20 + torn_lip * 0.15 + sub_lip * 0.10).astype(np.float32)
    G_ch = (0.78 - edge * 0.48 - node * 0.18 - torn_lip * 0.20 + interior * 0.05 - sub_lip * 0.08).astype(np.float32)
    CC = (0.55 - edge * 0.32 - torn_lip * 0.18 + interior * 0.18 + sub_lip * 0.06).astype(np.float32)

    # Lath modulation
    R_ch += (lath - 0.5) * edge * 0.12
    G_ch -= (lath - 0.5) * edge * 0.10
    CC += (lath - 0.5) * sub_lip * 0.10

    if _CV2_OK:
        # FINE TANGENTIAL LATH STRIATIONS â€” short 6-14 px lines along grain direction
        n_lath = int(np.clip(mn * mn / 320.0, 600, 4500))
        for _ in range(n_lath):
            cx = float(rng.uniform(2, w - 2)); cy = float(rng.uniform(2, h - 2))
            # Sample edge to bias toward lath cells (but allow some on interiors)
            edge_v = float(edge[int(cy), int(cx)])
            if edge_v < 0.08 and rng.random() < 0.55:
                continue
            length = float(rng.uniform(6.0, 14.0) * scale)
            ax = float(angle + rng.uniform(-0.06, 0.06))
            dx = np.cos(ax) * length * 0.5; dy = np.sin(ax) * length * 0.5
            p0 = (int(cx - dx), int(cy - dy)); p1 = (int(cx + dx), int(cy + dy))
            # INDEPENDENT continuous uniforms per stroke â€” wider ranges
            _cv2.line(R_ch, p0, p1, float(rng.uniform(0.18, 0.95)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(G_ch, p0, p1, float(rng.uniform(0.08, 0.65)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC,  p0, p1, float(rng.uniform(0.08, 0.78)), 1, lineType=_cv2.LINE_AA)

        # DENSE MILL-SCALE FLECKS â€” 1-3 px with INDEPENDENT uniforms (wider)
        n_scale = int(np.clip(mn * mn / 180.0, 800, 7200))
        sy = rng.integers(0, h, size=n_scale)
        sx = rng.integers(0, w, size=n_scale)
        edge_at = edge[sy, sx]
        for k in range(n_scale):
            if edge_at[k] < 0.10 and rng.random() < 0.55:
                continue
            y0 = int(sy[k]); x0 = int(sx[k])
            rr = int(max(1, rng.uniform(1.0, 3.0) * scale))
            _cv2.circle(R_ch, (x0, y0), rr, float(rng.uniform(0.18, 0.95)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(G_ch, (x0, y0), rr, float(rng.uniform(0.08, 0.72)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC,   (x0, y0), rr, float(rng.uniform(0.08, 0.72)), -1, lineType=_cv2.LINE_AA)

        # HERO NODE-CROSSOVER GLINT â€” bright stamped-corner highlights at node centers
        n_node = int(np.clip(mn * mn / 280.0, 400, 4200))
        ny_ = rng.integers(0, h, size=n_node); nx_ = rng.integers(0, w, size=n_node)
        sel_n = node[ny_, nx_] > 0.45
        if np.any(sel_n):
            yi = ny_[sel_n]; xi = nx_[sel_n]
            for k in range(yi.size):
                y0 = int(yi[k]); x0 = int(xi[k])
                _cv2.circle(R_ch, (x0, y0), 1, float(rng.uniform(0.72, 0.99)), -1, lineType=_cv2.LINE_AA)
                _cv2.circle(G_ch, (x0, y0), 1, float(rng.uniform(0.05, 0.18)), -1, lineType=_cv2.LINE_AA)
                _cv2.circle(CC,   (x0, y0), 1, float(rng.uniform(0.55, 0.95)), -1, lineType=_cv2.LINE_AA)

    # SUB-PIXEL SPARKLE on node crossovers
    n_fl = int(np.clip(mn * mn / 240.0, 600, 5500))
    fy = rng.integers(0, h, n_fl); fx = rng.integers(0, w, n_fl)
    sel = node[fy, fx] > 0.30
    if np.any(sel):
        yi = fy[sel]; xi = fx[sel]
        R_ch[yi, xi] = np.maximum(R_ch[yi, xi], rng.uniform(0.65, 0.99, yi.size).astype(np.float32))
        G_ch[yi, xi] = np.minimum(G_ch[yi, xi], rng.uniform(0.05, 0.22, yi.size).astype(np.float32))
        CC[yi, xi]   = np.minimum(CC[yi, xi],   rng.uniform(0.05, 0.22, yi.size).astype(np.float32))

    out = np.stack([R_ch, G_ch, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
spec_expanded_metal._spb_concept_complete = True


def spec_chainlink_fence(shape, seed, sm, wire_spacing=16.0, wire_width_px=1.8, **kwargs):
    """spec_chainlink_fence.

    identity: Round-6 tick-50 second-pass creative rebuild â€” galvanized
    diamond-mesh chainlink panel SEEN UP CLOSE with NEW HEROES stacked
    on the prior build. The HERO grid is the Â±45Â° interlock with crisp
    3D wire ridges. NEW HERO #1: TENSION-CABLE TURNBUCKLE NODES â€” hex
    8-12 px sleeve hardware with bright torque-mark dimples cinching
    the mesh. NEW HERO #2: STORM-PUSHED MESH BULGE LENS â€” 14-22 px
    elliptical sun-lens diffraction bulges where impact warped the
    grid. Plus: knuckle junctions, spiral-wrap micro-twists, zinc
    spangle flecks, rust-bloom rosettes, barb threads, bent-wire kinks,
    sky-fleck carpet through open diamonds. Per-feature INDEPENDENT
    continuous M/R/CC. Wide 0.04-0.99 chroma spread for galvanized
    vs rust vs sky.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 46017)
    scale = max(min(h, w) / 2048.0, 0.25)
    yy = np.arange(h, dtype=np.float32)[:, None]
    xx = np.arange(w, dtype=np.float32)[None, :]
    # Tighter diamond cells for finer fingerprint
    period = max(12.0, wire_spacing * 0.85 * (1.0 + 0.25 * scale))
    u = (xx + yy) / period
    v = (xx - yy) / period
    du = np.abs((u - np.round(u)))
    dv = np.abs((v - np.round(v)))
    wire_band = (1.45 / period)
    wire_u = np.clip(1.0 - du / wire_band, 0, 1)
    wire_v = np.clip(1.0 - dv / wire_band, 0, 1)
    wire = np.maximum(wire_u, wire_v)
    # 3D under-shadow band
    shadow_band = (0.65 / period)
    shadow_u = np.clip(1.0 - np.abs((u + 0.014) - np.round(u + 0.014)) / shadow_band, 0, 1) * 0.55
    shadow_v = np.clip(1.0 - np.abs((v + 0.014) - np.round(v + 0.014)) / shadow_band, 0, 1) * 0.55
    shadow = np.maximum(shadow_u, shadow_v) * (1.0 - wire)
    # INDEPENDENT FBM per channel
    sky_M = _normalize(multi_scale_noise(shape, [3.0, 9.0, 22.0], [0.42, 0.32, 0.26], int(seed) + 4601))
    sky_R = _normalize(multi_scale_noise(shape, [3.5, 10.0, 24.0], [0.40, 0.32, 0.28], int(seed) + 4602))
    sky_CC = _normalize(multi_scale_noise(shape, [4.0, 11.0, 26.0], [0.40, 0.32, 0.28], int(seed) + 4603))
    M = (0.18 + (sky_M - 0.5) * 0.22 + wire * 0.74 - shadow * 0.22).astype(np.float32)
    R = (0.62 - (sky_R - 0.5) * 0.20 - wire * 0.52 + shadow * 0.22).astype(np.float32)
    CC = (0.40 + (sky_CC - 0.5) * 0.20 + wire * 0.46).astype(np.float32)

    if _CV2_OK:
        # 2) KNUCKLE JUNCTIONS â€” bright bulb + dark socket (3-5 px)
        n_knot = max(1400, int(h * w / 1800))
        for _ in range(n_knot):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            if wire[cy, cx] < 0.45:
                continue
            r = max(2, int(rng.uniform(2.5, 5.0) * scale))
            _cv2.circle(M, (cx, cy), r, float(rng.uniform(0.76, 0.99)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r, float(rng.uniform(0.04, 0.22)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r, float(rng.uniform(0.70, 0.97)), -1, lineType=_cv2.LINE_AA)
            # dark socket center
            _cv2.circle(M, (cx, cy), max(1, r // 2), float(rng.uniform(0.18, 0.42)), -1, lineType=_cv2.LINE_AA)

        # 3) NEW â€” SPIRAL-WRAP MICRO TICKS at knot crossings
        n_wrap = max(700, int(h * w / 3600))
        for _ in range(n_wrap):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            if wire[cy, cx] < 0.50:
                continue
            # short tangent tick
            ang = float(rng.uniform(0, 2 * np.pi))
            length = float(rng.uniform(2.0, 4.0) * scale)
            x1 = int(cx + np.cos(ang) * length); y1 = int(cy + np.sin(ang) * length)
            _cv2.line(M, (cx, cy), (x1, y1), float(rng.uniform(0.82, 0.99)), 1, lineType=_cv2.LINE_AA)

        # 4) ZINC SPANGLE FLECKS â€” bright galvanized sparkle (1-2 px)
        n_spang = max(2800, int(h * w / 900))
        for _ in range(n_spang):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            if wire[cy, cx] < 0.40:
                continue
            r = max(1, int(rng.uniform(1.0, 2.0) * scale))
            _cv2.circle(M, (cx, cy), r, float(rng.uniform(0.82, 0.99)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r, float(rng.uniform(0.04, 0.18)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r, float(rng.uniform(0.80, 0.99)), -1, lineType=_cv2.LINE_AA)

        # 5) RUST-BLOOM ROSETTES (4-8 px)
        n_rust = max(820, int(h * w / 2600))
        for _ in range(n_rust):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            if wire[cy, cx] < 0.30:
                continue
            r = max(2, int(rng.uniform(4, 8) * scale * 0.5))
            _cv2.circle(M, (cx, cy), r, float(rng.uniform(0.14, 0.44)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r, float(rng.uniform(0.70, 0.96)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r, float(rng.uniform(0.40, 0.80)), -1, lineType=_cv2.LINE_AA)

        # 6) BARB THREADS (8-14 px hairlines)
        n_barb = max(280, int(h * w / 8500))
        for _ in range(n_barb):
            cx = float(rng.uniform(4, w - 4)); cy = float(rng.uniform(4, h - 4))
            ang = float(rng.choice([np.pi * 0.25, np.pi * 0.75, np.pi * 1.25, np.pi * 1.75])) + float(rng.uniform(-0.22, 0.22))
            length = float(rng.uniform(8.0, 14.0) * scale)
            x1 = int(cx + np.cos(ang) * length); y1 = int(cy + np.sin(ang) * length)
            _cv2.line(M, (int(cx), int(cy)), (x1, y1), float(rng.uniform(0.62, 0.96)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(R, (int(cx), int(cy)), (x1, y1), float(rng.uniform(0.06, 0.28)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (int(cx), int(cy)), (x1, y1), float(rng.uniform(0.60, 0.94)), 1, lineType=_cv2.LINE_AA)

        # 7) NEW â€” BENT-WIRE KINKS: short 4-6 px disruptions of the grid
        n_kink = max(180, int(h * w / 12000))
        for _ in range(n_kink):
            cx = int(rng.integers(4, w - 4)); cy = int(rng.integers(4, h - 4))
            if wire[cy, cx] < 0.40:
                continue
            # short break line at random angle
            ang = float(rng.uniform(0, 2 * np.pi))
            length = float(rng.uniform(4.0, 6.0) * scale)
            x1 = int(cx + np.cos(ang) * length); y1 = int(cy + np.sin(ang) * length)
            _cv2.line(M, (cx, cy), (x1, y1), float(rng.uniform(0.22, 0.50)), 2, lineType=_cv2.LINE_AA)
            _cv2.line(R, (cx, cy), (x1, y1), float(rng.uniform(0.55, 0.88)), 2, lineType=_cv2.LINE_AA)

        # 7b) R6-TICK50 NEW HERO â€” TENSION-CABLE TURNBUCKLE NODES.
        # Hex-sleeved 8-12 px turnbuckles cinching the mesh, with bright
        # torque-mark dimples. Reads as heavy-duty fence hardware.
        n_turn = int(np.clip(120 * (min(h, w) / 2048.0) ** 2, 26, 240))
        for _ in range(n_turn):
            cx = int(rng.integers(8, w - 8)); cy = int(rng.integers(8, h - 8))
            rr = max(3, int(rng.uniform(4.0, 6.0) * scale))
            # Hex sleeve â€” 6 vertex polygon
            hex_pts = np.array([
                [cx + int(rr * np.cos(a)), cy + int(rr * np.sin(a))]
                for a in np.linspace(0, 2 * np.pi, 7)[:6]
            ], dtype=np.int32)
            tM = float(rng.uniform(0.62, 0.94)); tR = float(rng.uniform(0.10, 0.34)); tCC = float(rng.uniform(0.55, 0.95))
            _cv2.fillPoly(M, [hex_pts], tM, lineType=_cv2.LINE_AA)
            _cv2.fillPoly(R, [hex_pts], tR, lineType=_cv2.LINE_AA)
            _cv2.fillPoly(CC, [hex_pts], tCC, lineType=_cv2.LINE_AA)
            # dark inner core socket
            _cv2.circle(M, (cx, cy), max(1, rr // 2), float(rng.uniform(0.14, 0.38)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), max(1, rr // 2), float(rng.uniform(0.55, 0.86)), -1, lineType=_cv2.LINE_AA)
            # torque-mark dimples â€” 3 bright micro dots around the sleeve
            for tk in range(3):
                tang = float(rng.uniform(0, 2 * np.pi))
                tx = int(cx + np.cos(tang) * rr * 0.7); ty = int(cy + np.sin(tang) * rr * 0.7)
                if 0 <= tx < w and 0 <= ty < h:
                    M[ty, tx] = float(rng.uniform(0.86, 0.99))
                    CC[ty, tx] = float(rng.uniform(0.05, 0.22))

        # 7c) R6-TICK50 NEW HERO â€” STORM-PUSHED MESH BULGE LENS.
        # Subtle 14-22 px elliptical chroma bulge where impact deformed
        # the grid â€” a soft sky-bright sun-lens diffraction lens reading.
        n_bulge = int(np.clip(36 * (min(h, w) / 2048.0) ** 2, 8, 90))
        for _ in range(n_bulge):
            cx = int(rng.integers(12, w - 12)); cy = int(rng.integers(12, h - 12))
            rxb = max(7, int(rng.uniform(7.0, 11.0) * scale))
            ryb = max(5, int(rxb * float(rng.uniform(0.55, 0.95))))
            rot = float(rng.uniform(0, 180))
            # soft ring lens â€” bright outer, dim inner halo
            _cv2.ellipse(M, (cx, cy), (rxb, ryb), rot, 0, 360, float(rng.uniform(0.48, 0.78)), 1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(R, (cx, cy), (rxb, ryb), rot, 0, 360, float(rng.uniform(0.20, 0.55)), 1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(CC, (cx, cy), (rxb, ryb), rot, 0, 360, float(rng.uniform(0.32, 0.85)), 1, lineType=_cv2.LINE_AA)
            # bright meridian line across the lens (diffraction line)
            ax = int(np.cos(np.radians(rot)) * rxb)
            ay = int(np.sin(np.radians(rot)) * rxb)
            _cv2.line(M, (cx - ax, cy - ay), (cx + ax, cy + ay), float(rng.uniform(0.72, 0.97)), 1, lineType=_cv2.LINE_AA)

    # 8) SKY FLECKS through open diamond holes
    n_fl = max(3600, int(h * w / 160))
    fy = rng.integers(0, h, n_fl); fx = rng.integers(0, w, n_fl)
    is_open = (wire[fy, fx] < 0.18)
    fy = fy[is_open]; fx = fx[is_open]
    if fy.size > 0:
        M[fy, fx] = np.maximum(M[fy, fx], rng.uniform(0.18, 0.58, fy.size).astype(np.float32))
        R[fy, fx] = np.maximum(R[fy, fx], rng.uniform(0.50, 0.88, fy.size).astype(np.float32))
        CC[fy, fx] = np.minimum(CC[fy, fx], rng.uniform(0.22, 0.58, fy.size).astype(np.float32))

    # 9) Wide-chroma random scatter (per the doctrine)
    for arr in (M, R, CC):
        mlo = rng.random(arr.shape) < 0.04
        mhi = rng.random(arr.shape) < 0.04
        arr[mlo] = float(rng.uniform(0.04, 0.18))
        arr[mhi] = float(rng.uniform(0.82, 0.98))

    # 10) R6-TICK56 NEW HERO â€” LICHEN-PATCH COLONIES (biology mandate).
    # 18-32 small irregular biological growth patches (10-18 px diam) on
    # shaded knot intersections â€” bumpy, cool-tinted, granular. Each patch
    # is a soft mid-CC blob with 6-14 micro pock-marks inside (the lichen
    # apothecia). Adds living organic break to the dead galvanized grid.
    if _CV2_OK:
        n_lichen = int(np.clip(28 * (min(h, w) / 2048.0) ** 2, 18, 44))
        for _ in range(n_lichen):
            cx = int(rng.integers(8, w - 8)); cy = int(rng.integers(8, h - 8))
            rx = int(rng.uniform(5.0, 9.0) * scale)
            ry = int(rng.uniform(4.0, 8.0) * scale)
            rot = float(rng.uniform(0, 180))
            # Lichen colony palette: cool grey-green to dusty cream
            lM = float(rng.uniform(0.22, 0.46))
            lR = float(rng.uniform(0.58, 0.82))
            lCC = float(rng.uniform(0.35, 0.62))
            _cv2.ellipse(M, (cx, cy), (rx, ry), rot, 0, 360, lM, -1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(R, (cx, cy), (rx, ry), rot, 0, 360, lR, -1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(CC, (cx, cy), (rx, ry), rot, 0, 360, lCC, -1, lineType=_cv2.LINE_AA)
            # Apothecia inside (the tiny reproductive cups)
            n_apo = int(rng.integers(5, 13))
            for _a in range(n_apo):
                aa = float(rng.uniform(0, 2 * np.pi))
                ad = float(rng.uniform(0, 0.8)) * max(rx, ry)
                ax = int(np.clip(cx + np.cos(aa) * ad, 0, w - 1))
                ay = int(np.clip(cy + np.sin(aa) * ad, 0, h - 1))
                M[ay, ax] = float(np.clip(lM - 0.12, 0, 1))
                R[ay, ax] = float(np.clip(lR + 0.10, 0, 1))
                CC[ay, ax] = float(np.clip(lCC + 0.08, 0, 1))

    out = np.stack([np.clip(M, 0, 1), np.clip(R, 0, 1), np.clip(CC, 0, 1)], axis=-1).astype(np.float32)
    return _validate_spec_output(_sm_scale(out, sm).astype(np.float32), "spec_chainlink_fence")
spec_chainlink_fence._spb_concept_complete = True


def spec_ballistic_weave(shape, seed=0, sm=1.0, **kwargs):
    """spec_ballistic_weave.

    identity: R6 creative rebuild â€” heavyweight aramid (Kevlar-style)
    plain weave that has TAKEN A HIT. SEVEN stacked tiers atop a thick
    triple-filament tow base: (1) tow ridge field + sub-filament
    microridge + 3 independent FBM grain fields, (2) thick-tow
    highlights (10-16 px), (3) dark interlace pits at cross-over
    valleys, (4) frayed filament splinters (8-14 px) constrained to
    axial fibers, (5) filament glint dots (1-2 px), (6) HERO 2-4
    BALLISTIC GRAZE DRAGS â€” long 28-60 px bright drag-scuffs along the
    tow grain where a round skidded across the surface, each with a
    char-darkened entry mark, AND 3-6 HERO RUPTURE BUNDLES â€” clusters
    of exploded fibers (8-14 radiating filaments 10-20 px) at impact
    points, (7) dust flecks. Widest per-feature M/R/CC uniforms for
    yellow/matte/fibrous chroma diversity.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + (hash("spec_ballistic_weave_r6") % 10000) + 70123)
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)
    cell = max(10.0, 12.0 * scale)
    yy = np.arange(h, dtype=np.float32)[:, None]; xx = np.arange(w, dtype=np.float32)[None, :]
    # 1) THICK-TOW BASE â€” wider warp/weft bands with triple sub-filament
    warp_ridge = (np.sin(xx * (2.0 * np.pi / cell)) * 0.5 + 0.5).astype(np.float32)
    weft_ridge = (np.sin(yy * (2.0 * np.pi / cell)) * 0.5 + 0.5).astype(np.float32)
    interlace = (np.cos(xx * (2.0 * np.pi / cell)) * np.cos(yy * (2.0 * np.pi / cell)) * 0.5 + 0.5).astype(np.float32)
    sub_warp = (np.sin(xx * (2.0 * np.pi / (cell / 3.0))) * 0.5 + 0.5).astype(np.float32)
    sub_weft = (np.sin(yy * (2.0 * np.pi / (cell / 3.0))) * 0.5 + 0.5).astype(np.float32)
    g1 = _normalize(multi_scale_noise(shape, [3.0, 7.0, 14.0], [0.42, 0.32, 0.26], seed + 701))
    g2 = _normalize(multi_scale_noise(shape, [4.0, 8.5, 17.0], [0.38, 0.32, 0.30], seed + 702))
    g3 = _normalize(multi_scale_noise(shape, [3.5, 7.5, 15.0], [0.40, 0.32, 0.28], seed + 703))
    # R6-loop tick (owner 6/KEEP refinement): R substrate 0.72 was producing
    # mean R 0.70 across canvas â€” too matte/yellow-magenta-leaning. Pulled to
    # 0.48 + slightly tighter weft contribution so fabric reads matte-fibrous
    # without saturating the rough axis. Feature glints unchanged.
    M = (0.20 + (warp_ridge - 0.5) * 0.18 + (sub_warp - 0.5) * 0.10 + (g1 - 0.5) * 0.12).astype(np.float32)
    R = (0.48 + (weft_ridge - 0.5) * 0.18 + (sub_weft - 0.5) * 0.10 + (g2 - 0.5) * 0.10).astype(np.float32)
    CC = (0.42 + (interlace - 0.5) * 0.20 + (g3 - 0.5) * 0.14).astype(np.float32)
    for arr in (M, R, CC):
        mlo = rng.random(arr.shape) < 0.05
        mhi = rng.random(arr.shape) < 0.05
        arr[mlo] = float(rng.uniform(0.05, 0.20))
        arr[mhi] = float(rng.uniform(0.80, 0.97))
    if _CV2_OK:
        # 2) THICK-TOW HIGHLIGHTS (10-16 px)
        n_high = int(np.clip(2520 * (mn / 2048.0) ** 2, 870, 5880))
        for _ in range(n_high):
            cx = float(rng.uniform(4, w - 4)); cy = float(rng.uniform(4, h - 4))
            horizontal = rng.random() < 0.5
            length = float(rng.uniform(10.0, 16.0) * scale)
            if horizontal:
                x0, y0 = int(cx - length * 0.5), int(cy); x1, y1 = int(cx + length * 0.5), int(cy)
                hM = float(rng.uniform(0.28, 0.62)); hR = float(rng.uniform(0.58, 0.92)); hCC = float(rng.uniform(0.28, 0.58))
            else:
                x0, y0 = int(cx), int(cy - length * 0.5); x1, y1 = int(cx), int(cy + length * 0.5)
                hM = float(rng.uniform(0.26, 0.60)); hR = float(rng.uniform(0.60, 0.94)); hCC = float(rng.uniform(0.30, 0.60))
            _cv2.line(M, (x0, y0), (x1, y1), hM, max(1, int(scale * 1.5)), lineType=_cv2.LINE_AA)
            _cv2.line(R, (x0, y0), (x1, y1), hR, max(1, int(scale * 1.5)), lineType=_cv2.LINE_AA)
            _cv2.line(CC, (x0, y0), (x1, y1), hCC, max(1, int(scale * 1.5)), lineType=_cv2.LINE_AA)
        # 3) INTERLACE PITS
        n_pit = int(np.clip(2100 * (mn / 2048.0) ** 2, 730, 4900))
        for _ in range(n_pit):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            r = max(1, int(rng.uniform(2.0, 4.0) * scale * 0.5))
            pM = float(rng.uniform(0.04, 0.22)); pR = float(rng.uniform(0.70, 0.97)); pCC = float(rng.uniform(0.55, 0.92))
            _cv2.circle(M, (cx, cy), r, pM, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r, pR, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r, pCC, -1, lineType=_cv2.LINE_AA)
        # 4) FRAYED FILAMENT SPLINTERS
        n_fray = int(np.clip(980 * (mn / 2048.0) ** 2, 340, 2380))
        for _ in range(n_fray):
            cx = float(rng.uniform(4, w - 4)); cy = float(rng.uniform(4, h - 4))
            base_ang = rng.choice([0.0, np.pi * 0.5])
            ang = base_ang + float(rng.uniform(-0.35, 0.35))
            length = float(rng.uniform(8.0, 14.0) * scale)
            x1 = int(cx + np.cos(ang) * length); y1 = int(cy + np.sin(ang) * length)
            fM = float(rng.uniform(0.15, 0.48)); fR = float(rng.uniform(0.52, 0.94)); fCC = float(rng.uniform(0.32, 0.80))
            _cv2.line(M, (int(cx), int(cy)), (x1, y1), fM, 1, lineType=_cv2.LINE_AA)
            _cv2.line(R, (int(cx), int(cy)), (x1, y1), fR, 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (int(cx), int(cy)), (x1, y1), fCC, 1, lineType=_cv2.LINE_AA)
        # 5) FILAMENT GLINT DOTS
        n_glint = int(np.clip(1540 * (mn / 2048.0) ** 2, 560, 3640))
        for _ in range(n_glint):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            r = max(1, int(rng.uniform(1.0, 2.0) * scale))
            gM = float(rng.uniform(0.32, 0.68)); gR = float(rng.uniform(0.38, 0.72)); gCC = float(rng.uniform(0.18, 0.52))
            _cv2.circle(M, (cx, cy), r, gM, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r, gR, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r, gCC, -1, lineType=_cv2.LINE_AA)

        # 6a) HERO BALLISTIC GRAZE DRAGS â€” 2-4 long bright skid streaks
        n_drag = int(rng.integers(2, 5))
        for _ in range(n_drag):
            dx = float(rng.uniform(-w * 0.10, w * 1.10))
            dy = float(rng.uniform(0, h))
            # Align roughly with one of the tow axes for realism
            d_ang = rng.choice([0.0, np.pi * 0.5]) + float(rng.uniform(-0.30, 0.30))
            d_len = float(rng.uniform(28.0, 60.0)) * scale
            x0d = int(dx); y0d = int(dy)
            x1d = int(dx + np.cos(d_ang) * d_len); y1d = int(dy + np.sin(d_ang) * d_len)
            dM = float(rng.uniform(0.55, 0.92))
            dR = float(rng.uniform(0.10, 0.30))
            dC = float(rng.uniform(0.10, 0.34))
            _cv2.line(M, (x0d, y0d), (x1d, y1d), dM, max(2, int(scale * 2.2)), lineType=_cv2.LINE_AA)
            _cv2.line(R, (x0d, y0d), (x1d, y1d), dR, max(2, int(scale * 2.2)), lineType=_cv2.LINE_AA)
            _cv2.line(CC, (x0d, y0d), (x1d, y1d), dC, max(2, int(scale * 2.2)), lineType=_cv2.LINE_AA)
            # Char-darkened entry mark
            _cv2.circle(M, (x0d, y0d), max(2, int(3 * scale)), float(rng.uniform(0.04, 0.18)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (x0d, y0d), max(2, int(3 * scale)), float(rng.uniform(0.80, 0.96)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (x0d, y0d), max(2, int(3 * scale)), float(rng.uniform(0.60, 0.90)), -1, lineType=_cv2.LINE_AA)

        # 6b) HERO RUPTURE BUNDLES â€” 3-6 exploded-fiber clusters
        n_rupt = int(rng.integers(3, 7))
        for _ in range(n_rupt):
            rx = float(rng.uniform(w * 0.08, w * 0.92))
            ry = float(rng.uniform(h * 0.08, h * 0.92))
            n_fil = int(rng.integers(8, 15))
            base_ang = rng.choice([0.0, np.pi * 0.5])
            for fi in range(n_fil):
                fang = base_ang + float(rng.uniform(-np.pi * 0.45, np.pi * 0.45))
                fL = float(rng.uniform(10.0, 20.0)) * scale
                x1f = int(rx + np.cos(fang) * fL); y1f = int(ry + np.sin(fang) * fL)
                _cv2.line(M, (int(rx), int(ry)), (x1f, y1f), float(rng.uniform(0.40, 0.82)), 1, lineType=_cv2.LINE_AA)
                _cv2.line(R, (int(rx), int(ry)), (x1f, y1f), float(rng.uniform(0.55, 0.94)), 1, lineType=_cv2.LINE_AA)
                _cv2.line(CC, (int(rx), int(ry)), (x1f, y1f), float(rng.uniform(0.40, 0.85)), 1, lineType=_cv2.LINE_AA)
            # Dark impact core
            _cv2.circle(M, (int(rx), int(ry)), max(2, int(2.2 * scale)), float(rng.uniform(0.06, 0.20)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (int(rx), int(ry)), max(2, int(2.2 * scale)), float(rng.uniform(0.78, 0.96)), -1, lineType=_cv2.LINE_AA)

    # 7) DUST FLECKS
    n_fl = int(np.clip(1900 * (mn / 2048.0) ** 2, 700, 4200))
    fx = rng.integers(0, w, n_fl); fy = rng.integers(0, h, n_fl)
    M[fy, fx] = rng.uniform(0.12, 0.88, n_fl).astype(np.float32)
    R[fy, fx] = rng.uniform(0.18, 0.95, n_fl).astype(np.float32)
    CC[fy, fx] = rng.uniform(0.08, 0.88, n_fl).astype(np.float32)
    out = np.stack([M, R, CC], axis=-1).astype(np.float32)
    return _validate_spec_output(_sm_scale(np.clip(out, 0.0, 1.0), sm).astype(np.float32), "spec_ballistic_weave")
spec_ballistic_weave._spb_concept_complete = True


# ============================================================================
# PRIORITY 2 BATCH E: ðŸ”µ CLEARCOAT BEHAVIOR (114â€“123)
# B=Clearcoat channel â€” INVERTED: low value = gloss, high = matte/rough
# These patterns make clearcoat variation visible: pooling, drips, fish-eyes,
# overspray halos, edge thinning. Dark output = extra-glossy zones.
# ============================================================================

def cc_panel_pool(shape, seed, sm, num_pools=12, pool_spread=0.18, base_density=0.0015, **kwargs):
    """cc_panel_pool â€” R6-Loop owner-corrective rebuild (was 6/KEEP).

    identity: NEW HERO â€” ANAMORPHIC OPTICAL-ILLUSION DROPLETS. Each pool
    is stretched along a UNIFIED perspective vanishing axis so the field
    reads like puddles on a wet road photographed in raking light. Single
    WARM TAN palette (M_base=0.50, R_base=0.30, CC_base=0.18 â€” composite
    reads warm tan-brown) with TIGHT +-0.05 per-feature jitter. Stacked
    tiers: (1) tan FBM substrate, (2) 800-3000 perspective-stretched
    ellipse droplets (length axis aligned to vanishing direction; pools
    further from horizon are elongated more â€” anamorphic illusion),
    (3) crescent MENISCUS highlights on each pool (1 px bright arc on
    the catch-light side), (4) interference reflection sub-arcs INSIDE
    larger pools (Newton's rings inside oil-thick beads), (5) capillary
    bridges 4-10 px between adjacent pools.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 54720)
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)

    # WARM TAN palette
    M_BASE, R_BASE, CC_BASE = 0.50, 0.30, 0.18
    JIT = 0.05

    # Substrate
    fbm_M = _normalize(multi_scale_noise(shape, [1.5, 4.0, 9.0], [0.42, 0.34, 0.24], seed + 151))
    fbm_R = _normalize(multi_scale_noise(shape, [1.8, 4.5, 11.0], [0.40, 0.34, 0.26], seed + 153))
    fbm_CC = _normalize(multi_scale_noise(shape, [2.0, 5.0, 12.0], [0.40, 0.34, 0.26], seed + 155))
    M = (M_BASE + (fbm_M - 0.5) * 0.10).astype(np.float32)
    R = (R_BASE + (fbm_R - 0.5) * 0.10).astype(np.float32)
    CC = (CC_BASE + (fbm_CC - 0.5) * 0.10).astype(np.float32)

    # Perspective vanishing axis (anamorphic stretch direction)
    vp_ang_deg = float(rng.uniform(15, 50))  # near-horizontal, raking
    vp_x = float(rng.uniform(-0.2, 1.2)) * w
    vp_y = float(rng.uniform(-0.1, 0.5)) * h

    pool_centers = []  # save for capillary bridges

    if _CV2_OK:
        # ANAMORPHIC DROPLETS â€” stretched along axis toward vanishing point
        n_pools = int(np.clip(1500 * (mn / 256.0) ** 2, 600, 3000))
        for _ in range(n_pools):
            cx = int(rng.uniform(0.01, 0.99) * w)
            cy = int(rng.uniform(0.01, 0.99) * h)
            # Distance from vanishing point â€” closer = more stretch
            dvp = float(np.hypot(cx - vp_x, cy - vp_y))
            dvp_n = float(np.clip(dvp / max(w, h) * 1.6, 0.0, 1.0))
            stretch = 1.0 + (1.0 - dvp_n) ** 1.5 * 5.0
            # 25% HERO bigger pools so puddles read on canvas
            if rng.random() < 0.25:
                base_r = max(2, int(rng.uniform(3.5, 6.5) * scale))
            else:
                base_r = max(1, int(rng.uniform(2.0, 4.0) * scale))
            rx = max(1, int(base_r * stretch))
            ry = max(1, base_r)
            # Body
            mv = float(np.clip(M_BASE + rng.uniform(-JIT, JIT) + 0.18, 0.05, 0.95))
            rv = float(np.clip(R_BASE + rng.uniform(-JIT, JIT) - 0.10, 0.05, 0.95))
            cv = float(np.clip(CC_BASE + rng.uniform(-JIT, JIT) + 0.45, 0.05, 0.99))
            _cv2.ellipse(M, (cx, cy), (rx, ry), vp_ang_deg, 0, 360, mv, -1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(R, (cx, cy), (rx, ry), vp_ang_deg, 0, 360, rv, -1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(CC, (cx, cy), (rx, ry), vp_ang_deg, 0, 360, cv, -1, lineType=_cv2.LINE_AA)
            # MENISCUS â€” bright crescent on one side (catch-light)
            arc0 = vp_ang_deg + 120; arc1 = arc0 + 100
            men_m = float(np.clip(M_BASE + rng.uniform(-JIT, JIT) + 0.40, 0.05, 0.99))
            men_c = float(np.clip(CC_BASE + rng.uniform(-JIT, JIT) + 0.65, 0.05, 0.99))
            _cv2.ellipse(M, (cx, cy), (rx + 1, ry + 1), vp_ang_deg, arc0, arc1, men_m, 1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(CC, (cx, cy), (rx + 1, ry + 1), vp_ang_deg, arc0, arc1, men_c, 1, lineType=_cv2.LINE_AA)
            pool_centers.append((cx, cy, rx, ry))

            # NEWTON'S-RINGS sub-arcs inside larger pools
            if rx >= 5 and rng.random() < 0.30:
                for ri in (1, 2):
                    rrx = max(1, rx - ri * 2); rry = max(1, ry - ri)
                    if rrx < 2 or rry < 2: break
                    ring_m = float(np.clip(M_BASE + rng.uniform(-JIT, JIT) + 0.30, 0.05, 0.95))
                    ring_c = float(np.clip(CC_BASE + rng.uniform(-JIT, JIT) + 0.32, 0.05, 0.99))
                    a0 = float(rng.uniform(0, 360))
                    _cv2.ellipse(M, (cx, cy), (rrx, rry), vp_ang_deg, a0, a0 + 160, ring_m, 1, lineType=_cv2.LINE_AA)
                    _cv2.ellipse(CC, (cx, cy), (rrx, rry), vp_ang_deg, a0, a0 + 160, ring_c, 1, lineType=_cv2.LINE_AA)

        # CAPILLARY BRIDGES â€” short connectors between random nearby pool pairs
        n_bridges = int(np.clip(min(len(pool_centers) // 4, 1200), 100, 1200))
        for _ in range(n_bridges):
            if len(pool_centers) < 2: break
            i, j = rng.integers(0, len(pool_centers)), rng.integers(0, len(pool_centers))
            if i == j: continue
            cxA, cyA, _, _ = pool_centers[i]
            cxB, cyB, _, _ = pool_centers[j]
            d = float(np.hypot(cxA - cxB, cyA - cyB))
            if d > 12 * scale * (mn / 256.0): continue
            mv = float(np.clip(M_BASE + rng.uniform(-JIT, JIT) + 0.14, 0.05, 0.95))
            cv = float(np.clip(CC_BASE + rng.uniform(-JIT, JIT) + 0.32, 0.05, 0.99))
            _cv2.line(M, (cxA, cyA), (cxB, cyB), mv, 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (cxA, cyA), (cxB, cyB), cv, 1, lineType=_cv2.LINE_AA)

    # DUST SPECK NUCLEI â€” single-pixel anchors, tight from base
    n_dust = int(np.clip(2400 * (mn / 256.0) ** 2, 1200, 7000))
    fx = rng.integers(0, w, n_dust); fy = rng.integers(0, h, n_dust)
    M[fy, fx] = np.clip(M_BASE + rng.uniform(-JIT, JIT, n_dust).astype(np.float32) + 0.30, 0, 1)
    R[fy, fx] = np.clip(R_BASE + rng.uniform(-JIT, JIT, n_dust).astype(np.float32), 0, 1)
    CC[fy, fx] = np.clip(CC_BASE + rng.uniform(-JIT, JIT, n_dust).astype(np.float32) + 0.20, 0, 1)

    out = np.stack([np.clip(M, 0, 1), np.clip(R, 0, 1), np.clip(CC, 0, 1)], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)


cc_panel_pool._spb_concept_complete = True

def cc_drip_runs(shape, seed, sm, num_drips=8, drip_length=0.25, **kwargs):
    """cc_drip_runs â€” R6-Loop owner-corrective rebuild (was 6/KEEP).

    identity: NEW HERO â€” PREDATOR-VEIN PULSE DRIPS. Each drip column is
    no longer a plain trickle: it now becomes a BIOLOGICAL VEIN PAIR
    (arteriole + venule near-parallel) with micro-capillary side-branches
    every 8-14 px and PULSING DILATION BULGES (3-5 px swells) at regular
    intervals. Dark STONE-GRAY substrate (M_base=0.18, R_base=0.15,
    CC_base=0.12) with TIGHT +-0.05 per-feature jitter. Drip identity
    sacred â€” strict near-vertical bias preserved.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 311100)
    scale = max(min(h, w) / 2048.0, 0.25)

    # DARK STONE-GRAY palette
    M_BASE, R_BASE, CC_BASE = 0.18, 0.15, 0.12
    JIT = 0.05

    fbm_M = _normalize(multi_scale_noise(shape, [3.0, 7.0, 14.0], [0.5, 0.3, 0.2], int(seed) + 311))
    fbm_R = _normalize(multi_scale_noise(shape, [3.0, 7.0, 14.0], [0.5, 0.3, 0.2], int(seed) + 312))
    fbm_CC = _normalize(multi_scale_noise(shape, [3.0, 7.0, 14.0], [0.5, 0.3, 0.2], int(seed) + 313))
    M = (M_BASE + (fbm_M - 0.5) * 0.08).astype(np.float32)
    R_ch = (R_BASE + (fbm_R - 0.5) * 0.08).astype(np.float32)
    CC = (CC_BASE + (fbm_CC - 0.5) * 0.08).astype(np.float32)

    drip_paths = []

    if _CV2_OK:
        n_drips = int(np.clip(80 * (min(h, w) / 256.0) ** 2, 60, 220))
        for _ in range(n_drips):
            cx = int(rng.uniform(6, w - 6))
            y0 = int(rng.uniform(0, h * 0.5))
            sag_len = int(rng.uniform(h * 0.25, h * 0.85))
            y1 = min(h - 1, y0 + sag_len)
            cx_end = int(np.clip(cx + rng.uniform(-3, 3), 0, w - 1))
            mvA = float(np.clip(M_BASE + rng.uniform(-JIT, JIT) + 0.40, 0.05, 0.95))
            rvA = float(np.clip(R_BASE + rng.uniform(-JIT, JIT) + 0.15, 0.05, 0.95))
            cvA = float(np.clip(CC_BASE + rng.uniform(-JIT, JIT) + 0.55, 0.05, 0.95))
            _cv2.line(M, (cx, y0), (cx_end, y1), mvA, 2, lineType=_cv2.LINE_AA)
            _cv2.line(R_ch, (cx, y0), (cx_end, y1), rvA, 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (cx, y0), (cx_end, y1), cvA, 2, lineType=_cv2.LINE_AA)
            off = int(rng.choice([-2, -1, 1, 2]))
            cxB = int(np.clip(cx + off, 0, w - 1)); cxB_end = int(np.clip(cx_end + off, 0, w - 1))
            mvB = float(np.clip(M_BASE + rng.uniform(-JIT, JIT) + 0.34, 0.05, 0.95))
            cvB = float(np.clip(CC_BASE + rng.uniform(-JIT, JIT) + 0.48, 0.05, 0.95))
            _cv2.line(M, (cxB, y0), (cxB_end, y1), mvB, 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (cxB, y0), (cxB_end, y1), cvB, 1, lineType=_cv2.LINE_AA)

            n_pulse = max(1, int((y1 - y0) / max(1, int(20 * scale))))
            for pi in range(n_pulse):
                t = (pi + 0.5) / max(n_pulse, 1)
                px_ = int(cx + (cx_end - cx) * t)
                py_ = int(y0 + (y1 - y0) * t)
                rb = max(2, int(rng.uniform(2, 4) * scale))
                bm = float(np.clip(M_BASE + rng.uniform(-JIT, JIT) + 0.50, 0.05, 0.95))
                bc = float(np.clip(CC_BASE + rng.uniform(-JIT, JIT) + 0.55, 0.05, 0.95))
                _cv2.circle(M, (px_, py_), rb, bm, -1, lineType=_cv2.LINE_AA)
                _cv2.circle(CC, (px_, py_), rb, bc, -1, lineType=_cv2.LINE_AA)

            n_cap = max(1, int((y1 - y0) / max(1, int(12 * scale))))
            for ci in range(n_cap):
                t = float(rng.uniform(0.1, 0.9))
                ox = int(cx + (cx_end - cx) * t)
                oy = int(y0 + (y1 - y0) * t)
                side = 1 if rng.random() < 0.5 else -1
                cap_len = float(rng.uniform(8.0, 14.0) * scale)
                ang = float(np.pi / 2) + side * float(rng.uniform(0.6, 1.2))
                ex_ = int(np.clip(ox + np.cos(ang) * cap_len, 0, w - 1))
                ey_ = int(np.clip(oy + np.sin(ang) * cap_len, 0, h - 1))
                cm = float(np.clip(M_BASE + rng.uniform(-JIT, JIT) + 0.28, 0.05, 0.95))
                cc_ = float(np.clip(CC_BASE + rng.uniform(-JIT, JIT) + 0.40, 0.05, 0.95))
                _cv2.line(M, (ox, oy), (ex_, ey_), cm, 1, lineType=_cv2.LINE_AA)
                _cv2.line(CC, (ox, oy), (ex_, ey_), cc_, 1, lineType=_cv2.LINE_AA)
                _cv2.circle(M, (ex_, ey_), 1, float(np.clip(cm + 0.12, 0.05, 0.99)), -1, lineType=_cv2.LINE_AA)

            r_b = max(2, int(rng.uniform(3, 5) * scale))
            bm = float(np.clip(M_BASE + rng.uniform(-JIT, JIT) + 0.55, 0.05, 0.95))
            bc = float(np.clip(CC_BASE + rng.uniform(-JIT, JIT) + 0.60, 0.05, 0.95))
            _cv2.circle(M, (cx_end, y1), r_b, bm, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx_end, y1), r_b, bc, -1, lineType=_cv2.LINE_AA)

            drip_paths.append((cx, y0, cx_end, y1))

        for (cx_s, y0_s, cx_e, y1_s) in drip_paths:
            n_grit = int(rng.integers(5, 12))
            for _ in range(n_grit):
                t = float(rng.uniform(0.0, 1.0))
                gx = int(np.clip(cx_s + (cx_e - cx_s) * t + rng.uniform(-2, 2), 0, w - 1))
                gy = int(np.clip(y0_s + (y1_s - y0_s) * t + rng.uniform(-1, 1), 0, h - 1))
                r_g = max(1, int(rng.uniform(1.0, 1.8) * scale))
                gm = float(np.clip(M_BASE + rng.uniform(-JIT, JIT) + 0.65, 0.05, 0.99))
                _cv2.circle(M, (gx, gy), r_g, gm, -1, lineType=_cv2.LINE_AA)

    out = np.stack([M, R_ch, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
cc_drip_runs._spb_concept_complete = True


def cc_fish_eye(shape, seed, sm, num_craters=20, crater_radius=0.04, **kwargs):
    """cc_fish_eye.

    identity: R6-Loop owner-rebuild â€” DENSE SILICONE FISH-EYE FIELD.
    Owner: "boring / too sparse". Fix: 4-5x crater density, smaller
    average craters so they read as dense field of dewetting events
    rather than scattered isolated dots. Keep the three-zone crater
    physics (moat/rim/island). Reduce satellites/tails so the eye
    catches the dense crater carpet first. NEW HERO motif: a few
    LARGE-CARAT iridescent OIL-SLICK CC RAINBOW HALOS â€” 5-9 oversized
    craters (18-26 px) each surrounded by 3-ring chromatic oil-sheen
    halos (the iconic silicone repellency shimmer).

    Per-feature TIGHT chroma uniform from a clearcoat zone palette.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 39231)
    scale = max(min(h, w) / 256.0, 0.6)

    # Base â€” glassy clearcoat (composite-friendly: low R, high CC, mid M)
    fbm_M = _normalize(multi_scale_noise(shape, [3.0, 7.0, 14.0], [0.5, 0.3, 0.2], int(seed) + 1211))
    fbm_R = _normalize(multi_scale_noise(shape, [3.5, 8.0, 16.0], [0.5, 0.3, 0.2], int(seed) + 1212))
    fbm_CC = _normalize(multi_scale_noise(shape, [3.0, 7.0, 14.0], [0.5, 0.3, 0.2], int(seed) + 1213))
    M = (0.45 + (fbm_M - 0.5) * 0.10).astype(np.float32)
    R_ch = (0.20 + (fbm_R - 0.5) * 0.08).astype(np.float32)
    CC = (0.58 + (fbm_CC - 0.5) * 0.12).astype(np.float32)

    # Spray-flow direction â€” defines comet-tail orientation
    flow_ang = float(rng.uniform(0, 2 * np.pi))

    # TIER 2 â€” DENSE CRATER FIELD (was sparse; owner: too sparse)
    # 4-5x previous density; smaller average so reads as carpet
    n_craters = int(np.clip(450 * scale * scale, 280, 900))
    crater_records = []
    for _ in range(n_craters):
        cx = float(rng.uniform(8, w - 8)); cy = float(rng.uniform(8, h - 8))
        # Smaller average so the field reads dense (8-32 px range)
        r_c = float(rng.uniform(3.0, 8.0) * scale)
        r_c = max(2.5, min(r_c, 7.0))
        crater_records.append((cx, cy, r_c))
        tile = int(r_c * 2.6) + 2
        x0 = max(0, int(cx) - tile); x1 = min(w, int(cx) + tile + 1)
        y0 = max(0, int(cy) - tile); y1 = min(h, int(cy) + tile + 1)
        if x1 <= x0 or y1 <= y0:
            continue
        tyy, txx = np.mgrid[y0:y1, x0:x1].astype(np.float32)
        d = np.sqrt((txx - cx) ** 2 + (tyy - cy) ** 2)
        moat = np.exp(-((d - r_c * 0.50) ** 2) / (2.0 * (r_c * 0.28) ** 2))
        rim = np.exp(-((d - r_c * 0.95) ** 2) / (2.0 * (r_c * 0.10) ** 2))
        island = np.exp(-(d * d) / (2.0 * (r_c * 0.15) ** 2))
        moat_M = float(rng.uniform(0.30, 0.55)); moat_R = float(rng.uniform(0.60, 0.92)); moat_CC = float(rng.uniform(0.10, 0.35))
        rim_M = float(rng.uniform(0.75, 0.98)); rim_R = float(rng.uniform(0.05, 0.18)); rim_CC = float(rng.uniform(0.70, 0.96))
        island_M = float(rng.uniform(0.08, 0.25)); island_R = float(rng.uniform(0.75, 0.96)); island_CC = float(rng.uniform(0.03, 0.18))
        sl_M = M[y0:y1, x0:x1]; sl_R = R_ch[y0:y1, x0:x1]; sl_CC = CC[y0:y1, x0:x1]
        sl_M = sl_M * (1.0 - moat * 0.55) + moat * moat_M * 0.55
        sl_R = sl_R * (1.0 - moat * 0.65) + moat * moat_R * 0.65
        sl_CC = sl_CC * (1.0 - moat * 0.65) + moat * moat_CC * 0.65
        sl_M = sl_M * (1.0 - rim * 0.80) + rim * rim_M * 0.80
        sl_R = sl_R * (1.0 - rim * 0.80) + rim * rim_R * 0.80
        sl_CC = sl_CC * (1.0 - rim * 0.80) + rim * rim_CC * 0.80
        sl_M = sl_M * (1.0 - island * 0.90) + island * island_M * 0.90
        sl_R = sl_R * (1.0 - island * 0.90) + island * island_R * 0.90
        sl_CC = sl_CC * (1.0 - island * 0.90) + island * island_CC * 0.90
        M[y0:y1, x0:x1] = sl_M; R_ch[y0:y1, x0:x1] = sl_R; CC[y0:y1, x0:x1] = sl_CC

    if _CV2_OK:
        # TIER 3 â€” SATELLITE micro-fish-eyes clustered around each hero
        # Crater count is 4-5x higher than before, so suppress most satellites.
        for (cx, cy, r_c) in crater_records:
            if rng.random() < 0.75:
                continue
            n_sat = int(rng.integers(2, 5))
            cluster_dir = float(rng.uniform(0, 2 * np.pi))
            cluster_spread = float(rng.uniform(0.4, 1.6))
            for _ in range(n_sat):
                phi = cluster_dir + float(rng.normal(0, cluster_spread))
                rad = float(rng.uniform(1.4, 3.5)) * r_c
                sx = cx + np.cos(phi) * rad
                sy = cy + np.sin(phi) * rad
                if not (1 < sx < w - 1 and 1 < sy < h - 1):
                    continue
                sr = max(1.0, float(rng.uniform(1.0, 3.0)) * scale)
                # Mini three-zone â€” implemented as 3 nested AA circles
                _cv2.circle(R_ch, (int(sx), int(sy)),
                            max(1, int(sr * 1.4)), float(rng.uniform(0.55, 0.85)),
                            -1, lineType=_cv2.LINE_AA)
                _cv2.circle(M, (int(sx), int(sy)),
                            max(1, int(sr)), float(rng.uniform(0.72, 0.97)),
                            1, lineType=_cv2.LINE_AA)
                _cv2.circle(CC, (int(sx), int(sy)),
                            max(1, int(sr)), float(rng.uniform(0.68, 0.94)),
                            1, lineType=_cv2.LINE_AA)
                # Tiny dark core (substrate)
                _cv2.circle(M, (int(sx), int(sy)),
                            max(1, int(sr * 0.45)), float(rng.uniform(0.08, 0.24)),
                            -1, lineType=_cv2.LINE_AA)
                _cv2.circle(CC, (int(sx), int(sy)),
                            max(1, int(sr * 0.45)), float(rng.uniform(0.05, 0.18)),
                            -1, lineType=_cv2.LINE_AA)

        # TIER 4 â€” COMET-TAIL drag streaks downstream (suppress most due to dense field)
        for (cx, cy, r_c) in crater_records:
            if rng.random() < 0.80:
                continue
            n_tail = int(rng.integers(2, 4))
            # Per-crater jitter of flow direction
            crater_ang = flow_ang + float(rng.normal(0, 0.25))
            for ti in range(n_tail):
                ang = crater_ang + float(rng.normal(0, 0.12))
                tail_len = float(rng.uniform(1.8, 3.6)) * r_c
                n_dash = max(2, int(tail_len * 0.6))
                tail_M = float(rng.uniform(0.50, 0.85))
                tail_R = float(rng.uniform(0.15, 0.42))
                tail_CC = float(rng.uniform(0.45, 0.82))
                for di in range(n_dash):
                    t = (di + 1) / n_dash
                    px = cx + np.cos(ang) * tail_len * t
                    py = cy + np.sin(ang) * tail_len * t
                    if 0 <= px < w and 0 <= py < h:
                        # Each pixel in tail gets independent jitter for chroma variety
                        ipx, ipy = int(px), int(py)
                        jM = float(np.clip(tail_M + rng.uniform(-0.10, 0.10), 0.0, 1.0))
                        jR = float(np.clip(tail_R + rng.uniform(-0.08, 0.08), 0.0, 1.0))
                        jCC = float(np.clip(tail_CC + rng.uniform(-0.12, 0.10), 0.0, 1.0))
                        if jM > M[ipy, ipx]: M[ipy, ipx] = jM
                        R_ch[ipy, ipx] = R_ch[ipy, ipx] * 0.5 + jR * 0.5
                        if jCC > CC[ipy, ipx]: CC[ipy, ipx] = jCC

        # TIER 5 â€” Iridescent silicone-sheen arcs hovering above a subset of rims
        n_arcs = int(np.clip(200 * scale * scale, 100, 350))
        for _ in range(n_arcs):
            cx = int(rng.uniform(6, w - 6)); cy = int(rng.uniform(6, h - 6))
            r_a = int(max(2, rng.uniform(2.0, 4.0) * scale))
            r_a = min(r_a, 5)
            ang0 = float(rng.uniform(0, 360)); ang1 = ang0 + float(rng.uniform(70, 150))
            aM = float(np.clip(0.78 + rng.uniform(-0.05, 0.05), 0, 1))
            aR = float(np.clip(0.12 + rng.uniform(-0.05, 0.05), 0, 1))
            aCC = float(np.clip(0.72 + rng.uniform(-0.06, 0.10), 0, 1))
            _cv2.ellipse(M, (cx, cy), (r_a, r_a), 0, ang0, ang1, aM, 1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(R_ch, (cx, cy), (r_a, r_a), 0, ang0, ang1, aR, 1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(CC, (cx, cy), (r_a, r_a), 0, ang0, ang1, aCC, 1, lineType=_cv2.LINE_AA)

        # TIER 6 â€” NEW HERO: LARGE-CARAT IRIDESCENT OIL-SLICK HALOS.
        # 5-9 oversized craters with 3-ring chromatic dispersion halo
        # (the iconic silicone-repellency rainbow shimmer the eye catches).
        n_oil = int(rng.integers(5, 10))
        for _ in range(n_oil):
            ocx = int(rng.uniform(12, w - 12))
            ocy = int(rng.uniform(12, h - 12))
            base_r = int(rng.uniform(8, 12))
            base_r = min(base_r, 12)
            # Dark crater core
            _cv2.circle(M, (ocx, ocy), max(1, base_r - 6), 0.08, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R_ch, (ocx, ocy), max(1, base_r - 6), 0.88, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (ocx, ocy), max(1, base_r - 6), 0.08, -1, lineType=_cv2.LINE_AA)
            # Bright rim ring
            _cv2.circle(M, (ocx, ocy), base_r - 4, 0.92, 1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (ocx, ocy), base_r - 4, 0.85, 1, lineType=_cv2.LINE_AA)
            # 3-ring chromatic dispersion (red-shift, green-shift, blue-shift)
            for ridx, dr in enumerate((0, 2, 4)):
                rr = base_r + dr
                if rr > min(w, h) / 2: break
                rM = float(np.clip(0.70 + rng.uniform(-0.05, 0.05), 0, 1))
                rR = float(np.clip(0.18 + rng.uniform(-0.05, 0.05), 0, 1))
                # Intentional spectral split â€” each ring distinct CC band
                rCC = float(np.clip([0.30, 0.60, 0.90][ridx] + rng.uniform(-0.06, 0.06), 0, 1))
                _cv2.circle(M, (ocx, ocy), rr, rM, 1, lineType=_cv2.LINE_AA)
                _cv2.circle(R_ch, (ocx, ocy), rr, rR, 1, lineType=_cv2.LINE_AA)
                _cv2.circle(CC, (ocx, ocy), rr, rCC, 1, lineType=_cv2.LINE_AA)

    out = np.stack([np.clip(M, 0, 1), np.clip(R_ch, 0, 1), np.clip(CC, 0, 1)], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
cc_fish_eye._spb_concept_complete = True


def cc_overspray_halo(shape, seed, sm, num_halos=6, halo_radius=0.22, **kwargs):
    """cc_overspray_halo â€” R6-Loop owner-corrective rebuild + R6-Loop
    creativity-mandate weird-pick layer.

    identity: HERO A â€” ENGINE-TURNED MACHINED HALO. The overspray
    transition annulus is rendered as Bugatti-dash OVERLAPPING ENGINE-
    TURN DISCS (10-18 px tool-marks tiled around the island perimeter,
    each with a tight catch-light arc + swirl interior). Deep VIOLET
    palette (M_base=0.45, R_base=0.15, CC_base=0.62 â€” composite reads
    violet). HERO B (NEW R6-Loop, deliberately weird) â€” DRAGON-CURVE
    FRACTAL TRACES: 1-3 Heighway dragon-curve fractals (iterated L-
    system, 7 iterations = 127 segments each) traced in iridescent ink
    across the mist halo, each segment 4-8 px with INDEPENDENT M/R/CC.
    Math-art on engineering canvas. Stacked: (1) violet substrate, (2)
    island core, (3) engine-turn disc band, (4) DRAGON CURVES, (5)
    wet-bead micro jewels, (6) mist pin-flecks, (7) tendril fingers.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 22851)
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)

    # DEEP VIOLET palette
    M_BASE, R_BASE, CC_BASE = 0.45, 0.15, 0.62
    JIT = 0.05

    # Substrate
    fbm_a = _normalize(_spb_fast_smooth_noise(shape, [4.0, 10.0, 24.0], [0.42, 0.34, 0.24], seed + 91))
    fbm_b = _normalize(_spb_fast_smooth_noise(shape, [5.0, 12.0, 27.0], [0.40, 0.36, 0.24], seed + 93))
    fbm_c = _normalize(_spb_fast_smooth_noise(shape, [3.0, 8.0], [0.55, 0.45], seed + 97))
    M = (M_BASE + (fbm_a - 0.5) * 0.08 + (fbm_c - 0.5) * 0.04).astype(np.float32)
    R = (R_BASE + (fbm_b - 0.5) * 0.08).astype(np.float32)
    CC = (CC_BASE + (fbm_a - 0.5) * 0.06 + (fbm_b - 0.5) * 0.06).astype(np.float32)

    yy, xx = np.mgrid[0:h, 0:w].astype(np.float32)
    xf = xx / max(w - 1, 1)
    yf = yy / max(h - 1, 1)

    # ISLAND â€” single big metaball with perturbed boundary
    n_island = int(rng.integers(2, 5))
    coat_field = np.zeros(shape, dtype=np.float32)
    perturb = (_normalize(_spb_fast_smooth_noise(shape, [4.0, 9.0], [0.55, 0.45], seed + 1133)) - 0.5) * 0.18
    for _ in range(n_island):
        cx0 = float(rng.uniform(0.25, 0.75)); cy0 = float(rng.uniform(0.25, 0.75))
        rx = float(rng.uniform(0.20, 0.36))
        ry = float(rng.uniform(0.20, 0.36))
        ang = float(rng.uniform(0, np.pi))
        dx = xf - cx0; dy = yf - cy0
        rdx = dx * np.cos(ang) + dy * np.sin(ang)
        rdy = -dx * np.sin(ang) + dy * np.cos(ang)
        d2 = (rdx / rx) ** 2 + (rdy / ry) ** 2 + perturb
        core = np.clip(1.0 - d2 * 0.8, 0.0, 1.0)
        halo = np.exp(-d2 * 1.2)
        coat_field = np.maximum(coat_field, np.maximum(core, halo * 0.90)).astype(np.float32)

    # Apply coating onto base (tight bias)
    M = np.clip(M + coat_field * 0.18, 0, 1)
    R = np.clip(R - coat_field * 0.08, 0, 1)
    CC = np.clip(CC + coat_field * 0.24, 0, 1)

    boundary = 1.0 - np.abs(coat_field - 0.5) * 2.0
    boundary = np.clip(boundary, 0.0, 1.0).astype(np.float32)

    if _CV2_OK:
        # HERO â€” ENGINE-TURN DISC BAND. Place 10-18 px circular tool-marks
        # along boundary annulus in a tiled grid; each disc has bright
        # catch-light arc + interior swirl streak.
        n_disc = int(np.clip(420 * (mn / 256.0) ** 2, 220, 1200))
        kept = 0; attempts = 0
        while kept < n_disc and attempts < n_disc * 6:
            attempts += 1
            cxd = int(rng.uniform(0, w)); cyd = int(rng.uniform(0, h))
            if rng.random() > boundary[cyd, cxd] * 0.92 + 0.04:
                continue
            kept += 1
            rd = max(5, int(rng.uniform(5.0, 9.0) * scale * (mn / 256.0)))
            rd = min(rd, 18)
            # Disc body
            dm = float(np.clip(M_BASE + rng.uniform(-JIT, JIT) + 0.25, 0.05, 0.95))
            dc = float(np.clip(CC_BASE + rng.uniform(-JIT, JIT) + 0.18, 0.05, 0.95))
            dr = float(np.clip(R_BASE + rng.uniform(-JIT, JIT) + 0.10, 0.05, 0.95))
            _cv2.circle(M, (cxd, cyd), rd, dm, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cxd, cyd), rd, dr, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cxd, cyd), rd, dc, -1, lineType=_cv2.LINE_AA)
            # Catch-light bright arc (top-left)
            am = float(np.clip(M_BASE + rng.uniform(-JIT, JIT) + 0.45, 0.05, 0.99))
            ac = float(np.clip(CC_BASE + rng.uniform(-JIT, JIT) + 0.32, 0.05, 0.99))
            _cv2.ellipse(M, (cxd, cyd), (rd, rd), 0, 200, 320, am, 1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(CC, (cxd, cyd), (rd, rd), 0, 200, 320, ac, 1, lineType=_cv2.LINE_AA)
            # Interior swirl streak
            sa = float(rng.uniform(0, 2 * np.pi))
            sx0 = int(cxd + np.cos(sa) * rd * 0.7); sy0 = int(cyd + np.sin(sa) * rd * 0.7)
            sx1 = int(cxd - np.cos(sa) * rd * 0.7); sy1 = int(cyd - np.sin(sa) * rd * 0.7)
            sm_ = float(np.clip(M_BASE + rng.uniform(-JIT, JIT) + 0.32, 0.05, 0.95))
            _cv2.line(M, (sx0, sy0), (sx1, sy1), sm_, 1, lineType=_cv2.LINE_AA)

        # WET BEADS in inner halo
        n_med = int(np.clip(1200 * (mn / 256.0) ** 2, 600, 3400))
        kept = 0; attempts = 0
        while kept < n_med and attempts < n_med * 4:
            attempts += 1
            cxb = int(rng.uniform(0, w)); cyb = int(rng.uniform(0, h))
            if rng.random() > boundary[cyb, cxb] * 0.92 + 0.05:
                continue
            kept += 1
            rr = max(1, int(rng.uniform(1.5, 3.0) * scale))
            bm = float(np.clip(M_BASE + rng.uniform(-JIT, JIT) + 0.22, 0.05, 0.95))
            bc = float(np.clip(CC_BASE + rng.uniform(-JIT, JIT) + 0.22, 0.05, 0.95))
            _cv2.circle(M, (cxb, cyb), rr, bm, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cxb, cyb), rr, bc, -1, lineType=_cv2.LINE_AA)

        # TENDRIL FINGERS
        n_tendril = int(rng.integers(5, 11))
        for _ in range(n_tendril):
            attempts = 0
            tx = 0; ty = 0; found = False
            while attempts < 20:
                attempts += 1
                tx = int(rng.uniform(0, w)); ty = int(rng.uniform(0, h))
                if 0.35 < coat_field[ty, tx] < 0.65:
                    found = True
                    break
            if not found:
                continue
            ang = float(rng.uniform(0, 2 * np.pi))
            length = float(rng.uniform(20.0, 50.0) * scale * (mn / 256.0))
            cx_, cy_ = float(tx), float(ty)
            for _step in range(int(length)):
                ang += float(rng.uniform(-0.18, 0.18))
                cx_ += float(np.cos(ang)); cy_ += float(np.sin(ang))
                if not (0 <= cx_ < w and 0 <= cy_ < h):
                    break
                rr = max(1, int(rng.uniform(2.0, 3.0) * scale))
                f = 1.0 - _step / max(length, 1)
                vm = float(np.clip(M_BASE + rng.uniform(-JIT, JIT) + 0.20 * f, 0.05, 0.95))
                vcc = float(np.clip(CC_BASE + rng.uniform(-JIT, JIT) + 0.22 * f, 0.05, 0.95))
                _cv2.circle(M, (int(cx_), int(cy_)), rr, vm, -1, lineType=_cv2.LINE_AA)
                _cv2.circle(CC, (int(cx_), int(cy_)), rr, vcc, -1, lineType=_cv2.LINE_AA)

        # HERO B (NEW R6-Loop creativity mandate â€” DELIBERATELY WEIRD):
        # DRAGON CURVE FRACTAL TRACES. Iterate the Heighway dragon L-system
        # (turn sequence built from successive folds), then walk it across
        # the mist halo zone. 1-3 curves per panel, 7 iterations = 127
        # segments each, segment length 4-8 px. Per-segment INDEPENDENT
        # M/R/CC across wide chroma range.
        n_dragons = int(rng.integers(1, 4))
        for _di in range(n_dragons):
            iters = 7
            # Classic Heighway dragon-curve turn sequence
            turns = []
            for i in range(1, (1 << iters)):
                # Heighway: turn at step i is L if ((((i & -i) << 1) & i) == 0)
                lb = i & (-i)
                turns.append(1 if (((lb << 1) & i) == 0) else -1)
            # Place start near an annulus zone if available
            attempts = 0
            sx0 = 0; sy0 = 0; placed = False
            while attempts < 30:
                attempts += 1
                tx = int(rng.uniform(0, w)); ty = int(rng.uniform(0, h))
                if 0.20 < coat_field[ty, tx] < 0.70:
                    sx0 = tx; sy0 = ty; placed = True; break
            if not placed:
                sx0 = int(rng.uniform(0.1, 0.9) * w); sy0 = int(rng.uniform(0.1, 0.9) * h)
            seg_len = float(rng.uniform(4.0, 8.0)) * scale
            heading = float(rng.uniform(0, 2 * np.pi))
            # Per-curve base palette in deep iridescent (violet/teal/magenta)
            curve_M_base = float(rng.uniform(0.30, 0.92))
            curve_R_base = float(rng.uniform(0.08, 0.30))
            curve_CC_base = float(rng.uniform(0.45, 0.95))
            cx_d = float(sx0); cy_d = float(sy0)
            for ti, turn in enumerate(turns):
                nx_d = cx_d + np.cos(heading) * seg_len
                ny_d = cy_d + np.sin(heading) * seg_len
                # Bounds clip â€” fold curve back inward if it walks off
                if not (0 <= nx_d < w and 0 <= ny_d < h):
                    heading += np.pi
                    nx_d = cx_d + np.cos(heading) * seg_len
                    ny_d = cy_d + np.sin(heading) * seg_len
                    if not (0 <= nx_d < w and 0 <= ny_d < h):
                        break
                # Per-SEGMENT independent chroma jitter (still INDEPENDENT)
                segM = float(np.clip(curve_M_base + rng.uniform(-0.15, 0.15), 0.08, 0.98))
                segR = float(np.clip(curve_R_base + rng.uniform(-0.10, 0.10), 0.05, 0.95))
                segCC = float(np.clip(curve_CC_base + rng.uniform(-0.15, 0.15), 0.08, 0.98))
                p0d = (int(cx_d), int(cy_d)); p1d = (int(nx_d), int(ny_d))
                _cv2.line(M, p0d, p1d, segM, 1, lineType=_cv2.LINE_AA)
                _cv2.line(R, p0d, p1d, segR, 1, lineType=_cv2.LINE_AA)
                _cv2.line(CC, p0d, p1d, segCC, 1, lineType=_cv2.LINE_AA)
                # Every 16 segments drop a 1-2 px node glint at the joint
                if ti % 16 == 0:
                    _cv2.circle(M, p1d, 1, float(rng.uniform(0.80, 0.98)), -1, lineType=_cv2.LINE_AA)
                    _cv2.circle(CC, p1d, 1, float(rng.uniform(0.78, 0.97)), -1, lineType=_cv2.LINE_AA)
                cx_d = nx_d; cy_d = ny_d
                heading += turn * (np.pi * 0.5)

    # MIST PIN-FLECKS â€” 1 px, tight from base
    n_haze = int(np.clip(2200 * (mn / 256.0) ** 2, 1200, 6500))
    sy = rng.integers(0, h, size=n_haze); sx = rng.integers(0, w, size=n_haze)
    cf = coat_field[sy, sx]
    mask = (cf > 0.04) & (cf < 0.55)
    yi = sy[mask]; xi = sx[mask]
    if yi.size > 0:
        M[yi, xi] = np.clip(M_BASE + rng.uniform(-JIT, JIT, yi.size).astype(np.float32) + 0.28, 0, 1)
        CC[yi, xi] = np.clip(CC_BASE + rng.uniform(-JIT, JIT, yi.size).astype(np.float32) + 0.18, 0, 1)

    out = np.stack([np.clip(M, 0, 1), np.clip(R, 0, 1), np.clip(CC, 0, 1)], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
cc_overspray_halo._spb_concept_complete = True


def cc_edge_thin(shape, seed, sm, edge_width=0.12, noise_scale=0.04, **kwargs):
    """cc_edge_thin.

    identity: CREATIVE REBUILD â€” multi-band edge-thinning with SIX
    stacked tiers showing the full clearcoat failure cascade: (1) waxy
    clearcoat base, (2) THREE inscribed thinning ribbons at the panel
    border (CC drops, R rises, M slightly drops), (3) bright glossy
    inner zone, (4) PERPENDICULAR STRETCH-MARK micro-striations running
    across each thinning band (lines that read like dried-paint fingerprint
    showing how the coat tore as it pulled back), (5) CRYSTALLINE
    CHALK-BLOOM rosettes (3-6 px) clustered along the worst part of
    the bands â€” radial efflorescence figures, (6) comet-tear droplets,
    chalk flakes, and gloss-wicking lines. Now reads as a believable
    over-time chalk-out failure event, not just an edge gradient.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 47101)
    scale = max(min(h, w) / 2048.0, 0.25)

    # Base â€” a slightly waxy clearcoat field
    fbm_M = _normalize(multi_scale_noise(shape, [3.0, 7.0, 14.0], [0.5, 0.3, 0.2], int(seed) + 1011))
    fbm_R = _normalize(multi_scale_noise(shape, [3.5, 8.0, 18.0], [0.5, 0.3, 0.2], int(seed) + 1012))
    fbm_CC = _normalize(multi_scale_noise(shape, [3.0, 7.0, 14.0], [0.5, 0.3, 0.2], int(seed) + 1013))
    M = (0.38 + (fbm_M - 0.5) * 0.20).astype(np.float32)
    R_ch = (0.30 + (fbm_R - 0.5) * 0.20).astype(np.float32)
    CC = (0.20 + (fbm_CC - 0.5) * 0.18).astype(np.float32)

    # KEY IDENTITY: multi-band edge thinning â€” inscribed rectangles whose
    # boundary regions go matte/bare (high R, low CC) and inner region is glossy.
    yy = np.arange(h, dtype=np.float32)[:, None] / max(h - 1, 1)
    xx = np.arange(w, dtype=np.float32)[None, :] / max(w - 1, 1)
    edge_f = np.minimum(np.minimum(xx, 1.0 - xx), np.minimum(yy, 1.0 - yy))
    # Stacked multi-ring: 3 thinning ribbons at increasing inset
    bands = np.zeros(shape, dtype=np.float32)
    for inset, width in [(0.00, 0.040), (0.07, 0.030), (0.14, 0.022)]:
        d = np.abs(edge_f - inset)
        bands = np.maximum(bands, np.exp(-(d * d) / (2.0 * width * width)).astype(np.float32))
    # Where bands are strong â†’ clearcoat thins (CC drops, R rises, M slightly drops)
    CC = CC - bands * 0.28
    R_ch = R_ch + bands * 0.42
    M = M - bands * 0.06
    # Inner glossy zone where bands are absent
    inner_w = np.clip((edge_f - 0.18) * 6.0, 0.0, 1.0)
    CC = CC + inner_w * 0.22
    R_ch = R_ch - inner_w * 0.12

    np.clip(M, 0, 1, out=M); np.clip(R_ch, 0, 1, out=R_ch); np.clip(CC, 0, 1, out=CC)

    if _CV2_OK:
        # COMET-TEAR DROPLETS â€” vertical teardrops hanging from the thinning bands
        n_tear = int(np.clip(1100 * (min(h, w) / 2048.0) ** 2, 360, 2800))
        for _ in range(n_tear):
            tx = float(rng.uniform(0.02, 0.98) * w)
            ty = float(rng.uniform(0.02, 0.98) * h)
            # Place preferentially where bands are strong
            iy = int(np.clip(ty, 0, h - 1)); ix = int(np.clip(tx, 0, w - 1))
            if rng.random() > bands[iy, ix] * 0.85 + 0.15:
                continue
            tail = float(rng.uniform(6.0, 14.0) * scale)
            head_r = max(1, int(rng.uniform(1.0, 2.4) * scale))
            # Teardrop: bright head + downward tail line
            _cv2.circle(M, (ix, iy), head_r, float(rng.uniform(0.55, 0.92)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R_ch, (ix, iy), head_r, float(rng.uniform(0.08, 0.30)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (ix, iy), head_r, float(rng.uniform(0.45, 0.85)), -1, lineType=_cv2.LINE_AA)
            _cv2.line(M, (ix, iy), (ix, int(min(h - 1, iy + tail))),
                      float(rng.uniform(0.40, 0.80)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (ix, iy), (ix, int(min(h - 1, iy + tail))),
                      float(rng.uniform(0.25, 0.65)), 1, lineType=_cv2.LINE_AA)
        # CHALK FLAKES â€” tiny bare-substrate motes that sit ON the thinning bands
        n_chalk = int(np.clip(800 * (min(h, w) / 2048.0) ** 2, 260, 2000))
        for _ in range(n_chalk):
            cx = int(rng.uniform(0, w)); cy = int(rng.uniform(0, h))
            if rng.random() > bands[cy, cx] * 0.9 + 0.10:
                continue
            r_p = max(1, int(rng.uniform(1.0, 2.5) * scale))
            _cv2.circle(M, (cx, cy), r_p, float(rng.uniform(0.20, 0.50)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R_ch, (cx, cy), r_p, float(rng.uniform(0.65, 0.95)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r_p, float(rng.uniform(0.04, 0.20)), -1, lineType=_cv2.LINE_AA)
        # GLOSS WICKING LINES â€” short bright lines that "wick" radially across
        # the gradient from glossy inner toward dry edge
        n_wick = int(np.clip(550 * (min(h, w) / 2048.0) ** 2, 180, 1400))
        for _ in range(n_wick):
            cx = float(rng.uniform(2, w - 2)); cy = float(rng.uniform(2, h - 2))
            # Direction: toward nearest edge
            dx = 0.5 - cx / w; dy = 0.5 - cy / h
            if abs(dx) >= abs(dy):
                ang = 0.0 if dx > 0 else np.pi
            else:
                ang = np.pi * 0.5 if dy < 0 else -np.pi * 0.5
            length = float(rng.uniform(8.0, 14.0) * scale)
            x2 = int(np.clip(cx + np.cos(ang) * length, 0, w - 1))
            y2 = int(np.clip(cy + np.sin(ang) * length, 0, h - 1))
            _cv2.line(CC, (int(cx), int(cy)), (x2, y2), float(rng.uniform(0.55, 0.90)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(R_ch, (int(cx), int(cy)), (x2, y2), float(rng.uniform(0.10, 0.32)), 1, lineType=_cv2.LINE_AA)

        # NEW TIER â€” PERPENDICULAR STRETCH-MARK MICRO-STRIATIONS
        # Each striation is a 4-10 px line oriented PARALLEL to the nearest
        # edge (perpendicular to the gradient direction) showing how the
        # coat fractured as it pulled away.
        n_stretch = int(np.clip(1400 * (min(h, w) / 2048.0) ** 2, 480, 3200))
        for _ in range(n_stretch):
            cx = float(rng.uniform(2, w - 2)); cy = float(rng.uniform(2, h - 2))
            iy = int(np.clip(cy, 0, h - 1)); ix = int(np.clip(cx, 0, w - 1))
            if rng.random() > bands[iy, ix] * 0.95 + 0.05:
                continue
            # Direction PARALLEL to nearest edge â€” perpendicular to wicking lines
            dx = 0.5 - cx / w; dy = 0.5 - cy / h
            if abs(dx) >= abs(dy):
                ang = np.pi * 0.5  # vertical edge -> stretch mark runs vertical
            else:
                ang = 0.0           # horizontal edge -> stretch mark runs horizontal
            ang += float(rng.normal(0, 0.10))
            length = float(rng.uniform(3.0, 9.0) * scale)
            x0s = int(np.clip(cx - np.cos(ang) * length * 0.5, 0, w - 1))
            y0s = int(np.clip(cy - np.sin(ang) * length * 0.5, 0, h - 1))
            x1s = int(np.clip(cx + np.cos(ang) * length * 0.5, 0, w - 1))
            y1s = int(np.clip(cy + np.sin(ang) * length * 0.5, 0, h - 1))
            _cv2.line(M, (x0s, y0s), (x1s, y1s),
                      float(rng.uniform(0.18, 0.42)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(R_ch, (x0s, y0s), (x1s, y1s),
                      float(rng.uniform(0.62, 0.92)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (x0s, y0s), (x1s, y1s),
                      float(rng.uniform(0.06, 0.22)), 1, lineType=_cv2.LINE_AA)

        # NEW TIER â€” CRYSTALLINE CHALK-BLOOM ROSETTES
        # Small radial efflorescence figures on the WORST parts of bands.
        n_bloom = int(np.clip(280 * (min(h, w) / 2048.0) ** 2, 90, 720))
        for _ in range(n_bloom):
            cx = int(rng.uniform(4, w - 4)); cy = int(rng.uniform(4, h - 4))
            if bands[cy, cx] < 0.55:
                continue
            n_arm = int(rng.integers(5, 9))
            base_ang = float(rng.uniform(0, 2 * np.pi))
            arm_len = float(rng.uniform(3.0, 6.0) * scale)
            for ai in range(n_arm):
                ang = base_ang + ai * (2 * np.pi / n_arm) + float(rng.normal(0, 0.10))
                ex = int(np.clip(cx + np.cos(ang) * arm_len, 0, w - 1))
                ey = int(np.clip(cy + np.sin(ang) * arm_len, 0, h - 1))
                _cv2.line(M, (cx, cy), (ex, ey),
                          float(rng.uniform(0.25, 0.55)), 1, lineType=_cv2.LINE_AA)
                _cv2.line(R_ch, (cx, cy), (ex, ey),
                          float(rng.uniform(0.55, 0.88)), 1, lineType=_cv2.LINE_AA)
                _cv2.line(CC, (cx, cy), (ex, ey),
                          float(rng.uniform(0.08, 0.26)), 1, lineType=_cv2.LINE_AA)
            # Central crystal nucleus
            _cv2.circle(M, (cx, cy), max(1, int(scale * 1.2)),
                        float(rng.uniform(0.35, 0.65)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R_ch, (cx, cy), max(1, int(scale * 1.2)),
                        float(rng.uniform(0.45, 0.80)), -1, lineType=_cv2.LINE_AA)

    out = np.stack([np.clip(M, 0, 1), np.clip(R_ch, 0, 1), np.clip(CC, 0, 1)], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
cc_edge_thin._spb_concept_complete = True


def cc_masking_edge(shape, seed, sm, num_edges=4, edge_softness=0.03, **kwargs):
    """cc_masking_edge.

    OWNER REBUILD: owner said "WAY TOO BIG" / sparse / boring. New
    identity â€” instead of 3-5 panel-spanning long masking lines, use
    14-22 SHORT masking-tape SEGMENTS (each 20-50 px long, never
    full-panel), packed in 3-4 quasi-parallel groups. Hero motifs:
    (1) every segment has a torn-tape serrated edge perturbation,
    (2) DENSE adhesive-transfer ghost rectangles (4-12 px) clustered
    on every segment, (3) bleed beads, fiber pull-up tufts, and (4)
    NEW micro-blue-tape COLOR FLAKES â€” small 3-6 px blue chips that
    pulled off when tape was peeled. Per-feature independent
    continuous M/R/CC. No feature exceeds 50 px length / 12 px width.
    Composite-dark substrate (M low, R mid, CC low) â€” no neon green.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 51422)
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)

    grain = _normalize(multi_scale_noise(shape, [3.5, 9.0, 22.0], [0.40, 0.34, 0.26], seed + 71))
    chroma = _normalize(multi_scale_noise(shape, [6.0, 14.0, 30.0], [0.38, 0.34, 0.28], seed + 73))

    # Composite-dark substrate: all three channels low (no neon green wash)
    M = (0.13 + (grain - 0.5) * 0.08 + (chroma - 0.5) * 0.04).astype(np.float32)
    R = (0.18 + (grain - 0.5) * 0.10 - (chroma - 0.5) * 0.06).astype(np.float32)
    CC = (0.12 + (chroma - 0.5) * 0.10).astype(np.float32)

    # NEW IDENTITY â€” many SHORT masking-tape segments arranged in 3-4
    # quasi-parallel groups, each segment 12-30% of min-dim long.
    yy, xx = np.mgrid[0:h, 0:w].astype(np.float32)
    boundary = np.zeros(shape, dtype=np.float32)
    n_groups = int(rng.integers(3, 5))
    seg_centers = []  # (cx, cy, ang, length) for later feature placement
    for g in range(n_groups):
        ang_g = float(rng.uniform(0, np.pi))
        # 4-7 segments per group
        n_seg = int(rng.integers(4, 8))
        for _ in range(n_seg):
            cx = float(rng.uniform(0.08, 0.92) * w)
            cy = float(rng.uniform(0.08, 0.92) * h)
            ang = ang_g + float(rng.normal(0, 0.10))
            # Length 14-32% of min dimension â€” visible at any thumbnail size
            length = float(rng.uniform(0.14, 0.32) * mn)
            seg_centers.append((cx, cy, ang, length))
            # Build the tape segment as a thin filled rect with TORN edge perturbation
            tx_, ty_ = np.cos(ang), np.sin(ang)
            nx_, ny_ = -np.sin(ang), np.cos(ang)
            # Tape width = 1.5-3% of min dim â€” small but visible
            half_w = float(rng.uniform(0.015, 0.030) * mn)
            # Compute mask in a local bounding box
            u = (xx - cx) * tx_ + (yy - cy) * ty_  # along-tape coord
            v = (xx - cx) * nx_ + (yy - cy) * ny_  # across-tape
            jitter = (np.sin(u * 0.85 + g * 1.7) * 0.8
                      + np.sin(u * 2.1 + g * 0.5) * 0.5).astype(np.float32)
            seg_mask = ((np.abs(u) < length * 0.5) & (np.abs(v + jitter) < half_w)).astype(np.float32)
            # Coated side: high M, low R, high-ish CC
            cm = float(rng.uniform(0.45, 0.85))
            cr = float(rng.uniform(0.10, 0.30))
            cc_ = float(rng.uniform(0.35, 0.78))
            M = M * (1.0 - seg_mask * 0.95) + cm * seg_mask * 0.95
            R = R * (1.0 - seg_mask * 0.95) + cr * seg_mask * 0.95
            CC = CC * (1.0 - seg_mask * 0.95) + cc_ * seg_mask * 0.95
            # Capture boundary near edges (for feature placement) â€” within 6 px of edge
            edge_band = ((np.abs(u) < length * 0.5) & (np.abs(v) < half_w + 6.0 * scale) & (np.abs(v) > half_w - 1.0)).astype(np.float32)
            boundary = np.maximum(boundary, edge_band)

    np.clip(M, 0, 1, out=M); np.clip(R, 0, 1, out=R); np.clip(CC, 0, 1, out=CC)

    if _CV2_OK:
        # PAINT BLEED â€” small chroma beads clustered on segment edges (dense)
        n_bleed = int(np.clip(2200 * (mn / 2048.0) ** 2, 800, 5500))
        kept = 0; attempts = 0
        while kept < n_bleed and attempts < n_bleed * 5:
            attempts += 1
            cx = int(rng.uniform(2, w - 2)); cy = int(rng.uniform(2, h - 2))
            if rng.random() > boundary[cy, cx] * 0.85 + 0.04:
                continue
            kept += 1
            r = max(1, int(rng.uniform(1.0, 2.5) * scale))
            _cv2.circle(M, (cx, cy), r, float(rng.uniform(0.45, 0.92)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r, float(rng.uniform(0.08, 0.35)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r, float(rng.uniform(0.30, 0.85)), -1, lineType=_cv2.LINE_AA)

        # FIBER PULL-UP â€” tiny short hairs at boundary
        n_fib = int(np.clip(1400 * (mn / 2048.0) ** 2, 500, 3600))
        kept = 0; attempts = 0
        while kept < n_fib and attempts < n_fib * 5:
            attempts += 1
            cx = float(rng.uniform(2, w - 2)); cy = float(rng.uniform(2, h - 2))
            ix = int(cx); iy = int(cy)
            if rng.random() > boundary[iy, ix] * 0.85 + 0.04:
                continue
            kept += 1
            ang = float(rng.uniform(0, np.pi * 2))
            length = float(rng.uniform(2.5, 6.0) * scale)
            x2 = int(np.clip(cx + np.cos(ang) * length, 0, w - 1))
            y2 = int(np.clip(cy + np.sin(ang) * length, 0, h - 1))
            _cv2.line(M, (int(cx), int(cy)), (x2, y2), float(rng.uniform(0.30, 0.70)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(R, (int(cx), int(cy)), (x2, y2), float(rng.uniform(0.55, 0.92)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (int(cx), int(cy)), (x2, y2), float(rng.uniform(0.10, 0.35)), 1, lineType=_cv2.LINE_AA)

        # ADHESIVE-TRANSFER GHOST RECTANGLES â€” DENSE clusters on segment edges
        n_ghost = int(np.clip(900 * (mn / 2048.0) ** 2, 400, 2400))
        kept = 0; attempts = 0
        while kept < n_ghost and attempts < n_ghost * 5:
            attempts += 1
            cx = int(rng.uniform(4, w - 4)); cy = int(rng.uniform(4, h - 4))
            if rng.random() > boundary[cy, cx] * 0.75 + 0.08:
                continue
            kept += 1
            rw = max(2, int(rng.uniform(3.0, 11.0) * scale))
            rh = max(2, int(rng.uniform(2.0, 7.0) * scale))
            ang_g = float(rng.uniform(0, np.pi))
            box = _cv2.boxPoints(((cx, cy), (rw, rh), float(np.degrees(ang_g)))).astype(np.int32)
            _cv2.fillPoly(M, [box], float(rng.uniform(0.18, 0.62)), lineType=_cv2.LINE_AA)
            _cv2.fillPoly(R, [box], float(rng.uniform(0.40, 0.85)), lineType=_cv2.LINE_AA)
            _cv2.fillPoly(CC, [box], float(rng.uniform(0.12, 0.55)), lineType=_cv2.LINE_AA)

        # NEW â€” BLUE-TAPE COLOR FLAKES (3-6 px chips that pulled off)
        n_flake = int(np.clip(1600 * (mn / 2048.0) ** 2, 600, 4200))
        for _ in range(n_flake):
            cx = int(rng.uniform(0, w)); cy = int(rng.uniform(0, h))
            r = max(2, int(rng.uniform(3.0, 6.0) * scale))
            # blue-tape blue: M mid, R mid-high (matte vinyl), CC high (clearcoat-bright B)
            _cv2.circle(M, (cx, cy), r, float(rng.uniform(0.25, 0.55)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r, float(rng.uniform(0.45, 0.75)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r, float(rng.uniform(0.55, 0.90)), -1, lineType=_cv2.LINE_AA)

        # FINE ASH FLECKS (vectorized)
        n_ash = int(np.clip(6000 * (mn / 2048.0) ** 2, 2200, 16000))
        fx = rng.integers(0, w, n_ash); fy = rng.integers(0, h, n_ash)
        M[fy, fx] = np.clip(M[fy, fx] + rng.uniform(-0.18, 0.30, n_ash).astype(np.float32), 0, 1)
        R[fy, fx] = np.clip(R[fy, fx] + rng.uniform(-0.25, 0.20, n_ash).astype(np.float32), 0, 1)
        CC[fy, fx] = np.clip(CC[fy, fx] + rng.uniform(-0.15, 0.30, n_ash).astype(np.float32), 0, 1)

    out = np.stack([np.clip(M, 0, 1), np.clip(R, 0, 1), np.clip(CC, 0, 1)], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
cc_masking_edge._spb_concept_complete = True


def cc_spot_polish(shape, seed, sm, num_spots=15, spot_radius=0.08, **kwargs):
    """cc_spot_polish.

    identity: Round-6 OWNER CORRECTIVE â€” owner said "Need 4x more of the
    Polished Discs". A dull-haze panel where the buffer pad just lifted
    to leave POLISHED DISCS at high density. Primary discs (8-22 px) keep
    their hotspot center + crisp dark rim, surrounded by a SOFT OVERSPRAY
    HALO ring 1.4-1.8x the disc radius. Between discs, short 6-12 px
    CONNECTING SWIRL traces hint at the pad-path. Sprinkled DEPRESSION
    MOTTLING (4-8 px dark soft spots) suggests unpolished valleys.
    NEW HERO: jeweled BIG-PAD MEDALLION discs (24-32 px, 8-14 of them)
    with internal sub-spiral polish marks for owner-eye character. Each
    feature carries independent continuous M/R/CC uniforms.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 17302)
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)

    # Dull substrate â€” composite-dark (low all three channels)
    # Owner palette lesson: substrate R must be LOW (was 0.55, made it neon-green).
    # Now M=0.18, R=0.22, CC=0.14 â†’ dark/stone-gray composite.
    fbm_a = _normalize(multi_scale_noise(shape, [3.0, 8.0, 18.0], [0.42, 0.34, 0.24], seed + 181))
    fbm_b = _normalize(multi_scale_noise(shape, [5.0, 12.0, 26.0], [0.40, 0.34, 0.26], seed + 183))
    M = (0.18 + (fbm_a - 0.5) * 0.10).astype(np.float32)
    R = (0.22 + (fbm_b - 0.5) * 0.10).astype(np.float32)
    CC = (0.14 + (fbm_a - 0.5) * 0.08 + (fbm_b - 0.5) * 0.04).astype(np.float32)

    # POLISHED DISCS â€” radial-gradient filled circles
    # Big primary discs â€” collect centers for swirl-trace tier
    # OWNER 4x DENSITY CORRECTION â€” use mn/512 so thumbs at 512 are dense
    disc_centers = []
    n_primary = int(np.clip(750 * (mn / 512.0) ** 2, 560, 4400))
    for _ in range(n_primary):
        cx = float(rng.uniform(0, w)); cy = float(rng.uniform(0, h))
        rad = float(rng.uniform(8.0, 22.0) * max(mn / 512.0, 0.5))
        disc_centers.append((cx, cy, rad))
        tile = int(rad * 1.9) + 2  # bigger tile for overspray halo
        x0 = max(0, int(cx) - tile); x1 = min(w, int(cx) + tile + 1)
        y0 = max(0, int(cy) - tile); y1 = min(h, int(cy) + tile + 1)
        if x1 <= x0 or y1 <= y0:
            continue
        tyy, txx = np.mgrid[y0:y1, x0:x1].astype(np.float32)
        d = np.sqrt((txx - cx) ** 2 + (tyy - cy) ** 2)
        # Overspray halo ring 1.4-1.8x disc radius â€” faint outer dust glow
        halo_r = rad * float(rng.uniform(1.4, 1.8))
        halo = np.exp(-((d - halo_r) ** 2) / (2.0 * (rad * 0.30) ** 2)).astype(np.float32)
        # Smoothstep mask + central hotspot
        mask = np.clip(1.0 - d / rad, 0.0, 1.0).astype(np.float32)
        hot = np.exp(-(d * d) / (2.0 * (rad * 0.35) ** 2)).astype(np.float32)
        rim = np.exp(-((d - rad * 0.92) ** 2) / (2.0 * (rad * 0.07) ** 2)).astype(np.float32)
        # Independent per-disc uniforms â€” TIGHT R range keeps composite from greening
        body_M = float(rng.uniform(0.55, 0.85)); body_R = float(rng.uniform(0.12, 0.26)); body_CC = float(rng.uniform(0.55, 0.88))
        hot_M = float(rng.uniform(0.78, 0.98)); hot_R = float(rng.uniform(0.04, 0.14)); hot_CC = float(rng.uniform(0.75, 0.98))
        rim_M = float(rng.uniform(0.18, 0.40)); rim_R = float(rng.uniform(0.28, 0.42)); rim_CC = float(rng.uniform(0.10, 0.30))
        halo_M = float(rng.uniform(0.32, 0.55)); halo_R = float(rng.uniform(0.22, 0.36)); halo_CC = float(rng.uniform(0.30, 0.62))
        sl_M = M[y0:y1, x0:x1]; sl_R = R[y0:y1, x0:x1]; sl_CC = CC[y0:y1, x0:x1]
        # Overspray halo (faint outer glow, applied first as base lift)
        sl_M = sl_M * (1.0 - halo * 0.30) + halo * halo_M * 0.30
        sl_R = sl_R * (1.0 - halo * 0.30) + halo * halo_R * 0.30
        sl_CC = sl_CC * (1.0 - halo * 0.30) + halo * halo_CC * 0.30
        # Body
        sl_M = sl_M * (1.0 - mask * 0.85) + mask * body_M * 0.85
        sl_R = sl_R * (1.0 - mask * 0.85) + mask * body_R * 0.85
        sl_CC = sl_CC * (1.0 - mask * 0.85) + mask * body_CC * 0.85
        # Hotspot center brighter
        sl_M = sl_M * (1.0 - hot * 0.55) + hot * hot_M * 0.55
        sl_R = sl_R * (1.0 - hot * 0.55) + hot * hot_R * 0.55
        sl_CC = sl_CC * (1.0 - hot * 0.55) + hot * hot_CC * 0.55
        # Crisp dark rim
        sl_M = sl_M * (1.0 - rim * 0.70) + rim * rim_M * 0.70
        sl_R = sl_R * (1.0 - rim * 0.70) + rim * rim_R * 0.70
        sl_CC = sl_CC * (1.0 - rim * 0.70) + rim * rim_CC * 0.70
        M[y0:y1, x0:x1] = sl_M; R[y0:y1, x0:x1] = sl_R; CC[y0:y1, x0:x1] = sl_CC

    if _CV2_OK:
        # NEW: CONNECTING SWIRL TRACES â€” 6-12 px arcs between nearby discs
        if len(disc_centers) >= 2:
            n_swirl_trace = int(np.clip(1100 * (mn / 2048.0) ** 2, 380, 2800))
            for _ in range(n_swirl_trace):
                a = disc_centers[int(rng.integers(0, len(disc_centers)))]
                cx = float(a[0]) + float(rng.uniform(-a[2] * 1.6, a[2] * 1.6))
                cy = float(a[1]) + float(rng.uniform(-a[2] * 1.6, a[2] * 1.6))
                if not (0 <= cx < w and 0 <= cy < h):
                    continue
                length = float(rng.uniform(6.0, 12.0) * scale)
                ang = float(rng.uniform(0, 2 * np.pi))
                x0t = int(cx - np.cos(ang) * length * 0.5); y0t = int(cy - np.sin(ang) * length * 0.5)
                x1t = int(cx + np.cos(ang) * length * 0.5); y1t = int(cy + np.sin(ang) * length * 0.5)
                tM = float(rng.uniform(0.45, 0.82)); tR = float(rng.uniform(0.15, 0.40)); tCC = float(rng.uniform(0.40, 0.78))
                _cv2.line(M, (x0t, y0t), (x1t, y1t), tM, 1, lineType=_cv2.LINE_AA)
                _cv2.line(R, (x0t, y0t), (x1t, y1t), tR, 1, lineType=_cv2.LINE_AA)
                _cv2.line(CC, (x0t, y0t), (x1t, y1t), tCC, 1, lineType=_cv2.LINE_AA)
        # NEW: DEPRESSION MOTTLING â€” soft dark unpolished valleys, 4-8 px
        # Owner palette: dR was 0.62-0.88 (way too high â€” made green). Now dark.
        n_dep = int(np.clip(380 * (mn / 2048.0) ** 2, 120, 950))
        for _ in range(n_dep):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            r = max(2, int(rng.uniform(4.0, 8.0) * scale))
            dM = float(rng.uniform(0.10, 0.22))
            dR = float(rng.uniform(0.20, 0.34))
            dCC = float(rng.uniform(0.10, 0.22))
            _cv2.circle(M, (cx, cy), r, dM, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r, dR, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r, dCC, -1, lineType=_cv2.LINE_AA)
        # MICRO POLISH SATELLITES â€” small bright dots around primaries
        n_sat = int(np.clip(1400 * (mn / 2048.0) ** 2, 480, 3500))
        for _ in range(n_sat):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            r = max(1, int(rng.uniform(2.0, 5.0) * scale))
            # Inner bright + outer ring â€” outer R kept low to avoid green halo
            _cv2.circle(R, (cx, cy), r + 1, float(rng.uniform(0.20, 0.34)), 1, lineType=_cv2.LINE_AA)
            _cv2.circle(M, (cx, cy), r, float(rng.uniform(0.55, 0.92)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r, float(rng.uniform(0.05, 0.18)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r, float(rng.uniform(0.55, 0.92)), -1, lineType=_cv2.LINE_AA)
        # CENTRE PINPOINTS â€” extra hot-spot speculars in disc centers
        n_pin = int(np.clip(900 * (mn / 2048.0) ** 2, 320, 2400))
        for _ in range(n_pin):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            r = max(1, int(rng.uniform(1.0, 2.0) * scale))
            _cv2.circle(M, (cx, cy), r, float(rng.uniform(0.80, 0.99)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r, float(rng.uniform(0.03, 0.15)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r, float(rng.uniform(0.78, 0.98)), -1, lineType=_cv2.LINE_AA)
        # NEW HERO: BIG-PAD MEDALLION discs â€” 8-14 large jeweled-spot polish marks
        # with internal sub-spiral marks (the watchmaker's signature). These are
        # the "owner-eye standout" big polished circles.
        sc_med = max(mn / 512.0, 0.5)
        n_med = int(rng.integers(8, 15))
        for _ in range(n_med):
            mcx = float(rng.uniform(0.10, 0.90) * w)
            mcy = float(rng.uniform(0.10, 0.90) * h)
            mrad = float(rng.uniform(12.0, 16.0) * sc_med)
            mtile = int(mrad * 1.4) + 2
            x0m = max(0, int(mcx) - mtile); x1m = min(w, int(mcx) + mtile + 1)
            y0m = max(0, int(mcy) - mtile); y1m = min(h, int(mcy) + mtile + 1)
            if x1m <= x0m or y1m <= y0m: continue
            tyy, txx = np.mgrid[y0m:y1m, x0m:x1m].astype(np.float32)
            d = np.sqrt((txx - mcx) ** 2 + (tyy - mcy) ** 2)
            mask = np.clip(1.0 - d / mrad, 0.0, 1.0).astype(np.float32)
            hot = np.exp(-(d * d) / (2.0 * (mrad * 0.30) ** 2)).astype(np.float32)
            ang_in_disc = np.arctan2(tyy - mcy, txx - mcx).astype(np.float32)
            # internal spiral polish trace â€” bright sub-radial sweep
            spiral = (np.sin(ang_in_disc * 6.0 + d * 0.55) * 0.5 + 0.5).astype(np.float32) * mask
            m_med_body = float(rng.uniform(0.62, 0.86))
            m_med_hot  = float(rng.uniform(0.85, 0.99))
            sl_M = M[y0m:y1m, x0m:x1m]; sl_R = R[y0m:y1m, x0m:x1m]; sl_CC = CC[y0m:y1m, x0m:x1m]
            sl_M = sl_M * (1.0 - mask * 0.82) + mask * m_med_body * 0.82
            sl_R = sl_R * (1.0 - mask * 0.82) + mask * 0.16 * 0.82
            sl_CC = sl_CC * (1.0 - mask * 0.82) + mask * 0.82 * 0.82
            sl_M = sl_M * (1.0 - hot * 0.55) + hot * m_med_hot * 0.55
            sl_CC = sl_CC * (1.0 - hot * 0.55) + hot * 0.96 * 0.55
            # sub-spiral bright sweep
            sl_M = sl_M + spiral * 0.18
            sl_CC = sl_CC + spiral * 0.20
            M[y0m:y1m, x0m:x1m] = sl_M
            R[y0m:y1m, x0m:x1m] = sl_R
            CC[y0m:y1m, x0m:x1m] = sl_CC
    out = np.stack([np.clip(M, 0, 1), np.clip(R, 0, 1), np.clip(CC, 0, 1)], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
cc_spot_polish._spb_concept_complete = True


def cc_gloss_stripe(shape, seed, sm, num_stripes=6, stripe_width=0.06, angle_deg=0.0, **kwargs):
    """cc_gloss_stripe â€” R6 OWNER-CORRECTIVE.

    identity: Owner rated 3/REBUILD: "doesn't match its name, generic noise,
    boring". Rewritten so STRIPES read instantly. Many narrow parallel
    glossy clearcoat STRIPES (12-22 px period) running the full canvas at
    one shared angle. Every stripe is razor-sharp on the CC channel (high
    gloss spine) with a soft falloff. Cross-stripe hair-fine pinstripes
    (every 3rd stripe) add rhythm. NEW HERO: per-stripe RAINBOW CHROMA
    shift â€” each stripe picks an independent M/R/CC point, creating real
    stripe identity instead of noise. Plus fine pinpoint shimmer + buff
    micro-streaks IN the bright stripes only. NEW WEIRD MOTIF: lissajous-
    rolled pinpoint sparkles ride along every 5th stripe like a metallic
    flake highway.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 60450)
    mn = min(h, w); scale = max(mn / 256.0, 0.5)

    # Pick stripe angle and period
    base_angle = float(np.deg2rad(angle_deg + rng.uniform(-25, 25)))
    cos_a, sin_a = float(np.cos(base_angle)), float(np.sin(base_angle))
    period = float(rng.uniform(14.0, 22.0))  # 14-22 px stripe-pair period â€” FINE
    half_glossy = float(rng.uniform(2.8, 4.5))  # bright stripe half-width
    # Stripe coordinate u = perpendicular distance from origin to a point
    yy = np.arange(h, dtype=np.float32)[:, np.newaxis]
    xx = np.arange(w, dtype=np.float32)[np.newaxis, :]
    u = (-sin_a) * xx + cos_a * yy  # perpendicular axis
    # Stripe index (integer) and local in-stripe coordinate
    stripe_idx = np.floor(u / period).astype(np.int32)
    in_stripe = (u / period) - stripe_idx  # 0..1

    # Triangle profile: 1 at stripe center, 0 at edges
    centered = np.abs(in_stripe - 0.5) * 2.0  # 0 at center, 1 at edge
    gloss_mask = np.clip(1.0 - centered * (period / (2.0 * half_glossy)), 0.0, 1.0)
    gloss_mask = gloss_mask ** 2.2  # sharpen falloff

    # --- SUBSTRATE composite-DARK (low all 3 channels per palette rule)
    M = np.full((h, w), 0.18, dtype=np.float32)
    R_ch = np.full((h, w), 0.62, dtype=np.float32)  # matte trough between gloss
    CC = np.full((h, w), 0.10, dtype=np.float32)

    # Per-stripe chroma â€” wide independent M/R/CC per stripe.
    n_stripes_seen = int(stripe_idx.max() - stripe_idx.min() + 1)
    stripe_min = int(stripe_idx.min())
    stripe_M_lut = rng.uniform(0.45, 0.96, n_stripes_seen + 4).astype(np.float32)
    stripe_R_lut = rng.uniform(0.06, 0.42, n_stripes_seen + 4).astype(np.float32)
    stripe_CC_lut = rng.uniform(0.55, 0.99, n_stripes_seen + 4).astype(np.float32)
    si = stripe_idx - stripe_min

    stripe_M = stripe_M_lut[si]
    stripe_R = stripe_R_lut[si]
    stripe_CC = stripe_CC_lut[si]

    # Blend toward stripe-specific gloss values within mask
    M = M * (1.0 - gloss_mask) + stripe_M * gloss_mask
    R_ch = R_ch * (1.0 - gloss_mask) + stripe_R * gloss_mask
    CC = CC * (1.0 - gloss_mask) + stripe_CC * gloss_mask

    # Cross-axis hair-fine pinstripe every 3rd stripe (8 px period along stripe)
    every_third = ((stripe_idx - stripe_min) % 3 == 0).astype(np.float32)
    along = cos_a * xx + sin_a * yy
    pin = (np.abs(np.mod(along, 9.0) - 4.5) < 0.6).astype(np.float32) * every_third * gloss_mask
    CC = np.maximum(CC, pin * 0.99)
    M = np.maximum(M, pin * 0.92)

    if _CV2_OK:
        # Lissajous "metallic flake highway" along every 5th stripe â€” a wandering
        # high-density pinpoint trail.
        n_highways = max(2, int(n_stripes_seen / 5))
        for hi in range(n_highways):
            si_target = stripe_min + hi * 5 + int(rng.integers(0, 5))
            # Sample many points along the stripe centerline
            length_axis = float(np.hypot(w, h)) * 0.6
            n_pts = int(np.clip(length_axis / 1.4, 80, 600))
            ts = np.linspace(-length_axis * 0.5, length_axis * 0.5, n_pts)
            # Lissajous wobble across stripe (small)
            wob = np.sin(ts * 0.08 + hi) * (half_glossy * 0.7)
            # Center of this stripe
            u_center = (si_target + 0.5) * period
            for k in range(n_pts):
                ux = (-sin_a) * 0 + cos_a * 0  # placeholder
                # Reconstruct (x,y) from (u_center + wob[k], ts[k]) using inverse basis
                ub = u_center + wob[k]
                tb = ts[k]
                xpt = int(round(cos_a * tb + (-sin_a) * ub + w * 0.5))
                ypt = int(round(sin_a * tb + cos_a * ub + h * 0.5))
                if 0 <= xpt < w and 0 <= ypt < h:
                    M[ypt, xpt] = float(rng.uniform(0.85, 0.99))
                    CC[ypt, xpt] = float(rng.uniform(0.88, 0.99))
                    R_ch[ypt, xpt] = float(rng.uniform(0.02, 0.10))

        # Buff micro-streaks INSIDE the gloss stripes only â€” 5-9 px segments at stripe angle
        n_buff = int(np.clip(900 * (mn / 256.0) ** 2, 350, 3000))
        for _ in range(n_buff):
            sx = int(rng.integers(0, w)); sy = int(rng.integers(0, h))
            # Test if we're in a bright stripe
            if gloss_mask[sy, sx] < 0.55:
                continue
            L = float(rng.uniform(5.0, 10.0) * scale)
            ang = base_angle + float(rng.uniform(-0.05, 0.05))
            x1 = int(sx + np.cos(ang) * L); y1 = int(sy + np.sin(ang) * L)
            v_cc = float(rng.uniform(0.88, 0.99))
            v_m = float(rng.uniform(0.70, 0.95))
            _cv2.line(CC, (sx, sy), (x1, y1), v_cc, 1, lineType=_cv2.LINE_AA)
            _cv2.line(M, (sx, sy), (x1, y1), v_m, 1, lineType=_cv2.LINE_AA)

        # Pinpoint shimmer ALL OVER â€” 1 px sparks
        n_sparks = int(np.clip(1800 * (mn / 256.0) ** 2, 700, 6000))
        spx = rng.integers(0, w, n_sparks); spy = rng.integers(0, h, n_sparks)
        spark_M = rng.uniform(0.65, 0.99, n_sparks).astype(np.float32)
        spark_CC = rng.uniform(0.70, 0.99, n_sparks).astype(np.float32)
        M[spy, spx] = np.maximum(M[spy, spx], spark_M)
        CC[spy, spx] = np.maximum(CC[spy, spx], spark_CC)

    # Per-pixel chroma jitter (broad value distribution)
    M = np.clip(M + rng.uniform(-0.03, 0.03, (h, w)).astype(np.float32), 0, 1)
    R_ch = np.clip(R_ch + rng.uniform(-0.04, 0.04, (h, w)).astype(np.float32), 0, 1)
    CC = np.clip(CC + rng.uniform(-0.04, 0.04, (h, w)).astype(np.float32), 0, 1)

    out = np.stack([M, R_ch, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
cc_gloss_stripe._spb_concept_complete = True


def cc_wet_zone(shape, seed, sm, num_zones=5, **kwargs):
    """cc_wet_zone.

    identity: R6 creative rebuild â€” irregular wet-clearcoat patches with
    new HERO tier of elongated tear-drop puddles (anisotropic warping)
    plus surface tension capillary fingerlets reaching off the patch
    edges. FIVE stacked tiers: (1) dryish FBM substrate, (2) macro
    amoeba wet-patch blobs (FBM-thresholded mask), (3) HERO tear-drop
    streaks where puddles ran during application, (4) meniscus reflection
    beads on rim, (5) edge-tension capillary fingers + surface dust
    flecks. Per-feature INDEPENDENT M/R/CC continuous uniforms.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 64711)
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)

    # Dryish base
    fbm_a = _normalize(multi_scale_noise(shape, [4.0, 11.0, 26.0], [0.42, 0.34, 0.24], seed + 211))
    fbm_b = _normalize(multi_scale_noise(shape, [5.0, 12.0, 28.0], [0.40, 0.34, 0.26], seed + 213))
    M = (0.38 + (fbm_a - 0.5) * 0.18).astype(np.float32)
    R = (0.55 + (fbm_b - 0.5) * 0.20).astype(np.float32)
    CC = (0.30 + (fbm_a - 0.5) * 0.14 + (fbm_b - 0.5) * 0.10).astype(np.float32)

    # KEY IDENTITY â€” irregular blob mask via low-freq FBM, thresholded soft
    blob_noise = _normalize(multi_scale_noise(shape, [22.0, 44.0, 88.0], [0.50, 0.30, 0.20], seed + 215))
    # Smooth threshold for soft amoeba edges
    blob_mask = np.clip((blob_noise - 0.50) * 4.0, 0.0, 1.0).astype(np.float32)
    # Center darkness â€” invert the blob inward where mask is densest
    deep_mask = np.clip((blob_noise - 0.62) * 6.0, 0.0, 1.0).astype(np.float32)

    # Apply wet patches: glossy CC ramp, low R, high M
    M = M + blob_mask * 0.35
    R = R - blob_mask * 0.42
    CC = CC + blob_mask * 0.55
    # Deep center darkens slightly (wet pool depth)
    M = M - deep_mask * 0.12
    CC = CC + deep_mask * 0.10

    # Add chroma jitter per-pixel scaled by blob to keep diversity inside puddles
    chroma_jit = (_normalize(multi_scale_noise(shape, [3.0, 7.0], [0.6, 0.4], seed + 217)) - 0.5).astype(np.float32)
    M = M + chroma_jit * blob_mask * 0.10
    R = R - chroma_jit * blob_mask * 0.06
    CC = CC + chroma_jit * blob_mask * 0.08

    np.clip(M, 0, 1, out=M); np.clip(R, 0, 1, out=R); np.clip(CC, 0, 1, out=CC)

    if _CV2_OK:
        # MENISCUS BEADS â€” bright tiny reflection spots that sit only INSIDE
        # the wet patches (rejection sampled)
        n_bead = int(np.clip(1200 * (mn / 2048.0) ** 2, 400, 3000))
        kept = 0; attempts = 0
        while kept < n_bead and attempts < n_bead * 4:
            attempts += 1
            cx = int(rng.uniform(0, w)); cy = int(rng.uniform(0, h))
            if rng.random() > blob_mask[cy, cx] * 0.92 + 0.05:
                continue
            kept += 1
            r = max(1, int(rng.uniform(1.5, 3.0) * scale))
            _cv2.circle(M, (cx, cy), r, float(rng.uniform(0.75, 0.98)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r, float(rng.uniform(0.03, 0.15)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r, float(rng.uniform(0.80, 0.98)), -1, lineType=_cv2.LINE_AA)
        # EDGE TENSION CURVES â€” short arcs that hint at meniscus edges
        # placed where blob_mask gradient is high (puddle rim)
        # Cheap rim detector: gradient magnitude approx
        gx = np.abs(np.diff(blob_mask, axis=1, prepend=0)).astype(np.float32)
        gy = np.abs(np.diff(blob_mask, axis=0, prepend=0)).astype(np.float32)
        rim = np.clip((gx + gy) * 3.0, 0.0, 1.0)
        n_arc = int(np.clip(700 * (mn / 2048.0) ** 2, 240, 1800))
        kept = 0; attempts = 0
        while kept < n_arc and attempts < n_arc * 4:
            attempts += 1
            cx = int(rng.uniform(6, w - 6)); cy = int(rng.uniform(6, h - 6))
            if rng.random() > rim[cy, cx] * 0.85 + 0.05:
                continue
            kept += 1
            r = max(2, int(rng.uniform(4.0, 9.0) * scale))
            a0 = float(rng.uniform(0, 360)); sweep = float(rng.uniform(40, 110))
            _cv2.ellipse(M, (cx, cy), (r, r), 0.0, a0, a0 + sweep, float(rng.uniform(0.55, 0.92)), 1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(CC, (cx, cy), (r, r), 0.0, a0, a0 + sweep, float(rng.uniform(0.55, 0.94)), 1, lineType=_cv2.LINE_AA)

        # HERO TEAR-DROP RUN PUDDLES â€” 5-10 elongated streaks anchored at random
        # puddle interior points and running downward/outward
        n_tear = int(rng.integers(5, 11))
        for _ in range(n_tear):
            # Find a point inside a wet patch
            tries = 0
            tx_ = 0; ty_ = 0
            while tries < 30:
                tries += 1
                cx = int(rng.uniform(0, w)); cy = int(rng.uniform(0, h * 0.85))
                if blob_mask[cy, cx] > 0.5:
                    tx_ = cx; ty_ = cy
                    break
            if tries >= 30:
                continue
            tlen = int(rng.uniform(18, 38) * scale * (mn / 256.0))
            tdir = float(rng.uniform(-0.40, 0.40))  # slight angle
            tx2 = int(np.clip(tx_ + tdir * tlen, 0, w - 1))
            ty2 = int(np.clip(ty_ + tlen, 0, h - 1))
            thick = max(2, int(rng.uniform(3, 7) * scale))
            tm = float(rng.uniform(0.65, 0.97))
            tr = float(rng.uniform(0.03, 0.18))
            tc = float(rng.uniform(0.75, 0.99))
            _cv2.line(M, (tx_, ty_), (tx2, ty2), tm, thick, lineType=_cv2.LINE_AA)
            _cv2.line(R, (tx_, ty_), (tx2, ty2), tr, thick, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (tx_, ty_), (tx2, ty2), tc, thick, lineType=_cv2.LINE_AA)
            # tear bead at tip
            rb = max(2, int(thick * 0.9))
            _cv2.circle(M, (tx2, ty2), rb, float(np.clip(tm + 0.05, 0, 1)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (tx2, ty2), rb, float(np.clip(tr * 0.5, 0, 1)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (tx2, ty2), rb, float(np.clip(tc + 0.02, 0, 1)), -1, lineType=_cv2.LINE_AA)

        # CAPILLARY FINGERLETS â€” tiny hair-thin tendrils reaching off rims
        n_cap = int(np.clip(900 * (mn / 2048.0) ** 2, 320, 2400))
        kept = 0; attempts = 0
        while kept < n_cap and attempts < n_cap * 4:
            attempts += 1
            cx = int(rng.uniform(4, w - 4)); cy = int(rng.uniform(4, h - 4))
            if rng.random() > rim[cy, cx] * 0.80 + 0.04:
                continue
            kept += 1
            clen = int(rng.uniform(4, 11) * scale)
            cang = float(rng.uniform(0, 2 * np.pi))
            cx1 = int(np.clip(cx + np.cos(cang) * clen, 0, w - 1))
            cy1 = int(np.clip(cy + np.sin(cang) * clen, 0, h - 1))
            _cv2.line(M, (cx, cy), (cx1, cy1), float(rng.uniform(0.50, 0.92)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (cx, cy), (cx1, cy1), float(rng.uniform(0.55, 0.95)), 1, lineType=_cv2.LINE_AA)

    # SURFACE DUST FLECKS â€” full canvas coverage (outside wet zones reads matte)
    n_dust = int(np.clip(1600 * (mn / 2048.0) ** 2, 600, 4200))
    fxx = rng.integers(0, w, n_dust); fyy = rng.integers(0, h, n_dust)
    M[fyy, fxx] = np.minimum(M[fyy, fxx], rng.uniform(0.18, 0.45, n_dust).astype(np.float32))
    R[fyy, fxx] = np.maximum(R[fyy, fxx], rng.uniform(0.45, 0.78, n_dust).astype(np.float32))

    out = np.stack([np.clip(M, 0, 1), np.clip(R, 0, 1), np.clip(CC, 0, 1)], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
cc_wet_zone._spb_concept_complete = True



def cc_panel_fade(shape, seed, sm, fade_direction=0.0, noise_warp=0.06, **kwargs):
    """cc_panel_fade.

    identity: ROUND-6 CREATIVE SECOND-PASS â€” a clearcoat panel where the
    UV burn isn't sun-rivers anymore; it's been COLONISED by FRACTAL
    LICHEN. NEW HERO motif: dendrite-branching lichen colonies (biology /
    L-system / DLA-flavour) creeping in from one edge of the fade axis,
    each colony 18-38 px wide, made of 1-3 px branched lines that
    bifurcate at 25-40Â°. Across the substrate the panel reads STORM
    BLUE-GREY (M=0.22 R=0.30 CC=0.45, well under anti-magenta cap).
    Six tiers: (1) cool-storm FBM substrate w/ very mild fade bias,
    (2) HERO fractal lichen colonies, (3) leopard cluster polish-spots
    3-7 px, (4) very fine 3-7 px UV-burn micro hatches perp to fade,
    (5) tight 3-6 px gravity drips, (6) per-pixel pigment flecks.
    Substrate is composite-dark cool; Mâ‰¤0.35 enforced.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 47720)
    mn = min(h, w); scale = max(mn / 2048.0, 0.25); s256 = max(mn / 256.0, 0.6)
    angle = float(np.deg2rad(fade_direction + rng.uniform(-18, 18)))
    cos_a = float(np.cos(angle)); sin_a = float(np.sin(angle))
    perp_a = angle + np.pi * 0.5
    cos_p = float(np.cos(perp_a)); sin_p = float(np.sin(perp_a))
    denom = (w * abs(cos_a) + h * abs(sin_a) + 1e-7)

    # 1) BASE â€” STORM BLUE-GREY substrate (Mâ‰ˆ0.22 Râ‰ˆ0.30 CCâ‰ˆ0.45) with mild axial fade
    yy = np.arange(h, dtype=np.float32)[:, None]
    xx = np.arange(w, dtype=np.float32)[None, :]
    t_field = np.clip(((xx * cos_a + yy * sin_a) / denom + 0.5), 0, 1).astype(np.float32)
    fbm_M = _normalize(multi_scale_noise(shape, [1.5, 4.0, 9.0], [0.42, 0.34, 0.24], int(seed) + 121))
    fbm_R = _normalize(multi_scale_noise(shape, [1.8, 5.0, 11.0], [0.40, 0.34, 0.26], int(seed) + 123))
    fbm_CC = _normalize(multi_scale_noise(shape, [2.0, 6.0, 13.0], [0.40, 0.34, 0.26], int(seed) + 125))
    # storm blue-grey: keep M low (â‰¤0.35) â€” anti-magenta safe; CC mid for storm hue
    M = (0.22 + t_field * 0.10 + (fbm_M - 0.5) * 0.10).astype(np.float32)
    R = (0.30 + t_field * 0.06 + (fbm_R - 0.5) * 0.08).astype(np.float32)
    CC = (0.45 - t_field * 0.10 + (fbm_CC - 0.5) * 0.14).astype(np.float32)
    np.clip(M, 0, 1, out=M); np.clip(R, 0, 1, out=R); np.clip(CC, 0, 1, out=CC)

    if _CV2_OK:
        # 2) HERO â€” FRACTAL LICHEN COLONIES (L-system / DLA branched dendrites)
        n_colonies = int(np.clip(48 * s256, 22, 110))

        def _branch(x, y, ang, depth, base_M, base_R, base_CC, max_seg):
            if depth <= 0:
                return
            seg = max(1.0, float(rng.uniform(2.0, 3.8) * s256))
            n_segs = int(rng.integers(3, max_seg))
            cur_ang = ang
            for _i in range(n_segs):
                cur_ang += float(rng.uniform(-0.18, 0.18))
                x2 = x + np.cos(cur_ang) * seg
                y2 = y + np.sin(cur_ang) * seg
                if not (1 <= x2 < w - 1 and 1 <= y2 < h - 1):
                    return
                vM = float(np.clip(base_M + rng.uniform(-0.05, 0.05), 0.10, 0.95))
                vR = float(np.clip(base_R + rng.uniform(-0.05, 0.05), 0.05, 0.90))
                vCC = float(np.clip(base_CC + rng.uniform(-0.06, 0.06), 0.05, 0.95))
                _cv2.line(M, (int(x), int(y)), (int(x2), int(y2)), vM, 1, lineType=_cv2.LINE_AA)
                _cv2.line(R, (int(x), int(y)), (int(x2), int(y2)), vR, 1, lineType=_cv2.LINE_AA)
                _cv2.line(CC, (int(x), int(y)), (int(x2), int(y2)), vCC, 1, lineType=_cv2.LINE_AA)
                # bifurcate sometimes â€” fractal branching at 25-40Â°
                if depth > 1 and rng.random() < 0.45:
                    split_ang = float(np.deg2rad(rng.uniform(25, 40))) * (1 if rng.random() < 0.5 else -1)
                    _branch(x2, y2, cur_ang + split_ang, depth - 1, base_M, base_R, base_CC, max_seg - 1)
                x, y = x2, y2

        for _ in range(n_colonies):
            cx0 = float(rng.integers(8, max(9, w - 8)))
            cy0 = float(rng.integers(8, max(9, h - 8)))
            # Colony chroma â€” one base per colony; lichen reads bright bluish or coppery
            if rng.random() < 0.5:
                base_M = float(rng.uniform(0.45, 0.78))   # bright spot
                base_R = float(rng.uniform(0.18, 0.40))
                base_CC = float(rng.uniform(0.60, 0.92))  # cool lichen
            else:
                base_M = float(rng.uniform(0.30, 0.55))
                base_R = float(rng.uniform(0.45, 0.78))
                base_CC = float(rng.uniform(0.18, 0.45))  # copper lichen
            # bright nucleus dot
            cr = max(1, int(rng.uniform(2.0, 4.0) * 0.5 * s256))
            _cv2.circle(M, (int(cx0), int(cy0)), cr, float(np.clip(base_M + 0.10, 0, 0.99)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (int(cx0), int(cy0)), cr, float(np.clip(base_R - 0.08, 0.05, 0.95)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (int(cx0), int(cy0)), cr, float(np.clip(base_CC + 0.05, 0.05, 0.99)), -1, lineType=_cv2.LINE_AA)
            # 4-7 primary arms radiating from nucleus
            n_arms = int(rng.integers(4, 8))
            for k in range(n_arms):
                a0 = (k / n_arms) * 2 * np.pi + float(rng.uniform(-0.25, 0.25))
                _branch(cx0, cy0, a0, depth=3, base_M=base_M, base_R=base_R, base_CC=base_CC, max_seg=6)

        # 3) LEOPARD CLUSTER POLISH-SPOTS (groups of 3-7 px circles)
        n_clusters = int(np.clip(120 * s256, 30, 320))
        for _ in range(n_clusters):
            ccx = float(rng.integers(8, max(9, w - 8))); ccy = float(rng.integers(8, max(9, h - 8)))
            n_in = int(rng.integers(3, 7))
            for _i in range(n_in):
                dx_ = rng.uniform(-10, 10) * s256; dy_ = rng.uniform(-10, 10) * s256
                cx = int(np.clip(ccx + dx_, 0, w - 1)); cy = int(np.clip(ccy + dy_, 0, h - 1))
                r = max(1, int(rng.uniform(2.0, 4.0) * 0.5 * s256))
                _cv2.circle(M, (cx, cy), r, float(rng.uniform(0.35, 0.85)), -1, lineType=_cv2.LINE_AA)
                _cv2.circle(R, (cx, cy), r, float(rng.uniform(0.10, 0.32)), -1, lineType=_cv2.LINE_AA)
                _cv2.circle(CC, (cx, cy), r, float(rng.uniform(0.45, 0.85)), -1, lineType=_cv2.LINE_AA)

        # 4) UV-BURN MICRO HATCHES â€” 3-7 px (tighter than before)
        n_h = int(np.clip(1100 * s256 * s256, 350, 3200))
        for _ in range(n_h):
            cx = float(rng.integers(4, max(5, w - 4))); cy = float(rng.integers(4, max(5, h - 4)))
            length = float(rng.uniform(3.0, 7.0) * s256)
            x1 = int(np.clip(cx - cos_p * length * 0.5, 0, w - 1))
            y1 = int(np.clip(cy - sin_p * length * 0.5, 0, h - 1))
            x2 = int(np.clip(cx + cos_p * length * 0.5, 0, w - 1))
            y2 = int(np.clip(cy + sin_p * length * 0.5, 0, h - 1))
            _cv2.line(M, (x1, y1), (x2, y2), float(rng.uniform(0.18, 0.55)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(R, (x1, y1), (x2, y2), float(rng.uniform(0.20, 0.50)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (x1, y1), (x2, y2), float(rng.uniform(0.20, 0.55)), 1, lineType=_cv2.LINE_AA)

        # 5) GRAVITY DRIPS â€” 3-6 px scattered everywhere (no t-bias gate)
        n_runs = int(np.clip(550 * s256 * s256, 180, 1800))
        for _ in range(n_runs):
            cx = int(rng.integers(2, max(3, w - 2)))
            cy = int(rng.integers(2, max(3, h - 6)))
            length = int(rng.uniform(3.0, 6.0) * s256)
            cy2 = min(h - 1, cy + length)
            _cv2.line(M, (cx, cy), (cx, cy2), float(rng.uniform(0.30, 0.70)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(R, (cx, cy), (cx, cy2), float(rng.uniform(0.20, 0.50)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (cx, cy), (cx, cy2), float(rng.uniform(0.15, 0.50)), 1, lineType=_cv2.LINE_AA)

    # 6) PIGMENT FLECKS â€” per-pixel TIGHT around storm palette
    n_flecks = max(2000, int(h * w / 1300))
    fx = rng.integers(0, w, n_flecks); fy = rng.integers(0, h, n_flecks)
    M[fy, fx] = np.clip(0.25 + rng.uniform(-0.12, 0.55, n_flecks).astype(np.float32), 0, 1)
    R[fy, fx] = np.clip(0.30 + rng.uniform(-0.12, 0.35, n_flecks).astype(np.float32), 0, 1)
    CC[fy, fx] = np.clip(0.45 + rng.uniform(-0.20, 0.40, n_flecks).astype(np.float32), 0, 1)

    out = np.stack([np.clip(M, 0, 1), np.clip(R, 0, 1), np.clip(CC, 0, 1)], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
cc_panel_fade._spb_concept_complete = True


# ============================================================================
# PRIORITY 2 BATCH E: ðŸ—ï¸ GEOMETRIC & ARCHITECTURAL (124â€“135)
# Precise geometric structures from architecture, industrial design, faceted surfaces.
# Each uses mathematically distinct geometry targeting R=Metallic channel primarily.
# ============================================================================

def spec_faceted_diamond(shape, seed, sm, num_cells=120, **kwargs):
    """spec_faceted_diamond.

    identity: Round-6 OWNER CORRECTIVE â€” owner: "Diamond Pattern needs to be
    spaced better and alot more of them". Now a STRICT DIAMOND (rhombus)
    TESSELLATION grid â€” every facet is a true diamond/rhombus shape, packed
    tight at 10-14 px size with regular geometric spacing, dramatically more
    facets than before. Stacked tiers:
      (1) RHOMBUS TILE GRID â€” true diamond cells at fixed pitch, each with
          per-facet INDEPENDENT M/R/CC and centre-bright shading.
      (2) Crisp 1-2 px bevel-edge ridges between every diamond pair.
      (3) Bright pinpoint sparkle at the centre of every diamond.
      (4) Sparse 18-28 px HERO BRILLIANT-CUT diamonds â€” 14-22 of them
          drawn as bright outlined rhombus facets with 4-spoke internal
          star (the gemstone table-cut signature).
      (5) Dense rainbow fire carpet for spectral character.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 2704)
    mn = float(min(h, w))
    scale = max(mn / 256.0, 0.6)

    # Diamond rhombus tessellation â€” pitch 10-14 px (was target 12-18, now denser)
    target_px = float(np.clip(np.sqrt((h * w) / 480.0), 7.0, 12.0))
    n_grid_y = max(14, int(h / target_px))
    n_grid_x = max(14, int(w / target_px))
    # Offset every other row by half-pitch to create the diamond row stagger
    pitch_y = h / max(n_grid_y, 1)
    pitch_x = w / max(n_grid_x, 1)
    site_list = []
    for iy in range(n_grid_y + 1):
        for ix in range(n_grid_x + 1):
            ys = iy * pitch_y + (pitch_y * 0.5 if (ix % 2 == 1) else 0.0)
            xs = ix * pitch_x
            ys += float(rng.uniform(-pitch_y * 0.10, pitch_y * 0.10))
            xs += float(rng.uniform(-pitch_x * 0.10, pitch_x * 0.10))
            if 0 <= ys < h and 0 <= xs < w:
                site_list.append((ys, xs))
    sites = np.array(site_list, dtype=np.float32) if site_list else np.array([[h/2, w/2]], dtype=np.float32)
    n_sites = len(sites)

    # Per-facet INDEPENDENT continuous uniforms (WIDE range)
    site_M = rng.uniform(0.38, 0.99, size=n_sites).astype(np.float32)
    site_R = rng.uniform(0.02, 0.30, size=n_sites).astype(np.float32)
    site_CC = rng.uniform(0.28, 0.99, size=n_sites).astype(np.float32)

    yy_g, xx_g = np.mgrid[0:h, 0:w]
    pts = np.column_stack([yy_g.ravel(), xx_g.ravel()]).astype(np.float64)
    tree = cKDTree(sites.astype(np.float64))
    dd, idx = tree.query(pts, k=2)
    idx_near = idx[:, 0].reshape(h, w)
    edge_dist = (dd[:, 1] - dd[:, 0]).reshape(h, w).astype(np.float32)

    M = site_M[idx_near]
    R_ch = site_R[idx_near]
    CC = site_CC[idx_near]

    inside_dist = dd[:, 0].reshape(h, w).astype(np.float32)
    inside_norm = np.clip(inside_dist / max(target_px, 1.0), 0.0, 1.2)
    shade = 1.0 - inside_norm * 0.38
    M = M * shade
    CC = CC * (0.84 + (1.0 - inside_norm) * 0.20)

    # Bright crisp bevel edges
    edge_mask = np.exp(-edge_dist / max(1.1, scale * 1.0))
    M = M + edge_mask * (0.96 - M) * 0.92
    R_ch = R_ch + edge_mask * (0.02 - R_ch) * 0.88
    CC = CC + edge_mask * (0.98 - CC) * 0.90

    if _CV2_OK:
        # Star pinpoint at centre of every facet
        for i in range(n_sites):
            cy0 = int(sites[i, 0]); cx0 = int(sites[i, 1])
            if not (0 <= cy0 < h and 0 <= cx0 < w):
                continue
            rr = int(max(1, rng.uniform(1.2, 2.6)))
            _cv2.circle(M, (cx0, cy0), rr, float(rng.uniform(0.88, 0.99)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R_ch, (cx0, cy0), rr, float(rng.uniform(0.02, 0.10)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx0, cy0), rr, float(rng.uniform(0.88, 0.99)), -1, lineType=_cv2.LINE_AA)

        # NEW HERO â€” BRILLIANT-CUT DIAMOND RHOMBI (replaces curvy fire-arcs
        # the owner called "random lines"). 14-22 hero diamonds at 18-28 px.
        n_hero = int(rng.integers(14, 23))
        for _ in range(n_hero):
            tcx = float(rng.uniform(0.10, 0.90) * w); tcy = float(rng.uniform(0.10, 0.90) * h)
            tr_long = float(rng.uniform(10.0, 14.0) * (scale / 1.2))
            tr_short = tr_long * float(rng.uniform(0.55, 0.70))
            rot = float(rng.uniform(0, np.pi))
            ca_r = float(np.cos(rot)); sa_r = float(np.sin(rot))
            # rhombus 4 corners: top/bottom along long axis, left/right along short
            p_top = (int(tcx + ca_r * 0 - sa_r * tr_long),  int(tcy + sa_r * 0 + ca_r * tr_long))
            p_bot = (int(tcx - ca_r * 0 + sa_r * tr_long),  int(tcy - sa_r * 0 - ca_r * tr_long))
            p_lt  = (int(tcx - ca_r * tr_short - sa_r * 0), int(tcy - sa_r * tr_short + ca_r * 0))
            p_rt  = (int(tcx + ca_r * tr_short + sa_r * 0), int(tcy + sa_r * tr_short - ca_r * 0))
            poly = np.array([p_top, p_rt, p_bot, p_lt], dtype=np.int32)
            tM = float(rng.uniform(0.80, 0.97))
            tR = float(rng.uniform(0.04, 0.14))
            tC = float(rng.uniform(0.85, 0.98))
            _cv2.fillPoly(M,    [poly], tM, lineType=_cv2.LINE_AA)
            _cv2.fillPoly(R_ch, [poly], tR, lineType=_cv2.LINE_AA)
            _cv2.fillPoly(CC,   [poly], tC, lineType=_cv2.LINE_AA)
            # crisp dark outline
            _cv2.polylines(M,    [poly], True, float(rng.uniform(0.25, 0.45)), 1, lineType=_cv2.LINE_AA)
            _cv2.polylines(R_ch, [poly], True, float(rng.uniform(0.30, 0.55)), 1, lineType=_cv2.LINE_AA)
            # inner 4-spoke gemstone star (table-cut signature)
            for ep in (p_top, p_bot, p_lt, p_rt):
                _cv2.line(M,  (int(tcx), int(tcy)), ep, float(rng.uniform(0.92, 0.99)), 1, lineType=_cv2.LINE_AA)
                _cv2.line(CC, (int(tcx), int(tcy)), ep, float(rng.uniform(0.92, 0.99)), 1, lineType=_cv2.LINE_AA)

    # Light rainbow fire pinpoints (reduced â€” owner said it was too noisy)
    n_fire = int(np.clip(mn * mn / 380.0, 400, 2800))
    fy = rng.integers(0, h, size=n_fire)
    fx = rng.integers(0, w, size=n_fire)
    M[fy, fx] = rng.uniform(0.60, 0.99, size=n_fire).astype(np.float32)
    R_ch[fy, fx] = rng.uniform(0.02, 0.22, size=n_fire).astype(np.float32)
    CC[fy, fx] = rng.uniform(0.50, 0.99, size=n_fire).astype(np.float32)

    out = np.stack([M.astype(np.float32), R_ch.astype(np.float32), CC.astype(np.float32)], axis=-1)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
spec_faceted_diamond._spb_concept_complete = True


def spec_hammered_dimple(shape, seed, sm, **kwargs):
    """spec_hammered_dimple.

    identity: OP-ART MOIRE (Bridget Riley). Two grids of parallel lines at a
    slight angle offset (3-7Â°) generate banded wave interference. A second
    layer adds concentric rings â†’ curved moire. M oscillates 1-3 px scale,
    R follows inverse, CC carries the iridescent shift.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 911005)

    yy, xx = np.indices((h, w), dtype=np.float32)
    ang1 = float(rng.uniform(0, np.pi))
    ang2 = ang1 + np.deg2rad(float(rng.uniform(3.0, 7.0)))
    pitch1 = float(rng.uniform(4.0, 6.5))
    pitch2 = float(rng.uniform(4.0, 6.5))
    line_w = float(rng.uniform(1.4, 2.6))

    proj1 = xx * np.cos(ang1) + yy * np.sin(ang1)
    proj2 = xx * np.cos(ang2) + yy * np.sin(ang2)
    # square wave: lines at integer multiples of pitch
    band1 = (np.mod(proj1, pitch1) < line_w).astype(np.float32)
    band2 = (np.mod(proj2, pitch2) < line_w).astype(np.float32)
    # interference: XOR-like
    interf = (band1 + band2) % 2.0  # 0,1
    overlap = np.minimum(band1, band2)  # both â†’ bright spot

    # Concentric rings layer (curved moire) â€” small radius range
    cy, cx = h * 0.5, w * 0.5
    r = np.hypot(yy - cy, xx - cx)
    ring_pitch = float(rng.uniform(5.0, 8.0))
    rings = (np.mod(r, ring_pitch) < line_w).astype(np.float32)

    M = np.full((h, w), 0.42, dtype=np.float32)
    M += interf * 0.30
    M += overlap * 0.25
    M -= rings * 0.20

    R_ch = np.full((h, w), 0.55, dtype=np.float32)
    R_ch -= interf * 0.25
    R_ch += rings * 0.15

    # CC carries the iridescent shift â€” different per ring band
    CC = (0.45 + 0.35 * np.sin(r * (2.0 * np.pi / ring_pitch))).astype(np.float32)
    CC += (band1 - band2) * 0.20  # diff drives chroma

    # Per-pixel jitter for chroma diversity
    M = np.clip(M + rng.uniform(-0.04, 0.04, (h, w)).astype(np.float32), 0.0, 1.0)
    CC = np.clip(CC + rng.uniform(-0.06, 0.06, (h, w)).astype(np.float32), 0.0, 1.0)
    R_ch = np.clip(R_ch, 0.0, 1.0)

    out = np.stack([M, R_ch, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
spec_hammered_dimple._spb_concept_complete = True



def spec_knurled_diamond(shape, seed, sm, frequency=80.0, angle_deg=60.0, **kwargs):
    """spec_knurled_diamond.

    identity: R6-creative rebuild - MILLED ALUMINUM DIAMOND PLATE with a
    realistic illumination story. Tight 5-9 px diamonds at +/-60deg with
    per-diamond INDEPENDENT continuous M/R/CC, PLUS a NEW hero element: a
    sweeping diagonal CATCH-LIGHT band that brightens the diamond crests
    along one axis (the literal way real knurl reflects under shop light),
    AND alternating-orientation NEXT-NEIGHBOR contrast (every other
    diamond row darkened toward chrome-black to break uniformity). Eight
    stacked tiers: cell-hash base, crest/valley split, 3 px tool-tooth
    micro-crosshatch, sweeping catch-light, burnish hairlines, dark oil
    pits in valleys, ultra-dense pinpoint sparkle on crests, and CENTER
    pip-marks (1 px dark seed at each diamond center for the machined
    look).
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + (hash("spec_knurled_diamond_r6") % 10000))
    mn = float(min(h, w))
    scale = max(mn / 256.0, 0.6)
    yy = np.arange(h, dtype=np.float32)
    xx = np.arange(w, dtype=np.float32)
    Y, X = np.meshgrid(yy, xx, indexing='ij')

    # Tight diamond pitch
    angle_rad = np.deg2rad(angle_deg)
    period = float(np.clip(7.0 * (mn / 256.0), 5.5, 9.5))
    proj_a = X * np.cos(angle_rad) + Y * np.sin(angle_rad)
    proj_b = X * np.cos(-angle_rad) + Y * np.sin(-angle_rad)
    ridge_a = (np.cos(proj_a / period * 2.0 * np.pi) + 1.0) * 0.5
    ridge_b = (np.cos(proj_b / period * 2.0 * np.pi) + 1.0) * 0.5
    crest = ridge_a * ridge_b
    valley = (1.0 - ridge_a) * (1.0 - ridge_b)

    # 2) Per-diamond cell hash - INDEPENDENT M/R/CC
    diamond_id_a = np.floor(proj_a / period).astype(np.int32)
    diamond_id_b = np.floor(proj_b / period).astype(np.int32)
    def _hash01(a, b, off):
        ha = (a.astype(np.int64) * 73856093) ^ (b.astype(np.int64) * 19349663) ^ (int(seed) + off)
        return ((ha & 0xFFFF).astype(np.float32) / 65535.0)
    cell_M  = (0.50 + _hash01(diamond_id_a, diamond_id_b, 11) * 0.48).astype(np.float32)
    cell_R  = (0.08 + _hash01(diamond_id_a, diamond_id_b, 23) * 0.62).astype(np.float32)
    cell_CC = (0.05 + _hash01(diamond_id_a, diamond_id_b, 37) * 0.62).astype(np.float32)

    # 2b) ALTERNATING-ORIENTATION DARK CHECKER - every other diamond pair muted
    alt = ((diamond_id_a + diamond_id_b) & 1).astype(np.float32)
    cell_M = cell_M * (1.0 - alt * 0.35) + 0.18 * (alt * 0.35)
    cell_R = cell_R * (1.0 - alt * 0.20) + 0.55 * (alt * 0.20)

    # 3) Crest/valley mix
    crest_w = crest ** 0.6
    valley_w = valley ** 0.6
    M  = cell_M  * crest_w + (0.18 + _hash01(diamond_id_a, diamond_id_b, 41) * 0.32) * valley_w + 0.38 * (1.0 - crest_w - valley_w)
    R  = cell_R  * crest_w + (0.55 + _hash01(diamond_id_a, diamond_id_b, 43) * 0.40) * valley_w + 0.42 * (1.0 - crest_w - valley_w)
    CC = cell_CC * crest_w + (0.50 + _hash01(diamond_id_a, diamond_id_b, 47) * 0.42) * valley_w + 0.40 * (1.0 - crest_w - valley_w)

    # 4) HERO: sweeping diagonal CATCH-LIGHT band - the highlight that screams "metal"
    sweep_ang = float(rng.uniform(0, np.pi))
    sweep_proj = X * np.cos(sweep_ang) + Y * np.sin(sweep_ang)
    sweep_center = float(rng.uniform(0.35, 0.65)) * (np.cos(sweep_ang) * w + np.sin(sweep_ang) * h)
    sweep_width = float(mn * 0.28)
    sweep = np.exp(-((sweep_proj - sweep_center) ** 2) / (2.0 * sweep_width ** 2)).astype(np.float32)
    sweep_on_crests = sweep * crest_w
    M = np.clip(M + sweep_on_crests * 0.30, 0, 1)
    R = np.clip(R - sweep_on_crests * 0.18, 0, 1)
    CC = np.clip(CC + sweep_on_crests * 0.22, 0, 1)

    # 5) 3 px cut-tooth micro-crosshatch
    hatch_a = np.sin((X + Y) / 3.0 * 2.0 * np.pi)
    hatch_b = np.sin((X - Y) / 3.0 * 2.0 * np.pi)
    micro = (np.maximum(hatch_a, hatch_b) > 0.0).astype(np.float32)
    M = np.clip(M + (micro - 0.5) * 0.12, 0, 1)
    R = np.clip(R - (micro - 0.5) * 0.10, 0, 1)

    M = M.astype(np.float32); R = R.astype(np.float32); CC = CC.astype(np.float32)

    if _CV2_OK:
        # 6) Burnish hairlines on crests
        n_burn = max(2200, int(h * w / 280))
        for _ in range(n_burn):
            cx = rng.uniform(2, w - 2); cy = rng.uniform(2, h - 2)
            length = float(rng.uniform(5.0, 12.0) * scale)
            ang = angle_rad if rng.random() < 0.5 else -angle_rad
            ang += float(rng.normal(0.0, 0.12))
            x0s = int(cx - np.cos(ang) * length * 0.5); y0s = int(cy - np.sin(ang) * length * 0.5)
            x1s = int(cx + np.cos(ang) * length * 0.5); y1s = int(cy + np.sin(ang) * length * 0.5)
            _cv2.line(M, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.70, 0.99)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(R, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.04, 0.22)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.05, 0.28)), 1, lineType=_cv2.LINE_AA)
        # 7) Dark oil pits in valleys
        n_pit = max(1100, int(h * w / 600))
        py = rng.integers(0, h, n_pit); px = rng.integers(0, w, n_pit)
        M[py, px] = np.minimum(M[py, px], rng.uniform(0.06, 0.26, n_pit).astype(np.float32))
        R[py, px] = np.maximum(R[py, px], rng.uniform(0.55, 0.94, n_pit).astype(np.float32))

    # 8) Pinpoint sparkle on highest crests
    n_sp = int(np.clip(mn * mn / 60.0, 2800, 14000))
    sy = rng.integers(0, h, n_sp); sx = rng.integers(0, w, n_sp)
    mask = crest_w[sy, sx] > 0.42
    idx = np.where(mask)[0]
    if idx.size:
        yi = sy[idx]; xi = sx[idx]
        M[yi, xi] = rng.uniform(0.78, 0.99, idx.size).astype(np.float32)
        R[yi, xi] = rng.uniform(0.02, 0.18, idx.size).astype(np.float32)
        CC[yi, xi] = rng.uniform(0.48, 0.99, idx.size).astype(np.float32)

    # 9) CENTER PIP-MARKS - the milled centerpoint of each diamond
    # Find every diamond cell center: where both ridge_a and ridge_b are near peak
    pip_mask = (crest > 0.85).astype(np.float32)
    py_idx, px_idx = np.where(pip_mask > 0.5)
    if py_idx.size > 0:
        # subsample so we don't write everywhere
        step = max(1, py_idx.size // max(int(mn * mn / 90.0), 500))
        py_idx = py_idx[::step]; px_idx = px_idx[::step]
        M[py_idx, px_idx] = np.minimum(M[py_idx, px_idx], rng.uniform(0.20, 0.45, py_idx.size).astype(np.float32))

    # 10) R6-TICK56 NEW HERO #1 â€” MACHINIST CORNER REFERENCE CROSS-HAIRS.
    # Small 8-14 px etched plus-signs scattered like inspection marks from
    # a coordinate measuring machine. Crisp, fine, distinct from the knurl.
    if _CV2_OK:
        n_cross = int(np.clip(45 * (mn / 256.0) ** 2, 12, 90))
        for _ in range(n_cross):
            cx = int(rng.integers(8, w - 8)); cy = int(rng.integers(8, h - 8))
            arm = int(rng.uniform(4.0, 7.0) * scale)
            tM = float(rng.uniform(0.18, 0.34))
            tR = float(rng.uniform(0.62, 0.88))
            tCC = float(rng.uniform(0.20, 0.46))
            _cv2.line(M,  (cx - arm, cy), (cx + arm, cy), tM,  1, lineType=_cv2.LINE_AA)
            _cv2.line(R,  (cx - arm, cy), (cx + arm, cy), tR,  1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (cx - arm, cy), (cx + arm, cy), tCC, 1, lineType=_cv2.LINE_AA)
            _cv2.line(M,  (cx, cy - arm), (cx, cy + arm), tM,  1, lineType=_cv2.LINE_AA)
            _cv2.line(R,  (cx, cy - arm), (cx, cy + arm), tR,  1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (cx, cy - arm), (cx, cy + arm), tCC, 1, lineType=_cv2.LINE_AA)

    # 11) R6-TICK56 NEW HERO #2 â€” COOLANT-DARKENING ZONES.
    # Soft 18-32 px irregular blobs where machining coolant pooled and dulled
    # the crests â€” adds chroma diversity, breaks uniformity at MID frequency.
    if _CV2_OK:
        n_cool = int(np.clip(28 * (mn / 256.0) ** 2, 8, 60))
        for _ in range(n_cool):
            cx = int(rng.integers(6, w - 6)); cy = int(rng.integers(6, h - 6))
            rx = int(rng.uniform(9.0, 16.0) * scale)
            ry = int(rng.uniform(7.0, 14.0) * scale)
            rot = float(rng.uniform(0, 180))
            # darken M, raise R, lower CC â€” wet/dull look
            mask_layer = np.zeros((h, w), dtype=np.float32)
            _cv2.ellipse(mask_layer, (cx, cy), (rx, ry), rot, 0, 360, 1.0, -1, lineType=_cv2.LINE_AA)
            mask_layer *= float(rng.uniform(0.18, 0.32))
            M = np.clip(M - mask_layer * 0.5, 0, 1)
            R = np.clip(R + mask_layer * 0.45, 0, 1)
            CC = np.clip(CC - mask_layer * 0.35, 0, 1)

    out = np.stack([M, R, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
spec_knurled_diamond._spb_concept_complete = True


def spec_knurled_straight(shape, seed, sm, frequency=36.0, sharpness=4.0, **kwargs):
    """spec_knurled_straight.

    identity: R6-CREATIVE tick 47 push â€” finer axial straight knurl (3-6 px
    parallel ridge bands, no crossing) PLUS a new HERO MOTIF: TOOL-PUSH-OUT
    CHEVRONS â€” sparse 12-18 px V-shaped chevron marks where the knurling
    roller was lifted/restarted, planted in 24-40 random spots and oriented
    along the axis. These break the pure-parallel monotony with periodic
    machine-tool signatures while keeping the strictly-parallel ridge
    identity. Per-band INDEPENDENT continuous M/R/CC. 2-3 px tool-tooth
    micro-hatch, 5x axial burnish hairlines on crests, dark valley scratches,
    oil-pit micro-discs (1-3 px), and a dense sparkle pinpoint carpet on
    crests. Full coverage, fine features only.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 2711)
    mn = float(min(h, w))
    scale = max(mn / 256.0, 0.6)
    yy_grid = np.arange(h, dtype=np.float32).reshape(h, 1)
    xx_grid = np.arange(w, dtype=np.float32).reshape(1, w)

    # 1) Ridge band coordinate (along Y) â€” 3-6 px ridge cells
    ridge_period = float(np.clip(4.5 * (mn / 256.0), 3.2, 6.5))
    fy_ridge = (yy_grid % ridge_period) / ridge_period
    ridge_1d = np.cos((fy_ridge - 0.5) * 2.0 * np.pi) * 0.5 + 0.5  # (h, 1)
    crest_1d = ridge_1d ** float(sharpness)
    valley_1d = (1.0 - ridge_1d) ** float(sharpness)
    # Broadcast to full (h, w)
    ones_x = np.ones((1, w), dtype=np.float32)
    crest = (crest_1d * ones_x).astype(np.float32)
    valley = (valley_1d * ones_x).astype(np.float32)

    # 2) Per-band hash â€” INDEPENDENT M/R/CC for each band
    band_id_1d = np.floor(yy_grid / ridge_period).astype(np.int32)
    def _hash01(a, off):
        h_arr = (a.astype(np.int64) * 73856093) ^ (int(seed) + off)
        return ((h_arr & 0xFFFF).astype(np.float32) / 65535.0)
    band_M  = ((0.55 + _hash01(band_id_1d, 11) * 0.42) * ones_x).astype(np.float32)
    band_R  = ((0.10 + _hash01(band_id_1d, 23) * 0.50) * ones_x).astype(np.float32)
    band_CC = ((0.05 + _hash01(band_id_1d, 37) * 0.55) * ones_x).astype(np.float32)
    val_M  = ((0.20 + _hash01(band_id_1d, 41) * 0.28) * ones_x).astype(np.float32)
    val_R  = ((0.55 + _hash01(band_id_1d, 43) * 0.35) * ones_x).astype(np.float32)
    val_CC = ((0.55 + _hash01(band_id_1d, 47) * 0.32) * ones_x).astype(np.float32)

    # Full-canvas channels
    M  = band_M  * crest + val_M  * valley + 0.40 * (1.0 - crest - valley)
    R  = band_R  * crest + val_R  * valley + 0.40 * (1.0 - crest - valley)
    CC = band_CC * crest + val_CC * valley + 0.40 * (1.0 - crest - valley)

    # 3) 3 px cut-tooth micro hatch
    hatch_a = np.sin((xx_grid + yy_grid) / 3.0 * 2.0 * np.pi)
    hatch_b = np.sin((xx_grid - yy_grid) / 3.0 * 2.0 * np.pi)
    micro = (np.maximum(hatch_a, hatch_b) > 0.0).astype(np.float32)
    M = np.clip(M + (micro - 0.5) * 0.10, 0, 1)
    R = np.clip(R - (micro - 0.5) * 0.08, 0, 1)

    M = M.astype(np.float32); R = R.astype(np.float32); CC = CC.astype(np.float32)

    if _CV2_OK:
        # 4) Axial burnish hairlines on crests
        n_burn = max(2200, int(h * w / 280))
        for _ in range(n_burn):
            cx = rng.uniform(2, w - 2); cy = rng.uniform(2, h - 2)
            length = float(rng.uniform(8.0, 22.0) * scale)
            ang = float(rng.uniform(-0.10, 0.10))  # axial
            x0s = int(cx - np.cos(ang) * length * 0.5)
            y0s = int(cy - np.sin(ang) * length * 0.5)
            x1s = int(cx + np.cos(ang) * length * 0.5)
            y1s = int(cy + np.sin(ang) * length * 0.5)
            _cv2.line(M, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.65, 0.97)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(R, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.05, 0.22)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.04, 0.25)), 1, lineType=_cv2.LINE_AA)
        # 5) Dark valley hairlines
        n_val_l = max(1300, int(h * w / 500))
        for _ in range(n_val_l):
            cx = rng.uniform(2, w - 2); cy = rng.uniform(2, h - 2)
            length = float(rng.uniform(8.0, 18.0) * scale)
            ang = float(rng.uniform(-0.10, 0.10))
            x0s = int(cx - np.cos(ang) * length * 0.5)
            y0s = int(cy - np.sin(ang) * length * 0.5)
            x1s = int(cx + np.cos(ang) * length * 0.5)
            y1s = int(cy + np.sin(ang) * length * 0.5)
            _cv2.line(M, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.10, 0.30)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(R, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.60, 0.92)), 1, lineType=_cv2.LINE_AA)
        # 6) Oil pit discs in valleys
        n_pit = max(900, int(h * w / 700))
        for _ in range(n_pit):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            r = max(1, int(rng.uniform(2.0, 5.0) * scale))
            _cv2.circle(M, (cx, cy), r, float(rng.uniform(0.08, 0.28)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r, float(rng.uniform(0.60, 0.92)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r, float(rng.uniform(0.55, 0.90)), -1, lineType=_cv2.LINE_AA)
        # 7) Bright pinpoint sparkle carpet on crests â€” 5x prior
        n_sp = int(np.clip(mn * mn / 70.0, 2500, 12000))
        sy = rng.integers(0, h, n_sp); sx = rng.integers(0, w, n_sp)
        cmask = crest[sy, sx] > 0.40
        idx = np.where(cmask)[0]
        if idx.size:
            yi = sy[idx]; xi = sx[idx]
            M[yi, xi] = rng.uniform(0.70, 0.99, idx.size).astype(np.float32)
            R[yi, xi] = rng.uniform(0.02, 0.18, idx.size).astype(np.float32)
            CC[yi, xi] = rng.uniform(0.50, 0.99, idx.size).astype(np.float32)

        # 8) HERO TOOL-PUSH-OUT CHEVRONS â€” 24-40 random spots where the
        # knurling roller lifted, leaving a 12-18 px V-shaped mark across
        # 3-4 ridge bands. Per-chevron INDEPENDENT M/R/CC continuous.
        n_chev = int(np.clip(32 * (mn / 256.0), 22, 50))
        for _ in range(n_chev):
            cx = float(rng.uniform(0.08, 0.92) * w)
            cy = float(rng.uniform(0.08, 0.92) * h)
            arm = float(rng.uniform(6.0, 9.0) * scale)
            # half-angle from axis (axis along X) â€” chevron opens along axis
            ha = float(rng.uniform(0.55, 0.85))  # ~32-49 deg
            x_apex = int(np.clip(cx, 0, w - 1)); y_apex = int(np.clip(cy, 0, h - 1))
            # two arms forming "V"
            x_a1 = int(np.clip(cx + np.cos(ha) * arm, 0, w - 1))
            y_a1 = int(np.clip(cy + np.sin(ha) * arm, 0, h - 1))
            x_a2 = int(np.clip(cx + np.cos(-ha) * arm, 0, w - 1))
            y_a2 = int(np.clip(cy + np.sin(-ha) * arm, 0, h - 1))
            chev_mv = float(rng.uniform(0.55, 0.95))
            chev_rv = float(rng.uniform(0.08, 0.42))
            chev_ccv = float(rng.uniform(0.10, 0.55))
            for (xa, ya) in ((x_a1, y_a1), (x_a2, y_a2)):
                _cv2.line(M,  (x_apex, y_apex), (xa, ya),
                          float(np.clip(chev_mv + rng.uniform(-0.12, 0.12), 0.20, 0.98)), 1, lineType=_cv2.LINE_AA)
                _cv2.line(R,  (x_apex, y_apex), (xa, ya),
                          float(np.clip(chev_rv + rng.uniform(-0.12, 0.12), 0.04, 0.88)), 1, lineType=_cv2.LINE_AA)
                _cv2.line(CC, (x_apex, y_apex), (xa, ya),
                          float(np.clip(chev_ccv + rng.uniform(-0.12, 0.12), 0.04, 0.85)), 1, lineType=_cv2.LINE_AA)

        # 9) R6-CREATIVE NEW: DRAGON-CURVE TOOL-SKIP GLYPHS ï¿½ 5-16 tiny
        # fractal scratches where the cutter chattered, plotted as a
        # 60-step dragon-curve polyline (recursive 90deg-turn sequence).
        # Each glyph spans ~10-22 px, gives an otherworldly micro-mark
        # inside an otherwise strictly-parallel knurl. Per-glyph
        # INDEPENDENT continuous M/R/CC uniforms.
        n_glyph = int(np.clip(10 * (mn / 256.0), 5, 16))
        # Pre-compute dragon turn sequence (boolean: True=left, False=right)
        turns = []
        for i in range(1, 80):
            turns.append((((i & -i) << 1) & i) == 0)
        for _ in range(n_glyph):
            seg = float(rng.uniform(0.6, 1.4) * scale)
            ang = float(rng.uniform(0, 2 * np.pi))
            cx = float(rng.uniform(0.06, 0.94) * w)
            cy = float(rng.uniform(0.06, 0.94) * h)
            gM  = float(rng.uniform(0.55, 0.95))
            gR  = float(rng.uniform(0.06, 0.38))
            gCC = float(rng.uniform(0.08, 0.55))
            px, py = cx, cy
            ax_dir = np.cos(ang); ay_dir = np.sin(ang)
            walk = min(len(turns), 60)
            for ti in range(walk):
                nx = px + ax_dir * seg
                ny = py + ay_dir * seg
                if 0 <= int(nx) < w and 0 <= int(ny) < h and 0 <= int(px) < w and 0 <= int(py) < h:
                    _cv2.line(M,  (int(px), int(py)), (int(nx), int(ny)),
                              float(np.clip(gM  + rng.uniform(-0.05, 0.05), 0, 1)), 1, lineType=_cv2.LINE_AA)
                    _cv2.line(R,  (int(px), int(py)), (int(nx), int(ny)),
                              float(np.clip(gR  + rng.uniform(-0.04, 0.04), 0, 1)), 1, lineType=_cv2.LINE_AA)
                    _cv2.line(CC, (int(px), int(py)), (int(nx), int(ny)),
                              float(np.clip(gCC + rng.uniform(-0.05, 0.05), 0, 1)), 1, lineType=_cv2.LINE_AA)
                px, py = nx, ny
                # rotate by +/-90 per the dragon turn
                if turns[ti]:
                    ax_dir, ay_dir = -ay_dir, ax_dir
                else:
                    ax_dir, ay_dir = ay_dir, -ax_dir

    out = np.stack([M, R, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
spec_knurled_straight._spb_concept_complete = True


def spec_architectural_grid(shape, seed, sm, cell_size=40.0, frame_frac=0.10, **kwargs):
    """spec_architectural_grid.

    identity: R6 OWNER-REBUILD (REBUILD 5) â€” owner notes: "not sure what
    the random lines are. ALSO TOO NOISY AS IS". REMOVED the neon piping
    differentiator (the random diagonal tubes were the complaint).
    REDUCED fleck/etch density 3x. CLEAN architectural mullion grid:
      (i) 10-14 px aluminum mullion grid (sharp frame).
      (ii) HERO: ILLUMINATED WINDOW CELLS (~10% warm bloom).
      (iii) HERO: MIRROR SKY-REFLECTION cells (~6% vertical gradient).
      (iv) Subtle building-corner shear plane break (low amplitude).
      (v) Sparse 2-4 px reflection sparks, 1-2 px frame pores ONLY.
    Per-feature INDEPENDENT M/R/CC TIGHT Â±0.05 around glass/frame bases.
    No more neon. No more etch hairlines.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 51490)
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)
    yy = np.arange(h, dtype=np.float32); xx = np.arange(w, dtype=np.float32)
    Y, X = np.meshgrid(yy, xx, indexing='ij')
    cell_h = max(8.0, float(cell_size) * 0.30)
    cell_w = cell_h * 1.35
    fx_n = (X % cell_w) / cell_w; fy_n = (Y % cell_h) / cell_h
    dist_x = np.minimum(fx_n, 1.0 - fx_n); dist_y = np.minimum(fy_n, 1.0 - fy_n)
    frame_dist = np.minimum(dist_x, dist_y)
    on_frame = np.clip(1.0 - frame_dist / float(frame_frac), 0.0, 1.0) ** 0.5
    col_idx = np.floor(X / cell_w); row_idx = np.floor(Y / cell_h)
    panel_var = (np.sin(col_idx * 3.7 + row_idx * 5.3 + seed * 0.011) * 0.5 + 0.5).astype(np.float32)
    # Per-cell hash for HERO selection â€” independent of panel_var
    cell_hash = (np.sin(col_idx * 12.9898 + row_idx * 78.233 + seed * 0.0173) * 43758.5453)
    cell_hash = (cell_hash - np.floor(cell_hash)).astype(np.float32)
    daylight = ((1.0 - fy_n) ** 1.6).astype(np.float32)
    # 1) BASE â€” frame vs glass
    M = (on_frame * 0.82 + (1.0 - on_frame) * (0.04 + panel_var * 0.08)).astype(np.float32)
    R = (on_frame * (0.18 + panel_var * 0.10) + (1.0 - on_frame) * (0.32 + daylight * 0.18 + panel_var * 0.10)).astype(np.float32)
    CC = (on_frame * 0.08 + (1.0 - on_frame) * (0.18 + panel_var * 0.14 + (1.0 - daylight) * 0.18)).astype(np.float32)
    glass_mask_f = (on_frame < 0.35).astype(np.float32)
    # HERO 1: ILLUMINATED WINDOWS â€” ~12% of cells, warm bright bloom on glass
    lit_mask = ((cell_hash < 0.12) & (glass_mask_f > 0.5)).astype(np.float32)
    # cell-center distance for vignetted bloom
    cell_cx = (fx_n - 0.5); cell_cy = (fy_n - 0.5)
    cell_rad = np.sqrt(cell_cx * cell_cx + cell_cy * cell_cy)
    bloom = (1.0 - np.clip(cell_rad * 2.0, 0.0, 1.0)).astype(np.float32)
    M = np.where(lit_mask > 0.5, M + bloom * 0.55, M).astype(np.float32)
    R = np.where(lit_mask > 0.5, R - bloom * 0.25, R).astype(np.float32)
    CC = np.where(lit_mask > 0.5, CC - bloom * 0.18, CC).astype(np.float32)
    # HERO 2: MIRROR SKY-REFLECTION cells â€” ~6%, vertical gradient
    mirror_mask = ((cell_hash > 0.85) & (cell_hash < 0.91) & (glass_mask_f > 0.5)).astype(np.float32)
    sky_grad = (1.0 - (Y / max(h, 1))).astype(np.float32)  # bright at top, dim at bottom
    M = np.where(mirror_mask > 0.5, 0.30 + sky_grad * 0.65, M).astype(np.float32)
    R = np.where(mirror_mask > 0.5, 0.08 + (1.0 - sky_grad) * 0.20, R).astype(np.float32)
    CC = np.where(mirror_mask > 0.5, 0.05 + (1.0 - sky_grad) * 0.15, CC).astype(np.float32)
    # HERO 3: BUILDING-CORNER SHEAR â€” diagonal plane break, subtle
    shear_ang = float(rng.uniform(0.20, 0.45) * np.pi)
    shear_off = float(rng.uniform(-0.25, 0.25))
    shear_proj = (X / max(w, 1)) * np.cos(shear_ang) + (Y / max(h, 1)) * np.sin(shear_ang) + shear_off
    plane_a = (shear_proj < 0.5).astype(np.float32)
    plane_b = 1.0 - plane_a
    plane_shift_M = float(rng.uniform(-0.06, 0.06))
    plane_shift_R = float(rng.uniform(-0.04, 0.04))
    M = (M + plane_a * plane_shift_M - plane_b * plane_shift_M).astype(np.float32)
    R = (R + plane_a * plane_shift_R - plane_b * plane_shift_R).astype(np.float32)
    # CLEAN-UP: removed BRU injection (was random-looking salt/pepper). Removed
    # noisy fleck/etch passes. Removed neon tubes entirely.
    if _CV2_OK:
        glass_mask = (on_frame < 0.35).astype(np.uint8)
        # SPARSE reflection sparks (1/3 prior density), tight chroma
        n_refl = int(np.clip(700 * (mn / 2048.0) ** 2, 220, 2000))
        for _ in range(n_refl):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            if glass_mask[cy, cx] == 0:
                continue
            r = max(1, int(rng.uniform(2.0, 4.0) * scale * 0.5))
            _cv2.circle(M, (cx, cy), r, float(np.clip(0.86 + rng.uniform(-0.05, 0.05), 0, 1)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r, float(np.clip(0.14 + rng.uniform(-0.04, 0.04), 0, 1)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r, float(np.clip(0.10 + rng.uniform(-0.04, 0.04), 0, 1)), -1, lineType=_cv2.LINE_AA)
        # SPARSE frame pores (1-2 px dark dots only on frame mask)
        frame_mask = (on_frame > 0.55).astype(np.uint8)
        n_sh = int(np.clip(500 * (mn / 2048.0) ** 2, 180, 1500))
        for _ in range(n_sh):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            if frame_mask[cy, cx] == 0:
                continue
            r = max(1, int(rng.uniform(1.0, 2.0) * scale))
            _cv2.circle(M, (cx, cy), r, float(np.clip(0.22 + rng.uniform(-0.06, 0.06), 0, 1)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r, float(np.clip(0.78 + rng.uniform(-0.05, 0.05), 0, 1)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r, float(np.clip(0.60 + rng.uniform(-0.06, 0.06), 0, 1)), -1, lineType=_cv2.LINE_AA)
    # Light pinpoint flecks (1/4 prior density), tight neighborhood â€” adds
    # surface micro-texture without the noisy salt/pepper look
    n_fl = max(600, int(h * w / 5500))
    fxs = rng.integers(0, w, n_fl); fys = rng.integers(0, h, n_fl)
    # additive jitter only â€” preserve underlying glass/frame chroma
    M[fys, fxs] = np.clip(M[fys, fxs] + rng.uniform(-0.05, 0.05, n_fl).astype(np.float32), 0, 1)
    R[fys, fxs] = np.clip(R[fys, fxs] + rng.uniform(-0.04, 0.04, n_fl).astype(np.float32), 0, 1)
    CC[fys, fxs] = np.clip(CC[fys, fxs] + rng.uniform(-0.04, 0.04, n_fl).astype(np.float32), 0, 1)

    out = np.stack([np.clip(M, 0, 1), np.clip(R, 0, 1), np.clip(CC, 0, 1)], axis=-1).astype(np.float32)
    return _validate_spec_output(_sm_scale(np.clip(out, 0.0, 1.0), sm).astype(np.float32), "spec_architectural_grid")
spec_architectural_grid._spb_concept_complete = True


def spec_hexagonal_tiles(shape, seed, sm, tile_size=22.0, grout_frac=0.12, **kwargs):
    """spec_hexagonal_tiles.

    identity: Round-6 CREATIVE rebuild â€” close-packed ceramic honeycomb
    14-22 px hexes with INDEPENDENT continuous-uniform M/R/CC per tile
    (wide [0.05, 0.99]), but now with a new HERO motif: rare LUMINESCENT
    "glow" tiles (~1 in 70) â€” single hex stamped with a mirror-bright
    center plus halo bloom that bleeds into adjacent grout. New: per-tile
    radial gradient (face center brighter than tile edge, sells curvature)
    PLUS sparse "glaze pour" diagonal rivers crossing 4-8 hex spans where
    a glossier overrun pooled into seams. Old details kept: FBM tint,
    bright flecks, grout pits, hairline crackle, sparkle carpet. Full
    coverage, fine pitch.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 2708)
    scale = max(min(h, w) / 256.0, 0.6)
    yy = np.arange(h, dtype=np.float32)
    xx = np.arange(w, dtype=np.float32)
    Y, X = np.meshgrid(yy, xx, indexing='ij')
    tsize = float(np.clip(tile_size * 0.7, 12.0, 22.0))
    spacing_x = tsize
    spacing_y = tsize * np.sqrt(3.0) / 2.0
    fy = (Y / spacing_y) - np.floor(Y / spacing_y) - 0.5
    offset = (np.floor(Y / spacing_y).astype(np.int32) % 2) * 0.5
    fx_off = ((X / spacing_x - offset) % 1.0) - 0.5
    hex_dist = np.maximum(np.abs(fx_off), (np.abs(fx_off) + np.abs(fy) * 1.1547) * 0.5773)
    hex_norm = hex_dist / 0.5
    on_grout = np.clip((hex_norm - (1.0 - grout_frac)) / grout_frac, 0.0, 1.0)

    # Per-tile hashed IDs and INDEPENDENT continuous-uniform M/R/CC per tile
    tile_id_x = np.floor(X / spacing_x - offset + 0.5).astype(np.int32)
    tile_id_y = np.floor(Y / spacing_y + 0.5).astype(np.int32)
    def _hash01(a, b, off):
        h_arr = (a.astype(np.int64) * 73856093) ^ (b.astype(np.int64) * 19349663) ^ (int(seed) + off)
        return ((h_arr & 0xFFFF).astype(np.float32) / 65535.0)
    bun_M = (0.10 + _hash01(tile_id_x, tile_id_y, 11) * 0.85).astype(np.float32)
    bun_R = (0.12 + _hash01(tile_id_x, tile_id_y, 23) * 0.82).astype(np.float32)
    bun_CC = (0.08 + _hash01(tile_id_x, tile_id_y, 37) * 0.85).astype(np.float32)

    # NEW: per-tile FACE RADIAL gradient â€” center of each hex slightly
    # brighter than its edge, so each tile reads as a domed lozenge not flat.
    face_grad = (1.0 - np.clip(hex_norm, 0.0, 1.0)).astype(np.float32)

    # FBM tint per channel for substrate variation
    tint = _normalize(multi_scale_noise(shape, [6.0, 18.0, 40.0], [0.45, 0.32, 0.23], int(seed) + 51))
    M = np.clip(bun_M + (tint - 0.5) * 0.12 + face_grad * 0.10, 0, 1).astype(np.float32)
    R = np.clip(bun_R + (tint - 0.5) * 0.10 - face_grad * 0.06, 0, 1).astype(np.float32)
    CC = np.clip(bun_CC + (tint - 0.5) * 0.12 + face_grad * 0.08, 0, 1).astype(np.float32)

    # Grout seams â€” dark dielectric matte
    g_mask = on_grout
    M = M * (1.0 - g_mask * 0.85) + 0.15 * (g_mask * 0.85)
    R = R * (1.0 - g_mask) + np.clip(0.62 + (tint - 0.5) * 0.18, 0, 1) * g_mask
    CC = CC * (1.0 - g_mask) + 0.78 * g_mask

    # HERO MOTIF â€” rare LUMINESCENT glow tiles. Pick ~1 in 70 tile cells via
    # the hash-id field; brighten the FACE only (not grout), stamp a bright
    # 2-3 px hot dot at the tile centroid for extra punch.
    glow_id = _hash01(tile_id_x, tile_id_y, 91)
    glow_mask = (glow_id > 0.985).astype(np.float32) * (1.0 - on_grout)
    M = np.clip(M + glow_mask * 0.55, 0, 1)
    R = np.clip(R - glow_mask * 0.40, 0, 1)
    CC = np.clip(CC + glow_mask * 0.45, 0, 1)

    if _CV2_OK:
        # Pass A â€” fine glaze flecks on tile faces (5x prior)
        n_fl = max(8000, int(h * w / 35))
        fyi = rng.integers(0, h, n_fl); fxi = rng.integers(0, w, n_fl)
        mask = on_grout[fyi, fxi] < 0.40
        idx = np.where(mask)[0]
        if idx.size:
            yi = fyi[idx]; xi = fxi[idx]
            M[yi, xi] = rng.uniform(0.55, 0.99, idx.size).astype(np.float32)
            R[yi, xi] = rng.uniform(0.05, 0.30, idx.size).astype(np.float32)
            CC[yi, xi] = rng.uniform(0.55, 0.99, idx.size).astype(np.float32)
        # Pass B â€” dark grit pits in grout
        n_pit = max(3500, int(h * w / 90))
        pyi = rng.integers(0, h, n_pit); pxi = rng.integers(0, w, n_pit)
        gmask = on_grout[pyi, pxi] > 0.5
        idx = np.where(gmask)[0]
        if idx.size:
            yi = pyi[idx]; xi = pxi[idx]
            M[yi, xi] = rng.uniform(0.05, 0.22, idx.size).astype(np.float32)
            R[yi, xi] = rng.uniform(0.62, 0.95, idx.size).astype(np.float32)
            CC[yi, xi] = rng.uniform(0.15, 0.42, idx.size).astype(np.float32)
        # Pass C â€” pinpoint sparkle along seams (each disc independent)
        n_sp = int(np.clip(2400 * scale * scale, 1200, 6000))
        for _ in range(n_sp):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            r = max(1, int(rng.uniform(1.0, 2.4)))
            _cv2.circle(M, (cx, cy), r, float(rng.uniform(0.50, 0.99)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r, float(rng.uniform(0.05, 0.35)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r, float(rng.uniform(0.40, 0.95)), -1, lineType=_cv2.LINE_AA)
        # Pass D â€” hairline crackle across tile faces (independent uniforms)
        n_cr = int(np.clip(1100 * scale * scale, 500, 3000))
        for _ in range(n_cr):
            cx = rng.uniform(0, w); cy = rng.uniform(0, h)
            length = float(rng.uniform(4.0, 12.0) * scale)
            ang = float(rng.uniform(0, 2 * np.pi))
            x0s = int(cx - np.cos(ang) * length * 0.5)
            y0s = int(cy - np.sin(ang) * length * 0.5)
            x1s = int(cx + np.cos(ang) * length * 0.5)
            y1s = int(cy + np.sin(ang) * length * 0.5)
            _cv2.line(M, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.20, 0.50)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(R, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.45, 0.85)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.20, 0.55)), 1, lineType=_cv2.LINE_AA)
        # Pass E â€” GLAZE POUR rivers: 3-6 short diagonal high-gloss streaks
        # crossing 4-8 hex spans, simulating overrun glaze that pooled in
        # seams. Per-river INDEPENDENT chroma.
        n_riv = int(rng.integers(3, 7))
        for _ in range(n_riv):
            cx = float(rng.uniform(0.1, 0.9) * w); cy = float(rng.uniform(0.1, 0.9) * h)
            ang = float(rng.uniform(0, 2 * np.pi))
            length = float(rng.uniform(40.0, 110.0) * scale)
            steps = max(8, int(length / 2.0))
            rM_ = float(rng.uniform(0.55, 0.95))
            rR_ = float(rng.uniform(0.06, 0.25))
            rCC_ = float(rng.uniform(0.55, 0.95))
            for k in range(steps):
                t = k / max(1, steps - 1)
                px_ = int(cx + np.cos(ang) * (t - 0.5) * length)
                py_ = int(cy + np.sin(ang) * (t - 0.5) * length)
                if 0 <= px_ < w and 0 <= py_ < h:
                    _cv2.circle(M, (px_, py_), 1, rM_, -1, lineType=_cv2.LINE_AA)
                    _cv2.circle(R, (px_, py_), 1, rR_, -1, lineType=_cv2.LINE_AA)
                    _cv2.circle(CC, (px_, py_), 1, rCC_, -1, lineType=_cv2.LINE_AA)

    out = np.stack([M, R, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
spec_hexagonal_tiles._spb_concept_complete = True


def spec_brick_mortar(shape, seed, sm, brick_h=16.0, brick_w=36.0, mortar_frac=0.10, **kwargs):
    """spec_brick_mortar.

    identity: A close-up brickwork weave â€” bricks shrunk 3-4x to
    fine-feature scale (8-12 px tall, 18-26 px wide) in running bond.
    Each brick gets INDEPENDENT continuous M/R/CC. Stacked feature
    tiers: brick-face chip ticks (4-9 px), mortar pebble grit (1-3 px),
    bright lime seam flecks, dark clay pits, plus an extra micro-pore
    pinprick layer for chroma diversity.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + (hash("spec_brick_mortar") % 10000))
    yy = np.arange(h, dtype=np.float32)[:, None]
    xx = np.arange(w, dtype=np.float32)[None, :]
    scale = max(min(h, w) / 2048.0, 0.25)
    # Shrunk 3-4x â€” pre-rebuild brick was ~28-36px, now ~8-12 px tall, 18-26 px wide
    bh = max(6.0, (brick_h * 0.30) * (1.0 + 0.3 * scale))
    bw = max(14.0, (brick_w * 0.30) * (1.0 + 0.3 * scale))
    course = np.floor(yy / bh).astype(np.int32)
    fy = (yy % bh) / bh
    x_offset = (course % 2).astype(np.float32) * (bw * 0.5)
    fx = ((xx + x_offset) % bw) / bw
    # Joint mask (mortar) â€” soft edge falloff
    mh_d = np.minimum(fy, 1.0 - fy) / (mortar_frac * 0.5)
    mv_d = np.minimum(fx, 1.0 - fx) / (mortar_frac * 0.5)
    on_mortar = np.clip(1.0 - np.minimum(mh_d, mv_d), 0.0, 1.0)
    # Per-brick continuous M/R/CC (INDEPENDENT hashes)
    brick_id = np.floor((xx + x_offset) / bw).astype(np.int32)
    def _hash01(a, b, off):
        ha = (a.astype(np.int64) * 73856093) ^ (b.astype(np.int64) * 19349663) ^ (int(seed) + off)
        return ((ha & 0xFFFF).astype(np.float32) / 65535.0)
    h_M = _hash01(brick_id, course, 1)
    h_R = _hash01(brick_id, course, 2)
    h_CC = _hash01(brick_id, course, 3)
    clay_fbm = _normalize(multi_scale_noise(shape, [2.0, 6.0, 14.0],
                                            [0.40, 0.34, 0.26], int(seed) + 4101))
    # Wider M/R/CC range per brick for chroma diversity
    M_brick = 0.05 + h_M * 0.45 + (clay_fbm - 0.5) * 0.14
    R_brick = 0.30 + h_R * 0.55 + (clay_fbm - 0.5) * 0.12
    CC_brick = 0.35 + h_CC * 0.55
    h_Mm = _hash01(brick_id, course + 7, 11)
    h_Rm = _hash01(brick_id, course + 7, 12)
    h_CCm = _hash01(brick_id, course + 7, 13)
    M_mortar = 0.08 + h_Mm * 0.50
    R_mortar = 0.50 + h_Rm * 0.45
    CC_mortar = 0.62 + h_CCm * 0.35
    M = M_brick * (1.0 - on_mortar) + M_mortar * on_mortar
    R = R_brick * (1.0 - on_mortar) + R_mortar * on_mortar
    CC = CC_brick * (1.0 - on_mortar) + CC_mortar * on_mortar
    M = M.astype(np.float32); R = R.astype(np.float32); CC = CC.astype(np.float32)
    if _CV2_OK:
        # Chip-marks shrunk to 4-9 px (was 6-16 px), density up to compensate
        n_chip = max(3200, int(h * w / 450))
        for _ in range(n_chip):
            cxc = rng.uniform(2, w - 2); cyc = rng.uniform(2, h - 2)
            length = float(rng.uniform(3.0, 8.0) * scale)
            ang = float(rng.uniform(0, 2 * np.pi))
            x0s = int(cxc - np.cos(ang) * length * 0.5); y0s = int(cyc - np.sin(ang) * length * 0.5)
            x1s = int(cxc + np.cos(ang) * length * 0.5); y1s = int(cyc + np.sin(ang) * length * 0.5)
            _cv2.line(M, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.04, 0.40)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(R, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.40, 0.95)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.30, 0.95)), 1, lineType=_cv2.LINE_AA)
        # Mortar pebble grit â€” denser
        n_grit = max(4800, int(h * w / 300))
        for _ in range(n_grit):
            cxc = int(rng.integers(0, w)); cyc = int(rng.integers(0, h))
            if on_mortar[cyc, cxc] < 0.4:
                continue
            r = max(1, int(rng.uniform(1.0, 2.5) * scale))
            _cv2.circle(M, (cxc, cyc), r, float(rng.uniform(0.08, 0.62)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cxc, cyc), r, float(rng.uniform(0.50, 0.97)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cxc, cyc), r, float(rng.uniform(0.40, 0.90)), -1, lineType=_cv2.LINE_AA)
    # Bright lime flecks
    n_fl = max(3600, int(h * w / 550))
    fyi = rng.integers(0, h, n_fl); fxi = rng.integers(0, w, n_fl)
    M[fyi, fxi] = np.maximum(M[fyi, fxi], rng.uniform(0.28, 0.85, n_fl).astype(np.float32))
    CC[fyi, fxi] = np.minimum(CC[fyi, fxi], rng.uniform(0.25, 0.70, n_fl).astype(np.float32))
    # Dark clay pits
    n_pit = max(2800, int(h * w / 900))
    pyi = rng.integers(0, h, n_pit); pxi = rng.integers(0, w, n_pit)
    R[pyi, pxi] = np.maximum(R[pyi, pxi], rng.uniform(0.60, 0.97, n_pit).astype(np.float32))
    M[pyi, pxi] = np.minimum(M[pyi, pxi], rng.uniform(0.04, 0.22, n_pit).astype(np.float32))
    # Micro-pore chroma carpet â€” new tier
    n_pore = max(4500, int(h * w / 400))
    qyi = rng.integers(0, h, n_pore); qxi = rng.integers(0, w, n_pore)
    CC[qyi, qxi] = np.clip(CC[qyi, qxi] + rng.uniform(-0.22, 0.22, n_pore).astype(np.float32), 0, 1)
    out = np.stack([M, R, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
spec_brick_mortar._spb_concept_complete = True


# spec_corrugated_panel moved to engine/spec_pattern_families/mechanical.py
# at tick 38 (SPB-106 r3 unique-motif redesign).


def spec_riveted_plate(shape, seed, sm, rivet_spacing=24.0, rivet_radius_frac=0.28, **kwargs):
    """spec_riveted_plate â€” R6 CREATIVE rebuild.

    identity: A real aircraft-skin / industrial plate at panel-zoom. HERO
    MOTIF: a 1-2 px overlap PANEL JOINT (large diagonal or curved seam
    cutting across the canvas) flanked on both sides by a DENSE
    DOUBLE-ROW of bigger structural rivets (16-22 px) â€” this reads at
    thumbnail as "real airframe construction". The rest of the plate
    fills with a tighter staggered RIVET FIELD (10-14 px) so the
    aluminum skin is fully cobbled with domed heads. Per-rivet
    INDEPENDENT continuous M/R/CC sampled from random hash so each rivet
    catches light differently â€” some chrome-fresh, some weathered.
    Underneath: brushed aluminum substrate w/ fine scratches, ID-stamps,
    burnish discs. Differentiator vs mesh_perforated: rivets are raised
    CONVEX bright domes, mesh has SUNKEN dark holes.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 62531)
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)

    # 1) BASE â€” brushed aluminum substrate, independent FBM per channel
    g1 = _normalize(multi_scale_noise(shape, [2.5, 6.0, 13.0, 24.0], [0.34, 0.30, 0.22, 0.14], int(seed) + 6253))
    g2 = _normalize(multi_scale_noise(shape, [3.0, 7.0, 14.0, 26.0], [0.34, 0.30, 0.22, 0.14], int(seed) + 6254))
    g3 = _normalize(multi_scale_noise(shape, [3.5, 7.5, 15.0, 28.0], [0.34, 0.30, 0.22, 0.14], int(seed) + 6255))
    M  = (0.72 + (g1 - 0.5) * 0.18).astype(np.float32)
    R  = (0.28 + (g2 - 0.5) * 0.20).astype(np.float32)
    CC = (0.22 + (g3 - 0.5) * 0.20).astype(np.float32)

    # 2) Aluminum brush direction â€” horizontal striations
    brush = _normalize(multi_scale_noise(shape, [1.5, 4.0], [0.6, 0.4], int(seed) + 6260))
    yy_arr = np.arange(h, dtype=np.float32)[:, None]
    h_brush = 0.5 + 0.5 * np.sin(yy_arr * 0.6 + brush[:, :1] * 6.28)
    h_brush = np.broadcast_to(h_brush, (h, w)).astype(np.float32)
    M = np.clip(M + (h_brush - 0.5) * 0.06, 0, 1)

    if _CV2_OK:
        # 3) HERO: PANEL JOINT (diagonal seam) with structural rivets either side
        # joint line endpoints
        joint_ang = float(rng.uniform(-0.5, 0.5))  # near-horizontal diagonal
        joint_cx = w * 0.5; joint_cy = h * 0.5
        # offset perpendicular
        dyj = np.sin(joint_ang); dxj = np.cos(joint_ang)
        # draw joint as 2px slight overlap
        seam_x0 = int(joint_cx - dxj * w * 1.0); seam_y0 = int(joint_cy - dyj * w * 1.0)
        seam_x1 = int(joint_cx + dxj * w * 1.0); seam_y1 = int(joint_cy + dyj * w * 1.0)
        _cv2.line(M, (seam_x0, seam_y0), (seam_x1, seam_y1), float(rng.uniform(0.25, 0.45)), 2, lineType=_cv2.LINE_AA)
        _cv2.line(R, (seam_x0, seam_y0), (seam_x1, seam_y1), float(rng.uniform(0.45, 0.75)), 2, lineType=_cv2.LINE_AA)
        _cv2.line(CC, (seam_x0, seam_y0), (seam_x1, seam_y1), float(rng.uniform(0.35, 0.65)), 2, lineType=_cv2.LINE_AA)

        # structural rivets along joint (both sides offset perp)
        n_struct = int(np.clip(28 * (mn / 1024.0), 14, 80))
        for side in (-1, 1):
            offperp_x = -dyj * 9.0 * side
            offperp_y = dxj * 9.0 * side
            for k in range(n_struct):
                t = (k + 0.5) / n_struct
                # parametrize along joint
                px = (1 - t) * seam_x0 + t * seam_x1 + offperp_x
                py = (1 - t) * seam_y0 + t * seam_y1 + offperp_y
                if not (0 <= px < w and 0 <= py < h): continue
                rr = int(rng.uniform(7.0, 11.0))  # 14-22 px diameter (structural)
                # base dome â€” independent M/R/CC
                bM = float(rng.uniform(0.70, 0.98))
                bR = float(rng.uniform(0.08, 0.30))
                bCC = float(rng.uniform(0.12, 0.38))
                _cv2.circle(M, (int(px), int(py)), rr, bM, -1, lineType=_cv2.LINE_AA)
                _cv2.circle(R, (int(px), int(py)), rr, bR, -1, lineType=_cv2.LINE_AA)
                _cv2.circle(CC, (int(px), int(py)), rr, bCC, -1, lineType=_cv2.LINE_AA)
                # dark rim ring
                _cv2.circle(M, (int(px), int(py)), rr, float(rng.uniform(0.20, 0.45)), 1, lineType=_cv2.LINE_AA)
                # bright dome highlight
                hx = int(px - rr * 0.35); hy = int(py - rr * 0.35)
                _cv2.circle(M, (hx, hy), max(1, int(rr * 0.30)), float(rng.uniform(0.92, 0.99)), -1, lineType=_cv2.LINE_AA)

        # 4) FIELD RIVETS â€” staggered tighter grid covering whole canvas (10-14 px)
        spacing = max(11.0, mn / 24.0)
        n_rows = int(h / spacing) + 2
        n_cols = int(w / spacing) + 2
        for ri in range(n_rows):
            stagger = (ri % 2) * spacing * 0.5
            for ci in range(n_cols):
                cx = ci * spacing + stagger
                cy = ri * spacing
                if not (0 <= cx < w and 0 <= cy < h): continue
                # skip if too near hero joint
                # compute distance to joint line
                if seam_x1 != seam_x0:
                    # line: (y1-y0)*x - (x1-x0)*y + (x1*y0 - y1*x0) = 0
                    A = (seam_y1 - seam_y0); B = -(seam_x1 - seam_x0); C = (seam_x1 * seam_y0 - seam_y1 * seam_x0)
                    denom = max(1e-6, (A * A + B * B) ** 0.5)
                    d_to_joint = abs(A * cx + B * cy + C) / denom
                    if d_to_joint < 16.0: continue
                # jitter
                jx = float(rng.uniform(-1.5, 1.5)); jy = float(rng.uniform(-1.5, 1.5))
                rr = int(rng.uniform(4.0, 7.0))  # 8-14 px diameter
                bM = float(rng.uniform(0.55, 0.97))
                bR = float(rng.uniform(0.08, 0.42))
                bCC = float(rng.uniform(0.10, 0.45))
                _cv2.circle(M, (int(cx + jx), int(cy + jy)), rr, bM, -1, lineType=_cv2.LINE_AA)
                _cv2.circle(R, (int(cx + jx), int(cy + jy)), rr, bR, -1, lineType=_cv2.LINE_AA)
                _cv2.circle(CC, (int(cx + jx), int(cy + jy)), rr, bCC, -1, lineType=_cv2.LINE_AA)
                # rim shadow
                _cv2.circle(M, (int(cx + jx), int(cy + jy)), rr, float(rng.uniform(0.22, 0.45)), 1, lineType=_cv2.LINE_AA)
                # micro highlight
                hx = int(cx + jx - rr * 0.30); hy = int(cy + jy - rr * 0.30)
                _cv2.circle(M, (hx, hy), max(1, int(rr * 0.25)), float(rng.uniform(0.88, 0.99)), -1, lineType=_cv2.LINE_AA)

        # 5) ID-STAMP RECTANGLES â€” small mfg marks
        n_id = int(np.clip(420 * (mn / 2048.0) ** 2, 140, 1100))
        for _ in range(n_id):
            cxp = int(rng.integers(4, max(5, w - 4))); cyp = int(rng.integers(4, max(5, h - 4)))
            cw_r = int(max(2, rng.uniform(4.0, 9.0)))
            ch_r = int(max(1, rng.uniform(2.0, 4.0)))
            x0r = max(0, cxp - cw_r // 2); x1r = min(w, cxp + cw_r // 2)
            y0r = max(0, cyp - ch_r // 2); y1r = min(h, cyp + ch_r // 2)
            mM = float(rng.uniform(0.40, 0.78))
            mR = float(rng.uniform(0.32, 0.62))
            mCC = float(rng.uniform(0.18, 0.45))
            _cv2.rectangle(M, (x0r, y0r), (x1r, y1r), mM, -1)
            _cv2.rectangle(R, (x0r, y0r), (x1r, y1r), mR, -1)
            _cv2.rectangle(CC, (x0r, y0r), (x1r, y1r), mCC, -1)

        # 6) HAIRLINE SCRATCHES (5-12 px)
        n_sc = int(np.clip(800 * (mn / 2048.0) ** 2, 280, 2200))
        for _ in range(n_sc):
            cxp = rng.uniform(4, w - 4); cyp = rng.uniform(4, h - 4)
            length = float(rng.uniform(5.0, 12.0))
            ang = float(rng.uniform(0, 2 * np.pi))
            x0s = int(cxp - np.cos(ang) * length * 0.5); y0s = int(cyp - np.sin(ang) * length * 0.5)
            x1s = int(cxp + np.cos(ang) * length * 0.5); y1s = int(cyp + np.sin(ang) * length * 0.5)
            _cv2.line(M, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.55, 0.92)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(R, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.10, 0.30)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.08, 0.28)), 1, lineType=_cv2.LINE_AA)

    # 7) BURNISH FLECKS â€” full canvas coverage carpet
    n_fl = int(np.clip(mn * mn / 90.0, 2400, 9000))
    fxa = rng.integers(0, w, n_fl); fya = rng.integers(0, h, n_fl)
    M[fya, fxa] = np.maximum(M[fya, fxa], rng.uniform(0.66, 0.97, n_fl).astype(np.float32))
    R[fya, fxa] = np.minimum(R[fya, fxa], rng.uniform(0.08, 0.32, n_fl).astype(np.float32))
    CC[fya, fxa] = np.minimum(CC[fya, fxa], rng.uniform(0.05, 0.24, n_fl).astype(np.float32))

    out = np.stack([M, R, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
spec_riveted_plate._spb_concept_complete = True


def spec_weld_seam(shape, seed, sm, num_passes=3, pass_spacing=8.0, **kwargs):
    """spec_weld_seam.

    identity: R6-CREATIVE â€” A FABRICATION-SHOP weld map that combines TWO
    weld dialects so the identity reads unmistakable at thumbnail: (1) a
    family of HORIZONTAL MIG bead lanes drawn as STACKED COIN-RIPPLE
    crescents (the signature TIG/MIG bead "dimes" â€” overlapping 6-10 px
    convex arcs along each lane, with bright crown + dark trailing
    shadow), and (2) a population of ARC-STRIKE STARBURSTS scattered
    across the panel â€” each starburst a bright 3-4 px nucleus with 4-6
    radial spatter trails (8-14 px) â€” a hero pyrotechnic motif. Stacked
    underneath: HAZ rainbow-oxide tempering dots (wide R/CC chroma),
    grinder-tool swirl arcs, deep slag voids, and a hot-rolled steel
    FBM substrate. Per-segment INDEPENDENT continuous M/R/CC, wide ranges.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + (hash("weld_seam_r6c") % 10000))
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)

    # 1) BASE â€” hot-rolled steel substrate, per-channel
    bM = _normalize(multi_scale_noise(shape, [2.5, 6.0, 12.0, 22.0], [0.36, 0.30, 0.22, 0.12], int(seed) + 3901))
    bR = _normalize(multi_scale_noise(shape, [3.0, 7.0, 14.0, 24.0], [0.34, 0.30, 0.22, 0.14], int(seed) + 3902))
    bC = _normalize(multi_scale_noise(shape, [3.5, 8.0, 15.0, 26.0], [0.32, 0.28, 0.22, 0.18], int(seed) + 3903))
    M = (0.48 + (bM - 0.5) * 0.26).astype(np.float32)
    R = (0.56 + (bR - 0.5) * 0.28).astype(np.float32)
    CC = (0.42 + (bC - 0.5) * 0.26).astype(np.float32)

    # 2) WELD LANES â€” horizontal repeated lanes (slight wobble)
    lane_pitch = max(22, int(32 * scale))
    lane_pitch = min(lane_pitch, max(8, h // 4))
    n_lanes = max(2, h // lane_pitch)
    lane_ys = [int((i + 0.5) * lane_pitch + rng.uniform(-2, 2)) for i in range(n_lanes)]

    if _CV2_OK:
        # 3) STACKED-COIN BEAD CRESCENTS â€” the hero dialect, fine convex arcs
        n_coin = int(np.clip(7500 * (mn / 2048.0) ** 2, 2400, 18000))
        for _ in range(n_coin):
            lane_y = lane_ys[int(rng.integers(0, n_lanes))]
            cx = int(rng.uniform(3, w - 3))
            cy = int(np.clip(lane_y + rng.uniform(-1.5, 1.5), 1, h - 1))
            ra = max(3, int(rng.uniform(4.5, 8.0) * scale))  # arc width
            rb = max(2, int(ra * rng.uniform(0.45, 0.75)))   # arc height
            # convex crown â€” top half
            _cv2.ellipse(M, (cx, cy), (ra, rb), 0, 200, 340,
                         float(rng.uniform(0.78, 0.99)), 1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(R, (cx, cy), (ra, rb), 0, 200, 340,
                         float(rng.uniform(0.22, 0.50)), 1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(CC, (cx, cy), (ra, rb), 0, 200, 340,
                         float(rng.uniform(0.12, 0.40)), 1, lineType=_cv2.LINE_AA)
            # trailing shadow â€” bottom shadow under each coin
            _cv2.ellipse(M, (cx, cy + 1), (ra, max(1, rb // 2)), 0, 0, 180,
                         float(rng.uniform(0.18, 0.38)), 1, lineType=_cv2.LINE_AA)

        # 4) BEAD-CHEVRON CROWN â€” overlapping short stitches for grit
        n_chev = int(np.clip(3500 * (mn / 2048.0) ** 2, 1200, 9000))
        for _ in range(n_chev):
            lane_y = lane_ys[int(rng.integers(0, n_lanes))]
            cx = float(rng.uniform(2, w - 2))
            cy = float(np.clip(lane_y + rng.uniform(-2.5, 2.5), 1, h - 1))
            L = float(rng.uniform(7.0, 14.0)) * scale
            A = float(rng.choice([-1, 1])) * float(rng.uniform(0.18, 0.42))
            x0 = int(cx - np.cos(A) * L * 0.5); y0 = int(cy - np.sin(A) * L * 0.5)
            x1 = int(cx + np.cos(A) * L * 0.5); y1 = int(cy + np.sin(A) * L * 0.5)
            _cv2.line(M, (x0, y0), (x1, y1), float(rng.uniform(0.72, 0.98)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(R, (x0, y0), (x1, y1), float(rng.uniform(0.22, 0.60)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (x0, y0), (x1, y1), float(rng.uniform(0.10, 0.42)), 1, lineType=_cv2.LINE_AA)

        # 5) ARC-STRIKE STARBURSTS â€” pyrotechnic hero accent (scattered freely)
        n_strike = int(np.clip(55 * (mn / 256.0), 24, 140))
        for _ in range(n_strike):
            cx = int(rng.integers(2, w - 2)); cy = int(rng.integers(2, h - 2))
            # bright nucleus
            nr = max(1, int(rng.uniform(2.0, 3.6) * scale))
            _cv2.circle(M, (cx, cy), nr, float(rng.uniform(0.88, 0.99)),
                        -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), nr, float(rng.uniform(0.06, 0.22)),
                        -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), nr, float(rng.uniform(0.05, 0.70)),
                        -1, lineType=_cv2.LINE_AA)
            n_rays = int(rng.integers(4, 7))
            a0 = float(rng.uniform(0, 2 * np.pi))
            for k in range(n_rays):
                a = a0 + k * (2 * np.pi / n_rays) + float(rng.uniform(-0.2, 0.2))
                L = float(rng.uniform(7.0, 14.0)) * scale
                x1p = int(np.clip(cx + np.cos(a) * L, 0, w - 1))
                y1p = int(np.clip(cy + np.sin(a) * L, 0, h - 1))
                _cv2.line(M, (cx, cy), (x1p, y1p), float(rng.uniform(0.55, 0.92)), 1, lineType=_cv2.LINE_AA)
                _cv2.line(R, (cx, cy), (x1p, y1p), float(rng.uniform(0.10, 0.38)), 1, lineType=_cv2.LINE_AA)
                _cv2.line(CC, (cx, cy), (x1p, y1p), float(rng.uniform(0.04, 0.50)), 1, lineType=_cv2.LINE_AA)

        # 6) HAZ TEMPERING DOTS â€” wide R/CC chroma (rainbow oxide bands)
        n_haz = int(np.clip(3500 * (mn / 2048.0) ** 2, 1200, 9000))
        for _ in range(n_haz):
            lane_y = lane_ys[int(rng.integers(0, n_lanes))]
            cx = int(rng.uniform(2, w - 2))
            cy = int(np.clip(lane_y + rng.uniform(-10, 10) * scale, 1, h - 1))
            r = max(1, int(rng.uniform(2.5, 6.0) * scale * 0.5))
            _cv2.circle(M, (cx, cy), r, float(rng.uniform(0.32, 0.72)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r, float(rng.uniform(0.18, 0.94)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r, float(rng.uniform(0.18, 0.88)), -1, lineType=_cv2.LINE_AA)

        # 7) GRINDER-SWIRL SCRATCH ARCS â€” 8-14 px curved scratches
        n_grind = int(np.clip(700 * (mn / 256.0), 220, 1800))
        for _ in range(n_grind):
            cx = int(rng.integers(4, w - 4)); cy = int(rng.integers(4, h - 4))
            ra = max(3, int(rng.uniform(5.0, 9.0) * scale))
            tilt = float(rng.uniform(0, 360))
            a0 = float(rng.uniform(0, 360)); a1 = a0 + float(rng.uniform(30, 90))
            _cv2.ellipse(M, (cx, cy), (ra, max(1, ra // 3)), tilt, a0, a1,
                         float(rng.uniform(0.18, 0.45)), 1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(R, (cx, cy), (ra, max(1, ra // 3)), tilt, a0, a1,
                         float(rng.uniform(0.55, 0.90)), 1, lineType=_cv2.LINE_AA)

        # 8) SLAG VOIDS â€” dark 1-3 px inclusions
        n_void = int(np.clip(2000 * (mn / 2048.0) ** 2, 700, 5500))
        for _ in range(n_void):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            r = max(1, int(rng.uniform(1.0, 2.2) * scale))
            _cv2.circle(M, (cx, cy), r, float(rng.uniform(0.12, 0.30)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r, float(rng.uniform(0.66, 0.92)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r, float(rng.uniform(0.55, 0.85)), -1, lineType=_cv2.LINE_AA)

    # 9) SPARK FLECKS â€” single-pixel scatter, wide chroma
    n_fl = int(np.clip(3500 * (mn / 2048.0) ** 2, 1200, 9000))
    fx = rng.integers(0, w, n_fl); fy = rng.integers(0, h, n_fl)
    M[fy, fx] = rng.uniform(0.28, 0.96, n_fl).astype(np.float32)
    R[fy, fx] = rng.uniform(0.18, 0.85, n_fl).astype(np.float32)
    CC[fy, fx] = rng.uniform(0.08, 0.78, n_fl).astype(np.float32)

    out = np.stack([M, R, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
spec_weld_seam._spb_concept_complete = True


def spec_stamped_emboss(shape, seed, sm, cell_size=28.0, **kwargs):
    """spec_stamped_emboss.

    identity: R6 creative rebuild â€” INDUSTRIAL DIE-PRESS HEX-CELL panel
    that reads unmistakably as stamped sheet metal. Five feature tiers:
    (1) HEXAGONAL HONEYCOMB die-cells (12-16 px cells in a true offset
    hex tiling â€” every other row offset, identity is non-square so it
    reads "stamped pattern", not "dots"); (2) raised CROWN RIM around
    each hex (bright M ring) with recessed BOWL interior (dark M, high
    R); (3) STAR RIVETS â€” 4-pointed cross-shaped rivet heads (8-12 px)
    sprinkled at random hex junctions; (4) cross-hatch TOOLING SCRATCH
    field between cells (4-10 px near-axial hairlines); (5) bright
    pinpoint die SPARKS. Per-cell INDEPENDENT continuous M/R/CC; widened
    ranges for dramatic chroma.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 320112)
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)
    cell = max(12.0, min(16.0, mn / 18.0))  # fine cell pitch 12-16 px
    hex_radius = cell * 0.5
    hex_h_step = cell * np.sqrt(3.0) * 0.5  # vertical spacing between rows

    # 1) SUBSTRATE â€” sheet-metal base, independent FBM per channel
    bM = _normalize(multi_scale_noise(shape, [2.5, 6.0, 12.0, 22.0], [0.36, 0.30, 0.22, 0.12], int(seed) + 32101))
    bR = _normalize(multi_scale_noise(shape, [3.0, 7.0, 14.0, 24.0], [0.32, 0.28, 0.22, 0.18], int(seed) + 32102))
    bC = _normalize(multi_scale_noise(shape, [3.5, 8.0, 16.0, 26.0], [0.30, 0.28, 0.24, 0.18], int(seed) + 32103))
    M = (0.58 + (bM - 0.5) * 0.26).astype(np.float32)
    R = (0.44 + (bR - 0.5) * 0.30).astype(np.float32)
    CC = (0.32 + (bC - 0.5) * 0.28).astype(np.float32)

    if _CV2_OK:
        # 2) HEX-CELL DIE GRID â€” true offset hex tiling
        nrows = int(np.ceil(h / hex_h_step)) + 2
        ncols = int(np.ceil(w / cell)) + 2
        hex_centers = []
        for ri in range(nrows):
            row_offset = (cell * 0.5) if (ri & 1) else 0.0
            cy = ri * hex_h_step
            for ci in range(ncols):
                cx = ci * cell + row_offset
                cx_j = cx + float(rng.uniform(-1.0, 1.0))
                cy_j = cy + float(rng.uniform(-1.0, 1.0))
                if cx_j < -hex_radius or cy_j < -hex_radius or cx_j >= w + hex_radius or cy_j >= h + hex_radius:
                    continue
                hex_centers.append((int(cx_j), int(cy_j)))
                # Hex polygon vertices (pointy-top)
                pts = []
                for k in range(6):
                    a = np.pi * (k / 3.0 + 0.5)
                    px = cx_j + np.cos(a) * hex_radius
                    py = cy_j + np.sin(a) * hex_radius
                    pts.append([int(px), int(py)])
                pts_np = np.array(pts, dtype=np.int32)
                # Bowl interior â€” recessed (dark M, high R)
                vM_b = float(rng.uniform(0.18, 0.48))
                vR_b = float(rng.uniform(0.58, 0.92))
                vC_b = float(rng.uniform(0.42, 0.80))
                _cv2.fillPoly(M, [pts_np], vM_b, lineType=_cv2.LINE_AA)
                _cv2.fillPoly(R, [pts_np], vR_b, lineType=_cv2.LINE_AA)
                _cv2.fillPoly(CC, [pts_np], vC_b, lineType=_cv2.LINE_AA)
                # Crown rim â€” bright sharp outline
                vM_r = float(rng.uniform(0.72, 0.98))
                vR_r = float(rng.uniform(0.06, 0.28))
                vC_r = float(rng.uniform(0.06, 0.26))
                _cv2.polylines(M, [pts_np], True, vM_r, 1, lineType=_cv2.LINE_AA)
                _cv2.polylines(R, [pts_np], True, vR_r, 1, lineType=_cv2.LINE_AA)
                _cv2.polylines(CC, [pts_np], True, vC_r, 1, lineType=_cv2.LINE_AA)

        # 3) STAR RIVETS â€” sparse 4-point cross-shaped rivet heads at hex junctions
        if hex_centers:
            n_rivet = int(np.clip(len(hex_centers) * 0.06, 30, 1500))
            for _ in range(n_rivet):
                idx = int(rng.integers(0, len(hex_centers)))
                cx, cy = hex_centers[idx]
                arm = max(2, int(rng.uniform(3.0, 6.0) * scale))
                vmM = float(rng.uniform(0.82, 0.99))
                vmR = float(rng.uniform(0.04, 0.18))
                vmC = float(rng.uniform(0.04, 0.20))
                _cv2.line(M, (cx - arm, cy), (cx + arm, cy), vmM, 1, lineType=_cv2.LINE_AA)
                _cv2.line(M, (cx, cy - arm), (cx, cy + arm), vmM, 1, lineType=_cv2.LINE_AA)
                _cv2.line(R, (cx - arm, cy), (cx + arm, cy), vmR, 1, lineType=_cv2.LINE_AA)
                _cv2.line(R, (cx, cy - arm), (cx, cy + arm), vmR, 1, lineType=_cv2.LINE_AA)
                _cv2.line(CC, (cx - arm, cy), (cx + arm, cy), vmC, 1, lineType=_cv2.LINE_AA)
                _cv2.line(CC, (cx, cy - arm), (cx, cy + arm), vmC, 1, lineType=_cv2.LINE_AA)
                # Central dot
                _cv2.circle(M, (cx, cy), max(1, arm // 2), vmM, -1, lineType=_cv2.LINE_AA)

        # 4) CROSS-HATCH TOOLING SCRATCHES â€” 4-10 px short axial hairlines
        n_scr = int(np.clip(6000 * (mn / 2048.0) ** 2, 2200, 15000))
        for _ in range(n_scr):
            cx = float(rng.uniform(2, w - 2)); cy = float(rng.uniform(2, h - 2))
            L = float(rng.uniform(4.0, 10.0)) * scale
            A = float(rng.choice([0.0, np.pi * 0.5]) + rng.uniform(-0.12, 0.12))
            x0 = int(cx - np.cos(A) * L * 0.5); y0 = int(cy - np.sin(A) * L * 0.5)
            x1 = int(cx + np.cos(A) * L * 0.5); y1 = int(cy + np.sin(A) * L * 0.5)
            _cv2.line(M, (x0, y0), (x1, y1), float(rng.uniform(0.50, 0.92)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(R, (x0, y0), (x1, y1), float(rng.uniform(0.16, 0.52)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (x0, y0), (x1, y1), float(rng.uniform(0.12, 0.42)), 1, lineType=_cv2.LINE_AA)

        # 5) DIE SPARKS â€” bright pinpoints
        n_spark = int(np.clip(3000 * (mn / 2048.0) ** 2, 1100, 7800))
        for _ in range(n_spark):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            r = max(1, int(rng.uniform(1.0, 2.0) * scale))
            _cv2.circle(M, (cx, cy), r, float(rng.uniform(0.78, 0.99)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r, float(rng.uniform(0.04, 0.22)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r, float(rng.uniform(0.04, 0.22)), -1, lineType=_cv2.LINE_AA)

    # 6) METAL SPARKLE FLECKS â€” fine per-pixel INDEPENDENT M/R/CC
    n_fl = int(np.clip(4200 * (mn / 2048.0) ** 2, 1500, 10500))
    fx = rng.integers(0, w, n_fl); fy = rng.integers(0, h, n_fl)
    M[fy, fx] = np.maximum(M[fy, fx], rng.uniform(0.55, 0.97, n_fl).astype(np.float32))
    R[fy, fx] = np.minimum(R[fy, fx], rng.uniform(0.06, 0.42, n_fl).astype(np.float32))
    CC[fy, fx] = np.minimum(CC[fy, fx], rng.uniform(0.05, 0.42, n_fl).astype(np.float32))

    out = np.stack([M, R, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
spec_stamped_emboss._spb_concept_complete = True


def spec_cast_surface(shape, seed, sm, bump_scale=0.15, grain_scale=0.05, **kwargs):
    """spec_cast_surface.

    identity: Tick-44 creative rebuild â€” RAW investment-cast metal as if pulled
    fresh from a sand mold. Hero motif: glowing PARTING SEAMS (5-7 long
    serpentine ridges crossing the panel, 2-4 px wide, with crystalline
    flash-burrs branching off) â€” these read as the actual seam where the
    two mold halves met. Around them: dense 1-3 px sand-grain stipple
    (carries the rough cast texture), 4-12 px irregular casting pits with
    bright sintered lips, 5-9 px gas blow-holes with dark voids + bright
    meniscus rings, 8-16 px pour-flow chevrons (where molten metal raced
    around obstructions), 6-14 px crystal-dendrite clusters (frozen
    solidification stars), and asymmetric SHRINK CAVITIES (12-24 px torn
    pockets where metal pulled away while cooling). Per-feature independent
    M/R/CC continuous uniforms with wide chroma spread for full owner-eye
    quality. No macro panel scale, no 8-tier palette, full coverage.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 45044)
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)

    # 1) Independent FBM substrate per channel (raw cast iron baseline)
    base_M = _normalize(multi_scale_noise(shape, [3.5, 10.0, 24.0, 55.0], [0.32, 0.28, 0.22, 0.18], int(seed) + 45045))
    base_R = _normalize(multi_scale_noise(shape, [4.0, 11.0, 26.0], [0.42, 0.30, 0.28], int(seed) + 45046))
    base_CC = _normalize(multi_scale_noise(shape, [4.5, 12.0, 28.0], [0.40, 0.32, 0.28], int(seed) + 45047))
    M = (0.58 + (base_M - 0.5) * 0.34).astype(np.float32)
    R = (0.57 + (base_R - 0.5) * 0.32).astype(np.float32)
    CC = (0.30 + (1.0 - base_CC) * 0.34).astype(np.float32)

    if _CV2_OK:
        # 2) HERO: PARTING SEAMS â€” serpentine mold-half ridges crossing the panel
        n_seam = int(rng.integers(5, 8))
        for _ in range(n_seam):
            x = float(rng.uniform(0, w)); y = float(rng.uniform(0, h))
            ang = float(rng.uniform(0, 2 * np.pi))
            seam_M = float(rng.uniform(0.70, 0.96))
            seam_R = float(rng.uniform(0.18, 0.46))
            seam_CC = float(rng.uniform(0.08, 0.34))
            wobble = float(rng.uniform(0.06, 0.18))
            steps = int(rng.integers(140, 260))
            step = float(rng.uniform(1.6, 2.4))
            for _s in range(steps):
                ang += float(rng.normal(0.0, wobble))
                nx = x + np.cos(ang) * step; ny = y + np.sin(ang) * step
                _cv2.line(M, (int(x), int(y)), (int(nx), int(ny)), seam_M, 2, lineType=_cv2.LINE_AA)
                _cv2.line(R, (int(x), int(y)), (int(nx), int(ny)), seam_R, 2, lineType=_cv2.LINE_AA)
                _cv2.line(CC, (int(x), int(y)), (int(nx), int(ny)), seam_CC, 2, lineType=_cv2.LINE_AA)
                # 5% chance: branch a flash-burr off this seam
                if rng.random() < 0.05:
                    bang = ang + float(rng.uniform(-1.5, 1.5))
                    blen = float(rng.uniform(4.0, 10.0) * scale)
                    bx = int(nx + np.cos(bang) * blen); by = int(ny + np.sin(bang) * blen)
                    _cv2.line(M, (int(nx), int(ny)), (bx, by), float(rng.uniform(0.62, 0.92)), 1, lineType=_cv2.LINE_AA)
                    _cv2.line(CC, (int(nx), int(ny)), (bx, by), float(rng.uniform(0.10, 0.38)), 1, lineType=_cv2.LINE_AA)
                x, y = nx, ny
                if x < 0 or x >= w or y < 0 or y >= h:
                    x = float(rng.uniform(0, w)); y = float(rng.uniform(0, h))

        # 3) DENSE SAND-GRAIN STIPPLE (1-3 px) â€” the raw cast tooth
        n_grain = max(24000, int(h * w / 9))
        gy = rng.integers(0, h, n_grain); gx = rng.integers(0, w, n_grain)
        M[gy, gx] = np.maximum(M[gy, gx], rng.uniform(0.40, 0.95, n_grain).astype(np.float32))
        R[gy, gx] = np.maximum(R[gy, gx], rng.uniform(0.30, 0.90, n_grain).astype(np.float32))
        CC[gy, gx] = np.minimum(CC[gy, gx], rng.uniform(0.12, 0.55, n_grain).astype(np.float32))

        # 4) IRREGULAR CASTING PITS (4-12 px) with bright sintered lip
        n_pit = max(900, int(h * w / 1800))
        for _ in range(n_pit):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            r = max(2, int(rng.uniform(4, 12) * scale * 0.5))
            # Irregular polygon pit (not perfect circle)
            n_v = int(rng.integers(5, 9))
            angs = np.sort(rng.uniform(0, 2 * np.pi, n_v))
            radii = r * rng.uniform(0.55, 1.30, n_v)
            pts = np.stack([cx + np.cos(angs) * radii, cy + np.sin(angs) * radii], axis=-1).astype(np.int32)
            _cv2.fillPoly(M, [pts], float(rng.uniform(0.06, 0.26)), lineType=_cv2.LINE_AA)
            _cv2.fillPoly(R, [pts], float(rng.uniform(0.76, 0.97)), lineType=_cv2.LINE_AA)
            _cv2.fillPoly(CC, [pts], float(rng.uniform(0.56, 0.93)), lineType=_cv2.LINE_AA)
            # Sintered bright lip
            _cv2.polylines(M, [pts], True, float(rng.uniform(0.66, 0.96)), 1, lineType=_cv2.LINE_AA)
            _cv2.polylines(R, [pts], True, float(rng.uniform(0.18, 0.44)), 1, lineType=_cv2.LINE_AA)

        # 5) GAS BLOW-HOLES (5-9 px) â€” dark interior + bright meniscus rim
        n_blow = max(750, int(h * w / 2900))
        for _ in range(n_blow):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            r = max(2, int(rng.uniform(5, 9) * scale * 0.5))
            _cv2.circle(M, (cx, cy), r, float(rng.uniform(0.05, 0.20)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r, float(rng.uniform(0.78, 0.97)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r, float(rng.uniform(0.60, 0.94)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(M, (cx, cy), r + 1, float(rng.uniform(0.64, 0.93)), 1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r + 1, float(rng.uniform(0.18, 0.42)), 1, lineType=_cv2.LINE_AA)

        # 6) POUR-FLOW CHEVRONS (8-16 px) â€” molten-metal race marks
        n_chev = max(600, int(h * w / 3800))
        flow_ang = float(rng.uniform(-0.4, 0.4))
        for _ in range(n_chev):
            cx = rng.uniform(8, w - 8); cy = rng.uniform(8, h - 8)
            length = float(rng.uniform(8.0, 16.0) * scale)
            for sign in (-1.0, 1.0):
                ang = flow_ang + sign * float(rng.uniform(0.30, 0.55))
                x1 = int(cx + np.cos(ang) * length); y1 = int(cy + np.sin(ang) * length)
                _cv2.line(M, (int(cx), int(cy)), (x1, y1), float(rng.uniform(0.52, 0.93)), 1, lineType=_cv2.LINE_AA)
                _cv2.line(R, (int(cx), int(cy)), (x1, y1), float(rng.uniform(0.28, 0.62)), 1, lineType=_cv2.LINE_AA)
                _cv2.line(CC, (int(cx), int(cy)), (x1, y1), float(rng.uniform(0.14, 0.46)), 1, lineType=_cv2.LINE_AA)

        # 7) CRYSTAL DENDRITES (6-14 px) â€” frozen solidification stars
        n_dend = max(280, int(h * w / 8400))
        for _ in range(n_dend):
            cx = float(rng.uniform(4, w - 4)); cy = float(rng.uniform(4, h - 4))
            n_arms = int(rng.integers(4, 7))
            arm_M = float(rng.uniform(0.66, 0.96))
            arm_R = float(rng.uniform(0.16, 0.40))
            arm_CC = float(rng.uniform(0.08, 0.34))
            ang0 = float(rng.uniform(0, 2 * np.pi))
            for a in range(n_arms):
                ang = ang0 + a * (2 * np.pi / n_arms) + float(rng.uniform(-0.18, 0.18))
                length = float(rng.uniform(6.0, 14.0) * scale)
                x1 = int(cx + np.cos(ang) * length); y1 = int(cy + np.sin(ang) * length)
                _cv2.line(M, (int(cx), int(cy)), (x1, y1), arm_M, 1, lineType=_cv2.LINE_AA)
                _cv2.line(R, (int(cx), int(cy)), (x1, y1), arm_R, 1, lineType=_cv2.LINE_AA)
                _cv2.line(CC, (int(cx), int(cy)), (x1, y1), arm_CC, 1, lineType=_cv2.LINE_AA)

        # 8) SHRINK CAVITIES (12-24 px) â€” torn asymmetric pockets
        n_shrink = max(60, int(h * w / 21000))
        for _ in range(n_shrink):
            cx = float(rng.uniform(12, w - 12)); cy = float(rng.uniform(12, h - 12))
            n_v = int(rng.integers(8, 14))
            base_r = float(rng.uniform(6.0, 12.0) * scale)
            angs = np.sort(rng.uniform(0, 2 * np.pi, n_v))
            radii = base_r * rng.uniform(0.40, 1.45, n_v)
            pts = np.stack([cx + np.cos(angs) * radii, cy + np.sin(angs) * radii], axis=-1).astype(np.int32)
            _cv2.fillPoly(M, [pts], float(rng.uniform(0.10, 0.32)), lineType=_cv2.LINE_AA)
            _cv2.fillPoly(R, [pts], float(rng.uniform(0.72, 0.95)), lineType=_cv2.LINE_AA)
            _cv2.fillPoly(CC, [pts], float(rng.uniform(0.50, 0.88)), lineType=_cv2.LINE_AA)

    out = np.stack([M, R, CC], axis=-1).astype(np.float32)
    return _validate_spec_output(_sm_scale(np.clip(out, 0.0, 1.0), sm).astype(np.float32), "spec_cast_surface")
spec_cast_surface._spb_concept_complete = True
spec_cast_surface._spb_concept_complete = True


