def spec_wood_grain_fine(shape, seed, sm, ring_freq=0.55, ring_warp=6.0, **kwargs):
    """spec_wood_grain_fine.

    identity: R6 OWNER-CORRECTIVE â€” owner saw "one design from one channel"
    on the previous anaglyph rebuild. Restored to ACTUAL fine quarter-sawn
    HARDWOOD GRAIN identity. Five stacked tiers: (1) deep amber substrate,
    (2) multi-octave warped GROWTH RINGS, the hero motif â€” densely packed
    arcs running edge-to-edge, (3) thousands of tiny PORE-VESSEL flecks
    (5-12 px) â€” the dark dots of open-grain oak/ash, (4) hair-fine MEDULLARY
    RAY streaks crossing the grain at 90deg, (5) fingernail-width LATEWOOD
    BAND highlights catching specular glint. All three channels carry the
    grain so the wood reads from every angle. Owner doctrine: fine 8-32 px,
    wide M/R/CC distribution, full canvas coverage, dense.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 911008)

    # --- TIER 1: amber substrate, composite-DARK (low all 3 channels)
    M = np.full((h, w), 0.20, dtype=np.float32)
    R_ch = np.full((h, w), 0.46, dtype=np.float32)  # mid roughness for satin wood
    CC = np.full((h, w), 0.16, dtype=np.float32)

    yy = np.arange(h, dtype=np.float32)[:, np.newaxis]
    xx = np.arange(w, dtype=np.float32)[np.newaxis, :]

    # Grain runs vertically (heart wood from "below"). Use warped distance
    # from a vertical pith line â€” produces parallel-but-curving rings.
    pith_x = float(rng.uniform(-w * 0.3, w * 0.4))
    # Warp the X coordinate with a couple of low-freq sines so rings feel organic
    warp = (np.sin(yy * 0.012 + rng.uniform(0, 6.28)) * 14.0 +
            np.sin(yy * 0.041 + rng.uniform(0, 6.28)) * 5.0 +
            np.sin((xx + yy) * 0.007 + rng.uniform(0, 6.28)) * 8.0)
    grain_x = xx + warp - pith_x

    # --- TIER 2: GROWTH RINGS â€” fine, ~3-6 px ring period. HERO.
    ring_period = float(rng.uniform(3.2, 5.5))
    rings = 0.5 + 0.5 * np.cos(grain_x * (2.0 * np.pi / ring_period))
    rings = rings ** 1.6  # sharpen the dark earlywood / light latewood transitions
    # Secondary slower modulation gives the "annual" growth-year breathing
    ring_year = 0.5 + 0.5 * np.sin(grain_x * (2.0 * np.pi / 38.0) + rng.uniform(0, 6.28))
    rings = rings * (0.55 + 0.45 * ring_year)
    rings = rings.astype(np.float32)

    # Apply rings: dark rings = LOW M / HIGH R / LOW CC ; light rings = MED M / MED R / HIGH CC
    M += rings * 0.55
    R_ch -= rings * 0.18
    CC += rings * 0.58

    if _CV2_OK:
        # --- TIER 5: LATEWOOD BAND highlights â€” fine bright streaks following rings
        n_bands = int(rng.integers(40, 70))
        for _ in range(n_bands):
            # Sample a ring peak and draw a thin AA line along it
            cx_b = int(rng.integers(0, w))
            cy_b = int(rng.integers(0, h))
            # Local grain tangent â€” rings curve, so use a short jittered vertical segment
            length = int(rng.integers(28, 90))  # streak length
            ang = rng.uniform(-0.15, 0.15)  # mostly vertical
            dx = np.sin(ang) * length
            dy = np.cos(ang) * length
            v_m = float(rng.uniform(0.78, 0.96))
            v_cc = float(rng.uniform(0.85, 0.99))
            _cv2.line(M, (cx_b, cy_b), (int(cx_b + dx), int(cy_b + dy)), v_m, 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (cx_b, cy_b), (int(cx_b + dx), int(cy_b + dy)), v_cc, 1, lineType=_cv2.LINE_AA)
            _cv2.line(R_ch, (cx_b, cy_b), (int(cx_b + dx), int(cy_b + dy)), float(rng.uniform(0.18, 0.32)), 1, lineType=_cv2.LINE_AA)

        # --- TIER 3: PORE VESSEL flecks â€” open-grain dark dots, 1500-2400 of them
        n_pores = int(np.clip(2200 * (min(h, w) / 256.0) ** 2, 400, 6000))
        px = rng.integers(0, w, n_pores)
        py = rng.integers(0, h, n_pores)
        for i in range(n_pores):
            r = int(rng.integers(1, 3))  # 1-2 px pore â€” SUPER fine
            v_dark_m = float(rng.uniform(0.04, 0.18))
            v_dark_cc = float(rng.uniform(0.02, 0.14))
            v_rough = float(rng.uniform(0.62, 0.88))
            _cv2.circle(M, (int(px[i]), int(py[i])), r, v_dark_m, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R_ch, (int(px[i]), int(py[i])), r, v_rough, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (int(px[i]), int(py[i])), r, v_dark_cc, -1, lineType=_cv2.LINE_AA)

        # --- TIER 4: MEDULLARY RAY streaks â€” hair-fine HORIZONTAL lines crossing grain
        n_rays = int(rng.integers(80, 140))
        for _ in range(n_rays):
            cy_r = int(rng.integers(0, h))
            cx_r = int(rng.integers(0, w))
            length_r = int(rng.integers(12, 28))  # 12-28 px fine ray
            v_m = float(rng.uniform(0.55, 0.78))
            v_cc = float(rng.uniform(0.45, 0.70))
            _cv2.line(M, (cx_r - length_r // 2, cy_r), (cx_r + length_r // 2, cy_r), v_m, 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (cx_r - length_r // 2, cy_r), (cx_r + length_r // 2, cy_r), v_cc, 1, lineType=_cv2.LINE_AA)

        # --- TIER 6 (bonus): tight KNOT eyes â€” 3-7 small dark whorls
        n_knots = int(rng.integers(3, 8))
        for _ in range(n_knots):
            cx_k = int(rng.integers(0, w))
            cy_k = int(rng.integers(0, h))
            rk = int(rng.integers(6, 14))
            # Concentric whorl rings
            for kr in range(rk, 0, -2):
                v = 0.10 + (rk - kr) * 0.05
                _cv2.circle(M, (cx_k, cy_k), kr, float(v), 1, lineType=_cv2.LINE_AA)
                _cv2.circle(CC, (cx_k, cy_k), kr, float(v * 0.7), 1, lineType=_cv2.LINE_AA)

    # Per-pixel chroma jitter â€” broad value distribution per Owner Rule 2
    M = np.clip(M + rng.uniform(-0.05, 0.05, (h, w)).astype(np.float32), 0.0, 1.0)
    R_ch = np.clip(R_ch + rng.uniform(-0.04, 0.04, (h, w)).astype(np.float32), 0.0, 1.0)
    CC = np.clip(CC + rng.uniform(-0.06, 0.06, (h, w)).astype(np.float32), 0.0, 1.0)

    out = np.stack([M, R_ch, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
spec_wood_grain_fine._spb_concept_complete = True



def spec_wood_burl(shape, seed, sm, num_eyes=8, eye_influence=0.55, **kwargs):
    """spec_wood_burl.

    identity: R6-CORRECTIVE for owner MIXED verdict on wood-burl. A walnut-
    burl veneer where the CATHEDRAL GRAIN-FLOW becomes the hero. Stacked:
    (A) deep-walnut FBM substrate with strong M/R/CC swings (warm chroma);
    (B) 3-6 LARGE HERO BURL BULLSEYES (12-22 px) â€” multi-ring 4-tier
    concentric formations with deep dark pupil, sapwood halo ring, bark
    outer rim, AND a bright crescent reflection chip; (C) hundreds of
    small 3-6 px secondary burl eyes carpeting the rest; (D) flow-aligned
    cathedral GRAIN BANDS â€” long 14-22 px dashes following a coherent
    swirl flow field so panels read with a strong directional grain
    story; (E) short cross-grain ticks 5-9 px; (F) pinhole knots 1-2 px
    very dark; (G) sapwood pinpoint flecks. Per-feature INDEPENDENT
    continuous M/R/CC. Heroes capped at 22 px (no panel-scale).
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 40117)
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)

    # A) BASE â€” wood-grain substrate, INDEPENDENT FBM per channel, wider swing
    bM = _normalize(multi_scale_noise(shape, [2.0, 5.0, 11.0, 22.0], [0.36, 0.30, 0.22, 0.12], int(seed) + 4101))
    bR = _normalize(multi_scale_noise(shape, [2.5, 6.0, 13.0, 24.0], [0.34, 0.30, 0.22, 0.14], int(seed) + 4102))
    bC = _normalize(multi_scale_noise(shape, [3.0, 7.0, 15.0, 26.0], [0.32, 0.28, 0.22, 0.18], int(seed) + 4103))
    M = (0.22 + (bM - 0.5) * 0.26).astype(np.float32)
    R = (0.60 + (bR - 0.5) * 0.34).astype(np.float32)
    CC = (0.44 + (bC - 0.5) * 0.32).astype(np.float32)

    # B) FLOW FIELD for grain streaming direction
    flow = _normalize(multi_scale_noise(shape, [12.0, 28.0], [0.6, 0.4], int(seed) + 4107))

    if _CV2_OK:
        # C) HERO BURL BULLSEYES â€” 3-6 large concentric multi-ring features
        n_hero = int(np.clip(6 * (mn / 256.0) ** 0.6, 3, 24))
        for _ in range(n_hero):
            cx = int(rng.uniform(0.08, 0.92) * w); cy = int(rng.uniform(0.08, 0.92) * h)
            r_out = max(6, int(rng.uniform(12.0, 22.0) * scale))
            r_brk = max(4, int(r_out * 0.85))
            r_sap = max(3, int(r_out * 0.62))
            r_pup = max(2, int(r_out * 0.32))
            # Independent hero chroma
            hM_dk = float(rng.uniform(0.08, 0.20)); hM_lt = float(rng.uniform(0.30, 0.55))
            hR_dk = float(rng.uniform(0.55, 0.78)); hR_lt = float(rng.uniform(0.30, 0.55))
            hC_dk = float(rng.uniform(0.30, 0.55)); hC_lt = float(rng.uniform(0.55, 0.85))
            # Outer bark rim (medium dark)
            _cv2.circle(M, (cx, cy), r_out, hM_dk, 2, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r_out, hR_dk, 2, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r_out, hC_dk, 2, lineType=_cv2.LINE_AA)
            # Brk inner ring (lighter sapwood)
            _cv2.circle(M, (cx, cy), r_brk, hM_lt, 1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r_brk, hR_lt, 1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r_brk, hC_lt, 1, lineType=_cv2.LINE_AA)
            # Sapwood ring
            _cv2.circle(M, (cx, cy), r_sap, float(hM_lt + 0.05), 1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r_sap, float(max(0.0, hR_lt - 0.10)), 1, lineType=_cv2.LINE_AA)
            # Deep dark pupil filled
            _cv2.circle(M, (cx, cy), r_pup, float(max(0.0, hM_dk - 0.04)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r_pup, float(min(1.0, hR_dk + 0.10)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r_pup, float(min(1.0, hC_dk + 0.10)), -1, lineType=_cv2.LINE_AA)
            # Crescent reflection chip on the top-left to give a 3D character
            cres_off = max(2, int(r_pup * 0.6))
            cres_r = max(1, int(r_pup * 0.55))
            _cv2.circle(M, (cx - cres_off, cy - cres_off), cres_r, float(rng.uniform(0.65, 0.92)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx - cres_off, cy - cres_off), cres_r, float(rng.uniform(0.55, 0.88)), -1, lineType=_cv2.LINE_AA)

        # D) SECONDARY BURL EYES â€” small 3-6 px multi-ring features (carpet)
        n_eye = int(np.clip(2400 * (mn / 2048.0) ** 2, 900, 6800))
        for _ in range(n_eye):
            cx = int(rng.uniform(2, w - 2)); cy = int(rng.uniform(2, h - 2))
            r_out = max(2, int(rng.uniform(3.0, 6.0) * scale))
            r_mid = max(1, int(r_out * 0.66))
            r_in = max(1, int(r_out * 0.33))
            _cv2.circle(M, (cx, cy), r_out, float(rng.uniform(0.16, 0.40)), 1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r_out, float(rng.uniform(0.48, 0.78)), 1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r_out, float(rng.uniform(0.28, 0.72)), 1, lineType=_cv2.LINE_AA)
            if r_mid >= 1:
                _cv2.circle(M, (cx, cy), r_mid, float(rng.uniform(0.20, 0.46)), 1, lineType=_cv2.LINE_AA)
                _cv2.circle(R, (cx, cy), r_mid, float(rng.uniform(0.34, 0.62)), 1, lineType=_cv2.LINE_AA)
                _cv2.circle(CC, (cx, cy), r_mid, float(rng.uniform(0.32, 0.66)), 1, lineType=_cv2.LINE_AA)
            _cv2.circle(M, (cx, cy), r_in, float(rng.uniform(0.06, 0.22)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r_in, float(rng.uniform(0.74, 0.96)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r_in, float(rng.uniform(0.42, 0.82)), -1, lineType=_cv2.LINE_AA)

        # E) CATHEDRAL GRAIN BANDS â€” long 14-22 px flow-aligned dashes
        n_band = int(np.clip(2400 * (mn / 2048.0) ** 2, 900, 6500))
        for _ in range(n_band):
            cx = int(rng.uniform(2, w - 2)); cy = int(rng.uniform(2, h - 2))
            L = float(rng.uniform(14.0, 22.0)) * scale
            A = float(flow[cy, cx]) * 2.0 * np.pi + float(rng.normal(0, 0.18))
            x0 = int(cx - np.cos(A) * L * 0.5); y0 = int(cy - np.sin(A) * L * 0.5)
            x1 = int(cx + np.cos(A) * L * 0.5); y1 = int(cy + np.sin(A) * L * 0.5)
            _cv2.line(M, (x0, y0), (x1, y1), float(rng.uniform(0.10, 0.34)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(R, (x0, y0), (x1, y1), float(rng.uniform(0.48, 0.82)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (x0, y0), (x1, y1), float(rng.uniform(0.28, 0.72)), 1, lineType=_cv2.LINE_AA)

        # F) CROSS-GRAIN TICKS â€” 5-9 px perpendicular to local flow
        n_tick = int(np.clip(2200 * (mn / 2048.0) ** 2, 800, 6000))
        for _ in range(n_tick):
            cx = int(rng.uniform(2, w - 2)); cy = int(rng.uniform(2, h - 2))
            L = float(rng.uniform(5.0, 9.0)) * scale
            A = float(flow[cy, cx]) * 2.0 * np.pi + np.pi / 2 + float(rng.normal(0, 0.20))
            x0 = int(cx - np.cos(A) * L * 0.5); y0 = int(cy - np.sin(A) * L * 0.5)
            x1 = int(cx + np.cos(A) * L * 0.5); y1 = int(cy + np.sin(A) * L * 0.5)
            _cv2.line(M, (x0, y0), (x1, y1), float(rng.uniform(0.16, 0.38)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(R, (x0, y0), (x1, y1), float(rng.uniform(0.50, 0.78)), 1, lineType=_cv2.LINE_AA)

        # G) PINHOLE KNOTS â€” small dark 1-2 px
        n_knot = int(np.clip(2400 * (mn / 2048.0) ** 2, 800, 6500))
        for _ in range(n_knot):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            r = max(1, int(rng.uniform(1.0, 2.2) * scale))
            _cv2.circle(M, (cx, cy), r, float(rng.uniform(0.04, 0.18)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r, float(rng.uniform(0.80, 0.97)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r, float(rng.uniform(0.55, 0.85)), -1, lineType=_cv2.LINE_AA)

    # H) SAPWOOD PINPOINT FLECKS â€” single-pixel
    n_fl = int(np.clip(4000 * (mn / 2048.0) ** 2, 1500, 10000))
    fx = rng.integers(0, w, n_fl); fy = rng.integers(0, h, n_fl)
    R[fy, fx] = np.minimum(R[fy, fx], rng.uniform(0.28, 0.72, n_fl).astype(np.float32))
    CC[fy, fx] = np.maximum(CC[fy, fx], rng.uniform(0.50, 0.92, n_fl).astype(np.float32))

    out = np.stack([M, R, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
spec_wood_burl._spb_concept_complete = True


def spec_stone_granite(shape, seed, sm, num_crystals=600, **kwargs):
    """spec_stone_granite.

    identity: R6 creative rebuild â€” DRAMATIC FLAMED granite slab, the
    kind torched on a counter shop floor. SEVEN feature tiers stacked on
    an independent-FBM substrate: (1) hard-edged rotated FELDSPAR grains
    (6-16 px rectangles) tile shoulder-to-shoulder; (2) glittering
    PYRITE CUBES (3-6 px hard-cornered squares, near-mirror M, ultra-low
    R); (3) QUARTZ disc grains (4-9 px glossy translucent pockets); (4)
    sharp angular FISSURES (8-22 px straight crack seams running in
    quasi-parallel diagonal bands); (5) MICA WINK FLAKES (1-3 px,
    directionally lit by a flame-blast gradient); (6) dark BIOTITE
    pepper; (7) hornblende needles (6-10 px stick streaks). Per-mineral
    INDEPENDENT continuous M/R/CC.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 330122)
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)

    # 1) SUBSTRATE â€” independent FBM per channel
    bM = _normalize(multi_scale_noise(shape, [2.5, 6.5, 13.0, 22.0], [0.36, 0.30, 0.22, 0.12], int(seed) + 33001))
    bR = _normalize(multi_scale_noise(shape, [3.0, 7.5, 15.0, 24.0], [0.34, 0.30, 0.22, 0.14], int(seed) + 33002))
    bC = _normalize(multi_scale_noise(shape, [3.5, 8.5, 16.5, 26.0], [0.32, 0.28, 0.22, 0.18], int(seed) + 33003))
    M = (0.32 + (bM - 0.5) * 0.26).astype(np.float32)
    R = (0.50 + (bR - 0.5) * 0.32).astype(np.float32)
    CC = (0.50 + (bC - 0.5) * 0.36).astype(np.float32)

    # Flame-torch flash gradient â€” light source angle for mica wink
    yy = np.arange(h, dtype=np.float32)[:, None]
    xx = np.arange(w, dtype=np.float32)[None, :]
    flash_ang = float(rng.uniform(0.3, 1.3))
    flash_proj = (xx * np.cos(flash_ang) + yy * np.sin(flash_ang)) / max(mn, 1)
    flash = np.exp(-((flash_proj - flash_proj.mean()) ** 2) / 0.16).astype(np.float32)

    # Choose dominant fissure direction
    fissure_ang = float(rng.uniform(0, np.pi))

    if _CV2_OK:
        # 2) FELDSPAR GRAINS â€” tile shoulder-to-shoulder
        n_feld = int(np.clip(11000 * (mn / 2048.0) ** 2, 3800, 30000))
        for _ in range(n_feld):
            cx = float(rng.uniform(4, w - 4)); cy = float(rng.uniform(4, h - 4))
            sw_ = float(rng.uniform(6.0, 16.0) * scale)
            sh_ = float(rng.uniform(6.0, 16.0) * scale)
            ang = float(rng.uniform(0, 180))
            vM = float(rng.uniform(0.14, 0.52))
            vR = float(rng.uniform(0.26, 0.66))
            vC = float(rng.uniform(0.42, 0.92))
            rect = ((cx, cy), (sw_, sh_), ang)
            box = _cv2.boxPoints(rect).astype(np.int32)
            _cv2.fillPoly(M, [box], vM, lineType=_cv2.LINE_AA)
            _cv2.fillPoly(R, [box], vR, lineType=_cv2.LINE_AA)
            _cv2.fillPoly(CC, [box], vC, lineType=_cv2.LINE_AA)

        # 3) PYRITE CUBES â€” bright 3-6 px hard-cornered squares
        n_pyr = int(np.clip(2200 * (mn / 2048.0) ** 2, 800, 6500))
        for _ in range(n_pyr):
            cx = float(rng.uniform(3, w - 3)); cy = float(rng.uniform(3, h - 3))
            s = float(rng.uniform(3.0, 6.0) * scale)
            ang = float(rng.choice([0.0, 15.0, 30.0, 45.0, 60.0, 75.0]))
            rect = ((cx, cy), (s, s), ang)
            box = _cv2.boxPoints(rect).astype(np.int32)
            _cv2.fillPoly(M, [box], float(rng.uniform(0.80, 0.99)), lineType=_cv2.LINE_AA)
            _cv2.fillPoly(R, [box], float(rng.uniform(0.04, 0.18)), lineType=_cv2.LINE_AA)
            _cv2.fillPoly(CC, [box], float(rng.uniform(0.10, 0.35)), lineType=_cv2.LINE_AA)

        # 4) QUARTZ TRANSLUCENT DISCS â€” 4-9 px glossy pockets
        n_qtz = int(np.clip(5500 * (mn / 2048.0) ** 2, 2000, 14000))
        for _ in range(n_qtz):
            cx = int(rng.uniform(2, w - 2)); cy = int(rng.uniform(2, h - 2))
            r = max(2, int(rng.uniform(2.0, 5.0) * scale))
            _cv2.circle(M, (cx, cy), r, float(rng.uniform(0.18, 0.50)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r, float(rng.uniform(0.20, 0.55)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r, float(rng.uniform(0.04, 0.28)), -1, lineType=_cv2.LINE_AA)

        # 5) ANGULAR FISSURES â€” 8-22 px straight seams in diagonal bands
        n_fis = int(np.clip(2400 * (mn / 2048.0) ** 2, 850, 6500))
        for _ in range(n_fis):
            cx = float(rng.uniform(2, w - 2)); cy = float(rng.uniform(2, h - 2))
            L = float(rng.uniform(8.0, 22.0)) * scale
            A = fissure_ang + float(rng.uniform(-0.40, 0.40))
            if rng.random() < 0.35:
                A = fissure_ang + np.pi * 0.5 + float(rng.uniform(-0.40, 0.40))
            x0 = int(cx - np.cos(A) * L * 0.5); y0 = int(cy - np.sin(A) * L * 0.5)
            x1 = int(cx + np.cos(A) * L * 0.5); y1 = int(cy + np.sin(A) * L * 0.5)
            _cv2.line(M, (x0, y0), (x1, y1), float(rng.uniform(0.06, 0.26)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(R, (x0, y0), (x1, y1), float(rng.uniform(0.66, 0.96)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (x0, y0), (x1, y1), float(rng.uniform(0.50, 0.88)), 1, lineType=_cv2.LINE_AA)

        # 6) HORNBLENDE NEEDLES â€” short dark sticks 6-10 px
        n_horn = int(np.clip(1800 * (mn / 2048.0) ** 2, 700, 5000))
        for _ in range(n_horn):
            cx = float(rng.uniform(2, w - 2)); cy = float(rng.uniform(2, h - 2))
            L = float(rng.uniform(6.0, 10.0)) * scale
            A = float(rng.uniform(0, 2 * np.pi))
            x0 = int(cx - np.cos(A) * L * 0.5); y0 = int(cy - np.sin(A) * L * 0.5)
            x1 = int(cx + np.cos(A) * L * 0.5); y1 = int(cy + np.sin(A) * L * 0.5)
            _cv2.line(M, (x0, y0), (x1, y1), float(rng.uniform(0.08, 0.28)), 2, lineType=_cv2.LINE_AA)
            _cv2.line(R, (x0, y0), (x1, y1), float(rng.uniform(0.58, 0.90)), 2, lineType=_cv2.LINE_AA)

    # 7) MICA WINK FLAKES â€” bright 1-3 px, modulated by torch-flash band
    n_mica = int(np.clip(9000 * (mn / 2048.0) ** 2, 3200, 24000))
    mx = rng.integers(0, w, n_mica); my = rng.integers(0, h, n_mica)
    flash_at = flash[my, mx]
    keep = rng.random(n_mica) < (0.30 + 0.65 * flash_at)
    mx = mx[keep]; my = my[keep]
    nM = mx.shape[0]
    if nM > 0:
        M[my, mx] = np.maximum(M[my, mx], rng.uniform(0.74, 0.99, nM).astype(np.float32))
        R[my, mx] = np.minimum(R[my, mx], rng.uniform(0.04, 0.24, nM).astype(np.float32))
        CC[my, mx] = np.minimum(CC[my, mx], rng.uniform(0.04, 0.22, nM).astype(np.float32))

    # 8) BIOTITE DARK FLECKS
    n_bi = int(np.clip(3800 * (mn / 2048.0) ** 2, 1300, 9500))
    bx = rng.integers(0, w, n_bi); by = rng.integers(0, h, n_bi)
    M[by, bx] = np.minimum(M[by, bx], rng.uniform(0.05, 0.22, n_bi).astype(np.float32))
    R[by, bx] = np.maximum(R[by, bx], rng.uniform(0.60, 0.94, n_bi).astype(np.float32))
    CC[by, bx] = np.maximum(CC[by, bx], rng.uniform(0.55, 0.92, n_bi).astype(np.float32))

    out = np.stack([M, R, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
spec_stone_granite._spb_concept_complete = True


def adelson_checker_shadow(shape, seed, sm, vein_freq=0.08, vein_warp=7.0, **kwargs):
    """adelson_checker_shadow - renamed from spec_stone_marble per owner.

    identity: ADELSON CHECKER-SHADOW. A checker grid (12-16 px tiles) is
    swept by a diagonal "shadow" gradient. Tiles inside the shadow appear
    BRIGHTER than identically-luminant tiles outside â€” a textbook demo of
    lateral inhibition / brightness constancy. R variation marks which
    tiles fall in shadow; CC varies per-tile (angle-dependent shift on car).

    TICK-81 SECOND-PASS HERO: 5-FOLD QUASIPERIODIC PENROSE ROSETTES.
    Scattered across the checker, 5-fold-symmetric kite/dart star clusters
    are inlaid (8-14 px radius) with 5 alternating triangular wedges,
    each wedge an INDEPENDENT TIGHT-jitter chroma sample from a COOL
    ICE-BLUE accent palette (M=0.30, R=0.18, CC=0.78). These pentagonal
    stars break the strict 4-fold grid with non-crystallographic symmetry â€”
    a literal slice of Penrose tiling embedded in the Adelson illusion.
    """
    h, w = shape
    if sm is None:
        sm = 1.0
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 911007)

    tile = int(rng.integers(12, 17))
    yy, xx = np.indices((h, w), dtype=np.float32)

    # Per-tile checker pattern (alternating bright/dark)
    ty = (yy // tile).astype(np.int32)
    tx = (xx // tile).astype(np.int32)
    checker = ((ty + tx) % 2).astype(np.float32)

    # Two physical M values (the "trick": same actual M, different perceived)
    M_bright = 0.78
    M_dark = 0.22
    M = np.where(checker > 0.5, M_bright, M_dark).astype(np.float32)

    # Diagonal "shadow" sweep â€” low-frequency smooth ramp
    ang = float(rng.uniform(0.5, 1.2))
    proj = (xx * np.cos(ang) + yy * np.sin(ang)) / max(h, w)
    # Soft penumbra: smoothstep from outside to inside the shadow
    shadow_start = float(rng.uniform(0.30, 0.40))
    shadow_end = float(rng.uniform(0.60, 0.72))
    shadow = np.clip((proj - shadow_start) / max(shadow_end - shadow_start, 1e-6), 0.0, 1.0)
    shadow = shadow * shadow * (3.0 - 2.0 * shadow)  # smoothstep

    # Shadow REDUCES M but the visual system corrects â€” that IS the illusion.
    # On the spec map we encode the literal physical M reduction. The GGX
    # renderer + viewer brain create the perceived equalization.
    M = M * (1.0 - shadow * 0.55)

    # R = lateral inhibition marker â€” tiles in shadow get LOWER R (smoother) to
    # contrast with bright unshaded tiles (rougher edges) â€” drives angle response.
    R_ch = np.where(checker > 0.5, 0.18, 0.62).astype(np.float32)
    R_ch = R_ch + (1.0 - shadow) * 0.10

    # CC per-tile INDEPENDENT continuous uniform â€” chroma diversity / angle shift
    # Sample a per-tile random table, vectorized
    n_tx = int(np.ceil(w / tile)) + 1
    n_ty = int(np.ceil(h / tile)) + 1
    cc_table = rng.uniform(0.05, 0.95, (n_ty, n_tx)).astype(np.float32)
    CC = cc_table[np.clip(ty, 0, n_ty - 1), np.clip(tx, 0, n_tx - 1)]
    CC = CC * (1.0 - shadow * 0.30)  # shadow also tints CC

    # Per-pixel jitter (chroma diversity)
    M = np.clip(M + rng.uniform(-0.03, 0.03, (h, w)).astype(np.float32), 0.0, 1.0)
    CC = np.clip(CC + rng.uniform(-0.05, 0.05, (h, w)).astype(np.float32), 0.0, 1.0)
    R_ch = np.clip(R_ch, 0.0, 1.0)

    # TICK-81 HERO: 5-FOLD PENROSE-INSPIRED ROSETTES â€” non-crystallographic
    # pentagonal stars inlaid across the checker. Each rosette is
    # 5 alternating wedge triangles in a COOL ICE-BLUE palette.
    # Use a deterministic full-canvas grid (with per-cell jitter) so coverage
    # is guaranteed â€” the previous random seed clustered them in one corner.
    if _CV2_OK:
        ICE_M, ICE_R, ICE_CC = 0.30, 0.18, 0.78
        JIT_ICE = 0.05
        pent_pitch = int(np.clip(36 * (min(h, w) / 256.0), 28, 48))
        gx_cells = max(1, w // pent_pitch + 1)
        gy_cells = max(1, h // pent_pitch + 1)
        n_pent = gx_cells * gy_cells
        for gi in range(n_pent):
            gcol = gi % gx_cells
            grow = gi // gx_cells
            base_cx = gcol * pent_pitch + pent_pitch // 2
            base_cy = grow * pent_pitch + pent_pitch // 2
            cxp = int(np.clip(base_cx + int(rng.integers(-pent_pitch // 3, pent_pitch // 3 + 1)), 8, max(9, w - 8)))
            cyp = int(np.clip(base_cy + int(rng.integers(-pent_pitch // 3, pent_pitch // 3 + 1)), 8, max(9, h - 8)))
            r_out = float(rng.uniform(8.0, 14.0))
            r_in = r_out * 0.42
            phi = float(rng.uniform(0, 2 * np.pi))
            # 10-vertex star (5 outer + 5 inner) â€” alternating wedge fill
            for k in range(5):
                a0 = phi + k * (2 * np.pi / 5)
                a1 = a0 + (2 * np.pi / 10)
                a2 = a0 + (2 * np.pi / 5)
                p_out = (cxp + np.cos(a0) * r_out, cyp + np.sin(a0) * r_out)
                p_mid = (cxp + np.cos(a1) * r_in, cyp + np.sin(a1) * r_in)
                p_out2 = (cxp + np.cos(a2) * r_out, cyp + np.sin(a2) * r_out)
                # outer wedge â€” brighter ice CC
                tri = np.array([[cxp, cyp],
                                [int(p_out[0]), int(p_out[1])],
                                [int(p_mid[0]), int(p_mid[1])]], dtype=np.int32)
                mv = float(np.clip(ICE_M + rng.uniform(-JIT_ICE, JIT_ICE), 0.05, 0.95))
                rv = float(np.clip(ICE_R + rng.uniform(-JIT_ICE, JIT_ICE), 0.02, 0.40))
                cv = float(np.clip(ICE_CC + rng.uniform(-JIT_ICE, JIT_ICE), 0.50, 0.99))
                _cv2.fillPoly(M, [tri], mv, lineType=_cv2.LINE_AA)
                _cv2.fillPoly(R_ch, [tri], rv, lineType=_cv2.LINE_AA)
                _cv2.fillPoly(CC, [tri], cv, lineType=_cv2.LINE_AA)
                # paired inner wedge â€” slightly darker variant for kite/dart contrast
                tri2 = np.array([[cxp, cyp],
                                 [int(p_mid[0]), int(p_mid[1])],
                                 [int(p_out2[0]), int(p_out2[1])]], dtype=np.int32)
                mv2 = float(np.clip(ICE_M + rng.uniform(-JIT_ICE, JIT_ICE) - 0.08, 0.05, 0.95))
                cv2 = float(np.clip(ICE_CC + rng.uniform(-JIT_ICE, JIT_ICE) - 0.06, 0.40, 0.99))
                _cv2.fillPoly(M, [tri2], mv2, lineType=_cv2.LINE_AA)
                _cv2.fillPoly(CC, [tri2], cv2, lineType=_cv2.LINE_AA)
            # pivot pinpoint
            if 0 <= cxp < w and 0 <= cyp < h:
                M[cyp, cxp] = 0.92; CC[cyp, cxp] = 0.94

    out = np.stack([M, R_ch, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
adelson_checker_shadow._spb_concept_complete = True



def spec_water_ripple_spec(shape, seed, sm, num_drops=6, **kwargs):
    """spec_water_ripple_spec.

    identity: R6-CREATIVE â€” A POND-IN-RAIN where the hero motif is an
    ANALYTIC interference field: a closed-form sum of concentric cosine
    wave-trains from ~10 droplet centres rendered into M and CC so each
    ring is a continuous sinusoidal crest/trough, plus INTERFERENCE
    fringes where waves cross (an actual physics-accurate look â€” owners
    can spot the wave-front spider web). Stacked: bright droplet cores
    with crown-splash crowns (5-7 spike micro-rays around each centre),
    a dense fine sparkle carpet, foam flecks, surface-tension micro-
    dimples (1-2 px dark CC), and a glossy water FBM substrate. Per-
    feature INDEPENDENT continuous M/R/CC, wide ranges. Full coverage.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + (hash("water_ripple_r6c") % 10000))
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)

    # 1) BASE â€” wet water substrate, per-channel independent FBM
    bM = _normalize(multi_scale_noise(shape, [2.0, 5.0, 12.0, 24.0], [0.34, 0.30, 0.22, 0.14], int(seed) + 3801))
    bR = _normalize(multi_scale_noise(shape, [2.5, 6.0, 13.0, 22.0], [0.32, 0.28, 0.22, 0.18], int(seed) + 3802))
    bC = _normalize(multi_scale_noise(shape, [3.0, 7.0, 14.0, 26.0], [0.30, 0.28, 0.24, 0.18], int(seed) + 3803))
    M = (0.22 + (bM - 0.5) * 0.20).astype(np.float32)
    R = (0.24 + (bR - 0.5) * 0.22).astype(np.float32)
    CC = (0.16 + (bC - 0.5) * 0.18).astype(np.float32)

    # 2) ANALYTIC RIPPLE INTERFERENCE FIELD â€” the hero motif (vectorised)
    yy = np.arange(h, dtype=np.float32)[:, None]
    xx = np.arange(w, dtype=np.float32)[None, :]
    n_centres = int(np.clip(12 * (mn / 256.0), 8, 20))
    wave_M = np.zeros((h, w), dtype=np.float32)
    wave_CC = np.zeros((h, w), dtype=np.float32)
    centres = []
    for _ in range(n_centres):
        cx = float(rng.uniform(0.05, 0.95) * w)
        cy = float(rng.uniform(0.05, 0.95) * h)
        centres.append((cx, cy))
        wavelen = float(rng.uniform(7.0, 14.0)) * scale  # ring pitch
        phase = float(rng.uniform(0, 2 * np.pi))
        amp = float(rng.uniform(0.32, 0.58))
        dist = np.sqrt((xx - cx) ** 2 + (yy - cy) ** 2)
        # damped cosine â€” ripples decay outward
        decay = np.exp(-dist / (max(mn, 1) * 0.7)).astype(np.float32)
        w_M = np.cos(dist * (2 * np.pi / wavelen) + phase).astype(np.float32) * decay * amp
        w_CC = np.cos(dist * (2 * np.pi / wavelen) + phase + 0.6).astype(np.float32) * decay * (amp * 0.7)
        wave_M += w_M
        wave_CC += w_CC

    # Normalise interference field and blend in
    M = np.clip(M + wave_M * 0.55, 0, 1)
    CC = np.clip(CC + wave_CC * 0.60, 0, 1)
    # Whiten R where wave crests are strongest (foam-rich crests)
    crest = np.clip(wave_M, 0, None)
    R = np.clip(R - crest * 0.35, 0, 1)

    if _CV2_OK:
        # 3) DROPLET CORES with CROWN SPLASH SPIKES â€” fine hero detail
        for (cx, cy) in centres:
            icx = int(np.clip(cx, 0, w - 1))
            icy = int(np.clip(cy, 0, h - 1))
            core_r = max(1, int(rng.uniform(1.6, 2.6) * scale))
            _cv2.circle(M, (icx, icy), core_r, float(rng.uniform(0.84, 0.99)),
                        -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (icx, icy), core_r, float(rng.uniform(0.04, 0.18)),
                        -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (icx, icy), core_r, float(rng.uniform(0.02, 0.16)),
                        -1, lineType=_cv2.LINE_AA)
            # crown of 5-7 micro-spikes (radial fine tendrils)
            n_sp = int(rng.integers(5, 8))
            a0 = float(rng.uniform(0, 2 * np.pi))
            for k in range(n_sp):
                a = a0 + k * (2 * np.pi / n_sp) + float(rng.uniform(-0.1, 0.1))
                L = float(rng.uniform(4.0, 9.0)) * scale
                x1p = int(np.clip(cx + np.cos(a) * L, 0, w - 1))
                y1p = int(np.clip(cy + np.sin(a) * L, 0, h - 1))
                _cv2.line(M, (icx, icy), (x1p, y1p), float(rng.uniform(0.60, 0.92)),
                          1, lineType=_cv2.LINE_AA)
                _cv2.line(R, (icx, icy), (x1p, y1p), float(rng.uniform(0.08, 0.24)),
                          1, lineType=_cv2.LINE_AA)
                _cv2.line(CC, (icx, icy), (x1p, y1p), float(rng.uniform(0.04, 0.18)),
                          1, lineType=_cv2.LINE_AA)

        # 4) CREST-ARC FRAGMENTS â€” short ellipse arcs scattered on crest bands
        n_arc = int(np.clip(2500 * (mn / 2048.0) ** 2, 800, 7000))
        for _ in range(n_arc):
            cx = int(rng.uniform(2, w - 2)); cy = int(rng.uniform(2, h - 2))
            r = max(2, int(rng.uniform(3.0, 6.0) * scale))
            a0 = float(rng.uniform(0, 360)); a1 = a0 + float(rng.uniform(40, 120))
            _cv2.ellipse(M, (cx, cy), (r, r), 0, a0, a1, float(rng.uniform(0.52, 0.94)), 1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(R, (cx, cy), (r, r), 0, a0, a1, float(rng.uniform(0.08, 0.30)), 1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(CC, (cx, cy), (r, r), 0, a0, a1, float(rng.uniform(0.03, 0.18)), 1, lineType=_cv2.LINE_AA)

    # 5) DROPLET SPARKLE CARPET â€” dense pinpoint highlights, wider chroma
    n_sp = int(np.clip(6500 * (mn / 2048.0) ** 2, 2400, 17000))
    sx = rng.integers(0, w, n_sp); sy = rng.integers(0, h, n_sp)
    M[sy, sx] = np.maximum(M[sy, sx], rng.uniform(0.62, 0.98, n_sp).astype(np.float32))
    R[sy, sx] = np.minimum(R[sy, sx], rng.uniform(0.06, 0.22, n_sp).astype(np.float32))
    CC[sy, sx] = np.minimum(CC[sy, sx], rng.uniform(0.02, 0.20, n_sp).astype(np.float32))

    # 6) FOAM FLECKS â€” matte high-R single-pixel scatter
    n_fl = int(np.clip(2200 * (mn / 2048.0) ** 2, 800, 6000))
    fx = rng.integers(0, w, n_fl); fy = rng.integers(0, h, n_fl)
    R[fy, fx] = np.maximum(R[fy, fx], rng.uniform(0.55, 0.88, n_fl).astype(np.float32))
    CC[fy, fx] = np.minimum(CC[fy, fx], rng.uniform(0.10, 0.32, n_fl).astype(np.float32))

    # 7) SURFACE-TENSION MICRO-DIMPLES â€” 1-2 px CC dark dots
    n_dim = int(np.clip(2800 * (mn / 2048.0) ** 2, 900, 7500))
    dx = rng.integers(0, w, n_dim); dy = rng.integers(0, h, n_dim)
    CC[dy, dx] = np.minimum(CC[dy, dx], rng.uniform(0.02, 0.10, n_dim).astype(np.float32))
    M[dy, dx] = np.maximum(M[dy, dx], rng.uniform(0.50, 0.85, n_dim).astype(np.float32))

    # 8) NEW HERO (tick-creativity) â€” DRAGON-CURVE FOAM TRAILS.
    # Math curve where wavy polylines would normally go: stamp 3-6 short
    # iterations of the dragon (Heighway) fractal across the pond, each ~30
    # vertices long, axis-aligned 90deg turns at 1.4 px scale clamped 12-22
    # px AABB. Reads as foam ribbons twisting in the current. Independent
    # M / R / CC per dragon ribbon.
    if _CV2_OK:
        n_dragons = int(rng.integers(3, 7))
        for _ in range(n_dragons):
            iters = 7  # 2^7-1 = 127 segments
            # turns: classic dragon-curve turn sequence
            turns = []
            for i in range(1, (1 << iters)):
                # bit just above the lowest set bit
                low = i & -i
                bit = (i & (low << 1)) == 0  # left-turn if bit set
                turns.append(1 if bit else -1)
            seg = float(rng.uniform(0.55, 0.95) * scale)
            heading = float(rng.uniform(0.0, 2.0 * np.pi))
            cx_d = float(rng.uniform(0.1, 0.9) * w)
            cy_d = float(rng.uniform(0.1, 0.9) * h)
            xs = [cx_d]; ys = [cy_d]
            x = cx_d; y = cy_d
            for t in turns[:50]:  # truncate to keep speed
                x += np.cos(heading) * seg
                y += np.sin(heading) * seg
                xs.append(x); ys.append(y)
                heading += (np.pi / 2.0) * t
            pts = np.stack([np.array(xs, dtype=np.int32),
                            np.array(ys, dtype=np.int32)], axis=-1)
            m_v = float(rng.uniform(0.55, 0.95))
            r_v = float(rng.uniform(0.10, 0.32))
            c_v = float(rng.uniform(0.45, 0.92))
            _cv2.polylines(M, [pts], False, m_v, 1, lineType=_cv2.LINE_AA)
            _cv2.polylines(R, [pts], False, r_v, 1, lineType=_cv2.LINE_AA)
            _cv2.polylines(CC, [pts], False, c_v, 1, lineType=_cv2.LINE_AA)

    out = np.stack([M, R, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
spec_water_ripple_spec._spb_concept_complete = True


def spec_coral_reef(shape, seed, sm, branch_octaves=6, **kwargs):
    """spec_coral_reef.

    identity: R6-Loop creativity-mandate layer (gut-microbiome/cellular
    biology motif via Voronoi micro-mosaic) on top of R6-Loop tick 46
    CREATIVE rebuild. NEW HERO: ZOOXANTHELLAE SYMBIONT COLONIES â€”
    14-22 px patches each containing a 5-9 cell Voronoi mosaic
    (microscope cross-section aesthetic of polyp tissue). Five coral
    form-types stack underneath on a sand+rubble seafloor: (1) BRAIN-
    CORAL DOMES (12-22 px) with concentric maze-gyri ridge canyons,
    (2) STAGHORN L-system colonies (4-12 px segments, branch prob
    0.42, asymmetric fork), (3) FAN-CORAL FRONDS (10-18 px) with 5-9
    radial ribs, (4) ANEMONE crowns (5-10 px) with 8-14 tentacle rays,
    (5) ENCRUSTING SPONGE patches (6-14 px irregular blobs). Tip-
    glints, polyp-pore pits, calcareous sand flecks, bio-luminescent
    micro-sparkles. Per-feature INDEPENDENT continuous M/R/CC uniforms
    across very wide ranges (0.08-0.95). Fine features only.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 47817)
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)
    # 1) SAND + RUBBLE SEAFLOOR â€” independent per-channel FBM, wide chroma
    sand_M = _normalize(multi_scale_noise(shape, [3.0, 9.0, 22.0], [0.40, 0.32, 0.28], int(seed) + 4701))
    sand_R = _normalize(multi_scale_noise(shape, [3.5, 10.0, 24.0], [0.40, 0.32, 0.28], int(seed) + 4702))
    sand_CC = _normalize(multi_scale_noise(shape, [4.0, 11.0, 26.0], [0.40, 0.32, 0.28], int(seed) + 4703))
    M = (0.22 + (sand_M - 0.5) * 0.22).astype(np.float32)
    R = (0.64 + (sand_R - 0.5) * 0.24).astype(np.float32)
    CC = (0.32 + (sand_CC - 0.5) * 0.22).astype(np.float32)
    # rubble pebbles via mask
    for arr in (M, R, CC):
        mlo = rng.random(arr.shape) < 0.055
        mhi = rng.random(arr.shape) < 0.055
        arr[mlo] = float(rng.uniform(0.08, 0.22))
        arr[mhi] = float(rng.uniform(0.78, 0.95))
    canvas_br = np.zeros(shape, dtype=np.float32)
    if _CV2_OK:
        # 2) HERO BRAIN-CORAL DOMES with maze-gyri canyons (12-22 px)
        n_dome = int(np.clip(200 * (mn / 2048.0) ** 2, 70, 500))
        for _ in range(n_dome):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            r = int(max(6, rng.uniform(12, 22) * scale * 0.5))
            dM = float(rng.uniform(0.42, 0.92))
            dR = float(rng.uniform(0.30, 0.78))
            dCC = float(rng.uniform(0.30, 0.85))
            _cv2.circle(M, (cx, cy), r, dM, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r, dR, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r, dCC, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(canvas_br, (cx, cy), r, 1.0, -1, lineType=_cv2.LINE_AA)
            # Meander gyri canyon â€” random-walk dark ridge through the dome
            wx, wy = float(cx), float(cy)
            wang = float(rng.uniform(0, 2 * np.pi))
            gM = float(rng.uniform(0.10, 0.35))
            gR = float(rng.uniform(0.55, 0.92))
            n_walk = int(rng.integers(int(r * 1.2), int(r * 2.4)))
            for _w in range(n_walk):
                wang += float(rng.normal(0, 0.55))
                wx = wx + np.cos(wang) * 1.5
                wy = wy + np.sin(wang) * 1.5
                if (wx - cx) ** 2 + (wy - cy) ** 2 > (r * 0.95) ** 2:
                    wang += np.pi
                    wx = wx + np.cos(wang) * 1.5
                    wy = wy + np.sin(wang) * 1.5
                ix = int(np.clip(wx, 0, w - 1))
                iy = int(np.clip(wy, 0, h - 1))
                _cv2.circle(M, (ix, iy), 1, gM, -1, lineType=_cv2.LINE_AA)
                _cv2.circle(R, (ix, iy), 1, gR, -1, lineType=_cv2.LINE_AA)
            # Bright rim crown
            _cv2.circle(M, (cx, cy), r, float(rng.uniform(0.78, 0.99)), 1, lineType=_cv2.LINE_AA)

        # 3) STAGHORN BRANCHING COLONIES â€” asymmetric L-system walks
        n_seed = int(np.clip(220 * (mn / 2048.0) ** 2, 200, 310))
        for _ in range(n_seed):
            x = float(rng.uniform(0, w)); y = float(rng.uniform(0, h))
            ang = float(rng.uniform(0, np.pi * 2))
            seg_len = float(rng.uniform(4.0, 12.0) * scale * 0.5)
            thick = max(1, int(rng.uniform(1.0, 2.4) * scale))
            col_M = float(rng.uniform(0.12, 0.92))
            col_R = float(rng.uniform(0.20, 0.90))
            col_CC = float(rng.uniform(0.15, 0.92))
            steps = int(rng.integers(5, 15))
            for _step in range(steps):
                ang += float(rng.normal(0, 0.36))
                nx = float(np.clip(x + np.cos(ang) * seg_len, 0, w - 1))
                ny = float(np.clip(y + np.sin(ang) * seg_len, 0, h - 1))
                _cv2.line(M, (int(x), int(y)), (int(nx), int(ny)), col_M, thick, lineType=_cv2.LINE_AA)
                _cv2.line(R, (int(x), int(y)), (int(nx), int(ny)), float(np.clip(0.65 - col_R * 0.35, 0.08, 0.95)), thick, lineType=_cv2.LINE_AA)
                _cv2.line(CC, (int(x), int(y)), (int(nx), int(ny)), col_CC, thick, lineType=_cv2.LINE_AA)
                _cv2.line(canvas_br, (int(x), int(y)), (int(nx), int(ny)), 1.0, thick, lineType=_cv2.LINE_AA)
                if rng.random() < 0.42:
                    ba = ang + float(rng.choice([-1.0, 1.0])) * float(rng.uniform(0.45, 1.20))
                    bx = float(np.clip(nx + np.cos(ba) * seg_len * 0.7, 0, w - 1))
                    by_ = float(np.clip(ny + np.sin(ba) * seg_len * 0.7, 0, h - 1))
                    _cv2.line(M, (int(nx), int(ny)), (int(bx), int(by_)), col_M * 0.88, 1, lineType=_cv2.LINE_AA)
                    _cv2.line(CC, (int(nx), int(ny)), (int(bx), int(by_)), col_CC * 0.88, 1, lineType=_cv2.LINE_AA)
                    _cv2.line(canvas_br, (int(nx), int(ny)), (int(bx), int(by_)), 1.0, 1, lineType=_cv2.LINE_AA)
                x, y = nx, ny

        # 4) NEW FAN-CORAL FRONDS â€” arc fan with 5-9 radial ribs (10-18 px)
        n_fan = int(np.clip(240 * (mn / 2048.0) ** 2, 80, 560))
        for _ in range(n_fan):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            r = max(4, int(rng.uniform(10, 18) * scale * 0.5))
            base_ang = float(rng.uniform(0, 2 * np.pi))
            spread = float(rng.uniform(1.2, 2.4))  # fan arc width radians
            n_rib = int(rng.integers(5, 10))
            fM = float(rng.uniform(0.35, 0.90))
            fR = float(rng.uniform(0.18, 0.78))
            fCC = float(rng.uniform(0.45, 0.95))
            for i in range(n_rib):
                ang = base_ang - spread * 0.5 + spread * (i / max(1, n_rib - 1))
                x2 = int(np.clip(cx + np.cos(ang) * r, 0, w - 1))
                y2 = int(np.clip(cy + np.sin(ang) * r, 0, h - 1))
                _cv2.line(M, (cx, cy), (x2, y2), fM + float(rng.uniform(-0.08, 0.08)), 1, lineType=_cv2.LINE_AA)
                _cv2.line(R, (cx, cy), (x2, y2), fR + float(rng.uniform(-0.08, 0.08)), 1, lineType=_cv2.LINE_AA)
                _cv2.line(CC, (cx, cy), (x2, y2), fCC + float(rng.uniform(-0.08, 0.08)), 1, lineType=_cv2.LINE_AA)
            # Iridescent tip ring
            _cv2.ellipse(M, (cx, cy), (r, max(1, r // 2)), np.degrees(base_ang), -np.degrees(spread*0.5), np.degrees(spread*0.5),
                         float(rng.uniform(0.65, 0.97)), 1, lineType=_cv2.LINE_AA)

        # 5) ANEMONE CROWNS (5-10 px) â€” tapered tentacle rays
        n_anem = int(np.clip(260 * (mn / 2048.0) ** 2, 100, 600))
        for _ in range(n_anem):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            r = max(3, int(rng.uniform(5, 10) * scale * 0.5))
            aM = float(rng.uniform(0.50, 0.96))
            aR = float(rng.uniform(0.20, 0.65))
            aCC = float(rng.uniform(0.40, 0.92))
            n_pet = int(rng.integers(8, 15))
            for i in range(n_pet):
                ang = (i / n_pet) * 2 * np.pi + float(rng.uniform(-0.20, 0.20))
                rr = r + int(rng.uniform(-1, 2))
                x1 = int(cx + np.cos(ang) * rr); y1 = int(cy + np.sin(ang) * rr)
                _cv2.line(M, (cx, cy), (x1, y1), aM, 1, lineType=_cv2.LINE_AA)
                _cv2.line(R, (cx, cy), (x1, y1), aR, 1, lineType=_cv2.LINE_AA)
                _cv2.line(CC, (cx, cy), (x1, y1), aCC, 1, lineType=_cv2.LINE_AA)
            # Mouth-disc center
            _cv2.circle(M, (cx, cy), 1, float(rng.uniform(0.06, 0.18)), -1, lineType=_cv2.LINE_AA)

        # 6) ENCRUSTING SPONGE patches (6-14 px irregular blobs)
        n_spg = int(np.clip(280 * (mn / 2048.0) ** 2, 100, 650))
        for _ in range(n_spg):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            # build a 3-point irregular polygon
            pts = []
            n_v = int(rng.integers(5, 9))
            r = float(rng.uniform(6, 14) * scale * 0.5)
            for k in range(n_v):
                a = 2 * np.pi * k / n_v + float(rng.uniform(-0.3, 0.3))
                rk = r * float(rng.uniform(0.55, 1.0))
                pts.append([int(cx + np.cos(a) * rk), int(cy + np.sin(a) * rk)])
            poly = np.array([pts], dtype=np.int32)
            sM = float(rng.uniform(0.20, 0.80))
            sR = float(rng.uniform(0.55, 0.96))  # matte sponge
            sCC = float(rng.uniform(0.10, 0.40))
            _cv2.fillPoly(M, poly, sM, lineType=_cv2.LINE_AA)
            _cv2.fillPoly(R, poly, sR, lineType=_cv2.LINE_AA)
            _cv2.fillPoly(CC, poly, sCC, lineType=_cv2.LINE_AA)

        # 7) POLYP PORE DOTS on branches/domes â€” dark holes (1-2 px)
        n_pore = max(5200, int(h * w / 380))
        for _ in range(n_pore):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            if canvas_br[cy, cx] < 0.5:
                continue
            r = max(1, int(rng.uniform(1.0, 2.0) * scale))
            _cv2.circle(M, (cx, cy), r, float(rng.uniform(0.04, 0.22)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r, float(rng.uniform(0.68, 0.96)), -1, lineType=_cv2.LINE_AA)
        # 8) BIO-LUMINESCENT MICRO-SPARKLES (1-2 px) â€” anywhere
        n_glow = max(3000, int(h * w / 580))
        for _ in range(n_glow):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            r = max(1, int(rng.uniform(1.0, 2.0) * scale))
            _cv2.circle(M, (cx, cy), r, float(rng.uniform(0.75, 0.99)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r, float(rng.uniform(0.72, 0.98)), -1, lineType=_cv2.LINE_AA)
    # 9) Inter-colony calcareous sand-grain flecks
    n_fl = max(4500, int(h * w / 140))
    fy = rng.integers(0, h, n_fl); fx = rng.integers(0, w, n_fl)
    M[fy, fx] = np.maximum(M[fy, fx], rng.uniform(0.12, 0.62, n_fl).astype(np.float32))
    R[fy, fx] = np.minimum(R[fy, fx], rng.uniform(0.30, 0.85, n_fl).astype(np.float32))

    # 10) NEW HERO (R6-Loop creativity mandate) â€” ZOOXANTHELLAE SYMBIONT
    # COLONIES. Voronoi micro-mosaic patches (gut-microbiome aesthetic):
    # 14-22 px patches each tiled with 5-9 small cells whose boundaries
    # are linked at a single shared centroid (cheap polygon Voronoi). Each
    # CELL has INDEPENDENT M/R/CC across the wide 0.08-0.95 range â€” reads
    # as living symbiont algae in coral polyp tissue.
    if _CV2_OK:
        n_micro = int(np.clip(30 * (mn / 2048.0) ** 2, 12, 80))
        for _ in range(n_micro):
            pcx = float(rng.uniform(0.06, 0.94) * w)
            pcy = float(rng.uniform(0.06, 0.94) * h)
            patch_r = float(rng.uniform(14.0, 22.0)) * scale
            n_cells = int(rng.integers(5, 8))
            # Generate cell centers inside the patch (random within disc)
            cells = []
            for _c in range(n_cells):
                ca = float(rng.uniform(0, 2 * np.pi))
                cd = float(rng.uniform(0.0, 0.75)) * patch_r
                cells.append((pcx + np.cos(ca) * cd, pcy + np.sin(ca) * cd))
            # For each cell: build polygon by walking ~8 directions from
            # its center until hitting the midline to the nearest other
            # cell. Cheap and avoids full Voronoi computation.
            for ci, (ccx, ccy) in enumerate(cells):
                # Per-cell INDEPENDENT M/R/CC
                cM = float(rng.uniform(0.08, 0.95))
                cR = float(rng.uniform(0.18, 0.92))
                cCC = float(rng.uniform(0.08, 0.95))
                n_dirs = 10
                poly = []
                for di in range(n_dirs):
                    ang = di * (2 * np.pi / n_dirs)
                    # Max radius limited by patch radius and nearest-neighbor midpoint
                    rmax = patch_r
                    for cj, (ocx, ocy) in enumerate(cells):
                        if cj == ci: continue
                        dx = ocx - ccx; dy = ocy - ccy
                        ndist = (dx * dx + dy * dy) ** 0.5
                        if ndist < 0.5: continue
                        # Project dir onto cj-ci direction; if direction faces
                        # neighbor, clamp to half-distance
                        nx_ = dx / ndist; ny_ = dy / ndist
                        cdot = np.cos(ang) * nx_ + np.sin(ang) * ny_
                        if cdot > 0:
                            half = ndist * 0.5 / max(cdot, 0.20)
                            if half < rmax: rmax = half
                    px = int(np.clip(ccx + np.cos(ang) * rmax * 0.95, 0, w - 1))
                    py = int(np.clip(ccy + np.sin(ang) * rmax * 0.95, 0, h - 1))
                    poly.append([px, py])
                pts = np.array([poly], dtype=np.int32)
                _cv2.fillPoly(M, pts, cM, lineType=_cv2.LINE_AA)
                _cv2.fillPoly(R, pts, cR, lineType=_cv2.LINE_AA)
                _cv2.fillPoly(CC, pts, cCC, lineType=_cv2.LINE_AA)
                # 1 px cell-wall outline (dark)
                _cv2.polylines(M, pts, True, float(rng.uniform(0.06, 0.20)), 1, lineType=_cv2.LINE_AA)
                # Nucleus pinpoint (1 px bright spot)
                _cv2.circle(M, (int(ccx), int(ccy)), 1, float(rng.uniform(0.72, 0.98)), -1, lineType=_cv2.LINE_AA)
                _cv2.circle(CC, (int(ccx), int(ccy)), 1, float(rng.uniform(0.70, 0.98)), -1, lineType=_cv2.LINE_AA)

    out = np.stack([M, R, CC], axis=-1).astype(np.float32)
    return _validate_spec_output(_sm_scale(np.clip(out, 0.0, 1.0), sm).astype(np.float32), "spec_coral_reef")
spec_coral_reef._spb_concept_complete = True


def spec_snake_scales(shape, seed, sm, scale_w=20.0, scale_h=14.0, **kwargs):
    """spec_snake_scales.

    identity: R6-Loop creativity-mandate layer on top of the Round-5
    snake-belly tessellation. New HERO motif: 2-4 HYPNOTIC OUROBOROS
    SPIRALS (snake-biting-tail mythology) drawn as tightening
    Archimedean spirals 60-120 px across with a snake-head tip glint at
    the outermost coil and a tail-tip 'bite' meeting it; the spiral
    arms are scale-tessellated themselves (1 px segmented hash marks
    along the spiral). Under the spirals: the original fine teardrop
    scale tessellation (10-18 px) with hard-edged crescent shadow,
    keel hairlines, tip-crown glints, seam-pore pits. Per-feature
    INDEPENDENT continuous M/R/CC across the full 0.08-0.95 range.
    Three+ stacked feature types, full canvas coverage, fine features.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 12190)
    yy, xx = np.mgrid[0:h, 0:w].astype(np.float32)
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)

    # FINE SCALE PITCH â€” 10-14 px scales, not panel-scale
    sw_px = max(10.0, min(16.0, mn / 16.0))
    sh_px = max(7.0,  min(11.0, mn / 22.0))

    # Slight warp for organic feel
    warp = (_normalize(multi_scale_noise(shape, [1.0, 3.0, 7.0], [0.42, 0.36, 0.22], int(seed) + 1219)) - 0.5)
    row = (yy + warp * sh_px * 0.40) / sh_px
    row_i = np.floor(row).astype(np.int32)
    row_f = row - np.floor(row)
    col = (xx + (row_i % 2) * sw_px * 0.50 + warp * sw_px * 0.45) / sw_px
    col_i = np.floor(col).astype(np.int32)
    col_f = col - np.floor(col)

    # Independent per-scale hashes (continuous uniforms)
    def _scl_hash(off):
        return (np.mod(row_i * 131.0 + col_i * 197.0 + int(seed) * 17.0 + off * 53.0, 101.0) / 101.0).astype(np.float32)
    hM = _scl_hash(1); hR = _scl_hash(2); hCC = _scl_hash(3); hT = _scl_hash(4)

    # TEARDROP SHAPE â€” narrower at the top, wider at the bottom (like real snake belly scales)
    dx = (col_f - 0.5) * 2.0  # -1 to +1
    dy = (row_f - 0.30) * 2.0  # tip near top
    # Teardrop radius: a stretched ellipse with a sharper top
    width_factor = 0.50 + (1.0 - row_f) * 0.55  # narrower at top, wider at bottom
    r_d = np.sqrt((dx / np.clip(width_factor, 0.3, 1.5)) ** 2 + (dy * 1.18) ** 2)
    crown = np.clip(1.0 - r_d, 0, 1) ** 1.4

    # CRESCENT SEAM SHADOW â€” only on lower edge of each scale (where next row overlaps)
    seam = np.exp(-((r_d - 0.96) ** 2) / 0.012)
    lower_half = np.clip(row_f - 0.55, 0, 1) * 2.2
    crescent_shadow = seam * lower_half

    # KEEL RIDGE â€” vertical hairline along long axis
    keel = np.exp(-((dx + (hM - 0.5) * 0.18) ** 2) / 0.012) * crown

    # 2) BASE â€” independent FBM (snake belly substrate)
    g1 = _normalize(multi_scale_noise(shape, [3.0, 7.0, 14.0, 22.0], [0.34, 0.30, 0.22, 0.14], int(seed) + 1221))
    g2 = _normalize(multi_scale_noise(shape, [3.5, 7.5, 15.0, 24.0], [0.32, 0.28, 0.22, 0.18], int(seed) + 1222))
    g3 = _normalize(multi_scale_noise(shape, [4.0, 8.5, 16.0, 26.0], [0.30, 0.28, 0.24, 0.18], int(seed) + 1223))

    # Per-scale uniforms drive the domed body chroma â€” WIDE continuous range
    M_scl = 0.32 + hM * 0.56  # 0.32..0.88
    R_scl = 0.16 + hR * 0.50  # 0.16..0.66
    CC_scl = 0.08 + hCC * 0.42  # 0.08..0.50

    M = (M_scl * crown + 0.20 * (1.0 - crown)).astype(np.float32)
    M = np.clip(M + keel * 0.18 - crescent_shadow * 0.32 + (g1 - 0.5) * 0.10, 0.0, 1.0)
    R = (R_scl * crown + 0.66 * (1.0 - crown)).astype(np.float32)
    R = np.clip(R - keel * 0.14 + crescent_shadow * 0.32 + (g2 - 0.5) * 0.10, 0.0, 1.0)
    CC = (CC_scl * crown + 0.55 * (1.0 - crown)).astype(np.float32)
    CC = np.clip(CC - keel * 0.10 + crescent_shadow * 0.18 + (g3 - 0.5) * 0.10, 0.0, 1.0)

    if _CV2_OK:
        # 3) TIP-CROWN BRIGHT GLINTS â€” 5x density, 1-3 px specular points
        n_tip = int(np.clip(4500 * (mn / 2048.0) ** 2, 1600, 12000))
        for _ in range(n_tip):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            r_t = max(1, int(rng.uniform(1.0, 3.0) * scale))
            _cv2.circle(M, (cx, cy), r_t, float(rng.uniform(0.74, 0.98)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r_t, float(rng.uniform(0.06, 0.24)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r_t, float(rng.uniform(0.04, 0.20)), -1, lineType=_cv2.LINE_AA)

        # 4) KEEL HAIRLINES â€” short vertical 6-12 px on every scale
        n_kl = int(np.clip(3000 * (mn / 2048.0) ** 2, 1100, 8000))
        for _ in range(n_kl):
            cx = float(rng.uniform(2, w - 2)); cy = float(rng.uniform(2, h - 2))
            L = float(rng.uniform(6.0, 12.0)) * scale
            A = float(rng.uniform(np.pi * 0.42, np.pi * 0.58))  # near-vertical
            x0 = int(cx - np.cos(A) * L * 0.5); y0 = int(cy - np.sin(A) * L * 0.5)
            x1 = int(cx + np.cos(A) * L * 0.5); y1 = int(cy + np.sin(A) * L * 0.5)
            _cv2.line(M, (x0, y0), (x1, y1), float(rng.uniform(0.62, 0.92)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(R, (x0, y0), (x1, y1), float(rng.uniform(0.10, 0.30)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (x0, y0), (x1, y1), float(rng.uniform(0.06, 0.24)), 1, lineType=_cv2.LINE_AA)

        # 5) SEAM-PORE DARK PITS â€” 1-3 px between scales
        n_dk = int(np.clip(2400 * (mn / 2048.0) ** 2, 800, 6500))
        for _ in range(n_dk):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            r_p = max(1, int(rng.uniform(1.0, 2.2) * scale))
            _cv2.circle(M, (cx, cy), r_p, float(rng.uniform(0.06, 0.22)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r_p, float(rng.uniform(0.62, 0.90)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r_p, float(rng.uniform(0.45, 0.78)), -1, lineType=_cv2.LINE_AA)

    # 6) WAXY SHEEN FLECKS
    n_fl = int(np.clip(3000 * (mn / 2048.0) ** 2, 1000, 8000))
    fy = rng.integers(0, h, n_fl); fx = rng.integers(0, w, n_fl)
    M[fy, fx] = np.maximum(M[fy, fx], rng.uniform(0.70, 0.96, n_fl).astype(np.float32))
    R[fy, fx] = np.minimum(R[fy, fx], rng.uniform(0.08, 0.26, n_fl).astype(np.float32))
    CC[fy, fx] = np.minimum(CC[fy, fx], rng.uniform(0.04, 0.22, n_fl).astype(np.float32))

    # 7) NEW HERO â€” OUROBOROS HYPNOTIC SPIRALS (R6-Loop creativity mandate:
    # mythology motif via Archimedean spiral math). 2-4 spirals per panel,
    # 60-120 px outer reach, each spiral is 1-2 px thick stamped along an
    # r = a + b*theta curve. Tip = bright snake-head glint, tail meets head.
    if _CV2_OK:
        # Density scales with canvas to keep tiny canvases readable
        n_spiral = int(np.clip(3 * (mn / 256.0), 2, 6))
        for _ in range(n_spiral):
            scx = float(rng.uniform(0.12, 0.88) * w)
            scy = float(rng.uniform(0.12, 0.88) * h)
            outer_r = float(rng.uniform(50.0, 110.0)) * (mn / 256.0) * 0.55
            outer_r = min(outer_r, min(w, h) * 0.32)
            n_turns = float(rng.uniform(2.5, 4.0))
            theta_max = n_turns * 2.0 * np.pi
            a_par = 1.5
            b_par = (outer_r - a_par) / max(theta_max, 0.1)
            # Per-spiral independent M/R/CC
            spM_base = float(rng.uniform(0.20, 0.95))
            spR_base = float(rng.uniform(0.08, 0.90))
            spCC_base = float(rng.uniform(0.10, 0.95))
            # Step theta finely so the line stamps overlap
            steps = max(80, int(theta_max * 18))
            prev_pt = None
            for si in range(steps):
                th = (si / steps) * theta_max
                rr = a_par + b_par * th
                px = int(np.clip(scx + np.cos(th) * rr, 0, w - 1))
                py = int(np.clip(scy + np.sin(th) * rr, 0, h - 1))
                if prev_pt is not None:
                    # Per-segment slight chroma jitter (INDEPENDENT continuous)
                    segM = float(np.clip(spM_base + rng.uniform(-0.10, 0.10), 0.08, 0.98))
                    segR = float(np.clip(spR_base + rng.uniform(-0.10, 0.10), 0.05, 0.95))
                    segCC = float(np.clip(spCC_base + rng.uniform(-0.10, 0.10), 0.05, 0.98))
                    _cv2.line(M, prev_pt, (px, py), segM, 1, lineType=_cv2.LINE_AA)
                    _cv2.line(R, prev_pt, (px, py), segR, 1, lineType=_cv2.LINE_AA)
                    _cv2.line(CC, prev_pt, (px, py), segCC, 1, lineType=_cv2.LINE_AA)
                # Scale-tessellated hash marks along spiral (every 4 steps, perpendicular tick)
                if si % 4 == 0 and si > 0:
                    perp = th + np.pi * 0.5
                    hx0 = int(np.clip(px + np.cos(perp) * 1.8, 0, w - 1))
                    hy0 = int(np.clip(py + np.sin(perp) * 1.8, 0, h - 1))
                    hx1 = int(np.clip(px - np.cos(perp) * 1.8, 0, w - 1))
                    hy1 = int(np.clip(py - np.sin(perp) * 1.8, 0, h - 1))
                    _cv2.line(M, (hx0, hy0), (hx1, hy1), float(rng.uniform(0.55, 0.95)), 1, lineType=_cv2.LINE_AA)
                    _cv2.line(CC, (hx0, hy0), (hx1, hy1), float(rng.uniform(0.08, 0.92)), 1, lineType=_cv2.LINE_AA)
                prev_pt = (px, py)
            # Snake-head bright glint at outer tip
            head_x = int(np.clip(scx + np.cos(theta_max) * outer_r, 0, w - 1))
            head_y = int(np.clip(scy + np.sin(theta_max) * outer_r, 0, h - 1))
            _cv2.circle(M, (head_x, head_y), 3, float(rng.uniform(0.88, 0.99)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (head_x, head_y), 3, float(rng.uniform(0.04, 0.18)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (head_x, head_y), 3, float(rng.uniform(0.85, 0.98)), -1, lineType=_cv2.LINE_AA)
            # Two snake-eye dark dots flanking the head
            for eye_sign in (-1, 1):
                ex = int(np.clip(head_x + eye_sign * 1, 0, w - 1))
                ey = int(np.clip(head_y - 1, 0, h - 1))
                _cv2.circle(M, (ex, ey), 1, float(rng.uniform(0.04, 0.18)), -1, lineType=_cv2.LINE_AA)
            # Tail meets head: tail-tip dark point at the spiral center
            _cv2.circle(M, (int(scx), int(scy)), 1, float(rng.uniform(0.04, 0.18)), -1, lineType=_cv2.LINE_AA)

    out = np.stack([M, R, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
spec_snake_scales._spb_concept_complete = True


def spec_fish_scales(shape, seed, sm, scale_r=16.0, **kwargs):
    """Iridescent fish-scale tessellation with arc edges and body-grad hue.

    identity: A tessellated curtain of fish scales â€” each scale a half-disc with a
    bright crescent edge, a darker base shadow, and per-row iridescent hue banding
    that mimics the chromatophore gradient along a real fish flank, with edge glints.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + (hash('fish_scales') % 10000))
    yy, xx = np.mgrid[0:h, 0:w].astype(np.float32)

    spacing_x = scale_r * 1.75
    spacing_y = scale_r * 1.02
    row = yy / spacing_y
    row_i = np.floor(row).astype(np.int32)
    row_f = row - np.floor(row)
    col = (xx + (row_i % 2) * spacing_x * 0.5) / spacing_x
    col_i = np.floor(col).astype(np.int32)
    col_f = col - np.floor(col)
    hashv = np.mod(row_i * 89.0 + col_i * 211.0 + seed * 0.11, 103.0) / 103.0
    dx = (col_f - 0.5) * spacing_x
    dy = (row_f - 0.84) * spacing_y
    r = np.sqrt(dx * dx + dy * dy) / (scale_r * (0.84 + hashv * 0.18))

    arc_edge = np.exp(-((r - 0.92) ** 2) / 0.010) * (row_f < 0.98)
    inner_ring = np.exp(-((r - 0.60) ** 2) / 0.040)
    body_shadow = np.exp(-((r - 0.40) ** 2) / 0.055)

    # Per-row iridescent hue band (slow gradient down the body)
    yy_r = (np.arange(h, dtype=np.float32) / max(h, 1))[:, None]
    body_grad = 0.5 + 0.5 * np.sin(yy_r * np.pi * 3.0 + rng.uniform(0, np.pi * 2))

    # Channels
    R = (0.50 + arc_edge * 0.42 + inner_ring * 0.10 - body_shadow * 0.10 + (body_grad - 0.5) * 0.14).astype(np.float32)
    G = (0.45 - arc_edge * 0.30 + body_shadow * 0.18 + (1.0 - body_grad) * 0.16).astype(np.float32)
    CC = (0.38 - arc_edge * 0.28 + body_shadow * 0.15 + (body_grad - 0.5) * 0.12).astype(np.float32)

    # Per-scale randomized R seed (each scale picks an independent reflectivity)
    scale_hash_R = hashv * 0.45 + 0.35
    scale_hash_G = (1.0 - hashv) * 0.30 + 0.15
    in_scale = (r < 0.94).astype(np.float32)
    R = R + (scale_hash_R - 0.5) * in_scale * 0.20
    G = G + (scale_hash_G - 0.3) * in_scale * 0.16

    # Iridescent edge glint pinpoints
    if _CV2_OK:
        edge_mask = (r > 0.85) & (r < 0.97)
        ey, ex = np.where(edge_mask)
        if ey.size > 0:
            n_glint = min(1500, ey.size // 22)
            pick = rng.choice(ey.size, size=n_glint, replace=False)
            for i in pick:
                py, px = int(ey[i]), int(ex[i])
                R[py, px] = float(rng.uniform(0.78, 0.98))
                G[py, px] = float(rng.uniform(0.04, 0.22))
                CC[py, px] = float(rng.uniform(0.04, 0.24))

    # Sub-scale chromatophore flecks (tiny rainbow dust)
    n_chrom = int(np.clip(h * w / 360.0, 240, 2200))
    cy_ = rng.integers(0, h, size=n_chrom)
    cx_ = rng.integers(0, w, size=n_chrom)
    R[cy_, cx_] = rng.uniform(0.45, 0.92, size=n_chrom).astype(np.float32)
    G[cy_, cx_] = rng.uniform(0.10, 0.55, size=n_chrom).astype(np.float32)
    CC[cy_, cx_] = rng.uniform(0.10, 0.55, size=n_chrom).astype(np.float32)

    out = np.stack([R, G, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)


