def spec_shot_peened(shape, seed, sm, dimple_density=0.022, dimple_radius=6.0,
                     **kwargs):
    """spec_shot_peened.

    identity: R6-Loop tick 55 SECOND-PASS â€” industrial shot-peened panel.
    Layer 1 (existing): ROSETTE OVERLAP CLUSTERS, primary dimples with
    dark bowls + bright rim rings + sun-side specular glints, secondary
    peens, deep double-strike voids, burnished-fleck sparkle field.
    HERO (tick 55): SUNBURST RICOCHET STREAKS â€” 18-46 asymmetric
    high-velocity ricochet rays radiating from cluster sites with 5-9
    short 12-22 px directional streaks and bright head sparks.

    NEW HERO (tick 78): CELLULAR-AUTOMATA STRESS-CRACK DENDRITES â€” fine
    branching 1-px crack networks emanating from concentrated impact
    sites. Iterates a Conway-style dilation rule: each crack grows in
    3-5 px segments with random ~45 deg branching at every node, like a
    work-hardened plate finally failing under accumulated peening
    fatigue. Independent per-segment M/R/CC, dark M (crack=void), high
    R (matte interior), modulated CC (oxide chroma). Adds an organic
    "kintsugi failure" overlay never before in shot_peened.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 55621)
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)

    # 1) BASE â€” independent FBM (work-hardened cold-blasted metal)
    g1 = _normalize(multi_scale_noise(shape, [2.0, 5.5, 12.0, 22.0], [0.36, 0.30, 0.22, 0.12], int(seed) + 5511))
    g2 = _normalize(multi_scale_noise(shape, [2.5, 6.5, 13.5, 25.0], [0.34, 0.30, 0.22, 0.14], int(seed) + 5513))
    g3 = _normalize(multi_scale_noise(shape, [3.0, 7.5, 15.0, 27.0], [0.32, 0.28, 0.22, 0.18], int(seed) + 5515))
    M  = (0.52 + (g1 - 0.5) * 0.24).astype(np.float32)
    R  = (0.62 + (g2 - 0.5) * 0.22).astype(np.float32)
    CC = (0.40 + (g3 - 0.5) * 0.24).astype(np.float32)

    if _CV2_OK:
        sun_dir = float(rng.uniform(0, 2 * np.pi))
        sx_off = np.cos(sun_dir); sy_off = np.sin(sun_dir)
        # 1B) HERO ROSETTE OVERLAP CLUSTERS â€” flower-like dimple groupings
        n_rose = int(np.clip(420 * (mn / 2048.0) ** 2, 140, 1100))
        for _ in range(n_rose):
            ccx = int(rng.uniform(8, w - 8)); ccy = int(rng.uniform(8, h - 8))
            cluster_r = max(4, int(rng.uniform(8.0, 13.0) * scale * 0.5))
            n_petal = int(rng.integers(6, 10))
            base_ang = float(rng.uniform(0, 2 * np.pi))
            # Center burst node â€” bright work-hardened core
            _cv2.circle(M, (ccx, ccy), max(1, int(cluster_r * 0.35)),
                        float(rng.uniform(0.85, 0.99)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (ccx, ccy), max(1, int(cluster_r * 0.35)),
                        float(rng.uniform(0.05, 0.18)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (ccx, ccy), max(1, int(cluster_r * 0.35)),
                        float(rng.uniform(0.05, 0.22)), -1, lineType=_cv2.LINE_AA)
            for k in range(n_petal):
                ang = base_ang + (k / n_petal) * 2 * np.pi + float(rng.uniform(-0.18, 0.18))
                px = int(np.clip(ccx + np.cos(ang) * cluster_r, 1, w - 2))
                py = int(np.clip(ccy + np.sin(ang) * cluster_r, 1, h - 2))
                pr = max(1, int(rng.uniform(4.0, 9.0) * scale * 0.5))
                # Petal dimple bowl
                _cv2.circle(M, (px, py), pr, float(rng.uniform(0.22, 0.48)), -1, lineType=_cv2.LINE_AA)
                _cv2.circle(R, (px, py), pr, float(rng.uniform(0.65, 0.92)), -1, lineType=_cv2.LINE_AA)
                _cv2.circle(CC, (px, py), pr, float(rng.uniform(0.45, 0.78)), -1, lineType=_cv2.LINE_AA)
                # Bright petal rim
                _cv2.circle(M, (px, py), pr, float(rng.uniform(0.78, 0.99)), 1, lineType=_cv2.LINE_AA)
                _cv2.circle(R, (px, py), pr, float(rng.uniform(0.06, 0.24)), 1, lineType=_cv2.LINE_AA)
            # Outer rosette halo
            _cv2.circle(R, (ccx, ccy), cluster_r + 2,
                        float(rng.uniform(0.55, 0.82)), 1, lineType=_cv2.LINE_AA)

        # 2) PRIMARY DIMPLES â€” dense overlapping golf-ball wells
        # (tick 78 iter: density trimmed 6000->3500 to escape static-noise look)
        n_prim = int(np.clip(3500 * (mn / 2048.0) ** 2, 1100, 9000))
        for _ in range(n_prim):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            r_d = max(2, int(rng.uniform(6.0, 14.0) * scale * 0.5))
            # Inner well â€” darker M (shadow), high R (matte), mid CC
            wM = float(rng.uniform(0.22, 0.46))
            wR = float(rng.uniform(0.68, 0.92))
            wC = float(rng.uniform(0.48, 0.78))
            _cv2.circle(M, (cx, cy), r_d, wM, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r_d, wR, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r_d, wC, -1, lineType=_cv2.LINE_AA)
            # Work-hardened rim ring â€” bright burnished outline
            rmM = float(rng.uniform(0.78, 0.98))
            rmR = float(rng.uniform(0.08, 0.28))
            rmC = float(rng.uniform(0.10, 0.30))
            _cv2.circle(M, (cx, cy), r_d, rmM, 1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r_d, rmR, 1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r_d, rmC, 1, lineType=_cv2.LINE_AA)
            # Specular pin-point glint offset toward sun-side
            gx = int(np.clip(cx + sx_off * r_d * 0.55, 0, w - 1))
            gy = int(np.clip(cy + sy_off * r_d * 0.55, 0, h - 1))
            _cv2.circle(M, (gx, gy), max(1, r_d // 3),
                        float(rng.uniform(0.88, 1.0)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (gx, gy), max(1, r_d // 3),
                        float(rng.uniform(0.04, 0.18)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (gx, gy), max(1, r_d // 3),
                        float(rng.uniform(0.04, 0.20)), -1, lineType=_cv2.LINE_AA)

        # 3) SECONDARY MICRO-PEENS â€” tiny 3-6 px between primaries
        # (tick 78 iter: density trimmed 6000->3000 to reduce noise feel)
        n_sec = int(np.clip(3000 * (mn / 2048.0) ** 2, 1100, 8000))
        for _ in range(n_sec):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            r_d = max(1, int(rng.uniform(3.0, 6.0) * scale * 0.5))
            _cv2.circle(M, (cx, cy), r_d, float(rng.uniform(0.32, 0.58)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r_d, float(rng.uniform(0.60, 0.85)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r_d, float(rng.uniform(0.45, 0.72)), -1, lineType=_cv2.LINE_AA)

        # 4) DEEP DOUBLE-STRIKE VOIDS â€” small dark pits (2-4 px)
        n_void = int(np.clip(2000 * (mn / 2048.0) ** 2, 700, 5000))
        for _ in range(n_void):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            r_d = max(1, int(rng.uniform(2.0, 4.0) * scale * 0.5))
            _cv2.circle(M, (cx, cy), r_d, float(rng.uniform(0.08, 0.22)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r_d, float(rng.uniform(0.75, 0.96)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r_d, float(rng.uniform(0.60, 0.88)), -1, lineType=_cv2.LINE_AA)

        # 4B) NEW HERO (tick 55) â€” SUNBURST RICOCHET STREAKS
        # High-velocity directional impact rays radiating from concentrated
        # cluster sites. Sells the kinetic story.
        n_rico_site = int(np.clip(34 * (mn / 256.0), 18, 46))
        for _ in range(n_rico_site):
            scx = int(rng.uniform(0.04, 0.96) * w)
            scy = int(rng.uniform(0.04, 0.96) * h)
            n_rays = int(rng.integers(5, 10))
            base_ang = float(rng.uniform(0, 2 * np.pi))
            for k in range(n_rays):
                # asymmetric spread â€” not perfectly radial
                ray_ang = base_ang + (k - n_rays / 2.0) * float(rng.uniform(0.18, 0.55)) + float(rng.uniform(-0.12, 0.12))
                ray_len = float(rng.uniform(12.0, 22.0) * scale * 0.6)
                ex = int(np.clip(scx + np.cos(ray_ang) * ray_len, 0, w - 1))
                ey = int(np.clip(scy + np.sin(ray_ang) * ray_len, 0, h - 1))
                # bright streak â€” independent M/R/CC per ray
                sM = float(rng.uniform(0.70, 0.99))
                sR = float(rng.uniform(0.06, 0.30))
                sCC = float(rng.uniform(0.20, 0.92))
                _cv2.line(M, (scx, scy), (ex, ey), sM, 1, lineType=_cv2.LINE_AA)
                _cv2.line(R, (scx, scy), (ex, ey), sR, 1, lineType=_cv2.LINE_AA)
                _cv2.line(CC, (scx, scy), (ex, ey), sCC, 1, lineType=_cv2.LINE_AA)
                # bright 1-2 px head spark at the ray tip
                head_r = max(1, int(rng.uniform(1.0, 2.0) * scale * 0.6))
                _cv2.circle(M, (ex, ey), head_r, float(rng.uniform(0.85, 1.0)), -1, lineType=_cv2.LINE_AA)
                _cv2.circle(R, (ex, ey), head_r, float(rng.uniform(0.02, 0.16)), -1, lineType=_cv2.LINE_AA)
                _cv2.circle(CC, (ex, ey), head_r, float(rng.uniform(0.30, 0.95)), -1, lineType=_cv2.LINE_AA)

    # 4C) NEW HERO (tick 78) â€” CELLULAR-AUTOMATA STRESS-CRACK DENDRITES.
    # Walk a 1-px crack 12-30 segments long from each origin, branching
    # with ~25% probability at each node. Independent per-segment chroma.
    # Tick 78 iter: count REDUCED to keep canvas readable (not static noise).
    if _CV2_OK:
        n_crack_origin = int(np.clip(8 * (mn / 256.0), 5, 16))
        for _ in range(n_crack_origin):
            ox = float(rng.uniform(0.05, 0.95) * w)
            oy = float(rng.uniform(0.05, 0.95) * h)
            # Active "frontier" of crack tips â€” list of (x,y,angle,remaining_life)
            frontier = [(ox, oy, float(rng.uniform(0, 2 * np.pi)), int(rng.integers(14, 30)))]
            steps = 0
            while frontier and steps < 80:
                steps += 1
                new_frontier = []
                for (cx_c, cy_c, ang_c, life) in frontier:
                    if life <= 0:
                        continue
                    seg_len = float(rng.uniform(3.0, 5.5) * scale * 0.6)
                    # tiny angle jitter â€” cracks meander
                    ang_c2 = ang_c + float(rng.uniform(-0.35, 0.35))
                    nx_c = cx_c + np.cos(ang_c2) * seg_len
                    ny_c = cy_c + np.sin(ang_c2) * seg_len
                    if 0 <= nx_c < w and 0 <= ny_c < h:
                        # crack = dark void thread
                        cM = float(rng.uniform(0.08, 0.24))
                        cR = float(rng.uniform(0.70, 0.92))
                        cCC = float(rng.uniform(0.18, 0.62))  # oxide chroma variance
                        _cv2.line(M,  (int(cx_c), int(cy_c)), (int(nx_c), int(ny_c)), cM,  1, lineType=_cv2.LINE_AA)
                        _cv2.line(R,  (int(cx_c), int(cy_c)), (int(nx_c), int(ny_c)), cR,  1, lineType=_cv2.LINE_AA)
                        _cv2.line(CC, (int(cx_c), int(cy_c)), (int(nx_c), int(ny_c)), cCC, 1, lineType=_cv2.LINE_AA)
                        new_frontier.append((nx_c, ny_c, ang_c2, life - 1))
                        # branch with 22% probability
                        if rng.random() < 0.22 and life > 4:
                            branch_ang = ang_c2 + float(rng.choice([-1, 1])) * float(rng.uniform(0.55, 1.05))
                            new_frontier.append((nx_c, ny_c, branch_ang, life - 6))
                frontier = new_frontier

    # 5) BURNISHED FLECKS â€” single-pixel sparkles (tick 78: density cut
    # to avoid static-noise look â€” owner doctrine: dense detail OK but
    # must remain readable, not white-noise).
    n_fl = int(np.clip(1600 * (mn / 2048.0) ** 2, 500, 4500))
    fy = rng.integers(0, h, n_fl); fx = rng.integers(0, w, n_fl)
    M[fy, fx] = np.maximum(M[fy, fx], rng.uniform(0.72, 0.99, n_fl).astype(np.float32))
    R[fy, fx] = np.minimum(R[fy, fx], rng.uniform(0.06, 0.28, n_fl).astype(np.float32))
    CC[fy, fx] = np.minimum(CC[fy, fx], rng.uniform(0.04, 0.24, n_fl).astype(np.float32))

    out = np.stack([M, R, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
