# SPB-3 owner-grade rebuild pass: Surface Treatment + Exotic spec overlays.
# These definitions intentionally shadow the older batch-H/I renderers before the
# catalog is built, so picker/workbench paths use the rebuilt source functions.
def _spb_surface_fbm(shape, seed, freqs, weights=None, warp=0.0):
    h, w = shape
    rng = np.random.default_rng(int(seed) & 0xFFFFFFFF)
    yy, xx = np.mgrid[0:h, 0:w].astype(np.float32)
    xn = xx / max(w - 1, 1)
    yn = yy / max(h - 1, 1)
    if weights is None:
        weights = [1.0] * len(freqs)
    out = np.zeros((h, w), dtype=np.float32)
    total = float(sum(weights)) or 1.0
    for freq, weight in zip(freqs, weights):
        ph = rng.uniform(0, np.pi * 2.0, 4)
        wx = np.sin(yn * np.pi * 2.0 * (freq * 0.21) + ph[2]) * warp
        wy = np.cos(xn * np.pi * 2.0 * (freq * 0.17) + ph[3]) * warp
        layer = (
            np.sin((xn + wx) * np.pi * 2.0 * freq + ph[0]) *
            np.cos((yn + wy) * np.pi * 2.0 * (freq * rng.uniform(0.72, 1.34)) + ph[1])
        )
        layer += 0.45 * np.sin((xn * 0.73 + yn * 1.27) * np.pi * 2.0 * freq + ph[2])
        out += layer.astype(np.float32) * (float(weight) / total)
    return _normalize(out).astype(np.float32)


def _spb_random_impulse_field(shape, seed, density=0.01, blur=0.8, amp=1.0):
    h, w = shape
    rng = np.random.default_rng(int(seed) & 0xFFFFFFFF)
    mask = (rng.random((h, w), dtype=np.float32) < float(density)).astype(np.float32)
    if blur > 0:
        mask = _gauss(mask, float(blur)).astype(np.float32)
    return np.clip(mask * float(amp), 0, None).astype(np.float32)


def spec_electroplated_chrome(shape, seed, sm, cell_density=55.0, metallic_base=230,
                               metallic_range=15, **kwargs):
    """spec_electroplated_chrome â€” R6 CREATIVE rebuild â€” show-chrome with story.

    identity: Wet-cell electroplated chrome on a bumper â€” six stacked
    tiers: (1) bright chrome substrate fine grain (no macro blobs),
    (2) crystalline NODULE GRAIN 3-6 px isotropic packing, (3) brilliant
    1-2 px CRYSTAL PINPOINTS, (4) dark 1-3 px PLATING PINHOLE defects,
    (5) NEW â€” NICKEL-STRIKE FLOW LINES: faint 14-28 px gently curving
    bright streaks (5-8 segments, slight horizontal drift) showing the
    current flow during deposition, (6) NEW â€” CRYSTALLIZATION SUNBURST
    PIPS: hero motif â€” small 8-14 px starbursts (5-7 thin arms each)
    at scattered nucleation centers where chromium crystallites grew
    outward; (7) isotropic 4-12 px polish-scratch fragments; (8) dense
    single-pixel crystal halo flecks. Per-feature INDEPENDENT M/R/CC
    continuous uniforms. Differentiator: the sunburst nucleation motif
    + flow lines tell the wet-cell deposition story, not generic gloss.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 2703)
    mn = float(min(h, w))
    scale = max(mn / 256.0, 0.6)

    # Bright chrome substrate â€” fine grain, no big macro blobs
    grain = _gauss(rng.random((h, w)).astype(np.float32), sigma=max(mn / 110.0, 1.0))
    grain = _normalize(grain)

    M = (0.78 + (grain - 0.5) * 0.14).astype(np.float32)
    R_ch = (0.10 + (1.0 - grain) * 0.14).astype(np.float32)
    CC = (0.78 + (grain - 0.5) * 0.10).astype(np.float32)

    if _CV2_OK:
        # Pass A â€” crystalline nodule grain field (5x prior density, isotropic)
        n_nod = int(np.clip(3200 * scale * scale, 2200, 11000))
        for _ in range(n_nod):
            cx = int(rng.uniform(0, w))
            cy = int(rng.uniform(0, h))
            rr = int(max(1, rng.uniform(2.0, 5.5)))
            vM = float(rng.uniform(0.72, 0.99))
            vR = float(rng.uniform(0.02, 0.16))
            vCC = float(rng.uniform(0.66, 0.99))
            _cv2.circle(M, (cx, cy), rr, vM, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R_ch, (cx, cy), rr, vR, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), rr, vCC, -1, lineType=_cv2.LINE_AA)

        # Pass B â€” brilliant 1-2 px crystal pinpoints
        n_xt = int(np.clip(2400 * scale * scale, 1600, 7000))
        for _ in range(n_xt):
            cx = int(rng.uniform(0, w))
            cy = int(rng.uniform(0, h))
            rr = int(max(1, rng.uniform(1.0, 2.4)))
            vM = float(rng.uniform(0.92, 0.99))
            vR = float(rng.uniform(0.01, 0.08))
            vCC = float(rng.uniform(0.85, 0.99))
            _cv2.circle(M, (cx, cy), rr, vM, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R_ch, (cx, cy), rr, vR, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), rr, vCC, -1, lineType=_cv2.LINE_AA)

        # Pass C â€” dark plating pinhole defects
        n_pin = int(np.clip(1500 * scale * scale, 900, 4500))
        for _ in range(n_pin):
            cx = int(rng.uniform(0, w))
            cy = int(rng.uniform(0, h))
            rr = int(max(1, rng.uniform(1.0, 2.8)))
            vM = float(rng.uniform(0.10, 0.34))
            vR = float(rng.uniform(0.58, 0.92))
            vCC = float(rng.uniform(0.18, 0.48))
            _cv2.circle(M, (cx, cy), rr, vM, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R_ch, (cx, cy), rr, vR, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), rr, vCC, -1, lineType=_cv2.LINE_AA)

        # Pass D â€” short isotropic polish-scratch fragments
        n_sc = int(np.clip(600 * scale * scale, 200, 1800))
        for _ in range(n_sc):
            cx = float(rng.uniform(2, w - 2))
            cy = float(rng.uniform(2, h - 2))
            length = float(rng.uniform(4.0, 12.0) * scale)
            ang = float(rng.uniform(0, 2 * np.pi))
            x_a = int(cx - np.cos(ang) * length * 0.5)
            y_a = int(cy - np.sin(ang) * length * 0.5)
            x_b = int(cx + np.cos(ang) * length * 0.5)
            y_b = int(cy + np.sin(ang) * length * 0.5)
            vM = float(rng.uniform(0.55, 0.92))
            vR = float(rng.uniform(0.15, 0.42))
            vCC = float(rng.uniform(0.30, 0.65))
            _cv2.line(M, (x_a, y_a), (x_b, y_b), vM, 1, lineType=_cv2.LINE_AA)
            _cv2.line(R_ch, (x_a, y_a), (x_b, y_b), vR, 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (x_a, y_a), (x_b, y_b), vCC, 1, lineType=_cv2.LINE_AA)

        # Pass E â€” NICKEL-STRIKE FLOW LINES (CREATIVE TIER)
        n_flow = int(np.clip(180 * scale * scale, 60, 480))
        flow_dir = float(rng.uniform(-0.35, 0.35))  # near-horizontal drift
        for _ in range(n_flow):
            x_cur = float(rng.uniform(0, w)); y_cur = float(rng.uniform(0, h))
            ang = flow_dir + float(rng.normal(0, 0.18))
            n_seg = int(rng.integers(5, 9))
            for _s in range(n_seg):
                L = float(rng.uniform(3.0, 5.0) * scale)
                ang += float(rng.normal(0, 0.10))
                x_n = x_cur + np.cos(ang) * L; y_n = y_cur + np.sin(ang) * L
                if not (0 <= x_n < w and 0 <= y_n < h): break
                _cv2.line(M, (int(x_cur), int(y_cur)), (int(x_n), int(y_n)),
                          float(rng.uniform(0.80, 0.98)), 1, lineType=_cv2.LINE_AA)
                _cv2.line(R_ch, (int(x_cur), int(y_cur)), (int(x_n), int(y_n)),
                          float(rng.uniform(0.04, 0.18)), 1, lineType=_cv2.LINE_AA)
                _cv2.line(CC, (int(x_cur), int(y_cur)), (int(x_n), int(y_n)),
                          float(rng.uniform(0.78, 0.98)), 1, lineType=_cv2.LINE_AA)
                x_cur = x_n; y_cur = y_n

        # Pass F â€” CRYSTALLIZATION SUNBURST PIPS (HERO TIER)
        n_sun = int(np.clip(220 * scale * scale, 70, 580))
        for _ in range(n_sun):
            ox = float(rng.uniform(4, w - 4)); oy = float(rng.uniform(4, h - 4))
            n_arm = int(rng.integers(5, 8))
            ang0 = float(rng.uniform(0, 2 * np.pi))
            for ai in range(n_arm):
                a = ang0 + (2 * np.pi / n_arm) * ai + float(rng.normal(0, 0.08))
                L = float(rng.uniform(4.0, 7.0) * scale)
                x_e = int(np.clip(ox + np.cos(a) * L, 0, w - 1))
                y_e = int(np.clip(oy + np.sin(a) * L, 0, h - 1))
                _cv2.line(M, (int(ox), int(oy)), (x_e, y_e),
                          float(rng.uniform(0.86, 0.99)), 1, lineType=_cv2.LINE_AA)
                _cv2.line(R_ch, (int(ox), int(oy)), (x_e, y_e),
                          float(rng.uniform(0.02, 0.10)), 1, lineType=_cv2.LINE_AA)
                _cv2.line(CC, (int(ox), int(oy)), (x_e, y_e),
                          float(rng.uniform(0.82, 0.99)), 1, lineType=_cv2.LINE_AA)
            # bright core pip
            cr = max(1, int(rng.uniform(1.0, 2.0)))
            _cv2.circle(M, (int(ox), int(oy)), cr, float(rng.uniform(0.92, 0.99)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R_ch, (int(ox), int(oy)), cr, float(rng.uniform(0.02, 0.08)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (int(ox), int(oy)), cr, float(rng.uniform(0.90, 0.99)), -1, lineType=_cv2.LINE_AA)

    # Stray single-pixel crystal halo flecks (5x prior)
    n_fl = int(np.clip(mn * mn / 75.0, 2000, 12000))
    sy = rng.integers(0, h, size=n_fl)
    sx = rng.integers(0, w, size=n_fl)
    M[sy, sx] = rng.uniform(0.62, 0.99, size=n_fl).astype(np.float32)
    R_ch[sy, sx] = rng.uniform(0.02, 0.24, size=n_fl).astype(np.float32)
    CC[sy, sx] = rng.uniform(0.55, 0.99, size=n_fl).astype(np.float32)

    out = np.stack([M, R_ch, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
spec_electroplated_chrome._spb_concept_complete = True


def spec_anodized_texture(shape, seed, sm, pore_density=105.0, metallic_base=170, **kwargs):
    """spec_anodized_texture â€” R6 CREATIVE rebuild.

    identity: A rainbow-anodized aluminum panel with the spectral oil-slick
    hue cycle owners actually want from anodize. HERO: 4 large irregular
    DYE-FIELD REGIONS (low-freq voronoi-style basins) each pulled toward a
    distinct anodize hue tier â€” gold, peacock-blue, deep-purple, and rust-
    bronze â€” modulating R+CC in opposite directions per tier so the panel
    reads as multi-zone, not flat. Underneath: hex nano-pore wells (2-4 px,
    2.4x density), satin sweep hairlines (12-22 px), bright oxide-rim
    halos (1-3 px), and a NEW concentric ring-burn motif â€” sparse 6-10 px
    bullseye marks where dye crystallized in rings. Per-feature INDEPENDENT
    continuous M/R/CC uniforms. No palette tiers.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 1213)
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)
    g1 = _normalize(multi_scale_noise(shape, [3.0, 7.0, 14.0, 22.0], [0.36, 0.30, 0.22, 0.14], seed + 121))
    g2 = _normalize(multi_scale_noise(shape, [4.0, 8.5, 17.0, 26.0], [0.32, 0.28, 0.22, 0.18], seed + 122))
    g3 = _normalize(multi_scale_noise(shape, [3.5, 7.5, 15.0, 23.0], [0.34, 0.30, 0.22, 0.14], seed + 123))
    yy = np.arange(h, dtype=np.float32)[:, None]
    xx = np.arange(w, dtype=np.float32)[None, :]
    sheen = (np.sin(yy * (2.0 * np.pi / 14.0) + seed * 0.011) * 0.5 + 0.5).astype(np.float32)
    # Hex-cell modulation from twin sine combo (12 px hex pitch)
    hex_pitch = max(10.0, 12.0 * scale)
    hex_mod = ((np.sin(xx * (2.0 * np.pi / hex_pitch)) + np.sin((xx * 0.5 + yy * 0.866) * (2.0 * np.pi / hex_pitch))) * 0.25 + 0.5).astype(np.float32)
    M = (0.62 + (g1 - 0.5) * 0.18 + (sheen - 0.5) * 0.10).astype(np.float32)
    R = (0.48 + (g2 - 0.5) * 0.24 + (hex_mod - 0.5) * 0.10).astype(np.float32)
    CC = (0.34 + (g3 - 0.5) * 0.22).astype(np.float32)

    # HERO: RAINBOW DYE-FIELD REGIONS â€” 4 low-freq noise fields define hue tier zones
    df_a = _normalize(multi_scale_noise(shape, [40.0, 90.0], [0.6, 0.4], int(seed) + 1271))
    df_b = _normalize(multi_scale_noise(shape, [44.0, 100.0], [0.6, 0.4], int(seed) + 1272))
    df_c = _normalize(multi_scale_noise(shape, [48.0, 110.0], [0.6, 0.4], int(seed) + 1273))
    df_d = _normalize(multi_scale_noise(shape, [52.0, 120.0], [0.6, 0.4], int(seed) + 1274))
    # Hue tiers: gold (high M, low R, low CC), peacock-blue (mid M, mid R, high CC),
    # purple (mid M, high R, mid CC), bronze (high M, mid R, low CC)
    gold_w   = np.clip(df_a - 0.55, 0.0, 1.0) * 2.2
    blue_w   = np.clip(df_b - 0.55, 0.0, 1.0) * 2.2
    purple_w = np.clip(df_c - 0.55, 0.0, 1.0) * 2.2
    bronze_w = np.clip(df_d - 0.55, 0.0, 1.0) * 2.2
    M  = M  + gold_w * 0.16 + bronze_w * 0.10 - blue_w * 0.06 - purple_w * 0.04
    R  = R  - gold_w * 0.10 + blue_w * 0.04 + purple_w * 0.14 + bronze_w * 0.06
    CC = CC - gold_w * 0.10 + blue_w * 0.22 + purple_w * 0.12 - bronze_w * 0.08
    for arr in (M, R, CC):
        mlo = rng.random(arr.shape) < 0.055
        mhi = rng.random(arr.shape) < 0.055
        arr[mlo] = float(rng.uniform(0.05, 0.18))
        arr[mhi] = float(rng.uniform(0.82, 0.97))
    if _CV2_OK:
        # 2) DENSE NANO-PORE WELLS (2-4 px) â€” 2.4x density (QC tick boost)
        n_pore = int(np.clip(3000 * (mn / 2048.0) ** 2, 1100, 7200))
        for _ in range(n_pore):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            r = max(1, int(rng.uniform(2.0, 4.0) * scale * 0.5))
            pM = float(rng.uniform(0.30, 0.60)); pR = float(rng.uniform(0.55, 0.92)); pCC = float(rng.uniform(0.30, 0.70))
            _cv2.circle(M, (cx, cy), r, pM, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r, pR, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r, pCC, -1, lineType=_cv2.LINE_AA)
        # 3) DYE BLOOM PUDDLES (5-12 px) â€” gold / blue / black anodize tiers
        n_bloom = int(np.clip(700 * (mn / 2048.0) ** 2, 250, 1820))
        for _ in range(n_bloom):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            r = max(2, int(rng.uniform(5.0, 12.0) * scale * 0.5))
            tier = int(rng.integers(0, 3))  # 0=gold (bright), 1=blue (mid), 2=black (dark)
            if tier == 0:
                dM = float(rng.uniform(0.72, 0.96)); dR = float(rng.uniform(0.22, 0.45)); dCC = float(rng.uniform(0.10, 0.32))
            elif tier == 1:
                dM = float(rng.uniform(0.45, 0.68)); dR = float(rng.uniform(0.35, 0.60)); dCC = float(rng.uniform(0.30, 0.55))
            else:
                dM = float(rng.uniform(0.12, 0.32)); dR = float(rng.uniform(0.55, 0.85)); dCC = float(rng.uniform(0.40, 0.75))
            _cv2.circle(M, (cx, cy), r, dM, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r, dR, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r, dCC, -1, lineType=_cv2.LINE_AA)
        # 4) SATIN SWEEP HAIRLINES (12-22 px) near-horizontal
        n_sat = int(np.clip(1120 * (mn / 2048.0) ** 2, 400, 2660))
        for _ in range(n_sat):
            cx = float(rng.uniform(4, w - 4)); cy = float(rng.uniform(4, h - 4))
            length = float(rng.uniform(12.0, 22.0) * scale)
            ang = float(rng.uniform(-0.30, 0.30))
            x0 = int(cx - np.cos(ang) * length * 0.5); y0 = int(cy - np.sin(ang) * length * 0.5)
            x1 = int(cx + np.cos(ang) * length * 0.5); y1 = int(cy + np.sin(ang) * length * 0.5)
            hM = float(rng.uniform(0.55, 0.94)); hR = float(rng.uniform(0.16, 0.42)); hCC = float(rng.uniform(0.08, 0.36))
            _cv2.line(M, (x0, y0), (x1, y1), hM, 1, lineType=_cv2.LINE_AA)
            _cv2.line(R, (x0, y0), (x1, y1), hR, 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (x0, y0), (x1, y1), hCC, 1, lineType=_cv2.LINE_AA)
        # 5) BRIGHT OXIDE RIM HIGHLIGHTS (1-3 px) â€” pore halos
        n_hi = int(np.clip(1260 * (mn / 2048.0) ** 2, 450, 3080))
        for _ in range(n_hi):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            r = max(1, int(rng.uniform(1.0, 2.5) * scale))
            sM = float(rng.uniform(0.65, 0.97)); sR = float(rng.uniform(0.06, 0.28)); sCC = float(rng.uniform(0.04, 0.22))
            _cv2.circle(M, (cx, cy), r, sM, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r, sR, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r, sCC, -1, lineType=_cv2.LINE_AA)
        # 5b) CONCENTRIC RING-BURN BULLSEYES â€” sparse 6-10 px crystallized dye rings
        n_ring = int(np.clip(220 * (mn / 2048.0) ** 2, 80, 600))
        for _ in range(n_ring):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            r_outer = max(3, int(rng.uniform(6.0, 10.0) * scale * 0.6))
            r_mid = max(2, int(r_outer * 0.66))
            r_in = max(1, int(r_outer * 0.33))
            rM = float(rng.uniform(0.30, 0.85)); rR = float(rng.uniform(0.10, 0.55)); rCC = float(rng.uniform(0.20, 0.75))
            _cv2.circle(M, (cx, cy), r_outer, rM, 1, lineType=_cv2.LINE_AA)
            _cv2.circle(M, (cx, cy), r_mid, float(rng.uniform(0.55, 0.95)), 1, lineType=_cv2.LINE_AA)
            _cv2.circle(M, (cx, cy), r_in, float(rng.uniform(0.20, 0.60)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r_outer, rR, 1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r_mid, float(rng.uniform(0.20, 0.55)), 1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r_in, float(rng.uniform(0.40, 0.75)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r_outer, rCC, 1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r_mid, float(rng.uniform(0.30, 0.70)), 1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r_in, float(rng.uniform(0.15, 0.55)), -1, lineType=_cv2.LINE_AA)
    # 6) FLECKS
    n_fl = int(np.clip(1800 * (mn / 2048.0) ** 2, 620, 4200))
    fx = rng.integers(0, w, n_fl); fy = rng.integers(0, h, n_fl)
    M[fy, fx] = rng.uniform(0.40, 0.96, n_fl).astype(np.float32)
    R[fy, fx] = rng.uniform(0.10, 0.88, n_fl).astype(np.float32)
    CC[fy, fx] = rng.uniform(0.06, 0.78, n_fl).astype(np.float32)
    out = np.stack([M, R, CC], axis=-1).astype(np.float32)
    return _validate_spec_output(_sm_scale(np.clip(out, 0.0, 1.0), sm).astype(np.float32), "spec_anodized_texture")
spec_anodized_texture._spb_concept_complete = True


def spec_powder_coat_texture(shape, seed, sm, cell_size=22.0, roughness_base=0.50, **kwargs):
    """spec_powder_coat_texture â€” R6 CREATIVE rebuild.

    identity: A factory powder-coated panel with VISIBLE CURE-ZONE STORY.
    HERO MOTIF: large irregular CURE-ZONE PATCHES (Voronoi-cell-style soft
    color zones) where the panel cooled at different rates, giving subtle
    rolling tonal shifts across the surface (each zone has its own
    matte-base chroma). On top of zones: dense fine ORANGE-PEEL BEAD field
    (3-7 px polymer pebbles packed shoulder-to-shoulder), each bead with
    BRIGHTER directional CAP highlight (sun-side) and DARKER opposing
    shadow rim â€” selling the 3D bead form. Plus: CRATER PITS (dark voids
    where outgassing escaped), SINTERING STRIATIONS (short fuse marks),
    METALLIC FLECK INCLUSIONS (rare bright micro-particles in the polymer),
    and dust-tip pinpoint sheen. Per-feature INDEPENDENT continuous M/R/CC
    with WIDE matte range. Seven stacked tiers, full canvas coverage.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 15101)
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)

    # 1) BASE â€” independent FBM, matte mid-range
    g1 = _normalize(multi_scale_noise(shape, [2.0, 5.0, 11.0], [0.42, 0.32, 0.26], int(seed) + 15111))
    g2 = _normalize(multi_scale_noise(shape, [2.5, 6.0, 13.0], [0.42, 0.32, 0.26], int(seed) + 15112))
    g3 = _normalize(multi_scale_noise(shape, [3.0, 6.5, 14.0], [0.42, 0.32, 0.26], int(seed) + 15113))
    M  = (0.22 + (g1 - 0.5) * 0.22).astype(np.float32)
    R  = (0.66 + (g2 - 0.5) * 0.26).astype(np.float32)
    CC = (0.42 + (g3 - 0.5) * 0.26).astype(np.float32)

    if _CV2_OK:
        # 2) HERO: CURE-ZONE PATCHES â€” large soft Voronoi-style cells with chroma shift
        n_zones = int(rng.integers(8, 14))
        zone_centers = []
        zone_M = []; zone_R = []; zone_CC = []
        for _ in range(n_zones):
            zone_centers.append((float(rng.uniform(0, w)), float(rng.uniform(0, h))))
            zone_M.append(float(rng.uniform(0.16, 0.36)))
            zone_R.append(float(rng.uniform(0.58, 0.82)))
            zone_CC.append(float(rng.uniform(0.30, 0.62)))
        # Build a soft zone-influence map using nearest-center weighting at coarse resolution
        # Use a downsampled grid for speed
        ds = max(1, int(mn / 96))
        ys_c = np.arange(0, h, ds, dtype=np.float32)
        xs_c = np.arange(0, w, ds, dtype=np.float32)
        gy_c, gx_c = np.meshgrid(ys_c, xs_c, indexing='ij')
        zone_map_M = np.zeros_like(gx_c, dtype=np.float32)
        zone_map_R = np.zeros_like(gx_c, dtype=np.float32)
        zone_map_CC = np.zeros_like(gx_c, dtype=np.float32)
        # For each grid cell, pick nearest zone center
        best_d = np.full_like(gx_c, 1e18, dtype=np.float32)
        best_idx = np.zeros_like(gx_c, dtype=np.int32)
        for zi, (zx, zy) in enumerate(zone_centers):
            d = (gx_c - zx) ** 2 + (gy_c - zy) ** 2
            mask = d < best_d
            best_d = np.where(mask, d, best_d)
            best_idx = np.where(mask, zi, best_idx).astype(np.int32)
        for zi in range(n_zones):
            sel = (best_idx == zi)
            zone_map_M[sel] = zone_M[zi]
            zone_map_R[sel] = zone_R[zi]
            zone_map_CC[sel] = zone_CC[zi]
        # Resize to full and soften
        zone_full_M = _cv2.resize(zone_map_M, (w, h), interpolation=_cv2.INTER_LINEAR)
        zone_full_R = _cv2.resize(zone_map_R, (w, h), interpolation=_cv2.INTER_LINEAR)
        zone_full_CC = _cv2.resize(zone_map_CC, (w, h), interpolation=_cv2.INTER_LINEAR)
        ksz = int(max(11, mn / 20)) | 1
        zone_full_M = _cv2.GaussianBlur(zone_full_M, (ksz, ksz), sigmaX=ksz / 5.0)
        zone_full_R = _cv2.GaussianBlur(zone_full_R, (ksz, ksz), sigmaX=ksz / 5.0)
        zone_full_CC = _cv2.GaussianBlur(zone_full_CC, (ksz, ksz), sigmaX=ksz / 5.0)
        # Blend zone-tint into base
        M = (M * 0.55 + zone_full_M * 0.45).astype(np.float32)
        R = (R * 0.55 + zone_full_R * 0.45).astype(np.float32)
        CC = (CC * 0.55 + zone_full_CC * 0.45).astype(np.float32)

        # 3) ORANGE-PEEL BEADS with directional cap/shadow
        n_bead = int(np.clip(9500 * (mn / 2048.0) ** 2, 3200, 19000))
        light_ang = float(rng.uniform(0, 2 * np.pi))
        cos_l, sin_l = float(np.cos(light_ang)), float(np.sin(light_ang))
        for _ in range(n_bead):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            r_p = max(1, int(rng.uniform(3.0, 7.0) * scale * 0.5))
            bM = float(rng.uniform(0.14, 0.40))
            bR = float(rng.uniform(0.48, 0.82))
            bCC = float(rng.uniform(0.28, 0.62))
            _cv2.circle(M, (cx, cy), r_p, bM, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r_p, bR, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r_p, bCC, -1, lineType=_cv2.LINE_AA)
            # CAP highlight (light-side)
            off = max(1, int(r_p * 0.45))
            cap_r = max(1, r_p // 2)
            _cv2.circle(M, (cx + int(cos_l * off), cy + int(sin_l * off)), cap_r, float(rng.uniform(0.40, 0.72)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx + int(cos_l * off), cy + int(sin_l * off)), cap_r, float(rng.uniform(0.28, 0.52)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx + int(cos_l * off), cy + int(sin_l * off)), cap_r, float(rng.uniform(0.18, 0.42)), -1, lineType=_cv2.LINE_AA)
            # SHADOW rim (opposite side)
            shr_r = max(1, r_p // 3)
            _cv2.circle(M, (cx - int(cos_l * off), cy - int(sin_l * off)), shr_r, float(rng.uniform(0.08, 0.20)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx - int(cos_l * off), cy - int(sin_l * off)), shr_r, float(rng.uniform(0.65, 0.88)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx - int(cos_l * off), cy - int(sin_l * off)), shr_r, float(rng.uniform(0.42, 0.70)), -1, lineType=_cv2.LINE_AA)

        # 4) CRATER PITS â€” outgas escape voids
        n_pit = int(np.clip(4800 * (mn / 2048.0) ** 2, 1500, 10000))
        for _ in range(n_pit):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            r_p = max(1, int(rng.uniform(2.0, 4.0) * scale * 0.5))
            _cv2.circle(M, (cx, cy), r_p, float(rng.uniform(0.04, 0.18)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r_p, float(rng.uniform(0.75, 0.98)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r_p, float(rng.uniform(0.50, 0.88)), -1, lineType=_cv2.LINE_AA)

        # 5) SINTERING STRIATIONS â€” short fuse marks
        n_st = int(np.clip(2400 * (mn / 2048.0) ** 2, 800, 5800))
        for _ in range(n_st):
            cx = rng.uniform(2, w - 2); cy = rng.uniform(2, h - 2)
            length = float(rng.uniform(3.0, 8.0) * scale)
            ang = float(rng.uniform(0, 2 * np.pi))
            x0s = int(cx - np.cos(ang) * length * 0.5)
            y0s = int(cy - np.sin(ang) * length * 0.5)
            x1s = int(cx + np.cos(ang) * length * 0.5)
            y1s = int(cy + np.sin(ang) * length * 0.5)
            _cv2.line(M, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.22, 0.55)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(R, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.42, 0.72)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.28, 0.60)), 1, lineType=_cv2.LINE_AA)

        # 6) METALLIC FLECK INCLUSIONS â€” rare bright micro-particles
        n_fk = int(np.clip(900 * (mn / 2048.0) ** 2, 280, 2400))
        for _ in range(n_fk):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            r = max(1, int(rng.uniform(1.0, 1.8) * scale))
            _cv2.circle(M, (cx, cy), r, float(rng.uniform(0.65, 0.92)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r, float(rng.uniform(0.12, 0.32)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r, float(rng.uniform(0.10, 0.34)), -1, lineType=_cv2.LINE_AA)

    # 7) BEAD-TIP FLECKS â€” single-pixel pinpoint sheen
    n_fl = int(np.clip(mn * mn / 80.0, 2400, 12000))
    fx = rng.integers(0, w, n_fl); fy = rng.integers(0, h, n_fl)
    M[fy, fx] = np.maximum(M[fy, fx], rng.uniform(0.38, 0.75, n_fl).astype(np.float32))
    R[fy, fx] = np.minimum(R[fy, fx], rng.uniform(0.20, 0.50, n_fl).astype(np.float32))
    CC[fy, fx] = np.minimum(CC[fy, fx], rng.uniform(0.16, 0.44, n_fl).astype(np.float32))

    out = np.stack([M, R, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
spec_powder_coat_texture._spb_concept_complete = True


def spec_thermal_spray(shape, seed, sm, splat_density=0.018, **kwargs):
    """spec_thermal_spray.

    identity: Round-6 creative rebuild â€” plasma-sprayed coating pushed for
    AWESOME. Six tiers stacked:
      (1) Coarse overspray substrate, independent FBM per channel.
      (2) Dense MOLTEN SPLAT PANCAKES (3-10 px elliptical impact discs,
          per-splat INDEPENDENT continuous M/R/CC, plus bright rim-flash).
      (3) UN-BONDED crater pits (2-4 px dark) scattered across surface.
      (4) HERO: re-melt FLOW RIVERS â€” short snaking molten paths (8-20 px
          polylines) that connect adjacent splats, simulating coalescence
          on a still-hot surface. Bright with low R, high CC.
      (5) HERO: cooled-bead micro-SPHERES â€” rare 3-5 px discs with bright
          highlight pinpoint offset toward the light direction (reads as
          3D ball reflections, owner-eye standout).
      (6) Pinpoint oxide-fleck carpet + dark un-melted particle scatter.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 37014)
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)
    s256 = max(mn / 256.0, 0.6)

    # 1) BASE
    bM = _normalize(multi_scale_noise(shape, [2.0, 5.0, 11.0, 22.0], [0.34, 0.30, 0.22, 0.14], int(seed) + 3701))
    bR = _normalize(multi_scale_noise(shape, [2.5, 6.0, 13.0, 24.0], [0.32, 0.28, 0.22, 0.18], int(seed) + 3702))
    bC = _normalize(multi_scale_noise(shape, [3.0, 7.0, 15.0, 26.0], [0.30, 0.28, 0.24, 0.18], int(seed) + 3703))
    M = (0.52 + (bM - 0.5) * 0.28).astype(np.float32)
    R = (0.66 + (bR - 0.5) * 0.30).astype(np.float32)
    CC = (0.54 + (bC - 0.5) * 0.30).astype(np.float32)

    # Track splat centres for flow-river connection
    splat_centers = []

    if _CV2_OK:
        # 2) MOLTEN SPLAT PANCAKES
        n_splat = int(np.clip(7000 * (mn / 2048.0) ** 2, 2500, 18000))
        for _ in range(n_splat):
            cx = int(rng.uniform(2, w - 2)); cy = int(rng.uniform(2, h - 2))
            r_maj = max(2, int(rng.uniform(3.0, 10.0) * scale * 0.5))
            squish = float(rng.uniform(0.6, 1.0))
            r_min = max(1, int(r_maj * squish))
            ang_deg = float(rng.uniform(0, 180))
            vM = float(rng.uniform(0.52, 0.98))
            vR = float(rng.uniform(0.32, 0.80))
            vC = float(rng.uniform(0.24, 0.74))
            _cv2.ellipse(M, (cx, cy), (r_maj, r_min), ang_deg, 0, 360, vM, -1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(R, (cx, cy), (r_maj, r_min), ang_deg, 0, 360, vR, -1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(CC, (cx, cy), (r_maj, r_min), ang_deg, 0, 360, vC, -1, lineType=_cv2.LINE_AA)
            if r_maj > 2:
                _cv2.ellipse(M, (cx, cy), (r_maj, r_min), ang_deg, 0, 360,
                             float(rng.uniform(0.78, 0.99)), 1, lineType=_cv2.LINE_AA)
                _cv2.ellipse(R, (cx, cy), (r_maj, r_min), ang_deg, 0, 360,
                             float(rng.uniform(0.08, 0.32)), 1, lineType=_cv2.LINE_AA)
                _cv2.ellipse(CC, (cx, cy), (r_maj, r_min), ang_deg, 0, 360,
                             float(rng.uniform(0.06, 0.30)), 1, lineType=_cv2.LINE_AA)
            if len(splat_centers) < 4000:
                splat_centers.append((cx, cy))

        # 3) UN-BONDED CRATERS
        n_crater = int(np.clip(4000 * (mn / 2048.0) ** 2, 1400, 11000))
        for _ in range(n_crater):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            r = max(1, int(rng.uniform(1.5, 3.5) * scale))
            _cv2.circle(M, (cx, cy), r, float(rng.uniform(0.14, 0.40)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r, float(rng.uniform(0.74, 0.97)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r, float(rng.uniform(0.58, 0.92)), -1, lineType=_cv2.LINE_AA)

        # 4) HERO â€” RE-MELT FLOW RIVERS (connect random splat-center pairs)
        n_river = int(np.clip(240 * s256 * s256, 80, 1200))
        if len(splat_centers) >= 2:
            sc_arr = np.array(splat_centers, dtype=np.int32)
            for _ in range(n_river):
                i1 = int(rng.integers(0, len(sc_arr)))
                i2 = int(rng.integers(0, len(sc_arr)))
                if i1 == i2:
                    continue
                x1c, y1c = int(sc_arr[i1, 0]), int(sc_arr[i1, 1])
                x2c, y2c = int(sc_arr[i2, 0]), int(sc_arr[i2, 1])
                # only connect if reasonably close (8-20 px)
                d = ((x1c - x2c) ** 2 + (y1c - y2c) ** 2) ** 0.5
                if d < 4 * s256 or d > 22 * s256:
                    continue
                # 3-vertex meander
                mxp = (x1c + x2c) * 0.5 + float(rng.normal(0, 2.0 * s256))
                myp = (y1c + y2c) * 0.5 + float(rng.normal(0, 2.0 * s256))
                pts_r = np.array([[x1c, y1c], [int(mxp), int(myp)], [x2c, y2c]], dtype=np.int32)
                rM = float(rng.uniform(0.72, 0.99))
                rR_v = float(rng.uniform(0.06, 0.28))
                rC = float(rng.uniform(0.62, 0.95))
                _cv2.polylines(M,  [pts_r], False, rM, 1, lineType=_cv2.LINE_AA)
                _cv2.polylines(R,  [pts_r], False, rR_v, 1, lineType=_cv2.LINE_AA)
                _cv2.polylines(CC, [pts_r], False, rC, 1, lineType=_cv2.LINE_AA)

        # 5) HERO â€” COOLED BEAD MICRO-SPHERES (3D-reading droplets)
        n_bead = int(np.clip(80 * s256 * s256, 30, 360))
        # consistent overhead light direction
        light_a = float(rng.uniform(-np.pi * 0.4, np.pi * 0.4)) - np.pi * 0.5
        lx = np.cos(light_a); ly = np.sin(light_a)
        for _ in range(n_bead):
            bcx = int(rng.uniform(4, w - 4)); bcy = int(rng.uniform(4, h - 4))
            br = max(2, int(rng.uniform(2.0, 3.5) * s256))
            # bead body â€” dim mid
            bM_v = float(rng.uniform(0.55, 0.82))
            bR_v = float(rng.uniform(0.25, 0.55))
            bC_v = float(rng.uniform(0.40, 0.72))
            _cv2.circle(M,  (bcx, bcy), br, bM_v, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R,  (bcx, bcy), br, bR_v, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (bcx, bcy), br, bC_v, -1, lineType=_cv2.LINE_AA)
            # bright specular highlight pinpoint offset toward light
            hx = int(bcx + lx * br * 0.45); hy = int(bcy + ly * br * 0.45)
            hr = max(1, br // 2)
            _cv2.circle(M,  (hx, hy), hr, float(rng.uniform(0.92, 0.99)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R,  (hx, hy), hr, float(rng.uniform(0.02, 0.10)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (hx, hy), hr, float(rng.uniform(0.88, 0.99)), -1, lineType=_cv2.LINE_AA)
            # dark terminator arc opposite to light
            _cv2.ellipse(M, (bcx, bcy), (br, br), float(np.degrees(light_a)),
                         60, 300, float(rng.uniform(0.30, 0.50)), 1, lineType=_cv2.LINE_AA)

    # 6) OXIDE FLECK CARPET + DARK UN-MELT PARTICLES
    n_fl = int(np.clip(7000 * (mn / 2048.0) ** 2, 2500, 18000))
    fx = rng.integers(0, w, n_fl); fy = rng.integers(0, h, n_fl)
    M[fy, fx] = rng.uniform(0.16, 0.97, n_fl).astype(np.float32)
    R[fy, fx] = rng.uniform(0.20, 0.94, n_fl).astype(np.float32)
    CC[fy, fx] = rng.uniform(0.06, 0.88, n_fl).astype(np.float32)

    # Dark un-melt particles (small dark seeds)
    n_unm = int(np.clip(2500 * (mn / 2048.0) ** 2, 900, 6000))
    uy = rng.integers(0, h, n_unm); ux = rng.integers(0, w, n_unm)
    M[uy, ux] = np.minimum(M[uy, ux], rng.uniform(0.10, 0.30, n_unm).astype(np.float32))
    R[uy, ux] = np.maximum(R[uy, ux], rng.uniform(0.68, 0.94, n_unm).astype(np.float32))

    # R6 TICK 54 SECOND-PASS HERO â€” SPATTER COMET STREAMERS
    # Long 6-14 px tapered streamers emanating from random splat centres,
    # like molten droplet trails caught mid-flight. Per-streamer INDEPENDENT
    # continuous M/R/CC. Each streamer has a bright leading head + 4-6
    # micro tail beads decreasing in brightness.
    if _CV2_OK and len(splat_centers) >= 2:
        n_comet = int(np.clip(360 * s256 * s256, 120, 1400))
        sc_arr2 = np.array(splat_centers, dtype=np.int32)
        for _ in range(n_comet):
            i = int(rng.integers(0, len(sc_arr2)))
            x0 = int(sc_arr2[i, 0]); y0 = int(sc_arr2[i, 1])
            ang = float(rng.uniform(0, 2 * np.pi))
            L = float(rng.uniform(6.0, 14.0) * s256)
            n_bead = int(rng.integers(4, 7))
            headM = float(rng.uniform(0.78, 0.99))
            headR = float(rng.uniform(0.04, 0.18))
            headCC = float(rng.uniform(0.62, 0.96))
            for k in range(n_bead):
                t = k / max(n_bead - 1, 1)
                bx = int(x0 + np.cos(ang) * L * t)
                by = int(y0 + np.sin(ang) * L * t)
                if 0 <= bx < w and 0 <= by < h:
                    fade = 1.0 - t * 0.65
                    br = max(1, int((1.6 - t) * s256))
                    _cv2.circle(M,  (bx, by), br, float(np.clip(headM * fade + rng.uniform(-0.05, 0.05), 0, 1)), -1, lineType=_cv2.LINE_AA)
                    _cv2.circle(R,  (bx, by), br, float(np.clip(headR + rng.uniform(-0.04, 0.10), 0, 1)), -1, lineType=_cv2.LINE_AA)
                    _cv2.circle(CC, (bx, by), br, float(np.clip(headCC * fade + rng.uniform(-0.06, 0.06), 0, 1)), -1, lineType=_cv2.LINE_AA)

    out = np.stack([M, R, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
spec_thermal_spray._spb_concept_complete = True


def spec_electroformed_texture(shape, seed, sm, num_columns=None, col_aspect=2.8, **kwargs):
    """spec_electroformed_texture -- R6 creative rebuild with HERO dendrite-burst crystals.

    identity: An electroformed nickel deposit where the HERO motifs are
    DENDRITIC CRYSTAL BURSTS - 18-32 starburst seed-crystals scattered
    across the surface, each radiating 5-9 short 6-12 px hairline arms
    out from a bright 2-4 px nodule core (the dendritic growth pattern
    you see in real electroforming). Plus a forest of fine vertical
    column hairlines, crystal-nodule discs, dark micropore voids, and
    sparkle. Seven tiers: (1) vertical-bias columnar substrate with
    top-of-canvas growth highlight; (2) HERO dendritic crystal bursts
    (5-9 arm starbursts with bright cores); (3) dense vertical column
    forest 4-14 px; (4) bright crystal nodule micro-discs 2-5 px;
    (5) dark micropore voids 1-3 px; (6) micro-fissure cracks (3-6 px
    angular lines at random tilts); (7) single-pixel sparkle floor.
    Per-feature INDEPENDENT continuous M/R/CC uniforms, WIDE ranges.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 2890)
    mn = float(min(h, w))
    scale = max(mn / 256.0, 0.6)

    # 1) Vertical-bias substrate noise + columnar pre-grain
    grain = _gauss(rng.random((h, w)).astype(np.float32), sigma=max(mn / 90.0, 1.5))
    band = _gauss(rng.random((1, w)).astype(np.float32), sigma=max(mn / 64.0, 2.0))
    band = np.broadcast_to(_normalize(band), (h, w)).astype(np.float32)
    grain = _normalize(grain * 0.45 + band * 0.55)

    yy_n = np.arange(h, dtype=np.float32).reshape(h, 1) / max(h - 1, 1)
    top_growth = (1.0 - yy_n * 0.18).astype(np.float32)

    M = (0.42 + (grain - 0.5) * 0.24) * top_growth
    R_ch = (0.46 + (1.0 - grain) * 0.22) * (1.0 - (top_growth - 0.82) * 0.4)
    CC = (0.38 + (grain - 0.5) * 0.20) * top_growth
    M = M.astype(np.float32)
    R_ch = R_ch.astype(np.float32)
    CC = CC.astype(np.float32)

    if _CV2_OK:
        # 2) HERO DENDRITIC CRYSTAL BURSTS - starburst seed-crystals
        n_burst = int(rng.integers(18, 33))
        for _ in range(n_burst):
            cx = int(rng.uniform(8, w - 8))
            cy = int(rng.uniform(8, h - 8))
            core_r = max(1, int(rng.uniform(1.8, 4.0)))
            coreM = float(rng.uniform(0.86, 0.99))
            coreR = float(rng.uniform(0.02, 0.12))
            coreCC = float(rng.uniform(0.70, 0.98))
            # bright nodule core
            _cv2.circle(M, (cx, cy), core_r, coreM, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R_ch, (cx, cy), core_r, coreR, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), core_r, coreCC, -1, lineType=_cv2.LINE_AA)
            # 5-9 radiating dendritic arms
            n_arm = int(rng.integers(5, 10))
            base_ang = float(rng.uniform(0, 2 * np.pi))
            for k in range(n_arm):
                arm_ang = base_ang + (2 * np.pi * k / n_arm) + float(rng.normal(0.0, 0.10))
                arm_len = float(rng.uniform(6.0, 12.0))
                ex = int(cx + np.cos(arm_ang) * arm_len)
                ey = int(cy + np.sin(arm_ang) * arm_len)
                _cv2.line(M, (cx, cy), (ex, ey),
                          float(np.clip(coreM + rng.uniform(-0.08, 0.04), 0, 1)), 1, lineType=_cv2.LINE_AA)
                _cv2.line(R_ch, (cx, cy), (ex, ey),
                          float(np.clip(coreR + rng.uniform(-0.02, 0.10), 0, 1)), 1, lineType=_cv2.LINE_AA)
                _cv2.line(CC, (cx, cy), (ex, ey),
                          float(np.clip(coreCC + rng.uniform(-0.10, 0.05), 0, 1)), 1, lineType=_cv2.LINE_AA)
                # secondary side-branches (dendrite branching)
                if rng.random() < 0.6:
                    side_ang = arm_ang + float(rng.choice([-1.0, 1.0])) * float(rng.uniform(0.5, 0.9))
                    side_len = float(rng.uniform(3.0, 6.0))
                    bx = int(cx + np.cos(arm_ang) * arm_len * 0.6)
                    by = int(cy + np.sin(arm_ang) * arm_len * 0.6)
                    sx2 = int(bx + np.cos(side_ang) * side_len)
                    sy2 = int(by + np.sin(side_ang) * side_len)
                    _cv2.line(M, (bx, by), (sx2, sy2),
                              float(rng.uniform(0.72, 0.96)), 1, lineType=_cv2.LINE_AA)
                    _cv2.line(R_ch, (bx, by), (sx2, sy2),
                              float(rng.uniform(0.04, 0.20)), 1, lineType=_cv2.LINE_AA)
                    _cv2.line(CC, (bx, by), (sx2, sy2),
                              float(rng.uniform(0.55, 0.92)), 1, lineType=_cv2.LINE_AA)

        # 3) Dense vertical column hairlines
        n_col = int(np.clip(2600 * scale * scale, 1800, 8500))
        for _ in range(n_col):
            cx = int(rng.uniform(0, w))
            cy = float(rng.uniform(0, h))
            length = float(rng.uniform(4.0, 14.0) * scale)
            tilt = float(rng.uniform(-1.2, 1.2))
            x_a = int(cx - tilt * 0.5)
            y_a = int(cy - length * 0.5)
            x_b = int(cx + tilt * 0.5)
            y_b = int(cy + length * 0.5)
            _cv2.line(M, (x_a, y_a), (x_b, y_b), float(rng.uniform(0.52, 0.97)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(R_ch, (x_a, y_a), (x_b, y_b), float(rng.uniform(0.06, 0.34)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (x_a, y_a), (x_b, y_b), float(rng.uniform(0.40, 0.94)), 1, lineType=_cv2.LINE_AA)

        # 4) Bright crystal nodule micro-discs
        n_nod = int(np.clip(1500 * scale * scale, 900, 4500))
        for _ in range(n_nod):
            cx = int(rng.uniform(0, w))
            cy = int(rng.uniform(0, h))
            rr = int(max(1, rng.uniform(1.6, 4.2)))
            _cv2.circle(M, (cx, cy), rr, float(rng.uniform(0.76, 0.99)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R_ch, (cx, cy), rr, float(rng.uniform(0.03, 0.18)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), rr, float(rng.uniform(0.55, 0.98)), -1, lineType=_cv2.LINE_AA)

        # 5) Dark micropore voids
        n_void = int(np.clip(1300 * scale * scale, 700, 3800))
        for _ in range(n_void):
            cx = int(rng.uniform(0, w))
            cy = int(rng.uniform(0, h))
            rr = int(max(1, rng.uniform(1.0, 3.0)))
            _cv2.circle(M, (cx, cy), rr, float(rng.uniform(0.06, 0.28)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R_ch, (cx, cy), rr, float(rng.uniform(0.60, 0.95)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), rr, float(rng.uniform(0.20, 0.58)), -1, lineType=_cv2.LINE_AA)

        # 6) Micro-fissure cracks 3-6 px angular lines
        n_crack = int(np.clip(1200 * scale * scale, 500, 3200))
        for _ in range(n_crack):
            cx = float(rng.uniform(2, w - 2))
            cy = float(rng.uniform(2, h - 2))
            length = float(rng.uniform(3.0, 6.0) * scale)
            ang = float(rng.uniform(0, 2 * np.pi))
            x0 = int(cx - np.cos(ang) * length * 0.5)
            y0 = int(cy - np.sin(ang) * length * 0.5)
            x1 = int(cx + np.cos(ang) * length * 0.5)
            y1 = int(cy + np.sin(ang) * length * 0.5)
            _cv2.line(M, (x0, y0), (x1, y1), float(rng.uniform(0.08, 0.30)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(R_ch, (x0, y0), (x1, y1), float(rng.uniform(0.55, 0.92)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (x0, y0), (x1, y1), float(rng.uniform(0.18, 0.50)), 1, lineType=_cv2.LINE_AA)

    # 7) Single-pixel sheen flecks
    n_fl = int(np.clip(mn * mn / 80.0, 1500, 10000))
    fy = rng.integers(0, h, size=n_fl)
    fx = rng.integers(0, w, size=n_fl)
    M[fy, fx] = rng.uniform(0.48, 0.98, size=n_fl).astype(np.float32)
    R_ch[fy, fx] = rng.uniform(0.04, 0.32, size=n_fl).astype(np.float32)
    CC[fy, fx] = rng.uniform(0.28, 0.94, size=n_fl).astype(np.float32)

    out = np.stack([M, R_ch, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
spec_electroformed_texture._spb_concept_complete = True


def spec_pvd_coating(shape, seed, sm, cell_density=80.0, **kwargs):
    """spec_pvd_coating.

    identity: R6-creative â€” TITANIUM-NITRIDE PVD with interference-color
    DOMAIN MAP. A coarse Voronoi domain field (24-px cells) tints CC per
    domain so different facets of the panel show distinct iridescent
    colors (gold, violet, teal, magenta) â€” the read of a real
    multi-angle PVD/anodized titanium surface. Hero motif: rare 8-14 px
    DROPLET CONDENSATE beads (overshoot deposit nodules with bright
    crown glints + rim halos) salted across the field. Tier-1 dense
    nano-nodules (1-4 px) carpet the substrate, tight near-vertical
    growth-column forest (4-10 px), gas-inclusion voids, single-pixel
    crystal sparkle. Per-feature INDEPENDENT continuous M/R/CC. Full
    canvas coverage, 1-14 px max.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 21171 + (hash("pvd_r6c") % 5000))
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)
    yy = np.arange(h, dtype=np.float32).reshape(h, 1)
    xx = np.arange(w, dtype=np.float32).reshape(1, w)

    # 1) BASE â€” independent FBM (vapor sheen) + thin-film rainbow CC stripe
    g1 = _normalize(multi_scale_noise(shape, [2.5, 6.0, 13.0, 24.0], [0.34, 0.30, 0.22, 0.14], int(seed) + 21111))
    g2 = _normalize(multi_scale_noise(shape, [3.0, 7.0, 14.0, 26.0], [0.34, 0.30, 0.22, 0.14], int(seed) + 21112))
    g3 = _normalize(multi_scale_noise(shape, [3.5, 7.5, 15.0, 28.0], [0.34, 0.30, 0.22, 0.14], int(seed) + 21113))
    # OWNER-REBUILD 2026-06-03: "barely comes through, way too weak". Richer
    # iridescent thin-film sweep (two beat frequencies = stronger rainbow) and
    # bolder per-channel amplitude so the PVD sheen actually reads on the car.
    rainbow = (np.sin(yy * 0.16 + xx * 0.05 + float(rng.uniform(0, 2 * np.pi))) * 0.5 + 0.5).astype(np.float32)
    rainbow2 = (np.sin(yy * 0.045 - xx * 0.10 + float(rng.uniform(0, 2 * np.pi))) * 0.5 + 0.5).astype(np.float32)
    M  = (0.70 + (g1 - 0.5) * 0.30 - (rainbow2 - 0.5) * 0.16).astype(np.float32)
    R  = (0.18 + (g2 - 0.5) * 0.22 + (rainbow2 - 0.5) * 0.14).astype(np.float32)
    CC = (0.28 + (g3 - 0.5) * 0.22 + (rainbow - 0.5) * 0.42 + (rainbow2 - 0.5) * 0.20).astype(np.float32)

    # 1b) DOMAIN MAP â€” coarse Voronoi assigning per-domain CC tint
    # (gold/violet/teal/magenta interference colors)
    cs_dom = max(16, int(24 * scale * 4))  # ~24px at 256
    ny_d = max(2, h // cs_dom + 2); nx_d = max(2, w // cs_dom + 2)
    IYd, IXd = np.meshgrid(np.arange(ny_d), np.arange(nx_d), indexing='ij')
    cyd = (IYd.astype(np.float64) + rng.uniform(0.1, 0.9, (ny_d, nx_d))) * cs_dom
    cxd = (IXd.astype(np.float64) + rng.uniform(0.1, 0.9, (ny_d, nx_d))) * cs_dom
    n_dom = ny_d * nx_d
    # 6 interference color archetypes spanning the full thin-film gamut so
    # adjacent facets contrast HARD (gold/violet/teal/magenta/cyan/amber).
    archetypes = np.array([0.86, 0.12, 0.55, 0.95, 0.70, 0.30], dtype=np.float32)
    dom_cc = archetypes[rng.integers(0, archetypes.size, n_dom)] + rng.uniform(-0.06, 0.06, n_dom).astype(np.float32)
    dom_m = rng.uniform(0.58, 0.96, n_dom).astype(np.float32)
    centers_d = np.column_stack([cyd.ravel(), cxd.ravel()])
    tree_d = cKDTree(centers_d)
    yy_g, xx_g = np.mgrid[0:h, 0:w].astype(np.float64)
    pts_d = np.column_stack([yy_g.ravel(), xx_g.ravel()])
    _, idx_d = tree_d.query(pts_d, k=1, workers=-1)
    dom_cc_field = dom_cc[idx_d].reshape(shape)
    dom_m_field = dom_m[idx_d].reshape(shape)
    # Mix domain map STRONGER into CC (60%) and M (28%) so each facet shows
    # its own distinct interference color -> the multi-angle PVD read.
    CC = (CC * 0.40 + dom_cc_field * 0.60).astype(np.float32)
    M  = (M * 0.72 + dom_m_field * 0.28).astype(np.float32)

    if _CV2_OK:
        # 2) DENSE NANO-NODULES â€” 5x density (1-4 px ceramic beads)
        n_nod = int(np.clip(11000 * (mn / 2048.0) ** 2, 3500, 22000))
        for _ in range(n_nod):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            r = max(1, int(rng.uniform(1.0, 4.0) * scale * 0.5))
            nM = float(rng.uniform(0.74, 0.98))
            nR = float(rng.uniform(0.03, 0.20))
            nCC = float(rng.uniform(0.04, 0.30))
            _cv2.circle(M, (cx, cy), r, nM, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r, nR, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r, nCC, -1, lineType=_cv2.LINE_AA)

        # 3) GROWTH-COLUMN FOREST â€” dense vertical columns (4-10 px, Â±15Â° bias)
        n_col = int(np.clip(4200 * (mn / 2048.0) ** 2, 1400, 9500))
        for _ in range(n_col):
            cx = float(rng.uniform(2, w - 2)); cy = float(rng.uniform(2, h - 2))
            length = float(rng.uniform(4.0, 10.0) * scale)
            ang = float(np.pi * 0.5 + rng.uniform(-0.26, 0.26))
            x0s = int(cx - np.cos(ang) * length * 0.5)
            y0s = int(cy - np.sin(ang) * length * 0.5)
            x1s = int(cx + np.cos(ang) * length * 0.5)
            y1s = int(cy + np.sin(ang) * length * 0.5)
            colM = float(rng.uniform(0.55, 0.92))
            colR = float(rng.uniform(0.08, 0.32))
            colCC = float(rng.uniform(0.08, 0.34))
            _cv2.line(M, (x0s, y0s), (x1s, y1s), colM, 1, lineType=_cv2.LINE_AA)
            _cv2.line(R, (x0s, y0s), (x1s, y1s), colR, 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (x0s, y0s), (x1s, y1s), colCC, 1, lineType=_cv2.LINE_AA)

        # 4) GAS-INCLUSION VOIDS â€” 1-2 px dark pits
        n_void = int(np.clip(3000 * (mn / 2048.0) ** 2, 1000, 7000))
        for _ in range(n_void):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            r = max(1, int(rng.uniform(1.0, 2.0) * scale))
            vM = float(rng.uniform(0.10, 0.35))
            vR = float(rng.uniform(0.42, 0.78))
            vCC = float(rng.uniform(0.30, 0.65))
            _cv2.circle(M, (cx, cy), r, vM, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r, vR, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r, vCC, -1, lineType=_cv2.LINE_AA)

    # 5) CRYSTAL SPARKLE FLECK CARPET â€” full canvas
    n_fl = int(np.clip(mn * mn / 80.0, 2800, 12000))
    fy = rng.integers(0, h, n_fl); fx = rng.integers(0, w, n_fl)
    M[fy, fx] = np.maximum(M[fy, fx], rng.uniform(0.75, 0.99, n_fl).astype(np.float32))
    R[fy, fx] = np.minimum(R[fy, fx], rng.uniform(0.04, 0.22, n_fl).astype(np.float32))
    CC[fy, fx] = rng.uniform(0.06, 0.96, n_fl).astype(np.float32)

    # 6) HERO DROPLET CONDENSATE â€” rare 8-14 px overshoot deposit nodules
    if _CV2_OK:
        n_drop = int(np.clip(60 + 40 * (mn / 256.0), 20, 240))
        for _ in range(n_drop):
            cx = int(rng.uniform(8, w - 8)); cy = int(rng.uniform(8, h - 8))
            rd = max(3, int(rng.uniform(4.0, 7.0) * scale * 1.4))
            dM = float(rng.uniform(0.86, 0.99))
            dR = float(rng.uniform(0.03, 0.14))
            dC = float(rng.uniform(0.10, 0.96))
            _cv2.circle(M, (cx, cy), rd, dM, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), rd, dR, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), rd, dC, -1, lineType=_cv2.LINE_AA)
            # rim halo
            _cv2.circle(M, (cx, cy), rd + 1, float(rng.uniform(0.50, 0.78)), 1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), rd + 1, float(rng.uniform(0.20, 0.90)), 1, lineType=_cv2.LINE_AA)
            # crown glint
            if rd >= 3:
                gx = int(cx + rd * 0.30); gy = int(cy - rd * 0.45)
                _cv2.circle(M, (gx, gy), max(1, rd // 3), float(rng.uniform(0.92, 0.99)), -1, lineType=_cv2.LINE_AA)

    out = np.stack([M, R, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
spec_pvd_coating._spb_concept_complete = True


def spec_laser_etched(shape, seed, sm, tile_size=32.0, border_frac=0.18, **kwargs):
    """spec_laser_etched.

    identity: R6-Loop tick 55 SECOND-PASS â€” polished steel inscribed with
    PROGRAMMED LASER GRAPHICS. Existing layers: (A) polished steel FBM
    substrate, (B) hex-lattice etch, (C) geometric glyph stamps, (D) four
    micro-hatch families, (E) 2-px scribe-tooth baseline, (F) melt-bead
    sparkle, (G) dark recast-slag micro-spots. NEW HERO STACKED ON TOP
    (tick 55): SERIAL DATA-MATRIX BARCODE INSERTS â€” 3-7 small machine-
    readable rectangles (14-24 px wide x 6-10 px tall) randomly placed
    across the panel. Each insert renders a 5-7 x 3-4 cell grid of laser-
    burnt dots/bars + a bright bounding border. Per-cell INDEPENDENT
    on/off + per-cell M/R/CC. Sells "programmed laser graphics" with a
    real industrial part-number look at thumbnail scale.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 2712)
    mn = float(min(h, w))
    scale = max(mn / 256.0, 0.6)
    yy = np.arange(h, dtype=np.float32).reshape(h, 1)
    xx = np.arange(w, dtype=np.float32).reshape(1, w)

    # (A) Polished steel substrate â€” INDEPENDENT M/R/CC
    fbm_M = _normalize(multi_scale_noise(shape, [3.0, 10.0, 22.0], [0.5, 0.3, 0.2], int(seed) + 51))
    fbm_R = _normalize(multi_scale_noise(shape, [4.0, 12.0, 26.0], [0.5, 0.3, 0.2], int(seed) + 71))
    fbm_CC = _normalize(multi_scale_noise(shape, [5.0, 13.0, 28.0], [0.5, 0.3, 0.2], int(seed) + 91))
    M  = (0.76 + (fbm_M - 0.5) * 0.18).astype(np.float32)
    R_ch = (0.18 + (fbm_R - 0.5) * 0.16).astype(np.float32)
    CC = (0.70 + (fbm_CC - 0.5) * 0.18).astype(np.float32)

    if _CV2_OK:
        # (B) HERO HEX-LATTICE â€” bright etched cuts on a triangulated grid
        hex_step = float(np.clip(14.0 * scale, 11.0, 18.0))
        rows = int(h / (hex_step * 0.866)) + 2
        cols = int(w / hex_step) + 2
        for ry in range(rows):
            for cx_i in range(cols):
                # honeycomb offset
                ox = (ry % 2) * (hex_step * 0.5)
                gx = cx_i * hex_step + ox + float(rng.uniform(-1.5, 1.5))
                gy = ry * hex_step * 0.866 + float(rng.uniform(-1.5, 1.5))
                # randomly skip some cells (sparser, programmed feel)
                if rng.random() < 0.32:
                    continue
                # Draw 2-3 of the 3 hex-spoke segments at this node
                for spoke_idx in range(3):
                    if rng.random() < 0.30:
                        continue
                    ang = spoke_idx * (np.pi / 3.0) + float(rng.uniform(-0.04, 0.04))
                    L = float(rng.uniform(10.0, 16.0) * (scale * 0.7))
                    x1 = int(np.clip(gx + np.cos(ang) * L, 0, w - 1))
                    y1 = int(np.clip(gy + np.sin(ang) * L, 0, h - 1))
                    _cv2.line(M, (int(gx), int(gy)), (x1, y1),
                              float(rng.uniform(0.10, 0.42)), 1, lineType=_cv2.LINE_AA)
                    _cv2.line(R_ch, (int(gx), int(gy)), (x1, y1),
                              float(rng.uniform(0.65, 0.96)), 1, lineType=_cv2.LINE_AA)
                    _cv2.line(CC, (int(gx), int(gy)), (x1, y1),
                              float(rng.uniform(0.30, 0.85)), 1, lineType=_cv2.LINE_AA)

        # (C) GLYPH STAMPS â€” 8-22 mixed geometric carvings (HERO motif)
        n_glyph = int(rng.integers(8, 23))
        for _ in range(n_glyph):
            gx = int(rng.uniform(0.06, 0.94) * w)
            gy = int(rng.uniform(0.06, 0.94) * h)
            kind = int(rng.integers(0, 4))
            R_glyph = float(rng.uniform(0.55, 0.92))
            M_glyph = float(rng.uniform(0.10, 0.40))
            CC_glyph = float(rng.uniform(0.25, 0.85))
            if kind == 0:  # concentric circles
                base_r = max(3, int(rng.uniform(4.0, 7.0) * scale * 0.7))
                for k in range(int(rng.integers(2, 4))):
                    rr = base_r + k * max(1, int(scale))
                    _cv2.circle(M, (gx, gy), rr, M_glyph, 1, lineType=_cv2.LINE_AA)
                    _cv2.circle(R_ch, (gx, gy), rr, R_glyph, 1, lineType=_cv2.LINE_AA)
                    _cv2.circle(CC, (gx, gy), rr, CC_glyph, 1, lineType=_cv2.LINE_AA)
            elif kind == 1:  # crosshair rosette (8-spoke star)
                r_outer = max(4, int(rng.uniform(5.0, 7.0) * scale * 0.7))
                for spoke in range(8):
                    a = spoke * (np.pi / 4.0)
                    xe = int(gx + np.cos(a) * r_outer); ye = int(gy + np.sin(a) * r_outer)
                    _cv2.line(M, (gx, gy), (xe, ye), M_glyph, 1, lineType=_cv2.LINE_AA)
                    _cv2.line(R_ch, (gx, gy), (xe, ye), R_glyph, 1, lineType=_cv2.LINE_AA)
                    _cv2.line(CC, (gx, gy), (xe, ye), CC_glyph, 1, lineType=_cv2.LINE_AA)
            elif kind == 2:  # square brackets
                r_b = max(3, int(rng.uniform(4.0, 6.0) * scale * 0.7))
                _cv2.rectangle(M, (gx - r_b, gy - r_b), (gx + r_b, gy + r_b), M_glyph, 1, lineType=_cv2.LINE_AA)
                _cv2.rectangle(R_ch, (gx - r_b, gy - r_b), (gx + r_b, gy + r_b), R_glyph, 1, lineType=_cv2.LINE_AA)
                _cv2.rectangle(CC, (gx - r_b, gy - r_b), (gx + r_b, gy + r_b), CC_glyph, 1, lineType=_cv2.LINE_AA)
            else:  # asterisk
                r_a = max(3, int(rng.uniform(4.0, 6.0) * scale * 0.7))
                for spoke in range(6):
                    a = spoke * (np.pi / 3.0)
                    x1 = int(gx + np.cos(a) * r_a); y1 = int(gy + np.sin(a) * r_a)
                    x2 = int(gx - np.cos(a) * r_a); y2 = int(gy - np.sin(a) * r_a)
                    _cv2.line(R_ch, (x1, y1), (x2, y2), R_glyph, 1, lineType=_cv2.LINE_AA)
                    _cv2.line(M, (x1, y1), (x2, y2), M_glyph, 1, lineType=_cv2.LINE_AA)
                    _cv2.line(CC, (x1, y1), (x2, y2), CC_glyph, 1, lineType=_cv2.LINE_AA)

        # (C2) NEW HERO (tick 55) â€” SERIAL DATA-MATRIX BARCODE INSERTS
        # Sells programmed-laser-graphics identity with industrial part-numbers.
        n_barcode = int(rng.integers(3, 8))
        for _ in range(n_barcode):
            bw_cells = int(rng.integers(5, 8))   # 5-7 wide
            bh_cells = int(rng.integers(3, 5))   # 3-4 tall
            cell_px = max(2, int(rng.uniform(2.0, 3.5) * scale))
            bw = bw_cells * cell_px
            bh = bh_cells * cell_px
            bx0 = int(rng.uniform(0.04, 0.96) * w - bw / 2)
            by0 = int(rng.uniform(0.04, 0.96) * h - bh / 2)
            bx1 = bx0 + bw; by1 = by0 + bh
            if bx0 < 1 or by0 < 1 or bx1 >= w - 1 or by1 >= h - 1:
                continue
            # Bright bounding rectangle border
            _cv2.rectangle(M, (bx0 - 1, by0 - 1), (bx1 + 1, by1 + 1),
                           float(rng.uniform(0.78, 0.98)), 1, lineType=_cv2.LINE_AA)
            _cv2.rectangle(R_ch, (bx0 - 1, by0 - 1), (bx1 + 1, by1 + 1),
                           float(rng.uniform(0.06, 0.22)), 1, lineType=_cv2.LINE_AA)
            _cv2.rectangle(CC, (bx0 - 1, by0 - 1), (bx1 + 1, by1 + 1),
                           float(rng.uniform(0.50, 0.92)), 1, lineType=_cv2.LINE_AA)
            # Per-cell randomized burnt dots / bars
            for cj in range(bh_cells):
                for ci in range(bw_cells):
                    if rng.random() < 0.5:
                        continue
                    cell_x = bx0 + ci * cell_px
                    cell_y = by0 + cj * cell_px
                    cx_end = min(bx1 - 1, cell_x + cell_px - 1)
                    cy_end = min(by1 - 1, cell_y + cell_px - 1)
                    if cx_end <= cell_x or cy_end <= cell_y:
                        continue
                    cM = float(rng.uniform(0.10, 0.38))
                    cR = float(rng.uniform(0.55, 0.95))
                    cCC = float(rng.uniform(0.30, 0.92))
                    _cv2.rectangle(M, (cell_x, cell_y), (cx_end, cy_end), cM, -1, lineType=_cv2.LINE_AA)
                    _cv2.rectangle(R_ch, (cell_x, cell_y), (cx_end, cy_end), cR, -1, lineType=_cv2.LINE_AA)
                    _cv2.rectangle(CC, (cell_x, cell_y), (cx_end, cy_end), cCC, -1, lineType=_cv2.LINE_AA)

        # (D) Four families of micro-hatch fill cuts
        for family_seed, ang_base in [(101, 0.18), (103, -0.36), (107, 1.04), (113, 1.95)]:
            rng_f = np.random.default_rng(int(seed) + family_seed + 9000)
            n_cut = int(np.clip(700 * scale * scale, 350, 1900))
            for _ in range(n_cut):
                cx = rng_f.uniform(0, w); cy = rng_f.uniform(0, h)
                length = float(rng_f.uniform(5.0, 14.0) * scale)
                ang = ang_base + float(rng_f.normal(0.0, 0.06))
                x0s = int(cx - np.cos(ang) * length * 0.5)
                y0s = int(cy - np.sin(ang) * length * 0.5)
                x1s = int(cx + np.cos(ang) * length * 0.5)
                y1s = int(cy + np.sin(ang) * length * 0.5)
                _cv2.line(M, (x0s, y0s), (x1s, y1s), float(rng_f.uniform(0.15, 0.55)), 1, lineType=_cv2.LINE_AA)
                _cv2.line(R_ch, (x0s, y0s), (x1s, y1s), float(rng_f.uniform(0.55, 0.94)), 1, lineType=_cv2.LINE_AA)
                _cv2.line(CC, (x0s, y0s), (x1s, y1s), float(rng_f.uniform(0.20, 0.78)), 1, lineType=_cv2.LINE_AA)

    # (E) 2 px scribe-tooth micro-hatch baseline
    hatch_a = np.sin((xx + yy) / 2.2 * 2.0 * np.pi)
    hatch_b = np.sin((xx - yy) / 2.2 * 2.0 * np.pi)
    micro = (np.maximum(hatch_a, hatch_b) > 0.0).astype(np.float32)
    M = np.clip(M + (micro - 0.5) * 0.08, 0, 1)
    R_ch = np.clip(R_ch - (micro - 0.5) * 0.06, 0, 1)
    CC = np.clip(CC + (micro - 0.5) * 0.06, 0, 1)

    # (F) Bright melt-bead pinpoints
    n_bead = int(np.clip(mn * mn / 60.0, 3000, 14000))
    by = rng.integers(0, h, n_bead); bx = rng.integers(0, w, n_bead)
    M[by, bx] = rng.uniform(0.65, 0.99, n_bead).astype(np.float32)
    R_ch[by, bx] = rng.uniform(0.02, 0.18, n_bead).astype(np.float32)
    CC[by, bx] = rng.uniform(0.55, 0.99, n_bead).astype(np.float32)

    # (G) Dark recast-slag micro-spots
    n_slag = int(np.clip(mn * mn / 110.0, 1500, 8000))
    sly = rng.integers(0, h, n_slag); slx = rng.integers(0, w, n_slag)
    M[sly, slx] = rng.uniform(0.05, 0.25, n_slag).astype(np.float32)
    R_ch[sly, slx] = rng.uniform(0.62, 0.95, n_slag).astype(np.float32)
    CC[sly, slx] = rng.uniform(0.15, 0.42, n_slag).astype(np.float32)

    out = np.stack([M, R_ch, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
spec_laser_etched._spb_concept_complete = True


def spec_liquid_metal(shape, seed, sm, wave1_freq=0.8, wave2_freq=1.3, amplitude=0.04, **kwargs):
    """spec_liquid_metal.

    identity: Round-6 CREATIVE rebuild â€” mercury/gallium pooled substrate
    with capillary sine ripples + bead droplets (body + rim + hot-point) +
    beadlets + debris + sparkle carpet. NEW hero motifs: (1) MERCURY VEIN
    SPLITS â€” 3-6 sinuous bright-meniscus catwalks 20-60 px long where two
    pools just connected, drawn as anti-aliased curve polylines with a
    bright rim and dark central trough; (2) per-cluster MENISCUS BLOOM â€”
    a soft radial brighten centered on dense bead clusters that sells
    surface tension. Per-feature INDEPENDENT M/R/CC continuous uniforms,
    fine features 1-12 px (veins up to 60 px length but 1-2 px thick).
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 51382)
    scale = max(min(h, w) / 2048.0, 0.25)
    mn = min(h, w)
    yy = np.arange(h, dtype=np.float32).reshape(h, 1)
    xx = np.arange(w, dtype=np.float32).reshape(1, w)

    # 1) Mercury substrate
    fbm_M = _normalize(multi_scale_noise(shape, [3.0, 9.0, 22.0], [0.45, 0.32, 0.23], int(seed) + 51383))
    fbm_R = _normalize(multi_scale_noise(shape, [4.0, 11.0, 26.0], [0.45, 0.32, 0.23], int(seed) + 51384))
    # Dense capillary ripple stack â€” 4 wave families
    cap_a = np.sin(xx * 0.42 + yy * 0.18 + int(seed) * 0.011) * 0.5 + 0.5
    cap_b = np.sin(xx * 0.27 - yy * 0.33 + int(seed) * 0.017) * 0.5 + 0.5
    cap_c = np.sin(xx * 0.58 + yy * 0.31 + int(seed) * 0.023) * 0.5 + 0.5
    cap_d = np.sin(xx * 0.15 - yy * 0.49 + int(seed) * 0.029) * 0.5 + 0.5
    cap = (cap_a + cap_b + cap_c + cap_d) * 0.25
    M  = (0.78 + (fbm_M - 0.5) * 0.18 + (cap - 0.5) * 0.14).astype(np.float32)
    R  = (0.14 + (fbm_R - 0.5) * 0.14 - (cap - 0.5) * 0.10).astype(np.float32)
    CC = (0.12 + (cap - 0.5) * 0.14 + (fbm_M - 0.5) * 0.10).astype(np.float32)
    M = np.clip(M, 0, 1); R = np.clip(R, 0, 1); CC = np.clip(CC, 0, 1)

    if _CV2_OK:
        # 2) BEAD DROPLETS â€” 5x density, each with rim halo + hot-point
        n_bead = int(np.clip(11000 * (mn / 2048.0) ** 2, 3800, 24000))
        for _ in range(n_bead):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            r_b = int(max(2, rng.uniform(4.0, 12.0) * scale * 0.5))
            bM = float(rng.uniform(0.58, 0.98))
            bR = float(rng.uniform(0.04, 0.30))
            bCC = float(rng.uniform(0.04, 0.42))
            _cv2.circle(M, (cx, cy), r_b, bM, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r_b, bR, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r_b, bCC, -1, lineType=_cv2.LINE_AA)
            # Rim halo
            rM = float(rng.uniform(0.65, 0.95))
            rR = float(rng.uniform(0.18, 0.50))
            _cv2.circle(M, (cx, cy), r_b + 1, rM, 1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r_b + 1, rR, 1, lineType=_cv2.LINE_AA)
            # Hot-point (1 px ultra-bright)
            off = max(1, r_b // 3)
            _cv2.circle(M, (cx - off, cy - off), 1, 0.99, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx - off, cy - off), 1, 0.02, -1, lineType=_cv2.LINE_AA)

        # 3) FINER MERCURY BEADLETS â€” tiny 1-3 px secondary beads
        n_small = int(np.clip(7000 * (mn / 2048.0) ** 2, 2200, 15000))
        for _ in range(n_small):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            r = max(1, int(rng.uniform(1.0, 3.0) * scale * 0.5))
            sM = float(rng.uniform(0.68, 0.99))
            sR = float(rng.uniform(0.02, 0.20))
            sCC = float(rng.uniform(0.02, 0.24))
            _cv2.circle(M, (cx, cy), r, sM, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r, sR, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r, sCC, -1, lineType=_cv2.LINE_AA)

        # 4) DARK DEBRIS SPECKS â€” tiny dust on surface (1-2 px)
        n_dust = int(np.clip(2200 * (mn / 2048.0) ** 2, 700, 5500))
        for _ in range(n_dust):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            r = max(1, int(rng.uniform(1.0, 2.0) * scale))
            _cv2.circle(M, (cx, cy), r, float(rng.uniform(0.08, 0.30)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r, float(rng.uniform(0.50, 0.88)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r, float(rng.uniform(0.32, 0.70)), -1, lineType=_cv2.LINE_AA)

    # 5) SURFACE-TENSION SPARKLE â€” full canvas
    n_sp = int(np.clip(mn * mn / 60.0, 4000, 14000))
    sy = rng.integers(0, h, n_sp); sx = rng.integers(0, w, n_sp)
    M[sy, sx] = np.maximum(M[sy, sx], rng.uniform(0.68, 0.99, n_sp).astype(np.float32))
    CC[sy, sx] = np.minimum(CC[sy, sx], rng.uniform(0.02, 0.20, n_sp).astype(np.float32))
    R[sy, sx] = np.minimum(R[sy, sx], rng.uniform(0.02, 0.18, n_sp).astype(np.float32))

    if _CV2_OK:
        # 6) MERCURY VEIN SPLITS â€” bright meniscus catwalks where two pools
        # joined. Sinuous polyline with bright rim + dark inner trough.
        n_vein = int(rng.integers(3, 7))
        for _ in range(n_vein):
            cx = float(rng.uniform(0.1, 0.9) * w); cy = float(rng.uniform(0.1, 0.9) * h)
            ang = float(rng.uniform(0, 2 * np.pi))
            length = float(rng.uniform(20.0, 60.0))
            steps = 24
            pts = []
            tortuosity = float(rng.uniform(0.6, 1.4))
            for k in range(steps):
                t = (k / (steps - 1)) - 0.5
                # add sine wiggle perpendicular to vein direction
                wobble = np.sin(t * np.pi * 2 * tortuosity + int(seed) * 0.07) * 3.0
                nx_ = -np.sin(ang); ny_ = np.cos(ang)
                px_ = int(cx + np.cos(ang) * t * length + nx_ * wobble)
                py_ = int(cy + np.sin(ang) * t * length + ny_ * wobble)
                pts.append([px_, py_])
            poly = np.array([pts], dtype=np.int32)
            mB = float(rng.uniform(0.78, 0.99))
            mR_ = float(rng.uniform(0.02, 0.14))
            mCC = float(rng.uniform(0.04, 0.30))
            _cv2.polylines(M, poly, False, mB, 2, lineType=_cv2.LINE_AA)
            _cv2.polylines(R, poly, False, mR_, 2, lineType=_cv2.LINE_AA)
            _cv2.polylines(CC, poly, False, mCC, 2, lineType=_cv2.LINE_AA)
            # central trough â€” 1 px dimmer line
            _cv2.polylines(M, poly, False, float(rng.uniform(0.30, 0.55)), 1, lineType=_cv2.LINE_AA)

        # 7) MENISCUS BLOOM â€” sparse soft radial brighten
        n_bloom = int(rng.integers(4, 9))
        for _ in range(n_bloom):
            bx = int(rng.uniform(0.1, 0.9) * w); by_ = int(rng.uniform(0.1, 0.9) * h)
            br = int(rng.uniform(8, 14))
            _cv2.circle(M, (bx, by_), br, float(rng.uniform(0.60, 0.85)), 1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (bx, by_), br, float(rng.uniform(0.35, 0.75)), 1, lineType=_cv2.LINE_AA)

    out = np.stack([M, R, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
spec_liquid_metal._spb_concept_complete = True


def spec_chameleon_flake(shape, seed, sm, cell_density=28.0, metallic_base=190, **kwargs):
    """Chameleon color-shift flake â€” angle-dependent iridescent paint.

    identity: paint with flake particles whose APPARENT COLOR varies with
    viewing angle (chameleon / flip paint). M is uniformly high (flake is
    metallic), R varies per-flake (some catch light, some don't), and CC
    is the IDENTITY of this finish â€” it encodes the spectral angle-shift
    via wide-range continuous values so the live preview shows real
    rainbow-banding in the clearcoat channel.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 11200)
    yy, xx = np.mgrid[0:h, 0:w].astype(np.float32)

    # SPECTRAL SHIFT FIELD â€” broad FBM-warped projection produces band-like color
    # zones across the canvas. This is the CC-channel star.
    if _CV2_OK:
        sh = max(64, h // 8); sw = max(64, w // 8)
        warp_n = rng.random((sh, sw)).astype(np.float32)
        warp_b = _cv2.GaussianBlur(warp_n, (0, 0), sigmaX=6.0, sigmaY=6.0)
        warp = _cv2.resize(warp_b, (w, h), interpolation=_cv2.INTER_CUBIC).astype(np.float32)
    else:
        warp = multi_scale_noise(shape, [40, 80], [0.6, 0.4], int(seed) + 11201)
    warp = _normalize(warp)
    # Spectral phase â€” combine x-band + y-band warped by FBM
    ang = float(rng.uniform(0.3, 1.4))
    phase = (yy * np.sin(ang) + xx * np.cos(ang)) / max(min(h, w), 1) + warp * 1.4
    # Three spectral channels for visible iridescent banding
    band_r = np.sin(phase * 12.0 + rng.uniform(0, 2*np.pi)) * 0.5 + 0.5
    band_g = np.sin(phase * 13.5 + rng.uniform(0, 2*np.pi)) * 0.5 + 0.5
    band_b = np.sin(phase * 15.0 + rng.uniform(0, 2*np.pi)) * 0.5 + 0.5
    cc_spectral = (band_r * 0.34 + band_g * 0.34 + band_b * 0.32)

    # Flake particle field (visible chrome dots across whole canvas)
    grain = _spb_fast_hash_grid(shape, int(seed) + 261)
    flake = (grain > 0.86).astype(np.float32)  # dense bright flake
    flake_hot = (grain > 0.972).astype(np.float32)
    # M channel: uniformly metallic with extra brightness on flake spots
    M = (0.62 + flake * 0.20 + flake_hot * 0.18 + warp * 0.10).astype(np.float32)
    # R channel: low overall (smooth chrome flake) but VARIES per flake
    R_ch = (0.32 - flake * 0.15 + warp * 0.18 + (1.0 - cc_spectral) * 0.15).astype(np.float32)
    # CC channel: spectral progression â€” VISIBLE color shift bands + flake gloss
    CC = (cc_spectral * 0.70 + 0.18 + flake * 0.12).astype(np.float32)

    # Random per-pixel flake jitter so each flake catches different light
    pixel_jitter = rng.uniform(-0.05, 0.05, shape).astype(np.float32)
    M = M + pixel_jitter * 0.5
    CC = CC + pixel_jitter * 0.6

    out = np.stack([np.clip(M, 0, 1), np.clip(R_ch, 0, 1), np.clip(CC, 0, 1)], axis=2).astype(np.float32)
    if sm != 1.0:
        out = out * float(sm) + 0.5 * (1.0 - float(sm))
    return np.clip(out, 0, 1).astype(np.float32)


def spec_xirallic_crystal(shape, seed, sm, cell_density=14.0, **kwargs):
    """Xirallic crystal pigment â€” dense spectral-rainbow crystal flake field.

    identity: A Merck xirallic-style crystal-pigment finish â€” thousands of
    4-12 px crystal flakes (hex/parallelogram facets) sit on a dark binder
    base, each flake carrying INDEPENDENT high-M, low-R, and a full
    spectral-rainbow CC pick so the population reads like a chromatic
    sparkle. A subset of flakes also stamps a dim outer halo ring for
    secondary glints, and a single-pixel sparkle scatter fills the gaps.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 282)
    scale = max(min(h, w) / 2048.0, 0.25)
    def _fbm(off, sigma):
        if _CV2_OK:
            sh = max(64, h // 10); sw = max(64, w // 10)
            n = np.random.default_rng(int(seed) + off).random((sh, sw)).astype(np.float32)
            b = _cv2.GaussianBlur(n, (0, 0), sigmaX=sigma, sigmaY=sigma)
            return _normalize(_cv2.resize(b, (w, h), interpolation=_cv2.INTER_CUBIC).astype(np.float32))
        return _normalize(multi_scale_noise(shape, [20, 40], [0.6, 0.4], int(seed) + off))
    # Dark crystal-pigment binder base â€” M moderate, R moderate, CC moderate
    M = (0.32 + (_fbm(291, 5.0) - 0.5) * 0.18).astype(np.float32)
    R_ch = (0.55 + (_fbm(293, 5.0) - 0.5) * 0.20).astype(np.float32)
    CC = (0.42 + (_fbm(295, 5.0) - 0.5) * 0.22).astype(np.float32)
    if _CV2_OK:
        # Dense crystal flakes â€” 4-12 px, hexagonal/parallelogram (polygon stamps)
        n_flake = max(20000, int(h * w / 35))
        # Per-flake: very high M, very low R, CC samples FULL spectral rainbow
        # Pre-sample arrays
        fcx = rng.uniform(0, w, n_flake)
        fcy = rng.uniform(0, h, n_flake)
        frr = (rng.uniform(2.0, 6.0, n_flake) * scale).astype(np.float32)  # half-size 2-6 â†’ diameter 4-12
        fM = rng.uniform(0.70, 0.99, n_flake).astype(np.float32)
        fR = rng.uniform(0.04, 0.20, n_flake).astype(np.float32)
        fCC = rng.uniform(0.08, 0.98, n_flake).astype(np.float32)  # full spectral rainbow
        fang = rng.uniform(0.0, 2 * np.pi, n_flake).astype(np.float32)
        # Use circles for speed but with small per-flake random shape
        # to keep doctrine-fast, plus halo for some
        for i in range(n_flake):
            r_i = max(1, int(frr[i]))
            ci = (int(fcx[i]), int(fcy[i]))
            _cv2.circle(M, ci, r_i, float(fM[i]), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R_ch, ci, r_i, float(fR[i]), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, ci, r_i, float(fCC[i]), -1, lineType=_cv2.LINE_AA)
        # A subset gets bright surrounding dim halos
        n_halo = max(2000, int(h * w / 700))
        for _ in range(n_halo):
            ci = (int(rng.integers(0, w)), int(rng.integers(0, h)))
            r_h = max(2, int(rng.uniform(4.0, 10.0) * scale))
            # halo ring (low-amplitude bright)
            _cv2.circle(M, ci, r_h, float(rng.uniform(0.45, 0.75)), 1, lineType=_cv2.LINE_AA)
            _cv2.circle(R_ch, ci, r_h, float(rng.uniform(0.10, 0.30)), 1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, ci, r_h, float(rng.uniform(0.20, 0.95)), 1, lineType=_cv2.LINE_AA)
        # Single-pixel sparkle scatter
        n_sp = max(10000, int(h * w / 60))
        sy = rng.integers(0, h, n_sp); sx = rng.integers(0, w, n_sp)
        M[sy, sx] = np.maximum(M[sy, sx], rng.uniform(0.72, 0.99, n_sp).astype(np.float32))
        R_ch[sy, sx] = np.minimum(R_ch[sy, sx], rng.uniform(0.04, 0.20, n_sp).astype(np.float32))
        CC[sy, sx] = np.maximum(CC[sy, sx], rng.uniform(0.08, 0.98, n_sp).astype(np.float32))
    out = np.stack([np.clip(M, 0, 1), np.clip(R_ch, 0, 1), np.clip(CC, 0, 1)], axis=2).astype(np.float32)
    if sm != 1.0:
        out = out * float(sm) + 0.5 * (1.0 - float(sm))
    return np.clip(out, 0, 1).astype(np.float32)


def spec_holographic_foil(shape, seed, sm, grating1_freq=55.0, grating2_freq=48.0, **kwargs):
    """spec_holographic_foil â€” R6 fix: DEPTH & FEEL, not random dots.

    identity: R6 owner-fix rebuild â€” owner said the prior version "looks
    like random dots", needs "real depth and feel". New build leads with
    SMOOTH continuous iridescence layers so the eye reads volume:
    1) FOIL SUBSTRATE â€” bright mirror M with crinkle FBM displacement so it
       has CREASE depth (low-freq M warp + crisp ridge highlights).
    2) DIFFRACTION GRATINGS â€” three crossed fine sin gratings (5-9 px pitch)
       producing the spectral cycle on CC, NOT painted as dots.
    3) HERO RAINBOW RIBBONS â€” 4-7 long curved swept arcs with smoothly
       cycling spectral CC across the canvas â€” the signature "flowing
       hologram" look.
    4) CREASE / FOLD LINES â€” bright catchpoints along the foil creases
       (8-22 px short ridges following the substrate displacement).
    5) PRISMATIC FACET SHARDS â€” small 6-14 px triangular shards with
       INDEPENDENT M/R/CC, sparser than before so they ACCENT not dominate.
    6) Micro spectral fleck carpet â€” restrained, no longer the lead.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + (hash('spec_holographic_foil_r6') % 100000))
    mn = float(min(h, w))
    scale = max(mn / 256.0, 0.6)
    yy = np.arange(h, dtype=np.float32).reshape(h, 1)
    xx = np.arange(w, dtype=np.float32).reshape(1, w)

    # FOIL SUBSTRATE â€” bright mirror M with low-freq CRINKLE for depth
    fbm_M_lo = _normalize(multi_scale_noise(shape, [12.0, 26.0, 48.0], [0.5, 0.3, 0.2], int(seed) + 31))
    fbm_M_hi = _normalize(multi_scale_noise(shape, [3.0, 9.0, 20.0],   [0.5, 0.3, 0.2], int(seed) + 51))
    # Low-freq carries depth; hi-freq carries micro-texture
    M = (0.78 + (fbm_M_lo - 0.5) * 0.18 + (fbm_M_hi - 0.5) * 0.10).astype(np.float32)
    R_ch = np.full((h, w), 0.16, dtype=np.float32)
    R_ch += (_normalize(multi_scale_noise(shape, [3.0, 10.0, 22.0], [0.5, 0.3, 0.2], int(seed) + 71)) - 0.5) * 0.16
    R_ch += (fbm_M_lo - 0.5) * 0.08  # crease shadows
    R_ch = np.clip(R_ch, 0, 1)

    # Crease ridge field â€” sharp peaks where crinkle has steep slope
    if _CV2_OK:
        sob_x = _cv2.Sobel(fbm_M_lo, _cv2.CV_32F, 1, 0, ksize=3)
        sob_y = _cv2.Sobel(fbm_M_lo, _cv2.CV_32F, 0, 1, ksize=3)
        crease = np.sqrt(sob_x * sob_x + sob_y * sob_y)
        crease = _normalize(crease)
    else:
        crease = np.zeros((h, w), dtype=np.float32)
    # Bright catchpoints along creases (depth cue)
    M = np.clip(M + crease * 0.18, 0, 1)
    R_ch = np.clip(R_ch - crease * 0.08, 0, 1)

    # DIFFRACTION GRATINGS â€” three crossed sin gratings drive CC spectrum
    pitch1 = float(rng.uniform(5.0, 7.0))
    pitch2 = float(rng.uniform(6.0, 8.0))
    pitch3 = float(rng.uniform(7.0, 9.0))
    g1 = np.sin(xx * (2.0 * np.pi / pitch1) + float(rng.uniform(0, 2 * np.pi))) * 0.5 + 0.5
    g2 = np.sin((xx + yy) * (2.0 * np.pi / pitch2) + float(rng.uniform(0, 2 * np.pi))) * 0.5 + 0.5
    g3 = np.sin((xx - yy) * (2.0 * np.pi / pitch3) + float(rng.uniform(0, 2 * np.pi))) * 0.5 + 0.5
    spec_fbm = _normalize(multi_scale_noise(shape, [4.0, 14.0, 30.0], [0.45, 0.35, 0.20], int(seed) + 91))
    # CC is dominated by the smooth grating cycle (NOT dots)
    CC = (0.08 + g1 * 0.32 + g2 * 0.26 + g3 * 0.22 + spec_fbm * 0.14).astype(np.float32)
    # Spectral hue shifts with crinkle depth â€” extra depth feel
    CC = np.clip(CC + (fbm_M_lo - 0.5) * 0.25, 0, 1)

    if _CV2_OK:
        # Pass A â€” grating line fragments at 4 angles, INDEPENDENT M/R/CC per cut
        n_per_angle = int(np.clip(800 * scale * scale, 400, 2200))
        for ang_base in (0.0, np.pi * 0.25, np.pi * 0.5, np.pi * 0.75):
            for _ in range(n_per_angle):
                cx = rng.uniform(0, w); cy = rng.uniform(0, h)
                length = float(rng.uniform(4.0, 12.0) * scale)
                ang = ang_base + float(rng.normal(0.0, 0.05))
                x0s = int(cx - np.cos(ang) * length * 0.5)
                y0s = int(cy - np.sin(ang) * length * 0.5)
                x1s = int(cx + np.cos(ang) * length * 0.5)
                y1s = int(cy + np.sin(ang) * length * 0.5)
                _cv2.line(M, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.55, 0.99)), 1, lineType=_cv2.LINE_AA)
                _cv2.line(R_ch, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.02, 0.30)), 1, lineType=_cv2.LINE_AA)
                _cv2.line(CC, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.04, 0.99)), 1, lineType=_cv2.LINE_AA)
        # Pass B â€” tear-edge dark stipple (REDUCED count vs prior rebuild)
        n_tear = int(np.clip(600 * scale * scale, 300, 1500))
        for _ in range(n_tear):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            r_t = max(1, int(rng.uniform(1.4, 3.2)))
            _cv2.circle(M, (cx, cy), r_t, float(rng.uniform(0.12, 0.38)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R_ch, (cx, cy), r_t, float(rng.uniform(0.45, 0.85)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r_t, float(rng.uniform(0.10, 0.50)), -1, lineType=_cv2.LINE_AA)

        # Pass B2 NEW â€” CREASE FOLD LINES: short bright 8-22 px ridges
        # along the high-crease zones so creases READ as folds, giving depth.
        ys_c, xs_c = np.where(crease > 0.55)
        if len(ys_c) > 200:
            sel = rng.choice(len(ys_c), size=min(len(ys_c), int(2200 * scale * scale)), replace=False)
            crease_angle_field = np.arctan2(sob_y + 1e-7, sob_x + 1e-7)  # perpendicular to gradient
            for idx in sel:
                cy_c = int(ys_c[idx]); cx_c = int(xs_c[idx])
                a = float(crease_angle_field[cy_c, cx_c]) + np.pi * 0.5  # along the ridge
                length = float(rng.uniform(8.0, 22.0) * scale)
                x0c = int(cx_c - np.cos(a) * length * 0.5)
                y0c = int(cy_c - np.sin(a) * length * 0.5)
                x1c = int(cx_c + np.cos(a) * length * 0.5)
                y1c = int(cy_c + np.sin(a) * length * 0.5)
                _cv2.line(M,    (x0c, y0c), (x1c, y1c), float(rng.uniform(0.82, 0.99)), 1, lineType=_cv2.LINE_AA)
                _cv2.line(R_ch, (x0c, y0c), (x1c, y1c), float(rng.uniform(0.02, 0.14)), 1, lineType=_cv2.LINE_AA)
                _cv2.line(CC,   (x0c, y0c), (x1c, y1c), float(rng.uniform(0.10, 0.95)), 1, lineType=_cv2.LINE_AA)

        # Pass C-NEW â€” HERO RAINBOW RIBBON SWEEPS: 3-5 long curved bands
        # crossing the canvas with smoothly-cycling spectral CC, mimicking a
        # holographic foil's signature flowing rainbow.
        n_ribbon = int(rng.integers(3, 6))
        for _r in range(n_ribbon):
            # ribbon defined as a wide circle arc with HUGE radius and small sweep
            rib_r = float(rng.uniform(1.6, 3.2)) * max(h, w)
            rib_cx = float(rng.uniform(-rib_r * 0.4, w + rib_r * 0.4))
            rib_cy = float(rng.uniform(h * 0.5, h * 2.2)) * float(rng.choice([1.0, -1.0]))
            band_a0 = float(rng.uniform(0, 360))
            band_sweep = float(rng.uniform(10.0, 30.0))
            band_thick = max(2, int(rng.uniform(3.0, 7.0) * scale))
            # draw the band as ~24 short consecutive sub-arcs each with a stepped CC color
            steps = 28
            base_cc_phase = float(rng.uniform(0, 2 * np.pi))
            for k in range(steps):
                fa = band_a0 + band_sweep * (k / steps)
                fa2 = band_a0 + band_sweep * ((k + 1) / steps)
                cc_val = 0.20 + 0.78 * (0.5 + 0.5 * np.sin(base_cc_phase + k * 0.55))
                m_val = float(rng.uniform(0.78, 0.99))
                r_val = float(rng.uniform(0.04, 0.20))
                _cv2.ellipse(M, (int(rib_cx), int(rib_cy)), (int(rib_r), int(rib_r)),
                             0.0, fa, fa2, m_val, band_thick, lineType=_cv2.LINE_AA)
                _cv2.ellipse(R_ch, (int(rib_cx), int(rib_cy)), (int(rib_r), int(rib_r)),
                             0.0, fa, fa2, r_val, band_thick, lineType=_cv2.LINE_AA)
                _cv2.ellipse(CC, (int(rib_cx), int(rib_cy)), (int(rib_r), int(rib_r)),
                             0.0, fa, fa2, float(cc_val), band_thick, lineType=_cv2.LINE_AA)

        # Pass D-NEW â€” PRISMATIC FACET SHARDS: small triangular bright shards
        # (6-14 px) scattered across the canvas, each a distinct spectral identity.
        n_shard = int(np.clip(420 * (mn / 2048.0) ** 2, 140, 1100))
        for _ in range(n_shard):
            sx0 = int(rng.uniform(4, w - 4)); sy0 = int(rng.uniform(4, h - 4))
            size_s = float(rng.uniform(6.0, 14.0) * scale)
            ang = float(rng.uniform(0, 2 * np.pi))
            pts = np.array([
                [sx0, sy0],
                [int(sx0 + np.cos(ang) * size_s), int(sy0 + np.sin(ang) * size_s)],
                [int(sx0 + np.cos(ang + 2.1) * size_s * 0.7),
                 int(sy0 + np.sin(ang + 2.1) * size_s * 0.7)],
            ], dtype=np.int32)
            m_s = float(rng.uniform(0.78, 0.99))
            r_s = float(rng.uniform(0.03, 0.18))
            cc_s = float(rng.uniform(0.05, 0.99))
            _cv2.fillPoly(M, [pts], m_s, lineType=_cv2.LINE_AA)
            _cv2.fillPoly(R_ch, [pts], r_s, lineType=_cv2.LINE_AA)
            _cv2.fillPoly(CC, [pts], cc_s, lineType=_cv2.LINE_AA)

    # Pass E â€” RESTRAINED single-pixel rainbow micro-sparkle (no longer the lead)
    n_sp = int(np.clip(mn * mn / 180.0, 1200, 5000))
    sy = rng.integers(0, h, n_sp); sx = rng.integers(0, w, n_sp)
    M[sy, sx] = rng.uniform(0.62, 0.99, n_sp).astype(np.float32)
    R_ch[sy, sx] = rng.uniform(0.02, 0.25, n_sp).astype(np.float32)
    CC[sy, sx] = rng.uniform(0.02, 0.99, n_sp).astype(np.float32)

    out = np.stack([M, R_ch, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
spec_holographic_foil._spb_concept_complete = True


def spec_oil_film_thick(shape, seed, sm, num_pools=6, **kwargs):
    """Thick oil film â€” fine iridescent droplet field, NO panel-scale pools.

    identity: A puddle of motor oil seen at close range â€” hundreds of FINE
    iridescent droplet pools (each 8-26 px) packed tight across the canvas,
    each with INDEPENDENT M/R/CC continuous draws so neighbors show wildly
    contrasting spectral identities. Between them: a relentless mid layer
    of 4-10 px sub-pools, a single-pixel spectral fleck carpet, and short
    4-12 px filament drag streaks. Owner fix R6: shrunk macros 4x to enforce
    8-32 px owner-eye rule.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 327)
    scale = max(min(h, w) / 2048.0, 0.25)
    px_unit = max(scale, 0.7)

    def _fbm(off, sigma):
        if _CV2_OK:
            sh = max(64, h // 10); sw = max(64, w // 10)
            n = np.random.default_rng(int(seed) + off).random((sh, sw)).astype(np.float32)
            b = _cv2.GaussianBlur(n, (0, 0), sigmaX=sigma, sigmaY=sigma)
            return _normalize(_cv2.resize(b, (w, h), interpolation=_cv2.INTER_CUBIC).astype(np.float32))
        return _normalize(multi_scale_noise(shape, [20, 40], [0.6, 0.4], int(seed) + off))

    # Independent per-channel FBM ground (no flat substrate)
    fbm_M = _fbm(328, 5.0); fbm_R = _fbm(330, 4.0); fbm_CC = _fbm(332, 6.0)
    M = (0.40 + (fbm_M - 0.5) * 0.30).astype(np.float32)
    R_ch = (0.55 + (fbm_R - 0.5) * 0.34).astype(np.float32)
    CC = (0.45 + (fbm_CC - 0.5) * 0.50).astype(np.float32)

    if _CV2_OK:
        # PRIMARY POOLS â€” fine 8-26 px, very dense (tile densely instead of panel-scale)
        n_macro = max(700, int(h * w / 900))
        for _ in range(n_macro):
            cx = int(rng.uniform(0.0, 1.0) * w)
            cy = int(rng.uniform(0.0, 1.0) * h)
            rx = max(3, int(rng.uniform(4.0, 13.0) * px_unit))
            ry = max(3, int(rng.uniform(3.5, 11.0) * px_unit))
            ang_deg = float(rng.uniform(0, 180))
            pool_M = float(rng.uniform(0.50, 0.98))
            pool_R = float(rng.uniform(0.04, 0.32))
            pool_CC = float(rng.uniform(0.08, 0.96))
            _cv2.ellipse(M, (cx, cy), (rx, ry), ang_deg, 0, 360, pool_M, -1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(R_ch, (cx, cy), (rx, ry), ang_deg, 0, 360, pool_R, -1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(CC, (cx, cy), (rx, ry), ang_deg, 0, 360, pool_CC, -1, lineType=_cv2.LINE_AA)
            # Inner spectral band (contrasting CC inside same pool)
            if rx > 4 and ry > 4:
                inner_CC = float(rng.uniform(0.08, 0.96))
                _cv2.ellipse(CC, (cx, cy), (max(2, rx - 2), max(2, ry - 2)),
                             ang_deg, 0, 360, inner_CC, -1, lineType=_cv2.LINE_AA)

        # SUB POOLS â€” 4-10 px secondary cloud filling gaps, even denser
        n_mid = max(1800, int(h * w / 400))
        for _ in range(n_mid):
            cx = int(rng.uniform(0.0, 1.0) * w)
            cy = int(rng.uniform(0.0, 1.0) * h)
            rx = max(2, int(rng.uniform(2.0, 5.0) * px_unit))
            ry = max(2, int(rng.uniform(2.0, 5.0) * px_unit))
            ang_deg = float(rng.uniform(0, 180))
            _cv2.ellipse(M, (cx, cy), (rx, ry), ang_deg, 0, 360,
                         float(rng.uniform(0.55, 0.97)), -1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(R_ch, (cx, cy), (rx, ry), ang_deg, 0, 360,
                         float(rng.uniform(0.04, 0.32)), -1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(CC, (cx, cy), (rx, ry), ang_deg, 0, 360,
                         float(rng.uniform(0.08, 0.96)), -1, lineType=_cv2.LINE_AA)

        # MICRO DROPLETS â€” single-pixel spectral flecks, dense fill
        n_drop = max(9000, int(h * w / 90))
        dy = rng.integers(0, h, n_drop); dx = rng.integers(0, w, n_drop)
        M[dy, dx] = rng.uniform(0.55, 0.98, n_drop).astype(np.float32)
        R_ch[dy, dx] = rng.uniform(0.04, 0.32, n_drop).astype(np.float32)
        CC[dy, dx] = rng.uniform(0.08, 0.96, n_drop).astype(np.float32)

        # SHORT FILAMENT DRAGS â€” 4-12 px streaks (downsized from 8-22 px)
        n_stk = max(800, int(h * w / 1200))
        for _ in range(n_stk):
            cx = rng.uniform(2, w - 2); cy = rng.uniform(2, h - 2)
            length = float(rng.uniform(4.0, 12.0) * px_unit)
            ang = float(rng.uniform(0, 2 * np.pi))
            x0s = int(cx - np.cos(ang) * length * 0.5)
            y0s = int(cy - np.sin(ang) * length * 0.5)
            x1s = int(cx + np.cos(ang) * length * 0.5)
            y1s = int(cy + np.sin(ang) * length * 0.5)
            _cv2.line(M, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.60, 0.96)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.08, 0.96)), 1, lineType=_cv2.LINE_AA)

    out = np.stack([np.clip(M, 0, 1), np.clip(R_ch, 0, 1), np.clip(CC, 0, 1)], axis=2).astype(np.float32)
    return _sm_scale(np.clip(out, 0, 1), sm).astype(np.float32)
spec_oil_film_thick._spb_concept_complete = True

def _LEGACY_spec_oil_film_thick_dead(shape, seed, sm, num_pools=6, **kwargs):
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    if min(h, w) >= 512 and _CV2_OK:
        sh = (max(128, h // 2), max(128, w // 2))
        small = None  # dead
        up = small
        palette_of = np.array([0.18,0.28,0.38,0.48,0.58,0.68,0.78,0.92], dtype=np.float32)
        rng_of = np.random.default_rng(seed + 327)
        scale_of = max(min(h, w) / 2048.0, 0.25)
        n_l = int(np.clip(350 * (min(h, w) / 2048.0) ** 2, 120, 850))
        for _ in range(n_l):
            cx = rng_of.uniform(4, w - 4); cy = rng_of.uniform(4, h - 4)
            length = float(rng_of.uniform(5.0, 10.0) * scale_of)
            ang = float(rng_of.uniform(0, 2 * np.pi))
            x0s = int(cx - np.cos(ang) * length * 0.5)
            y0s = int(cy - np.sin(ang) * length * 0.5)
            x1s = int(cx + np.cos(ang) * length * 0.5)
            y1s = int(cy + np.sin(ang) * length * 0.5)
            v = float(palette_of[rng_of.integers(2, 7)])
            _cv2.line(up, (x0s, y0s), (x1s, y1s), v, 1, lineType=_cv2.LINE_AA)
        return _sm_scale(np.clip(up, 0, 1), sm).astype(np.float32)
    yy, xx = np.mgrid[0:h, 0:w].astype(np.float32)
    rng = np.random.default_rng(seed + 321)
    thickness = _spb_surface_fbm(shape, seed + 322, [1.5, 4.5, 13, 31], [0.30, 0.32, 0.24, 0.14], 0.030)
    pools = np.zeros((h, w), dtype=np.float32)
    for _ in range(num_pools + 8):
        cx = rng.uniform(0, w)
        cy = rng.uniform(0, h)
        rx = rng.uniform(w * 0.035, w * 0.15)
        ry = rng.uniform(h * 0.025, h * 0.11)
        d = ((xx - cx) / rx) ** 2 + ((yy - cy) / ry) ** 2
        pools = np.maximum(pools, np.exp(-d).astype(np.float32) * rng.uniform(0.45, 1.0))
    film = _normalize(thickness * 0.55 + pools * 0.75)
    meniscus = np.clip(np.abs(film - _gauss(film, 2.8)) * 4.5, 0, 1)
    interference = _smoothstep(0.70, 0.995, np.sin(film * 85.0 + xx * 0.017 + yy * 0.011) * 0.5 + 0.5)
    micro = _spb_random_impulse_field(shape, seed + 323, 0.004, 0.65, 1.0)
    # tick 135 NOTE: tried zone band amp 0.08 â€” regressed -0.2 (B-0.4, D-0.4).
    # Recipe lesson: at B=34.5 borderline + film/pool structure, even small zone
    # disrupts the meniscus/interference scales. Skip.
    # tick 140 NOTE: tried bumping meniscus 0.38â†’0.50 (regressed -0.1) and
    # interference 0.20â†’0.30 (regressed -0.2). Pattern is in tight equilibrium;
    # any single-term amp change disrupts B-D balance. Stuck at 71.4.
    combined = film * 0.44 + meniscus * 0.38 + interference * 0.20 + micro * 0.18
    return _sm_scale(_normalize(np.clip(combined, 0, 1)), sm).astype(np.float32)


def spec_magnetic_ferrofluid(shape, seed, sm, hex_spacing=30.0, spike_sigma=0.35, **kwargs):
    """spec_magnetic_ferrofluid.

    identity: R6-creative â€” Rosensweig-instability ferrofluid bed under an
    active hex magnet array. Hero motif: a dense field of CONICAL SPIKES
    (8-14 px spike-to-spike, each cone 4-8 px tall) each with explicit
    upward geometry: a BRIGHT SPECULAR TIP (1-2 px) + a vertically-elongated
    bright BODY ELLIPSE (3-6 px) + a DARK BASE SHADOW arc (the ground
    contact). Between spikes: VALLEY MENISCUS curves bowing toward the
    nearest spikes (short 4-9 px curved hairlines, NOT straight lines),
    occasional MERGED twin-spikes where two cones share a base (peanut
    bipoles), DARK MICRO-PORES in the deep valleys (1-2 px), and a magnetic
    FIELD-LINE sparkle carpet that flows in subtle dipole arcs (vectorized
    flecks biased along simulated field lines). Per-feature INDEPENDENT
    continuous M/R/CC uniforms over wide ranges.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 62411)
    scale = max(min(h, w) / 2048.0, 0.25)
    mn = min(h, w)
    yy = np.arange(h, dtype=np.float32).reshape(h, 1)
    xx = np.arange(w, dtype=np.float32).reshape(1, w)

    # 1) Viscous ferrofluid pool substrate â€” INDEPENDENT per-channel FBM
    fbm_M = _normalize(multi_scale_noise(shape, [3.0, 9.0, 22.0], [0.45, 0.32, 0.23], int(seed) + 62412))
    fbm_R = _normalize(multi_scale_noise(shape, [4.0, 11.0, 26.0], [0.45, 0.32, 0.23], int(seed) + 62413))
    fbm_CC = _normalize(multi_scale_noise(shape, [5.0, 13.0, 28.0], [0.45, 0.32, 0.23], int(seed) + 62414))
    # R6-TICK79 palette discipline: ferrofluid substrate is INKY BLACK with
    # silvery spike tips. Lower base M (0.18) to keep composite mean_M <= 0.45.
    M  = (0.18 + (fbm_M - 0.5) * 0.16).astype(np.float32)
    R  = (0.38 + (fbm_R - 0.5) * 0.24).astype(np.float32)
    CC = (0.22 + (fbm_CC - 0.5) * 0.20).astype(np.float32)

    # 2) Hex lattice base field â€” gentle continuous spike substrate
    # R6-TICK79 ITER4: WIDER spacing (mn/36) so hex cells are ~14 px apart,
    # and lower coverage (0.30) so the substrate stays dark with only mild
    # bright lattice highlights. Heavy lifting is done by cv2 spikes/twins.
    spacing = max(14.0, mn / 36.0)
    freq = 2.0 * np.pi / spacing
    warp_x = (fbm_M - 0.5) * 18.0
    warp_y = (fbm_R - 0.5) * 18.0
    cx_warp = xx + warp_x
    cy_warp = yy + warp_y
    hex_field = (np.cos(cx_warp * freq)
                 + np.cos(cx_warp * freq * 0.5 + cy_warp * freq * 0.866)
                 + np.cos(-cx_warp * freq * 0.5 + cy_warp * freq * 0.866)) / 3.0
    spikes = np.clip((hex_field - 0.55) / 0.45, 0, 1) ** 2.0
    M = M * (1.0 - spikes * 0.30) + 0.78 * (spikes * 0.30)
    R = R * (1.0 - spikes * 0.30) + 0.12 * (spikes * 0.30)
    CC = CC * (1.0 - spikes * 0.30) + 0.12 * (spikes * 0.30)
    M = np.clip(M, 0, 1); R = np.clip(R, 0, 1); CC = np.clip(CC, 0, 1)

    if _CV2_OK:
        # 3) HERO CONICAL SPIKES â€” explicit upward geometry
        # R6-TICK79 ITER5: bigger (rx 3-6, ry 6-10) and fewer (area / 520)
        # so spikes read as discrete features at 512px thumb. ~500 @ 512^2.
        n_spike = int(np.clip((h * w) / 520.0, 120, 2200))
        for _ in range(n_spike):
            cx = int(rng.integers(2, max(3, w - 2))); cy = int(rng.integers(3, max(4, h - 3)))
            # Body: vertically-elongated ellipse â€” ABSOLUTE px (no scale mul)
            rx = int(rng.uniform(3.0, 6.0))
            ry = int(rng.uniform(6.0, 10.0))
            sM = float(rng.uniform(0.55, 0.88))
            sR = float(rng.uniform(0.06, 0.30))
            sCC = float(rng.uniform(0.04, 0.30))
            _cv2.ellipse(M, (cx, cy), (rx, ry), 0, 0, 360, sM, -1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(R, (cx, cy), (rx, ry), 0, 0, 360, sR, -1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(CC, (cx, cy), (rx, ry), 0, 0, 360, sCC, -1, lineType=_cv2.LINE_AA)
            # Bright specular TIP (1-2 px at top of body)
            tip_y = max(0, cy - ry)
            _cv2.circle(M, (cx, tip_y), max(1, rx // 2), float(rng.uniform(0.85, 0.99)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, tip_y), max(1, rx // 2), float(rng.uniform(0.04, 0.16)), -1, lineType=_cv2.LINE_AA)
            # DARK BASE SHADOW arc (ground contact, half-ellipse below)
            if cy + ry + 1 < h:
                _cv2.ellipse(M, (cx, cy + ry), (rx + 1, max(1, ry // 2)), 0, 0, 180, float(rng.uniform(0.06, 0.22)), 1, lineType=_cv2.LINE_AA)
                _cv2.ellipse(R, (cx, cy + ry), (rx + 1, max(1, ry // 2)), 0, 0, 180, float(rng.uniform(0.62, 0.92)), 1, lineType=_cv2.LINE_AA)
                _cv2.ellipse(CC, (cx, cy + ry), (rx + 1, max(1, ry // 2)), 0, 0, 180, float(rng.uniform(0.45, 0.82)), 1, lineType=_cv2.LINE_AA)

        # 4) MERGED TWIN-SPIKES â€” bipole peanut shapes
        # R6-TICK79 ITER3: ABSOLUTE area scaling, sparser.
        n_twin = int(np.clip((h * w) / 720.0, 80, 1800))
        for _ in range(n_twin):
            cx = int(rng.integers(3, max(4, w - 3))); cy = int(rng.integers(3, max(4, h - 3)))
            offset = int(rng.uniform(3, 6) * scale)
            r = max(1, int(rng.uniform(2.0, 3.5) * scale))
            tM = float(rng.uniform(0.62, 0.94))
            tR = float(rng.uniform(0.06, 0.24))
            tCC = float(rng.uniform(0.06, 0.28))
            cx2 = int(np.clip(cx + offset, 0, w - 1))
            _cv2.circle(M, (cx, cy), r, tM, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(M, (cx2, cy), r, tM, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r, tR, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx2, cy), r, tR, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r, tCC, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx2, cy), r, tCC, -1, lineType=_cv2.LINE_AA)
            # Connecting bridge (lower brightness)
            _cv2.line(M, (cx, cy), (cx2, cy), float(rng.uniform(0.40, 0.70)), 1, lineType=_cv2.LINE_AA)

        # 5) VALLEY MENISCUS CURVES â€” short curved hairlines (arcs not lines)
        # R6-TICK79 ITER3: scale by area, ABSOLUTE arc radius (3-7 px).
        n_men = int(np.clip((h * w) / 540.0, 120, 5500))
        for _ in range(n_men):
            cx = int(rng.integers(3, max(4, w - 3))); cy = int(rng.integers(3, max(4, h - 3)))
            r = max(2, int(rng.uniform(3.0, 7.0) * scale))
            a0 = float(rng.uniform(0, 360)); a1 = a0 + float(rng.uniform(35, 90))
            vM = float(rng.uniform(0.28, 0.62))
            vR = float(rng.uniform(0.42, 0.80))
            vCC = float(rng.uniform(0.18, 0.55))
            _cv2.ellipse(M, (cx, cy), (r, r), 0, a0, a1, vM, 1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(R, (cx, cy), (r, r), 0, a0, a1, vR, 1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(CC, (cx, cy), (r, r), 0, a0, a1, vCC, 1, lineType=_cv2.LINE_AA)

        # 6) DARK MICRO-PORES in deep valleys
        # R6-TICK79 ITER3: less density so spikes read.
        n_dark = int(np.clip((h * w) / 380.0, 600, 6000))
        dy = rng.integers(0, h, n_dark); dx = rng.integers(0, w, n_dark)
        M[dy, dx] = np.minimum(M[dy, dx], rng.uniform(0.04, 0.20, n_dark).astype(np.float32))
        R[dy, dx] = np.maximum(R[dy, dx], rng.uniform(0.66, 0.96, n_dark).astype(np.float32))
        CC[dy, dx] = np.maximum(CC[dy, dx], rng.uniform(0.40, 0.78, n_dark).astype(np.float32))

    # 7) FIELD-LINE SPARKLE CARPET â€” flecks biased along simulated dipole arcs
    # R6-TICK79 ITER3: very sparse (area / 900) so thumbnail reads as
    # spike-dominated, not pinprick noise.
    n_sp = int(np.clip((h * w) / 900.0, 200, 2500))
    sy = rng.integers(0, h, n_sp); sx = rng.integers(0, w, n_sp)
    # Apply a small dipole-arc shift to make sparkle align organically
    cx_field = float(rng.uniform(0.3, 0.7) * w); cy_field = float(rng.uniform(0.3, 0.7) * h)
    dx_f = sx.astype(np.float32) - cx_field
    dy_f = sy.astype(np.float32) - cy_field
    dist = np.sqrt(dx_f * dx_f + dy_f * dy_f) + 1.0
    # Skew bright sparkles toward axes near the dipole center
    weight = np.clip(1.0 - dist / (mn * 0.6), 0.0, 1.0)
    M[sy, sx] = np.maximum(M[sy, sx],
        (rng.uniform(0.55, 0.92, n_sp).astype(np.float32) * (0.50 + 0.30 * weight)).astype(np.float32))
    CC[sy, sx] = np.minimum(CC[sy, sx], rng.uniform(0.04, 0.22, n_sp).astype(np.float32))
    R[sy, sx] = np.minimum(R[sy, sx], rng.uniform(0.04, 0.26, n_sp).astype(np.float32))

    # 8) R6-TICK79 HERO â€” TURING REACTION-DIFFUSION SPOT FOAM
    # MATHEMATICAL motif: between the magnetic spikes we inject a layer
    # of Turing-pattern-like interstitial spots â€” small dark dimples
    # surrounded by tighter bright rings â€” produced by thresholding a
    # difference-of-Gaussians on a fresh noise field. This is the
    # signature of Alan Turing's reaction-diffusion morphogenesis,
    # which produces leopard-spot foam in real chemistry. Adds a
    # MATH-CURVE hero into a ferrofluid pattern (unexpected mix).
    if _CV2_OK:
        turing_noise = _normalize(multi_scale_noise(shape, [4.0, 9.0], [0.55, 0.45], int(seed) + 62511)).astype(np.float32)
        # Difference of Gaussians produces leopard-spot-like activation peaks
        g_small = _cv2.GaussianBlur(turing_noise, (0, 0), sigmaX=1.6, sigmaY=1.6)
        g_large = _cv2.GaussianBlur(turing_noise, (0, 0), sigmaX=4.0, sigmaY=4.0)
        dog = g_small - g_large
        # Activation peaks (bright dimple cores)
        peak_mask = (dog > float(dog.std()) * 0.7).astype(np.float32)
        # Inhibition halo (slightly outside the peaks)
        halo_mask = ((dog > float(dog.std()) * 0.25) & (dog < float(dog.std()) * 0.7)).astype(np.float32)
        # Apply: peaks get bright tight M + low R; halos get dimmed mid-tone
        M  = np.clip(M  + peak_mask * 0.22 - halo_mask * 0.12, 0, 1)
        R  = np.clip(R  - peak_mask * 0.18 + halo_mask * 0.10, 0, 1)
        CC = np.clip(CC + peak_mask * 0.10, 0, 1)

    out = np.stack([M, R, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
spec_magnetic_ferrofluid._spb_concept_complete = True


def spec_aerogel_surface(shape, seed, sm, octaves=4, threshold=0.52, **kwargs):
    """spec_aerogel_surface.

    identity: R6 tick-50 second-pass â€” frozen-smoke silica aerogel as a
    sintered foam of glass struts and gas pores. HERO #1: VORONOI
    CELL-WALL NETWORK (90-380 seeds). HERO #2: IRIDESCENT THIN-FILM
    ARC BANDS (peacock chroma). HERO #3: PLASMA-DISCHARGE FILAMENTS
    (UV/cyan/violet/lime per-segment chroma). Dark pore voids, bright
    glass-strut rings, micro pinpoints, dust flecks.

    NEW HERO #4 (tick 78): TURING REACTION-DIFFUSION MICRO-SPOTS.
    Approximated activator-inhibitor field via blurred-then-thresholded
    FBM. Produces evenly-spaced organic spot field (3-7 px) that mimics
    the leopard/cheetah/zebrafish patterning emergence â€” the same math
    that paints animal skins, here rendered on a glass foam. Per-spot
    INDEPENDENT M/R/CC in cool ultraviolet-lab palette.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 36227)
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)

    # 1) Independent foam FBM substrate per channel
    def _aerogel_noise(scales, weights, noise_seed):
        if _CV2_OK and max(h, w) > 1024:
            ds_noise = 2
            small_shape = (max(256, h // ds_noise), max(256, w // ds_noise))
            small_scales = [max(0.65, float(s) / ds_noise) for s in scales]
            small = _normalize(multi_scale_noise(small_shape, small_scales, weights, noise_seed))
            return _cv2.resize(small.astype(np.float32), (w, h), interpolation=_cv2.INTER_LINEAR)
        return _normalize(multi_scale_noise(shape, scales, weights, noise_seed))

    g1 = _aerogel_noise([2.5, 6.0, 13.0, 21.0], [0.36, 0.30, 0.22, 0.12], int(seed) + 3621)
    g2 = _aerogel_noise([3.0, 7.0, 15.0, 24.0], [0.32, 0.30, 0.22, 0.16], int(seed) + 3623)
    g3 = _aerogel_noise([3.5, 7.5, 16.0, 25.0], [0.34, 0.30, 0.22, 0.14], int(seed) + 3625)
    M = (0.16 + (g1 - 0.5) * 0.20).astype(np.float32)
    R = (0.55 + (g2 - 0.5) * 0.34).astype(np.float32)
    CC = (0.22 + (g3 - 0.5) * 0.32).astype(np.float32)

    # Faint Rayleigh haze gradient (blue scatter)
    yy = np.arange(h, dtype=np.float32)[:, None]
    haze = 1.0 - (yy / max(h - 1, 1)) * 0.5
    CC = np.clip(CC + (haze - 0.75) * 0.10, 0, 1).astype(np.float32)

    # 2) HERO #1 â€” VORONOI CELL-WALL NETWORK. Vectorized via tiled
    # nearest-2 lookup on a coarse grid, then upsampled / refined.
    # To stay fast we operate at a downsampled resolution.
    ds = 4 if max(h, w) > 1536 else max(2, int(round(1.0 / max(scale, 0.25))))
    # work res
    wh = max(64, h // ds); ww = max(64, w // ds)
    n_seeds = int(np.clip(140 * (mn / 256.0), 90, 380))
    sx = rng.uniform(0, ww, n_seeds).astype(np.float32)
    sy = rng.uniform(0, wh, n_seeds).astype(np.float32)
    yy_l, xx_l = np.mgrid[0:wh, 0:ww].astype(np.float32)
    # compute nearest and second-nearest distances per pixel
    # cap n_seeds * wh * ww memory at ~200k * float32 -> chunk by rows
    d_min1 = np.full((wh, ww), 1e9, dtype=np.float32)
    d_min2 = np.full((wh, ww), 1e9, dtype=np.float32)
    nearest_idx = np.zeros((wh, ww), dtype=np.int32)
    for i in range(n_seeds):
        dx = xx_l - sx[i]; dy = yy_l - sy[i]
        d = dx * dx + dy * dy
        # update min1 and min2
        new_min = d < d_min1
        # where new_min: shift current min1 to min2
        d_min2 = np.where(new_min, d_min1, np.minimum(d_min2, d))
        d_min1 = np.where(new_min, d, d_min1)
        nearest_idx = np.where(new_min, i, nearest_idx)
    # cell edges where d2-d1 small relative to seed spacing
    edge_thresh_l = (mn / ds) * 0.012  # in low-res units squared-ish
    diff = np.sqrt(np.maximum(d_min2, 0)) - np.sqrt(np.maximum(d_min1, 0))
    edge_mask_l = (diff < max(edge_thresh_l, 0.8)).astype(np.float32)
    # upsample edge mask back to full res
    if _CV2_OK:
        edge_mask = _cv2.resize(edge_mask_l, (w, h), interpolation=_cv2.INTER_LINEAR)
    else:
        # numpy fallback
        edge_mask = np.kron(edge_mask_l, np.ones((h // wh + 1, w // ww + 1), dtype=np.float32))[:h, :w]
    edge_mask = np.clip(edge_mask, 0, 1).astype(np.float32)
    # also give each cell a tinted interior wash for chroma diversity
    if _CV2_OK:
        cell_idx_full = _cv2.resize(nearest_idx.astype(np.float32), (w, h), interpolation=_cv2.INTER_NEAREST).astype(np.int32)
    else:
        cell_idx_full = np.kron(nearest_idx, np.ones((h // wh + 1, w // ww + 1), dtype=np.int32))[:h, :w]
    # generate per-cell tints (independent M/R/CC) and look them up
    cell_tM = rng.uniform(0.05, 0.40, n_seeds).astype(np.float32)
    cell_tR = rng.uniform(0.30, 0.92, n_seeds).astype(np.float32)
    cell_tCC = rng.uniform(0.18, 0.92, n_seeds).astype(np.float32)
    cell_idx_clip = np.clip(cell_idx_full, 0, n_seeds - 1)
    interior_M = cell_tM[cell_idx_clip]
    interior_R = cell_tR[cell_idx_clip]
    interior_CC = cell_tCC[cell_idx_clip]
    # apply gentle wash inside cells (alpha 0.32) â€” keeps FBM mixed in
    wash_alpha = 0.30
    M = M * (1.0 - wash_alpha) + interior_M * wash_alpha
    R = R * (1.0 - wash_alpha) + interior_R * wash_alpha
    CC = CC * (1.0 - wash_alpha) + interior_CC * wash_alpha
    # paint cell walls brighter on M, low on R/CC (crisp glass strut edges)
    M = np.where(edge_mask > 0.5, np.clip(M + 0.42, 0, 1), M)
    R = np.where(edge_mask > 0.5, np.clip(R - 0.32, 0, 1), R)
    CC = np.where(edge_mask > 0.5, np.clip(CC - 0.30, 0, 1), CC)

    if _CV2_OK:
        # 3) HERO #2 â€” IRIDESCENT THIN-FILM ARC BANDS. Short 6-14 px arcs
        # painted across cell faces, alternating peacock chroma. Each arc
        # picks an iridescent tint family.
        n_irid = int(np.clip(900 * (mn / 256.0) ** 2, 480, 3200))
        peacock_families = [
            # (M_lo, M_hi, R_lo, R_hi, CC_lo, CC_hi)
            (0.55, 0.85, 0.05, 0.20, 0.05, 0.15),   # blue-violet
            (0.50, 0.80, 0.08, 0.25, 0.30, 0.55),   # teal
            (0.55, 0.85, 0.30, 0.55, 0.10, 0.30),   # red-orange
            (0.45, 0.75, 0.10, 0.30, 0.55, 0.85),   # amber-gold
            (0.55, 0.82, 0.04, 0.18, 0.40, 0.70),   # cyan
        ]
        for _ in range(n_irid):
            cx_a = float(rng.uniform(0, w)); cy_a = float(rng.uniform(0, h))
            length = float(rng.uniform(6.0, 14.0) * scale)
            ang = float(rng.uniform(0, 2 * np.pi))
            fam = peacock_families[int(rng.integers(0, len(peacock_families)))]
            iM = float(rng.uniform(fam[0], fam[1]))
            iR = float(rng.uniform(fam[2], fam[3]))
            iCC = float(rng.uniform(fam[4], fam[5]))
            x2 = int(np.clip(cx_a + np.cos(ang) * length, 0, w - 1))
            y2 = int(np.clip(cy_a + np.sin(ang) * length, 0, h - 1))
            _cv2.line(M, (int(cx_a), int(cy_a)), (x2, y2), iM, 1, lineType=_cv2.LINE_AA)
            _cv2.line(R, (int(cx_a), int(cy_a)), (x2, y2), iR, 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (int(cx_a), int(cy_a)), (x2, y2), iCC, 1, lineType=_cv2.LINE_AA)

        # 4) DARK PORE VOIDS (5-10 px) â€” gas pockets in the foam
        n_pore = int(np.clip(3200 * (mn / 2048.0) ** 2, 1100, 7500))
        for _ in range(n_pore):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            r = int(max(2, rng.uniform(5, 10) * scale * 0.5))
            pM = float(rng.uniform(0.05, 0.22))
            pR = float(rng.uniform(0.55, 0.92))
            pCC = float(rng.uniform(0.55, 0.95))
            _cv2.circle(M, (cx, cy), r, pM, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r, pR, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r, pCC, -1, lineType=_cv2.LINE_AA)

        # 5) BRIGHT GLASS-STRUT RINGS (7-14 px) â€” strut outlines
        n_strut = int(np.clip(2200 * (mn / 2048.0) ** 2, 700, 5500))
        for _ in range(n_strut):
            cx = int(rng.uniform(6, w - 6)); cy = int(rng.uniform(6, h - 6))
            r = int(max(3, rng.uniform(6, 14) * scale * 0.5))
            sM = float(rng.uniform(0.55, 0.92))
            sR = float(rng.uniform(0.04, 0.22))
            sCC = float(rng.uniform(0.04, 0.18))
            _cv2.circle(M, (cx, cy), r, sM, 1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r, sR, 1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r, sCC, 1, lineType=_cv2.LINE_AA)

        # 6) MICRO PINPOINT PORES (2-4 px)
        n_micro = int(np.clip(3000 * (mn / 2048.0) ** 2, 1000, 7000))
        for _ in range(n_micro):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            r = int(max(1, rng.uniform(2, 4) * scale * 0.5))
            uM = float(rng.uniform(0.05, 0.22))
            uR = float(rng.uniform(0.62, 0.95))
            uCC = float(rng.uniform(0.35, 0.88))
            _cv2.circle(M, (cx, cy), r, uM, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r, uR, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r, uCC, -1, lineType=_cv2.LINE_AA)

        # 6b) R6-TICK50 NEW HERO â€” PLASMA-DISCHARGE FILAMENTS.
        # Captures the alien UV-fluorescence glow real aerogel gets:
        # 3-5 segment 6-14 px zigzag ionic threads with dramatic
        # per-segment CC chroma swings across cyan/violet/lime.
        n_plasma = int(np.clip(420 * (mn / 256.0), 220, 1400))
        plasma_chroma = [
            (0.72, 0.95, 0.04, 0.18, 0.06, 0.20),  # ultraviolet hot core
            (0.45, 0.70, 0.06, 0.22, 0.55, 0.86),  # cyan-electric
            (0.55, 0.82, 0.20, 0.46, 0.18, 0.48),  # magenta plasma
            (0.40, 0.68, 0.10, 0.30, 0.70, 0.96),  # amber arc
            (0.62, 0.88, 0.04, 0.18, 0.40, 0.72),  # lime ionic
        ]
        for _ in range(n_plasma):
            cx_f = float(rng.uniform(4, w - 4))
            cy_f = float(rng.uniform(4, h - 4))
            fam = plasma_chroma[int(rng.integers(0, len(plasma_chroma)))]
            n_seg = int(rng.integers(3, 6))
            ang0 = float(rng.uniform(0, 2 * np.pi))
            cur_x, cur_y = cx_f, cy_f
            for sgi in range(n_seg):
                seg_len = float(rng.uniform(2.5, 4.5) * scale)
                # zigzag: alternate +/- 0.6 rad jitter
                ang0 += float(rng.uniform(-0.9, 0.9))
                nx_f = cur_x + np.cos(ang0) * seg_len
                ny_f = cur_y + np.sin(ang0) * seg_len
                fM = float(rng.uniform(fam[0], fam[1]))
                fR = float(rng.uniform(fam[2], fam[3]))
                fCC = float(rng.uniform(fam[4], fam[5]))
                _cv2.line(M, (int(cur_x), int(cur_y)), (int(nx_f), int(ny_f)), fM, 1, lineType=_cv2.LINE_AA)
                _cv2.line(R, (int(cur_x), int(cur_y)), (int(nx_f), int(ny_f)), fR, 1, lineType=_cv2.LINE_AA)
                _cv2.line(CC, (int(cur_x), int(cur_y)), (int(nx_f), int(ny_f)), fCC, 1, lineType=_cv2.LINE_AA)
                cur_x, cur_y = nx_f, ny_f
            # bright endpoint nodes
            _cv2.circle(M, (int(cur_x), int(cur_y)), 1, float(rng.uniform(0.85, 0.99)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(M, (int(cx_f), int(cy_f)), 1, float(rng.uniform(0.85, 0.99)), -1, lineType=_cv2.LINE_AA)

    # 7) DUST FLECK CARPET
    n_fl = int(np.clip(7000 * (mn / 2048.0) ** 2, 2200, 16000))
    fx = rng.integers(0, w, n_fl); fy = rng.integers(0, h, n_fl)
    M[fy, fx] = rng.uniform(0.04, 0.42, n_fl).astype(np.float32)
    R[fy, fx] = rng.uniform(0.18, 0.92, n_fl).astype(np.float32)
    CC[fy, fx] = rng.uniform(0.05, 0.85, n_fl).astype(np.float32)

    # 8) NEW HERO (tick 78) â€” TURING REACTION-DIFFUSION MICRO-SPOTS.
    # Approximated activator-inhibitor: blur a high-freq noise twice at
    # different sigmas, take difference, threshold â€” yields evenly spaced
    # organic spot field at characteristic wavelength.
    if _CV2_OK:
        # Activator field: high-freq noise blurred at small sigma
        if max(h, w) > 1024:
            spot_ds = 2
            spot_shape = (max(256, h // spot_ds), max(256, w // spot_ds))
            noise_t = rng.random(spot_shape).astype(np.float32)
            act = _cv2.GaussianBlur(noise_t, (0, 0), sigmaX=0.9, sigmaY=0.9)
            inh = _cv2.GaussianBlur(noise_t, (0, 0), sigmaX=1.8, sigmaY=1.8)
        else:
            noise_t = rng.random((h, w)).astype(np.float32)
            act = _cv2.GaussianBlur(noise_t, (0, 0), sigmaX=1.4, sigmaY=1.4)
            inh = _cv2.GaussianBlur(noise_t, (0, 0), sigmaX=3.2, sigmaY=3.2)
        # difference of gaussians ~ Mexican hat = activator-inhibitor approx
        turing = act - inh
        # threshold at top quantile for spots
        thr_t = float(np.quantile(turing, 0.86))
        spot_mask = (turing > thr_t).astype(np.float32)
        if max(h, w) > 1024:
            spot_mask = _cv2.resize(spot_mask, (w, h), interpolation=_cv2.INTER_NEAREST)
        # find spot pixels and apply spot-tinting with cool ultraviolet palette
        sy_idx, sx_idx = np.where(spot_mask > 0.5)
        if sy_idx.size > 0:
            # sub-sample to avoid stomping everything
            max_take = int(np.clip(1400 * (mn / 256.0), 800, 4000))
            n_take_t = min(sy_idx.size, max_take)
            pick_t = rng.choice(sy_idx.size, n_take_t, replace=False)
            py_t = sy_idx[pick_t]; px_t = sx_idx[pick_t]
            # cool UV palette: low M, low-mid R, mid-high CC (violet/cyan)
            base_tM  = float(rng.uniform(0.20, 0.32))
            base_tR  = float(rng.uniform(0.18, 0.28))
            base_tCC = float(rng.uniform(0.62, 0.78))
            M[py_t, px_t]  = np.clip(base_tM  + rng.uniform(-0.05, 0.05, n_take_t).astype(np.float32), 0, 1)
            R[py_t, px_t]  = np.clip(base_tR  + rng.uniform(-0.05, 0.05, n_take_t).astype(np.float32), 0, 1)
            CC[py_t, px_t] = np.clip(base_tCC + rng.uniform(-0.06, 0.06, n_take_t).astype(np.float32), 0, 1)

    out = np.stack([M, R, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
spec_aerogel_surface._spb_concept_complete = True


def spec_damascus_steel_spec(shape, seed, sm, num_layers=18, warp_strength=4.5, **kwargs):
    """Damascus â€” flowing watered bands with per-band continuous chroma.

    identity: A pattern-welded DAMASCUS blade close-up. TIGHT 6-14 px
    watered bands flow and pool across the canvas like wood-grain in
    steel. Each band has CONTINUOUS independent M, R, CC draws (no
    4-tier palette â€” owner doctrine rule 2). Three feature tiers stack:
      (1) Hero watered-band field â€” high-contrast flowing layers,
          M varies continuously per-band from dim 0.20 to mirror 0.97.
      (2) Etched edge highlights at every band boundary lift M and
          drop R â€” the signature Damascus "shine line".
      (3) Per-band FORGE-TEMPER macros: random elongated heat-tint
          patches (8-22 px) carrying independent CC (blues, ambers,
          straws), stacked over the bands so the watered grain shows
          THROUGH the temper colors.
      (4) Micro-etching pit field (1-2 px), bright crystal flecks
          (1-3 px), and short polish hairlines along the band
          direction â€” all with per-feature independent M/R/CC.
    Owner-rated 6/KEEP â€” Round-6 rebuild kills the discrete 4-tier
    quantization, lifts to continuous per-band uniforms, adds the
    forge-temper layer for chroma diversity.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + (hash('damascus_steel_spec_v2') % 10000))
    mn = float(min(h, w))
    px_unit = max(mn / 256.0, 0.7)
    yy, xx = np.mgrid[0:h, 0:w].astype(np.float32)

    # Flow field â€” multi-scale gaussian noise warps the band coord
    flow_a = _gauss(rng.random((h, w)).astype(np.float32), sigma=mn / 28.0)
    flow_b = _gauss(rng.random((h, w)).astype(np.float32), sigma=mn / 10.0)
    flow = (flow_a - 0.5) * 0.7 + (flow_b - 0.5) * 0.3

    # FINE band coord â€” period 6-14 px at thumbnail, flowing
    band_period = max(6.0, 10.0 * px_unit)
    band_coord = yy / band_period + np.sin(xx * 0.035 + flow * 6.0) * 1.4 + np.sin((xx + yy) * 0.016) * 1.8
    band_idx = np.floor(band_coord).astype(np.int64)

    def _hash01_1d(idx, off, span=0xFFFF):
        h_arr = (idx * 73856093) ^ (int(seed) + off)
        return ((h_arr & span).astype(np.float32) / float(span))

    # CONTINUOUS per-band M (was 4-tier â€” now full uniform)
    M_band = (0.18 + _hash01_1d(band_idx, 1) * 0.79).astype(np.float32)
    # Boost contrast between adjacent bands: even bands lean dark, odd lean bright
    parity = (band_idx & 1).astype(np.float32)
    contrast_pull = (parity - 0.5) * 0.18 * _hash01_1d(band_idx, 11)
    M = np.clip(M_band + contrast_pull, 0.0, 1.0).astype(np.float32)
    # CONTINUOUS per-band R and CC, fully independent
    R = (0.12 + _hash01_1d(band_idx, 3) * 0.62).astype(np.float32)
    CC = (0.05 + _hash01_1d(band_idx, 7) * 0.92).astype(np.float32)

    # Etched edge highlights at band boundaries
    etch = np.clip(np.abs(M - _gauss(M, 0.9)) * 3.0, 0.0, 1.0)
    M = np.clip(M + etch * 0.16, 0, 1)
    R = np.clip(R - etch * 0.10, 0, 1)

    if _CV2_OK:
        # TIER 3: Forge-temper macros â€” elongated heat-tint patches with INDEPENDENT M/R/CC
        n_temper = int(np.clip(34 * px_unit, 18, 110))
        for _ in range(n_temper):
            cx = float(rng.uniform(0.02, 0.98) * w)
            cy = float(rng.uniform(0.02, 0.98) * h)
            rx = float(rng.uniform(8.0, 22.0) * px_unit)
            ry = rx * float(rng.uniform(0.18, 0.45))
            ang = float(rng.uniform(-15, 15))  # along band direction
            # Temper colors: pick from realistic forge palette (straw, brown, purple, blue, gray)
            cc_pick = rng.choice([
                float(rng.uniform(0.08, 0.18)),   # straw yellow
                float(rng.uniform(0.55, 0.72)),   # bronze/brown
                float(rng.uniform(0.78, 0.92)),   # blue
                float(rng.uniform(0.30, 0.45)),   # purple
            ])
            m_val = float(rng.uniform(0.55, 0.88))
            r_val = float(rng.uniform(0.30, 0.62))
            # Temper macros nudge channels but don't fully overwrite â€” preserve watered grain
            _cv2.ellipse(M, (int(cx), int(cy)), (int(rx), int(ry)), ang, 0, 360, m_val, 2, lineType=_cv2.LINE_AA)
            _cv2.ellipse(R, (int(cx), int(cy)), (int(rx), int(ry)), ang, 0, 360, r_val, 2, lineType=_cv2.LINE_AA)
            _cv2.ellipse(CC, (int(cx), int(cy)), (int(rx), int(ry)), ang, 0, 360, float(cc_pick), -1, lineType=_cv2.LINE_AA)

        # TIER 4a: Micro-etching pits (1-2 px) with INDEPENDENT M/R/CC
        n_mi = max(10000, int(h * w / 60))
        my = rng.integers(0, h, n_mi)
        mx = rng.integers(0, w, n_mi)
        m_mi = rng.uniform(0.04, 0.22, n_mi).astype(np.float32)
        r_mi = rng.uniform(0.62, 0.95, n_mi).astype(np.float32)
        cc_mi = rng.uniform(0.05, 0.95, n_mi).astype(np.float32)
        M[my, mx] = np.minimum(M[my, mx], m_mi)
        R[my, mx] = np.maximum(R[my, mx], r_mi)
        CC[my, mx] = cc_mi

        # TIER 4b: Bright crystal flecks (1-3 px) with INDEPENDENT M/R/CC
        n_xt = int(np.clip(mn * mn / 200.0, 600, 6000))
        cy_ = rng.integers(0, h, size=n_xt)
        cx_ = rng.integers(0, w, size=n_xt)
        m_xt = rng.uniform(0.82, 0.99, n_xt).astype(np.float32)
        r_xt = rng.uniform(0.04, 0.20, n_xt).astype(np.float32)
        cc_xt = rng.uniform(0.05, 0.98, n_xt).astype(np.float32)
        M[cy_, cx_] = np.maximum(M[cy_, cx_], m_xt)
        R[cy_, cx_] = np.minimum(R[cy_, cx_], r_xt)
        CC[cy_, cx_] = cc_xt

        # TIER 4c: Short polish hairlines along band direction (~1 px wide, 4-12 px long)
        n_pol = max(800, int(h * w / 700))
        for _ in range(n_pol):
            cx0 = float(rng.uniform(4, w - 4))
            cy0 = float(rng.uniform(4, h - 4))
            length = float(rng.uniform(4.0, 12.0) * px_unit)
            ang = float(rng.uniform(-0.30, 0.30))
            x_a = int(cx0 - np.cos(ang) * length * 0.5)
            y_a = int(cy0 - np.sin(ang) * length * 0.5)
            x_b = int(cx0 + np.cos(ang) * length * 0.5)
            y_b = int(cy0 + np.sin(ang) * length * 0.5)
            m_val = float(rng.uniform(0.74, 0.97))
            cc_val = float(rng.uniform(0.05, 0.95))
            r_val = float(rng.uniform(0.06, 0.30))
            _cv2.line(M, (x_a, y_a), (x_b, y_b), m_val, 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (x_a, y_a), (x_b, y_b), cc_val, 1, lineType=_cv2.LINE_AA)
            _cv2.line(R, (x_a, y_a), (x_b, y_b), r_val, 1, lineType=_cv2.LINE_AA)

    out = np.stack([M, R, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
spec_damascus_steel_spec._spb_concept_complete = True


# SPARKLE SYSTEM EXPANSION â€” 9 new sparkle spec patterns
# ============================================================================

def sparkle_rain(shape, seed, sm, density=0.008, streak_len=12):
    """sparkle_rain â€” R6 CREATIVE rebuild.

    identity: A neon-tinted SLANTED RAINSTORM with three storm layers and
    a splash floor. Layer-1: a uniform diagonal sheet of slanted hairline
    streaks (10-20 px, all tilted in one prevailing wind direction) with
    per-streak INDEPENDENT continuous M/R/CC. Layer-2: HERO â€” 80-220
    LIGHT-TRAIL COMET drops â€” bright head circle (2-3 px) trailing a
    fading wake (24-44 px) in the wind direction, each comet a different
    chroma. Layer-3: 50-140 cross-wind drizzle threads (shorter, opposite
    tilt) for layered storm depth. Floor: hundreds of SPLASH BURSTS â€”
    each a 3-5 pt micro-arc of droplets at random angle where rain hits
    surface. Plus dense head-dot pinpricks, dark cloud-pinprick floor,
    and a few faint RIPPLE RINGS (concentric arcs 8-18 px) from heavy
    drops. Full canvas storm coverage.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + (hash("sparkle_rain") % 10000))
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)

    # 1) Wet-sky FBM substrate
    sM_n = _normalize(multi_scale_noise((h, w), [8.0, 22.0, 56.0], [0.40, 0.32, 0.28], int(seed) + 1611))
    sR_n = _normalize(multi_scale_noise((h, w), [9.0, 24.0, 60.0], [0.40, 0.32, 0.28], int(seed) + 1613))
    sC_n = _normalize(multi_scale_noise((h, w), [10.0, 26.0, 64.0], [0.40, 0.32, 0.28], int(seed) + 1615))
    M  = (0.32 + (sM_n - 0.5) * 0.26).astype(np.float32)
    R  = (0.68 + (sR_n - 0.5) * 0.22).astype(np.float32)
    CC = (0.50 + (sC_n - 0.5) * 0.22).astype(np.float32)

    # prevailing wind direction (downward-right-ish)
    wind_ang = float(rng.uniform(np.pi * 0.4, np.pi * 0.6))  # mostly down with slight slant
    wind_cos = float(np.cos(wind_ang)); wind_sin = float(np.sin(wind_ang))

    if _CV2_OK:
        # 2) MAIN SLANTED SHEET â€” 5x density, uniform wind direction
        n_str = int(np.clip(h * w * float(density) * 2.6, 4000, 26000))
        for _ in range(n_str):
            cx = float(rng.uniform(0.01, 0.99) * w)
            cy = float(rng.uniform(0.01, 0.99) * h)
            length = max(2, int(rng.uniform(10.0, 22.0) * scale))
            # slight per-drop variation around wind direction
            ang = wind_ang + float(rng.uniform(-0.12, 0.12))
            x2 = int(np.clip(cx + np.cos(ang) * length, 0, w - 1))
            y2 = int(np.clip(cy + np.sin(ang) * length, 0, h - 1))
            sM = float(rng.uniform(0.40, 0.97))
            sR = float(rng.uniform(0.05, 0.42))
            sCC = float(rng.uniform(0.04, 0.58))
            _cv2.line(M, (int(cx), int(cy)), (x2, y2), sM, 1, lineType=_cv2.LINE_AA)
            _cv2.line(R, (int(cx), int(cy)), (x2, y2), sR, 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (int(cx), int(cy)), (x2, y2), sCC, 1, lineType=_cv2.LINE_AA)

        # 3) HERO â€” LIGHT-TRAIL COMETS (head + fading wake)
        n_comet = int(np.clip(140 * (mn / 1024.0), 60, 320))
        for _ in range(n_comet):
            cx = float(rng.uniform(0.02, 0.98) * w)
            cy = float(rng.uniform(0.02, 0.98) * h)
            ang = wind_ang + float(rng.uniform(-0.08, 0.08))
            length = float(rng.uniform(24.0, 44.0) * scale)
            n_seg = 12
            head_m = float(rng.uniform(0.80, 0.99))
            head_r = float(rng.uniform(0.03, 0.18))
            head_c = float(rng.uniform(0.03, 0.40))
            # head circle
            hr = max(1, int(rng.uniform(1.8, 3.2) * scale))
            _cv2.circle(M, (int(cx), int(cy)), hr, head_m, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (int(cx), int(cy)), hr, head_r, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (int(cx), int(cy)), hr, head_c, -1, lineType=_cv2.LINE_AA)
            # fading wake (segments lose brightness)
            for s in range(1, n_seg + 1):
                t = s / float(n_seg)
                x0s = int(cx - np.cos(ang) * length * (t - 1.0 / n_seg))
                y0s = int(cy - np.sin(ang) * length * (t - 1.0 / n_seg))
                x1s = int(cx - np.cos(ang) * length * t)
                y1s = int(cy - np.sin(ang) * length * t)
                fade = 1.0 - t
                _cv2.line(M, (x0s, y0s), (x1s, y1s), head_m * (0.4 + 0.6 * fade), 1, lineType=_cv2.LINE_AA)

        # 4) CROSS-WIND drizzle threads â€” depth layer (shorter, opposite tilt)
        n_cross = int(np.clip(100 * (mn / 1024.0), 50, 240))
        cross_ang = wind_ang + float(np.pi * 0.18)
        for _ in range(n_cross):
            cx = float(rng.uniform(0, w)); cy = float(rng.uniform(0, h))
            length = float(rng.uniform(5.0, 11.0) * scale)
            ang = cross_ang + float(rng.uniform(-0.18, 0.18))
            x2 = int(np.clip(cx + np.cos(ang) * length, 0, w - 1))
            y2 = int(np.clip(cy + np.sin(ang) * length, 0, h - 1))
            _cv2.line(M, (int(cx), int(cy)), (x2, y2), float(rng.uniform(0.34, 0.78)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(R, (int(cx), int(cy)), (x2, y2), float(rng.uniform(0.20, 0.55)), 1, lineType=_cv2.LINE_AA)

        # 5) SPLASH BURSTS â€” micro-arc droplets where rain hits
        n_splash = int(np.clip(220 * (mn / 1024.0), 80, 540))
        for _ in range(n_splash):
            cx0 = float(rng.uniform(0, w)); cy0 = float(rng.uniform(0, h))
            n_drop = int(rng.integers(3, 6))
            base_ang = float(rng.uniform(0, 2 * np.pi))
            for d in range(n_drop):
                a = base_ang + d * (2 * np.pi / n_drop) + float(rng.uniform(-0.4, 0.4))
                r = float(rng.uniform(2.0, 5.0) * scale)
                px = int(cx0 + np.cos(a) * r); py = int(cy0 + np.sin(a) * r)
                if 0 <= px < w and 0 <= py < h:
                    _cv2.circle(M, (px, py), 1, float(rng.uniform(0.72, 0.99)), -1, lineType=_cv2.LINE_AA)
                    _cv2.circle(R, (px, py), 1, float(rng.uniform(0.06, 0.26)), -1, lineType=_cv2.LINE_AA)

        # 6) RIPPLE RINGS â€” faint concentric arcs from heavy drops
        n_ring = int(np.clip(38 * (mn / 1024.0), 18, 80))
        for _ in range(n_ring):
            cx = int(rng.uniform(0, w)); cy = int(rng.uniform(0, h))
            for k in range(2):
                rr = max(3, int(rng.uniform(8.0, 18.0) * scale) + k * 4)
                _cv2.circle(M, (cx, cy), rr, float(rng.uniform(0.40, 0.72)), 1, lineType=_cv2.LINE_AA)
                _cv2.circle(R, (cx, cy), rr, float(rng.uniform(0.30, 0.62)), 1, lineType=_cv2.LINE_AA)

    # 7) Carpet of head-dot pinpricks (vectorized)
    n_head = int(np.clip(9000 * (mn / 2048.0) ** 2, 3500, 18000))
    hy = rng.integers(0, h, n_head); hx = rng.integers(0, w, n_head)
    M[hy, hx] = np.maximum(M[hy, hx], rng.uniform(0.55, 0.97, n_head).astype(np.float32))
    CC[hy, hx] = np.minimum(CC[hy, hx], rng.uniform(0.03, 0.30, n_head).astype(np.float32))
    R[hy, hx] = np.minimum(R[hy, hx], rng.uniform(0.05, 0.30, n_head).astype(np.float32))

    # 8) Dark cloud-pinprick floor (vectorized)
    n_dark = int(np.clip(5000 * (mn / 2048.0) ** 2, 1800, 11000))
    dy = rng.integers(0, h, n_dark); dx = rng.integers(0, w, n_dark)
    M[dy, dx] = np.minimum(M[dy, dx], rng.uniform(0.04, 0.22, n_dark).astype(np.float32))
    R[dy, dx] = np.maximum(R[dy, dx], rng.uniform(0.62, 0.95, n_dark).astype(np.float32))

    # 9) TICK52 NEW HERO â€” LIGHTNING FORK BOLTS during the storm
    # 2-4 ragged-zigzag bolts forking across the canvas. Each bolt: a main
    # trunk built from ~14-22 jagged 6-14 px segments with a few branch
    # forks splitting off mid-trunk. Per-bolt independent chroma (electric
    # blue / violet / white-hot pink) to deliver wide spec coloring.
    if _CV2_OK:
        n_bolt = int(rng.integers(2, 5))
        for _ in range(n_bolt):
            # Bolt origin (top edge bias) and rough downward direction
            bx = float(rng.uniform(0.10, 0.90) * w)
            by = float(rng.uniform(0.00, 0.18) * h)
            ang_main = float(rng.uniform(np.pi * 0.35, np.pi * 0.65))
            # Per-bolt independent chroma â€” wide range across electric hues
            bM = float(rng.uniform(0.62, 0.98))
            bR = float(rng.uniform(0.03, 0.22))
            bCC = float(rng.uniform(0.04, 0.45))
            x_cur, y_cur = bx, by
            n_seg = int(rng.integers(16, 26))
            trunk_pts = [(int(x_cur), int(y_cur))]
            for s in range(n_seg):
                seg_len = float(rng.uniform(6.0, 14.0) * scale)
                ang_main += float(rng.normal(0, 0.45))  # jagged jitter
                x_new = x_cur + np.cos(ang_main) * seg_len
                y_new = y_cur + np.sin(ang_main) * seg_len
                if not (0 <= x_new < w and 0 <= y_new < h):
                    break
                # Bright core line
                _cv2.line(M, (int(x_cur), int(y_cur)), (int(x_new), int(y_new)), bM, 2, lineType=_cv2.LINE_AA)
                _cv2.line(R, (int(x_cur), int(y_cur)), (int(x_new), int(y_new)), bR, 2, lineType=_cv2.LINE_AA)
                _cv2.line(CC, (int(x_cur), int(y_cur)), (int(x_new), int(y_new)), bCC, 2, lineType=_cv2.LINE_AA)
                # Halo glow line (wider, dimmer)
                _cv2.line(M, (int(x_cur), int(y_cur)), (int(x_new), int(y_new)),
                          bM * 0.55, 4, lineType=_cv2.LINE_AA)
                trunk_pts.append((int(x_new), int(y_new)))
                x_cur, y_cur = x_new, y_new
            # 2-4 fork branches off random trunk midpoints
            n_fork = int(rng.integers(2, 5))
            for _f in range(n_fork):
                if len(trunk_pts) < 3:
                    break
                fi = int(rng.integers(1, len(trunk_pts) - 1))
                fx0, fy0 = trunk_pts[fi]
                fang = float(rng.uniform(0, 2 * np.pi))
                fx_cur, fy_cur = float(fx0), float(fy0)
                f_n_seg = int(rng.integers(5, 11))
                f_M = float(rng.uniform(0.58, 0.95))
                f_R = float(rng.uniform(0.05, 0.28))
                f_CC = float(rng.uniform(0.06, 0.48))
                for fs in range(f_n_seg):
                    fseg_len = float(rng.uniform(4.0, 9.0) * scale)
                    fang += float(rng.normal(0, 0.55))
                    fx_n = fx_cur + np.cos(fang) * fseg_len
                    fy_n = fy_cur + np.sin(fang) * fseg_len
                    if not (0 <= fx_n < w and 0 <= fy_n < h):
                        break
                    _cv2.line(M, (int(fx_cur), int(fy_cur)), (int(fx_n), int(fy_n)), f_M, 1, lineType=_cv2.LINE_AA)
                    _cv2.line(R, (int(fx_cur), int(fy_cur)), (int(fx_n), int(fy_n)), f_R, 1, lineType=_cv2.LINE_AA)
                    _cv2.line(CC, (int(fx_cur), int(fy_cur)), (int(fx_n), int(fy_n)), f_CC, 1, lineType=_cv2.LINE_AA)
                    fx_cur, fy_cur = fx_n, fy_n

    out = np.stack([M, R, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
sparkle_rain._spb_concept_complete = True

def sparkle_constellation(shape, seed, sm, n_clusters=12, stars_per=60):
    """sparkle_constellation.

    identity: R6-Loop tick 55 SECOND-PASS â€” named-constellation atlas.
    Existing layers: nebular FBM substrate, milky-way diagonal band,
    explicit named figures (Orion-belt 3-stars, Big-Dipper Z, triangle,
    pentagram, ring5, cross), prismatic supergiant diffraction stars,
    planet rings, drift-star carpet, micro-twinkle pinpricks. NEW HERO
    STACKED ON TOP (tick 55): SHOOTING-STAR METEOR TRAILS â€” 8-14 angled
    comet streaks (18-34 px long) crossing the sky with a bright 2-3 px
    head, mid-section taper, and dim fading tail of 4-7 fading 1 px
    pinpoint embers. Per-trail INDEPENDENT M/R/CC, each meteor a
    different shooting direction. Sells the dynamic "look-up-at-night"
    energy and adds motion to the static star field.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + (hash("sparkle_constellation_r6c") % 10000))
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)

    # 1) Per-channel nebular FBM substrate
    sky_M = _normalize(_spb_fast_smooth_noise((h, w), [10.0, 28.0, 70.0],
                                          [0.40, 0.34, 0.26], int(seed) + 1011))
    sky_R = _normalize(_spb_fast_smooth_noise((h, w), [9.0, 24.0, 60.0],
                                          [0.40, 0.34, 0.26], int(seed) + 1013))
    sky_CC = _normalize(_spb_fast_smooth_noise((h, w), [12.0, 32.0, 78.0],
                                           [0.38, 0.34, 0.28], int(seed) + 1017))
    M = (0.28 + (sky_M - 0.5) * 0.24).astype(np.float32)
    R = (0.74 + (sky_R - 0.5) * 0.20).astype(np.float32)
    CC = (0.56 + (sky_CC - 0.5) * 0.30).astype(np.float32)

    # 2) Milky-way diagonal dust band â€” soft brighter strip
    yy = np.arange(h, dtype=np.float32)[:, None] / max(h, 1)
    xx = np.arange(w, dtype=np.float32)[None, :] / max(w, 1)
    band_ang = float(rng.uniform(0.25, 0.75)) * np.pi
    band_pos = xx * np.cos(band_ang) + yy * np.sin(band_ang)
    band_center = float(rng.uniform(0.35, 0.65))
    band_width = float(rng.uniform(0.18, 0.30))
    band_mask = np.exp(-((band_pos - band_center) ** 2) / (2.0 * band_width ** 2)).astype(np.float32)
    M = np.clip(M + band_mask * 0.10, 0, 1)
    CC = np.clip(CC + band_mask * 0.12, 0, 1)

    if _CV2_OK:
        # 3) NAMED FIGURES â€” the hero identity. Pick one shape per "constellation"
        #    and draw with explicit geometry so the figure reads.
        figure_types = ['line3', 'bigZ', 'triangle', 'pentagram', 'ring5', 'cross']
        n_fig = int(np.clip(40 * (mn / 256.0), 18, 90))
        for _ in range(n_fig):
            cxc = float(rng.uniform(0.06, 0.94) * w)
            cyc = float(rng.uniform(0.06, 0.94) * h)
            fig_R = float(rng.uniform(14, 36) * scale)
            ang0 = float(rng.uniform(0, 2 * np.pi))
            ft = figure_types[int(rng.integers(0, len(figure_types)))]
            pts = []
            if ft == 'line3':  # belt of 3 stars
                for k in range(3):
                    t = (k - 1.0)
                    px = cxc + np.cos(ang0) * t * fig_R
                    py = cyc + np.sin(ang0) * t * fig_R
                    pts.append((int(np.clip(px, 0, w - 1)), int(np.clip(py, 0, h - 1))))
            elif ft == 'bigZ':  # Z / dipper bend
                offs = [(-1, -0.5), (-0.3, 0.4), (0.3, -0.4), (1, 0.5)]
                for ox, oy in offs:
                    px = cxc + (np.cos(ang0) * ox - np.sin(ang0) * oy) * fig_R
                    py = cyc + (np.sin(ang0) * ox + np.cos(ang0) * oy) * fig_R
                    pts.append((int(np.clip(px, 0, w - 1)), int(np.clip(py, 0, h - 1))))
            elif ft == 'triangle':
                for k in range(3):
                    a = ang0 + k * (2 * np.pi / 3)
                    px = cxc + np.cos(a) * fig_R
                    py = cyc + np.sin(a) * fig_R
                    pts.append((int(np.clip(px, 0, w - 1)), int(np.clip(py, 0, h - 1))))
                pts.append(pts[0])
            elif ft == 'pentagram':
                pent = []
                for k in range(5):
                    a = ang0 + k * (2 * np.pi / 5)
                    pent.append((int(np.clip(cxc + np.cos(a) * fig_R, 0, w - 1)),
                                 int(np.clip(cyc + np.sin(a) * fig_R, 0, h - 1))))
                order = [0, 2, 4, 1, 3, 0]
                pts = [pent[k] for k in order]
            elif ft == 'ring5':
                for k in range(5):
                    a = ang0 + k * (2 * np.pi / 5)
                    px = cxc + np.cos(a) * fig_R
                    py = cyc + np.sin(a) * fig_R
                    pts.append((int(np.clip(px, 0, w - 1)), int(np.clip(py, 0, h - 1))))
                pts.append(pts[0])
            else:  # cross
                for ox, oy in [(-1, 0), (1, 0), (0, 0), (0, -1), (0, 1)]:
                    px = cxc + (np.cos(ang0) * ox - np.sin(ang0) * oy) * fig_R
                    py = cyc + (np.sin(ang0) * ox + np.cos(ang0) * oy) * fig_R
                    pts.append((int(np.clip(px, 0, w - 1)), int(np.clip(py, 0, h - 1))))

            # connecting starlines (low brightness)
            for i in range(len(pts) - 1):
                _cv2.line(M, pts[i], pts[i + 1],
                          float(rng.uniform(0.36, 0.66)), 1, lineType=_cv2.LINE_AA)
                _cv2.line(CC, pts[i], pts[i + 1],
                          float(rng.uniform(0.10, 0.42)), 1, lineType=_cv2.LINE_AA)
            # anchor stars (bright, 3-5 px)
            for (sx, sy) in pts:
                r_s = max(2, int(rng.uniform(2.5, 4.5) * scale))
                _cv2.circle(M, (sx, sy), r_s, float(rng.uniform(0.78, 0.99)),
                            -1, lineType=_cv2.LINE_AA)
                _cv2.circle(R, (sx, sy), r_s, float(rng.uniform(0.04, 0.36)),
                            -1, lineType=_cv2.LINE_AA)
                _cv2.circle(CC, (sx, sy), r_s, float(rng.uniform(0.04, 0.60)),
                            -1, lineType=_cv2.LINE_AA)

        # 4) PRISMATIC SUPERGIANT HEROES â€” diffraction-cross diamonds, 6-8 px
        n_hero = int(np.clip(45 * (mn / 256.0), 18, 110))
        for _ in range(n_hero):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            arm = max(3, int(rng.uniform(4.0, 7.0) * scale))
            hM = float(rng.uniform(0.85, 0.99))
            hR = float(rng.uniform(0.04, 0.22))
            hCC = float(rng.uniform(0.05, 0.85))  # very wide for prismatic colour
            _cv2.line(M, (cx - arm, cy), (cx + arm, cy), hM, 1, lineType=_cv2.LINE_AA)
            _cv2.line(M, (cx, cy - arm), (cx, cy + arm), hM, 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (cx - arm, cy), (cx + arm, cy), hCC, 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (cx, cy - arm), (cx, cy + arm), hCC, 1, lineType=_cv2.LINE_AA)
            _cv2.circle(M, (cx, cy), max(1, int(2 * scale)), hM, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), max(1, int(2 * scale)), hR, -1, lineType=_cv2.LINE_AA)

        # 5) PLANET RINGS â€” 10-18 px concentric ellipse pairs (rare hero accent)
        n_ring = int(np.clip(14 * (mn / 256.0), 5, 28))
        for _ in range(n_ring):
            cx = int(rng.integers(int(w * 0.06), int(w * 0.94)))
            cy = int(rng.integers(int(h * 0.06), int(h * 0.94)))
            ra = max(5, int(rng.uniform(6.0, 9.0) * scale))
            rb = max(2, int(ra * rng.uniform(0.32, 0.55)))
            tilt = float(rng.uniform(0, 180))
            _cv2.ellipse(M, (cx, cy), (ra, rb), tilt, 0, 360,
                         float(rng.uniform(0.42, 0.78)), 1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(R, (cx, cy), (ra, rb), tilt, 0, 360,
                         float(rng.uniform(0.18, 0.50)), 1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(CC, (cx, cy), (max(2, ra - 2), max(1, rb - 1)), tilt, 0, 360,
                         float(rng.uniform(0.12, 0.62)), 1, lineType=_cv2.LINE_AA)
            # planet core
            _cv2.circle(M, (cx, cy), max(1, int(2 * scale)), float(rng.uniform(0.70, 0.95)),
                        -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), max(1, int(2 * scale)), float(rng.uniform(0.20, 0.85)),
                        -1, lineType=_cv2.LINE_AA)

        # 5B) NEW HERO (tick 55) â€” SHOOTING-STAR METEOR TRAILS
        # Angled comet streaks with bright head + tapering tail + ember pinpoints.
        n_meteor = int(rng.integers(8, 15))
        for _ in range(n_meteor):
            # Start head somewhere in the field
            hcx = int(rng.uniform(0.08, 0.92) * w)
            hcy = int(rng.uniform(0.08, 0.92) * h)
            trail_len = float(rng.uniform(18.0, 34.0) * max(scale, 0.5))
            trail_ang = float(rng.uniform(0, 2 * np.pi))
            tcx = int(np.clip(hcx - np.cos(trail_ang) * trail_len, 0, w - 1))
            tcy = int(np.clip(hcy - np.sin(trail_ang) * trail_len, 0, h - 1))
            mM = float(rng.uniform(0.78, 0.99))
            mR = float(rng.uniform(0.04, 0.20))
            mCC = float(rng.uniform(0.25, 0.95))
            # Streak line
            _cv2.line(M, (tcx, tcy), (hcx, hcy), mM * 0.6, 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (tcx, tcy), (hcx, hcy), mCC * 0.7, 1, lineType=_cv2.LINE_AA)
            # Bright 2-3 px head
            head_r = max(2, int(rng.uniform(2.0, 3.5) * max(scale, 0.7)))
            _cv2.circle(M, (hcx, hcy), head_r, mM, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (hcx, hcy), head_r, mR, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (hcx, hcy), head_r, mCC, -1, lineType=_cv2.LINE_AA)
            # Fading ember pinpoints along the tail
            n_ember = int(rng.integers(4, 8))
            for k in range(n_ember):
                t_frac = (k + 1) / (n_ember + 1)
                ex = int(np.clip(hcx - np.cos(trail_ang) * trail_len * t_frac, 0, w - 1))
                ey = int(np.clip(hcy - np.sin(trail_ang) * trail_len * t_frac, 0, h - 1))
                fade = 1.0 - t_frac * 0.8
                M[ey, ex] = max(float(M[ey, ex]), float(mM * fade * rng.uniform(0.7, 1.0)))
                R[ey, ex] = min(float(R[ey, ex]), float(mR + (1.0 - fade) * 0.4))
                CC[ey, ex] = float(np.clip(mCC * fade * rng.uniform(0.5, 1.0), 0, 1))

    # 6) Drift-stars carpet â€” independent per-channel
    n_loose = int(np.clip(9000 * (mn / 2048.0) ** 2, 3500, 22000))
    ly = rng.integers(0, h, n_loose); lx = rng.integers(0, w, n_loose)
    M[ly, lx] = np.maximum(M[ly, lx], rng.uniform(0.45, 0.95, n_loose).astype(np.float32))
    R[ly, lx] = np.minimum(R[ly, lx], rng.uniform(0.04, 0.30, n_loose).astype(np.float32))
    CC[ly, lx] = rng.uniform(0.04, 0.78, n_loose).astype(np.float32)

    # 7) Micro-twinkle pinpricks â€” wide chroma
    n_tw = int(np.clip(15000 * (mn / 2048.0) ** 2, 4500, 30000))
    ty = rng.integers(0, h, n_tw); tx = rng.integers(0, w, n_tw)
    CC[ty, tx] = np.clip(CC[ty, tx] + rng.uniform(-0.35, 0.35, n_tw).astype(np.float32), 0, 1)
    M[ty, tx] = np.maximum(M[ty, tx], rng.uniform(0.38, 0.85, n_tw).astype(np.float32))

    out = np.stack([M, R, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
sparkle_constellation._spb_concept_complete = True

def sparkle_nebula(shape, seed, sm, density=0.006):
    """sparkle_nebula.

    identity: R6-creative rebuild â€” Cosmic ionised gas with TWO spiral galactic
    arms sweeping across the canvas, ionised plasma FILAMENTS arcing between
    star nurseries, dense star pinpricks tier-stacked into Class O (white-hot),
    Class K (orange), Class M (deep red dwarf) populations, a few hero
    SUPERNOVA flares with rainbow accretion rings, micro dust pillars (8-16
    px stretched ovals at consistent shear angle), and a chroma-rich per-
    channel FBM nebular substrate. Every primitive picks INDEPENDENT M/R/CC
    from wide continuous uniforms. Full coverage, no blank space.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + (hash("sparkle_nebula_r6") % 10000))
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)

    # 1) Per-channel deep-space FBM (chroma-diverse substrate)
    space_M = _normalize(multi_scale_noise((h, w), [10.0, 26.0, 60.0],
                                            [0.40, 0.35, 0.25], int(seed) + 1511))
    space_R = _normalize(multi_scale_noise((h, w), [9.0, 22.0, 54.0],
                                            [0.40, 0.35, 0.25], int(seed) + 1513))
    space_CC = _normalize(multi_scale_noise((h, w), [12.0, 30.0, 70.0],
                                             [0.40, 0.35, 0.25], int(seed) + 1517))
    M = (0.30 + (space_M - 0.5) * 0.26).astype(np.float32)
    R = (0.72 + (space_R - 0.5) * 0.22).astype(np.float32)
    CC = (0.52 + (space_CC - 0.5) * 0.32).astype(np.float32)

    # 2) TWO spiral galactic arms â€” large-scale rotational structure
    yy = np.arange(h, dtype=np.float32)[:, None]
    xx = np.arange(w, dtype=np.float32)[None, :]
    gcx = float(rng.uniform(w * 0.30, w * 0.70))
    gcy = float(rng.uniform(h * 0.30, h * 0.70))
    rdist = np.sqrt((xx - gcx) ** 2 + (yy - gcy) ** 2)
    theta = np.arctan2(yy - gcy, xx - gcx)
    pitch = float(rng.uniform(0.35, 0.65))  # spiral tightness
    arm_phase = (theta - np.log(np.maximum(rdist, 1.0)) / pitch) % (np.pi)
    # Two-arm spiral: bright where phase near 0 or pi
    arm_intensity = (np.cos(arm_phase * 2.0) * 0.5 + 0.5) ** 1.6
    # Radial fall-off
    arm_falloff = np.exp(-rdist / (min(h, w) * 0.5))
    arm = (arm_intensity * arm_falloff).astype(np.float32)
    M = np.clip(M + arm * 0.22, 0, 1)
    CC = np.clip(CC + arm * 0.18, 0, 1)
    R = np.clip(R - arm * 0.10, 0, 1)

    if _CV2_OK:
        # 3) Ionised PLASMA FILAMENTS â€” short curved arcs crossing the field
        n_fil = int(np.clip(220 * (mn / 2048.0) ** 2 + 70, 70, 520))
        for _ in range(n_fil):
            cx = float(rng.uniform(8, w - 8)); cy = float(rng.uniform(8, h - 8))
            seg_n = int(rng.integers(4, 9))
            ang = float(rng.uniform(0, 2 * np.pi))
            curve = float(rng.uniform(-0.22, 0.22))
            step = float(rng.uniform(2.5, 4.5)) * scale
            fM = float(rng.uniform(0.55, 0.98))
            fR = float(rng.uniform(0.06, 0.32))
            fCC = float(rng.uniform(0.10, 0.95))
            px, py = cx, cy
            for _s in range(seg_n):
                ang += curve
                nx = px + np.cos(ang) * step
                ny = py + np.sin(ang) * step
                _cv2.line(M,  (int(px), int(py)), (int(nx), int(ny)), fM, 1, lineType=_cv2.LINE_AA)
                _cv2.line(R,  (int(px), int(py)), (int(nx), int(ny)), fR, 1, lineType=_cv2.LINE_AA)
                _cv2.line(CC, (int(px), int(py)), (int(nx), int(ny)), fCC, 1, lineType=_cv2.LINE_AA)
                px, py = nx, ny

        # 4) Cloud-blob field (nebular pockets, 8-22 px)
        blob_buf_M = np.zeros((h, w), dtype=np.float32)
        blob_buf_R = np.zeros((h, w), dtype=np.float32)
        blob_buf_CC = np.zeros((h, w), dtype=np.float32)
        n_blob = int(np.clip(h * w * float(density) * 0.55, 480, 3000))
        for _ in range(n_blob):
            cx = int(rng.uniform(0.01, 0.99) * w)
            cy = int(rng.uniform(0.01, 0.99) * h)
            r_outer = max(4, int(rng.uniform(7, 18) * scale))
            r_core = max(1, int(r_outer * 0.35))
            bM = float(rng.uniform(0.28, 0.82))
            bR = float(rng.uniform(0.12, 0.58))
            bCC = float(rng.uniform(0.08, 0.92))
            _cv2.circle(blob_buf_M, (cx, cy), r_outer, bM, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(blob_buf_M, (cx, cy), r_core, float(rng.uniform(0.65, 0.96)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(blob_buf_R, (cx, cy), r_outer, bR, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(blob_buf_CC, (cx, cy), r_outer, bCC, -1, lineType=_cv2.LINE_AA)
        blob_buf_M = _cv2.GaussianBlur(blob_buf_M, (0, 0), sigmaX=1.8, sigmaY=1.8)
        blob_buf_R = _cv2.GaussianBlur(blob_buf_R, (0, 0), sigmaX=1.8, sigmaY=1.8)
        blob_buf_CC = _cv2.GaussianBlur(blob_buf_CC, (0, 0), sigmaX=1.8, sigmaY=1.8)
        M = np.maximum(M, blob_buf_M)
        R = np.where(blob_buf_R > 0.04, R * 0.55 + blob_buf_R * 0.45, R).astype(np.float32)
        CC = np.where(blob_buf_CC > 0.04, CC * 0.55 + blob_buf_CC * 0.45, CC).astype(np.float32)

        # 5) DUST PILLARS â€” 8-16 px stretched ovals at consistent shear angle
        pillar_ang = float(rng.uniform(np.pi * 0.15, np.pi * 0.35))
        n_pil = int(np.clip(380 * (mn / 2048.0) ** 2 + 90, 90, 900))
        for _ in range(n_pil):
            cx = int(rng.uniform(0, w)); cy = int(rng.uniform(0, h))
            rx = max(2, int(rng.uniform(4.0, 8.0) * scale))
            ry = max(1, int(rng.uniform(1.0, 2.5) * scale))
            ang_deg = float(np.degrees(pillar_ang + rng.normal(0, 0.18)))
            _cv2.ellipse(M,  (cx, cy), (rx, ry), ang_deg, 0, 360, float(rng.uniform(0.10, 0.40)), -1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(R,  (cx, cy), (rx, ry), ang_deg, 0, 360, float(rng.uniform(0.62, 0.92)), -1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(CC, (cx, cy), (rx, ry), ang_deg, 0, 360, float(rng.uniform(0.35, 0.85)), -1, lineType=_cv2.LINE_AA)

        # 6) Star carpet â€” three stellar classes
        # Class O â€” white-hot pinpricks
        n_O = int(np.clip(8000 * (mn / 2048.0) ** 2, 2400, 16000))
        sy = rng.integers(0, h, n_O); sx = rng.integers(0, w, n_O)
        M[sy, sx] = np.maximum(M[sy, sx], rng.uniform(0.74, 0.99, n_O).astype(np.float32))
        CC[sy, sx] = np.minimum(CC[sy, sx], rng.uniform(0.02, 0.20, n_O).astype(np.float32))
        R[sy, sx] = np.minimum(R[sy, sx], rng.uniform(0.04, 0.22, n_O).astype(np.float32))
        # Class K â€” orange dwarfs (warm M, mid CC)
        n_K = int(np.clip(5500 * (mn / 2048.0) ** 2, 1800, 11000))
        sy = rng.integers(0, h, n_K); sx = rng.integers(0, w, n_K)
        M[sy, sx] = np.maximum(M[sy, sx], rng.uniform(0.50, 0.82, n_K).astype(np.float32))
        CC[sy, sx] = np.maximum(CC[sy, sx], rng.uniform(0.40, 0.80, n_K).astype(np.float32))
        # Class M â€” deep red dwarfs (low M, moderate R, high CC chroma)
        n_M = int(np.clip(4200 * (mn / 2048.0) ** 2, 1400, 8500))
        sy = rng.integers(0, h, n_M); sx = rng.integers(0, w, n_M)
        M[sy, sx] = np.minimum(M[sy, sx], rng.uniform(0.18, 0.42, n_M).astype(np.float32))
        CC[sy, sx] = np.maximum(CC[sy, sx], rng.uniform(0.60, 0.95, n_M).astype(np.float32))

        # 7) Supernova flares with accretion rings â€” hero motif (sparse, dramatic)
        n_super = int(np.clip(40 * (mn / 2048.0) ** 2 + 6, 6, 80))
        for _ in range(n_super):
            cx = int(rng.uniform(0.02, 0.98) * w); cy = int(rng.uniform(0.02, 0.98) * h)
            r_s = max(2, int(rng.uniform(2, 4) * scale))
            _cv2.circle(M, (cx, cy), r_s, float(rng.uniform(0.92, 1.00)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r_s, float(rng.uniform(0.02, 0.18)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r_s, float(rng.uniform(0.04, 0.18)), -1, lineType=_cv2.LINE_AA)
            # 2-3 accretion rings â€” each in its own chroma
            for ri in range(int(rng.integers(2, 4))):
                rr = max(r_s + 2, int(r_s * (2.0 + ri * 1.2)))
                _cv2.circle(M, (cx, cy), rr, float(rng.uniform(0.30, 0.85)), 1, lineType=_cv2.LINE_AA)
                _cv2.circle(CC, (cx, cy), rr, float(rng.uniform(0.10, 0.90)), 1, lineType=_cv2.LINE_AA)

        # 8) Micro-dust pinpricks
        n_d = int(np.clip(7500 * (mn / 2048.0) ** 2, 2200, 15000))
        dy = rng.integers(0, h, n_d); dx = rng.integers(0, w, n_d)
        R[dy, dx] = np.clip(R[dy, dx] + rng.uniform(-0.18, 0.28, n_d).astype(np.float32), 0, 1)
        CC[dy, dx] = np.clip(CC[dy, dx] + rng.uniform(-0.20, 0.30, n_d).astype(np.float32), 0, 1)

    out = np.stack([M, R, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
sparkle_nebula._spb_concept_complete = True

def sparkle_firefly(shape, seed, sm, n_flies=200, glow_radius=8):
    """sparkle_firefly.

    identity: ROUND-6 CREATIVE rebuild (tick53 second-pass) â€” a summer
    meadow at dusk with a swarm of fireflies. NEW HERO (tick53):
    CONSTELLATION STREAMER ARCS â€” 8-16 dramatic curved flight-trail arcs
    (3 connected fireflies each, 4-10 px segments, drawn as bright tapered
    arc paths) suggesting a fly hopping between blinks. The arcs read as
    little astrological hieroglyphs of light. Stacked on prior heroes:
    (a) dusk-meadow FBM substrate, (b) 900-12000 firefly cores 1-2 px
    with INDEPENDENT continuous chroma (warm-yellow, cool-blue,
    ember-orange MIXED simultaneously), (c) SOFT BLURRED halo pass,
    (d) motion-trail ticks 2-4 px, (e) sub-glow pinpricks, (f) pollen
    dust field. Per-feature INDEPENDENT M/R/CC.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + (hash("sparkle_firefly") % 10000))
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)

    # 1) Dusk meadow FBM substrate
    # R6-TICK79: lower R substrate (0.72 -> 0.48) to keep composite mean_R <= 0.55.
    dusk_M = _normalize(multi_scale_noise((h, w), [12.0, 30.0, 75.0], [0.40, 0.32, 0.28], int(seed) + 1311))
    dusk_R = _normalize(multi_scale_noise((h, w), [10.0, 26.0, 68.0], [0.40, 0.32, 0.28], int(seed) + 1313))
    dusk_CC = _normalize(multi_scale_noise((h, w), [14.0, 34.0, 80.0], [0.40, 0.32, 0.28], int(seed) + 1317))
    M = (0.30 + (dusk_M - 0.5) * 0.20).astype(np.float32)
    R = (0.48 + (dusk_R - 0.5) * 0.20).astype(np.float32)
    CC = (0.46 + (dusk_CC - 0.5) * 0.24).astype(np.float32)

    if _CV2_OK:
        n_fl = max(int(n_flies) * 5, 900)
        n_fl = min(n_fl, int(11000 * (mn / 2048.0) ** 2 + 1200))
        halo_M = np.zeros((h, w), dtype=np.float32)
        halo_CC = np.zeros((h, w), dtype=np.float32)
        halo_R = np.zeros((h, w), dtype=np.float32)

        # Pre-sample firefly positions so we can also draw motion trails
        fxs = rng.integers(0, w, n_fl)
        fys = rng.integers(0, h, n_fl)
        for k in range(n_fl):
            cx = int(fxs[k]); cy = int(fys[k])
            intensity = float(rng.uniform(0.30, 1.00))
            r_glow = max(2, int(float(glow_radius) * scale * rng.uniform(0.45, 1.40)))
            r_core = max(1, int(r_glow * 0.30))
            hM = float(0.40 + intensity * 0.38)
            hR_ = float(rng.uniform(0.04, 0.30))
            hCC = float(rng.uniform(0.06, 0.65))
            _cv2.circle(halo_M, (cx, cy), r_glow, hM, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(halo_R, (cx, cy), r_glow, hR_, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(halo_CC, (cx, cy), r_glow, hCC, -1, lineType=_cv2.LINE_AA)
            # bright core â€” INDEPENDENT continuous M/R/CC
            _cv2.circle(M, (cx, cy), r_core, float(rng.uniform(0.72, 0.99)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r_core, float(rng.uniform(0.04, 0.32)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r_core, float(rng.uniform(0.03, 0.65)), -1, lineType=_cv2.LINE_AA)

            # HERO: MOTION TRAIL TICK â€” short line behind every 4th fly (creative)
            if k % 4 == 0:
                ang_t = float(rng.uniform(0, 2 * np.pi))
                tlen = int(rng.uniform(2, 4) * scale + 1)
                tx = int(np.clip(cx + np.cos(ang_t) * tlen, 0, w - 1))
                ty = int(np.clip(cy + np.sin(ang_t) * tlen, 0, h - 1))
                _cv2.line(M, (cx, cy), (tx, ty), float(rng.uniform(0.55, 0.92)), 1, lineType=_cv2.LINE_AA)
                _cv2.line(R, (cx, cy), (tx, ty), float(rng.uniform(0.05, 0.30)), 1, lineType=_cv2.LINE_AA)
                _cv2.line(CC, (cx, cy), (tx, ty), float(rng.uniform(0.05, 0.55)), 1, lineType=_cv2.LINE_AA)

        halo_M = _cv2.GaussianBlur(halo_M, (0, 0), sigmaX=1.8, sigmaY=1.8)
        halo_R = _cv2.GaussianBlur(halo_R, (0, 0), sigmaX=1.8, sigmaY=1.8)
        halo_CC = _cv2.GaussianBlur(halo_CC, (0, 0), sigmaX=1.8, sigmaY=1.8)
        M = np.maximum(M, halo_M)
        R = np.where(halo_R > 0.05, R * 0.55 + halo_R * 0.45, R).astype(np.float32)
        CC = np.where(halo_CC > 0.05, CC * 0.55 + halo_CC * 0.45, CC).astype(np.float32)

        # NEW HERO tick53 â€” CONSTELLATION STREAMER ARCS. 3 connected
        # fireflies per arc, each 4-10 px segment, drawn bright tapered.
        # Reads as a chained-blink flight path between perch points.
        n_arc = int(np.clip(140 * (mn / 2048.0) ** 2, 28, 360))
        for _ in range(n_arc):
            ax = float(rng.uniform(0.06, 0.94) * w)
            ay = float(rng.uniform(0.06, 0.94) * h)
            base_a = float(rng.uniform(0, 2 * np.pi))
            seg_len = float(rng.uniform(5.0, 10.0) * scale)
            pts = [(int(ax), int(ay))]
            for _s in range(3):
                base_a += float(rng.uniform(-0.7, 0.7))
                ax += np.cos(base_a) * seg_len
                ay += np.sin(base_a) * seg_len
                pts.append((int(np.clip(ax, 0, w - 1)), int(np.clip(ay, 0, h - 1))))
            am = float(rng.uniform(0.74, 0.99))
            ar = float(rng.uniform(0.05, 0.30))
            ac = float(rng.uniform(0.18, 0.92))
            for k in range(len(pts) - 1):
                _cv2.line(M, pts[k], pts[k + 1], am, 1, lineType=_cv2.LINE_AA)
                _cv2.line(R, pts[k], pts[k + 1], ar, 1, lineType=_cv2.LINE_AA)
                _cv2.line(CC, pts[k], pts[k + 1], ac, 1, lineType=_cv2.LINE_AA)
            # 3 perch-point fireflies (bright cores at each junction)
            for (px_, py_) in pts:
                rcore = max(1, int(1.5 * scale))
                _cv2.circle(M, (px_, py_), rcore, float(rng.uniform(0.85, 0.99)), -1, lineType=_cv2.LINE_AA)
                _cv2.circle(CC, (px_, py_), rcore, float(rng.uniform(0.40, 0.96)), -1, lineType=_cv2.LINE_AA)

        # Sub-glow micro pinpricks (distant dim fireflies)
        n_sub = int(np.clip(11000 * (mn / 2048.0) ** 2, 3500, 22000))
        sy = rng.integers(0, h, n_sub); sx = rng.integers(0, w, n_sub)
        M[sy, sx] = np.maximum(M[sy, sx], rng.uniform(0.42, 0.88, n_sub).astype(np.float32))
        CC[sy, sx] = rng.uniform(0.04, 0.60, n_sub).astype(np.float32)

        # Pollen dust field
        n_dust = int(np.clip(11000 * (mn / 2048.0) ** 2, 3000, 22000))
        dy = rng.integers(0, h, n_dust); dx = rng.integers(0, w, n_dust)
        M[dy, dx] = np.clip(M[dy, dx] + rng.uniform(-0.14, 0.32, n_dust).astype(np.float32), 0, 1)
        R[dy, dx] = np.clip(R[dy, dx] + rng.uniform(-0.14, 0.20, n_dust).astype(np.float32), 0, 1)

        # NEW HERO R6-TICK79 â€” BIOLUMINESCENT DINOFLAGELLATE WAKES
        # Tiny curved comma-shaped trail strokes (6-10 px arc segments)
        # representing the cool-blue chemical wake of sea plankton instead
        # of a warm-yellow firefly. Adds an unexpected COOL-leaning chroma
        # cluster that contrasts the warm fireflies. ~120-400 wakes.
        # Each wake is a short 60-110-deg arc with a comma tail and a
        # bright nucleus pinpoint.
        n_wake = int(np.clip(300 * (mn / 2048.0) ** 2, 100, 700))
        for _ in range(n_wake):
            cx = int(rng.integers(8, w - 8)); cy = int(rng.integers(8, h - 8))
            arc_r = max(3, int(float(rng.uniform(4.0, 7.0)) * scale))
            a0 = float(rng.uniform(0, 360)); a1 = a0 + float(rng.uniform(60, 110))
            wM = float(rng.uniform(0.55, 0.85))  # not super bright (plankton glow is dim)
            wR = float(rng.uniform(0.14, 0.32))
            wCC = float(rng.uniform(0.65, 0.95))  # COOL: high CC dominant
            _cv2.ellipse(M,  (cx, cy), (arc_r, arc_r), 0, a0, a1, wM, 1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(R,  (cx, cy), (arc_r, arc_r), 0, a0, a1, wR, 1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(CC, (cx, cy), (arc_r, arc_r), 0, a0, a1, wCC, 1, lineType=_cv2.LINE_AA)
            # nucleus pinpoint at the head of the wake
            ang_h = float(np.deg2rad(a0))
            hx = int(np.clip(cx + np.cos(ang_h) * arc_r, 0, w - 1))
            hy = int(np.clip(cy + np.sin(ang_h) * arc_r, 0, h - 1))
            _cv2.circle(M,  (hx, hy), 1, float(rng.uniform(0.78, 0.97)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (hx, hy), 1, float(rng.uniform(0.80, 0.99)), -1, lineType=_cv2.LINE_AA)

    out = np.stack([M, R, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)


sparkle_firefly._spb_concept_complete = True

def sparkle_shattered(shape, seed, sm, n_shards=600):
    """sparkle_shattered â€” R6 CREATIVE rebuild.

    identity: A glass panel hit by a hammer â€” HERO MOTIF is the IMPACT
    STAR-BURST: 6-10 impact points distributed across the canvas, each
    firing 8-14 RADIAL CRACK SPOKES (bright glowing lines tapering with
    distance from impact) producing the iconic spiderweb pattern.
    Connecting CONCENTRIC ARC FRAGMENTS (3-8 px curved lines circling
    each impact at different radii) sell the stress-ring physics. On top:
    dense triangular shard polygons everywhere (the small slivers) with
    bright PRISM-EDGE highlights along their longer edges. Plus: bright
    facet-catch pinpricks, chroma flecks. Per-shard and per-crack
    INDEPENDENT continuous M/R/CC. Wide chroma diversity â€” refracted
    light shows rainbow tints, not uniform glassy. Seven stacked tiers.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + (hash("sparkle_shattered") % 10000))
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)

    # 1) Per-channel broken-glass FBM haze substrate
    haze_M = _normalize(multi_scale_noise((h, w), [4.0, 12.0, 30.0], [0.42, 0.32, 0.26], int(seed) + 1711))
    haze_R = _normalize(multi_scale_noise((h, w), [3.5, 10.0, 26.0], [0.42, 0.32, 0.26], int(seed) + 1713))
    haze_CC = _normalize(multi_scale_noise((h, w), [5.0, 14.0, 34.0], [0.42, 0.32, 0.26], int(seed) + 1717))
    M = (0.48 + (haze_M - 0.5) * 0.28).astype(np.float32)
    R = (0.50 + (haze_R - 0.5) * 0.28).astype(np.float32)
    CC = (0.38 + (haze_CC - 0.5) * 0.28).astype(np.float32)

    if _CV2_OK:
        # 2) HERO: IMPACT STAR-BURST POINTS â€” 6-10 dramatic radial crack centers
        n_impacts = int(rng.integers(6, 11))
        impact_pts = []
        for _ in range(n_impacts):
            ix = float(rng.uniform(0.08, 0.92) * w)
            iy = float(rng.uniform(0.08, 0.92) * h)
            impact_pts.append((ix, iy))
            # Bright central impact splat
            r_imp = max(2, int(rng.uniform(3.5, 6.0) * scale))
            _cv2.circle(M, (int(ix), int(iy)), r_imp, float(rng.uniform(0.88, 0.99)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (int(ix), int(iy)), r_imp, float(rng.uniform(0.02, 0.18)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (int(ix), int(iy)), r_imp, float(rng.uniform(0.05, 0.25)), -1, lineType=_cv2.LINE_AA)

            # Radial crack spokes â€” 8 to 14 per impact, dramatic length
            n_spokes = int(rng.integers(8, 15))
            base_ang = float(rng.uniform(0, 2 * np.pi))
            for s in range(n_spokes):
                ang = base_ang + s * (2 * np.pi / n_spokes) + float(rng.uniform(-0.18, 0.18))
                spoke_len = float(rng.uniform(16.0, 32.0) * scale)
                # Draw as 3 tapering segments â€” brightest near impact, fading outward
                cur_x, cur_y = ix, iy
                segs = 3
                for sg in range(segs):
                    seg_len = spoke_len / segs
                    # Slight kink at each segment
                    seg_ang = ang + float(rng.uniform(-0.10, 0.10))
                    nx = cur_x + np.cos(seg_ang) * seg_len
                    ny = cur_y + np.sin(seg_ang) * seg_len
                    bright = 0.95 - sg * 0.20
                    _cv2.line(M, (int(cur_x), int(cur_y)), (int(nx), int(ny)), float(np.clip(bright, 0.30, 0.99)), 1, lineType=_cv2.LINE_AA)
                    _cv2.line(R, (int(cur_x), int(cur_y)), (int(nx), int(ny)), float(rng.uniform(0.05, 0.32)), 1, lineType=_cv2.LINE_AA)
                    _cv2.line(CC, (int(cur_x), int(cur_y)), (int(nx), int(ny)), float(rng.uniform(0.08, 0.55)), 1, lineType=_cv2.LINE_AA)
                    cur_x, cur_y = nx, ny

            # CONCENTRIC ARC FRAGMENTS â€” stress rings around impact
            n_rings = int(rng.integers(2, 5))
            for ri in range(n_rings):
                rad = float(rng.uniform(5.0, 14.0) * scale * (ri + 1))
                a0 = float(rng.uniform(0, 360))
                arc_span = float(rng.uniform(40, 140))
                _cv2.ellipse(M, (int(ix), int(iy)), (int(rad), int(rad)), 0, a0, a0 + arc_span, float(rng.uniform(0.55, 0.88)), 1, lineType=_cv2.LINE_AA)
                _cv2.ellipse(R, (int(ix), int(iy)), (int(rad), int(rad)), 0, a0, a0 + arc_span, float(rng.uniform(0.10, 0.30)), 1, lineType=_cv2.LINE_AA)
                _cv2.ellipse(CC, (int(ix), int(iy)), (int(rad), int(rad)), 0, a0, a0 + arc_span, float(rng.uniform(0.20, 0.65)), 1, lineType=_cv2.LINE_AA)

        # 3) TRIANGULAR SHARD POLYGONS â€” dense small slivers everywhere
        n_sh = int(np.clip(11000 * (mn / 2048.0) ** 2 + 1500, 3500, 18000))
        for _ in range(n_sh):
            cx = float(rng.uniform(0.01, 0.99) * w)
            cy = float(rng.uniform(0.01, 0.99) * h)
            ang0 = float(rng.uniform(0, 2 * np.pi))
            size = float(rng.uniform(2.2, 5.5) * scale)
            pts = []
            for k in range(3):
                a = ang0 + k * (2 * np.pi / 3) + float(rng.uniform(-0.4, 0.4))
                rr = size * float(rng.uniform(0.6, 1.4))
                pts.append([int(np.clip(cx + np.cos(a) * rr, 0, w - 1)),
                            int(np.clip(cy + np.sin(a) * rr, 0, h - 1))])
            pts = np.array(pts, dtype=np.int32)
            _cv2.fillPoly(M, [pts], float(rng.uniform(0.42, 0.98)), lineType=_cv2.LINE_AA)
            _cv2.fillPoly(R, [pts], float(rng.uniform(0.03, 0.48)), lineType=_cv2.LINE_AA)
            _cv2.fillPoly(CC, [pts], float(rng.uniform(0.03, 0.70)), lineType=_cv2.LINE_AA)

        # 4) BACKGROUND HAIRLINE FRACTURES â€” short, between impact zones
        n_crack = int(np.clip(1800 * (mn / 2048.0) ** 2, 500, 5500))
        for _ in range(n_crack):
            cx = int(rng.uniform(0.02, 0.98) * w); cy = int(rng.uniform(0.02, 0.98) * h)
            length = int(rng.uniform(4, 14) * scale)
            ang = float(rng.uniform(0, 2 * np.pi))
            x2 = int(np.clip(cx + np.cos(ang) * length, 0, w - 1))
            y2 = int(np.clip(cy + np.sin(ang) * length, 0, h - 1))
            _cv2.line(M, (cx, cy), (x2, y2), float(rng.uniform(0.12, 0.45)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(R, (cx, cy), (x2, y2), float(rng.uniform(0.55, 0.92)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (cx, cy), (x2, y2), float(rng.uniform(0.42, 0.85)), 1, lineType=_cv2.LINE_AA)

        # 5) CATCH-GLINT PINPRICK BLANKET â€” bright shard tips
        n_g = int(np.clip(12000 * (mn / 2048.0) ** 2, 3500, 22000))
        gy = rng.integers(0, h, n_g); gx = rng.integers(0, w, n_g)
        CC[gy, gx] = np.minimum(CC[gy, gx], rng.uniform(0.02, 0.20, n_g).astype(np.float32))
        M[gy, gx] = np.maximum(M[gy, gx], rng.uniform(0.65, 0.99, n_g).astype(np.float32))

    # 6) CHROMA DUST-FLECK POWDER â€” wide rainbow chroma
    n_dust = int(np.clip(10000 * (mn / 2048.0) ** 2, 2800, 20000))
    dy = rng.integers(0, h, n_dust); dx = rng.integers(0, w, n_dust)
    CC[dy, dx] = rng.uniform(0.05, 0.92, n_dust).astype(np.float32)
    R[dy, dx] = np.clip(R[dy, dx] + rng.uniform(-0.22, 0.25, n_dust).astype(np.float32), 0, 1)
    M[dy, dx] = np.clip(M[dy, dx] + rng.uniform(-0.10, 0.18, n_dust).astype(np.float32), 0, 1)

    out = np.stack([M, R, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
sparkle_shattered._spb_concept_complete = True

def sparkle_champagne(shape, seed, sm, density=0.05, bubble_max=10):
    """sparkle_champagne.

    identity: R6-creative â€” GLASS-FULL-OF-CHAMPAGNE with cluster nucleation
    sites and rim sparkle. Multiple hero NUCLEATION CLUSTERS (3-7 dense
    rosettes of bubbles around an invisible glass-wall site) anchor each
    upward trail chain â€” 5-10 px clustered tight, with the largest
    crowning bubbles 6-12 px showing a bright top-arc glint AND a darker
    bottom-shadow crescent (true wet sphere read). Tier-1 bubble carpet
    3-9 px independent M/R/CC. Trails curve gently as they rise. New:
    bright flute-rim sparkle BAND across the top 12% of canvas (denser
    pinpricks) and rose-gold tint bias on every 5th bubble. Micro-fizz
    fills every gap so no substrate shows.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + (hash("sparkle_champagne_r6c") % 10000))
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)
    px_unit = max(scale, 0.7)

    # Warm champagne substrate
    warm = _normalize(multi_scale_noise((h, w), [8.0, 22.0, 60.0],
                                        [0.40, 0.32, 0.28], int(seed) + 821))
    M = (0.62 + (warm - 0.5) * 0.22).astype(np.float32)
    R = (0.42 + (warm - 0.5) * 0.20).astype(np.float32)
    CC = (0.30 + (warm - 0.5) * 0.20).astype(np.float32)

    if _CV2_OK:
        # 1) HERO NUCLEATION CLUSTERS â€” rosettes of dense bubbles
        n_clusters = int(np.clip(40 + 25 * (mn / 256.0), 12, 180))
        for _ in range(n_clusters):
            cx_n = int(rng.uniform(0.04, 0.96) * w)
            cy_n = int(rng.uniform(0.18, 0.96) * h)
            cluster_tint = float(rng.uniform(0.10, 0.92))
            n_bb = int(rng.integers(4, 9))
            for k in range(n_bb):
                off_a = float(rng.uniform(0, 2 * np.pi))
                off_r = float(rng.uniform(1.0, 7.0) * px_unit)
                bx = int(cx_n + np.cos(off_a) * off_r)
                by = int(cy_n + np.sin(off_a) * off_r)
                if not (0 <= bx < w and 0 <= by < h): continue
                rb = max(2, int(rng.uniform(2.0, 6.0) * px_unit))
                _cv2.circle(M, (bx, by), rb, float(rng.uniform(0.75, 0.99)), -1, lineType=_cv2.LINE_AA)
                _cv2.circle(R, (bx, by), rb, float(rng.uniform(0.04, 0.24)), -1, lineType=_cv2.LINE_AA)
                _cv2.circle(CC, (bx, by), rb, float(cluster_tint + rng.uniform(-0.08, 0.08)), -1, lineType=_cv2.LINE_AA)
                # crown bubble â€” top arc glint + bottom shadow crescent
                if rb >= 3:
                    gx = int(bx + rb * 0.30); gy = int(by - rb * 0.45)
                    _cv2.circle(M, (gx, gy), max(1, rb // 3), float(rng.uniform(0.90, 0.99)), -1, lineType=_cv2.LINE_AA)
                    sx = int(bx - rb * 0.20); sy = int(by + rb * 0.50)
                    _cv2.circle(M, (sx, sy), max(1, rb // 4), float(rng.uniform(0.30, 0.55)), -1, lineType=_cv2.LINE_AA)

        # 2) Tier-1 bubble carpet (existing 7x density)
        n_bub = int(np.clip(h * w * float(density) * 3.0, 2800, 38000))
        for i in range(n_bub):
            cx = int(rng.uniform(0.0, 1.0) * w)
            cy = int(rng.uniform(0.0, 1.0) * h)
            r_b = max(2, int(rng.uniform(1.4, max(3.0, float(bubble_max)) * 0.45) * px_unit))
            m_v = float(rng.uniform(0.55, 0.98))
            r_v = float(rng.uniform(0.05, 0.40))
            # every 5th bubble = rose-gold tint, others wide chroma
            if i % 5 == 0:
                cc_v = float(rng.uniform(0.62, 0.92))
            else:
                cc_v = float(rng.uniform(0.05, 0.92))
            _cv2.circle(M, (cx, cy), r_b, m_v, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r_b, r_v, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r_b, cc_v, -1, lineType=_cv2.LINE_AA)
            if r_b > 2:
                gx = int(cx + r_b * 0.30); gy = int(cy - r_b * 0.45)
                _cv2.circle(M, (gx, gy), max(1, r_b // 3),
                            float(rng.uniform(0.85, 0.99)), -1, lineType=_cv2.LINE_AA)

        # 3) CURVING upward bubble trails (more chains, with drift)
        n_trail = int(np.clip(800 * (mn / 2048.0) ** 2 + 200, 200, 3500))
        for _ in range(n_trail):
            cx = float(rng.uniform(0.02, 0.98) * w)
            cy = float(rng.uniform(0.05, 0.99) * h)
            seg = int(rng.integers(5, 12))
            cc_tint = float(rng.uniform(0.08, 0.92))
            drift_x = float(rng.uniform(-0.6, 0.6))
            for s in range(seg):
                yy_p = int(cy - s * rng.uniform(2.5, 5.0) * px_unit)
                cx += drift_x  # gentle horizontal drift
                if yy_p < 0: break
                xx_p = int(cx + rng.uniform(-2, 2))
                rr = max(1, int(rng.uniform(1.0, 2.4) * px_unit))
                _cv2.circle(M, (xx_p, yy_p), rr,
                            float(rng.uniform(0.65, 0.97)), -1, lineType=_cv2.LINE_AA)
                _cv2.circle(CC, (xx_p, yy_p), rr, cc_tint, -1, lineType=_cv2.LINE_AA)

        # 4) MICRO-FIZZ â€” single-pixel nuclei everywhere
        n_fizz = max(20000, int(h * w / 22))
        fy = rng.integers(0, h, n_fizz); fx = rng.integers(0, w, n_fizz)
        M[fy, fx] = np.maximum(M[fy, fx], rng.uniform(0.55, 0.97, n_fizz).astype(np.float32))
        CC[fy, fx] = rng.uniform(0.08, 0.94, n_fizz).astype(np.float32)
        R[fy, fx] = np.minimum(R[fy, fx], rng.uniform(0.04, 0.30, n_fizz).astype(np.float32))

        # 5) FLUTE-RIM SPARKLE BAND â€” top 12% of canvas, denser pinpricks
        rim_h = max(4, int(h * 0.12))
        n_rim = int(np.clip(rim_h * w * 0.10, 600, 12000))
        ry_rim = rng.integers(0, rim_h, n_rim).astype(np.int32)
        rx_rim = rng.integers(0, w, n_rim).astype(np.int32)
        M[ry_rim, rx_rim] = np.maximum(M[ry_rim, rx_rim], rng.uniform(0.88, 0.99, n_rim).astype(np.float32))
        R[ry_rim, rx_rim] = np.minimum(R[ry_rim, rx_rim], rng.uniform(0.02, 0.10, n_rim).astype(np.float32))
        CC[ry_rim, rx_rim] = rng.uniform(0.55, 0.96, n_rim).astype(np.float32)

        # 6) Bright catch-glint pinpricks (full canvas)
        n_glint = int(np.clip(5500 * (mn / 2048.0) ** 2 + 800, 900, 9000))
        ly = rng.integers(0, h, n_glint); lx = rng.integers(0, w, n_glint)
        M[ly, lx] = np.maximum(M[ly, lx], rng.uniform(0.85, 0.99, n_glint).astype(np.float32))
        CC[ly, lx] = np.maximum(CC[ly, lx], rng.uniform(0.55, 0.96, n_glint).astype(np.float32))

    out = np.stack([M, R, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
sparkle_champagne._spb_concept_complete = True

def sparkle_comet(shape, seed, sm, n_comets=850, tail_len=18):
    """sparkle_comet.

    identity: STRUCTURAL COLOR GRATING v2 (HOLY GRAIL â€” angle-dependent rainbow).
    Canvas divided into 70-120 SMALL Voronoi zones (5x denser than v1) â€” each
    zone is small enough to read as a fine facet, not a panel-scale blob. Per
    zone: 1-3 px alternating M=high/M=low micro-stripes at a ZONE-SPECIFIC
    random orientation. High-frequency M oscillation preserves the GGX
    angle-dependent rainbow on a car body. 12-24 small rosette "eye" zones
    (12-20 px radius) scattered throughout. CC max gloss everywhere. R
    ultra-low (mirror).
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 911009)

    M = np.full((h, w), 0.50, dtype=np.float32)
    R_ch = np.full((h, w), 0.06, dtype=np.float32)  # ultra-low R = mirror
    CC = np.full((h, w), 0.94, dtype=np.float32)  # high gloss

    # 5x denser zones â€” 70-120 small facets instead of 14-24 big ones
    n_zones = int(rng.integers(70, 121))
    seeds_y = rng.uniform(0, h, n_zones).astype(np.float32)
    seeds_x = rng.uniform(0, w, n_zones).astype(np.float32)
    zone_angles = rng.uniform(0, np.pi, n_zones).astype(np.float32)
    zone_pitches = rng.uniform(2.0, 4.0, n_zones).astype(np.float32)
    zone_stripe_w = rng.uniform(1.0, 2.0, n_zones).astype(np.float32)

    # 12-24 small rosette "eye" zones (vs 2-4 large in v1)
    n_eyes = int(rng.integers(12, 25))
    n_eyes = min(n_eyes, n_zones)
    eye_idxs = rng.choice(n_zones, size=n_eyes, replace=False)
    eye_set = set(int(i) for i in eye_idxs)
    # Per-eye small radius cap (12-20 px) â†’ applied as eye_max_r mask
    eye_max_r = {int(i): float(rng.uniform(12.0, 20.0)) for i in eye_idxs}

    yy = np.arange(h, dtype=np.float32)[:, None]
    xx = np.arange(w, dtype=np.float32)[None, :]

    # Nearest-zone assignment
    zone_idx = np.zeros((h, w), dtype=np.int32)
    min_d = np.full((h, w), 1e18, dtype=np.float32)
    for zi in range(n_zones):
        d = (yy - seeds_y[zi]) ** 2 + (xx - seeds_x[zi]) ** 2
        mask = d < min_d
        zone_idx = np.where(mask, zi, zone_idx)
        min_d = np.where(mask, d, min_d)

    for zi in range(n_zones):
        m = (zone_idx == zi)
        if not m.any():
            continue
        a = float(zone_angles[zi])
        pitch = float(zone_pitches[zi])
        sw = float(zone_stripe_w[zi])
        if zi in eye_set:
            # Concentric rosette â€” but clipped to a SMALL radius (12-20 px)
            r_loc = np.sqrt((yy - seeds_y[zi]) ** 2 + (xx - seeds_x[zi]) ** 2)
            stripe = (np.mod(r_loc, pitch) < sw).astype(np.float32)
            # outside eye radius, fall back to linear grating so the rest of
            # the (small) Voronoi cell still gets micro-stripes
            in_eye = (r_loc <= eye_max_r[zi])
            proj = xx * np.cos(a) + yy * np.sin(a)
            linear_stripe = (np.mod(proj, pitch) < sw).astype(np.float32)
            stripe = np.where(in_eye, stripe, linear_stripe)
        else:
            proj = xx * np.cos(a) + yy * np.sin(a)
            stripe = (np.mod(proj, pitch) < sw).astype(np.float32)
        # High-freq M oscillation = diffraction-grating preserved
        zone_M = np.where(stripe > 0.5, 0.99, 0.02)
        M[m] = zone_M[m]
        # Per-zone CC sweeps the FULL spectrum 0.05-0.99 so the thumbnail
        # composite reads as actual rainbow (red/orange/yellow/green/blue
        # zones across canvas) â€” not just pink-magenta. R also varies wider
        # to add the warm-cool color spectrum visible in the composite.
        CC[m] = float(rng.uniform(0.05, 0.99))
        R_ch[m] = float(rng.uniform(0.02, 0.55))

    # Sub-pixel chroma jitter at seams
    CC = np.clip(CC + rng.uniform(-0.04, 0.04, (h, w)).astype(np.float32), 0.0, 1.0)
    M = np.clip(M, 0.0, 1.0)
    R_ch = np.clip(R_ch, 0.0, 1.0)

    out = np.stack([M, R_ch, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
sparkle_comet._spb_concept_complete = True


def sparkle_galaxy_swirl(shape, seed, sm, n_arms=3, density=0.008):
    """sparkle_galaxy_swirl.

    identity: R6 creative rebuild â€” a full barred-spiral galaxy reading
    at thumbnail scale. HERO #1: a bright HOT CORE bulge (radial
    falloff, brightest M/CC, hottest star density) clearly visible as
    the galactic center. HERO #2: a CENTRAL BAR cutting through the
    core (the "barred" in barred-spiral) â€” bright stretched ellipse
    feeding into the arms. HERO #3: COLORED NEBULA CLOUDS scattered
    along the arms â€” small 8-18 px irregular tinted clusters where
    star-forming regions glow (red H-alpha, blue O-III, pink mixed).
    Plus: spiral-arm star carpets (1-3 px), arm star knots, inter-arm
    dust-lane FBM substrate, micro-twinkle background, and a sweep of
    foreground globular cluster blobs (2-4 px high-density spots). Each
    primitive draws independent continuous M/R/CC. Full canvas
    coverage; no blank inter-arm voids.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + (hash("sparkle_galaxy_swirl_r6") % 10000))
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)

    # 1) Per-channel deep-space dust-lane substrate
    dust_M = _normalize(multi_scale_noise((h, w), [14.0, 38.0, 85.0],
                                            [0.35, 0.35, 0.30], int(seed) + 1411))
    dust_R = _normalize(multi_scale_noise((h, w), [12.0, 32.0, 75.0],
                                            [0.35, 0.35, 0.30], int(seed) + 1413))
    dust_CC = _normalize(multi_scale_noise((h, w), [16.0, 44.0, 95.0],
                                             [0.35, 0.35, 0.30], int(seed) + 1417))
    M = (0.28 + (dust_M - 0.5) * 0.20).astype(np.float32)
    R = (0.74 + (dust_R - 0.5) * 0.22).astype(np.float32)
    CC = (0.52 + (dust_CC - 0.5) * 0.30).astype(np.float32)

    # Galaxy geometry
    cy_g = h * 0.5 + float(rng.uniform(-0.05, 0.05)) * h
    cx_g = w * 0.5 + float(rng.uniform(-0.05, 0.05)) * w
    n_a = max(int(n_arms), 2)
    pitch = float(rng.uniform(0.18, 0.32))
    bar_ang = float(rng.uniform(0, np.pi))

    # 2) HERO #1 â€” HOT CORE BULGE. Soft radial gaussian boost in M & CC.
    yy, xx = np.mgrid[0:h, 0:w].astype(np.float32)
    rr = np.sqrt((xx - cx_g) ** 2 + (yy - cy_g) ** 2)
    core_sigma = max(mn * 0.10, 8.0)
    core = np.exp(-(rr * rr) / (2.0 * core_sigma * core_sigma)).astype(np.float32)
    M = np.clip(M + core * 0.55, 0, 1)
    CC = np.clip(CC - core * 0.35, 0, 1)
    R = np.clip(R - core * 0.45, 0, 1)

    if _CV2_OK:
        # 3) HERO #2 â€” CENTRAL BAR. Bright stretched ellipse through core.
        bar_len = int(mn * 0.32)
        bar_thk = int(max(2, mn * 0.06))
        _cv2.ellipse(M, (int(cx_g), int(cy_g)), (bar_len, bar_thk),
                     float(np.degrees(bar_ang)), 0, 360,
                     float(rng.uniform(0.85, 0.97)), -1, lineType=_cv2.LINE_AA)
        _cv2.ellipse(R, (int(cx_g), int(cy_g)), (bar_len, bar_thk),
                     float(np.degrees(bar_ang)), 0, 360,
                     float(rng.uniform(0.06, 0.20)), -1, lineType=_cv2.LINE_AA)
        _cv2.ellipse(CC, (int(cx_g), int(cy_g)), (bar_len, bar_thk),
                     float(np.degrees(bar_ang)), 0, 360,
                     float(rng.uniform(0.05, 0.22)), -1, lineType=_cv2.LINE_AA)

        # 4) ARM-STARS â€” packed along log-spiral arms
        n_stars_total = int(np.clip(h * w * float(density) * 6.0, 5000, 42000))
        for _ in range(n_stars_total):
            arm = int(rng.integers(0, n_a))
            r_polar = float(rng.uniform(0.04, 0.58)) * mn
            theta0 = (2 * np.pi / n_a) * arm
            theta = theta0 + np.log(max(r_polar, 1.0)) / pitch
            theta += float(rng.normal(0, 0.20))
            sx = int(np.clip(cx_g + np.cos(theta) * r_polar, 0, w - 1))
            sy = int(np.clip(cy_g + np.sin(theta) * r_polar, 0, h - 1))
            r_s = max(1, int(rng.uniform(1.2, 2.4) * scale))
            # color-temperature draw â€” hot blue (low R, low CC) to red-shifted (mid R, mid CC)
            star_M = float(rng.uniform(0.55, 0.99))
            star_R = float(rng.uniform(0.05, 0.45))
            star_CC = float(rng.uniform(0.04, 0.65))
            _cv2.circle(M, (sx, sy), r_s, star_M, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (sx, sy), r_s, star_R, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (sx, sy), r_s, star_CC, -1, lineType=_cv2.LINE_AA)

        # 5) HERO #3 â€” COLORED NEBULA CLOUDS. Each is a small irregular
        # cluster of overlapping soft discs with strongly tinted M/R/CC.
        n_neb = int(np.clip(48 * (mn / 256.0) ** 2, 32, 220))
        for _ in range(n_neb):
            # bias positions along arms â€” pick a random arm coord
            arm = int(rng.integers(0, n_a))
            r_polar = float(rng.uniform(0.08, 0.55)) * mn
            theta0 = (2 * np.pi / n_a) * arm
            theta = theta0 + np.log(max(r_polar, 1.0)) / pitch
            theta += float(rng.normal(0, 0.30))
            ncx = float(np.clip(cx_g + np.cos(theta) * r_polar, 0, w - 1))
            ncy = float(np.clip(cy_g + np.sin(theta) * r_polar, 0, h - 1))
            # nebula tint family â€” H-alpha red, O-III blue-green, pink mix
            family = int(rng.integers(0, 3))
            if family == 0:  # H-alpha â€” hot pink-red, low CC
                nM = float(rng.uniform(0.60, 0.88)); nR = float(rng.uniform(0.48, 0.78)); nCC = float(rng.uniform(0.08, 0.28))
            elif family == 1:  # O-III â€” bluish, very low CC
                nM = float(rng.uniform(0.70, 0.96)); nR = float(rng.uniform(0.06, 0.22)); nCC = float(rng.uniform(0.04, 0.16))
            else:  # mixed pink
                nM = float(rng.uniform(0.68, 0.92)); nR = float(rng.uniform(0.30, 0.62)); nCC = float(rng.uniform(0.10, 0.40))
            # 4-7 overlapping wisps
            n_wisp = int(rng.integers(4, 8))
            for _w in range(n_wisp):
                ox = ncx + float(rng.uniform(-6, 6)) * scale
                oy = ncy + float(rng.uniform(-6, 6)) * scale
                rr_w = int(max(2, rng.uniform(3.0, 7.0) * scale))
                _cv2.circle(M, (int(ox), int(oy)), rr_w, nM, -1, lineType=_cv2.LINE_AA)
                _cv2.circle(R, (int(ox), int(oy)), rr_w, nR, -1, lineType=_cv2.LINE_AA)
                _cv2.circle(CC, (int(ox), int(oy)), rr_w, nCC, -1, lineType=_cv2.LINE_AA)

        # 6) ARM KNOTS â€” bright star-cluster spots along arms
        n_knot = int(np.clip(320 * (mn / 2048.0) ** 2 + 60, 60, 900))
        for _ in range(n_knot):
            arm = int(rng.integers(0, n_a))
            r_polar = float(rng.uniform(0.06, 0.55)) * mn
            theta0 = (2 * np.pi / n_a) * arm
            theta = theta0 + np.log(max(r_polar, 1.0)) / pitch
            sx = int(np.clip(cx_g + np.cos(theta) * r_polar, 0, w - 1))
            sy = int(np.clip(cy_g + np.sin(theta) * r_polar, 0, h - 1))
            r_k = max(2, int(rng.uniform(3, 6) * scale))
            _cv2.circle(M, (sx, sy), r_k, float(rng.uniform(0.78, 0.99)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (sx, sy), r_k, float(rng.uniform(0.05, 0.28)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (sx, sy), r_k, float(rng.uniform(0.04, 0.42)), -1, lineType=_cv2.LINE_AA)

        # 7) GLOBULAR CLUSTERS â€” foreground bright blobs scattered randomly
        n_glob = int(np.clip(140 * (mn / 256.0) ** 2, 80, 540))
        for _ in range(n_glob):
            gx_p = int(rng.uniform(0, w)); gy_p = int(rng.uniform(0, h))
            r_g = max(1, int(rng.uniform(2.0, 4.0) * scale))
            _cv2.circle(M, (gx_p, gy_p), r_g, float(rng.uniform(0.70, 0.98)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (gx_p, gy_p), r_g, float(rng.uniform(0.06, 0.28)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (gx_p, gy_p), r_g, float(rng.uniform(0.05, 0.40)), -1, lineType=_cv2.LINE_AA)

    # 8) Off-arm star carpet â€” full coverage, no blank voids
    n_off = int(np.clip(18000 * (mn / 2048.0) ** 2, 5500, 32000))
    oy = rng.integers(0, h, n_off); ox = rng.integers(0, w, n_off)
    M[oy, ox] = np.maximum(M[oy, ox], rng.uniform(0.40, 0.85, n_off).astype(np.float32))
    CC[oy, ox] = rng.uniform(0.05, 0.75, n_off).astype(np.float32)

    # 9) Micro-twinkle pinpricks â€” single-px deep CC dips
    n_tw = int(np.clip(12000 * (mn / 2048.0) ** 2, 3000, 25000))
    ty = rng.integers(0, h, n_tw); tx = rng.integers(0, w, n_tw)
    CC[ty, tx] = np.minimum(CC[ty, tx], rng.uniform(0.03, 0.22, n_tw).astype(np.float32))

    out = np.stack([M, R, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
sparkle_galaxy_swirl._spb_concept_complete = True

def sparkle_electric_field(shape, seed, sm, density=0.01):
    """sparkle_electric_field.

    identity: R6 second-pass â€” plasma chamber gone critical with NEW
    DIFFERENTIATORS layered on prior heroes:
      (i) Per-channel ionised-haze FBM substrate.
      (ii) Lightning fragments (5x density, finer pieces 6-18 px).
      (iii) Corona pinprick carpet.
      (iv) Soft arc-glow halos.
      (v) HERO: ION-PULSE ORBS (core + 2-3 concentric rings).
      (vi) HERO: PLASMA TENDRIL CURLS (curling arcs).
      (vii) NEW DIFFERENTIATOR â€” CAPACITOR DISCHARGE STARS: 6-pointed
            plasma flares (cross-arms + 2 diagonals), 6-12 px reach,
            evoking a high-voltage flashpoint with cruciform spike
            symmetry distinct from the round orbs.
      (viii) NEW DIFFERENTIATOR â€” TESLA-COIL FORK-CHAINS: recursive
            bifurcating bolts that split into 2 children at each
            node, 3 generations deep, finer 4-8 px segments â€”
            unmistakable fractal lightning vs the prior straight
            zig-zag fragments.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + (hash("sparkle_electric_field") % 10000))
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)

    # 1) Per-channel ionised-haze substrate
    haze_M = _normalize(multi_scale_noise((h, w), [6.0, 16.0, 40.0],
                                            [0.40, 0.32, 0.28], int(seed) + 1217))
    haze_R = _normalize(multi_scale_noise((h, w), [5.0, 14.0, 34.0],
                                            [0.40, 0.32, 0.28], int(seed) + 1219))
    haze_CC = _normalize(multi_scale_noise((h, w), [7.0, 18.0, 44.0],
                                             [0.40, 0.32, 0.28], int(seed) + 1223))
    M = (0.38 + (haze_M - 0.5) * 0.26).astype(np.float32)
    R = (0.60 + (haze_R - 0.5) * 0.22).astype(np.float32)
    CC = (0.40 + (haze_CC - 0.5) * 0.28).astype(np.float32)

    if _CV2_OK:
        # 2) Lightning fragments â€” 5x density, smaller pieces, packed tight
        n_frag = int(np.clip(h * w * float(density) * 1.6, 2200, 16000))
        for _ in range(n_frag):
            cx = float(rng.uniform(0.01, 0.99) * w)
            cy = float(rng.uniform(0.01, 0.99) * h)
            n_seg = int(rng.integers(2, 5))
            # INDEPENDENT continuous M/R/CC per fragment
            frag_M = float(rng.uniform(0.55, 0.99))
            frag_R = float(rng.uniform(0.04, 0.45))
            frag_CC = float(rng.uniform(0.03, 0.65))
            ang = float(rng.uniform(0, 2 * np.pi))
            pts = [(int(cx), int(cy))]
            for s in range(n_seg):
                ang += float(rng.uniform(-1.3, 1.3))
                length = float(rng.uniform(2.0, 5.5) * scale)
                nx = pts[-1][0] + np.cos(ang) * length
                ny = pts[-1][1] + np.sin(ang) * length
                pts.append((int(np.clip(nx, 0, w - 1)), int(np.clip(ny, 0, h - 1))))
            for i in range(len(pts) - 1):
                _cv2.line(M, pts[i], pts[i + 1], frag_M, 1, lineType=_cv2.LINE_AA)
                _cv2.line(R, pts[i], pts[i + 1], frag_R, 1, lineType=_cv2.LINE_AA)
                _cv2.line(CC, pts[i], pts[i + 1], frag_CC, 1, lineType=_cv2.LINE_AA)
            # 30% chance: small branch off the middle
            if rng.random() < 0.30 and len(pts) >= 2:
                mid = pts[len(pts) // 2]
                b_ang = ang + float(rng.uniform(-2.0, 2.0))
                b_len = float(rng.uniform(2.0, 4.0) * scale)
                bx = int(np.clip(mid[0] + np.cos(b_ang) * b_len, 0, w - 1))
                by = int(np.clip(mid[1] + np.sin(b_ang) * b_len, 0, h - 1))
                _cv2.line(M, mid, (bx, by), float(rng.uniform(0.50, 0.90)), 1, lineType=_cv2.LINE_AA)
                _cv2.line(CC, mid, (bx, by), float(rng.uniform(0.05, 0.55)), 1, lineType=_cv2.LINE_AA)

        # 3) Corona pinprick carpet (5x)
        n_cor = int(np.clip(12000 * (mn / 2048.0) ** 2, 3500, 25000))
        cy_ = rng.integers(0, h, n_cor); cx_ = rng.integers(0, w, n_cor)
        M[cy_, cx_] = np.maximum(M[cy_, cx_], rng.uniform(0.55, 0.97, n_cor).astype(np.float32))
        CC[cy_, cx_] = rng.uniform(0.04, 0.65, n_cor).astype(np.float32)
        R[cy_, cx_] = np.minimum(R[cy_, cx_], rng.uniform(0.04, 0.30, n_cor).astype(np.float32))

        # 4) Arc-glow halos (more)
        n_halo = int(np.clip(800 * (mn / 2048.0) ** 2, 220, 2200))
        for _ in range(n_halo):
            cx = int(rng.uniform(0.02, 0.98) * w); cy = int(rng.uniform(0.02, 0.98) * h)
            r_h = max(2, int(rng.uniform(4, 9) * scale))
            _cv2.circle(R, (cx, cy), r_h, float(rng.uniform(0.25, 0.60)),
                        -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r_h, float(rng.uniform(0.20, 0.70)),
                        -1, lineType=_cv2.LINE_AA)

        # 5) HERO â€” ION-PULSE ORBS (core + 2-3 expanding electric rings)
        n_orb = int(np.clip(450 * (mn / 2048.0) ** 2, 140, 1600))
        for _ in range(n_orb):
            cx = int(rng.uniform(0.03, 0.97) * w); cy = int(rng.uniform(0.03, 0.97) * h)
            r_core = max(2, int(rng.uniform(2.0, 4.0) * scale))
            oM = float(rng.uniform(0.72, 0.99))
            oR = float(rng.uniform(0.05, 0.30))
            oCC = float(rng.uniform(0.04, 0.55))
            _cv2.circle(M, (cx, cy), r_core, oM, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r_core, oR, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r_core, oCC, -1, lineType=_cv2.LINE_AA)
            n_rings = int(rng.integers(2, 4))
            for k in range(n_rings):
                rr_ring = r_core + int(rng.uniform(2.0, 5.0) * scale) * (k + 1)
                rM = float(rng.uniform(0.45, 0.88))
                rCC = float(rng.uniform(0.08, 0.55))
                _cv2.circle(M, (cx, cy), rr_ring, rM, 1, lineType=_cv2.LINE_AA)
                _cv2.circle(CC, (cx, cy), rr_ring, rCC, 1, lineType=_cv2.LINE_AA)

        # 6) HERO â€” PLASMA TENDRIL CURLS (8-14 px curling arc segments)
        n_tendril = int(np.clip(1200 * (mn / 2048.0) ** 2, 400, 4500))
        for _ in range(n_tendril):
            cx = int(rng.uniform(0.03, 0.97) * w); cy = int(rng.uniform(0.03, 0.97) * h)
            r_t = max(3, int(rng.uniform(4.0, 7.0) * scale))
            a0 = float(rng.uniform(0, 360)); sweep = float(rng.uniform(110, 280))
            tM = float(rng.uniform(0.58, 0.96))
            tR = float(rng.uniform(0.04, 0.28))
            tCC = float(rng.uniform(0.06, 0.65))
            ecc = float(rng.uniform(0.55, 0.95))
            ry = max(2, int(r_t * ecc))
            rot = float(rng.uniform(-60, 60))
            _cv2.ellipse(M, (cx, cy), (r_t, ry), rot, a0, a0 + sweep, tM, 1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(R, (cx, cy), (r_t, ry), rot, a0, a0 + sweep, tR, 1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(CC, (cx, cy), (r_t, ry), rot, a0, a0 + sweep, tCC, 1, lineType=_cv2.LINE_AA)

        # 7) NEW DIFFERENTIATOR â€” CAPACITOR DISCHARGE STARS (6-pointed flares)
        s256 = max(mn / 256.0, 0.6)
        n_star = int(np.clip(380 * s256 * s256, 110, 1400))
        for _ in range(n_star):
            cx = int(rng.uniform(0.04, 0.96) * w); cy = int(rng.uniform(0.04, 0.96) * h)
            arm_len = max(2, int(rng.uniform(3.0, 6.0) * s256))
            base_rot = float(rng.uniform(0, np.pi / 3))
            # bright cruciform core
            sM = float(rng.uniform(0.78, 0.99))
            sR = float(rng.uniform(0.03, 0.20))
            sCC = float(rng.uniform(0.04, 0.45))
            for k in range(6):
                ang = base_rot + (np.pi / 3) * k
                x1 = int(cx + np.cos(ang) * arm_len)
                y1 = int(cy + np.sin(ang) * arm_len)
                _cv2.line(M, (cx, cy), (x1, y1), sM, 1, lineType=_cv2.LINE_AA)
                _cv2.line(R, (cx, cy), (x1, y1), sR, 1, lineType=_cv2.LINE_AA)
                _cv2.line(CC, (cx, cy), (x1, y1), sCC, 1, lineType=_cv2.LINE_AA)
            # core dot
            _cv2.circle(M, (cx, cy), 1, float(rng.uniform(0.85, 0.99)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), 1, float(rng.uniform(0.03, 0.14)), -1, lineType=_cv2.LINE_AA)

        # 8) NEW DIFFERENTIATOR â€” TESLA-COIL FORK-CHAINS (recursive 3-gen bolts)
        n_fork = int(np.clip(180 * s256 * s256, 50, 700))
        def _fork(x0, y0, ang, length, depth, parent_M, parent_R, parent_CC):
            if depth <= 0 or length < 2.0:
                return
            x1 = x0 + np.cos(ang) * length
            y1 = y0 + np.sin(ang) * length
            p0 = (int(np.clip(x0, 0, w - 1)), int(np.clip(y0, 0, h - 1)))
            p1 = (int(np.clip(x1, 0, w - 1)), int(np.clip(y1, 0, h - 1)))
            _cv2.line(M, p0, p1, parent_M, 1, lineType=_cv2.LINE_AA)
            _cv2.line(R, p0, p1, parent_R, 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, p0, p1, parent_CC, 1, lineType=_cv2.LINE_AA)
            # bifurcate into 2 children
            split_ang = float(rng.uniform(0.45, 1.05))
            child_len = length * float(rng.uniform(0.55, 0.78))
            childM_a = float(rng.uniform(0.55, 0.95))
            childR_a = float(rng.uniform(0.04, 0.28))
            childCC_a = float(rng.uniform(0.05, 0.55))
            childM_b = float(rng.uniform(0.55, 0.95))
            childR_b = float(rng.uniform(0.04, 0.28))
            childCC_b = float(rng.uniform(0.05, 0.55))
            _fork(x1, y1, ang - split_ang, child_len, depth - 1, childM_a, childR_a, childCC_a)
            _fork(x1, y1, ang + split_ang, child_len, depth - 1, childM_b, childR_b, childCC_b)
        for _ in range(n_fork):
            sx = float(rng.uniform(0.05, 0.95) * w); sy = float(rng.uniform(0.05, 0.95) * h)
            s_ang = float(rng.uniform(0, 2 * np.pi))
            s_len = float(rng.uniform(4.0, 7.0) * s256)
            rootM = float(rng.uniform(0.72, 0.99))
            rootR = float(rng.uniform(0.03, 0.18))
            rootCC = float(rng.uniform(0.05, 0.50))
            _fork(sx, sy, s_ang, s_len, 3, rootM, rootR, rootCC)

    out = np.stack([M, R, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
sparkle_electric_field._spb_concept_complete = True

def tire_rubber_transfer(shape, seed, sm, block_w=42.0, block_h=64.0, **kwargs):
    """tire_rubber_transfer.

    identity: R6 creative pass â€” a black-streaked asphalt panel where
    tire-tread rubber stamped onto pavement, now with NEW HEROES:
    (A) TIRE-CONFETTI CURLED RUBBER SHAVINGS â€” 6-14 px curled
    crescent fragments (curls of rubber peeled off the tread) read as
    little black commas scattered through the wear; (B) GRAVEL-IMPACT
    STAR-CRACKS â€” small 5-10 px 4-pointed asterisk impact marks
    where stones chipped the asphalt. Plus the existing tread-block
    stamps, siping kerfs, skid-arc fragments, smear streaks, sandy
    aggregate bright dots, micro-pit pocks, bright-fleck accents.
    Every primitive 1-22 px (no panel-scale). Per-feature INDEPENDENT
    continuous M/R/CC uniforms; NO palette.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 50212)
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)

    # 1) ASPHALT SUBSTRATE â€” gritty FBM, INDEPENDENT M/R/CC fields
    fM = _normalize(multi_scale_noise(shape, [1.5, 4.0, 11.0, 28.0], [0.35, 0.30, 0.22, 0.13], int(seed) + 4811))
    fR = _normalize(multi_scale_noise(shape, [2.0, 6.0, 14.0, 30.0], [0.40, 0.28, 0.20, 0.12], int(seed) + 4812))
    fCC = _normalize(multi_scale_noise(shape, [2.5, 7.0, 18.0, 36.0], [0.40, 0.30, 0.18, 0.12], int(seed) + 4813))
    M = (0.42 + (fM - 0.5) * 0.32).astype(np.float32)
    R_ch = (0.60 + (fR - 0.5) * 0.34).astype(np.float32)
    CC = (0.55 + (fCC - 0.5) * 0.32).astype(np.float32)

    if _CV2_OK:
        # 2) TREAD BLOCK STAMPS â€” 2x density, 8-18 px
        n_blocks = int(np.clip(1500 * (mn / 2048.0) ** 2, 520, 4800))
        for _ in range(n_blocks):
            cx = int(rng.uniform(0.02, 0.98) * w); cy = int(rng.uniform(0.02, 0.98) * h)
            bw = int(max(3, rng.uniform(5.0, 13.0) * scale))
            bh = int(max(3, rng.uniform(6.0, 16.0) * scale))
            x0 = max(0, cx - bw // 2); x1 = min(w, cx + bw // 2)
            y0 = max(0, cy - bh // 2); y1 = min(h, cy + bh // 2)
            _cv2.rectangle(M,  (x0, y0), (x1, y1), float(rng.uniform(0.08, 0.30)), -1)
            _cv2.rectangle(R_ch,(x0, y0), (x1, y1), float(rng.uniform(0.74, 0.96)), -1)
            _cv2.rectangle(CC, (x0, y0), (x1, y1), float(rng.uniform(0.68, 0.94)), -1)
            # 3) SIPING KERF â€” horizontal slot inside block
            if bh >= 4 and rng.random() < 0.75:
                ky = y0 + bh // 2
                _cv2.line(M, (x0 + 1, ky), (x1 - 1, ky), float(rng.uniform(0.04, 0.16)), 1, lineType=_cv2.LINE_AA)

        # 4) SKID ARC FRAGMENTS â€” NEW differentiator, curved 5-14 px rubber arcs
        n_arc = int(np.clip(900 * (mn / 2048.0) ** 2, 320, 2800))
        for _ in range(n_arc):
            cx = int(rng.uniform(0.02, 0.98) * w); cy = int(rng.uniform(0.02, 0.98) * h)
            r = max(3, int(rng.uniform(3.5, 7.0) * scale))
            start = int(rng.uniform(0, 360)); sweep = int(rng.uniform(40, 120))
            _cv2.ellipse(M,  (cx, cy), (r, r), 0, start, start + sweep, float(rng.uniform(0.06, 0.24)), 1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(R_ch,(cx, cy), (r, r), 0, start, start + sweep, float(rng.uniform(0.72, 0.94)), 1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(CC, (cx, cy), (r, r), 0, start, start + sweep, float(rng.uniform(0.55, 0.88)), 1, lineType=_cv2.LINE_AA)

        # 5) SMEAR FRAGMENTS â€” 6-14 px dark rubber streaks at multiple angles
        n_smear = int(np.clip(1100 * (mn / 2048.0) ** 2, 380, 3400))
        for _ in range(n_smear):
            cx_p = rng.uniform(0.02, 0.98) * w; cy_p = rng.uniform(0.02, 0.98) * h
            length = float(rng.uniform(6.0, 14.0) * scale)
            ang = float(rng.uniform(-0.6, 0.6))
            x2 = int(np.clip(cx_p + np.cos(ang) * length, 0, w - 1))
            y2 = int(np.clip(cy_p + np.sin(ang) * length, 0, h - 1))
            _cv2.line(M,  (int(cx_p), int(cy_p)), (x2, y2), float(rng.uniform(0.06, 0.24)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(R_ch,(int(cx_p), int(cy_p)), (x2, y2), float(rng.uniform(0.74, 0.95)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (int(cx_p), int(cy_p)), (x2, y2), float(rng.uniform(0.55, 0.88)), 1, lineType=_cv2.LINE_AA)

        # 6) AGGREGATE BRIGHT DOTS â€” sandy asphalt 2-4 px specks
        n_agg = int(np.clip(1800 * (mn / 2048.0) ** 2, 600, 5500))
        for _ in range(n_agg):
            cx = int(rng.uniform(0.02, 0.98) * w); cy = int(rng.uniform(0.02, 0.98) * h)
            r = max(1, int(rng.uniform(1.0, 2.0) * scale))
            _cv2.circle(M,  (cx, cy), r, float(rng.uniform(0.55, 0.94)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R_ch,(cx, cy), r, float(rng.uniform(0.18, 0.50)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r, float(rng.uniform(0.18, 0.55)), -1, lineType=_cv2.LINE_AA)

        # 7) MICRO PIT POCKS â€” dark 1-2 px
        n_pit = int(np.clip(900 * (mn / 2048.0) ** 2, 300, 2800))
        for _ in range(n_pit):
            cx = int(rng.uniform(0.02, 0.98) * w); cy = int(rng.uniform(0.02, 0.98) * h)
            r = max(1, int(rng.uniform(1.0, 1.6) * scale))
            _cv2.circle(M,  (cx, cy), r, float(rng.uniform(0.10, 0.28)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R_ch,(cx, cy), r, float(rng.uniform(0.78, 0.96)), -1, lineType=_cv2.LINE_AA)

        # 7b) HERO â€” TIRE-CONFETTI CURLED RUBBER SHAVINGS (6-14 px crescents)
        n_curl = int(np.clip(1200 * (mn / 2048.0) ** 2, 400, 3800))
        for _ in range(n_curl):
            cx = int(rng.uniform(0.02, 0.98) * w); cy = int(rng.uniform(0.02, 0.98) * h)
            r_c = max(3, int(rng.uniform(3.0, 6.5) * scale))
            ry_c = max(2, int(r_c * float(rng.uniform(0.45, 0.75))))
            rot_c = float(rng.uniform(0, 360))
            a0_c = float(rng.uniform(0, 360)); sweep_c = float(rng.uniform(70, 170))
            cM = float(rng.uniform(0.04, 0.20))
            cR = float(rng.uniform(0.78, 0.96))
            cCC = float(rng.uniform(0.60, 0.92))
            _cv2.ellipse(M, (cx, cy), (r_c, ry_c), rot_c, a0_c, a0_c + sweep_c, cM, 2, lineType=_cv2.LINE_AA)
            _cv2.ellipse(R_ch, (cx, cy), (r_c, ry_c), rot_c, a0_c, a0_c + sweep_c, cR, 2, lineType=_cv2.LINE_AA)
            _cv2.ellipse(CC, (cx, cy), (r_c, ry_c), rot_c, a0_c, a0_c + sweep_c, cCC, 2, lineType=_cv2.LINE_AA)

        # 7c) HERO â€” GRAVEL-IMPACT STAR-CRACKS (5-10 px 4-pointed asterisks)
        n_star = int(np.clip(700 * (mn / 2048.0) ** 2, 240, 2200))
        for _ in range(n_star):
            cx = int(rng.uniform(0.03, 0.97) * w); cy = int(rng.uniform(0.03, 0.97) * h)
            r_s = max(2, int(rng.uniform(2.5, 5.0) * scale))
            sM = float(rng.uniform(0.55, 0.92))
            sR = float(rng.uniform(0.20, 0.55))
            sCC = float(rng.uniform(0.10, 0.45))
            for ang_idx in range(4):
                ang_s = ang_idx * (np.pi / 2.0) + float(rng.uniform(-0.25, 0.25))
                ex = int(np.clip(cx + np.cos(ang_s) * r_s, 0, w - 1))
                ey = int(np.clip(cy + np.sin(ang_s) * r_s, 0, h - 1))
                _cv2.line(M, (cx, cy), (ex, ey), sM, 1, lineType=_cv2.LINE_AA)
                _cv2.line(R_ch, (cx, cy), (ex, ey), sR, 1, lineType=_cv2.LINE_AA)
                _cv2.line(CC, (cx, cy), (ex, ey), sCC, 1, lineType=_cv2.LINE_AA)

    # 8) DENSE BRIGHT-FLECK ACCENT â€” single pixel
    n_fl = int(np.clip(1500 * (mn / 2048.0) ** 2, 520, 4400))
    fy = rng.integers(0, h, n_fl); fx = rng.integers(0, w, n_fl)
    M[fy, fx] = np.maximum(M[fy, fx], rng.uniform(0.55, 0.94, n_fl).astype(np.float32))
    R_ch[fy, fx] = np.minimum(R_ch[fy, fx], rng.uniform(0.22, 0.55, n_fl).astype(np.float32))
    CC[fy, fx] = np.maximum(CC[fy, fx], rng.uniform(0.18, 0.80, n_fl).astype(np.float32))

    out = np.stack([np.clip(M, 0, 1), np.clip(R_ch, 0, 1), np.clip(CC, 0, 1)], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)


tire_rubber_transfer._spb_concept_complete = True


def vinyl_wrap_texture(shape, seed, sm, channel_spacing=80, bubble_density=0.001):
    """vinyl_wrap_texture.

    identity: Round-6 CREATIVE rebuild â€” a freshly squeegeed cast-vinyl
    wrap caught mid-install with NEW HERO MOTIF: vinyl-cut DECAL SLIVERS
    floating ON the wrap (chevron and arrowhead outlines, 12-22 px) like
    the installer just applied a stripe kit. The wrap itself shows AIR-
    RELEASE CHANNEL GRID + TRAPPED BUBBLES underneath. Nine stacked tiers
    fill every pixel: (1) FBM vinyl substrate, INDEPENDENT M/R/CC, (2) the
    factory air-release groove micro-grid â€” short 10-24 px segments in two
    perpendicular runs, (3) cast-film orange-peel dimple field (1-3 px),
    (4) trapped bubbles with bright glint + dark sag crescent (3-6 px),
    (5) HERO CHEVRON DECAL SLIVERS â€” 5-12 chevron/arrowhead vinyl-cut
    overlays scattered, each a bright thin border outline 12-22 px, (6)
    HERO STAR/HEX BADGE STICKERS â€” 3-8 small geometric decals 10-16 px
    with distinct chroma, (7) squeegee drag streaks (8-18 px), (8)
    edge-lift micro-bubbles 1-2 px clusters, (9) clearcoat fleck floor.
    Per-feature INDEPENDENT continuous M/R/CC across WIDE chroma ranges.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 91237)
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)

    # 1) VINYL FBM SUBSTRATE â€” INDEPENDENT M/R/CC
    fM = _normalize(multi_scale_noise(shape, [1.6, 4.4, 11.0, 26.0], [0.34, 0.30, 0.22, 0.14], int(seed) + 9111))
    fR = _normalize(multi_scale_noise(shape, [1.9, 5.2, 13.0, 28.0], [0.36, 0.30, 0.20, 0.14], int(seed) + 9212))
    fCC = _normalize(multi_scale_noise(shape, [2.3, 6.4, 15.0, 30.0], [0.38, 0.28, 0.20, 0.14], int(seed) + 9313))
    M = (0.55 + (fM - 0.5) * 0.22).astype(np.float32)
    R_ch = (0.40 + (fR - 0.5) * 0.22).astype(np.float32)
    CC = (0.32 + (fCC - 0.5) * 0.22).astype(np.float32)

    if _CV2_OK:
        # 2) AIR-RELEASE GROOVE GRID â€” 5x density, two perpendicular runs (10-24 px)
        n_grooves = int(np.clip(3800 * (mn / 2048.0) ** 2, 1300, 12500))
        for _ in range(n_grooves):
            cx = float(rng.uniform(0.02, 0.98) * w); cy = float(rng.uniform(0.02, 0.98) * h)
            length = float(rng.uniform(10.0, 24.0) * scale)
            if rng.random() < 0.55:
                ang = float(rng.uniform(-0.14, 0.14))
            else:
                ang = float(np.pi * 0.5 + rng.uniform(-0.14, 0.14))
            x2 = int(np.clip(cx + np.cos(ang) * length, 0, w - 1))
            y2 = int(np.clip(cy + np.sin(ang) * length, 0, h - 1))
            # Per-stroke INDEPENDENT continuous chroma
            _cv2.line(M,    (int(cx), int(cy)), (x2, y2), float(rng.uniform(0.32, 0.72)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(R_ch, (int(cx), int(cy)), (x2, y2), float(rng.uniform(0.50, 0.85)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC,   (int(cx), int(cy)), (x2, y2), float(rng.uniform(0.18, 0.55)), 1, lineType=_cv2.LINE_AA)

        # 3) ORANGE-PEEL DIMPLES â€” 5x density
        n_dim = int(np.clip(3500 * (mn / 2048.0) ** 2, 1200, 11500))
        for _ in range(n_dim):
            cx = int(rng.uniform(0.01, 0.99) * w); cy = int(rng.uniform(0.01, 0.99) * h)
            r = max(1, int(rng.uniform(1.0, 1.8) * scale))
            _cv2.circle(M,    (cx, cy), r, float(rng.uniform(0.28, 0.58)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R_ch, (cx, cy), r, float(rng.uniform(0.55, 0.88)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC,   (cx, cy), r, float(rng.uniform(0.32, 0.65)), -1, lineType=_cv2.LINE_AA)

        # 4) TRAPPED BUBBLES â€” bright glint + dark sag crescent (3-6 px)
        n_bub = int(np.clip(1100 * (mn / 2048.0) ** 2, 360, 3600))
        for _ in range(n_bub):
            cx = int(rng.uniform(0.02, 0.98) * w); cy = int(rng.uniform(0.02, 0.98) * h)
            r = max(2, int(rng.uniform(2.0, 3.5) * scale))
            # Bright bubble body
            _cv2.circle(M,    (cx, cy), r, float(rng.uniform(0.70, 0.97)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R_ch, (cx, cy), r, float(rng.uniform(0.08, 0.28)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC,   (cx, cy), r, float(rng.uniform(0.05, 0.22)), -1, lineType=_cv2.LINE_AA)
            # Dark gravity-sag crescent below
            if r >= 2:
                _cv2.circle(M, (cx, cy + max(1, r // 2)), max(1, r - 1), float(rng.uniform(0.20, 0.40)), -1, lineType=_cv2.LINE_AA)

        # 4b) HERO CHEVRON DECAL SLIVERS â€” vinyl-cut arrowhead outlines
        n_chev = int(rng.integers(5, 13))
        for _ in range(n_chev):
            cx = float(rng.uniform(0.10, 0.90) * w)
            cy = float(rng.uniform(0.10, 0.90) * h)
            L = float(rng.uniform(12.0, 22.0) * scale)
            ang = float(rng.uniform(0, 2 * np.pi))
            # chevron: two line segments forming a V
            ca = np.cos(ang); sa = np.sin(ang)
            # tip
            tx = cx; ty = cy
            # back two points (V opens away from tip)
            half_open = float(rng.uniform(0.6, 0.9))  # opening width factor
            bx1 = cx + ca * L - sa * (L * half_open * 0.5)
            by1 = cy + sa * L + ca * (L * half_open * 0.5)
            bx2 = cx + ca * L + sa * (L * half_open * 0.5)
            by2 = cy + sa * L - ca * (L * half_open * 0.5)
            M_d = float(rng.uniform(0.62, 0.96))
            R_d = float(rng.uniform(0.06, 0.30))
            CC_d = float(rng.uniform(0.06, 0.32))
            _cv2.line(M, (int(tx), int(ty)), (int(bx1), int(by1)), M_d, 1, lineType=_cv2.LINE_AA)
            _cv2.line(M, (int(tx), int(ty)), (int(bx2), int(by2)), M_d, 1, lineType=_cv2.LINE_AA)
            _cv2.line(R_ch, (int(tx), int(ty)), (int(bx1), int(by1)), R_d, 1, lineType=_cv2.LINE_AA)
            _cv2.line(R_ch, (int(tx), int(ty)), (int(bx2), int(by2)), R_d, 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (int(tx), int(ty)), (int(bx1), int(by1)), CC_d, 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (int(tx), int(ty)), (int(bx2), int(by2)), CC_d, 1, lineType=_cv2.LINE_AA)
            # bright tip pinpoint
            _cv2.circle(M, (int(tx), int(ty)), max(1, int(scale)),
                        float(rng.uniform(0.85, 0.99)), -1, lineType=_cv2.LINE_AA)

        # 4c) HERO STAR/HEX BADGE STICKERS â€” small geometric decals
        n_badge = int(rng.integers(3, 9))
        for _ in range(n_badge):
            cx = int(rng.uniform(0.08, 0.92) * w)
            cy = int(rng.uniform(0.08, 0.92) * h)
            r = max(4, int(rng.uniform(5.0, 8.0) * scale))
            n_pts = int(rng.choice([5, 6, 8]))
            base_ang = float(rng.uniform(0, 2 * np.pi))
            verts = []
            for k in range(n_pts):
                a = base_ang + k * (2 * np.pi / n_pts)
                verts.append([int(np.clip(cx + np.cos(a) * r, 0, w - 1)),
                              int(np.clip(cy + np.sin(a) * r, 0, h - 1))])
            pts = np.array([verts], dtype=np.int32)
            badge_M = float(rng.uniform(0.55, 0.95))
            badge_R = float(rng.uniform(0.08, 0.32))
            badge_CC = float(rng.uniform(0.10, 0.45))
            _cv2.polylines(M, pts, True, badge_M, 1, lineType=_cv2.LINE_AA)
            _cv2.polylines(R_ch, pts, True, badge_R, 1, lineType=_cv2.LINE_AA)
            _cv2.polylines(CC, pts, True, badge_CC, 1, lineType=_cv2.LINE_AA)
            # fill center with mid-tone
            _cv2.circle(M, (cx, cy), max(1, r // 3),
                        float(rng.uniform(0.45, 0.85)), -1, lineType=_cv2.LINE_AA)

        # 5) SQUEEGEE DRAG STREAKS â€” 8-18 px near-horizontal
        n_drag = int(np.clip(900 * (mn / 2048.0) ** 2, 300, 3000))
        for _ in range(n_drag):
            cx = float(rng.uniform(2, w - 2)); cy = float(rng.uniform(2, h - 2))
            length = float(rng.uniform(8.0, 18.0) * scale)
            ang = float(rng.uniform(-0.10, 0.10))
            x2 = int(np.clip(cx + np.cos(ang) * length, 0, w - 1))
            y2 = int(np.clip(cy + np.sin(ang) * length, 0, h - 1))
            _cv2.line(M,    (int(cx), int(cy)), (x2, y2), float(rng.uniform(0.50, 0.88)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(R_ch, (int(cx), int(cy)), (x2, y2), float(rng.uniform(0.12, 0.38)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC,   (int(cx), int(cy)), (x2, y2), float(rng.uniform(0.10, 0.32)), 1, lineType=_cv2.LINE_AA)

    # 6) EDGE-LIFT MICRO-BUBBLES â€” 1-2 px bright dense cluster
    n_mb = int(np.clip(4500 * (mn / 2048.0) ** 2, 1500, 15000))
    my = rng.integers(0, h, n_mb); mx = rng.integers(0, w, n_mb)
    M[my, mx]    = np.maximum(M[my, mx],    rng.uniform(0.60, 0.96, n_mb).astype(np.float32))
    R_ch[my, mx] = np.minimum(R_ch[my, mx], rng.uniform(0.06, 0.26, n_mb).astype(np.float32))
    CC[my, mx]   = np.minimum(CC[my, mx],   rng.uniform(0.04, 0.22, n_mb).astype(np.float32))

    # 7) CLEARCOAT FLECK FLOOR
    n_fl = int(np.clip(2200 * (mn / 2048.0) ** 2, 750, 7500))
    fy = rng.integers(0, h, n_fl); fx = rng.integers(0, w, n_fl)
    M[fy, fx]  = np.maximum(M[fy, fx], rng.uniform(0.55, 0.95, n_fl).astype(np.float32))
    CC[fy, fx] = np.minimum(CC[fy, fx], rng.uniform(0.04, 0.22, n_fl).astype(np.float32))

    out = np.stack([np.clip(M, 0, 1), np.clip(R_ch, 0, 1), np.clip(CC, 0, 1)], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)


vinyl_wrap_texture._spb_concept_complete = True


def paint_drip_edge(shape, seed, sm, edge_fraction=0.25, drip_count=30):
    """paint_drip_edge.

    identity: A still-wet painted panel covered in thousands of small rope
    drips. Each drip is 18-32 px (kept fine), tapers from wide top to thin
    tail, ends in a heavier round terminal droplet w/ sharp top highlight.
    Drips overwhelmingly run DOWNWARD (panel direction reads) but with
    5x more drip count than before. Stacked feature types: drip ropes,
    terminal droplets, micro-runs (tiny 4-8 px secondary streams that
    branch off main ropes), and wet-surface sparkle on the substrate.
    Per-drip INDEPENDENT continuous M/R/CC.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 109501)
    scale = max(min(h, w) / 2048.0, 0.25)
    mn = min(h, w)

    # 1) WET PAINTED SUBSTRATE
    if _CV2_OK:
        sh = max(64, h // 6); sw = max(64, w // 6)
        sub_n = rng.random((sh, sw)).astype(np.float32)
        sub_blur = _cv2.GaussianBlur(sub_n, (0, 0), sigmaX=4.0, sigmaY=4.0)
        substrate = _cv2.resize(sub_blur, (w, h), interpolation=_cv2.INTER_CUBIC).astype(np.float32)
    else:
        substrate = multi_scale_noise(shape, [20, 40], [0.6, 0.4], int(seed) + 9121)
    substrate = _normalize(substrate)
    M = (0.55 + (substrate - 0.5) * 0.22).astype(np.float32)
    R_ch = (0.38 + (substrate - 0.5) * 0.18).astype(np.float32)
    CC = (0.60 + (substrate - 0.5) * 0.16).astype(np.float32)

    # 2) DRIP ROPES â€” 5x density, fine-feature (18-32 px each)
    n_drips = max(1500, int(5500 * scale * scale + rng.integers(1000, 2400)))
    if _CV2_OK:
        for _ in range(n_drips):
            x = int(rng.integers(0, w))
            y_start = int(rng.integers(0, h))
            drip_len = int(rng.uniform(18.0, 32.0) * scale * 2.0)  # 18-32 px range scaled
            drip_len = max(8, drip_len)
            d_ang = float(rng.uniform(np.pi * 0.40, np.pi * 0.60))  # tighter down-bias
            dxc = float(np.cos(d_ang))
            dyc = float(np.sin(d_ang))
            y_end = int(np.clip(y_start + dyc * drip_len, 0, h - 1))
            x_end = int(np.clip(x + dxc * drip_len, 0, w - 1))
            w_top = max(1, int(rng.uniform(1.5, 3.5) * scale))
            w_bot = max(1, int(w_top * 0.45))
            # per-drip INDEPENDENT
            M_top = float(rng.uniform(0.75, 0.98))
            M_bot = float(rng.uniform(0.50, 0.82))
            R_top = float(rng.uniform(0.03, 0.12))
            R_bot = float(rng.uniform(0.10, 0.25))
            CC_top = float(rng.uniform(0.82, 0.99))
            CC_bot = float(rng.uniform(0.70, 0.92))
            n_seg = max(4, drip_len // 3)
            for si in range(n_seg):
                t = si / max(n_seg - 1, 1)
                seg_y = int(y_start + dyc * t * drip_len)
                seg_x = int(x + dxc * t * drip_len)
                if seg_y < 0 or seg_y >= h:
                    break
                seg_w = int(w_top * (1 - t) + w_bot * t)
                seg_x += int(rng.normal(0, 0.4 * scale))
                if seg_w > 0:
                    x0 = max(0, seg_x - seg_w); x1 = min(w, seg_x + seg_w + 1)
                    M[seg_y, x0:x1] = np.maximum(M[seg_y, x0:x1], M_top * (1 - t) + M_bot * t)
                    R_ch[seg_y, x0:x1] = np.minimum(R_ch[seg_y, x0:x1], R_top * (1 - t) + R_bot * t)
                    CC[seg_y, x0:x1] = np.maximum(CC[seg_y, x0:x1], CC_top * (1 - t) + CC_bot * t)
            # 3) TERMINAL DROPLET
            if 0 <= y_end < h and 0 <= x_end < w:
                droplet_r = max(1, int(w_top * 1.3))
                _cv2.circle(M, (x_end, y_end), droplet_r, float(rng.uniform(0.82, 0.99)), -1, lineType=_cv2.LINE_AA)
                _cv2.circle(R_ch, (x_end, y_end), droplet_r, float(rng.uniform(0.02, 0.10)), -1, lineType=_cv2.LINE_AA)
                _cv2.circle(CC, (x_end, y_end), droplet_r, float(rng.uniform(0.88, 0.99)), -1, lineType=_cv2.LINE_AA)

        # 4) MICRO-RUNS â€” short 4-8 px secondary streams (new feature type)
        n_micro = int(np.clip(4500 * (mn / 2048.0) ** 2, 1500, 18000))
        for _ in range(n_micro):
            cx = float(rng.uniform(0, w)); cy = float(rng.uniform(0, h))
            length = float(rng.uniform(4.0, 8.0) * scale)
            ang = float(np.pi * 0.5 + rng.uniform(-0.10, 0.10))
            x2 = int(np.clip(cx + np.cos(ang) * length, 0, w - 1))
            y2 = int(np.clip(cy + np.sin(ang) * length, 0, h - 1))
            _cv2.line(M, (int(cx), int(cy)), (x2, y2), float(rng.uniform(0.65, 0.93)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (int(cx), int(cy)), (x2, y2), float(rng.uniform(0.65, 0.95)), 1, lineType=_cv2.LINE_AA)

    # 5) WET-SURFACE SPARKLE â€” vectorized bright pinpoints
    n_fl = int(np.clip(4000 * (mn / 2048.0) ** 2, 1500, 16000))
    fx = rng.integers(0, w, n_fl); fy = rng.integers(0, h, n_fl)
    M[fy, fx] = np.maximum(M[fy, fx], rng.uniform(0.75, 0.99, n_fl).astype(np.float32))
    CC[fy, fx] = np.maximum(CC[fy, fx], rng.uniform(0.80, 0.99, n_fl).astype(np.float32))

    out = np.stack([np.clip(M, 0, 1), np.clip(R_ch, 0, 1), np.clip(CC, 0, 1)], axis=2).astype(np.float32)
    return _sm_scale(out, sm)
paint_drip_edge._spb_concept_complete = True
def _LEGACY_paint_drip_edge_stub(shape, seed, sm, edge_fraction=0.25, drip_count=30):
    """Legacy implementation kept for reference."""
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(seed + 9120)
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)
    palette = np.array([0.18, 0.28, 0.38, 0.48, 0.58, 0.68, 0.78, 0.92], dtype=np.float32)

    # 1) BASE â€” wet-paint FBM
    grain = multi_scale_noise(shape, [1.5, 4.0, 11.0, 28.0], [0.35, 0.30, 0.22, 0.13], seed + 9121)
    result = 0.50 + (_normalize(grain) - 0.5) * 0.30
    # post-blackout-52 REVERT: BRU mask attempt regressed -0.5. Drip primitives wash out the extreme injection. Parked.

    # 2) HORIZONTAL DRIP SEGMENTS â€” lower-biased (10-22 px)
    n_drips = int(np.clip(700 * (mn / 2048.0) ** 2, 240, 2800))
    if _CV2_OK:
        for _ in range(n_drips):
            cx = rng.uniform(0.02, 0.98) * w; cy_p = rng.uniform(0.02, 0.98) * h
            # Lower-half bias
            if rng.random() > 0.2 + 0.8 * (cy_p / h):
                continue
            length = rng.uniform(10.0, 22.0) * scale
            ang = rng.uniform(-0.2, 0.2)  # mostly horizontal
            x2 = int(np.clip(cx + np.cos(ang) * length, 0, w - 1))
            y2 = int(np.clip(cy_p + np.sin(ang) * length, 0, h - 1))
            v = float(palette[rng.integers(5, 8)])
            _cv2.line(result, (int(cx), int(cy_p)), (x2, y2), v, max(1, int(scale * 1.5)), lineType=_cv2.LINE_AA)

    # 3) SAG DROPLETS â€” small bright dots (2-5 px)
    n_drops = int(np.clip(400 * (mn / 2048.0) ** 2, 120, 1600))
    if _CV2_OK:
        for _ in range(n_drops):
            cx = int(rng.uniform(0.02, 0.98) * w); cy_p = int(rng.uniform(0.30, 0.98) * h)
            r = max(1, int(rng.uniform(1.5, 3.0) * scale))
            v = float(palette[rng.integers(5, 8)])
            _cv2.circle(result, (cx, cy_p), r, v, -1, lineType=_cv2.LINE_AA)

    # 4) EDGE FRAGMENTS â€” short perpendicular sag indicators (6-14 px)
    n_edges = int(np.clip(400 * (mn / 2048.0) ** 2, 120, 1600))
    if _CV2_OK:
        for _ in range(n_edges):
            cx = int(rng.uniform(0.02, 0.98) * w); cy_p = int(rng.uniform(0.20, 0.98) * h)
            length = int(rng.uniform(6.0, 14.0) * scale)
            v = float(palette[rng.integers(2, 6)])
            _cv2.line(result, (cx, cy_p), (cx + int(rng.uniform(-2, 2)), min(h - 1, cy_p + length)), v, 1, lineType=_cv2.LINE_AA)

    # 5) BRIGHT FLECKS
    n_flecks = int(np.clip(500 * (mn / 2048.0) ** 2, 160, 2000))
    fx = rng.integers(0, w, n_flecks); fy = rng.integers(0, h, n_flecks)
    result[fy, fx] = np.maximum(result[fy, fx], palette[rng.integers(5, 8, n_flecks)])

    return _sm_scale(_normalize(np.clip(result, 0, 1)), sm).astype(np.float32)


def racing_tape_residue(shape, seed, sm, **kwargs):
    """racing_tape_residue.

    identity: Round-6 creative rebuild â€” the tell-tale ghost zone where
    masking tape was peeled off a freshly painted race panel. HERO: a
    set of 3-6 horizontal-leaning RESIDUE BANDS (each ~12-26 px tall)
    with SHARP CRISP EDGES (the tape-line shadow stripes top and bottom)
    enclosing a sticky-matte adhesive interior. INSIDE the bands the
    paint signature differs from outside â€” sticky-matte vs glossy. New
    layers: (a) crisp band edges with bright reflective tape-line
    hairlines, (b) interior glue-bead carpet (2-5 px, 5x density) with
    independent per-bead chroma, (c) fiber-pull scratches near-parallel
    to band direction (10-24 px), (d) NEW corner-pull TRIANGLE ghost
    marks (5-10 px) at random band edges (where peeling started), (e)
    dark dust-trap pinpoint carpet in sticky zones, (f) NEW bright tape
    REFLECTION GLINTS (1-2 px) along band centerlines, (g) outside-band
    micro-fleck carpet for full canvas coverage. Per-feature INDEPENDENT
    continuous M/R/CC uniforms.
    """
    shape = tuple(shape) if hasattr(shape, '__iter__') else shape
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 78319)
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)

    yy = np.arange(h, dtype=np.float32)[:, None]
    xx = np.arange(w, dtype=np.float32)[None, :]

    # 1) Clean paint substrate â€” three indep FBM channels
    g_M = _normalize(multi_scale_noise((h, w), [2.5, 7.0, 20.0], [0.5, 0.3, 0.2], int(seed) + 111))
    g_R = _normalize(multi_scale_noise((h, w), [3.0, 8.0, 22.0], [0.5, 0.3, 0.2], int(seed) + 113))
    g_CC = _normalize(multi_scale_noise((h, w), [3.5, 9.0, 24.0], [0.5, 0.3, 0.2], int(seed) + 117))
    M = (0.42 + (g_M - 0.5) * 0.24).astype(np.float32)
    R = (0.42 + (g_R - 0.5) * 0.22).astype(np.float32)
    CC = (0.38 + (g_CC - 0.5) * 0.24).astype(np.float32)

    # 2) HERO RESIDUE BANDS with CRISP edges (not gaussian-soft)
    n_bands = int(rng.integers(3, 7))
    band_mask = np.zeros((h, w), dtype=np.float32)
    edge_mask = np.zeros((h, w), dtype=np.float32)
    band_info = []  # (y_c, band_h, tilt) for downstream layers
    for _ in range(n_bands):
        y_c = float(rng.uniform(0.08, 0.92)) * h
        band_h = float(rng.uniform(0.025, 0.060)) * h
        tilt = float(rng.uniform(-0.04, 0.04))
        d = np.abs((yy - y_c) - tilt * (xx - w * 0.5))
        # Crisp band: inside is 1, outside is 0, with thin edge highlight
        inside = (d < band_h).astype(np.float32)
        edge = ((d > band_h - 1.4) & (d < band_h + 0.6)).astype(np.float32)
        band_mask = np.maximum(band_mask, inside)
        edge_mask = np.maximum(edge_mask, edge)
        band_info.append((y_c, band_h, tilt))

    # Adhesive zones inside band: lower M, higher R, slightly higher CC
    M = np.clip(M - band_mask * 0.22, 0, 1)
    R = np.clip(R + band_mask * 0.32, 0, 1)
    CC = np.clip(CC + band_mask * 0.20, 0, 1)
    # Crisp bright tape-edge highlight (the line where tape edge sat)
    M = np.clip(M + edge_mask * 0.40, 0, 1)
    CC = np.clip(CC + edge_mask * 0.30, 0, 1)
    R = np.clip(R - edge_mask * 0.20, 0, 1)

    if _CV2_OK:
        # 3) Bright reflective tape-line hairlines (along band centers)
        n_edges = int(np.clip(80 * (mn / 2048.0) ** 1.0, 28, 240))
        for _ in range(n_edges):
            y_c = float(rng.uniform(0.05, 0.95)) * h
            x0 = int(rng.uniform(0, w * 0.30)); x1 = int(rng.uniform(w * 0.70, w))
            y_off = float(rng.uniform(-2, 2))
            _cv2.line(M, (x0, int(y_c)), (x1, int(y_c + y_off)), float(rng.uniform(0.58, 0.96)), max(1, int(scale * 1.5)), lineType=_cv2.LINE_AA)
            _cv2.line(R, (x0, int(y_c)), (x1, int(y_c + y_off)), float(rng.uniform(0.08, 0.30)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (x0, int(y_c)), (x1, int(y_c + y_off)), float(rng.uniform(0.50, 0.92)), 1, lineType=_cv2.LINE_AA)

        # 4) GLUE-BEAD CARPET inside bands (2-5 px) â€” 5x density
        n_beads = int(np.clip(2400 * (mn / 2048.0) ** 2, 900, 5500))
        for _ in range(n_beads):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            # Bias to bands
            if band_mask[cy, cx] < 0.5 and rng.random() < 0.6:
                continue
            r = max(1, int(rng.uniform(2.0, 5.0) * scale * 0.55))
            _cv2.circle(M, (cx, cy), r, float(rng.uniform(0.32, 0.88)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r, float(rng.uniform(0.28, 0.70)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r, float(rng.uniform(0.12, 0.55)), -1, lineType=_cv2.LINE_AA)

        # 5) Fiber-pull hairlines (10-24 px) near-horizontal
        n_fiber = int(np.clip(700 * (mn / 2048.0) ** 2, 240, 1700))
        for _ in range(n_fiber):
            cx = float(rng.uniform(6, w - 6)); cy = float(rng.uniform(6, h - 6))
            length = float(rng.uniform(10.0, 24.0) * scale)
            ang = float(rng.uniform(-0.42, 0.42))
            x0s = int(cx - np.cos(ang) * length * 0.5); y0s = int(cy - np.sin(ang) * length * 0.5)
            x1s = int(cx + np.cos(ang) * length * 0.5); y1s = int(cy + np.sin(ang) * length * 0.5)
            _cv2.line(M, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.35, 0.82)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(R, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.48, 0.88)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.18, 0.58)), 1, lineType=_cv2.LINE_AA)

        # 6) NEW â€” CORNER-PULL TRIANGLES at band edges (5-10 px)
        n_pull = int(np.clip(180 * (mn / 2048.0) ** 2, 60, 500))
        for _ in range(n_pull):
            if not band_info:
                break
            y_c, band_h, tilt = band_info[int(rng.integers(0, len(band_info)))]
            cx = int(rng.uniform(0.04, 0.96) * w)
            cy = int(y_c + tilt * (cx - w * 0.5) + float(rng.choice([-1.0, 1.0])) * band_h)
            cy = int(np.clip(cy, 1, h - 2))
            sz = max(2, int(float(rng.uniform(5.0, 10.0)) * scale))
            ang = float(rng.uniform(0, 2 * np.pi))
            p1 = (cx, cy)
            p2 = (int(cx + np.cos(ang) * sz), int(cy + np.sin(ang) * sz))
            p3 = (int(cx + np.cos(ang + 1.0) * sz * 0.5), int(cy + np.sin(ang + 1.0) * sz * 0.5))
            tri = np.array([p1, p2, p3], dtype=np.int32)
            _cv2.fillPoly(M, [tri], float(rng.uniform(0.62, 0.96)))
            _cv2.fillPoly(R, [tri], float(rng.uniform(0.08, 0.28)))
            _cv2.fillPoly(CC, [tri], float(rng.uniform(0.55, 0.92)))

        # 7) NEW â€” REFLECTION GLINTS (1-2 px) bright pinpoints on band centerlines
        n_glint = int(np.clip(900 * (mn / 2048.0) ** 2, 320, 2300))
        for _ in range(n_glint):
            if not band_info:
                break
            y_c, band_h, tilt = band_info[int(rng.integers(0, len(band_info)))]
            cx = int(rng.uniform(0.02, 0.98) * w)
            cy = int(np.clip(y_c + tilt * (cx - w * 0.5) + float(rng.uniform(-band_h * 0.6, band_h * 0.6)), 0, h - 1))
            r = max(1, int(rng.uniform(1.0, 2.0) * scale))
            _cv2.circle(M, (cx, cy), r, float(rng.uniform(0.78, 0.98)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r, float(rng.uniform(0.70, 0.95)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r, float(rng.uniform(0.04, 0.18)), -1, lineType=_cv2.LINE_AA)

    # 8) Dark dust-stuck pinpoints inside adhesive zones
    n_dust = max(900, int(h * w / 3600))
    dy = rng.integers(0, h, n_dust); dx = rng.integers(0, w, n_dust)
    # bias to bands
    keep = band_mask[dy, dx] > 0.3
    dy = dy[keep]; dx = dx[keep]
    if dy.size > 0:
        M[dy, dx] = np.minimum(M[dy, dx], rng.uniform(0.04, 0.22, dy.size).astype(np.float32))
        R[dy, dx] = np.maximum(R[dy, dx], rng.uniform(0.60, 0.95, dy.size).astype(np.float32))

    # 9) Outside-band fleck carpet for full canvas coverage
    n_carp = max(2500, int(h * w / 250))
    cy_a = rng.integers(0, h, n_carp); cx_a = rng.integers(0, w, n_carp)
    M[cy_a, cx_a] = np.maximum(M[cy_a, cx_a], rng.uniform(0.28, 0.80, n_carp).astype(np.float32))
    CC[cy_a, cx_a] = np.maximum(CC[cy_a, cx_a], rng.uniform(0.12, 0.65, n_carp).astype(np.float32))

    out = np.stack([np.clip(M, 0, 1), np.clip(R, 0, 1), np.clip(CC, 0, 1)], axis=-1).astype(np.float32)
    return _sm_scale(out, sm)
racing_tape_residue._spb_concept_complete = True


def sponsor_deboss(shape, seed=0, sm=1.0, **kwargs):
    """sponsor_deboss.

    identity: R6 creative rebuild â€” pressed-in sponsor mark catalogue.
    The HERO upgrade: real GLYPH-SHAPED debosses scattered alongside
    geometric ones â€” 5-armed STARS (6-12 px), V-CHEVRONS (8-14 px),
    X-CROSSES (8-12 px), plus the geometric trio (rect/circle/diamond).
    Six shape families stacked so the panel reads like a NASCAR-style
    sponsor wall, not abstract notches. Each deboss has dark floor +
    bright chamfered rim. Plus tool-scratch hairlines (8-18 px),
    polish-mark specks (2-3 px), bright accent fleck saturation.
    Per-deboss INDEPENDENT continuous M/R/CC. Every primitive 1-18 px.
    Differentiator vs generic_deboss: actual glyph shapes (stars,
    chevrons, crosses) give the sponsor-wall fingerprint.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 50213)
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)

    # 1) BASE â€” polished panel FBM, INDEPENDENT M/R/CC
    fM = _normalize(multi_scale_noise(shape, [3.5, 11.0, 26.0], [0.50, 0.30, 0.20], int(seed) + 11000))
    fR = _normalize(multi_scale_noise(shape, [4.0, 12.0, 28.0], [0.48, 0.30, 0.22], int(seed) + 11001))
    fCC = _normalize(multi_scale_noise(shape, [4.5, 13.0, 30.0], [0.46, 0.32, 0.22], int(seed) + 11002))
    M = (0.45 + (fM - 0.5) * 0.18).astype(np.float32)
    R = (0.35 + (fR - 0.5) * 0.14).astype(np.float32)
    CC = (0.32 + (fCC - 0.5) * 0.20).astype(np.float32)

    if _CV2_OK:
        # 2a) DEBOSS RECTANGLES â€” 3x density, smaller
        n_rec = int(np.clip(540 * (mn / 2048.0) ** 2, 200, 1600))
        for _ in range(n_rec):
            cx = int(rng.integers(8, max(9, w - 8))); cy = int(rng.integers(8, max(9, h - 8)))
            rw = max(2, int(float(rng.uniform(6.0, 18.0)) * scale))
            rh = max(2, int(float(rng.uniform(5.0, 14.0)) * scale))
            x0 = max(0, cx - rw // 2); x1 = min(w, cx + rw // 2)
            y0 = max(0, cy - rh // 2); y1 = min(h, cy + rh // 2)
            _cv2.rectangle(M, (x0, y0), (x1, y1), float(rng.uniform(0.18, 0.55)), -1)
            _cv2.rectangle(R, (x0, y0), (x1, y1), float(rng.uniform(0.55, 0.92)), -1)
            _cv2.rectangle(CC, (x0, y0), (x1, y1), float(rng.uniform(0.55, 0.92)), -1)
            # Bright chamfered rim
            _cv2.rectangle(M, (x0, y0), (x1, y1), float(rng.uniform(0.70, 0.96)), 1)
            _cv2.rectangle(R, (x0, y0), (x1, y1), float(rng.uniform(0.06, 0.25)), 1)
            _cv2.rectangle(CC, (x0, y0), (x1, y1), float(rng.uniform(0.10, 0.55)), 1)

        # 2b) DEBOSS CIRCLES â€” NEW shape type
        n_cir = int(np.clip(420 * (mn / 2048.0) ** 2, 150, 1300))
        for _ in range(n_cir):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            r_s = max(3, int(float(rng.uniform(4.0, 8.0)) * scale))
            _cv2.circle(M, (cx, cy), r_s, float(rng.uniform(0.18, 0.50)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r_s, float(rng.uniform(0.55, 0.90)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r_s, float(rng.uniform(0.55, 0.90)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(M, (cx, cy), r_s, float(rng.uniform(0.72, 0.96)), 1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r_s, float(rng.uniform(0.08, 0.28)), 1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r_s, float(rng.uniform(0.10, 0.55)), 1, lineType=_cv2.LINE_AA)

        # 2c) DIAMOND DEBOSS NOTCHES â€” NEW shape type
        n_dia = int(np.clip(380 * (mn / 2048.0) ** 2, 130, 1100))
        for _ in range(n_dia):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            r_s = max(3, int(float(rng.uniform(3.5, 6.5)) * scale))
            pts = np.array([[cx, cy - r_s], [cx + r_s, cy], [cx, cy + r_s], [cx - r_s, cy]], dtype=np.int32)
            _cv2.fillPoly(M, [pts], float(rng.uniform(0.22, 0.55)), lineType=_cv2.LINE_AA)
            _cv2.fillPoly(R, [pts], float(rng.uniform(0.55, 0.88)), lineType=_cv2.LINE_AA)
            _cv2.fillPoly(CC, [pts], float(rng.uniform(0.50, 0.88)), lineType=_cv2.LINE_AA)
            _cv2.polylines(M, [pts], True, float(rng.uniform(0.70, 0.95)), 1, lineType=_cv2.LINE_AA)

        # 2d) HERO â€” 5-POINT STAR DEBOSS (sponsor-wall glyph)
        n_star = int(np.clip(360 * (mn / 2048.0) ** 2, 130, 1000))
        for _ in range(n_star):
            cx = int(rng.integers(8, max(9, w - 8))); cy = int(rng.integers(8, max(9, h - 8)))
            r_out = max(3, int(float(rng.uniform(4.0, 7.0)) * scale))
            r_in = max(1, int(r_out * 0.45))
            rot = float(rng.uniform(0, 2 * np.pi))
            pts = []
            for k in range(10):
                ang = rot + k * (np.pi / 5.0)
                rad = r_out if (k % 2 == 0) else r_in
                pts.append([int(cx + np.cos(ang) * rad), int(cy + np.sin(ang) * rad)])
            poly = np.array(pts, dtype=np.int32)
            _cv2.fillPoly(M, [poly], float(rng.uniform(0.20, 0.52)), lineType=_cv2.LINE_AA)
            _cv2.fillPoly(R, [poly], float(rng.uniform(0.58, 0.92)), lineType=_cv2.LINE_AA)
            _cv2.fillPoly(CC, [poly], float(rng.uniform(0.55, 0.90)), lineType=_cv2.LINE_AA)
            _cv2.polylines(M, [poly], True, float(rng.uniform(0.72, 0.96)), 1, lineType=_cv2.LINE_AA)
            _cv2.polylines(R, [poly], True, float(rng.uniform(0.06, 0.24)), 1, lineType=_cv2.LINE_AA)
            _cv2.polylines(CC, [poly], True, float(rng.uniform(0.10, 0.45)), 1, lineType=_cv2.LINE_AA)

        # 2e) HERO â€” V-CHEVRON DEBOSS
        n_chev = int(np.clip(300 * (mn / 2048.0) ** 2, 110, 900))
        for _ in range(n_chev):
            cx = int(rng.integers(8, max(9, w - 8))); cy = int(rng.integers(8, max(9, h - 8)))
            length = max(3, int(float(rng.uniform(5.0, 8.0)) * scale))
            rot = float(rng.uniform(0, 2 * np.pi))
            spread = float(rng.uniform(0.5, 0.9))  # half-angle of the V
            a1 = rot - spread; a2 = rot + spread
            x1 = int(cx + np.cos(a1) * length); y1 = int(cy + np.sin(a1) * length)
            x2 = int(cx + np.cos(a2) * length); y2 = int(cy + np.sin(a2) * length)
            cM = float(rng.uniform(0.70, 0.95))
            cR = float(rng.uniform(0.08, 0.30))
            cCC = float(rng.uniform(0.12, 0.50))
            _cv2.line(M, (x1, y1), (cx, cy), cM, 1, lineType=_cv2.LINE_AA)
            _cv2.line(M, (cx, cy), (x2, y2), cM, 1, lineType=_cv2.LINE_AA)
            _cv2.line(R, (x1, y1), (cx, cy), cR, 1, lineType=_cv2.LINE_AA)
            _cv2.line(R, (cx, cy), (x2, y2), cR, 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (x1, y1), (cx, cy), cCC, 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (cx, cy), (x2, y2), cCC, 1, lineType=_cv2.LINE_AA)

        # 2f) HERO â€” X-CROSS DEBOSS
        n_xcr = int(np.clip(260 * (mn / 2048.0) ** 2, 90, 800))
        for _ in range(n_xcr):
            cx = int(rng.integers(6, max(7, w - 6))); cy = int(rng.integers(6, max(7, h - 6)))
            length = max(3, int(float(rng.uniform(4.0, 6.5)) * scale))
            rot = float(rng.uniform(0, np.pi))
            xM = float(rng.uniform(0.70, 0.96))
            xR = float(rng.uniform(0.08, 0.28))
            xCC = float(rng.uniform(0.10, 0.45))
            for k in range(2):
                ang = rot + k * (np.pi / 2.0)
                xa = int(cx + np.cos(ang) * length); ya = int(cy + np.sin(ang) * length)
                xb = int(cx - np.cos(ang) * length); yb = int(cy - np.sin(ang) * length)
                _cv2.line(M, (xa, ya), (xb, yb), xM, 1, lineType=_cv2.LINE_AA)
                _cv2.line(R, (xa, ya), (xb, yb), xR, 1, lineType=_cv2.LINE_AA)
                _cv2.line(CC, (xa, ya), (xb, yb), xCC, 1, lineType=_cv2.LINE_AA)

        # 3) TOOL SCRATCH HAIRLINES â€” short 8-18 px, 1.5x density
        n_scr = int(np.clip(1100 * (mn / 2048.0) ** 2, 380, 3000))
        for _ in range(n_scr):
            cx = float(rng.uniform(4, w - 4)); cy = float(rng.uniform(4, h - 4))
            length = float(rng.uniform(8.0, 18.0)) * scale
            ang = float(rng.uniform(0.0, 2 * np.pi))
            x0s = int(cx - np.cos(ang) * length * 0.5)
            y0s = int(cy - np.sin(ang) * length * 0.5)
            x1s = int(cx + np.cos(ang) * length * 0.5)
            y1s = int(cy + np.sin(ang) * length * 0.5)
            _cv2.line(M, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.45, 0.92)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(R, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.08, 0.35)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.12, 0.68)), 1, lineType=_cv2.LINE_AA)

        # 4) CORNER MASCOT SPECKS â€” 2-4 px, 2x density
        n_dot = int(np.clip(1800 * (mn / 2048.0) ** 2, 640, 4800))
        for _ in range(n_dot):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            r_s = max(1, int(float(rng.uniform(1.2, 2.5)) * scale))
            _cv2.circle(M, (cx, cy), r_s, float(rng.uniform(0.28, 0.92)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r_s, float(rng.uniform(0.10, 0.55)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r_s, float(rng.uniform(0.18, 0.88)), -1, lineType=_cv2.LINE_AA)

    # 5) DENSE ACCENT SPECKS â€” single pixel
    n_fl = int(np.clip(2400 * (mn / 2048.0) ** 2, 800, 5800))
    fy = rng.integers(0, h, n_fl); fx = rng.integers(0, w, n_fl)
    M[fy, fx] = np.maximum(M[fy, fx], rng.uniform(0.40, 0.92, n_fl).astype(np.float32))
    R[fy, fx] = np.minimum(R[fy, fx], rng.uniform(0.08, 0.42, n_fl).astype(np.float32))
    CC[fy, fx] = np.maximum(CC[fy, fx], rng.uniform(0.18, 0.85, n_fl).astype(np.float32))

    out = np.stack([np.clip(M, 0, 1), np.clip(R, 0, 1), np.clip(CC, 0, 1)], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)


sponsor_deboss._spb_concept_complete = True


def heat_discoloration(shape, seed, sm, num_zones=12, **kwargs):
    """heat_discoloration â€” R6 tick 2026-05-26.

    identity: owner rated 3/REBUILD ("generic noise, not the named thing,
    boring"). REBUILD: torch-cut weld bead with temper halos as the
    unmistakable HERO. Two or three big curved WELD-BEAD strokes cross
    the panel â€” each bead is a chain of overlapping bright fusion-blob
    nuggets 14-26 px running along a curved path, surrounded by a
    rainbow temper halo (blue->purple->bronze->straw rings stepping
    outward in concentric arcs). Plus 30-60 standalone heat-discoloration
    spots scattered across the panel â€” each a 4-tier concentric ring
    showing the same temper sequence. Composite-dark cool-steel substrate.
    Single coherent steel + temper palette with tight Â±0.04-0.06 jitter.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 60188)
    mn = min(h, w)
    s = max(mn / 256.0, 0.6)

    # 1) Cool-steel substrate â€” composite-dark (NOT neon-green)
    fbm = _normalize(multi_scale_noise(shape, [3.0, 8.0, 16.0], [0.5, 0.32, 0.18], int(seed) + 8111))
    BASE_M, BASE_R, BASE_CC = 0.22, 0.28, 0.18
    M  = (BASE_M  + (fbm - 0.5) * 0.06).astype(np.float32)
    R  = (BASE_R  + (fbm - 0.5) * 0.05).astype(np.float32)
    CC = (BASE_CC + (fbm - 0.5) * 0.05).astype(np.float32)

    # Steel-temper colour stops (phase 0=blue, 0.33=purple, 0.66=bronze, 1.0=straw)
    def _temper(phase):
        # returns (M, R, CC) at given temper phase 0..1
        # blue: dark M, R 0.50, low CC
        # purple: M 0.30, R 0.55, CC 0.20
        # bronze: M 0.55, R 0.40, CC 0.35
        # straw: M 0.80, R 0.25, CC 0.55
        tM  = 0.18 + 0.62 * phase
        tR  = 0.55 - 0.30 * phase
        tCC = 0.10 + 0.50 * phase
        return tM, tR, tCC

    if _CV2_OK:
        # 2) HERO â€” 2-3 torch-cut WELD BEAD strokes
        n_beads = int(rng.integers(2, 4))
        bead_centers = []
        for _ in range(n_beads):
            # Pick a start anchored ANYWHERE (no edge-only)
            x0 = float(rng.uniform(0.10 * w, 0.90 * w))
            y0 = float(rng.uniform(0.10 * h, 0.90 * h))
            ang0 = float(rng.uniform(0, 2 * np.pi))
            curve = float(rng.uniform(-0.025, 0.025))  # gentle curve per step
            n_steps = int(max(h, w) * 0.9 / (8 * s))
            cx, cy = x0, y0
            ang = ang0
            stroke_path = []
            for st in range(n_steps):
                if not (0 < cx < w and 0 < cy < h):
                    # wrap-around or stop near edges
                    break
                stroke_path.append((cx, cy))
                step_len = 7 * s
                ang += curve
                cx += np.cos(ang) * step_len
                cy += np.sin(ang) * step_len
            # Draw the temper-halo first (wide arcs, then narrowing)
            # Outer straw halo
            halo_r = int(14 * s)
            for (px_, py_) in stroke_path[::3]:
                tM, tR, tCC = _temper(0.95)
                _cv2.circle(M,  (int(px_), int(py_)), halo_r, float(np.clip(tM  + rng.uniform(-0.04, 0.04), 0, 1)), -1, lineType=_cv2.LINE_AA)
                _cv2.circle(R,  (int(px_), int(py_)), halo_r, float(np.clip(tR  + rng.uniform(-0.04, 0.04), 0, 1)), -1, lineType=_cv2.LINE_AA)
                _cv2.circle(CC, (int(px_), int(py_)), halo_r, float(np.clip(tCC + rng.uniform(-0.04, 0.04), 0, 1)), -1, lineType=_cv2.LINE_AA)
            # Mid bronze halo
            bronze_r = int(10 * s)
            for (px_, py_) in stroke_path[::3]:
                tM, tR, tCC = _temper(0.60)
                _cv2.circle(M,  (int(px_), int(py_)), bronze_r, float(np.clip(tM  + rng.uniform(-0.04, 0.04), 0, 1)), -1, lineType=_cv2.LINE_AA)
                _cv2.circle(R,  (int(px_), int(py_)), bronze_r, float(np.clip(tR  + rng.uniform(-0.04, 0.04), 0, 1)), -1, lineType=_cv2.LINE_AA)
                _cv2.circle(CC, (int(px_), int(py_)), bronze_r, float(np.clip(tCC + rng.uniform(-0.04, 0.04), 0, 1)), -1, lineType=_cv2.LINE_AA)
            # Inner purple ring
            purple_r = int(7 * s)
            for (px_, py_) in stroke_path[::2]:
                tM, tR, tCC = _temper(0.30)
                _cv2.circle(M,  (int(px_), int(py_)), purple_r, float(np.clip(tM  + rng.uniform(-0.04, 0.04), 0, 1)), -1, lineType=_cv2.LINE_AA)
                _cv2.circle(R,  (int(px_), int(py_)), purple_r, float(np.clip(tR  + rng.uniform(-0.04, 0.04), 0, 1)), -1, lineType=_cv2.LINE_AA)
                _cv2.circle(CC, (int(px_), int(py_)), purple_r, float(np.clip(tCC + rng.uniform(-0.04, 0.04), 0, 1)), -1, lineType=_cv2.LINE_AA)
            # WELD BEAD nuggets â€” chain of bright fusion blobs along the path
            nugget_r = max(2, int(4 * s))  # 8-12 px nugget diameter
            for i, (px_, py_) in enumerate(stroke_path[::2]):
                # bright bead core with Â±0.04 jitter
                _cv2.circle(M,  (int(px_), int(py_)), nugget_r, float(np.clip(0.85 + rng.uniform(-0.04, 0.04), 0, 1)), -1, lineType=_cv2.LINE_AA)
                _cv2.circle(R,  (int(px_), int(py_)), nugget_r, float(np.clip(0.18 + rng.uniform(-0.04, 0.04), 0, 1)), -1, lineType=_cv2.LINE_AA)
                _cv2.circle(CC, (int(px_), int(py_)), nugget_r, float(np.clip(0.62 + rng.uniform(-0.04, 0.04), 0, 1)), -1, lineType=_cv2.LINE_AA)
                bead_centers.append((int(px_), int(py_)))

        # 3) 30-60 standalone heat zones â€” 4-tier concentric temper ring
        n_zones = int(np.clip(45 * s * s, 30, 60))
        for _ in range(n_zones):
            cx = int(rng.integers(8, w - 8)); cy = int(rng.integers(8, h - 8))
            r_outer = int(rng.uniform(10, 16) * s)
            r_outer = max(8, min(r_outer, 16))
            # Tier 1 â€” outer faint straw halo
            tM, tR, tCC = _temper(0.92)
            _cv2.circle(M,  (cx, cy), r_outer, float(np.clip(tM  + rng.uniform(-0.04, 0.04), 0, 1)), max(1, int(s)), lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r_outer, float(np.clip(tCC + rng.uniform(-0.04, 0.04), 0, 1)), max(1, int(s)), lineType=_cv2.LINE_AA)
            # Tier 2 â€” bronze ring filled
            r2 = max(3, int(r_outer * 0.72))
            tM, tR, tCC = _temper(0.55)
            _cv2.circle(M,  (cx, cy), r2, float(np.clip(tM  + rng.uniform(-0.04, 0.04), 0, 1)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R,  (cx, cy), r2, float(np.clip(tR  + rng.uniform(-0.04, 0.04), 0, 1)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r2, float(np.clip(tCC + rng.uniform(-0.04, 0.04), 0, 1)), -1, lineType=_cv2.LINE_AA)
            # Tier 3 â€” purple/blue temper
            r3 = max(2, int(r_outer * 0.48))
            tM, tR, tCC = _temper(0.25)
            _cv2.circle(M,  (cx, cy), r3, float(np.clip(tM  + rng.uniform(-0.04, 0.04), 0, 1)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R,  (cx, cy), r3, float(np.clip(tR  + rng.uniform(-0.04, 0.04), 0, 1)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r3, float(np.clip(tCC + rng.uniform(-0.04, 0.04), 0, 1)), -1, lineType=_cv2.LINE_AA)
            # Tier 4 â€” burned dark scale core
            r4 = max(1, int(r_outer * 0.22))
            _cv2.circle(M,  (cx, cy), r4, float(np.clip(0.12 + rng.uniform(-0.04, 0.04), 0, 1)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R,  (cx, cy), r4, float(np.clip(0.62 + rng.uniform(-0.04, 0.04), 0, 1)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r4, float(np.clip(0.10 + rng.uniform(-0.04, 0.04), 0, 1)), -1, lineType=_cv2.LINE_AA)

        # 4) Sparse warm ember sparkles â€” only ON or NEAR weld beads, not chaos
        if bead_centers:
            n_ember = min(len(bead_centers) * 4, 250)
            for _ in range(n_ember):
                bc = bead_centers[rng.integers(0, len(bead_centers))]
                ex = bc[0] + int(rng.uniform(-12, 12) * s)
                ey = bc[1] + int(rng.uniform(-12, 12) * s)
                if 0 <= ex < w and 0 <= ey < h:
                    M[ey, ex]  = np.clip(M[ey, ex]  + 0.20, 0, 1)
                    CC[ey, ex] = np.clip(CC[ey, ex] + 0.16, 0, 1)

    out = np.stack([M, R, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)


