def checker_flag_subtle(shape, seed, sm, squares=44, warp=0.012, **kwargs):
    """checker_flag_subtle.

    identity: R6-creative rebuild â€” A WIND-FLAPPING checker flag in motion.
    Finer 14-18 px checker cells with parity-locked contrast (BRIGHT cells
    M-high R-low CC-low polished; DARK cells M-low R-high CC-mid matte).
    Hero motifs: (1) SINUSOIDAL WAVE WARP â€” flag ripple deforms the cell
    grid in a flowing sin pattern (the flag is FLUTTERING), (2) WIND-SHEAR
    motion-blur hairlines aligned with wave direction (5x density), (3)
    corner SPARKLES at cell junctions, (4) DARK MATTE WEFT specks inside
    dark cells, (5) parity-locked color-zone modulation â€” bright cells get
    chroma-rich variants (cream, ivory, pearl), (6) FRAYED-EDGE thread
    micro-tufts (1-3 px chroma flecks) along the flag's tear lines, (7)
    fine fleck carpet. Per-cell INDEPENDENT continuous M/R/CC. Dynamic
    energetic identity â€” not a static checkerboard.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + (hash("checker_flag_subtle_r6") % 10000))
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)

    yy_grid = np.arange(h, dtype=np.float32).reshape(h, 1)
    xx_grid = np.arange(w, dtype=np.float32).reshape(1, w)
    cell_px = max(14.0, 16.0 * scale)
    warp_field = _normalize(multi_scale_noise(shape, [16.0, 34.0], [0.55, 0.45], seed + 251))
    # SINUSOIDAL WIND-WAVE WARP (the flag is fluttering)
    wave_freq = 2.0 * np.pi / max(40.0, 90.0 * scale)
    wave_amp = float(rng.uniform(2.5, 4.5)) * scale
    wind_warp_y = np.sin(xx_grid * wave_freq + warp_field * 2.0).astype(np.float32) * wave_amp
    wind_warp_x = np.cos(yy_grid * wave_freq * 0.85 + warp_field * 1.5).astype(np.float32) * wave_amp * 0.6
    yyw = yy_grid + (warp_field - 0.5) * cell_px * float(warp) * 2.5 + wind_warp_y
    xxw = xx_grid + (warp_field - 0.5) * cell_px * float(warp) * 2.5 + wind_warp_x
    cell_y = np.floor(yyw / cell_px).astype(np.int32)
    cell_x = np.floor(xxw / cell_px).astype(np.int32)
    checker = np.mod(cell_x + cell_y, 2).astype(np.float32)

    n_cells_y = int(h / cell_px) + 2; n_cells_x = int(w / cell_px) + 2
    # Parity-locked: bright cells get bright M, dark cells get dark M.
    cell_M_bright = rng.uniform(0.65, 0.95, (n_cells_y, n_cells_x)).astype(np.float32)
    cell_M_dark   = rng.uniform(0.08, 0.30, (n_cells_y, n_cells_x)).astype(np.float32)
    cell_R_bright = rng.uniform(0.08, 0.25, (n_cells_y, n_cells_x)).astype(np.float32)
    cell_R_dark   = rng.uniform(0.65, 0.92, (n_cells_y, n_cells_x)).astype(np.float32)
    cell_CC_bright = rng.uniform(0.05, 0.25, (n_cells_y, n_cells_x)).astype(np.float32)
    cell_CC_dark   = rng.uniform(0.50, 0.85, (n_cells_y, n_cells_x)).astype(np.float32)
    iy = np.clip(cell_y, 0, n_cells_y - 1); ix = np.clip(cell_x, 0, n_cells_x - 1)
    M_b  = cell_M_bright[iy, ix]; M_d  = cell_M_dark[iy, ix]
    R_b  = cell_R_bright[iy, ix]; R_d  = cell_R_dark[iy, ix]
    CC_b = cell_CC_bright[iy, ix]; CC_d = cell_CC_dark[iy, ix]
    M  = (checker * M_b  + (1 - checker) * M_d).astype(np.float32)
    R  = (checker * R_b  + (1 - checker) * R_d).astype(np.float32)
    CC = (checker * CC_b + (1 - checker) * CC_d).astype(np.float32)

    fbm = _normalize(multi_scale_noise(shape, [3.0, 8.0, 18.0], [0.42, 0.34, 0.24], seed + 253))
    M = np.clip(M + (fbm - 0.5) * 0.14, 0, 1)
    R = np.clip(R + (fbm - 0.5) * 0.10, 0, 1)
    CC = np.clip(CC + (fbm - 0.5) * 0.10, 0, 1)

    if _CV2_OK:
        # FLUTTER LINES (5x density) â€” 6-16 px hairlines
        n_flutter = int(np.clip(3500 * (mn / 2048.0) ** 2, 1200, 11000))
        for _ in range(n_flutter):
            cx = rng.uniform(4, w - 4); cy = rng.uniform(4, h - 4)
            length = float(rng.uniform(6.0, 16.0) * scale)
            ang = float(rng.uniform(-0.20, 0.20))
            x0 = int(cx - np.cos(ang) * length * 0.5); y0 = int(cy - np.sin(ang) * length * 0.5)
            x1 = int(cx + np.cos(ang) * length * 0.5); y1 = int(cy + np.sin(ang) * length * 0.5)
            _cv2.line(M, (x0, y0), (x1, y1), float(rng.uniform(0.20, 0.88)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(R, (x0, y0), (x1, y1), float(rng.uniform(0.20, 0.72)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (x0, y0), (x1, y1), float(rng.uniform(0.15, 0.65)), 1, lineType=_cv2.LINE_AA)
        # CORNER SPARKLES â€” every cell junction
        n_corner = int(np.clip(3000 * (mn / 2048.0) ** 2, 1000, 9000))
        for _ in range(n_corner):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            r = max(1, int(rng.uniform(2.5, 5.5) * scale * 0.5))
            _cv2.circle(M, (cx, cy), r, float(rng.uniform(0.65, 0.94)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r, float(rng.uniform(0.06, 0.22)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r, float(rng.uniform(0.05, 0.22)), -1, lineType=_cv2.LINE_AA)
        # DARK MATTE WEFT SPECKS
        n_dark = int(np.clip(2200 * (mn / 2048.0) ** 2, 700, 6600))
        for _ in range(n_dark):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            r = max(1, int(rng.uniform(2.5, 5.0) * scale * 0.5))
            _cv2.circle(M, (cx, cy), r, float(rng.uniform(0.06, 0.22)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r, float(rng.uniform(0.60, 0.92)), -1, lineType=_cv2.LINE_AA)

        # WIND-SHEAR MOTION-BLUR HAIRLINES â€” along wave-direction (5x density)
        # Use a consistent flutter direction derived from the wave_freq
        shear_ang = float(rng.uniform(-0.18, 0.18))
        n_shear = int(np.clip(3200 * (mn / 2048.0) ** 2, 1100, 9500))
        for _ in range(n_shear):
            cx = float(rng.uniform(4, w - 4)); cy = float(rng.uniform(4, h - 4))
            length = float(rng.uniform(5.0, 12.0) * scale)
            ang = shear_ang + float(rng.normal(0, 0.08))
            x0 = int(cx - np.cos(ang) * length * 0.5); y0 = int(cy - np.sin(ang) * length * 0.5)
            x1 = int(cx + np.cos(ang) * length * 0.5); y1 = int(cy + np.sin(ang) * length * 0.5)
            _cv2.line(M, (x0, y0), (x1, y1), float(rng.uniform(0.28, 0.86)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(R, (x0, y0), (x1, y1), float(rng.uniform(0.15, 0.66)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (x0, y0), (x1, y1), float(rng.uniform(0.12, 0.62)), 1, lineType=_cv2.LINE_AA)

        # FRAYED-EDGE THREAD MICRO-TUFTS â€” 1-3 px chroma flecks (full coverage tufts)
        n_tuft = int(np.clip(2400 * (mn / 2048.0) ** 2, 800, 7200))
        for _ in range(n_tuft):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            r = max(1, int(rng.uniform(1.0, 2.5) * scale))
            tM = float(rng.uniform(0.18, 0.85))
            tR = float(rng.uniform(0.20, 0.85))
            tCC = float(rng.uniform(0.10, 0.80))
            _cv2.circle(M, (cx, cy), r, tM, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r, tR, -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r, tCC, -1, lineType=_cv2.LINE_AA)

    # FINE FLECKS â€” reduced density (owner: too much noise)
    n_flecks = int(np.clip(1800 * (mn / 2048.0) ** 2, 600, 5500))
    fx = rng.integers(0, w, n_flecks); fy = rng.integers(0, h, n_flecks)
    M[fy, fx] = np.clip(M[fy, fx] + rng.uniform(0.05, 0.20, n_flecks).astype(np.float32), 0, 1)
    R[fy, fx] = np.clip(R[fy, fx] - rng.uniform(0.05, 0.18, n_flecks).astype(np.float32), 0, 1)
    CC[fy, fx] = np.clip(CC[fy, fx] + rng.uniform(-0.12, 0.15, n_flecks).astype(np.float32), 0, 1)

    # OWNER REBUILD: removed rip-triangles + drift chevrons (owner said
    # "weird triangles + too much noise"). Pure clean fluttering checker
    # with one NEW soft motif â€” CHECKER-CELL CORNER POLISH HIGHLIGHTS:
    # tiny bright glint at every 4th cell corner where flag catches sun.
    if _CV2_OK:
        n_corner_glint = int(np.clip(1200 * (mn / 2048.0) ** 2, 400, 3000))
        for _ in range(n_corner_glint):
            cx = int(rng.uniform(0, w)); cy = int(rng.uniform(0, h))
            r = max(1, int(rng.uniform(1.5, 3.0) * scale))
            _cv2.circle(M, (cx, cy), r, float(rng.uniform(0.78, 0.96)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r, float(rng.uniform(0.05, 0.18)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r, float(rng.uniform(0.05, 0.20)), -1, lineType=_cv2.LINE_AA)

    out = np.stack([M, R, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)


checker_flag_subtle._spb_concept_complete = True


def drag_strip_burnout(shape, seed, sm, **kwargs):
    """drag_strip_burnout â€” R6 CREATIVE rebuild.

    identity: A wild Christmas-tree launch. HERO MOTIF: 2-4 huge horizontal
    SCORCH BANDS (10-30 px tall, near-full-width) of dark laid rubber â€”
    these read at thumbnail as the "drag strip burnout" story. INSIDE
    those bands: dense linear smear striations (1-3 px tall, 10-22 px
    long), grip-pit micro dots (rubber bit out of the contact patch), and
    crossed chevron tread imprint fragments. Punching through the bands
    and across the rest of the canvas: bright asphalt aggregate pebble
    flecks (1-3 px) so the substrate reads as real pavement, and a few
    "blue heat" smoke wisps streaming back from the launch. Per-feature
    INDEPENDENT continuous M/R/CC so the rubber field has chroma life,
    not flat soot. Differentiator vs aniso_grain: low M (rubber), high R
    (matte soot), with dramatic HORIZONTAL banding that names the launch.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + (hash("drag_strip_burnout_r6") % 10000))
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)

    yy, xx = np.mgrid[0:h, 0:w].astype(np.float32)

    # 1) BASE â€” pavement asphalt FBM, independent M/R/CC
    bM = _normalize(multi_scale_noise(shape, [3.0, 9.0, 18.0], [0.45, 0.35, 0.20], int(seed) + 8801))
    bR = _normalize(multi_scale_noise(shape, [3.0, 9.0, 18.0], [0.45, 0.35, 0.20], int(seed) + 8802))
    bC = _normalize(multi_scale_noise(shape, [3.0, 9.0, 18.0], [0.45, 0.35, 0.20], int(seed) + 8803))
    M = (0.38 + (bM - 0.5) * 0.28).astype(np.float32)
    R = (0.62 + (bR - 0.5) * 0.26).astype(np.float32)
    CC = (0.68 + (bC - 0.5) * 0.24).astype(np.float32)

    # 2) HERO: 2-4 BIG SCORCH BANDS â€” soft horizontal bands of laid rubber
    n_bands = int(rng.integers(2, 5))
    band_mask = np.zeros((h, w), dtype=np.float32)
    for _ in range(n_bands):
        by = float(rng.uniform(0.08, 0.92) * h)
        bH = float(rng.uniform(10.0, 30.0))  # 10-30 px tall
        # gaussian band cross-section, with along-band density wobble
        dy = yy - by
        band = np.exp(-(dy * dy) / (2.0 * bH * bH * 0.5))
        # band density wobble along x â€” make it darker in middle
        along = 0.6 + 0.4 * np.sin(xx / max(20.0, w / 32.0) + rng.uniform(0, 6.28))
        band = (band * along).astype(np.float32)
        band_mask = np.maximum(band_mask, band)
        # darken rubber zone â€” per-band independent chroma
        sM = float(rng.uniform(0.10, 0.22))
        sR = float(rng.uniform(0.82, 0.97))
        sCC = float(rng.uniform(0.78, 0.93))
        alpha = float(rng.uniform(0.55, 0.80))
        M = M * (1.0 - band * alpha) + sM * band * alpha
        R = R * (1.0 - band * alpha) + sR * band * alpha
        CC = CC * (1.0 - band * alpha) + sCC * band * alpha
    np.clip(M, 0, 1, out=M); np.clip(R, 0, 1, out=R); np.clip(CC, 0, 1, out=CC)

    if _CV2_OK:
        # 3) HORIZONTAL SMEAR STRIATIONS â€” denser inside bands
        n_str = int(np.clip(3600 * (mn / 2048.0) ** 2, 1400, 9000))
        for _ in range(n_str):
            cx = float(rng.uniform(4, w - 4)); cy = float(rng.uniform(4, h - 4))
            # bias position toward band zones if band_mask is high there
            length = float(rng.uniform(10.0, 22.0) * scale)
            ang = float(rng.normal(0.0, 0.06))
            x0s = int(cx - np.cos(ang) * length * 0.5); y0s = int(cy - np.sin(ang) * length * 0.5)
            x1s = int(cx + np.cos(ang) * length * 0.5); y1s = int(cy + np.sin(ang) * length * 0.5)
            tw = int(rng.choice([1, 1, 2]))
            _cv2.line(M, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.04, 0.30)), tw, lineType=_cv2.LINE_AA)
            _cv2.line(R, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.62, 0.98)), tw, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.55, 0.95)), tw, lineType=_cv2.LINE_AA)

        # 4) GRIP PIT MICRO-DOTS â€” bitten rubber craters
        n_pit = int(np.clip(2200 * (mn / 2048.0) ** 2, 800, 6000))
        for _ in range(n_pit):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            r = max(1, int(rng.uniform(1.0, 2.5)))
            _cv2.circle(M, (cx, cy), r, float(rng.uniform(0.04, 0.18)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r, float(rng.uniform(0.80, 0.99)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r, float(rng.uniform(0.78, 0.96)), -1, lineType=_cv2.LINE_AA)

        # 5) CHEVRON TREAD IMPRINT FRAGMENTS â€” paired crossed lines
        n_tr = int(np.clip(1400 * (mn / 2048.0) ** 2, 500, 4000))
        for _ in range(n_tr):
            cx = float(rng.uniform(6, w - 6)); cy = float(rng.uniform(6, h - 6))
            length = float(rng.uniform(8.0, 16.0))
            ang = float(rng.choice([0.6, -0.6])) + float(rng.normal(0.0, 0.10))
            x0s = int(cx - np.cos(ang) * length * 0.5); y0s = int(cy - np.sin(ang) * length * 0.5)
            x1s = int(cx + np.cos(ang) * length * 0.5); y1s = int(cy + np.sin(ang) * length * 0.5)
            _cv2.line(M, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.12, 0.40)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(R, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.58, 0.92)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.55, 0.90)), 1, lineType=_cv2.LINE_AA)

        # 6) BLUE HEAT SMOKE WISPS â€” short horizontal soft trails (rare)
        n_wisp = int(np.clip(140 * (mn / 1024.0) ** 2, 60, 420))
        for _ in range(n_wisp):
            cx = float(rng.uniform(0, w)); cy = float(rng.uniform(0, h))
            length = float(rng.uniform(12.0, 24.0))
            ang = float(rng.normal(0.0, 0.05))
            x0s = int(cx - np.cos(ang) * length * 0.5); y0s = int(cy - np.sin(ang) * length * 0.5)
            x1s = int(cx + np.cos(ang) * length * 0.5); y1s = int(cy + np.sin(ang) * length * 0.5)
            # heat-blue glint: high CC variance
            _cv2.line(CC, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.20, 0.55)), 1, lineType=_cv2.LINE_AA)

    # 7) PEBBLE FLECKS â€” bright asphalt aggregate pokes through rubber
    n_pebble = max(5200, int(h * w / 220))
    fy = rng.integers(0, h, n_pebble); fx = rng.integers(0, w, n_pebble)
    M[fy, fx] = np.maximum(M[fy, fx], rng.uniform(0.42, 0.95, n_pebble).astype(np.float32))
    R[fy, fx] = np.minimum(R[fy, fx], rng.uniform(0.12, 0.42, n_pebble).astype(np.float32))
    CC[fy, fx] = np.minimum(CC[fy, fx], rng.uniform(0.18, 0.55, n_pebble).astype(np.float32))

    out = np.stack([M, R, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
drag_strip_burnout._spb_concept_complete = True


def pit_lane_stripes(shape, seed, sm, num_stripes=22, stripe_width=0.010,
                     gap=0.042, angle=0.0, **kwargs):
    """pit_lane_stripes.

    identity: R6 creative rebuild â€” a fresh hot pit-out lane. HERO MOTIF: 3-5
    LONG BRIGHT BURNT-RUBBER SKID ARCS (rendered as multi-segment polylines
    14-22 px each, chained head-to-tail across the canvas) â€” these dark
    serpentine skids are the defining mark. Around them, thousands of short
    bright painted dashes (8-16 px) at ONE COMMON angle define the pit-out
    box striping. Diagonal layout. Asphalt substrate with three indep FBMs,
    cone-marker safety beads, grease droplets, sodium-light flares (rare
    bright spots), and asphalt 1-2 px aggregate. Per-stripe and per-skid
    INDEPENDENT continuous M/R/CC.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 119613)
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)

    # ASPHALT SUBSTRATE â€” three indep FBMs
    g_M = _normalize(multi_scale_noise((h, w), [2.0, 5.5, 14.0], [0.45, 0.35, 0.20], int(seed) + 121))
    g_R = _normalize(multi_scale_noise((h, w), [2.5, 6.0, 16.0], [0.45, 0.35, 0.20], int(seed) + 127))
    g_CC = _normalize(multi_scale_noise((h, w), [3.0, 7.0, 18.0], [0.45, 0.35, 0.20], int(seed) + 131))
    M = (0.30 + (g_M - 0.5) * 0.28).astype(np.float32)
    R = (0.70 + (g_R - 0.5) * 0.22).astype(np.float32)
    CC = (0.26 + (g_CC - 0.5) * 0.22).astype(np.float32)

    # DIAGONAL stripe angle â€” common to all dashes
    base_angle = float(angle + rng.uniform(0.25, 0.55))

    if _CV2_OK:
        # HERO â€” 3-5 LONG SKID ARCS as multi-segment serpentine polylines
        n_skids = int(rng.integers(3, 6))
        for _ in range(n_skids):
            sx = float(rng.uniform(0.0, 1.0) * w)
            sy = float(rng.uniform(0.0, 1.0) * h)
            seg_len = float(rng.uniform(14.0, 22.0) * scale)
            ang = base_angle + float(rng.uniform(-0.20, 0.20))
            n_seg = int(rng.integers(24, 44))
            v_M = float(rng.uniform(0.04, 0.18))
            v_R = float(rng.uniform(0.72, 0.96))
            v_CC = float(rng.uniform(0.08, 0.24))
            thick = max(2, int(rng.uniform(2.5, 4.5) * scale))
            for _s in range(n_seg):
                ang = ang + float(rng.normal(0, 0.06))  # serpentine drift
                ex = sx + np.cos(ang) * seg_len
                ey = sy + np.sin(ang) * seg_len
                _cv2.line(M, (int(sx), int(sy)), (int(ex), int(ey)), v_M, thick, lineType=_cv2.LINE_AA)
                _cv2.line(R, (int(sx), int(sy)), (int(ex), int(ey)), v_R, thick, lineType=_cv2.LINE_AA)
                _cv2.line(CC, (int(sx), int(sy)), (int(ex), int(ey)), v_CC, thick, lineType=_cv2.LINE_AA)
                sx, sy = ex, ey
                if sx < -8 or sx > w + 8 or sy < -8 or sy > h + 8:
                    break

        # PAINTED STRIPE DASHES â€” dense field, all near base_angle
        n_stripes = int(np.clip(4000 * (mn / 2048.0) ** 2, 1400, 16000))
        for _ in range(n_stripes):
            cx = float(rng.uniform(0.02, 0.98) * w); cy = float(rng.uniform(0.02, 0.98) * h)
            length = float(rng.uniform(8.0, 16.0) * scale)
            ang = base_angle + float(rng.normal(0, 0.06))
            x2 = int(np.clip(cx + np.cos(ang) * length, 0, w - 1))
            y2 = int(np.clip(cy + np.sin(ang) * length, 0, h - 1))
            thick = max(1, int(rng.uniform(1.0, 2.5) * scale))
            _cv2.line(M, (int(cx), int(cy)), (x2, y2), float(rng.uniform(0.55, 0.97)), thick, lineType=_cv2.LINE_AA)
            _cv2.line(R, (int(cx), int(cy)), (x2, y2), float(rng.uniform(0.18, 0.52)), thick, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (int(cx), int(cy)), (x2, y2), float(rng.uniform(0.06, 0.36)), thick, lineType=_cv2.LINE_AA)

        # TIRE-SCUFF DARK FRAGMENTS â€” 6-12 px, parallel
        n_scuff = int(np.clip(2200 * (mn / 2048.0) ** 2, 750, 8500))
        for _ in range(n_scuff):
            cx = float(rng.uniform(0.02, 0.98) * w); cy = float(rng.uniform(0.02, 0.98) * h)
            length = float(rng.uniform(6.0, 12.0) * scale)
            ang = base_angle + float(rng.normal(0, 0.40))
            x2 = int(np.clip(cx + np.cos(ang) * length, 0, w - 1))
            y2 = int(np.clip(cy + np.sin(ang) * length, 0, h - 1))
            _cv2.line(M, (int(cx), int(cy)), (x2, y2), float(rng.uniform(0.06, 0.25)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(R, (int(cx), int(cy)), (x2, y2), float(rng.uniform(0.65, 0.94)), 1, lineType=_cv2.LINE_AA)

        # CONE-MARKER DOTS â€” 2-4 px bright safety beads
        n_cones = int(np.clip(1600 * (mn / 2048.0) ** 2, 550, 6500))
        for _ in range(n_cones):
            cx = int(rng.uniform(0.02, 0.98) * w); cy = int(rng.uniform(0.02, 0.98) * h)
            r = max(1, int(rng.uniform(2.0, 4.0) * scale))
            _cv2.circle(M, (cx, cy), r, float(rng.uniform(0.70, 0.98)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r, float(rng.uniform(0.05, 0.30)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r, float(rng.uniform(0.18, 0.48)), -1, lineType=_cv2.LINE_AA)

        # GREASE DROPLET BEADS â€” 2-4 px
        n_grease = int(np.clip(2200 * (mn / 2048.0) ** 2, 750, 8500))
        for _ in range(n_grease):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            r = max(1, int(rng.uniform(1.5, 3.0) * scale))
            _cv2.circle(M, (cx, cy), r, float(rng.uniform(0.30, 0.65)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r, float(rng.uniform(0.10, 0.40)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r, float(rng.uniform(0.10, 0.32)), -1, lineType=_cv2.LINE_AA)

        # SODIUM-LIGHT FLARES â€” rare bright halos 6-12 px (about a dozen total)
        n_flare = int(rng.integers(8, 16))
        for _ in range(n_flare):
            fx_ = int(rng.uniform(0.05, 0.95) * w)
            fy_ = int(rng.uniform(0.05, 0.95) * h)
            for ri in range(3):
                rr = int((4 + ri * 3) * scale)
                _cv2.circle(M, (fx_, fy_), rr, float(rng.uniform(0.80, 0.99)), 1, lineType=_cv2.LINE_AA)
                _cv2.circle(CC, (fx_, fy_), rr, float(rng.uniform(0.75, 0.96)), 1, lineType=_cv2.LINE_AA)
                _cv2.circle(R, (fx_, fy_), rr, float(rng.uniform(0.08, 0.22)), 1, lineType=_cv2.LINE_AA)

    # ASPHALT AGGREGATE â€” 1-2 px speckle bright + dark
    n_fl = int(np.clip(6000 * (mn / 2048.0) ** 2, 2000, 22000))
    fy = rng.integers(0, h, n_fl); fx = rng.integers(0, w, n_fl)
    M[fy, fx] = np.maximum(M[fy, fx], rng.uniform(0.55, 0.95, n_fl).astype(np.float32))
    n_dk = int(np.clip(5000 * (mn / 2048.0) ** 2, 1600, 18000))
    dy = rng.integers(0, h, n_dk); dx = rng.integers(0, w, n_dk)
    M[dy, dx] = np.minimum(M[dy, dx], rng.uniform(0.05, 0.22, n_dk).astype(np.float32))
    R[dy, dx] = np.maximum(R[dy, dx], rng.uniform(0.60, 0.95, n_dk).astype(np.float32))

    out = np.stack([M, R, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
pit_lane_stripes._spb_concept_complete = True


def victory_lap_confetti(shape, seed, sm, density=0.0048, min_r=0.45,
                          max_r=2.2, **kwargs):
    """Victory-lap paper confetti â€” celebratory streamer scatter.

    identity: tumbling paper + foil confetti pieces over dark track surface.
    Each piece is INDEPENDENT across all 3 channels: some are metallic foil
    (high M + low R + glossy CC), some are matte paper (low M + high R +
    dull CC). Full-canvas coverage of pieces at varied rotations.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 9420)
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)
    # Dark track substrate
    if _CV2_OK:
        sh = max(64, h // 8); sw = max(64, w // 8)
        sn = rng.random((sh, sw)).astype(np.float32)
        sb = _cv2.GaussianBlur(sn, (0, 0), sigmaX=5.0, sigmaY=5.0)
        substrate = _cv2.resize(sb, (w, h), interpolation=_cv2.INTER_CUBIC).astype(np.float32)
    else:
        substrate = multi_scale_noise(shape, [25, 50], [0.6, 0.4], int(seed) + 9421)
    substrate = _normalize(substrate)
    M = (0.22 + (substrate - 0.5) * 0.10).astype(np.float32)
    R_ch = (0.62 + (substrate - 0.5) * 0.12).astype(np.float32)
    CC = (0.28 + (substrate - 0.5) * 0.10).astype(np.float32)

    if _CV2_OK:
        # DENSE confetti pieces across the whole canvas
        n_pieces = max(2400, int(h * w * 0.0028 + rng.integers(400, 1200)))
        for _ in range(n_pieces):
            cx = float(rng.uniform(-0.02, 1.02) * w)
            cy = float(rng.uniform(-0.02, 1.02) * h)
            # Streamer rectangle dimensions
            length = float(rng.uniform(8.0, 24.0) * scale)
            width = float(rng.uniform(2.0, 5.0) * scale)
            ang = float(rng.uniform(0, 2 * np.pi))
            ca, sa = float(np.cos(ang)), float(np.sin(ang))
            corners = [(-length, -width), (length, -width), (length, width), (-length, width)]
            pts = np.array([[int(np.clip(cx + cx_c * ca - cy_c * sa, 0, w - 1)),
                             int(np.clip(cy + cx_c * sa + cy_c * ca, 0, h - 1))]
                            for cx_c, cy_c in corners], dtype=np.int32)
            # Two confetti types â€” foil OR paper, each with independent channels
            is_foil = rng.random() < 0.45
            if is_foil:
                pc_M = float(rng.uniform(0.80, 0.97))
                pc_R = float(rng.uniform(0.05, 0.18))
                pc_CC = float(rng.uniform(0.78, 0.96))
            else:
                pc_M = float(rng.uniform(0.20, 0.55))
                pc_R = float(rng.uniform(0.62, 0.90))
                pc_CC = float(rng.uniform(0.22, 0.55))
            _cv2.fillPoly(M, [pts], pc_M, lineType=_cv2.LINE_AA)
            _cv2.fillPoly(R_ch, [pts], pc_R, lineType=_cv2.LINE_AA)
            _cv2.fillPoly(CC, [pts], pc_CC, lineType=_cv2.LINE_AA)
        # Curling thin paper twists (1-px hairlines) â€” adds movement
        n_twist = max(800, int(h * w / 1800))
        for _ in range(n_twist):
            cx = rng.uniform(2, w - 2); cy = rng.uniform(2, h - 2)
            length = float(rng.uniform(10.0, 26.0) * scale)
            ang = float(rng.uniform(0, 2 * np.pi))
            x0s = int(cx - np.cos(ang) * length * 0.5)
            y0s = int(cy - np.sin(ang) * length * 0.5)
            x1s = int(cx + np.cos(ang) * length * 0.5)
            y1s = int(cy + np.sin(ang) * length * 0.5)
            tw_M = float(rng.uniform(0.30, 0.92))
            tw_R = float(rng.uniform(0.15, 0.78))
            tw_CC = float(rng.uniform(0.30, 0.92))
            _cv2.line(M, (x0s, y0s), (x1s, y1s), tw_M, 1, lineType=_cv2.LINE_AA)
            _cv2.line(R_ch, (x0s, y0s), (x1s, y1s), tw_R, 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (x0s, y0s), (x1s, y1s), tw_CC, 1, lineType=_cv2.LINE_AA)

    out = np.stack([np.clip(M, 0, 1), np.clip(R_ch, 0, 1), np.clip(CC, 0, 1)], axis=2).astype(np.float32)
    if sm != 1.0:
        out = out * float(sm) + 0.5 * (1.0 - float(sm))
    return np.clip(out, 0, 1).astype(np.float32)

def _LEGACY_victory_lap_confetti_dead(shape, seed, sm, density=0.0048, min_r=0.45, max_r=2.2, **kwargs):
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(seed + 9420)
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)
    palette = np.array([0.18, 0.28, 0.38, 0.48, 0.58, 0.68, 0.78, 0.92], dtype=np.float32)
    # 1) SUBSTRATE â€” high-freq FBM + static-seed sin tile (dark track baseline)
    grain = multi_scale_noise(shape, [3.0, 7.0, 14.0, 22.0], [0.36, 0.30, 0.22, 0.14], seed + 9421)
    grain = _normalize(grain)
    yy_grid = np.arange(h, dtype=np.float32).reshape(h, 1)
    xx_grid = np.arange(w, dtype=np.float32).reshape(1, w)
    tile_a = (np.sin(yy_grid * (2.0 * np.pi / 16.0) + seed * 0.013) *
              np.sin(xx_grid * (2.0 * np.pi / 16.0) + seed * 0.017)) * 0.5 + 0.5
    result = 0.16 + (grain - 0.5) * 0.16 + (tile_a - 0.5) * 0.08
    result = result.astype(np.float32)
    # 2) EARLY BRU MASK â€” 5%/5% extreme injection BEFORE confetti
    mlo = rng.random(result.shape).astype(np.float32) < 0.055
    mhi = rng.random(result.shape).astype(np.float32) < 0.055
    result = np.where(mlo, 0.10, result)
    result = np.where(mhi, 0.92, result)
    if _CV2_OK:
        # 3) STREAMER RECTANGLES â€” rotated paper streamers (8-22 px) full palette
        n_pieces = int(np.clip(density * 0.55 * h * w, 600, 8000))
        for _ in range(n_pieces):
            cx_p = rng.uniform(0, w); cy_p = rng.uniform(0, h)
            length = rng.uniform(8.0, 22.0) * scale * 0.5
            width = rng.uniform(2.0, 5.0) * scale * 0.5
            ang = rng.uniform(0, 2 * np.pi)
            ca, sa = np.cos(ang), np.sin(ang)
            corners = [(-length, -width), (length, -width), (length, width), (-length, width)]
            pts = np.array([[int(np.clip(cx_p + cx_c * ca - cy_c * sa, 0, w - 1)),
                             int(np.clip(cy_p + cx_c * sa + cy_c * ca, 0, h - 1))]
                            for cx_c, cy_c in corners], dtype=np.int32)
            val = float(palette[rng.integers(0, 8)])
            _cv2.fillPoly(result, [pts], val, lineType=_cv2.LINE_AA)
        # 4) CURLING PAPER TWISTS â€” 1-px arc fragments (10-26 px)
        n_twist = int(np.clip(500 * (mn / 2048.0) ** 2, 180, 1800))
        for _ in range(n_twist):
            cx = rng.uniform(4, w - 4); cy = rng.uniform(4, h - 4)
            length = float(rng.uniform(10.0, 26.0) * scale * 0.5)
            ang = float(rng.uniform(0, 2 * np.pi))
            x0s = int(cx - np.cos(ang) * length * 0.5)
            y0s = int(cy - np.sin(ang) * length * 0.5)
            x1s = int(cx + np.cos(ang) * length * 0.5)
            y1s = int(cy + np.sin(ang) * length * 0.5)
            v = float(palette[rng.integers(2, 8)])
            _cv2.line(result, (x0s, y0s), (x1s, y1s), v, 1, lineType=_cv2.LINE_AA)
        # 5) SPARKLE DISCS â€” bright confetti points (3-7 px)
        n_sp = int(np.clip(450 * (mn / 2048.0) ** 2, 160, 1600))
        for _ in range(n_sp):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            r = max(1, int(rng.uniform(3.0, 7.0) * scale * 0.5))
            v = float(palette[rng.integers(5, 8)])
            _cv2.circle(result, (cx, cy), r, v, -1, lineType=_cv2.LINE_AA)
        # 6) DARK FLICKER DOTS â€” palette bottom (1-3 px)
        n_dk = int(np.clip(500 * (mn / 2048.0) ** 2, 180, 1800))
        for _ in range(n_dk):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            r = max(1, int(rng.uniform(1.0, 2.5) * scale))
            v = float(palette[rng.integers(0, 3)])
            _cv2.circle(result, (cx, cy), r, v, -1, lineType=_cv2.LINE_AA)
    # 7) FLECKS â€” 1500 single-pixel scatter, full palette
    n_flecks = int(np.clip(1500 * (mn / 2048.0) ** 2, 500, 4000))
    fx = rng.integers(0, w, n_flecks); fy = rng.integers(0, h, n_flecks)
    result[fy, fx] = np.maximum(result[fy, fx], palette[rng.integers(0, 8, n_flecks)])
    out = _sm_scale(_normalize(np.clip(result, 0.0, 1.0)), sm).astype(np.float32)
    return _validate_spec_output(out, "victory_lap_confetti")


def sponsor_tape_vinyl(shape, seed, sm, num_tapes=3, tape_length=0.55,
                       tape_width=0.06, **kwargs):
    """sponsor_tape_vinyl -- tick51 second-pass adds BARCODE/SERIAL strips hero.

    identity: A stockcar trunk plastered with sponsor decals AFTER A FEW LAPS.
    Hero: small rectangular vinyl SPONSOR PATCHES (8-18 x 5-12 px) at multiple
    rotations with bright foil edges and crisp inner contrast.
    TICK-51 NEW HERO: BARCODE / SERIAL NUMBER STRIPS â€” 14-22 tiny barcode
    strips (6-12 px wide x 3-5 px tall) scattered across the canvas, each
    built from 6-10 alternating bright/dark 1px vertical bars, like the
    serial / UPC strips on real sponsor decals. Each barcode gets
    INDEPENDENT continuous M/R/CC, with random rotation jitter so they
    don't all march together. Eight stacked tiers: base FBM, hero decal
    patches, NEW barcode/serial strips, tape segments, corner lifts,
    adhesive residue, fiber threads, foil glints, accent flecks.
    Per-feature INDEPENDENT continuous M/R/CC, WIDE chroma per element.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 50218)
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)

    # 1) BASE â€” INDEPENDENT FBM per channel for chroma diversity
    fM = _normalize(multi_scale_noise(shape, [2.0, 6.0, 16.0], [0.50, 0.30, 0.20], int(seed) + 9431))
    fR = _normalize(multi_scale_noise(shape, [2.5, 7.0, 18.0], [0.48, 0.30, 0.22], int(seed) + 9432))
    fCC = _normalize(multi_scale_noise(shape, [3.0, 8.0, 20.0], [0.46, 0.32, 0.22], int(seed) + 9433))
    M = (0.36 + (fM - 0.5) * 0.20).astype(np.float32)
    R = (0.44 + (fR - 0.5) * 0.18).astype(np.float32)
    CC = (0.34 + (fCC - 0.5) * 0.22).astype(np.float32)

    if _CV2_OK:
        # 2) HERO DECAL PATCHES â€” rotated rectangles, varied size, wide chroma
        n_hero = int(np.clip(420 * (mn / 2048.0) ** 2, 160, 1100))
        for _ in range(n_hero):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            rw = max(4, int(float(rng.uniform(8.0, 18.0)) * scale))
            rh = max(3, int(float(rng.uniform(5.0, 12.0)) * scale))
            ang_deg = float(rng.choice([0, 15, 30, 45, -15, -30, -45, 75, -75, 90])) + float(rng.uniform(-6, 6))
            # Build rotated rect via boxPoints
            box = _cv2.boxPoints(((cx, cy), (rw, rh), ang_deg)).astype(np.int32)
            mv = float(rng.uniform(0.18, 0.96))
            rv = float(rng.uniform(0.06, 0.42))
            ccv = float(rng.uniform(0.10, 0.92))
            _cv2.fillPoly(M, [box], mv)
            _cv2.fillPoly(R, [box], rv)
            _cv2.fillPoly(CC, [box], ccv)
            # Bright foil edge trim
            _cv2.polylines(M, [box], True, float(rng.uniform(0.78, 0.99)), 1, lineType=_cv2.LINE_AA)
            _cv2.polylines(CC, [box], True, float(rng.uniform(0.60, 0.95)), 1, lineType=_cv2.LINE_AA)

        # TICK-51 NEW HERO â€” BARCODE / SERIAL NUMBER STRIPS
        # Tiny 6-12 x 3-5 px strips of alternating 1-px bright/dark vertical
        # bars at random rotations, like UPC codes on real sponsor decals.
        n_bc = int(rng.integers(14, 23))
        for _ in range(n_bc):
            bcx = float(rng.uniform(0.05, 0.95) * w)
            bcy = float(rng.uniform(0.05, 0.95) * h)
            bc_w = float(rng.uniform(6.0, 12.0) * scale)
            bc_h = float(rng.uniform(3.0, 5.0) * scale)
            bc_ang = float(rng.uniform(-np.pi, np.pi))
            # Independent chroma flavor for this barcode strip
            bright_M = float(rng.uniform(0.75, 0.98))
            bright_R = float(rng.uniform(0.04, 0.16))
            bright_CC = float(rng.uniform(0.20, 0.95))
            dark_M = float(rng.uniform(0.05, 0.20))
            dark_R = float(rng.uniform(0.55, 0.90))
            dark_CC = float(rng.uniform(0.05, 0.30))
            n_bars = int(rng.integers(6, 11))
            ca = np.cos(bc_ang); sa = np.sin(bc_ang)
            for k in range(n_bars):
                t = (k - (n_bars - 1) * 0.5) / max(n_bars, 1) * bc_w
                # End coords along bar (perpendicular to bc_ang)
                px = bcx + ca * t
                py = bcy + sa * t
                ex0 = int(np.clip(px - sa * bc_h * 0.5, 0, w - 1))
                ey0 = int(np.clip(py + ca * bc_h * 0.5, 0, h - 1))
                ex1 = int(np.clip(px + sa * bc_h * 0.5, 0, w - 1))
                ey1 = int(np.clip(py - ca * bc_h * 0.5, 0, h - 1))
                # Alternate bright/dark bars
                if k & 1:
                    mv_b = dark_M; rv_b = dark_R; ccv_b = dark_CC
                else:
                    mv_b = bright_M; rv_b = bright_R; ccv_b = bright_CC
                _cv2.line(M, (ex0, ey0), (ex1, ey1), mv_b, 1, lineType=_cv2.LINE_AA)
                _cv2.line(R, (ex0, ey0), (ex1, ey1), rv_b, 1, lineType=_cv2.LINE_AA)
                _cv2.line(CC, (ex0, ey0), (ex1, ey1), ccv_b, 1, lineType=_cv2.LINE_AA)

        # 3) TAPE-STRIP SEGMENTS â€” 4 angle buckets, 10-22 px
        n_tape = int(np.clip(1600 * (mn / 2048.0) ** 2, 580, 4200))
        ang_buckets = [0.0, np.pi * 0.25, np.pi * 0.5, -np.pi * 0.25]
        for i in range(n_tape):
            cx = float(rng.uniform(0.02, 0.98)) * w
            cy = float(rng.uniform(0.02, 0.98)) * h
            length = float(rng.uniform(10.0, 22.0)) * scale
            ang = ang_buckets[i & 3] + float(rng.uniform(-0.14, 0.14))
            x2 = int(np.clip(cx + np.cos(ang) * length, 0, w - 1))
            y2 = int(np.clip(cy + np.sin(ang) * length, 0, h - 1))
            thick = max(1, int(float(rng.uniform(1.4, 3.0)) * scale))
            _cv2.line(M, (int(cx), int(cy)), (x2, y2), float(rng.uniform(0.50, 0.96)), thick, lineType=_cv2.LINE_AA)
            _cv2.line(R, (int(cx), int(cy)), (x2, y2), float(rng.uniform(0.06, 0.36)), thick, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (int(cx), int(cy)), (x2, y2), float(rng.uniform(0.10, 0.82)), thick, lineType=_cv2.LINE_AA)

        # 4) NEW â€” DECAL CORNER LIFT highlights (4-8 px triangles)
        n_lift = int(np.clip(560 * (mn / 2048.0) ** 2, 200, 1500))
        for _ in range(n_lift):
            cx = int(rng.integers(4, w - 4)); cy = int(rng.integers(4, h - 4))
            sz = max(2, int(float(rng.uniform(4.0, 8.0)) * scale))
            ang = float(rng.uniform(0, 2 * np.pi))
            p1 = (cx, cy)
            p2 = (int(cx + np.cos(ang) * sz), int(cy + np.sin(ang) * sz))
            p3 = (int(cx + np.cos(ang + 0.7) * sz * 0.6), int(cy + np.sin(ang + 0.7) * sz * 0.6))
            tri = np.array([p1, p2, p3], dtype=np.int32)
            _cv2.fillPoly(M, [tri], float(rng.uniform(0.78, 0.98)))
            _cv2.fillPoly(R, [tri], float(rng.uniform(0.04, 0.18)))
            _cv2.fillPoly(CC, [tri], float(rng.uniform(0.62, 0.95)))

        # 5) ADHESIVE RESIDUE SPECKS (2-3 px)
        n_specks = int(np.clip(1500 * (mn / 2048.0) ** 2, 520, 3800))
        for _ in range(n_specks):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            r_s = max(1, int(float(rng.uniform(1.2, 2.5)) * scale))
            _cv2.circle(M, (cx, cy), r_s, float(rng.uniform(0.10, 0.36)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r_s, float(rng.uniform(0.55, 0.95)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r_s, float(rng.uniform(0.46, 0.94)), -1, lineType=_cv2.LINE_AA)

        # 6) FIBER-PULL THREADS (6-12 px)
        n_fib = int(np.clip(900 * (mn / 2048.0) ** 2, 320, 2700))
        for _ in range(n_fib):
            cx = float(rng.uniform(4, w - 4)); cy = float(rng.uniform(4, h - 4))
            length = float(rng.uniform(6.0, 12.0)) * scale
            ang = float(rng.uniform(0.0, 2 * np.pi))
            x2 = int(np.clip(cx + np.cos(ang) * length, 0, w - 1))
            y2 = int(np.clip(cy + np.sin(ang) * length, 0, h - 1))
            _cv2.line(M, (int(cx), int(cy)), (x2, y2), float(rng.uniform(0.30, 0.86)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(R, (int(cx), int(cy)), (x2, y2), float(rng.uniform(0.18, 0.58)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (int(cx), int(cy)), (x2, y2), float(rng.uniform(0.16, 0.72)), 1, lineType=_cv2.LINE_AA)

        # 7) FOIL GLINTS (1-2 px) â€” bright pinpoints
        n_dot = int(np.clip(1900 * (mn / 2048.0) ** 2, 680, 4800))
        for _ in range(n_dot):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            r_s = max(1, int(float(rng.uniform(1.0, 2.0)) * scale))
            _cv2.circle(M, (cx, cy), r_s, float(rng.uniform(0.62, 0.98)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r_s, float(rng.uniform(0.04, 0.22)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r_s, float(rng.uniform(0.08, 0.62)), -1, lineType=_cv2.LINE_AA)

        # 7b) R6-TICK79 HERO â€” PRINT MISREGISTRATION GHOST OFFSET
        # Tiny rectangular GHOST OFFSETS shifted 2-3 px in an opposing
        # chroma â€” the signature of a misregistered CMYK silkscreen pass.
        # Visually reads as halftone ghosting: bright cyan-leaning offset
        # PLUS dim magenta-leaning offset paired around small decal cores.
        # ~60-160 ghosts. INDEPENDENT continuous M/R/CC per offset.
        n_ghost = int(np.clip(280 * (mn / 2048.0) ** 2, 90, 700))
        for _ in range(n_ghost):
            gx = int(rng.integers(6, w - 6)); gy = int(rng.integers(6, h - 6))
            gw = max(3, int(float(rng.uniform(4.0, 9.0)) * scale))
            gh = max(2, int(float(rng.uniform(3.0, 6.0)) * scale))
            dx_o = int(rng.choice([-3, -2, 2, 3]))
            dy_o = int(rng.choice([-2, -1, 1, 2]))
            # CORE (warm-leaning, brighter M, lower R)
            _cv2.rectangle(M,  (gx, gy), (gx + gw, gy + gh), float(rng.uniform(0.62, 0.88)), -1, lineType=_cv2.LINE_AA)
            _cv2.rectangle(R,  (gx, gy), (gx + gw, gy + gh), float(rng.uniform(0.05, 0.18)), -1, lineType=_cv2.LINE_AA)
            _cv2.rectangle(CC, (gx, gy), (gx + gw, gy + gh), float(rng.uniform(0.15, 0.45)), -1, lineType=_cv2.LINE_AA)
            # GHOST offset (cool-leaning, lower M, higher CC)
            gx2 = int(np.clip(gx + dx_o, 0, w - gw - 1)); gy2 = int(np.clip(gy + dy_o, 0, h - gh - 1))
            _cv2.rectangle(M,  (gx2, gy2), (gx2 + gw, gy2 + gh), float(rng.uniform(0.28, 0.55)), 1, lineType=_cv2.LINE_AA)
            _cv2.rectangle(R,  (gx2, gy2), (gx2 + gw, gy2 + gh), float(rng.uniform(0.10, 0.25)), 1, lineType=_cv2.LINE_AA)
            _cv2.rectangle(CC, (gx2, gy2), (gx2 + gw, gy2 + gh), float(rng.uniform(0.55, 0.88)), 1, lineType=_cv2.LINE_AA)

    # 8) DENSE ACCENT FLECKS â€” no blank substrate
    n_fl = int(np.clip(2600 * (mn / 2048.0) ** 2, 900, 6000))
    fy = rng.integers(0, h, n_fl); fx = rng.integers(0, w, n_fl)
    M[fy, fx] = np.maximum(M[fy, fx], rng.uniform(0.40, 0.96, n_fl).astype(np.float32))
    R[fy, fx] = np.minimum(R[fy, fx], rng.uniform(0.06, 0.38, n_fl).astype(np.float32))
    CC[fy, fx] = np.maximum(CC[fy, fx], rng.uniform(0.10, 0.92, n_fl).astype(np.float32))

    out = np.stack([np.clip(M, 0, 1), np.clip(R, 0, 1), np.clip(CC, 0, 1)], axis=-1).astype(np.float32)
    return _sm_scale(out, sm)


sponsor_tape_vinyl._spb_concept_complete = True


def race_number_ghost(shape, seed, sm, **kwargs):
    """race_number_ghost.

    identity: Round-6 CREATIVE rebuild â€” where a vinyl race number used
    to sit. Aged paint substrate covered in dense sticker-glue residue
    specks (1.5-5 px, INDEPENDENT M/R/CC), tape-edge dashes (10-24 px),
    glyph-fragment arc strokes, crystalline crust flecks, dust pinpoints.
    NEW hero motifs: (1) a faint MEGA-NUMERAL silhouette â€” a soft
    rectangular zone where the vinyl protected the paint, slightly
    fresher M/CC underneath, with a hint of a digit edge running through
    it (helps name read at thumbnail); (2) RIVET / SCREW HOLE shadow
    rings â€” 4-8 sparse 3-4 px concentric ring marks where number-plate
    mount holes used to be. Full-canvas coverage, fine features
    everywhere.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + (hash("race_number_ghost") % 10000))
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)

    # 1) Aged paint substrate (where sticker was)
    g_M = _normalize(multi_scale_noise((h, w), [2.5, 7.0, 18.0], [0.45, 0.32, 0.23], int(seed) + 141))
    g_R = _normalize(multi_scale_noise((h, w), [3.0, 8.0, 22.0], [0.45, 0.32, 0.23], int(seed) + 143))
    g_CC = _normalize(multi_scale_noise((h, w), [3.5, 9.0, 24.0], [0.45, 0.32, 0.23], int(seed) + 149))
    M = (0.46 + (g_M - 0.5) * 0.30).astype(np.float32)
    R = (0.48 + (g_R - 0.5) * 0.28).astype(np.float32)
    CC = (0.40 + (g_CC - 0.5) * 0.30).astype(np.float32)

    # HERO MOTIF â€” faint MEGA-NUMERAL silhouette zone. A rectangular
    # patch (about 40-65% of canvas) where the vinyl PROTECTED the paint,
    # so under it M is slightly higher, R slightly lower (fresher gloss).
    # This is NOT a macro feature in the doctrine sense â€” it's a soft
    # gradient layer that the fine details overlay; the eye reads "this
    # is where a number was" at thumbnail scale.
    yy, xx = np.mgrid[0:h, 0:w].astype(np.float32)
    nx_c = float(rng.uniform(0.30, 0.70) * w)
    ny_c = float(rng.uniform(0.30, 0.70) * h)
    nrw = float(rng.uniform(0.35, 0.55) * w)
    nrh = float(rng.uniform(0.45, 0.65) * h)
    inside = (np.abs(xx - nx_c) < nrw * 0.5) & (np.abs(yy - ny_c) < nrh * 0.5)
    # Soft edge falloff
    ex = np.clip(1.0 - (np.abs(xx - nx_c) / (nrw * 0.5)) ** 4, 0, 1)
    ey = np.clip(1.0 - (np.abs(yy - ny_c) / (nrh * 0.5)) ** 4, 0, 1)
    ghost = (ex * ey).astype(np.float32)
    M = np.clip(M + ghost * 0.12, 0, 1)
    R = np.clip(R - ghost * 0.10, 0, 1)
    CC = np.clip(CC + ghost * 0.08, 0, 1)
    # Hint of a digit edge â€” a single vertical line inside the silhouette
    # at a random offset (suggests "1" or edge of "0").
    if _CV2_OK:
        dx = int(nx_c + rng.uniform(-0.20, 0.20) * nrw)
        dy0 = int(ny_c - nrh * 0.32); dy1 = int(ny_c + nrh * 0.32)
        _cv2.line(M, (dx, dy0), (dx, dy1), float(rng.uniform(0.50, 0.70)), 2, lineType=_cv2.LINE_AA)
        _cv2.line(R, (dx, dy0), (dx, dy1), float(rng.uniform(0.30, 0.50)), 2, lineType=_cv2.LINE_AA)

    if _CV2_OK:
        # 2) Adhesive residue specks (1.5-5 px)
        n_specks = int(np.clip(750 * (mn / 2048.0) ** 2, 260, 2800))
        for _ in range(n_specks):
            cx = int(rng.uniform(0.02, 0.98) * w); cy = int(rng.uniform(0.02, 0.98) * h)
            r = max(1, int(rng.uniform(1.5, 5.0) * scale))
            _cv2.circle(M, (cx, cy), r, float(rng.uniform(0.20, 0.85)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r, float(rng.uniform(0.30, 0.85)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r, float(rng.uniform(0.15, 0.55)), -1, lineType=_cv2.LINE_AA)

        # 3) Tape-edge dashed lines (12-28 px)
        n_dash = int(np.clip(520 * (mn / 2048.0) ** 2, 170, 2000))
        for _ in range(n_dash):
            cx = float(rng.uniform(0.05, 0.95) * w); cy = float(rng.uniform(0.05, 0.95) * h)
            length = float(rng.uniform(10.0, 24.0) * scale)
            ang = float(rng.uniform(0, 2 * np.pi))
            x0s = int(cx - np.cos(ang) * length * 0.5); y0s = int(cy - np.sin(ang) * length * 0.5)
            x1s = int(cx + np.cos(ang) * length * 0.5); y1s = int(cy + np.sin(ang) * length * 0.5)
            thick = max(1, int(rng.uniform(1.0, 2.0) * scale))
            _cv2.line(M, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.45, 0.85)), thick, lineType=_cv2.LINE_AA)
            _cv2.line(R, (x0s, y0s), (x1s, y1s), float(rng.uniform(0.25, 0.60)), thick, lineType=_cv2.LINE_AA)

        # 4) Glyph-fragment arc strokes (8-16 px arcs â€” sticker-text remnants)
        n_glyph = int(np.clip(420 * (mn / 2048.0) ** 2, 140, 1700))
        for _ in range(n_glyph):
            cx = int(rng.uniform(0.05, 0.95) * w); cy = int(rng.uniform(0.05, 0.95) * h)
            r = max(2, int(rng.uniform(4.0, 8.0) * scale))
            a0 = float(rng.uniform(0, 360))
            a1 = a0 + float(rng.uniform(40, 130))
            thick = max(1, int(scale * 1.5))
            _cv2.ellipse(M, (cx, cy), (r, r), 0, a0, a1, float(rng.uniform(0.50, 0.88)), thick, lineType=_cv2.LINE_AA)
            _cv2.ellipse(R, (cx, cy), (r, r), 0, a0, a1, float(rng.uniform(0.22, 0.58)), thick, lineType=_cv2.LINE_AA)

        # 5) Bright crystalline crust flecks (1-3 px solid bright)
        n_crust = int(np.clip(700 * (mn / 2048.0) ** 2, 240, 1800))
        for _ in range(n_crust):
            cx = int(rng.integers(0, w)); cy = int(rng.integers(0, h))
            r = max(1, int(rng.uniform(1.0, 2.5) * scale))
            _cv2.circle(M, (cx, cy), r, float(rng.uniform(0.75, 0.98)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r, float(rng.uniform(0.04, 0.20)), -1, lineType=_cv2.LINE_AA)

    # Dark dust pinpoints
    n_dust = max(500, int(h * w / 5500))
    dy = rng.integers(0, h, n_dust); dx = rng.integers(0, w, n_dust)
    M[dy, dx] = np.minimum(M[dy, dx], rng.uniform(0.08, 0.25, n_dust).astype(np.float32))
    R[dy, dx] = np.maximum(R[dy, dx], rng.uniform(0.55, 0.88, n_dust).astype(np.float32))

    # HERO MOTIF â€” RIVET / SCREW HOLE shadow rings: 4-8 sparse concentric
    # ring marks where number-plate mount holes used to be, around the
    # silhouette zone. Per-ring INDEPENDENT M/R/CC.
    if _CV2_OK:
        n_riv = int(rng.integers(4, 9))
        for _ in range(n_riv):
            rx = int(nx_c + rng.uniform(-0.55, 0.55) * nrw)
            ry = int(ny_c + rng.uniform(-0.55, 0.55) * nrh)
            if not (0 <= rx < w and 0 <= ry < h):
                continue
            rrad = max(2, int(rng.uniform(3.0, 4.5) * scale))
            # Outer ring (dim)
            _cv2.circle(M, (rx, ry), rrad, float(rng.uniform(0.10, 0.30)), 1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (rx, ry), rrad, float(rng.uniform(0.60, 0.85)), 1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (rx, ry), rrad, float(rng.uniform(0.10, 0.30)), 1, lineType=_cv2.LINE_AA)
            # Inner dark dot (hole)
            _cv2.circle(M, (rx, ry), 1, float(rng.uniform(0.04, 0.15)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (rx, ry), 1, float(rng.uniform(0.70, 0.95)), -1, lineType=_cv2.LINE_AA)

    out = np.stack([M, R, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
race_number_ghost._spb_concept_complete = True


