# 2026-04-21 HEENAN OVERNIGHT iter 3: HP2 / HP3 / H4HR-4..H4HR-8
# cross-registry rename aliases. The JS side renamed these spec-pattern
# IDs to disambiguate from colliding MONOLITHIC ids (HP2: carbon_weave,
# HP3: diffraction_grating, H4HR-4..8: oil_slick/gravity_well/sparkle_*),
# but PATTERN_CATALOG still uses the un-prefixed legacy keys. Without
# this block, selecting the JS-canonical id results in
# PATTERN_CATALOG.get(sp_name) â†’ None â†’ `continue` (silent no-render).
#
# Each alias points the JS-canonical id at the same function the old
# key points at, so the painter gets identical render output.
_HP_H4HR_SPEC_ALIASES = {
    # HP2 â€” cross-registry rename to disambiguate from BASES/PATTERNS carbon_weave
    "spec_carbon_weave":              "carbon_weave",
    # HP3 â€” renamed to spec_diffraction_grating_cd (CC target via docstring)
    "spec_diffraction_grating_cd":    "diffraction_grating",
    # H4HR-4..H4HR-8 â€” 5 collisions vs MONOLITHICS
    "spec_oil_slick":                 "oil_slick",
    "spec_gravity_well":              "gravity_well",
    "spec_sparkle_constellation":     "sparkle_constellation",
    "spec_sparkle_firefly":           "sparkle_firefly",
    "spec_sparkle_champagne":         "sparkle_champagne",
}
for _new_id, _old_id in _HP_H4HR_SPEC_ALIASES.items():
    if _new_id not in PATTERN_CATALOG and _old_id in PATTERN_CATALOG:
        PATTERN_CATALOG[_new_id] = PATTERN_CATALOG[_old_id]


def _spb_catalog_seed(name):
    h = 2166136261
    for ch in str(name):
        h ^= ord(ch)
        h = (h * 16777619) & 0xFFFFFFFF
    return h


def _spb_micro_overlay(shape, seed, family):
    h, w = shape[:2] if len(shape) > 2 else shape
    rng_seed = (int(seed) * 1664525 + int(family) * 1013904223) & 0xFFFFFFFF
    rng = np.random.default_rng(rng_seed)
    raw = rng.random((h, w), dtype=np.float32)
    fine = raw * 0.58 + _gauss(raw, sigma=0.85) * 0.27 + _gauss(raw, sigma=2.1) * 0.15
    fine = _normalize(fine).astype(np.float32)
    sparkle = (raw > (0.986 - min(0.018, (family % 10) * 0.0018))).astype(np.float32)
    if sparkle.any():
        sparkle = np.maximum(sparkle, _gauss(sparkle, sigma=0.38) * 0.55).astype(np.float32)
    return fine, sparkle


_SPB_SPEC_REBUILD_MODES = {
    # "depth_gradient": removed 2026-05-24 â€” direct 3-channel rebuild owns this
    # "exhaust_pipe_scorch": removed 2026-05-24 spec-rebuild tick â€” direct 3-channel rebuild owns this
    "undercarriage_spray": "spray_grit",
    # "tarmac_grit_embed": removed 2026-05-25 round-5 corrective rebuild â€” direct 3-channel rebuild owns this
    # "spec_chromatic_aberration": removed 2026-05-24 round-4 rebuild â€” direct 3-channel owns this
    "sponsor_deboss": "deboss",
    # "rain_droplet_beads": removed 2026-05-24 spec-rebuild tick â€” direct 3-channel rebuild owns this
    "sticker_bubble_film": "bubbles",
    # "spec_caustic_light": removed 2026-05-23 owner rebuild â€” direct 3-channel impl
    # "gravel_chip_field": removed 2026-05-25 round-5 corrective rebuild â€” direct 3-channel rebuild owns this
    # "racing_tape_residue": removed 2026-05-24 spec-rebuild tick â€” direct 3-channel rebuild owns this
    "sponsor_emboss_v2": "emboss",
    # "moire_overlay": removed 2026-05-24 spec-rebuild tick â€” direct 3-channel rebuild owns this
}


def _spb_draw_line(canvas, x0, y0, x1, y1, value=1.0, thickness=1):
    h, w = canvas.shape
    if _CV2_OK:
        _cv2.line(
            canvas,
            (int(np.clip(x0, 0, w - 1)), int(np.clip(y0, 0, h - 1))),
            (int(np.clip(x1, 0, w - 1)), int(np.clip(y1, 0, h - 1))),
            float(value),
            thickness=max(1, int(thickness)),
            lineType=_cv2.LINE_AA,
        )
        return
    steps = max(abs(int(x1 - x0)), abs(int(y1 - y0)), 1)
    xs = np.clip(np.linspace(x0, x1, steps + 1).astype(np.int32), 0, w - 1)
    ys = np.clip(np.linspace(y0, y1, steps + 1).astype(np.int32), 0, h - 1)
    np.maximum.at(canvas, (ys, xs), float(value))


def _spb_spec_rebuild_feature(shape, seed, name, mode):
    """Targeted concept layer for underperforming spec overlays.

    This is intentionally ID-gated. The global wrapper adds pixel coverage;
    these modes add the visual idea the weak thumbnail promised.
    """
    h, w = shape[:2] if len(shape) > 2 else shape
    rng = np.random.default_rng((_spb_catalog_seed(name) + int(seed) * 2654435761) & 0xFFFFFFFF)
    yy, xx = np.mgrid[0:h, 0:w].astype(np.float32)
    xn = xx / max(w - 1, 1)
    yn = yy / max(h - 1, 1)
    base = np.zeros((h, w), dtype=np.float32)
    fine, sparkle = _spb_micro_overlay((h, w), seed + 991, _spb_catalog_seed(name) ^ 0xA5A5A5A5)

    if mode == "depth_pool":
        gravity = yn ** 1.35
        meniscus = np.sin((yn + fine * 0.075) * np.pi * 34.0 + np.sin(xn * 13.0) * 1.7)
        base = gravity * 0.58 + (meniscus * 0.5 + 0.5) * 0.22 + fine * 0.20
        for _ in range(18):
            x = rng.uniform(0, w)
            _spb_draw_line(base, x, rng.uniform(0, h * 0.15), x + rng.uniform(-18, 18), h, rng.uniform(0.35, 0.95), 1)
        base = np.maximum(base, _gauss(base, 0.55) * 0.72)
    elif mode in {"drips", "spray_grit"}:
        for _ in range(90 if mode == "drips" else 150):
            x = rng.uniform(0, w)
            y0 = rng.uniform(0, h * 0.92)
            length = rng.uniform(h * 0.035, h * (0.28 if mode == "drips" else 0.13))
            lean = rng.uniform(-0.08, 0.08) * length
            _spb_draw_line(base, x, y0, x + lean, y0 + length, rng.uniform(0.35, 1.0), rng.integers(1, 3))
        base += sparkle * (0.40 if mode == "spray_grit" else 0.20)
        base = np.maximum(base, _gauss(base, 0.75) * 0.62)
    elif mode in {"bubbles", "beads"}:
        count = 180 if mode == "bubbles" else 260
        max_r = 13.0 if mode == "bubbles" else 8.0
        for _ in range(count):
            cx = int(rng.integers(0, w))
            cy = int(rng.integers(0, h))
            r = int(max(2, rng.uniform(2.0, max_r)))
            value = float(rng.uniform(0.48, 1.0))
            if _CV2_OK:
                _cv2.circle(base, (cx, cy), r, value, 1, lineType=_cv2.LINE_AA)
                if r > 3:
                    _cv2.circle(base, (cx, cy), max(1, r // 3), value * 0.22, -1, lineType=_cv2.LINE_AA)
            else:
                _spb_draw_line(base, cx - r, cy, cx + r, cy, value, 1)
                _spb_draw_line(base, cx, cy - r, cx, cy + r, value * 0.72, 1)
        base += fine * 0.20
    elif mode == "race_ghost":
        # Two faded seven-segment-style numerals, with residue halos and worn edges.
        for digit in range(2):
            ox = w * (0.24 + digit * 0.27 + rng.uniform(-0.025, 0.025))
            oy = h * rng.uniform(0.24, 0.36)
            dw = w * rng.uniform(0.16, 0.22)
            dh = h * rng.uniform(0.30, 0.42)
            segs = [
                (0.08, 0.00, 0.92, 0.00),
                (0.00, 0.06, 0.00, 0.48),
                (1.00, 0.06, 1.00, 0.48),
                (0.10, 0.50, 0.90, 0.50),
                (0.00, 0.54, 0.00, 0.94),
                (1.00, 0.54, 1.00, 0.94),
                (0.08, 1.00, 0.92, 1.00),
            ]
            keep = rng.choice(len(segs), size=int(rng.integers(4, 7)), replace=False)
            for idx in keep:
                x0, y0, x1, y1 = segs[int(idx)]
                _spb_draw_line(
                    base,
                    ox + x0 * dw,
                    oy + y0 * dh,
                    ox + x1 * dw,
                    oy + y1 * dh,
                    rng.uniform(0.55, 1.0),
                    max(2, int(min(h, w) * rng.uniform(0.006, 0.012))),
                )
        halo = _gauss(base, 2.0)
        worn = (fine > 0.58).astype(np.float32)
        base = np.maximum(base * (0.62 + worn * 0.38), halo * 0.42)
        base += fine * 0.22 + sparkle * 0.18
    elif mode in {"tape", "ghost", "deboss", "emboss"}:
        for _ in range(16):
            y = rng.uniform(0.05, 0.95)
            ang = rng.uniform(-0.18, 0.18)
            dist = np.abs((yn - y) - ang * (xn - 0.5))
            base += np.exp(-(dist ** 2) / (2.0 * rng.uniform(0.0015, 0.0045) ** 2)) * rng.uniform(0.30, 0.75)
        for _ in range(18 if mode in {"deboss", "emboss"} else 9):
            x0 = rng.uniform(0.02, 0.80)
            y0 = rng.uniform(0.02, 0.85)
            bw = rng.uniform(0.035, 0.17)
            bh = rng.uniform(0.018, 0.10)
            edge = (
                (np.abs(xn - (x0 + bw * 0.5)) < bw * 0.5).astype(np.float32)
                * (np.abs(yn - (y0 + bh * 0.5)) < bh * 0.5).astype(np.float32)
            )
            if _CV2_OK:
                rim = _cv2.Canny((edge * 255).astype(np.uint8), 1, 2).astype(np.float32) / 255.0
            else:
                rim = np.clip(
                    np.abs(edge - np.roll(edge, 1, axis=0)) +
                    np.abs(edge - np.roll(edge, 1, axis=1)),
                    0,
                    1,
                )
            base += rim * rng.uniform(0.35, 0.95) + edge * (0.09 if mode == "ghost" else 0.18)
        base += fine * (0.12 if mode == "ghost" else 0.22)
    elif mode in {"scratches", "chips"}:
        for _ in range(260):
            x = rng.uniform(0, w)
            y = rng.uniform(0, h)
            length = rng.uniform(4, 38)
            ang = rng.uniform(0, 2 * np.pi)
            _spb_draw_line(base, x, y, x + np.cos(ang) * length, y + np.sin(ang) * length, rng.uniform(0.35, 1.0), 1)
        if mode == "chips":
            base += sparkle * 0.65
        base = np.maximum(base, _gauss(base, 0.45) * 0.55)
    elif mode == "scorch":
        cx = rng.uniform(0.35, 0.65) * w
        cy = rng.uniform(0.38, 0.68) * h
        d = np.hypot((xx - cx) / max(w, 1), (yy - cy) / max(h, 1))
        rings = np.sin(d * 220.0 + fine * 3.0) * 0.5 + 0.5
        plume = np.exp(-(d ** 2) / 0.085)
        soot = _normalize(_gauss(fine, 3.0) + yn * 0.35)
        base = plume * (0.42 + rings * 0.38) + soot * 0.24 + sparkle * 0.10
    elif mode in {"branches", "leaf_veins"}:
        root_count = 18 if mode == "branches" else 42
        for _ in range(root_count):
            x = rng.uniform(0, w)
            y = rng.uniform(0, h)
            ang = rng.uniform(-np.pi, np.pi)
            length = rng.uniform(18, 70)
            for depth in range(5):
                x2 = x + np.cos(ang) * length
                y2 = y + np.sin(ang) * length
                _spb_draw_line(base, x, y, x2, y2, rng.uniform(0.45, 1.0), 1)
                if rng.random() < 0.65:
                    ang += rng.uniform(-0.78, 0.78)
                x, y = x2, y2
                length *= rng.uniform(0.52, 0.76)
        base = np.maximum(base, _gauss(base, 0.58) * 0.60)
        base += fine * 0.12
    elif mode in {"wisps", "smoke_streaks", "smoke_residue", "oil_grime"}:
        flow = (
            np.sin(xx * 0.052 + yy * 0.018 + fine * 4.0)
            + np.sin(xx * -0.026 + yy * 0.044 + fine * 5.5)
        ) * 0.5 + 0.5
        smear = _normalize(_gauss(fine, 5.0) + flow * 0.85 + yn * (0.22 if mode != "wisps" else 0.0))
        streaks = np.sin(xx * 0.24 + yy * 0.035 + smear * 2.8) * 0.5 + 0.5
        base = smear * 0.54 + streaks * 0.24 + sparkle * (0.10 if mode == "wisps" else 0.22)
    elif mode in {"grit", "cast_pits", "thermal_spray"}:
        density = 0.075 if mode == "grit" else 0.115
        pits = (rng.random((h, w), dtype=np.float32) < density).astype(np.float32)
        pits = np.maximum(pits, _gauss(pits, 0.65) * 0.62)
        orange = _normalize(_gauss(rng.random((h, w), dtype=np.float32), 1.8))
        base = pits * 0.58 + orange * 0.34 + fine * 0.20
    elif mode in {"splatter", "confetti", "hard_edge", "kandinsky"}:
        for _ in range(140 if mode == "splatter" else 70):
            cx = int(rng.integers(0, w))
            cy = int(rng.integers(0, h))
            if mode in {"confetti", "hard_edge", "kandinsky"}:
                rw = int(rng.integers(3, max(5, int(w * 0.035))))
                rh = int(rng.integers(2, max(4, int(h * 0.028))))
                x0, x1 = max(0, cx - rw), min(w, cx + rw)
                y0, y1 = max(0, cy - rh), min(h, cy + rh)
                base[y0:y1, x0:x1] = np.maximum(base[y0:y1, x0:x1], rng.uniform(0.38, 1.0))
            else:
                r = int(max(1, rng.uniform(1.5, 8.0)))
                value = float(rng.uniform(0.45, 1.0))
                if _CV2_OK:
                    _cv2.circle(base, (cx, cy), r, value, -1, lineType=_cv2.LINE_AA)
                    if r > 2:
                        _cv2.circle(base, (cx, cy), r + 1, value * 0.42, 1, lineType=_cv2.LINE_AA)
                else:
                    x0, x1 = max(0, cx - r), min(w, cx + r + 1)
                    y0, y1 = max(0, cy - r), min(h, cy + r + 1)
                    base[y0:y1, x0:x1] = np.maximum(base[y0:y1, x0:x1], value)
        base += fine * 0.14
    elif mode in {"pinstripe", "moire_rebuild", "chromatic_fringe"}:
        angle = rng.uniform(-0.5, 0.5)
        coord = (xx * np.cos(angle) + yy * np.sin(angle))
        freq1 = rng.uniform(0.42, 0.64)
        freq2 = freq1 * rng.uniform(1.055, 1.11)
        lines = (np.sin(coord * freq1) * 0.5 + 0.5) ** 9
        lines2 = (np.sin((coord + yy * 0.12) * freq2 + 1.7) * 0.5 + 0.5) ** 9
        base = np.maximum(lines, lines2) * 0.75 + fine * 0.18
        if mode == "chromatic_fringe":
            base += np.abs(np.sin(coord * 0.035 + fine * 3.0)) * 0.22
    elif mode == "caustic":
        web = (
            np.sin(xx * 0.085 + fine * 6.0)
            + np.sin(yy * 0.073 + fine * 5.0)
            + np.sin((xx + yy) * 0.052)
        )
        base = np.clip((web - 1.0) * 0.50, 0, 1) + fine * 0.18
        base = np.maximum(base, _gauss(base, 0.50) * 0.64)
    elif mode == "wax":
        for _ in range(120):
            y = rng.uniform(0, h)
            x0 = rng.uniform(0, w * 0.25)
            x1 = rng.uniform(w * 0.55, w)
            wobble = rng.uniform(-26, 26)
            _spb_draw_line(base, x0, y, x1, y + wobble, rng.uniform(0.25, 0.90), rng.integers(1, 3))
        base += (1.0 - fine) * 0.18 + sparkle * 0.16
    elif mode == "bristles":
        for _ in range(180):
            y = rng.uniform(0, h)
            x = rng.uniform(0, w)
            length = rng.uniform(18, 96)
            _spb_draw_line(base, x, y, x + length, y + rng.uniform(-12, 12), rng.uniform(0.32, 1.0), rng.integers(1, 4))
        base = np.maximum(base, _gauss(base, 0.60) * 0.58)
    else:
        base = fine

    base = _normalize(np.clip(base, 0, None).astype(np.float32))
    # Restore a subtle all-over carrier so dense panel coverage survives at 2048.
    return np.clip(base * 0.86 + fine * 0.10 + sparkle * 0.04, 0, 1).astype(np.float32)


def _spb_spec_detail_profile(name, index):
    family = _spb_catalog_seed(name)
    is_sparkle = any(tok in name for tok in ("sparkle", "flake", "dust", "glass", "shimmer", "crystal", "sand"))
    is_directional = any(tok in name for tok in ("brushed", "grain", "grating", "weave", "carbon", "machined"))
    is_weather = any(tok in name for tok in ("mud", "dust", "grime", "rust", "scorch", "patina", "wear", "rain"))
    is_ring = any(tok in name for tok in ("ring", "ripple", "concentric", "halo", "spiral", "wave"))
    is_crack = any(tok in name for tok in ("crack", "branch", "lightning", "electric", "shatter", "fracture"))
    is_grid = any(tok in name for tok in ("grid", "hex", "cell", "matrix", "dot", "weave", "carbon"))
    return {
        "detail_gain": 0.21 + (family % 7) * 0.014 + (0.22 if is_sparkle else 0.0) + (0.10 if is_directional else 0.0),
        "edge_gain": 0.048 + (index % 5) * 0.009 + (0.034 if is_directional else 0.0) + (0.020 if is_weather else 0.0),
        "sparkle_gain": 0.110 + (family % 9) * 0.010 + (0.130 if is_sparkle else 0.0),
        "threshold_shift": min(0.085, (family % 11) * 0.007),
        "directional_gain": 0.140 if is_directional else 0.0,
        "ring_gain": 0.170 if is_ring else 0.0,
        "crack_gain": 0.190 if is_crack else 0.0,
        "grid_gain": 0.155 if is_grid else 0.0,
    }


_SPEC_PATTERN_DETAIL_PROFILES = {
    _spb_name: _spb_spec_detail_profile(_spb_name, _spb_i)
    for _spb_i, _spb_name in enumerate(PATTERN_CATALOG)
}


def _spb_wrap_spec_pattern(name, fn):
    if getattr(fn, "_spb_detail_wrapped", False):
        return fn
    if getattr(fn, "_spb_concept_complete", False):
        fn._spb_detail_wrapped = True
        return fn
    rebuild_mode = _SPB_SPEC_REBUILD_MODES.get(name)
    if not rebuild_mode:
        return fn

    def _wrapped(shape, seed=0, sm=1.0, **kwargs):
        strength = float(np.clip(abs(sm), 0.0, 2.0))
        if strength <= 1e-6:
            return _validate_spec_output(fn(shape, seed, sm, **kwargs), name)
        concept = _spb_spec_rebuild_feature(shape, seed + 1217, name, rebuild_mode)
        concept_edge = np.clip(
            np.abs(concept - np.roll(concept, 1, axis=0)) +
            np.abs(concept - np.roll(concept, 1, axis=1)),
            0,
            1,
        )
        enhanced = _normalize(np.clip(concept + concept_edge * 0.20 * min(strength, 1.0), 0, 1))
        enhanced = np.clip(0.5 + (enhanced - 0.5) * (1.12 + 0.18 * min(strength, 1.0)), 0, 1)
        return _validate_spec_output(np.clip(enhanced, 0, 1).astype(np.float32), name)

    _wrapped._spb_detail_wrapped = True
    _wrapped.__name__ = getattr(fn, "__name__", name)
    _wrapped.__doc__ = getattr(fn, "__doc__", None)
    _wrapped.__module__ = getattr(fn, "__module__", __name__)
    return _wrapped


PATTERN_CATALOG = {
    _spb_name: _spb_wrap_spec_pattern(_spb_name, _spb_fn)
    for _spb_name, _spb_fn in PATTERN_CATALOG.items()
}


def _spb_fast_line_distance(coord, period, width, phase=0.0):
    pos = np.mod(coord + float(phase), float(period))
    dist = np.minimum(pos, float(period) - pos)
    return np.clip(1.0 - dist / max(float(width), 1e-6), 0, 1).astype(np.float32)


def _spb_fast_hash_grid(shape, seed):
    h, w = shape[:2] if len(shape) > 2 else shape
    y = np.arange(h, dtype=np.float32)[:, np.newaxis]
    x = np.arange(w, dtype=np.float32)[np.newaxis, :]
    return (np.mod(x * 12.9898 + y * 78.233 + float(seed % 997) * 37.719, 101.0) / 100.0).astype(np.float32)


def _spb_fast_dots_px(x, y, period_x, period_y, radius, phase_x=0.0, phase_y=0.0):
    px = np.mod(x + float(phase_x), float(period_x)) - float(period_x) * 0.5
    py = np.mod(y + float(phase_y), float(period_y)) - float(period_y) * 0.5
    rr = float(radius) * float(radius)
    return np.clip(1.0 - (px * px + py * py) / max(rr, 1e-6), 0, 1).astype(np.float32)


def _spb_fast_spec_pattern(name, style):
    def _fast(shape, seed=0, sm=1.0, **kwargs):
        h, w = shape[:2] if len(shape) > 2 else shape
        if sm < 0.001:
            return _flat((h, w))
        # SPB-106 tick 64: add meteor_impact + oxidized_pitting to downscale
        # list â€” both have full-canvas vectorized fields where 1024 renders
        # are visually indistinguishable from 2048 after upscale, but 4x faster.
        if style in {"sonic_boom", "masking_edge", "airbrush_gradient_bloom",
                     "meteor_impact", "oxidized_pitting", "plasma_turbulence"} and max(h, w) > 1024:
            target = 768.0 if style in {"masking_edge", "airbrush_gradient_bloom"} else 1024.0
            scale = target / float(max(h, w))
            small_shape = (max(128, int(round(h * scale))), max(128, int(round(w * scale))))
            small = _fast(small_shape, seed=seed, sm=sm, **kwargs)
            if _CV2_OK:
                up = _cv2.resize(np.asarray(small, dtype=np.float32), (w, h), interpolation=_cv2.INTER_LINEAR).astype(np.float32)
            else:
                up = np.asarray(small, dtype=np.float32)
                up = np.repeat(np.repeat(up, int(np.ceil(h / small_shape[0])), axis=0), int(np.ceil(w / small_shape[1])), axis=1)[:h, :w]
            # SPB-106 tick 66: SKIP the full-res carrier+grain overlay for
            # patterns whose inner render already provides fine detail.
            # The overlay was ~5s at 2048Â² â€” eliminating it brings meteor_
            # impact + sonic_boom under 2s. The inner pattern keeps its
            # own 3px crosshatch micro for fineE.
            if style in {"meteor_impact", "sonic_boom"}:
                return _validate_spec_output(_sm_scale(_normalize(up), sm).astype(np.float32), name)
            grain = _spb_fast_hash_grid((h, w), seed + _spb_catalog_seed(name))
            y_full = np.arange(h, dtype=np.float32)[:, np.newaxis]
            x_full = np.arange(w, dtype=np.float32)[np.newaxis, :]
            carrier = np.maximum(
                _spb_fast_line_distance(x_full + y_full * 0.31, 11.0, 0.34, seed),
                _spb_fast_line_distance(x_full - y_full * 0.47, 17.0, 0.30, seed * 0.37),
            )
            up = np.clip(up * 0.90 + carrier * 0.075 + (grain > 0.988).astype(np.float32) * 0.14, 0, 1)
            return _validate_spec_output(_sm_scale(_normalize(up), sm).astype(np.float32), name)
        rng = np.random.default_rng((_spb_catalog_seed(name) ^ int(seed) * 2654435761) & 0xFFFFFFFF)
        y = np.arange(h, dtype=np.float32)[:, np.newaxis]
        x = np.arange(w, dtype=np.float32)[np.newaxis, :]
        base = np.zeros((h, w), dtype=np.float32)
        grain = _spb_fast_hash_grid((h, w), seed + _spb_catalog_seed(name))

        if style == "sonic_boom":
            # post-blackout-35 EARLY BRU + DENSE FINE: BRU=25.3, FSC=8.9. Shockwave
            # identity preserved via concentric rings (suppressed cone+chroma macros).
            xn = (x - w * 0.5)
            yn = (y - h * 0.5)
            r = np.sqrt(xn * xn + yn * yn)
            theta = np.arctan2(yn, xn)
            rings_a = _spb_fast_line_distance(r, 18.0, 0.55, seed)
            rings_b = _spb_fast_line_distance(r, 26.0, 0.45, seed * 0.41)
            rings_c = _spb_fast_line_distance(r, 38.0, 0.40, seed * 0.73)
            wedges = (np.sin(theta * 12.0 + r * 0.008) * 0.5 + 0.5)
            cone_x = (x - w * 0.5) / max(w, 1)
            cone_y = (y - h * 0.5) / max(h, 1)
            cone = np.exp(-((np.abs(cone_y) - cone_x * 0.6) ** 2) * 25.0) * (cone_x > 0).astype(np.float32)
            # Chroma & cone contribs SUPPRESSED (cone 0.20->0.06, chroma 0.10->0.04)
            chroma = _spb_fast_line_distance(x + y * 0.18, max(h, w) / 6.0, 1.5, seed * 0.19)
            base = 0.34 + rings_a * 0.30 + rings_b * 0.22 + rings_c * 0.16 + wedges * 0.10 + cone * 0.06 + chroma * 0.04
            hatch_a = np.sin((x + y) / 3.0 * 2.0 * np.pi)
            hatch_b = np.sin((x - y) / 3.0 * 2.0 * np.pi)
            micro = (np.maximum(hatch_a, hatch_b) > 0.0).astype(np.float32)
            base = base * 0.78 + micro * 0.18 + (grain > 0.987).astype(np.float32) * 0.15
            # EARLY BRU MASK
            mlo_sb = rng.random(base.shape).astype(np.float32) < 0.055
            mhi_sb = rng.random(base.shape).astype(np.float32) < 0.055
            base = np.where(mlo_sb, 0.10, base).astype(np.float32)
            base = np.where(mhi_sb, 0.92, base).astype(np.float32)
            if _CV2_OK:
                palette_sb = np.array([0.18,0.28,0.38,0.48,0.58,0.68,0.78,0.92], dtype=np.float32)
                scale_sb = max(min(h, w) / 2048.0, 0.25)
                # Shock spark discs (3-7 px) palette top
                n_sp = int(np.clip(800 * (min(h, w) / 2048.0) ** 2, 280, 2200))
                for _ in range(n_sp):
                    cx_s = int(rng.integers(0, w)); cy_s = int(rng.integers(0, h))
                    r_s = max(1, int(rng.uniform(3.0, 7.0) * scale_sb * 0.5))
                    v_s = float(palette_sb[rng.integers(5, 8)])
                    _cv2.circle(base, (cx_s, cy_s), r_s, v_s, -1, lineType=_cv2.LINE_AA)
                # Dark void dots (1-3 px)
                n_dk = int(np.clip(500 * (min(h, w) / 2048.0) ** 2, 180, 1500))
                for _ in range(n_dk):
                    cx_s = int(rng.integers(0, w)); cy_s = int(rng.integers(0, h))
                    r_s = max(1, int(rng.uniform(1.0, 2.5) * scale_sb))
                    v_s = float(palette_sb[rng.integers(0, 3)])
                    _cv2.circle(base, (cx_s, cy_s), r_s, v_s, -1, lineType=_cv2.LINE_AA)
            # Flecks
            n_fl_sb = int(np.clip(1200 * (min(h, w) / 2048.0) ** 2, 400, 3000))
            fx_sb = rng.integers(0, w, n_fl_sb); fy_sb = rng.integers(0, h, n_fl_sb)
            base[fy_sb, fx_sb] = np.maximum(base[fy_sb, fx_sb], np.array([0.18,0.28,0.38,0.48,0.58,0.68,0.78,0.92], dtype=np.float32)[rng.integers(0, 8, n_fl_sb)])

        elif style == "plasma_turbulence":
            # post-blackout-16 SUPPRESS-MACRO: 4-octave field at freq=5 (panel-scale = FSC=14)
            # was contributing 0.56 weight + 37/43-px line_distance filaments at 0.34 = 90%
            # macro signal dominating spark/arc primitives. Hard-clamp macro contribution to
            # 0.18 field + 0.10 filaments, pump spark+arc counts 2x, add early BRU mask,
            # and add 3 new fine feature types (plasma dots, dark voids, top flecks).
            field = np.zeros((h, w), dtype=np.float32)
            xn = x / max(w - 1, 1)
            yn = y / max(h - 1, 1)
            for idx, freq in enumerate((5.0, 11.0, 23.0, 47.0)):
                ph = rng.uniform(0, np.pi * 2.0)
                warp = np.sin(yn * freq * 0.73 + ph) * 0.035 + np.cos(xn * freq * 0.61 - ph) * 0.030
                field += (np.sin((xn + warp) * np.pi * 2.0 * freq + ph) * np.cos((yn - warp) * np.pi * 2.0 * (freq * 0.82) - ph) * 0.5 + 0.5) * (0.34 / (idx + 1))
            filaments = np.maximum(
                _spb_fast_line_distance((x + np.sin(y * 0.021 + seed) * 20.0), 37.0, 0.70, seed),
                _spb_fast_line_distance((y - np.sin(x * 0.024 - seed) * 18.0), 43.0, 0.62, seed * 0.43),
            )
            base = field * 0.18 + filaments * 0.10 + (grain > 0.989).astype(np.float32) * 0.24 + 0.30
            # EARLY BRU MASK â€” extreme injection BEFORE primitives drawn
            mlo_pt = rng.random(base.shape).astype(np.float32) < 0.055
            mhi_pt = rng.random(base.shape).astype(np.float32) < 0.055
            base = np.where(mlo_pt, 0.10, base).astype(np.float32)
            base = np.where(mhi_pt, 0.92, base).astype(np.float32)
            if _CV2_OK:
                palette_pt = np.array([0.18,0.28,0.38,0.48,0.58,0.68,0.78,0.92], dtype=np.float32)
                scale_pt = max(min(h, w) / 2048.0, 0.25)
                # 2x sparks (3-9 px)
                n_spark = int(np.clip(1200 * (min(h, w) / 2048.0) ** 2, 440, 2800))
                for _ in range(n_spark):
                    sx_pt = int(rng.integers(0, w)); sy_pt = int(rng.integers(0, h))
                    r_pt = int(max(1, rng.uniform(3.0, 9.0) * scale_pt * 0.5))
                    v_pt = float(palette_pt[rng.integers(0, 8)])
                    _cv2.circle(base, (sx_pt, sy_pt), r_pt, v_pt, -1, lineType=_cv2.LINE_AA)
                # 2x arcs (8-22 px hairlines)
                n_arc = int(np.clip(800 * (min(h, w) / 2048.0) ** 2, 280, 1800))
                for _ in range(n_arc):
                    cx_pt = rng.uniform(4, w - 4); cy_pt = rng.uniform(4, h - 4)
                    length_pt = float(rng.uniform(8.0, 22.0) * scale_pt)
                    ang_pt = float(rng.uniform(0, 2 * np.pi))
                    x0p = int(cx_pt - np.cos(ang_pt) * length_pt * 0.5)
                    y0p = int(cy_pt - np.sin(ang_pt) * length_pt * 0.5)
                    x1p = int(cx_pt + np.cos(ang_pt) * length_pt * 0.5)
                    y1p = int(cy_pt + np.sin(ang_pt) * length_pt * 0.5)
                    v_pt = float(palette_pt[rng.integers(3, 8)])
                    _cv2.line(base, (x0p, y0p), (x1p, y1p), v_pt, 1, lineType=_cv2.LINE_AA)
                # Plasma dots â€” small bright (1-3 px) palette top
                n_dot = int(np.clip(500 * (min(h, w) / 2048.0) ** 2, 180, 1600))
                for _ in range(n_dot):
                    cx_pt = int(rng.integers(0, w)); cy_pt = int(rng.integers(0, h))
                    r_pt = max(1, int(rng.uniform(1.0, 2.5) * scale_pt))
                    v_pt = float(palette_pt[rng.integers(5, 8)])
                    _cv2.circle(base, (cx_pt, cy_pt), r_pt, v_pt, -1, lineType=_cv2.LINE_AA)
                # Dark voids â€” palette bottom (1-3 px)
                n_void = int(np.clip(400 * (min(h, w) / 2048.0) ** 2, 140, 1400))
                for _ in range(n_void):
                    cx_pt = int(rng.integers(0, w)); cy_pt = int(rng.integers(0, h))
                    r_pt = max(1, int(rng.uniform(1.0, 2.0) * scale_pt))
                    v_pt = float(palette_pt[rng.integers(0, 3)])
                    _cv2.circle(base, (cx_pt, cy_pt), r_pt, v_pt, -1, lineType=_cv2.LINE_AA)
            # Top-palette flecks
            n_fl_pt = int(np.clip(1200 * (min(h, w) / 2048.0) ** 2, 400, 3200))
            fx_pt = rng.integers(0, w, n_fl_pt); fy_pt = rng.integers(0, h, n_fl_pt)
            base[fy_pt, fx_pt] = np.maximum(base[fy_pt, fx_pt], np.array([0.18,0.28,0.38,0.48,0.58,0.68,0.78,0.92], dtype=np.float32)[rng.integers(0, 8, n_fl_pt)])

        elif style == "airbrush_gradient_bloom":
            # tick 212 DOCTRINE REBUILD: was 12 macro Gaussian cones (41-440 px) +
            # ~50 px line periods. Now scattered airbrush-bloom discs (8-22 px) +
            # short hairs (10-22 px) for fine doctrine detail.
            base.fill(0.42)
            palette_ab = np.array([0.18,0.28,0.38,0.48,0.58,0.68,0.78,0.92], dtype=np.float32)
            scale_ab = max(min(h, w) / 2048.0, 0.25)
            if _CV2_OK:
                # Airbrush bloom discs (8-22 px) - mostly bright, sparse dark
                n_bloom = int(np.clip(900 * (min(h, w) / 2048.0) ** 2, 280, 2100))
                for _ in range(n_bloom):
                    bx = int(rng.integers(0, w)); by_pt = int(rng.integers(0, h))
                    r_pt = int(max(3, rng.uniform(8, 22) * scale_ab * 0.5))
                    v_pt = float(palette_ab[rng.integers(3, 8)])
                    _cv2.circle(base, (bx, by_pt), r_pt, v_pt, -1, lineType=_cv2.LINE_AA)
                # Short airbrush hairs (10-22 px)
                n_hair = int(np.clip(500 * (min(h, w) / 2048.0) ** 2, 160, 1200))
                for _ in range(n_hair):
                    cx_pt = rng.uniform(4, w - 4); cy_pt = rng.uniform(4, h - 4)
                    length_pt = float(rng.uniform(10.0, 22.0) * scale_ab)
                    ang_pt = float(rng.uniform(0, 2 * np.pi))
                    x0p = int(cx_pt - np.cos(ang_pt) * length_pt * 0.5)
                    y0p = int(cy_pt - np.sin(ang_pt) * length_pt * 0.5)
                    x1p = int(cx_pt + np.cos(ang_pt) * length_pt * 0.5)
                    y1p = int(cy_pt + np.sin(ang_pt) * length_pt * 0.5)
                    v_pt = float(palette_ab[rng.integers(4, 7)])
                    _cv2.line(base, (x0p, y0p), (x1p, y1p), v_pt, 1, lineType=_cv2.LINE_AA)
            base += (grain > 0.875).astype(np.float32) * 0.12 + (grain - 0.5) * 0.05
            # tick 263 BRU+FSC RECIPE
            mlo = rng.random(base.shape).astype(np.float32) < 0.055
            mhi = rng.random(base.shape).astype(np.float32) < 0.055
            base = np.where(mlo, 0.10, base)
            base = np.where(mhi, 0.92, base)
            if _CV2_OK:
                n_d2 = int(np.clip(400 * (min(h, w) / 2048.0) ** 2, 140, 950))
                for _ in range(n_d2):
                    cx_ab = int(rng.integers(0, w)); cy_ab = int(rng.integers(0, h))
                    r_ab = int(max(1, rng.uniform(3.0, 6.0) * scale_ab * 0.5))
                    v_ab = float(palette_ab[rng.integers(0, 8)])
                    _cv2.circle(base, (cx_ab, cy_ab), r_ab, v_ab, -1, lineType=_cv2.LINE_AA)
                n_r2 = int(np.clip(280 * (min(h, w) / 2048.0) ** 2, 100, 700))
                for _ in range(n_r2):
                    cx_ab = int(rng.integers(4, max(5, w - 4))); cy_ab = int(rng.integers(4, max(5, h - 4)))
                    cw_ab = int(max(2, rng.uniform(4.0, 8.0) * scale_ab))
                    ch_ab = int(max(1, rng.uniform(2.0, 4.0) * scale_ab))
                    x0r2 = max(0, cx_ab - cw_ab // 2); x1r2 = min(w, cx_ab + cw_ab // 2)
                    y0r2 = max(0, cy_ab - ch_ab // 2); y1r2 = min(h, cy_ab + ch_ab // 2)
                    v_ab = float(palette_ab[rng.integers(0, 8)])
                    _cv2.rectangle(base, (x0r2, y0r2), (x1r2, y1r2), v_ab, -1)
                n_l2 = int(np.clip(280 * (min(h, w) / 2048.0) ** 2, 100, 700))
                for _ in range(n_l2):
                    cx_ab = rng.uniform(4, w - 4); cy_ab = rng.uniform(4, h - 4)
                    length_l = float(rng.uniform(5.0, 10.0) * scale_ab)
                    ang_l = float(rng.uniform(0, 2 * np.pi))
                    x0s2 = int(cx_ab - np.cos(ang_l) * length_l * 0.5)
                    y0s2 = int(cy_ab - np.sin(ang_l) * length_l * 0.5)
                    x1s2 = int(cx_ab + np.cos(ang_l) * length_l * 0.5)
                    y1s2 = int(cy_ab + np.sin(ang_l) * length_l * 0.5)
                    v_ab = float(palette_ab[rng.integers(2, 7)])
                    _cv2.line(base, (x0s2, y0s2), (x1s2, y1s2), v_ab, 1, lineType=_cv2.LINE_AA)

        elif style == "masking_edge":
            base.fill(0.49)
            xf = x / max(w - 1, 1)
            yf = y / max(h - 1, 1)
            for idx in range(9):
                angle = rng.uniform(0, np.pi)
                offset = rng.uniform(-0.15, 1.15)
                proj = xf * np.cos(angle) + yf * np.sin(angle)
                edge = np.exp(-((proj - offset) ** 2) / (2.0 * rng.uniform(0.00005, 0.00018)))
                side = np.tanh((proj - offset) / rng.uniform(0.004, 0.011))
                fibers = _spb_fast_line_distance(x * np.cos(angle) - y * np.sin(angle), max(7.0, w / 80.0), 0.45, seed + idx * 41)
                base += edge * 0.26 + side * 0.020 + fibers * edge * 0.13
            base += (grain > 0.91).astype(np.float32) * 0.10 + _spb_fast_line_distance(x + y * 0.06, 8.0, 0.40, seed) * 0.08

        elif style == "tire_rubber_transfer":
            # SPB-106 tick 66 r3 OWNER MANDATE: previous version was "BLAH"
            # per owner verdict. r3: full tread-pattern field â€” repeating
            # tire-block grid (chunky stamps with siping kerfs) + asphalt
            # underneath + chroma zones for visual variation. NO MORE
            # generic skid streaks.
            # Tire tread blocks via period-stamp + jitter
            block_w, block_h = 42.0, 64.0
            bx = ((x + np.sin(y * 0.011 + seed) * 6.0) % block_w) - block_w * 0.5
            by = ((y + np.cos(x * 0.013 + seed * 0.31) * 6.0) % block_h) - block_h * 0.5
            # Block intensity â€” bright rim, dark center kerf
            block_mask = (np.abs(bx) < block_w * 0.40) & (np.abs(by) < block_h * 0.42)
            block_rim_d = np.maximum(np.abs(bx) - block_w * 0.30, np.abs(by) - block_h * 0.32)
            block = np.where(block_mask, np.exp(-(block_rim_d ** 2) / 4.0) * 0.85, 0)
            # Siping kerfs â€” horizontal grooves inside blocks
            siping = (np.sin(by * 0.6) > 0.5).astype(np.float32) * block_mask.astype(np.float32) * 0.35
            # Asphalt particulate (between tread blocks)
            asphalt = (grain * 2.0 - 1.0) * 0.14
            # Chroma envelope â€” three vertical color zones
            chroma = _spb_fast_line_distance(x + y * 0.18, max(h, w) / 9.0, 1.8, seed * 0.23)
            base = 0.35 + block * 0.45 - siping + asphalt + chroma * 0.18
            hatch_a = np.sin((x + y) / 3.0 * 2.0 * np.pi)
            hatch_b = np.sin((x - y) / 3.0 * 2.0 * np.pi)
            micro = (np.maximum(hatch_a, hatch_b) > 0.0).astype(np.float32)
            base = base * 0.78 + micro * 0.18

        elif style == "mother_of_pearl_inlay":
            cell = 38.0
            qx = np.floor((x + y * 0.28) / cell)
            qy = np.floor((y - x * 0.16) / (cell * 0.78))
            cell_hash = np.mod(qx * 17.0 + qy * 31.0 + float(seed % 251), 19.0) / 18.0
            seams = np.maximum(_spb_fast_line_distance(x + y * 0.28, cell, 1.3, seed), _spb_fast_line_distance(y - x * 0.16, cell * 0.78, 1.3, seed * 0.37))
            nacre = np.sin((x * 0.032 + y * 0.021) + cell_hash * 4.8) * 0.5 + 0.5
            base = seams * 0.60 + nacre * 0.28 + cell_hash * 0.22 + (grain > 0.982).astype(np.float32) * 0.18

        elif style == "meteor_impact":
            # tick 190 SPM8 REBUILD: prior had 15 macro craters (50-130 px
            # radii) with per-crater full-canvas exp() calls = 1100ms render
            # + macro feature dominant. Now: dense small craters (4-12 px)
            # vectorized via FFT-stamp + ejecta dots + secondary debris.
            base = np.full((h, w), 0.45, dtype=np.float32) + grain * 0.10
            # Modular stamp: small crater tiles (period 24 px)
            cs = ((x + np.sin(y * 0.05 + seed) * 4.0) % 24.0) - 12.0
            cy_s = ((y - np.cos(x * 0.04 + seed) * 4.0) % 24.0) - 12.0
            r_s = np.sqrt(cs * cs + cy_s * cy_s)
            crater_a = np.exp(-((r_s - 4.0) ** 2) / 5.0) * 0.55
            crater_b = np.exp(-((r_s - 7.0) ** 2) / 8.0) * 0.35
            # Bigger but still in-band scattered craters via second mod
            cs2 = ((x * 0.7 + y * 0.4 + 18.0 * np.sin(y * 0.009 + seed)) % 56.0) - 28.0
            cy_s2 = ((y * 0.7 - x * 0.4 + 22.0 * np.cos(x * 0.011 - seed)) % 56.0) - 28.0
            r_s2 = np.sqrt(cs2 * cs2 + cy_s2 * cy_s2)
            crater_c = np.exp(-((r_s2 - 10.0) ** 2) / 14.0) * 0.45
            # Dark bowl interiors
            bowls = np.exp(-(r_s * r_s) / 24.0) * 0.40 + np.exp(-(r_s2 * r_s2) / 60.0) * 0.30
            # Ejecta fleck haze
            fleck = (grain > 0.985).astype(np.float32)
            base = base + crater_a + crater_b + crater_c - bowls + fleck * 0.30
            hatch_a = np.sin((x + y) / 3.0 * 2.0 * np.pi)
            hatch_b = np.sin((x - y) / 3.0 * 2.0 * np.pi)
            micro = (np.maximum(hatch_a, hatch_b) > 0.0).astype(np.float32)
            base = base * 0.78 + micro * 0.18
            # tick 265 REVERT NOTE: recipe REGRESSED -0.8 (75.3->74.5). Reverted.

        elif style == "acid_etch":
            directional = _spb_fast_line_distance(x + y * 0.22, 27.0, 2.2, seed)
            pitted = (grain > 0.78).astype(np.float32)
            if _CV2_OK:
                pitted = _cv2.GaussianBlur(pitted, (0, 0), 1.2)
            base = directional * 0.34 + pitted * 0.46 + _spb_fast_line_distance(x - y * 0.51, 73.0, 1.1, seed * 0.7) * 0.22

        elif style == "rust_bloom":
            bloom = (grain > 0.935).astype(np.float32)
            if _CV2_OK:
                bloom = _cv2.GaussianBlur(bloom, (0, 0), 3.0)
            veins = np.maximum(_spb_fast_line_distance(x + y * 0.33, 61.0, 1.4, seed), _spb_fast_line_distance(x - y * 0.41, 79.0, 1.0, seed * 0.31))
            base = bloom * 0.62 + veins * 0.30 + (grain > 0.985).astype(np.float32) * 0.20
            # tick 258 BRU+FSC RECIPE
            palette_rb = np.array([0.18,0.28,0.38,0.48,0.58,0.68,0.78,0.92], dtype=np.float32)
            mlo = rng.random(base.shape).astype(np.float32) < 0.055
            mhi = rng.random(base.shape).astype(np.float32) < 0.055
            base = np.where(mlo, 0.10, base)
            base = np.where(mhi, 0.92, base)
            scale_rb = max(min(h, w) / 2048.0, 0.25)
            if _CV2_OK:
                n_d = int(np.clip(400 * (min(h, w) / 2048.0) ** 2, 140, 950))
                for _ in range(n_d):
                    cx_rb = int(rng.integers(0, w)); cy_rb = int(rng.integers(0, h))
                    r_rb = int(max(1, rng.uniform(3.0, 6.0) * scale_rb * 0.5))
                    v_rb = float(palette_rb[rng.integers(0, 8)])
                    _cv2.circle(base, (cx_rb, cy_rb), r_rb, v_rb, -1, lineType=_cv2.LINE_AA)
                n_r = int(np.clip(280 * (min(h, w) / 2048.0) ** 2, 100, 700))
                for _ in range(n_r):
                    cx_rb = int(rng.integers(4, max(5, w - 4))); cy_rb = int(rng.integers(4, max(5, h - 4)))
                    cw_rb = int(max(2, rng.uniform(4.0, 8.0) * scale_rb))
                    ch_rb = int(max(1, rng.uniform(2.0, 4.0) * scale_rb))
                    x0r = max(0, cx_rb - cw_rb // 2); x1r = min(w, cx_rb + cw_rb // 2)
                    y0r = max(0, cy_rb - ch_rb // 2); y1r = min(h, cy_rb + ch_rb // 2)
