                    x0l = int(cx_ll - np.cos(ang_ll) * length_ll * 0.5)
                    y0l = int(cy_ll - np.sin(ang_ll) * length_ll * 0.5)
                    x1l = int(cx_ll + np.cos(ang_ll) * length_ll * 0.5)
