            weft = _spb_fast_line_distance(y - np.sin(x * 0.019 - seed) * 3.0, 12.0, 1.4, seed * 0.37)
            rip = _spb_fast_line_distance(x + y * 0.18, 5.0, 0.34, seed * 0.13)
            base = 0.36 + np.maximum(warp, weft) * 0.46 + np.minimum(warp, weft) * 0.16 + rip * 0.12 + grain * 0.04

