# === SPB SPEC OVERLAY PURGE REWORK 2026-05-29 START ===
# Owner verdict: four purge REWORK picks had potential but were too noisy/soft.
# Rebuilds below keep the same public IDs and make the intended finish cleaner:
# sharp diagonal bands, crisp gold-leaf flakes, chopped fiberglass strands, and
# distinct dew beads without generic speckle haze.

def purge_rework_diagonal_bands(shape, seed, sm, **kwargs):
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 529101)
    scale = max(min(h, w) / 2048.0, 0.25)
    yy = np.arange(h, dtype=np.float32)[:, None]
    xx = np.arange(w, dtype=np.float32)[None, :]
    ang = np.deg2rad(43.0)
    u = xx * float(np.cos(ang)) + yy * float(np.sin(ang))
    pitch = max(14.0 * scale, 5.0)
    phase = (u / pitch) % 1.0
    band = (phase < 0.48).astype(np.float32)
    edge = np.minimum(phase, 1.0 - phase)
    pin = (edge < 0.055).astype(np.float32)
    band_index = np.floor(u / pitch).astype(np.int32)
    table = 512
    jitter_m = rng.uniform(-0.10, 0.16, table).astype(np.float32)
    jitter_r = rng.uniform(-0.08, 0.10, table).astype(np.float32)
    jitter_c = rng.uniform(-0.12, 0.18, table).astype(np.float32)
    idx = ((band_index.astype(np.int64) * 1103515245 + int(seed)) & (table - 1)).astype(np.int32)

    base = _normalize(multi_scale_noise(shape, [7.0, 18.0], [0.65, 0.35], int(seed) + 91))
    M = (0.18 + base * 0.10 + band * (0.34 + jitter_m[idx]) + pin * 0.26).astype(np.float32)
    R = (0.54 - band * (0.24 + jitter_r[idx]) + pin * 0.18).astype(np.float32)
    CC = (0.34 + band * (0.34 + jitter_c[idx]) + pin * 0.22).astype(np.float32)

    if _CV2_OK:
        # Sparse, sharp cut marks along the diagonal tape; no random haze carpet.
        for _ in range(int(np.clip(420 * (min(h, w) / 512.0) ** 2, 160, 1600))):
            cx = float(rng.uniform(0, w))
            cy = float(rng.uniform(0, h))
            length = float(rng.uniform(8.0, 22.0) * scale)
            a = ang + float(rng.normal(0, 0.08))
            x0 = int(cx - np.cos(a) * length * 0.5)
            y0 = int(cy - np.sin(a) * length * 0.5)
            x1 = int(cx + np.cos(a) * length * 0.5)
            y1 = int(cy + np.sin(a) * length * 0.5)
            _cv2.line(M, (x0, y0), (x1, y1), float(rng.uniform(0.66, 0.96)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(R, (x0, y0), (x1, y1), float(rng.uniform(0.10, 0.28)), 1, lineType=_cv2.LINE_AA)
            _cv2.line(CC, (x0, y0), (x1, y1), float(rng.uniform(0.64, 0.94)), 1, lineType=_cv2.LINE_AA)

    out = np.stack([M, R, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)


def purge_rework_gold_flake(shape, seed, sm, **kwargs):
    # OWNER-REBUILD 2026-06-03: "low effort/lazy". Now DENSE varied-size
    # metallic gold flake with real sparkle: three flake size tiers (big
    # torn-leaf islands, mid platelets, fine grains) over a dark substrate,
    # each flake carrying its own warm gold tone (CC variation), bright
    # specular glint cores, and high-contrast 1-2 px sparkle pops so the
    # metallic flash actually reads on the car.
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 529102)
    scale = max(min(h, w) / 2048.0, 0.25)
    # Dark warm substrate so flakes POP (gold flake over a dark candy base).
    base = _normalize(multi_scale_noise(shape, [5.0, 13.0, 31.0], [0.45, 0.35, 0.20], int(seed) + 122))
    M = (0.14 + base * 0.10).astype(np.float32)
    R = (0.66 - base * 0.16).astype(np.float32)
    CC = (0.30 + base * 0.18).astype(np.float32)

    if _CV2_OK:
        # --- TIER 1: big torn gold-leaf islands (varied size) ---------------
        n_leaf = int(np.clip(1200 * (min(h, w) / 512.0) ** 2, 360, 4200))
        for _ in range(n_leaf):
            cx = int(rng.uniform(0, w)); cy = int(rng.uniform(0, h))
            sides = int(rng.integers(5, 9))
            radius = float(rng.uniform(4.0, 16.0) * scale)
            pts = []
            for k in range(sides):
                a = 2.0 * np.pi * k / sides + float(rng.uniform(-0.22, 0.22))
                r = radius * float(rng.uniform(0.55, 1.20))
                pts.append([int(cx + np.cos(a) * r), int(cy + np.sin(a) * r)])
            poly = np.asarray(pts, dtype=np.int32)
            gloss = float(rng.uniform(0.78, 0.99))            # bright metal face
            gold_cc = float(rng.uniform(0.30, 0.78))          # warm gold tone, varied
            _cv2.fillConvexPoly(M, poly, gloss, lineType=_cv2.LINE_AA)
            _cv2.fillConvexPoly(R, poly, float(rng.uniform(0.04, 0.22)), lineType=_cv2.LINE_AA)
            _cv2.fillConvexPoly(CC, poly, gold_cc, lineType=_cv2.LINE_AA)
            # dark torn-edge rim = facet definition
            _cv2.polylines(M, [poly], True, float(rng.uniform(0.06, 0.22)), 1, lineType=_cv2.LINE_AA)
            _cv2.polylines(R, [poly], True, float(rng.uniform(0.62, 0.90)), 1, lineType=_cv2.LINE_AA)
            # specular glint core on a fraction of leaves
            if rng.random() < 0.55:
                gx = int(cx + radius * 0.2); gy = int(cy - radius * 0.2)
                _cv2.circle(M, (gx, gy), max(1, int(radius * 0.30)), float(rng.uniform(0.94, 0.99)), -1, lineType=_cv2.LINE_AA)
                _cv2.circle(CC, (gx, gy), max(1, int(radius * 0.30)), float(rng.uniform(0.55, 0.95)), -1, lineType=_cv2.LINE_AA)

        # --- TIER 2: mid platelet flakes (dense) ---------------------------
        n_plate = int(np.clip(2600 * (min(h, w) / 512.0) ** 2, 800, 9000))
        for _ in range(n_plate):
            cx = int(rng.uniform(0, w)); cy = int(rng.uniform(0, h))
            r = max(1, int(rng.uniform(2.0, 6.0) * scale * 0.9))
            _cv2.circle(M, (cx, cy), r, float(rng.uniform(0.72, 0.98)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r, float(rng.uniform(0.05, 0.24)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r, float(rng.uniform(0.28, 0.82)), -1, lineType=_cv2.LINE_AA)

    # --- TIER 3: fine gold dust + bright SPARKLE pops ----------------------
    n_dust = int(np.clip(h * w / 120.0, 900, 18000))
    fy = rng.integers(0, h, n_dust); fx = rng.integers(0, w, n_dust)
    M[fy, fx] = np.maximum(M[fy, fx], rng.uniform(0.55, 0.92, n_dust).astype(np.float32))
    R[fy, fx] = np.minimum(R[fy, fx], rng.uniform(0.06, 0.28, n_dust).astype(np.float32))
    CC[fy, fx] = np.clip(0.30 + rng.uniform(0.0, 0.55, n_dust).astype(np.float32), 0, 1)
    # high-contrast sparkle: pure white specular hits scattered sparsely
    n_spark = int(np.clip(h * w / 900.0, 120, 3000))
    sy = rng.integers(0, h, n_spark); sx = rng.integers(0, w, n_spark)
    M[sy, sx] = 0.99
    R[sy, sx] = rng.uniform(0.02, 0.12, n_spark).astype(np.float32)
    CC[sy, sx] = rng.uniform(0.70, 0.99, n_spark).astype(np.float32)

    out = np.stack([np.clip(M, 0, 1), np.clip(R, 0, 1), np.clip(CC, 0, 1)], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)


def purge_rework_spec_fiberglass_chopped(shape, seed, sm, **kwargs):
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 529103)
    scale = max(min(h, w) / 2048.0, 0.25)
    resin = _normalize(multi_scale_noise(shape, [6.0, 18.0], [0.65, 0.35], int(seed) + 133))
    M = (0.28 + resin * 0.12).astype(np.float32)
    R = (0.56 - resin * 0.16).astype(np.float32)
    CC = (0.44 + resin * 0.20).astype(np.float32)

    if _CV2_OK:
        # Chopped-strand mat: clear glass fibers grouped in small bundles.
        n_bundles = int(np.clip(1500 * (min(h, w) / 512.0) ** 2, 520, 5600))
        for _ in range(n_bundles):
            cx = float(rng.uniform(0, w))
            cy = float(rng.uniform(0, h))
            a0 = float(rng.uniform(0, 2 * np.pi))
            length = float(rng.uniform(12.0, 30.0) * scale)
            fibers = int(rng.integers(3, 8))
            for _f in range(fibers):
                off = float(rng.uniform(-2.2, 2.2) * scale)
                a = a0 + float(rng.normal(0, 0.10))
                px = off * np.cos(a0 + np.pi / 2.0)
                py = off * np.sin(a0 + np.pi / 2.0)
                x0 = int(cx + px - np.cos(a) * length * 0.5)
                y0 = int(cy + py - np.sin(a) * length * 0.5)
                x1 = int(cx + px + np.cos(a) * length * 0.5)
                y1 = int(cy + py + np.sin(a) * length * 0.5)
                _cv2.line(M, (x0, y0), (x1, y1), float(rng.uniform(0.48, 0.92)), 1, lineType=_cv2.LINE_AA)
                _cv2.line(R, (x0, y0), (x1, y1), float(rng.uniform(0.08, 0.30)), 1, lineType=_cv2.LINE_AA)
                _cv2.line(CC, (x0, y0), (x1, y1), float(rng.uniform(0.56, 0.96)), 1, lineType=_cv2.LINE_AA)

        n_resin = int(np.clip(260 * (min(h, w) / 512.0) ** 2, 90, 1000))
        for _ in range(n_resin):
            cx = int(rng.uniform(0, w))
            cy = int(rng.uniform(0, h))
            rx = max(2, int(rng.uniform(4.0, 9.0) * scale))
            ry = max(1, int(rng.uniform(2.0, 5.0) * scale))
            _cv2.ellipse(CC, (cx, cy), (rx, ry), float(rng.uniform(0, 180)), 0, 360,
                         float(rng.uniform(0.76, 0.99)), -1, lineType=_cv2.LINE_AA)
            _cv2.ellipse(R, (cx, cy), (rx, ry), float(rng.uniform(0, 180)), 0, 360,
                         float(rng.uniform(0.08, 0.22)), -1, lineType=_cv2.LINE_AA)

    n_spark = int(np.clip(h * w / 260.0, 450, 9000))
    fy = rng.integers(0, h, n_spark)
    fx = rng.integers(0, w, n_spark)
    M[fy, fx] = np.maximum(M[fy, fx], rng.uniform(0.58, 0.94, n_spark).astype(np.float32))
    CC[fy, fx] = np.maximum(CC[fy, fx], rng.uniform(0.64, 0.98, n_spark).astype(np.float32))
    out = np.stack([M, R, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)


def purge_rework_morning_dew_fog(shape, seed, sm, **kwargs):
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    rng = np.random.default_rng(int(seed) + 529104)
    scale = max(min(h, w) / 2048.0, 0.25)
    mist = _normalize(multi_scale_noise(shape, [8.0, 22.0, 50.0], [0.45, 0.35, 0.20], int(seed) + 144))
    M = (0.22 + mist * 0.10).astype(np.float32)
    R = (0.70 - mist * 0.16).astype(np.float32)
    CC = (0.48 + mist * 0.18).astype(np.float32)

    if _CV2_OK:
        # Dew should read as clean beads with highlights, not random static.
        n_beads = int(np.clip(2300 * (min(h, w) / 512.0) ** 2, 800, 9000))
        for _ in range(n_beads):
            cx = int(rng.uniform(2, w - 2))
            cy = int(rng.uniform(2, h - 2))
            r = max(1, int(rng.uniform(1.3, 4.0) * scale))
            _cv2.circle(M, (cx, cy), r, float(rng.uniform(0.20, 0.42)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r, float(rng.uniform(0.04, 0.18)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r, float(rng.uniform(0.78, 0.99)), -1, lineType=_cv2.LINE_AA)
            hx = max(0, cx - max(1, r // 2))
            hy = max(0, cy - max(1, r // 2))
            M[hy, hx] = float(rng.uniform(0.86, 0.99))
            CC[hy, hx] = float(rng.uniform(0.03, 0.12))

        n_hero = int(rng.integers(10, 18))
        for _ in range(n_hero):
            cx = int(rng.uniform(0.08, 0.92) * w)
            cy = int(rng.uniform(0.08, 0.92) * h)
            r = max(3, int(rng.uniform(6.0, 11.0) * scale))
            _cv2.circle(CC, (cx, cy), r + 2, float(rng.uniform(0.56, 0.72)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(M, (cx, cy), r, float(rng.uniform(0.24, 0.40)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), r, float(rng.uniform(0.04, 0.14)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(CC, (cx, cy), r, float(rng.uniform(0.86, 0.99)), -1, lineType=_cv2.LINE_AA)
            _cv2.circle(M, (cx - r // 2, cy - r // 2), max(1, r // 3),
                        float(rng.uniform(0.88, 0.99)), -1, lineType=_cv2.LINE_AA)
            # Short drip chain from a few hero beads.
            if rng.random() < 0.55:
                for k in range(1, int(rng.integers(4, 7))):
                    rr = max(1, int(r * (1.0 - k * 0.14)))
                    tx = int(np.clip(cx + rng.normal(0, 1.2) * scale, 0, w - 1))
                    ty = int(np.clip(cy + k * r * 1.15, 0, h - 1))
                    _cv2.circle(M, (tx, ty), rr, float(rng.uniform(0.20, 0.38)), -1, lineType=_cv2.LINE_AA)
                    _cv2.circle(R, (tx, ty), rr, float(rng.uniform(0.04, 0.16)), -1, lineType=_cv2.LINE_AA)
                    _cv2.circle(CC, (tx, ty), rr, float(rng.uniform(0.80, 0.98)), -1, lineType=_cv2.LINE_AA)

    out = np.stack([M, R, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)


