# === LET FREEDOM RING SPEC OVERLAYS (spec_lfr_*) 2026-06-09 START ===
# 10 patriotic spec overlays for the Let Freedom Ring drop. All are
# UV-orientation-agnostic (scattered / radial / multi-angle motifs only)
# and decorrelate M/R/Cc via independent seed offsets + distinct geometry
# per channel (wild-spec doctrine, max|corr|<0.85). Each fn is marked
# _spb_concept_complete so _spb_wrap_spec_pattern leaves it untouched.

def _lfr_opt_ms_noise(shape, scales, weights, seed, half_min_sigma=8.0):
    """multi_scale_noise with identical rng draws, faster smooth octaves.

    Octaves with sigma >= half_min_sigma carry no content near Nyquist, so
    they are box-decimated 2x, blurred with sigma/2 and bilinearly upscaled
    (snapshot-validated, sub-1% field drift). Octaves below the threshold
    (and the rng sequence) are bit-identical to multi_scale_noise. Only for
    value substrates — never for fields that drive drawn geometry.
    """
    h, w = shape
    rng = np.random.RandomState(seed)
    result = np.zeros(shape, dtype=np.float32)
    total_w = sum(weights)
    use_half = _CV2_OK and min(h, w) >= 128
    for sigma, wgt in zip(scales, weights):
        noise = rng.rand(h, w).astype(np.float32)
        if sigma > 0:
            if use_half and sigma >= half_min_sigma:
                small = _cv2.resize(noise, ((w + 1) // 2, (h + 1) // 2),
                                    interpolation=_cv2.INTER_AREA)
                small = _gauss(small, sigma=float(sigma) * 0.5)
                noise = _cv2.resize(small, (w, h), interpolation=_cv2.INTER_LINEAR)
            else:
                noise = _gauss(noise, sigma=float(sigma))
        result += noise * (wgt / total_w)
    return result


def _lfr_opt_smear_field(noise, ang, length, xx, yy, step=1):
    """Fast, bitwise-identical version of the anisotropic advection smear.

    ``xx`` is a (1, w) float32 row and ``yy`` an (h, 1) float32 column of
    pixel indices (broadcast adds are bitwise-identical to the original
    full-mgrid adds). Replaces the original per-step full-grid loop
    (cos/sin recomputed every step + clip() + fancy-index gathers) with:
    trig hoisted out of the loop (same bits every step), truncating-cast
    int16 maps, and cv2.remap INTER_NEAREST + BORDER_REPLICATE (verified
    exactly equal to the original clip()+fancy-index gather, including
    out-of-range coords). Work is row-blocked so per-step buffers stay
    cache-resident. Same sample positions, same accumulation order ->
    identical output.

    ``step > 1`` samples every step-th original ray offset (a bitwise-exact
    SUBSET of the original positions; _normalize is scale-invariant so the
    subset mean only differs by the smooth-field sampling density). Only
    used for the heavily-blurred Cc source — never for white-noise sources.
    """
    h, w = noise.shape
    if not _CV2_OK:
        acc = noise.copy()
        cnt = 1.0
        for s in range(1, length + 1):
            dx = np.cos(ang) * (s * step)
            dy = np.sin(ang) * (s * step)
            xi = np.clip((xx + dx).astype(np.int32), 0, w - 1)
            yi = np.clip((yy + dy).astype(np.int32), 0, h - 1)
            acc = acc + noise[yi, xi]
            xi2 = np.clip((xx - dx).astype(np.int32), 0, w - 1)
            yi2 = np.clip((yy - dy).astype(np.int32), 0, h - 1)
            acc = acc + noise[yi2, xi2]
            cnt += 2.0
        return _normalize(acc / cnt)
    ca = np.cos(ang)
    sa = np.sin(ang)
    acc = noise.copy()
    B = 128

    def _run_blocks(starts):
        for r0 in starts:
            r1 = min(h, r0 + B)
            bh = r1 - r0
            cab = ca[r0:r1]; sab = sa[r0:r1]
            yb = yy[r0:r1]
            ab = acc[r0:r1]
            mp = np.empty((2 * bh, w, 2), dtype=np.int16)
            fb = np.empty((bh, w), dtype=np.float32)
            db = np.empty((2 * bh, w), dtype=np.float32)
            dxb = np.empty((bh, w), dtype=np.float32)
            dyb = np.empty((bh, w), dtype=np.float32)
            for s in range(1, length + 1):
                sf = np.float32(s * step)   # bitwise == python-int multiply for s <= 2^24
                np.multiply(cab, sf, out=dxb)
                np.multiply(sab, sf, out=dyb)
                np.add(xx, dxb, out=fb); mp[:bh, :, 0] = fb
                np.add(yb, dyb, out=fb); mp[:bh, :, 1] = fb
                np.subtract(xx, dxb, out=fb); mp[bh:, :, 0] = fb
                np.subtract(yb, dyb, out=fb); mp[bh:, :, 1] = fb
                _cv2.remap(noise, mp, None, _cv2.INTER_NEAREST, dst=db,
                           borderMode=_cv2.BORDER_REPLICATE)
                np.add(ab, db[:bh], out=ab)
                np.add(ab, db[bh:], out=ab)

    blocks = list(range(0, h, B))
    # PERF: row blocks are fully independent (disjoint acc slices, read-only
    # shared inputs, bitwise-deterministic ops) — wall-clock-only threading.
    if h >= 1024 and len(blocks) >= 3:
        try:
            from concurrent.futures import ThreadPoolExecutor as _TPE
            with _TPE(max_workers=3) as _ex:
                list(_ex.map(_run_blocks, [blocks[i::3] for i in range(3)]))
        except Exception:
            _run_blocks(blocks)
    else:
        _run_blocks(blocks)
    cnt = float(1 + 2 * length)
    return _normalize(acc / cnt)

def spec_lfr_starfield_scatter(shape, seed, sm, star_density=0.00018, min_pts=140, **kwargs):
    """spec_lfr_starfield_scatter.

    identity: Let Freedom Ring — the canton abstracted into an
    OMNIDIRECTIONAL scatter of 5-point stars at random angles & sizes.
    Decorrelated channels: M = bright filled star glint cores; R = a
    signed roughness 'twinkle' halo ring around a DIFFERENT scattered
    point set; Cc = a faint constellation filament web linking random
    neighbors. No upright grid, no centered emblem.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)
    # --- independent substrates (own seeds) ---
    gM = _normalize(multi_scale_noise((h, w), [3.0, 9.0], [0.6, 0.4], int(seed) + 101))
    gR = _normalize(multi_scale_noise((h, w), [2.2, 7.0, 16.0], [0.4, 0.35, 0.25], int(seed) + 211))
    gC = _normalize(multi_scale_noise((h, w), [4.0, 12.0], [0.55, 0.45], int(seed) + 307))
    M  = (0.30 + (gM - 0.5) * 0.14).astype(np.float32)   # dark velvet field, stars pop bright
    R  = (0.58 + (gR - 0.5) * 0.22).astype(np.float32)   # mid roughness, signed halos cut both ways
    CC = (0.50 + (gC - 0.5) * 0.16).astype(np.float32)

    def _star_poly(cx, cy, rad, ang, points=5):
        pts = []
        for k in range(points * 2):
            rr = rad if (k % 2 == 0) else rad * 0.40
            a = ang + k * np.pi / points
            pts.append([int(cx + np.cos(a) * rr), int(cy + np.sin(a) * rr)])
        return np.array([pts], dtype=np.int32)

    n_star = int(np.clip(star_density * h * w, min_pts, 2600))
    rngM = np.random.default_rng(int(seed) + 101)
    rngR = np.random.default_rng(int(seed) + 211)
    rngC = np.random.default_rng(int(seed) + 307)

    if _CV2_OK:
        # --- M: filled star glint cores (own point set) ---
        for _ in range(n_star):
            cx = int(rngM.uniform(0.01, 0.99) * w); cy = int(rngM.uniform(0.01, 0.99) * h)
            rad = float(rngM.uniform(3.0, 11.0) * scale)
            ang = float(rngM.uniform(0, 2 * np.pi))
            poly = _star_poly(cx, cy, rad, ang, 5)
            _cv2.fillPoly(M, poly, float(rngM.uniform(0.80, 0.99)), lineType=_cv2.LINE_AA)
            _cv2.circle(M, (cx, cy), 1, float(rngM.uniform(0.90, 1.0)), -1, lineType=_cv2.LINE_AA)

        # --- R: signed roughness twinkle halos (DIFFERENT scattered centers) ---
        n_halo = int(n_star * 1.3)
        for _ in range(n_halo):
            cx = int(rngR.uniform(0.0, 1.0) * w); cy = int(rngR.uniform(0.0, 1.0) * h)
            rr = max(2, int(rngR.uniform(3.0, 9.0) * scale))
            # signed: some halos polish (low R), some roughen (high R)
            val = float(rngR.uniform(0.05, 0.30)) if rngR.random() < 0.55 else float(rngR.uniform(0.70, 0.95))
            _cv2.circle(R, (cx, cy), rr, val, 1, lineType=_cv2.LINE_AA)
            _cv2.circle(R, (cx, cy), max(1, rr // 2), float(np.clip(val + rngR.uniform(-0.1, 0.1), 0, 1)), 1, lineType=_cv2.LINE_AA)

        # --- Cc: constellation filaments linking random neighbors ---
        n_node = int(np.clip(n_star * 0.5, 60, 1400))
        nodes = np.stack([rngC.uniform(0, w, n_node), rngC.uniform(0, h, n_node)], axis=1)
        for i in range(n_node):
            j = int(rngC.integers(0, n_node))
            if j == i:
                continue
            x0, y0 = int(nodes[i, 0]), int(nodes[i, 1])
            x1, y1 = int(nodes[j, 0]), int(nodes[j, 1])
            dd = (x0 - x1) ** 2 + (y0 - y1) ** 2
            if dd > (mn * 0.10) ** 2:   # only short links — keeps it a web, not chaos
                continue
            _cv2.line(CC, (x0, y0), (x1, y1), float(rngC.uniform(0.62, 0.88)), 1, lineType=_cv2.LINE_AA)
        for i in range(n_node):
            _cv2.circle(CC, (int(nodes[i, 0]), int(nodes[i, 1])), 1, float(rngC.uniform(0.70, 0.95)), -1, lineType=_cv2.LINE_AA)
    else:
        # numpy fallback: sparse pixel glints / pits (still decorrelated)
        yM = rngM.integers(0, h, n_star); xM = rngM.integers(0, w, n_star)
        M[yM, xM] = rngM.uniform(0.80, 0.99, n_star).astype(np.float32)
        yR = rngR.integers(0, h, n_star); xR = rngR.integers(0, w, n_star)
        R[yR, xR] = rngR.uniform(0.05, 0.95, n_star).astype(np.float32)
        yC = rngC.integers(0, h, n_star); xC = rngC.integers(0, w, n_star)
        CC[yC, xC] = rngC.uniform(0.62, 0.90, n_star).astype(np.float32)

    out = np.stack([np.clip(M, 0, 1), np.clip(R, 0, 1), np.clip(CC, 0, 1)], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
spec_lfr_starfield_scatter._spb_concept_complete = True

def spec_lfr_corridor_sheen(shape, seed, sm, num_lane_sets=4, **kwargs):
    """spec_lfr_corridor_sheen.

    identity: Let Freedom Ring — the 13 stripes abstracted into a
    MULTI-DIRECTIONAL sheen-corridor field. Several lane families each at
    an independent random angle so it never reads as parallel flag stripes.
    Decorrelated: M = lane gloss bands (angle set A); R = anisotropic brush
    grain along an orthogonal axis (set B), signed; Cc = wide soft corridor
    pooling (set C, low freq).
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    mn = min(h, w)
    # PERF: row/col vectors instead of full mgrid — broadcasting produces
    # bitwise-identical elementwise results (incl. the sign-sensitive
    # polarity field) with far less memory traffic.
    yy = np.arange(h, dtype=np.float32)[:, None]
    xx = np.arange(w, dtype=np.float32)[None, :]
    rngM = np.random.default_rng(int(seed) + 131)
    rngR = np.random.default_rng(int(seed) + 233)
    rngC = np.random.default_rng(int(seed) + 349)
    n_set = int(max(3, num_lane_sets))

    # --- M: lane gloss bands summed over several random angles ---
    accM = np.zeros((h, w), dtype=np.float32)
    for _ in range(n_set):
        ang = float(rngM.uniform(0, np.pi))
        freq = float(rngM.uniform(5.0, 11.0)) / mn * 2 * np.pi
        phase = float(rngM.uniform(0, 2 * np.pi))
        proj = xx * np.cos(ang) + yy * np.sin(ang)
        accM += np.sin(proj * freq + phase)
    accM = _normalize(accM)
    # square it up to feathered bands
    bands = _smoothstep(0.42, 0.58, accM)
    M = (0.34 + bands * 0.55).astype(np.float32)

    # --- R: anisotropic brush grain on an ORTHOGONAL axis, signed ---
    ang_b = float(rngR.uniform(0, np.pi))
    # build directional noise: sample noise then blur strongly along ang_b
    base_n = rngR.random((h, w)).astype(np.float32)
    if _CV2_OK:
        # directional blur via rotated box: approximate with a long thin kernel
        klen = max(9, int(mn * 0.02)) | 1
        kern = np.zeros((klen, klen), dtype=np.float32)
        cxk = klen // 2
        for t in range(klen):
            dx = int(round(np.cos(ang_b) * (t - cxk))) + cxk
            dy = int(round(np.sin(ang_b) * (t - cxk))) + cxk
            if 0 <= dx < klen and 0 <= dy < klen:
                kern[dy, dx] = 1.0
        kern /= max(kern.sum(), 1.0)
        grain = _cv2.filter2D(base_n, -1, kern)
    else:
        grain = _gauss(base_n, sigma=2.0)
    grain = _normalize(grain)
    # signed: center around 0.5, push some lanes glossy (low R) some rough (high R)
    polarity = np.sin((xx * np.cos(ang_b + np.pi / 2) + yy * np.sin(ang_b + np.pi / 2)) * (float(rngR.uniform(4.0, 8.0)) / mn * 2 * np.pi))
    R = (0.50 + (grain - 0.5) * 0.30 + np.sign(polarity) * (grain - 0.5) * 0.18).astype(np.float32)

    # --- Cc: wide soft corridor pooling, third angle, low freq ---
    accC = np.zeros((h, w), dtype=np.float32)
    for _ in range(max(2, n_set - 1)):
        ang = float(rngC.uniform(0, np.pi))
        freq = float(rngC.uniform(1.6, 3.2)) / mn * 2 * np.pi
        phase = float(rngC.uniform(0, 2 * np.pi))
        proj = xx * np.cos(ang) + yy * np.sin(ang)
        accC += np.sin(proj * freq + phase)
    accC = _normalize(accC)
    accC = _gauss(accC, sigma=max(2.0, mn * 0.004))
    CC = (0.46 + (accC - 0.5) * 0.34).astype(np.float32)

    out = np.stack([np.clip(M, 0, 1), np.clip(R, 0, 1), np.clip(CC, 0, 1)], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
spec_lfr_corridor_sheen._spb_concept_complete = True

def spec_lfr_firework_radial(shape, seed, sm, num_bursts=22, **kwargs):
    """spec_lfr_firework_radial.

    identity: Let Freedom Ring — scattered radial firework bursts.
    Decorrelated: M = bright burst spokes (hub->dark tip ramp); R =
    expanding signed shock rings on a separate center set; Cc = soft
    glow corona + ember trails on a third set. Radial = UV-rotation-proof.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)
    gM = _normalize(_lfr_opt_ms_noise((h, w), [4.0, 11.0], [0.6, 0.4], int(seed) + 151))
    gR = _normalize(_lfr_opt_ms_noise((h, w), [3.0, 9.0], [0.55, 0.45], int(seed) + 263))
    gC = _normalize(_lfr_opt_ms_noise((h, w), [6.0, 16.0], [0.5, 0.5], int(seed) + 373))
    M  = (0.24 + (gM - 0.5) * 0.14).astype(np.float32)   # dark night sky
    R  = (0.55 + (gR - 0.5) * 0.20).astype(np.float32)
    CC = (0.40 + (gC - 0.5) * 0.16).astype(np.float32)

    nb = int(np.clip(num_bursts * scale * scale * 4 + num_bursts, 14, 120))
    rngM = np.random.default_rng(int(seed) + 151)
    rngR = np.random.default_rng(int(seed) + 263)
    rngC = np.random.default_rng(int(seed) + 373)

    if _CV2_OK:
        # --- M: spoke bursts (hub bright -> tip dark) ---
        for _ in range(nb):
            cx = int(rngM.uniform(0.05, 0.95) * w); cy = int(rngM.uniform(0.05, 0.95) * h)
            reach = float(rngM.uniform(28.0, 70.0) * scale)
            n_spk = int(rngM.integers(18, 40))
            a0 = float(rngM.uniform(0, 2 * np.pi))
            for i in range(n_spk):
                ang = a0 + i * (2 * np.pi / n_spk) + float(rngM.uniform(-0.04, 0.04))
                ca_s = np.cos(ang); sa_s = np.sin(ang)   # hoisted, same bits
                for seg in range(4):
                    t0 = seg / 4.0; t1 = (seg + 1) / 4.0
                    x0 = int(min(max(cx + ca_s * reach * t0, 0), w - 1))
                    y0 = int(min(max(cy + sa_s * reach * t0, 0), h - 1))
                    x1 = int(min(max(cx + ca_s * reach * t1, 0), w - 1))
                    y1 = int(min(max(cy + sa_s * reach * t1, 0), h - 1))
                    val = float(min(max(0.95 - (t0 + t1) * 0.5 * 0.85, 0.08), 0.99))
                    _cv2.line(M, (x0, y0), (x1, y1), val, 1, lineType=_cv2.LINE_AA)
            _cv2.circle(M, (cx, cy), max(2, int(2 * scale)), 0.99, -1, lineType=_cv2.LINE_AA)

        # --- R: signed expanding shock rings on DIFFERENT centers ---
        for _ in range(int(nb * 1.2)):
            cx = int(rngR.uniform(0.0, 1.0) * w); cy = int(rngR.uniform(0.0, 1.0) * h)
            n_ring = int(rngR.integers(2, 6))
            base_r = float(rngR.uniform(6.0, 16.0) * scale)
            for k in range(n_ring):
                rr = max(2, int(base_r * (k + 1)))
                glossy = (k % 2 == 0)
                val = float(rngR.uniform(0.06, 0.26)) if glossy else float(rngR.uniform(0.72, 0.94))
                _cv2.circle(R, (cx, cy), rr, val, 1, lineType=_cv2.LINE_AA)

        # --- Cc: glow corona + downward ember trails on THIRD centers ---
        # PERF: each corona is drawn/blurred/max-blended in its local window
        # (the blur kernel has compact support, so outside the window the
        # full-grid tmp was exactly 0 and np.maximum was a no-op).
        for _ in range(nb):
            cx = int(rngC.uniform(0.05, 0.95) * w); cy = int(rngC.uniform(0.05, 0.95) * h)
            glow = float(rngC.uniform(0.62, 0.90))
            gr = max(4, int(rngC.uniform(10.0, 26.0) * scale))
            sig_g = max(2.0, gr * 0.4)
            pad_g = gr + (int(sig_g * 6) | 1) // 2 + 4
            wx0 = max(0, cx - pad_g); wx1 = min(w, cx + pad_g + 1)
            wy0 = max(0, cy - pad_g); wy1 = min(h, cy + pad_g + 1)
            tmp = np.zeros((wy1 - wy0, wx1 - wx0), dtype=np.float32)
            _cv2.circle(tmp, (cx - wx0, cy - wy0), gr, glow, -1, lineType=_cv2.LINE_AA)
            tmp = _gauss(tmp, sigma=sig_g)
            CC[wy0:wy1, wx0:wx1] = np.maximum(CC[wy0:wy1, wx0:wx1], tmp)
            # ember trails fall in a random-but-consistent 'down' per burst (not global up/down)
            fall = float(rngC.uniform(0, 2 * np.pi))
            n_em = int(rngC.integers(5, 14))
            for _e in range(n_em):
                tlen = float(rngC.uniform(8.0, 30.0) * scale)
                ex = int(min(max(cx + np.cos(fall) * tlen + rngC.uniform(-6, 6), 0), w - 1))
                ey = int(min(max(cy + np.sin(fall) * tlen + rngC.uniform(-6, 6), 0), h - 1))
                _cv2.line(CC, (cx, cy), (ex, ey), float(rngC.uniform(0.55, 0.82)), 1, lineType=_cv2.LINE_AA)
    else:
        yy, xx = np.mgrid[0:h, 0:w].astype(np.float32)
        cx, cy = w * 0.5, h * 0.5
        rad = np.sqrt((xx - cx) ** 2 + (yy - cy) ** 2)
        ang = np.arctan2(yy - cy, xx - cx)
        M = _normalize((np.cos(ang * 24) * 0.5 + 0.5) * np.exp(-rad / (mn * 0.4))).astype(np.float32)
        R = _normalize(np.sin(rad / (mn * 0.03))).astype(np.float32)
        CC = _normalize(np.exp(-rad / (mn * 0.3))).astype(np.float32)

    out = np.stack([np.clip(M, 0, 1), np.clip(R, 0, 1), np.clip(CC, 0, 1)], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
spec_lfr_firework_radial._spb_concept_complete = True

def spec_lfr_brocade_relief(shape, seed, sm, scale_px=26, **kwargs):
    """spec_lfr_brocade_relief.

    identity: Let Freedom Ring — the eagle abstracted to an OMNIDIRECTIONAL
    feather-brocade relief: interlocking feather-scale lozenges tiled at
    varying angles + a damask diamond overlay. Decorrelated: M = raised
    feather-scale rims; R = signed barb grain inside scales (offset
    lattice); Cc = damask diamond network (rotated lattice, diff scale).
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)
    sp = max(10, int(scale_px * scale * (2048.0 / max(mn, 1)) * (mn / 2048.0)))
    sp = max(12, int(scale_px * max(mn / 2048.0, 0.45)))
    gM = _normalize(_lfr_opt_ms_noise((h, w), [3.0, 8.0], [0.6, 0.4], int(seed) + 173))
    gR = _normalize(_lfr_opt_ms_noise((h, w), [2.0, 6.0, 14.0], [0.4, 0.35, 0.25], int(seed) + 281))
    gC = _normalize(_lfr_opt_ms_noise((h, w), [5.0, 13.0], [0.55, 0.45], int(seed) + 397))
    M  = (0.40 + (gM - 0.5) * 0.16).astype(np.float32)
    R  = (0.52 + (gR - 0.5) * 0.22).astype(np.float32)
    CC = (0.46 + (gC - 0.5) * 0.16).astype(np.float32)
    rngM = np.random.default_rng(int(seed) + 173)
    rngR = np.random.default_rng(int(seed) + 281)
    rngC = np.random.default_rng(int(seed) + 397)

    if _CV2_OK:
        # --- M: feather-scale lozenge rims (offset brick rows, per-scale angle jitter) ---
        ny = int(h / (sp * 0.7)) + 2
        nx = int(w / sp) + 2
        for iy in range(ny):
            for ix in range(nx):
                cx = int(ix * sp + (sp * 0.5 if iy % 2 else 0) + rngM.uniform(-2, 2))
                cy = int(iy * sp * 0.7 + rngM.uniform(-2, 2))
                if not (0 <= cx < w and 0 <= cy < h):
                    continue
                aw = int(sp * 0.55); ah = int(sp * 0.42)
                rot = float(rngM.uniform(-18, 18))
                rim = float(rngM.uniform(0.66, 0.95))
                # raised feather rim = bright lower arc, dark upper notch
                _cv2.ellipse(M, (cx, cy), (aw, ah), rot, 20, 160, rim, 1, lineType=_cv2.LINE_AA)
                _cv2.ellipse(M, (cx, cy), (int(aw * 0.6), int(ah * 0.6)), rot, 200, 340, float(rngM.uniform(0.18, 0.40)), 1, lineType=_cv2.LINE_AA)

        # --- R: signed barb grain inside scales, OFFSET half-step lattice ---
        for iy in range(ny):
            for ix in range(nx):
                cx = int(ix * sp + (sp * 0.25) + (sp * 0.5 if iy % 2 == 0 else 0) + rngR.uniform(-2, 2))
                cy = int(iy * sp * 0.7 + sp * 0.35 + rngR.uniform(-2, 2))
                if not (0 <= cx < w and 0 <= cy < h):
                    continue
                barb_ang = float(rngR.uniform(0, np.pi))
                glossy = rngR.random() < 0.5
                bval = float(rngR.uniform(0.08, 0.30)) if glossy else float(rngR.uniform(0.70, 0.92))
                # PERF: trig hoisted per scale (same bits), clips via min/max.
                cbp = np.cos(barb_ang + np.pi / 2); sbp = np.sin(barb_ang + np.pi / 2)
                cba = np.cos(barb_ang); sba = np.sin(barb_ang)
                for kb in range(int(rngR.integers(3, 6))):
                    off = (kb - 2) * 2
                    x0 = int(cx + cbp * off - cba * sp * 0.3)
                    y0 = int(cy + sbp * off - sba * sp * 0.3)
                    x1 = int(cx + cbp * off + cba * sp * 0.3)
                    y1 = int(cy + sbp * off + sba * sp * 0.3)
                    _cv2.line(R, (min(max(x0, 0), w - 1), min(max(y0, 0), h - 1)),
                                 (min(max(x1, 0), w - 1), min(max(y1, 0), h - 1)), bval, 1, lineType=_cv2.LINE_AA)

        # --- Cc: damask diamond network, 45-deg rotated lattice, coarser ---
        dsp = int(sp * 1.7)
        for iy in range(-1, int(h / dsp) + 2):
            for ix in range(-1, int(w / dsp) + 2):
                cx = ix * dsp + (dsp // 2 if iy % 2 else 0)
                cy = iy * dsp
                pts = np.array([[[cx, cy - dsp // 2], [cx + dsp // 2, cy], [cx, cy + dsp // 2], [cx - dsp // 2, cy]]], dtype=np.int32)
                _cv2.polylines(CC, pts, True, float(rngC.uniform(0.58, 0.84)), 1, lineType=_cv2.LINE_AA)
                _cv2.circle(CC, (cx, cy), 1, float(rngC.uniform(0.66, 0.90)), -1, lineType=_cv2.LINE_AA)
    else:
        yy, xx = np.mgrid[0:h, 0:w].astype(np.float32)
        M = _normalize(np.abs(np.sin(xx / sp * np.pi) * np.cos(yy / sp * np.pi))).astype(np.float32)
        R = _normalize(np.sin((xx + yy) / (sp * 0.5))).astype(np.float32)
        CC = _normalize(np.abs(np.sin((xx - yy) / (sp * 1.7) * np.pi))).astype(np.float32)

    out = np.stack([np.clip(M, 0, 1), np.clip(R, 0, 1), np.clip(CC, 0, 1)], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
spec_lfr_brocade_relief._spb_concept_complete = True

def spec_lfr_liberty_colorflip(shape, seed, sm, num_waves=5, **kwargs):
    """spec_lfr_liberty_colorflip.

    identity: Let Freedom Ring — a LIVING red/white/blue color-flip
    clearcoat. Angle-reveal thin-film iridescence where M/R/Cc peak at
    different phases (0, 120, 240 deg) and different detuned frequencies,
    so the panel flashes tricolor as light sweeps. Decorrelated by phase
    offset + frequency detune + per-channel jittered wave sets.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    mn = min(h, w)
    # PERF: row/col vectors instead of full mgrid — broadcasting produces
    # bitwise-identical elementwise results with far less memory traffic.
    yy = np.arange(h, dtype=np.float32)[:, None]
    xx = np.arange(w, dtype=np.float32)[None, :]
    nw = int(max(3, num_waves))

    def _phase_field(seed_off, freq_lo, freq_hi):
        rng = np.random.default_rng(int(seed) + seed_off)
        acc = np.zeros((h, w), dtype=np.float32)
        for _ in range(nw):
            ang = float(rng.uniform(0, np.pi))
            freq = float(rng.uniform(freq_lo, freq_hi)) / mn * 2 * np.pi
            ph = float(rng.uniform(0, 2 * np.pi))
            # PERF: sin(proj*freq + ph) with proj affine in x/y is expanded
            # via sin(U+V) = sinU cosV + cosU sinV on 1-D row/col vectors —
            # no full-grid transcendental (error ~1e-6, snapshot-validated).
            u = xx * np.float32(np.cos(ang) * freq)               # (1, w)
            v = yy * np.float32(np.sin(ang) * freq) + np.float32(ph)  # (h, 1)
            acc += np.sin(u) * np.cos(v) + np.cos(u) * np.sin(v)
        return _normalize(acc)

    # shared-ish accumulators but DIFFERENT seeds + frequencies per channel
    pM = _phase_field(401, 2.0, 4.0)
    pR = _phase_field(509, 2.6, 5.2)
    pC = _phase_field(617, 3.2, 6.4)

    # thin-film: cosine of (phase * 2pi + channel offset) -> tricolor peaks
    twopi = 2 * np.pi
    M  = 0.5 + 0.42 * np.cos(pM * twopi + 0.0)
    R0 = 0.5 + 0.42 * np.cos(pR * twopi + twopi / 3.0)
    CC = 0.5 + 0.42 * np.cos(pC * twopi + 2.0 * twopi / 3.0)
    # R signed: remap so it reads as glossy<->rough swing rather than brightness
    R = (0.5 + (R0 - 0.5) * 0.9).astype(np.float32)
    M = M.astype(np.float32); CC = CC.astype(np.float32)

    # subtle micro-shimmer so it isn't a pure smooth gradient (keeps it 'living')
    rngS = np.random.default_rng(int(seed) + 701)
    spk = rngS.random((h, w)).astype(np.float32)
    micro = (spk > 0.992).astype(np.float32) * 0.18
    M = np.clip(M + micro, 0, 1)
    CC = np.clip(CC + micro * 0.6, 0, 1)

    out = np.stack([np.clip(M, 0, 1), np.clip(R, 0, 1), np.clip(CC, 0, 1)], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
spec_lfr_liberty_colorflip._spb_concept_complete = True

def spec_lfr_anisotropic_drift(shape, seed, sm, **kwargs):
    """spec_lfr_anisotropic_drift.

    identity: Let Freedom Ring — multi-directional anisotropic brushed
    metal that FLOWS along a curl-noise field (a furling-flag sheen with
    no literal stripes). Decorrelated: M = brush highlights along flow A;
    R = signed cross-grain scratches along perpendicular of flow B;
    Cc = broad slow satin swirl pools.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    mn = min(h, w)

    # PERF: row/col index vectors — broadcast adds in the smear are
    # bitwise-identical to the original full-mgrid adds.
    yy = np.arange(h, dtype=np.float32)[:, None]
    xx = np.arange(w, dtype=np.float32)[None, :]
    L = max(3, int(mn * 0.012))

    def _dir_field(p, sigma):
        # curl of a smoothed scalar field -> divergence-free flow angle map
        p = _gauss(p, sigma=sigma)
        gy, gx = np.gradient(p)
        ang = np.arctan2(gx, -gy)   # curl direction
        return ang.astype(np.float32, copy=False)

    # Each channel draws from its own generators (original seeds, params,
    # per-generator order/count — values are independent of inter-generator
    # scheduling, so running channels concurrently is identity-safe).
    # --- M: brush highlights along flow A (bitwise-identical fast smear) ---
    def _chan_m():
        pA = np.random.default_rng(int(seed) + 191).random((h, w)).astype(np.float32)
        nM = np.random.default_rng(int(seed) + 191).random((h, w)).astype(np.float32)
        angA = _dir_field(pA, max(6.0, mn * 0.03))
        brushM = _lfr_opt_smear_field(nM, angA, L, xx, yy)
        return (0.40 + (brushM - 0.5) * 0.50).astype(np.float32)

    # --- R: signed cross-grain scratches along PERP of flow B ---
    def _chan_r():
        pB = np.random.default_rng(int(seed) + 293).random((h, w)).astype(np.float32)
        nR0 = np.random.default_rng(int(seed) + 293).random((h, w)).astype(np.float32)
        angB = _dir_field(pB, max(5.0, mn * 0.022)) + np.pi / 2.0
        # bias toward sparse scratches
        nR = np.where(nR0 > 0.78, nR0, 0.5).astype(np.float32)
        brushR = _lfr_opt_smear_field(nR, angB, max(2, L // 2), xx, yy)
        return (0.50 + (brushR - 0.5) * 0.44).astype(np.float32)

    # --- Cc: broad slow satin swirl pools ---
    # PERF: the Cc source is heavily blurred (smooth), so the L*2-deep ray
    # average is sampled at every other original offset (step=2): the
    # positions used are a bitwise-exact subset of the original ones, full
    # resolution and reach are kept, and only the sampling density of a
    # smooth field changes (snapshot-validated; M/R stay bitwise-exact).
    def _chan_c():
        pC = np.random.default_rng(int(seed) + 409).random((h, w)).astype(np.float32)
        nC0 = np.random.default_rng(int(seed) + 409).random((h, w)).astype(np.float32)
        angC = _dir_field(pC, max(12.0, mn * 0.06))
        nC = _gauss(nC0, sigma=max(3.0, mn * 0.012))
        brushC = _lfr_opt_smear_field(nC, angC, L, xx, yy, step=2)
        return (0.46 + (brushC - 0.5) * 0.34).astype(np.float32)

    # PERF: the three channel pipelines are independent (read-only inputs,
    # disjoint outputs, no rng) and every op in them is bitwise-deterministic
    # regardless of scheduling — overlap them on threads for wall-clock only.
    try:
        from concurrent.futures import ThreadPoolExecutor as _TPE
        with _TPE(max_workers=3) as _ex:
            _fM = _ex.submit(_chan_m); _fR = _ex.submit(_chan_r); _fC = _ex.submit(_chan_c)
            M = _fM.result(); R = _fR.result(); CC = _fC.result()
    except Exception:
        M = _chan_m(); R = _chan_r(); CC = _chan_c()

    # M/R/CC are affine maps of _normalize outputs and provably lie inside
    # [0, 1], so the former per-channel clips and the pre-_sm_scale clip
    # were identity ops — stacking directly is bitwise-identical.
    out = np.stack([M, R, CC], axis=-1)
    return _sm_scale(out, sm)
spec_lfr_anisotropic_drift._spb_concept_complete = True

def spec_lfr_sparkler_embers(shape, seed, sm, spark_density=0.010, **kwargs):
    """spec_lfr_sparkler_embers.

    identity: Let Freedom Ring — handheld-sparkler ember dust: dense
    scattered hot micro-sparks with short radiating jets + drifting smoke.
    Decorrelated: M = fine spark grains + micro jets; R = signed soot/smoke
    streaks (own drift); Cc = warm glow blooms around spark clusters.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)
    gM = _normalize(multi_scale_noise((h, w), [2.5, 7.0], [0.6, 0.4], int(seed) + 211))
    gR = _normalize(multi_scale_noise((h, w), [4.0, 11.0, 22.0], [0.4, 0.35, 0.25], int(seed) + 317))
    gC = _normalize(multi_scale_noise((h, w), [8.0, 20.0], [0.5, 0.5], int(seed) + 431))
    M  = (0.26 + (gM - 0.5) * 0.12).astype(np.float32)   # dark, sparks blaze
    R  = (0.56 + (gR - 0.5) * 0.22).astype(np.float32)
    CC = (0.42 + (gC - 0.5) * 0.16).astype(np.float32)
    rngM = np.random.default_rng(int(seed) + 211)
    rngR = np.random.default_rng(int(seed) + 317)
    rngC = np.random.default_rng(int(seed) + 431)

    # --- M: fine spark grains (vectorized) ---
    n_grain = int(np.clip(spark_density * h * w, 2000, 90000))
    ys = rngM.integers(0, h, n_grain); xs = rngM.integers(0, w, n_grain)
    M[ys, xs] = np.maximum(M[ys, xs], rngM.uniform(0.70, 0.99, n_grain).astype(np.float32))
    if _CV2_OK:
        # micro radiating jets from a subset of sparks
        n_jet = int(np.clip(n_grain * 0.04, 300, 8000))
        for _ in range(n_jet):
            cx = int(rngM.uniform(0, 1) * w); cy = int(rngM.uniform(0, 1) * h)
            n_arm = int(rngM.integers(2, 5))
            a0 = float(rngM.uniform(0, 2 * np.pi))
            for k in range(n_arm):
                ang = a0 + k * (2 * np.pi / n_arm) + float(rngM.uniform(-0.2, 0.2))
                ln = float(rngM.uniform(2.0, 5.0) * scale)
                ex = int(min(max(cx + np.cos(ang) * ln, 0), w - 1))
                ey = int(min(max(cy + np.sin(ang) * ln, 0), h - 1))
                _cv2.line(M, (cx, cy), (ex, ey), float(rngM.uniform(0.60, 0.95)), 1, lineType=_cv2.LINE_AA)

        # --- R: signed soft soot/smoke streaks (own drift) ---
        # PERF: each streak is drawn/blurred/blended in its local window
        # only (identical rng sequence, identical math on the slice; the
        # blur kernel has compact support so outside the window the
        # full-grid tmp was exactly 0 and the np.where left R untouched).
        n_smoke = int(np.clip(160 * scale * scale + 80, 40, 900))
        tk_smoke = max(1, int(2 * scale))
        sig_smoke = max(1.5, 3.0 * scale)
        pad_smoke = (int(sig_smoke * 6) | 1) // 2 + tk_smoke + 4
        for _ in range(n_smoke):
            cx = float(rngR.uniform(0, w)); cy = float(rngR.uniform(0, h))
            drift = float(rngR.uniform(0, 2 * np.pi))
            glossy = rngR.random() < 0.5
            val = float(rngR.uniform(0.06, 0.26)) if glossy else float(rngR.uniform(0.70, 0.92))
            x, y = cx, cy
            ang = drift
            segs = []
            for step in range(int(rngR.integers(8, 22))):
                ang += float(rngR.uniform(-0.25, 0.25))
                nx = x + np.cos(ang) * rngR.uniform(3, 7) * scale
                ny = y + np.sin(ang) * rngR.uniform(3, 7) * scale
                segs.append((int(min(max(x, 0), w - 1)), int(min(max(y, 0), h - 1)),
                             int(min(max(nx, 0), w - 1)), int(min(max(ny, 0), h - 1))))
                x, y = nx, ny
            ex_all = [s_[0] for s_ in segs] + [s_[2] for s_ in segs]
            ey_all = [s_[1] for s_ in segs] + [s_[3] for s_ in segs]
            wx0 = max(0, min(ex_all) - pad_smoke); wx1 = min(w, max(ex_all) + pad_smoke + 1)
            wy0 = max(0, min(ey_all) - pad_smoke); wy1 = min(h, max(ey_all) + pad_smoke + 1)
            tmp = np.zeros((wy1 - wy0, wx1 - wx0), dtype=np.float32)
            for (ax_, ay_, bx_, by_) in segs:
                _cv2.line(tmp, (ax_ - wx0, ay_ - wy0), (bx_ - wx0, by_ - wy0), val,
                          tk_smoke, lineType=_cv2.LINE_AA)
            tmp = _gauss(tmp, sigma=sig_smoke)
            # blend signed streak in
            sub = R[wy0:wy1, wx0:wx1]
            R[wy0:wy1, wx0:wx1] = np.where(
                tmp > 0.01, 0.5 + (val - 0.5) * np.clip(tmp * 2.2, 0, 1) + (sub - 0.5), sub
            ).astype(np.float32)

        # --- Cc: warm glow blooms around spark clusters (own centers) ---
        n_bloom = int(np.clip(120 * scale * scale + 60, 30, 700))
        glow = np.zeros((h, w), dtype=np.float32)
        for _ in range(n_bloom):
            cx = int(rngC.uniform(0.03, 0.97) * w); cy = int(rngC.uniform(0.03, 0.97) * h)
            rr = max(3, int(rngC.uniform(6.0, 18.0) * scale))
            _cv2.circle(glow, (cx, cy), rr, float(rngC.uniform(0.55, 0.9)), -1, lineType=_cv2.LINE_AA)
        glow = _gauss(glow, sigma=max(2.0, mn * 0.006))
        CC = np.maximum(CC, glow)

    out = np.stack([np.clip(M, 0, 1), np.clip(R, 0, 1), np.clip(CC, 0, 1)], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
spec_lfr_sparkler_embers._spb_concept_complete = True

def spec_lfr_torch_flicker(shape, seed, sm, num_flames=60, **kwargs):
    """spec_lfr_torch_flicker.

    identity: Let Freedom Ring — living Statue-of-Liberty torch flicker:
    scattered multi-directional flame-tongue lobes with a heat-shimmer
    warp. Decorrelated: M = bright flame-tongue cores (turbulence-warped);
    R = signed heat-shimmer roughness from an independent turbulence field;
    Cc = ember-glow pooling at lobe bases.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)

    # --- turbulence fields (independent seeds) ---
    # T1 stays exact: it drives the flame polygon GEOMETRY (wob lookups).
    T1 = _normalize(multi_scale_noise((h, w), [3.0, 8.0, 18.0], [0.5, 0.3, 0.2], int(seed) + 233))
    # T2 stays exact too: sin(T2*6pi) amplifies its error ~7x into R.
    T2 = _normalize(multi_scale_noise((h, w), [2.0, 5.0, 12.0], [0.45, 0.35, 0.2], int(seed) + 331))
    T3 = _normalize(_lfr_opt_ms_noise((h, w), [6.0, 15.0], [0.55, 0.45], int(seed) + 443))

    M = (0.24 + (T1 - 0.5) * 0.12).astype(np.float32)
    CC = (0.40 + (T3 - 0.5) * 0.14).astype(np.float32)
    rngM = np.random.default_rng(int(seed) + 233)
    rngC = np.random.default_rng(int(seed) + 443)

    nf = int(np.clip(num_flames * scale * scale * 6 + num_flames, 40, 520))
    if _CV2_OK:
        for _ in range(nf):
            cx = int(rngM.uniform(0.04, 0.96) * w); cy = int(rngM.uniform(0.04, 0.96) * h)
            local_dir = float(rngM.uniform(0, 2 * np.pi))   # each flame its own direction
            flen = float(rngM.uniform(14.0, 40.0) * scale)
            fwid = float(rngM.uniform(4.0, 10.0) * scale)
            # flame tongue as a tapered teardrop polyline (warped by turbulence)
            # PERF: trig hoisted per flame (same bits), scalar clips via min/max.
            cld = np.cos(local_dir); sld = np.sin(local_dir)
            perp = local_dir + np.pi / 2
            cpd = np.cos(perp); spd = np.sin(perp)
            n_pt = 10
            left = []; right = []
            for i in range(n_pt + 1):
                t = i / n_pt
                taper = np.sin(t * np.pi) ** 0.7
                wob = (T1[int(min(max(cy + sld * flen * t, 0), h - 1)),
                          int(min(max(cx + cld * flen * t, 0), w - 1))] - 0.5) * fwid * 1.6
                bx = cx + cld * flen * t
                by = cy + sld * flen * t
                hw_ = fwid * taper
                left.append([bx + cpd * hw_ + cld * wob, by + spd * hw_ + sld * wob])
                right.append([bx - cpd * hw_ + cld * wob, by - spd * hw_ + sld * wob])
            poly = np.array([left + right[::-1]], dtype=np.int32)
            _cv2.fillPoly(M, poly, float(rngM.uniform(0.72, 0.98)), lineType=_cv2.LINE_AA)
            # hot inner core, smaller
            poly2 = np.array([[ [int((p[0]*0.6 + cx*0.4)), int((p[1]*0.6 + cy*0.4))] for p in (left + right[::-1]) ]], dtype=np.int32)
            _cv2.fillPoly(M, poly2, float(rngM.uniform(0.85, 1.0)), lineType=_cv2.LINE_AA)
            # ember glow at the BASE
            _cv2.circle(CC, (cx, cy), max(3, int(fwid * 1.3)), float(rngC.uniform(0.6, 0.9)), -1, lineType=_cv2.LINE_AA)
        M = _gauss(M, sigma=max(0.6, 0.8 * scale))
        CC = _gauss(CC, sigma=max(1.5, mn * 0.005))

    # --- R: signed heat-shimmer roughness from INDEPENDENT turbulence ---
    # (the former "+ xx*0.0 + yy*0.0" added exact zeros — removed, identical)
    shimmer = np.sin(T2 * 6.0 * np.pi)   # warp purely from noise, isotropic
    shimmer = _normalize(shimmer + (T2 - 0.5))
    # signed: hot rising columns polish (low R), cooler troughs roughen (high R)
    R = (0.50 + (shimmer - 0.5) * 0.40 + (T2 - 0.5) * 0.18).astype(np.float32)

    out = np.stack([np.clip(M, 0, 1), np.clip(R, 0, 1), np.clip(CC, 0, 1)], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
spec_lfr_torch_flicker._spb_concept_complete = True

def spec_lfr_capitol_veins(shape, seed, sm, num_veins=28, **kwargs):
    """spec_lfr_capitol_veins.

    identity: Let Freedom Ring — white-marble Capitol veining: branching
    translucent veins on polished stone. Decorrelated: M = bright polished
    vein ridges (network A); R = signed hairline micro-fractures (network
    B); Cc = deep translucent vein interiors (network C) + calcite cloud
    mottling. Organic, omnidirectional.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)

    def _grow_veins(seed_off, n_root, width, val_lo, val_hi, signed=False, jitter=0.30):
        rng = np.random.default_rng(int(seed) + seed_off)
        canvas = np.zeros((h, w), dtype=np.float32)
        if not _CV2_OK:
            return canvas, rng
        for _ in range(int(n_root)):
            x = float(rng.uniform(0, w)); y = float(rng.uniform(0, h))
            ang = float(rng.uniform(0, 2 * np.pi))
            steps = int(rng.integers(40, 120))
            if signed:
                glossy = rng.random() < 0.5
                v = float(rng.uniform(val_lo, (val_lo + val_hi) / 2)) if glossy else float(rng.uniform((val_lo + val_hi) / 2, val_hi))
            else:
                v = float(rng.uniform(val_lo, val_hi))
            branch_stack = []
            lw_ = max(1, int(width * scale))   # hoisted, same value every line
            for s in range(steps):
                ang += float(rng.uniform(-jitter, jitter))
                nx = x + np.cos(ang) * 3.0 * scale
                ny = y + np.sin(ang) * 3.0 * scale
                _cv2.line(canvas, (int(min(max(x, 0), w - 1)), int(min(max(y, 0), h - 1))),
                                  (int(min(max(nx, 0), w - 1)), int(min(max(ny, 0), h - 1))), v, lw_, lineType=_cv2.LINE_AA)
                x, y = nx, ny
                if rng.random() < 0.04 and len(branch_stack) < 4:
                    branch_stack.append((x, y, ang + float(rng.uniform(-1.0, 1.0))))
                if not (0 <= x < w and 0 <= y < h) and branch_stack:
                    x, y, ang = branch_stack.pop()
            for (bx, by, bang) in branch_stack:
                x, y, ang = bx, by, bang
                for s in range(int(steps * 0.5)):
                    ang += float(rng.uniform(-jitter, jitter))
                    nx = x + np.cos(ang) * 3.0 * scale; ny = y + np.sin(ang) * 3.0 * scale
                    _cv2.line(canvas, (int(min(max(x, 0), w - 1)), int(min(max(y, 0), h - 1))),
                                      (int(min(max(nx, 0), w - 1)), int(min(max(ny, 0), h - 1))), v, lw_, lineType=_cv2.LINE_AA)
                    x, y = nx, ny
        return canvas, rng

    nr = int(np.clip(num_veins * scale + num_veins * 0.5, 14, 90))
    # M: bright polished primary veins
    vM, _ = _grow_veins(251, nr, width=2.5, val_lo=0.62, val_hi=0.95, signed=False, jitter=0.28)
    baseM = _normalize(_lfr_opt_ms_noise((h, w), [10.0, 26.0], [0.5, 0.5], int(seed) + 251))
    M = (0.62 + (baseM - 0.5) * 0.10)   # bright marble field
    M = np.where(vM > 0.01, np.maximum(M, vM), M).astype(np.float32)

    # R: signed hairline micro-fractures, separate network
    vR, _ = _grow_veins(359, int(nr * 1.4), width=1.2, val_lo=0.08, val_hi=0.92, signed=True, jitter=0.45)
    baseR = _normalize(_lfr_opt_ms_noise((h, w), [4.0, 12.0, 26.0], [0.4, 0.35, 0.25], int(seed) + 359))
    R = (0.50 + (baseR - 0.5) * 0.20)
    R = np.where(vR > 0.01, 0.5 + (vR - 0.5) * 0.9, R).astype(np.float32)

    # Cc: deep translucent vein interiors + calcite clouds, third network
    vC, _ = _grow_veins(467, int(nr * 0.8), width=4.0, val_lo=0.55, val_hi=0.85, signed=False, jitter=0.22)
    # sigma=22 stays exact (half-res tripped the 0.02 gate); sigma=50 is
    # smooth enough for the half-res path.
    clouds = _normalize(_lfr_opt_ms_noise((h, w), [22.0, 50.0], [0.5, 0.5], int(seed) + 467,
                                          half_min_sigma=30.0))
    CC = (0.44 + (clouds - 0.5) * 0.26)
    CC = np.where(vC > 0.01, np.maximum(CC, vC * 0.85), CC).astype(np.float32)

    out = np.stack([np.clip(M, 0, 1), np.clip(R, 0, 1), np.clip(CC, 0, 1)], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
spec_lfr_capitol_veins._spb_concept_complete = True

def spec_lfr_canyon_bevel(shape, seed, sm, num_cells=120, edge_w=2.0, **kwargs):
    """spec_lfr_canyon_bevel.

    identity: Let Freedom Ring — fake-3D faceted canyon/monument-stone
    bevel relief. Voronoi plateaus, each facet beveled by its OWN random
    light. Decorrelated: M = per-facet directional bevel highlight; R =
    signed roughness on facet edges; Cc = smooth ambient-occlusion depth
    pool (blurred plateau heights). Scattered/isotropic = UV-proof.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)
    # PERF: row/col vectors instead of full mgrid (bitwise-identical math).
    yy = np.arange(h, dtype=np.float32)[:, None]
    xx = np.arange(w, dtype=np.float32)[None, :]
    nc = int(np.clip(num_cells * scale * 2 + num_cells, 60, 700))
    rng = np.random.default_rng(int(seed) + 271)
    sites = np.stack([rng.uniform(0, w, nc), rng.uniform(0, h, nc)], axis=1).astype(np.float32)
    # per-cell attributes (own RNGs for R and Cc so they are independent)
    rngR = np.random.default_rng(int(seed) + 379)
    rngC = np.random.default_rng(int(seed) + 487)
    light_ang = rng.uniform(0, 2 * np.pi, nc).astype(np.float32)    # M: per-facet light dir
    edge_rough = rngR.uniform(0.0, 1.0, nc).astype(np.float32)      # R: per-edge polarity
    cell_height = rngC.uniform(0.2, 0.9, nc).astype(np.float32)     # Cc: plateau height

    try:
        from scipy.spatial import cKDTree as _KD
        # downsample grid for speed, then upscale label/dist maps
        ds = 2 if max(h, w) > 1024 else 1
        hs, ws = h // ds, w // ds
        gy, gx = np.mgrid[0:hs, 0:ws]
        pts = np.stack([gx.ravel() * ds, gy.ravel() * ds], axis=1).astype(np.float32)
        tree = _KD(sites)
        dist2, idx = tree.query(pts, k=2, workers=-1)   # nearest + 2nd nearest for edges
        nearest = idx[:, 0].reshape(hs, ws)
        d1 = dist2[:, 0].reshape(hs, ws)
        d2 = dist2[:, 1].reshape(hs, ws)
        edge_dist = (d2 - d1).reshape(hs, ws)   # small near borders
        if ds > 1 and _CV2_OK:
            nearest = _cv2.resize(nearest.astype(np.float32), (w, h), interpolation=_cv2.INTER_NEAREST).astype(np.int32)
            edge_dist = _cv2.resize(edge_dist.astype(np.float32), (w, h), interpolation=_cv2.INTER_LINEAR)
        else:
            nearest = nearest.astype(np.int32)
        # --- M: directional bevel per facet ---
        # PERF: trig on the per-cell vectors, then gathered per pixel
        # (identical per-site values); plane gathers instead of an
        # (h, w, 2) gather.
        cos_la = np.cos(light_ang)[nearest]; sin_la = np.sin(light_ang)[nearest]
        sx = sites[:, 0][nearest]; sy = sites[:, 1][nearest]
        rel = (xx - sx) * cos_la + (yy - sy) * sin_la
        rel = rel / (mn * 0.06)
        M = (0.5 + np.clip(rel, -1, 1) * 0.42).astype(np.float32)
        # --- R: signed roughness on edges (thin borders) ---
        edge_mask = np.clip(1.0 - edge_dist / (edge_w * scale + 1e-3), 0, 1).astype(np.float32)
        pol = edge_rough[nearest]   # 0..1 per facet -> glossy vs rough edge
        edge_val = np.where(pol > 0.5, 0.85, 0.12).astype(np.float32)
        baseR = _normalize(_lfr_opt_ms_noise((h, w), [6.0, 16.0], [0.5, 0.5], int(seed) + 379))
        R = (0.50 + (baseR - 0.5) * 0.16)
        R = (R * (1 - edge_mask) + edge_val * edge_mask).astype(np.float32)
        # --- Cc: smooth AO depth = blurred plateau heights ---
        CC = cell_height[nearest].astype(np.float32)
        CC = _gauss(CC, sigma=max(2.0, mn * 0.01))
        CC = (0.40 + (_normalize(CC) - 0.5) * 0.40).astype(np.float32)
    except Exception:
        # pure-numpy fallback (coarse) — still 3 decorrelated fields
        M = _normalize(multi_scale_noise((h, w), [18.0, 40.0], [0.5, 0.5], int(seed) + 271)).astype(np.float32)
        R = _normalize(multi_scale_noise((h, w), [5.0, 12.0], [0.5, 0.5], int(seed) + 379)).astype(np.float32)
        CC = _normalize(multi_scale_noise((h, w), [30.0, 70.0], [0.5, 0.5], int(seed) + 487)).astype(np.float32)

    out = np.stack([np.clip(M, 0, 1), np.clip(R, 0, 1), np.clip(CC, 0, 1)], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
