# --- IGNITION: spec_lfr_starfield_scatter ---
def spec_lfr_starfield_scatter(shape, seed, sm, star_density=0.00028, min_pts=160, **kwargs):
    '''spec_lfr_starfield_scatter -- 2026-06-10 rebuild: first-light volley.

    ONE motif system: a single scattered constellation of rotated 5-point
    stars (one shared point set; every star has its own random angle and
    size, so the layout is UV-orientation-agnostic). The three channels
    ride three ASPECTS of that same constellation:
      M  = star BODIES: a calm pewter majority (0.55-0.66) on a dark velvet
           field, plus a designed ~27% first-light subset detonated
           near-max (0.93-1.0) with four cross-flare arms and a hot bloom
           core -- quiet at most angles, a volley of glints when the sun
           lines up (the ignition channel).
      R  = ORBIT arcs around the same star centers: broken signed orbit
           sweeps that alternate polished (low R) / scuffed (high R);
           first-light stars carry a second counter-polarity arc.
      Cc = the CONSTELLATION web: short filaments linking near-neighbour
           stars of the same point set, node ticks, and a soft glow pool
           under the first-light stars.
    Calm surroundings; single detonating channel (M); hot(>200) area 5-12%.
    '''
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    mn = min(h, w)
    scale = max(mn / 2048.0, 0.25)

    gM = _normalize(_spb_fast_smooth_noise((h, w), [3.0, 11.0], [0.6, 0.4], int(seed) + 101))
    gR = _normalize(_spb_fast_smooth_noise((h, w), [2.5, 8.0, 18.0], [0.4, 0.35, 0.25], int(seed) + 211))
    gC = _normalize(_spb_fast_smooth_noise((h, w), [5.0, 14.0], [0.55, 0.45], int(seed) + 307))
    M = (0.27 + (gM - 0.5) * 0.10).astype(np.float32)
    R = (0.52 + (gR - 0.5) * 0.18).astype(np.float32)
    CC = (0.40 + (gC - 0.5) * 0.12).astype(np.float32)

    rngS = np.random.default_rng(int(seed) + 17)
    rngM = np.random.default_rng(int(seed) + 101)
    rngR = np.random.default_rng(int(seed) + 211)
    rngC = np.random.default_rng(int(seed) + 307)
    n = int(np.clip(star_density * h * w, min_pts, 2400))
    cx = rngS.uniform(0.015, 0.985, n) * w
    cy = rngS.uniform(0.015, 0.985, n) * h
    rad = rngS.uniform(4.5, 13.0, n) * scale
    ang = rngS.uniform(0.0, 2.0 * np.pi, n)
    ign = rngS.random(n) < 0.27

    def _star_poly(px, py, rr, aa):
        pts = []
        for k in range(10):
            r2 = rr if (k % 2 == 0) else rr * 0.42
            a2 = aa + k * (np.pi / 5.0)
            pts.append([int(px + np.cos(a2) * r2), int(py + np.sin(a2) * r2)])
        return np.array([pts], dtype=np.int32)

    if _CV2_OK:
        bloom = np.zeros((h, w), dtype=np.float32)
        for i in range(n):
            if ign[i]:
                _cv2.circle(bloom, (int(cx[i]), int(cy[i])), max(2, int(rad[i] * 1.9)), 1.0, -1,
                            lineType=_cv2.LINE_AA)
        bloom = np.asarray(_gauss(bloom, sigma=max(2.0, 6.0 * scale)), dtype=np.float32)
        M = np.maximum(M, bloom * np.float32(0.93))
        CC = np.maximum(CC, bloom * np.float32(0.52))
        for i in range(n):
            xi, yi = int(cx[i]), int(cy[i])
            if ign[i]:
                arm = rad[i] * float(rngM.uniform(4.2, 7.6))
                for k in range(4):
                    aa = ang[i] + k * (np.pi / 2.0)
                    ca, sa = float(np.cos(aa)), float(np.sin(aa))
                    xm, ym = int(xi + ca * arm * 0.45), int(yi + sa * arm * 0.45)
                    x1, y1 = int(xi + ca * arm), int(yi + sa * arm)
                    _cv2.line(M, (xi, yi), (xm, ym), float(rngM.uniform(0.93, 1.0)), 3,
                              lineType=_cv2.LINE_AA)
                    _cv2.line(M, (xm, ym), (x1, y1), float(rngM.uniform(0.82, 0.92)), 1,
                              lineType=_cv2.LINE_AA)
                _cv2.fillPoly(M, _star_poly(cx[i], cy[i], rad[i] * 1.15, ang[i]),
                              float(rngM.uniform(0.94, 1.0)), lineType=_cv2.LINE_AA)
            else:
                _cv2.fillPoly(M, _star_poly(cx[i], cy[i], rad[i], ang[i]),
                              float(rngM.uniform(0.55, 0.66)), lineType=_cv2.LINE_AA)
                _cv2.circle(M, (xi, yi), 1, float(rngM.uniform(0.62, 0.72)), -1,
                            lineType=_cv2.LINE_AA)
        for i in range(n):
            xi, yi = int(cx[i]), int(cy[i])
            pol = rngR.random() < 0.5
            v = float(rngR.uniform(0.04, 0.18)) if pol else float(rngR.uniform(0.82, 0.97))
            rr = max(2, int(rad[i] * 1.9))
            st = float(rngR.uniform(0.0, 360.0))
            sw = float(rngR.uniform(150.0, 330.0))
            _cv2.ellipse(R, (xi, yi), (rr, rr), 0.0, st, st + sw, v, 2, lineType=_cv2.LINE_AA)
            if ign[i]:
                v2 = float(rngR.uniform(0.82, 0.97)) if pol else float(rngR.uniform(0.04, 0.18))
                r2 = max(3, int(rad[i] * 2.9))
                st2 = float(rngR.uniform(0.0, 360.0))
                _cv2.ellipse(R, (xi, yi), (r2, r2), 0.0, st2, st2 + float(rngR.uniform(200.0, 340.0)),
                             v2, 2, lineType=_cv2.LINE_AA)
        pts = np.stack([cx, cy], axis=1)
        try:
            pairs = cKDTree(pts).query_pairs(r=mn * 0.045, output_type='ndarray')
        except TypeError:
            pairs = np.array(sorted(cKDTree(pts).query_pairs(r=mn * 0.045)),
                             dtype=np.int64).reshape(-1, 2)
        if len(pairs):
            keep = rngC.random(len(pairs)) < 0.55
            for a, b in pairs[keep]:
                _cv2.line(CC, (int(cx[a]), int(cy[a])), (int(cx[b]), int(cy[b])),
                          float(rngC.uniform(0.60, 0.82)), 1, lineType=_cv2.LINE_AA)
        for i in range(n):
            _cv2.circle(CC, (int(cx[i]), int(cy[i])), 1 if rngC.random() < 0.7 else 2,
                        float(rngC.uniform(0.65, 0.85)), -1, lineType=_cv2.LINE_AA)
    else:
        for i in range(n):
            xi, yi = int(cx[i]), int(cy[i])
            r0 = max(1, int(rad[i]))
            r1 = int(r0 * 2.0) + 1
            y0, y1 = max(0, yi - r1), min(h, yi + r1 + 1)
            x0, x1 = max(0, xi - r1), min(w, xi + r1 + 1)
            if y1 <= y0 or x1 <= x0:
                continue
            dy = np.abs(np.arange(y0, y1, dtype=np.float32) - yi)[:, None]
            dx = np.abs(np.arange(x0, x1, dtype=np.float32) - xi)[None, :]
            dd = dy + dx
            body = dd <= r0
            vM = float(rngM.uniform(0.93, 1.0)) if ign[i] else float(rngM.uniform(0.55, 0.66))
            M[y0:y1, x0:x1][body] = vM
            ring = np.abs(dd - r0 * 1.7) <= 0.9
            pol = rngR.random() < 0.5
            vR = float(rngR.uniform(0.06, 0.22)) if pol else float(rngR.uniform(0.78, 0.94))
            R[y0:y1, x0:x1][ring] = vR
            CC[y0:y1, x0:x1][dd <= max(1, r0 // 2)] = float(rngC.uniform(0.62, 0.80))

    out = np.stack([np.clip(M, 0.0, 1.0), np.clip(R, 0.0, 1.0), np.clip(CC, 0.0, 1.0)],
                   axis=-1).astype(np.float32)
    if sm > 1.0:
        sm = 1.0 + (sm - 1.0) * 0.42
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
spec_lfr_starfield_scatter._spb_concept_complete = True


# --- IGNITION: spec_lfr_corridor_sheen ---
def spec_lfr_corridor_sheen(shape, seed, sm, num_lane_sets=4, **kwargs):
    '''spec_lfr_corridor_sheen -- 2026-06-10 rebuild: beacon lanes.

    ONE motif system: a multi-angle family of serpentine sheen corridors.
    Every lane family rides its own random angle off one random base
    rotation; all families share one low-frequency domain warp plus one
    lane-shift field, so corridors bend, drift and branch -- never
    ruler-straight, never upright (UV-orientation-agnostic). The channels
    ride three ASPECTS of that same lane system:
      M  = lane BODIES of the calm families: feathered gloss corridors with
           9-16 px micro-ribbing inside, plus a faint ghost of the beacon
           family -- restrained, max ~0.65.
      R  = lane EDGES: signed boundary ridges of the same calm corridors,
           alternating polished (low R) / scuffed (high R) lane by lane.
      Cc = the BEACON family (ignition): one wide low-frequency corridor
           family at its own angle, detonated near-max with hot micro-ribs
           and a thin squared edge liner -- the clearcoat explodes along
           those lanes when the sun sweeps them; everything else is quiet.
    Calm surroundings; single detonating channel (Cc); hot(>200) area 5-15%.
    '''
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    mn = float(min(h, w))
    yy = np.arange(h, dtype=np.float32)[:, None]
    xx = np.arange(w, dtype=np.float32)[None, :]

    rngS = np.random.default_rng(int(seed) + 59)
    rngM = np.random.default_rng(int(seed) + 131)
    rngR = np.random.default_rng(int(seed) + 233)
    rngC = np.random.default_rng(int(seed) + 349)

    n_set = int(np.clip(num_lane_sets, 3, 6))
    calm_n = max(2, n_set - 2)
    two_pi = 2.0 * np.pi
    warp = (_normalize(_spb_fast_smooth_noise((h, w), [mn * 0.05, mn * 0.015], [0.6, 0.4],
                                              int(seed) + 431, max_dim=512)) - 0.5).astype(np.float32)
    shift = (_normalize(_spb_fast_smooth_noise((h, w), [mn * 0.08, mn * 0.03], [0.6, 0.4],
                                               int(seed) + 523, max_dim=512)) - 0.5).astype(np.float32)

    subM = _normalize(_spb_fast_smooth_noise((h, w), [2.5, 9.0], [0.6, 0.4], int(seed) + 131,
                                             max_dim=512))
    subR = _normalize(_spb_fast_smooth_noise((h, w), [3.0, 12.0], [0.55, 0.45], int(seed) + 233,
                                             max_dim=512))
    subC = _normalize(_spb_fast_smooth_noise((h, w), [4.0, 15.0], [0.5, 0.5], int(seed) + 349,
                                             max_dim=512))
    M = (0.34 + (subM - 0.5) * 0.10).astype(np.float32)
    R = (0.50 + (subR - 0.5) * 0.12).astype(np.float32)
    CC = (0.42 + (subC - 0.5) * 0.10).astype(np.float32)

    a0 = float(rngS.uniform(0.0, np.pi))
    laneM = np.zeros((h, w), dtype=np.float32)
    edgeR = np.zeros((h, w), dtype=np.float32)
    px_scale = max(mn / 2048.0, 0.25)
    wampA = np.float32(mn * 0.03)
    for i in range(calm_n):
        ai = a0 + (i + 1) * (np.pi / (calm_n + 1)) + float(rngS.uniform(-0.22, 0.22))
        u = float(rngS.uniform(7.0, 13.0))
        ph = float(rngS.uniform(0.0, two_pi))
        proj = xx * np.float32(np.cos(ai)) + yy * np.float32(np.sin(ai)) + warp * wampA
        t = np.sin(proj * np.float32(two_pi * u / mn) + np.float32(ph))
        t += shift * np.float32(1.1)
        lane = _smoothstep(0.55, 0.80, t).astype(np.float32)
        ribp = float(rngM.uniform(9.0, 16.0)) * px_scale
        rib = (0.5 + 0.5 * np.sin(proj * np.float32(two_pi / max(ribp, 2.0)))).astype(np.float32)
        laneM = np.maximum(laneM, lane * (np.float32(0.18) + np.float32(0.10) * rib))
        edge = (lane * (1.0 - lane) * 4.0).astype(np.float32)
        pol = np.sign(np.sin(proj * np.float32(two_pi * u * 0.5 / mn)
                             + np.float32(rngR.uniform(0.0, two_pi)))).astype(np.float32)
        edgeR += edge * pol

    ab = a0 + float(rngS.uniform(-0.30, 0.30))
    ub = float(rngS.uniform(2.6, 4.2))
    phb = float(rngS.uniform(0.0, two_pi))
    phb2 = float(rngS.uniform(0.0, two_pi))
    wampB = np.float32(mn * 0.055)
    projb = xx * np.float32(np.cos(ab)) + yy * np.float32(np.sin(ab)) + warp * wampB
    tb = np.sin(projb * np.float32(two_pi * ub / mn) + np.float32(phb))
    tb += np.float32(0.55) * np.sin(projb * np.float32(two_pi * ub * 2.717 / mn) + np.float32(phb2))
    tb *= np.float32(1.0 / 1.55)
    tb += shift * np.float32(0.5)
    lane_b = _smoothstep(0.50, 0.68, tb).astype(np.float32)
    ribpb = float(rngC.uniform(14.0, 22.0)) * px_scale
    rib_b = _smoothstep(0.05, 0.60, np.sin(projb * np.float32(two_pi / max(ribpb, 2.0)))).astype(np.float32)
    lane_bw = _smoothstep(0.44, 0.74, tb).astype(np.float32)
    liner = (lane_bw * (1.0 - lane_bw) * 4.0).astype(np.float32)

    M = np.clip(M + laneM + lane_b * np.float32(0.05), 0.0, 1.0)
    R = np.clip(R + edgeR * np.float32(0.22), 0.0, 1.0)
    hot = lane_b * (np.float32(0.44) + np.float32(0.54) * rib_b)
    CC = np.maximum(CC, hot)
    CC = np.maximum(CC, liner * liner * np.float32(0.90))
    CC = np.clip(CC, 0.0, 1.0)

    out = np.stack([M, R, CC], axis=-1).astype(np.float32)
    if sm > 1.0:
        sm = 1.0 + (sm - 1.0) * 0.42
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
spec_lfr_corridor_sheen._spb_concept_complete = True


# --- IGNITION: spec_lfr_firework_radial ---
def spec_lfr_firework_radial(shape, seed, sm, num_bursts=22, **kwargs):
    '''spec_lfr_firework_radial -- Let Freedom Ring: Finale Over The Harbor.

    ONE motif system: a single shared list of chrysanthemum shellbursts
    (one event rng builds every center / reach / spoke-count / heading).
    Each channel rides a different ASPECT of those same bursts:
      M  = spoke-comet skeletons (bright hubs fading to dark tips),
      R  = signed concussion annuli on the SAME centers (alternating
           gloss/rough shock rings),
      Cc = quiet powder haze that DETONATES only on the designed finale
           subset (~1 in 3 shells): a chrysanthemum corona striated along
           the EXACT spoke angles of the M skeleton (~230-255 core) plus
           peony tip-stars stamped on the exact spoke-tip pixels --
           invisible at most angles, explodes when the sun lines up.
    Scattered centers + purely radial geometry = UV-orientation-agnostic.
    '''
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    mn = min(h, w)
    scale = max(mn / 2048.0, 0.25)

    rngE = np.random.default_rng(int(seed) + 17)
    rngM = np.random.default_rng(int(seed) + 113)
    rngR = np.random.default_rng(int(seed) + 229)
    rngC = np.random.default_rng(int(seed) + 337)

    nb = int(np.clip(num_bursts * scale * scale * 3 + num_bursts, 16, 96))
    bursts = []
    for _bi in range(nb):
        bx = float(rngE.uniform(0.04, 0.96)) * w
        by = float(rngE.uniform(0.04, 0.96)) * h
        reach = float(rngE.uniform(30.0, 78.0)) * scale
        n_spk = int(rngE.integers(12, 26))
        a0 = float(rngE.uniform(0.0, 2.0 * np.pi))
        finale = bool(rngE.random() < 0.34)
        bursts.append((bx, by, reach, n_spk, a0, finale))

    gM = _normalize(_spb_fast_smooth_noise((h, w), [2.0, 7.0], [0.6, 0.4], int(seed) + 113))
    gR = _normalize(_spb_fast_smooth_noise((h, w), [3.0, 10.0], [0.55, 0.45], int(seed) + 229))
    gC = _normalize(_spb_fast_smooth_noise((h, w), [5.0, 14.0], [0.5, 0.5], int(seed) + 337))
    M = (0.30 + (gM - 0.5) * 0.10).astype(np.float32)
    R = (0.55 + (gR - 0.5) * 0.14).astype(np.float32)
    CC = (0.46 + (gC - 0.5) * 0.06).astype(np.float32)

    for (bx, by, reach, n_spk, a0, finale) in bursts:
        cx = int(bx)
        cy = int(by)
        tips = []
        if _CV2_OK:
            for i in range(n_spk):
                ang = a0 + i * (2.0 * np.pi / n_spk)
                ca = float(np.cos(ang))
                sa = float(np.sin(ang))
                px = cx
                py = cy
                for seg in range(3):
                    t1 = (seg + 1) / 3.0
                    qx = int(min(max(bx + ca * reach * t1, 0), w - 1))
                    qy = int(min(max(by + sa * reach * t1, 0), h - 1))
                    val = 0.90 - seg * 0.26 + float(rngM.uniform(-0.04, 0.04))
                    _cv2.line(M, (px, py), (qx, qy), float(min(max(val, 0.12), 0.97)), 1, lineType=_cv2.LINE_AA)
                    px = qx
                    py = qy
                tips.append((px, py))
            _cv2.circle(M, (cx, cy), max(2, int(2.5 * scale)), float(rngM.uniform(0.86, 0.96)), -1, lineType=_cv2.LINE_AA)
            for k, frac in enumerate((0.34, 0.58, 0.82, 1.04)):
                rr = max(2, int(reach * frac))
                glossy = (k % 2 == 0)
                rv = float(rngR.uniform(0.08, 0.24)) if glossy else float(rngR.uniform(0.78, 0.93))
                _cv2.circle(R, (cx, cy), rr, rv, 1, lineType=_cv2.LINE_AA)

        crad = reach * 1.45
        pad = int(crad) + 4
        x0 = max(0, cx - pad)
        x1 = min(w, cx + pad + 1)
        y0 = max(0, cy - pad)
        y1 = min(h, cy + pad + 1)
        if x1 <= x0 or y1 <= y0:
            continue
        wy = np.arange(y0, y1, dtype=np.float32)[:, None] - by
        wx = np.arange(x0, x1, dtype=np.float32)[None, :] - bx
        rad = np.sqrt(wx * wx + wy * wy) + 1e-6
        th = np.arctan2(wy, wx)
        if not _CV2_OK:
            t = rad / max(reach, 1e-3)
            spoke = _smoothstep(0.90, 0.995, np.cos((th - a0) * n_spk)) * np.clip(1.05 - t, 0.0, 1.0)
            M[y0:y1, x0:x1] = np.maximum(M[y0:y1, x0:x1], (0.30 + 0.62 * spoke).astype(np.float32))
            ringv = 0.55 + 0.34 * np.sin(t * np.pi * 6.0) * np.exp(-t * 1.1) * float(rngR.uniform(0.7, 1.0))
            band = (t < 1.1).astype(np.float32) * 0.75
            R[y0:y1, x0:x1] = R[y0:y1, x0:x1] * (1.0 - band) + ringv.astype(np.float32) * band

        if finale:
            bloom = 1.0 - _smoothstep(0.34, 1.0, rad / max(crad, 1e-3))
            spoke_cos = 0.5 + 0.5 * np.cos((th - a0) * n_spk)
            corona = (0.46 + 0.54 * (0.78 + 0.22 * spoke_cos)).astype(np.float32)
            alpha = (bloom * (0.84 + 0.16 * spoke_cos)).astype(np.float32)
            win = CC[y0:y1, x0:x1]
            CC[y0:y1, x0:x1] = win * (1.0 - alpha) + corona * alpha
            if _CV2_OK:
                star_r = max(2, int(2.6 * scale))
                for (tx, ty) in tips:
                    _cv2.circle(CC, (tx, ty), star_r, float(rngC.uniform(0.93, 1.0)), -1, lineType=_cv2.LINE_AA)
        elif _CV2_OK:
            _cv2.circle(CC, (cx, cy), max(3, int(reach * 0.5)), float(rngC.uniform(0.54, 0.62)), 1, lineType=_cv2.LINE_AA)

    out = np.stack([np.clip(M, 0.0, 1.0), np.clip(R, 0.0, 1.0), np.clip(CC, 0.0, 1.0)], axis=-1).astype(np.float32)
    smc = float(sm)
    if smc > 1.0:
        out = (0.5 + (out - 0.5) * ((1.0 + 0.42 * (smc - 1.0)) / smc)).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
spec_lfr_firework_radial._spb_concept_complete = True


# --- IGNITION: spec_lfr_brocade_relief ---
def spec_lfr_brocade_relief(shape, seed, sm, scale_px=26, **kwargs):
    '''spec_lfr_brocade_relief -- Let Freedom Ring: Struck-Gold Brocade.

    ONE motif system: a tri-axial woven thread lattice (three hairline
    thread families ~60 deg apart at a seed-random base angle, so the
    weave lands rotation-proof on any UV) studded with rosette medallions
    sewn onto that SAME lattice. Aspects of the one system:
      M  = the fine thread hairlines (calm relief) plus the IGNITION --
           a designed struck subset (~half) of medallions whose gold
           cores blaze at ~230-255 in M only, with the thread texture
           woven straight through the blaze and petal arcs ringing it;
      R  = the weave's over/under parity lozenges (signed satin/matte
           cells) plus a matte moat ringing every medallion so each
           strike reads against a quiet ring of cloth;
      Cc = broad damask sheen pools riding the same thread coordinates
           plus thin bright rim halos at the medallion edges.
    Calm everywhere else -- the strike only reads against quiet.
    '''
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    mn = min(h, w)
    scale = max(mn / 2048.0, 0.25)
    sp = max(7.0, float(scale_px) * 0.5 * scale)

    rngE = np.random.default_rng(int(seed) + 23)
    rngM = np.random.default_rng(int(seed) + 131)
    rngR = np.random.default_rng(int(seed) + 241)
    rngC = np.random.default_rng(int(seed) + 359)

    yy = np.arange(h, dtype=np.float32)[:, None]
    xx = np.arange(w, dtype=np.float32)[None, :]
    th0 = float(rngE.uniform(0.0, np.pi))
    us = []
    for k in range(3):
        ang = th0 + k * (np.pi / 3.0) + float(rngE.uniform(-0.07, 0.07))
        us.append((xx * float(np.cos(ang)) + yy * float(np.sin(ang))).astype(np.float32))

    gA = _normalize(_spb_fast_smooth_noise((h, w), [3.0, 9.0], [0.55, 0.45], int(seed) + 131))
    gB = _normalize(_spb_fast_smooth_noise((h, w), [6.0, 16.0], [0.5, 0.5], int(seed) + 241))

    threads = np.zeros((h, w), dtype=np.float32)
    for k in range(3):
        f = us[k] / sp
        d = np.abs(f - np.round(f))
        lk = 1.0 - _smoothstep(0.05, 0.115, d)
        gain = float(rngM.uniform(0.78, 1.0)) * (0.72 + 0.28 * np.roll(gA, (k + 1) * 311, axis=k % 2))
        threads = np.maximum(threads, (lk * gain).astype(np.float32))
    M = (0.40 + (gA - 0.5) * 0.07 + threads * 0.22).astype(np.float32)

    par = (np.floor(us[0] / sp) + np.floor(us[1] / sp) + np.floor(us[2] / sp)) % 2.0
    R = (0.55 + (par - 0.5) * 0.26 * (0.6 + 0.4 * gB) + (gB - 0.5) * 0.10 + float(rngR.uniform(-0.02, 0.02))).astype(np.float32)

    pool = (np.sin(us[0] / (sp * 5.3)) * np.sin(us[1] / (sp * 6.1) + 1.7) + np.sin(us[2] / (sp * 5.7) + 3.1)) * 0.5
    CC = (0.46 + pool * 0.11 + (gB - 0.5) * 0.05 + float(rngC.uniform(-0.02, 0.02))).astype(np.float32)

    nmed = int(np.clip(30 * scale * scale + 18, 14, 72))
    for _mi in range(nmed):
        bx = float(rngE.uniform(0.05, 0.95)) * w
        by = float(rngE.uniform(0.05, 0.95)) * h
        rad = float(rngE.uniform(50.0, 105.0)) * scale
        struck = bool(rngE.random() < 0.55)
        pad = int(rad * 1.55) + 4
        cx = int(bx)
        cy = int(by)
        x0 = max(0, cx - pad)
        x1 = min(w, cx + pad + 1)
        y0 = max(0, cy - pad)
        y1 = min(h, cy + pad + 1)
        if x1 <= x0 or y1 <= y0:
            continue
        wy = np.arange(y0, y1, dtype=np.float32)[:, None] - by
        wx = np.arange(x0, x1, dtype=np.float32)[None, :] - bx
        rr = np.sqrt(wx * wx + wy * wy)
        rim = 1.0 - _smoothstep(1.2, 2.6, np.abs(rr - rad))
        CC[y0:y1, x0:x1] = np.maximum(CC[y0:y1, x0:x1], (0.46 + rim * float(rngC.uniform(0.24, 0.32))).astype(np.float32))
        moat = _smoothstep(rad * 1.02, rad * 1.12, rr) * (1.0 - _smoothstep(rad * 1.30, rad * 1.50, rr))
        R[y0:y1, x0:x1] = np.maximum(R[y0:y1, x0:x1], (0.55 + moat * float(rngR.uniform(0.22, 0.30))).astype(np.float32))
        if struck:
            bloom = 1.0 - _smoothstep(rad * 0.58, rad * 1.00, rr)
            tw = threads[y0:y1, x0:x1]
            blaze = (0.46 + 0.53 * bloom * (0.86 + 0.14 * tw)).astype(np.float32)
            M[y0:y1, x0:x1] = np.maximum(M[y0:y1, x0:x1], blaze)
            if _CV2_OK:
                n_pet = int(rngM.integers(7, 12))
                pr = max(3, int(rad * 0.62))
                for p in range(n_pet):
                    pa = (360.0 / n_pet) * p + float(rngM.uniform(-6.0, 6.0))
                    _cv2.ellipse(M, (cx, cy), (pr, max(2, int(pr * 0.42))), pa, 200, 340, float(rngM.uniform(0.90, 0.99)), 1, lineType=_cv2.LINE_AA)
        else:
            petal = 1.0 - _smoothstep(0.8, 2.0, np.abs(rr - rad * 0.55))
            M[y0:y1, x0:x1] = np.maximum(M[y0:y1, x0:x1], (0.40 + petal * float(rngM.uniform(0.14, 0.20))).astype(np.float32))

    out = np.stack([np.clip(M, 0.0, 1.0), np.clip(R, 0.0, 1.0), np.clip(CC, 0.0, 1.0)], axis=-1).astype(np.float32)
    smc = float(sm)
    if smc > 1.0:
        out = (0.5 + (out - 0.5) * ((1.0 + 0.42 * (smc - 1.0)) / smc)).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
spec_lfr_brocade_relief._spb_concept_complete = True


# --- IGNITION: spec_lfr_liberty_colorflip ---
def spec_lfr_liberty_colorflip(shape, seed, sm, num_waves=5, **kwargs):
    """spec_lfr_liberty_colorflip.

    identity: Let Freedom Ring -- BELL-STRIKE COLORFLIP. One motif system:
    scattered 'liberty bell' epicenters, each ringing concentric ripple
    crests outward (radial + scattered = UV-orientation-agnostic). The
    FLIP: successive rings alternate between two interleaved families --
    odd rings carry the metallic flash (M), even rings carry the clearcoat
    flash (Cc) -- so the panel flips identity as the light angle sweeps.
    IGNITION: a designed subset of bells detonates -- inside their basins
    the even rings are traced near-max in Cc while everything else stays
    calm. R rides a third aspect of the same system: the slow resonance
    interference between ALL the bells (smooth signed sheen pools).
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    mn = float(min(h, w))
    sc = max(mn / 2048.0, 0.25)
    yy = np.arange(h, dtype=np.float32)[:, None]
    xx = np.arange(w, dtype=np.float32)[None, :]

    # --- ONE shared motif system: scattered bell-strike epicenters ---
    n_src = int(np.clip(round(2.4 * max(3, int(num_waves))), 8, 24))
    rngS = np.random.default_rng(int(seed) + 101)
    cxs = (rngS.uniform(-0.06, 1.06, n_src) * (w - 1)).astype(np.float32)
    cys = (rngS.uniform(-0.06, 1.06, n_src) * (h - 1)).astype(np.float32)
    lam = (rngS.uniform(13.0, 21.0, n_src) * sc).astype(np.float32)
    ph0 = rngS.uniform(0.0, 1.0, n_src).astype(np.float32)
    n_det = max(2, int(round(n_src * 0.5)))
    det = np.zeros(n_src, dtype=bool)
    det[rngS.permutation(n_src)[:n_det]] = True

    # nearest-bell distance + basin id (small vectorized source loop)
    d2min = np.full((h, w), np.inf, dtype=np.float32)
    idx = np.zeros((h, w), dtype=np.int16)
    for i in range(n_src):
        d2 = (xx - cxs[i]) ** 2 + (yy - cys[i]) ** 2
        m = d2 < d2min
        d2min[m] = d2[m]
        idx[m] = np.int16(i)
    d = np.sqrt(d2min)

    lam_map = lam[idx]
    t = d / lam_map + ph0[idx]              # ring coordinate of the owning bell
    f = t - np.floor(t)
    df = np.minimum(f, 1.0 - f)             # distance to nearest crest (periods)
    ring_n = np.floor(t + 0.5).astype(np.int32)
    odd = (ring_n & 1).astype(np.float32)   # whole-ring family parity
    even = 1.0 - odd
    crest = (1.0 - _smoothstep(0.07, 0.18, df)).astype(np.float32)   # 3-7 px lines
    ring_out = (1.0 - _smoothstep(11.0, 17.0, d / lam_map)).astype(np.float32)
    hot = det[idx].astype(np.float32) * ring_out

    # --- M: odd-ring metallic comb, restrained everywhere ---
    rngM = np.random.default_rng(int(seed) + 211)
    ampM = (0.70 + 0.30 * rngM.random(n_src).astype(np.float32))[idx]
    M = (0.38 + crest * odd * 0.33 * ampM).astype(np.float32)
    spk = rngM.random((h, w)).astype(np.float32)
    M = M + (spk > 0.994).astype(np.float32) * np.float32(0.16) * (0.4 + 0.6 * crest)

    # --- Cc: even-ring flip comb; DETONATES inside the chosen basins ---
    rngC = np.random.default_rng(int(seed) + 431)
    ampC = (0.90 + 0.10 * rngC.random(n_src).astype(np.float32))[idx]
    calm = (0.44 + 0.06 * np.cos(t * np.float32(2.0 * np.pi))).astype(np.float32)
    CC = calm + crest * even * np.float32(0.16)
    blast = (1.0 - _smoothstep(0.12, 0.30, df)).astype(np.float32) * even * hot * ampC
    CC = np.maximum(CC, blast * np.float32(0.97))

    # --- R: slow resonance interference between ALL bells (3rd aspect) ---
    ds = 4 if mn >= 1024 else 1
    xs = xx[:, ::ds]
    ys = yy[::ds]
    acc = np.zeros((ys.shape[0], xs.shape[1]), dtype=np.float32)
    twopi = np.float32(2.0 * np.pi)
    for i in range(n_src):
        dd = np.sqrt((xs - cxs[i]) ** 2 + (ys - cys[i]) ** 2)
        acc += np.sin(dd / (lam[i] * np.float32(3.1)) * twopi + ph0[i] * twopi) * \
               np.exp(-dd / np.float32(0.55 * mn))
    acc = _gauss(acc, sigma=max(1.5, 2.5 * sc))
    if _CV2_OK:
        res = _cv2.resize(np.ascontiguousarray(acc, dtype=np.float32), (w, h),
                          interpolation=_cv2.INTER_LINEAR)
    else:
        res = np.repeat(np.repeat(acc, ds, 0), ds, 1)[:h, :w]
    R = (0.52 + (_normalize(res) - 0.5) * 0.40).astype(np.float32)

    out = np.stack([M, R, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0, 1), sm)
spec_lfr_liberty_colorflip._spb_concept_complete = True


# --- IGNITION: spec_lfr_anisotropic_drift ---
def _lfr_opt_smear_field(noise, ang, length, xx, yy, step=1):
    h, w = noise.shape
    if not _CV2_OK:
        acc = noise.copy()
        cnt = 1.0
        for s in range(1, length + 1):
            dx = np.cos(ang) * (s * step)
            dy = np.sin(ang) * (s * step)
            xi = np.clip((xx + dx).astype(np.int32), 0, w - 1)
            yi = np.clip((yy + dy).astype(np.int32), 0, h - 1)
            acc = acc + noise[yi, xi]
            xi2 = np.clip((xx - dx).astype(np.int32), 0, w - 1)
            yi2 = np.clip((yy - dy).astype(np.int32), 0, h - 1)
            acc = acc + noise[yi2, xi2]
            cnt += 2.0
        return _normalize(acc / cnt)
    ca = np.cos(ang)
    sa = np.sin(ang)
    acc = noise.copy()
    B = 128

    def _run_blocks(starts):
        for r0 in starts:
            r1 = min(h, r0 + B)
            bh = r1 - r0
            cab = ca[r0:r1]; sab = sa[r0:r1]
            yb = yy[r0:r1]
            ab = acc[r0:r1]
            mp = np.empty((2 * bh, w, 2), dtype=np.int16)
            fb = np.empty((bh, w), dtype=np.float32)
            db = np.empty((2 * bh, w), dtype=np.float32)
            dxb = np.empty((bh, w), dtype=np.float32)
            dyb = np.empty((bh, w), dtype=np.float32)
            for s in range(1, length + 1):
                sf = np.float32(s * step)
                np.multiply(cab, sf, out=dxb)
                np.multiply(sab, sf, out=dyb)
                np.add(xx, dxb, out=fb); mp[:bh, :, 0] = fb
                np.add(yb, dyb, out=fb); mp[:bh, :, 1] = fb
                np.subtract(xx, dxb, out=fb); mp[bh:, :, 0] = fb
                np.subtract(yb, dyb, out=fb); mp[bh:, :, 1] = fb
                _cv2.remap(noise, mp, None, _cv2.INTER_NEAREST, dst=db,
                           borderMode=_cv2.BORDER_REPLICATE)
                np.add(ab, db[:bh], out=ab)
                np.add(ab, db[bh:], out=ab)

    blocks = list(range(0, h, B))
    if h >= 1024 and len(blocks) >= 3:
        try:
            from concurrent.futures import ThreadPoolExecutor as _TPE
            with _TPE(max_workers=3) as _ex:
                list(_ex.map(_run_blocks, [blocks[i::3] for i in range(3)]))
        except Exception:
            _run_blocks(blocks)
    else:
        _run_blocks(blocks)
    cnt = float(1 + 2 * length)
    return _normalize(acc / cnt)

def spec_lfr_anisotropic_drift(shape, seed, sm, **kwargs):
    """spec_lfr_anisotropic_drift.

    identity: Let Freedom Ring -- METEOR DRIFT. ONE divergence-free curl
    drift field is the entire motif system and every channel rides a
    different ASPECT of it. R = anisotropic brushed micro-grain advected
    ALONG the flow (the calm satin metal itself, signed around mid). M =
    IGNITION: the top-speed drift corridors become hot metallic lanes and
    comet streaks -- particles stepped along the SAME flow -- blaze
    near-max inside them; invisible at most angles, the corridors detonate
    when the sun lines up. Cc = smooth eddy pools at the vortex cores
    (band-pass of the same potential). The flow turns through every
    direction -- UV-orientation-agnostic, no stripes, no flag geometry.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    mn = float(min(h, w))
    sc = max(mn / 2048.0, 0.25)
    yy = np.arange(h, dtype=np.float32)[:, None]
    xx = np.arange(w, dtype=np.float32)[None, :]

    # --- ONE shared drift system: smooth curl-noise potential ---
    rngF = np.random.default_rng(int(seed) + 137)
    dsf = 8 if mn >= 1024 else 4
    ph_ = max(96, (h + dsf - 1) // dsf)
    pw_ = max(96, (w + dsf - 1) // dsf)
    pot_s = _gauss(rngF.random((ph_, pw_)).astype(np.float32),
                   sigma=max(4.0, min(ph_, pw_) * 0.05)).astype(np.float32)
    if _CV2_OK:
        pot = _cv2.resize(pot_s, (w, h), interpolation=_cv2.INTER_CUBIC)
    else:
        pot = np.repeat(np.repeat(pot_s, dsf, 0), dsf, 1)[:h, :w]
        pot = _gauss(pot, sigma=float(dsf)).astype(np.float32)
    gy, gx = np.gradient(pot)
    gx = gx.astype(np.float32, copy=False)
    gy = gy.astype(np.float32, copy=False)
    ang = np.arctan2(gx, -gy).astype(np.float32)        # flow direction (curl)
    spd = _normalize(np.sqrt(gx * gx + gy * gy)).astype(np.float32)
    sub = spd[::max(1, h // 256), ::max(1, w // 256)]
    lane = _smoothstep(float(np.quantile(sub, 0.80)),
                       float(np.quantile(sub, 0.93)), spd).astype(np.float32)

    # --- M: IGNITION -- hot drift corridors + comet streaks on the flow ---
    rngM = np.random.default_rng(int(seed) + 173)
    M = (0.34 + lane * 0.50).astype(np.float32)
    if _CV2_OK:
        n_cm = int(np.clip(1400.0 * sc * sc, 220, 4200))
        px = rngM.uniform(0, w - 1, n_cm).astype(np.float32)
        py = rngM.uniform(0, h - 1, n_cm).astype(np.float32)
        sp0 = spd[py.astype(np.int32), px.astype(np.int32)]
        keep = sp0 > float(np.quantile(sub, 0.55))
        px = px[keep]; py = py[keep]
        n_keep = int(px.shape[0])
        if n_keep > 0:
            steps = max(6, int(round(10.0 * sc)))
            seg = max(2.0, 2.6 * sc)
            pts = np.empty((steps + 1, n_keep, 2), dtype=np.float32)
            pts[0, :, 0] = px; pts[0, :, 1] = py
            cx = px.copy(); cy = py.copy()
            for s in range(steps):
                ai = ang[np.clip(cy.astype(np.int32), 0, h - 1),
                         np.clip(cx.astype(np.int32), 0, w - 1)]
                cx = cx + np.cos(ai) * np.float32(seg)
                cy = cy + np.sin(ai) * np.float32(seg)
                pts[s + 1, :, 0] = cx; pts[s + 1, :, 1] = cy
            streak = np.zeros((h, w), dtype=np.float32)
            poly = np.round(pts.transpose(1, 0, 2)).astype(np.int32)
            bright = rngM.uniform(0.78, 1.0, n_keep).astype(np.float32)
            order = np.argsort(bright)
            nb = 5
            for b in range(nb):
                sel = order[(b * n_keep) // nb:((b + 1) * n_keep) // nb]
                if sel.size:
                    _cv2.polylines(streak, [np.ascontiguousarray(poly[j]) for j in sel], False,
                                   float(bright[sel].mean()), 1,
                                   lineType=_cv2.LINE_AA)
            hxs = np.clip(np.round(px).astype(np.int32), 0, w - 1)
            hys = np.clip(np.round(py).astype(np.int32), 0, h - 1)
            streak[hys, hxs] = 1.0
            comet = np.clip(streak + _gauss(streak, sigma=1.2) * 0.9, 0.0, 1.0)
            M = np.maximum(M, comet * np.float32(0.98))
    else:
        g = rngM.random((h, w)).astype(np.float32)
        M = np.maximum(M, (g > 0.995).astype(np.float32) * np.float32(0.95)
                       * (0.4 + 0.6 * lane))

    # --- R: brushed micro-grain advected ALONG the same flow (calm, signed) ---
    rngR = np.random.default_rng(int(seed) + 277)
    nR = rngR.random((h, w)).astype(np.float32)
    L = max(4, int(round(mn * 0.007)))
    brush = _lfr_opt_smear_field(nR, ang, L, xx, yy)
    R = (0.52 + (brush - 0.5) * (0.30 + 0.16 * lane)).astype(np.float32)

    # --- Cc: smooth eddy pools at the vortex cores (band-pass, 3rd aspect) ---
    rngC = np.random.default_rng(int(seed) + 389)
    s1 = max(1.5, min(ph_, pw_) * 0.018)
    dog_s = (_gauss(pot_s, s1) - _gauss(pot_s, s1 * 2.6)).astype(np.float32)
    if _CV2_OK:
        dog = _cv2.resize(dog_s, (w, h), interpolation=_cv2.INTER_LINEAR)
    else:
        dog = np.repeat(np.repeat(dog_s, dsf, 0), dsf, 1)[:h, :w]
    CC = (0.46 + (_normalize(dog) - 0.5) * 0.34).astype(np.float32)
    frost = rngC.random((h, w)).astype(np.float32)
    CC = CC + (frost > 0.9965).astype(np.float32) * np.float32(0.20) * (0.3 + 0.7 * (1.0 - lane))

    out = np.stack([M, R, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0, 1), sm)
spec_lfr_anisotropic_drift._spb_concept_complete = True


# --- IGNITION: spec_lfr_sparkler_embers ---
def spec_lfr_sparkler_embers(shape, seed, sm, spark_density=0.010, **kwargs):
    """spec_lfr_sparkler_embers.

    identity: Let Freedom Ring — whirled-sparkler light-writing: curved
    comet trails whipped at every angle over a soot-quiet field. ONE
    motif system (the whirl arcs) carries all three channels as
    different aspects: M = the trail cores, with a DESIGNED ~1/3 "live"
    subset detonating near-max while the rest stay calm (ignition);
    R = signed heat-wake rims hugging the SAME arcs (glossy rim on one
    side, sooty rim on the other, polarity flips per arc); Cc = ember
    beads strung along the SAME trails plus blooms at the trail heads.
    UV-agnostic (arcs at every angle and curvature), trail features
    2-6 px at 2048.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    if sm > 1.0:
        sm = 1.0 + (sm - 1.0) * 0.42   # damped contrast above 1.0 — never flat-white clip
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)
    rngM = np.random.default_rng(int(seed) + 67)
    rngR = np.random.default_rng(int(seed) + 389)
    rngC = np.random.default_rng(int(seed) + 911)

    # calm ambient substrates (the explosion only reads against quiet)
    gM = _normalize(_spb_fast_smooth_noise((h, w), [9.0, 24.0], [0.55, 0.45], int(seed) + 67))
    gR = _normalize(_spb_fast_smooth_noise((h, w), [6.0, 16.0, 38.0], [0.40, 0.35, 0.25], int(seed) + 389))
    gC = _normalize(_spb_fast_smooth_noise((h, w), [12.0, 30.0], [0.5, 0.5], int(seed) + 911))
    M = (0.30 + (gM - 0.5) * 0.10).astype(np.float32)
    R = (0.50 + (gR - 0.5) * 0.16).astype(np.float32)
    CC = (0.36 + (gC - 0.5) * 0.10).astype(np.float32)

    def _stamp(canvas, ys, xs, vals, offs):
        # windowed point splats — vectorized, no per-pixel python loops
        for dy, dx in offs:
            yy = ys + dy; xx = xs + dx
            ok = (yy >= 0) & (yy < h) & (xx >= 0) & (xx < w)
            canvas[yy[ok], xx[ok]] = np.maximum(canvas[yy[ok], xx[ok]], vals[ok])

    offs5 = ((0, 0), (0, 1), (0, -1), (1, 0), (-1, 0))
    offs13 = offs5 + ((1, 1), (1, -1), (-1, 1), (-1, -1), (0, 2), (0, -2), (2, 0), (-2, 0))

    # ---- ONE motif system: whirled trail arcs (geometry from rngM) ----
    n_arc = int(np.clip(620 * scale * scale + 200, 160, 1600))
    n_arc = int(np.clip(n_arc * (max(spark_density, 1e-4) / 0.010) ** 0.5, 120, 2200))
    cx = rngM.uniform(0, w, n_arc).astype(np.float32)
    cy = rngM.uniform(0, h, n_arc).astype(np.float32)
    rad = (rngM.uniform(60.0, 170.0, n_arc) * scale).astype(np.float32)
    a0 = rngM.uniform(0, 2 * np.pi, n_arc).astype(np.float32)
    sgn = np.where(rngM.random(n_arc) < 0.5, -1.0, 1.0).astype(np.float32)
    swp = rngM.uniform(1.2, 3.4, n_arc).astype(np.float32) * sgn
    wob_a = (rngM.uniform(2.0, 6.0, n_arc) * scale).astype(np.float32)
    wob_f = rngM.uniform(2.0, 5.0, n_arc).astype(np.float32)
    wob_p = rngM.uniform(0, 2 * np.pi, n_arc).astype(np.float32)
    live = rngM.random(n_arc) < 0.34          # DESIGNED ignition subset

    n_s = 384
    t = np.linspace(0.0, 1.0, n_s, dtype=np.float32)[None, :]
    ang = a0[:, None] + swp[:, None] * t
    rr = rad[:, None] + wob_a[:, None] * np.sin(t * wob_f[:, None] * 2.0 * np.pi + wob_p[:, None])
    ca = np.cos(ang); sa = np.sin(ang)
    px = cx[:, None] + ca * rr
    py = cy[:, None] + sa * rr
    vM = np.where(live[:, None], 0.90 + 0.10 * t, 0.50 + 0.12 * t).astype(np.float32)

    xi = np.rint(px).astype(np.int64).ravel()
    yi = np.rint(py).astype(np.int64).ravel()
    vv = vM.ravel()
    lv = np.repeat(live, n_s)

    core = np.zeros((h, w), dtype=np.float32)
    _stamp(core, yi[~lv], xi[~lv], vv[~lv], offs5)
    _stamp(core, yi[lv], xi[lv], vv[lv], offs13)
    core = _gauss(core, sigma=max(0.5, 0.6 * scale)).astype(np.float32)

    halo = np.zeros((h, w), dtype=np.float32)
    _stamp(halo, yi[lv], xi[lv], np.ones(int(lv.sum()), dtype=np.float32), offs5)
    halo = _gauss(halo, sigma=max(2.0, 3.0 * scale)).astype(np.float32)
    M = np.clip(M + np.clip(halo, 0.0, 1.0) * 0.12, 0.0, 0.70)
    M = np.maximum(M, core).astype(np.float32)

    # ---- R: signed heat-wake rims of the SAME arcs ----
    offr = (rngR.uniform(3.0, 6.0, n_arc) * scale).astype(np.float32)[:, None]
    pxo = cx[:, None] + ca * (rr + offr); pyo = cy[:, None] + sa * (rr + offr)
    pxn = cx[:, None] + ca * (rr - offr); pyn = cy[:, None] + sa * (rr - offr)
    sR = (rngR.uniform(0.55, 1.0, n_arc).astype(np.float32)[:, None] * (0.35 + 0.65 * t)).ravel()
    swap = np.repeat(rngR.random(n_arc) < 0.5, n_s)   # rim polarity per arc — no global bias
    xo = np.rint(pxo).astype(np.int64).ravel(); yo = np.rint(pyo).astype(np.int64).ravel()
    xn = np.rint(pxn).astype(np.int64).ravel(); yn = np.rint(pyn).astype(np.int64).ravel()
    wake_g = np.zeros((h, w), dtype=np.float32)
    wake_s = np.zeros((h, w), dtype=np.float32)
    _stamp(wake_g, np.where(swap, yn, yo), np.where(swap, xn, xo), sR, offs5)
    _stamp(wake_s, np.where(swap, yo, yn), np.where(swap, xo, xn), sR, offs5)
    wake_g = _gauss(wake_g, sigma=max(1.0, 1.4 * scale))
    wake_s = _gauss(wake_s, sigma=max(1.0, 1.4 * scale))
    R = R + (np.clip(wake_s, 0.0, 1.0) - np.clip(wake_g, 0.0, 1.0)) * 0.34
    R = np.clip(R, 0.04, 0.96).astype(np.float32)

    # ---- Cc: ember beads strung on the SAME trails + head blooms ----
    step = 12
    bx = px[:, ::step]; by = py[:, ::step]
    nb = bx.shape[1]
    jx = (rngC.random((n_arc, nb)).astype(np.float32) - 0.5) * 3.0 * scale
    jy = (rngC.random((n_arc, nb)).astype(np.float32) - 0.5) * 3.0 * scale
    bvals = np.where(live[:, None],
                     rngC.uniform(0.70, 0.95, (n_arc, nb)),
                     rngC.uniform(0.45, 0.70, (n_arc, nb))).astype(np.float32).ravel()
    bxs = np.rint(bx + jx).astype(np.int64).ravel()
    bys = np.rint(by + jy).astype(np.int64).ravel()
    beads = np.zeros((h, w), dtype=np.float32)
    _stamp(beads, bys, bxs, bvals, offs5)
    glow = np.zeros((h, w), dtype=np.float32)
    hx = np.rint(px[:, -1]).astype(np.int64); hy = np.rint(py[:, -1]).astype(np.int64)
    hv = np.where(live, 1.0, 0.55).astype(np.float32)
    _stamp(glow, hy, hx, hv, offs13)
    glow = _gauss(glow, sigma=max(3.0, 5.0 * scale))
    CC = np.clip(CC + _gauss(beads, sigma=max(0.5, 0.7 * scale)) * 0.50
                 + np.clip(glow * 3.0, 0.0, 1.0) * 0.38, 0.0, 0.92).astype(np.float32)

    out = np.stack([M, R, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0, 1), sm)
spec_lfr_sparkler_embers._spb_concept_complete = True


# --- IGNITION: spec_lfr_torch_flicker ---
def spec_lfr_torch_flicker(shape, seed, sm, num_flames=60, **kwargs):
    """spec_lfr_torch_flicker.

    identity: Let Freedom Ring — a field of liberty-torch coronas:
    torch nodes scattered across the panel, each crowned with
    turbulence-bent flame filaments radiating in ALL directions (no
    up). ONE motif system (the torch nodes + crowns) carries all three
    channels as different aspects: M = the filament crowns, with a
    DESIGNED ~30% "roaring" subset detonating near-max while the rest
    smoulder (ignition); R = signed heat-lens refraction rings circling
    the SAME nodes (alternating gloss/rough); Cc = molten throat pools
    at the SAME node cores + ember spit at the filament tips.
    UV-agnostic (radial, no preferred direction), filaments 2-4 px at
    2048.
    """
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    if sm > 1.0:
        sm = 1.0 + (sm - 1.0) * 0.42   # damped contrast above 1.0 — never flat-white clip
    mn = min(h, w); scale = max(mn / 2048.0, 0.25)
    rngM = np.random.default_rng(int(seed) + 151)
    rngR = np.random.default_rng(int(seed) + 457)
    rngC = np.random.default_rng(int(seed) + 1013)

    # calm ambient substrates
    gM = _normalize(_spb_fast_smooth_noise((h, w), [7.0, 19.0], [0.55, 0.45], int(seed) + 151))
    gR = _normalize(_spb_fast_smooth_noise((h, w), [5.0, 13.0, 31.0], [0.40, 0.35, 0.25], int(seed) + 457))
    gC = _normalize(_spb_fast_smooth_noise((h, w), [11.0, 27.0], [0.5, 0.5], int(seed) + 1013))
    M = (0.28 + (gM - 0.5) * 0.10).astype(np.float32)
    R = (0.50 + (gR - 0.5) * 0.14).astype(np.float32)
    CC = (0.36 + (gC - 0.5) * 0.10).astype(np.float32)

    def _stamp(canvas, ys, xs, vals, offs):
        # windowed point splats — vectorized, no per-pixel python loops
        for dy, dx in offs:
            yy = ys + dy; xx = xs + dx
            ok = (yy >= 0) & (yy < h) & (xx >= 0) & (xx < w)
            canvas[yy[ok], xx[ok]] = np.maximum(canvas[yy[ok], xx[ok]], vals[ok])

    offs5 = ((0, 0), (0, 1), (0, -1), (1, 0), (-1, 0))
    offs9 = offs5 + ((1, 1), (1, -1), (-1, 1), (-1, -1))

    # ---- ONE motif system: torch nodes + crowns (geometry from rngM) ----
    n_t = int(np.clip(num_flames * 2.2 * scale * scale + 36, 40, 420))
    tx = rngM.uniform(0, w, n_t).astype(np.float32)
    ty = rngM.uniform(0, h, n_t).astype(np.float32)
    crown = (rngM.uniform(40.0, 80.0, n_t) * scale).astype(np.float32)
    roar = rngM.random(n_t) < 0.30            # DESIGNED ignition subset
    crown = np.where(roar, crown * 1.5, crown).astype(np.float32)

    n_f = 34; n_s = 64
    fa = rngM.uniform(0, 2 * np.pi, (n_t, n_f)).astype(np.float32)
    bend = rngM.uniform(-0.9, 0.9, (n_t, n_f)).astype(np.float32)
    wig_a = rngM.uniform(0.05, 0.22, (n_t, n_f)).astype(np.float32)
    wig_f = rngM.uniform(1.5, 4.0, (n_t, n_f)).astype(np.float32)
    wig_p = rngM.uniform(0, 2 * np.pi, (n_t, n_f)).astype(np.float32)
    flen = (crown[:, None] * rngM.uniform(0.55, 1.0, (n_t, n_f))).astype(np.float32)
    t = np.linspace(0.05, 1.0, n_s, dtype=np.float32)[None, None, :]
    ang = (fa[..., None] + bend[..., None] * t
           + wig_a[..., None] * np.sin(t * wig_f[..., None] * 2.0 * np.pi + wig_p[..., None]))
    rr = flen[..., None] * t
    px = tx[:, None, None] + np.cos(ang) * rr
    py = ty[:, None, None] + np.sin(ang) * rr
    vM = np.where(roar[:, None, None], 0.99 - 0.07 * t, 0.58 - 0.12 * t)
    vv = np.broadcast_to(vM, px.shape).astype(np.float32).ravel()
    rm = np.broadcast_to(roar[:, None, None], px.shape).ravel()
    xi = np.rint(px).astype(np.int64).ravel()
    yi = np.rint(py).astype(np.int64).ravel()

    fil = np.zeros((h, w), dtype=np.float32)
    _stamp(fil, yi[~rm], xi[~rm], vv[~rm], offs5)
    _stamp(fil, yi[rm], xi[rm], vv[rm], offs9)
    fil = _gauss(fil, sigma=max(0.5, 0.6 * scale)).astype(np.float32)
    haze = _gauss((fil > 0.8).astype(np.float32), sigma=max(2.5, 4.0 * scale))
    M = np.clip(M + np.clip(haze * 1.5, 0.0, 1.0) * 0.10, 0.0, 0.70)
    M = np.maximum(M, fil).astype(np.float32)

    # ---- R: signed heat-lens rings circling the SAME nodes ----
    n_rg = 3; n_q = 200
    rk = (crown[:, None] * np.array([0.55, 0.85, 1.18], dtype=np.float32)[None, :]
          * rngR.uniform(0.90, 1.10, (n_t, n_rg)).astype(np.float32))
    qa = np.linspace(0.0, 2.0 * np.pi, n_q, endpoint=False, dtype=np.float32)[None, None, :]
    lobes = rngR.integers(3, 7, (n_t, n_rg)).astype(np.float32)[..., None]
    lph = rngR.uniform(0, 2 * np.pi, (n_t, n_rg)).astype(np.float32)[..., None]
    rwav = (1.0 + 0.06 * np.sin(qa * lobes + lph)).astype(np.float32)
    rx = tx[:, None, None] + np.cos(qa) * rk[..., None] * rwav
    ry = ty[:, None, None] + np.sin(qa) * rk[..., None] * rwav
    pol0 = np.where(rngR.random(n_t) < 0.5, 1.0, -1.0).astype(np.float32)
    polk = pol0[:, None] * np.array([1.0, -1.0, 1.0], dtype=np.float32)[None, :]
    rstr = (np.where(roar[:, None], 0.95, 0.55)
            * rngR.uniform(0.70, 1.0, (n_t, n_rg))).astype(np.float32)
    pos = np.broadcast_to((polk > 0)[..., None], rx.shape).ravel()
    rsv = np.broadcast_to(rstr[..., None], rx.shape).astype(np.float32).ravel()
    rxi = np.rint(rx).astype(np.int64).ravel()
    ryi = np.rint(ry).astype(np.int64).ravel()
    ring_g = np.zeros((h, w), dtype=np.float32)
    ring_s = np.zeros((h, w), dtype=np.float32)
    _stamp(ring_g, ryi[pos], rxi[pos], rsv[pos], offs5)
    _stamp(ring_s, ryi[~pos], rxi[~pos], rsv[~pos], offs5)
    ring_g = _gauss(ring_g, sigma=max(1.0, 1.3 * scale))
    ring_s = _gauss(ring_s, sigma=max(1.0, 1.3 * scale))
    R = R + (np.clip(ring_s, 0.0, 1.0) - np.clip(ring_g, 0.0, 1.0)) * 0.36
    R = np.clip(R, 0.04, 0.96).astype(np.float32)

    # ---- Cc: molten throat pools at the SAME nodes + ember spit at tips ----
    throat = np.zeros((h, w), dtype=np.float32)
    txi = np.rint(tx).astype(np.int64); tyi = np.rint(ty).astype(np.int64)
    tv = (np.where(roar, 1.0, 0.55) * rngC.uniform(0.75, 1.0, n_t)).astype(np.float32)
    _stamp(throat, tyi, txi, tv, offs9)
    pools = _gauss(throat, sigma=max(4.0, 7.0 * scale))
    pmax = float(pools.max())
    if pmax > 1e-6:
        pools = pools / pmax
    spit = np.zeros((h, w), dtype=np.float32)
    sx = np.rint(px[..., -1]).astype(np.int64).ravel()
    sy = np.rint(py[..., -1]).astype(np.int64).ravel()
    keep = rngC.random(sx.shape[0]) < 0.45
    sv = (rngC.uniform(0.5, 0.9, sx.shape[0])
          * np.where(np.repeat(roar, n_f), 1.0, 0.7)).astype(np.float32)
    _stamp(spit, sy[keep], sx[keep], sv[keep], offs5)
    CC = np.clip(CC + np.clip(pools, 0.0, 1.0) * 0.50
                 + _gauss(spit, sigma=max(0.5, 0.8 * scale)) * 0.40, 0.0, 0.92).astype(np.float32)

    out = np.stack([M, R, CC], axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0, 1), sm)
spec_lfr_torch_flicker._spb_concept_complete = True


# --- IGNITION: spec_lfr_capitol_veins ---
def spec_lfr_capitol_veins(shape, seed, sm, num_veins=28, **kwargs):
    '''spec_lfr_capitol_veins -- Let Freedom Ring: gilded fault-light marble.

    One motif system: iso-level vein families of a single marble carrier
    field. M = soft polished sheen pools around the whole vein network;
    R = signed flank polish (one flank glossy, one rough, per family);
    Cc = IGNITION -- a chosen central subset of vein families detonates
    at near-max clearcoat (fault-light), quantile-sized so the hot veins
    always cover a designed sliver of the car, over a calm calcite pool.
    The marble reads quiet until the sun lines up with a live vein.
    Omnidirectional iso-contours, UV-agnostic, fully vectorized.
    '''
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    mn = min(h, w)
    ds = 2 if (_CV2_OK and mn > 1100) else 1
    hh, wh = min(max(h // ds, 256), h), min(max(w // ds, 256), w)  # cap at target so sub-256 swatches don't 256-floor into a broadcast mismatch (fix 2026-06-13)
    sc = max(min(hh, wh) / 1024.0, 0.25)

    car = _normalize(_spb_fast_smooth_noise(
        (hh, wh), [13.0 * sc, 32.0 * sc, 75.0 * sc], [0.30, 0.38, 0.32],
        int(seed) + 11)).astype(np.float32)
    gy, gx = np.gradient(car)
    gm = np.sqrt(gx * gx + gy * gy)
    inv_gm = (float(ds) / np.maximum(gm, 0.0012 * ds)).astype(np.float32)

    rng = np.random.default_rng(int(seed) + 11)
    rngR = np.random.default_rng(int(seed) + 307)
    rngC = np.random.default_rng(int(seed) + 401)
    K = int(np.clip(num_veins // 4, 4, 9))
    levels = np.sort(rng.uniform(0.18, 0.82, K)).astype(np.float32)
    flank_pol = np.where(rngR.random(K) < 0.5, 1.0, -1.0).astype(np.float32)
    central = np.argsort(np.abs(levels - 0.5))[:4]
    live = np.zeros(K, dtype=bool)
    live[rngC.choice(central, size=min(max(2, K // 3), central.size), replace=False)] = True

    mot = _normalize(_spb_fast_smooth_noise(
        (hh, wh), [6.0 * sc, 17.0 * sc], [0.5, 0.5], int(seed) + 211))
    M = (0.56 + (mot - 0.5) * 0.10).astype(np.float32)
    halo_acc = np.zeros((hh, wh), dtype=np.float32)
    R = np.full((hh, wh), 0.5, dtype=np.float32)
    clouds = _normalize(_spb_fast_smooth_noise(
        (hh, wh), [20.0 * sc, 55.0 * sc], [0.5, 0.5], int(seed) + 401))
    CC = (0.42 + (clouds - 0.5) * 0.14).astype(np.float32)
    dmin = np.full((hh, wh), 1e9, dtype=np.float32)

    for k in range(K):
        d = np.abs(car - levels[k]) * inv_gm   # approx px to the iso-vein
        halo_acc = np.maximum(halo_acc, (1.0 - _smoothstep(2.0, 16.0, d)).astype(np.float32))
        flank = (1.0 - _smoothstep(1.0, 9.0, d)) * np.sign(car - levels[k]) * flank_pol[k]
        R += flank.astype(np.float32) * 0.27
        if live[k]:
            dmin = np.minimum(dmin, d)
        else:
            CC -= (1.0 - _smoothstep(1.0, 6.0, d)).astype(np.float32) * 0.10

    qd = float(np.clip(np.quantile(dmin, 0.10), 2.5, 14.0))
    core = (1.0 - _smoothstep(qd * 0.55, qd * 1.45, dmin)).astype(np.float32)
    charge = (1.0 - _smoothstep(qd * 1.3, qd * 4.0, dmin)).astype(np.float32)
    CC = np.maximum(CC, (0.46 + charge * 0.18).astype(np.float32))
    CC = np.maximum(CC, (0.52 + core * 0.48).astype(np.float32))
    M = M + halo_acc * 0.16

    if ds > 1:
        M = _cv2.resize(M, (w, h), interpolation=_cv2.INTER_LINEAR)
        R = _cv2.resize(R, (w, h), interpolation=_cv2.INTER_LINEAR)
        CC = _cv2.resize(CC, (w, h), interpolation=_cv2.INTER_LINEAR)
    grain = _normalize(_spb_fast_smooth_noise(
        (h, w), [2.5, 6.0], [0.6, 0.4], int(seed) + 307))
    M = M + (grain - 0.5).astype(np.float32) * 0.05
    R = np.clip(R + (grain - 0.5).astype(np.float32) * 0.14, 0.18, 0.82)

    out = np.stack([np.clip(M, 0, 1), np.clip(R, 0, 1), np.clip(CC, 0, 1)],
                   axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
spec_lfr_capitol_veins._spb_concept_complete = True


# --- IGNITION: spec_lfr_canyon_bevel ---
def spec_lfr_canyon_bevel(shape, seed, sm, num_cells=120, edge_w=2.0, **kwargs):
    '''spec_lfr_canyon_bevel -- Let Freedom Ring: slot-canyon strata terraces.

    One motif system: a domain-warped height field quantized into stone
    terraces. M = per-terrace plateau sheen plus fake-3D rim light and
    foot shadow on every step; R = parity-signed riser roughness
    (alternating glossy and gritty steps) with ledge grit; Cc = IGNITION
    -- an area-weighted subset of strata (about a third of the surface)
    detonates its rim shelf at near-max clearcoat over a smooth
    ambient-depth pool, so a few canyon ledges blaze when the sun rakes
    them. Warped organic contour terraces = omnidirectional, UV-agnostic,
    fully vectorized.
    '''
    h, w = shape
    if sm < 0.001:
        return _flat(shape)
    mn = min(h, w)
    sc = max(mn / 2048.0, 0.25)

    H0 = _normalize(_spb_fast_smooth_noise(
        (h, w), [40.0 * sc, 110.0 * sc, 240.0 * sc], [0.34, 0.36, 0.30],
        int(seed) + 71, max_dim=512)).astype(np.float32)
    if _CV2_OK:
        wxn = _normalize(_spb_fast_smooth_noise(
            (h, w), [120.0 * sc, 260.0 * sc], [0.5, 0.5], int(seed) + 137, max_dim=256))
        wyn = _normalize(_spb_fast_smooth_noise(
            (h, w), [120.0 * sc, 260.0 * sc], [0.5, 0.5], int(seed) + 193, max_dim=256))
        amp = mn * 0.035
        xx = np.arange(w, dtype=np.float32)[None, :]
        yy = np.arange(h, dtype=np.float32)[:, None]
        mapx = np.clip(xx + (wxn * 2.0 - 1.0) * amp, 0, w - 1).astype(np.float32)
        mapy = np.clip(yy + (wyn * 2.0 - 1.0) * amp, 0, h - 1).astype(np.float32)
        Hf = _cv2.remap(H0, mapx, mapy, interpolation=_cv2.INTER_LINEAR)
    else:
        Hf = H0
    Hf = np.clip(Hf, 0.0, 1.0).astype(np.float32)

    L = int(np.clip(num_cells // 8, 10, 24))
    t = Hf * (L - 1e-4)
    lev = t.astype(np.int32)
    f = (t - lev).astype(np.float32)

    rngM = np.random.default_rng(int(seed) + 223)
    rngR = np.random.default_rng(int(seed) + 331)
    rngC = np.random.default_rng(int(seed) + 439)
    sheen = rngM.uniform(0.0, 1.0, L).astype(np.float32)
    pol = np.where(rngR.random(L) < 0.5, 1.0, -1.0).astype(np.float32)

    # area-weighted live-strata pick: ignite ~a third of the surface
    frac = np.bincount(lev.ravel(), minlength=L).astype(np.float64) / float(lev.size)
    live = np.zeros(L, dtype=bool)
    acc = 0.0
    for li in rngC.permutation(L):
        if frac[li] < 0.01:
            continue
        live[li] = True
        acc += frac[li]
        if acc >= 0.32 and live.sum() >= 2:
            break
    if live.sum() < 2:
        live[np.argsort(frac)[-2:]] = True

    ew = float(np.clip(0.06 * edge_w, 0.05, 0.30))
    e0 = (1.0 - _smoothstep(0.0, ew, f)).astype(np.float32)
    e1 = _smoothstep(1.0 - ew, 1.0, f).astype(np.float32)
    grain = _normalize(_spb_fast_smooth_noise(
        (h, w), [2.5, 7.0], [0.6, 0.4], int(seed) + 547))

    M = (0.42 + sheen[lev] * 0.26).astype(np.float32)
    M = M + e1 * 0.20 - e0 * 0.15 + (grain - 0.5).astype(np.float32) * 0.08

    riser = np.maximum(e0, e1)
    R = (0.50 + (grain - 0.5) * 0.18).astype(np.float32)
    R = R + pol[lev] * riser * 0.28

    if _CV2_OK:
        small = _cv2.resize(Hf, (max(w // 4, 128), max(h // 4, 128)),
                            interpolation=_cv2.INTER_AREA)
        AO = _cv2.resize(_gauss(small, sigma=max(1.0, mn * 0.003)), (w, h),
                         interpolation=_cv2.INTER_LINEAR)
    else:
        AO = _gauss(Hf, sigma=max(2.0, mn * 0.012))
    AO = _normalize(AO)
    CC = (0.40 + (AO - 0.5) * 0.18).astype(np.float32)
    shelf = _smoothstep(0.55, 0.88, f).astype(np.float32)
    CC = np.where(live[lev], np.maximum(CC, 0.55 + shelf * 0.45), CC).astype(np.float32)

    out = np.stack([np.clip(M, 0, 1), np.clip(R, 0, 1), np.clip(CC, 0, 1)],
                   axis=-1).astype(np.float32)
    return _sm_scale(np.clip(out, 0.0, 1.0), sm)
